load_dotenv()

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s"
)

# ===========================================================
# STAGE 175: ROTATING LOG FILES + REQUEST/PERFORMANCE LOGGERS
# ===========================================================
# PythonAnywhere disk quotas are limited, so every file handler here is
# a RotatingFileHandler (bounded size + backup count) rather than an
# unbounded append — nothing here can silently fill the account's quota.
#
# LOG_DIR defaults to a local "logs" folder next to app.py; override with
# the LOG_DIR env var if you want it elsewhere (e.g. a separate volume).
# SLOW_REQUEST_MS sets the threshold (in milliseconds) above which a
# request is also written to slow.log — tune this if some AI-powered
# endpoints (WhatsApp bot, voice-note parsing) are naturally slower than
# the rest of the app; a per-route override can be layered on later.
from logging.handlers import RotatingFileHandler

LOG_DIR = os.environ.get("LOG_DIR", os.path.join(os.path.dirname(os.path.abspath(__file__)), "logs"))
os.makedirs(LOG_DIR, exist_ok=True)
SLOW_REQUEST_MS = int(os.environ.get("SLOW_REQUEST_MS", "500"))

_log_formatter = logging.Formatter("%(asctime)s - %(levelname)s - %(message)s")

def _make_rotating_logger(name, filename, level=logging.INFO, max_bytes=5 * 1024 * 1024, backups=3):
    logger = logging.getLogger(name)
    logger.setLevel(level)
    logger.propagate = False  # keep these out of the root/basicConfig stream handler
    if not logger.handlers:
        handler = RotatingFileHandler(os.path.join(LOG_DIR, filename), maxBytes=max_bytes, backupCount=backups)
        handler.setFormatter(_log_formatter)
        logger.addHandler(handler)
    return logger

# Root app logger (errors/info) also gets a rotating file, in addition to
# the console stream basicConfig already sets up above.
_app_file_handler = RotatingFileHandler(os.path.join(LOG_DIR, "app.log"), maxBytes=5 * 1024 * 1024, backupCount=3)
_app_file_handler.setFormatter(_log_formatter)
logging.getLogger().addHandler(_app_file_handler)

access_logger = _make_rotating_logger("smile_again.access", "access.log")
slow_logger   = _make_rotating_logger("smile_again.slow", "slow.log", level=logging.WARNING)

project_root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
if project_root not in sys.path:
    sys.path.append(project_root)


# ===========================================================
