# STAGE 239: automatic DocuSign -> Notion envelope-activity logging.
# Requires a Notion internal integration token (created once at
# https://www.notion.so/my-integrations) shared with the
# "Smile Again — DocuSign Envelope Log" database. Without these two
# values set, logging is silently skipped (DocusignEnvelopeLog in
# Postgres still records everything either way).
NOTION_API_KEY = os.environ.get("NOTION_API_KEY", "")
NOTION_DOCUSIGN_LOG_DATA_SOURCE_ID = os.environ.get(
    "NOTION_DOCUSIGN_LOG_DATA_SOURCE_ID", "9eb06a65-102a-4311-90f9-58386f82add5"
)


def log_docusign_envelope_to_notion(document_name, sent_by, signer_name, signer_email,
                                     subject, status, envelope_id, error):
    """Best-effort push of one DocuSign envelope row into the shared Notion
    log. Never raises — a Notion outage or missing token must never break
    the actual envelope send."""
    if not NOTION_API_KEY:
        return
    try:
        payload = {
            "parent": {"type": "data_source_id", "data_source_id": NOTION_DOCUSIGN_LOG_DATA_SOURCE_ID},
            "properties": {
                "Document": {"title": [{"text": {"content": (document_name or "Untitled document")[:200]}}]},
                "Date Sent": {"date": {"start": datetime.utcnow().strftime("%Y-%m-%d")}},
                "Sent By": {"rich_text": [{"text": {"content": (sent_by or "")[:200]}}]},
                "Signer Name": {"rich_text": [{"text": {"content": (signer_name or "")[:200]}}]},
                "Signer Email": {"email": signer_email or None},
                "Subject": {"rich_text": [{"text": {"content": (subject or "")[:200]}}]},
                "Status": {"select": {"name": "sent" if status == "sent" else "failed"}},
                "Envelope ID": {"rich_text": [{"text": {"content": (envelope_id or "")[:200]}}]},
                "Error": {"rich_text": [{"text": {"content": (error or "")[:1500]}}]},
            },
        }
        requests.post(
            "https://api.notion.com/v1/pages",
            headers={
                "Authorization": f"Bearer {NOTION_API_KEY}",
                "Notion-Version": "2025-09-03",
                "Content-Type": "application/json",
            },
            json=payload, timeout=8,
        )
    except Exception as e:
        logging.error(f"[NOTION DOCUSIGN LOG ERROR] {e}")


def _sync_admin_from_email(user) -> None:
    """If this account's email is one of the hardcoded ADMIN_EMAILS,
    make sure is_admin is set on it. Called on signup, login, Google
    sign-in, and /api/auth/me so admin rights apply immediately without
    needing a manual database edit — and this never downgrades an admin
    flag that was granted some other way."""
    try:
        if user.email and user.email.strip().lower() in ADMIN_EMAILS and not user.is_admin:
            user.is_admin = True
            db.session.commit()
    except Exception as e:
        db.session.rollback()
        logging.error(f"[ADMIN SYNC] failed for {getattr(user, 'email', '?')}: {e}")

