POSTHOG_API_KEY = os.environ.get("POSTHOG_API_KEY", "")
POSTHOG_HOST = os.environ.get("POSTHOG_HOST", "https://us.i.posthog.com")


def track_analytics_event(user_id, event_name, properties=None):
    """Fire-and-forget server-side event capture. No-ops silently if
    POSTHOG_API_KEY isn't set — safe to call unconditionally anywhere."""
    if not POSTHOG_API_KEY:
        return
    try:
        requests.post(
            f"{POSTHOG_HOST}/capture/",
            json={
                "api_key": POSTHOG_API_KEY,
                "event": event_name,
                "distinct_id": str(user_id) if user_id else "anonymous",
                "properties": properties or {},
            },
            timeout=5,
        )
    except Exception as e:
        logging.error(f"[POSTHOG CAPTURE ERROR] event={event_name}: {e}")


