# ════════════════════════════════════════════════════════════
# PWA / TWA SUPPORT — STAGE 241: INSTALLABILITY FIX
# Previously /manifest.json and /sw.js just proxied to static files
# that may or may not actually exist/be valid on disk — if either 404'd
# or the manifest was missing a required field (icons, start_url,
# display mode), Chrome/Android silently never fires
# beforeinstallprompt (the client-side listener for it already exists,
# see the PWA block in index.html — it was never the problem). Both
# are now generated here instead, so installability no longer depends
# on a deploy step uploading the right files to the right path. Icon
# files still come from static/icons/ if present (swap in the real
# logo there any time — see _pwa_icon_fallback below for what happens
# if they're not).
# ════════════════════════════════════════════════════════════
import zlib
import binascii

PWA_THEME_COLOR = "#1e3a8a"
PWA_BG_COLOR = "#1e3a8a"


def _pwa_png_chunk(chunk_type: bytes, data: bytes) -> bytes:
    return (struct.pack(">I", len(data)) + chunk_type + data +
            struct.pack(">I", binascii.crc32(chunk_type + data) & 0xffffffff))


def _pwa_generate_icon_png(size: int) -> bytes:
    """Pure stdlib (no Pillow dependency) PNG encoder: a solid navy
    square with a lighter circular mark, used ONLY as a fallback when
    the real brand icon file isn't on disk yet at static/icons/. Good
    enough to satisfy install-criteria checks (which just need a valid
    192x192 and 512x512 PNG) without blocking installability on an
    asset upload."""
    fg = (0x1e, 0x3a, 0x8a)   # brand navy, matches theme_color
    mark = (0xff, 0xff, 0xff, 235)
    cx = cy = size / 2.0
    radius = size * 0.32
    raw = bytearray()
    for y in range(size):
        raw.append(0)  # filter type 0 (none) for this scanline
        for x in range(size):
            dx, dy = x - cx, y - cy
            if (dx * dx + dy * dy) ** 0.5 <= radius:
                r, g, b = fg[0] + int((mark[0] - fg[0]) * mark[3] / 255), \
                          fg[1] + int((mark[1] - fg[1]) * mark[3] / 255), \
                          fg[2] + int((mark[2] - fg[2]) * mark[3] / 255)
            else:
                r, g, b = fg
            raw += bytes((r, g, b, 255))
    compressed = zlib.compress(bytes(raw), 6)
    ihdr = struct.pack(">IIBBBBB", size, size, 8, 6, 0, 0, 0)  # 8-bit RGBA, no interlace
    png = b"\x89PNG\r\n\x1a\n"
    png += _pwa_png_chunk(b"IHDR", ihdr)
    png += _pwa_png_chunk(b"IDAT", compressed)
    png += _pwa_png_chunk(b"IEND", b"")
    return png


