@app.route('/sw.js')
def service_worker():
    sw_js = """
// Generated by the backend (see /sw.js route in app.py) instead of
// shipped as a static file, so a missed/failed static-asset deploy can
// never silently break installability again. Cache-name is versioned —
// bump PWA_CACHE_VERSION server-side (below) to force clients to pick
// up a new app shell.
const PWA_CACHE_VERSION = 'connectit-shell-v1';
const APP_SHELL = ['/', '/manifest.json',
  '/static/icons/android-chrome-192x192.png', '/static/icons/android-chrome-512x512.png',
  '/static/icons/maskable-icon-192x192.png', '/static/icons/maskable-icon-512x512.png'];

self.addEventListener('install', function(event) {
  self.skipWaiting();
  event.waitUntil(
    caches.open(PWA_CACHE_VERSION).then(function(cache) {
      return Promise.all(APP_SHELL.map(function(url) {
        return cache.add(url).catch(function() { /* fine if one asset 404s during install */ });
      }));
    })
  );
});

self.addEventListener('activate', function(event) {
  event.waitUntil(
    caches.keys().then(function(keys) {
      return Promise.all(keys.filter(function(k) { return k !== PWA_CACHE_VERSION; })
        .map(function(k) { return caches.delete(k); }));
    }).then(function() { return self.clients.claim(); })
  );
});

// Network-first, falling back to cache — keeps the live app fresh while
// still satisfying the "has a fetch handler" installability requirement
// and giving a basic offline shell (pairs with the client-side offline
// widget cache already built for STAGE 234).
self.addEventListener('fetch', function(event) {
  if (event.request.method !== 'GET') return;
  const url = new URL(event.request.url);
  if (url.origin !== self.location.origin) return;

  // FIX: /api/* calls must never resolve with the cached app-shell HTML.
  // The old fallback below (`cached || caches.match('/')`) meant that any
  // offline GET to e.g. /api/jobs or /api/whatsapp/opt-in-widget/* that
  // wasn't itself in the cache silently resolved with the cached index.html
  // page instead of failing. Callers doing `res.json()` on that then threw
  // "Unexpected token '<', "<!DOCTYPE"... is not valid JSON" — exactly the
  // Job Board and WhatsApp Opt-in Widget errors. API requests should just
  // fail like a normal offline fetch so the page's own offline/queueing
  // logic (queuedFetch, the offline banner, etc.) can handle it correctly.
  if (url.pathname.startsWith('/api/')) {
    event.respondWith(fetch(event.request));
    return;
  }

  event.respondWith(
    fetch(event.request).then(function(res) {
      const copy = res.clone();
      caches.open(PWA_CACHE_VERSION).then(function(cache) { cache.put(event.request, copy); });
      return res;
    }).catch(function() {
      return caches.match(event.request).then(function(cached) {
        if (cached) return cached;
        // Only fall back to the app-shell for actual page navigations —
        // never for other static assets (scripts, images, etc.), where
        // returning HTML in place of the real asset would be just as
        // broken as it was for API calls above.
        if (event.request.mode === 'navigate') return caches.match('/');
        return Response.error();
      });
    })
  );
});

// =====================================================================
// STAGE: Enterprise Roadmap Part 2.7 — Offline-First "Queue & Push".
// This is the piece that makes the offline outbox (see offlineQueuePush
// / queuedFetch in the app shell) actually push the moment connectivity
// returns, even if no tab is open — a plain 'online' window-event
// listener in page JS can't fire if there's no page. The Background
// Sync API instead lets the browser wake this worker (subject to OS/
// battery constraints — this is "as soon as reasonably possible on
// reconnect", not an instant guarantee, which is the correct
// expectation to set for field conditions) and hand it a registered
// tag. Reads/writes the *same* IndexedDB database and object store the
// page writes to (name/version/keyPath below must stay in lock-step
// with _connectitDb() in the app shell), so nothing needs to be handed
// to the worker beyond the sync event itself — the auth session
// cookie travels with same-origin fetches from the SW exactly as it
// does from a page, and /api/offline-sync/batch is CSRF-exempt, so no
// tokens need to be relayed into worker scope (which has no
// localStorage access anyway).
// =====================================================================
const CONNECTIT_DB_NAME    = 'connectit_offline_v1';
const CONNECTIT_DB_VERSION = 1;
const CONNECTIT_STORE      = 'outbox';
const CONNECTIT_SYNC_TAG   = 'connectit-outbox-sync';

function _connectitSwOpenDb() {
  return new Promise(function(resolve, reject) {
    const req = indexedDB.open(CONNECTIT_DB_NAME, CONNECTIT_DB_VERSION);
    // Mirrors the app shell's onupgradeneeded so a sync event that
    // wakes the worker before any tab has run (e.g. first launch after
    // install, browser pre-warming the SW) still finds/creates the
    // right schema instead of failing outright.
    req.onupgradeneeded = function(ev) {
      const db = ev.target.result;
      if (!db.objectStoreNames.contains(CONNECTIT_STORE)) {
        const store = db.createObjectStore(CONNECTIT_STORE, { keyPath: 'client_id' });
        store.createIndex('queued_at', 'queued_at', { unique: false });
      }
    };
    req.onsuccess = function(ev) { resolve(ev.target.result); };
    req.onerror = function(ev) { reject(ev.target.error); };
  });
}
function _connectitSwReqToPromise(req) {
  return new Promise(function(resolve, reject) {
    req.onsuccess = function() { resolve(req.result); };
    req.onerror = function() { reject(req.error); };
  });
}
function _connectitSwGetAll() {
  return _connectitSwOpenDb().then(function(db) {
    const tx = db.transaction(CONNECTIT_STORE, 'readonly');
    return _connectitSwReqToPromise(tx.objectStore(CONNECTIT_STORE).getAll());
  });
}
function _connectitSwDelete(clientId) {
  return _connectitSwOpenDb().then(function(db) {
    const tx = db.transaction(CONNECTIT_STORE, 'readwrite');
    return _connectitSwReqToPromise(tx.objectStore(CONNECTIT_STORE).delete(clientId));
  });
}

async function _connectitSwFlush() {
  let synced = 0;
  try {
    const all = await _connectitSwGetAll();
    const entityEntries = all.filter(function(e) { return e.kind === 'entity'; }).slice(0, 200);
    const rawEntries = all.filter(function(e) { return e.kind === 'raw'; })
      .sort(function(a, b) { return (a.queued_at || 0) - (b.queued_at || 0); });

    if (entityEntries.length) {
      const res = await fetch('/api/offline-sync/batch', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'same-origin',
        body: JSON.stringify({ entries: entityEntries.map(function(e) {
          return { client_id: e.client_id, entity_type: e.entity_type, recorded_at: e.recorded_at, payload: e.payload };
        }) })
      });
      if (res.ok) {
        const data = await res.json();
        for (const r of (data.results || [])) {
          if (r.ok) { await _connectitSwDelete(r.client_id); synced++; }
        }
      }
      // A non-ok response (e.g. 401 — no active session in this worker's
      // cookie jar) leaves entries queued for the next sync event or the
      // next time a tab flushes them itself; never dropped silently.
    }

    for (const e of rawEntries) {
      try {
        const opts = Object.assign({}, e.options, { credentials: 'same-origin' });
        const res = await fetch(e.url, opts);
        if (res.ok || (res.status >= 400 && res.status < 500)) {
          await _connectitSwDelete(e.client_id);
          if (res.ok) synced++;
        } else {
          break; // 5xx — stop here, retry the rest on the next sync event
        }
      } catch (netErr) {
        break; // connection dropped mid-replay — stop, retry on next sync event
      }
    }
  } catch (e) {
    // IndexedDB or network unavailable this cycle — the registered sync
    // tag is retried by the browser with backoff, nothing to do here.
  }

  if (synced > 0 && 'BroadcastChannel' in self) {
    try {
      new BroadcastChannel('connectit-outbox').postMessage({ type: 'connectit-outbox-synced', count: synced });
    } catch (e) {}
  }
  return synced;
}

self.addEventListener('sync', function(event) {
  if (event.tag === CONNECTIT_SYNC_TAG) {
    event.waitUntil(_connectitSwFlush());
  }
});

// Best-effort periodic retry for installed PWAs on browsers that
// support the Periodic Background Sync API (chromium-based, and only
// once the user has granted the 'periodic-background-sync' permission
// via installing the app to their home screen/desktop). Purely
// additive — browsers that never register a periodicsync tag (every
// browser without this API, including Safari/iOS) simply never fire
// this listener, and the page-side 45s interval + 'online' listener
// remain the fallback there.
self.addEventListener('periodicsync', function(event) {
  if (event.tag === CONNECTIT_SYNC_TAG) {
    event.waitUntil(_connectitSwFlush());
  }
});
"""
    return Response(
        sw_js,
        mimetype='application/javascript',
        headers={
            # Belt-and-braces: scope is already root by URL position, but
            # this header removes any ambiguity for browsers that check it,
            # and no-cache ensures a browser always revalidates sw.js so a
            # server-side fix (like this one) actually reaches installed
            # clients instead of being masked by a long-lived cached copy.
            "Service-Worker-Allowed": "/",
            "Cache-Control": "no-cache",
        },
    )


@app.route('/static/icons/<path:filename>')
def pwa_icon(filename):
    """Serves the real brand icon file if it's been uploaded to
    static/icons/; otherwise generates a placeholder PNG on the fly so
    the manifest's icon URLs never 404 and installability isn't blocked
    on that upload happening first."""
    icons_dir = os.path.join(app.static_folder, 'icons')
    real_path = os.path.join(icons_dir, filename)
    if os.path.isfile(real_path):
        real_mimetype = 'image/x-icon' if filename.lower().endswith('.ico') else 'image/png'
        return send_from_directory(icons_dir, filename, mimetype=real_mimetype)
    # Fallback sizing: pull the first NxN (or just N) run of digits out of
    # the filename so this still degrades sensibly for the fuller icon set
    # (favicon-32x32.png, android-chrome-192x192.png, maskable-icon-512x512.png,
    # apple-touch-icon.png, favicon.ico, etc.) and not just the older
    # icon-NNN.png naming.
    m = re.search(r'(\d+)(?:x\d+)?', filename)
    size = int(m.group(1)) if m else 192
    size = min(max(size, 16), 512)
    if filename.lower().endswith('.ico'):
        return Response(_pwa_generate_icon_png(48), mimetype='image/x-icon')
    return Response(_pwa_generate_icon_png(size), mimetype='image/png')


@app.route('/.well-known/assetlinks.json')
def asset_links():
    """Digital Asset Links for the Android TWA (see STAGE 520 below).
    Preference order: (1) a real TwaConfig row saved through the Android
    App admin panel — the normal path once Bubblewrap/Play Console setup
    is done; (2) a hand-placed .well-known/assetlinks.json file on disk,
    for anyone who prefers to manage it outside the admin panel; (3) an
    empty array, so a site with no Android app configured yet still
    returns valid (if empty) JSON instead of a 404 or a crash."""
    try:
        cfg = TwaConfig.query.get(1)
        if cfg and cfg.package_name and cfg.sha256_fingerprints:
            fingerprints = json.loads(cfg.sha256_fingerprints)
            if fingerprints:
                payload = [{
                    "relation": ["delegate_permission/common.handle_all_urls"],
                    "target": {
                        "namespace": "android_app",
                        "package_name": cfg.package_name,
                        "sha256_cert_fingerprints": fingerprints,
                    },
                }]
                return Response(json.dumps(payload), mimetype='application/json')
    except Exception as e:
        logging.warning(f"[TWA] assetlinks.json DB lookup failed, falling back: {e}")
    try:
        return send_from_directory('.well-known', 'assetlinks.json', mimetype='application/json')
    except Exception:
        # Only needed for Android TWA/Play Store domain verification —
        # absence must not affect ordinary browser installability above.
        return Response("[]", mimetype='application/json')

