# FIX: no global error handler existed anywhere in this app, so any
# unhandled exception, wrong HTTP method (405), or unknown route (404)
# fell through to Flask/Werkzeug's default HTML error page. Every
# frontend fetch() call here expects JSON, so that HTML response broke
# with a "Unexpected token '<' ... is not valid JSON" parse error on
# the client — this is what was actually behind the Compliance
# Checker / Domain Trust Check / Job Board failures, not a bug unique
# to each of those three features individually.
@app.errorhandler(Exception)
def _handle_uncaught_exception(e):
    from werkzeug.exceptions import HTTPException
    wants_json = (
        request.path.startswith("/api/") or request.path in ("/mcp", "/oauth/token", "/oauth/register")
        or request.accept_mimetypes.best == "application/json"
    )
    if isinstance(e, HTTPException):
        if wants_json:
            return jsonify({"error": e.description or e.name}), e.code
        return e
    logging.error(f"[UNCAUGHT EXCEPTION] {request.method} {request.path}: {e}", exc_info=True)
    try:
        db.session.rollback()
    except Exception:
        pass
    if wants_json:
        return jsonify({"error": "Something went wrong on our end. Please try again in a moment."}), 500
    return "Internal Server Error", 500


# ════════════════════════════════════════════════════════════
# PLATFORM FEATURE FLAGS — helpers + decorator
# ════════════════════════════════════════════════════════════

def _feature_enabled(key: str) -> bool:
    """A flag row's explicit value is authoritative. If the row doesn't
    exist yet for some reason, fall back to mirroring the single
    platform-wide Lock All / Unlock All switch (_all_programs_locked)
    instead of a hardcoded default — there is exactly ONE binary state
    for the whole platform now: everything is locked, or everything is
    unlocked. Nothing defaults to locked on its own anymore."""
    try:
        flag = PlatformFeatureFlag.query.filter_by(key=key).first()
        enabled = bool(flag.enabled) if flag is not None else (not _all_programs_locked())
        if not enabled and _all_programs_locked() and _viewer_is_platform_admin():
            # Lock All switches every flag off for the public; owners/admins
            # still need these routes to work so they can run the platform.
            return True
        return enabled
    except Exception as e:
        logging.error(f"[FEATURE FLAG CHECK ERROR] key={key}: {e}")
        return False


def _seed_feature_flag(key: str, label: str, description: str, locked_reason: str = None, enabled: bool = None) -> None:
    """Ensures a flag row exists, without ever touching an admin's
    existing choice if the row is already there. enabled=None (the
    default) means "inherit whatever the platform-wide Lock All /
    Unlock All switch currently is" rather than a hardcoded False —
    so a brand-new flag never silently reintroduces a default-locked
    state outside that one switch. Pass enabled=True/False explicitly
    only if a flag genuinely needs to start out of step with the
    master switch."""
    try:
        if not PlatformFeatureFlag.query.filter_by(key=key).first():
            resolved_enabled = enabled if enabled is not None else (not _all_programs_locked())
            db.session.add(PlatformFeatureFlag(
                key=key, label=label, description=description,
                enabled=resolved_enabled, locked_reason=locked_reason,
            ))
            db.session.commit()
    except Exception as e:
        db.session.rollback()
        logging.error(f"[FEATURE FLAG SEED ERROR] key={key}: {e}")


def requires_feature_flag(key: str):
    """Route decorator: blocks the route with a clean 503 unless a
    superadmin has explicitly enabled this flag. Stack it directly
    above the route function, below @app.route/@csrf.exempt."""
    def decorator(fn):
        @wraps(fn)
        def wrapper(*args, **kwargs):
            if not _feature_enabled(key):
                flag = PlatformFeatureFlag.query.filter_by(key=key).first()
                return jsonify({
                    "error": "This feature is currently unavailable.",
                    "feature_locked": True,
                    "reason": (flag.locked_reason if flag and flag.locked_reason else None),
                }), 503
            return fn(*args, **kwargs)
        return wrapper
    return decorator


# STAGE 151: the actual SocketIO server instance. async_mode="threading"
# is used deliberately — it needs no extra dependency (eventlet/gevent)
# beyond flask-socketio itself and works fine under gunicorn's default
# sync worker for a feature like a handful of concurrent SSH terminals.
# If this ever needs to scale to many simultaneous WebSocket connections,
# switch to `pip install eventlet` and async_mode="eventlet" plus
# `gunicorn --worker-class eventlet`.
socketio_app = SocketIO(
    app,
    cors_allowed_origins=["https://your-site.netlify.app"],
    async_mode="threading",
) if FLASK_SOCKETIO_AVAILABLE else None

user_store: dict = {}


# ===========================================================
# IN-MEMORY STORES & LOCKS
# ===========================================================
conversation_store:   dict = defaultdict(list)
whatsapp_store:       dict = defaultdict(list)
messenger_store:      dict = defaultdict(list)
instagram_dm_store:   dict = defaultdict(list)

_verification_tokens: dict = {}
_verification_lock         = threading.Lock()

_reset_tokens:        dict = {}
_reset_lock                = threading.Lock()

# STAGE 149: short-lived token issued right after a correct email+password
# check for an account with 2FA enabled. The real session isn't created
# until the matching TOTP/backup code comes back in — so a stolen
# password alone can't log in. Same in-memory-with-lock pattern as the
# email verification/reset tokens above; entries expire in 10 minutes.
_pending_2fa_tokens:  dict = {}
_pending_2fa_lock           = threading.Lock()

# STAGE 515: MANDATORY EMAIL VERIFICATION BEFORE LOGIN. Same
# short-lived, in-memory, lock-guarded pending-token pattern as 2FA
# above — a signup or a login attempt for an unverified account never
# creates a real session by itself. It only returns a pending_token;
# the real session (and auth token) is created by
# /api/auth/verify-email-code, and only once the 6-digit code just
# emailed to that address is typed back in. A password alone — or an
# email address nobody actually controls — can never reach a session.
_pending_email_verify_tokens: dict = {}
_pending_email_verify_lock          = threading.Lock()

# STAGE 150: application-layer firewall. A real network/packet firewall is
# infrastructure-level and outside what Flask code can control, so this is
# the equivalent that actually lives in this app: per-key rate limiting on
# sensitive endpoints, escalating lockout after repeated failures, and an
# admin-managed IP blocklist checked on every request. All in-memory with
# a lock, same pattern as the reset/2FA token stores above — no new
# dependency (flask-Limiter etc.) required.
_rate_limit_hits:     dict = {}   # key -> [timestamps]
_rate_limit_lock            = threading.Lock()

_lockout_state:       dict = {}   # key (email or ip) -> {"fail_count": int, "locked_until": float}
_lockout_lock                = threading.Lock()

_blocked_ips_cache:   set  = set()
_blocked_ips_lock            = threading.Lock()


def _client_ip() -> str:
    """Best-effort real client IP behind a proxy (PythonAnywhere/most PaaS
    set X-Forwarded-For). Falls back to Flask's remote_addr."""
    xff = request.headers.get("X-Forwarded-For", "")
    if xff:
        return xff.split(",")[0].strip()
    return request.remote_addr or "unknown"


def _rate_limited(key: str, max_attempts: int, window_seconds: int) -> bool:
    """Sliding-window limiter. Returns True if `key` has already made
    max_attempts (or more) calls within window_seconds — caller should
    reject the request with 429. Records this call either way, so bursts
    right at the limit self-throttle correctly."""
    now = time.time()
    with _rate_limit_lock:
        hits = _rate_limit_hits.setdefault(key, [])
        hits[:] = [t for t in hits if now - t < window_seconds]
        if len(hits) >= max_attempts:
            return True
        hits.append(now)
        return False


def _lockout_check(key: str):
    """Returns seconds remaining if `key` is currently locked out, else None."""
    with _lockout_lock:
        state = _lockout_state.get(key)
        if not state:
            return None
        remaining = state.get("locked_until", 0) - time.time()
        if remaining > 0:
            return round(remaining)
        return None


def _lockout_record_failure(key: str, threshold: int = 5, base_seconds: int = 60):
    """Call on every failed login/2FA/reset attempt. After `threshold`
    failures the key is locked out with exponential backoff
    (base_seconds, then x2, x4, ... capped at 1 hour)."""
    with _lockout_lock:
        state = _lockout_state.setdefault(key, {"fail_count": 0, "locked_until": 0, "lockout_stage": 0})
        state["fail_count"] += 1
        if state["fail_count"] >= threshold:
            stage = state.get("lockout_stage", 0)
            duration = min(base_seconds * (2 ** stage), 3600)
            state["locked_until"] = time.time() + duration
            state["lockout_stage"] = stage + 1
            state["fail_count"] = 0


def _lockout_clear(key: str):
    """Call on any successful login/2FA/reset — wipes the failure history."""
    with _lockout_lock:
        _lockout_state.pop(key, None)


def _refresh_blocked_ips_cache():
    """Reloads the admin-managed IP blocklist from the DB into the
    in-memory set that every request is checked against. Called once at
    startup and again whenever an admin adds/removes a blocked IP, so the
    hot path (before_request) never touches the database."""
    try:
        rows = BlockedIp.query.filter_by(active=True).all()
        with _blocked_ips_lock:
            _blocked_ips_cache.clear()
            _blocked_ips_cache.update(r.ip_address for r in rows)
        logging.info(f"[FIREWALL] Loaded {len(rows)} blocked IP(s) into cache.")
    except Exception as e:
        logging.error(f"[FIREWALL] Could not load blocked IPs (table may not exist yet): {e}")


