    # pending_quote -> pending_partner (premium paid, no partner configured yet) -> active -> triggered/expired/cancelled
    status                = db.Column(db.String(24), nullable=False, default="pending_quote", index=True)
    premium_paid_at       = db.Column(db.DateTime, nullable=True)
