class ChatLog(db.Model):
    __tablename__ = "chat_logs"
    id             = db.Column(db.Integer,    primary_key=True)
    session_id     = db.Column(db.String(64), nullable=False, index=True)
    channel        = db.Column(db.String(16), nullable=False, default="web")
    role           = db.Column(db.String(16), nullable=False)
    content        = db.Column(db.Text,       nullable=False)
    # Which Connect It business account this conversation belongs to -- e.g. for
    # channel="whatsapp_cloud" this is the business owner whose WhatsApp
    # number received the message (session_id is the *customer's* phone
    # number, so it alone can't answer "show me my recent conversations").
    # Nullable/backfill-safe: existing rows and channels that don't set it
    # (like plain "web" widget chat) are unaffected.
    owner_user_id  = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=True, index=True)
    created_at     = db.Column(db.DateTime,   default=datetime.utcnow)

    def __repr__(self):
        return f"<ChatLog {self.channel} {self.role} {self.created_at}>"

    def to_dict(self) -> dict:
        return {"role": self.role, "content": self.content}


# NEW BLOCK: permanent per-user memory archive ("Activity Log" log book).
# Unlike ChatLog (which is session-keyed and gets pruned/cleared as part of
# normal housekeeping), rows here are tied to a real account and are never
# touched by any automatic cleanup job. This is a tamper-resistant audit
# trail: a user can VIEW their own entries but can never delete them —
# only a recognized admin can soft-delete a single entry or fully wipe an
# account (see /api/admin/memory/wipe), and every such action is logged
# with a reason so it can be produced for a legal/fraud review.
class UserMemory(db.Model):
    __tablename__  = "user_memory"
    id             = db.Column(db.Integer, primary_key=True)
    user_id        = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    role           = db.Column(db.String(16), nullable=False)        # 'user' or 'assistant'
    content_type   = db.Column(db.String(32), nullable=False, default="chat")  # chat, code, doc, calendar, receipt, etc.
    content        = db.Column(db.Text, nullable=False)
    extra_json     = db.Column(db.Text, nullable=True)               # optional: links, filenames, ids, etc.
    created_at     = db.Column(db.DateTime, default=datetime.utcnow, index=True)
    deleted_at     = db.Column(db.DateTime, nullable=True)           # admin-only soft delete

    def to_dict(self) -> dict:
        extra = None
        if self.extra_json:
            try:
                extra = json.loads(self.extra_json)
            except Exception:
                extra = None
        return {
            "id": self.id,
            "role": self.role,
            "content_type": self.content_type,
            "content": self.content,
            "extra": extra,
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }

    def to_admin_dict(self) -> dict:
        """Same as to_dict() but includes the owning account, for admin
        cross-user review/export — never sent to a non-admin caller."""
        d = self.to_dict()
        d["user_id"] = self.user_id
        return d


# NEW BLOCK: hope/positivity content meant for distribution beyond the
# app itself — Telegram, Discord, a public RSS feed, and push notifications.
class BroadcastPost(db.Model):
    __tablename__  = "broadcast_posts"
