class GratitudeEntry(db.Model):
    __tablename__ = "gratitude_gallery"
    id        = db.Column(db.Integer,    primary_key=True)
    user      = db.Column(db.String(64), nullable=False)
    message   = db.Column(db.Text,       nullable=False)
    timestamp = db.Column(db.String(32), nullable=False)
    user_id   = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=True, index=True)
    photo_url = db.Column(db.String(500), nullable=True)

    def to_dict(self, viewer_id=None) -> dict:
        likes = GalleryReaction.query.filter_by(entry_id=self.id, reaction="like").count()
        dislikes = GalleryReaction.query.filter_by(entry_id=self.id, reaction="dislike").count()
        comment_count = GalleryComment.query.filter_by(entry_id=self.id).count()
        viewer_reaction = None
        if viewer_id:
            r = GalleryReaction.query.filter_by(entry_id=self.id, user_id=viewer_id).first()
            viewer_reaction = r.reaction if r else None
        return {
            "id":        self.id,
            "user":      self.user,
            "message":   self.message,
            "timestamp": self.timestamp,
            "user_id":   self.user_id,
            "photo_url": self.photo_url,
            "likes": likes, "dislikes": dislikes, "comment_count": comment_count,
            "viewer_reaction": viewer_reaction,
        }


class GalleryReaction(db.Model):
    __tablename__  = "gallery_reactions"
