# ACTION_REGISTRY maps an action_key to a metadata dict + a handler.
# Handler signature: handler(owner_user_id, org_id, config: dict, context: dict) -> dict
#   - Must never raise for "expected" failures (missing credentials, bad
#     recipient, etc.) — return {"ok": False, "error": "..."} instead.
#   - `context` = {"trigger": <trigger payload>, "steps": {<step_order>: <output>, ...}}
#     so a later step's config can reference an earlier step's output,
#     e.g. {"to": "{{steps.1.customer_email}}"}.

def _automation_action_http_webhook(owner_user_id, org_id, config, context):
    url = _automation_render(config.get("url"), context)
    if not url:
        return {"ok": False, "error": "config.url is required."}
    method = (config.get("method") or "POST").upper()
    body = _automation_render(config.get("body") or {}, context)
    try:
        r = requests.request(method, url, json=body if method != "GET" else None,
                              params=body if method == "GET" else None, timeout=10)
        return {"ok": r.status_code < 400, "status_code": r.status_code, "response_snippet": r.text[:300]}
    except Exception as e:
        return {"ok": False, "error": str(e)}


def _automation_action_zapier_event(owner_user_id, org_id, config, context):
    event_type = _automation_render(config.get("event_type") or "automation_event", context)
    payload = _automation_render(config.get("payload") or context.get("trigger") or {}, context)
    return trigger_zapier_event(owner_user_id, event_type, payload)


def _automation_action_send_email(owner_user_id, org_id, config, context):
    to = _automation_render(config.get("to"), context)
    subject = _automation_render(config.get("subject") or "Notification", context)
    body = _automation_render(config.get("body") or "", context)
    if not to:
        return {"ok": False, "error": "config.to is required."}
    try:
        ok = _send_plain_email(to, subject, body)
        return {"ok": bool(ok)}
    except Exception as e:
        return {"ok": False, "error": str(e)}


def _automation_action_send_whatsapp(owner_user_id, org_id, config, context):
    to = _automation_render(config.get("to"), context)
    text = _automation_render(config.get("text") or "", context)
    if not to or not text:
        return {"ok": False, "error": "config.to and config.text are required."}
    try:
        data = send_whatsapp_cloud_message(owner_user_id, to, text)
        return {"ok": True, "result": data}
    except Exception as e:
        return {"ok": False, "error": str(e)}


def _automation_action_erp_create_customer(owner_user_id, org_id, config, context):
    name = _automation_render(config.get("name"), context)
    if not name:
        return {"ok": False, "error": "config.name is required."}
    try:
        cust = ErpCustomer(
            owner_user_id=owner_user_id, name=name[:200],
            email=_automation_render(config.get("email"), context),
            phone=_automation_render(config.get("phone"), context),
            notes=_automation_render(config.get("notes"), context),
        )
        db.session.add(cust)
        db.session.commit()
        return {"ok": True, "customer_id": cust.id}
    except Exception as e:
        db.session.rollback()
        return {"ok": False, "error": str(e)}


def _automation_action_log_note(owner_user_id, org_id, config, context):
    """No external effect — just records a note in the run log. Useful
    while building a workflow, or as a lightweight audit breadcrumb."""
    return {"ok": True, "note": _automation_render(config.get("note") or "", context)}


def _automation_action_delay(owner_user_id, org_id, config, context):
    """Blocks this background thread for up to 120s. Fine for short
    waits at moderate volume; a real queue (Stage 3+) should replace
    this with a scheduled re-entry instead of a sleep."""
    seconds = min(max(int(config.get("seconds") or 0), 0), 120)
    if seconds:
        _automation_time.sleep(seconds)
    return {"ok": True, "waited_seconds": seconds}


AUTOMATION_ACTION_REGISTRY = {
    "http_webhook": {
        "label": "Call a webhook URL", "handler": _automation_action_http_webhook,
        "config_schema": {"url": "string (required)", "method": "GET|POST|PUT (default POST)", "body": "object"},
    },
    "zapier_event": {
        "label": "Send event to Zapier / Make", "handler": _automation_action_zapier_event,
        "config_schema": {"event_type": "string", "payload": "object (defaults to trigger payload)"},
    },
    "send_email": {
        "label": "Send an email", "handler": _automation_action_send_email,
        "config_schema": {"to": "string (required)", "subject": "string", "body": "string"},
    },
    "send_whatsapp": {
        "label": "Send a WhatsApp message", "handler": _automation_action_send_whatsapp,
        "config_schema": {"to": "string phone (required)", "text": "string (required)"},
    },
    "erp_create_customer": {
        "label": "Create an ERP customer", "handler": _automation_action_erp_create_customer,
        "config_schema": {"name": "string (required)", "email": "string", "phone": "string", "notes": "string"},
    },
    "send_whatsapp_payment_request": {
        "label": "Send a WhatsApp payment request", "handler": (lambda *a, **k: globals()["_automation_action_send_whatsapp_payment_request"](*a, **k)),  # defined later in the file; resolved at call time
        "config_schema": {"invoice_id": "integer (required)"},
    },
    "queue_whatsapp_call": {
        "label": "Queue a WhatsApp call", "handler": (lambda *a, **k: globals()["_automation_action_queue_whatsapp_call"](*a, **k)),  # defined later in the file; resolved at call time
        "config_schema": {"to": "string phone or BSUID (required)",
                          "purpose": "order_confirmation | appointment_reminder | payment_followup | custom",
                          "notes": "string", "reference": "string", "customer_name": "string",
                          "invoice_id": "integer (required for payment_followup)", "scheduled_for": "ISO datetime"},
    },
    "log_note": {
        "label": "Log a note (no-op)", "handler": _automation_action_log_note,
        "config_schema": {"note": "string"},
    },
    "delay": {
        "label": "Wait N seconds", "handler": _automation_action_delay,
        "config_schema": {"seconds": "integer, max 120"},
    },
}


def _automation_get(context, dotted_path):
    """Looks up 'trigger.customer.name' inside context={'trigger': {...}, 'steps': {...}}."""
    cur = context
    for part in (dotted_path or "").split("."):
        if isinstance(cur, dict) and part in cur:
            cur = cur[part]
        else:
            return None
    return cur


_AUTOMATION_TEMPLATE_RE = re.compile(r"\{\{\s*([a-zA-Z0-9_\.]+)\s*\}\}")


def _automation_render(value, context):
    """Recursively replaces {{trigger.x}} / {{steps.1.y}} placeholders
    inside strings, dicts, and lists. A string that is *entirely* one
    placeholder returns the raw looked-up value (so {{trigger.total}}
    can resolve to a number, not just a stringified one); placeholders
    mixed into surrounding text are stringified in place."""
    if isinstance(value, str):
        stripped = value.strip()
        whole_match = _AUTOMATION_TEMPLATE_RE.fullmatch(stripped)
        if whole_match:
            return _automation_get(context, whole_match.group(1))

        def _sub(m):
            looked_up = _automation_get(context, m.group(1))
            return "" if looked_up is None else str(looked_up)
        return _AUTOMATION_TEMPLATE_RE.sub(_sub, value)
    if isinstance(value, dict):
        return {k: _automation_render(v, context) for k, v in value.items()}
    if isinstance(value, list):
        return [_automation_render(v, context) for v in value]
    return value


def _automation_eval_condition(condition, context):
    """condition shapes:
         {"field": "trigger.total", "op": "gt", "value": 100}
         {"all": [<condition>, <condition>, ...]}
         {"any": [<condition>, <condition>, ...]}
       Returns True if condition is falsy/None (no gate = always run)."""
    if not condition:
        return True
    if "all" in condition:
        return all(_automation_eval_condition(c, context) for c in condition["all"])
    if "any" in condition:
        return any(_automation_eval_condition(c, context) for c in condition["any"])

    actual = _automation_get(context, condition.get("field"))
    op = condition.get("op", "eq")
    expected = condition.get("value")
    try:
        if op == "eq":
            return actual == expected
        if op == "neq":
            return actual != expected
        if op == "gt":
            return float(actual) > float(expected)
        if op == "gte":
            return float(actual) >= float(expected)
        if op == "lt":
            return float(actual) < float(expected)
        if op == "lte":
            return float(actual) <= float(expected)
        if op == "contains":
            return expected in (actual or "")
        if op == "exists":
            return actual is not None
    except Exception:
        return False
    return False


# ─────────────────────────────────────────────────────────────
# STAGE 300c: AUTOMATION — EXECUTION ENGINE
# ─────────────────────────────────────────────────────────────

def _automation_gate_run(owner_user_id):
    """Meters each workflow EXECUTION against the owner's plan. This has
    to live here rather than on the CRUD routes above, because the real
    cost (send_email / send_whatsapp calling paid provider APIs) is
    incurred by the ACTION STEPS below, which fire from a background
    job with no Flask session or request — there's no `user` dict to
    gate at a route level. Builds a minimal one from the workflow
    owner's own account instead, so this can reuse the existing
    gate_ai_usage() spend-guard + monthly-FeatureUsage machinery rather
    than duplicating it. Returns None if allowed to run, or a short
    error string if blocked."""
    acct = UserAccount.query.get(owner_user_id)
    if not acct or not acct.is_active:
        return "Workflow owner's account is inactive."
    result = gate_ai_usage({"id": acct.id, "plan": acct.plan}, "automation_workflow_run")
    if result is None:
        return None
    resp, _status = result
    try:
        return (resp.get_json() or {}).get("error") or "This workflow has hit its usage limit."
    except Exception:
        return "This workflow has hit its usage limit."


def _automation_run_workflow(app_ref, workflow_id, trigger_payload):
    """Runs one workflow's steps in order inside its own app context and
    its own AutomationRun row. Never raises out of this function — any
    unexpected exception is caught and recorded as a failed run so a bug
    in one workflow can't take down the thread or any other workflow."""
    app_ref = app_ref or app  # STAGE 239: RQ can't pickle a live Flask app across processes
    with app_ref.app_context():
        workflow = AutomationWorkflow.query.get(workflow_id)
        if not workflow or not workflow.is_active:
            return

        gate_error = _automation_gate_run(workflow.owner_user_id)
        if gate_error:
            # Blocked BEFORE any action step runs, so no send_email /
            # send_whatsapp call (the actual costs) is ever made. Still
            # recorded as a real run so it's visible in run history and
            # counts toward last_run_status — not silently dropped.
            blocked_run = AutomationRun(
                workflow_id=workflow.id, org_id=workflow.org_id, trigger_key=workflow.trigger_key,
                status="blocked", trigger_payload_json=json.dumps(trigger_payload or {})[:8000],
                error_message=gate_error[:500], finished_at=datetime.utcnow(),
            )
            db.session.add(blocked_run)
            workflow.run_count = (workflow.run_count or 0) + 1
            workflow.last_run_at = blocked_run.finished_at
            workflow.last_run_status = "blocked"
            db.session.commit()
            return

        run = AutomationRun(
            workflow_id=workflow.id, org_id=workflow.org_id, trigger_key=workflow.trigger_key,
            status="running", trigger_payload_json=json.dumps(trigger_payload or {})[:8000],
        )
        db.session.add(run)
        db.session.commit()

        context = {"trigger": trigger_payload or {}, "steps": {}}
        overall_status = "success"
        steps = (AutomationStep.query.filter_by(workflow_id=workflow.id)
                 .order_by(AutomationStep.step_order.asc()).all())

        for step in steps:
            action_meta = AUTOMATION_ACTION_REGISTRY.get(step.action_key)
            if not action_meta:
                db.session.add(AutomationRunLog(
                    run_id=run.id, step_id=step.id, step_order=step.step_order, action_key=step.action_key,
                    status="failed", error_message=f"Unknown action_key '{step.action_key}'.",
                ))
                overall_status = "partial" if step.continue_on_error else "failed"
                db.session.commit()
                if not step.continue_on_error:
                    break
                continue

            condition = json.loads(step.condition_json) if step.condition_json else None
            if not _automation_eval_condition(condition, context):
                db.session.add(AutomationRunLog(
                    run_id=run.id, step_id=step.id, step_order=step.step_order,
                    action_key=step.action_key, status="skipped",
                ))
                db.session.commit()
                continue

            config = json.loads(step.config_json) if step.config_json else {}
            try:
                result = action_meta["handler"](workflow.owner_user_id, workflow.org_id, config, context)
            except Exception as e:
                result = {"ok": False, "error": str(e)}

            ok = bool(result.get("ok"))
            db.session.add(AutomationRunLog(
                run_id=run.id, step_id=step.id, step_order=step.step_order, action_key=step.action_key,
                status="success" if ok else "failed",
                output_json=json.dumps(result)[:4000],
                error_message=None if ok else str(result.get("error"))[:500],
            ))
            context["steps"][step.step_order] = result
            db.session.commit()

            if not ok:
                overall_status = "partial" if step.continue_on_error else "failed"
                if not step.continue_on_error:
                    break

        run.status = overall_status
        run.finished_at = datetime.utcnow()
        if overall_status == "failed":
            last_fail = (AutomationRunLog.query.filter_by(run_id=run.id, status="failed")
                         .order_by(AutomationRunLog.id.desc()).first())
            run.error_message = (last_fail.error_message if last_fail else "Workflow failed.")[:500]
        db.session.commit()

        workflow.run_count = (workflow.run_count or 0) + 1
        workflow.last_run_at = run.finished_at
        workflow.last_run_status = overall_status
        db.session.commit()

        _audit(workflow.org_id, workflow.owner_user_id, None, "automation.run_finished",
               "automation_run", run.id, {"workflow_id": workflow.id, "status": overall_status})


def fire_automation_trigger(org_id, trigger_key, payload, run_async=True):
    """Call this from anywhere else in app.py where a real event already
    happens (a new lead captured, a booking made, etc.). Finds every
    active workflow in this org listening for trigger_key and runs each
    one. Fire-and-forget by default (matches trigger_zapier_event's
    existing style) so a slow/broken automation can never delay or
    break the real feature that triggered it."""
    if not org_id or not trigger_key:
        return {"ok": False, "error": "org_id and trigger_key are required.", "queued": 0}

    workflows = AutomationWorkflow.query.filter_by(
        org_id=org_id, trigger_key=trigger_key, is_active=True
    ).all()
    if not workflows:
        return {"ok": True, "queued": 0}

    for wf in workflows:
        if run_async:
            enqueue_job(_automation_run_workflow, app, wf.id, payload)
        else:
            _automation_run_workflow(app, wf.id, payload)

    return {"ok": True, "queued": len(workflows)}


def _automation_org_id_for_user(user_id):
    """Resolves the org_id to fire workflows under for a per-user (not
    per-org) event. Returns None if the user hasn't created/joined a
    workspace yet — fire_automation_trigger() no-ops safely on None."""
    org = _org_for_user(user_id)
    return org.id if org else None


