def _automation_workflow_or_404(workflow_id, user):
    workflow = AutomationWorkflow.query.get(workflow_id)
    if not workflow:
        return None, None, (jsonify({"error": "Workflow not found."}), 404)
    member, err = _org_member_or_403(user, workflow.org_id)
    if err:
        return None, None, err
    return workflow, member, None


