@app.route("/api/automation/workflows", methods=["GET"])
def automation_list_workflows():
    user, err = _erp_user_or_401()
    if err: return err
    org = _org_for_user(user["id"])
    if not org:
        return jsonify({"workflows": []}), 200
    _, err = _org_member_or_403(user, org.id)
    if err: return err
    rows = (AutomationWorkflow.query.filter_by(org_id=org.id)
            .order_by(AutomationWorkflow.created_at.desc()).all())
    return jsonify({"workflows": [w.to_dict() for w in rows]}), 200


@app.route("/api/automation/workflows", methods=["POST"])
@csrf.exempt
def automation_create_workflow():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    org = _org_for_user(user["id"])
    if not org:
        return jsonify({"error": "Create a workspace first (Workspace -> Create)."}), 404
    _, err = _org_member_or_403(user, org.id, roles=("owner", "admin"))
    if err: return err

    data = request.get_json(silent=True) or {}
    name = (data.get("name") or "").strip()
    trigger_key = (data.get("trigger_key") or "").strip()
    if not name:
        return jsonify({"error": "name is required."}), 400
    if trigger_key not in AUTOMATION_TRIGGER_REGISTRY:
        return jsonify({"error": f"trigger_key must be one of: {', '.join(AUTOMATION_TRIGGER_REGISTRY.keys())}."}), 400

    workflow = AutomationWorkflow(
        org_id=org.id, owner_user_id=user["id"], name=name[:120],
        description=(data.get("description") or "").strip()[:500] or None,
        trigger_key=trigger_key, is_active=bool(data.get("is_active", True)),
    )
    db.session.add(workflow)
    db.session.flush()

    for i, step_data in enumerate(data.get("steps") or []):
        action_key = (step_data.get("action_key") or "").strip()
        if action_key not in AUTOMATION_ACTION_REGISTRY:
            db.session.rollback()
            return jsonify({"error": f"Unknown action_key '{action_key}' in step {i}."}), 400
        db.session.add(AutomationStep(
            workflow_id=workflow.id, step_order=i, action_key=action_key,
            config_json=json.dumps(step_data.get("config") or {}),
            condition_json=json.dumps(step_data["condition"]) if step_data.get("condition") else None,
            continue_on_error=bool(step_data.get("continue_on_error", False)),
        ))
    db.session.commit()

    _audit(org.id, user["id"], user["email"], "automation.workflow_created",
           "automation_workflow", workflow.id, {"name": workflow.name, "trigger_key": trigger_key})
    return jsonify({"ok": True, "workflow": workflow.to_dict(include_steps=True)}), 201


@app.route("/api/automation/workflows/<int:workflow_id>", methods=["GET"])
def automation_get_workflow(workflow_id):
    user, err = _erp_user_or_401()
    if err: return err
    workflow, _, err = _automation_workflow_or_404(workflow_id, user)
    if err: return err
    return jsonify({"workflow": workflow.to_dict(include_steps=True)}), 200


@app.route("/api/automation/workflows/<int:workflow_id>", methods=["PUT"])
@csrf.exempt
def automation_update_workflow(workflow_id):
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    workflow = AutomationWorkflow.query.get(workflow_id)
    if not workflow:
        return jsonify({"error": "Workflow not found."}), 404
    _, err = _org_member_or_403(user, workflow.org_id, roles=("owner", "admin"))
    if err: return err

    data = request.get_json(silent=True) or {}
    if "name" in data:
        name = (data.get("name") or "").strip()
        if not name:
            return jsonify({"error": "name cannot be empty."}), 400
        workflow.name = name[:120]
    if "description" in data:
        workflow.description = (data.get("description") or "").strip()[:500] or None
    if "trigger_key" in data:
        trigger_key = (data.get("trigger_key") or "").strip()
        if trigger_key not in AUTOMATION_TRIGGER_REGISTRY:
            return jsonify({"error": f"trigger_key must be one of: {', '.join(AUTOMATION_TRIGGER_REGISTRY.keys())}."}), 400
        workflow.trigger_key = trigger_key
    if "is_active" in data:
        workflow.is_active = bool(data.get("is_active"))

    if "steps" in data:
        AutomationStep.query.filter_by(workflow_id=workflow.id).delete()
        for i, step_data in enumerate(data.get("steps") or []):
            action_key = (step_data.get("action_key") or "").strip()
            if action_key not in AUTOMATION_ACTION_REGISTRY:
                db.session.rollback()
                return jsonify({"error": f"Unknown action_key '{action_key}' in step {i}."}), 400
            db.session.add(AutomationStep(
                workflow_id=workflow.id, step_order=i, action_key=action_key,
                config_json=json.dumps(step_data.get("config") or {}),
                condition_json=json.dumps(step_data["condition"]) if step_data.get("condition") else None,
                continue_on_error=bool(step_data.get("continue_on_error", False)),
            ))

    db.session.commit()
    _audit(workflow.org_id, user["id"], user["email"], "automation.workflow_updated",
           "automation_workflow", workflow.id, {"name": workflow.name})
    return jsonify({"ok": True, "workflow": workflow.to_dict(include_steps=True)}), 200


@app.route("/api/automation/workflows/<int:workflow_id>", methods=["DELETE"])
@csrf.exempt
def automation_delete_workflow(workflow_id):
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    workflow = AutomationWorkflow.query.get(workflow_id)
    if not workflow:
        return jsonify({"error": "Workflow not found."}), 404
    _, err = _org_member_or_403(user, workflow.org_id, roles=("owner", "admin"))
    if err: return err

    AutomationStep.query.filter_by(workflow_id=workflow.id).delete()
    run_ids = [r.id for r in AutomationRun.query.filter_by(workflow_id=workflow.id).all()]
    if run_ids:
        AutomationRunLog.query.filter(AutomationRunLog.run_id.in_(run_ids)).delete(synchronize_session=False)
        AutomationRun.query.filter_by(workflow_id=workflow.id).delete()
    name = workflow.name
    db.session.delete(workflow)
    db.session.commit()
    _audit(workflow.org_id, user["id"], user["email"], "automation.workflow_deleted",
           "automation_workflow", workflow_id, {"name": name})
    return jsonify({"ok": True}), 200


@app.route("/api/automation/workflows/<int:workflow_id>/test-run", methods=["POST"])
@csrf.exempt
def automation_test_run_workflow(workflow_id):
    """Runs the workflow SYNCHRONOUSLY (blocks the request) using either
    a caller-supplied payload or the trigger's registered sample_payload,
    so the builder UI can show results immediately instead of having to
    poll run history."""
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    workflow, _, err = _automation_workflow_or_404(workflow_id, user)
    if err: return err

    data = request.get_json(silent=True) or {}
    payload = data.get("payload")
    if payload is None:
        payload = AUTOMATION_TRIGGER_REGISTRY.get(workflow.trigger_key, {}).get("sample_payload", {})

    _automation_run_workflow(app, workflow.id, payload)
    latest_run = (AutomationRun.query.filter_by(workflow_id=workflow.id)
                  .order_by(AutomationRun.id.desc()).first())
    return jsonify({"ok": True, "run": latest_run.to_dict(include_logs=True) if latest_run else None}), 200


@app.route("/api/automation/workflows/<int:workflow_id>/runs", methods=["GET"])
def automation_list_runs(workflow_id):
    user, err = _erp_user_or_401()
    if err: return err
    workflow, _, err = _automation_workflow_or_404(workflow_id, user)
    if err: return err
    limit = min(request.args.get("limit", default=20, type=int) or 20, 100)
    rows = (AutomationRun.query.filter_by(workflow_id=workflow.id)
            .order_by(AutomationRun.started_at.desc()).limit(limit).all())
    return jsonify({"runs": [r.to_dict() for r in rows]}), 200


@app.route("/api/automation/runs/<int:run_id>", methods=["GET"])
def automation_get_run(run_id):
    user, err = _erp_user_or_401()
    if err: return err
    run = AutomationRun.query.get(run_id)
    if not run:
        return jsonify({"error": "Run not found."}), 404
    _, err = _org_member_or_403(user, run.org_id)
    if err: return err
    return jsonify({"run": run.to_dict(include_logs=True)}), 200


# ════════════════════════════════════════════════════════════
# STAGE 202: EMBEDDABLE CHAT WIDGET
# A <script> snippet a business drops on their own website/app to expose
# Connect It to their own customers, white-labeled with their branding.
# public_key is safe to expose client-side (it only ever unlocks that
# one org's PUBLIC branding + a chat endpoint scoped to that org — never
# the org's internal data, credentials, or admin routes). allowed_domains
# is optional defense-in-depth: if the owner sets it, /api/widget/chat
# rejects requests whose Origin isn't on the list.
# ════════════════════════════════════════════════════════════

class WidgetConfig(db.Model):
    __tablename__     = "widget_configs"
    id                = db.Column(db.Integer,     primary_key=True)
    org_id            = db.Column(db.Integer,     db.ForeignKey("organizations.id"), nullable=False, unique=True, index=True)
    public_key        = db.Column(db.String(64),  nullable=False, unique=True, index=True)
    enabled           = db.Column(db.Boolean,     nullable=False, default=True)
    title             = db.Column(db.String(120), nullable=False, default="Chat with us")
    brand_color       = db.Column(db.String(16),  nullable=False, default="#7c3aed")
    welcome_message   = db.Column(db.String(500), nullable=False, default="Hi! How can I help you today?")
    system_prompt     = db.Column(db.Text,        nullable=True)  # optional business-specific instructions for the AI
    allowed_domains   = db.Column(db.String(1000), nullable=True)  # comma-separated hostnames, empty = allow any
    # STAGE 236: once a fine-tuning job on this org's own conversation
    # data completes, they can point their widget at the resulting model
    # instead of the shared default.
    custom_model_id   = db.Column(db.String(120), nullable=True)
    created_at        = db.Column(db.DateTime,    default=datetime.utcnow)
    updated_at        = db.Column(db.DateTime,    default=datetime.utcnow, onupdate=datetime.utcnow)

    def to_dict(self, include_key=True):
        return {
            "id": self.id, "org_id": self.org_id,
            "public_key": self.public_key if include_key else None,
            "enabled": self.enabled, "title": self.title, "brand_color": self.brand_color,
            "welcome_message": self.welcome_message, "system_prompt": self.system_prompt,
            "allowed_domains": [d.strip() for d in (self.allowed_domains or "").split(",") if d.strip()],
            "custom_model_id": self.custom_model_id,
            "embed_snippet": f'<script src="{APP_BASE_URL}/widget/embed.js?key={self.public_key}" async></script>' if include_key else None,
            "updated_at": self.updated_at.isoformat() if self.updated_at else None,
        }

    def public_dict(self):
        """Only what an anonymous visitor's browser is allowed to see."""
        return {
            "title": self.title, "brand_color": self.brand_color,
            "welcome_message": self.welcome_message, "enabled": self.enabled,
        }


class WidgetMessage(db.Model):
    """Short-lived transcript per anonymous visitor session, used only to
    give the AI conversational context within one widget session."""
    __tablename__  = "widget_messages"
    id             = db.Column(db.Integer,  primary_key=True)
    org_id         = db.Column(db.Integer,  db.ForeignKey("organizations.id"), nullable=False, index=True)
    session_id     = db.Column(db.String(64), nullable=False, index=True)
    role           = db.Column(db.String(16), nullable=False)  # "user" | "assistant"
    content        = db.Column(db.Text,     nullable=False)
    created_at     = db.Column(db.DateTime, default=datetime.utcnow, index=True)


def _widget_cors(resp):
    resp.headers["Access-Control-Allow-Origin"] = "*"
    resp.headers["Access-Control-Allow-Methods"] = "GET, POST, OPTIONS"
    resp.headers["Access-Control-Allow-Headers"] = "Content-Type"
    return resp


@app.route("/api/widget/config", methods=["GET"])
def widget_config_get():
    user, err = _erp_user_or_401()
    if err: return err
    org_id = request.args.get("org_id", type=int)
    if not org_id:
        return jsonify({"error": "org_id is required."}), 400
    _, err = _org_member_or_403(user, org_id, roles=("owner", "admin"))
    if err: return err
    cfg = WidgetConfig.query.filter_by(org_id=org_id).first()
    return jsonify({"config": cfg.to_dict() if cfg else None}), 200


@app.route("/api/widget/config", methods=["POST"])
@csrf.exempt
def widget_config_save():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    org_id = data.get("org_id")
    if not org_id:
        return jsonify({"error": "org_id is required."}), 400
    _, err = _org_member_or_403(user, org_id, roles=("owner", "admin"))
    if err: return err

    cfg = WidgetConfig.query.filter_by(org_id=org_id).first()
    is_new = cfg is None
    if not cfg:
        cfg = WidgetConfig(org_id=org_id, public_key=secrets.token_urlsafe(24))
        db.session.add(cfg)

    if data.get("regenerate_key"):
        cfg.public_key = secrets.token_urlsafe(24)
    if "enabled" in data: cfg.enabled = bool(data["enabled"])
    if "title" in data: cfg.title = (data.get("title") or "Chat with us").strip()[:120]
    if "brand_color" in data: cfg.brand_color = (data.get("brand_color") or "#7c3aed").strip()[:16]
    if "welcome_message" in data: cfg.welcome_message = (data.get("welcome_message") or "").strip()[:500] or cfg.welcome_message
    if "system_prompt" in data: cfg.system_prompt = (data.get("system_prompt") or "").strip()[:4000] or None
    if "allowed_domains" in data:
        domains = data.get("allowed_domains")
        cfg.allowed_domains = ", ".join(d.strip() for d in domains if d.strip()) if isinstance(domains, list) else (data.get("allowed_domains") or "").strip()

    db.session.commit()
    _audit(org_id, user["id"], user["email"], "widget.config_created" if is_new else "widget.config_updated", "widget_config", cfg.id)
    return jsonify({"ok": True, "config": cfg.to_dict()}), 200


@app.route("/api/widget/public-config", methods=["GET", "OPTIONS"])
@csrf.exempt
def widget_public_config():
    if request.method == "OPTIONS":
        return _widget_cors(jsonify({"ok": True}))
    key = (request.args.get("key") or "").strip()
    cfg = WidgetConfig.query.filter_by(public_key=key).first()
    if not cfg or not cfg.enabled:
        return _widget_cors(jsonify({"error": "This chat widget is unavailable."})), 404
    return _widget_cors(jsonify({"config": cfg.public_dict()}))


# ════════════════════════════════════════════════════════════
# STAGE 234: EDGE / OFFLINE-CAPABLE WIDGET
# A real, honestly-scoped version of "edge deployment" for a hosted web
# app: rather than claiming to run a full LLM on someone's phone (not
# feasible here), the widget downloads a small offline bundle — its own
# config plus a compact slice of the org's own knowledge base — and
# caches it on the visitor's device. If the connection drops, the widget
# keeps answering from that cached bundle with the same keyword-overlap
# matching the server uses, queues whatever the customer typed, and
# flushes the queue back through the real AI the moment the connection
# returns. Faster for cached hits, keeps working with no connectivity,
# and never fabricates an answer it can't ground in the cached data.
# ════════════════════════════════════════════════════════════

WIDGET_OFFLINE_BUNDLE_MAX_CHUNKS = 25
WIDGET_OFFLINE_BUNDLE_MAX_CHARS = 500  # per chunk, trimmed for a small on-device payload


@app.route("/api/widget/offline-bundle", methods=["GET", "OPTIONS"])
@csrf.exempt
def widget_offline_bundle():
    if request.method == "OPTIONS":
        return _widget_cors(jsonify({"ok": True}))
    key = (request.args.get("key") or "").strip()
    cfg = WidgetConfig.query.filter_by(public_key=key).first()
    if not cfg or not cfg.enabled:
        return _widget_cors(jsonify({"error": "This chat widget is unavailable."})), 404

    chunks = (KnowledgeChunk.query.filter_by(org_id=cfg.org_id)
              .order_by(KnowledgeChunk.document_id.asc(), KnowledgeChunk.chunk_index.asc())
              .limit(WIDGET_OFFLINE_BUNDLE_MAX_CHUNKS).all())
    offline_texts = [c.text[:WIDGET_OFFLINE_BUNDLE_MAX_CHARS] for c in chunks]

    return _widget_cors(jsonify({
        "config": cfg.public_dict(),
        "offline_chunks": offline_texts,
        "offline_fallback_message": (
            "I'm having trouble connecting right now, but here's what I could find. "
            "I'll follow up properly once we're back online."
        ),
        "generated_at": datetime.utcnow().isoformat(),
    }))



# The customer-facing widget AI ("front desk") is a conversational
# persona and should never guess at account-specific facts (invoice
# balances, stock levels). This adds a second, specialized "back
# office" agent that only ever reads real ERP rows — never
# generates text — and hands its findings to the front-desk AI as
# grounded facts, the same way STAGE 230's knowledge base does for
# static documents. This is real two-agent delegation rather than
# a single model pretending to know things: one agent talks, the
# other only fetches verified data, and they hand off mid-request.
# ════════════════════════════════════════════════════════════

class AgentDelegationLog(db.Model):
    """A record of a front-desk → back-office handoff, so the owner can
    see what live business data the AI has been pulling into chats."""
    __tablename__ = "agent_delegation_log"
    id            = db.Column(db.Integer,  primary_key=True)
    org_id        = db.Column(db.Integer,  db.ForeignKey("organizations.id"), nullable=False, index=True)
    session_id    = db.Column(db.String(64), nullable=False, index=True)
    intent_type   = db.Column(db.String(20), nullable=False)   # invoice | stock | customer
    question      = db.Column(db.Text,     nullable=False)
    result_summary = db.Column(db.Text,    nullable=True)
    created_at    = db.Column(db.DateTime, default=datetime.utcnow, index=True)


_BACKOFFICE_INVOICE_RE = re.compile(r"\b(?:inv(?:oice)?[\s#-]*)([a-z0-9\-]{3,20})\b", re.IGNORECASE)
_BACKOFFICE_EMAIL_RE   = re.compile(r"[\w.+-]+@[\w-]+\.[\w.-]+")
_BACKOFFICE_PHONE_RE   = re.compile(r"\+?\d[\d\s-]{7,14}\d")
_BACKOFFICE_STOCK_WORDS = ("stock", "in stock", "available", "availability", "how many", "do you have")


def _backoffice_extract_intent(message):
    """Cheap, deterministic pattern matching — no AI call needed just to
    decide whether to check the books. Returns {"type", "value"} or None."""
    msg = message.strip()
    m = _BACKOFFICE_INVOICE_RE.search(msg)
    if m:
        return {"type": "invoice", "value": m.group(1)}
    m = _BACKOFFICE_EMAIL_RE.search(msg) or _BACKOFFICE_PHONE_RE.search(msg)
    if m:
        return {"type": "customer", "value": m.group(0)}
    if any(w in msg.lower() for w in _BACKOFFICE_STOCK_WORDS):
        # crude product-name guess: strip stock-related words and question
        # words, keep what's left as the likely product name to search for.
        cleaned = msg.lower()
        for w in _BACKOFFICE_STOCK_WORDS + ("do", "you", "have", "is", "there", "any", "left", "?"):
            cleaned = cleaned.replace(w, "")
        cleaned = cleaned.strip(" .,!")
        if cleaned:
            return {"type": "stock", "value": cleaned}
    return None


def _backoffice_lookup(org, intent):
    """The back-office agent itself: only ever reads real rows, never
    generates prose. Returns a short factual string, or None if nothing
    matched — in which case the front-desk AI just answers normally."""
    owner_id = org.owner_user_id
    if intent["type"] == "invoice":
        inv = (ErpInvoice.query.filter_by(owner_user_id=owner_id)
               .filter(ErpInvoice.invoice_number.ilike(f"%{intent['value']}%")).first())
        if not inv:
            return None
        d = inv.to_dict()
        return (f"Invoice {inv.invoice_number}: status={d['status']}, total={d['total']} {inv.currency}, "
                f"balance due={d['balance_due']} {inv.currency}, due date={d['due_date']}.")
    if intent["type"] == "customer":
        cust = (ErpCustomer.query.filter_by(owner_user_id=owner_id)
                .filter(db.or_(ErpCustomer.email == intent["value"], ErpCustomer.phone == intent["value"])).first())
        if not cust:
            return None
        last_inv = (ErpInvoice.query.filter_by(owner_user_id=owner_id, customer_id=cust.id)
                    .order_by(ErpInvoice.created_at.desc()).first())
        if not last_inv:
            return f"Customer on file: {cust.name}. No invoices yet."
        d = last_inv.to_dict()
        return (f"Customer on file: {cust.name}. Most recent invoice {last_inv.invoice_number}: "
                f"status={d['status']}, balance due={d['balance_due']} {last_inv.currency}.")
    if intent["type"] == "stock":
        item = (InventoryItem.query.filter_by(user_id=owner_id, active=True)
                .filter(InventoryItem.name.ilike(f"%{intent['value']}%")).first())
        if not item:
            return None
        price = f", price {item.unit_price}" if item.unit_price else ""
        return f"{item.name}: {item.quantity} {item.unit or 'units'} in stock{price}."
    return None


def _backoffice_delegate(org_id, session_id, message):
    """Full front-desk → back-office handoff for one customer message.
    Best-effort and silent on failure — a lookup problem should never
    break the chat, it just means the AI answers without that context."""
    try:
        org = Organization.query.get(org_id)
        if not org:
            return None
        intent = _backoffice_extract_intent(message)
        if not intent:
            return None
        result = _backoffice_lookup(org, intent)
        db.session.add(AgentDelegationLog(
            org_id=org_id, session_id=session_id, intent_type=intent["type"],
            question=message[:300], result_summary=(result or "no match")[:300],
        ))
        db.session.commit()
        return result
    except Exception as e:
        logging.error(f"[BACKOFFICE DELEGATE] org={org_id}: {e}")
        return None



@csrf.exempt
def widget_chat():
    if request.method == "OPTIONS":
        return _widget_cors(jsonify({"ok": True}))

    data = request.get_json(silent=True) or {}
    key = (data.get("key") or "").strip()
    session_id = (data.get("session_id") or "").strip() or secrets.token_hex(12)
    message = (data.get("message") or "").strip()

    cfg = WidgetConfig.query.filter_by(public_key=key).first()
    if not cfg or not cfg.enabled:
        return _widget_cors(jsonify({"error": "This chat widget is unavailable."})), 404
    if not message:
        return _widget_cors(jsonify({"error": "message is required."})), 400

    allowed = [d.strip().lower() for d in (cfg.allowed_domains or "").split(",") if d.strip()]
    if allowed:
        origin_host = urllib.parse.urlparse(request.headers.get("Origin") or request.headers.get("Referer") or "").hostname or ""
        if origin_host.lower() not in allowed:
            return _widget_cors(jsonify({"error": "This domain is not authorized to use this chat widget."})), 403

    if _rate_limited(f"widget:key:{key}:ip:{_client_ip()}", max_attempts=30, window_seconds=60):
        return _widget_cors(jsonify({"error": "Too many messages. Please slow down."})), 429

    # STAGE (metering gap fix): the visitor sending this message is
    # anonymous by design (this is a public embeddable widget) — the
    # real cost is billed against the WIDGET OWNER's plan, so gate on
    # them, same pattern as the automation engine's background-job gate.
    widget_org = Organization.query.get(cfg.org_id)
    if widget_org and widget_org.owner_user_id:
        owner_acct = UserAccount.query.get(widget_org.owner_user_id)
        if owner_acct:
            gate_result = gate_ai_usage({"id": owner_acct.id, "plan": owner_acct.plan}, "widget_chat")
            if gate_result is not None:
                resp, status = gate_result
                return _widget_cors(resp), status

    is_first = WidgetMessage.query.filter_by(org_id=cfg.org_id, session_id=session_id).first() is None
    history_rows = (WidgetMessage.query.filter_by(org_id=cfg.org_id, session_id=session_id)
                     .order_by(WidgetMessage.created_at.asc()).limit(20).all())
    history = [{"role": r.role, "content": r.content} for r in history_rows]

    system_prompt = cfg.system_prompt or f"You are a helpful support assistant for this business (widget title: '{cfg.title}'). Be concise and friendly."

    # STAGE 230: ground the reply in the business's own knowledge base, if
    # they've added one and any chunks match this message. Best-effort —
    # a retrieval failure should never break the chat itself.
    try:
        kb_chunks = _kb_retrieve(cfg.org_id, message)
    except Exception as e:
        logging.error(f"[KB RETRIEVE] org={cfg.org_id}: {e}")
        kb_chunks = []
    if kb_chunks:
        kb_context = "\n\n---\n\n".join(kb_chunks)
        system_prompt = (
            system_prompt +
            "\n\nUse the following information from this business's own knowledge base to answer "
            "the customer's question when it's relevant. If the knowledge base doesn't cover their "
            "question, answer normally from general knowledge — don't say you 'don't have that in "
            "the knowledge base'.\n\n" + kb_context
        )

    # STAGE 233: delegate to the back-office agent for anything account-
    # specific (an invoice number, their own contact details, a stock
    # question) — this agent only reads real rows, never guesses, so its
    # answer is authoritative where the front-desk persona's own general
    # knowledge would otherwise have to hedge or make something up.
    backoffice_fact = _backoffice_delegate(cfg.org_id, session_id, message)
    if backoffice_fact:
        system_prompt = (
            system_prompt +
            "\n\nYour back-office system just looked this up for you — it is live, authoritative "
            "business data, treat it as fact and use it to answer directly:\n" + backoffice_fact
        )

    try:
        # STAGE 236: if this org has activated a fine-tuned model (trained
        # on their own conversation history), use it directly instead of
        # the shared multi-provider default — it's OpenAI-specific, so it
        # bypasses generate_ai_reply's provider abstraction.
        if cfg.custom_model_id:
            byok_key = get_effective_credential(widget_org.owner_user_id if widget_org else None, "openai", "api_key", None)
            client = OpenAI(api_key=byok_key) if byok_key else openai_client
            if not client:
                raise RuntimeError("Custom model configured but no OpenAI key available.")
            completion = client.chat.completions.create(
                model=cfg.custom_model_id,
                messages=[{"role": "system", "content": system_prompt}] + history + [{"role": "user", "content": message}],
            )
            reply = completion.choices[0].message.content
        else:
            reply, _ = generate_ai_reply(message, history, system_prompt=system_prompt)
    except Exception as e:
        logging.error(f"[WIDGET CHAT ERROR] org={cfg.org_id}: {e}")
        return _widget_cors(jsonify({"error": "The assistant is temporarily unavailable. Please try again."})), 502

    db.session.add(WidgetMessage(org_id=cfg.org_id, session_id=session_id, role="user", content=message[:4000]))
    assistant_msg = WidgetMessage(org_id=cfg.org_id, session_id=session_id, role="assistant", content=str(reply)[:4000])
    db.session.add(assistant_msg)
    db.session.flush()  # STAGE 231: need assistant_msg.id before commit, so the widget can poll for anything newer
    assistant_msg_id = assistant_msg.id
    db.session.commit()

    if is_first:
        _audit(cfg.org_id, None, None, "widget.session_started", "widget_session", session_id, {"origin": request.headers.get("Origin")})

    return _widget_cors(jsonify({"ok": True, "reply": reply, "session_id": session_id, "message_id": assistant_msg_id}))


@app.route("/api/widget/messages", methods=["GET", "OPTIONS"])
def widget_messages_poll():
    """STAGE 231: lightweight polling endpoint so a live customer session
    can pick up a message the business owner sends from the admin mission
    control dashboard, without the customer needing to send anything
    themselves first."""
    if request.method == "OPTIONS":
        return _widget_cors(jsonify({"ok": True}))
    key = (request.args.get("key") or "").strip()
    session_id = (request.args.get("session_id") or "").strip()
    after_id = request.args.get("after_id", 0, type=int)
    cfg = WidgetConfig.query.filter_by(public_key=key).first()
    if not cfg or not cfg.enabled or not session_id:
        return _widget_cors(jsonify({"error": "This chat widget is unavailable."})), 404
    rows = (WidgetMessage.query.filter_by(org_id=cfg.org_id, session_id=session_id)
            .filter(WidgetMessage.id > after_id)
            .order_by(WidgetMessage.id.asc()).limit(50).all())
    return _widget_cors(jsonify({"ok": True, "messages": [
        {"id": r.id, "role": r.role, "content": r.content, "created_at": r.created_at.isoformat()} for r in rows
    ]}))


# ════════════════════════════════════════════════════════════
# STAGE 230: KNOWLEDGE BASE / RAG
# Lets an owner feed their own documents (FAQs, policies, product
# catalogs, pasted text) into their widget's AI, so the assistant
# answers from THIS business's own facts instead of only general
# knowledge. No vector DB dependency is added — chunks are scored
# by keyword overlap at query time, which is cheap, has zero extra
# infra, and is plenty accurate for the FAQ-length documents small
# businesses actually upload here.
# ════════════════════════════════════════════════════════════

KB_CHUNK_SIZE = 900       # characters per chunk
KB_CHUNK_OVERLAP = 150    # characters of overlap between consecutive chunks
KB_MAX_DOC_CHARS = 200_000  # ~50k words per document, generous for a FAQ/catalog/policy doc
KB_TOP_K = 4              # chunks injected into the AI's context per customer message
KB_MAX_CONTEXT_CHARS = 2800  # total chars of retrieved context capped, so prompts stay bounded

KB_STOPWORDS = {
    "the", "a", "an", "and", "or", "but", "is", "are", "was", "were", "be", "been", "being",
    "to", "of", "in", "on", "at", "for", "with", "as", "by", "that", "this", "it", "its",
    "from", "you", "your", "i", "we", "they", "he", "she", "do", "does", "did", "have", "has",
    "had", "will", "would", "can", "could", "should", "what", "when", "where", "how", "why",
    "not", "no", "yes", "if", "so", "my", "me", "us", "our", "their", "his", "her", "him",
}


class KnowledgeDocument(db.Model):
    """One uploaded/pasted knowledge-base source document per org."""
    __tablename__ = "knowledge_documents"
    id          = db.Column(db.Integer,  primary_key=True)
    org_id      = db.Column(db.Integer,  db.ForeignKey("organizations.id"), nullable=False, index=True)
    title       = db.Column(db.String(200), nullable=False)
    source      = db.Column(db.String(20),  nullable=False, default="pasted")  # "pasted" | "upload"
    char_count  = db.Column(db.Integer,  nullable=False, default=0)
    created_at  = db.Column(db.DateTime, default=datetime.utcnow, index=True)

    def to_dict(self):
        return {
            "id": self.id, "title": self.title, "source": self.source,
            "char_count": self.char_count, "created_at": self.created_at.isoformat(),
        }


class KnowledgeChunk(db.Model):
    """A single retrievable slice of a KnowledgeDocument's text, precomputed
    at ingestion time so query-time retrieval never has to re-split text."""
    __tablename__ = "knowledge_chunks"
    id           = db.Column(db.Integer,  primary_key=True)
    document_id  = db.Column(db.Integer,  db.ForeignKey("knowledge_documents.id"), nullable=False, index=True)
    org_id       = db.Column(db.Integer,  db.ForeignKey("organizations.id"), nullable=False, index=True)
    chunk_index  = db.Column(db.Integer,  nullable=False, default=0)
    text         = db.Column(db.Text,     nullable=False)


def _kb_tokenize(text):
    words = re.findall(r"[a-zA-Z0-9']+", (text or "").lower())
    return [w for w in words if w not in KB_STOPWORDS and len(w) > 1]


def _kb_chunk_text(text):
    """Splits on paragraph boundaries where possible, falling back to a
    fixed-size sliding window so no single chunk blows past KB_CHUNK_SIZE."""
    text = text.strip()
    if not text:
        return []
    chunks = []
    start = 0
    n = len(text)
    while start < n:
        end = min(start + KB_CHUNK_SIZE, n)
        # try to break on a paragraph/sentence boundary near the end
        if end < n:
            boundary = text.rfind("\n\n", start, end)
            if boundary == -1 or boundary <= start + 200:
                boundary = text.rfind(". ", start, end)
            if boundary != -1 and boundary > start + 200:
                end = boundary + 1
        chunk = text[start:end].strip()
        if chunk:
            chunks.append(chunk)
        if end >= n:
            break
        start = max(end - KB_CHUNK_OVERLAP, start + 1)
    return chunks


def _kb_retrieve(org_id, query, top_k=KB_TOP_K, max_chars=KB_MAX_CONTEXT_CHARS):
    """Keyword-overlap retrieval — scores every chunk in this org's
    knowledge base against the query's terms and returns the best few,
    capped at max_chars total so it can't blow out the AI prompt."""
    q_terms = _kb_tokenize(query)
    if not q_terms:
        return []
    rows = KnowledgeChunk.query.filter_by(org_id=org_id).all()
    if not rows:
        return []
    scored = []
    for r in rows:
        chunk_terms = _kb_tokenize(r.text)
        if not chunk_terms:
            continue
        chunk_counts = {}
        for t in chunk_terms:
            chunk_counts[t] = chunk_counts.get(t, 0) + 1
        score = sum(chunk_counts.get(t, 0) for t in q_terms)
        if score > 0:
            scored.append((score, r))
    scored.sort(key=lambda p: p[0], reverse=True)
    picked, used_chars = [], 0
    for score, r in scored[: top_k * 2]:  # look a little wider than top_k, then cap by char budget
        if used_chars >= max_chars or len(picked) >= top_k:
            break
        picked.append(r.text)
        used_chars += len(r.text)
    return picked


@app.route("/api/knowledge/documents", methods=["GET"])
def knowledge_documents_list():
    user, err = _erp_user_or_401()
    if err: return err
    org = _org_for_user(user["id"])
    if not org:
        return jsonify({"error": "No workspace found."}), 404
    _, err = _org_member_or_403(user, org.id)
    if err: return err
    docs = (KnowledgeDocument.query.filter_by(org_id=org.id)
            .order_by(KnowledgeDocument.created_at.desc()).all())
    return jsonify({"documents": [d.to_dict() for d in docs]}), 200


@app.route("/api/knowledge/documents", methods=["POST"])
@csrf.exempt
def knowledge_documents_add():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    org = _org_for_user(user["id"])
    if not org:
        return jsonify({"error": "No workspace found."}), 404
    _, err = _org_member_or_403(user, org.id, roles=("owner", "admin"))
    if err: return err

    data = request.get_json(silent=True) or {}
    title = (data.get("title") or "").strip()[:200]
    content = (data.get("content") or "").strip()
    source = "upload" if data.get("source") == "upload" else "pasted"
    if not title or not content:
        return jsonify({"error": "title and content are required."}), 400
    if len(content) > KB_MAX_DOC_CHARS:
        return jsonify({"error": f"Document is too long (max {KB_MAX_DOC_CHARS:,} characters). Split it into smaller documents."}), 400

    doc = KnowledgeDocument(org_id=org.id, title=title, source=source, char_count=len(content))
    db.session.add(doc)
    db.session.flush()  # get doc.id before committing chunks

    for i, chunk_text in enumerate(_kb_chunk_text(content)):
        db.session.add(KnowledgeChunk(document_id=doc.id, org_id=org.id, chunk_index=i, text=chunk_text))

    db.session.commit()
    _audit(org.id, user["id"], user["email"], "knowledge.document_added", "knowledge_document", doc.id, {"title": title})
    return jsonify({"ok": True, "document": doc.to_dict()}), 200


@app.route("/api/knowledge/documents/<int:doc_id>", methods=["DELETE"])
@csrf.exempt
def knowledge_documents_delete(doc_id):
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    org = _org_for_user(user["id"])
    if not org:
        return jsonify({"error": "No workspace found."}), 404
    _, err = _org_member_or_403(user, org.id, roles=("owner", "admin"))
    if err: return err

    doc = KnowledgeDocument.query.filter_by(id=doc_id, org_id=org.id).first()
    if not doc:
        return jsonify({"error": "Document not found."}), 404
    KnowledgeChunk.query.filter_by(document_id=doc.id).delete()
    title = doc.title
    db.session.delete(doc)
    db.session.commit()
    _audit(org.id, user["id"], user["email"], "knowledge.document_deleted", "knowledge_document", doc_id, {"title": title})
    return jsonify({"ok": True}), 200


@app.route("/api/knowledge/test-query", methods=["POST"])
@csrf.exempt
def knowledge_test_query():
    """Lets the owner sanity-check retrieval — 'if a customer asked X,
    what would the AI pull from my knowledge base?' — without needing to
    actually go message the live widget."""
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    org = _org_for_user(user["id"])
    if not org:
        return jsonify({"error": "No workspace found."}), 404
    _, err = _org_member_or_403(user, org.id)
    if err: return err
    data = request.get_json(silent=True) or {}
    query = (data.get("query") or "").strip()
    if not query:
        return jsonify({"error": "query is required."}), 400
    chunks = _kb_retrieve(org.id, query)
    return jsonify({"query": query, "matched_chunks": chunks, "match_count": len(chunks)}), 200


# ════════════════════════════════════════════════════════════
# STAGE 232: UNIFIED ADMIN MISSION CONTROL DASHBOARD
# One panel for the owner instead of scattered ones: workspace vitals,
# live/recent widget conversations with the ability to read the full
# thread and reply directly (bypassing the AI for that message — the
# customer's widget picks it up via the STAGE 231 polling endpoint),
# and quick counts that link out to the fuller Analytics/Knowledge
# Base panels rather than re-implementing them here.
# ════════════════════════════════════════════════════════════

@app.route("/api/admin/dashboard/summary", methods=["GET"])
def admin_dashboard_summary():
    user, err = _erp_user_or_401()
    if err: return err
    org = _org_for_user(user["id"])
    if not org:
        return jsonify({"error": "No workspace found."}), 404
    _, err = _org_member_or_403(user, org.id, roles=("owner", "admin"))
    if err: return err

    since_7d = datetime.utcnow() - timedelta(days=7)
    recent_rows = WidgetMessage.query.filter_by(org_id=org.id).filter(WidgetMessage.created_at >= since_7d).all()
    sessions_7d = {}
    for r in recent_rows:
        sessions_7d.setdefault(r.session_id, []).append(r)
    unresolved = sum(1 for msgs in sessions_7d.values() if msgs[-1].role == "user")

    member_count = OrgMember.query.filter_by(org_id=org.id, status="active").count()
    doc_count = KnowledgeDocument.query.filter_by(org_id=org.id).count()
    widget_cfg = WidgetConfig.query.filter_by(org_id=org.id).first()
    delegations_7d = AgentDelegationLog.query.filter_by(org_id=org.id).filter(AgentDelegationLog.created_at >= since_7d).count()

    return jsonify({
        "org_name": org.name, "plan": org.plan, "subscription_status": org.subscription_status,
        "member_count": member_count, "knowledge_doc_count": doc_count,
        "conversations_7d": len(sessions_7d), "unresolved_7d": unresolved,
        "delegations_7d": delegations_7d,
        "widget_configured": widget_cfg is not None and widget_cfg.enabled,
        # STAGE 234: whether the widget has enough knowledge-base content
        # cached client-side to answer something useful while offline.
        "offline_ready": doc_count > 0,
    }), 200


@app.route("/api/admin/dashboard/delegations", methods=["GET"])
def admin_dashboard_delegations():
    """Recent front-desk → back-office handoffs, so the owner can see
    exactly what live business data the AI has been pulling into chats."""
    user, err = _erp_user_or_401()
    if err: return err
    org = _org_for_user(user["id"])
    if not org:
        return jsonify({"error": "No workspace found."}), 404
    _, err = _org_member_or_403(user, org.id, roles=("owner", "admin"))
    if err: return err
    limit = min(request.args.get("limit", 20, type=int), 100)
    rows = (AgentDelegationLog.query.filter_by(org_id=org.id)
            .order_by(AgentDelegationLog.created_at.desc()).limit(limit).all())
    return jsonify({"delegations": [
        {"id": r.id, "session_id": r.session_id, "intent_type": r.intent_type,
         "question": r.question, "result_summary": r.result_summary,
         "created_at": r.created_at.isoformat()} for r in rows
    ]}), 200


@app.route("/api/admin/dashboard/conversations", methods=["GET"])
def admin_dashboard_conversations():
    user, err = _erp_user_or_401()
    if err: return err
    org = _org_for_user(user["id"])
    if not org:
        return jsonify({"error": "No workspace found."}), 404
    _, err = _org_member_or_403(user, org.id, roles=("owner", "admin"))
    if err: return err

    limit = min(request.args.get("limit", 25, type=int), 100)
    since = datetime.utcnow() - timedelta(days=14)
    rows = (WidgetMessage.query.filter_by(org_id=org.id).filter(WidgetMessage.created_at >= since)
            .order_by(WidgetMessage.created_at.asc()).all())
    sessions = {}
    for r in rows:
        sessions.setdefault(r.session_id, []).append(r)

    out = []
    for sid, msgs in sessions.items():
        last = msgs[-1]
        out.append({
            "session_id": sid, "message_count": len(msgs),
            "last_message": last.content[:160], "last_role": last.role,
            "last_activity": last.created_at.isoformat(),
            "awaiting_reply": last.role == "user",
        })
    out.sort(key=lambda c: c["last_activity"], reverse=True)
    return jsonify({"conversations": out[:limit]}), 200


@app.route("/api/admin/dashboard/conversations/<session_id>", methods=["GET"])
def admin_dashboard_conversation_thread(session_id):
    user, err = _erp_user_or_401()
    if err: return err
    org = _org_for_user(user["id"])
    if not org:
        return jsonify({"error": "No workspace found."}), 404
    _, err = _org_member_or_403(user, org.id, roles=("owner", "admin"))
    if err: return err
    msgs = (WidgetMessage.query.filter_by(org_id=org.id, session_id=session_id)
            .order_by(WidgetMessage.created_at.asc()).all())
    if not msgs:
        return jsonify({"error": "Conversation not found."}), 404
    return jsonify({"session_id": session_id, "messages": [
        {"id": m.id, "role": m.role, "content": m.content, "created_at": m.created_at.isoformat()} for m in msgs
    ]}), 200


@app.route("/api/admin/dashboard/conversations/<session_id>/reply", methods=["POST"])
@csrf.exempt
def admin_dashboard_conversation_reply(session_id):
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    org = _org_for_user(user["id"])
    if not org:
        return jsonify({"error": "No workspace found."}), 404
    _, err = _org_member_or_403(user, org.id, roles=("owner", "admin"))
    if err: return err

    data = request.get_json(silent=True) or {}
    message = (data.get("message") or "").strip()
    if not message:
        return jsonify({"error": "message is required."}), 400
    if not WidgetMessage.query.filter_by(org_id=org.id, session_id=session_id).first():
        return jsonify({"error": "Conversation not found."}), 404

    # Sent as role="assistant" so it flows through the same customer-facing
    # bubble, but prefixed so it's visibly a human, not the AI, replying —
    # and so the owner can tell their own overrides apart in the thread view.
    msg = WidgetMessage(org_id=org.id, session_id=session_id, role="assistant",
                         content=("[Team] " + message)[:4000])
    db.session.add(msg)
    db.session.flush()
    msg_id = msg.id
    db.session.commit()
    _audit(org.id, user["id"], user["email"], "widget.admin_reply", "widget_session", session_id, {"message": message[:200]})
    return jsonify({"ok": True, "message_id": msg_id}), 200



def widget_embed_js():
    """Serves the actual embeddable script. A business pastes:
    <script src=".../widget/embed.js?key=THEIR_PUBLIC_KEY" async></script>
    and gets a floating chat bubble in the bottom-right corner of their
    own site, talking only to their own org's widget config/AI."""
    key = (request.args.get("key") or "").strip()
    js = """
(function(){
  var KEY = __RJ_KEY__, BASE = __RJ_BASE__;
  function el(tag, attrs, parent){ var e=document.createElement(tag); Object.keys(attrs||{}).forEach(function(k){ if(k==='text') e.textContent=attrs[k]; else e.setAttribute(k, attrs[k]); }); if(parent) parent.appendChild(e); return e; }
  var sessionId = localStorage.getItem('connectit_widget_session') || (Date.now().toString(36)+Math.random().toString(36).slice(2));
  try{ localStorage.setItem('connectit_widget_session', sessionId); }catch(e){}
  var CACHE_KEY = 'connectit_offline_bundle_' + KEY;
  var QUEUE_KEY = 'connectit_offline_queue_' + KEY;
  function getCachedBundle(){ try{ var raw=localStorage.getItem(CACHE_KEY); return raw?JSON.parse(raw):null; }catch(e){ return null; } }
  function setCachedBundle(b){ try{ localStorage.setItem(CACHE_KEY, JSON.stringify(b)); }catch(e){} }
  function getQueue(){ try{ var raw=localStorage.getItem(QUEUE_KEY); return raw?JSON.parse(raw):[]; }catch(e){ return []; } }
  function setQueue(q){ try{ localStorage.setItem(QUEUE_KEY, JSON.stringify(q)); }catch(e){} }
  // STAGE 234: tiny client-side port of the server's keyword-overlap
  // retrieval, used only when the network request itself has failed —
  // this is what makes the widget still useful with no connectivity,
  // instead of just showing an error.
  var STOP = {the:1,a:1,an:1,and:1,or:1,but:1,is:1,are:1,was:1,were:1,to:1,of:1,in:1,on:1,at:1,for:1,with:1,as:1,by:1,that:1,this:1,it:1,from:1,you:1,your:1,i:1,we:1,they:1,do:1,does:1,did:1,have:1,has:1,had:1,will:1,would:1,can:1,could:1,should:1,what:1,when:1,where:1,how:1,why:1,not:1,so:1,my:1,me:1};
  function tok(s){ var m=(s||'').toLowerCase().match(/[a-z0-9']+/g); return (m||[]).filter(function(w){ return w.length>1 && !STOP[w]; }); }
  function offlineAnswer(bundle, message){
    var qTerms = tok(message);
    if (!qTerms.length || !bundle.offline_chunks || !bundle.offline_chunks.length) return null;
    var best = null, bestScore = 0;
    bundle.offline_chunks.forEach(function(chunk){
      var terms = tok(chunk), counts = {};
      terms.forEach(function(t){ counts[t] = (counts[t]||0)+1; });
      var score = qTerms.reduce(function(s,t){ return s + (counts[t]||0); }, 0);
      if (score > bestScore){ bestScore = score; best = chunk; }
    });
    return best;
  }
  function fetchBundleFresh(){
    return fetch(BASE+'/api/widget/offline-bundle?key='+encodeURIComponent(KEY)).then(function(r){return r.json();}).then(function(data){
      if (data && data.config) setCachedBundle(data);
      return data;
    });
  }
  fetchBundleFresh().catch(function(){ return null; }).then(function(fresh){
    var data = (fresh && fresh.config) ? fresh : getCachedBundle();
    if (!data || !data.config || !data.config.enabled) return;
    var cfg = data.config;
    var bubble = el('button',{id:'rj-widget-bubble'}, document.body);
    bubble.textContent = '';
    bubble.style.cssText = 'position:fixed;bottom:20px;right:20px;width:56px;height:56px;border-radius:50%;background:'+cfg.brand_color+';color:#fff;border:none;font-size:24px;cursor:pointer;box-shadow:0 4px 14px rgba(0,0,0,.25);z-index:999999;';
    var panel = el('div',{id:'rj-widget-panel'}, document.body);
    panel.style.cssText = 'display:none;position:fixed;bottom:86px;right:20px;width:320px;max-height:460px;background:#fff;border-radius:12px;box-shadow:0 8px 30px rgba(0,0,0,.25);z-index:999999;flex-direction:column;overflow:hidden;font-family:sans-serif;';
    var head = el('div',{},panel); head.style.cssText='background:'+cfg.brand_color+';color:#fff;padding:12px 14px;font-weight:600;'; head.textContent = cfg.title;
    var body = el('div',{id:'rj-widget-body'},panel); body.style.cssText='flex:1;overflow-y:auto;padding:10px;font-size:14px;max-height:320px;';
    var welcome = el('div',{},body); welcome.style.cssText='background:#f1f1f4;padding:8px 10px;border-radius:8px;margin-bottom:8px;max-width:85%;'; welcome.textContent = cfg.welcome_message;
    var inputRow = el('div',{},panel); inputRow.style.cssText='display:flex;border-top:1px solid #eee;';
    var input = el('input',{type:'text',placeholder:'Type a message…'},inputRow); input.style.cssText='flex:1;border:none;padding:10px;font-size:14px;outline:none;';
    var send = el('button',{text:'➤'},inputRow); send.style.cssText='border:none;background:none;color:'+cfg.brand_color+';font-size:18px;padding:0 12px;cursor:pointer;';
    function addMsg(text, who){ var m=el('div',{},body); m.textContent=text; m.style.cssText='padding:8px 10px;border-radius:8px;margin-bottom:8px;max-width:85%;'+(who==='user'?'background:'+cfg.brand_color+';color:#fff;margin-left:auto;':'background:#f1f1f4;'); body.scrollTop=body.scrollHeight; }
    var lastMsgId = 0;
    function sendLive(text){
      return fetch(BASE+'/api/widget/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({key:KEY,session_id:sessionId,message:text})}).then(function(r){return r.json();});
    }
    function flushQueue(){
      var q = getQueue();
      if (!q.length) return;
      setQueue([]);
      q.forEach(function(text){
        sendLive(text).then(function(d){
          addMsg((d.reply || d.error || 'Sorry, something went wrong.'), 'bot');
          if (d.message_id) lastMsgId = d.message_id;
        }).catch(function(){ var q2=getQueue(); q2.push(text); setQueue(q2); });
      });
    }
    function doSend(){
      var text=input.value.trim(); if(!text) return; input.value=''; addMsg(text,'user');
      sendLive(text).then(function(d){
        addMsg(d.reply || d.error || 'Sorry, something went wrong.', 'bot');
        if(d.message_id) lastMsgId = d.message_id;
      }).catch(function(){
        // STAGE 234: no connection — answer from the cached offline
        // bundle if anything matches, and queue the message so it still
        // gets a real AI answer once we're back online.
        var q = getQueue(); q.push(text); setQueue(q);
        var bundle = getCachedBundle();
        var match = bundle ? offlineAnswer(bundle, text) : null;
        var fallback = (bundle && bundle.offline_fallback_message) || "I'm having trouble connecting right now \u2014 I'll follow up once we're back online.";
        addMsg(match ? (match + '\\n\\n' + fallback) : fallback, 'bot');
      });
    }
    send.onclick = doSend;
    input.addEventListener('keydown', function(e){ if(e.key==='Enter') doSend(); });
    window.addEventListener('online', flushQueue);
    if (navigator.onLine) flushQueue();
    // STAGE 232: poll for a human teammate joining the conversation from the
    // admin dashboard — shows up here without the customer needing to send
    // anything first.
    setInterval(function(){
      if (!navigator.onLine) return;
      fetch(BASE+'/api/widget/messages?key='+encodeURIComponent(KEY)+'&session_id='+encodeURIComponent(sessionId)+'&after_id='+lastMsgId)
        .then(function(r){return r.json();}).then(function(d){
          (d.messages||[]).forEach(function(m){
            if (m.id > lastMsgId){ lastMsgId = m.id; if (m.role === 'assistant') addMsg(m.content, 'bot'); }
          });
        }).catch(function(){});
    }, 5000);
    bubble.onclick = function(){ panel.style.display = panel.style.display==='none' || !panel.style.display ? 'flex' : 'none'; };
  });
})();
"""
    js = js.replace("__RJ_KEY__", json.dumps(key)).replace("__RJ_BASE__", json.dumps(APP_BASE_URL))
    resp = Response(js, mimetype="application/javascript")
    return _widget_cors(resp)


# ════════════════════════════════════════════════════════════
# STAGE 221: WHATSAPP OPT-IN WIDGET
# A drop-in <form> a business embeds on their OWN checkout/website to
# capture explicit WhatsApp consent (name, phone, timestamped consent
# text) from THEIR customers before messaging them — separate from the
# WhatsApp Business Gateway connect flow above, which links the
# business's own WhatsApp Business API credentials to Connect It.
# Same public_key pattern as WidgetConfig: safe to expose client-side,
# it only ever unlocks submission into that one user's lead list — never
# their account, credentials, or admin routes. Tied to user_id (not
# org_id) since a solo SME may never create an Organization.
# ════════════════════════════════════════════════════════════

class WhatsAppOptInWidget(db.Model):
    __tablename__  = "whatsapp_optin_widgets"
    id             = db.Column(db.Integer,     primary_key=True)
    user_id        = db.Column(db.Integer,     db.ForeignKey("user_accounts.id"), nullable=False, unique=True, index=True)
    public_key     = db.Column(db.String(64),  nullable=False, unique=True, index=True)
    business_name  = db.Column(db.String(200), nullable=False, default="our business")
    enabled        = db.Column(db.Boolean,     nullable=False, default=True)
    created_at     = db.Column(db.DateTime,    default=datetime.utcnow)
    updated_at     = db.Column(db.DateTime,    default=datetime.utcnow, onupdate=datetime.utcnow)

    def to_dict(self):
        return {
            "id": self.id, "public_key": self.public_key,
            "business_name": self.business_name, "enabled": self.enabled,
            "optin_endpoint": f"{APP_BASE_URL}/api/public/whatsapp-optin?key={self.public_key}",
            "updated_at": self.updated_at.isoformat() if self.updated_at else None,
        }


class WhatsAppOptInLead(db.Model):
    """One consent-captured submission from a business's embedded opt-in
    form. Kept as its own append-only audit trail (never edited) even
    though we also upsert a CrmContact so the lead shows up in the CRM."""
    __tablename__   = "whatsapp_optin_leads"
    id              = db.Column(db.Integer,     primary_key=True)
    user_id         = db.Column(db.Integer,     db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    name            = db.Column(db.String(160), nullable=False)
    phone           = db.Column(db.String(32),  nullable=False, index=True)
    consent_text    = db.Column(db.Text,        nullable=False)
    consent_time    = db.Column(db.DateTime,    nullable=False)
    source          = db.Column(db.String(64),  nullable=True)
    page_url        = db.Column(db.String(500), nullable=True)
    page_referrer   = db.Column(db.String(500), nullable=True)
    created_at      = db.Column(db.DateTime,    default=datetime.utcnow, index=True)

    def to_dict(self):
        return {
            "id": self.id, "name": self.name, "phone": self.phone,
            "consent_text": self.consent_text,
            "consent_time": self.consent_time.isoformat() if self.consent_time else None,
            "source": self.source, "page_url": self.page_url,
            "page_referrer": self.page_referrer,
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }


@app.route("/api/whatsapp-optin/config", methods=["GET"])
def whatsapp_optin_get_config():
    """Auth'd: get-or-create this business's widget config so the app can
    render a ready-to-copy embed snippet with their real business name
    and endpoint already filled in."""
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Please log in."}), 401
    cfg = WhatsAppOptInWidget.query.filter_by(user_id=user["id"]).first()
    if not cfg:
        cfg = WhatsAppOptInWidget(
            user_id=user["id"],
            public_key=secrets.token_urlsafe(24),
            business_name=user.get("name") or "our business",
        )
        db.session.add(cfg)
        db.session.commit()
    return jsonify({"config": cfg.to_dict()}), 200


@app.route("/api/whatsapp-optin/config", methods=["POST"])
def whatsapp_optin_update_config():
    """Auth'd: let the business rename how they're identified in their
    own consent line (e.g. their actual trading name)."""
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Please log in."}), 401
    data = request.get_json(silent=True) or {}
    cfg = WhatsAppOptInWidget.query.filter_by(user_id=user["id"]).first()
    if not cfg:
        cfg = WhatsAppOptInWidget(user_id=user["id"], public_key=secrets.token_urlsafe(24))
        db.session.add(cfg)
    business_name = (data.get("business_name") or "").strip()
    if business_name:
        cfg.business_name = business_name[:200]
    if "enabled" in data:
        cfg.enabled = bool(data.get("enabled"))
    db.session.commit()
    return jsonify({"config": cfg.to_dict()}), 200


@app.route("/api/whatsapp-optin/leads", methods=["GET"])
def whatsapp_optin_list_leads():
    """Auth'd: the business's own captured consent records."""
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Please log in."}), 401
    limit = min(request.args.get("limit", default=100, type=int) or 100, 500)
    rows = (WhatsAppOptInLead.query.filter_by(user_id=user["id"])
            .order_by(WhatsAppOptInLead.created_at.desc()).limit(limit).all())
    return jsonify({"leads": [r.to_dict() for r in rows]}), 200


_WA_OPTIN_PHONE_RE = re.compile(r"^\+[0-9]{10,15}$")


@app.route("/api/public/whatsapp-optin", methods=["POST", "OPTIONS"])
@csrf.exempt
def whatsapp_optin_submit():
    """Public, cross-origin endpoint the embedded form on a business's OWN
    website posts to. No login — identified only by the public_key in the
    query string, which resolves to exactly one business's lead list."""
    if request.method == "OPTIONS":
        return _widget_cors(jsonify({"ok": True}))

    key = (request.args.get("key") or "").strip()
    cfg = WhatsAppOptInWidget.query.filter_by(public_key=key).first()
    if not cfg or not cfg.enabled:
        return _widget_cors(jsonify({"error": "This opt-in form is unavailable."})), 404

    if _rate_limited(f"wa_optin:key:{key}:ip:{_client_ip()}", max_attempts=20, window_seconds=60):
        return _widget_cors(jsonify({"error": "Too many submissions. Please try again shortly."})), 429

    data  = request.get_json(silent=True) or {}
    name  = (data.get("name") or "").strip()
    phone = (data.get("phone") or "").strip()
    optin = bool(data.get("optin"))
    consent_text = (data.get("consent_text") or "").strip()

    if not name or not phone:
        return _widget_cors(jsonify({"error": "Name and phone are required."})), 400
    if not _WA_OPTIN_PHONE_RE.match(phone):
        return _widget_cors(jsonify({"error": "Phone must be in international format, e.g. +254712345678."})), 400
    if not optin or not consent_text:
        return _widget_cors(jsonify({"error": "Consent to receive WhatsApp messages is required."})), 400

    consent_time_raw = data.get("consent_time")
    try:
        consent_time = datetime.fromisoformat(consent_time_raw.replace("Z", "+00:00")) if consent_time_raw else datetime.utcnow()
    except Exception:
        consent_time = datetime.utcnow()

    try:
        lead = WhatsAppOptInLead(
            user_id=cfg.user_id, name=name[:160], phone=phone[:32],
            consent_text=consent_text[:2000], consent_time=consent_time,
            source=(data.get("source") or "")[:64],
            page_url=(data.get("page_url") or "")[:500],
            page_referrer=(data.get("page_referrer") or "")[:500],
        )
        db.session.add(lead)

        # Also upsert a CrmContact so the lead shows up in the regular
        # CRM tool, not just this audit table.
        contact = CrmContact.query.filter_by(user_id=cfg.user_id, phone=phone).first()
        if not contact:
            contact = CrmContact(user_id=cfg.user_id, name=name[:160], phone=phone[:32], stage="lead",
                                  notes="Captured via WhatsApp opt-in widget.")
            db.session.add(contact)

        db.session.commit()
    except Exception as e:
        db.session.rollback()
        logging.error(f"[WA OPTIN SUBMIT ERROR] key={key[:8]}…: {e}")
        return _widget_cors(jsonify({"error": "Could not save right now. Please try again."})), 503

    # Best-effort confirmation on WhatsApp if the business has their own
    # WhatsApp Cloud API connected — never blocks the opt-in from saving.
    try:
        if get_effective_credential(cfg.user_id, "whatsapp_cloud", "access_token"):
            send_whatsapp_cloud_message(
                cfg.user_id, phone,
                f"Hi {name.split(' ')[0]}, you're opted in to WhatsApp updates from {cfg.business_name}. Reply STOP anytime to opt out."
            )
    except Exception as e:
        logging.error(f"[WA OPTIN CONFIRM SEND ERROR] user={cfg.user_id}: {e}")

    return _widget_cors(jsonify({"ok": True}))


# ════════════════════════════════════════════════════════════
# STAGE 203: CRM SYNC — Salesforce, HubSpot, Zoho, Pipedrive
# Pushes an org's ERP customers out to the business's own CRM so leads
# don't live only inside Connect It. Uses the same BYOK "paste your own
# token" pattern as the rest of this codebase's integrations, rather than
# a full OAuth app-registration flow per provider (each of those requires
# a developer app registered with Salesforce/HubSpot/Zoho/Pipedrive first
# — worth doing as a follow-up once Connect It has its own listed app
# with each of them; until then, users paste a token generated from their
# own CRM account, exactly like the existing Twilio/Stripe/etc BYOK rows).
# ════════════════════════════════════════════════════════════

CRM_PROVIDERS = ("salesforce", "hubspot", "zoho", "pipedrive")


class CrmConnection(db.Model):
    __tablename__     = "crm_connections"
    id                = db.Column(db.Integer,  primary_key=True)
    org_id            = db.Column(db.Integer,  db.ForeignKey("organizations.id"), nullable=False, index=True)
    provider          = db.Column(db.String(20), nullable=False)
    credentials_blob  = db.Column(db.Text,     nullable=False)  # encrypted: access_token, instance_url/api_domain/company_domain
    enabled           = db.Column(db.Boolean,  nullable=False, default=True)
    last_synced_at    = db.Column(db.DateTime, nullable=True)
    last_sync_status  = db.Column(db.String(255), nullable=True)
    created_at        = db.Column(db.DateTime, default=datetime.utcnow)

    __table_args__ = (db.UniqueConstraint("org_id", "provider", name="uq_crm_org_provider"),)

    def to_dict(self):
        return {
            "id": self.id, "org_id": self.org_id, "provider": self.provider,
            "enabled": self.enabled,
            "last_synced_at": self.last_synced_at.isoformat() if self.last_synced_at else None,
            "last_sync_status": self.last_sync_status,
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }


class CrmSyncedRecord(db.Model):
    """Remembers which ErpCustomer already has a matching record in a given
    CRM, and its external ID, so repeat syncs update instead of duplicate."""
    __tablename__   = "crm_synced_records"
    id              = db.Column(db.Integer, primary_key=True)
    org_id          = db.Column(db.Integer, db.ForeignKey("organizations.id"), nullable=False, index=True)
    provider        = db.Column(db.String(20), nullable=False)
    erp_customer_id = db.Column(db.Integer, db.ForeignKey("erp_customers.id"), nullable=False, index=True)
    external_id     = db.Column(db.String(120), nullable=False)
    synced_at       = db.Column(db.DateTime, default=datetime.utcnow)

    __table_args__ = (db.UniqueConstraint("org_id", "provider", "erp_customer_id", name="uq_crm_synced_record"),)


def _crm_push_contact(provider: str, creds: dict, customer, existing_external_id=None):
    """Creates or updates one contact/lead in the given CRM. Returns the
    provider's external record ID, or raises on failure."""
    name_parts = (customer.name or "").strip().split(" ", 1)
    first_name = name_parts[0] if name_parts else ""
    last_name = name_parts[1] if len(name_parts) > 1 else (name_parts[0] if name_parts else "Unknown")
    token = creds.get("access_token", "")

    if provider == "salesforce":
        instance_url = (creds.get("instance_url") or "").rstrip("/")
        headers = {"Authorization": f"Bearer {token}", "Content-Type": "application/json"}
        payload = {"LastName": last_name, "FirstName": first_name, "Email": customer.email,
                   "Phone": customer.phone, "Company": customer.name or "Unknown"}
        if existing_external_id:
            resp = requests.patch(f"{instance_url}/services/data/v59.0/sobjects/Lead/{existing_external_id}",
                                   headers=headers, json=payload, timeout=20)
            resp.raise_for_status()
            return existing_external_id
        resp = requests.post(f"{instance_url}/services/data/v59.0/sobjects/Lead/", headers=headers, json=payload, timeout=20)
        resp.raise_for_status()
        return resp.json().get("id")

    if provider == "hubspot":
        headers = {"Authorization": f"Bearer {token}", "Content-Type": "application/json"}
        payload = {"properties": {"email": customer.email, "firstname": first_name,
                                   "lastname": last_name, "phone": customer.phone, "company": customer.name}}
        if existing_external_id:
            resp = requests.patch(f"https://api.hubapi.com/crm/v3/objects/contacts/{existing_external_id}",
                                   headers=headers, json=payload, timeout=20)
            resp.raise_for_status()
            return existing_external_id
        resp = requests.post("https://api.hubapi.com/crm/v3/objects/contacts", headers=headers, json=payload, timeout=20)
        resp.raise_for_status()
        return resp.json().get("id")

    if provider == "zoho":
        api_domain = (creds.get("api_domain") or "www.zohoapis.com").rstrip("/")
        headers = {"Authorization": f"Zoho-oauthtoken {token}", "Content-Type": "application/json"}
        payload = {"data": [{"Last_Name": last_name, "First_Name": first_name, "Email": customer.email,
                              "Phone": customer.phone, "Company": customer.name or "Unknown"}]}
        if existing_external_id:
            resp = requests.put(f"https://{api_domain}/crm/v2/Leads/{existing_external_id}", headers=headers, json=payload, timeout=20)
            resp.raise_for_status()
            return existing_external_id
        resp = requests.post(f"https://{api_domain}/crm/v2/Leads", headers=headers, json=payload, timeout=20)
        resp.raise_for_status()
        body = resp.json()
        return (body.get("data") or [{}])[0].get("details", {}).get("id")

    if provider == "pipedrive":
        company_domain = creds.get("company_domain", "")
        base = f"https://{company_domain}.pipedrive.com/api/v1/persons"
        payload = {"name": customer.name, "email": [customer.email] if customer.email else [],
                   "phone": [customer.phone] if customer.phone else []}
        if existing_external_id:
            resp = requests.put(f"{base}/{existing_external_id}", params={"api_token": token}, json=payload, timeout=20)
            resp.raise_for_status()
            return existing_external_id
        resp = requests.post(base, params={"api_token": token}, json=payload, timeout=20)
        resp.raise_for_status()
        return resp.json().get("data", {}).get("id")

    raise ValueError(f"Unsupported CRM provider: {provider}")


@app.route("/api/crm/connections", methods=["GET"])
def crm_connections_list():
    user, err = _erp_user_or_401()
    if err: return err
    org_id = request.args.get("org_id", type=int)
    if not org_id:
        return jsonify({"error": "org_id is required."}), 400
    _, err = _org_member_or_403(user, org_id, roles=("owner", "admin"))
    if err: return err
    rows = CrmConnection.query.filter_by(org_id=org_id).all()
    return jsonify({"connections": [r.to_dict() for r in rows]}), 200


@app.route("/api/crm/connect", methods=["POST"])
@csrf.exempt
def crm_connect():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    org_id = data.get("org_id")
    provider = (data.get("provider") or "").strip().lower()
    access_token = (data.get("access_token") or "").strip()

    if not org_id or provider not in CRM_PROVIDERS or not access_token:
        return jsonify({"error": f"org_id, a valid provider ({', '.join(CRM_PROVIDERS)}), and access_token are required."}), 400
    _, err = _org_member_or_403(user, org_id, roles=("owner", "admin"))
    if err: return err

    creds = {"access_token": access_token}
    if provider == "salesforce": creds["instance_url"] = (data.get("instance_url") or "").strip()
    if provider == "zoho": creds["api_domain"] = (data.get("api_domain") or "www.zohoapis.com").strip()
    if provider == "pipedrive": creds["company_domain"] = (data.get("company_domain") or "").strip()

    conn = CrmConnection.query.filter_by(org_id=org_id, provider=provider).first()
    if not conn:
        conn = CrmConnection(org_id=org_id, provider=provider, credentials_blob="")
        db.session.add(conn)
    conn.credentials_blob = encrypt_secret_blob(creds)
    conn.enabled = True
    db.session.commit()
    _audit(org_id, user["id"], user["email"], "crm.connected", "crm_connection", conn.id, {"provider": provider})
    return jsonify({"ok": True, "connection": conn.to_dict()}), 200


@app.route("/api/crm/connections/<int:conn_id>", methods=["DELETE"])
@csrf.exempt
def crm_disconnect(conn_id):
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    conn = CrmConnection.query.get(conn_id)
    if not conn:
        return jsonify({"error": "Connection not found."}), 404
    _, err = _org_member_or_403(user, conn.org_id, roles=("owner", "admin"))
    if err: return err
    db.session.delete(conn)
    db.session.commit()
    _audit(conn.org_id, user["id"], user["email"], "crm.disconnected", "crm_connection", conn_id, {"provider": conn.provider})
    return jsonify({"ok": True}), 200


@app.route("/api/crm/sync", methods=["POST"])
@csrf.exempt
def crm_sync():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    org_id = data.get("org_id")
    if not org_id:
        return jsonify({"error": "org_id is required."}), 400
    _, err = _org_member_or_403(user, org_id, roles=("owner", "admin"))
    if err: return err

    conn = CrmConnection.query.filter_by(org_id=org_id, provider=(data.get("provider") or "").strip().lower(), enabled=True).first()
    if not conn:
        return jsonify({"error": "No enabled CRM connection found for that provider."}), 404

    org = Organization.query.get(org_id)
    creds = decrypt_secret_blob(conn.credentials_blob)
    customers = ErpCustomer.query.filter_by(owner_user_id=org.owner_user_id, active=True).all()

    pushed, failed = 0, []
    for customer in customers:
        existing = CrmSyncedRecord.query.filter_by(org_id=org_id, provider=conn.provider, erp_customer_id=customer.id).first()
        try:
            external_id = _crm_push_contact(conn.provider, creds, customer, existing.external_id if existing else None)
            if not external_id:
                continue
            if existing:
                existing.external_id = str(external_id)
                existing.synced_at = datetime.utcnow()
            else:
                db.session.add(CrmSyncedRecord(org_id=org_id, provider=conn.provider, erp_customer_id=customer.id,
                                                external_id=str(external_id)))
            pushed += 1
        except requests.HTTPError as e:
            failed.append({"customer_id": customer.id, "error": (e.response.text[:200] if e.response is not None else str(e))})
        except Exception as e:
            failed.append({"customer_id": customer.id, "error": str(e)})

    conn.last_synced_at = datetime.utcnow()
    conn.last_sync_status = f"{pushed} synced, {len(failed)} failed"
    db.session.commit()
    _audit(org_id, user["id"], user["email"], "crm.sync_run", "crm_connection", conn.id,
           {"provider": conn.provider, "pushed": pushed, "failed": len(failed)})

    return jsonify({"ok": True, "pushed": pushed, "failed": failed}), 200


# ════════════════════════════════════════════════════════════
# STAGE 204: SELF-SERVE BILLING PORTAL
# Lets a workspace owner/billing-role member upgrade/downgrade their own
# plan and view invoice history without emailing support. Built on the
# Stripe wiring that already exists (STRIPE_SECRET_KEY, STRIPE_AVAILABLE)
# — this adds subscription-mode Checkout (vs the existing one-off payment
# session) plus Stripe's own hosted Billing Portal for invoice history,
# payment method updates, and cancellation, which Stripe manages for us.
# ════════════════════════════════════════════════════════════

# One Stripe Price ID per paid plan, created once in the Stripe Dashboard
# (Products > add recurring price) and pasted into these env vars.
STRIPE_PRICE_IDS = {
    "pro":        os.environ.get("STRIPE_PRICE_PRO", ""),
    "business":   os.environ.get("STRIPE_PRICE_BUSINESS", ""),
    "enterprise": os.environ.get("STRIPE_PRICE_ENTERPRISE", ""),
}


def _get_or_create_stripe_customer(org, user):
    if org.stripe_customer_id:
        return org.stripe_customer_id
    customer = stripe.Customer.create(email=user["email"], name=org.name, metadata={"org_id": str(org.id)})
    org.stripe_customer_id = customer.id
    db.session.commit()
    return customer.id


@app.route("/api/billing/subscription", methods=["GET"])
def billing_subscription_get():
    user, err = _erp_user_or_401()
    if err: return err
    org_id = request.args.get("org_id", type=int)
    if not org_id:
        return jsonify({"error": "org_id is required."}), 400
    _, err = _org_member_or_403(user, org_id, roles=("owner", "admin", "billing"))
    if err: return err
    org = Organization.query.get(org_id)
    if not org:
        return jsonify({"error": "Workspace not found."}), 404
    return jsonify({"org": org.to_dict(), "available_plans": list(STRIPE_PRICE_IDS.keys())}), 200


@app.route("/api/billing/checkout", methods=["POST"])
@csrf.exempt
def billing_checkout():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    if not STRIPE_AVAILABLE or not STRIPE_SECRET_KEY:
        return jsonify({"error": "Billing is not configured on this server yet."}), 503
    user, err = _erp_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    org_id = data.get("org_id")
    plan = (data.get("plan") or "").strip().lower()
    if not org_id or plan not in STRIPE_PRICE_IDS:
        return jsonify({"error": f"org_id and a valid plan ({', '.join(STRIPE_PRICE_IDS)}) are required."}), 400
    price_id = STRIPE_PRICE_IDS[plan]
    if not price_id:
        return jsonify({"error": f"The '{plan}' plan isn't priced yet — set STRIPE_PRICE_{plan.upper()} on the server."}), 503

    _, err = _org_member_or_403(user, org_id, roles=("owner", "billing"))
    if err: return err
    org = Organization.query.get(org_id)
    if not org:
        return jsonify({"error": "Workspace not found."}), 404

    try:
        customer_id = _get_or_create_stripe_customer(org, user)
        session = stripe.checkout.Session.create(
            customer=customer_id,
            mode="subscription",
            line_items=[{"price": price_id, "quantity": 1}],
            success_url=data.get("success_url", f"{APP_BASE_URL}/?billing=success"),
            cancel_url=data.get("cancel_url", f"{APP_BASE_URL}/?billing=cancelled"),
            metadata={"org_id": str(org_id), "plan": plan},
            subscription_data={"metadata": {"org_id": str(org_id), "plan": plan}},
        )
    except stripe.error.StripeError as e:
        logging.error(f"[BILLING CHECKOUT ERROR] org={org_id}: {e}")
        return jsonify({"error": str(getattr(e, "user_message", None) or e)}), 400

    _audit(org_id, user["id"], user["email"], "billing.checkout_started", "organization", org_id, {"plan": plan})
    return jsonify({"ok": True, "url": session.url}), 200


@app.route("/api/billing/portal", methods=["GET"])
def billing_portal():
    if not STRIPE_AVAILABLE or not STRIPE_SECRET_KEY:
        return jsonify({"error": "Billing is not configured on this server yet."}), 503
    user, err = _erp_user_or_401()
    if err: return err
    org_id = request.args.get("org_id", type=int)
    if not org_id:
        return jsonify({"error": "org_id is required."}), 400
    _, err = _org_member_or_403(user, org_id, roles=("owner", "billing"))
    if err: return err
    org = Organization.query.get(org_id)
    if not org or not org.stripe_customer_id:
        return jsonify({"error": "This workspace has no billing history yet — start a checkout first."}), 404

    try:
        portal = stripe.billing_portal.Session.create(
            customer=org.stripe_customer_id,
            return_url=request.args.get("return_url", f"{APP_BASE_URL}/?billing=portal_closed"),
        )
    except stripe.error.StripeError as e:
        logging.error(f"[BILLING PORTAL ERROR] org={org_id}: {e}")
        return jsonify({"error": str(getattr(e, "user_message", None) or e)}), 400

    return jsonify({"ok": True, "url": portal.url}), 200


def _user_subscription_handle_event(event: dict):
    """Keep UserAccount.plan in sync with a single user's own Pro/Team
    subscription (see /api/payments/create-checkout). Mirrors
    _billing_handle_subscription_event, which does the same thing for
    Organization.plan — kept separate because the two are billed and
    owned independently."""
    obj = event["data"]["object"]
    metadata = obj.get("metadata") or {}
    user_id = metadata.get("user_id")
    user = None
    if user_id:
        user = UserAccount.query.get(int(user_id))
    if not user:
        customer_id = obj.get("customer")
        if customer_id:
            user = UserAccount.query.filter_by(stripe_customer_id=customer_id).first()
    if not user:
        return

    if event["type"] == "checkout.session.completed" and obj.get("mode") == "subscription":
        plan = USER_STRIPE_PLAN_NAME.get(metadata.get("plan"), metadata.get("plan"))
        user.stripe_subscription_id = obj.get("subscription")
        user.subscription_status = "active"
        if plan:
            user.plan = plan
    elif event["type"] in ("customer.subscription.updated", "customer.subscription.created"):
        user.stripe_subscription_id = obj.get("id")
        user.subscription_status = obj.get("status")
        plan = USER_STRIPE_PLAN_NAME.get(metadata.get("plan"), metadata.get("plan"))
        if plan and obj.get("status") in ("active", "trialing"):
            user.plan = plan
        elif obj.get("status") in ("canceled", "unpaid", "incomplete_expired"):
            user.plan = "free"
    elif event["type"] == "customer.subscription.deleted":
        user.subscription_status = "canceled"
        user.plan = "free"

    db.session.commit()


def _billing_handle_subscription_event(event: dict):
    """Called from the existing Stripe webhook handler for subscription
    lifecycle events, so a plan upgrade/downgrade/cancellation made in
    Stripe's own Checkout/Billing Portal is reflected back on the org."""
    obj = event["data"]["object"]
    org_id = (obj.get("metadata") or {}).get("org_id")
    if not org_id:
        customer_id = obj.get("customer")
        org = Organization.query.filter_by(stripe_customer_id=customer_id).first()
    else:
        org = Organization.query.get(int(org_id))
    if not org:
        return

    if event["type"] == "checkout.session.completed" and obj.get("mode") == "subscription":
        plan = (obj.get("metadata") or {}).get("plan")
        org.stripe_subscription_id = obj.get("subscription")
        org.subscription_status = "active"
        if plan in STRIPE_PRICE_IDS:
            org.plan = plan
    elif event["type"] in ("customer.subscription.updated", "customer.subscription.created"):
        org.stripe_subscription_id = obj.get("id")
        org.subscription_status = obj.get("status")
        plan = (obj.get("metadata") or {}).get("plan")
        if plan in STRIPE_PRICE_IDS and obj.get("status") in ("active", "trialing"):
            org.plan = plan
    elif event["type"] == "customer.subscription.deleted":
        org.subscription_status = "canceled"
        org.plan = "free"

    db.session.commit()
    _audit(org.id, None, None, f"billing.{event['type']}", "organization", org.id, {"status": org.subscription_status, "plan": org.plan})


