class GoogleOAuthToken(db.Model):
    __tablename__  = "google_oauth_tokens"
    id             = db.Column(db.Integer, primary_key=True)
    user_id        = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, unique=True, index=True)
    access_token   = db.Column(db.String(2048), nullable=False)
    refresh_token  = db.Column(db.String(2048), nullable=True)
    expires_at     = db.Column(db.DateTime, nullable=False)
    scope          = db.Column(db.String(512), nullable=True)
