class ErpInvoice(db.Model):
    __tablename__ = "erp_invoices"
    id             = db.Column(db.Integer,     primary_key=True)
    owner_user_id  = db.Column(db.Integer,     db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    customer_id    = db.Column(db.Integer,     db.ForeignKey("erp_customers.id"), nullable=True, index=True)
    invoice_number = db.Column(db.String(40),  nullable=False)
    status         = db.Column(db.String(20),  nullable=False, default="draft")  # draft, sent, paid, overdue, void
    currency       = db.Column(db.String(8),   nullable=False, default="USD")
    issue_date     = db.Column(db.Date,        nullable=True)
    due_date       = db.Column(db.Date,        nullable=True)
    subtotal       = db.Column(db.Float,       nullable=False, default=0)
    tax_rate       = db.Column(db.Float,       nullable=False, default=0)
    tax_amount     = db.Column(db.Float,       nullable=False, default=0)
    total          = db.Column(db.Float,       nullable=False, default=0)
    amount_paid    = db.Column(db.Float,       nullable=False, default=0)
    notes          = db.Column(db.Text,        nullable=True)
    source_quote_id = db.Column(db.Integer,    nullable=True)
    paid_at        = db.Column(db.DateTime,    nullable=True)
    created_at     = db.Column(db.DateTime,    default=datetime.utcnow)
    # NEW: multi-currency (USD/ZiG) — see the matching comment on
    # ErpQuote.exchange_rate; same USD-per-unit-of-currency reference rate,
    # not applied to subtotal/total.
    exchange_rate  = db.Column(db.Float,       nullable=True)
    # STAGE 176: how this invoice was ACTUALLY paid — cash, card, or an
    # as-yet-unmapped method (ecocash/mobile money, bank transfer, etc).
    # Needed because ZIMRA fiscalisation (Stage 175) must report the real
    # payment type (moneyTypeCode) instead of assuming cash. Only "cash"
    # and "card" have a confirmed, documented moneyTypeCode in the `zimra`
    # library's own README (0 and 1 respectively) — every other method is
    # stored as free text here for record-keeping, but fiscalisation
    # refuses to guess a code ZIMRA hasn't published, rather than risk
    # silently mis-reporting a receipt (the same failure class as the
    # earlier production incident).
    payment_method = db.Column(db.String(40),  nullable=True, default="cash")
    # STAGE 178: flags a Partner API sandbox/demo record, auto-seeded for
    # a test-mode API key so external integrators can build against real,
    # isolated data without touching the business's real invoices. Never
    # set true for anything created through the normal UI.
    is_sandbox_demo = db.Column(db.Boolean,    nullable=False, default=False)
    # STAGE 179: set once this invoice has been pushed to the user's
    # connected accounting platform, so re-running the sync updates the
    # same remote invoice instead of creating a duplicate every time.
    xero_invoice_id       = db.Column(db.String(64), nullable=True)
    quickbooks_invoice_id = db.Column(db.String(64), nullable=True)
    # GLOBAL-08: GLOBAL E-INVOICING FOUNDATIONS
    # einvoice_uuid is this invoice's stable identifier for the public
    # verification link/QR code (never the raw sequential invoice_number,
    # since exposing that publicly would let anyone guess how many
    # invoices a business has issued). einvoice_hash chains this
    # invoice's key fields together with the PREVIOUS invoice's hash —
    # the same tamper-evident chaining pattern France/Portugal/several
    # other e-invoicing mandates require: altering any past invoice, or
    # deleting one, breaks every hash after it, so the chain itself is
    # the audit trail. Computed once, at finalization (see
    # _erp_invoice_finalize_einvoice), not recomputed on every read.
    einvoice_uuid  = db.Column(db.String(36),  nullable=True, unique=True, index=True)
    einvoice_hash  = db.Column(db.String(64),  nullable=True)

    def to_dict(self, include_items=False):
        d = {
            "id": self.id, "customer_id": self.customer_id, "invoice_number": self.invoice_number,
            "status": self.status, "currency": self.currency, "exchange_rate": self.exchange_rate,
            "issue_date": self.issue_date.isoformat() if self.issue_date else None,
            "due_date": self.due_date.isoformat() if self.due_date else None,
            "subtotal": self.subtotal, "tax_rate": self.tax_rate, "tax_amount": self.tax_amount,
            "total": self.total, "amount_paid": self.amount_paid,
            "balance_due": round((self.total or 0) - (self.amount_paid or 0), 2),
            "total_usd_equivalent": round(self.total * self.exchange_rate, 2) if self.exchange_rate else None,
            "notes": self.notes, "source_quote_id": self.source_quote_id,
            "paid_at": self.paid_at.isoformat() if self.paid_at else None,
            "created_at": self.created_at.isoformat() if self.created_at else None,
            "payment_method": self.payment_method or "cash",
            "is_sandbox_demo": bool(self.is_sandbox_demo),
            "xero_invoice_id": self.xero_invoice_id,
            "quickbooks_invoice_id": self.quickbooks_invoice_id,
            "einvoice_uuid": self.einvoice_uuid, "einvoice_hash": self.einvoice_hash,
        }
        if include_items:
            d["items"] = [i.to_dict() for i in ErpInvoiceItem.query.filter_by(invoice_id=self.id).all()]
        return d


class ErpInvoiceItem(db.Model):
    __tablename__ = "erp_invoice_items"
    id           = db.Column(db.Integer,  primary_key=True)
    invoice_id   = db.Column(db.Integer,  db.ForeignKey("erp_invoices.id"), nullable=False, index=True)
    product_id   = db.Column(db.Integer,  db.ForeignKey("inventory_items.id"), nullable=True)
    description  = db.Column(db.String(300), nullable=False)
    quantity     = db.Column(db.Float,    nullable=False, default=1)
    unit_price   = db.Column(db.Float,    nullable=False, default=0)
    line_total   = db.Column(db.Float,    nullable=False, default=0)

    def to_dict(self):
        return {
            "id": self.id, "product_id": self.product_id, "description": self.description,
            "quantity": self.quantity, "unit_price": self.unit_price, "line_total": self.line_total,
        }


# ════════════════════════════════════════════════════════════
# GLOBAL-06: INVOICE FACTORING MARKETPLACE
# Lets a business sell an unpaid invoice's receivable to another
# platform user for cash today instead of waiting out the due date —
# and lets that other user (an investor, or simply a business with
# spare cash) earn the spread by funding it. The listed invoice's
# owner still legally issued it; what changes hands is the right to
# collect it, which is why _erp_apply_invoice_payment (below, near the
# existing invoice payment logic) redirects the eventual payment to
# whoever funded the listing instead of the original seller once
# funded — the seller was already paid their advance up front.
class FactoringListing(db.Model):
    __tablename__  = "factoring_listings"
    id             = db.Column(db.Integer, primary_key=True)
    invoice_id     = db.Column(db.Integer, db.ForeignKey("erp_invoices.id"), nullable=False, index=True, unique=True)
    seller_user_id = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    buyer_user_id  = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=True, index=True)
    face_value     = db.Column(db.Float, nullable=False)     # invoice balance at the time of listing
    advance_rate   = db.Column(db.Float, nullable=False, default=0.85)
    advance_amount = db.Column(db.Float, nullable=False)      # what the seller receives immediately on funding
    status         = db.Column(db.String(16), nullable=False, default="listed")  # listed, funded, collected, cancelled
    listed_at      = db.Column(db.DateTime, default=datetime.utcnow)
    funded_at      = db.Column(db.DateTime, nullable=True)
    collected_at   = db.Column(db.DateTime, nullable=True)

    def to_dict(self):
        return {
            "id": self.id, "invoice_id": self.invoice_id, "seller_user_id": self.seller_user_id,
            "buyer_user_id": self.buyer_user_id, "face_value": self.face_value,
            "advance_rate": self.advance_rate, "advance_amount": self.advance_amount,
            "potential_return": round(self.face_value - self.advance_amount, 2),
            "status": self.status,
            "listed_at": self.listed_at.isoformat() if self.listed_at else None,
            "funded_at": self.funded_at.isoformat() if self.funded_at else None,
            "collected_at": self.collected_at.isoformat() if self.collected_at else None,
        }


# ════════════════════════════════════════════════════════════
# TOKENIZED TRADE RECEIVABLES MARKETPLACE
# FactoringListing (above) is an all-or-nothing sale to a single
# investor. This is the fractional version: a seller splits an unpaid
# invoice's receivable into TOKENIZED_RECEIVABLE_UNITS equal units and
# many investors can each buy however many units they want, at
# unit_price = (amount_tokenized / total_units) * advance_rate. Units
# already sold can also be resold on a secondary market
# (ReceivableTokenResaleListing) to a different investor before the
# invoice is ever paid — real liquidity, not just fractional buy-in.
# Honesty note: "tokenized" here means fractional ownership units
# tracked in this platform's own database, the same pattern as the
# Stage 342 notarized ledger — there is no cryptocurrency, wallet, or
# distributed blockchain token involved.
# Settlement happens inside _erp_apply_invoice_payment (near the
# existing FactoringListing redirect, below): whatever share of each
# incoming payment corresponds to sold units is split pro-rata across
# current unit holders; the share corresponding to any units that
# never sold simply flows to the original seller as normal revenue,
# since they were never advanced cash for those units.
# ════════════════════════════════════════════════════════════
TOKENIZED_RECEIVABLE_UNITS = 1000  # fixed unit count per tokenized receivable

class TokenizedReceivable(db.Model):
    __tablename__          = "tokenized_receivables"
    id                     = db.Column(db.Integer, primary_key=True)
    invoice_id             = db.Column(db.Integer, db.ForeignKey("erp_invoices.id"), nullable=False, index=True)
    seller_user_id         = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    face_value_at_listing  = db.Column(db.Float, nullable=False)   # invoice balance at the moment of listing
    amount_tokenized       = db.Column(db.Float, nullable=False)   # portion of that balance being tokenized (<= face_value_at_listing)
    advance_rate           = db.Column(db.Float, nullable=False, default=0.85)
    unit_price             = db.Column(db.Float, nullable=False)   # (amount_tokenized / TOKENIZED_RECEIVABLE_UNITS) * advance_rate
    units_sold             = db.Column(db.Integer, nullable=False, default=0)
    status                 = db.Column(db.String(16), nullable=False, default="open", index=True)  # open, funded, settled, cancelled
    listed_at              = db.Column(db.DateTime, default=datetime.utcnow)
    funded_at              = db.Column(db.DateTime, nullable=True)   # all units sold
    settled_at             = db.Column(db.DateTime, nullable=True)   # invoice fully paid, proceeds distributed

    def to_dict(self):
        return {
            "id": self.id, "invoice_id": self.invoice_id, "seller_user_id": self.seller_user_id,
            "face_value_at_listing": self.face_value_at_listing, "amount_tokenized": self.amount_tokenized,
            "advance_rate": self.advance_rate, "unit_price": self.unit_price,
            "total_units": TOKENIZED_RECEIVABLE_UNITS, "units_sold": self.units_sold,
            "units_remaining": TOKENIZED_RECEIVABLE_UNITS - self.units_sold,
            "percent_sold": round((self.units_sold / TOKENIZED_RECEIVABLE_UNITS) * 100, 1),
            "advance_raised": round(self.units_sold * self.unit_price, 2),
            "potential_total_return": round(self.amount_tokenized - (TOKENIZED_RECEIVABLE_UNITS * self.unit_price), 2),
            "status": self.status,
            "listed_at": self.listed_at.isoformat() if self.listed_at else None,
            "funded_at": self.funded_at.isoformat() if self.funded_at else None,
            "settled_at": self.settled_at.isoformat() if self.settled_at else None,
        }


class ReceivableTokenHolding(db.Model):
    """One row per (tokenized_receivable, holder) — units currently owned
    plus a running cost basis, updated on both primary purchases and
    secondary-market trades."""
    __tablename__          = "receivable_token_holdings"
    id                     = db.Column(db.Integer, primary_key=True)
    tokenized_receivable_id = db.Column(db.Integer, db.ForeignKey("tokenized_receivables.id"), nullable=False, index=True)
    holder_user_id         = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    units                  = db.Column(db.Integer, nullable=False, default=0)
    total_cost             = db.Column(db.Float, nullable=False, default=0.0)
    first_acquired_at      = db.Column(db.DateTime, default=datetime.utcnow)
    last_acquired_at       = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        return {
            "id": self.id, "tokenized_receivable_id": self.tokenized_receivable_id,
            "units": self.units, "total_cost": round(self.total_cost, 2),
            "avg_unit_cost": round(self.total_cost / self.units, 4) if self.units else 0,
            "first_acquired_at": self.first_acquired_at.isoformat() if self.first_acquired_at else None,
            "last_acquired_at": self.last_acquired_at.isoformat() if self.last_acquired_at else None,
        }


class ReceivableTokenResaleListing(db.Model):
    """Secondary market: a holder resells some or all of their units to
    a different investor before the underlying invoice is paid."""
    __tablename__          = "receivable_token_resale_listings"
    id                     = db.Column(db.Integer, primary_key=True)
    tokenized_receivable_id = db.Column(db.Integer, db.ForeignKey("tokenized_receivables.id"), nullable=False, index=True)
    seller_user_id         = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    buyer_user_id          = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=True, index=True)
    units                  = db.Column(db.Integer, nullable=False)
    price_per_unit         = db.Column(db.Float, nullable=False)
    status                 = db.Column(db.String(16), nullable=False, default="listed")  # listed, sold, cancelled
    listed_at              = db.Column(db.DateTime, default=datetime.utcnow)
    sold_at                = db.Column(db.DateTime, nullable=True)

    def to_dict(self):
        return {
            "id": self.id, "tokenized_receivable_id": self.tokenized_receivable_id,
            "seller_user_id": self.seller_user_id, "buyer_user_id": self.buyer_user_id,
            "units": self.units, "price_per_unit": self.price_per_unit,
            "total_price": round(self.units * self.price_per_unit, 2),
            "status": self.status,
            "listed_at": self.listed_at.isoformat() if self.listed_at else None,
            "sold_at": self.sold_at.isoformat() if self.sold_at else None,
        }


# ════════════════════════════════════════════════════════════
# PURCHASE ORDER FINANCING
# A buyer with a confirmed PO from a seller on this platform doesn't
# have to come up with the full payment themselves before goods move.
# Investors (the same pool that already funds LoanListing/
# FactoringListing) advance most of the PO value straight to the
# seller now, in exchange for the buyer repaying the advance plus a
# financing fee once the term is up. A slice of the PO value (the
# "holdback") is deliberately withheld from the advance and only
# counted as released once the buyer confirms the goods actually
# arrived — a standard trade-finance safeguard against paying a
# seller in full for something that's never delivered.
# ════════════════════════════════════════════════════════════

class POFinancingRequest(db.Model):
    __tablename__     = "po_financing_requests"
    id                = db.Column(db.Integer, primary_key=True)
    buyer_user_id     = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)   # repays the financiers
    seller_user_id    = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=True, index=True)    # receives the advance; null if the seller isn't a platform user (external supplier)
    product_order_id  = db.Column(db.Integer, db.ForeignKey("product_orders.id"), nullable=True, index=True)   # optional link if this PO originated from a marketplace order
    po_reference       = db.Column(db.String(80), nullable=True)   # external PO number, when not linked to a marketplace order
    seller_name_external = db.Column(db.String(150), nullable=True)  # display name when seller_user_id is null
    description        = db.Column(db.Text, nullable=True)
    amount              = db.Column(db.Float, nullable=False)          # total PO value
    currency            = db.Column(db.String(8), nullable=False, default="USD")
    advance_rate         = db.Column(db.Float, nullable=False, default=0.90)   # % of PO value advanced to the seller now
    advance_amount        = db.Column(db.Float, nullable=False)                 # amount*advance_rate
    fee_pct               = db.Column(db.Float, nullable=False, default=6.0)    # flat financing fee for the term, charged to the buyer
    term_days             = db.Column(db.Integer, nullable=False, default=60)
    trust_score_snapshot  = db.Column(db.Float, nullable=True)
    trust_grade_snapshot  = db.Column(db.String(20), nullable=True)
    status                = db.Column(db.String(16), nullable=False, default="open", index=True)  # open, funded, delivered, repaying, completed, cancelled
    delivery_confirmed_at = db.Column(db.DateTime, nullable=True)
    created_at            = db.Column(db.DateTime, default=datetime.utcnow, index=True)
    funded_at              = db.Column(db.DateTime, nullable=True)
    due_date                = db.Column(db.Date, nullable=True)
    completed_at            = db.Column(db.DateTime, nullable=True)
    # STAGE 344: SUPPLY CHAIN FINANCING CASCADE — a seller who was
    # advanced funds on a request below (cascade_tier 1, the original
    # buyer-to-seller PO) can turn around and become the *buyer* on a
    # brand new request of their own, financing payment to one of
    # their own registered suppliers (ErpSupplier). That child request
    # points back at the one that funded it via cascade_parent_id, and
    # cascade_tier increments by one each hop — so the same advance
    # can, in principle, cascade down through several tiers of a real
    # supply chain, not just one buyer-seller pair. cascade_supplier_id
    # links a cascade request to the seller's own supplier record when
    # that supplier isn't itself a platform user (the common case).
    cascade_parent_id    = db.Column(db.Integer, db.ForeignKey("po_financing_requests.id"), nullable=True, index=True)
    cascade_tier         = db.Column(db.Integer, nullable=False, default=1)
    cascade_supplier_id  = db.Column(db.Integer, db.ForeignKey("erp_suppliers.id"), nullable=True, index=True)
    # On a database that already has po_financing_requests (db.create_all()
    # only adds new tables, not new columns to existing ones), run once:
    #   ALTER TABLE po_financing_requests ADD COLUMN cascade_parent_id INTEGER NULL;
    #   ALTER TABLE po_financing_requests ADD COLUMN cascade_tier INTEGER NOT NULL DEFAULT 1;
    #   ALTER TABLE po_financing_requests ADD COLUMN cascade_supplier_id INTEGER NULL;

    def amount_owed(self):
        return round(self.advance_amount * (1 + self.fee_pct / 100.0), 2)

    def cascade_committed(self):
        """Sum of advance_amount already committed to this request's own
        cascade children (cancelled ones don't tie up capacity)."""
        children = POFinancingRequest.query.filter_by(cascade_parent_id=self.id).filter(
            POFinancingRequest.status != "cancelled").all()
        return round(sum(c.advance_amount for c in children), 2)

    def cascade_available(self):
        """How much of this request's own advance is still free to cascade
        down to the seller's suppliers. Only meaningful once funds have
        actually moved (funded or later) — nothing to cascade from an
        offer that's still just 'open'."""
        if self.status not in ("funded", "delivered", "repaying", "completed"):
            return 0.0
        return round(max(self.advance_amount - self.cascade_committed(), 0), 2)

    def to_dict(self, include_detail=False):
        fundings = POFinancingFunding.query.filter_by(request_id=self.id).all()
        funded_total = round(sum(f.amount_funded for f in fundings), 2)
        repayments = POFinancingRepayment.query.filter_by(request_id=self.id).all()
        repaid_total = round(sum(r.amount for r in repayments), 2)
        buyer = UserAccount.query.get(self.buyer_user_id)
        seller = UserAccount.query.get(self.seller_user_id) if self.seller_user_id else None
        supplier = ErpSupplier.query.get(self.cascade_supplier_id) if self.cascade_supplier_id else None
        d = {
            "id": self.id, "buyer_user_id": self.buyer_user_id, "buyer_name": buyer.name if buyer else None,
            "seller_user_id": self.seller_user_id,
            "seller_name": (seller.name if seller else None) or self.seller_name_external,
            "product_order_id": self.product_order_id, "po_reference": self.po_reference,
            "description": self.description, "amount": self.amount, "currency": self.currency,
            "advance_rate": self.advance_rate, "advance_amount": self.advance_amount,
            "holdback_amount": round(self.amount - self.advance_amount, 2),
            "fee_pct": self.fee_pct, "term_days": self.term_days,
            "amount_owed": self.amount_owed(),
            "potential_return": round(self.amount_owed() - self.advance_amount, 2),
            "trust_score_snapshot": self.trust_score_snapshot, "trust_grade_snapshot": self.trust_grade_snapshot,
            "status": self.status, "funded_total": funded_total,
            "funding_pct": round(min(funded_total / self.advance_amount * 100, 100), 1) if self.advance_amount else 0,
            "repaid_total": repaid_total,
            "amount_remaining_owed": round(max(self.amount_owed() - repaid_total, 0), 2),
            "delivery_confirmed_at": self.delivery_confirmed_at.isoformat() if self.delivery_confirmed_at else None,
            "due_date": self.due_date.isoformat() if self.due_date else None,
            "created_at": self.created_at.isoformat() if self.created_at else None,
            "funded_at": self.funded_at.isoformat() if self.funded_at else None,
            "completed_at": self.completed_at.isoformat() if self.completed_at else None,
            "cascade_parent_id": self.cascade_parent_id, "cascade_tier": self.cascade_tier,
            "cascade_supplier_id": self.cascade_supplier_id,
            "cascade_supplier_name": (supplier.name if supplier else None),
            "cascade_available": self.cascade_available(),
            "cascade_committed": self.cascade_committed(),
        }
        if include_detail:
            d["fundings"] = [f.to_dict() for f in fundings]
            d["repayments"] = [r.to_dict() for r in repayments]
        return d


