class ErpExpense(db.Model):
    __tablename__ = "erp_expenses"
    id             = db.Column(db.Integer,     primary_key=True)
    owner_user_id  = db.Column(db.Integer,     db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    expense_date   = db.Column(db.Date,        nullable=False)
    category       = db.Column(db.String(80),  nullable=False, default="general")
    vendor         = db.Column(db.String(200), nullable=True)
    amount         = db.Column(db.Float,       nullable=False, default=0)
    currency       = db.Column(db.String(8),   nullable=False, default="USD")
    payment_method = db.Column(db.String(40),  nullable=True)
    receipt_url    = db.Column(db.String(500), nullable=True)   # scanned receipt image/PDF, see Stage 51
    notes          = db.Column(db.Text,        nullable=True)
    created_at     = db.Column(db.DateTime,    default=datetime.utcnow)
    # STAGE 132: optional link to a real supplier record + the invoice
    # details on that bill, so Invoice Fraud Detection can compare it
    # against that supplier's history (past amounts, past invoice numbers,
    # bank account on file). All nullable — existing expenses are untouched.
    supplier_id       = db.Column(db.Integer,    db.ForeignKey("erp_suppliers.id"), nullable=True, index=True)
    invoice_number    = db.Column(db.String(60), nullable=True)
    bank_account_used = db.Column(db.String(120), nullable=True)  # account this expense was actually paid to
    # STAGE 178: see matching comment on ErpInvoice.is_sandbox_demo.
    is_sandbox_demo   = db.Column(db.Boolean,    nullable=False, default=False)
    # STAGE 182: set by /api/banking/reconcile once this expense has been
    # matched against a real transaction from the user's connected bank
    # feed (Mono/Okra), so re-running reconciliation doesn't re-match
    # the same expense twice.
    bank_matched         = db.Column(db.Boolean,     nullable=False, default=False)
    bank_transaction_ref = db.Column(db.String(120), nullable=True)
    # STAGE: Deep Offline-First Dominance. A client-generated UUID stamped
    # when the expense was entered offline (no signal, but the business
    # still needs to log it). Unique per owner so a retried sync after
    # reconnect is a no-op instead of a duplicate expense — same pattern
    # as ProductionDowntimeEvent.client_sync_id. New column, run once on
    # production MySQL:
    #   ALTER TABLE erp_expenses ADD COLUMN client_sync_id VARCHAR(64) NULL;
    #   ALTER TABLE erp_expenses ADD UNIQUE KEY uq_erp_exp_owner_sync (owner_user_id, client_sync_id);
    client_sync_id = db.Column(db.String(64), nullable=True, index=True)

    def to_dict(self):
        return {
            "id": self.id, "expense_date": self.expense_date.isoformat() if self.expense_date else None,
            "category": self.category, "vendor": self.vendor, "amount": self.amount,
            "currency": self.currency, "payment_method": self.payment_method,
            "receipt_url": self.receipt_url, "notes": self.notes,
            "supplier_id": self.supplier_id, "invoice_number": self.invoice_number,
            "bank_account_used": self.bank_account_used,
            "created_at": self.created_at.isoformat() if self.created_at else None,
            "is_sandbox_demo": bool(self.is_sandbox_demo),
            "bank_matched": bool(self.bank_matched),
            "bank_transaction_ref": self.bank_transaction_ref,
        }


class ErpLedgerEntry(db.Model):
    """A lightweight single-line ledger (not full double-entry
    bookkeeping): every money-moving event in the ERP posts one row
    here with a signed amount (+ revenue, - expense/cost), so the P&L
    report is always summed live from source events rather than a
    hand-maintained running total that can drift out of sync."""
    __tablename__ = "erp_ledger_entries"
    id             = db.Column(db.Integer,     primary_key=True)
    owner_user_id  = db.Column(db.Integer,     db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    entry_date     = db.Column(db.Date,        nullable=False, index=True)
    kind           = db.Column(db.String(20),  nullable=False)  # revenue, expense, cogs, payroll
    account        = db.Column(db.String(80),  nullable=False)  # e.g. 'Sales', 'Rent', 'Wages', 'COGS'
    description    = db.Column(db.String(300), nullable=True)
    amount         = db.Column(db.Float,       nullable=False)  # positive=inflow, negative=outflow
    reference_type = db.Column(db.String(30),  nullable=True)   # 'invoice','expense','purchase_order','payroll'
    reference_id   = db.Column(db.Integer,     nullable=True)
    created_at     = db.Column(db.DateTime,    default=datetime.utcnow)

    def to_dict(self):
        return {
            "id": self.id, "entry_date": self.entry_date.isoformat() if self.entry_date else None,
            "kind": self.kind, "account": self.account, "description": self.description,
            "amount": self.amount, "reference_type": self.reference_type, "reference_id": self.reference_id,
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }


# ===========================================================
# BANK STATEMENT RECONCILIATION
# No open banking API covers Zimbabwean/SA banks, so this is CSV-import
# based: the business exports a statement from their bank's own portal
# (every bank supports this) and uploads it here. Each row becomes a
# BankStatementLine; auto-match then pairs it against an ErpLedgerEntry
# by amount + a date window, and anything left over gets matched (or
# marked as not-in-the-books, e.g. bank charges) by hand.
# ===========================================================

class BankStatementImport(db.Model):
    __tablename__ = "bank_statement_imports"
    id             = db.Column(db.Integer,     primary_key=True)
    owner_user_id  = db.Column(db.Integer,     db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    filename       = db.Column(db.String(255), nullable=True)
    bank_name      = db.Column(db.String(100), nullable=True)
    line_count     = db.Column(db.Integer,     nullable=False, default=0)
    matched_count  = db.Column(db.Integer,     nullable=False, default=0)
    created_at     = db.Column(db.DateTime,    default=datetime.utcnow)

    def to_dict(self):
        return {
            "id": self.id, "filename": self.filename, "bank_name": self.bank_name,
            "line_count": self.line_count, "matched_count": self.matched_count,
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }


class BankStatementLine(db.Model):
    __tablename__ = "bank_statement_lines"
    id                = db.Column(db.Integer,     primary_key=True)
    import_id         = db.Column(db.Integer,     db.ForeignKey("bank_statement_imports.id"), nullable=False, index=True)
    owner_user_id     = db.Column(db.Integer,     db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    txn_date          = db.Column(db.Date,        nullable=False)
