class ErpPayslip(db.Model):
    __tablename__ = "erp_payslips"
    id             = db.Column(db.Integer,  primary_key=True)
    payroll_run_id = db.Column(db.Integer,  db.ForeignKey("erp_payroll_runs.id"), nullable=False, index=True)
    employee_id    = db.Column(db.Integer,  db.ForeignKey("erp_employees.id"), nullable=False, index=True)
    gross          = db.Column(db.Float,    nullable=False, default=0)
    deductions     = db.Column(db.Float,    nullable=False, default=0)
    net            = db.Column(db.Float,    nullable=False, default=0)
    # NEW: statutory deduction breakdown (Zimbabwe PAYE/AIDS levy/NSSA — see
    # calc_zimbabwe_paye). All zero for employees with statutory_deductions
    # off, in which case deductions/net keep the old gross=net behaviour.
    # nssa_employer is the business's own matching contribution — it's not
    # subtracted from the employee's pay, just tracked here for the payroll
    # ledger/reporting. NEW columns, run once on the production MySQL DB:
    #   ALTER TABLE erp_payslips ADD COLUMN paye FLOAT NOT NULL DEFAULT 0;
    #   ALTER TABLE erp_payslips ADD COLUMN aids_levy FLOAT NOT NULL DEFAULT 0;
    #   ALTER TABLE erp_payslips ADD COLUMN nssa_employee FLOAT NOT NULL DEFAULT 0;
    #   ALTER TABLE erp_payslips ADD COLUMN nssa_employer FLOAT NOT NULL DEFAULT 0;
    # GLOBAL-01: full generic statutory breakdown as JSON — e.g. for a UK
    # payslip this holds Income Tax + National Insurance + pension; for
    # Zimbabwe it mirrors the four legacy columns below (kept for backward
    # compatibility with existing dashboards/reports). Nullable so old rows
    # with no breakdown still read fine.
    statutory_breakdown = db.Column(db.Text, nullable=True)
    paye           = db.Column(db.Float,    nullable=False, default=0)
    aids_levy      = db.Column(db.Float,    nullable=False, default=0)
    nssa_employee  = db.Column(db.Float,    nullable=False, default=0)
    nssa_employer  = db.Column(db.Float,    nullable=False, default=0)

    def to_dict(self):
        return {
            "id": self.id, "employee_id": self.employee_id,
            "gross": self.gross, "deductions": self.deductions, "net": self.net,
            "paye": self.paye, "aids_levy": self.aids_levy,
            "nssa_employee": self.nssa_employee, "nssa_employer": self.nssa_employer,
            "statutory_breakdown": json.loads(self.statutory_breakdown) if self.statutory_breakdown else None,
        }


# ════════════════════════════════════════════════════════════
# STAGE 455: EXTERNAL PAYSLIP SYNC — real payroll, run by a licensed
# provider (Gusto/ADP/Deel), pulled in read-only. This is deliberately
# a SEPARATE table from ErpPayslip above: ErpPayslip rows are payroll
# this platform itself computed and posted to the ledger; ExternalPayslip
# rows are a mirror of what a licensed provider already ran and already
# paid out via their own banking/tax rails. Never write to this table
# from anywhere except _sync_external_payroll() below, and never let
# any ledger/P&L code treat these as money this platform moved.
# ════════════════════════════════════════════════════════════
class ExternalPayslip(db.Model):
    __tablename__ = "external_payslips"
    id                = db.Column(db.Integer,  primary_key=True)
    user_id           = db.Column(db.Integer,  db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    provider          = db.Column(db.String(32), nullable=False, index=True)   # gusto | adp_workforce_now | deel
    provider_payslip_id = db.Column(db.String(120), nullable=False)            # the ID Gusto/ADP/Deel assigned it
    employee_name     = db.Column(db.String(160), nullable=True)
    employee_external_id = db.Column(db.String(120), nullable=True)
    period_start      = db.Column(db.Date,     nullable=True)
    period_end        = db.Column(db.Date,     nullable=True)
    pay_date          = db.Column(db.Date,     nullable=True)
    gross_pay         = db.Column(db.Float,    nullable=True)
    net_pay           = db.Column(db.Float,    nullable=True)
    currency          = db.Column(db.String(8), nullable=False, default="USD")
    raw_json          = db.Column(db.Text,     nullable=True)   # full provider response, for drill-down
    synced_at         = db.Column(db.DateTime, default=datetime.utcnow, index=True)

    __table_args__ = (
        db.UniqueConstraint("user_id", "provider", "provider_payslip_id", name="uix_ext_payslip_dedupe"),
    )

    def to_dict(self, include_raw=False):
        d = {
            "id": self.id, "provider": self.provider,
            "provider_payslip_id": self.provider_payslip_id,
            "employee_name": self.employee_name,
            "employee_external_id": self.employee_external_id,
            "period_start": self.period_start.isoformat() if self.period_start else None,
            "period_end": self.period_end.isoformat() if self.period_end else None,
            "pay_date": self.pay_date.isoformat() if self.pay_date else None,
            "gross_pay": self.gross_pay, "net_pay": self.net_pay, "currency": self.currency,
            "synced_at": self.synced_at.isoformat() if self.synced_at else None,
        }
        if include_raw:
            try:
                d["raw"] = json.loads(self.raw_json) if self.raw_json else None
            except Exception:
                d["raw"] = None
        return d


# ════════════════════════════════════════════════════════════
# STAGE 54B: USD / ZiG (ZWG) MULTI-CURRENCY ON ERP QUOTES & INVOICES
# Zimbabwe trades in both USD and ZiG (Zimbabwe Gold, ISO code ZWG),
# and the ZiG rate moves often enough that hardcoding it isn't viable
# the way the PAYE tax bands are. So this stores one editable rate per
# business (USD per 1 ZWG), with a best-effort live refresh from a
# public FX source and a manual override — the same BYOK-style "you
# stay in control of the number" pattern used elsewhere in this file.
# The rate is stamped onto a quote/invoice when created so historical
# documents keep showing the USD-equivalent they were actually issued
# at, even if the rate moves later.
# ════════════════════════════════════════════════════════════

class ErpExchangeRateSetting(db.Model):
    __tablename__ = "erp_exchange_rate_settings"
    id             = db.Column(db.Integer,  primary_key=True)
    owner_user_id  = db.Column(db.Integer,  db.ForeignKey("user_accounts.id"), nullable=False, unique=True, index=True)
    zwg_per_usd    = db.Column(db.Float,    nullable=True)   # e.g. 26.5 ZWG = 1 USD
    source         = db.Column(db.String(20), nullable=False, default="manual")  # manual, live
    updated_at     = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        return {
            "zwg_per_usd": self.zwg_per_usd,
            "usd_per_zwg": round(1 / self.zwg_per_usd, 6) if self.zwg_per_usd else None,
            "source": self.source,
            "updated_at": self.updated_at.isoformat() if self.updated_at else None,
        }


