# STAGE 55: PUBLIC APPOINTMENT BOOKING LINK
# Distinct from the Google Calendar service-account bookings and the
# Microsoft Bookings integration above — those both require the
# *business* to be signed into a provider. This is a shareable,
# no-login link (connectit.example/book/<slug>) where a customer picks
# an open slot themselves — for salons, clinics, consultants. Booking
# ties into ERP: a confirmed appointment auto-matches or creates an
# ErpCustomer record so the business's customer list stays real.
# ════════════════════════════════════════════════════════════

class PublicBookingPage(db.Model):
    __tablename__ = "public_booking_pages"
    id             = db.Column(db.Integer,     primary_key=True)
    owner_user_id  = db.Column(db.Integer,     db.ForeignKey("user_accounts.id"), nullable=False, unique=True, index=True)
    slug           = db.Column(db.String(64),  nullable=False, unique=True, index=True)
    business_name  = db.Column(db.String(200), nullable=False)
    welcome_note   = db.Column(db.String(500), nullable=True)
    # Working hours as {"0": "08:00-17:00", ...} keyed 0=Mon..6=Sun;
    # a missing/blank day means closed that day. Stored as JSON text.
    hours_json     = db.Column(db.Text,        nullable=True)
    slot_minutes   = db.Column(db.Integer,     nullable=False, default=30)
    timezone       = db.Column(db.String(64),  nullable=False, default="Africa/Harare")
    active         = db.Column(db.Boolean,     nullable=False, default=True)
    created_at     = db.Column(db.DateTime,    default=datetime.utcnow)

    def hours(self):
        try:
            return json.loads(self.hours_json) if self.hours_json else {}
        except Exception:
            return {}

    def to_dict(self):
        return {
            "id": self.id, "slug": self.slug, "business_name": self.business_name,
            "welcome_note": self.welcome_note, "hours": self.hours(),
            "slot_minutes": self.slot_minutes, "timezone": self.timezone,
            "active": self.active,
        }


class PublicBookingService(db.Model):
    __tablename__ = "public_booking_services"
    id                = db.Column(db.Integer,  primary_key=True)
    page_id           = db.Column(db.Integer,  db.ForeignKey("public_booking_pages.id"), nullable=False, index=True)
    name              = db.Column(db.String(150), nullable=False)
