# --- 1. Apprenticeship-to-Employment Training Bond ---------------------
# Distinct from Mentor & Apprentice Board (informal matching, no
# commitment) and Job Board (open listings): an employer funds a
# worker's named training/certification course in exchange for a
# committed employment period afterward, tracked with real milestones
# (funded -> training_in_progress -> completed -> employed / defaulted)
# instead of a handshake. No money changes hands through the platform
# itself — same reasoning as DealConfirmation above — this is the
# accountability record both sides can point to.
class TrainingBond(db.Model):
    __tablename__  = "training_bonds"
    id             = db.Column(db.Integer, primary_key=True)
    employer_id    = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    apprentice_id  = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=True, index=True)  # null until claimed
    training_title = db.Column(db.String(200), nullable=False)
    training_cost  = db.Column(db.Float, nullable=False, default=0)
    currency       = db.Column(db.String(8), nullable=False, default="USD")
    committed_months = db.Column(db.Integer, nullable=False, default=6)  # employment period owed after training
    status         = db.Column(db.String(24), nullable=False, default="open")
    # open -> claimed -> training_in_progress -> completed -> employed -> defaulted
    area           = db.Column(db.String(120), nullable=True, index=True)
    notes          = db.Column(db.Text, nullable=True)
    created_at     = db.Column(db.DateTime, default=datetime.utcnow, index=True)

    def to_dict(self):
        apprentice = UserAccount.query.get(self.apprentice_id) if self.apprentice_id else None
        return {
            "id": self.id, "employer_id": self.employer_id, "apprentice_id": self.apprentice_id,
            "apprentice_name": apprentice.name if apprentice else None,
            "training_title": self.training_title, "training_cost": self.training_cost,
            "currency": self.currency, "committed_months": self.committed_months,
            "status": self.status, "area": self.area, "notes": self.notes,
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }


