class DealConfirmation(db.Model):
    __tablename__  = "deal_confirmations"
    id             = db.Column(db.Integer, primary_key=True)
    deal_type      = db.Column(db.String(20), nullable=False, index=True)  # barter, delivery, escrow, product_order
    ref_id         = db.Column(db.Integer, nullable=False, index=True)     # BarterListing.id or DeliveryRequest.id
    party_a_id     = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    party_b_id     = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    party_a_confirmed = db.Column(db.Boolean, nullable=False, default=False)
    party_b_confirmed = db.Column(db.Boolean, nullable=False, default=False)
    status         = db.Column(db.String(16), nullable=False, default="pending", index=True)  # pending, confirmed, disputed, refunded (escrow only — no review eligibility)
    dispute_reason = db.Column(db.String(300), nullable=True)
    created_at     = db.Column(db.DateTime, default=datetime.utcnow, index=True)
    confirmed_at   = db.Column(db.DateTime, nullable=True)
    __table_args__ = (db.UniqueConstraint("deal_type", "ref_id", name="uq_deal_confirmation_ref"),)

    def to_dict(self, viewer_id=None):
        pa = UserAccount.query.get(self.party_a_id)
        pb = UserAccount.query.get(self.party_b_id)
        return {
            "id": self.id, "deal_type": self.deal_type, "ref_id": self.ref_id,
            "party_a_id": self.party_a_id, "party_a_name": pa.name if pa else None,
            "party_b_id": self.party_b_id, "party_b_name": pb.name if pb else None,
            "party_a_confirmed": self.party_a_confirmed, "party_b_confirmed": self.party_b_confirmed,
            "status": self.status, "dispute_reason": self.dispute_reason,
            "your_confirmation_needed": bool(viewer_id) and (
                (viewer_id == self.party_a_id and not self.party_a_confirmed) or
                (viewer_id == self.party_b_id and not self.party_b_confirmed)
            ),
            "created_at": self.created_at.isoformat() if self.created_at else None,
            "confirmed_at": self.confirmed_at.isoformat() if self.confirmed_at else None,
        }


# ════════════════════════════════════════════════════════════
# STAGE 91: VERIFIED DEAL REVIEWS
# Closes a real trust gap Trust Score and star ratings can't close alone:
# there was nowhere on the platform to leave an actual written review.
# A review can only be created once a DealConfirmation has reached
# "confirmed" status — i.e. both parties independently verified the deal
# happened — which makes fake, never-transacted reviews structurally
# impossible rather than merely against the rules. One review per
# reviewer per deal. Feeds a real average rating back onto Trust Score,
# the Trades Directory, and Barter listings.
# ════════════════════════════════════════════════════════════

class DealReview(db.Model):
    __tablename__  = "deal_reviews"
    id             = db.Column(db.Integer, primary_key=True)
    deal_confirmation_id = db.Column(db.Integer, db.ForeignKey("deal_confirmations.id"), nullable=False, index=True)
    reviewer_id    = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    reviewee_id    = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    rating         = db.Column(db.Integer, nullable=False)  # 1-5
    comment        = db.Column(db.String(600), nullable=True)
    # STAGE 306: PRODUCT-LEVEL REVIEWS — new column, auto-migrated on
    # startup (or run once on production MySQL):
    #   ALTER TABLE deal_reviews ADD COLUMN product_id INTEGER NULL;
    # Every other deal_type (barter, delivery, escrow) rates a PERSON —
    # this system was never wrong about that. product_order deals rate
    # both: the seller (reviewee_id, unchanged) AND, uniquely, a specific
    # LISTING — set only when deal_type == "product_order", so a Browse
    # card can show "4.6★ (12)" for that exact item instead of only the
    # seller's overall Trust Score.
    product_id     = db.Column(db.Integer, db.ForeignKey("products.id"), nullable=True, index=True)
    created_at     = db.Column(db.DateTime, default=datetime.utcnow, index=True)
    __table_args__ = (db.UniqueConstraint("deal_confirmation_id", "reviewer_id", name="uq_deal_review_reviewer"),)

    def to_dict(self):
        reviewer = UserAccount.query.get(self.reviewer_id)
        deal = DealConfirmation.query.get(self.deal_confirmation_id)
        return {
            "id": self.id, "deal_confirmation_id": self.deal_confirmation_id,
            "deal_type": deal.deal_type if deal else None,
            "reviewer_id": self.reviewer_id, "reviewer_name": reviewer.name if reviewer else "A Connect It member",
            "reviewee_id": self.reviewee_id, "rating": self.rating, "comment": self.comment,
            "product_id": self.product_id,
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }


# ════════════════════════════════════════════════════════════
# STAGE 92: GOVERNMENT TENDER ALERT & AUTO-MATCH
# Governments publish tenders publicly, but small businesses rarely see
# them in time. Real data pulled from two official, free, public sources
# — no fabricated listings, no fake portal:
#   • Zimbabwe: PRAZ eGP System (egp.praz.org.zw), the official
#     Procurement Regulatory Authority of Zimbabwe live tender board.
#   • South Africa: National Treasury's eTenders OCDS Public API
#     (ocds-api.etenders.gov.za) — open government procurement data.
# A subscription is just keywords + optional country/category filter;
# matching happens against real fetched listings, never invented ones.
# Ties into the existing AI Tender/Bid Writer for a first-pass draft,
# and into the Micro-Consortium Maker when a tender is too big to bid
# on alone.
# ════════════════════════════════════════════════════════════

class TenderListing(db.Model):
    __tablename__  = "tender_listings"
    id             = db.Column(db.Integer, primary_key=True)
    source         = db.Column(db.String(20),  nullable=False, index=True)  # praz_zw, etenders_za
    external_id    = db.Column(db.String(64),  nullable=False, index=True)
    reference      = db.Column(db.String(160), nullable=True)
    title          = db.Column(db.String(400), nullable=False)
    description    = db.Column(db.String(1500), nullable=True)
    category       = db.Column(db.String(300), nullable=True, index=True)
    procuring_entity = db.Column(db.String(250), nullable=True)
    country        = db.Column(db.String(4),   nullable=False, index=True)  # ZW, ZA
    closing_date   = db.Column(db.DateTime, nullable=True, index=True)
    publish_date   = db.Column(db.DateTime, nullable=True)
    value_amount   = db.Column(db.Float, nullable=True)
    value_currency = db.Column(db.String(8), nullable=True)
    url            = db.Column(db.String(500), nullable=True)
    fetched_at     = db.Column(db.DateTime, default=datetime.utcnow, index=True)
    __table_args__ = (db.UniqueConstraint("source", "external_id", name="uq_tender_source_extid"),)

    def to_dict(self):
        return {
            "id": self.id, "source": self.source, "external_id": self.external_id,
            "reference": self.reference, "title": self.title, "description": self.description,
            "category": self.category, "procuring_entity": self.procuring_entity,
            "country": self.country,
            "closing_date": self.closing_date.isoformat() if self.closing_date else None,
            "publish_date": self.publish_date.isoformat() if self.publish_date else None,
            "value_amount": self.value_amount, "value_currency": self.value_currency,
            "url": self.url,
            "is_open": bool(self.closing_date and self.closing_date > datetime.utcnow()),
        }


class TenderAlertSubscription(db.Model):
    __tablename__  = "tender_alert_subscriptions"
    id             = db.Column(db.Integer, primary_key=True)
    user_id        = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    keywords       = db.Column(db.String(300), nullable=False)  # comma-separated, matched against title/description/category
    country        = db.Column(db.String(4), nullable=True)     # ZW, ZA, or null for both
    active         = db.Column(db.Boolean, nullable=False, default=True)
    created_at     = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        return {
            "id": self.id, "keywords": self.keywords, "country": self.country,
            "active": self.active,
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }


# ════════════════════════════════════════════════════════════
# STAGE 170: GLOBAL GRANTS & FUNDING MATCHER
# Same real-data, no-fabricated-listings approach as Stage 92's Tender
# Alerts, extended to a source that's genuinely global by nature
# rather than one more single country: the World Bank Group's public
# Procurement Notices API (search.worldbank.org/api/procnotices, no
# key required), which covers World-Bank-financed grants, contracts,
# and consultancy calls across roughly 180 countries — the closest
# thing to a single global funding-opportunity feed that's actually
# free and public. Businesses anywhere can subscribe by keyword; more
# regional grant portals (EU, AfDB, ADB, IDB, national innovation
# agencies) can be added later as additional "source" values using
# this same schema, same as PRAZ/eTenders did for tenders.
# ════════════════════════════════════════════════════════════

class GrantListing(db.Model):
    __tablename__    = "grant_listings"
    id               = db.Column(db.Integer, primary_key=True)
    source           = db.Column(db.String(20),  nullable=False, index=True)  # "worldbank"
    external_id      = db.Column(db.String(64),  nullable=False, index=True)
    notice_type      = db.Column(db.String(80),  nullable=True)
    title            = db.Column(db.String(400), nullable=False)
    description      = db.Column(db.String(1500), nullable=True)
    country          = db.Column(db.String(100), nullable=True, index=True)
    procuring_entity = db.Column(db.String(250), nullable=True)
    project_id       = db.Column(db.String(20),  nullable=True)
    submission_date  = db.Column(db.DateTime, nullable=True, index=True)
    url              = db.Column(db.String(500), nullable=True)
    fetched_at       = db.Column(db.DateTime, default=datetime.utcnow, index=True)
    __table_args__   = (db.UniqueConstraint("source", "external_id", name="uq_grant_source_extid"),)

    def to_dict(self):
        return {
            "id": self.id, "source": self.source, "external_id": self.external_id,
            "notice_type": self.notice_type, "title": self.title, "description": self.description,
            "country": self.country, "procuring_entity": self.procuring_entity, "project_id": self.project_id,
            "submission_date": self.submission_date.isoformat() if self.submission_date else None,
            "url": self.url,
            "is_open": bool(self.submission_date is None or self.submission_date > datetime.utcnow()),
        }


class GrantAlertSubscription(db.Model):
    __tablename__  = "grant_alert_subscriptions"
    id             = db.Column(db.Integer, primary_key=True)
    user_id        = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    keywords       = db.Column(db.String(300), nullable=False)  # comma-separated, matched against title/description
    country        = db.Column(db.String(100), nullable=True)   # free-text country filter, or null for all
    active         = db.Column(db.Boolean, nullable=False, default=True)
    created_at     = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        return {
            "id": self.id, "keywords": self.keywords, "country": self.country,
            "active": self.active,
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }


# ════════════════════════════════════════════════════════════
# STAGE 171: AI NEGOTIATION ASSISTANT — MODEL
# Any business worldwide negotiating with a supplier, customer,
# landlord, or lender can draft an opening position (target /
# acceptable / walk-away) and stress-test it against an AI playing
# the other side before a real conversation. No external data source
# needed — pure AI reasoning over what the business tells it.
# ════════════════════════════════════════════════════════════

class NegotiationSession(db.Model):
    __tablename__         = "negotiation_sessions"
    id                    = db.Column(db.Integer, primary_key=True)
    owner_user_id         = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    counterparty          = db.Column(db.String(200), nullable=True)
    subject               = db.Column(db.String(300), nullable=False)
    our_goals             = db.Column(db.Text, nullable=True)
    context               = db.Column(db.Text, nullable=True)
    opening_position_json = db.Column(db.Text, nullable=True)  # {target, acceptable, walk_away, opening_message}
    transcript_json       = db.Column(db.Text, nullable=True)  # [{role: "counterparty"|"advisor", content: "..."}]
    created_at            = db.Column(db.DateTime, default=datetime.utcnow)
    updated_at            = db.Column(db.DateTime, default=datetime.utcnow, onupdate=datetime.utcnow)

    def to_dict(self):
        return {
            "id": self.id, "counterparty": self.counterparty, "subject": self.subject,
            "our_goals": self.our_goals, "context": self.context,
            "opening_position": json.loads(self.opening_position_json) if self.opening_position_json else {},
            "transcript": json.loads(self.transcript_json) if self.transcript_json else [],
            "created_at": self.created_at.isoformat() if self.created_at else None,
            "updated_at": self.updated_at.isoformat() if self.updated_at else None,
        }


# ════════════════════════════════════════════════════════════
# STAGE 173: BUSINESS DIGITAL TWIN / SCENARIO SIMULATOR — MODEL
# Pure arithmetic against the business's own real ERP history (last 90
# days of ledger/invoice data) — no external calls, no AI guesswork.
# "What if I hire 2 more staff", "what if my biggest customer leaves",
# "what if I raise prices 10%" all resolve to real before/after numbers
# a business anywhere can act on.
# ════════════════════════════════════════════════════════════

class DigitalTwinScenario(db.Model):
    __tablename__   = "digital_twin_scenarios"
    id              = db.Column(db.Integer, primary_key=True)
    owner_user_id   = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    scenario_type   = db.Column(db.String(40), nullable=False)
    label           = db.Column(db.String(200), nullable=True)
    params_json     = db.Column(db.Text, nullable=True)
    baseline_json   = db.Column(db.Text, nullable=True)
    projected_json  = db.Column(db.Text, nullable=True)
    created_at      = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        return {
            "id": self.id, "scenario_type": self.scenario_type, "label": self.label,
            "params": json.loads(self.params_json) if self.params_json else {},
            "baseline": json.loads(self.baseline_json) if self.baseline_json else {},
            "projected": json.loads(self.projected_json) if self.projected_json else {},
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }


# ════════════════════════════════════════════════════════════
# STAGE 174: PARTNER & DEVELOPER API PLATFORM — MODELS
# What actually gets a foreign bank, fintech, accounting platform, or
# government trade portal to integrate with a product isn't a sales
# pitch — it's a real key they can generate themselves, real scoped
# read-only REST endpoints, and real webhooks for the one event
# outside integrators most want (a real payment landing). Every key
# is generated BY the business's own user and scoped to their own
# data only — this platform never shares data across users.
# ════════════════════════════════════════════════════════════

class PartnerApiKey(db.Model):
    __tablename__  = "partner_api_keys"
    id             = db.Column(db.Integer, primary_key=True)
    owner_user_id  = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    key_id         = db.Column(db.String(40), unique=True, nullable=False, index=True)   # public identifier, safe to log
    secret_hash    = db.Column(db.String(128), nullable=False)                            # sha256 of the real secret — never store it raw
    label          = db.Column(db.String(120), nullable=True)
    scopes         = db.Column(db.String(300), nullable=False, default="read:customers,read:invoices,read:expenses,read:inventory")
    active         = db.Column(db.Boolean, nullable=False, default=True)
    created_at     = db.Column(db.DateTime, default=datetime.utcnow)
    last_used_at   = db.Column(db.DateTime, nullable=True)
    # STAGE 178: SANDBOX / TEST-MODE KEYS. A test-mode key only ever sees
    # or writes rows flagged is_sandbox_demo=True (auto-seeded real DB rows,
    # clearly labelled "[SANDBOX]") — never the business's real records.
    # Standard practice (Stripe/PayPal test keys); lets an integrator's
    # developer build and test against real, isolated data with zero risk
    # of touching production business data.
    is_test_mode   = db.Column(db.Boolean, nullable=False, default=False)

    def to_dict(self, mask_key=True):
        return {
            "id": self.id, "key_id": (self.key_id[:8] + "…") if mask_key else self.key_id,
            "label": self.label, "scopes": self.scopes.split(","), "active": self.active,
            "created_at": self.created_at.isoformat() if self.created_at else None,
            "last_used_at": self.last_used_at.isoformat() if self.last_used_at else None,
            "is_test_mode": bool(self.is_test_mode),
        }


class WebhookSubscription(db.Model):
    __tablename__  = "webhook_subscriptions"
    id             = db.Column(db.Integer, primary_key=True)
    owner_user_id  = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    url            = db.Column(db.String(500), nullable=False)
    event_types    = db.Column(db.String(300), nullable=False, default="invoice.paid")  # comma-separated
    secret         = db.Column(db.String(64), nullable=False)  # for HMAC-signing outbound payloads
    active         = db.Column(db.Boolean, nullable=False, default=True)
    created_at     = db.Column(db.DateTime, default=datetime.utcnow)
    last_fired_at  = db.Column(db.DateTime, nullable=True)
    last_status    = db.Column(db.String(20), nullable=True)

    def to_dict(self):
        return {
            "id": self.id, "url": self.url, "event_types": self.event_types.split(","),
            "active": self.active, "created_at": self.created_at.isoformat() if self.created_at else None,
            "last_fired_at": self.last_fired_at.isoformat() if self.last_fired_at else None,
            "last_status": self.last_status,
        }


# NEW: public directory of integration partners — foreign banks, fintechs,
# accounting platforms, trade/government portals, or POS/desktop vendors
# that connect to Connect It via the Partner API above. A logged-in user
# (or the partner organization itself) submits a listing; an admin reviews
# it before it goes live, so the public page stays trustworthy. This is
# the outward-facing half of "attract foreign countries and businesses to
# integrate with us" — the API/webhooks above are the technical means,
# this directory is what makes them discoverable.
class IntegrationListing(db.Model):
    __tablename__     = "integration_listings"
    id                = db.Column(db.Integer, primary_key=True)
    submitted_by_id   = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    company_name      = db.Column(db.String(200), nullable=False)
    country            = db.Column(db.String(100), nullable=True)
    category           = db.Column(db.String(60), nullable=False, default="other")
    # e.g. bank, fintech, accounting_software, trade_portal, pos_desktop, government, other
    website            = db.Column(db.String(300), nullable=True)
    contact_email      = db.Column(db.String(200), nullable=True)
    description        = db.Column(db.Text, nullable=True)
    status             = db.Column(db.String(20), nullable=False, default="pending")  # pending, approved, rejected
    reviewed_by_id     = db.Column(db.Integer, nullable=True)
    review_note        = db.Column(db.Text, nullable=True)
    created_at         = db.Column(db.DateTime, default=datetime.utcnow)
    reviewed_at        = db.Column(db.DateTime, nullable=True)
    # NEW: real-time GLEIF verification attached to this listing (see
    # /api/partner/directory/<id>/verify-gleif below). Only ever set from
    # a live GLEIF API match at ACTIVE/ISSUED status — never hand-typed,
    # so the "Verified" badge means what it says.
    verified_lei        = db.Column(db.String(20), nullable=True)
    verified_legal_name = db.Column(db.String(300), nullable=True)
    verified_at          = db.Column(db.DateTime, nullable=True)

    def to_dict(self):
        return {
            "id": self.id, "company_name": self.company_name, "country": self.country,
            "category": self.category, "website": self.website, "contact_email": self.contact_email,
            "description": self.description, "status": self.status,
            "created_at": self.created_at.isoformat() if self.created_at else None,
            "verified": bool(self.verified_at),
            "verified_lei": self.verified_lei,
            "verified_legal_name": self.verified_legal_name,
            "verified_at": self.verified_at.isoformat() if self.verified_at else None,
        }



