# ════════════════════════════════════════════════════════════
# STAGE 85: LOCAL SKILLS & TRADES DIRECTORY
# A searchable "who can actually do X near me" directory — plumber,
# tailor, mechanic — ranked using the existing Trust Score rather than
# starting reputation from zero.
# ════════════════════════════════════════════════════════════

class TradeListing(db.Model):
    __tablename__  = "trade_listings"
    id             = db.Column(db.Integer, primary_key=True)
    user_id        = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    trade_name     = db.Column(db.String(120), nullable=False, index=True)
    description    = db.Column(db.String(500), nullable=True)
    area           = db.Column(db.String(120), nullable=False, index=True)
    phone          = db.Column(db.String(32), nullable=True)
    years_experience = db.Column(db.Integer, nullable=True)
    active         = db.Column(db.Boolean, nullable=False, default=True)
    created_at     = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        trust = None
        try:
            trust = compute_trust_score(self.user_id)
        except Exception:
            trust = None
        try:
            review_stats = get_user_review_stats(self.user_id)
        except Exception:
            review_stats = {"average_rating": None, "review_count": 0}
        return {
            "id": self.id, "user_id": self.user_id, "trade_name": self.trade_name,
            "description": self.description, "area": self.area, "phone": self.phone,
            "years_experience": self.years_experience, "active": self.active,
            "trust_score": trust["score"] if trust else None, "trust_grade": trust["grade"] if trust else None,
            "average_rating": review_stats["average_rating"], "review_count": review_stats["review_count"],
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }


# ════════════════════════════════════════════════════════════
# STAGE 86: COMMUNITY POLLS
# Real, database-backed, one-vote-per-user — replaces a prior
# localStorage-only "Community Polls" panel that never actually shared
# votes across users or devices.
# ════════════════════════════════════════════════════════════

class CommunityPoll(db.Model):
    __tablename__  = "community_polls"
    id             = db.Column(db.Integer, primary_key=True)
    user_id        = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    question       = db.Column(db.String(300), nullable=False)
    options_json   = db.Column(db.Text, nullable=False)  # JSON list of option strings
    created_at     = db.Column(db.DateTime, default=datetime.utcnow, index=True)
    closes_at      = db.Column(db.DateTime, nullable=True)

    def to_dict(self, include_results=True):
        options = json.loads(self.options_json)
        d = {
            "id": self.id, "user_id": self.user_id, "question": self.question, "options": options,
            "created_at": self.created_at.isoformat() if self.created_at else None,
            "closes_at": self.closes_at.isoformat() if self.closes_at else None,
        }
        if include_results:
            votes = PollVote.query.filter_by(poll_id=self.id).all()
            counts = [0] * len(options)
            for v in votes:
                if 0 <= v.option_index < len(counts):
                    counts[v.option_index] += 1
            d["vote_counts"] = counts
            d["total_votes"] = len(votes)
        return d


class PollVote(db.Model):
    __tablename__  = "poll_votes"
    id             = db.Column(db.Integer, primary_key=True)
    poll_id        = db.Column(db.Integer, db.ForeignKey("community_polls.id"), nullable=False, index=True)
    user_id        = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    option_index   = db.Column(db.Integer, nullable=False)
    created_at     = db.Column(db.DateTime, default=datetime.utcnow)
    __table_args__ = (db.UniqueConstraint("poll_id", "user_id", name="uq_poll_vote_user"),)


# ════════════════════════════════════════════════════════════
# STAGE 87: E-SIGNATURE — real rebuild
# Replaces a prior localStorage-only e-signature panel. A signed
# contract that only exists in one browser is a real liability — this
# version stores the document and every signer's status server-side,
# with a per-signer access link (no login required for external
# signers) and an audit trail of when/where each signature landed.
# ════════════════════════════════════════════════════════════

class ESignDocument(db.Model):
    __tablename__  = "esign_documents"
    id             = db.Column(db.Integer, primary_key=True)
    owner_id       = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    title          = db.Column(db.String(200), nullable=False)
    document_text  = db.Column(db.Text, nullable=False)
    status         = db.Column(db.String(16), nullable=False, default="pending", index=True)  # pending, completed, voided
    created_at     = db.Column(db.DateTime, default=datetime.utcnow, index=True)

    def to_dict(self, include_signers=True):
        d = {
            "id": self.id, "title": self.title, "document_text": self.document_text,
            "status": self.status, "created_at": self.created_at.isoformat() if self.created_at else None,
        }
        if include_signers:
            signers = ESignSigner.query.filter_by(document_id=self.id).all()
            d["signers"] = [s.to_dict() for s in signers]
        return d


class ESignSigner(db.Model):
    __tablename__  = "esign_signers"
    id             = db.Column(db.Integer, primary_key=True)
    document_id    = db.Column(db.Integer, db.ForeignKey("esign_documents.id"), nullable=False, index=True)
    name           = db.Column(db.String(120), nullable=False)
    email          = db.Column(db.String(160), nullable=True)
