    sign_token     = db.Column(db.String(64), nullable=False, unique=True, index=True)
    signed         = db.Column(db.Boolean, nullable=False, default=False)
    signature_text = db.Column(db.String(300), nullable=True)  # typed full-name signature
    signed_at      = db.Column(db.DateTime, nullable=True)
    ip_address     = db.Column(db.String(64), nullable=True)
    created_at     = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self, reveal_token=False):
        d = {
            "id": self.id, "document_id": self.document_id, "name": self.name,
            "email": self.email, "phone": self.phone, "signed": self.signed,
            "signature_text": self.signature_text,
            "signed_at": self.signed_at.isoformat() if self.signed_at else None,
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }
        if reveal_token:
            d["sign_token"] = self.sign_token
        return d


