# SAVED CONTACT LISTS — a reusable, persisted audience a business
# builds once (from their CrmContacts and/or manual entries) and
# reuses across many template broadcasts, instead of re-typing
# recipients into a chip box every time. See TemplateBroadcast /
# TemplateBroadcastRecipient below for the send side, which fires
# one real individual API call per list member — never a single
# fabricated "group send" call.
# ════════════════════════════════════════════════════════════

class ContactList(db.Model):
    __tablename__  = "contact_lists"
    id             = db.Column(db.Integer, primary_key=True)
    user_id        = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    name           = db.Column(db.String(160), nullable=False)
    description    = db.Column(db.Text, nullable=True)
    created_at     = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        member_count = ContactListMember.query.filter_by(list_id=self.id).count()
        return {
            "id": self.id, "name": self.name, "description": self.description,
            "member_count": member_count,
            # True only for the one auto-created list that the public
            # /store/<slug> "Follow this shop" form feeds — lets the
            # Contact Lists panel badge it distinctly from lists the
            # seller built by hand, without a new column: the name is
            # reserved (STOREFRONT_FOLLOWERS_LIST_NAME) and never used
            # for a manually-created list, since clCreateList() lets the
            # seller type any name except this exact one (enforced below).
            "is_storefront_list": self.name == STOREFRONT_FOLLOWERS_LIST_NAME,
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }


class ContactListMember(db.Model):
    """A single entry in a ContactList. Either linked back to a real
    CrmContact (crm_contact_id set — name/phone/email stay live-synced
    at send time via the join, not copied) or a standalone manual
    entry (crm_contact_id NULL, name/phone/email stored directly)."""
    __tablename__   = "contact_list_members"
    id              = db.Column(db.Integer, primary_key=True)
    list_id         = db.Column(db.Integer, db.ForeignKey("contact_lists.id"), nullable=False, index=True)
    crm_contact_id  = db.Column(db.Integer, db.ForeignKey("crm_contacts.id"), nullable=True, index=True)
    name            = db.Column(db.String(160), nullable=True)
    phone           = db.Column(db.String(32),  nullable=True)
    email           = db.Column(db.String(160), nullable=True)
    added_at        = db.Column(db.DateTime, default=datetime.utcnow)

    def resolved(self):
        """Returns (name, phone, email), preferring the live CrmContact
        record over any stale copy if this member is CRM-linked."""
        if self.crm_contact_id:
            c = CrmContact.query.get(self.crm_contact_id)
            if c:
                return (c.name, c.phone, c.email)
        return (self.name, self.phone, self.email)

    def to_dict(self):
        name, phone, email = self.resolved()
        return {
            "id": self.id, "list_id": self.list_id, "crm_contact_id": self.crm_contact_id,
            "name": name, "phone": phone, "email": email,
            "added_at": self.added_at.isoformat() if self.added_at else None,
        }


