# ════════════════════════════════════════════════════════════
# STAGE 471: GEMINI MANAGED AGENTS (Interactions API) — remote MCP
# tool use + "scheduled" triggers. Built against Google's real, GA
# (June 22, 2026) Interactions API: POST /v1beta/interactions on the
# plain Gemini API (generativelanguage.googleapis.com), base agent
# "antigravity-preview-05-2026", tools:[{"type":"mcp_server","name":
# ...,"url":...}] to let the agent call the user's OWN remote MCP
# server, agent_config.model for gemini-3.7-flash (default) down to
# 3.5-flash-lite, background=true for async long-running runs.
#
# Honest scope note on "scheduled triggers": Google's own trigger
# resource isn't something this app can host (it's a Google-side
# cron). This server, like the rest of this codebase's cron features
# (see /api/cron/db-backup, /api/cron/key-rotation-check above), has
# no in-process scheduler either — so a trigger here is a real,
# persisted definition (agent + prompt + tools + an interval in
# minutes) that fires the next time the SAME external "sweep" pattern
# already used everywhere else in this file (a PythonAnywhere
# Scheduled Task hitting an X-Cron-Secret-guarded endpoint) runs and
# finds it due. No cron-syntax parser, no croniter dependency — due-
# ness is a plain "minutes since last run" check, which is honest
# about what's actually enforced and needs zero new packages.
# ════════════════════════════════════════════════════════════

class GeminiAgentTrigger(db.Model):
    __tablename__      = "gemini_agent_triggers"
    id                 = db.Column(db.Integer, primary_key=True)
    owner_user_id      = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    name               = db.Column(db.String(200), nullable=False)
    prompt             = db.Column(db.Text, nullable=False)
    model              = db.Column(db.String(64), default="gemini-3.7-flash")
    mcp_servers_json   = db.Column(db.Text, nullable=True)   # [{"name":"...","url":"...","headers":{...}}]
    interval_minutes   = db.Column(db.Integer, default=1440)  # display/enforcement cadence; 1440 = daily
    schedule_label     = db.Column(db.String(64), nullable=True)  # free-text, e.g. "Daily 9am" — display only
    enabled            = db.Column(db.Boolean, default=True)
    last_run_at        = db.Column(db.DateTime, nullable=True)
    last_status        = db.Column(db.String(20), nullable=True)  # success / error
    created_at         = db.Column(db.DateTime, default=datetime.utcnow)

    def is_due(self, now=None) -> bool:
        if not self.enabled:
            return False
        now = now or datetime.utcnow()
        if not self.last_run_at:
            return True
        return (now - self.last_run_at).total_seconds() >= (self.interval_minutes or 1440) * 60

    def to_dict(self):
        try:
            mcp_servers = json.loads(self.mcp_servers_json or "[]")
        except Exception:
            mcp_servers = []
        return {
            "id": self.id, "name": self.name, "prompt": self.prompt, "model": self.model,
            "mcp_servers": mcp_servers, "interval_minutes": self.interval_minutes,
            "schedule_label": self.schedule_label, "enabled": self.enabled,
            "last_run_at": self.last_run_at.isoformat() if self.last_run_at else None,
            "last_status": self.last_status,
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }


class GeminiAgentRun(db.Model):
    """One row per interaction — manual 'Run Now' or a cron-swept trigger."""
    __tablename__   = "gemini_agent_runs"
    id              = db.Column(db.Integer, primary_key=True)
    owner_user_id   = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
