# ════════════════════════════════════════════════════════════
# WHATSAPP GROUPS — Meta's real, 2026-launched Groups API on the
# WhatsApp Business Platform (Cloud API). Verified facts this
# integration is built against (Meta's own Groups API docs, updated
# June 2026):
#   - Requires an Official Business Account (OBA / green tick) on the
#     Cloud API number. NOT available on WhatsApp Business app numbers
#     or Multi-solution Conversations numbers. There is no way for this
#     platform to grant that status — it's a Meta business verification
#     a user completes on their own Meta Business Manager account. If
#     the account isn't eligible, Meta's API rejects the create-group
#     call and the real error message is surfaced, not papered over.
#   - Max 8 participants per group, max 10,000 groups per business
#     phone number.
#   - Groups are invite-only: there is no "add participant" endpoint.
#     Once created, the ONLY way anyone joins is by using the invite
#     link this platform gets back from Meta and sends out itself
#     (WhatsApp message, email, wherever) — never simulated as if
#     participants can be added directly, because that endpoint does
#     not exist.
#   - Supported message types in a group: text, media, text-based
#     templates, media-based templates. No voice/video calling.
#   - Real-time group state (participant count, lifecycle, settings)
#     arrives via webhook fields (group_lifecycle_update,
#     group_participants_update, group_settings_update,
#     group_status_update) — logged in WhatsAppGroupEvent below rather
#     than guessed at.
# ════════════════════════════════════════════════════════════

class WhatsAppGroup(db.Model):
    __tablename__     = "whatsapp_groups"
    id                = db.Column(db.Integer, primary_key=True)
    user_id           = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    meta_group_id     = db.Column(db.String(128), nullable=False, unique=True, index=True)  # the real group ID Meta returned
    name              = db.Column(db.String(200), nullable=False)
    invite_link       = db.Column(db.String(500), nullable=True)  # the real invite link Meta returned
    status            = db.Column(db.String(16), nullable=False, default="active")  # active, archived, deleted (per group_status_update)
    participant_count = db.Column(db.Integer, nullable=True)  # best-effort, kept current from group_participants_update webhooks only — never estimated
    # Off by default — auto-replying into every message posted in every
    # group is a real behavior change a business must opt into per
    # group, not something turned on silently. See the webhook receiver
    # for why this exists: without it, an inbound group message used to
    # get mistaken for a private 1:1 message.
    auto_reply_enabled = db.Column(db.Boolean, nullable=False, default=False)
    created_at        = db.Column(db.DateTime, default=datetime.utcnow, index=True)

    def to_dict(self):
        return {
            "id": self.id, "meta_group_id": self.meta_group_id, "name": self.name,
            "invite_link": self.invite_link, "status": self.status,
            "participant_count": self.participant_count,
            "auto_reply_enabled": self.auto_reply_enabled,
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }


class WhatsAppGroupEvent(db.Model):
    """Real webhook events for a group (lifecycle/participants/settings/
    status), kept as an audit trail rather than only mutating the row
    above in place — so a user can see exactly what actually happened
    and when, not just the current snapshot."""
    __tablename__ = "whatsapp_group_events"
    id            = db.Column(db.Integer, primary_key=True)
    group_id      = db.Column(db.Integer, db.ForeignKey("whatsapp_groups.id"), nullable=False, index=True)
    event_type    = db.Column(db.String(40), nullable=False)  # group_lifecycle_update, group_participants_update, etc.
    payload_json  = db.Column(db.Text, nullable=True)  # the raw webhook payload for this event, for real auditability
    created_at    = db.Column(db.DateTime, default=datetime.utcnow, index=True)

    def to_dict(self):
        try:
            payload = json.loads(self.payload_json or "{}")
        except Exception:
            payload = {}
        return {
            "id": self.id, "event_type": self.event_type, "payload": payload,
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }


# WHATSAPP DELIVERY / READ RECEIPTS
# Meta's Cloud API webhook sends a separate "statuses" array (distinct
# from "messages") on the SAME POST whenever an outbound message we sent
# changes state: sent -> delivered -> read, or failed. That array was
# never parsed here, so a business had no way to tell whether a WhatsApp
# message it sent actually landed. One row per status event (not one row
# overwritten in place) so the full sent/delivered/read/failed timeline
# stays visible -- same audit-trail reasoning as WhatsAppGroupEvent above.

class WhatsAppMessageStatus(db.Model):
    __tablename__     = "whatsapp_message_statuses"
    id                = db.Column(db.Integer, primary_key=True)
    owner_user_id     = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=True, index=True)
    wa_message_id     = db.Column(db.String(128), nullable=False, index=True)  # Meta's messages[].id this status refers to
    recipient_id      = db.Column(db.String(32),  nullable=True)               # the wa_id phone this was sent to
    status            = db.Column(db.String(16),  nullable=False, index=True)  # sent, delivered, read, failed
    error_code        = db.Column(db.String(20),  nullable=True)               # populated only when status == "failed"
    error_title       = db.Column(db.String(200), nullable=True)
    conversation_id   = db.Column(db.String(128), nullable=True)               # Meta's billing conversation id, if present
    pricing_category  = db.Column(db.String(24),  nullable=True)               # e.g. "service", "marketing", "utility"
    raw_timestamp     = db.Column(db.String(20),  nullable=True)               # Meta's unix-epoch-seconds string, kept as-is
    created_at        = db.Column(db.DateTime, default=datetime.utcnow, index=True)

    def to_dict(self):
        return {
            "id": self.id, "wa_message_id": self.wa_message_id, "recipient_id": self.recipient_id,
            "status": self.status, "error_code": self.error_code, "error_title": self.error_title,
            "conversation_id": self.conversation_id, "pricing_category": self.pricing_category,
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }


# WHATSAPP BUSINESS CALLING — persisted call sessions. Inbound calls
# arrive at /whatsapp-cloud/webhook (field="calls") carrying an SDP
# *offer* the customer's client generated; this platform can't answer
# it server-side (answering means capturing this business's own mic
# audio, which only runs in the operator's browser), so an inbound call
# is stored here in "ringing" state with its offer, the operator's
# browser polls for it, and posts back an SDP *answer* once a human
# picks up. Outbound calls placed via /api/whatsapp-cloud/calling/connect
# are logged here too, so both directions show up in one call log.
class WhatsAppCall(db.Model):
    __tablename__      = "whatsapp_calls"
    id                 = db.Column(db.Integer, primary_key=True)
    owner_user_id      = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=True, index=True)
    meta_call_id       = db.Column(db.String(128), nullable=False, index=True)   # Meta's call id
    direction          = db.Column(db.String(10),  nullable=False, default="inbound")   # inbound, outbound
    phone_number_id    = db.Column(db.String(64),  nullable=True)   # this business's Cloud API number
    counterparty_wa_id = db.Column(db.String(32),  nullable=True)   # the customer's wa_id, either side
    status             = db.Column(db.String(16),  nullable=False, default="ringing", index=True)
    # ringing, connected, rejected, terminated, missed, failed
    sdp_offer          = db.Column(db.Text, nullable=True)   # stored only long enough for the operator to answer
    termination_reason = db.Column(db.String(64),  nullable=True)
    duration_seconds   = db.Column(db.Integer, nullable=True)
    raw_timestamp       = db.Column(db.String(20), nullable=True)
    created_at         = db.Column(db.DateTime, default=datetime.utcnow, index=True)
    updated_at         = db.Column(db.DateTime, default=datetime.utcnow, onupdate=datetime.utcnow)

    def to_dict(self, include_sdp=False):
        d = {
            "id": self.id, "meta_call_id": self.meta_call_id, "direction": self.direction,
            "phone_number_id": self.phone_number_id, "counterparty_wa_id": self.counterparty_wa_id,
            "status": self.status, "termination_reason": self.termination_reason,
            "duration_seconds": self.duration_seconds,
            "created_at": self.created_at.isoformat() if self.created_at else None,
            "updated_at": self.updated_at.isoformat() if self.updated_at else None,
        }
        if include_sdp:
            d["sdp_offer"] = self.sdp_offer
        return d


# META BUSINESS AGENT — Meta's own native WhatsApp AI (launched globally
# June 2026), separate from this platform's AI reply pipeline. While it's
# handling a chat, Meta can optionally deliver that live conversation to
# ONE account-wide webhook destination via the "standby" field (a business
# must explicitly subscribe their Meta app to it in the dashboard — it is
# not sent by default). This platform does not try to intercept or block
# the agent; it listens in (read-only) while standby is active, and the
# real, reliable handoff signal is architectural rather than a single
# flag: once the agent hands a chat to a human, Meta stops routing that
# conversation through standby and the next inbound message instead
# arrives as a completely normal "messages" webhook event — at which
# point this platform's own AI/CRM pipeline picks it up exactly like any
# other inbound WhatsApp message, now with full customer/order/inventory
# context the agent itself never had access to.
#
# The "reclaim a conversation early" action (thread_control release) is
# a newer, less-documented part of this API that is still evolving
# industry-wide as of this writing — implemented best-effort below, but
# verify the exact endpoint/payload in your Meta dashboard's current API
# reference before relying on it in production.
class MetaBusinessAgentEvent(db.Model):
    __tablename__   = "meta_business_agent_events"
    id              = db.Column(db.Integer, primary_key=True)
    owner_user_id   = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=True, index=True)
    phone_number_id = db.Column(db.String(64), nullable=True, index=True)
    customer_wa_id  = db.Column(db.String(32), nullable=True, index=True)
    event_type      = db.Column(db.String(24), nullable=False, index=True)  # standby_message, handoff_detected, reclaim_requested
    direction       = db.Column(db.String(10), nullable=True)  # inbound (customer) / outbound (agent), for standby_message rows
    body_text       = db.Column(db.Text, nullable=True)
    created_at      = db.Column(db.DateTime, default=datetime.utcnow, index=True)

    def to_dict(self):
        return {
            "id": self.id, "customer_wa_id": self.customer_wa_id, "event_type": self.event_type,
            "direction": self.direction, "body_text": self.body_text,
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }


# ════════════════════════════════════════════════════════════
# META BUSINESS AGENT HANDOFF RECEIVER
# One row per "Meta's free agent handed this chat to a human" event.
# The agent only knows catalog/hours/description; the point of this
# record is the ERP context it can't see — the real customer record,
# invoices/balance, WhatsApp orders and live stock for whatever the
# customer was asking about — frozen at handoff time and refreshable.
# status: open → in_progress (a human claimed it; AI auto-reply paused
# for this customer) → resolved (AI auto-reply resumes as normal).
# ════════════════════════════════════════════════════════════
class MetaAgentHandoff(db.Model):
    __tablename__    = "meta_agent_handoffs"
    id               = db.Column(db.Integer, primary_key=True)
    owner_user_id    = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    phone_number_id  = db.Column(db.String(64),  nullable=True)
    customer_wa_id   = db.Column(db.String(64),  nullable=False, index=True)   # phone digits OR a BSUID
    customer_name    = db.Column(db.String(120), nullable=True)
    erp_customer_id  = db.Column(db.Integer,     nullable=True)
    status           = db.Column(db.String(16),  nullable=False, default="open", index=True)
    trigger_text     = db.Column(db.Text,        nullable=True)   # the first message after the handoff
    transcript_json  = db.Column(db.Text,        nullable=True)   # what the agent and customer said before the handoff
    context_json     = db.Column(db.Text,        nullable=True)   # structured ERP packet
    context_text     = db.Column(db.Text,        nullable=True)   # rendered packet the AI reply pipeline is given
    context_built_at = db.Column(db.DateTime,    nullable=True)
    claimed_at       = db.Column(db.DateTime,    nullable=True)
    resolved_at      = db.Column(db.DateTime,    nullable=True)
    created_at       = db.Column(db.DateTime,    default=datetime.utcnow, index=True)

    def to_dict(self, full=False):
        d = {
            "id": self.id, "customer_wa_id": self.customer_wa_id, "customer_name": self.customer_name,
            "erp_customer_id": self.erp_customer_id, "status": self.status,
            "trigger_text": self.trigger_text,
            "created_at": self.created_at.isoformat() if self.created_at else None,
            "claimed_at": self.claimed_at.isoformat() if self.claimed_at else None,
            "resolved_at": self.resolved_at.isoformat() if self.resolved_at else None,
            "context_built_at": self.context_built_at.isoformat() if self.context_built_at else None,
        }
        if full:
            try:
                d["transcript"] = json.loads(self.transcript_json or "[]")
            except Exception:
                d["transcript"] = []
            try:
                d["context"] = json.loads(self.context_json or "{}")
            except Exception:
                d["context"] = {}
            d["context_text"] = self.context_text
        return d


# BUSINESS-SCOPED USER IDS (BSUID). WhatsApp usernames mean a customer's
# phone number may be absent from a webhook; the stable identifier is
# their BSUID. This table remembers bsuid ↔ username ↔ phone (when Meta
# supplies it) ↔ ERP customer so history, orders and handoff context
# keep resolving to the same person.
class WhatsAppContactIdentity(db.Model):
    __tablename__   = "whatsapp_contact_identities"
    __table_args__  = (db.UniqueConstraint("owner_user_id", "bsuid", name="uq_wa_identity_owner_bsuid"),)
    id              = db.Column(db.Integer, primary_key=True)
    owner_user_id   = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    bsuid           = db.Column(db.String(64),  nullable=False, index=True)
    username        = db.Column(db.String(64),  nullable=True)
    wa_id           = db.Column(db.String(32),  nullable=True, index=True)   # phone digits, only when Meta supplied it
    profile_name    = db.Column(db.String(120), nullable=True)
    erp_customer_id = db.Column(db.Integer,     nullable=True)
    first_seen      = db.Column(db.DateTime,    default=datetime.utcnow)
    last_seen       = db.Column(db.DateTime,    default=datetime.utcnow, onupdate=datetime.utcnow)

    def to_dict(self):
        return {
            "id": self.id, "bsuid": self.bsuid, "username": self.username, "wa_id": self.wa_id,
            "profile_name": self.profile_name, "erp_customer_id": self.erp_customer_id,
            "first_seen": self.first_seen.isoformat() if self.first_seen else None,
            "last_seen": self.last_seen.isoformat() if self.last_seen else None,
        }


# WHATSAPP CALL PERMISSIONS — Meta requires a customer's explicit
# accept before a business-initiated call. Recorded from the
# call_permission_reply webhook so call tasks can be gated honestly
# instead of guessing, and so permission requests aren't spammed.
class WhatsAppCallPermission(db.Model):
    __tablename__     = "whatsapp_call_permissions"
    __table_args__    = (db.UniqueConstraint("owner_user_id", "customer_wa_id", name="uq_wa_callperm_owner_cust"),)
    id                = db.Column(db.Integer, primary_key=True)
    owner_user_id     = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    customer_wa_id    = db.Column(db.String(64), nullable=False, index=True)
    status            = db.Column(db.String(12), nullable=False, default="requested")  # requested, granted, denied
    is_permanent      = db.Column(db.Boolean, nullable=False, default=False)
    expires_at        = db.Column(db.DateTime, nullable=True)
    requested_log     = db.Column(db.Text, nullable=True)   # JSON list of ISO timestamps of requests we sent (last 7d)
    updated_at        = db.Column(db.DateTime, default=datetime.utcnow, onupdate=datetime.utcnow)

    def is_active_grant(self):
        if self.status != "granted":
            return False
        if self.is_permanent or not self.expires_at:
            return True
        return self.expires_at > datetime.utcnow()

    def to_dict(self):
        return {
            "customer_wa_id": self.customer_wa_id, "status": self.status,
            "active": self.is_active_grant(), "is_permanent": self.is_permanent,
            "expires_at": self.expires_at.isoformat() if self.expires_at else None,
            "updated_at": self.updated_at.isoformat() if self.updated_at else None,
        }


# WHATSAPP CALL TASKS — a work queue for the calls a business wants to
# make (order confirmation, appointment reminder, payment follow-up).
# The server cannot place a call by itself: a call needs a human's
# microphone in a browser (WebRTC). So tasks are queued, gated on the
# customer's call permission, and an operator works them from the
# "Call queue" panel, which uses the existing in-browser calling flow.
class WhatsAppCallTask(db.Model):
    __tablename__    = "whatsapp_call_tasks"
    id               = db.Column(db.Integer, primary_key=True)
    owner_user_id    = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    customer_wa_id   = db.Column(db.String(64),  nullable=False, index=True)
    customer_name    = db.Column(db.String(120), nullable=True)
    purpose          = db.Column(db.String(24),  nullable=False)   # order_confirmation, appointment_reminder, payment_followup, custom
    notes            = db.Column(db.String(500), nullable=True)    # what to say / what it's about
    reference        = db.Column(db.String(120), nullable=True)    # e.g. order or invoice number
    invoice_id       = db.Column(db.Integer,     nullable=True)
    scheduled_for    = db.Column(db.DateTime,    nullable=True)
    status           = db.Column(db.String(24),  nullable=False, default="awaiting_permission", index=True)
    # awaiting_permission, ready, in_progress, done, no_answer, failed, skipped
    attempts         = db.Column(db.Integer,     nullable=False, default=0)
    outcome          = db.Column(db.String(24),  nullable=True)
    outcome_note     = db.Column(db.String(500), nullable=True)
    last_error       = db.Column(db.String(300), nullable=True)
    meta_call_id     = db.Column(db.String(128), nullable=True)
    created_at       = db.Column(db.DateTime,    default=datetime.utcnow, index=True)
    updated_at       = db.Column(db.DateTime,    default=datetime.utcnow, onupdate=datetime.utcnow)

    def to_dict(self):
        return {
            "id": self.id, "customer_wa_id": self.customer_wa_id, "customer_name": self.customer_name,
            "purpose": self.purpose, "notes": self.notes, "reference": self.reference,
            "invoice_id": self.invoice_id, "status": self.status, "attempts": self.attempts,
            "outcome": self.outcome, "outcome_note": self.outcome_note, "last_error": self.last_error,
            "scheduled_for": self.scheduled_for.isoformat() if self.scheduled_for else None,
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }


# ════════════════════════════════════════════════════════════
# CLICK-TO-WHATSAPP AD ATTRIBUTION
# A customer who taps a Facebook/Instagram "Send WhatsApp message" ad
# arrives with a `referral` object (ad id, headline, ctwa_clid) on their
# first message. We keep it, tie it to the ERP customer, and when that
# customer pays an invoice we (a) log the revenue against the ad — always,
# so the "which ad made money" report works with no Meta setup — and
# (b) if a Messaging dataset is configured, send the event to Meta's
# Conversions API so ad delivery learns from real sales.
# ════════════════════════════════════════════════════════════
class WhatsAppAdReferral(db.Model):
    __tablename__   = "whatsapp_ad_referrals"
    id              = db.Column(db.Integer, primary_key=True)
    owner_user_id   = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    customer_wa_id  = db.Column(db.String(64),  nullable=False, index=True)   # phone digits or BSUID
    ctwa_clid       = db.Column(db.String(512), nullable=True, index=True)
    source_id       = db.Column(db.String(64),  nullable=True, index=True)    # the ad / post id
    source_type     = db.Column(db.String(16),  nullable=True)                # ad, post
    source_url      = db.Column(db.String(500), nullable=True)
    headline        = db.Column(db.String(300), nullable=True)
    profile_name    = db.Column(db.String(120), nullable=True)
    created_at      = db.Column(db.DateTime, default=datetime.utcnow, index=True)

    def to_dict(self):
        return {"id": self.id, "customer_wa_id": self.customer_wa_id, "source_id": self.source_id,
                "source_type": self.source_type, "headline": self.headline,
                "profile_name": self.profile_name, "has_click_id": bool(self.ctwa_clid),
                "created_at": self.created_at.isoformat() if self.created_at else None}


class WhatsAppAdConversion(db.Model):
    __tablename__   = "whatsapp_ad_conversions"
    __table_args__  = (db.UniqueConstraint("owner_user_id", "event_id", name="uq_wa_adconv_owner_event"),)
    id              = db.Column(db.Integer, primary_key=True)
    owner_user_id   = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    referral_id     = db.Column(db.Integer, db.ForeignKey("whatsapp_ad_referrals.id"), nullable=False, index=True)
    source_id       = db.Column(db.String(64), nullable=True, index=True)
    event_name      = db.Column(db.String(40), nullable=False)
    event_id        = db.Column(db.String(80), nullable=False)       # deterministic → idempotent
    value           = db.Column(db.Float, nullable=True)
    currency        = db.Column(db.String(8), nullable=True)
    status          = db.Column(db.String(16), nullable=False, default="local_only")  # local_only, sent, failed, expired
    error           = db.Column(db.String(300), nullable=True)
    created_at      = db.Column(db.DateTime, default=datetime.utcnow, index=True)


class WhatsAppAdSettings(db.Model):
    __tablename__   = "whatsapp_ad_settings"
    id              = db.Column(db.Integer, primary_key=True)
    owner_user_id   = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, unique=True)
    dataset_id      = db.Column(db.String(64), nullable=True)   # Meta dataset for business-messaging events
    test_event_code = db.Column(db.String(64), nullable=True)
    auto_lead       = db.Column(db.Boolean, nullable=False, default=True)
    auto_purchase   = db.Column(db.Boolean, nullable=False, default=True)
    window_days     = db.Column(db.Integer, nullable=False, default=7)  # don't send events for clicks older than this


# WHATSAPP FLOWS DATA ENDPOINT — per-business RSA key (private half kept
# encrypted at rest, public half uploaded to Meta) plus the settings the
# live booking/stock screens need. url_token is the secret path segment
# that tells the shared endpoint which business a request belongs to.
class WhatsAppFlowEndpoint(db.Model):
    __tablename__      = "whatsapp_flow_endpoints"
    id                 = db.Column(db.Integer, primary_key=True)
    owner_user_id      = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, unique=True)
    url_token          = db.Column(db.String(64), nullable=False, unique=True, index=True)
    private_key_enc    = db.Column(db.Text, nullable=False)
    public_key_pem     = db.Column(db.Text, nullable=False)
    key_uploaded       = db.Column(db.Boolean, nullable=False, default=False)
    first_screen       = db.Column(db.String(64), nullable=False, default="WELCOME_SCREEN")
    success_screen     = db.Column(db.String(64), nullable=False, default="SUCCESS_SCREEN")
    slot_minutes       = db.Column(db.Integer, nullable=False, default=30)
    slot_days_ahead    = db.Column(db.Integer, nullable=False, default=14)
    tz_offset_minutes  = db.Column(db.Integer, nullable=False, default=0)   # business local time = UTC + this
    created_at         = db.Column(db.DateTime, default=datetime.utcnow)


# WHATSAPP VOICE AGENT — AI answers inbound WhatsApp calls. The Flask
# app is the control plane (settings, call routing, the AI's turn logic,
# transcripts, human callback). The audio itself runs in a separate
# long-lived process, voice_bridge.py, because WebRTC media can't live
# inside request/response workers. The bridge authenticates with
# VOICE_BRIDGE_TOKEN and speaks only to the /api/voice-bridge/* routes.
class WhatsAppVoiceAgentSettings(db.Model):
    __tablename__      = "whatsapp_voice_agent_settings"
    id                 = db.Column(db.Integer, primary_key=True)
    owner_user_id      = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, unique=True)
    enabled            = db.Column(db.Boolean, nullable=False, default=False)
    greeting           = db.Column(db.String(300), nullable=False,
                                   default="Hello, thanks for calling. I'm the virtual assistant. How can I help?")
    voice              = db.Column(db.String(32), nullable=False, default="alloy")
    language           = db.Column(db.String(16), nullable=False, default="en")
    max_call_seconds   = db.Column(db.Integer, nullable=False, default=300)
