# INVOICE PAYMENT LINKS — a hosted Stripe/Flutterwave checkout created for
# ONE ERP invoice. Settlement is confirmed server-to-server with the
# business's OWN provider key (never trusting a redirect or a webhook
# body alone), and applied exactly once.
class InvoicePaymentLink(db.Model):
    __tablename__     = "invoice_payment_links"
    id                = db.Column(db.Integer, primary_key=True)
    owner_user_id     = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    invoice_id        = db.Column(db.Integer, nullable=False, index=True)
    provider          = db.Column(db.String(16), nullable=False)          # stripe, flutterwave
    reference         = db.Column(db.String(80), nullable=False, unique=True, index=True)   # INV<id>-...
    provider_ref      = db.Column(db.String(200), nullable=False, index=True)  # stripe session id / flutterwave tx_ref
    currency          = db.Column(db.String(8), nullable=False)
