# ════════════════════════════════════════════════════════════
# STAGE 133: AI CONTRACT RISK ANALYZER
# Different direction from the existing Contract Generator (Stage-era
# 'contract' tool, which drafts a contract for the user to send out):
# this reviews a contract someone hands the user — a lease, supplier
# agreement, employment offer — and flags real risk patterns (auto-renewal
# traps, unlimited liability, one-sided termination) before they sign.
# Every scan is a real record: the extracted contract text and the AI's
# risk report are both stored, not thrown away after the response.
# ════════════════════════════════════════════════════════════
class ContractRiskAnalysis(db.Model):
    __tablename__ = "contract_risk_analyses"
    id             = db.Column(db.Integer,     primary_key=True)
    user_id        = db.Column(db.Integer,     db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    contract_name  = db.Column(db.String(200), nullable=True)
    source_text    = db.Column(db.Text,        nullable=False)  # extracted/pasted contract text analyzed
    risk_report    = db.Column(db.Text,        nullable=False)  # AI's structured risk findings
    created_at     = db.Column(db.DateTime,    default=datetime.utcnow, index=True)

    def to_dict(self, include_text=False):
        d = {
            "id": self.id, "contract_name": self.contract_name,
            "risk_report": self.risk_report,
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }
        if include_text:
            d["source_text"] = self.source_text
        return d


