# STAGE 134: PRODUCT RECALL CHECKER
# Checks a product name against the real, official US CPSC recall
# database (saferproducts.gov REST API — public, documented, live) before
# a business stocks or sells it. The EU Safety Gate/RAPEX system does not
# publish a stable public keyword-search JSON API, so rather than fake an
# automated EU match, this gives a real deep link into the official EU
# Safety Gate portal pre-filled with the product name to check by hand.
# Every check performed is saved as a real record.
# ════════════════════════════════════════════════════════════
class ProductRecallCheck(db.Model):
    __tablename__ = "product_recall_checks"
    id             = db.Column(db.Integer,     primary_key=True)
    user_id        = db.Column(db.Integer,     db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    product_name   = db.Column(db.String(300), nullable=False)
    cpsc_match_count = db.Column(db.Integer,   nullable=False, default=0)
    cpsc_matches_json = db.Column(db.Text,     nullable=True)  # JSON list of simplified CPSC recall matches
    eu_search_url  = db.Column(db.String(500), nullable=True)
    created_at     = db.Column(db.DateTime,    default=datetime.utcnow, index=True)

    def to_dict(self):
        try:
            matches = json.loads(self.cpsc_matches_json) if self.cpsc_matches_json else []
        except Exception:
            matches = []
        return {
            "id": self.id, "product_name": self.product_name,
            "cpsc_match_count": self.cpsc_match_count, "cpsc_matches": matches,
            "eu_search_url": self.eu_search_url,
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }


