def _maintenance_due_check(reminder):
    """Returns (due_soon: bool, reason: str|None) for a MaintenanceReminder,
    based on km since last done and/or months since last done."""
    reasons = []
    if reminder.interval_km and reminder.current_km is not None:
        base = reminder.last_done_km or 0
        remaining = (base + reminder.interval_km) - reminder.current_km
        if remaining <= 0:
            reasons.append(f"{abs(remaining)} km overdue")
        elif remaining <= 500:
            reasons.append(f"due in {remaining} km")
    if reminder.interval_months and reminder.last_done_at:
        due_date = reminder.last_done_at + timedelta(days=reminder.interval_months * 30)
        days_left = (due_date - datetime.utcnow()).days
        if days_left <= 0:
            reasons.append(f"{abs(days_left)} day(s) overdue")
        elif days_left <= 14:
            reasons.append(f"due in {days_left} day(s)")
    return (len(reasons) > 0, "; ".join(reasons) if reasons else None)


