# ════════════════════════════════════════════════════════════
# STAGE 94B: SUCCESSION EXTENSION — DIGITAL WILL
# Closes the real gap in STAGE 94 above: that plan has exactly one
# successor contact and free-text notes, and nobody but the owner can
# ever see it, even if the owner becomes unreachable. This adds (1) a
# structured asset/key-contact register instead of one notes field,
# and (2) an actual access mechanism — a trusted contact, a check-in
# interval, and a real email sent through the platform's existing SMTP
# sender (_send_platform_email) once the owner goes quiet past that
# interval. Overdue status is evaluated for real, on demand — see the
# routes below and their comments for exactly what triggers a check
# and what a PythonAnywhere Scheduled Task needs to hit for the email
# side to fire without the owner or trusted contact visiting anything
# first.
# ════════════════════════════════════════════════════════════

class SuccessionAsset(db.Model):
    __tablename__  = "succession_assets"
    id             = db.Column(db.Integer, primary_key=True)
    user_id        = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    category       = db.Column(db.String(24), nullable=False, default="other")  # equipment, account, property, ip, inventory, other
    label          = db.Column(db.String(200), nullable=False)
    location_note  = db.Column(db.Text, nullable=True)  # WHERE to find it / WHO holds it — never an actual password or secret
    created_at     = db.Column(db.DateTime, default=datetime.utcnow, index=True)

    def to_dict(self):
        return {
            "id": self.id, "category": self.category, "label": self.label,
            "location_note": self.location_note,
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }


class SuccessionContact(db.Model):
    __tablename__  = "succession_contacts"
    id             = db.Column(db.Integer, primary_key=True)
    user_id        = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    role           = db.Column(db.String(24), nullable=False, default="other")  # accountant, lawyer, supplier, landlord, bank, other
    name           = db.Column(db.String(200), nullable=False)
    phone          = db.Column(db.String(64), nullable=True)
    email          = db.Column(db.String(200), nullable=True)
    notes          = db.Column(db.String(500), nullable=True)
    created_at     = db.Column(db.DateTime, default=datetime.utcnow, index=True)

    def to_dict(self):
        return {
            "id": self.id, "role": self.role, "name": self.name,
            "phone": self.phone, "email": self.email, "notes": self.notes,
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }


class SuccessionAccessGrant(db.Model):
    __tablename__  = "succession_access_grants"
    id             = db.Column(db.Integer, primary_key=True)
    user_id        = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, unique=True, index=True)
    trusted_name   = db.Column(db.String(200), nullable=False)
    trusted_email  = db.Column(db.String(200), nullable=False)
    checkin_interval_days = db.Column(db.Integer, nullable=False, default=90)
    last_checkin_at = db.Column(db.DateTime, default=datetime.utcnow, nullable=False)
    status         = db.Column(db.String(16), nullable=False, default="active")  # active, triggered, revoked
    access_token   = db.Column(db.String(64), nullable=False, unique=True, index=True)
    triggered_at   = db.Column(db.DateTime, nullable=True)
    notified_at    = db.Column(db.DateTime, nullable=True)
    created_at     = db.Column(db.DateTime, default=datetime.utcnow)

    def is_overdue(self) -> bool:
        if self.status != "active":
            return False
        return datetime.utcnow() - self.last_checkin_at > timedelta(days=self.checkin_interval_days)

    def to_dict(self):
        days_since = (datetime.utcnow() - self.last_checkin_at).days
        return {
            "trusted_name": self.trusted_name, "trusted_email": self.trusted_email,
            "checkin_interval_days": self.checkin_interval_days,
            "last_checkin_at": self.last_checkin_at.isoformat() if self.last_checkin_at else None,
            "days_since_checkin": days_since,
            "status": self.status,
            "triggered_at": self.triggered_at.isoformat() if self.triggered_at else None,
        }



# An extension of the Group-Buy mechanic (STAGE 72) above, but for
# shared OWNERSHIP of one expensive asset rather than a one-time bulk
# purchase — several businesses pool capital toward a solar system (or
# any shared equipment), each holding a real ownership share
# proportional to what they actually put in, and splitting whatever
# the asset earns or saves (e.g. electricity savings) the same way.
# Real pledges, real ownership percentages, real logged savings —
# nothing simulated or auto-generated.
# ════════════════════════════════════════════════════════════

class EquipmentPool(db.Model):
    __tablename__  = "equipment_pools"
    id             = db.Column(db.Integer, primary_key=True)
    organizer_id   = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    title          = db.Column(db.String(160), nullable=False)
    equipment_type = db.Column(db.String(100), nullable=False, default="Solar system")
    description    = db.Column(db.Text, nullable=True)
    total_cost     = db.Column(db.Float, nullable=False, default=0)   # full price of the asset
    currency       = db.Column(db.String(8), nullable=False, default="USD")
    area           = db.Column(db.String(120), nullable=True, index=True)
    deadline       = db.Column(db.DateTime, nullable=True)
    status         = db.Column(db.String(16), nullable=False, default="open", index=True)  # open, funded, active, dissolved, cancelled
    notes          = db.Column(db.Text, nullable=True)
    created_at     = db.Column(db.DateTime, default=datetime.utcnow, index=True)

    def to_dict(self, include_contributions=False):
        contributions = EquipmentPoolContribution.query.filter_by(pool_id=self.id).all()
        pledged_total = round(sum(c.amount_pledged for c in contributions), 2)
        d = {
            "id": self.id, "organizer_id": self.organizer_id, "title": self.title,
            "equipment_type": self.equipment_type, "description": self.description,
            "total_cost": self.total_cost, "currency": self.currency, "area": self.area,
            "deadline": self.deadline.isoformat() if self.deadline else None,
            "status": self.status, "notes": self.notes,
            "created_at": self.created_at.isoformat() if self.created_at else None,
            "pledged_total": pledged_total,
            "funding_pct": round(min(pledged_total / self.total_cost * 100, 100), 1) if self.total_cost else 0,
            "fully_funded": self.total_cost > 0 and pledged_total >= self.total_cost,
            "member_count": len(contributions),
        }
        if include_contributions:
            d["contributions"] = [
                dict(c.to_dict(), ownership_pct=round((c.amount_pledged / pledged_total * 100), 1) if pledged_total else 0)
                for c in contributions
            ]
        return d


class EquipmentPoolContribution(db.Model):
    __tablename__  = "equipment_pool_contributions"
    id             = db.Column(db.Integer, primary_key=True)
    pool_id        = db.Column(db.Integer, db.ForeignKey("equipment_pools.id"), nullable=False, index=True)
    user_id        = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    amount_pledged = db.Column(db.Float, nullable=False, default=0)
    contact        = db.Column(db.String(120), nullable=True)
    created_at     = db.Column(db.DateTime, default=datetime.utcnow)
    __table_args__ = (db.UniqueConstraint("pool_id", "user_id", name="uq_equipmentpool_user_contribution"),)

    def to_dict(self):
        member = UserAccount.query.get(self.user_id)
        return {
            "id": self.id, "user_id": self.user_id, "member_name": member.name if member else None,
            "amount_pledged": self.amount_pledged, "contact": self.contact,
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }


class EquipmentPoolSavingsLog(db.Model):
    """A period's real recorded savings/earnings from the shared asset
    (e.g. electricity bill reduction from a solar system), split among
    members proportional to their actual ownership share at log time."""
    __tablename__  = "equipment_pool_savings_logs"
    id             = db.Column(db.Integer, primary_key=True)
    pool_id        = db.Column(db.Integer, db.ForeignKey("equipment_pools.id"), nullable=False, index=True)
    logged_by      = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False)
    period_label   = db.Column(db.String(60), nullable=False)   # e.g. "June 2026"
    amount         = db.Column(db.Float, nullable=False, default=0)
    notes          = db.Column(db.String(300), nullable=True)
    created_at     = db.Column(db.DateTime, default=datetime.utcnow, index=True)

    def to_dict(self):
        return {
            "id": self.id, "period_label": self.period_label, "amount": self.amount,
            "notes": self.notes, "created_at": self.created_at.isoformat() if self.created_at else None,
        }


# ════════════════════════════════════════════════════════════
# STAGE 96: CURRENCY VOLATILITY PRICING ADVISOR
# Businesses that price in a volatile local currency (ZWG, ZAR, etc.)
# quietly lose margin between price reviews as the currency slides
# against the USD — the product still costs the same in USD to
# restock, but the local-currency shelf price hasn't moved. This
# tracks a real "anchor" FX rate (captured the last time the user
# confirmed their price list was in sync) against the live rate from
# the same free FX source used by the ERP exchange-rate setting
# above, and flags exactly how far local prices have drifted so the
# business knows when — and by how much — to reprice. Nothing
# simulated: real live rates, real product prices from InventoryItem.
# ════════════════════════════════════════════════════════════

class FxVolatilityAdvisorSetting(db.Model):
    __tablename__      = "fx_volatility_advisor_settings"
    id                 = db.Column(db.Integer,  primary_key=True)
    owner_user_id      = db.Column(db.Integer,  db.ForeignKey("user_accounts.id"), nullable=False, unique=True, index=True)
    home_currency      = db.Column(db.String(8), nullable=False, default="ZWG")   # currency the business prices in
    alert_threshold_pct = db.Column(db.Float,   nullable=False, default=5.0)      # flag once drift exceeds this
    anchor_rate        = db.Column(db.Float,    nullable=True)    # home_currency per 1 USD, at last confirmed repricing
    anchor_captured_at = db.Column(db.DateTime, nullable=True)
    last_checked_rate  = db.Column(db.Float,    nullable=True)
    last_checked_at    = db.Column(db.DateTime, nullable=True)
    last_alert_sent_at = db.Column(db.DateTime, nullable=True)   # throttles the cron email to once per breach
    created_at         = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        return {
            "home_currency": self.home_currency,
            "alert_threshold_pct": self.alert_threshold_pct,
            "anchor_rate": self.anchor_rate,
            "anchor_captured_at": self.anchor_captured_at.isoformat() if self.anchor_captured_at else None,
            "last_checked_rate": self.last_checked_rate,
            "last_checked_at": self.last_checked_at.isoformat() if self.last_checked_at else None,
        }


# ════════════════════════════════════════════════════════════
# STAGE 97: DIGITAL POS / TILL
# Real checkout flow tying Inventory, Payments, and the Ledger together
# instead of three separate tools — scan/search a product, build a
# cart, take payment, print/send a receipt. Stock decrements for real;
# revenue posts to ErpLedgerEntry for real; loyalty points earn for
# real if the phone number matches a LoyaltyCustomer.
# ════════════════════════════════════════════════════════════

class PosSale(db.Model):
    __tablename__  = "pos_sales"
    id             = db.Column(db.Integer,  primary_key=True)
    owner_user_id  = db.Column(db.Integer,  db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    sale_number    = db.Column(db.String(40), nullable=False)
    employee_id    = db.Column(db.Integer,  db.ForeignKey("erp_employees.id"), nullable=True, index=True)
    customer_id    = db.Column(db.Integer,  db.ForeignKey("erp_customers.id"), nullable=True)
    currency       = db.Column(db.String(8), nullable=False, default="USD")
    subtotal       = db.Column(db.Float,    nullable=False, default=0)
    tax_amount     = db.Column(db.Float,    nullable=False, default=0)
    total          = db.Column(db.Float,    nullable=False, default=0)
    payment_method = db.Column(db.String(20), nullable=False, default="cash")  # cash, ecocash, card, bank, split
    amount_tendered = db.Column(db.Float,   nullable=True)
    change_due     = db.Column(db.Float,    nullable=True)
    created_at     = db.Column(db.DateTime, default=datetime.utcnow, index=True)
    # STAGE 500: TILL / POS — new columns, all nullable so every existing
    # sale row and the original single-screen checkout keep working
    # unchanged. Run once on the production MySQL DB before deploying:
    #   ALTER TABLE pos_sales ADD COLUMN till_id INTEGER NULL;
    #   ALTER TABLE pos_sales ADD COLUMN till_session_id INTEGER NULL;
    #   ALTER TABLE pos_sales ADD COLUMN client_txn_id VARCHAR(64) NULL;
    #   ALTER TABLE pos_sales ADD COLUMN is_return BOOLEAN NOT NULL DEFAULT FALSE;
    #   ALTER TABLE pos_sales ADD COLUMN original_sale_id INTEGER NULL;
    #   ALTER TABLE pos_sales ADD COLUMN voided BOOLEAN NOT NULL DEFAULT FALSE;
    #   CREATE UNIQUE INDEX uq_pos_sales_owner_client_txn ON pos_sales (owner_user_id, client_txn_id);
    # till_id/till_session_id identify which physical register and which
    # cashier shift rang this sale up — see PosTill/PosTillSession below.
    # client_txn_id is a UUID the CHECKOUT SCREEN generates itself before
    # the request ever leaves the device; it's what makes offline-queued
    # sales safe to replay on reconnect without ringing the same sale up
    # twice (see /api/pos/sync and _pos_process_sale's idempotency check).
    till_id         = db.Column(db.Integer,  db.ForeignKey("pos_tills.id"), nullable=True, index=True)
    till_session_id = db.Column(db.Integer,  db.ForeignKey("pos_till_sessions.id"), nullable=True, index=True)
    client_txn_id   = db.Column(db.String(64), nullable=True, index=True)
    is_return       = db.Column(db.Boolean,  nullable=False, default=False)
    original_sale_id = db.Column(db.Integer, db.ForeignKey("pos_sales.id"), nullable=True)
    voided          = db.Column(db.Boolean,  nullable=False, default=False)
    # RETAIL PACK 2: digital receipt lookup by phone — a snapshot of the
    # walk-in customer's phone number at sale time (separate from
    # customer_id, which only exists for saved ErpCustomer records). New
    # column, auto-migrated on startup (or run once on production MySQL):
    #   ALTER TABLE pos_sales ADD COLUMN customer_phone VARCHAR(64) NULL;
    customer_phone  = db.Column(db.String(64), nullable=True, index=True)

    __table_args__ = (
        db.UniqueConstraint("owner_user_id", "client_txn_id", name="uq_pos_sales_owner_client_txn"),
    )

    def to_dict(self, include_items=False, include_tenders=False):
        employee = ErpEmployee.query.get(self.employee_id) if self.employee_id else None
        d = {
            "id": self.id, "sale_number": self.sale_number, "employee_id": self.employee_id,
            "employee_name": employee.full_name if employee else None,
            "customer_id": self.customer_id, "currency": self.currency, "subtotal": self.subtotal,
            "tax_amount": self.tax_amount, "total": self.total, "payment_method": self.payment_method,
            "amount_tendered": self.amount_tendered, "change_due": self.change_due,
            "created_at": self.created_at.isoformat() if self.created_at else None,
            "till_id": self.till_id, "till_session_id": self.till_session_id,
            "client_txn_id": self.client_txn_id, "is_return": bool(self.is_return),
            "original_sale_id": self.original_sale_id, "voided": bool(self.voided),
            "customer_phone": self.customer_phone,
        }
        if include_items:
            d["items"] = [i.to_dict() for i in PosSaleItem.query.filter_by(sale_id=self.id).all()]
        if include_tenders:
            d["tenders"] = [t.to_dict() for t in PosSaleTender.query.filter_by(sale_id=self.id).all()]
        return d


class PosSaleItem(db.Model):
    __tablename__ = "pos_sale_items"
    id           = db.Column(db.Integer,  primary_key=True)
    sale_id      = db.Column(db.Integer,  db.ForeignKey("pos_sales.id"), nullable=False, index=True)
    product_id   = db.Column(db.Integer,  db.ForeignKey("inventory_items.id"), nullable=True)
    description  = db.Column(db.String(300), nullable=False)
    quantity     = db.Column(db.Float,    nullable=False, default=1)
    unit_price   = db.Column(db.Float,    nullable=False, default=0)
    line_total   = db.Column(db.Float,    nullable=False, default=0)

    def to_dict(self):
        return {
            "id": self.id, "product_id": self.product_id, "description": self.description,
            "quantity": self.quantity, "unit_price": self.unit_price, "line_total": self.line_total,
        }


# ════════════════════════════════════════════════════════════
# STAGE 500: TILL / POS — MULTI-REGISTER, SHIFTS, SPLIT TENDER, RETURNS
# Everything below extends Stage 97's single-screen checkout into a
# real till environment: several physical registers under one seller
# account (PosTill), a cashier-level open/close/cash-count audit trail
# per register (PosTillSession), part-cash/part-card/part-store-credit
# sales in one transaction (PosSaleTender), and a returns/exchange flow
# that restocks Inventory and refunds against the original sale
# (PosReturn). Offline selling reuses the frontend's existing
# queuedFetch() localStorage queue (Stage 118) — PosSale.client_txn_id
# is what lets a queued sale replay safely on reconnect without
# double-ringing it up.
# ════════════════════════════════════════════════════════════

class PosTill(db.Model):
    """A physical register/till under this seller account. Sales,
    sessions and the customer-facing display are all scoped to one of
    these — 'multi-till' just means more than one row here per owner."""
    __tablename__  = "pos_tills"
    id             = db.Column(db.Integer,  primary_key=True)
    owner_user_id  = db.Column(db.Integer,  db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    name           = db.Column(db.String(80), nullable=False)             # e.g. "Front Counter", "Till 2"
    location_note  = db.Column(db.String(160), nullable=True)
    active         = db.Column(db.Boolean,  nullable=False, default=True)
    created_at     = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        open_session = (PosTillSession.query.filter_by(till_id=self.id, status="open")
                         .order_by(PosTillSession.opened_at.desc()).first())
        return {
            "id": self.id, "name": self.name, "location_note": self.location_note,
            "active": self.active, "created_at": self.created_at.isoformat() if self.created_at else None,
            "is_open": bool(open_session), "open_session": open_session.to_dict() if open_session else None,
        }


class PosTillSession(db.Model):
    """One cashier's shift on one till: opened with a starting cash
    float, closed with a physical cash count reconciled against what
    the system expected. This IS the shift/cashier login + audit trail
    — who rang up what, when, on which till."""
    __tablename__     = "pos_till_sessions"
    id                = db.Column(db.Integer,  primary_key=True)
    owner_user_id     = db.Column(db.Integer,  db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    till_id           = db.Column(db.Integer,  db.ForeignKey("pos_tills.id"), nullable=False, index=True)
    employee_id       = db.Column(db.Integer,  db.ForeignKey("erp_employees.id"), nullable=True, index=True)
    cashier_name      = db.Column(db.String(120), nullable=True)   # fallback if no ErpEmployee record picked
    status            = db.Column(db.String(12), nullable=False, default="open", index=True)  # open, closed
    opening_float     = db.Column(db.Float,    nullable=False, default=0)
    opening_note      = db.Column(db.String(300), nullable=True)
    opened_at         = db.Column(db.DateTime, default=datetime.utcnow, index=True)
    closing_counted_cash = db.Column(db.Float, nullable=True)
    closing_expected_cash = db.Column(db.Float, nullable=True)
    closing_variance  = db.Column(db.Float,    nullable=True)   # counted - expected; negative = short
    closing_note      = db.Column(db.String(300), nullable=True)
    closed_at         = db.Column(db.DateTime, nullable=True)

    def summary(self):
        """Live totals for this session, computed from real PosSale rows
        rather than kept as a separately-maintained running counter that
        could drift."""
        sales = (PosSale.query.filter_by(till_session_id=self.id, voided=False)
                 .filter(PosSale.is_return.is_(False)).all())
        returns = (PosSale.query.filter_by(till_session_id=self.id, voided=False)
                   .filter(PosSale.is_return.is_(True)).all())
        gross_sales = round(sum((s.total or 0) for s in sales), 2)
        gross_returns = round(sum((r.total or 0) for r in returns), 2)
        cash_in = 0.0
        cash_out = 0.0
        for s in sales:
            tenders = PosSaleTender.query.filter_by(sale_id=s.id).all()
            if tenders:
                cash_in += sum(t.amount for t in tenders if t.method == "cash")
            elif (s.payment_method or "") == "cash":
                cash_in += (s.total or 0)
        for r in returns:
            tenders = PosSaleTender.query.filter_by(sale_id=r.id).all()
            if tenders:
                cash_out += sum(t.amount for t in tenders if t.method == "cash")
            elif (r.payment_method or "") == "cash":
                cash_out += (r.total or 0)
        expected_cash = round((self.opening_float or 0) + cash_in - cash_out, 2)
        return {
            "sale_count": len(sales), "return_count": len(returns),
            "gross_sales": gross_sales, "gross_returns": gross_returns,
            "net_sales": round(gross_sales - gross_returns, 2),
            "cash_in": round(cash_in, 2), "cash_out": round(cash_out, 2),
            "expected_cash": expected_cash,
        }

    def to_dict(self, include_summary=True):
        employee = ErpEmployee.query.get(self.employee_id) if self.employee_id else None
        till = PosTill.query.get(self.till_id)
        d = {
            "id": self.id, "till_id": self.till_id, "till_name": till.name if till else None,
            "employee_id": self.employee_id, "cashier_name": employee.full_name if employee else self.cashier_name,
            "status": self.status, "opening_float": self.opening_float, "opening_note": self.opening_note,
            "opened_at": self.opened_at.isoformat() if self.opened_at else None,
            "closing_counted_cash": self.closing_counted_cash, "closing_expected_cash": self.closing_expected_cash,
            "closing_variance": self.closing_variance, "closing_note": self.closing_note,
            "closed_at": self.closed_at.isoformat() if self.closed_at else None,
        }
        if include_summary:
            d["summary"] = self.summary()
        return d


class PosSaleTender(db.Model):
    """One payment line within a sale. A simple single-method sale still
    gets exactly one row here (mirroring PosSale.payment_method) so
    every sale — split or not — has a consistent tender breakdown to
    query against for till reconciliation."""
    __tablename__ = "pos_sale_tenders"
    id           = db.Column(db.Integer,  primary_key=True)
    sale_id      = db.Column(db.Integer,  db.ForeignKey("pos_sales.id"), nullable=False, index=True)
    method       = db.Column(db.String(20), nullable=False)   # cash, card, ecocash, bank, store_credit
    amount       = db.Column(db.Float,    nullable=False, default=0)
    reference    = db.Column(db.String(120), nullable=True)   # card auth code / store-credit note, optional

    def to_dict(self):
        return {"id": self.id, "method": self.method, "amount": self.amount, "reference": self.reference}


class PosReturn(db.Model):
    """A return or exchange processed at the till against a specific
    original sale. Restocks Inventory (unless the item was damaged) and
    posts a real refund PosSale (is_return=True) so the ledger and till
    reconciliation both see it, instead of only living in this table."""
    __tablename__     = "pos_returns"
    id                = db.Column(db.Integer,  primary_key=True)
    owner_user_id     = db.Column(db.Integer,  db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    original_sale_id  = db.Column(db.Integer,  db.ForeignKey("pos_sales.id"), nullable=False, index=True)
    refund_sale_id    = db.Column(db.Integer,  db.ForeignKey("pos_sales.id"), nullable=True)
    till_session_id   = db.Column(db.Integer,  db.ForeignKey("pos_till_sessions.id"), nullable=True, index=True)
    sale_item_id      = db.Column(db.Integer,  db.ForeignKey("pos_sale_items.id"), nullable=True)
    description       = db.Column(db.String(300), nullable=False)
    quantity          = db.Column(db.Float,    nullable=False, default=1)
    refund_amount     = db.Column(db.Float,    nullable=False, default=0)
    refund_method     = db.Column(db.String(20), nullable=False, default="cash")
    reason            = db.Column(db.String(300), nullable=True)
    kind              = db.Column(db.String(16), nullable=False, default="return")  # return, exchange
    restocked         = db.Column(db.Boolean,  nullable=False, default=True)
    created_at        = db.Column(db.DateTime, default=datetime.utcnow, index=True)

    def to_dict(self):
        return {
            "id": self.id, "original_sale_id": self.original_sale_id, "refund_sale_id": self.refund_sale_id,
            "till_session_id": self.till_session_id, "sale_item_id": self.sale_item_id,
            "description": self.description, "quantity": self.quantity, "refund_amount": self.refund_amount,
            "refund_method": self.refund_method, "reason": self.reason, "kind": self.kind,
            "restocked": self.restocked, "created_at": self.created_at.isoformat() if self.created_at else None,
        }


# ════════════════════════════════════════════════════════════
# STAGE 98: RECURRING / SUBSCRIPTION BILLING
# For retainers, cleaning contracts, subscriptions — an invoice that
# should go out on a schedule without the owner remembering. The cron
# route creates a real ErpInvoice from the schedule each time it's due.
# ════════════════════════════════════════════════════════════

class RecurringInvoiceSchedule(db.Model):
    __tablename__  = "recurring_invoice_schedules"
    id             = db.Column(db.Integer,  primary_key=True)
    owner_user_id  = db.Column(db.Integer,  db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    customer_id    = db.Column(db.Integer,  db.ForeignKey("erp_customers.id"), nullable=True, index=True)
    description    = db.Column(db.String(300), nullable=False)
    amount         = db.Column(db.Float,    nullable=False, default=0)
    currency       = db.Column(db.String(8), nullable=False, default="USD")
    frequency      = db.Column(db.String(16), nullable=False, default="monthly")  # weekly, monthly
    next_run_date  = db.Column(db.Date,     nullable=False)
    active         = db.Column(db.Boolean,  nullable=False, default=True)
    last_invoice_id = db.Column(db.Integer, nullable=True)
    created_at     = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        customer = ErpCustomer.query.get(self.customer_id) if self.customer_id else None
        return {
            "id": self.id, "customer_id": self.customer_id, "customer_name": customer.name if customer else None,
            "description": self.description, "amount": self.amount, "currency": self.currency,
            "frequency": self.frequency,
            "next_run_date": self.next_run_date.isoformat() if self.next_run_date else None,
            "active": self.active, "last_invoice_id": self.last_invoice_id,
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }


# ════════════════════════════════════════════════════════════
# STAGE 99: AUTOMATED INVOICE CHASING
# Nudges customers with overdue ErpInvoice balances on a set cadence
# instead of the owner having to remember who still owes them.
# ════════════════════════════════════════════════════════════

class InvoiceChaseSetting(db.Model):
    __tablename__  = "invoice_chase_settings"
    id             = db.Column(db.Integer,  primary_key=True)
    owner_user_id  = db.Column(db.Integer,  db.ForeignKey("user_accounts.id"), nullable=False, unique=True, index=True)
    enabled        = db.Column(db.Boolean,  nullable=False, default=True)
    days_after_due = db.Column(db.Integer,  nullable=False, default=3)   # tier 1 (polite) threshold, days overdue
    message_template = db.Column(db.Text,   nullable=True)               # tier 1 (polite) message

    # STAGE 166: GRADUATED COLLECTIONS — tier 2 (firm) and tier 3 (final
    # notice) escalate the tone and urgency the longer an invoice sits
    # unpaid, instead of repeating the same polite nudge forever.
    tier2_days        = db.Column(db.Integer, nullable=False, default=7)
    tier2_template     = db.Column(db.Text,   nullable=True)
    tier3_days        = db.Column(db.Integer, nullable=False, default=14)
    tier3_template     = db.Column(db.Text,   nullable=True)

    # STAGE 166: AUTO-INSTALLMENT PLAN OFFER — once an invoice has been
    # chased to the final-notice tier and stays unpaid, the platform can
    # automatically propose splitting the balance into equal instalments
    # rather than the owner having to negotiate this by hand.
    installment_enabled       = db.Column(db.Boolean, nullable=False, default=False)
    installment_trigger_days  = db.Column(db.Integer, nullable=False, default=21)
    installment_num_parts     = db.Column(db.Integer, nullable=False, default=3)
    installment_frequency_days = db.Column(db.Integer, nullable=False, default=14)

    created_at     = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        return {
            "enabled": self.enabled, "days_after_due": self.days_after_due,
            "message_template": self.message_template,
            "tier2_days": self.tier2_days, "tier2_template": self.tier2_template,
            "tier3_days": self.tier3_days, "tier3_template": self.tier3_template,
            "installment_enabled": self.installment_enabled,
            "installment_trigger_days": self.installment_trigger_days,
            "installment_num_parts": self.installment_num_parts,
            "installment_frequency_days": self.installment_frequency_days,
        }


class InvoiceChaseLog(db.Model):
    __tablename__  = "invoice_chase_logs"
    id             = db.Column(db.Integer,  primary_key=True)
    invoice_id     = db.Column(db.Integer,  db.ForeignKey("erp_invoices.id"), nullable=False, index=True)
    sent_at        = db.Column(db.DateTime, default=datetime.utcnow, index=True)
    channel        = db.Column(db.String(16), nullable=False, default="email")
    # STAGE 166: which escalation tier this nudge belonged to — "tier1"
    # (polite), "tier2" (firm), "tier3" (final notice), or
    # "installment_offer" (the auto-proposed payment-plan message).
    tier           = db.Column(db.String(24), nullable=False, default="tier1")

    def to_dict(self):
        return {"invoice_id": self.invoice_id, "sent_at": self.sent_at.isoformat() if self.sent_at else None,
                "channel": self.channel, "tier": self.tier}


# ════════════════════════════════════════════════════════════
# STAGE 166: AUTO-INSTALLMENT PLANS
# When graduated collections reach the final-notice tier and the
# balance is still unpaid, the platform can propose splitting it into
# equal instalments. The customer accepts via a public, no-login link
# (same revocable-token pattern as BusinessPassportShare/TrustScoreShare
# above) — no app or account needed on their side.
# ════════════════════════════════════════════════════════════

class InstallmentPlan(db.Model):
    __tablename__     = "installment_plans"
    id                = db.Column(db.Integer,  primary_key=True)
    invoice_id        = db.Column(db.Integer,  db.ForeignKey("erp_invoices.id"), nullable=False, index=True)
    owner_user_id     = db.Column(db.Integer,  db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    customer_id       = db.Column(db.Integer,  db.ForeignKey("erp_customers.id"), nullable=True, index=True)
    token             = db.Column(db.String(64), unique=True, nullable=False, index=True)
    total_amount      = db.Column(db.Float,    nullable=False, default=0)
    currency          = db.Column(db.String(8), nullable=False, default="USD")
    num_installments  = db.Column(db.Integer,  nullable=False, default=3)
    installment_amount = db.Column(db.Float,   nullable=False, default=0)
    frequency_days    = db.Column(db.Integer,  nullable=False, default=14)
    status            = db.Column(db.String(16), nullable=False, default="proposed", index=True)  # proposed, active, completed, cancelled
    created_at        = db.Column(db.DateTime, default=datetime.utcnow)
    accepted_at       = db.Column(db.DateTime, nullable=True)

    def to_dict(self, include_schedule=False):
        d = {
            "id": self.id, "invoice_id": self.invoice_id, "customer_id": self.customer_id,
            "token": self.token, "total_amount": self.total_amount, "currency": self.currency,
            "num_installments": self.num_installments, "installment_amount": self.installment_amount,
            "frequency_days": self.frequency_days, "status": self.status,
            "created_at": self.created_at.isoformat() if self.created_at else None,
            "accepted_at": self.accepted_at.isoformat() if self.accepted_at else None,
        }
        if include_schedule:
            d["schedule"] = [p.to_dict() for p in
                              InstallmentPayment.query.filter_by(plan_id=self.id).order_by(InstallmentPayment.sequence_number.asc()).all()]
        return d


class InstallmentPayment(db.Model):
    __tablename__     = "installment_payments"
    id                = db.Column(db.Integer,  primary_key=True)
    plan_id           = db.Column(db.Integer,  db.ForeignKey("installment_plans.id"), nullable=False, index=True)
    sequence_number   = db.Column(db.Integer,  nullable=False)   # 1-based position in the schedule
    due_date          = db.Column(db.Date,     nullable=True)
    amount            = db.Column(db.Float,    nullable=False, default=0)
    paid              = db.Column(db.Boolean,  nullable=False, default=False)
    paid_at           = db.Column(db.DateTime, nullable=True)

    def to_dict(self):
        return {
            "id": self.id, "sequence_number": self.sequence_number,
            "due_date": self.due_date.isoformat() if self.due_date else None,
            "amount": self.amount, "paid": self.paid,
            "paid_at": self.paid_at.isoformat() if self.paid_at else None,
        }


# ════════════════════════════════════════════════════════════
# STAGE 167: WHATSAPP VOICE-NOTE-TO-LEDGER
# A business owner sends a WhatsApp voice note ("sold 3 bags of cement
# to John for $40 cash") to their own connected WhatsApp Cloud number;
# it's transcribed and AI-parsed into a structured sale or expense, then
# held for a one-word WhatsApp confirmation ("YES"/"NO") before it's
# ever posted — same "no blind auto-posting of misreads" discipline as
# Stage 110's receipt OCR, just over a channel with no buttons/forms.
#
# Only phone numbers the owner explicitly authorizes (their own number,
# or a trusted staff member's) can post ledger entries this way —
# everyone else's WhatsApp messages to the business number keep getting
# the normal AI chatbot reply, completely unaffected.
# ════════════════════════════════════════════════════════════

class VoiceLedgerSetting(db.Model):
    __tablename__     = "voice_ledger_settings"
    id                = db.Column(db.Integer,  primary_key=True)
    owner_user_id     = db.Column(db.Integer,  db.ForeignKey("user_accounts.id"), nullable=False, unique=True, index=True)
    enabled           = db.Column(db.Boolean,  nullable=False, default=False)
    # Comma-separated, digits-only phone numbers authorized to post ledger
    # entries by voice note (e.g. "263771234567,27821234567").
    authorized_numbers = db.Column(db.Text,    nullable=True)
    created_at        = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        return {
            "enabled": self.enabled,
            "authorized_numbers": [n for n in (self.authorized_numbers or "").split(",") if n],
        }


class VoiceLedgerLog(db.Model):
    __tablename__     = "voice_ledger_logs"
    id                = db.Column(db.Integer,  primary_key=True)
    owner_user_id     = db.Column(db.Integer,  db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    sender_phone      = db.Column(db.String(32), nullable=False)
    transcript        = db.Column(db.Text,     nullable=True)
    extracted_json    = db.Column(db.Text,     nullable=True)
    entry_type        = db.Column(db.String(16), nullable=True)   # "sale" or "expense"
    status            = db.Column(db.String(24), nullable=False, default="pending_confirmation", index=True)
    # pending_confirmation, confirmed, rejected, failed
    linked_ref_type   = db.Column(db.String(24), nullable=True)   # "pos_sale" or "expense"
    linked_ref_id     = db.Column(db.Integer,  nullable=True)
    created_at        = db.Column(db.DateTime, default=datetime.utcnow, index=True)
    resolved_at       = db.Column(db.DateTime, nullable=True)

    def to_dict(self):
        return {
            "id": self.id, "sender_phone": self.sender_phone, "transcript": self.transcript,
            "extracted": json.loads(self.extracted_json) if self.extracted_json else {},
            "entry_type": self.entry_type, "status": self.status,
            "linked_ref_type": self.linked_ref_type, "linked_ref_id": self.linked_ref_id,
            "created_at": self.created_at.isoformat() if self.created_at else None,
            "resolved_at": self.resolved_at.isoformat() if self.resolved_at else None,
        }
# Staff submit a small expense from their phone; the owner approves or
# declines. On approval, a real ErpExpense + ErpLedgerEntry is posted —
# nothing is double-entered by hand afterward.
# ════════════════════════════════════════════════════════════

class ExpenseApprovalRequest(db.Model):
    __tablename__  = "expense_approval_requests"
    id             = db.Column(db.Integer,  primary_key=True)
    owner_user_id  = db.Column(db.Integer,  db.ForeignKey("user_accounts.id"), nullable=False, index=True)  # the business owner who approves
    employee_id    = db.Column(db.Integer,  db.ForeignKey("erp_employees.id"), nullable=True, index=True)
    submitted_by_name = db.Column(db.String(120), nullable=True)
    description    = db.Column(db.String(300), nullable=False)
    amount         = db.Column(db.Float,    nullable=False, default=0)
    currency       = db.Column(db.String(8), nullable=False, default="USD")
    category       = db.Column(db.String(80), nullable=True)
    status         = db.Column(db.String(16), nullable=False, default="pending", index=True)  # pending, approved, declined
    decline_reason = db.Column(db.String(300), nullable=True)
    linked_expense_id = db.Column(db.Integer, nullable=True)
    created_at     = db.Column(db.DateTime, default=datetime.utcnow, index=True)
    decided_at     = db.Column(db.DateTime, nullable=True)

    def to_dict(self):
        return {
            "id": self.id, "employee_id": self.employee_id, "submitted_by_name": self.submitted_by_name,
            "description": self.description, "amount": self.amount, "currency": self.currency,
            "category": self.category, "status": self.status, "decline_reason": self.decline_reason,
            "created_at": self.created_at.isoformat() if self.created_at else None,
            "decided_at": self.decided_at.isoformat() if self.decided_at else None,
        }


# ════════════════════════════════════════════════════════════
# STAGE 101: SHIFT / ROTA SCHEDULER
# A weekly roster for ErpEmployee staff — who's working when, so
# Attendance (which already exists) has a real schedule to check
# against instead of just a raw clock-in log.
# ════════════════════════════════════════════════════════════

class ShiftSchedule(db.Model):
    __tablename__  = "shift_schedules"
    id             = db.Column(db.Integer,  primary_key=True)
    owner_user_id  = db.Column(db.Integer,  db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    employee_id    = db.Column(db.Integer,  db.ForeignKey("erp_employees.id"), nullable=False, index=True)
    shift_date     = db.Column(db.Date,     nullable=False, index=True)
    start_time     = db.Column(db.String(8), nullable=False, default="08:00")
    end_time       = db.Column(db.String(8), nullable=False, default="17:00")
    role_note      = db.Column(db.String(120), nullable=True)
    status         = db.Column(db.String(16), nullable=False, default="scheduled")  # scheduled, completed, missed
    created_at     = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        employee = ErpEmployee.query.get(self.employee_id)
        return {
            "id": self.id, "employee_id": self.employee_id,
            "employee_name": employee.full_name if employee else None,
            "shift_date": self.shift_date.isoformat() if self.shift_date else None,
            "start_time": self.start_time, "end_time": self.end_time,
            "role_note": self.role_note, "status": self.status,
        }


# ════════════════════════════════════════════════════════════
# STAGE 103: DELIVERY ROUTE OPTIMIZER
# No geocoding/mapping API key is wired into this backend, so this is a
# real but deliberately simple heuristic: group a rider's open/accepted
# DeliveryRequest rows by dropoff area so they aren't zig-zagging across
# town, rather than a true shortest-path solve. Clearly labelled as a
# heuristic in the response, same spirit as the Weather Insurance
# Estimator's disclaimer.
# ════════════════════════════════════════════════════════════

# (no dedicated table — reuses DeliveryRequest / DeliveryRider above)


# ════════════════════════════════════════════════════════════
# STAGE 104: FLEET / VEHICLE MAINTENANCE LOG
# For businesses running delivery vehicles — real service history and
# due-date tracking instead of a paper logbook in the glovebox.
# ════════════════════════════════════════════════════════════

class FleetVehicle(db.Model):
    __tablename__  = "fleet_vehicles"
    id             = db.Column(db.Integer,  primary_key=True)
    owner_user_id  = db.Column(db.Integer,  db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    label          = db.Column(db.String(120), nullable=False)   # e.g. "Delivery Van 1"
    plate_number   = db.Column(db.String(32),  nullable=True)
    vehicle_type   = db.Column(db.String(40),  nullable=False, default="van")
    odometer_km    = db.Column(db.Float,    nullable=False, default=0)
    active         = db.Column(db.Boolean,  nullable=False, default=True)
    created_at     = db.Column(db.DateTime, default=datetime.utcnow)
    # Vehicle & Fleet Diagnostics expansion — nullable additions, every
    # existing row and the original simple fleet-log UI keep working
    # unchanged. On the production MySQL DB, run once before deploying:
    #   ALTER TABLE fleet_vehicles ADD COLUMN vin VARCHAR(32) NULL;
    #   ALTER TABLE fleet_vehicles ADD COLUMN make VARCHAR(80) NULL;
    #   ALTER TABLE fleet_vehicles ADD COLUMN model VARCHAR(80) NULL;
    #   ALTER TABLE fleet_vehicles ADD COLUMN year INTEGER NULL;
    #   ALTER TABLE fleet_vehicles ADD COLUMN engine_hours FLOAT NULL;
    vin            = db.Column(db.String(32),  nullable=True)
    make           = db.Column(db.String(80),  nullable=True)
    model          = db.Column(db.String(80),  nullable=True)
    year           = db.Column(db.Integer,     nullable=True)
    engine_hours   = db.Column(db.Float,       nullable=True)

    def to_dict(self):
        logs = FleetMaintenanceLog.query.filter_by(vehicle_id=self.id).order_by(FleetMaintenanceLog.service_date.desc()).all()
        next_due = next((l for l in logs if l.next_service_due_km and l.next_service_due_km <= self.odometer_km), None)
        return {
            "id": self.id, "label": self.label, "name": self.label, "plate_number": self.plate_number,
            "plate": self.plate_number, "vehicle_type": self.vehicle_type,
            "odometer_km": self.odometer_km, "active": self.active,
            "vin": self.vin, "make": self.make, "model": self.model, "year": self.year,
            "engine_hours": self.engine_hours,
            "last_service_date": logs[0].service_date.isoformat() if logs and logs[0].service_date else None,
            "service_due": next_due is not None,
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }


class FleetMaintenanceLog(db.Model):
    __tablename__  = "fleet_maintenance_logs"
    id             = db.Column(db.Integer,  primary_key=True)
    vehicle_id     = db.Column(db.Integer,  db.ForeignKey("fleet_vehicles.id"), nullable=False, index=True)
    service_type   = db.Column(db.String(120), nullable=False)   # e.g. "Oil change"
    cost           = db.Column(db.Float,    nullable=True)
    currency       = db.Column(db.String(8), nullable=False, default="USD")
    odometer_km_at_service = db.Column(db.Float, nullable=True)
    service_date   = db.Column(db.Date,     nullable=True)
    next_service_due_km = db.Column(db.Float, nullable=True)
    notes          = db.Column(db.String(300), nullable=True)
    created_at     = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        return {
            "id": self.id, "vehicle_id": self.vehicle_id, "service_type": self.service_type,
            "cost": self.cost, "currency": self.currency, "odometer_km_at_service": self.odometer_km_at_service,
            "service_date": self.service_date.isoformat() if self.service_date else None,
            "next_service_due_km": self.next_service_due_km, "notes": self.notes,
        }


# ════════════════════════════════════════════════════════════
# VEHICLE & FLEET DIAGNOSTICS EXPANSION
# Extends the Stage 104 FleetVehicle/FleetMaintenanceLog pair with
# real live OBD-II diagnostics. The ELM327 conversation itself (Web
# Serial for USB adapters, Web Bluetooth for BLE adapters) happens
# entirely in the browser — this backend never talks to a vehicle or
# an adapter directly, it only stores and interprets numbers the
# browser already read off the real adapter. DTC decoding reuses the
# existing generic SAE J2012 code table (_GENERIC_DTC_CODES /
# _decode_dtc) built for the personal OBD2 tool above, so both tools
# share one source of truth for fault-code descriptions. Predictive
# alerts are rule-based against real stored readings/DTC history —
# nothing fabricated. Driver behavior scoring uses only real events
# the browser logged from the phone's own GPS/motion sensors during
# an active driving session. Dispatch links to the existing
# DeliveryRequest table when an order_id is given, so fleet dispatch
# and the delivery/logistics system share the same order records
# instead of duplicating them.
# ════════════════════════════════════════════════════════════

class FleetDiagnosticReading(db.Model):
    """One live OBD-II snapshot read from a real ELM327 adapter (or the
    manual-entry fallback) and saved against a fleet vehicle."""
    __tablename__  = "fleet_diagnostic_readings"
    id             = db.Column(db.Integer,  primary_key=True)
    vehicle_id     = db.Column(db.Integer,  db.ForeignKey("fleet_vehicles.id"), nullable=False, index=True)
    owner_user_id  = db.Column(db.Integer,  db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    adapter_kind   = db.Column(db.String(20), nullable=True)   # usb_serial, bluetooth_le, manual
    rpm            = db.Column(db.Float,    nullable=True)
    coolant_temp_c = db.Column(db.Float,    nullable=True)
    fuel_trim_short_pct = db.Column(db.Float, nullable=True)
    fuel_trim_long_pct  = db.Column(db.Float, nullable=True)
    o2_sensor_v    = db.Column(db.Float,    nullable=True)
    intake_temp_c  = db.Column(db.Float,    nullable=True)
    throttle_pct   = db.Column(db.Float,    nullable=True)
    dtc_codes      = db.Column(db.String(300), nullable=True)  # comma-separated, e.g. "P0301,P0420"
    readiness_json = db.Column(db.Text,     nullable=True)     # emissions-readiness monitor snapshot
    recorded_at    = db.Column(db.DateTime, default=datetime.utcnow, index=True)

    def to_dict(self):
        try:
            readiness = json.loads(self.readiness_json) if self.readiness_json else None
        except Exception:
            readiness = None
        return {
            "id": self.id, "vehicle_id": self.vehicle_id, "adapter_kind": self.adapter_kind,
            "rpm": self.rpm, "coolant_temp_c": self.coolant_temp_c,
            "fuel_trim_short_pct": self.fuel_trim_short_pct, "fuel_trim_long_pct": self.fuel_trim_long_pct,
            "o2_sensor_v": self.o2_sensor_v, "intake_temp_c": self.intake_temp_c,
            "throttle_pct": self.throttle_pct,
            "dtc_codes": [c for c in (self.dtc_codes or "").split(",") if c],
            "readiness": readiness,
            "recorded_at": self.recorded_at.isoformat() if self.recorded_at else None,
        }


class FleetMaintenanceSchedule(db.Model):
    """A recurring maintenance task tracked against real mileage and/or
    real elapsed days for one fleet vehicle — distinct from the older
    FleetMaintenanceLog (which is a one-off completed-service record,
    not a schedule of upcoming/recurring tasks)."""
    __tablename__  = "fleet_maintenance_schedules"
    id             = db.Column(db.Integer,  primary_key=True)
    vehicle_id     = db.Column(db.Integer,  db.ForeignKey("fleet_vehicles.id"), nullable=False, index=True)
    owner_user_id  = db.Column(db.Integer,  db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    task_name      = db.Column(db.String(120), nullable=False)
    interval_km    = db.Column(db.Float,    nullable=True)
    interval_days  = db.Column(db.Integer,  nullable=True)
    last_done_at   = db.Column(db.DateTime, nullable=True)
    last_done_km   = db.Column(db.Float,    nullable=True)
    active         = db.Column(db.Boolean,  nullable=False, default=True)
    created_at     = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        vehicle = FleetVehicle.query.get(self.vehicle_id)
        current_km = vehicle.odometer_km if vehicle else None
        km_remaining = None
        days_remaining = None
        overdue = False
        if self.interval_km and current_km is not None:
            base = self.last_done_km or 0
            km_remaining = (base + self.interval_km) - current_km
            if km_remaining <= 0:
                overdue = True
        if self.interval_days:
            base_date = self.last_done_at or self.created_at or datetime.utcnow()
            due_date = base_date + timedelta(days=self.interval_days)
            days_remaining = (due_date - datetime.utcnow()).days
            if days_remaining <= 0:
                overdue = True
        return {
            "id": self.id, "vehicle_id": self.vehicle_id, "task_name": self.task_name,
            "interval_km": self.interval_km, "interval_days": self.interval_days,
            "last_done_at": self.last_done_at.isoformat() if self.last_done_at else None,
            "last_done_km": self.last_done_km, "active": self.active,
            "km_remaining": km_remaining, "days_remaining": days_remaining, "overdue": overdue,
        }


