# ════════════════════════════════════════════════════════════
# STAGE 105: SUPPLIER RFQ TOOL
# No supplier portal exists (or is realistic for most small suppliers
# here), so this matches how the request actually happens: the owner
# calls/emails/WhatsApps a few suppliers, then logs what each one
# quoted, so the comparison and final decision are still tracked
# properly instead of living in someone's notebook.
# ════════════════════════════════════════════════════════════

class RfqRequest(db.Model):
    __tablename__  = "rfq_requests"
    id             = db.Column(db.Integer,  primary_key=True)
    owner_user_id  = db.Column(db.Integer,  db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    title          = db.Column(db.String(200), nullable=False)
    description    = db.Column(db.Text,     nullable=True)
    needed_by_date = db.Column(db.Date,     nullable=True)
    status         = db.Column(db.String(16), nullable=False, default="open", index=True)  # open, closed
    winning_quote_id = db.Column(db.Integer, nullable=True)
    created_at     = db.Column(db.DateTime, default=datetime.utcnow, index=True)

    def to_dict(self, include_quotes=False):
        d = {
            "id": self.id, "title": self.title, "description": self.description,
            "needed_by_date": self.needed_by_date.isoformat() if self.needed_by_date else None,
            "status": self.status, "winning_quote_id": self.winning_quote_id,
            "quote_count": RfqSupplierQuote.query.filter_by(rfq_id=self.id).count(),
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }
        if include_quotes:
            d["quotes"] = [q.to_dict() for q in RfqSupplierQuote.query.filter_by(rfq_id=self.id).order_by(RfqSupplierQuote.quoted_amount.asc()).all()]
        return d


class RfqSupplierQuote(db.Model):
    __tablename__  = "rfq_supplier_quotes"
    id             = db.Column(db.Integer,  primary_key=True)
    rfq_id         = db.Column(db.Integer,  db.ForeignKey("rfq_requests.id"), nullable=False, index=True)
    supplier_id    = db.Column(db.Integer,  db.ForeignKey("erp_suppliers.id"), nullable=True)
    supplier_name  = db.Column(db.String(200), nullable=False)
    quoted_amount  = db.Column(db.Float,    nullable=False, default=0)
    currency       = db.Column(db.String(8), nullable=False, default="USD")
    lead_time_days = db.Column(db.Integer,  nullable=True)
    notes          = db.Column(db.String(300), nullable=True)
    created_at     = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        return {
            "id": self.id, "rfq_id": self.rfq_id, "supplier_id": self.supplier_id,
            "supplier_name": self.supplier_name, "quoted_amount": self.quoted_amount,
            "currency": self.currency, "lead_time_days": self.lead_time_days, "notes": self.notes,
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }


# ════════════════════════════════════════════════════════════
# STAGE 106: UNIFIED CUSTOMER INBOX
# One thread per customer contact regardless of channel. The existing
# WhatsApp Cloud / Messenger webhooks and the SMS/email senders each
# log into this same table (see _inbox_log below) so a business isn't
# checking four apps to see what a customer said.
# ════════════════════════════════════════════════════════════

class UnifiedInboxMessage(db.Model):
    __tablename__  = "unified_inbox_messages"
    id             = db.Column(db.Integer,  primary_key=True)
    owner_user_id  = db.Column(db.Integer,  db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    channel        = db.Column(db.String(16), nullable=False, index=True)  # whatsapp, sms, messenger, email
    contact_identifier = db.Column(db.String(200), nullable=False, index=True)  # phone or email
    contact_name   = db.Column(db.String(120), nullable=True)
    direction      = db.Column(db.String(8),  nullable=False, default="in")  # in, out
    body           = db.Column(db.Text,     nullable=False)
    read_at        = db.Column(db.DateTime, nullable=True)
    # Meta's messages[].id for this exact message, when the channel is a
    # WhatsApp Cloud API message (in either direction). Lets a business
    # reply to a SPECIFIC customer message (Meta's quoted-reply "context")
    # instead of only a plain new message. Nullable/backfill-safe — other
    # channels (email/sms/messenger) and pre-existing rows simply have no
    # value here. New column, auto-migrated on startup (or run once on
    # production MySQL):
    #   ALTER TABLE unified_inbox_messages ADD COLUMN wa_message_id VARCHAR(128) NULL;
    wa_message_id  = db.Column(db.String(128), nullable=True, index=True)
    created_at     = db.Column(db.DateTime, default=datetime.utcnow, index=True)

    def to_dict(self):
        return {
            "id": self.id, "channel": self.channel, "contact_identifier": self.contact_identifier,
            "contact_name": self.contact_name, "direction": self.direction, "body": self.body,
            "read_at": self.read_at.isoformat() if self.read_at else None,
            "wa_message_id": self.wa_message_id,
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }


