# ════════════════════════════════════════════════════════════
# STAGE 115: MUTUAL AID EMERGENCY FUND
# Same real-money-pool mechanic as the Equipment/Solar Financing Pool
# (Stage 95), applied to community emergencies instead of an asset
# purchase — a digital, transparent version of the burial societies and
# stokvels already common in this market. The organizer approves claims
# (matches the owner-scoped approval pattern used throughout this
# platform) rather than requiring on-platform voting infrastructure.
# ════════════════════════════════════════════════════════════

class MutualAidPool(db.Model):
    __tablename__  = "mutual_aid_pools"
    id             = db.Column(db.Integer,  primary_key=True)
    organizer_id   = db.Column(db.Integer,  db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    title          = db.Column(db.String(160), nullable=False)
    description    = db.Column(db.Text,     nullable=True)
    currency       = db.Column(db.String(8), nullable=False, default="USD")
    created_at     = db.Column(db.DateTime, default=datetime.utcnow, index=True)

    def to_dict(self):
        contributions = MutualAidContribution.query.filter_by(pool_id=self.id).all()
        paid_claims = MutualAidClaim.query.filter_by(pool_id=self.id, status="paid").all()
        total_in = round(sum(c.amount for c in contributions), 2)
        total_out = round(sum(c.amount_requested for c in paid_claims), 2)
        return {
            "id": self.id, "title": self.title, "description": self.description, "currency": self.currency,
            "member_count": len({c.user_id for c in contributions}), "total_contributed": total_in,
            "total_paid_out": total_out, "balance": round(total_in - total_out, 2),
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }


class MutualAidContribution(db.Model):
    __tablename__  = "mutual_aid_contributions"
    id             = db.Column(db.Integer,  primary_key=True)
    pool_id        = db.Column(db.Integer,  db.ForeignKey("mutual_aid_pools.id"), nullable=False, index=True)
    user_id        = db.Column(db.Integer,  db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    amount         = db.Column(db.Float,    nullable=False, default=0)
    created_at     = db.Column(db.DateTime, default=datetime.utcnow, index=True)

    def to_dict(self):
        member = UserAccount.query.get(self.user_id)
        return {"id": self.id, "member_name": member.name if member else None, "amount": self.amount,
                "created_at": self.created_at.isoformat() if self.created_at else None}


class MutualAidClaim(db.Model):
    __tablename__  = "mutual_aid_claims"
