# ════════════════════════════════════════════════════════════
# STAGE 152: GLOBAL LEGAL ENTITY VERIFICATION (GLEIF)
# Verifies a business's identity against the Global Legal Entity Identifier
# Foundation's public LEI database — the actual worldwide counterpart to a
# single-country company registry. GLEIF is an international standards body
# whose Global LEI Index covers legal entities in essentially every
# jurisdiction, not one country, so this is the version of "verify this
# business is real" that fits a global platform rather than a regional one.
# API: https://api.gleif.org/api/v1/lei-records — free, no API key, no
# registration required. Rate limit: 60 requests/minute (GLEIF's published
# limit). Confirmed live via GLEIF's own quick-start docs before building.
# Coverage honesty: only entities that hold an LEI are found. Many small
# businesses worldwide don't have one (LEIs are mainly used for financial/
# regulatory reporting), so "no match" means "not found in the LEI system,"
# not "not a real business." The UI states this plainly.
# ════════════════════════════════════════════════════════════
class GleifVerificationCheck(db.Model):
    __tablename__  = "gleif_verification_checks"
    id             = db.Column(db.Integer,     primary_key=True)
    user_id        = db.Column(db.Integer,     db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    query_type     = db.Column(db.String(20),  nullable=False, default="name")  # name | lei | bic
    query_value    = db.Column(db.String(300), nullable=False)
    country_filter = db.Column(db.String(10),  nullable=True)   # optional ISO 3166-1 alpha-2 filter
    match_count    = db.Column(db.Integer,     nullable=False, default=0)
    results_json   = db.Column(db.Text,        nullable=True)   # JSON list of simplified GLEIF matches
    created_at     = db.Column(db.DateTime,    default=datetime.utcnow, index=True)

    def to_dict(self):
        try:
            results = json.loads(self.results_json) if self.results_json else []
        except Exception:
            results = []
        return {
            "id": self.id, "query_type": self.query_type, "query_value": self.query_value,
            "country_filter": self.country_filter, "match_count": self.match_count,
            "results": results,
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }


# ════════════════════════════════════════════════════════════
# STAGE 153: MULTI-CURRENCY FX ENGINE
# Real-time and historical exchange rates from the Frankfurter API
# (ECB reference rates) — free, open-source, no API key, no rate limit.
# Confirmed live at https://api.frankfurter.dev/v1/latest before building.
# Powers multi-currency invoice conversion / reporting for any pair of the
# 30+ currencies ECB publishes; not simulated, pulled fresh every call.
# ════════════════════════════════════════════════════════════
class FxRateQuery(db.Model):
    __tablename__  = "fx_rate_queries"
    id             = db.Column(db.Integer,     primary_key=True)
    user_id        = db.Column(db.Integer,     db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    base_currency  = db.Column(db.String(10),  nullable=False)
    symbols        = db.Column(db.String(200), nullable=True)   # comma list, blank = all
    amount         = db.Column(db.Float,       nullable=False, default=1.0)
    rate_date      = db.Column(db.String(20),  nullable=True)
    rates_json     = db.Column(db.Text,        nullable=True)
    created_at     = db.Column(db.DateTime,    default=datetime.utcnow, index=True)

    def to_dict(self):
        try:
            rates = json.loads(self.rates_json) if self.rates_json else {}
        except Exception:
            rates = {}
        return {
            "id": self.id, "base_currency": self.base_currency, "symbols": self.symbols,
            "amount": self.amount, "rate_date": self.rate_date, "rates": rates,
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }


