# ════════════════════════════════════════════════════════════
# STAGE 150: APPLICATION FIREWALL — SECURITY HEADERS + IP BLOCK
# ════════════════════════════════════════════════════════════

@app.before_request
def _firewall_block_ip():
    """Rejects every request from an IP an admin has blocked, before it
    reaches any route. Checked against the in-memory cache (not the DB)
    so this costs nothing on the hot path."""
    ip = _client_ip()
    with _blocked_ips_lock:
        blocked = ip in _blocked_ips_cache
    if blocked:
        return jsonify({"error": "Access denied."}), 403



# Endpoints that must stay reachable even while the emergency "lock all
# programs" master switch is on — otherwise nobody, including an admin,
# could ever sign in and flip it back off, and legitimate infrastructure
# (uptime checks, static assets, the lock-status/admin-lock endpoints
# themselves) would go down along with everything else. Keep this list
# to auth + the lock system's own plumbing + true infra, nothing else —
# every actual product/business route stays fully subject to the switch.
#
# PWA installability infra (manifest, service worker, icons, TWA domain
# verification) is explicitly included here too: these are not a
# "program" a business owner would ever want gated by the kill switch,
# and blocking them silently breaks "Add to Home Screen"/install on
# every browser with no visible error to the user — exactly the kind of
# outage this exemption list exists to prevent.
_LOCK_EXEMPT_PATH_PREFIXES = (
    "/static/", "/healthz", "/favicon",
    "/manifest.json", "/sw.js", "/.well-known/",
    "/api/program-locks/", "/api/admin/program-locks",
    "/api/feature-flags/public", "/admin/feature-flags",
    "/api/auth/", "/sso/", "/oauth/",
)
_LOCK_EXEMPT_ENDPOINTS = set()  # kept for any future single-endpoint exemptions

@app.before_request
def _emergency_lock_gate():
    """Server-side enforcement of the platform-wide emergency kill
    switch (see ProgramLock/PlatformLockState + /api/admin/program-locks
    above). Individual per-program locks are enforced client-side in
    the menu (they map to UI panels, not 1:1 backend routes), but this
    master switch is real backend enforcement: once an admin locks
    everything, every non-exempt request — API or page — is blocked
    regardless of what the client-side JS does, which is what actually
    matters for a court-order/government-directive shutdown."""
    path = request.path or ""
    if any(path.startswith(p) for p in _LOCK_EXEMPT_PATH_PREFIXES):
        return None
    if (request.endpoint or "") in _LOCK_EXEMPT_ENDPOINTS:
        return None
    # The app shell itself must always load. Previously "/" was blocked too,
    # so while locked nobody (admins included) could even reach the login
    # screen to unlock. The shell is just static UI; every data/API route
    # stays blocked for the public, and index.html shows non-admins a
    # full-screen "suspended" screen (see _renderGlobalLockBanner).
    if path == "/":
        return None
    if not PROGRAM_LOCK_ENFORCEMENT:
        return None  # PROGRAM_LOCK_ENFORCEMENT is always True now — this branch is dead code, kept only in case a future need for a client-side-only mode reintroduces the flag.
                     # This is the actual site-wide gate: with enforcement off, no request
                     # is ever blocked here regardless of what's stored in PlatformLockState,
                     # even if a prior 'lock all' left all_locked=True in the database.
    try:
        if not _all_programs_locked():
            return None
    except Exception:
        return None  # never let the lock-check itself take the site down
    # Platform owner / admins are never locked out — the lock is for the public.
    if _viewer_is_platform_admin():
        return None
    wants_json = (
        path.startswith("/api/") or path in ("/mcp", "/oauth/token", "/oauth/register")
        or request.accept_mimetypes.best == "application/json"
    )
    state = _get_platform_lock_state()
    message = state.reason or "Services have been temporarily suspended by platform administrators."
    if wants_json:
        return jsonify({"error": message, "all_locked": True}), 423
    return (
        "<html><body style='font-family:sans-serif;text-align:center;padding:60px;'>"
        f"<h2>Service Unavailable</h2><p>{xml_escape(message)}</p></body></html>", 423
    )


@app.after_request
def _firewall_security_headers(response):
    """Application-layer equivalent of a WAF's response hardening —
    doesn't require flask-Talisman as a new dependency, just sets the
    headers directly."""
    response.headers["X-Content-Type-Options"] = "nosniff"
    response.headers["X-Frame-Options"] = "DENY"
    response.headers["Referrer-Policy"] = "strict-origin-when-cross-origin"
    response.headers["Permissions-Policy"] = "geolocation=(), microphone=(), camera=()"
    # Only set HSTS when actually served over HTTPS (PythonAnywhere free
    # tier proxies HTTPS to plain HTTP internally, so check the forwarded
    # proto header rather than request.is_secure, which would be wrong).
    if request.headers.get("X-Forwarded-Proto", "https") == "https":
        response.headers["Strict-Transport-Security"] = "max-age=31536000; includeSubDomains"
    return response


# ════════════════════════════════════════════════════════════
# STAGE 175: REQUEST LOGGING + UPTIME/PERFORMANCE MONITORING
# ════════════════════════════════════════════════════════════
# Every request gets its latency and status logged to access.log.
# Anything slower than SLOW_REQUEST_MS also lands in slow.log so
# slow endpoints are easy to find without grepping the full access log.
# /healthz is the endpoint an external uptime monitor (e.g. UptimeRobot's
# free tier) should ping every few minutes — it does a real DB round-trip
# so a database outage shows up as downtime, not a false "healthy".

@app.before_request
def _request_timer_start():
    g._request_start_time = time.time()


@app.after_request
def _request_timer_log(response):
    started = getattr(g, "_request_start_time", None)
    if started is not None:
        duration_ms = round((time.time() - started) * 1000, 1)
        line = (f"{request.method} {request.path} -> {response.status_code} "
                f"({duration_ms}ms) ip={_client_ip()}")
        access_logger.info(line)
        if duration_ms >= SLOW_REQUEST_MS:
            slow_logger.warning(line)
    return response


@app.route("/healthz", methods=["GET"])
def healthz():
    """Uptime-monitor target. No auth, no session — meant to be pinged
    every few minutes by an external service. Does a real DB round-trip
    so a database outage is correctly reported as unhealthy rather than
    the app process merely being alive."""
    from sqlalchemy import text as _sa_text_health
    try:
        db.session.execute(_sa_text_health("SELECT 1"))
        return jsonify({"status": "ok", "time": datetime.utcnow().isoformat() + "Z"}), 200
    except Exception as e:
        logging.error(f"[HEALTHZ] Database check failed: {e}")
        return jsonify({"status": "error", "detail": "database unreachable"}), 503


# ════════════════════════════════════════════════════════════
# STAGE 205: PUBLIC STATUS PAGE — a status.io/Better-Uptime style front
# end for the existing /healthz check, plus admin-postable incidents so
# a business (or Connect It's own team) can see current uptime and any
# ongoing/resolved incidents at a glance, without needing a third-party
# status-page product.
# ════════════════════════════════════════════════════════════

class StatusIncident(db.Model):
    __tablename__  = "status_incidents"
    id             = db.Column(db.Integer,  primary_key=True)
    title          = db.Column(db.String(200), nullable=False)
    message        = db.Column(db.Text,        nullable=True)
    severity       = db.Column(db.String(16),  nullable=False, default="minor")   # minor|major|critical
    status         = db.Column(db.String(16),  nullable=False, default="investigating")  # investigating|identified|monitoring|resolved
    created_at     = db.Column(db.DateTime,    default=datetime.utcnow)
    updated_at     = db.Column(db.DateTime,    default=datetime.utcnow, onupdate=datetime.utcnow)
    resolved_at    = db.Column(db.DateTime,    nullable=True)

    def to_dict(self):
        return {
            "id": self.id, "title": self.title, "message": self.message,
            "severity": self.severity, "status": self.status,
            "created_at": self.created_at.isoformat() if self.created_at else None,
            "updated_at": self.updated_at.isoformat() if self.updated_at else None,
            "resolved_at": self.resolved_at.isoformat() if self.resolved_at else None,
        }


def _status_admin_or_401():
    user, err = _erp_user_or_401()
    if err: return None, err
    email = (user.get("email") or "").strip().lower()
    is_admin = email in ADMIN_EMAILS
    if not is_admin:
        try:
            account = UserAccount.query.get(user["id"])
            is_admin = bool(account and account.is_admin)
        except Exception:
            is_admin = False
    if not is_admin:
        return None, (jsonify({"error": "Admin access required."}), 403)
    return user, None


