def public_list_feature_flags():
    """Read-only, no-admin-required view of every flag's lock state, so the
    menu itself can show a lock badge and pop up 'Locked by Admin' before
    the user ever hits a gated endpoint, instead of only finding out after
    a 503 comes back from deep inside a panel."""
    flags = PlatformFeatureFlag.query.order_by(PlatformFeatureFlag.key.asc()).all()
    return jsonify([
        {"key": f.key, "label": f.label, "enabled": f.enabled, "locked_reason": f.locked_reason}
        for f in flags
    ]), 200


@app.route("/admin/feature-flags/apply-seed-defaults", methods=["POST"])
@csrf.exempt
def admin_apply_feature_flag_seed_defaults():
    """One-off migration for flags whose *seed default* changed in code
    after the row already existed in a live database — _seed_feature_flag()
    only sets the initial value for a brand-new row, so a code change to
    an existing key's default (e.g. carbon_credit_marketplace flipping to
    enabled=True) never reaches an already-deployed database on its own.
    This route closes that gap, but only for rows an admin has never
    actually touched (updated_by_email IS NULL) — a real admin decision,
    once made, is never silently overwritten by a later seed-default
    change, matching _seed_feature_flag()'s own stated guarantee."""
    user, err = _status_admin_or_401()
    if err: return err
    # key -> the enabled value it should have per its CURRENT seed call in
    # code. Keep this in sync with any _seed_feature_flag(..., enabled=...)
    # call above that passes something other than the implicit False.
    CURRENT_SEED_DEFAULTS = {
        "carbon_credit_marketplace": True,
    }
    updated = []
    for key, target_enabled in CURRENT_SEED_DEFAULTS.items():
        flag = PlatformFeatureFlag.query.filter_by(key=key).first()
        if not flag:
            continue  # not seeded yet on this deployment — next request will seed it correctly
        if flag.updated_by_email is not None:
            continue  # an admin already made a real decision on this flag — never touch it
        if flag.enabled != target_enabled:
            flag.enabled = target_enabled
            # Deliberately NOT setting updated_by_email here — this is a
            # code-default migration, not an admin decision, so the row
            # should still read as "never explicitly touched" afterward
            # and remain eligible for this same migration to re-apply
            # cleanly if the seed default changes again later.
            updated.append(key)
    if updated:
        db.session.commit()
    logging.info(f"[FEATURE FLAG SEED MIGRATION] applied to {updated} by {user.get('email')}")
    return jsonify({"ok": True, "updated": updated}), 200


