    data = request.get_json(silent=True) or {}
    key = (data.get("key") or "").strip()
    enabled = bool(data.get("enabled"))
    locked_reason = data.get("locked_reason")
    if not key:
        return jsonify({"error": "'key' is required."}), 400
    flag = PlatformFeatureFlag.query.filter_by(key=key).first()
    if not flag:
        return jsonify({"error": f"Unknown feature flag '{key}'."}), 404
    flag.enabled = enabled
    if locked_reason is not None:
        flag.locked_reason = locked_reason
    flag.updated_by_email = user.get("email")
    flag.updated_at = datetime.utcnow()
    db.session.commit()
    logging.info(f"[FEATURE FLAG] {key} set to enabled={enabled} by {user.get('email')}")
    return jsonify({"ok": True, "flag": flag.to_dict()}), 200


