def admin_toggle_program_lock():
    """Lock or unlock exactly one program."""
    user, err = _status_admin_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    key = (data.get("key") or "").strip()
    locked = bool(data.get("locked"))
    reason = data.get("reason")
    if not key:
        return jsonify({"error": "'key' is required."}), 400
    row = ProgramLock.query.filter_by(program_key=key).first()
    if not row:
        return jsonify({"error": f"Unknown program '{key}'. It may not have registered yet — reopen the menu and try again."}), 404
    row.locked = locked
    if reason is not None:
        row.reason = reason
    row.locked_by_email = user.get("email") if locked else row.locked_by_email
    row.locked_at = datetime.utcnow() if locked else row.locked_at
    db.session.commit()
    logging.warning(f"[PROGRAM LOCK] '{key}' set to locked={locked} by {user.get('email')}")
    return jsonify({"ok": True, "program": row.to_dict()}), 200


@app.route("/api/admin/program-locks/lock-all", methods=["POST"])
@csrf.exempt
def admin_lock_all_programs():
    """Master kill switch — the SINGLE on/off state for the entire
    platform. Locking sets the platform-wide switch, marks every
    currently-known program row as locked, AND disables every
    PlatformFeatureFlag (the separate curated-feature system used by
    routes wrapped in @requires_feature_flag — loans, insurance, BNPL,
    chargeback automation, PO approval, punchout/EDI, etc). Both
    systems used to drift independently — a program could show
    "unlocked" here while its underlying feature flag stayed off (or
    vice versa). They now always move together: locked means locked,
    unlocked means unlocked, no partial state either way."""
    user, err = _status_admin_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    reason = (data.get("reason") or "").strip() or None
    state = _get_platform_lock_state()
    state.all_locked = True
    state.reason = reason
    state.locked_by_email = user.get("email")
    state.locked_at = datetime.utcnow()
    now = datetime.utcnow()
    ProgramLock.query.update({
        ProgramLock.locked: True,
        ProgramLock.reason: reason,
        ProgramLock.locked_by_email: user.get("email"),
        ProgramLock.locked_at: now,
    })
    PlatformFeatureFlag.query.update({
        PlatformFeatureFlag.enabled: False,
    })
    db.session.commit()
    logging.warning(f"[PROGRAM LOCK] ALL PROGRAMS + ALL FEATURE FLAGS LOCKED by {user.get('email')} — reason: {reason}")
    return jsonify({"ok": True, "all_locked": True}), 200


@app.route("/api/admin/program-locks/unlock-all", methods=["POST"])
@csrf.exempt
def admin_unlock_all_programs():
    """Unlock side of the single master switch — see admin_lock_all_programs
    above. Re-enables every PlatformFeatureFlag along with every
    ProgramLock row, so 'unlock all' really does mean everything, with
    no separate curated list staying quietly disabled."""
    user, err = _status_admin_or_401()
    if err: return err
    state = _get_platform_lock_state()
    state.all_locked = False
    state.reason = None
    state.locked_by_email = None
    state.locked_at = None
    ProgramLock.query.update({ProgramLock.locked: False})
    PlatformFeatureFlag.query.update({
        PlatformFeatureFlag.enabled: True,
    })
    db.session.commit()
    logging.warning(f"[PROGRAM LOCK] ALL PROGRAMS + ALL FEATURE FLAGS UNLOCKED by {user.get('email')}")
    return jsonify({"ok": True, "all_locked": False}), 200


