@app.route("/api/status/incidents/<int:incident_id>", methods=["PATCH"])
@csrf.exempt
def status_incident_update(incident_id):
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _status_admin_or_401()
    if err: return err
    incident = StatusIncident.query.get(incident_id)
    if not incident:
        return jsonify({"error": "Incident not found."}), 404
    data = request.get_json(silent=True) or {}
    if "title" in data: incident.title = (data.get("title") or incident.title).strip()
    if "message" in data: incident.message = (data.get("message") or "").strip() or None
    if data.get("severity") in ("minor", "major", "critical"): incident.severity = data["severity"]
    if data.get("status") in ("investigating", "identified", "monitoring", "resolved"):
        incident.status = data["status"]
        if data["status"] == "resolved" and not incident.resolved_at:
            incident.resolved_at = datetime.utcnow()
    db.session.commit()
    return jsonify({"ok": True, "incident": incident.to_dict()}), 200


@app.route("/api/status/summary", methods=["GET"])
def status_summary():
    """Public, no-auth JSON — what the /status HTML page (and any
    third-party monitor that wants JSON instead of HTML) reads from."""
    from sqlalchemy import text as _sa_text_status
    db_ok = True
    try:
        db.session.execute(_sa_text_status("SELECT 1"))
    except Exception:
        db_ok = False

    active = StatusIncident.query.filter(StatusIncident.status != "resolved").order_by(StatusIncident.created_at.desc()).all()
    resolved = StatusIncident.query.filter_by(status="resolved").order_by(StatusIncident.resolved_at.desc()).limit(10).all()

    if not db_ok:
        overall = "major_outage"
    elif any(i.severity == "critical" for i in active):
        overall = "major_outage"
    elif active:
        overall = "degraded_performance"
    else:
        overall = "operational"

    return jsonify({
        "overall_status": overall,
        "database": "operational" if db_ok else "outage",
        "checked_at": datetime.utcnow().isoformat() + "Z",
        "active_incidents": [i.to_dict() for i in active],
        "recent_resolved": [i.to_dict() for i in resolved],
    }), 200


