def _generate_smile_api_key(label: str = "default", tier: str = "free") -> dict:
    key_id     = f"sa-{secrets.token_urlsafe(32)}"
    key_hash   = hashlib.sha256(key_id.encode()).hexdigest()
    created_at = datetime.utcnow().isoformat()
    limits     = TIER_LIMITS.get(tier, TIER_LIMITS["free"])

    record = ApiKeyRecord(
        key_id           = key_id,
        key_hash         = key_hash,
        label            = label,
        tier             = tier,
        created_at       = created_at,
        active           = True,
        usage_today      = 0,
        usage_reset      = created_at[:10],
        requests_per_day = limits["requests_per_day"],
        max_tokens       = limits["max_tokens"],
    )
    try:
        db.session.add(record)
        db.session.commit()
        logging.info(f"[KEY] Minted {tier} key: {key_id[:24]}… label='{label}'")
    except Exception as e:
        db.session.rollback()
        logging.error(f"Failed to save API key to DB: {e}")
    return record.to_dict()


def _validate_smile_api_key(key: str) -> tuple:
    if not key:
        return False, None, "No API key provided."
    try:
        record = ApiKeyRecord.query.filter_by(key_id=key).first()
    except Exception as e:
        logging.error(f"DB key lookup failed: {e}")
        return False, None, "Database error."

    if not record:
        return False, None, "Key not found."
    if not record.active:
        return False, None, "Key has been revoked."

    today = datetime.utcnow().strftime("%Y-%m-%d")
    if record.usage_reset != today:
        record.usage_today = 0
        record.usage_reset = today

    if record.usage_today >= record.requests_per_day:
        return False, None, f"Daily limit of {record.requests_per_day} reached."

    record.usage_today += 1
    try:
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        logging.error(f"Failed to update key usage: {e}")

    return True, record.to_dict(), "ok"


def _boot_internal_key():
    if not SMILE_AGAIN_ACTIVE_KEY:
        return
    try:
        existing = ApiKeyRecord.query.filter_by(
            key_id=SMILE_AGAIN_ACTIVE_KEY
        ).first()
        if not existing:
            record = ApiKeyRecord(
                key_id           = SMILE_AGAIN_ACTIVE_KEY,
                key_hash         = hashlib.sha256(
                                       SMILE_AGAIN_ACTIVE_KEY.encode()
                                   ).hexdigest(),
                label            = "internal-app",
                tier             = "internal",
                created_at       = datetime.utcnow().isoformat(),
                active           = True,
                usage_today      = 0,
                usage_reset      = datetime.utcnow().strftime("%Y-%m-%d"),
                requests_per_day = 99999,
                max_tokens       = 65536,
            )
            db.session.add(record)
            db.session.commit()
            logging.info("Internal key registered — app is self-powered.")
        else:
            logging.info("Internal key already in database.")
    except Exception as e:
        db.session.rollback()
        logging.error(f"Failed to boot internal key: {e}")


with app.app_context():
    _boot_internal_key()


