def _db_get_history(session_id: str, channel: str = "web") -> list:
    try:
        rows = (
            ChatLog.query
            .filter_by(session_id=session_id, channel=channel)
            .order_by(ChatLog.id.asc())
            .limit(MAX_HISTORY_TURNS * 2)
            .all()
        )
        return [r.to_dict() for r in rows]
    except Exception as e:
        logging.error(f"DB history fetch failed: {e}")
        return []


def _db_save_turn(
    session_id: str, channel: str, role: str, content: str,
    user_id=None, content_type: str = "chat", extra: dict = None,
    owner_user_id=None,
) -> None:
    try:
        entry = ChatLog(
            session_id    = session_id,
            channel       = channel,
            role          = role,
            content       = content,
            owner_user_id = owner_user_id,
            created_at    = datetime.utcnow(),
        )
        db.session.add(entry)
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        logging.error(f"DB save turn failed: {e}")

    # Permanent archive — only written when we actually know who the user
    # is. This row is NEVER touched by _db_clear_history or any cleanup
    # job; only /api/admin/memory/wipe (admin-only) can remove it.
    if user_id:
        try:
            mem = UserMemory(
                user_id=user_id, role=role, content_type=content_type,
                content=content,
                extra_json=json.dumps(extra) if extra else None,
            )
            db.session.add(mem)
            db.session.commit()
        except Exception as e:
            db.session.rollback()
            logging.error(f"UserMemory archive failed: {e}")


def save_to_memory(user_id, role: str, content: str, content_type: str = "chat", extra: dict = None) -> None:
    """Standalone version of the archive-write above, for anything that
    isn't going through _db_save_turn (generated docs, code, bookings...)."""
    if not user_id:
        return
    try:
        mem = UserMemory(
            user_id=user_id, role=role, content_type=content_type,
            content=content,
            extra_json=json.dumps(extra) if extra else None,
        )
        db.session.add(mem)
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        logging.error(f"UserMemory archive failed: {e}")


def _db_clear_history(session_id: str, channel: str = "web") -> None:
    try:
        ChatLog.query.filter_by(
            session_id=session_id, channel=channel
        ).delete()
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        logging.error(f"DB clear history failed: {e}")


