def _require_master_key(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        if request.headers.get("X-Master-Key", "") != SMILE_AGAIN_MASTER_KEY:
            return jsonify({"error": "Unauthorized."}), 401
        return f(*args, **kwargs)
    return decorated

def _require_smile_api_key(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        key   = request.headers.get("X-Smile-API-Key", "")
        valid, record, reason = _validate_smile_api_key(key)
        if not valid:
            return jsonify({"error": reason}), 403
        request.smile_api_record = record
        # MEGA PACK feature 3: partner API usage analytics — log every
        # authenticated partner call (best-effort, never blocks the request).
        try:
            _log_partner_api_usage(record, request.path, request.method)
        except Exception as _mega_log_err:
            logging.warning(f"[PARTNER API USAGE LOG] skipped: {_mega_log_err}")
        return f(*args, **kwargs)
    return decorated

def _issue_auth_token(user) -> str:
    """Mints a Bearer token AND persists it to auth_session_tokens (not
    just the in-memory user_store cache), so it keeps working no matter
    which worker process serves a later request."""
    token = secrets.token_urlsafe(64)
    user_store[token] = {"id": user.id, "name": user.name, "email": user.email, "plan": user.plan,
                          "country_code": user.country_code}
    try:
        db.session.add(AuthSessionToken(token=token, user_id=user.id))
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        logging.error(f"[AUTH TOKEN PERSIST ERROR] user={user.id}: {e}")
    return token


def _get_current_user():
    auth_header = request.headers.get("Authorization", "")
    if auth_header.startswith("Bearer "):
        token = auth_header[7:].strip()
        if token in user_store:
            return user_store[token]
        # Not in this worker's in-memory cache — check the durable store
        # before giving up. This is the actual fix for genuinely
        # signed-in users occasionally hitting "Login required."
        try:
            row = AuthSessionToken.query.get(token)
            if row:
                u = UserAccount.query.get(row.user_id)
                if u and u.is_active:
                    cached = {"id": u.id, "name": u.name, "email": u.email, "plan": u.plan,
                              "country_code": u.country_code}
                    user_store[token] = cached  # warm this worker's cache
                    row.last_used_at = datetime.utcnow()
                    try:
                        db.session.commit()
                    except Exception:
                        db.session.rollback()
                    return cached
        except Exception as e:
            logging.error(f"[AUTH TOKEN LOOKUP ERROR] {e}")
    # Fall back to the session-cookie path directly — NOT via
    # _current_user_id(), which itself delegates back to this function.
    # Calling that here is what caused the mutual infinite recursion
    # (_get_current_user -> _current_user_id -> _get_current_user ->
    # ...) for every request that didn't resolve via the Bearer-token
    # branch above (i.e. any cookie-session request).
    user_id = session.get("user_id")
    if user_id:
        try:
            u = UserAccount.query.get(user_id)
            if u:
                return {"id": u.id, "name": u.name, "email": u.email, "plan": u.plan,
                        "country_code": u.country_code}
        except Exception:
            pass
    return None


def _current_user_id():
    """Resolves the signed-in user's id from either a Bearer token
    (mobile/webview clients, which is how this app's frontend actually
    authenticates via authHeaders()) or a session cookie, by delegating
    to _get_current_user(). Many older routes below were written to
    check session.get("user_id") directly, which only recognizes the
    cookie path — a genuinely signed-in user calling those routes with
    only a Bearer token would incorrectly get "Login required.". Use
    this helper (or _get_current_user() directly) in any new route."""
    u = _get_current_user()
    return u["id"] if u else None


def _effective_business_id(user_id=None):
    """STAGE 154: resolves which BUSINESS's data a logged-in user should
    see — not necessarily their own account id. A business owner (the
    default, no team membership) sees their own data, same as always.
    An active staff member (TeamMember.status == 'active') sees their
    owner's data instead. Use this instead of _current_user_id() when
    scoping a query to 'this business'; use _current_user_id() (or
    _get_current_user()) when you specifically need the literal logged-
    in account — e.g. for their own name, email, or personal settings.
    See the STAGE 154 comment above TeamMember for what is and isn't
    wired to this yet."""
    uid = user_id if user_id is not None else _current_user_id()
    if not uid:
        return None
    membership = TeamMember.query.filter_by(member_user_id=uid, status="active").first()
    return membership.owner_user_id if membership else uid


# ===========================================================
# BYOK — CREDENTIAL RESOLUTION
# Every user can plug in their own paid API keys for AI providers,
# Twilio, WhatsApp Business, Google Cloud Storage, Stripe, Flutterwave,
# and more. These helpers fetch a user's own key when they have one
# configured and active, otherwise transparently fall back to the
# platform's shared key so nothing breaks for users on the free/Pro plan.
# ===========================================================

def get_user_credentials(user_id, provider: str) -> dict:
    """Return the decrypted credentials dict a user saved for `provider`,
    or {} if they have none configured (or it's turned off)."""
    if not user_id or provider not in BYOK_PROVIDERS:
        return {}
    try:
        row = UserIntegration.query.filter_by(
            user_id=user_id, provider=provider, active=True
        ).first()
        if not row:
            return {}
        return decrypt_secret_blob(row.credentials_encrypted)
    except Exception as e:
        logging.error(f"[BYOK LOOKUP ERROR] provider={provider} user={user_id}: {e}")
        return {}


def get_effective_credential(user_id, provider: str, field: str, platform_fallback=None):
    """The core BYOK rule: a user's own key always wins over the platform key
    when they have one configured. Otherwise, use the platform's key so the
    feature still works for everyone else."""
    user_creds = get_user_credentials(user_id, provider)
    if user_creds and user_creds.get(field):
        return user_creds[field]
    return platform_fallback


def gate_ai_usage(user, feature_key: str, byok_provider: str = None):
    """Call as the FIRST line inside any route that costs you real money.
    Returns None if allowed to proceed. Returns a (response, status) tuple
    if it should be blocked — `return` it immediately and do nothing else,
    so no cost is incurred. One straight-line call, not a decorator —
    nothing to stack."""
    if _ai_killswitch_on():
        return jsonify({"error": "This feature is temporarily paused. Please try again shortly."}), 503

    if not user:
        return jsonify({"error": "Please log in to use this feature."}), 401

    is_byok = bool(byok_provider and get_user_credentials(user["id"], byok_provider))
    if is_byok:
        return None  # their key, their money — no metering

    day_key = _current_day_key()
    try:
        guard = PlatformSpendGuard.query.filter_by(day_key=day_key).first()
        if not guard:
            guard = PlatformSpendGuard(day_key=day_key, call_count=0)
            db.session.add(guard)
            db.session.flush()
        if guard.call_count >= PLATFORM_DAILY_CALL_CAP:
            return jsonify({"error": "This feature has hit today's platform-wide cap. Try again tomorrow."}), 429
        guard.call_count += 1
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        logging.error(f"[SPEND GUARD ERROR] {e}")
        return jsonify({"error": "Temporarily unavailable, please try again."}), 503  # fail CLOSED

    limits = FEATURE_LIMITS.get(feature_key)
    if limits is None:
        return None
    # Resolve org plan too (see _effective_plan_for_user) — otherwise a
    # team on a paid workspace plan would still be capped at "free"
    # limits for anything metered here, since UserAccount.plan alone
    # never reflects an org-level subscription.
    plan  = _effective_plan_for_user(user["id"], user.get("plan"))
    limit = limits.get(plan, limits.get("free", 0))
    if limit is None:
        return None

    period_key = _current_period_key()
    try:
        row = FeatureUsage.query.filter_by(user_id=user["id"], feature_key=feature_key, period_key=period_key).first()
        if not row:
            row = FeatureUsage(user_id=user["id"], feature_key=feature_key, period_key=period_key, count=0)
            db.session.add(row)
            db.session.flush()
        if row.count >= limit:
            plan_idx = PLAN_ORDER.index(plan) if plan in PLAN_ORDER else 0
            next_plan = PLAN_ORDER[min(plan_idx + 1, len(PLAN_ORDER) - 1)]
            body = {"error": f"You've used all {limit} {feature_key.replace('_', ' ')} calls in your {plan} plan this month."}
            body.update(_upgrade_cta(next_plan))
            return jsonify(body), 402
        row.count += 1
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        logging.error(f"[USAGE GATE ERROR] feature={feature_key} user={user['id']}: {e}")
        return jsonify({"error": "Temporarily unavailable, please try again."}), 503

    return None


def _autoprovision_twilio_verify_service(credentials: dict) -> dict:
    """If a user is saving Twilio Verify credentials with an account_sid +
    auth_token but no service_sid, create a Verify Service for them on the
    spot so they don't have to go create one manually in the Twilio console
    first. Mutates and returns the credentials dict."""
    account_sid = (credentials or {}).get("account_sid", "")
    auth_token  = (credentials or {}).get("auth_token", "")
    service_sid = (credentials or {}).get("service_sid", "")
    if account_sid and auth_token and not service_sid:
        try:
            client  = Client(account_sid, auth_token)
            service = client.verify.v2.services.create(friendly_name="Connect It")
            credentials["service_sid"] = service.sid
            logging.info(f"[TWILIO VERIFY] auto-created service {service.sid} for account {account_sid}")
        except Exception as e:
            logging.error(f"[TWILIO VERIFY AUTO-PROVISION ERROR] {e}")
            raise ValueError(
                "Couldn't auto-create a Twilio Verify Service with those credentials. "
                "Double-check your Account SID and Auth Token, or paste your own "
                "Verify Service SID instead."
            )
    return credentials


def _autoprovision_telegram_webhook(user_id, credentials: dict) -> dict:
    """If a user is saving a Telegram bot token, validate it, generate a
    private webhook path for them, and register it with Telegram —
    same 'do the setup step for them' pattern as Twilio Verify above."""
    bot_token = (credentials or {}).get("bot_token", "").strip()
    if not bot_token:
        return credentials
    try:
        me = requests.get(f"https://api.telegram.org/bot{bot_token}/getMe", timeout=10).json()
        if not me.get("ok"):
            raise ValueError(me.get("description", "Invalid bot token."))
        credentials["bot_username"] = (me.get("result") or {}).get("username", "")
        webhook_secret = credentials.get("webhook_secret") or secrets.token_urlsafe(24)
        credentials["webhook_secret"] = webhook_secret
        base_url = (os.environ.get("PUBLIC_BASE_URL") or request.host_url).rstrip("/")
        set_resp = requests.get(
            f"https://api.telegram.org/bot{bot_token}/setWebhook",
            params={"url": f"{base_url}/telegram/webhook/{webhook_secret}"},
            timeout=10,
        ).json()
        if not set_resp.get("ok"):
            raise ValueError(set_resp.get("description", "Could not register the Telegram webhook."))
        logging.info(f"[TELEGRAM] webhook registered for user={user_id} bot=@{credentials['bot_username']}")
    except Exception as e:
        logging.error(f"[TELEGRAM AUTO-PROVISION ERROR] {e}")
        raise ValueError(f"Couldn't set up that Telegram bot: {e}")
    return credentials


def save_user_integration(user_id, provider: str, credentials: dict) -> "UserIntegration":
    if provider not in BYOK_PROVIDERS:
        raise ValueError(f"Unknown provider: {provider}")
    if provider == "twilio_verify":
        credentials = _autoprovision_twilio_verify_service(credentials)
    if provider == "telegram_bot":
        credentials = _autoprovision_telegram_webhook(user_id, credentials)
    if provider in ("msteams_bot", "viber_bot", "rcs_business", "apple_messages"):
        credentials = _autoprovision_inbox_channel(user_id, provider, credentials)
    row = UserIntegration.query.filter_by(user_id=user_id, provider=provider).first()
    encrypted = encrypt_secret_blob(credentials)
    if row:
        row.credentials_encrypted = encrypted
        row.active = True
        row.updated_at = datetime.utcnow()
    else:
        row = UserIntegration(
            user_id=user_id, provider=provider,
            credentials_encrypted=encrypted, active=True,
        )
        db.session.add(row)
    db.session.commit()
    return row


# ===========================================================
# NEW BLOCK: GOOGLE SERVICE-ACCOUNT HELPERS
# Sheets, Drive, Vision, Translate, Calendar+Meet, and Maps —
# every one of these skips the Google OAuth consent-screen review
# entirely. Either a platform-wide service account (env vars above)
# or a user's own service-account JSON (BYOK) is used.
# ===========================================================

_SHEETS_SCOPES    = ["https://www.googleapis.com/auth/spreadsheets", "https://www.googleapis.com/auth/drive"]
_CALENDAR_SCOPES  = ["https://www.googleapis.com/auth/calendar"]


def _load_service_account_info(raw_json: str) -> dict | None:
    if not raw_json:
        return None
    try:
        return json.loads(raw_json) if isinstance(raw_json, str) else raw_json
    except Exception as e:
        logging.error(f"[GOOGLE SA ERROR] could not parse service-account JSON: {e}")
        return None


def _get_google_credentials(user_id, provider: str, platform_json: str, scopes: list):
    """BYOK-aware: a user's own service-account JSON (saved under
    provider='google_sheets' / 'google_vision' / etc, field
    'service_account_json') wins over the platform's shared one."""
    if not GSPREAD_AVAILABLE:
        return None
    raw = get_effective_credential(user_id, provider, "service_account_json", platform_json)
    info = _load_service_account_info(raw)
    if not info:
        return None
    try:
        return Credentials.from_service_account_info(info, scopes=scopes)
    except Exception as e:
        logging.error(f"[GOOGLE SA ERROR] provider={provider} user={user_id}: {e}")
        return None


# --- Vertex AI: Lyria music generation (lyria-002) -----------------------
# Requires a Google Cloud project with Vertex AI enabled and billing on
# (gated access on Google's side, not something a plain API key unlocks).
# Auth is a service account with the "aiplatform.user" role or similar,
# same BYOK JSON pattern as the rest of this file, minted into a short-
# lived OAuth access token per request (Vertex AI predict doesn't take a
# static API key).
_VERTEX_AI_SCOPES = ["https://www.googleapis.com/auth/cloud-platform"]


def generate_lyria_music(user_id, prompt: str, negative_prompt: str = "", seed: int | None = None,
                          sample_count: int = 1) -> dict:
    """Calls Vertex AI's lyria-002:predict endpoint. Returns
    {"ok": True, "clips": [{"audio_base64": "...", "mime_type": "audio/wav"}, ...]}
    or {"ok": False, "error": "..."}. Each clip is a 30-second 48kHz WAV,
    base64-encoded, per Google's Lyria API contract."""
    if not GOOGLE_SIGNIN_AVAILABLE:
        return {"ok": False, "error": "google-auth is not installed. Run: pip install google-auth"}
    creds = _get_google_credentials(user_id, "vertex_ai_lyria", "", _VERTEX_AI_SCOPES)
    if not creds:
        return {"ok": False, "error": "Vertex AI is not configured. Add your service-account JSON, "
                                       "Cloud project ID, and region under Integrations \u2192 Vertex AI Lyria."}
    project_id = get_effective_credential(user_id, "vertex_ai_lyria", "project_id", "")
    location   = get_effective_credential(user_id, "vertex_ai_lyria", "location", "") or "us-central1"
    if not project_id:
        return {"ok": False, "error": "Missing Google Cloud project_id for Vertex AI Lyria."}
    try:
        creds.refresh(google_auth_requests.Request())
    except Exception as e:
        logging.error(f"[VERTEX AI AUTH ERROR] user={user_id}: {e}")
        return {"ok": False, "error": "Could not authenticate with Google Cloud — check the service account JSON."}

    instance = {"prompt": prompt[:2000]}
    if negative_prompt:
        instance["negative_prompt"] = negative_prompt[:1000]
    if seed is not None:
        instance["seed"] = int(seed)
    params = {} if seed is not None else {"sample_count": max(1, min(int(sample_count or 1), 4))}

    url = (f"https://{location}-aiplatform.googleapis.com/v1/projects/{project_id}"
           f"/locations/{location}/publishers/google/models/lyria-002:predict")
    try:
        resp = requests.post(
            url,
            headers={"Authorization": f"Bearer {creds.token}", "Content-Type": "application/json"},
            json={"instances": [instance], "parameters": params},
            timeout=60,
        )
    except requests.exceptions.RequestException as e:
        logging.error(f"[LYRIA REQUEST ERROR] user={user_id}: {e}")
        return {"ok": False, "error": "Could not reach Vertex AI. Try again shortly."}

    if resp.status_code != 200:
        logging.error(f"[LYRIA API ERROR] user={user_id}: {resp.status_code} {resp.text[:500]}")
        try:
            msg = resp.json().get("error", {}).get("message", resp.text[:300])
        except Exception:
            msg = resp.text[:300]
        return {"ok": False, "error": f"Vertex AI returned an error: {msg}"}

    predictions = (resp.json() or {}).get("predictions", [])
    clips = [{"audio_base64": p.get("audioContent"), "mime_type": p.get("mimeType", "audio/wav")}
              for p in predictions if p.get("audioContent")]
    if not clips:
        return {"ok": False, "error": "Vertex AI returned no audio — the prompt may have been blocked by safety filters."}
    return {"ok": True, "clips": clips}


# --- Google Sheets / Drive sync -----------------------------------------

def get_or_create_user_sheet(user_id, sheet_name: str, headers: list, share_with_email: str | None = None):
    """Returns (worksheet, spreadsheet_url) for a user's named sheet,
    creating it (and sharing it back to the user's email via Drive) the
    first time it's needed."""
    if not GSPREAD_AVAILABLE:
        raise RuntimeError("gspread is not installed. Run: pip install gspread google-auth")

    creds = _get_google_credentials(user_id, "google_sheets", GOOGLE_SHEETS_CREDS, _SHEETS_SCOPES)
    if not creds:
        raise RuntimeError("Google Sheets is not configured. Set GOOGLE_SHEETS_CREDS_JSON or add your own service-account JSON in Integrations.")

    gc = gspread.authorize(creds)

    target = SheetSyncTarget.query.filter_by(user_id=user_id, sheet_name=sheet_name).first()
    if target:
        sh = gc.open_by_key(target.spreadsheet_id)
    else:
        sh = gc.create(f"Connect It — {sheet_name}")
        if share_with_email:
            try:
                sh.share(share_with_email, perm_type="user", role="writer")
            except Exception as e:
                logging.warning(f"[SHEETS SHARE WARNING] could not share sheet with {share_with_email}: {e}")
        target = SheetSyncTarget(
            user_id=user_id, sheet_name=sheet_name,
            spreadsheet_id=sh.id, sheet_url=sh.url,
        )
        db.session.add(target)
        db.session.commit()

    worksheet = sh.sheet1
    if headers and worksheet.row_count and not worksheet.get_all_values():
        worksheet.append_row(headers)
    return worksheet, sh.url


def sync_row_to_sheet(user_id, sheet_name: str, headers: list, row_values: list, share_with_email: str | None = None) -> str:
    """Appends one row to the user's named Google Sheet, creating it if
    needed. Returns the spreadsheet's shareable URL."""
    worksheet, url = get_or_create_user_sheet(user_id, sheet_name, headers, share_with_email)
    worksheet.append_row([str(v) if v is not None else "" for v in row_values])
    return url


# --- Google Cloud Vision (receipt / invoice OCR) -------------------------

def ocr_image_bytes(image_bytes: bytes, user_id=None) -> dict:
    """Runs Google Vision OCR on raw image bytes. Returns
    {"ok": True, "text": "..."} or {"ok": False, "error": "..."}."""
    if not GVISION_AVAILABLE:
        return {"ok": False, "error": "google-cloud-vision is not installed. Run: pip install google-cloud-vision"}

    raw = get_effective_credential(user_id, "google_vision", "service_account_json", GOOGLE_VISION_CREDENTIALS_JSON)
    info = _load_service_account_info(raw)
    if not info:
        return {"ok": False, "error": "Google Vision is not configured. Set GOOGLE_VISION_CREDENTIALS_JSON (or GOOGLE_SHEETS_CREDS_JSON)."}

    try:
        from google.oauth2.service_account import Credentials as VisionCredentials
        creds = VisionCredentials.from_service_account_info(info)
        client = gvision.ImageAnnotatorClient(credentials=creds)
        image = gvision.Image(content=image_bytes)
        response = client.document_text_detection(image=image)
        if response.error.message:
            return {"ok": False, "error": response.error.message}
        text = response.full_text_annotation.text if response.full_text_annotation else ""
        return {"ok": True, "text": text}
    except Exception as e:
        logging.error(f"[VISION OCR ERROR] user={user_id}: {e}")
        return {"ok": False, "error": str(e)}


def parse_receipt_text_with_ai(raw_text: str) -> dict:
    """Hands the raw OCR text to the existing AI provider chain to turn
    it into structured {vendor, date, line_items, tax, total}. Falls back
    to returning the raw text if no AI provider is configured."""
    prompt = (
        "Extract structured data from this receipt/invoice OCR text. "
        "Return ONLY valid JSON with keys: vendor, date, line_items "
        "(array of {description, amount}), tax, total, currency. "
        "If a field is missing, use null.\n\nOCR TEXT:\n" + raw_text
    )
    try:
        reply, _ = generate_ai_reply(prompt, [], user_id=None, system_prompt=ANALYSIS_SYSTEM_PROMPT)
        cleaned = reply.strip().strip("`")
        if cleaned.lower().startswith("json"):
            cleaned = cleaned[4:].strip()
        return json.loads(cleaned)
    except Exception as e:
        logging.warning(f"[RECEIPT PARSE WARNING] falling back to raw text: {e}")
        return {"vendor": None, "date": None, "line_items": [], "tax": None, "total": None, "raw_text": raw_text}


# --- Google Cloud Translate (real Google NMT, not the AI-chain version) --

def google_translate_text(text: str, target_lang: str, source_lang: str | None = None, user_id=None) -> dict:
    if not GTRANSLATE_AVAILABLE:
        return {"ok": False, "error": "google-cloud-translate is not installed. Run: pip install google-cloud-translate"}

    raw = get_effective_credential(user_id, "google_translate", "service_account_json", GOOGLE_TRANSLATE_CREDENTIALS_JSON)
    info = _load_service_account_info(raw)
    if not info:
        return {"ok": False, "error": "Google Translate is not configured. Set GOOGLE_TRANSLATE_CREDENTIALS_JSON (or GOOGLE_SHEETS_CREDS_JSON)."}

    try:
        from google.oauth2.service_account import Credentials as TranslateCredentials
        creds = TranslateCredentials.from_service_account_info(info)
        client = gtranslate.Client(credentials=creds)
        result = client.translate(text, target_language=target_lang, source_language=source_lang)
        return {
            "ok": True,
            "translated_text": result.get("translatedText"),
            "detected_source_language": result.get("detectedSourceLanguage", source_lang),
        }
    except Exception as e:
        logging.error(f"[TRANSLATE ERROR] user={user_id}: {e}")
        return {"ok": False, "error": str(e)}


# --- Google Maps: Geocoding + Distance Matrix (plain API key, no OAuth) --

def geocode_address(address: str, user_id=None) -> dict:
    api_key = get_effective_credential(user_id, "google_maps", "api_key", GOOGLE_MAPS_API_KEY)
    if not api_key:
        return {"ok": False, "error": "Google Maps is not configured. Set GOOGLE_MAPS_API_KEY."}
    try:
        r = requests.get(
            "https://maps.googleapis.com/maps/api/geocode/json",
            params={"address": address, "key": api_key},
            timeout=10,
        )
        body = r.json()
        if body.get("status") != "OK" or not body.get("results"):
            return {"ok": False, "error": body.get("status", "Geocoding failed"), "raw": body}
        top = body["results"][0]
        loc = top["geometry"]["location"]
        return {
            "ok": True,
            "formatted_address": top.get("formatted_address"),
            "lat": loc["lat"],
            "lng": loc["lng"],
            "place_id": top.get("place_id"),
        }
    except Exception as e:
        logging.error(f"[GEOCODE ERROR] {e}")
        return {"ok": False, "error": str(e)}


def reverse_geocode(lat: float, lng: float, user_id=None) -> dict:
    """Turns a lat/lng (from the browser's Geolocation API) into a city +
    country — real Google reverse geocoding, no IP-based guessing. Falls
    back to free OpenStreetMap Nominatim (no API key needed) if Google
    Maps isn't configured for this user, instead of failing outright."""
    api_key = get_effective_credential(user_id, "google_maps", "api_key", GOOGLE_MAPS_API_KEY)
    if not api_key:
        osm_result = osm_reverse_geocode(lat, lng)
        if osm_result.get("ok"):
            addr = osm_result.get("address", {})
            return {
                "ok": True,
                "city": addr.get("city") or addr.get("town") or addr.get("village"),
                "country": addr.get("country"),
                "formatted_address": osm_result.get("display_name"),
                "source": "openstreetmap",
            }
        return {"ok": False, "error": "Google Maps is not configured. Set GOOGLE_MAPS_API_KEY."}
    try:
        r = requests.get(
            "https://maps.googleapis.com/maps/api/geocode/json",
            params={"latlng": f"{lat},{lng}", "key": api_key},
            timeout=10,
        )
        body = r.json()
        if body.get("status") != "OK" or not body.get("results"):
            return {"ok": False, "error": body.get("status", "Reverse geocoding failed"), "raw": body}

        city = None
        country = None
        for result in body["results"]:
            for comp in result.get("address_components", []):
                types = comp.get("types", [])
                if not city and ("locality" in types or "postal_town" in types or "administrative_area_level_2" in types):
                    city = comp.get("long_name")
                if not country and "country" in types:
                    country = comp.get("long_name")
            if city and country:
                break

        return {
            "ok": True,
            "city": city,
            "country": country,
            "formatted_address": body["results"][0].get("formatted_address"),
        }
    except Exception as e:
        logging.error(f"[REVERSE GEOCODE ERROR] {e}")
        return {"ok": False, "error": str(e)}


def ip_geolocate(ip_address: str | None = None) -> dict:
    """Fallback location lookup by IP address — no browser permission
    prompt, no Google API key needed. Used when the browser's Geolocation
    API is unavailable, blocked (common inside embedded webviews/iframes),
    or the user declines the permission prompt."""
    try:
        target = ip_address or ""
        # Private/local addresses can't be geolocated — this is expected
        # during local testing, not a real failure.
        if target in ("127.0.0.1", "::1", "localhost") or target.startswith(("10.", "192.168.", "172.")):
            return {"ok": False, "error": "Local/private IP address — cannot geolocate."}

        r = requests.get(
            f"http://ip-api.com/json/{target}",
            params={"fields": "status,message,country,city"},
            timeout=6,
        )
        body = r.json()
        if body.get("status") != "success":
            return {"ok": False, "error": body.get("message", "IP lookup failed")}
        return {"ok": True, "city": body.get("city"), "country": body.get("country")}
    except Exception as e:
        logging.error(f"[IP GEOLOCATE ERROR] {e}")
        return {"ok": False, "error": str(e)}


