def broadcast_to_telegram(text: str) -> dict:
    """Posts to a public Telegram channel via a bot — completely free,
    no OAuth, just a bot token from @BotFather."""
    if not TELEGRAM_BOT_TOKEN or not TELEGRAM_CHANNEL_ID:
        return {"ok": False, "error": "Telegram is not configured. Set TELEGRAM_BOT_TOKEN and TELEGRAM_CHANNEL_ID."}
    try:
        r = requests.post(
            f"https://api.telegram.org/bot{TELEGRAM_BOT_TOKEN}/sendMessage",
            json={"chat_id": TELEGRAM_CHANNEL_ID, "text": text, "parse_mode": "Markdown"},
            timeout=10,
        )
        body = r.json()
        if not body.get("ok"):
            return {"ok": False, "error": body.get("description", "Telegram send failed")}
        return {"ok": True, "message_id": body.get("result", {}).get("message_id")}
    except Exception as e:
        logging.error(f"[TELEGRAM BROADCAST ERROR] {e}")
        return {"ok": False, "error": str(e)}


def broadcast_to_discord(text: str, title: str | None = None) -> dict:
    """Posts to a Discord server channel via an incoming webhook — free,
    no bot approval process, just a webhook URL from Server Settings ->
    Integrations -> Webhooks."""
    if not DISCORD_WEBHOOK_URL:
        return {"ok": False, "error": "Discord is not configured. Set DISCORD_WEBHOOK_URL."}
    try:
        payload = {"content": (f"**{title}**\n{text}" if title else text)}
        r = requests.post(DISCORD_WEBHOOK_URL, json=payload, timeout=10)
        if r.status_code not in (200, 204):
            return {"ok": False, "error": f"Discord returned HTTP {r.status_code}"}
        return {"ok": True}
    except Exception as e:
        logging.error(f"[DISCORD BROADCAST ERROR] {e}")
        return {"ok": False, "error": str(e)}


def send_fcm_push(topic: str, title: str, body: str) -> dict:
    """Firebase Cloud Messaging (V1 API) push notification to a topic —
    free, and every device/browser that has the app open and subscribed
    to that topic receives it. Uses a Firebase service account, the same
    pattern as every other Google integration here (no separate OAuth
    consent flow)."""
    if not GCALENDAR_AVAILABLE:
        return {"ok": False, "error": "google-api-python-client / google-auth is not installed."}
    if not FIREBASE_CREDENTIALS_JSON or not FIREBASE_PROJECT_ID:
        return {"ok": False, "error": "Firebase is not configured. Set FIREBASE_CREDENTIALS_JSON and FIREBASE_PROJECT_ID."}
    try:
        info = _load_service_account_info(FIREBASE_CREDENTIALS_JSON)
        if not info:
            return {"ok": False, "error": "Could not parse FIREBASE_CREDENTIALS_JSON."}

        from google.oauth2.service_account import Credentials as FirebaseCredentials
        import google.auth.transport.requests as google_requests_transport

        creds = FirebaseCredentials.from_service_account_info(
            info, scopes=["https://www.googleapis.com/auth/firebase.messaging"]
        )
        creds.refresh(google_requests_transport.Request())

        r = requests.post(
            f"https://fcm.googleapis.com/v1/projects/{FIREBASE_PROJECT_ID}/messages:send",
            headers={"Authorization": f"Bearer {creds.token}", "Content-Type": "application/json"},
            json={"message": {"topic": topic, "notification": {"title": title, "body": body}}},
            timeout=10,
        )
        if r.status_code != 200:
            return {"ok": False, "error": f"FCM returned HTTP {r.status_code}: {r.text[:200]}"}
        return {"ok": True, "response": r.json()}
    except Exception as e:
        logging.error(f"[FCM PUSH ERROR] {e}")
        return {"ok": False, "error": str(e)}


# STAGE 319: PER-USER PUSH NOTIFICATIONS
# send_fcm_push() above only ever shipped one broadcast topic
# ("all_users") — real browser/mobile push for a SPECIFIC user (low
# stock on their own listing, an order update) needs their device
# subscribed to a personal topic instead. Reuses the same Firebase
# project/service account, just adds the per-user topic convention and
# the token-subscription step a device does once after opting in.
def _fcm_user_topic(user_id) -> str:
    return f"user_{user_id}"


def send_user_push(user_id, title, body) -> dict:
    """Thin wrapper — sends to this one user's personal topic instead
    of a platform-wide broadcast."""
    return send_fcm_push(_fcm_user_topic(user_id), title, body)


def _fcm_subscribe_token_to_topic(registration_token: str, topic: str) -> dict:
    """Subscribes one device's FCM registration token to a topic, via
    Google's Instance ID API — same service-account bearer token as
    send_fcm_push above."""
    if not FIREBASE_CREDENTIALS_JSON or not FIREBASE_PROJECT_ID:
        return {"ok": False, "error": "Firebase is not configured on this platform."}
    try:
        info = _load_service_account_info(FIREBASE_CREDENTIALS_JSON)
        if not info:
            return {"ok": False, "error": "Could not parse FIREBASE_CREDENTIALS_JSON."}
        from google.oauth2.service_account import Credentials as FirebaseCredentials
        import google.auth.transport.requests as google_requests_transport
        creds = FirebaseCredentials.from_service_account_info(
            info, scopes=["https://www.googleapis.com/auth/firebase.messaging"])
        creds.refresh(google_requests_transport.Request())
        r = requests.post(
            f"https://iid.googleapis.com/iid/v1/{registration_token}/rel/topics/{topic}",
            headers={"Authorization": f"Bearer {creds.token}", "Content-Type": "application/json",
                     "access_token_auth": "true"},
            timeout=10,
        )
        if r.status_code != 200:
            return {"ok": False, "error": f"Topic subscription failed: HTTP {r.status_code}"}
        return {"ok": True}
    except Exception as e:
        logging.error(f"[FCM TOPIC SUBSCRIBE ERROR] {e}")
        return {"ok": False, "error": str(e)}


@app.route("/api/push/subscribe", methods=["POST"])
@csrf.exempt
def push_subscribe():
    """Body: registration_token (from the browser's Firebase Messaging
    getToken() call). Subscribes this device to the current user's
    personal push topic so send_user_push() can reach it."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    token = (data.get("registration_token") or "").strip()
    if not token:
        return jsonify({"error": "registration_token is required."}), 400
    result = _fcm_subscribe_token_to_topic(token, _fcm_user_topic(user["id"]))
    return jsonify(result), (200 if result.get("ok") else 400)


def generate_hope_content(category: str = "hope", user_id=None) -> dict:
    """AI-generated uplifting content for broadcasting — this is the ONE
    place in the app where the main poetic/narrative SYSTEM_PROMPT persona
    is exactly right, not a bug: hope, positivity, thought-provoking,
    healing, thinking-big, unleash-greatness content all want that voice."""
    prompts = {
        "hope":               "Write a short, powerful message of hope for someone having a hard day. 60-90 words.",
        "positive_vibes":     "Write an uplifting, energizing message radiating positive energy. 60-90 words.",
        "thought_provoking":  "Write a short thought-provoking reflection that challenges how someone sees their situation. 60-90 words.",
        "healing":            "Write a gentle, healing message for someone processing pain or loss. 60-90 words.",
        "thinking_big":       "Write a bold message that pushes someone to think bigger about what's possible for their life. 60-90 words.",
        "unleash_greatness":  "Write a fierce, motivating message that calls someone to unleash their greatness today. 60-90 words.",
    }
    prompt = prompts.get(category, prompts["hope"])
    reply, _ = generate_ai_reply(prompt, [], user_id=user_id)  # default persona — intentional here
    title_prompt = f"Give a short, punchy 4-8 word title for this message, nothing else:\n\n{reply}"
    title_reply, _ = generate_ai_reply(title_prompt, [], user_id=user_id, system_prompt=ANALYSIS_SYSTEM_PROMPT)
    title = _strip_code_fences(title_reply).strip().strip('"')
    return {"title": title or category.replace("_", " ").title(), "content": reply.strip(), "category": category}


def generate_hope_rss_feed(limit: int = 30) -> str:
    """Builds a real RSS 2.0 XML feed of recent broadcast posts — zero
    third-party dependency, works in every RSS reader, completely free."""
    posts = (
        BroadcastPost.query
        .order_by(BroadcastPost.created_at.desc())
        .limit(limit)
        .all()
    )
    items = []
    for p in posts:
        pub_date = p.created_at.strftime("%a, %d %b %Y %H:%M:%S +0000") if p.created_at else ""
        items.append(
            "<item>"
            f"<title>{xml_escape(p.title)}</title>"
            f"<description>{xml_escape(p.content)}</description>"
            f"<category>{xml_escape(p.category)}</category>"
            f"<pubDate>{pub_date}</pubDate>"
            f"<guid isPermaLink=\"false\">connectit-broadcast-{p.id}</guid>"
            "</item>"
        )
    return (
        '<?xml version="1.0" encoding="UTF-8"?>'
        '<rss version="2.0"><channel>'
        "<title>Connect It — Hope &amp; Inspiration</title>"
        "<link>https://connectit.example.com</link>"
        "<description>Hope, positivity, thought-provoking reflections, healing, and thinking-big content from Connect It.</description>"
        + "".join(items) +
        "</channel></rss>"
    )


def get_distance_matrix(origin: str, destination: str, mode: str = "driving", user_id=None) -> dict:
    api_key = get_effective_credential(user_id, "google_maps", "api_key", GOOGLE_MAPS_API_KEY)
    if not api_key:
        return {"ok": False, "error": "Google Maps is not configured. Set GOOGLE_MAPS_API_KEY."}
    try:
        r = requests.get(
            "https://maps.googleapis.com/maps/api/distancematrix/json",
            params={"origins": origin, "destinations": destination, "mode": mode, "key": api_key},
            timeout=10,
        )
        body = r.json()
        rows = body.get("rows", [])
        if body.get("status") != "OK" or not rows or rows[0]["elements"][0]["status"] != "OK":
            return {"ok": False, "error": body.get("status", "Distance Matrix failed"), "raw": body}
        element = rows[0]["elements"][0]
        return {
            "ok": True,
            "distance_text": element["distance"]["text"],
            "distance_meters": element["distance"]["value"],
            "duration_text": element["duration"]["text"],
            "duration_seconds": element["duration"]["value"],
        }
    except Exception as e:
        logging.error(f"[DISTANCE MATRIX ERROR] {e}")
        return {"ok": False, "error": str(e)}


# --- Google Calendar + Meet (service account) ----------------------------

def create_calendar_event(user_id, summary: str, description: str, start_iso: str,
                           end_iso: str, attendee_email: str | None = None,
                           timezone: str = "Africa/Harare") -> dict:
    """Creates an event with an auto-generated Google Meet link on the
    configured calendar. Requires the calendar to be shared with the
    service account's client_email (Settings -> Share with specific
    people -> 'Make changes to events')."""
    if not GCALENDAR_AVAILABLE:
        return {"ok": False, "error": "google-api-python-client is not installed. Run: pip install google-api-python-client"}

    raw = get_effective_credential(user_id, "google_calendar", "service_account_json", GOOGLE_CALENDAR_CREDENTIALS_JSON)
    info = _load_service_account_info(raw)
    if not info:
        return {"ok": False, "error": "Google Calendar is not configured. Set GOOGLE_CALENDAR_CREDENTIALS_JSON (or GOOGLE_SHEETS_CREDS_JSON)."}

    calendar_id = get_effective_credential(user_id, "google_calendar", "calendar_id", GOOGLE_CALENDAR_ID)

    try:
        from google.oauth2.service_account import Credentials as CalendarCredentials
        creds = CalendarCredentials.from_service_account_info(info, scopes=_CALENDAR_SCOPES)
        service = google_api_build("calendar", "v3", credentials=creds, cache_discovery=False)

        event_body = {
            "summary": summary,
            "description": description or "",
            "start": {"dateTime": start_iso, "timeZone": timezone},
            "end":   {"dateTime": end_iso,   "timeZone": timezone},
            "conferenceData": {
                "createRequest": {
                    "requestId": secrets.token_hex(8),
                    "conferenceSolutionKey": {"type": "hangoutsMeet"},
                }
            },
        }
        if attendee_email:
            event_body["attendees"] = [{"email": attendee_email}]

        created = service.events().insert(
            calendarId=calendar_id, body=event_body,
            conferenceDataVersion=1, sendUpdates="all" if attendee_email else "none",
        ).execute()

        meet_link = None
        for ep in created.get("conferenceData", {}).get("entryPoints", []):
            if ep.get("entryPointType") == "video":
                meet_link = ep.get("uri")
                break

        return {"ok": True, "event_id": created.get("id"), "html_link": created.get("htmlLink"), "meet_link": meet_link}
    except Exception as e:
        logging.error(f"[CALENDAR ERROR] user={user_id}: {e}")
        return {"ok": False, "error": str(e)}


def delete_calendar_event(user_id, event_id: str) -> dict:
    """Counterpart to create_calendar_event() above — removes a
    previously-synced event, e.g. when a booking gets cancelled.
    Not calling this after create_calendar_event() succeeded is exactly
    how a cancelled appointment ends up leaving a stale calendar event
    behind, which is the gap this closes."""
    if not GCALENDAR_AVAILABLE:
        return {"ok": False, "error": "google-api-python-client is not installed."}
    if not event_id:
        return {"ok": False, "error": "No event_id to delete."}

    raw = get_effective_credential(user_id, "google_calendar", "service_account_json", GOOGLE_CALENDAR_CREDENTIALS_JSON)
    info = _load_service_account_info(raw)
    if not info:
        return {"ok": False, "error": "Google Calendar is not configured."}
    calendar_id = get_effective_credential(user_id, "google_calendar", "calendar_id", GOOGLE_CALENDAR_ID)

    try:
        from google.oauth2.service_account import Credentials as CalendarCredentials
        creds = CalendarCredentials.from_service_account_info(info, scopes=_CALENDAR_SCOPES)
        service = google_api_build("calendar", "v3", credentials=creds, cache_discovery=False)
        service.events().delete(calendarId=calendar_id, eventId=event_id, sendUpdates="all").execute()
        return {"ok": True}
    except Exception as e:
        # A 410/404 just means it's already gone (e.g. someone deleted
        # it by hand in Google Calendar) — treat that as success rather
        # than a real failure so cancellation flows don't get stuck.
        if "410" in str(e) or "404" in str(e) or "Not Found" in str(e) or "deleted" in str(e).lower():
            return {"ok": True}
        logging.error(f"[CALENDAR DELETE ERROR] user={user_id} event={event_id}: {e}")
        return {"ok": False, "error": str(e)}


# --- Google Drive: generic file backup/upload (service account) ---------

def upload_file_to_drive(user_id, filename: str, file_bytes: bytes, mime_type: str = "application/octet-stream",
                          share_with_email: str | None = None) -> dict:
    """Uploads any file (receipts, exported reports, zips, anything) to
    Drive under the service account, then shares it with the user's email
    so it shows up in their own Drive."""
    if not GCALENDAR_AVAILABLE:
        return {"ok": False, "error": "google-api-python-client is not installed. Run: pip install google-api-python-client"}

    raw = get_effective_credential(user_id, "google_sheets", GOOGLE_SHEETS_CREDS, GOOGLE_SHEETS_CREDS)
    info = _load_service_account_info(raw)
    if not info:
        return {"ok": False, "error": "Google Drive is not configured. Set GOOGLE_SHEETS_CREDS_JSON (reused for Drive)."}

    try:
        from google.oauth2.service_account import Credentials as DriveCredentials
        from googleapiclient.http import MediaIoBaseUpload

        creds = DriveCredentials.from_service_account_info(info, scopes=_SHEETS_SCOPES)
        service = google_api_build("drive", "v3", credentials=creds, cache_discovery=False)

        media = MediaIoBaseUpload(io.BytesIO(file_bytes), mimetype=mime_type, resumable=False)
        created = service.files().create(
            body={"name": filename}, media_body=media, fields="id, webViewLink",
        ).execute()

        if share_with_email:
            try:
                service.permissions().create(
                    fileId=created["id"],
                    body={"type": "user", "role": "writer", "emailAddress": share_with_email},
                    fields="id",
                ).execute()
            except Exception as e:
                logging.warning(f"[DRIVE SHARE WARNING] could not share {filename} with {share_with_email}: {e}")

        return {"ok": True, "file_id": created["id"], "web_view_link": created.get("webViewLink")}
    except Exception as e:
        logging.error(f"[DRIVE UPLOAD ERROR] user={user_id}: {e}")
        return {"ok": False, "error": str(e)}


