_CODE_FENCE_RE = re.compile(r"^```[a-zA-Z0-9_+\-]*\n|\n```$", re.MULTILINE)


def _strip_code_fences(text: str) -> str:
    """Strips a single leading/trailing ``` fence (with optional language
    tag) that models love to wrap code in, without touching fences that
    might legitimately appear inside the code itself."""
    t = text.strip()
    if t.startswith("```"):
        first_newline = t.find("\n")
        if first_newline != -1:
            t = t[first_newline + 1:]
    if t.endswith("```"):
        t = t[: -3]
    return t.strip()


# ════════════════════════════════════════════════════════════
# STAGE 153: AI SEMANTIC SEARCH — engine
# See SemanticIndexEntry above for the storage model. Two entry
# points: semantic_index_upsert() keeps one record's embedding
# current, semantic_search() ranks every indexed record for a
# business against a natural-language query. Both no-op safely
# (return False / an "ok": False result) if no OpenAI key is
# configured, rather than raising — search is a feature that's
# absent without a key, not a hard dependency of the app.
# ════════════════════════════════════════════════════════════

EMBEDDING_MODEL = "text-embedding-3-small"


def _get_embedding(text: str):
    """Returns a list[float] embedding for `text`, or None if embeddings
    aren't configured/available. Truncates input — embedding models have
    a token limit and a short business-record summary never needs more."""
    if not openai_client or not (text or "").strip():
        return None
    try:
        resp = openai_client.embeddings.create(model=EMBEDDING_MODEL, input=text[:8000])
        return resp.data[0].embedding
    except Exception as e:
        logging.error(f"[EMBEDDING ERROR] {e}")
        return None


def _cosine_similarity(a: list, b: list) -> float:
    if not a or not b or len(a) != len(b):
        return 0.0
    dot = sum(x * y for x, y in zip(a, b))
    norm_a = sum(x * x for x in a) ** 0.5
    norm_b = sum(y * y for y in b) ** 0.5
    if norm_a == 0 or norm_b == 0:
        return 0.0
    return dot / (norm_a * norm_b)


def semantic_index_upsert(owner_user_id: int, source_type: str, source_id: int, text: str) -> bool:
    """Computes and stores/updates the embedding for one business record.
    Call this after creating or updating a record you want searchable.
    Returns False (no-op) if embeddings aren't configured."""
    vec = _get_embedding(text)
    if vec is None:
        return False
    entry = SemanticIndexEntry.query.filter_by(
        owner_user_id=owner_user_id, source_type=source_type, source_id=source_id
    ).first()
    if entry:
        entry.text = text
        entry.embedding = json.dumps(vec)
        entry.updated_at = datetime.utcnow()
    else:
        entry = SemanticIndexEntry(
            owner_user_id=owner_user_id, source_type=source_type,
            source_id=source_id, text=text, embedding=json.dumps(vec),
        )
        db.session.add(entry)
    db.session.commit()
    return True


def semantic_search(owner_user_id: int, query: str, top_k: int = 10, source_types: list = None) -> dict:
    """Ranks every indexed record for this business against `query` by
    cosine similarity. Returns {"ok", "error", "results": [{"source_type",
    "source_id", "text", "score"}, ...]}, highest score first."""
    q_vec = _get_embedding(query)
    if q_vec is None:
        return {"ok": False, "error": "AI search isn't configured (no OpenAI API key set).", "results": []}

    qset = SemanticIndexEntry.query.filter_by(owner_user_id=owner_user_id)
    if source_types:
        qset = qset.filter(SemanticIndexEntry.source_type.in_(source_types))

    scored = []
    for entry in qset.all():
        try:
            vec = json.loads(entry.embedding)
        except Exception:
            continue
        scored.append((_cosine_similarity(q_vec, vec), entry))
    scored.sort(key=lambda t: t[0], reverse=True)

    return {
        "ok": True, "error": None,
        "results": [
            {"source_type": e.source_type, "source_id": e.source_id, "text": e.text, "score": round(score, 4)}
            for score, e in scored[:top_k]
        ],
    }


def _semantic_text_for_customer(c) -> str:
    return " | ".join(str(p) for p in [c.name, c.email, c.phone, c.address, c.notes] if p)


def _semantic_text_for_invoice(inv, customer_name: str = None) -> str:
    parts = [f"Invoice {inv.invoice_number}", f"status {inv.status}",
             f"total {inv.total} {inv.currency}", customer_name, inv.notes]
    return " | ".join(str(p) for p in parts if p)


def _semantic_text_for_inventory_item(item) -> str:
    parts = [item.name, item.sku, item.category, f"qty {item.quantity}" if item.quantity is not None else None]
    return " | ".join(str(p) for p in parts if p)


def _semantic_text_for_crm_contact(ct) -> str:
    parts = [ct.name, ct.company, ct.email, ct.phone, f"stage {ct.stage}" if ct.stage else None, ct.notes]
    return " | ".join(str(p) for p in parts if p)


# ════════════════════════════════════════════════════════════
# STAGE 152: CODE VALIDATION + REGRESSION DETECTION
# Every AI code endpoint below runs its output through these two
# checks before returning it — the same discipline used to prepare
# this file for delivery: parse it, and diff it against what was
# there before to catch anything that got silently dropped.
# ════════════════════════════════════════════════════════════

_VALIDATABLE_LANGS = {"python", "py", "javascript", "js"}


def _validate_code_syntax(language: str, code: str) -> dict:
    """Syntax-checks generated/edited code before it's handed back.
    Python uses the standard library's ast.parse (always available).
    JavaScript uses esprima if installed, otherwise validation is
    skipped rather than blocking the response. Returns:
      {"checked": bool, "valid": bool, "error": str|None, "line": int|None}
    """
    lang = (language or "").strip().lower()

    if lang in ("python", "py"):
        try:
            ast.parse(code)
            return {"checked": True, "valid": True, "error": None, "line": None}
        except SyntaxError as e:
            return {
                "checked": True, "valid": False,
                "error": f"{e.msg} (line {e.lineno})", "line": e.lineno,
            }
        except Exception as e:
            return {"checked": True, "valid": False, "error": str(e), "line": None}

    if lang in ("javascript", "js"):
        if not ESPRIMA_AVAILABLE:
            return {"checked": False, "valid": True, "error": None, "line": None,
                     "note": "esprima not installed — JS syntax was not checked. Run: pip install esprima"}
        try:
            esprima.parseScript(code, {"tolerant": False})
            return {"checked": True, "valid": True, "error": None, "line": None}
        except Exception as e:
            line = getattr(e, "lineNumber", None)
            return {"checked": True, "valid": False, "error": str(e), "line": line}

    # Other languages (html, css, sql, java, go, ...): no lightweight
    # validator available server-side yet — don't block, just say so.
    return {"checked": False, "valid": True, "error": None, "line": None,
             "note": f"No syntax validator wired up for '{language}' yet."}


def _extract_signatures(code: str, language: str) -> set:
    """Pulls a rough set of 'def name(' / 'class name' / '@app.route(...)'
    signatures out of a file so two versions can be compared. Deliberately
    simple (regex, not a full parser) so it works even on code that fails
    to parse — that's exactly when you most need to see what disappeared."""
    lang = (language or "").strip().lower()
    sigs = set()
    if lang in ("python", "py"):
        sigs.update(re.findall(r"^\s*def\s+(\w+)\s*\(", code, re.MULTILINE))
        sigs.update("class:" + c for c in re.findall(r"^\s*class\s+(\w+)", code, re.MULTILINE))
        sigs.update("route:" + r for r in re.findall(r'@app\.route\(\s*["\']([^"\']+)["\']', code))
    else:
        sigs.update(re.findall(r"function\s+(\w+)\s*\(", code))
        sigs.update(re.findall(r"\b(\w+)\s*=\s*function\s*\(", code))
        sigs.update(re.findall(r"\b(?:async\s+)?function\*?\s*(\w+)", code))
    return sigs


def _check_regression_risks(before: str, after: str, language: str) -> list:
    """Flags things a whole-file AI rewrite may have silently dropped:
    removed function/class definitions, removed Flask routes, and a
    drastic, unexplained line-count drop. Warnings only — the caller
    decides whether to block or just surface them."""
    warnings = []

    before_sigs = _extract_signatures(before, language)
    after_sigs = _extract_signatures(after, language)
    removed = sorted(before_sigs - after_sigs)
    if removed:
        shown = ", ".join(removed[:8])
        more = f" (+{len(removed) - 8} more)" if len(removed) > 8 else ""
        warnings.append(f"Possibly removed: {shown}{more} — present before the edit, missing after.")

    before_lines = before.count("\n") + 1
    after_lines = after.count("\n") + 1
    if before_lines >= 20 and after_lines < before_lines * 0.7:
        pct = round((1 - after_lines / before_lines) * 100)
        warnings.append(f"File shrank by {pct}% ({before_lines} → {after_lines} lines) — confirm nothing unrelated was cut.")

    return warnings


def ai_generate_code(language: str, spec: str, user_id=None) -> str:
    """Generates a complete, runnable file in `language` from a plain-
    English spec. Returns raw code (fences stripped)."""
    prompt = (
        f"Write complete, production-quality {language} code for the following request. "
        f"Return ONLY the code — no explanation, no markdown fences, no commentary before or after.\n\n"
        f"REQUEST:\n{spec}"
    )
    reply, _ = generate_ai_reply(prompt, [], user_id=user_id, system_prompt=CODE_SYSTEM_PROMPT)
    return _strip_code_fences(reply)


def ai_edit_code(language: str, current_content: str, instructions: str, user_id=None) -> dict:
    """Edits an existing file's content against plain-English instructions.
    Returns {"updated_content", "diff", "validation", "regression_warnings"}.
    validation/regression_warnings run on the AI's output before it goes
    back to the caller — this whole-file mode regenerates everything, so
    it's the one most likely to silently drop something; for large files
    prefer /api/code/patch instead, which never touches anything outside
    the targeted snippet."""
    prompt = (
        f"You are editing an existing {language} file. Apply the following instructions and "
        f"return the COMPLETE updated file — not a snippet, not a diff, the whole file from top "
        f"to bottom. Return ONLY the code, no explanation, no markdown fences.\n\n"
        f"INSTRUCTIONS:\n{instructions}\n\n"
        f"CURRENT FILE CONTENT:\n{current_content}"
    )
    reply, _ = generate_ai_reply(prompt, [], user_id=user_id, system_prompt=CODE_SYSTEM_PROMPT)
    updated = _strip_code_fences(reply)

    diff = "\n".join(difflib.unified_diff(
        current_content.splitlines(), updated.splitlines(),
        fromfile="before", tofile="after", lineterm="",
    ))
    return {
        "updated_content": updated,
        "diff": diff,
        "validation": _validate_code_syntax(language, updated),
        "regression_warnings": _check_regression_risks(current_content, updated, language),
    }


def ai_patch_code(language: str, current_content: str, old_str: str, instructions: str = "",
                   new_str: str = None, context_lines: int = 6, user_id=None) -> dict:
    """Surgical edit: replaces exactly one occurrence of `old_str` inside
    `current_content`, without ever sending the whole file to the model.
    This is the recommended way to edit large files — cost and risk stay
    constant no matter how big the surrounding file is, and nothing
    outside `old_str` can be touched.

    Either pass `new_str` directly (deterministic, no AI call), or pass
    `instructions` and let the AI write just the replacement — the model
    only ever sees `old_str` plus a few lines of surrounding context, not
    the rest of the file.

    Returns one of:
      {"ok": False, "error": ..., "match_count": int}   — old_str not
        found, or found more than once (ambiguous; needs more context
        to be unique, exactly like a str_replace tool call).
      {"ok": True, "updated_content", "new_str", "diff",
       "validation", "regression_warnings"}
    """
    match_count = current_content.count(old_str)
    if match_count == 0:
        return {"ok": False, "error": "old_str was not found in current_content.", "match_count": 0}
    if match_count > 1:
        return {
            "ok": False, "match_count": match_count,
            "error": f"old_str matches {match_count} places — it must match exactly one. "
                     f"Include more surrounding lines to make it unique.",
        }

    if new_str is None:
        if not instructions:
            return {"ok": False, "error": "Provide either new_str or instructions.", "match_count": match_count}
        idx = current_content.find(old_str)
        before_ctx = "\n".join(current_content[:idx].splitlines()[-context_lines:])
        after_ctx = "\n".join(current_content[idx + len(old_str):].splitlines()[:context_lines])
        prompt = (
            f"You are making a surgical edit to a snippet of {language} code. Only the exact "
            f"snippet below (OLD_STR) will be replaced — everything else in the file stays "
            f"untouched, so do not repeat or reference code outside it.\n\n"
            f"CONTEXT BEFORE (for reference only, do not include in your answer):\n{before_ctx}\n\n"
            f"OLD_STR (replace this exactly):\n{old_str}\n\n"
            f"CONTEXT AFTER (for reference only, do not include in your answer):\n{after_ctx}\n\n"
            f"INSTRUCTIONS:\n{instructions}\n\n"
            f"Return ONLY the replacement text for OLD_STR — no explanation, no markdown fences, "
            f"no surrounding context repeated back."
        )
        reply, _ = generate_ai_reply(prompt, [], user_id=user_id, system_prompt=CODE_SYSTEM_PROMPT)
        new_str = _strip_code_fences(reply)

    updated_content = current_content.replace(old_str, new_str, 1)
    diff = "\n".join(difflib.unified_diff(
        old_str.splitlines(), new_str.splitlines(),
        fromfile="old_str", tofile="new_str", lineterm="",
    ))
    return {
        "ok": True,
        "updated_content": updated_content,
        "new_str": new_str,
        "diff": diff,
        "validation": _validate_code_syntax(language, updated_content),
        "regression_warnings": _check_regression_risks(current_content, updated_content, language),
    }


def ai_review_code(language: str, code: str, user_id=None) -> dict:
    """Real code review: bugs, security issues, style, and concrete fixes —
    structured, not narrative. Returns parsed JSON where possible, falls
    back to the raw text under 'raw' if the model didn't return clean JSON."""
    prompt = (
        f"Review this {language} code like a senior engineer doing a real code review. "
        f"Return ONLY a JSON object with keys: \"bugs\" (array of strings), "
        f"\"security_issues\" (array of strings), \"style_issues\" (array of strings), "
        f"\"suggestions\" (array of strings), \"overall_assessment\" (one paragraph, plain text). "
        f"No markdown fences, no text outside the JSON object.\n\n"
        f"CODE:\n{code}"
    )
    reply, _ = generate_ai_reply(prompt, [], user_id=user_id, system_prompt=CODE_SYSTEM_PROMPT)
    cleaned = _strip_code_fences(reply)
    try:
        return {"ok": True, **json.loads(cleaned)}
    except Exception:
        return {"ok": True, "raw": cleaned}


def _lang_from_filename(filename: str) -> str:
    ext = (filename or "").rsplit(".", 1)[-1].lower() if "." in (filename or "") else ""
    return {"py": "python", "js": "javascript", "mjs": "javascript", "cjs": "javascript"}.get(ext, ext)


def ai_build_project(project_type: str, spec: str, user_id=None) -> dict:
    """Generates a full MULTI-FILE project from one spec — e.g. 'a Flask
    API with a health check and a /users endpoint' becomes app.py,
    requirements.txt, README.md, etc. Returns {"files": [{"filename",
    "content", "validation"}, ...]} — each file is syntax-checked (where
    a validator is available for its extension) before being returned."""
    prompt = (
        f"Design and write a complete {project_type} project for this request. "
        f"Return ONLY a JSON object of the shape "
        f'{{"files": [{{"filename": "path/name.ext", "content": "full file contents"}}, ...]}}. '
        f"Include every file a working project needs (source files, a dependency/requirements "
        f"file if the language has one, and a short README.md). Use realistic, complete code in "
        f"every file — no placeholders, no '...', no TODO stubs. "
        f"Return ONLY that JSON object, no markdown fences, no text outside it.\n\n"
        f"REQUEST:\n{spec}"
    )
    reply, _ = generate_ai_reply(prompt, [], user_id=user_id, system_prompt=CODE_SYSTEM_PROMPT)
    cleaned = _strip_code_fences(reply)
    try:
        parsed = json.loads(cleaned)
        files = parsed.get("files", [])
        if not files:
            return {"ok": False, "error": "Model returned no files."}
        for f in files:
            f["validation"] = _validate_code_syntax(_lang_from_filename(f.get("filename", "")), f.get("content", ""))
        return {"ok": True, "files": files}
    except Exception as e:
        logging.error(f"[BUILD PROJECT PARSE ERROR] {e}")
        return {"ok": False, "error": "Could not parse the generated project as JSON.", "raw": cleaned}




def ai_analyze_content(content: str, analysis_type: str = "general", user_id=None) -> dict:
    """General-purpose structured analysis (documents, data, business
    content — not just code) using the non-poetic ANALYSIS_SYSTEM_PROMPT.
    Returns parsed JSON where possible."""
    prompt = (
        f"Analyze the following content. Analysis focus: {analysis_type}. "
        f"Return ONLY a JSON object with keys: \"summary\" (2-3 sentences), "
        f"\"key_points\" (array of strings), \"concerns_or_risks\" (array of strings, empty if none), "
        f"\"recommendations\" (array of strings). No markdown fences, no text outside the JSON.\n\n"
        f"CONTENT:\n{content}"
    )
    reply, _ = generate_ai_reply(prompt, [], user_id=user_id, system_prompt=ANALYSIS_SYSTEM_PROMPT)
    cleaned = _strip_code_fences(reply)
    try:
        return {"ok": True, **json.loads(cleaned)}
    except Exception:
        return {"ok": True, "raw": cleaned}


def build_zip_from_files(files: list) -> bytes:
    """files: [{"filename": "app.py", "content": "..."}]. Returns zip bytes."""
    buf = io.BytesIO()
    with zipfile.ZipFile(buf, "w", zipfile.ZIP_DEFLATED) as z:
        for f in files:
            name = f.get("filename") or "file.txt"
            content = f.get("content") or ""
            z.writestr(name, content)
    buf.seek(0)
    return buf.read()


