# ===========================================================
# STAGE 38: META ADS MANAGER + TIKTOK ADS MANAGER
# Actual campaign creation and spend visibility — the natural next step
# from the read-only meta_conversion_api tracking already built above.
# Every created campaign is left PAUSED/DISABLED by default: Connect It
# should never spend a user's ad budget without them explicitly turning
# a campaign on in the platform's own Ads Manager.
# ===========================================================

def _meta_ads_creds_for_user(user_id) -> dict:
    return {
        "ad_account_id": get_effective_credential(user_id, "meta_ads_manager", "ad_account_id", META_ADS_AD_ACCOUNT_ID),
        "access_token":  get_effective_credential(user_id, "meta_ads_manager", "access_token", META_ADS_ACCESS_TOKEN),
    }


def _meta_ads_request(user_id, method: str, path: str, **kwargs) -> dict:
    creds = _meta_ads_creds_for_user(user_id)
    if not (creds["ad_account_id"] and creds["access_token"]):
        return {"ok": False, "error": "Meta Ads Manager is not configured. Add your ad account id and a Marketing-API access token under Integrations."}
    acct = creds["ad_account_id"].strip()
    if not acct.startswith("act_"):
        acct = f"act_{acct}"
    url = f"https://graph.facebook.com/{FACEBOOK_GRAPH_API_VERSION}/{acct}{path}"
    params = kwargs.pop("params", {}) or {}
    params["access_token"] = creds["access_token"]
    try:
        r = requests.request(method, url, params=params, timeout=15, **kwargs)
        body = r.json() if r.text else {}
        if r.status_code >= 400:
            return {"ok": False, "error": (body.get("error") or {}).get("message", f"Meta Ads API error ({r.status_code}).")}
        return {"ok": True, "data": body}
    except Exception as e:
        logging.error(f"[META ADS REQUEST ERROR] user={user_id}: {e}")
        return {"ok": False, "error": str(e)}


def meta_ads_list_campaigns(user_id) -> dict:
    """Lists this ad account's campaigns with status and budget."""
    result = _meta_ads_request(user_id, "GET", "/campaigns", params={
        "fields": "id,name,status,objective,daily_budget,lifetime_budget", "limit": 25,
    })
    if not result.get("ok"):
        return result
    campaigns = [{
        "id": c.get("id"), "name": c.get("name"), "status": c.get("status"),
        "objective": c.get("objective"),
        "daily_budget": c.get("daily_budget"), "lifetime_budget": c.get("lifetime_budget"),
    } for c in (result["data"] or {}).get("data", [])]
    return {"ok": True, "campaigns": campaigns}


def meta_ads_campaign_insights(user_id, campaign_id: str = None) -> dict:
    """Real spend/performance — the numbers meta_conversion_api's
    tracking feeds into but doesn't itself show."""
    path = f"/{campaign_id}/insights" if campaign_id else "/insights"
    if campaign_id:
        # Insights on a specific campaign hang off its own node, not the ad account.
        creds = _meta_ads_creds_for_user(user_id)
        if not (creds["ad_account_id"] and creds["access_token"]):
            return {"ok": False, "error": "Meta Ads Manager is not configured."}
        url = f"https://graph.facebook.com/{FACEBOOK_GRAPH_API_VERSION}/{campaign_id}/insights"
        try:
            r = requests.get(url, params={
                "fields": "campaign_name,spend,impressions,clicks,cpc,ctr",
                "access_token": creds["access_token"],
            }, timeout=15)
            body = r.json() if r.text else {}
            if r.status_code >= 400:
                return {"ok": False, "error": (body.get("error") or {}).get("message", "Meta Ads API error.")}
            rows = body.get("data", [])
        except Exception as e:
            return {"ok": False, "error": str(e)}
    else:
        result = _meta_ads_request(user_id, "GET", "/insights", params={
            "fields": "campaign_name,spend,impressions,clicks,cpc,ctr", "level": "campaign", "limit": 25,
        })
        if not result.get("ok"):
            return result
        rows = (result["data"] or {}).get("data", [])
    insights = [{
        "campaign_name": r.get("campaign_name"), "spend": r.get("spend"),
        "impressions": r.get("impressions"), "clicks": r.get("clicks"),
        "cpc": r.get("cpc"), "ctr": r.get("ctr"),
    } for r in rows]
    return {"ok": True, "insights": insights}


def meta_ads_create_campaign(user_id, name: str, objective: str, daily_budget_cents: int) -> dict:
    """Creates a real campaign — always PAUSED, so ad spend only starts
    once the user reviews and turns it on themselves in Ads Manager."""
    if not (name and objective):
        return {"ok": False, "error": "'name' and 'objective' are required."}
    payload = {
        "name": name,
        "objective": objective,
        "status": "PAUSED",
        "special_ad_categories": [],
    }
    if daily_budget_cents:
        payload["daily_budget"] = int(daily_budget_cents)
    result = _meta_ads_request(user_id, "POST", "/campaigns", data=payload)
    if not result.get("ok"):
        return result
    return {"ok": True, "id": (result["data"] or {}).get("id"), "status": "PAUSED"}


