    data = request.get_json(silent=True) or {}
    items = data.get("menu_items") or []
    if not items:
        return jsonify({"error": "menu_items (a non-empty list) is required."}), 400
    result = _messenger_profile_call(user_id, "POST", {
        "persistent_menu": [{
            "locale": "default", "composer_input_disabled": False,
            "call_to_actions": items[:3],
        }]
    })
    return jsonify(result), (200 if result.get("ok") else 502)


