@app.route("/api/messenger/send-action", methods=["POST"])
@csrf.exempt
def messenger_send_action():
    """Sender actions: typing_on, typing_off, mark_seen -- no message
    content, just presence/read-receipt signals shown to the customer."""
    user_id = _current_user_id()
    if not user_id:
        return jsonify({"error": "Login required."}), 401
    creds = _messenger_creds_for_user(user_id)
    if not creds["page_access_token"]:
        return jsonify({"error": "Messenger is not configured."}), 503
    data = request.get_json(silent=True) or {}
    psid = (data.get("recipient_id") or "").strip()
    action = (data.get("sender_action") or "").strip()
    if not psid or action not in ("typing_on", "typing_off", "mark_seen"):
        return jsonify({"error": "recipient_id and a valid sender_action (typing_on/typing_off/mark_seen) are required."}), 400
    try:
        r = requests.post(
            f"https://graph.facebook.com/{FACEBOOK_GRAPH_API_VERSION}/me/messages",
            params={"access_token": creds["page_access_token"]},
            json={"recipient": {"id": psid}, "sender_action": action},
            timeout=15,
        )
        body = r.json()
        if r.status_code >= 400:
            return jsonify({"ok": False, "error": (body.get("error") or {}).get("message", "Sender action failed.")}), 502
        return jsonify({"ok": True})
    except Exception as e:
        logging.error(f"[MESSENGER ACTION ERROR] {e}")
        return jsonify({"ok": False, "error": str(e)}), 500


@app.route("/api/messenger/send-quick-replies", methods=["POST"])
@csrf.exempt
def messenger_send_quick_replies():
    """Sends a text message with up to 13 tappable quick-reply chips.
    Body: {"recipient_id":"...", "text":"...", "quick_replies":[{"title":"Yes","payload":"YES"}, ...]}"""
    user_id = _current_user_id()
    if not user_id:
        return jsonify({"error": "Login required."}), 401
    creds = _messenger_creds_for_user(user_id)
    if not creds["page_access_token"]:
        return jsonify({"error": "Messenger is not configured."}), 503
    data = request.get_json(silent=True) or {}
    psid = (data.get("recipient_id") or "").strip()
    text = (data.get("text") or "").strip()
    replies = data.get("quick_replies") or []
    if not psid or not text or not replies:
        return jsonify({"error": "recipient_id, text, and quick_replies are all required."}), 400
    qr_payload = [{"content_type": "text", "title": str(r.get("title", ""))[:20], "payload": str(r.get("payload", ""))[:1000]}
                  for r in replies[:13]]
    try:
        r = requests.post(
            f"https://graph.facebook.com/{FACEBOOK_GRAPH_API_VERSION}/me/messages",
            params={"access_token": creds["page_access_token"]},
            json={"recipient": {"id": psid}, "message": {"text": text, "quick_replies": qr_payload}},
            timeout=15,
        )
        body = r.json()
        if r.status_code >= 400:
            return jsonify({"ok": False, "error": (body.get("error") or {}).get("message", "Quick-reply send failed.")}), 502
        return jsonify({"ok": True, "message_id": body.get("message_id")})
    except Exception as e:
        logging.error(f"[MESSENGER QUICK REPLIES ERROR] {e}")
        return jsonify({"ok": False, "error": str(e)}), 500


