@app.route("/api/messenger/send-attachment", methods=["POST"])
@csrf.exempt
def messenger_send_attachment():
    """Sends an image/audio/video/file by public URL.
    Body: {"recipient_id":"...", "attachment_type":"image", "url":"...", "is_reusable": true}"""
    user_id = _current_user_id()
    if not user_id:
        return jsonify({"error": "Login required."}), 401
    creds = _messenger_creds_for_user(user_id)
    if not creds["page_access_token"]:
        return jsonify({"error": "Messenger is not configured."}), 503
    data = request.get_json(silent=True) or {}
    psid = (data.get("recipient_id") or "").strip()
    atype = (data.get("attachment_type") or "image").strip()
    url = (data.get("url") or "").strip()
    if atype not in ("image", "audio", "video", "file"):
        return jsonify({"error": "attachment_type must be one of image, audio, video, file."}), 400
    if not psid or not url:
        return jsonify({"error": "recipient_id and url are required."}), 400
    try:
        r = requests.post(
            f"https://graph.facebook.com/{FACEBOOK_GRAPH_API_VERSION}/me/messages",
            params={"access_token": creds["page_access_token"]},
            json={"recipient": {"id": psid}, "message": {"attachment": {
                "type": atype, "payload": {"url": url, "is_reusable": bool(data.get("is_reusable", True))},
            }}},
            timeout=20,
        )
        body = r.json()
        if r.status_code >= 400:
            return jsonify({"ok": False, "error": (body.get("error") or {}).get("message", "Attachment send failed.")}), 502
        return jsonify({"ok": True, "message_id": body.get("message_id"), "attachment_id": body.get("attachment_id")})
    except Exception as e:
        logging.error(f"[MESSENGER ATTACHMENT ERROR] {e}")
        return jsonify({"ok": False, "error": str(e)}), 500


