@app.route("/instagram/webhook", methods=["GET"])
@csrf.exempt
def instagram_webhook_verify():
    """Meta's one-time handshake to verify this webhook URL. Instagram
    messaging can share Messenger's verify token if a separate one
    wasn't set."""
    mode      = request.args.get("hub.mode", "")
    token     = request.args.get("hub.verify_token", "")
    challenge = request.args.get("hub.challenge", "")
    expected  = FACEBOOK_INSTAGRAM_VERIFY_TOKEN or FACEBOOK_MESSENGER_VERIFY_TOKEN
    if mode == "subscribe" and expected and hmac.compare_digest(token, expected):
        return challenge, 200
    return "Forbidden", 403


@app.route("/instagram/webhook", methods=["POST"])
@csrf.exempt
def instagram_webhook_receive():
    """Incoming Instagram DMs (including story replies and story
    mentions). Runs the same AI-reply pipeline as WhatsApp/Messenger,
    then replies via the Instagram Send API using whichever business's
    BYOK credentials own the receiving IG account."""
    try:
        payload = request.get_json(force=True) or {}
        for entry in payload.get("entry", []):
            ig_id = str(entry.get("id", ""))
            owner_uid = _find_user_for_instagram_account(ig_id)
            for event in entry.get("messaging", []) or []:
                sender_igsid = str((event.get("sender") or {}).get("id", ""))
                msg = event.get("message") or {}
                incoming_msg = (msg.get("text") or "").strip()
                reply_to = (msg.get("reply_to") or {})
                is_story_reply = bool(reply_to.get("story"))
                is_story_mention = bool((msg.get("attachments") or [{}])[0].get("type") == "story_mention"
                                          if msg.get("attachments") else False)
                if not sender_igsid:
                    continue
                if not incoming_msg:
                    if is_story_mention:
                        logging.info(f"[INSTAGRAM] story mention from {sender_igsid}")
                    continue
                tag = " (story reply)" if is_story_reply else ""
                logging.info(f"[INSTAGRAM] from {sender_igsid}{tag}: '{incoming_msg}'")

                if sender_igsid not in instagram_dm_store:
                    instagram_dm_store[sender_igsid] = _db_get_history(sender_igsid, channel="instagram")
                history = _get_history(instagram_dm_store, sender_igsid)

                ai_reply_raw, updated_history = generate_ai_reply(incoming_msg, history)
                _save_history(instagram_dm_store, sender_igsid, updated_history)
                _db_save_turn(sender_igsid, "instagram", "user",      incoming_msg, owner_user_id=owner_uid)
                _db_save_turn(sender_igsid, "instagram", "assistant", ai_reply_raw,  owner_user_id=owner_uid)
                _db_add_gratitude(f"Instagram ({sender_igsid})", incoming_msg)
                _db_add_gratitude(AI_DISPLAY_NAME, ai_reply_raw)

                try:
                    send_instagram_dm(owner_uid, sender_igsid, ai_reply_raw)
                except Exception as send_err:
                    logging.error(f"[INSTAGRAM DM REPLY ERROR] {send_err}")
        return connectit_json_response({"status": "received"})
    except Exception as e:
        logging.error(f"[INSTAGRAM WEBHOOK ERROR] {e}")
        return connectit_json_response({"error": str(e)}, 500)


# ===========================================================
# STAGE 21: THREADS API (Meta's text app)
# Free public posting API — same publish button pattern you already
# have for Facebook/Instagram, extended here. Two-step Graph-style
# flow: create a media container, then publish it.
# ===========================================================

def _threads_creds_for_user(user_id) -> dict:
    return {
        "access_token": get_effective_credential(user_id, "threads", "access_token", THREADS_ACCESS_TOKEN),
        "threads_user_id": get_effective_credential(user_id, "threads", "threads_user_id", THREADS_USER_ID),
    }


def post_to_threads(user_id, text: str) -> dict:
    """Publishes a text post to Threads. Two-step flow: create a media
    container, then publish it (same shape as Instagram publishing)."""
    creds = _threads_creds_for_user(user_id)
    if not creds["access_token"] or not creds["threads_user_id"]:
        return {"ok": False, "error": "Threads is not configured. Add your Access Token and Threads User ID under Integrations."}
    if not text or not text.strip():
        return {"ok": False, "error": "Post text is required."}
    try:
        create_r = requests.post(
            f"https://graph.threads.net/{THREADS_API_VERSION}/{creds['threads_user_id']}/threads",
            data={"media_type": "TEXT", "text": text.strip(), "access_token": creds["access_token"]},
            timeout=20,
        )
        create_body = create_r.json()
        if create_r.status_code >= 400:
            return {"ok": False, "error": (create_body.get("error") or {}).get("message", "Could not create Threads post.")}
        creation_id = create_body.get("id")

        publish_r = requests.post(
            f"https://graph.threads.net/{THREADS_API_VERSION}/{creds['threads_user_id']}/threads_publish",
            data={"creation_id": creation_id, "access_token": creds["access_token"]},
            timeout=20,
        )
        publish_body = publish_r.json()
        if publish_r.status_code >= 400:
            return {"ok": False, "error": (publish_body.get("error") or {}).get("message", "Could not publish to Threads.")}
        thread_id = publish_body.get("id")
        return {"ok": True, "post_id": thread_id}
    except Exception as e:
        logging.error(f"[THREADS POST ERROR] user={user_id}: {e}")
        return {"ok": False, "error": str(e)}


@app.route("/api/social/threads/post", methods=["POST"])
@csrf.exempt
def threads_post_endpoint():
    user_id = _current_user_id()
    if not user_id:
        return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    text = (data.get("text") or "").strip()
    if not text:
        return jsonify({"error": "'text' is required."}), 400
    result = post_to_threads(user_id, text)
    return jsonify(result), (200 if result.get("ok") else 502)


# ===========================================================
# STAGE 22: PINTEREST (Pinterest API v5)
# Same publish-button pattern as Facebook/LinkedIn/Threads, extended
# here. BYOK: user pastes a personal access token from a Pinterest app
# created at developers.pinterest.com (with the "pins:write" and
# "boards:read" scopes), plus the numeric ID of the board to pin to.
# ===========================================================

def _pinterest_creds_for_user(user_id) -> dict:
    return {
        "access_token": get_effective_credential(user_id, "pinterest", "access_token", PINTEREST_ACCESS_TOKEN),
        "board_id": get_effective_credential(user_id, "pinterest", "board_id", PINTEREST_BOARD_ID),
    }


def post_to_pinterest(user_id, image_url: str, title: str = "", description: str = "", link_url: str = "") -> dict:
    """Creates a new Pin on the user's default board via the Pinterest
    API v5 /pins endpoint."""
    creds = _pinterest_creds_for_user(user_id)
    if not creds["access_token"] or not creds["board_id"]:
        return {"ok": False, "error": "Pinterest is not configured. Add your Access Token and Board ID under Integrations."}
    if not image_url or not image_url.strip():
        return {"ok": False, "error": "'image_url' is required — Pinterest pins must have an image."}
    payload = {
        "board_id": creds["board_id"],
        "media_source": {"source_type": "image_url", "url": image_url.strip()},
    }
    if title.strip():
        payload["title"] = title.strip()[:100]
    if description.strip():
        payload["description"] = description.strip()[:800]
    if link_url.strip():
        payload["link"] = link_url.strip()
    try:
        r = requests.post(
            "https://api.pinterest.com/v5/pins",
            headers={"Authorization": f"Bearer {creds['access_token']}", "Content-Type": "application/json"},
            json=payload,
            timeout=20,
        )
        body = r.json()
        if r.status_code >= 400:
            return {"ok": False, "error": body.get("message") or f"Pinterest pin failed ({r.status_code})."}
        pin_id = body.get("id")
        return {"ok": True, "pin_id": pin_id,
                "post_url": f"https://www.pinterest.com/pin/{pin_id}/" if pin_id else None}
    except Exception as e:
        logging.error(f"[PINTEREST POST ERROR] user={user_id}: {e}")
        return {"ok": False, "error": str(e)}


def list_pinterest_pins(user_id, limit: int = 10) -> dict:
    creds = _pinterest_creds_for_user(user_id)
    if not creds["access_token"]:
        return {"ok": False, "error": "Pinterest is not configured."}
    try:
        r = requests.get(
            "https://api.pinterest.com/v5/pins",
            headers={"Authorization": f"Bearer {creds['access_token']}"},
            params={"page_size": limit},
            timeout=15,
        )
        body = r.json()
        if r.status_code >= 400:
            return {"ok": False, "error": body.get("message", "Could not load Pinterest pins.")}
        pins = [{
            "id": p.get("id"),
            "title": p.get("title"),
            "image_url": ((p.get("media") or {}).get("images") or {}).get("600x", {}).get("url"),
            "post_url": f"https://www.pinterest.com/pin/{p.get('id')}/" if p.get("id") else None,
        } for p in body.get("items", [])]
        return {"ok": True, "pins": pins}
    except Exception as e:
        logging.error(f"[PINTEREST LIST PINS ERROR] user={user_id}: {e}")
        return {"ok": False, "error": str(e)}


