# ===========================================================
# STAGE 23: OPENWEATHERMAP
# Dead simple, single free API key, no OAuth. Read-only current
# conditions lookup for any city — used to ground business tools (e.g.
# "should we run the outdoor event") in real, current weather data.
# ===========================================================

def get_current_weather(user_id, location: str, units: str = "metric") -> dict:
    api_key = get_effective_credential(user_id, "openweathermap", "api_key", OPENWEATHERMAP_API_KEY)
    if not api_key:
        return {"ok": False, "error": "OpenWeatherMap is not configured. Add a free OpenWeatherMap API key under Integrations."}
    if not location or not location.strip():
        return {"ok": False, "error": "'location' is required."}
    try:
        r = requests.get(
            "https://api.openweathermap.org/data/2.5/weather",
            params={"q": location.strip(), "appid": api_key, "units": units},
            timeout=15,
        )
        body = r.json()
        if r.status_code >= 400:
            return {"ok": False, "error": body.get("message", "Weather lookup failed.")}
        weather_list = body.get("weather") or [{}]
        main = body.get("main") or {}
        wind = body.get("wind") or {}
        rain = body.get("rain") or {}
        return {"ok": True, "weather": {
            "location": body.get("name"),
            "country": (body.get("sys") or {}).get("country"),
            "description": weather_list[0].get("description"),
            "icon": weather_list[0].get("icon"),
            "icon_url": f"https://openweathermap.org/img/wn/{weather_list[0].get('icon')}@2x.png" if weather_list[0].get("icon") else None,
            "temp": main.get("temp"),
            "feels_like": main.get("feels_like"),
            "temp_min": main.get("temp_min"),
            "temp_max": main.get("temp_max"),
            "humidity": main.get("humidity"),
            "wind_speed": wind.get("speed"),
            "rain_1h_mm": rain.get("1h", 0.0),
            "units": units,
        }}
    except Exception as e:
        logging.error(f"[OPENWEATHERMAP ERROR] user={user_id}: {e}")
        return {"ok": False, "error": str(e)}


@app.route("/api/weather", methods=["GET"])
@csrf.exempt
def weather_endpoint():
    user_id = _current_user_id()
    if not user_id:
        return jsonify({"ok": False, "error": "Login required."}), 401
    location = (request.args.get("location") or "").strip()
    units = (request.args.get("units") or "metric").strip()
    result = get_current_weather(user_id, location, units=units)
    return jsonify(result), (200 if result.get("ok") else 502)


# ===========================================================
# STAGE 14: GOOGLE DRIVE — real cloud backup for AI-generated
# documents (contracts, invoices, reports) instead of local download
# only. Same service-account BYOK pattern as Docs/Sheets/Calendar.
# ===========================================================

_DRIVE_SCOPES = ["https://www.googleapis.com/auth/drive"]


def drive_upload_text(user_id, title: str, content: str, mime_type: str = "text/plain") -> dict:
    """Uploads a piece of generated text (e.g. a contract or report) to
    the user's Google Drive as a real, shareable file."""
    if not GCALENDAR_AVAILABLE:
        return {"ok": False, "error": "google-api-python-client is not installed. Run: pip install google-api-python-client"}
    raw = get_effective_credential(user_id, "google_drive", "service_account_json", GOOGLE_DRIVE_CREDENTIALS_JSON)
    info = _load_service_account_info(raw)
    if not info:
        return {"ok": False, "error": "Google Drive is not configured. Add a Google service-account JSON under Integrations."}
    folder_id = get_effective_credential(user_id, "google_drive", "folder_id", GOOGLE_DRIVE_FOLDER_ID)
    try:
        from google.oauth2.service_account import Credentials as DriveCredentials
        from googleapiclient.http import MediaIoBaseUpload
        creds = DriveCredentials.from_service_account_info(info, scopes=_DRIVE_SCOPES)
        drive_service = google_api_build("drive", "v3", credentials=creds, cache_discovery=False)
        metadata = {"name": title or "Connect It Document"}
        if folder_id:
            metadata["parents"] = [folder_id]
        media = MediaIoBaseUpload(io.BytesIO((content or "").encode("utf-8")), mimetype=mime_type, resumable=False)
        file = drive_service.files().create(body=metadata, media_body=media, fields="id,webViewLink").execute()
        return {"ok": True, "file_id": file.get("id"), "view_url": file.get("webViewLink")}
    except Exception as e:
        logging.error(f"[GOOGLE DRIVE UPLOAD ERROR] user={user_id}: {e}")
        return {"ok": False, "error": str(e)}


def drive_list_files(user_id, limit: int = 25) -> dict:
    """Lists files in the connected Drive folder (or 'My Drive' root if
    no folder_id is set)."""
    if not GCALENDAR_AVAILABLE:
        return {"ok": False, "error": "google-api-python-client is not installed. Run: pip install google-api-python-client"}
    raw = get_effective_credential(user_id, "google_drive", "service_account_json", GOOGLE_DRIVE_CREDENTIALS_JSON)
    info = _load_service_account_info(raw)
    if not info:
        return {"ok": False, "error": "Google Drive is not configured. Add a Google service-account JSON under Integrations."}
    folder_id = get_effective_credential(user_id, "google_drive", "folder_id", GOOGLE_DRIVE_FOLDER_ID)
    try:
        from google.oauth2.service_account import Credentials as DriveCredentials
        creds = DriveCredentials.from_service_account_info(info, scopes=_DRIVE_SCOPES)
        drive_service = google_api_build("drive", "v3", credentials=creds, cache_discovery=False)
        query = f"'{folder_id}' in parents and trashed = false" if folder_id else "trashed = false"
        results = drive_service.files().list(
            q=query, pageSize=limit, fields="files(id,name,mimeType,modifiedTime,webViewLink)"
        ).execute()
        files = [{"id": f.get("id"), "name": f.get("name"), "mime_type": f.get("mimeType"),
                  "modified_time": f.get("modifiedTime"), "view_url": f.get("webViewLink")}
                 for f in results.get("files", [])]
        return {"ok": True, "files": files}
    except Exception as e:
        logging.error(f"[GOOGLE DRIVE LIST ERROR] user={user_id}: {e}")
        return {"ok": False, "error": str(e)}


# ===========================================================
# STAGE 15: YOUTUBE DATA API (read-only research)
# Free API key from Google Cloud Console, no OAuth. Good for content
# research alongside the video-generation tool — trending videos in a
# niche, a competitor's channel stats — not channel management, since
# uploading on a user's behalf needs Google's sensitive-scope OAuth
# review (weeks-long, not a "connect in one click" integration).
# ===========================================================

def youtube_search_videos(user_id, query: str, max_results: int = 10) -> dict:
    api_key = get_effective_credential(user_id, "youtube", "api_key", YOUTUBE_DATA_API_KEY)
    if not api_key:
        return {"ok": False, "error": "YouTube is not configured. Add a free YouTube Data API key under Integrations."}
    if not query:
        return {"ok": False, "error": "'query' is required."}
    try:
        r = requests.get(
            "https://www.googleapis.com/youtube/v3/search",
            params={"part": "snippet", "q": query, "type": "video", "maxResults": max_results,
                    "order": "viewCount", "key": api_key},
            timeout=15,
        )
        body = r.json()
        if r.status_code >= 400:
            return {"ok": False, "error": (body.get("error") or {}).get("message", "YouTube search failed.")}
        videos = [{
            "video_id": (v.get("id") or {}).get("videoId"),
            "title": (v.get("snippet") or {}).get("title"),
            "channel": (v.get("snippet") or {}).get("channelTitle"),
            "published_at": (v.get("snippet") or {}).get("publishedAt"),
            "thumbnail": ((v.get("snippet") or {}).get("thumbnails") or {}).get("medium", {}).get("url"),
            "url": f"https://youtube.com/watch?v={(v.get('id') or {}).get('videoId')}",
        } for v in body.get("items", [])]
        return {"ok": True, "videos": videos}
    except Exception as e:
        logging.error(f"[YOUTUBE SEARCH ERROR] user={user_id}: {e}")
        return {"ok": False, "error": str(e)}


def youtube_channel_stats(user_id, channel_id_or_handle: str) -> dict:
    api_key = get_effective_credential(user_id, "youtube", "api_key", YOUTUBE_DATA_API_KEY)
    if not api_key:
        return {"ok": False, "error": "YouTube is not configured. Add a free YouTube Data API key under Integrations."}
    if not channel_id_or_handle:
        return {"ok": False, "error": "'channel_id_or_handle' is required."}
    try:
        params = {"part": "snippet,statistics", "key": api_key}
        if channel_id_or_handle.startswith("@"):
            params["forHandle"] = channel_id_or_handle
        else:
            params["id"] = channel_id_or_handle
        r = requests.get("https://www.googleapis.com/youtube/v3/channels", params=params, timeout=15)
        body = r.json()
        if r.status_code >= 400:
            return {"ok": False, "error": (body.get("error") or {}).get("message", "YouTube lookup failed.")}
        items = body.get("items") or []
        if not items:
            return {"ok": False, "error": "Channel not found."}
        ch = items[0]
        stats = ch.get("statistics") or {}
        return {"ok": True, "channel": {
            "title": (ch.get("snippet") or {}).get("title"),
            "subscribers": stats.get("subscriberCount"),
            "views": stats.get("viewCount"),
            "video_count": stats.get("videoCount"),
        }}
    except Exception as e:
        logging.error(f"[YOUTUBE CHANNEL STATS ERROR] user={user_id}: {e}")
        return {"ok": False, "error": str(e)}


