def unsplash_search_photos(user_id, query: str, count: int = 6) -> dict:
    access_key = get_effective_credential(user_id, "unsplash", "access_key", UNSPLASH_ACCESS_KEY)
    if not access_key:
        return {"ok": False, "error": "Unsplash is not configured. Add a free Unsplash Access Key under Integrations."}
    if not query:
        return {"ok": False, "error": "'query' is required."}
    try:
        r = requests.get(
            "https://api.unsplash.com/search/photos",
            params={"query": query, "per_page": min(count, 12), "orientation": "landscape"},
            headers={"Authorization": f"Client-ID {access_key}"},
            timeout=15,
        )
        body = r.json()
        if r.status_code >= 400:
            return {"ok": False, "error": body.get("errors", ["Unsplash search failed."])[0]}
        photos = [{
            "id": p.get("id"),
            "description": p.get("alt_description") or p.get("description"),
            "thumb_url": (p.get("urls") or {}).get("small"),
            "full_url": (p.get("urls") or {}).get("regular"),
            "photographer": (p.get("user") or {}).get("name"),
            "photographer_url": ((p.get("user") or {}).get("links") or {}).get("html"),
        } for p in body.get("results", [])]
        return {"ok": True, "photos": photos}
    except Exception as e:
        logging.error(f"[UNSPLASH SEARCH ERROR] user={user_id}: {e}")
        return {"ok": False, "error": str(e)}


