# ===========================================================
#  GOOGLE PROGRAMMABLE SEARCH ENGINE (PRIMARY)
# ===========================================================

# ===========================================================
#  TAVILY SEARCH — STAGE 237, tried first
# Built specifically for AI agents: returns a direct "answer" summary
# plus a handful of clean source snippets, so the AI usually doesn't
# need to synthesize across raw SERP snippets the way it does with
# Google CSE / SerpAPI below. BYOK-aware: a user's own Tavily key wins
# over the shared platform one, same pattern as every other provider.
# ===========================================================

def tavily_search(query: str, num_results: int = 5, user_id=None) -> str:
    if not TAVILY_AVAILABLE:
        return ""
    api_key = get_effective_credential(user_id, "tavily", "api_key", TAVILY_API_KEY) if user_id else TAVILY_API_KEY
    if not api_key:
        return ""
    try:
        client = TavilyClient(api_key=api_key)
        response = client.search(query=query, max_results=min(num_results, 10), include_answer=True)
        results = response.get("results", [])
        if not results and not response.get("answer"):
            return ""

        lines = ["[LIVE SEARCH RESULTS (Tavily) — use these to inform your answer]\n"]
        if response.get("answer"):
            lines.append(f"DIRECT ANSWER: {response['answer']}\n")
        for i, item in enumerate(results[:num_results], 1):
            title   = item.get("title", "")
            content = (item.get("content") or "")[:400]
            url     = item.get("url", "")
            lines.append(f"{i}. {title}\n   {content}\n   Source: {url}\n")
        return "\n".join(lines)
    except Exception as e:
        logging.error(f"Tavily search failed: {e}")
        return ""


def google_cse_search(query: str, num_results: int = 5) -> str:
    if not GOOGLE_CSE_API:
        return ""
    try:
        params = {
            "key": GOOGLE_CSE_API,
            "cx":  GOOGLE_CSE_ID,
            "q":   query,
            "num": min(num_results, 10),
        }
        r = requests.get(
            "https://www.googleapis.com/customsearch/v1",
            params  = params,
            timeout = 10,
        )
        if r.status_code != 200:
            logging.error(
                f"Google CSE returned HTTP {r.status_code}: {r.text[:200]}"
            )
            return ""

        data  = r.json()
        items = data.get("items", [])
        if not items:
            return ""

        lines = ["[GOOGLE SEARCH RESULTS — use these to inform your answer]\n"]
        for i, item in enumerate(items[:num_results], 1):
            title   = item.get("title",   "")
            snippet = item.get("snippet", "")
            link    = item.get("link",    "")
            lines.append(
                f"{i}. {title}\n   {snippet}\n   Source: {link}\n"
            )
        return "\n".join(lines)

    except Exception as e:
        logging.error(f"Google CSE search failed: {e}")
        return ""


# ===========================================================
#  SERPAPI SEARCH (FALLBACK)
# ===========================================================

def serpapi_search(query: str, num_results: int = 5) -> str:
    if not SERPAPI_KEY:
        return ""
    try:
        params = {
            "engine":  "google",
            "q":       query,
            "api_key": SERPAPI_KEY,
            "num":     num_results,
            "hl":      "en",
            "gl":      "us",
        }
        r = requests.get(
            "https://serpapi.com/search",
            params  = params,
            timeout = 10,
        )
        if r.status_code != 200:
            logging.error(f"SerpAPI returned HTTP {r.status_code}")
            return ""

        data            = r.json()
        organic_results = data.get("organic_results", [])
        answer_box      = data.get("answer_box", {})
        knowledge_graph = data.get("knowledge_graph", {})

        lines = ["[LIVE SEARCH RESULTS — use these to inform your answer]\n"]

        if answer_box:
            ab_answer = answer_box.get("answer") or answer_box.get("snippet", "")
            ab_title  = answer_box.get("title", "")
            if ab_answer:
                lines.append(f"DIRECT ANSWER: {ab_title} — {ab_answer}\n")

        if knowledge_graph:
            kg_desc = knowledge_graph.get("description", "")
            kg_name = knowledge_graph.get("title", "")
            if kg_desc:
                lines.append(f"KNOWLEDGE: {kg_name} — {kg_desc}\n")

        for i, result in enumerate(organic_results[:num_results], 1):
            title   = result.get("title",   "")
            snippet = result.get("snippet", "")
            link    = result.get("link",    "")
            lines.append(
                f"{i}. {title}\n   {snippet}\n   Source: {link}\n"
            )

        return "\n".join(lines) if len(lines) > 1 else ""

    except Exception as e:
        logging.error(f"SerpAPI search failed: {e}")
        return ""


# ===========================================================
#  SMART SEARCH — Google CSE first, SerpAPI fallback
# ===========================================================

def smart_search(query: str, num_results: int = 5, user_id=None) -> str:
    result = tavily_search(query, num_results, user_id=user_id)
    if result:
        logging.info("Search answered by Tavily.")
        return result
    result = google_cse_search(query, num_results)
    if result:
        logging.info("Search answered by Google CSE.")
        return result
    result = serpapi_search(query, num_results)
    if result:
        logging.info("Search answered by SerpAPI fallback.")
        return result
    logging.warning("No search engine returned results.")
    return ""


def _should_search(message: str) -> bool:
    message_lower  = message.lower()
    search_signals = [
        "search", "look up", "find", "google", "what is", "who is",
        "who are", "where is", "how to", "how do", "latest", "recent",
        "news", "today", "current", "price", "cost", "weather",
        "when is", "when was", "what happened", "tell me about",
        "definition", "meaning of", "explain", "compare",
        # STAGE 237: catch open-ended "what's happening"-style questions
        # that don't contain "latest"/"news" but clearly need live data.
        "trend", "trending", "this week", "this month", "right now",
        "happening", "update on", "what's new", "whats new",
    ]
    return any(signal in message_lower for signal in search_signals)


# ===========================================================
# GMAIL — CHAT ASSISTANT INTEGRATION (MCP-style tool context)
# Connect It already has full Gmail read/send REST integration (see the
# GMAIL ASSISTANT block further down: _gmail_headers, gmail_inbox,
# gmail_send_response) using the user's own per-user Google OAuth
# token. What was missing is wiring that into the general-purpose AI
# chat pipeline itself (generate_ai_reply/_one_round) -- this mirrors
# the existing smart_search() injection pattern above: best-effort,
# never raises, silently no-ops if Gmail isn't connected. Deliberately
# read-only from the AI's perspective -- it can draft a reply, but
# never claims to have sent one; actually sending still requires the
# user to hit Send via the existing gmail_send_response endpoint. This
# keeps a human in the loop for a real-world, irreversible action.
# ===========================================================

def _should_check_gmail(message: str) -> bool:
    message_lower = message.lower()
    gmail_signals = [
        "email", "e-mail", "inbox", "gmail", "unread", "who emailed",
        "emailed me", "check my mail", "check my email", "reply to",
        "message from", "mailbox",
    ]
    return any(signal in message_lower for signal in gmail_signals)


def _gmail_context_for_ai(user_id) -> str:
    """Best-effort recent-inbox summary for injection into the AI's
    context. Returns '' (never raises) if Gmail isn't connected, the
    user has no id, or the API call fails -- this is optional context,
    not a hard dependency of the chat turn."""
    if not user_id:
        return ""
    headers = _gmail_headers(user_id)
    if not headers:
        return ""
    try:
        list_r = requests.get(
            "https://gmail.googleapis.com/gmail/v1/users/me/messages",
            headers=headers, params={"maxResults": 8, "q": "in:inbox"}, timeout=10,
        )
        if list_r.status_code != 200:
            return ""
        lines = []
        for m in list_r.json().get("messages", [])[:8]:
            msg_r = requests.get(
                f"https://gmail.googleapis.com/gmail/v1/users/me/messages/{m['id']}",
                headers=headers,
                params={"format": "metadata", "metadataHeaders": ["From", "Subject", "Date"]},
                timeout=10,
            )
            if msg_r.status_code != 200:
                continue
            msg  = msg_r.json()
            hdrs = _gmail_decode_headers((msg.get("payload") or {}).get("headers"))
            lines.append(
                f"- From: {hdrs.get('from', '(unknown)')} | Subject: {hdrs.get('subject', '(no subject)')} "
                f"| Date: {hdrs.get('date', '')} | Snippet: {msg.get('snippet', '')}"
            )
        if not lines:
            return ""
        return (
            "[Recent Gmail inbox context, most recent first -- use this to answer the user's "
            "questions about their email. If asked to send/reply to an email, draft the content "
            "and tell the user to review and send it themselves via the Gmail Assistant panel -- "
            "never claim you have already sent an email, since you have no ability to actually do so.]\n"
            + "\n".join(lines)
        )
    except Exception as e:
        logging.error(f"[GMAIL AI CONTEXT ERROR] user={user_id}: {e}")
        return ""


# ===========================================================
# WHATSAPP — CHAT ASSISTANT INTEGRATION
# Deliberately NOT another outbound-sending integration -- this app
# already has a full WhatsApp Business Cloud API stack (opt-in widget,
# templates, catalog, flows, the webhook that auto-replies to
# customers). What's missing is letting the *business owner's own*
# Connect It assistant see and summarize those already-received
# customer conversations, the same way the Gmail integration above
# lets it see the owner's inbox. Sourced from ChatLog rows the
# whatsapp_cloud webhook already writes (see owner_user_id on ChatLog),
# not a new external API call -- there is no personal "read someone's
# WhatsApp" API to connect to; WhatsApp Business only ever sees
# messages sent to a business's own registered number.
# ===========================================================

def _should_check_whatsapp(message: str) -> bool:
    message_lower = message.lower()
    whatsapp_signals = [
        "whatsapp", "whats app", "customer message", "customer asked",
        "customer said", "who messaged", "messaged me", "wa customer",
    ]
    return any(signal in message_lower for signal in whatsapp_signals)


def _whatsapp_context_for_ai(user_id) -> str:
    """Best-effort recent-WhatsApp-conversation summary for injection
    into the AI's context. Returns '' (never raises) if there's no
    WhatsApp history for this business yet."""
    if not user_id:
        return ""
    try:
        rows = (
            ChatLog.query
            .filter(ChatLog.channel.in_(["whatsapp_cloud", "whatsapp"]), ChatLog.owner_user_id == user_id)
            .order_by(ChatLog.id.desc())
            .limit(20)
            .all()
        )
        if not rows:
            return ""
        lines = [
            f"- [{r.role}] ({r.session_id}) {r.content[:200]}"
            for r in reversed(rows)
        ]
        return (
            "[Recent WhatsApp Business conversations with your customers, oldest first -- "
            "use this to answer questions like what a customer asked about or whether "
            "someone has replied yet. 'session_id' is the customer's phone number.]\n"
            + "\n".join(lines)
        )
    except Exception as e:
        logging.error(f"[WHATSAPP AI CONTEXT ERROR] user={user_id}: {e}")
        return ""


# ===========================================================
# GOOGLE CALENDAR — CHAT ASSISTANT INTEGRATION
# Reuses the existing get_valid_calendar_token OAuth (same per-user
# Google token table as Gmail) -- mirrors the Gmail context-injection
# pattern above exactly. Read-only: schedule questions in, no ability
# to create/move/cancel events from chat.
# ===========================================================

def _should_check_calendar(message: str) -> bool:
    message_lower = message.lower()
    calendar_signals = [
        "calendar", "schedule", "meeting", "appointment", "my day",
        "today's events", "what's on", "free time", "busy", "agenda",
        "next meeting", "upcoming",
    ]
    return any(signal in message_lower for signal in calendar_signals)


def _calendar_context_for_ai(user_id) -> str:
    """Best-effort upcoming-events summary for injection into the AI's
    context. Returns '' (never raises) if Calendar isn't connected."""
    if not user_id:
        return ""
    token = get_valid_calendar_token(user_id)
    if not token:
        return ""
    try:
        resp = requests.get(
            "https://www.googleapis.com/calendar/v3/calendars/primary/events",
            headers={"Authorization": f"Bearer {token}"},
            params={
                "timeMin": datetime.utcnow().isoformat() + "Z",
                "maxResults": 10, "singleEvents": "true", "orderBy": "startTime",
            }, timeout=10,
        )
        if resp.status_code != 200:
            return ""
        items = resp.json().get("items", [])
        if not items:
            return ""
        lines = [
            f"- {e.get('summary', '(No title)')} | "
            f"{e.get('start', {}).get('dateTime') or e.get('start', {}).get('date')} "
            f"to {e.get('end', {}).get('dateTime') or e.get('end', {}).get('date')}"
            for e in items
        ]
        return (
            "[Upcoming Google Calendar events -- use this to answer scheduling "
            "questions. You cannot create, move, or cancel events yourself; tell "
            "the user to do that in the Calendar panel.]\n" + "\n".join(lines)
        )
    except Exception as e:
        logging.error(f"[CALENDAR AI CONTEXT ERROR] user={user_id}: {e}")
        return ""


# ===========================================================
# OUTLOOK MAIL — CHAT ASSISTANT INTEGRATION
# Reuses the existing Microsoft Graph OAuth (MicrosoftOAuthToken /
# get_valid_microsoft_token) already built for the outlook_inbox REST
# endpoint -- mirrors the Gmail context-injection pattern exactly.
# Deliberately gated on the SAME _should_check_gmail trigger as Gmail
# (the user just asked about "email"; whichever provider they've
# actually connected, or both, should answer) rather than a separate
# keyword set.
# ===========================================================

def _outlook_context_for_ai(user_id) -> str:
    """Best-effort recent-inbox summary for injection into the AI's
    context. Returns '' (never raises) if Outlook isn't connected."""
    if not user_id:
        return ""
    token = get_valid_microsoft_token(user_id)
    if not token:
        return ""
    try:
        resp = requests.get(
            f"{_MS_GRAPH_BASE}/me/mailFolders/inbox/messages"
            "?$top=8&$select=subject,from,bodyPreview,receivedDateTime",
            headers={"Authorization": f"Bearer {token}"}, timeout=10,
        )
        if resp.status_code != 200:
            return ""
        items = resp.json().get("value", [])
        if not items:
            return ""
        lines = [
            f"- From: {((m.get('from') or {}).get('emailAddress') or {}).get('address', '(unknown)')} "
            f"| Subject: {m.get('subject', '(no subject)')} | Received: {m.get('receivedDateTime', '')} "
            f"| Preview: {m.get('bodyPreview', '')}"
            for m in items
        ]
        return (
            "[Recent Outlook inbox context (most recent first) -- use this to answer "
            "questions about the user's email. Never claim to have sent an email yourself; "
            "if asked to send one, draft the content and tell the user to review/send it "
            "via the Outlook panel.]\n" + "\n".join(lines)
        )
    except Exception as e:
        logging.error(f"[OUTLOOK AI CONTEXT ERROR] user={user_id}: {e}")
        return ""


# ===========================================================
# AI PROVIDER HELPERS
# ===========================================================

def _ollama_call(model: str, messages: list, base_url: str | None = None, system_prompt: str | None = None) -> str | None:
    try:
        ollama_messages = [{"role": "system", "content": system_prompt or SYSTEM_PROMPT}] + [
            {"role": m["role"], "content": m["content"]} for m in messages
        ]
        payload = {
            "model":    model,
            "messages": ollama_messages,
            "stream":   False,
            "options":  {
                "num_predict": OLLAMA_MAX_TOKENS,
                "temperature": 0.9,
                "top_p":       0.95,
            }
        }
        r = requests.post(
            f"{base_url or OLLAMA_BASE_URL}/api/chat",
            json    = payload,
            timeout = 120,
        )
        if r.status_code == 200:
            return r.json().get("message", {}).get("content", "").strip()
        logging.error(f"Ollama {model} → HTTP {r.status_code}: {r.text[:200]}")
        return None
    except Exception as e:
        logging.error(f"Ollama {model} failed: {e}")
        return None


# Gemini 3.x's thinking_level replaces the old thinking_budget knob and is
# ONLY valid on Gemini 3-series models (gemini-3*) — sending it to a 2.5/2.0
# model, or sending both thinking_level and thinking_budget together, is a
# hard 400 from Google's API. Default "low" here (not the API's own default
# "high") because this call sits in the fast synchronous chat-fallback path
# (_one_round) where latency matters more than deep reasoning; callers doing
# genuinely hard analysis can still pass "high"/"medium" explicitly.
GEMINI_DEFAULT_THINKING_LEVEL = os.environ.get("GEMINI_DEFAULT_THINKING_LEVEL", "low")

def _gemini_is_v3_model(model: str) -> bool:
    return bool(re.match(r"^gemini-3", model or ""))

def _gemini_call(model: str, messages: list, api_key: str | None = None, system_prompt: str | None = None,
                  thinking_level: str | None = None) -> str | None:
    try:
        client = genai.Client(api_key=api_key) if api_key else gemini_client
        if not client:
            return None
        contents = []
        for m in messages:
            role = "user" if m["role"] == "user" else "model"
            contents.append(
                genai.types.Content(
                    role  = role,
                    parts = [genai.types.Part(text=m["content"])]
                )
            )
        config_kwargs = dict(
            system_instruction = system_prompt or SYSTEM_PROMPT,
            max_output_tokens  = GEMINI_MAX_OUTPUT_TOKENS,
            temperature        = 1.0,
            top_p              = 0.95,
        )
        # Only Gemini 3.x models accept thinking_level; older models (2.5/2.0)
        # either reject it outright or expect the legacy thinking_budget
        # shape instead, so this is deliberately gated on the model family.
        if _gemini_is_v3_model(model):
            level = (thinking_level or GEMINI_DEFAULT_THINKING_LEVEL or "low").lower()
            try:
                config_kwargs["thinking_config"] = genai.types.ThinkingConfig(thinking_level=level)
            except (AttributeError, TypeError):
                # Installed google-genai package predates ThinkingConfig/
                # thinking_level support — degrade to no thinking control
                # rather than failing the whole call over a version gap.
                logging.info(f"Gemini SDK doesn't support thinking_level; calling {model} without it.")
        try:
            response = client.models.generate_content(
                model    = model,
                contents = contents,
                config   = genai.types.GenerateContentConfig(**config_kwargs)
            )
        except TypeError as thinking_err:
            if "thinking_config" in config_kwargs:
                logging.info(f"Gemini {model} rejected thinking_config ({thinking_err}); retrying without it.")
                config_kwargs.pop("thinking_config", None)
                response = client.models.generate_content(
                    model    = model,
                    contents = contents,
                    config   = genai.types.GenerateContentConfig(**config_kwargs)
                )
            else:
                raise
        if not response or not response.text:
            logging.warning(f"Gemini {model} returned empty response.")
            return None
        return response.text.strip()

    except Exception as e:
        logging.error(f"Gemini {model} failed: {e}")
        return None


# --- Gemini native image generation (Nano Banana Pro / Nano Banana 2) ----
# Distinct from the Stage 235 Vertex AI Imagen path (Vertex needs a GCP
# project + service account; this uses the plain Gemini API key, same
# "gemini" BYOK credential the chat provider chain already uses). GA model
# IDs as of the May 28 2026 Google release: gemini-3-pro-image (Nano Banana
# Pro, reasoning-heavy, up to 4K, best for multi-image composition and
# legible in-image text) and gemini-3.1-flash-image (Nano Banana 2, the
# faster/cheaper equivalent). The old *-preview model IDs were deprecated
# June 25, 2026 — deliberately not used here.
GEMINI_IMAGE_MODEL_PRO  = os.environ.get("GEMINI_IMAGE_MODEL_PRO", "gemini-3-pro-image")
GEMINI_IMAGE_MODEL_FAST = os.environ.get("GEMINI_IMAGE_MODEL_FAST", "gemini-3.1-flash-image")

def generate_gemini_image(user_id, prompt: str, reference_images: list | None = None,
                           aspect_ratio: str = "1:1", resolution: str = "2K",
                           use_pro: bool = True) -> dict:
    """Generate (or edit/compose, if reference_images are supplied) an image
    with Gemini's native image-output models. reference_images is an
    optional list of {"bytes": <raw bytes>, "mime_type": "image/png"} dicts
    for multi-image composition/editing — Nano Banana Pro treats editing as
    a first-class operation, not a separate inpainting call.
    Returns {"ok": True, "images": [{"image_base64": "...", "mime_type": "..."}]}
    or {"ok": False, "error": "..."}."""
    if not (prompt or "").strip():
        return {"ok": False, "error": "A prompt is required."}
    api_key = get_effective_credential(user_id, "gemini", "api_key") if user_id else None
    try:
        client = genai.Client(api_key=api_key) if api_key else gemini_client
        if not client:
            return {"ok": False, "error": "Gemini is not configured. Add your Gemini API key under "
                                           "Integrations \u2192 Gemini, or ask the platform admin to set one."}
        model = GEMINI_IMAGE_MODEL_PRO if use_pro else GEMINI_IMAGE_MODEL_FAST
        parts = [genai.types.Part(text=prompt[:4000])]
        for ref in (reference_images or [])[:6]:
            if ref.get("bytes"):
                parts.append(genai.types.Part.from_bytes(
                    data=ref["bytes"], mime_type=ref.get("mime_type", "image/png")))
        image_config_kwargs = {"aspect_ratio": aspect_ratio or "1:1"}
        # imageSize/resolution is documented for the Pro model; harmless to
        # omit on Flash, but guard anyway in case an older SDK rejects it.
        if use_pro and resolution:
            image_config_kwargs["image_size"] = resolution
        try:
            image_config = genai.types.ImageConfig(**image_config_kwargs)
        except TypeError:
            image_config = genai.types.ImageConfig(aspect_ratio=aspect_ratio or "1:1")
        response = client.models.generate_content(
            model    = model,
            contents = [genai.types.Content(role="user", parts=parts)],
            config   = genai.types.GenerateContentConfig(
                response_modalities = ["IMAGE"],
                image_config        = image_config,
            ),
        )
        images = []
        for cand in (getattr(response, "candidates", None) or []):
            for part in (getattr(cand.content, "parts", None) or []):
                inline = getattr(part, "inline_data", None)
                if inline and getattr(inline, "data", None):
                    data = inline.data
                    if isinstance(data, bytes):
                        data = base64.b64encode(data).decode("ascii")
                    images.append({"image_base64": data, "mime_type": getattr(inline, "mime_type", "image/png")})
        if not images:
            return {"ok": False, "error": "Gemini returned no image — the prompt may have been blocked by safety filters."}
        return {"ok": True, "images": images, "model": model}
    except Exception as e:
        logging.error(f"[GEMINI IMAGE ERROR] user={user_id}: {e}")
        return {"ok": False, "error": str(e)}


def _openai_call(messages: list, api_key: str | None = None, system_prompt: str | None = None,
                  model: str | None = None) -> str | None:
    """Uses the Responses API, OpenAI's 2026 replacement for Chat Completions
    (Assistants API sunsets Aug 26, 2026; Responses is the recommended path
    going forward). Falls back to Chat Completions automatically if the
    installed `openai` package predates the `client.responses` surface —
    that's a version bump away, not a code change, so this avoids a hard
    break if the deployed environment hasn't updated the package yet."""
    mdl = model or OPENAI_MODEL
    try:
        client = OpenAI(api_key=api_key) if api_key else openai_client
        if not client:
            return None

        if hasattr(client, "responses"):
            response = client.responses.create(
                model              = mdl,
                instructions       = system_prompt or SYSTEM_PROMPT,
                input              = [{"role": m["role"], "content": m["content"]} for m in messages],
                max_output_tokens  = OPENAI_MAX_TOKENS,
                temperature        = 1.0,
            )
            text = getattr(response, "output_text", None)
            return text.strip() if text else None

        # Legacy SDK fallback — Chat Completions is unaffected by the
        # Responses migration and keeps working as-is.
        response = client.chat.completions.create(
            model       = mdl,
            messages    = [{"role": "system", "content": system_prompt or SYSTEM_PROMPT}] + messages,
            temperature = 1.0,
            max_tokens  = OPENAI_MAX_TOKENS,
        )
        return response.choices[0].message.content.strip()
    except Exception as e:
        logging.error(f"OpenAI {mdl} failed: {e}")
        return None


def _claude_call(model: str, messages: list, api_key: str | None = None, system_prompt: str | None = None) -> str | None:
    try:
        client = anthropic.Anthropic(api_key=api_key) if api_key else anthropic_client
        if not client:
            return None
        response = client.messages.create(
            model      = model,
            max_tokens = CLAUDE_MAX_TOKENS,
            system     = system_prompt or SYSTEM_PROMPT,
            messages   = messages,
        )
        return response.content[0].text.strip()
    except Exception as e:
        logging.error(f"Claude {model} failed: {e}")
        return None


# ===========================================================
# PROVIDER CHAIN — Claude first → Gemini → OpenAI → Ollama last
# Each step first tries the calling user's own BYOK key (if they have one
# saved for that provider) before falling back to the platform's shared key,
# so a user's own paid key is always preferred when available.
# ===========================================================

META_MODEL_BASE_URL = os.getenv("META_MODEL_BASE_URL", "https://api.llama.com/compat/v1")
META_MODEL_DEFAULT  = os.getenv("META_MODEL_DEFAULT", "Llama-4-Maverick-17B-128E-Instruct-FP8")


def _meta_model_call(messages: list, api_key: str, system_prompt: str | None = None,
                      model: str | None = None) -> str | None:
    """Meta Model API (Muse Spark), via the Chat Completions surface every
    OpenAI-SDK-compatible host supports, rather than the newer Responses API
    which isn't guaranteed outside api.openai.com itself."""
    if not api_key:
        return None
    try:
        client = OpenAI(api_key=api_key, base_url=META_MODEL_BASE_URL)
        resp = client.chat.completions.create(
            model=model or META_MODEL_DEFAULT,
            messages=[{"role": "system", "content": system_prompt or SYSTEM_PROMPT}]
                     + [{"role": m["role"], "content": m["content"]} for m in messages],
            max_tokens=OPENAI_MAX_TOKENS,
            temperature=1.0,
        )
        text = resp.choices[0].message.content if resp.choices else None
        return text.strip() if text else None
    except Exception as e:
        logging.error(f"[META MODEL API ERROR] {e}")
        return None


def _one_round(messages: list, user_id=None, system_prompt: str | None = None) -> str | None:
    byok_claude = get_effective_credential(user_id, "claude", "api_key") if user_id else None
    byok_gemini = get_effective_credential(user_id, "gemini", "api_key") if user_id else None
    byok_openai = get_effective_credential(user_id, "openai", "api_key") if user_id else None

    # 1. Claude — tried first, as the primary provider
    if anthropic_client or byok_claude:
        for model in CLAUDE_MODELS:
            result = _claude_call(model, messages, api_key=byok_claude, system_prompt=system_prompt)
            if result:
                logging.info(f"Answered by Claude ({model}){' [BYOK]' if byok_claude else ''}")
                return result

    # 2. Gemini — second in line
    if gemini_client or byok_gemini:
        for model in GEMINI_MODELS:
            result = _gemini_call(model, messages, api_key=byok_gemini, system_prompt=system_prompt)
            if result:
                logging.info(f"Answered by Gemini ({model}){' [BYOK]' if byok_gemini else ''}")
                return result

    # 3. OpenAI — third in line
    if openai_client or byok_openai:
        for model in OPENAI_MODELS:
            result = _openai_call(messages, api_key=byok_openai, system_prompt=system_prompt, model=model)
            if result:
                logging.info(f"Answered by OpenAI ({model}){' [BYOK]' if byok_openai else ''}")
                return result

    # 3b. Meta Model API (Muse Spark) — BYOK only, no platform-wide key,
    # since this is a bring-your-own-account provider, not a built-in one.
    byok_meta_model = get_effective_credential(user_id, "meta_model", "api_key") if user_id else None
    if byok_meta_model:
        result = _meta_model_call(messages, byok_meta_model, system_prompt=system_prompt,
                                   model=get_effective_credential(user_id, "meta_model", "model"))
        if result:
            logging.info("Answered by Meta Model API (Muse Spark) [BYOK]")
            return result

    # 4. Ollama — last resort / free local inference
    if OLLAMA_ENABLED:
        try:
            r        = requests.get(f"{OLLAMA_BASE_URL}/api/tags", timeout=3)
            available = [
                m["name"] for m in r.json().get("models", [])
            ] if r.status_code == 200 else []
            for model in OLLAMA_MODELS:
                matched = next(
                    (a for a in available if a.startswith(model.split(":")[0])),
                    None
                )
                if matched:
                    result = _ollama_call(matched, messages, system_prompt=system_prompt)
                    if result:
                        logging.info(f"Answered by Ollama ({matched})")
                        return result
        except Exception:
            pass

    return None


# ===========================================================
# UNLIMITED RESPONSE ENGINE
# ===========================================================

_NETWORK_ERROR_MESSAGE = (
    "Hello beautiful soul, I'm ready — but there seems to be a connection hiccup. "
    "Please hold on and resend your message. "
    "Something groundbreaking is waiting just on the other side. "
)


def _looks_complete(text: str) -> bool:
    stripped = text.rstrip()
    return not stripped or any(
        stripped.endswith(s) for s in COMPLETION_SIGNALS
    )


def _get_history(store: dict, key: str) -> list:
    history      = store.get(key, [])
    max_messages = MAX_HISTORY_TURNS * 2
    return (
        history[-max_messages:] if len(history) > max_messages else list(history)
    )


def _save_history(store: dict, key: str, history: list) -> None:
    max_messages = MAX_HISTORY_TURNS * 2
    store[key]   = (
        history[-max_messages:] if len(history) > max_messages else history
    )


def generate_ai_reply(user_message: str, history: list, user_id=None, system_prompt: str | None = None) -> tuple:
    if SMILE_AGAIN_ACTIVE_KEY:
        valid, _, reason = _validate_smile_api_key(SMILE_AGAIN_ACTIVE_KEY)
        if not valid:
            logging.warning(f"Internal key check: {reason}")

    #  Smart search injection — skipped for code/analysis tasks, which
    # supply their own focused system_prompt and don't want web search
    # results muddying a "write me this exact function" request.
    enriched_message = user_message
    if not system_prompt and _should_search(user_message):
        search_results = smart_search(user_message, user_id=user_id)
        if search_results:
            enriched_message = (
                f"{user_message}\n\n"
                f"{search_results}\n"
                f"[Use the above search results to give an accurate, current answer. "
                f"Cite sources naturally when relevant. "
                f"Do not list them robotically.]"
            )
            logging.info("Search results injected into context.")

    if not system_prompt and user_id and _should_check_gmail(user_message):
        gmail_context = _gmail_context_for_ai(user_id)
        if gmail_context:
            enriched_message = f"{enriched_message}\n\n{gmail_context}"
            logging.info("Gmail context injected.")

        outlook_context = _outlook_context_for_ai(user_id)
        if outlook_context:
            enriched_message = f"{enriched_message}\n\n{outlook_context}"
            logging.info("Outlook context injected.")

    if not system_prompt and user_id and _should_check_whatsapp(user_message):
        whatsapp_context = _whatsapp_context_for_ai(user_id)
        if whatsapp_context:
            enriched_message = f"{enriched_message}\n\n{whatsapp_context}"
            logging.info("WhatsApp context injected.")

    if not system_prompt and user_id and _should_check_calendar(user_message):
        calendar_context = _calendar_context_for_ai(user_id)
        if calendar_context:
            enriched_message = f"{enriched_message}\n\n{calendar_context}"
            logging.info("Calendar context injected.")

    working_messages    = history + [{"role": "user", "content": enriched_message}]
    full_reply_chunks: list = []
    loops = 0

    while loops < MAX_CONTINUATION_LOOPS:
        loops += 1
        logging.info(f"Generation loop {loops}/{MAX_CONTINUATION_LOOPS}")

        chunk = _one_round(working_messages, user_id=user_id, system_prompt=system_prompt)

        if not chunk:
            if not full_reply_chunks:
                logging.error("All providers failed on loop 1.")
                return _NETWORK_ERROR_MESSAGE, history
            logging.warning("Provider failed mid-continuation — returning partial.")
            break

        full_reply_chunks.append(chunk)

        if _looks_complete(chunk):
            logging.info(f"Response complete after {loops} loop(s).")
            break

        working_messages.append({"role": "assistant", "content": chunk})
        working_messages.append({
            "role":    "user",
            "content": (
                "Continue exactly where you left off. "
                "Do not repeat anything. Do not summarise. "
                "Do not reintroduce. "
                "Just keep writing seamlessly from the very last word."
            )
        })

    full_reply = "".join(full_reply_chunks).strip()

    updated_history = history + [
        {"role": "user",      "content": user_message},
        {"role": "assistant", "content": full_reply},
    ]
    max_messages = MAX_HISTORY_TURNS * 2
    if len(updated_history) > max_messages:
        updated_history = updated_history[-max_messages:]

    return full_reply, updated_history


# ===========================================================
# GOOGLE DIALOGFLOW — INTENT DETECTION
# Supports both the platform's own Dialogflow agent and a user's own
# Dialogflow project (BYOK), so multiple businesses can each run their
# own bot personality/intents on top of Connect It.
# ===========================================================

def _get_dialogflow_client_for_user(user_id=None):
    """Return (session_client, project_id, language_code) — a user's own
    Dialogflow project if they have one configured, otherwise the
    platform's shared agent."""
    if user_id:
        creds = get_user_credentials(user_id, "dialogflow")
        if creds.get("project_id") and creds.get("credentials_json"):
            try:
                creds_dict = json.loads(creds["credentials_json"])
                df_creds = DialogflowCredentials.from_service_account_info(creds_dict)
                client = dialogflow.SessionsClient(credentials=df_creds)
                return client, creds["project_id"], creds.get("language_code", "en")
            except Exception as e:
                logging.error(f"[DIALOGFLOW BYOK ERROR] user={user_id}: {e}")
    return dialogflow_session_client, DIALOGFLOW_PROJECT_ID, DIALOGFLOW_LANGUAGE_CODE


def detect_dialogflow_intent(session_id: str, text: str, user_id=None, language_code: str | None = None) -> dict:
    """Send text to Dialogflow and return the matched intent, confidence,
    fulfillment text, and any extracted parameters. Returns an 'ok': False
    dict (never raises) if Dialogflow isn't configured or the call fails."""
    if not DIALOGFLOW_AVAILABLE:
        return {"ok": False, "error": "google-cloud-dialogflow is not installed."}

    client, project_id, default_lang = _get_dialogflow_client_for_user(user_id)
    if not client or not project_id:
        return {"ok": False, "error": "Dialogflow is not configured."}

    try:
        session_path = client.session_path(project_id, session_id or "default-session")
        text_input   = dialogflow.TextInput(text=text, language_code=language_code or default_lang)
        query_input  = dialogflow.QueryInput(text=text_input)
        response = client.detect_intent(
            request={"session": session_path, "query_input": query_input}
        )
        result = response.query_result
        return {
            "ok":                True,
            "intent":            result.intent.display_name if result.intent else None,
            "confidence":        round(result.intent_detection_confidence, 3),
            "fulfillment_text":  result.fulfillment_text,
            "parameters":        dict(result.parameters) if result.parameters else {},
            "action":            result.action,
            "all_required_params_present": result.all_required_params_present,
        }
    except Exception as e:
        logging.error(f"[DIALOGFLOW DETECT ERROR] {e}")
        return {"ok": False, "error": str(e)}




# ===========================================================
# TWILIO / WHATSAPP BUSINESS — PER-USER (BYOK)
# A business on Connect It can plug in their own Twilio account (or their
# own WhatsApp Business number routed through Twilio) so messages send
# from THEIR number and bill to THEIR Twilio account, not the platform's.
# ===========================================================

def get_twilio_client_for_user(user_id=None):
    """Return (client, whatsapp_from_number, sms_from_number). Falls back to
    the platform's shared Twilio account when the user has no BYOK creds."""
    if user_id:
        byok = get_user_credentials(user_id, "twilio") or get_user_credentials(user_id, "whatsapp_business")
        if byok.get("account_sid") and byok.get("auth_token"):
            try:
                client = TwilioClient(byok["account_sid"], byok["auth_token"])
                return (
                    client,
                    byok.get("whatsapp_number", TWILIO_WHATSAPP_NUMBER),
                    byok.get("sms_number", TWILIO_PHONE_NUMBER),
                )
            except Exception as e:
                logging.error(f"[TWILIO BYOK ERROR] user={user_id}: {e}")
    return twilio_client, TWILIO_WHATSAPP_NUMBER, TWILIO_PHONE_NUMBER


def _find_user_for_twilio_whatsapp_number(to_number: str):
    """FIX: the inbound Twilio webhook is one shared URL for every business
    that has plugged in their own Twilio WhatsApp number (BYOK), but nothing
    previously looked up which business's number actually received the
    message -- so those conversations had no owner and were invisible to
    the business's own AI assistant / the list_whatsapp_conversations MCP
    tool. Mirrors _find_user_for_whatsapp_cloud_phone. Returns None (falls
    back to the platform's shared/demo number, unscoped as before) if no
    BYOK match."""
    digits = re.sub(r"\D", "", (to_number or "").replace("whatsapp:", ""))
    if not digits:
        return None
    try:
        rows = UserIntegration.query.filter(
            UserIntegration.provider.in_(["twilio", "whatsapp_business"]),
            UserIntegration.active == True,
        ).all()
        for row in rows:
            creds = decrypt_secret_blob(row.credentials_encrypted)
            configured = re.sub(r"\D", "", (creds.get("whatsapp_number") or "").replace("whatsapp:", ""))
            if configured and configured == digits:
                return row.user_id
    except Exception as e:
        logging.error(f"[TWILIO WA USER LOOKUP ERROR] {e}")
    return None


# ===========================================================
# TWILIO SPLITTER
# ===========================================================

def _split_into_twilio_chunks(text: str, limit: int = 1600) -> list:
    chunks = []
    while len(text) > limit:
        split_at = limit
        for punct in (". ", "! ", "? ", "\n"):
            idx = text.rfind(punct, 0, limit)
            if idx != -1:
                split_at = idx + len(punct)
                break
        chunks.append(text[:split_at].strip())
        text = text[split_at:].strip()
    if text:
        chunks.append(text)
    return chunks


# ===========================================================
#  MEDIA GENERATION HELPERS
# ===========================================================

def _upload_to_cloudinary(
    file_url:      str   = None,
    file_bytes:    bytes = None,
    resource_type: str   = "image",
    folder:        str   = "connect it",
) -> str | None:
    if not cloudinary_enabled:
        return file_url
    try:
        import cloudinary.uploader
        if file_url:
            result = cloudinary.uploader.upload(
                file_url,
                resource_type = resource_type,
                folder        = folder,
            )
        elif file_bytes:
            result = cloudinary.uploader.upload(
                file_bytes,
                resource_type = resource_type,
                folder        = folder,
            )
        else:
            return None
        return result.get("secure_url")
    except Exception as e:
        logging.error(f"Cloudinary upload failed: {e}")
        return file_url


def _replicate_run(
    model:         str,
    input_data:    dict,
    poll_interval: int = 3,
    max_wait:      int = 300,
) -> dict:
    if not REPLICATE_API_KEY:
        return {"status": "error", "error": "Replicate API key not configured."}

    headers = {
        "Authorization": f"Token {REPLICATE_API_KEY}",
        "Content-Type":  "application/json",
    }
    try:
        r = requests.post(
            "https://api.replicate.com/v1/predictions",
            headers = headers,
            json    = {"version": model, "input": input_data},
            timeout = 30,
        )
        if r.status_code not in (200, 201):
            return {
                "status": "error",
                "error":  f"Replicate start failed: {r.text[:300]}"
            }
        prediction = r.json()
        poll_url   = prediction.get("urls", {}).get("get")
        if not poll_url:
            return {"status": "error", "error": "No polling URL returned."}

    except Exception as e:
        return {"status": "error", "error": str(e)}

    elapsed = 0
    while elapsed < max_wait:
        try:
            poll   = requests.get(poll_url, headers=headers, timeout=15)
            data   = poll.json()
            status = data.get("status")
            if status == "succeeded":
                return {"status": "succeeded", "output": data.get("output")}
            elif status in ("failed", "canceled"):
                return {
                    "status": "error",
                    "error":  data.get("error", "Generation failed.")
                }
            time.sleep(poll_interval)
            elapsed += poll_interval
        except Exception as e:
            return {"status": "error", "error": str(e)}

    return {"status": "error", "error": "Generation timed out."}


def _veed_create_render(
    elements:      list,
    poll_interval: int = 4,
    max_wait:      int = 240,
) -> dict:
    """
    Submits a render job to VEED's Renders API and polls until it
    completes. `elements` follows VEED's render-object schema (a list of
    {"type": "image"/"video"/"text"/"audio", "params": {...}} layers).
    Docs: https://documentation.veed.io/docs/making-first-render

    NOTE: VEED's exact terminal status strings and result-field name
    aren't fully confirmed here — this checks a few plausible variants
    defensively. If VEED changes its response shape, adjust
    _DONE_STATUSES / _FAILED_STATUSES / the result-url lookup below
    against the current docs before relying on this in production.
    """
    if not VEED_API_KEY:
        return {"status": "error", "error": "VEED API key not configured."}

    headers = {
        "Authorization": VEED_API_KEY,
        "Content-Type":  "application/json",
    }
    try:
        r = requests.post(
            f"{VEED_API_BASE}/api/renders",
            headers = headers,
            json    = {"elements": elements},
            timeout = 30,
        )
        if r.status_code not in (200, 201):
            return {
                "status": "error",
                "error":  f"VEED render request failed: {r.text[:300]}"
            }
        job     = r.json()
        job_id  = job.get("id") or job.get("job_id") or job.get("renderId")
        if not job_id:
            return {"status": "error", "error": "No render id returned by VEED."}
    except Exception as e:
        return {"status": "error", "error": str(e)}

    _DONE_STATUSES   = {"finished", "completed", "done", "succeeded", "ready"}
    _FAILED_STATUSES = {"failed", "error", "cancelled", "canceled"}

    elapsed = 0
    while elapsed < max_wait:
        try:
            poll   = requests.get(
                f"{VEED_API_BASE}/api/renders/{job_id}",
                headers = headers, timeout = 15,
            )
            data   = poll.json()
            status = str(data.get("status", "")).lower()

            if status in _DONE_STATUSES:
                video_url = (
                    data.get("url") or data.get("output_url")
                    or data.get("result", {}).get("url")
                    or data.get("download_url")
                )
                if video_url:
                    return {"status": "succeeded", "output": video_url}
                return {"status": "error", "error": "VEED finished but returned no video URL."}

            if status in _FAILED_STATUSES:
                return {
                    "status": "error",
                    "error":  data.get("error", "VEED render failed."),
                }

            time.sleep(poll_interval)
            elapsed += poll_interval
        except Exception as e:
            return {"status": "error", "error": str(e)}

    return {"status": "error", "error": "VEED render timed out.", "job_id": job_id}


def _stability_generate_image(
    prompt:          str,
    negative_prompt: str = "",
    width:           int = 1024,
    height:          int = 1024,
    style:           str = "photographic",
) -> dict:
    if not STABILITY_API_KEY:
        return {"status": "error", "error": "Stability AI key not configured."}
    try:
        r = requests.post(
            "https://api.stability.ai/v1/generation/"
            "stable-diffusion-xl-1024-v1-0/text-to-image",
            headers = {
                "Authorization": f"Bearer {STABILITY_API_KEY}",
                "Content-Type":  "application/json",
                "Accept":        "application/json",
            },
            json = {
                "text_prompts": [
                    {"text": prompt,          "weight":  1.0},
                    {"text": negative_prompt, "weight": -1.0},
                ],
                "cfg_scale":    7,
                "width":        width,
                "height":       height,
                "samples":      1,
                "steps":        30,
                "style_preset": style,
            },
            timeout = 60,
        )
        if r.status_code != 200:
            return {"status": "error", "error": f"Stability error: {r.text[:300]}"}
        image_b64 = r.json()["artifacts"][0]["base64"]
        return {"status": "succeeded", "image_b64": image_b64}
    except Exception as e:
        return {"status": "error", "error": str(e)}


