@app.route("/api/media/image/generate", methods=["POST"])
@csrf.exempt
def image_generate_endpoint():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403

    user = _get_current_user()
    blocked = gate_ai_usage(user, "image_generate", byok_provider="openai")
    if blocked: return blocked

    data            = request.get_json() or {}
    prompt          = data.get("prompt", "").strip()
    negative_prompt = data.get("negative_prompt", "blurry, low quality, watermark")
    style           = data.get("style", "photographic")
    width           = int(data.get("width",  1024))
    height          = int(data.get("height", 1024))
    engine          = data.get("engine", "stability")

    if not prompt:
        return jsonify({"error": "prompt field is required."}), 400

    enhanced_prompt, _ = generate_ai_reply(
        f"Enhance this image generation prompt to be more vivid, "
        f"detailed and cinematic. Return ONLY the enhanced prompt: {prompt}",
        []
    )

    if engine == "dalle" and openai_client:
        try:
            response  = openai_client.images.generate(
                model   = "dall-e-3",
                prompt  = enhanced_prompt,
                size    = (
                    f"{width}x{height}"
                    if f"{width}x{height}" in
                    ["1024x1024", "1792x1024", "1024x1792"]
                    else "1024x1024"
                ),
                quality = "hd",
                n       = 1,
            )
            image_url = response.data[0].url
            final_url = _upload_to_cloudinary(
                file_url=image_url, resource_type="image"
            )
            return jsonify({
                "status":          "succeeded",
                "image_url":       final_url,
                "original_prompt": prompt,
                "enhanced_prompt": enhanced_prompt,
                "engine":          "DALL-E 3",
                "powered_by":      "Connect It",
            }), 200
        except Exception as e:
            logging.error(f"DALL-E generation failed: {e}")

    elif engine == "replicate" and REPLICATE_API_KEY:
        result = _replicate_run(
            model      = "black-forest-labs/flux-schnell",
            input_data = {
                "prompt":         enhanced_prompt,
                "num_outputs":    1,
                "aspect_ratio":   "1:1",
                "output_format":  "webp",
                "output_quality": 90,
            }
        )
        if result["status"] == "succeeded":
            output    = result["output"]
            image_url = output[0] if isinstance(output, list) else output
            final_url = _upload_to_cloudinary(
                file_url=image_url, resource_type="image"
            )
            return jsonify({
                "status":          "succeeded",
                "image_url":       final_url,
                "original_prompt": prompt,
                "enhanced_prompt": enhanced_prompt,
                "engine":          "Flux Schnell",
                "powered_by":      "Connect It",
            }), 200
        return jsonify({"status": "error", "error": result.get("error")}), 500

    else:
        result = _stability_generate_image(
            prompt          = enhanced_prompt,
            negative_prompt = negative_prompt,
            width           = width,
            height          = height,
            style           = style,
        )
        if result["status"] == "succeeded":
            img_bytes = base64.b64decode(result["image_b64"])
            final_url = _upload_to_cloudinary(
                file_bytes=img_bytes, resource_type="image"
            )
            return jsonify({
                "status":          "succeeded",
                "image_url":       final_url,
                "image_b64":       result["image_b64"] if not cloudinary_enabled else None,
                "original_prompt": prompt,
                "enhanced_prompt": enhanced_prompt,
                "engine":          "Stability AI SDXL",
                "powered_by":      "Connect It",
            }), 200
        return jsonify({"status": "error", "error": result.get("error")}), 500


