@app.route("/api/media/ad/create", methods=["POST"])
@csrf.exempt
def ad_create_endpoint():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    gate_result = gate_ai_usage(user, "ad_create_endpoint")
    if gate_result is not None:
        return gate_result

    data            = request.get_json() or {}
    product         = data.get("product",  "").strip()
    audience        = data.get("audience", "").strip()
    duration        = data.get("duration", "30 seconds")
    platform        = data.get("platform", "social media")
    tone            = data.get("tone",     "exciting")
    usp             = data.get("usp",      "").strip()
    cta             = data.get("cta",      "Learn more").strip()
    generate_video  = data.get("generate_video", False)
    # A real video needs a visual layer to animate/overlay text on, so
    # requesting a video implicitly requests the key visual image too.
    generate_visual = data.get("generate_visual", False) or generate_video

    if not product:
        return jsonify({"error": "product field is required."}), 400

    script_prompt = (
        f"You are a world-class advertising creative director. "
        f"Create a complete {duration} video ad for: {product}.\n"
        f"Platform: {platform}\n"
        f"Target audience: {audience or 'general consumers'}\n"
        f"Tone: {tone}\n\n"
        f"Deliver:\n"
        f"1. AD CONCEPT\n2. HOOK\n3. FULL SCRIPT\n"
        f"4. SCENE DESCRIPTIONS\n5. VISUAL STYLE\n"
        f"6. MUSIC BRIEF\n7. CALL TO ACTION\n"
        f"8. IMAGE GENERATION PROMPT"
    )

    script_raw, _ = generate_ai_reply(script_prompt, [])
    script_html   = format_ai_response(script_raw)

    response_data = {
        "status":     "succeeded",
        "ad_script":  script_html,
        "ad_text":    script_raw,
        "product":    product,
        "platform":   platform,
        "duration":   duration,
        "powered_by": "Connect It",
    }

    if generate_visual and (STABILITY_API_KEY or REPLICATE_API_KEY or openai_client):
        image_prompt = product + " advertisement, professional, cinematic, high quality"
        lines = script_raw.split("\n")
        for i, line in enumerate(lines):
            if "IMAGE GENERATION PROMPT" in line.upper() and i + 1 < len(lines):
                image_prompt = lines[i + 1].strip()
                break

        if openai_client:
            try:
                img_response = openai_client.images.generate(
                    model   = "dall-e-3",
                    prompt  = image_prompt,
                    size    = "1792x1024",
                    quality = "hd",
                    n       = 1,
                )
                img_url   = img_response.data[0].url
                final_url = _upload_to_cloudinary(
                    file_url=img_url, resource_type="image"
                )
                response_data["key_visual_url"] = final_url
                response_data["image_prompt"]   = image_prompt
            except Exception as e:
                logging.error(f"Ad image generation failed: {e}")

    # --- VEED.io: render the key visual + script highlights into a
    # real MP4 ad, instead of leaving it as script + still image. ---
    if generate_video:
        if not VEED_API_KEY:
            response_data["video_status"] = "skipped"
            response_data["video_note"] = (
                "Video rendering requires a VEED_API_KEY in your .env "
                "(get one at https://www.veed.io/api). Script and key "
                "visual were still generated above."
            )
        elif not response_data.get("key_visual_url"):
            response_data["video_status"] = "skipped"
            response_data["video_note"] = (
                "No key visual was generated (image API key missing), "
                "so there was nothing for VEED to render into a video."
            )
        else:
            try:
                secs_match = re.search(r"\d+", str(duration))
                seconds    = int(secs_match.group()) if secs_match else 15
                seconds    = max(5, min(seconds, 60))  # sane clamp

                hook_line = ""
                for line in script_raw.split("\n"):
                    if "HOOK" in line.upper():
                        idx = script_raw.split("\n").index(line)
                        rest = script_raw.split("\n")[idx + 1:idx + 2]
                        hook_line = rest[0].strip() if rest else ""
                        break

                elements = [
                    {
                        "type": "image",
                        "params": {
                            "source":   {"url": response_data["key_visual_url"]},
                            "duration": seconds,
                            "fit":      "cover",
                        },
                    },
                    {
                        "type": "text",
                        "params": {
                            "value":    hook_line or product,
                            "position": {"x": "center", "y": "top"},
                            "duration": seconds,
                        },
                    },
                    {
                        "type": "text",
                        "params": {
                            "value":    cta or "Learn more",
                            "position": {"x": "center", "y": "bottom"},
                            "duration": seconds,
                        },
                    },
                ]

                veed_result = _veed_create_render(elements, max_wait=240)
                if veed_result["status"] == "succeeded":
                    response_data["ad_video_url"] = veed_result["output"]
                    response_data["video_status"] = "succeeded"
                else:
                    response_data["video_status"] = "error"
                    response_data["video_note"]   = veed_result.get("error", "Video render failed.")
            except Exception as e:
                logging.error(f"VEED ad render failed: {e}")
                response_data["video_status"] = "error"
                response_data["video_note"]   = str(e)

    return jsonify(response_data), 200


