# The frontend renders Google's Identity Services button, gets back a
# signed ID token (a JWT), and POSTs it here as {"credential": "..."}.
# We verify it against GOOGLE_OAUTH_CLIENT_ID, then either log the
# matching user in or create a brand-new account. Email/password signup
# and login are untouched — this is an alternative, not a replacement.
@app.route("/api/auth/google", methods=["POST"])
@csrf.exempt
def google_auth_endpoint():
    if not GOOGLE_SIGNIN_AVAILABLE:
        return jsonify({"error": "google-auth is not installed on the server. Run: pip install google-auth"}), 503
    if not GOOGLE_OAUTH_CLIENT_ID:
        return jsonify({"error": "Google Sign-In is not configured. Set GOOGLE_OAUTH_CLIENT_ID."}), 503

    data       = request.get_json(silent=True) or {}
    credential = data.get("credential") or data.get("id_token")
    if not credential:
        return jsonify({"error": "'credential' (the Google ID token) is required."}), 400

    try:
        claims = google_id_token.verify_oauth2_token(
            credential, google_auth_requests.Request(), GOOGLE_OAUTH_CLIENT_ID
        )
    except Exception as e:
        logging.warning(f"[GOOGLE SIGN-IN] token verification failed: {e}")
        return jsonify({"error": "Invalid or expired Google credential."}), 401

    google_sub   = claims.get("sub")
    email        = (claims.get("email") or "").strip().lower()
    name         = claims.get("name") or (email.split("@")[0] if email else "Connect It User")
    email_verified_by_google = bool(claims.get("email_verified"))

    if not google_sub or not email:
        return jsonify({"error": "Google did not return the expected profile fields."}), 400

    try:
        user = UserAccount.query.filter(
            (UserAccount.google_id == google_sub) | (UserAccount.email == email)
        ).first()

        if user:
            # Existing account (possibly created via email/password) —
            # link the Google identity to it if not already linked.
            if not user.google_id:
                user.google_id = google_sub
            if email_verified_by_google and not user.email_verified:
                user.email_verified = True
            user.last_login = datetime.utcnow()
            db.session.commit()
            message = f"Welcome back, {user.name}! "
            status_code = 200
        else:
            # Brand-new account via Google. A random, never-shown password
            # is set so password_hash can stay NOT NULL — this user simply
            # always signs in with the Google button, not a password.
            user = UserAccount(
                name=name, email=email, plan="free",
                google_id=google_sub, auth_provider="google",
                email_verified=email_verified_by_google,
            )
            user.set_password(secrets.token_urlsafe(32))
            db.session.add(user)
            db.session.commit()
            logging.info(f"New user signed up via Google: {email}")
            message = f"Welcome to Connect It, {user.name}! "
            status_code = 201
    except Exception as e:
        db.session.rollback()
        logging.error(f"[GOOGLE SIGN-IN ERROR] {e}")
        return jsonify({"error": "Could not complete Google sign-in. Please try again."}), 500

    _sync_admin_from_email(user)

    session["user_id"]    = user.id
    session["user_name"]  = user.name
    session["user_email"] = user.email
    session["user_plan"]  = user.plan

    token = _issue_auth_token(user)

    return jsonify({
        "message":    message,
        "user":       user.to_dict(),
        "token":      token,
        "powered_by": "Smile Again API",
    }), status_code


@app.route("/api/auth/microsoft", methods=["POST"])
@csrf.exempt
def microsoft_auth_endpoint():
    """STAGE 184: Sign in with Microsoft — verifies the id_token the
    frontend's MSAL.js popup hands us against Microsoft's own public
    signing keys (fetched live from their JWKS endpoint), the same way
    the Google Sign-In route above verifies Google's token. Real
    signature + issuer + audience verification, not a trust-the-frontend
    shortcut."""
    if not JWT_AVAILABLE:
        return jsonify({"error": "PyJWT is not installed on the server. Run: pip install PyJWT"}), 503
    if not MICROSOFT_OAUTH_CLIENT_ID:
        return jsonify({"error": "Sign in with Microsoft is not configured. Set MICROSOFT_OAUTH_CLIENT_ID."}), 503

    data       = request.get_json(silent=True) or {}
    credential = data.get("credential") or data.get("id_token")
    if not credential:
        return jsonify({"error": "'credential' (the Microsoft ID token) is required."}), 400

    try:
        jwks_client = jwt.PyJWKClient(
            f"https://login.microsoftonline.com/{MICROSOFT_OAUTH_TENANT}/discovery/v2.0/keys"
        )
        signing_key = jwks_client.get_signing_key_from_jwt(credential)
        claims = jwt.decode(
            credential, signing_key.key, algorithms=["RS256"],
            audience=MICROSOFT_OAUTH_CLIENT_ID,
            options={"verify_iss": False},  # issuer varies per Microsoft tenant; aud+signature already prove it's really Microsoft
        )
    except Exception as e:
        logging.warning(f"[MICROSOFT SIGN-IN] token verification failed: {e}")
        return jsonify({"error": "Invalid or expired Microsoft credential."}), 401

    ms_oid = claims.get("oid") or claims.get("sub")
    email  = (claims.get("email") or claims.get("preferred_username") or "").strip().lower()
    name   = claims.get("name") or (email.split("@")[0] if email else "Connect It User")

    if not ms_oid or not email:
        return jsonify({"error": "Microsoft did not return the expected profile fields."}), 400

    try:
        user = UserAccount.query.filter(
            (UserAccount.microsoft_id == ms_oid) | (UserAccount.email == email)
        ).first()

        if user:
            if not user.microsoft_id:
                user.microsoft_id = ms_oid
            user.last_login = datetime.utcnow()
            db.session.commit()
            message = f"Welcome back, {user.name}! "
            status_code = 200
        else:
            user = UserAccount(
                name=name, email=email, plan="free",
                microsoft_id=ms_oid, auth_provider="microsoft",
                email_verified=True,  # Microsoft work/school/personal accounts are already verified
            )
            user.set_password(secrets.token_urlsafe(32))
            db.session.add(user)
            db.session.commit()
            logging.info(f"New user signed up via Microsoft: {email}")
            message = f"Welcome to Connect It, {user.name}! "
            status_code = 201
    except Exception as e:
        db.session.rollback()
        logging.error(f"[MICROSOFT SIGN-IN ERROR] {e}")
        return jsonify({"error": "Could not complete Microsoft sign-in. Please try again."}), 500

    _sync_admin_from_email(user)
    session["user_id"]    = user.id
    session["user_name"]  = user.name
    session["user_email"] = user.email
    session["user_plan"]  = user.plan
    token = _issue_auth_token(user)

    return jsonify({
        "message": message, "user": user.to_dict(), "token": token,
        "powered_by": "Smile Again API",
    }), status_code


# ════════════════════════════════════════════════════════════
# STAGE 185: ENTERPRISE SSO — SAML 2.0
# Real SP (Service Provider) implementation via python3-saml. A business
# owner configures their own IdP once; from then on, anyone with an email
# on that domain can sign in through the company's own identity provider
# instead of a Connect It password. Nothing here is simulated — a
# misconfigured IdP will fail to validate, exactly like a real SP should.
# ════════════════════════════════════════════════════════════

def _saml_settings_for_domain(cfg: "OrgSsoConfig", base_url: str) -> dict:
    return {
        "strict": True,
        "debug": False,
        "sp": {
            "entityId": f"{base_url}/sso/saml/metadata",
            "assertionConsumerService": {
                "url": f"{base_url}/sso/saml/acs",
                "binding": "urn:oasis:names:tc:SAML:2.0:bindings:HTTP-POST",
            },
            "singleLogoutService": {
                "url": f"{base_url}/sso/saml/slo",
                "binding": "urn:oasis:names:tc:SAML:2.0:bindings:HTTP-Redirect",
            },
            "NameIDFormat": "urn:oasis:names:tc:SAML:1.1:nameid-format:emailAddress",
        },
        "idp": {
            "entityId": cfg.idp_entity_id,
            "singleSignOnService": {
                "url": cfg.idp_sso_url,
                "binding": "urn:oasis:names:tc:SAML:2.0:bindings:HTTP-Redirect",
            },
            "singleLogoutService": {
                "url": cfg.idp_slo_url or cfg.idp_sso_url,
                "binding": "urn:oasis:names:tc:SAML:2.0:bindings:HTTP-Redirect",
            },
            "x509cert": cfg.idp_x509cert,
        },
    }


def _saml_prepare_flask_request():
    return {
        "https": "on" if request.scheme == "https" else "off",
        "http_host": request.host,
        "script_name": request.path,
        "get_data": request.args.copy(),
        "post_data": request.form.copy(),
    }


def _oidc_discover(issuer: str) -> tuple[dict | None, str | None]:
    """Fetches the IdP's /.well-known/openid-configuration document and
    pulls out the four endpoints Connect It's SP flow needs. Returns
    (endpoints_dict, None) on success or (None, error_message) — a
    business owner only has to paste the issuer URL, not hand-copy four
    separate endpoint URLs from their IdP's docs the way SAML metadata
    has to be pasted today."""
    issuer = (issuer or "").strip().rstrip("/")
    if not issuer.startswith("https://"):
        return None, "The issuer URL must start with https://."
    try:
        r = requests.get(f"{issuer}/.well-known/openid-configuration", timeout=10)
        if r.status_code >= 400:
            return None, f"Could not fetch OIDC discovery document from {issuer} (HTTP {r.status_code})."
        doc = r.json()
    except Exception as e:
        return None, f"Could not reach {issuer}/.well-known/openid-configuration: {e}"
    auth_ep  = doc.get("authorization_endpoint")
    token_ep = doc.get("token_endpoint")
    jwks_uri = doc.get("jwks_uri")
    if not auth_ep or not token_ep or not jwks_uri:
        return None, "The issuer's discovery document is missing authorization_endpoint, token_endpoint, or jwks_uri."
    return {
        "authorization_endpoint": auth_ep, "token_endpoint": token_ep,
        "jwks_uri": jwks_uri, "userinfo_endpoint": doc.get("userinfo_endpoint"),
        "issuer": doc.get("issuer") or issuer,
    }, None


@app.route("/api/auth/sso/config", methods=["GET"])
def sso_config_get():
    """The signed-in business owner views their own SSO setup (secrets masked)."""
    user, err = _erp_user_or_401()
    if err: return err
    cfg = OrgSsoConfig.query.filter_by(owner_user_id=user["id"]).first()
    return jsonify({"config": cfg.to_dict() if cfg else None}), 200


@app.route("/api/auth/sso/config", methods=["POST"])
@csrf.exempt
def sso_config_save():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    blocked = require_plan(user, "sso")
    if blocked: return blocked
    data = request.get_json(silent=True) or {}
    domain   = (data.get("domain") or "").strip().lower().lstrip("@")
    protocol = (data.get("protocol") or "saml").strip().lower()
    auto_provision = bool(data.get("auto_provision", True))

    if not domain or "." not in domain:
        return jsonify({"error": "A valid company domain (e.g. acmecorp.com) is required."}), 400
    if protocol not in ("saml", "oidc"):
        return jsonify({"error": "protocol must be 'saml' or 'oidc'."}), 400

    existing_domain = OrgSsoConfig.query.filter(
        OrgSsoConfig.domain == domain, OrgSsoConfig.owner_user_id != user["id"]
    ).first()
    if existing_domain:
        return jsonify({"error": "That domain is already configured for SSO by another account."}), 409

    cfg = OrgSsoConfig.query.filter_by(owner_user_id=user["id"]).first()

    if protocol == "saml":
        if not SAML_AVAILABLE:
            return jsonify({"error": "SAML support isn't available on this server (python3-saml not installed)."}), 503
        idp_entity_id = (data.get("idp_entity_id") or "").strip()
        idp_sso_url   = (data.get("idp_sso_url") or "").strip()
        idp_x509cert  = (data.get("idp_x509cert") or "").strip()
        idp_slo_url   = (data.get("idp_slo_url") or "").strip()
        if not idp_entity_id or not idp_sso_url or not idp_x509cert:
            return jsonify({"error": "idp_entity_id, idp_sso_url, and idp_x509cert (from your IdP's app config) are all required for SAML."}), 400
        if not cfg:
            cfg = OrgSsoConfig(owner_user_id=user["id"])
            db.session.add(cfg)
        cfg.domain = domain
        cfg.protocol = "saml"
        cfg.idp_entity_id = idp_entity_id
        cfg.idp_sso_url = idp_sso_url
        cfg.idp_x509cert = idp_x509cert
        cfg.idp_slo_url = idp_slo_url or None
        cfg.auto_provision = auto_provision
        cfg.enabled = True
        db.session.commit()
        return jsonify({"config": cfg.to_dict(), "sp_metadata_url": f"{APP_BASE_URL}/sso/saml/metadata"}), 200

    # protocol == "oidc"
    if not JWT_AVAILABLE:
        return jsonify({"error": "OIDC support isn't available on this server (PyJWT not installed)."}), 503
    oidc_issuer        = (data.get("oidc_issuer") or "").strip()
    oidc_client_id     = (data.get("oidc_client_id") or "").strip()
    oidc_client_secret = (data.get("oidc_client_secret") or "").strip()
    if not oidc_issuer or not oidc_client_id or not oidc_client_secret:
        return jsonify({"error": "oidc_issuer, oidc_client_id, and oidc_client_secret (from your IdP's app registration) are all required for OIDC."}), 400

    endpoints, disc_err = _oidc_discover(oidc_issuer)
    if disc_err:
        return jsonify({"error": disc_err}), 400

    if not cfg:
        cfg = OrgSsoConfig(owner_user_id=user["id"])
        db.session.add(cfg)
    cfg.domain = domain
    cfg.protocol = "oidc"
    cfg.oidc_issuer = endpoints["issuer"]
    cfg.oidc_client_id = oidc_client_id
    cfg.oidc_client_secret = oidc_client_secret
    cfg.oidc_authorization_endpoint = endpoints["authorization_endpoint"]
    cfg.oidc_token_endpoint = endpoints["token_endpoint"]
    cfg.oidc_jwks_uri = endpoints["jwks_uri"]
    cfg.oidc_userinfo_endpoint = endpoints.get("userinfo_endpoint")
    cfg.auto_provision = auto_provision
    cfg.enabled = True
    db.session.commit()
    return jsonify({"config": cfg.to_dict(), "redirect_uri": f"{APP_BASE_URL}/sso/oidc/callback"}), 200


@app.route("/api/auth/sso/config", methods=["DELETE"])
@csrf.exempt
def sso_config_delete():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    cfg = OrgSsoConfig.query.filter_by(owner_user_id=user["id"]).first()
    if cfg:
        db.session.delete(cfg)
        db.session.commit()
    return jsonify({"ok": True}), 200


@app.route("/sso/saml/metadata", methods=["GET"])
def sso_saml_metadata():
    """Our fixed SP metadata — the business's IdP admin uploads/points to
    this URL when adding Connect It as an application in their IdP."""
    if not SAML_AVAILABLE:
        return jsonify({"error": "SAML support isn't available on this server (python3-saml not installed)."}), 503
    placeholder_cfg = OrgSsoConfig(idp_entity_id="placeholder", idp_sso_url=f"{APP_BASE_URL}/sso/saml/login", idp_x509cert="")
    settings = OneLogin_Saml2_Settings(_saml_settings_for_domain(placeholder_cfg, APP_BASE_URL), sp_validation_only=True)
    metadata = settings.get_sp_metadata()
    errors = settings.validate_metadata(metadata)
    if errors:
        return jsonify({"error": "Could not generate valid SP metadata: " + ", ".join(errors)}), 500
    return Response(metadata, mimetype="text/xml")


@app.route("/sso/saml/login", methods=["GET"])
def sso_saml_login():
    """SP-initiated login: given ?domain=acmecorp.com, redirects to that
    business's own configured IdP to authenticate."""
    if not SAML_AVAILABLE:
        return "SAML support isn't available on this server (python3-saml not installed).", 503
    domain = (request.args.get("domain") or "").strip().lower().lstrip("@")
    cfg = OrgSsoConfig.query.filter_by(domain=domain, enabled=True).first()
    if not cfg:
        return jsonify({"error": f"No SSO is configured for '{domain}'."}), 404
    req = _saml_prepare_flask_request()
    auth = OneLogin_Saml2_Auth(req, _saml_settings_for_domain(cfg, APP_BASE_URL))
    return redirect(auth.login(return_to=domain))


@app.route("/sso/saml/acs", methods=["POST"])
@csrf.exempt
def sso_saml_acs():
    """Assertion Consumer Service — the IdP POSTs the SAML assertion here
    after the user authenticates on the IdP's own site. RelayState carries
    back which domain/config to validate against."""
    if not SAML_AVAILABLE:
        return "SAML support isn't available on this server (python3-saml not installed).", 503
    domain = (request.form.get("RelayState") or "").strip().lower()
    cfg = OrgSsoConfig.query.filter_by(domain=domain, enabled=True).first()
    if not cfg:
        return jsonify({"error": f"No SSO is configured for '{domain}'."}), 404

    req = _saml_prepare_flask_request()
    auth = OneLogin_Saml2_Auth(req, _saml_settings_for_domain(cfg, APP_BASE_URL))
    auth.process_response()
    errors = auth.get_errors()
    if errors:
        logging.warning(f"[SAML SSO] validation failed for domain={domain}: {errors} — {auth.get_last_error_reason()}")
        return jsonify({"error": "SSO sign-in failed: " + auth.get_last_error_reason()}), 401
    if not auth.is_authenticated():
        return jsonify({"error": "SSO assertion was not authenticated."}), 401

    email = (auth.get_nameid() or "").strip().lower()
    attrs = auth.get_attributes() or {}
    name = None
    for key in ("displayName", "name", "http://schemas.xmlsoap.org/ws/2005/05/identity/claims/name"):
        if attrs.get(key):
            name = attrs[key][0]
            break
    if not email or not email.endswith("@" + domain):
        return jsonify({"error": "The identity provider did not return a matching email for this domain."}), 401

    user = UserAccount.query.filter_by(email=email).first()
    if not user:
        if not cfg.auto_provision:
            return jsonify({"error": f"No Connect It account exists for {email}, and auto-provisioning is off for this domain."}), 404
        user = UserAccount(
            name=name or email.split("@")[0], email=email, plan="free",
            auth_provider="saml", email_verified=True,
        )
        user.set_password(secrets.token_urlsafe(32))
        db.session.add(user)
        db.session.commit()
        logging.info(f"New user auto-provisioned via SAML SSO: {email} (domain={domain})")
    else:
        user.last_login = datetime.utcnow()
        db.session.commit()

    _sync_admin_from_email(user)
    session["user_id"]    = user.id
    session["user_name"]  = user.name
    session["user_email"] = user.email
    session["user_plan"]  = user.plan
    token = _issue_auth_token(user)

    # The IdP posts here as a full-page browser redirect (not fetch/XHR), so
    # we hand back a tiny page that stores the token and returns to the app,
    # rather than JSON a script wouldn't see.
    return _sso_login_success_page(user, token)


def _sso_login_success_page(user, token):
    """Shared by both the SAML ACS handler and the OIDC callback below —
    both land here as a full-page browser redirect from the IdP, not a
    fetch/XHR the frontend JS could read directly, so both hand back the
    same tiny page that stores the token client-side and bounces back
    into the app."""
    safe_token = token.replace("'", "")
    safe_user = json.dumps(user.to_dict()).replace("</", "<\\/")
    return f"""<!DOCTYPE html><html><body>
<script>
  try {{
    localStorage.setItem('connectitAuthToken', '{safe_token}');
    localStorage.setItem('connectitAuthUser', JSON.stringify({safe_user}));
  }} catch(e) {{}}
  window.location.href = '/?sso=success';
</script>
Signing you in…
</body></html>"""


# ════════════════════════════════════════════════════════════
# STAGE 523: ENTERPRISE SSO — OIDC (OpenID Connect)
# Alongside the SAML flow above, on the same OrgSsoConfig-per-domain
# model. Authorization Code flow + PKCE (RFC 7636) — PKCE is used even
# though a confidential client secret is also held server-side, because
# it costs nothing and closes the authorization-code-interception class
# of attack outright. The id_token that comes back from the token
# endpoint is verified for real: signature checked against the IdP's
# own JWKS (fetched live, same PyJWKClient pattern STAGE 184's "Sign in
# with Microsoft" already uses), plus issuer, audience, and nonce all
# checked — not a trust-the-redirect shortcut.
# ════════════════════════════════════════════════════════════

def _oidc_cleanup_expired_states():
    cutoff = datetime.utcnow() - timedelta(minutes=OIDC_STATE_TTL_MINUTES)
    OidcSsoState.query.filter(OidcSsoState.created_at < cutoff).delete()
    db.session.commit()


def _oidc_pkce_pair():
    """Returns (code_verifier, code_challenge) per RFC 7636 — a random
    43-128 char verifier, and its S256 (SHA-256, base64url, unpadded)
    challenge sent in the authorization request."""
    verifier = base64.urlsafe_b64encode(secrets.token_bytes(64)).rstrip(b"=").decode("ascii")
    digest = hashlib.sha256(verifier.encode("ascii")).digest()
    challenge = base64.urlsafe_b64encode(digest).rstrip(b"=").decode("ascii")
    return verifier, challenge


@app.route("/sso/oidc/login", methods=["GET"])
def sso_oidc_login():
    """SP-initiated login: given ?domain=acmecorp.com, redirects to that
    business's own configured OIDC IdP to authenticate."""
    if not JWT_AVAILABLE:
        return "OIDC support isn't available on this server (PyJWT not installed).", 503
    domain = (request.args.get("domain") or "").strip().lower().lstrip("@")
    cfg = OrgSsoConfig.query.filter_by(domain=domain, enabled=True, protocol="oidc").first()
    if not cfg or not cfg.oidc_authorization_endpoint:
        return jsonify({"error": f"No OIDC SSO is configured for '{domain}'."}), 404

    _oidc_cleanup_expired_states()
    state = secrets.token_urlsafe(32)
    nonce = secrets.token_urlsafe(24)
    verifier, challenge = _oidc_pkce_pair()
    db.session.add(OidcSsoState(state=state, domain=domain, code_verifier=verifier, nonce=nonce))
    db.session.commit()

    params = {
        "response_type": "code",
        "client_id": cfg.oidc_client_id,
        "redirect_uri": f"{APP_BASE_URL}/sso/oidc/callback",
        "scope": "openid email profile",
        "state": state,
        "nonce": nonce,
        "code_challenge": challenge,
        "code_challenge_method": "S256",
    }
    return redirect(f"{cfg.oidc_authorization_endpoint}?{urlencode(params)}")


@app.route("/sso/oidc/callback", methods=["GET"])
def sso_oidc_callback():
    """Exchanges the authorization code for tokens, verifies the id_token
    against the IdP's own JWKS, and signs the user in — auto-provisioning
    a new account on first login if the domain's config allows it, same
    policy as the SAML ACS handler above."""
    if not JWT_AVAILABLE:
        return "OIDC support isn't available on this server (PyJWT not installed).", 503

    error = request.args.get("error")
    if error:
        return jsonify({"error": f"The identity provider returned an error: {error} "
                                  f"{request.args.get('error_description', '')}"}), 401

    state = request.args.get("state") or ""
    code = request.args.get("code") or ""
    if not state or not code:
        return jsonify({"error": "Missing 'state' or 'code' from the identity provider."}), 400

    state_row = OidcSsoState.query.filter_by(state=state).first()
    if not state_row or state_row.created_at < datetime.utcnow() - timedelta(minutes=OIDC_STATE_TTL_MINUTES):
        return jsonify({"error": "This SSO sign-in link has expired or was already used. Please try signing in again."}), 400
    # Single-use: delete immediately so a replayed callback (e.g. the
    # browser back button) can't reuse the same state/code pair.
    domain, code_verifier, nonce = state_row.domain, state_row.code_verifier, state_row.nonce
    db.session.delete(state_row)
    db.session.commit()

    cfg = OrgSsoConfig.query.filter_by(domain=domain, enabled=True, protocol="oidc").first()
    if not cfg:
        return jsonify({"error": f"No OIDC SSO is configured for '{domain}'."}), 404

    try:
        token_resp = requests.post(cfg.oidc_token_endpoint, data={
            "grant_type": "authorization_code",
            "code": code,
            "redirect_uri": f"{APP_BASE_URL}/sso/oidc/callback",
            "client_id": cfg.oidc_client_id,
            "client_secret": cfg.oidc_client_secret,
            "code_verifier": code_verifier,
        }, timeout=10)
        if token_resp.status_code >= 400:
            logging.warning(f"[OIDC SSO] token exchange failed for domain={domain}: {token_resp.text[:300]}")
            return jsonify({"error": "SSO sign-in failed: could not exchange the authorization code."}), 401
        tokens = token_resp.json()
        id_token = tokens.get("id_token")
        if not id_token:
            return jsonify({"error": "The identity provider did not return an id_token."}), 401
    except Exception as e:
        logging.error(f"[OIDC SSO] token exchange exception for domain={domain}: {e}")
        return jsonify({"error": "Could not reach the identity provider's token endpoint."}), 502

    try:
        jwks_client = jwt.PyJWKClient(cfg.oidc_jwks_uri)
        signing_key = jwks_client.get_signing_key_from_jwt(id_token)
        claims = jwt.decode(
            id_token, signing_key.key, algorithms=["RS256"],
            audience=cfg.oidc_client_id, issuer=cfg.oidc_issuer,
        )
    except Exception as e:
        logging.warning(f"[OIDC SSO] id_token verification failed for domain={domain}: {e}")
        return jsonify({"error": "Invalid or expired identity provider token."}), 401

    if claims.get("nonce") != nonce:
        logging.warning(f"[OIDC SSO] nonce mismatch for domain={domain} — possible replay.")
        return jsonify({"error": "SSO sign-in failed: security check did not match."}), 401

    email = (claims.get("email") or "").strip().lower()
    name = claims.get("name") or (email.split("@")[0] if email else None)
    if not email or not email.endswith("@" + domain):
        return jsonify({"error": "The identity provider did not return a matching email for this domain."}), 401
    if claims.get("email_verified") is False:
        return jsonify({"error": "Your identity provider account's email is not verified."}), 401

    user = UserAccount.query.filter_by(email=email).first()
    if not user:
        if not cfg.auto_provision:
            return jsonify({"error": f"No Connect It account exists for {email}, and auto-provisioning is off for this domain."}), 404
        user = UserAccount(
            name=name or email.split("@")[0], email=email, plan="free",
            auth_provider="oidc", email_verified=True,
        )
        user.set_password(secrets.token_urlsafe(32))
        db.session.add(user)
        db.session.commit()
        logging.info(f"New user auto-provisioned via OIDC SSO: {email} (domain={domain})")
    else:
        user.last_login = datetime.utcnow()
        db.session.commit()

    _sync_admin_from_email(user)
    session["user_id"]    = user.id
    session["user_name"]  = user.name
    session["user_email"] = user.email
    session["user_plan"]  = user.plan
    token = _issue_auth_token(user)
    return _sso_login_success_page(user, token)


@app.route("/sso/login", methods=["GET"])
def sso_login_dispatch():
    """Single entry point the login page's 'Sign in with company SSO'
    form can always hit regardless of which protocol a given domain is
    configured for — looks up the domain's config and forwards to the
    matching SAML or OIDC flow above, so the frontend never has to know
    or guess which protocol a business chose."""
    domain = (request.args.get("domain") or "").strip().lower().lstrip("@")
    cfg = OrgSsoConfig.query.filter_by(domain=domain, enabled=True).first()
    if not cfg:
        return jsonify({"error": f"No SSO is configured for '{domain}'."}), 404
    if cfg.protocol == "oidc":
        return redirect(f"/sso/oidc/login?domain={quote(domain)}")
    return redirect(f"/sso/saml/login?domain={quote(domain)}")


@app.route("/api/auth/logout", methods=["POST"])
@csrf.exempt
def logout_endpoint():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403

    auth_header = request.headers.get("Authorization", "")
    if auth_header.startswith("Bearer "):
        token = auth_header[7:].strip()
        user_store.pop(token, None)
        try:
            row = AuthSessionToken.query.get(token)
            if row:
                db.session.delete(row)
                db.session.commit()
        except Exception as e:
            db.session.rollback()
            logging.error(f"[AUTH TOKEN LOGOUT ERROR] {e}")

    session.pop("user_id",    None)
    session.pop("user_name",  None)
    session.pop("user_email", None)
    session.pop("user_plan",  None)

    return jsonify({
        "message": "You have been logged out. Come back soon! "
    }), 200


@app.route("/api/auth/me", methods=["GET"])
def me_endpoint():
    user_id = _current_user_id()
    if not user_id:
        return jsonify({"error": "Not logged in."}), 401
    try:
        user = UserAccount.query.get(user_id)
        if not user:
            return jsonify({"error": "User not found."}), 404
        _sync_admin_from_email(user)
        if not user.sync_key_salt:
            _ensure_sync_key_salt(user)
            db.session.commit()
        return jsonify({"user": user.to_dict()}), 200
    except Exception as e:
        return jsonify({"error": str(e)}), 500


@app.route("/api/auth/send-verification", methods=["POST"])
@csrf.exempt
def send_verification_endpoint():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403

    user_id = _current_user_id()
    if not user_id:
        return jsonify({"error": "Login required."}), 401

    try:
        user = UserAccount.query.get(user_id)
        if not user:
            return jsonify({"error": "User not found."}), 404
        if user.email_verified:
            return jsonify({"message": "Email already verified."}), 200
    except Exception as e:
        return jsonify({"error": str(e)}), 500

    token   = secrets.token_urlsafe(48)
    expires = time.time() + 86400
    with _verification_lock:
        _verification_tokens[token] = {
            "user_id": user_id,
            "email":   user.email,
            "expires": expires,
        }

    sent = _send_verification_email(user.email, user.name, token)
    return jsonify({
        "message": (
            "Verification email sent! Check your inbox." if sent
            else "SMTP not configured on this server."
        ),
        "sent": sent,
    }), 200


@app.route("/api/auth/verify-email", methods=["GET"])
def verify_email_endpoint():
    token = request.args.get("token", "").strip()
    if not token:
        return (
            "<html><body style='font-family:sans-serif;padding:40px;"
            "text-align:center;'>"
            "<h2 style='color:#dc2626;'> Invalid Link</h2>"
            "<p>No token provided.</p></body></html>"
        ), 400

    with _verification_lock:
        record = _verification_tokens.get(token)

    if not record:
        return (
            "<html><body style='font-family:sans-serif;padding:40px;"
            "text-align:center;'>"
            "<h2 style='color:#dc2626;'> Invalid or Expired</h2>"
            "<p>Please request a new verification email.</p>"
            "</body></html>"
        ), 400

    if time.time() > record["expires"]:
        with _verification_lock:
            _verification_tokens.pop(token, None)
        return (
            "<html><body style='font-family:sans-serif;padding:40px;"
            "text-align:center;'>"
            "<h2 style='color:#f97316;'>⏰ Link Expired</h2>"
            "<p>Request a new verification email from your account.</p>"
            "</body></html>"
        ), 400

    try:
        user = UserAccount.query.get(record["user_id"])
        if user:
            user.email_verified = True
            db.session.commit()
        with _verification_lock:
            _verification_tokens.pop(token, None)
    except Exception as e:
        db.session.rollback()
        return f"<html><body><p>Error: {e}</p></body></html>", 500

    return """
    <html>
    <head>
      <meta charset='UTF-8'/>
      <title>Email Verified</title>
      <style>
        body{font-family:Arial,sans-serif;background:#f0fdf4;
             display:flex;align-items:center;justify-content:center;
             min-height:100vh;margin:0;}
        .card{background:white;border-radius:16px;padding:40px;
              text-align:center;max-width:400px;
              box-shadow:0 8px 32px rgba(0,0,0,0.1);}
        h2{color:#16a34a;}
        a{display:inline-block;margin-top:20px;padding:12px 28px;
          background:#2563eb;color:white;border-radius:8px;
          text-decoration:none;font-weight:700;}
      </style>
    </head>
    <body>
      <div class='card'>
        <div style='font-size:3rem;'></div>
        <h2>Email Verified!</h2>
        <p>Your Connect It account is now fully activated. </p>
        <a href='/'>Go to Connect It</a>
      </div>
    </body>
    </html>
    """, 200


@app.route("/api/auth/forgot-password", methods=["POST"])
@csrf.exempt
def forgot_password_endpoint():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403

    data  = request.get_json() or {}
    email = data.get("email", "").strip().lower()

    if not email:
        return jsonify({"error": "Email is required."}), 400

    # STAGE 150: cap how often this IP can trigger reset emails — the
    # endpoint already avoids leaking whether an email exists, but without
    # this it could still be used to spam an inbox or hammer the DB.
    ip = _client_ip()
    if _rate_limited(f"forgot:ip:{ip}", max_attempts=5, window_seconds=600):
        return jsonify({"error": "Too many reset requests. Please wait a few minutes and try again."}), 429

    try:
        user = UserAccount.query.filter_by(email=email).first()
    except Exception as e:
        return jsonify({"error": str(e)}), 500

    # Always return success to prevent email enumeration
    if user:
        token   = secrets.token_urlsafe(48)
        expires = time.time() + 3600  # 1 hour
        with _reset_lock:
            _reset_tokens[token] = {
                "user_id": user.id,
                "email":   user.email,
                "expires": expires,
            }
        enqueue_job(_send_password_reset_email, user.email, user.name, token)

    return jsonify({
        "message": (
            "If that email exists in our system, "
            "a reset link has been sent. Check your inbox. "
        )
    }), 200


@app.route("/api/auth/reset-password", methods=["POST"])
@csrf.exempt
def reset_password_endpoint():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403

    data         = request.get_json() or {}
    token        = data.get("token",        "").strip()
    new_password = data.get("new_password", "").strip()

    if not token or not new_password:
        return jsonify({
            "error": "token and new_password are required."
        }), 400
    if len(new_password) < 8:
        return jsonify({
            "error": "Password must be at least 8 characters."
        }), 400

    with _reset_lock:
        record = _reset_tokens.get(token)

    if not record:
        return jsonify({"error": "Invalid or expired reset token."}), 400
    if time.time() > record["expires"]:
        with _reset_lock:
            _reset_tokens.pop(token, None)
        return jsonify({"error": "Reset link has expired. Please request a new one."}), 400

    try:
        user = UserAccount.query.get(record["user_id"])
        if not user:
            return jsonify({"error": "User not found."}), 404
        user.set_password(new_password)
        db.session.commit()
        with _reset_lock:
            _reset_tokens.pop(token, None)
        return jsonify({
            "message": "Password reset successfully. You can now log in. "
        }), 200
    except Exception as e:
        db.session.rollback()
        return jsonify({"error": str(e)}), 500


@app.route("/api/auth/update-username", methods=["POST"])
@csrf.exempt
def update_username_endpoint():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403

    user_id  = _current_user_id()
    if not user_id:
        return jsonify({"error": "Login required."}), 401

    data     = request.get_json() or {}
    new_name = data.get("name", "").strip()

    if not new_name or len(new_name) < 2:
        return jsonify({"error": "Name must be at least 2 characters."}), 400
    if len(new_name) > 64:
        return jsonify({"error": "Name must be under 64 characters."}), 400

    try:
        user = UserAccount.query.get(user_id)
        if not user:
            return jsonify({"error": "User not found."}), 404
        user.name = new_name
        db.session.commit()
        session["user_name"] = new_name
        return jsonify({
            "message": f"Username updated to {new_name}! ",
            "user":    user.to_dict(),
        }), 200
    except Exception as e:
        db.session.rollback()
        return jsonify({"error": str(e)}), 500


@app.route("/api/auth/change-password", methods=["POST"])
@csrf.exempt
def change_password_endpoint():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403

    user_id = _current_user_id()
    if not user_id:
        return jsonify({"error": "Login required."}), 401

    data         = request.get_json() or {}
    old_password = data.get("old_password", "").strip()
    new_password = data.get("new_password", "").strip()

    if not old_password or not new_password:
        return jsonify({
            "error": "old_password and new_password are required."
        }), 400
    if len(new_password) < 8:
        return jsonify({
            "error": "New password must be at least 8 characters."
        }), 400

    try:
        user = UserAccount.query.get(user_id)
        if not user or not user.check_password(old_password):
            return jsonify({"error": "Current password is incorrect."}), 401
        user.set_password(new_password)
        db.session.commit()
        return jsonify({"message": "Password updated successfully. "}), 200
    except Exception as e:
        db.session.rollback()
        return jsonify({"error": str(e)}), 500


@app.route("/api/auth/delete-account", methods=["POST"])
@csrf.exempt
def delete_account_endpoint():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403

    user_id = _current_user_id()
    if not user_id:
        return jsonify({"error": "Login required."}), 401

    data     = request.get_json() or {}
    password = data.get("password", "").strip()

    if not password:
        return jsonify({
            "error": "Password is required to delete your account."
        }), 400

    try:
        user = UserAccount.query.get(user_id)
        if not user:
            return jsonify({"error": "User not found."}), 404
        if not user.check_password(password):
            return jsonify({"error": "Incorrect password."}), 401

        # NOTE: this used to be a hard db.session.delete(user). Under the
        # new policy, a user's generated content/messages (UserMemory) is
        # never erased except by an admin — including when the erasure is
        # the user's own request. So "delete my account" now deactivates
        # and anonymizes the login, but preserves the account row and its
        # entire Memory archive intact. A real full wipe only happens via
        # /api/admin/memory/wipe, performed by an admin after the user (or
        # a law-enforcement/legal request) asks for it.
        user.is_active     = False
        user.email         = f"deleted-{user.id}-{secrets.token_hex(4)}@deleted.connectit"
        user.password_hash = generate_password_hash(secrets.token_urlsafe(32))
        db.session.commit()

        session.pop("user_id",    None)
        session.pop("user_name",  None)
        session.pop("user_email", None)
        session.pop("user_plan",  None)

        logging.info(f"Account deactivated (memory preserved pending admin action): user_id={user_id}")
        return jsonify({
            "message": (
                "Your account has been deactivated and you're now logged out. "
                "In line with our data policy, your generated content is kept "
                "safe and is only fully erased by an admin, on your request or "
                "where required by law — reach out any time to request that. "
            )
        }), 200
    except Exception as e:
        db.session.rollback()
        logging.error(f"Account deletion failed: {e}")
        return jsonify({"error": str(e)}), 500


