@app.route("/api/chat", methods=["POST"])
@csrf.exempt
def chat_endpoint():
    """Non-streaming chat endpoint — used by panels that call /api/chat directly.
    Accepts a plain JSON {"content": "..."} body, OR a multipart/form-data
    request with a "content" text field plus one or more "files", OR a JSON
    body with an "attachments" list (already-extracted text or base64 bytes).
    Whatever file content comes in gets merged into the message Connect It
    actually sees — not just previewed and discarded."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403

    if request.files:
        user_content = (request.form.get("content", "") or "").strip()
    else:
        data = request.get_json(force=True, silent=True) or {}
        user_content = (data.get("content", "") or "").strip()

    user_content = _merge_content_with_attachments(user_content)

    if not user_content:
        return jsonify({"error": "No content or attachments provided."}), 400

    if "session_id" not in session:
        session["session_id"] = os.urandom(16).hex()
    session_id = session["session_id"]

    if session_id not in conversation_store:
        conversation_store[session_id] = _db_get_history(session_id, channel="web")
    history = _get_history(conversation_store, session_id)

    current_user  = _get_current_user()
    current_uid   = current_user.get("id") if current_user else None
    # Anonymous visitors can still use this (it's the public-facing demo
    # chat) — metering only applies once someone's actually signed in,
    # which matches what FEATURE_LIMITS['chat_reply'] was already priced
    # for (a per-plan monthly quota keyed by account, not by session).
    if current_user:
        blocked = gate_ai_usage(current_user, "chat_reply")
        if blocked: return blocked

    _db_save_turn(session_id, "web", "user", user_content, user_id=current_uid)
    # Also archive into the PERMANENT "Activity Log" log (UserMemory) for
    # signed-in users — unlike ChatLog above (session-keyed, gets pruned),
    # this is the log the Activity Log page actually reads from. Every
    # real conversation a signed-in user has with Connect It belongs here,
    # not just the handful of features that called save_to_memory before.
    if current_uid:
        save_to_memory(current_uid, "user", user_content, content_type="chat")

    try:
        ai_reply_raw, updated_history = generate_ai_reply(user_content, history, user_id=current_uid)
        _save_history(conversation_store, session_id, updated_history)
        _db_save_turn(session_id, "web", "assistant", ai_reply_raw, user_id=current_uid)
        if current_uid:
            save_to_memory(current_uid, "assistant", ai_reply_raw, content_type="chat")
        ai_reply_html = format_ai_response(ai_reply_raw)
        return jsonify({"reply": ai_reply_html}), 200
    except Exception as e:
        logging.error(f"Chat error: {e}")
        return jsonify({"error": str(e)}), 500



@app.route("/api/chat/stream", methods=["POST"])
@csrf.exempt
def chat_stream_endpoint():
    if request.files:
        user_content = (request.form.get("content", "") or "").strip()
    else:
        data = request.get_json(force=True, silent=True) or {}
        user_content = (data.get("content", "") or "").strip()

    user_content = _merge_content_with_attachments(user_content)

    if not user_content:
        return jsonify({"error": "No content or attachments provided."}), 400

    if "session_id" not in session:
        session["session_id"] = os.urandom(16).hex()
    session_id = session["session_id"]

    if session_id not in conversation_store:
        conversation_store[session_id] = _db_get_history(
            session_id, channel="web"
        )
    history = _get_history(conversation_store, session_id)

    current_user = _get_current_user()
    current_uid  = current_user.get("id") if current_user else None

    if current_user:
        # STAGE (metering gap fix): this is the SSE-streaming twin of
        # /api/chat (chat_reply), which is already gated the same way —
        # open for anonymous visitors by design, metered once signed in.
        # Must happen before the stream starts, since a blocked response
        # can't be swapped in mid-stream.
        gate_result = gate_ai_usage(current_user, "chat_reply")
        if gate_result is not None:
            return gate_result

    _db_save_turn(session_id, "web", "user", user_content, user_id=current_uid)
    if current_uid:
        save_to_memory(current_uid, "user", user_content, content_type="chat")

    def generate():
        try:
            ai_reply_raw, updated_history = generate_ai_reply(
                user_content, history, user_id=current_uid
            )
            _save_history(conversation_store, session_id, updated_history)
            _db_save_turn(session_id, "web", "assistant", ai_reply_raw, user_id=current_uid)
            if current_uid:
                save_to_memory(current_uid, "assistant", ai_reply_raw, content_type="chat")

            ai_reply_html = format_ai_response(ai_reply_raw)
            chunk_size = 200

            for i in range(0, len(ai_reply_html), chunk_size):
                chunk = ai_reply_html[i:i + chunk_size]
                yield f"data: {json.dumps({'chunk': chunk})}\n\n"

            yield "data: [DONE]\n\n"

        except Exception as e:
            logging.error(f"Stream error: {e}")
            yield f"data: {json.dumps({'error': str(e)})}\n\n"
            yield "data: [DONE]\n\n"

    return Response(
        stream_with_context(generate()),
        mimetype="text/event-stream",
        headers={
            "X-Accel-Buffering": "no",
            "Cache-Control": "no-cache",
            "Connection": "keep-alive",
            "Access-Control-Allow-Origin": "*",
        }
    )


