@app.route("/api/my-applications", methods=["GET"])
def my_applications():
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401

    apps = (
        JobApplication.query.filter_by(applicant_id=user["id"])
        .order_by(JobApplication.created_at.desc())
        .all()
    )
    result = []
    for a in apps:
        job = Job.query.get(a.job_id)
        d = a.to_dict()
        d["job"] = job.to_dict() if job else None
        result.append(d)
    return jsonify({"applications": result}), 200


