@app.route("/api/sentiment", methods=["POST"])
@csrf.exempt
def sentiment_endpoint():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    gate_result = gate_ai_usage(user, "sentiment_endpoint")
    if gate_result is not None:
        return gate_result

    data = request.get_json() or {}
    text = data.get("text", "").strip()

    if not text:
        return jsonify({"error": "text field is required."}), 400

    prompt = (
        "Analyze the sentiment and emotional tone of the following text. "
        "Respond ONLY with a valid JSON object in this exact format:\n"
        '{"sentiment": "positive|negative|neutral|mixed", '
        '"score": 0.0-1.0, '
        '"emotions": ["list","of","emotions"], '
        '"urgency": "low|medium|high", '
        '"summary": "one sentence summary of the tone"}\n\n'
        f"TEXT:\n{text}"
    )

    result_raw, _ = generate_ai_reply(prompt, [])

    try:
        clean  = result_raw.strip().replace("```json", "").replace("```", "")
        parsed = json.loads(clean)
    except Exception:
        parsed = {
            "sentiment": "unknown",
            "score":     0.5,
            "emotions":  [],
            "urgency":   "low",
            "summary":   result_raw,
        }

    return jsonify({
        "analysis":   parsed,
        "input_text": text,
        "powered_by": "Smile Again API",
    }), 200


