@app.route("/api/compose/email", methods=["POST"])
@csrf.exempt
def compose_email_endpoint():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    gate_result = gate_ai_usage(user, "compose_email_endpoint")
    if gate_result is not None:
        return gate_result

    data      = request.get_json() or {}
    brief     = data.get("brief",     "").strip()
    tone      = data.get("tone",      "professional")
    recipient = data.get("recipient", "")
    sender    = data.get("sender",    "")

    if not brief:
        return jsonify({"error": "brief field is required."}), 400

    context = ""
    if recipient: context += f" This email is going to: {recipient}."
    if sender:    context += f" It is from: {sender}."

    prompt = (
        f"Write a complete, polished {tone} email based on this brief:{context}\n\n"
        f"BRIEF: {brief}\n\n"
        f"Include a strong subject line on the first line starting with 'Subject: ', "
        f"then a blank line, then the full email body."
    )

    email_raw, _ = generate_ai_reply(prompt, [])

    lines   = email_raw.strip().split("\n")
    subject = ""
    body    = email_raw

    if lines and lines[0].lower().startswith("subject:"):
        subject = lines[0].replace("Subject:", "").replace("subject:", "").strip()
        body    = "\n".join(lines[2:]).strip()

    return jsonify({
        "subject":    subject,
        "body":       body,
        "body_html":  format_ai_response(body),
        "tone":       tone,
        "powered_by": "Smile Again API",
    }), 200


