@app.route("/api/social/generate", methods=["POST"])
@csrf.exempt
def social_generate_endpoint():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    gate_result = gate_ai_usage(user, "social_generate_endpoint")
    if gate_result is not None:
        return gate_result

    data      = request.get_json() or {}
    topic     = data.get("topic",     "").strip()
    platforms = data.get("platforms", ["linkedin", "twitter", "instagram"])
    tone      = data.get("tone",      "professional")

    if not topic:
        return jsonify({"error": "topic field is required."}), 400

    platform_instructions = {
        "linkedin":  "LinkedIn post (300-500 words, professional, ends with a question)",
        "twitter":   "Twitter/X thread of 5 tweets (each under 280 chars, numbered 1/ 2/ etc)",
        "instagram": "Instagram caption (150-200 words, warm, 10-15 hashtags at the end)",
        "facebook":  "Facebook post (200-300 words, conversational, ends with a call to action)",
        "tiktok":    "TikTok video script (hook in first 3 seconds, 60-90 seconds, casual)",
    }

    results = {}
    for platform in platforms:
        if platform.lower() in platform_instructions:
            instruction = platform_instructions[platform.lower()]
            prompt = (
                f"Write a {tone} {instruction} about:\n\n"
                f"TOPIC: {topic}\n\n"
                f"Make it engaging, original, and human. Not corporate. Not generic."
            )
            content, _ = generate_ai_reply(prompt, [])
            results[platform] = {
                "content":      content,
                "content_html": format_ai_response(content),
            }

    return jsonify({
        "topic":      topic,
        "tone":       tone,
        "platforms":  results,
        "powered_by": "Smile Again API",
    }), 200


