@app.route("/api/hr/job-description", methods=["POST"])
@csrf.exempt
def job_description_endpoint():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    gate_result = gate_ai_usage(user, "job_description_endpoint")
    if gate_result is not None:
        return gate_result

    data         = request.get_json() or {}
    role         = data.get("role",         "").strip()
    company      = data.get("company",      "").strip()
    industry     = data.get("industry",     "").strip()
    location     = data.get("location",     "").strip()
    salary       = data.get("salary",       "").strip()
    requirements = data.get("requirements", "").strip()

    if not role:
        return jsonify({"error": "role field is required."}), 400

    context = ""
    if company:      context += f" Company: {company}."
    if industry:     context += f" Industry: {industry}."
