# PRODUCTIVITY — INVOICE GENERATOR
# ===========================================================

@app.route("/api/invoice/generate", methods=["POST"])
@csrf.exempt
def invoice_generate_endpoint():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    blocked = gate_ai_usage(user, "invoice_generate")
    if blocked: return blocked

    data          = request.get_json() or {}
    business_name = data.get("business_name", "").strip()
    client_name   = data.get("client_name",   "").strip()
    items         = data.get("items",         [])
    due_date      = data.get("due_date",      "")
    invoice_no    = data.get("invoice_no",    f"INV-{secrets.token_hex(3).upper()}")
    notes         = data.get("notes",         "")
    currency      = data.get("currency",      "USD")

    if not business_name or not client_name or not items:
        return jsonify({
            "error": "business_name, client_name, and items are required."
        }), 400

    line_items = []
    subtotal   = 0.0
    for item in items:
        desc       = item.get("description", "Service")
        qty        = float(item.get("qty",        1))
        unit_price = float(item.get("unit_price", 0))
        total      = qty * unit_price
        subtotal  += total
        line_items.append({
            "description": desc,
            "qty":         qty,
            "unit_price":  unit_price,
            "total":       total,
        })

    tax_rate    = float(data.get("tax_rate", 0))
    tax_amt     = subtotal * (tax_rate / 100)
    grand_total = subtotal + tax_amt

    items_text = "\n".join(
        f"  - {li['description']}: "
        f"{li['qty']} x {currency}{li['unit_price']:.2f} "
        f"= {currency}{li['total']:.2f}"
        for li in line_items
    )

    prompt = (
        f"Format this as a professional invoice:\n\n"
        f"Invoice No: {invoice_no}\n"
        f"From: {business_name}\n"
        f"To: {client_name}\n"
        f"Due Date: {due_date or 'Upon receipt'}\n\n"
        f"Items:\n{items_text}\n\n"
        f"Subtotal: {currency}{subtotal:.2f}\n"
        f"Tax ({tax_rate}%): {currency}{tax_amt:.2f}\n"
        f"TOTAL DUE: {currency}{grand_total:.2f}\n\n"
        f"Notes: {notes or 'Thank you for your business.'}\n\n"
        f"Write a clean professional invoice layout with a warm closing line."
    )

    invoice_raw, _ = generate_ai_reply(prompt, [])
    invoice_html   = format_ai_response(invoice_raw)

    return jsonify({
        "invoice_html":  invoice_html,
        "invoice_text":  invoice_raw,
        "invoice_no":    invoice_no,
        "subtotal":      subtotal,
        "tax":           tax_amt,
        "grand_total":   grand_total,
        "currency":      currency,
        "powered_by":    "Smile Again API",
    }), 200


