@app.route("/api/legal/contract", methods=["POST"])
@csrf.exempt
def contract_generator_endpoint():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    gate_result = gate_ai_usage(user, "contract_generator_endpoint")
    if gate_result is not None:
        return gate_result

    data          = request.get_json() or {}
    contract_type = data.get("contract_type", "service agreement").strip()
    party_one     = data.get("party_one",     "").strip()
    party_two     = data.get("party_two",     "").strip()
    services      = data.get("services",      "").strip()
    payment_terms = data.get("payment_terms", "").strip()
    duration      = data.get("duration",      "").strip()
    jurisdiction  = data.get("jurisdiction",  "").strip()

    if not party_one or not party_two:
        return jsonify({
            "error": "party_one and party_two are required."
        }), 400

    prompt = (
        f"Draft a complete, legally sound {contract_type} between:\n\n"
        f"Party One: {party_one}\n"
        f"Party Two: {party_two}\n"
        f"Services: {services or 'as mutually agreed'}\n"
        f"Payment Terms: {payment_terms or 'as mutually agreed'}\n"
        f"Duration: {duration or 'ongoing until terminated'}\n"
        f"Jurisdiction: {jurisdiction or 'international best practice'}\n\n"
        f"Include all standard clauses: Definitions, Scope, Payment, IP Rights, "
        f"Confidentiality, Termination, Dispute Resolution, Liability, "
        f"Force Majeure, Governing Law, and Signature Block."
    )

    contract_raw, _ = generate_ai_reply(prompt, [])
    contract_html   = format_ai_response(contract_raw)

    session_id = None
    if user:
        session_row = ContractDraftSession(
            user_id=user["id"], contract_type=contract_type, party_one=party_one, party_two=party_two,
            services=services or None, payment_terms=payment_terms or None,
            duration=duration or None, jurisdiction=jurisdiction or None, contract_text=contract_raw,
        )
        try:
            db.session.add(session_row); db.session.commit()
            session_id = session_row.id
        except Exception as e:
            db.session.rollback(); logging.error(f"[CONTRACT SESSION SAVE] {e}")

    return jsonify({
        "contract":      contract_html,
        "contract_text": contract_raw,
        "contract_type": contract_type,
        "session_id":    session_id,
        "disclaimer":    "AI-generated for reference. Have a lawyer review before signing.",
        "powered_by":    "Smile Again API",
    }), 200


