@app.route("/api/hr/payslip", methods=["POST"])
@csrf.exempt
def payslip_generator_endpoint():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    gate_result = gate_ai_usage(user, "payslip_generator_endpoint")
    if gate_result is not None:
        return gate_result

    data          = request.get_json() or {}
    employee_name = data.get("employee_name", "").strip()
    employee_id   = data.get("employee_id",   "EMP001").strip()
    company       = data.get("company",       "").strip()
    position      = data.get("position",      "").strip()
    pay_period    = data.get("pay_period",    "").strip()
    basic_salary  = float(data.get("basic_salary", 0))
    allowances    = data.get("allowances",    [])
    deductions    = data.get("deductions",    [])
    currency      = data.get("currency",      "USD")

    if not employee_name or basic_salary <= 0:
        return jsonify({
            "error": "employee_name and basic_salary are required."
        }), 400

    total_allowances = sum(float(a.get("amount", 0)) for a in allowances)
    total_deductions = sum(float(d.get("amount", 0)) for d in deductions)
    gross_pay        = basic_salary + total_allowances
    net_pay          = gross_pay - total_deductions

    allowances_text = "\n".join(
        f"  {a.get('name','Allowance')}: "
        f"{currency}{float(a.get('amount',0)):.2f}"
        for a in allowances
    ) or "  None"

    deductions_text = "\n".join(
        f"  {d.get('name','Deduction')}: "
        f"{currency}{float(d.get('amount',0)):.2f}"
        for d in deductions
    ) or "  None"

    prompt = (
        f"Format this as a professional payslip:\n\n"
        f"Company: {company or 'Company Name'}\n"
        f"Employee: {employee_name}\n"
        f"Employee ID: {employee_id}\n"
        f"Position: {position or 'Staff'}\n"
        f"Pay Period: {pay_period or 'Current Month'}\n\n"
        f"EARNINGS:\n  Basic Salary: {currency}{basic_salary:.2f}\n"
        f"{allowances_text}\n"
        f"  Gross Pay: {currency}{gross_pay:.2f}\n\n"
        f"DEDUCTIONS:\n{deductions_text}\n"
        f"  Total Deductions: {currency}{total_deductions:.2f}\n\n"
        f"NET PAY: {currency}{net_pay:.2f}\n\n"
        f"Add a warm professional closing line."
    )

    payslip_raw, _ = generate_ai_reply(prompt, [])
    payslip_html   = format_ai_response(payslip_raw)

    return jsonify({
        "payslip":          payslip_html,
        "payslip_text":     payslip_raw,
        "gross_pay":        gross_pay,
        "total_deductions": total_deductions,
        "net_pay":          net_pay,
        "currency":         currency,
        "powered_by":       "Smile Again API",
    }), 200


