# ===========================================================
# NEW BLOCK: BUSINESS — BREAK-EVEN CALCULATOR
# (backend for the "Break-Even Calculator" tool, endpoint
#  /api/business/breakeven in index.html's TOOL_FORMS)
# ===========================================================

@app.route("/api/business/breakeven", methods=["POST"])
@csrf.exempt
def breakeven_endpoint():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    gate_result = gate_ai_usage(user, "breakeven_endpoint")
    if gate_result is not None:
        return gate_result

    data       = request.get_json() or {}
    try:
        fixed_costs = float(data.get("fixed_costs", 0) or 0)
        var_cost    = float(data.get("variable_cost_per_unit", 0) or 0)
        price       = float(data.get("price_per_unit", 0) or 0)
    except (TypeError, ValueError):
        return jsonify({"error": "fixed_costs, variable_cost_per_unit and price_per_unit must be numbers."}), 400
    currency = (data.get("currency") or "USD").strip()

    if fixed_costs <= 0 or price <= 0:
        return jsonify({"error": "fixed_costs and price_per_unit are required and must be greater than 0."}), 400

    contribution_margin = price - var_cost
    if contribution_margin <= 0:
        return jsonify({
            "error": "Your selling price must be higher than your variable cost per unit for a break-even point to exist."
        }), 400

    breakeven_units   = fixed_costs / contribution_margin
    breakeven_revenue = breakeven_units * price
    margin_percent     = (contribution_margin / price) * 100

    prompt = (
        f"You are a business finance advisor. A business has calculated its break-even point:\n"
        f"Fixed monthly costs: {currency} {fixed_costs:,.2f}\n"
        f"Variable cost per unit: {currency} {var_cost:,.2f}\n"
        f"Selling price per unit: {currency} {price:,.2f}\n"
        f"Contribution margin per unit: {currency} {contribution_margin:,.2f} ({margin_percent:.1f}%)\n"
        f"Break-even point: {breakeven_units:,.1f} units, or {currency} {breakeven_revenue:,.2f} in revenue.\n\n"
        f"Explain what this means in plain language, then give 4-5 concrete, practical suggestions "
        f"for lowering the break-even point (cutting fixed costs, raising price, reducing variable "
        f"cost per unit) tailored to a small business."
    )
    narrative_raw, _ = generate_ai_reply(prompt, [])
    narrative_html   = format_ai_response(narrative_raw)

    return jsonify({
        "analysis":            narrative_html,
        "analysis_text":       narrative_raw,
        "breakeven_units":     round(breakeven_units, 1),
        "breakeven_revenue":   round(breakeven_revenue, 2),
        "contribution_margin": round(contribution_margin, 2),
        "margin_percent":      round(margin_percent, 1),
        "currency":            currency,
        "powered_by":          "Smile Again API",
    }), 200


# ===========================================================
# NEW BLOCK: BUSINESS — CASH FLOW FORECASTER
# (backend for /api/business/cashflow-forecast)
# ===========================================================

@app.route("/api/business/cashflow-forecast", methods=["POST"])
@csrf.exempt
def cashflow_forecast_endpoint():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    gate_result = gate_ai_usage(user, "cashflow_forecast_endpoint")
    if gate_result is not None:
        return gate_result

    data = request.get_json() or {}
    try:
        current_cash        = float(data.get("current_cash", 0) or 0)
        monthly_income       = float(data.get("monthly_income", 0) or 0)
        monthly_expenses     = float(data.get("monthly_expenses", 0) or 0)
        outstanding_invoices = float(data.get("outstanding_invoices", 0) or 0)
        upcoming_expenses    = float(data.get("upcoming_expenses", 0) or 0)
    except (TypeError, ValueError):
        return jsonify({"error": "All amount fields must be numbers."}), 400
    currency = (data.get("currency") or "USD").strip()

    try:
        forecast_days = int(float(str(data.get("forecast_days", 30)).strip() or 30))
    except (TypeError, ValueError):
        forecast_days = 30
    forecast_days = max(1, min(forecast_days, 365))

    if monthly_income <= 0 and monthly_expenses <= 0:
        return jsonify({"error": "current_cash, monthly_income and monthly_expenses are required."}), 400

    daily_net      = (monthly_income - monthly_expenses) / 30.0
    projected_cash = current_cash + (daily_net * forecast_days) + outstanding_invoices - upcoming_expenses
    daily_burn     = monthly_expenses / 30.0
    runway_days    = (current_cash / daily_burn) if daily_burn > 0 else None

    prompt = (
        f"You are a small business cash flow advisor. Here is a cash flow forecast:\n"
        f"Current cash on hand: {currency} {current_cash:,.2f}\n"
        f"Average monthly income: {currency} {monthly_income:,.2f}\n"
        f"Average monthly expenses: {currency} {monthly_expenses:,.2f}\n"
        f"Outstanding invoices owed to the business: {currency} {outstanding_invoices:,.2f}\n"
        f"Known upcoming expenses (next 90 days): {currency} {upcoming_expenses:,.2f}\n"
        f"Forecast period: {forecast_days} days\n"
        f"Projected cash at end of period: {currency} {projected_cash:,.2f}\n"
        f"Cash runway at current burn rate: "
        f"{(str(round(runway_days)) + ' days') if runway_days is not None else 'not applicable (not burning cash)'}\n\n"
        f"Explain what this forecast means, flag any risk of running out of cash, and give 4-5 "
        f"concrete actions the owner should take this month."
    )
    narrative_raw, _ = generate_ai_reply(prompt, [])
    narrative_html   = format_ai_response(narrative_raw)

    return jsonify({
        "analysis":       narrative_html,
        "analysis_text":  narrative_raw,
        "projected_cash": round(projected_cash, 2),
        "daily_net":      round(daily_net, 2),
        "runway_days":    (round(runway_days) if runway_days is not None else None),
        "forecast_days":  forecast_days,
        "currency":       currency,
        "powered_by":     "Smile Again API",
    }), 200


