@app.route("/api/business/loan-readiness", methods=["POST"])
@csrf.exempt
def loan_readiness_endpoint():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    gate_result = gate_ai_usage(user, "loan_readiness_endpoint")
    if gate_result is not None:
        return gate_result

    data = request.get_json() or {}
    business_name = (data.get("business_name") or "").strip()
    purpose       = (data.get("purpose") or "").strip()
    if not business_name or not purpose:
        return jsonify({"error": "business_name and purpose are required."}), 400

    try:
        years_operating = float(data.get("years_operating", 0) or 0)
        monthly_revenue = float(data.get("monthly_revenue", 0) or 0)
        monthly_profit  = float(data.get("monthly_profit", 0) or 0)
        existing_debt   = float(data.get("existing_debt", 0) or 0)
        funding_needed  = float(data.get("funding_amount_needed", 0) or 0)
    except (TypeError, ValueError):
        return jsonify({"error": "Numeric fields must be numbers."}), 400
    collateral = (data.get("collateral_available") or "Not specified").strip()
    currency   = (data.get("currency") or "USD").strip()

    profit_margin    = (monthly_profit / monthly_revenue * 100) if monthly_revenue > 0 else 0
    annual_revenue    = monthly_revenue * 12
    debt_to_revenue   = (existing_debt / annual_revenue * 100) if annual_revenue > 0 else 0

    # Simple heuristic readiness score out of 100
    score = 0
    score += min(years_operating, 5) * 8            # up to 40 for time in business
    score += min(max(profit_margin, 0), 30) * 1      # up to 30 for profitability
    score += 20 if collateral.lower().startswith("y") else (10 if collateral.lower().startswith("p") else 0)
    score += 10 if debt_to_revenue < 30 else (5 if debt_to_revenue < 60 else 0)
    score = round(min(score, 100))

    prompt = (
        f"You are a loan and grant readiness advisor. Assess this business:\n"
        f"Business: {business_name}\n"
        f"Years operating: {years_operating}\n"
        f"Monthly revenue: {currency} {monthly_revenue:,.2f} (profit margin {profit_margin:.1f}%)\n"
        f"Monthly profit: {currency} {monthly_profit:,.2f}\n"
        f"Existing debt: {currency} {existing_debt:,.2f} (debt-to-annual-revenue {debt_to_revenue:.1f}%)\n"
        f"Collateral available: {collateral}\n"
        f"Funding amount needed: {currency} {funding_needed:,.2f}\n"
        f"Purpose: {purpose}\n"
        f"Computed readiness score: {score}/100\n\n"
        f"Write a Readiness Report with these sections: Overall Assessment (reference the score), "
        f"Strengths, Weaknesses / Red Flags a lender would notice, Documents You Should Prepare, "
        f"and 4-5 Concrete Next Steps to improve readiness before applying."
    )
    report_raw, _ = generate_ai_reply(prompt, [])
    report_html   = format_ai_response(report_raw)

    return jsonify({
        "analysis":         report_html,
        "analysis_text":    report_raw,
        "readiness_score":  score,
        "profit_margin":    round(profit_margin, 1),
        "debt_to_revenue":  round(debt_to_revenue, 1),
        "business_name":    business_name,
        "powered_by":       "Smile Again API",
    }), 200


