# NEW BLOCK: FUNDING & GRANT MATCHER
# (backend for /api/funding/matches — used by the Grant & Loan
#  Readiness Matcher panel's "Find Matches" button)
# ===========================================================

def _safe_json_list(raw_text, key):
    """Best-effort extraction of a JSON list from an AI text response.
    Strips markdown code fences and falls back to an empty list."""
    if not raw_text:
        return []
    text = raw_text.strip()
    text = re.sub(r"^```(?:json)?\s*", "", text)
    text = re.sub(r"\s*```$", "", text)
    try:
        parsed = json.loads(text)
    except Exception:
        match = re.search(r"\[.*\]", text, re.DOTALL)
        if not match:
            return []
        try:
            parsed = json.loads(match.group(0))
        except Exception:
            return []
    if isinstance(parsed, dict):
        parsed = parsed.get(key, [])
    return parsed if isinstance(parsed, list) else []


@app.route("/api/funding/matches", methods=["POST"])
@csrf.exempt
def funding_matches_endpoint():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    gate_result = gate_ai_usage(user, "funding_matches_endpoint")
    if gate_result is not None:
        return gate_result

    data    = request.get_json() or {}
    sector  = (data.get("sector") or "").strip()
    country = (data.get("country") or "").strip()
    if not sector or not country:
        return jsonify({"error": "sector and country are required."}), 400
    revenue = float(data.get("monthly_revenue", 0) or 0)
    amount  = float(data.get("amount_needed", 0) or 0)

    prompt = (
        f"You are a funding research assistant with knowledge of real grants, microfinance "
        f"institutions, development finance institutions, angel networks, and government "
        f"funding programs. List realistic funding sources for a business in the "
        f"'{sector}' sector, based in {country}, with monthly revenue around "
        f"{revenue:,.2f} and needing about {amount:,.2f} in funding.\n\n"
        f"Reply with ONLY a raw JSON array (no markdown, no commentary) of up to 6 objects, "
        f"each shaped exactly like:\n"
        f'{{"name": "Fund or Program Name", "type": "Grant / Microloan / DFI / Angel / Government", '
        f'"max_amount": 50000, "description": "One or two sentence description of eligibility and focus."}}'
    )
    raw, _  = generate_ai_reply(prompt, [])
    matches = _safe_json_list(raw, "matches")

    cleaned = []
    for m in matches[:6]:
        if not isinstance(m, dict) or not m.get("name"):
            continue
        cleaned.append({
            "name":        str(m.get("name", ""))[:200],
            "type":        str(m.get("type", ""))[:80],
            "max_amount":  m.get("max_amount", 0) if isinstance(m.get("max_amount"), (int, float)) else 0,
            "description": str(m.get("description", ""))[:600],
        })

    return jsonify({"matches": cleaned, "sector": sector, "country": country, "powered_by": "Smile Again API"}), 200


