# NEW BLOCK: REGULATORY COMPLIANCE CHECKER
# (backend for /api/compliance/check)
# ===========================================================

@app.route("/api/compliance/check", methods=["POST"])
@csrf.exempt
def compliance_check_endpoint():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    gate_result = gate_ai_usage(user, "compliance_check_endpoint")
    if gate_result is not None:
        return gate_result

    data      = request.get_json() or {}
    biz_type  = (data.get("business_type") or "").strip()
    country   = (data.get("country") or "").strip()
    if not biz_type or not country:
        return jsonify({"error": "business_type and country are required."}), 400
    employees = int(data.get("employees", 0) or 0)

    # STAGE 72: cost breakdown — ask the AI for a real, current-best-
    # estimate registration/licensing FEE alongside each requirement, in
    # the country's actual currency, so the checker answers "how much
    # will this cost in total" and not just "what do I need".
    prompt = (
        f"You are a regulatory compliance advisor familiar with real business registration, "
        f"licensing, tax and labour requirements and their actual government fees around the world. "
        f"List the requirements for running a '{biz_type}' business in {country} with {employees} employees.\n\n"
        f"Reply with ONLY a raw JSON array (no markdown, no commentary) of up to 8 objects, "
        f"each shaped exactly like:\n"
        f'{{"name": "Requirement Name", "required": true, "description": "One or two sentence '
        f'explanation of what it is and why it applies.", "estimated_cost": 0, "currency": "USD", '
        f'"cost_note": "e.g. one-off vs annual, or \\"varies\\" if truly unpredictable"}}\n'
        f"Set \"required\": false for things that are optional/recommended rather than mandatory. "
        f"Use the country's actual official registration/licensing currency for \"currency\" "
        f"(e.g. ZAR for South Africa, USD for Zimbabwe company registration). "
        f"\"estimated_cost\" must be your best real numeric estimate of the government fee in that "
        f"currency (use 0 only if a requirement is genuinely free)."
    )
    raw, _ = generate_ai_reply(prompt, [])
    reqs   = _safe_json_list(raw, "requirements")

    cleaned = []
    currency = "USD"
    for r in reqs[:8]:
        if not isinstance(r, dict) or not r.get("name"):
            continue
        try:
            cost = float(r.get("estimated_cost", 0) or 0)
        except (TypeError, ValueError):
            cost = 0.0
        row_currency = str(r.get("currency") or "USD")[:8]
        if row_currency:
            currency = row_currency  # last non-empty wins; typically all rows agree
        cleaned.append({
            "name":           str(r.get("name", ""))[:200],
            "required":       bool(r.get("required", True)),
            "description":    str(r.get("description", ""))[:600],
            "estimated_cost": round(cost, 2),
            "currency":       row_currency,
            "cost_note":      str(r.get("cost_note", ""))[:120],
        })

    subtotal_required = round(sum(c["estimated_cost"] for c in cleaned if c["required"]), 2)
    total_all          = round(sum(c["estimated_cost"] for c in cleaned), 2)

    return jsonify({
        "requirements": cleaned, "business_type": biz_type, "country": country,
        "currency": currency,
        "subtotal_required": subtotal_required,
        "total_all": total_all,
        "cost_disclaimer": "Fee estimates are AI-generated best guesses, not official quotes — always confirm exact amounts with the relevant registrar/authority before budgeting.",
        "powered_by": "Smile Again API",
    }), 200


# ════════════════════════════════════════════════════════════
# STAGE 150: AUTO-COMPLIANCE FILING ROUTES
# Not the checklist above — this pulls the business's OWN real payroll
# and ledger numbers for a chosen period and turns them into a
# pre-filled PAYE / NSSA / VAT filing, ready to hand to an accountant
# or copy into the authority's own e-filing portal.
# ════════════════════════════════════════════════════════════
VAT_RATE_ZW = 0.155  # Zimbabwe standard VAT rate — raised from 15% to 15.5% in 2026; verified 2026-08

def _compliance_generate_paye_nssa(user_id, period_start, period_end, want="paye"):
    runs = (ErpPayrollRun.query.filter_by(owner_user_id=user_id)
            .filter(ErpPayrollRun.period_end >= period_start, ErpPayrollRun.period_start <= period_end)
            .all())
    lines, paye_total, aids_total, nssa_emp_total, nssa_er_total = [], 0.0, 0.0, 0.0, 0.0
    for run in runs:
        payslips = ErpPayslip.query.filter_by(payroll_run_id=run.id).all()
        for p in payslips:
            emp = ErpEmployee.query.get(p.employee_id)
            if not emp:
                continue
            paye_total += (p.paye or 0)
            aids_total += (p.aids_levy or 0)
            nssa_emp_total += (p.nssa_employee or 0)
            nssa_er_total += (p.nssa_employer or 0)
            lines.append({
                "employee": emp.full_name, "gross": p.gross,
                "paye": p.paye, "aids_levy": p.aids_levy,
                "nssa_employee": p.nssa_employee, "nssa_employer": p.nssa_employer,
                "payroll_period": run.period_start.isoformat() + " to " + run.period_end.isoformat(),
            })
    if want == "paye":
        total_due = round(paye_total + aids_total, 2)
        summary = {"paye_total": round(paye_total, 2), "aids_levy_total": round(aids_total, 2)}
    else:
        total_due = round(nssa_emp_total + nssa_er_total, 2)
        summary = {"nssa_employee_total": round(nssa_emp_total, 2), "nssa_employer_total": round(nssa_er_total, 2)}
    return total_due, {"summary": summary, "employee_lines": lines, "payroll_runs_included": len(runs)}


def _compliance_generate_vat(user_id, period_start, period_end):
    entries = (ErpLedgerEntry.query.filter_by(owner_user_id=user_id)
               .filter(ErpLedgerEntry.entry_date >= period_start, ErpLedgerEntry.entry_date <= period_end)
               .all())
    revenue = sum(e.amount for e in entries if e.kind == "revenue" and e.amount > 0)
    expense = sum(abs(e.amount) for e in entries if e.kind in ("expense", "cogs") and e.amount < 0)
    output_vat = round(revenue * VAT_RATE_ZW, 2)
    input_vat  = round(expense * VAT_RATE_ZW, 2)
    net_due    = round(output_vat - input_vat, 2)
    return net_due, {
        "summary": {
            "taxable_revenue": round(revenue, 2), "taxable_expenses": round(expense, 2),
            "output_vat": output_vat, "input_vat": input_vat, "net_vat_due": net_due,
            "vat_rate_used": VAT_RATE_ZW,
        },
        "note": "Output VAT is estimated on all ledger revenue and input VAT on all ledger expenses/COGS at the standard rate — exclude any zero-rated or exempt lines by hand before filing.",
    }


@app.route("/api/compliance/filing/generate", methods=["POST"])
@csrf.exempt
def compliance_filing_generate():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    filing_type = (data.get("filing_type") or "").strip().lower()
    if filing_type not in ("paye", "nssa", "vat"):
        return jsonify({"error": "filing_type must be paye, nssa, or vat."}), 400
    try:
        period_start = datetime.strptime(data.get("period_start", ""), "%Y-%m-%d").date()
        period_end   = datetime.strptime(data.get("period_end", ""), "%Y-%m-%d").date()
    except Exception:
        return jsonify({"error": "period_start and period_end must be YYYY-MM-DD."}), 400
    if period_end < period_start:
        return jsonify({"error": "period_end must be on or after period_start."}), 400

    if filing_type in ("paye", "nssa"):
        total_due, form_data = _compliance_generate_paye_nssa(user["id"], period_start, period_end, want=filing_type)
    else:
        total_due, form_data = _compliance_generate_vat(user["id"], period_start, period_end)

    filing = ComplianceFiling(
        owner_user_id=user["id"], filing_type=filing_type,
        period_start=period_start, period_end=period_end,
        total_due=total_due, currency="USD",
        form_data_json=json.dumps(form_data),
    )
    db.session.add(filing)
    db.session.commit()
    return jsonify({"filing": filing.to_dict()}), 201


