@app.route("/api/savings-groups/<path:group_name>", methods=["GET"])
def savings_group_get_endpoint(group_name):
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401

    rows = (SavingsContribution.query
            .filter_by(user_id=user["id"], group_name=group_name)
            .all())
    totals = {}
    for r in rows:
        totals[r.member_name] = totals.get(r.member_name, 0) + (r.amount or 0)
    members = [{"name": name, "total": total} for name, total in totals.items()]
    members.sort(key=lambda m: m["name"].lower())

    return jsonify({"group_name": group_name, "members": members}), 200


