# ===========================================================
# NEW BLOCK: GOOGLE DIALOGFLOW — DETECT INTENT
# Requires DIALOGFLOW_PROJECT_ID and DIALOGFLOW_CREDENTIALS_JSON
# env vars (see the CREDENTIALS section near the top of this file)
# and `pip install google-cloud-dialogflow`.
# ===========================================================

_dialogflow_session_client = None

def _get_dialogflow_session_client():
    global _dialogflow_session_client
    if not DIALOGFLOW_AVAILABLE:
        return None
    if not DIALOGFLOW_PROJECT_ID or not DIALOGFLOW_CREDENTIALS_JSON:
        return None
    if _dialogflow_session_client is not None:
        return _dialogflow_session_client
    try:
        info = json.loads(DIALOGFLOW_CREDENTIALS_JSON)
        creds = DialogflowCredentials.from_service_account_info(info)
        _dialogflow_session_client = dialogflow.SessionsClient(credentials=creds)
        return _dialogflow_session_client
    except Exception as e:
        logging.error(f"Dialogflow client init failed: {e}")
        return None


@app.route("/api/dialogflow/detect-intent", methods=["POST"])
@csrf.exempt
def dialogflow_detect_intent_endpoint():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403

    if not DIALOGFLOW_AVAILABLE:
        return jsonify({
            "error": "google-cloud-dialogflow is not installed on the server. "
                     "Run: pip install google-cloud-dialogflow"
        }), 501

    client = _get_dialogflow_session_client()
    if not client:
        return jsonify({
            "error": "Dialogflow is not configured. Set DIALOGFLOW_PROJECT_ID and "
                     "DIALOGFLOW_CREDENTIALS_JSON in your .env file."
        }), 501

    data          = request.get_json(silent=True) or {}
    text          = (data.get("text") or "").strip()
    session_id    = (data.get("session_id") or str(uuid.uuid4()))
    language_code = (data.get("language_code") or DIALOGFLOW_LANGUAGE_CODE)
    if not text:
        return jsonify({"error": "text is required."}), 400

    try:
        session = client.session_path(DIALOGFLOW_PROJECT_ID, session_id)
        text_input = dialogflow.TextInput(text=text, language_code=language_code)
        query_input = dialogflow.QueryInput(text=text_input)
        response = client.detect_intent(
            request={"session": session, "query_input": query_input}
        )
        qr = response.query_result
        parameters = dict(qr.parameters) if qr.parameters else {}

        return jsonify({
            "session_id":        session_id,
            "query_text":        qr.query_text,
            "intent":            qr.intent.display_name if qr.intent else None,
            "confidence":        qr.intent_detection_confidence,
            "fulfillment_text":  qr.fulfillment_text,
            "parameters":        parameters,
            "action":            qr.action,
            "all_required_params_present": qr.all_required_params_present,
        }), 200
    except Exception as e:
        logging.error(f"Dialogflow detect_intent failed: {e}")
        return jsonify({"error": f"Dialogflow request failed: {e}"}), 500


