# FLASK ROUTES — TWILIO WHATSAPP
# ===========================================================

@app.route("/twilio/webhook", methods=["POST"])
@csrf.exempt
def twilio_webhook():
    incoming_msg = request.form.get("Body", "").strip()
    sender_num   = request.form.get("From", "")
    owner_uid    = _find_user_for_twilio_whatsapp_number(request.form.get("To", ""))
    logging.info(f"WhatsApp from {sender_num}: '{incoming_msg}'")

    resp = MessagingResponse()
    if not incoming_msg:
        resp.message(
            "Looks like that came through empty — "
            "what did you want to say? "
        )
        return str(resp)

    if sender_num not in whatsapp_store:
        whatsapp_store[sender_num] = _db_get_history(
            sender_num, channel="whatsapp"
        )
    history = _get_history(whatsapp_store, sender_num)

    ai_reply_raw, updated_history = generate_ai_reply(incoming_msg, history)
    _save_history(whatsapp_store, sender_num, updated_history)

    _db_save_turn(sender_num, "whatsapp", "user",      incoming_msg, owner_user_id=owner_uid)
    _db_save_turn(sender_num, "whatsapp", "assistant", ai_reply_raw,  owner_user_id=owner_uid)

    display_number = sender_num.split(":")[-1]
    _db_add_gratitude(f"WhatsApp ({display_number})", incoming_msg)
    _db_add_gratitude(AI_DISPLAY_NAME, ai_reply_raw)

    if len(ai_reply_raw) <= 1600:
        resp.message(ai_reply_raw)
    else:
        for chunk in _split_into_twilio_chunks(ai_reply_raw):
            resp.message(chunk)

    return str(resp)


