@app.route("/api/v1/chat", methods=["POST"])
@_require_smile_api_key
def public_api_chat():
    data         = request.get_json() or {}
    user_message = data.get("message",    "").strip()
    custom_sid   = data.get("session_id", "").strip()

    if not user_message:
        return jsonify({"error": "message field is required."}), 400

    record     = request.smile_api_record
    session_id = (
        f"api_{record['key_hash'][:16]}_{custom_sid}"
        if custom_sid else f"api_{record['key_hash'][:16]}"
    )

    if session_id not in conversation_store:
        conversation_store[session_id] = _db_get_history(
            session_id, channel="api"
        )
    history = _get_history(conversation_store, session_id)

    reply_raw, updated_history = generate_ai_reply(user_message, history)
    _save_history(conversation_store, session_id, updated_history)

    _db_save_turn(session_id, "api", "user",      user_message)
    _db_save_turn(session_id, "api", "assistant", reply_raw)

    return jsonify({
        "reply":       reply_raw,
        "reply_html":  format_ai_response(reply_raw),
        "tier":        record["tier"],
        "usage_today": record["usage_today"],
        "limit_today": record["requests_per_day"],
        "powered_by":  "Smile Again API",
    }), 200


