# ANALYTICS
# ===========================================================

@app.route("/api/analytics/summary", methods=["GET"])
@_require_master_key
def analytics_summary():
    try:
        from sqlalchemy import func

        daily_counts = (
            db.session.query(
                func.date(ChatLog.created_at).label("day"),
                ChatLog.channel,
                func.count(ChatLog.id).label("count")
            )
            .group_by(
                func.date(ChatLog.created_at),
                ChatLog.channel
            )
            .order_by(func.date(ChatLog.created_at).desc())
            .limit(21)
            .all()
        )

        channel_counts = (
            db.session.query(
                ChatLog.channel,
                func.count(ChatLog.id).label("count")
            )
            .group_by(ChatLog.channel)
            .all()
        )

        unique_sessions = db.session.query(
            func.count(func.distinct(ChatLog.session_id))
        ).scalar()

        return jsonify({
            "unique_sessions":   unique_sessions,
            "channel_breakdown": [
                {"channel": c.channel, "messages": c.count}
                for c in channel_counts
            ],
            "daily_activity": [
                {
                    "day":      str(d.day),
                    "channel":  d.channel,
                    "messages": d.count,
                }
                for d in daily_counts
            ],
        }), 200
    except Exception as e:
        return jsonify({"error": str(e)}), 500


