@app.route("/admin/api-keys/revoke", methods=["POST"])
@_require_master_key
def admin_revoke_key():
    data   = request.get_json() or {}
    key_id = data.get("key_id", "")
    try:
        record = ApiKeyRecord.query.filter_by(key_id=key_id).first()
        if record:
            record.active = False
            db.session.commit()
            return jsonify({
                "message": f"Key revoked: {key_id[:24]}…"
            }), 200
    except Exception as e:
        db.session.rollback()
        logging.error(f"Revoke failed: {e}")
    return jsonify({"error": "Key not found."}), 404


