@app.route("/admin/status", methods=["GET"])
@_require_master_key
def admin_full_status():
    def _check(val):
        if not val:
            return {"status": "missing", "icon": ""}
        masked = val[:6] + "..." + val[-4:] if len(val) > 12 else "***"
        return {"status": "loaded", "icon": "", "preview": masked}

    try:
        db.session.execute(db.text("SELECT 1"))
        db_status = {"status": "connected", "icon": ""}
    except Exception as e:
        db_status = {"status": "error", "icon": "", "detail": str(e)}

    return jsonify({
        "timestamp": datetime.utcnow().isoformat(),
        "database":  db_status,
        "ai_providers": {
            "ollama":    {
                "status": "disabled on PythonAnywhere",
                "icon":   "",
            },
            "gemini":    {
                **_check(GEMINI_API_KEY),
                "models": GEMINI_MODELS[:3],
            },
            "openai":    {
                **_check(OPENAI_API_KEY),
                "model": OPENAI_MODEL,
            },
            "anthropic": {
                **_check(ANTHROPIC_API_KEY),
                "models": CLAUDE_MODELS,
            },
        },
        "search_engines": {
            "google_cse": {
                **_check(GOOGLE_CSE_API),
                "cse_id":     GOOGLE_CSE_ID,
                "widget_url": f"https://cse.google.com/cse.js?cx={GOOGLE_CSE_ID}",
            },
            "serpapi": _check(SERPAPI_KEY),
        },
        "media_services": {
            "replicate":  _check(REPLICATE_API_KEY),
            "stability":  _check(STABILITY_API_KEY),
            "cloudinary": {
                "status": "loaded" if cloudinary_enabled else "missing",
                "icon":   "" if cloudinary_enabled else "",
            },
        },
        "other_services": {
            "twilio": _check(TWILIO_ACCOUNT_SID),
            "smtp":   _check(SMTP_USER),
        },
        "app_keys": {
            "master_key": _check(SMILE_AGAIN_MASTER_KEY),
            "active_key": _check(SMILE_AGAIN_ACTIVE_KEY),
        },
        "summary": {
            "ready_for_chat":     bool(
                GEMINI_API_KEY or OPENAI_API_KEY or ANTHROPIC_API_KEY
            ),
            "ready_for_search":   bool(GOOGLE_CSE_API or SERPAPI_KEY),
            "ready_for_media":    bool(REPLICATE_API_KEY or STABILITY_API_KEY),
            "ready_for_whatsapp": bool(TWILIO_ACCOUNT_SID and TWILIO_AUTH_TOKEN),
            "ready_for_email":    bool(SMTP_USER and SMTP_PASS),
        },
    }), 200


