@app.route("/api/download", methods=["POST"])
@csrf.exempt
def download_document_endpoint():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403

    data     = request.get_json() or {}
    content  = data.get("content", "").strip()
    title    = data.get("title",   "document").strip()
    fmt      = data.get("format",  "pdf").strip().lower()

    if not content:
        return jsonify({"error": "content is required."}), 400

    clean_text = re.sub(r'<br\s*/?>', '\n', content, flags=re.IGNORECASE)
    clean_text = re.sub(r'</p>',      '\n\n', clean_text, flags=re.IGNORECASE)
    clean_text = re.sub(r'</li>',     '\n',   clean_text, flags=re.IGNORECASE)
    clean_text = re.sub(r'</h[1-6]>', '\n\n', clean_text, flags=re.IGNORECASE)
    clean_text = re.sub(r'<[^>]+>',   '',     clean_text)
    clean_text = clean_text.replace('&amp;','&').replace('&lt;','<') \
                            .replace('&gt;','>').replace('&nbsp;',' ') \
                            .replace('&quot;','"').replace('&#39;',"'")
    clean_text = re.sub(r'\n{3,}', '\n\n', clean_text).strip()

    if fmt == "txt":
        buf = io.BytesIO(clean_text.encode("utf-8"))
        buf.seek(0)
        return Response(
            buf,
            mimetype    = "text/plain",
            headers     = {
                "Content-Disposition": f'attachment; filename="{title}.txt"'
            }
        )

    if fmt == "docx" and DOCX_AVAILABLE:
        try:
            doc  = Document()
            head = doc.add_heading(title, 0)
            head.runs[0].font.color.rgb = RGBColor(0x1e, 0x3a, 0x8a)
            for para in clean_text.split('\n\n'):
                para = para.strip()
                if para:
                    doc.add_paragraph(para)
            buf = io.BytesIO()
            doc.save(buf)
            buf.seek(0)
            return Response(
                buf,
                mimetype = "application/vnd.openxmlformats-officedocument"
                           ".wordprocessingml.document",
                headers  = {
                    "Content-Disposition": f'attachment; filename="{title}.docx"'
                }
            )
        except Exception as e:
            logging.error(f"DOCX generation failed: {e}")

    if fmt == "pdf" and REPORTLAB_AVAILABLE:
        try:
            buf = io.BytesIO()
            doc = SimpleDocTemplate(
                buf,
                pagesize     = A4,
                rightMargin  = 40,
                leftMargin   = 40,
                topMargin    = 50,
                bottomMargin = 40,
            )
            styles   = getSampleStyleSheet()
            story    = []
            story.append(Paragraph(title, styles['Title']))
            story.append(Spacer(1, 12))
            for para in clean_text.split('\n\n'):
                para = para.strip()
                if para:
                    safe = para.replace('&','&amp;').replace('<','&lt;').replace('>','&gt;')
                    story.append(Paragraph(safe, styles['Normal']))
                    story.append(Spacer(1, 8))
            doc.build(story)
            buf.seek(0)
            return Response(
                buf,
                mimetype = "application/pdf",
                headers  = {
                    "Content-Disposition": f'attachment; filename="{title}.pdf"'
                }
            )
        except Exception as e:
            logging.error(f"PDF generation failed: {e}")

    buf = io.BytesIO(clean_text.encode("utf-8"))
    buf.seek(0)
    return Response(
        buf,
        mimetype = "text/plain",
        headers  = {"Content-Disposition": f'attachment; filename="{title}.txt"'}
    )

# ===========================================================
# DIRECT MESSAGES — Full backend, backed by the real DirectMessage
# table above (see its docstring for why the old version was fake:
# it stored everything in a plain Python list that lived in one
# process's memory only). dm_sse_clients/presence_store below stay
# as in-memory state on purpose — they're live/ephemeral (who's
# online right now, who has a stream open right now), not data that
# needs to survive a restart, so there's nothing "fake" about them.
# ===========================================================

dm_sse_clients  = {}
dm_typing_state = {}
presence_store  = {}

@app.route("/api/dm/send", methods=["POST"])
@csrf.exempt
def dm_send():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401

    data        = request.get_json() or {}
    receiver_id = data.get("receiver_id")
    content     = data.get("content", "").strip()

    if not receiver_id or not content:
        return jsonify({"error": "receiver_id and content required."}), 400
    if guardianCheck_py(content):
        return jsonify({"error": "Message blocked by content guardian."}), 400
    receiver = UserAccount.query.get(int(receiver_id))
    if not receiver or not receiver.is_active:
        return jsonify({"error": "That user does not exist."}), 404

    msg = DirectMessage(sender_id=user["id"], receiver_id=receiver.id, content=content)
    db.session.add(msg)
    db.session.commit()
    msg_dict = msg.to_dict()

    _dm_broadcast(receiver.id,  {"type": "new_message", "message": msg_dict})
    _dm_broadcast(user["id"],   {"type": "new_message", "message": msg_dict})

    return jsonify({"message": msg_dict}), 200


@app.route("/api/dm/start", methods=["POST"])
@csrf.exempt
def dm_start():
    """Starts (or continues) a conversation by email address, for the
    'New Message' compose form — the sender may not know the
    recipient's numeric user id or see them in a search list yet.
    Looks the recipient up against the real user_accounts table; if
    no account with that email exists, this returns a real 404 rather
    than silently pretending the message sent."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401

    data    = request.get_json() or {}
    email   = (data.get("recipient_email") or "").strip().lower()
    content = (data.get("content") or "").strip()

    if not email or not content:
        return jsonify({"error": "recipient_email and content are required."}), 400
    if guardianCheck_py(content):
        return jsonify({"error": "Message blocked by content guardian."}), 400

    receiver = UserAccount.query.filter(
        db.func.lower(UserAccount.email) == email
    ).first()
    if not receiver or not receiver.is_active:
        return jsonify({"ok": False, "error": f"No Connect It account found for {email}."}), 404
    if receiver.id == user["id"]:
        return jsonify({"ok": False, "error": "You can't message yourself."}), 400

    msg = DirectMessage(sender_id=user["id"], receiver_id=receiver.id, content=content)
    db.session.add(msg)
    db.session.commit()
    msg_dict = msg.to_dict()

    _dm_broadcast(receiver.id, {"type": "new_message", "message": msg_dict})
    _dm_broadcast(user["id"],  {"type": "new_message", "message": msg_dict})

    return jsonify({
        "ok": True,
        "message": msg_dict,
        "recipient": {
            "id": receiver.id, "name": receiver.name, "email": receiver.email,
            "is_online": receiver.id in presence_store and (time.time() - presence_store[receiver.id]) < 60,
        },
    }), 200


@app.route("/api/users/lookup-by-email", methods=["GET"])
@csrf.exempt
def users_lookup_by_email():
    """Real-time validation for the 'New Message' compose form: as the
    person types a recipient's email, this confirms whether a real
    Connect It account exists for it and returns their display name —
    so the Send button only ever fires at a genuine account, never a
    made-up address."""
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    email = (request.args.get("email") or "").strip().lower()
    if not email:
        return jsonify({"found": False}), 200
    match = UserAccount.query.filter(
        db.func.lower(UserAccount.email) == email,
        UserAccount.is_active == True
    ).first()
    if not match:
        return jsonify({"found": False}), 200
    if match.id == user["id"]:
        return jsonify({"found": False, "error": "That's your own account."}), 200
    return jsonify({
        "found": True, "id": match.id, "name": match.name, "email": match.email,
        "is_online": match.id in presence_store and (time.time() - presence_store[match.id]) < 60,
    }), 200


