@app.route("/api/dm/inbox", methods=["GET"])
@csrf.exempt
def dm_inbox():
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401

    uid   = user["id"]
    convs = []
    seen  = set()

    recent = (
        DirectMessage.query.filter(
            db.or_(DirectMessage.sender_id == uid, DirectMessage.receiver_id == uid)
        )
        .order_by(DirectMessage.id.desc())
        .limit(500)
        .all()
    )
    for msg in recent:
        other = msg.receiver_id if msg.sender_id == uid else msg.sender_id
        if other in seen:
            continue
        seen.add(other)
        try:
            partner_obj = UserAccount.query.get(other)
            partner = {
                "id":        other,
                "name":      partner_obj.name  if partner_obj else f"User {other}",
                "email":     partner_obj.email if partner_obj else "",
                "is_online": other in presence_store and
                             (time.time() - presence_store[other]) < 60,
            }
        except Exception:
            partner = {"id": other, "name": f"User {other}", "email": "", "is_online": False}
        unread = DirectMessage.query.filter(
            DirectMessage.sender_id == other, DirectMessage.receiver_id == uid, DirectMessage.read == False
        ).count()
        convs.append({
            "partner":      partner,
            "last_message": msg.to_dict(),
            "unread_count": unread,
        })

    return jsonify({"conversations": convs}), 200


