@app.route("/api/dm/stream", methods=["GET"])
def dm_stream():
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    uid = user["id"]

    def event_stream():
        queue = []
        dm_sse_clients[uid] = queue
        try:
            yield "data: {\"type\":\"connected\"}\n\n"
            last_ping = time.time()
            while True:
                if queue:
                    event = queue.pop(0)
                    yield f"data: {json.dumps(event)}\n\n"
                if time.time() - last_ping > 25:
                    yield "data: {\"type\":\"ping\"}\n\n"
                    last_ping = time.time()
                time.sleep(0.3)
        except GeneratorExit:
            dm_sse_clients.pop(uid, None)

    return Response(
        stream_with_context(event_stream()),
        mimetype = "text/event-stream",
        headers  = {
            "X-Accel-Buffering": "no",
            "Cache-Control":     "no-cache",
            "Connection":        "keep-alive",
        }
    )


# ════════════════════════════════════════════════════════════
# STAGE 359: LIVE CHAT TRANSLATION — ROUTES
# ════════════════════════════════════════════════════════════

def _user_locale(user_id: int) -> str:
    u = UserAccount.query.get(user_id)
    return (u.locale if u and u.locale else "en")


def _dm_translate_text(text: str, target_lang: str, user_id: int):
    """Real translation, never fabricated. Prefers Google Cloud
    Translate (whichever account has it configured, via the same
    get_effective_credential lookup every other Google integration on
    this platform uses); falls back to the AI translation chain only
    when Google Translate isn't configured, same fallback style as
    /api/translate. Returns (translated_text, detected_source_lang)."""
    g = google_translate_text(text, target_lang, user_id=user_id)
    if g.get("ok"):
        return g.get("translated_text"), g.get("detected_source_language")
    prompt = (
        f"Translate the following chat message into language code '{target_lang}'. "
        f"Return ONLY the translated text, nothing else, no quotes.\n\nTEXT:\n{text}"
    )
    translated, _ = generate_ai_reply(prompt, [])
    return (translated or "").strip(), None


def _get_or_create_dm_translation(message: DirectMessage, target_lang: str, user_id: int):
    if not message.content or message.deleted:
        return None
    existing = DmMessageTranslation.query.filter_by(
        message_id=message.id, target_lang=target_lang
    ).first()
    if existing:
        return existing
    translated_text, detected = _dm_translate_text(message.content, target_lang, user_id)
    if not translated_text:
        return None
    row = DmMessageTranslation(
        message_id=message.id, target_lang=target_lang,
        translated_text=translated_text, detected_source_lang=detected,
    )
    db.session.add(row)
    try:
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        # Another request may have cached the same (message_id, target_lang)
        # concurrently — that's fine, just read what's there now.
        existing = DmMessageTranslation.query.filter_by(
            message_id=message.id, target_lang=target_lang
        ).first()
        if existing:
            return existing
        logging.error(f"[DM TRANSLATION CACHE ERROR] msg={message.id}: {e}")
        return None
    return row


@app.route("/api/dm/translate", methods=["POST"])
@csrf.exempt
def dm_translate_message():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    message_id  = data.get("message_id")
    target_lang = (data.get("target_lang") or "").strip()[:8]
    message = DirectMessage.query.get(message_id) if message_id else None
    if not message:
        return jsonify({"error": "Message not found."}), 404
    if user["id"] not in (message.sender_id, message.receiver_id):
        return jsonify({"error": "You weren't a party to this conversation."}), 403
    if not target_lang:
        target_lang = _user_locale(user["id"])
    gate_result = gate_ai_usage(user, "dm_translate")
    if gate_result is not None:
        return gate_result
    row = _get_or_create_dm_translation(message, target_lang, user["id"])
    if not row:
        return jsonify({"error": "Could not translate that message right now."}), 502
    return jsonify({"ok": True, "translation": row.to_dict()}), 200


@app.route("/api/dm/translate/conversation/<int:other_id>", methods=["GET"])
def dm_translate_conversation(other_id):
    """Bulk-translates a conversation's visible history in one call so
    flipping Live Translate on doesn't fire one request per message."""
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    target_lang = (request.args.get("target_lang") or _user_locale(user["id"])).strip()[:8]
    limit = min(int(request.args.get("limit", 50) or 50), 100)
    gate_result = gate_ai_usage(user, "dm_translate")
    if gate_result is not None:
        return gate_result
    messages = (DirectMessage.query
                .filter(db.or_(
                    db.and_(DirectMessage.sender_id == user["id"], DirectMessage.receiver_id == other_id),
                    db.and_(DirectMessage.sender_id == other_id, DirectMessage.receiver_id == user["id"]),
                ))
                .filter(DirectMessage.deleted == False)
                .order_by(DirectMessage.id.desc()).limit(limit).all())
    translations = []
    for m in messages:
        row = _get_or_create_dm_translation(m, target_lang, user["id"])
        if row:
            translations.append(row.to_dict())
    return jsonify({"target_lang": target_lang, "translations": translations}), 200


def _dm_broadcast(user_id, event: dict):
    uid   = int(user_id) if user_id else None
    queue = dm_sse_clients.get(uid)
    if queue is not None:
        queue.append(event)


def guardianCheck_py(text: str) -> bool:
    forbidden = [
        'fuck','sex','nude','naked','porn', 'anus', 'mhata', 'mboro', 'critoris',
        'matuzvi', 'machende', 'shondo', 'mukosho', 'matinji', 'duzvi', 'musuri',
        'nyini', 'cum on me', 'fuck hard', 'erotic',
        'dick','cock','penis','vagina','pussy','cunt','slut','whore','rape',
        'nigger','nigga','kike','spic','chink','faggot','retard',
        'kill yourself','kys','bomb','terrorist','heroin','cocaine',
    ]
    lower = text.lower()
    return any(w in lower for w in forbidden)

