@app.route("/api/users/search", methods=["GET"])
@csrf.exempt
def users_search():
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    q = request.args.get("q", "").strip()
    if not q:
        return jsonify({"users": []}), 200
    try:
        results = UserAccount.query.filter(
            (UserAccount.name.ilike(f"%{q}%")) |
            (UserAccount.email.ilike(f"%{q}%"))
        ).filter(
            UserAccount.id != user["id"],
            UserAccount.is_active == True
        ).limit(10).all()
        users = [
            {
                "id":        u.id,
                "name":      u.name,
                "email":     u.email,
                "is_online": u.id in presence_store and
                             (time.time() - presence_store[u.id]) < 60,
            }
            for u in results
        ]
        return jsonify({"users": users}), 200
    except Exception as e:
        return jsonify({"error": str(e)}), 500


@app.route("/api/users/online", methods=["GET"])
@csrf.exempt
def users_online():
    user = _get_current_user()
    if not user:
        return jsonify({"online_users": []}), 200
    cutoff = time.time() - 60
    online_ids = [uid for uid, ts in presence_store.items() if ts > cutoff]
    try:
        results = UserAccount.query.filter(
            UserAccount.id.in_(online_ids),
            UserAccount.id != user["id"],
            UserAccount.is_active == True
        ).limit(50).all()
        return jsonify({
            "online_users": [
                {
                    "id":        u.id,
                    "name":      u.name,
                    "email":     u.email,
                    "is_online": True,
                }
                for u in results
            ]
        }), 200
    except Exception as e:
        return jsonify({"online_users": []}), 200


