# ===========================================================
# GMAIL ASSISTANT — real Gmail API, using the same per-user Google OAuth
# token (GoogleOAuthToken) as Calendar. Requires CLIENT_ID/CLIENT_SECRET/
# GOOGLE_OAUTH_REDIRECT_URI to be set (see google_auth_url above), and the
# Gmail API enabled on the same Google Cloud project. In Google's
# "Testing" publishing status this works for up to 100 named test users
# (added under OAuth consent screen -> Test users) with no further
# review; a fully public launch needs Google's verification review
# because gmail.send/modify/readonly are "sensitive" scopes.
# ===========================================================

_GMAIL_REQUIRED_SCOPE = "gmail.readonly"


def _gmail_headers(user_id):
    token = get_valid_google_token(user_id, required_scope=_GMAIL_REQUIRED_SCOPE)
    if not token:
        return None
    return {"Authorization": f"Bearer {token}"}


@app.route("/api/gmail/check_auth_status", methods=["GET"])
@csrf.exempt
def gmail_check_auth():
    user = _get_current_user()
    if not user:
        return jsonify({"authenticated": False}), 200
    token = get_valid_google_token(user["id"], required_scope=_GMAIL_REQUIRED_SCOPE)
    return jsonify({"authenticated": bool(token)}), 200


@app.route("/api/gmail/auth", methods=["GET"])
def gmail_auth():
    """Opened in a popup by the frontend. Redirects the browser straight
    to Google's real consent screen for Gmail (+ Calendar) scopes, then
    Google redirects back to /api/google/oauth/callback which saves the
    token and closes the popup."""
    if not CLIENT_ID or not CLIENT_SECRET or not GOOGLE_OAUTH_REDIRECT_URI:
        return """
        <html><body style='font-family:sans-serif;padding:40px;text-align:center;'>
        <h2>Gmail OAuth Not Configured</h2>
        <p>Set CLIENT_ID, CLIENT_SECRET and GOOGLE_OAUTH_REDIRECT_URI to enable Gmail.</p>
        <script>setTimeout(function(){window.close();},3000);</script>
        </body></html>
        """, 200
    user = _get_current_user()
    if not user:
        return """
        <html><body style='font-family:sans-serif;padding:40px;text-align:center;'>
        <h2>Please log in to Connect It first, then reconnect Gmail.</h2>
        <script>setTimeout(function(){window.close();},3000);</script>
        </body></html>
        """, 200
    params = {
        "client_id":     CLIENT_ID,
        "redirect_uri":  GOOGLE_OAUTH_REDIRECT_URI,
        "response_type": "code",
        "scope":         _google_oauth_scope_for_service("gmail"),
        "access_type":   "offline",
        "prompt":        "consent",
        "include_granted_scopes": "true",
        "state":         f"{user['id']}:gmail",
    }
    url = "https://accounts.google.com/o/oauth2/v2/auth?" + "&".join(
        f"{k}={requests.utils.quote(str(v))}" for k, v in params.items()
    )
    return redirect(url)


def _gmail_decode_headers(payload_headers: list) -> dict:
    out = {}
    for h in payload_headers or []:
        name = (h.get("name") or "").lower()
        if name in ("from", "subject", "date"):
            out[name] = h.get("value", "")
    return out


def _gmail_extract_body(payload: dict) -> str:
    """Walks a Gmail message payload for the first text/plain (falling
    back to text/html) part and base64url-decodes it."""
    def _decode(data: str) -> str:
        try:
            return base64.urlsafe_b64decode(data + "=" * (-len(data) % 4)).decode("utf-8", errors="replace")
        except Exception:
            return ""

    if not payload:
        return ""
    if payload.get("body", {}).get("data"):
        return _decode(payload["body"]["data"])
    for part in payload.get("parts", []) or []:
        if part.get("mimeType") == "text/plain" and part.get("body", {}).get("data"):
            return _decode(part["body"]["data"])
    for part in payload.get("parts", []) or []:
        if part.get("mimeType") == "text/html" and part.get("body", {}).get("data"):
            return _decode(part["body"]["data"])
    for part in payload.get("parts", []) or []:
        nested = _gmail_extract_body(part)
        if nested:
            return nested
    return ""


@app.route("/api/gmail/inbox", methods=["GET"])
@csrf.exempt
def gmail_inbox():
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    headers = _gmail_headers(user["id"])
    if not headers:
        return jsonify({"emails": [], "message": "Connect Gmail via OAuth to see real emails."}), 200
    try:
        list_r = requests.get(
            "https://gmail.googleapis.com/gmail/v1/users/me/messages",
            headers=headers, params={"maxResults": 15, "q": "in:inbox"}, timeout=15,
        )
        if list_r.status_code != 200:
            logging.error(f"[GMAIL LIST ERROR] {list_r.text}")
            return jsonify({"emails": [], "error": "Could not list Gmail messages."}), 200
        message_ids = [m["id"] for m in list_r.json().get("messages", [])]
        emails = []
        for mid in message_ids:
            msg_r = requests.get(
                f"https://gmail.googleapis.com/gmail/v1/users/me/messages/{mid}",
                headers=headers, params={"format": "full"}, timeout=15,
            )
            if msg_r.status_code != 200:
                continue
            msg = msg_r.json()
            hdrs = _gmail_decode_headers((msg.get("payload") or {}).get("headers"))
            emails.append({
                "id": msg.get("id"),
                "threadId": msg.get("threadId"),
                "sender": hdrs.get("from", ""),
                "subject": hdrs.get("subject", "(No subject)"),
                "snippet": msg.get("snippet", ""),
                "body": _gmail_extract_body(msg.get("payload")) or msg.get("snippet", ""),
                "date": hdrs.get("date", ""),
            })
        return jsonify({"emails": emails}), 200
    except Exception as e:
        logging.error(f"[GMAIL INBOX ERROR] user={user['id']}: {e}")
        return jsonify({"emails": [], "error": str(e)}), 200


@app.route("/api/gmail/send-response", methods=["POST"])
@csrf.exempt
def gmail_send_response():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    headers = _gmail_headers(user["id"])
    if not headers:
        return jsonify({"error": "Gmail is not connected. Connect it under the Gmail Assistant panel."}), 400

    data      = request.get_json(force=True, silent=True) or {}
    recipient = (data.get("recipient") or "").strip()
    subject   = (data.get("subject") or "").strip() or "(No subject)"
    body_text = data.get("body") or ""
    thread_id = data.get("threadId") or ""

    if not recipient or "@" not in recipient:
        return jsonify({"error": "A valid 'recipient' is required."}), 400
    if not body_text.strip():
        return jsonify({"error": "'body' is required."}), 400

    try:
        mime_msg = MIMEText(body_text)
        mime_msg["to"] = recipient
        mime_msg["subject"] = subject
        raw = base64.urlsafe_b64encode(mime_msg.as_bytes()).decode("utf-8")
        payload = {"raw": raw}
        if thread_id:
            payload["threadId"] = thread_id
        r = requests.post(
            "https://gmail.googleapis.com/gmail/v1/users/me/messages/send",
            headers={**headers, "Content-Type": "application/json"},
            json=payload, timeout=15,
        )
        body = r.json()
        if r.status_code >= 400:
            return jsonify({"error": (body.get("error") or {}).get("message", "Gmail send failed.")}), 502
        return jsonify({"message": "Email sent successfully.", "id": body.get("id")}), 200
    except Exception as e:
        logging.error(f"[GMAIL SEND ERROR] user={user['id']}: {e}")
        return jsonify({"error": str(e)}), 502


