@app.route("/api/rss/fetch", methods=["GET"])
@csrf.exempt
def rss_fetch_proxy():
    feed_url = request.args.get("url", "").strip()
    if not feed_url:
        return jsonify({"error": "url parameter required."}), 400

    try:
        api_url = f"https://api.rss2json.com/v1/api.json?rss_url={feed_url}&count=10"
        r = requests.get(api_url, timeout=12)
        if r.status_code != 200:
            return jsonify({"error": "Feed fetch failed.", "items": []}), 200
        data = r.json()
        return jsonify({
            "status": data.get("status", "ok"),
            "items":  data.get("items", []),
        }), 200
    except Exception as e:
        logging.error(f"RSS proxy failed: {e}")
        return jsonify({"error": str(e), "items": []}), 200


@app.route("/api/qrcode/generate", methods=["POST"])
@csrf.exempt
def generate_qr_code_alias():
    """Generate QR code server-side. Returns PNG as base64. (alias of /api/tools/qr/generate)"""
    try:
        data    = request.get_json(force=True) or {}
        content = data.get("data", "")
        size    = int(data.get("size", 300))
        color   = data.get("color", "000000")
        bg      = data.get("background", "ffffff")

        if not content:
            return connectit_json_response({"error": "QR data required"}, 400)

        size = max(100, min(size, 1000))

        try:
            import qrcode
            from PIL import Image
            import io as _io

            def hex_to_rgb(h):
                h = h.lstrip("#")
                return tuple(int(h[i:i+2], 16) for i in (0, 2, 4))

            qr = qrcode.QRCode(
                version=1,
                error_correction=qrcode.constants.ERROR_CORRECT_M,
                box_size=10,
                border=4
            )
            qr.add_data(content)
            qr.make(fit=True)
            img = qr.make_image(
                fill_color=hex_to_rgb(color),
                back_color=hex_to_rgb(bg)
            )
            img = img.resize((size, size), Image.LANCZOS)
            buf = _io.BytesIO()
            img.save(buf, format="PNG")
            img_b64 = base64.b64encode(buf.getvalue()).decode()
            return connectit_json_response({
                "image_base64": img_b64,
                "mime_type":    "image/png",
                "size":         size
            })
        except ImportError:
            qr_url = (
                f"https://api.qrserver.com/v1/create-qr-code/"
                f"?size={size}x{size}&color={color}&bgcolor={bg}"
                f"&data={requests.utils.quote(content)}"
            )
            return connectit_json_response({
                "url":      qr_url,
                "fallback": True,
                "message":  "Using external QR service (qrcode library not installed)"
            })
    except Exception as e:
        logging.error(f"[QR ERROR] {e}")
        return connectit_json_response({"error": str(e)}, 500)


@app.route("/api/files/analyze", methods=["POST"])
@csrf.exempt
def analyze_files_endpoint():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403

    if "files" not in request.files:
        return jsonify({"error": "no_files"}), 400

    MAX_UPLOAD_BYTES = 15 * 1024 * 1024
    results = []
    for f in request.files.getlist("files"):
        raw = f.read()
        if len(raw) > MAX_UPLOAD_BYTES:
            results.append({"name": f.filename, "size": len(raw), "error": "File too large to analyze (15MB limit)"})
            continue
        results.append({"name": f.filename, "size": len(raw), "content": fi_extract(f.filename, raw)})

    return jsonify({"files": results}), 200


@csrf.exempt
@app.route("/api/sheets/sync", methods=["POST"])
@csrf.exempt
def sheets_sync_alias():
    """Sync data from Connect It to Google Sheets. (alias of /api/integrations/sheets/sync)"""
    user = _get_current_user()
    if not user:
        return connectit_json_response({"error": "Login required."}, 401)
    try:
        data           = request.get_json(force=True) or {}
        spreadsheet_id = data.get("spreadsheet_id", "")
        api_key_json   = get_effective_credential(user["id"], "google_sheets", "service_account_json", None)
        sheet_name     = data.get("sheet_name", "Data")
        table_key      = data.get("table_key", "custom")
        raw_data       = data.get("data", data.get("rows", []))

        if not spreadsheet_id:
            return connectit_json_response({"error": "Spreadsheet ID required"}, 400)
        if not raw_data:
            return connectit_json_response({
                "synced": True, "rows": 0, "message": "No data to sync"})

        client = get_gspread_client(api_key_json)
        if not client:
            return connectit_json_response({
                "error": "Google Sheets isn't connected yet. Add your service-account "
                         "JSON in Integrations, or download CSV instead.",
                "csv_fallback": True,
                "data":         raw_data
            }, 503)

        try:
            spreadsheet = client.open_by_key(spreadsheet_id)
        except gspread.SpreadsheetNotFound:
            return connectit_json_response(
                {"error": "Spreadsheet not found. Check the ID and sharing permissions."}, 404)

        try:
            worksheet = spreadsheet.worksheet(sheet_name)
        except gspread.WorksheetNotFound:
            worksheet = spreadsheet.add_worksheet(
                title=sheet_name, rows="1000", cols="26")

        headers, rows = prepare_sheet_data(table_key, raw_data)
        sync_time = datetime.utcnow().strftime("%Y-%m-%d %H:%M UTC")
        all_rows  = (
            [[f"Connect It — {sheet_name} — Synced: {sync_time}"]] +
            [[""] * max(len(headers), 1)] +
            [headers] +
            rows
        )
        worksheet.clear()
        worksheet.update("A1", all_rows, value_input_option="USER_ENTERED")

        try:
            worksheet.format("A3:Z3", {
                "textFormat":      {"bold": True},
                "backgroundColor": {"red": 0.12, "green": 0.23, "blue": 0.54}
            })
        except Exception:
            pass

        logging.info(f"[SHEETS SYNC] {table_key} → {sheet_name} | {len(rows)} rows")
        return connectit_json_response({
            "synced":    True,
            "rows":      len(rows),
            "sheet":     sheet_name,
            "columns":   len(headers),
            "synced_at": sync_time
        })
    except Exception as e:
        logging.error(f"[SHEETS SYNC ERROR] {e}")
        return connectit_json_response({"error": str(e)}, 500)


