def _get_user_key() -> str:
    """Returns a stable per-user key (logged-in user id, or session-based guest id)."""
    user = _get_current_user()
    if user and user.get("id"):
        return "user_" + str(user["id"])
    if "guest_key" not in session:
        session["guest_key"] = "guest_" + secrets.token_hex(12)
    return session["guest_key"]


