@app.route("/api/soul/grief/checkins", methods=["GET"])
@csrf.exempt
def soul_grief_checkins():
    """Returns entries due for a weekly check-in and updates their lastChecked."""
    try:
        rows = GriefEntry.query.filter_by(user_key=_get_user_key()).all()
        due = []
        now = datetime.utcnow()
        for r in rows:
            last = r.last_checked or r.created_at or now
            if (now - last).days >= 7:
                r.last_checked = now
                r.check_in_count = (r.check_in_count or 0) + 1
                due.append(r.to_dict())
        db.session.commit()
        return jsonify({"due": due}), 200
    except Exception as e:
        db.session.rollback()
        return jsonify({"due": [], "error": str(e)}), 200


