    user, err = _erp_user_or_401()
    if err:
        return err
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    gate_result = gate_ai_usage(user, "soul_dreams_interpret")
    if gate_result is not None:
        return gate_result
    try:
        rows = (DreamEntry.query
                .filter_by(user_key=_get_user_key())
                .order_by(DreamEntry.created_at.desc())
                .limit(20).all())
        if not rows:
            return jsonify({"error": "No dreams recorded yet."}), 400
        summary = "\n\n".join(
            f"{i+1}. {r.title}: {r.content}" for i, r in enumerate(rows)
        )
        prompt = (
            "You are a deeply intuitive dream analyst with knowledge of Jungian "
            "psychology, symbolism, and pattern recognition. Analyse these "
            f"{len(rows)} recorded dreams in full and find recurring themes, symbols, "
            "emotions, and patterns. Give deep, personal, poetic insights — not "
            "generic horoscope-style answers. Find the real subconscious story "
            f"being told:\n\n{summary}"
        )
        raw, _ = generate_ai_reply(prompt, [])
        # Permanent record: the generated interpretation is archived to the
        # user's Memory log so it can be reread later, indefinitely.
        save_to_memory(user["id"], "assistant", raw,
                        content_type="dream_interpretation", extra={"source": "Dream Interpreter"})
        return jsonify({
            "interpretation": format_ai_response(raw),
            "interpretation_text": raw,
        }), 200
    except Exception as e:
        return jsonify({"error": str(e)}), 500


