def _iso_week(dt: datetime) -> int:
    return int(dt.strftime("%V"))


@app.route("/api/soul/emotions", methods=["GET", "POST"])
@csrf.exempt
def soul_emotions():
    if request.method == "GET":
        try:
            rows = (EmotionEntry.query
                    .filter_by(user_key=_get_user_key())
                    .order_by(EmotionEntry.created_at.desc())
                    .limit(365).all())
            return jsonify({"entries": [r.to_dict() for r in rows]}), 200
        except Exception as e:
            return jsonify({"entries": [], "error": str(e)}), 200

    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    data = request.get_json() or {}
    mood = (data.get("mood") or "").strip()
    note = (data.get("note") or "").strip()
    if not mood:
        return jsonify({"error": "mood field is required."}), 400
    try:
        now = datetime.utcnow()
        entry = EmotionEntry(user_key=_get_user_key(), mood=mood, note=note,
                              week_number=_iso_week(now))
        db.session.add(entry)
        db.session.commit()
        return jsonify({"entry": entry.to_dict()}), 201
    except Exception as e:
        db.session.rollback()
        return jsonify({"error": str(e)}), 500


@app.route("/api/soul/emotions/shift-check", methods=["GET"])
@csrf.exempt
def soul_emotions_shift_check():
    try:
        now = datetime.utcnow()
        this_week = _iso_week(now)
        last_week = this_week - 1 if this_week > 1 else 52
        rows = (EmotionEntry.query
                .filter_by(user_key=_get_user_key())
                .filter(EmotionEntry.week_number.in_([this_week, last_week]))
                .all())
        neg = {"sad", "anxious", "angry", "overwhelmed", "lost", "tired"}
        this_neg = sum(1 for r in rows if r.week_number == this_week and r.mood in neg)
        last_neg = sum(1 for r in rows if r.week_number == last_week and r.mood in neg)
        shift = this_neg > last_neg + 2
        return jsonify({"shift_detected": shift,
                         "this_week_negative": this_neg,
                         "last_week_negative": last_neg}), 200
    except Exception as e:
        return jsonify({"shift_detected": False, "error": str(e)}), 200


