@app.route("/api/soul/legacy/write", methods=["POST"])
@csrf.exempt
def soul_legacy_write():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    gate_result = gate_ai_usage(user, "soul_legacy_write")
    if gate_result is not None:
        return gate_result
    data = request.get_json() or {}
    title = (data.get("title") or "").strip()
    story = (data.get("story") or "").strip()
    save_id = data.get("chapter_id")
    if not story:
        return jsonify({"error": "story field is required."}), 400
    try:
        previous = (LegacyChapter.query
                    .filter_by(user_key=_get_user_key())
                    .order_by(LegacyChapter.created_at.desc())
                    .limit(3).all())
        context = ""
        if previous:
            context = "\n\nPrevious chapters for context:\n" + "\n".join(
                f"{c.title}: {c.raw_story[:300]}" for c in previous
            )
        prompt = (
            "You are a master literary biographer — someone who turns ordinary "
            "lives into extraordinary literature. Take this raw personal narrative "
            "and transform it into a beautifully written, COMPLETE chapter for a "
            "family memoir. Preserve every real detail, emotion, and truth in full "
            "— do not shorten or summarise any part of it — but elevate the "
            "language into something their grandchildren will read with tears in "
            "their eyes and pride in their hearts. Write in first person. Make it "
            f"timeless and complete from beginning to end:\n\n"
            f"Chapter Title: {title or 'Untitled'}\n\n"
            f"Raw Narrative:\n{story}{context}"
        )
        raw, _ = generate_ai_reply(prompt, [])

        # Save / update the chapter with the full polished story
        if save_id:
            chapter = LegacyChapter.query.filter_by(
                id=save_id, user_key=_get_user_key()
            ).first()
        else:
            chapter = None

        if chapter:
            chapter.raw_story = story
            if title:
                chapter.title = title
            chapter.polished_story = raw
            chapter.updated_at = datetime.utcnow()
        else:
            count = LegacyChapter.query.filter_by(user_key=_get_user_key()).count()
            chapter = LegacyChapter(
                user_key=_get_user_key(),
                title=title or f"Chapter {count + 1}",
                raw_story=story,
                polished_story=raw
            )
            db.session.add(chapter)

        db.session.commit()
        return jsonify({
            "chapter": chapter.to_dict(),
            "polished_html": format_ai_response(raw),
        }), 200
    except Exception as e:
        db.session.rollback()
        return jsonify({"error": str(e)}), 500


