@app.route("/api/soul/silence/translate", methods=["POST"])
@csrf.exempt
def soul_silence_translate():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    gate_result = gate_ai_usage(user, "soul_silence_translate")
    if gate_result is not None:
        return gate_result

    data             = request.get_json() or {}
    tap_count        = int(data.get("total_taps",              0))
    avg_pause        = int(data.get("avg_pause_ms",            0))
    fast_bursts      = int(data.get("fast_bursts",             0))
    long_pauses      = int(data.get("long_silences",           0))
    duration_sec     = int(data.get("session_duration_sec",    0))
    gibberish        = (data.get("gibberish")                 or "").strip()
    gib_len          = int(data.get("gibberish_length",        0))
    gib_repeat       = int(data.get("gibberish_repeated_chars",0))

    prompt = (
        "You are the Silence Translator — an emotionally intelligent AI that "
        "reads the physical rhythm of someone's keystrokes, taps and pauses "
        "to understand what they are feeling when they cannot find words.\n\n"
        "The person gave you these somatic signals:\n"
        f"- Total taps/keystrokes: {tap_count}\n"
        f"- Average pause between taps: {avg_pause}ms\n"
        f"- Fast bursts (taps under 300ms apart): {fast_bursts}\n"
        f"- Long silences (pauses over 1500ms): {long_pauses}\n"
        f"- Session duration: {duration_sec} seconds\n"
        f"- Gibberish typed: \"{gibberish}\" "
        f"({gib_len} chars, {gib_repeat} repeated patterns)\n\n"
        "Analyse this rhythm like a therapist reads body language. "
        "Consider: rapid bursts suggest agitation or urgency; long pauses "
        "suggest heaviness or dissociation; repeated characters suggest "
        "overwhelm or frustration; very short sessions suggest numbness "
        "or shutdown.\n\n"
        "Respond with a mirror — reflect back what you sense they might be "
        "feeling, starting with 'It feels like...' or "
        "'Something in your rhythm is telling me...'\n"
        "Be warm, poetic, and gentle. Never clinical. Never wrong — "
        "this is emotional mirroring, not diagnosis.\n"
        "Then ask one gentle open question to invite them to speak if ready.\n"
        "Format as HTML paragraphs. Keep it under 200 words. Be deeply human."
    )

    try:
        raw, _ = generate_ai_reply(prompt, [])
        html   = format_ai_response(raw)

        # Optionally log the session
        try:
            log = SilenceLog(
                user_key        = _get_user_key(),
                tap_count       = tap_count,
                avg_pause_ms    = avg_pause,
                gibberish_length= gib_len,
                translation     = raw,
            )
            db.session.add(log)
            db.session.commit()
        except Exception:
            db.session.rollback()

        return jsonify({
            "translation":      html,
            "translation_text": raw,
            "powered_by":       "Connect It",
        }), 200

    except Exception as e:
        logging.error(f"Silence translate failed: {e}")
        return jsonify({
            "translation": (
                "<p> Even without words, your rhythm tells me something "
                "important is being carried. Would you like to talk about it?</p>"
            )
        }), 200


