@app.route("/api/soul/sandbox", methods=["GET", "POST"])
@csrf.exempt
def soul_sandbox():
    user_key = _get_user_key()

    if request.method == "GET":
        try:
            rows = (SandboxEntry.query
                    .filter_by(user_key=user_key)
                    .order_by(SandboxEntry.created_at.desc())
                    .limit(20).all())
            return jsonify({"entries": [r.to_dict() for r in rows]}), 200
        except Exception as e:
            return jsonify({"entries": [], "error": str(e)}), 200

    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403

    user, err = _erp_user_or_401()
    if err: return err
    gate_result = gate_ai_usage(user, "soul_sandbox")
    if gate_result is not None:
        return gate_result

    data     = request.get_json() or {}
    idea     = (data.get("idea")     or "").strip()
    audience = (data.get("audience") or "").strip()
    budget   = (data.get("budget")   or "bootstrap").strip()
    mode     = (data.get("mode")     or "app").strip()
    # Digital Twin (industrial) mode only — see DIGITAL_TWIN_OPERATION_TYPES.
    operation_type  = (data.get("operation_type")  or "Other").strip()[:80]
    current_setup   = (data.get("current_setup")   or "").strip()[:3000]
    proposed_change = (data.get("proposed_change") or "").strip()[:3000]
    constraints     = (data.get("constraints")     or "").strip()[:2000]

    if not idea:
        return jsonify({"error": "idea field is required."}), 400
    if mode == "industrial" and (not current_setup or not proposed_change):
        return jsonify({"error": "Describe both your current setup and the change you want to simulate."}), 400

    budget_map = {
        "bootstrap": "zero budget — use free tools, open source, no-code where possible",
        "seed":      "$1K-$50K — lean but real, can hire one developer",
        "funded":    "$50K-$500K — proper team, real infrastructure",
        "enterprise":"unlimited budget — best possible stack and team",
    }
    mode_map = {
        "app":     "mobile/web application",
        "business":"physical or service business",
        "game":    "video game or interactive experience",
        "social":  "social media platform or community",
        "ai":      "AI-powered product or tool",
        "content": "content brand, media company, or creator business",
    }

    budget_ctx = budget_map.get(budget, budget_map["bootstrap"])

    if mode == "industrial":
        # Digital Twin: models a real physical operation (a production line,
        # a crop rotation, a mining pit, a herd, a logistics route) so an
        # operator can test a change virtually before committing real
        # capital, land, machinery, or people to it.
        prompt = (
            "You are the Multiverse Sandbox's Digital Twin engine — a virtual "
            "testbed that lets a manufacturer, farmer, miner, or operator "
            "simulate a change to a real physical operation before committing "
            "real money, land, machinery, or people to it. Think like a "
            "production engineer, an agronomist, and a risk analyst at once.\n\n"
            f"OPERATION TYPE: {operation_type}\n"
            f"SCENARIO NAME: {idea}\n"
            f"LOCATION / REGION: {audience or 'not specified'}\n"
            f"CAPITAL AVAILABLE FOR THIS CHANGE: {budget_ctx}\n"
            f"CURRENT SETUP:\n{current_setup}\n\n"
            f"PROPOSED CHANGE TO SIMULATE:\n{proposed_change}\n\n"
            f"KNOWN CONSTRAINTS:\n{constraints or 'none stated'}\n\n"
            "Build a full digital-twin simulation of this change. Return a "
            "JSON object with these exact keys (return ONLY valid JSON, no "
            "markdown, no backticks):\n\n"
            "{\n"
            "  \"baseline_summary\": \"a clear model of the CURRENT setup as-is, including its likely throughput/yield/capacity today\",\n"
            "  \"simulated_scenario\": \"a vivid, concrete walk-through of what happens once the proposed change is applied, step by step\",\n"
            "  \"projected_outcomes\": \"quantified before/after deltas -- throughput, yield, cost, time, quality -- with real numbers and percent changes, clearly flagged as model estimates\",\n"
            "  \"risk_factors\": \"the specific things most likely to go wrong, ranked by severity, each with an early-warning sign to watch for\",\n"
            "  \"resource_requirements\": \"exactly what capital, equipment, land, labor, and time this change actually requires\",\n"
            "  \"implementation_roadmap\": \"a phased rollout plan (e.g. pilot on one line or one plot first) that de-risks the change over time\",\n"
            "  \"recommendation\": \"a direct go / go-with-caution / do-not-proceed call, with the single biggest reason why\"\n"
            "}\n\n"
            "Be extremely concrete: use real units (tonnes, hectares, "
            "units/hour, % moisture, kWh, USD or local currency) and ground "
            "every number in the specifics given above rather than generic "
            "industry averages. Always make clear these are model estimates, "
            "not guarantees, and that a real pilot should confirm them."
        )
    else:
        mode_ctx = mode_map.get(mode, mode_map["app"])
        prompt = (
            "You are the Multiverse Sandbox — an AI architect that builds complete "
            "functional prototypes from a single idea whisper. Think like a CTO, "
            "designer, product manager, and launch strategist simultaneously.\n\n"
            f"THE IDEA: {idea}\n"
            f"TYPE: {mode_ctx}\n"
            f"TARGET AUDIENCE: {audience or 'to be determined'}\n"
            f"BUDGET LEVEL: {budget_ctx}\n\n"
            "Generate the COMPLETE architecture. Return a JSON object with these "
            "exact keys (return ONLY valid JSON, no markdown, no backticks):\n\n"
            "{\n"
            "  \"overview\": \"vivid 3-paragraph description of the full vision\",\n"
            "  \"architecture\": \"full ASCII system architecture diagram\",\n"
            "  \"database\": \"complete database schema with tables, columns, types\",\n"
            "  \"code_snippets\": \"3-5 production-ready code snippets with language labels\",\n"
            "  \"ui_wireframe\": \"detailed text wireframe of the main 3 screens\",\n"
            "  \"launch_strategy\": \"week-by-week 12-week launch plan\",\n"
            "  \"revenue_model\": \"detailed revenue model with pricing and MRR projections\",\n"
            "  \"tech_stack\": \"complete tech stack with reasoning for every choice\"\n"
            "}\n\n"
            "Be EXTREMELY specific. Use real technology names. Write code that works. "
            "Make architecture diagrams detailed. Give real pricing numbers. "
            "This should feel like a $50,000 technical scoping document."
        )

    try:
        raw, _ = generate_ai_reply(prompt, [])

        # Parse JSON safely — strip any markdown the model adds
        clean = raw.strip()
        clean = re.sub(r'^```json\s*',  '', clean)
        clean = re.sub(r'^```\s*',      '', clean)
        clean = re.sub(r'\s*```$',      '', clean)

        try:
            result = json.loads(clean)
        except Exception:
            # Graceful fallback if model returns plain text
            if mode == "industrial":
                result = {
                    "baseline_summary":      raw,
                    "simulated_scenario":    "",
                    "projected_outcomes":    "",
                    "risk_factors":          "",
                    "resource_requirements": "",
                    "implementation_roadmap":"",
                    "recommendation":        "",
                }
            else:
                result = {
                    "overview":        raw,
                    "architecture":    "",
                    "database":        "",
                    "code_snippets":   "",
                    "ui_wireframe":    "",
                    "launch_strategy": "",
                    "revenue_model":   "",
                    "tech_stack":      "",
                }

        # Persist the entry
        try:
            entry = SandboxEntry(
                user_key = user_key,
                idea     = idea,
                audience = audience,
                budget   = budget,
                mode     = mode,
                result   = json.dumps(result)[:10000],  # cap at 10K chars
            )
            db.session.add(entry)
            db.session.commit()
        except Exception:
            db.session.rollback()

        return jsonify({**result, "powered_by": "Connect It"}), 200

    except Exception as e:
        logging.error(f"Multiverse sandbox failed: {e}")
        return jsonify({"error": str(e)}), 500

