# ── 4. CONNECT IT DEBATER (persistent, multi-user debate rooms) ──
# A debate room is a shared, server-stored conversation between Connect It
# Debater (AI) and any number of logged-in users who choose to join.
# Every message is written to the database as it happens, so the full
# back-and-forth survives a page reload and is visible to anyone who
# opens or joins the room afterward — including someone who joins after
# the debate has been running for a while. This intentionally does NOT
# use localStorage anywhere: localStorage is per-browser/per-device, so
# it can never be the source of truth for something other people need
# to read.
class DebateRoom(db.Model):
    __tablename__  = "debate_rooms"
    id             = db.Column(db.Integer, primary_key=True)
    topic          = db.Column(db.String(300), nullable=False)
    position       = db.Column(db.String(500), nullable=True)   # the room-creator's stated position
    intensity      = db.Column(db.String(20), nullable=False, default="fierce")
    context        = db.Column(db.Text, nullable=False)          # the system prompt driving the AI side
    status         = db.Column(db.String(16), nullable=False, default="open", index=True)  # open, closed
    created_by     = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=True)
    created_at     = db.Column(db.DateTime, default=datetime.utcnow, index=True)
    last_activity_at = db.Column(db.DateTime, default=datetime.utcnow, index=True)

    def to_dict(self, include_counts=True):
        d = {
            "id": self.id, "topic": self.topic, "position": self.position,
            "intensity": self.intensity, "status": self.status,
            "created_at": self.created_at.isoformat() if self.created_at else None,
            "last_activity_at": self.last_activity_at.isoformat() if self.last_activity_at else None,
        }
        if include_counts:
            d["message_count"] = DebateMessage.query.filter_by(room_id=self.id).count()
            d["participant_count"] = DebateParticipant.query.filter_by(room_id=self.id, active=True).count()
        return d


class DebateMessage(db.Model):
    __tablename__  = "debate_messages"
    id             = db.Column(db.Integer, primary_key=True)
    room_id        = db.Column(db.Integer, db.ForeignKey("debate_rooms.id"), nullable=False, index=True)
    role           = db.Column(db.String(10), nullable=False)   # 'ai' or 'user'
    user_id        = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=True)
    author_name    = db.Column(db.String(120), nullable=False)  # 'Connect It Debater' for AI turns
    text           = db.Column(db.Text, nullable=False)
    created_at     = db.Column(db.DateTime, default=datetime.utcnow, index=True)

    def to_dict(self):
        return {
            "id": self.id, "room_id": self.room_id, "role": self.role,
            "user_id": self.user_id, "author_name": self.author_name, "text": self.text,
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }


class DebateParticipant(db.Model):
    """Tracks who has joined a debate room, so the room can show a real
    participant count and so 'Exit Debate' has something to flip off.
    A user re-joining an already-joined room is a no-op, not a duplicate
    row — the unique constraint enforces that."""
    __tablename__  = "debate_participants"
    id             = db.Column(db.Integer, primary_key=True)
    room_id        = db.Column(db.Integer, db.ForeignKey("debate_rooms.id"), nullable=False, index=True)
    user_id        = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    name           = db.Column(db.String(120), nullable=False)
    joined_at      = db.Column(db.DateTime, default=datetime.utcnow)
    active         = db.Column(db.Boolean, nullable=False, default=True)

    __table_args__ = (db.UniqueConstraint("room_id", "user_id", name="uq_debate_room_user"),)

    def to_dict(self):
        return {"user_id": self.user_id, "name": self.name,
                "joined_at": self.joined_at.isoformat() if self.joined_at else None, "active": self.active}


def _debate_ai_reply(context: str, history_text: str) -> str:
    prompt = (
        f"{context}\n\nDEBATE SO FAR:\n{history_text}\n\n"
        "Multiple different people may be arguing against you in this room — treat every "
        "HUMAN line as coming from the group collectively. Now give your sharp counter-argument "
        "in under 150 words."
    )
    result, _ = generate_ai_reply(prompt, [])
    return result


@app.route("/api/debate/rooms", methods=["GET"])
def debate_rooms_list():
    """Lists open debate rooms so anyone — including someone who has never
    posted before — can see what's currently being argued and join in."""
    rows = (DebateRoom.query.filter_by(status="open")
            .order_by(DebateRoom.last_activity_at.desc()).limit(50).all())
    return jsonify({"rooms": [r.to_dict() for r in rows]}), 200


@app.route("/api/debate/rooms", methods=["POST"])
@csrf.exempt
def debate_rooms_create():
    """Starts a new persistent, joinable debate room and posts Connect It
    Debater's opening counter-argument as the first message."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    data      = request.get_json(silent=True) or {}
    topic     = (data.get("topic") or "").strip()
    position  = (data.get("position") or "").strip()
    intensity = (data.get("intensity") or "fierce").strip()
    if not topic:
        return jsonify({"error": "topic is required."}), 400
    context = (
        f"You are Connect It Debater, an elite debate partner. The opening human position is: "
        f"\"{position}\" on the topic: \"{topic}\". You argue the EXACT OPPOSITE position. "
        f"Style: {intensity}. Be sharp, logical, cite evidence and examples. "
        "Never agree with the humans. Push their thinking hard. "
        "Keep responses under 150 words unless making a key point."
    )
    try:
        room = DebateRoom(topic=topic[:300], position=position[:500] or None, intensity=intensity[:20],
                           context=context, created_by=user["id"] if user else None)
        db.session.add(room)
        db.session.flush()

        opening_raw = _debate_ai_reply(context, "(No arguments yet — give your opening counter-argument.)")
        opening_msg = DebateMessage(room_id=room.id, role="ai", user_id=None,
                                     author_name="Connect It Debater", text=format_ai_response(opening_raw))
        db.session.add(opening_msg)

        if user:
            db.session.add(DebateParticipant(room_id=room.id, user_id=user["id"], name=user["name"]))

        room.last_activity_at = datetime.utcnow()
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        logging.error(f"[DEBATE ROOM CREATE] {e}")
        return jsonify({"error": "Could not start the debate."}), 500
    return jsonify({"room": room.to_dict(), "messages": [opening_msg.to_dict()]}), 201


@app.route("/api/debate/rooms/<int:room_id>", methods=["GET"])
def debate_room_get(room_id):
    """Full room state — used both when opening a room and by the
    background poll that keeps everyone's view in sync. Anyone can read
    a room's messages without joining, so a brand-new user landing on
    the page can see the full history Connect It and other users already
    argued through before deciding whether to jump in."""
    room = DebateRoom.query.get(room_id)
    if not room:
        return jsonify({"error": "Debate room not found."}), 404
    messages = (DebateMessage.query.filter_by(room_id=room_id)
                .order_by(DebateMessage.created_at.asc(), DebateMessage.id.asc()).all())
    participants = DebateParticipant.query.filter_by(room_id=room_id, active=True).all()
    user = _get_current_user()
    joined = bool(user) and DebateParticipant.query.filter_by(
        room_id=room_id, user_id=user["id"], active=True).first() is not None
    return jsonify({
        "room": room.to_dict(), "messages": [m.to_dict() for m in messages],
        "participants": [p.to_dict() for p in participants], "joined": joined,
    }), 200


@app.route("/api/debate/rooms/<int:room_id>/join", methods=["POST"])
@csrf.exempt
def debate_room_join(room_id):
    """Lets any logged-in user join a running debate. Joining never wipes
    or resets the room's messages — the whole point is that everyone
    joining sees and can build on what's already been argued."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required to join a debate."}), 401
    room = DebateRoom.query.get(room_id)
    if not room:
        return jsonify({"error": "Debate room not found."}), 404
    if room.status != "open":
        return jsonify({"error": "This debate has been closed."}), 400
    try:
        p = DebateParticipant.query.filter_by(room_id=room_id, user_id=user["id"]).first()
        if p:
            p.active = True
        else:
            p = DebateParticipant(room_id=room_id, user_id=user["id"], name=user["name"])
            db.session.add(p)
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        logging.error(f"[DEBATE ROOM JOIN] {e}")
        return jsonify({"error": "Could not join the debate."}), 500
    return jsonify({"ok": True, "joined": True}), 200


@app.route("/api/debate/rooms/<int:room_id>/exit", methods=["POST"])
@csrf.exempt
def debate_room_exit(room_id):
    """Leaving a debate only removes you from the participant list — the
    messages you and everyone else posted stay in the room permanently,
    visible to whoever reads it next."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    p = DebateParticipant.query.filter_by(room_id=room_id, user_id=user["id"]).first()
    if p:
        p.active = False
        db.session.commit()
    return jsonify({"ok": True, "joined": False}), 200


@app.route("/api/debate/rooms/<int:room_id>/message", methods=["POST"])
@csrf.exempt
def debate_room_message(room_id):
    """Posts one human argument into the room (from whichever joined
    user sent it) and immediately posts Connect It Debater's counter-
    argument right after it — both permanently saved, both visible to
    every other participant and any future joiner."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required to argue in this debate."}), 401
    room = DebateRoom.query.get(room_id)
    if not room:
        return jsonify({"error": "Debate room not found."}), 404
    if room.status != "open":
        return jsonify({"error": "This debate has been closed."}), 400
    data = request.get_json(silent=True) or {}
    text = (data.get("message") or "").strip()
    if not text:
        return jsonify({"error": "message is required."}), 400

    try:
        # Joining is implicit the moment someone argues — no reason to
        # force a separate join click before their first message lands.
        p = DebateParticipant.query.filter_by(room_id=room_id, user_id=user["id"]).first()
        if p:
            p.active = True
        else:
            db.session.add(DebateParticipant(room_id=room_id, user_id=user["id"], name=user["name"]))

        user_msg = DebateMessage(room_id=room_id, role="user", user_id=user["id"],
                                  author_name=user["name"], text=text[:4000])
        db.session.add(user_msg)
        db.session.flush()

        history_rows = (DebateMessage.query.filter_by(room_id=room_id)
                         .order_by(DebateMessage.created_at.asc(), DebateMessage.id.asc()).all())
        history_text = "\n".join(
            (f"HUMAN ({m.author_name}): " if m.role == "user" else "CONNECT IT DEBATER: ")
            + re.sub(r"<[^>]+>", "", m.text)
            for m in history_rows
        )
        ai_raw = _debate_ai_reply(room.context, history_text)
        ai_msg = DebateMessage(room_id=room_id, role="ai", user_id=None,
                                author_name="Connect It Debater", text=format_ai_response(ai_raw))
        db.session.add(ai_msg)

        room.last_activity_at = datetime.utcnow()
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        logging.error(f"[DEBATE ROOM MESSAGE] {e}")
        return jsonify({"error": "Could not post your argument."}), 500
    return jsonify({"user_message": user_msg.to_dict(), "ai_message": ai_msg.to_dict()}), 201


