# ── 14. SMS BROADCAST ───────────────────────────────────────
@app.route("/api/sms/broadcast", methods=["POST"])
@csrf.exempt
def sms_broadcast():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    data       = request.get_json() or {}
    recipients = data.get("recipients", [])
    message    = data.get("message",    "").strip()
    if not message:
        return jsonify({"error": "message is required."}), 400
    if not recipients:
        return jsonify({"error": "recipients list is required."}), 400

    sent = 0
    failed = 0

    current_user = _get_current_user()
    current_uid  = current_user.get("id") if current_user else None
    active_client, active_wa_number, _ = get_twilio_client_for_user(current_uid)

    if active_client and active_wa_number:
        for number in recipients:
            try:
                active_client.messages.create(
                    body = message,
                    from_ = active_wa_number,
                    to    = number
                )
                sent += 1
            except Exception as e:
                logging.error(f"SMS to {number} failed: {e}")
                failed += 1
    else:
        # Log only — no provider configured
        logging.warning(
            f"SMS broadcast: no provider configured. "
            f"Would send to {len(recipients)} recipients."
        )
        sent   = len(recipients)
        failed = 0

    return jsonify({
        "sent":        sent,
        "failed":      failed,
        "total":       len(recipients),
        "powered_by":  "Connect It",
    }), 200


# ── 15. EMAIL CAMPAIGN ──────────────────────────────────────
@app.route("/api/email/campaign", methods=["POST"])
@csrf.exempt
def email_campaign():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    data        = request.get_json() or {}
    subject     = data.get("subject",     "").strip()
    sender_name = data.get("sender_name", "Connect It").strip()
    reply_to    = data.get("reply_to",    SMTP_FROM).strip()
    body        = data.get("body",        "").strip()
    subscribers = data.get("subscribers", [])
    if not subject or not body:
        return jsonify({"error": "subject and body are required."}), 400
    if not subscribers:
        return jsonify({"error": "No subscribers provided."}), 400

    sent = 0
    failed = 0

    if SMTP_USER and SMTP_PASS:
        html_body = f"""
        <!DOCTYPE html>
        <html>
        <body style="font-family:Arial,sans-serif;max-width:600px;margin:0 auto;
                     background:#f9fafb;padding:20px;">
          <div style="background:white;border-radius:12px;overflow:hidden;
                      box-shadow:0 4px 16px rgba(0,0,0,0.08);">
            <div style="background:linear-gradient(90deg,#1e3a8a,#2563eb);
                        padding:20px;text-align:center;">
              <h1 style="color:white;margin:0;font-size:1.4rem;"> Connect It</h1>
            </div>
            <div style="padding:24px;color:#1e293b;line-height:1.8;font-size:0.9rem;">
              {body.replace(chr(10), '<br/>')}
            </div>
            <div style="background:#f8fafc;padding:16px;text-align:center;
                        font-size:0.72rem;color:#9ca3af;">
              © 2025 Connect It · Built with  by the Nzombe Family<br/>
              <a href="#" style="color:#9ca3af;">Unsubscribe</a>
            </div>
          </div>
        </body>
        </html>
        """
        for sub in subscribers[:500]:  # cap at 500 per campaign
            email = sub.get("email", "") if isinstance(sub, dict) else str(sub)
            name  = sub.get("name",  "") if isinstance(sub, dict) else ""
            if not email or "@" not in email:
                failed += 1
                continue
            try:
                msg = MIMEMultipart("alternative")
                msg["Subject"] = subject
                msg["From"]    = f"{sender_name} <{SMTP_USER}>"
                msg["To"]      = email
                msg["Reply-To"] = reply_to
                msg.attach(MIMEText(html_body, "html"))
                with smtplib.SMTP(SMTP_HOST, SMTP_PORT, timeout=15) as server:
                    server.ehlo()
                    server.starttls()
                    server.login(SMTP_USER, SMTP_PASS)
                    server.sendmail(SMTP_USER, email, msg.as_string())
                sent += 1
            except Exception as e:
                logging.error(f"Email to {email} failed: {e}")
                failed += 1
    else:
        logging.warning(
            "Email campaign: SMTP not configured. "
            f"Would send to {len(subscribers)} subscribers."
        )
        sent   = len(subscribers)
        failed = 0

    return jsonify({
        "sent":       sent,
        "failed":     failed,
        "total":      len(subscribers),
        "powered_by": "Connect It",
    }), 200


# ── 16. PAYMENTS — CREATE CHECKOUT SESSION (individual user plans) ──
# One Stripe Price ID per paid individual plan, created once in the
# Stripe Dashboard (Products > add recurring price) and pasted into
# these env vars. Mirrors the org-level STRIPE_PRICE_IDS pattern used
# by /api/billing/checkout (STAGE 204) but for a single user's own
# UserAccount.plan rather than an Organization.plan.
USER_STRIPE_PRICE_IDS = {
    "monthly": os.environ.get("STRIPE_PRICE_USER_PRO_MONTHLY", ""),
    "yearly":  os.environ.get("STRIPE_PRICE_USER_PRO_YEARLY", ""),
    "team":    os.environ.get("STRIPE_PRICE_USER_TEAM_MONTHLY", ""),
}
USER_STRIPE_PLAN_NAME = {"monthly": "pro", "yearly": "pro", "team": "team"}


@app.route("/api/payments/create-checkout", methods=["POST"])
@csrf.exempt
def payments_create_checkout():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    data    = request.get_json() or {}
    plan    = data.get("plan", "monthly")
    user_id = data.get("user_id")

    if plan not in USER_STRIPE_PRICE_IDS:
        return jsonify({"error": f"Unknown plan '{plan}'. Valid plans: {', '.join(USER_STRIPE_PRICE_IDS)}"}), 400

    if not STRIPE_AVAILABLE or not STRIPE_SECRET_KEY:
        return jsonify({
            "error": (
                "Payment system not yet configured. "
                "Contact smile.again.tec@gmail.com to upgrade."
            )
        }), 503

    price_id = USER_STRIPE_PRICE_IDS[plan]
    if not price_id:
        env_name = {"monthly": "STRIPE_PRICE_USER_PRO_MONTHLY",
                     "yearly": "STRIPE_PRICE_USER_PRO_YEARLY",
                     "team":   "STRIPE_PRICE_USER_TEAM_MONTHLY"}[plan]
        return jsonify({
            "error": f"The '{plan}' plan isn't priced yet on the server — set {env_name}."
        }), 503

    if not user_id:
        return jsonify({"error": "Login required to upgrade."}), 401
    user = UserAccount.query.get(user_id)
    if not user:
        return jsonify({"error": "Account not found."}), 404

    try:
        customer_id = user.stripe_customer_id
        if not customer_id:
            customer = stripe.Customer.create(email=user.email, name=user.name)
            customer_id = customer.id
            user.stripe_customer_id = customer_id
            db.session.commit()

        session = stripe.checkout.Session.create(
            customer   = customer_id,
            line_items = [{"price": price_id, "quantity": 1}],
            mode       = "subscription",
            success_url = APP_BASE_URL + "/?payment=success&session_id={CHECKOUT_SESSION_ID}",
            cancel_url  = APP_BASE_URL + "/?payment=cancelled",
            subscription_data={
                "trial_period_days": 7,
                "metadata": {"kind": "user_subscription", "user_id": str(user.id), "plan": plan},
            },
            metadata    = {"kind": "user_subscription", "user_id": str(user.id), "plan": plan},
        )
        return jsonify({"checkout_url": session.url}), 200
    except stripe.error.StripeError as e:
        logging.error(f"Stripe checkout failed: {e}")
        return jsonify({"error": str(getattr(e, "user_message", None) or e)}), 400
    except Exception as e:
        logging.error(f"Stripe checkout failed: {e}")
        return jsonify({"error": str(e)}), 500


