# ── STAGE 133: AI CONTRACT RISK ANALYZER ────────────────────
# Accepts either a pasted contract text (JSON) or an uploaded document
# (multipart — pdf/docx/txt, reusing the same fi_extract() used for chat
# attachments), asks the AI to flag real risk patterns, and saves the
# result as a real ContractRiskAnalysis row so the user has a history.
@app.route("/api/legal/contract-risk-scan", methods=["POST"])
@csrf.exempt
def contract_risk_scan():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401

    contract_name = None
    text = ""
    # multipart file upload
    for key in ("file", "files", "contract_file"):
        if key in request.files:
            f = request.files.getlist(key)[0]
            raw = f.read()
            if raw:
                if len(raw) > MAX_ATTACHMENT_BYTES:
                    return jsonify({"error": "File too large (15MB limit)."}), 400
                contract_name = f.filename
                text = fi_extract(f.filename, raw)
            break
    if not text:
        data = request.get_json(silent=True) or {}
        text = (data.get("contract_text") or "").strip()
        contract_name = data.get("contract_name") or contract_name

    if not text or len(text.strip()) < 30:
        return jsonify({"error": "Paste the contract text or upload a document (pdf/docx/txt) to analyze."}), 400

    gate_result = gate_ai_usage(user, "contract_risk_scan")
    if gate_result is not None:
        return gate_result

    prompt = (
        "You are a contract risk reviewer helping a small business owner understand a contract "
        "someone else has handed them (a lease, supplier agreement, employment offer, etc.) BEFORE they sign it. "
        "You are not their lawyer and this is not legal advice — say so briefly at the top. "
        "Then review the contract text below and produce:\n"
        "1. OVERALL RISK LEVEL: Low / Medium / High (bold, prominent)\n"
        "2. RED FLAGS FOUND — for each one found, quote or paraphrase the clause, name the risk pattern "
        "(e.g. auto-renewal trap, unlimited liability, one-sided termination rights, unusually short notice periods, "
        "vague payment terms, non-compete overreach, unilateral amendment rights), and explain in plain language "
        "why it matters for the person signing.\n"
        "3. CLAUSES THAT ARE FAIR / STANDARD — brief reassurance on what looks normal.\n"
        "4. QUESTIONS TO ASK OR NEGOTIATE before signing.\n"
        "5. BOTTOM LINE: one paragraph, plain language, on whether to sign as-is, negotiate, or get a lawyer to look at it.\n\n"
        f"CONTRACT TEXT:\n{text[:MAX_CHARS_PER_FILE]}"
    )
    result, _ = generate_ai_reply(prompt, [])
    report = format_ai_response(result)

    try:
        rec = ContractRiskAnalysis(
            user_id=user["id"], contract_name=(contract_name or "Untitled contract")[:200],
            source_text=text[:MAX_CHARS_PER_FILE], risk_report=result,
        )
        db.session.add(rec); db.session.commit()
    except Exception as e:
        db.session.rollback(); logging.error(f"[CONTRACT RISK SCAN SAVE] {e}")
        # still return the analysis even if saving history failed
        return jsonify({"risk_report": report, "risk_report_text": result, "saved": False, "powered_by": "Connect It"}), 200

    return jsonify({
        "risk_report": report, "risk_report_text": result, "saved": True,
        "analysis": rec.to_dict(), "powered_by": "Connect It",
    }), 200


