# ════════════════════════════════════════════════════════════
# NEW STAGE: AI CONTRACT REDLINING ASSISTANT
# The Stage 133 Risk Analyzer above only flags issues in prose. This is
# a different feature: it asks the AI for actual clause-level edit
# suggestions (original wording → a rewritten "redline" → why), the
# format a real redlining pass produces, and stores each proposed edit
# individually so the user can accept/reject and export a marked-up
# draft — not just read a risk report.
# ════════════════════════════════════════════════════════════
class ContractRedline(db.Model):
    __tablename__ = "contract_redlines"
    id             = db.Column(db.Integer,     primary_key=True)
    user_id        = db.Column(db.Integer,     db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    contract_name  = db.Column(db.String(200), nullable=True)
    source_text    = db.Column(db.Text,        nullable=False)
    clauses_json   = db.Column(db.Text,        nullable=False)  # JSON list of clause-level suggestions
    created_at     = db.Column(db.DateTime,    default=datetime.utcnow, index=True)

    def to_dict(self, include_text=False):
        try:
            clauses = json.loads(self.clauses_json)
        except Exception:
            clauses = []
        d = {
            "id": self.id, "contract_name": self.contract_name,
            "clauses": clauses, "clause_count": len(clauses),
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }
        if include_text:
            d["source_text"] = self.source_text
        return d


def _redline_parse_ai_json(raw_text):
    """The AI is asked for a bare JSON array. Be forgiving of a stray
    code fence or leading/trailing prose the model adds anyway — pull
    out the first [...] block rather than failing the whole request."""
    text = (raw_text or "").strip()
    text = re.sub(r"^```(?:json)?", "", text.strip())
    text = re.sub(r"```$", "", text.strip())
    try:
        data = json.loads(text)
        if isinstance(data, list):
            return data
    except Exception:
        pass
    m = re.search(r"\[.*\]", text, re.DOTALL)
    if m:
        try:
            data = json.loads(m.group(0))
            if isinstance(data, list):
                return data
        except Exception:
            pass
    return None


@app.route("/api/legal/contract-redline", methods=["POST"])
@csrf.exempt
def contract_redline_create():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401

    contract_name = None
    text = ""
    for key in ("file", "files", "contract_file"):
        if key in request.files:
            f = request.files.getlist(key)[0]
            raw = f.read()
            if raw:
                if len(raw) > MAX_ATTACHMENT_BYTES:
                    return jsonify({"error": "File too large (15MB limit)."}), 400
                contract_name = f.filename
                text = fi_extract(f.filename, raw)
            break
    if not text:
        data = request.get_json(silent=True) or {}
        # Reuse a previous risk-scan's source text instead of re-pasting.
        prior_id = data.get("from_risk_analysis_id")
        if prior_id:
            prior = ContractRiskAnalysis.query.get(int(prior_id))
            if prior and prior.user_id == user["id"]:
                text = prior.source_text
                contract_name = prior.contract_name
        if not text:
            text = (data.get("contract_text") or "").strip()
        contract_name = data.get("contract_name") or contract_name

    if not text or len(text.strip()) < 30:
        return jsonify({"error": "Paste the contract text, upload a document, or reference a prior risk scan."}), 400

    gate_result = gate_ai_usage(user, "contract_redline_create")
    if gate_result is not None:
        return gate_result

    prompt = (
        "You are an experienced contract redliner for a small business owner reviewing a contract someone "
        "else handed them. Produce ACTUAL clause-level redline suggestions — the exact editing pass a lawyer "
        "would mark up — not general commentary. This is not legal advice.\n\n"
        "Respond with ONLY a JSON array, no prose before or after, no markdown code fence. Each element:\n"
        '{"original_clause": "<verbatim excerpt from the contract, under 50 words>", '
        '"issue": "<short label, e.g. Unlimited liability>", '
        '"suggested_redline": "<the rewritten clause language you propose in its place>", '
        '"rationale": "<1-2 plain-language sentences on why this edit protects the signer>", '
        '"severity": "<low|medium|high>"}\n'
        "Include every clause worth negotiating (aim for 3-12 items depending on contract length). "
        "The \"original_clause\" text must be copied verbatim from the contract below so it can be matched "
        "and replaced automatically.\n\n"
        f"CONTRACT TEXT:\n{text[:MAX_CHARS_PER_FILE]}"
    )
    result, _ = generate_ai_reply(prompt, [])
    clauses = _redline_parse_ai_json(result)
    if clauses is None:
        return jsonify({"error": "Could not generate structured redlines from this contract. Try again or use the Risk Scanner instead."}), 502

    # Normalize/sanitize each suggestion — never trust the model's shape blindly.
    clean = []
    for i, c in enumerate(clauses):
        if not isinstance(c, dict):
            continue
        orig = str(c.get("original_clause") or "").strip()
        redline = str(c.get("suggested_redline") or "").strip()
        if not orig or not redline:
            continue
        clean.append({
            "clause_id": i + 1,
            "original_clause": orig[:1000],
            "issue": str(c.get("issue") or "Suggested edit")[:200],
            "suggested_redline": redline[:1000],
            "rationale": str(c.get("rationale") or "")[:500],
            "severity": (str(c.get("severity") or "medium").lower() if str(c.get("severity") or "").lower() in ("low", "medium", "high") else "medium"),
            "found_in_text": orig in text,
        })

    try:
        rec = ContractRedline(
            user_id=user["id"], contract_name=(contract_name or "Untitled contract")[:200],
            source_text=text[:MAX_CHARS_PER_FILE], clauses_json=json.dumps(clean),
        )
        db.session.add(rec); db.session.commit()
    except Exception as e:
        db.session.rollback(); logging.error(f"[CONTRACT REDLINE SAVE] {e}")
        return jsonify({"clauses": clean, "saved": False, "powered_by": "Connect It"}), 200

    return jsonify({"ok": True, "saved": True, "redline": rec.to_dict(), "powered_by": "Connect It"}), 200


