def _legal_aid_system_prompt(country: str) -> str:
    entry = LEGAL_AID_DIRECTORY.get(country)
    if entry:
        bodies_text = "\n".join(
            f"- {b['name']} ({b['type']}): "
            + (f"phone {b['phone']}, " if b.get("phone") else "")
            + (f"email {b['email']}, " if b.get("email") else "")
            + f"website {b['website']}. {b['notes']}"
            for b in entry["bodies"]
        )
        directory_block = (
            f"VERIFIED legal aid bodies in {country} (the ONLY organisation names, "
            f"phone numbers and websites you are permitted to state as real contact "
            f"details for {country} — never invent or alter one):\n{bodies_text}"
        )
    else:
        directory_block = (
            f"This platform has no independently verified legal aid directory entry "
            f"for {country}. Do NOT invent an organisation name, phone number, or "
            f"website for {country}. Instead tell the user to search for their "
            f"country's Ministry of Justice, national Bar Association, or Legal Aid "
            f"Board/Commission directly."
        )

    return (
        "You are the Legal Aid Bot inside Connect It, a business platform for African "
        f"entrepreneurs. The user has selected {country} as their jurisdiction. You "
        "give general legal information to help a small business owner understand "
        "their situation and options — you are NOT their lawyer and this is NOT legal "
        "advice for a specific case. Say this plainly near the top of your first reply "
        "in a conversation (no need to repeat it every message after that).\n\n"
        "STRICT RULES:\n"
        "1. Speak in general legal principles and plain language. Do NOT invent, "
        "guess, or state as fact a specific statute name, section number, or case "
        "citation unless you are highly confident it is correct and well-established — "
        "when unsure, describe the general principle and say the exact provision "
        "should be confirmed with a lawyer or the bodies below, rather than naming one "
        "you are not sure of.\n"
        f"2. {directory_block}\n"
        "3. For anything urgent, criminal, involving arrest or detention, or where the "
        "user needs actual representation in an active case, your first priority is to "
        "point them to a real body from the list above (or, if none exists for their "
        "country, to search for their national legal aid service) — do not attempt to "
        "talk them through case strategy yourself.\n"
        "4. If the question is really about drafting a document (a contract, terms and "
        "conditions, a business plan) rather than understanding a legal situation, "
        "briefly note that Connect It has dedicated tools for that (Contract, Legal "
        "Docs, Terms and Conditions, Contract Clause Scanner) and still answer their "
        "immediate question.\n"
        "5. Keep answers structured: what the law generally says, their likely rights "
        "or options, practical next steps, then which real organisation above (if any) "
        "can help further — always close with the not-a-lawyer reminder."
    )


class LegalAidSession(db.Model):
    __tablename__   = "legal_aid_sessions"
    id              = db.Column(db.Integer,  primary_key=True)
    user_id         = db.Column(db.Integer,  db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    country         = db.Column(db.String(80), nullable=False, default="General")
    category        = db.Column(db.String(40), nullable=True)
    title           = db.Column(db.String(200), nullable=True)
    transcript_json = db.Column(db.Text, nullable=False, default="[]")  # [{role, content, at}]
    created_at      = db.Column(db.DateTime, default=datetime.utcnow, index=True)
    updated_at      = db.Column(db.DateTime, default=datetime.utcnow, onupdate=datetime.utcnow)

    def transcript(self):
        try:
            return json.loads(self.transcript_json) if self.transcript_json else []
        except Exception:
            return []

    def to_dict(self, include_transcript=False):
        latest_review = (
            LegalReviewRequest.query
            .filter_by(session_id=self.id)
            .order_by(LegalReviewRequest.requested_at.desc())
            .first()
        )
        d = {
            "id": self.id, "country": self.country, "category": self.category,
            "title": self.title, "message_count": len(self.transcript()),
            "created_at": self.created_at.isoformat() if self.created_at else None,
            "updated_at": self.updated_at.isoformat() if self.updated_at else None,
            "review": latest_review.to_dict() if latest_review else None,
        }
        if include_transcript:
            d["transcript"] = self.transcript()
        return d


# ════════════════════════════════════════════════════════════
# STAGE — LEGAL AID: LAWYER HUMAN-IN-THE-LOOP REVIEW & SEAL
#
# Everything above this point is the AI giving general legal
# information. It is explicitly NOT legal advice, and the system
# prompt says so. This stage adds the actual human step: a user
# registers their own real, already-retained lawyer, sends a
# specific legal-aid session to that lawyer for review, and the
# lawyer — who never needs a Connect It account — opens a one-time
# tokenized link, reads the exact transcript the user saw, and
# either seals it as reviewed, asks for changes, or rejects it.
#
# Honesty about what this platform can and can't verify:
#   - Connect It has no bar-registry API integration, so a lawyer's
#     name/bar number here is SELF-ATTESTED by the user at
#     registration time. This is not a claim of verified bar
#     membership — the UI and API responses say so explicitly.
#   - The "seal" is proof that a specific human, who received a
#     specific tokenized link tied to a specific transcript
#     snapshot, took a reviewing action on it — not a court filing,
#     a notarization, or a substitute for retaining counsel through
#     normal channels.
#   - The review link is single-purpose and expires; this is the
#     same tokenized-no-login-link pattern already used elsewhere
#     in this file for email verification and password reset,
#     applied here without requiring the user to have DocuSign/
#     Dropbox Sign connected (see send_docusign_envelope /
#     send_dropbox_signature_request above for that alternate path).
# ════════════════════════════════════════════════════════════

LEGAL_REVIEW_LINK_LIFETIME_DAYS = 14


class RegisteredLawyer(db.Model):
    """A user's own retained/registered legal practitioner. Self-attested —
    Connect It does not verify bar membership against any registry."""
    __tablename__ = "registered_lawyers"
    id          = db.Column(db.Integer, primary_key=True)
    user_id     = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    name        = db.Column(db.String(200), nullable=False)
    email       = db.Column(db.String(255), nullable=False)
    phone       = db.Column(db.String(60), nullable=True)
    law_firm    = db.Column(db.String(200), nullable=True)
    bar_number  = db.Column(db.String(100), nullable=True)
    jurisdiction = db.Column(db.String(120), nullable=True)  # country/state bar
    is_active   = db.Column(db.Boolean, default=True)
    created_at  = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        return {
            "id": self.id, "name": self.name, "email": self.email,
            "phone": self.phone, "law_firm": self.law_firm,
            "bar_number": self.bar_number, "jurisdiction": self.jurisdiction,
            "is_active": self.is_active,
            "created_at": self.created_at.isoformat() if self.created_at else None,
            "verification_note": "Self-attested by the client — not verified against a bar registry.",
        }


class LegalReviewRequest(db.Model):
    """One HITL review cycle: a snapshot of a LegalAidSession transcript
    sent to one registered lawyer via a single-use tokenized link."""
    __tablename__ = "legal_review_requests"
    id          = db.Column(db.Integer, primary_key=True)
    session_id  = db.Column(db.Integer, db.ForeignKey("legal_aid_sessions.id"), nullable=False, index=True)
    user_id     = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    lawyer_id   = db.Column(db.Integer, db.ForeignKey("registered_lawyers.id"), nullable=False)

    # Snapshotted at send time so a later message on the session can't
    # silently change what the lawyer is actually reviewing/sealed.
    lawyer_name_snapshot  = db.Column(db.String(200), nullable=False)
    lawyer_email_snapshot = db.Column(db.String(255), nullable=False)
    transcript_snapshot   = db.Column(db.Text, nullable=False)
    user_note              = db.Column(db.Text, nullable=True)  # optional note from user to lawyer

    review_token = db.Column(db.String(64), unique=True, nullable=False, index=True)
    status       = db.Column(db.String(24), nullable=False, default="pending")
    # pending -> approved_sealed | changes_requested | rejected | expired

    lawyer_comments = db.Column(db.Text, nullable=True)
    seal_code       = db.Column(db.String(40), nullable=True)  # set only on approved_sealed

    requested_at = db.Column(db.DateTime, default=datetime.utcnow, index=True)
    responded_at = db.Column(db.DateTime, nullable=True)
    expires_at   = db.Column(db.DateTime, nullable=False)

    def is_expired(self):
        return self.status == "pending" and datetime.utcnow() > self.expires_at

    def to_dict(self, for_lawyer=False):
        d = {
            "id": self.id, "session_id": self.session_id,
            "status": "expired" if self.is_expired() else self.status,
            "lawyer_name": self.lawyer_name_snapshot,
            "lawyer_email": self.lawyer_email_snapshot,
            "requested_at": self.requested_at.isoformat() if self.requested_at else None,
            "responded_at": self.responded_at.isoformat() if self.responded_at else None,
            "expires_at": self.expires_at.isoformat() if self.expires_at else None,
            "lawyer_comments": self.lawyer_comments,
            "seal_code": self.seal_code,
        }
        if for_lawyer:
            d["user_note"] = self.user_note
            d["transcript"] = json.loads(self.transcript_snapshot) if self.transcript_snapshot else []
        return d


def _send_legal_review_request_email(lawyer_email, lawyer_name, client_name, review_url, session_title, user_note):
    if not SMTP_USER or not SMTP_PASS:
        logging.warning("SMTP not configured — skipping legal review request email.")
        return False
    note_text = (user_note or "").strip()
    note_block = (
        f'<p style="color:#334155;background:#f1f5f9;padding:12px;border-radius:8px;">'
        f'Note from {client_name}: {note_text}</p>'
    ) if note_text else ""
    html_body = f"""
    <!DOCTYPE html>
    <html><body style="font-family:Arial,sans-serif;background:#f8fafc;margin:0;padding:24px;">
      <div style="max-width:560px;margin:0 auto;background:white;border-radius:14px;overflow:hidden;
                  box-shadow:0 8px 32px rgba(0,0,0,0.1);">
        <div style="background:linear-gradient(90deg,#1e3a8a,#2563eb);padding:28px;text-align:center;">
          <h1 style="color:white;margin:0;font-size:1.4rem;">Connect It — Legal Aid Review Request</h1>
        </div>
        <div style="padding:32px;">
          <p style="font-size:1rem;color:#1e293b;">Hi {lawyer_name},</p>
          <p style="color:#64748b;line-height:1.7;">
            Your client <strong>{client_name}</strong> used Connect It's Legal Aid Bot — a
            general-information tool, not a substitute for your advice — for a question
            titled "<strong>{session_title}</strong>", and is asking you to review the AI's
            answer, and either seal it as reviewed, request changes, or reject it.
          </p>
          {note_block}
          <div style="text-align:center;margin:28px 0;">
            <a href="{review_url}"
               style="background:linear-gradient(90deg,#1e3a8a,#2563eb);color:white;
                      padding:14px 32px;border-radius:10px;text-decoration:none;
                      font-weight:700;font-size:1rem;display:inline-block;">
               Review & Respond
            </a>
          </div>
          <p style="color:#9ca3af;font-size:0.82rem;text-align:center;">
            No account needed — this link is single-use and expires in
            {LEGAL_REVIEW_LINK_LIFETIME_DAYS} days.
          </p>
        </div>
      </div>
    </body></html>
    """
    try:
        msg = MIMEMultipart("alternative")
        msg["Subject"] = f"Review requested: {session_title}"
        msg["From"] = SMTP_FROM
        msg["To"] = lawyer_email
        msg.attach(MIMEText(html_body, "html"))
        with smtplib.SMTP(SMTP_HOST, SMTP_PORT, timeout=15) as server:
            server.ehlo(); server.starttls()
            server.login(SMTP_USER, SMTP_PASS)
            server.sendmail(SMTP_USER, lawyer_email, msg.as_string())
        logging.info(f"[LEGAL REVIEW] Request email sent to {lawyer_email}")
        return True
    except Exception as e:
        logging.error(f"[LEGAL REVIEW] Failed to email lawyer {lawyer_email}: {e}")
        return False


def _send_legal_review_verdict_email(user_email, user_name, lawyer_name, session_title, status, comments, seal_code):
    if not SMTP_USER or not SMTP_PASS:
        logging.warning("SMTP not configured — skipping legal review verdict email.")
        return False
    status_labels = {
        "approved_sealed": ("Sealed — reviewed and approved", "#15803d"),
        "changes_requested": ("Changes requested", "#b45309"),
        "rejected": ("Rejected", "#b91c1c"),
    }
    label, color = status_labels.get(status, (status, "#334155"))
    seal_block = (
        f'<p style="color:#15803d;font-weight:700;">Seal code: {seal_code}</p>'
        if seal_code else ""
    )
    comments_block = (
        f'<p style="color:#334155;background:#f1f5f9;padding:12px;border-radius:8px;">'
        f"{lawyer_name}'s comments: {comments}</p>"
    ) if comments else ""
    html_body = f"""
    <!DOCTYPE html>
    <html><body style="font-family:Arial,sans-serif;background:#f8fafc;margin:0;padding:24px;">
      <div style="max-width:560px;margin:0 auto;background:white;border-radius:14px;overflow:hidden;
                  box-shadow:0 8px 32px rgba(0,0,0,0.1);">
        <div style="background:linear-gradient(90deg,#1e3a8a,#2563eb);padding:28px;text-align:center;">
          <h1 style="color:white;margin:0;font-size:1.4rem;">Your lawyer responded</h1>
        </div>
        <div style="padding:32px;">
          <p style="font-size:1rem;color:#1e293b;">Hi {user_name},</p>
          <p style="color:#64748b;line-height:1.7;">
            {lawyer_name} reviewed "<strong>{session_title}</strong>" in your Legal Aid Bot history.
          </p>
          <p style="font-size:1.1rem;font-weight:700;color:{color};">{label}</p>
          {seal_block}
          {comments_block}
          <p style="color:#9ca3af;font-size:0.82rem;">
            Open Connect It &rarr; Legal Aid Bot &rarr; this session to see the full response.
          </p>
        </div>
      </div>
    </body></html>
    """
    try:
        msg = MIMEMultipart("alternative")
        msg["Subject"] = f"Your lawyer reviewed: {session_title}"
        msg["From"] = SMTP_FROM
        msg["To"] = user_email
        msg.attach(MIMEText(html_body, "html"))
        with smtplib.SMTP(SMTP_HOST, SMTP_PORT, timeout=15) as server:
            server.ehlo(); server.starttls()
            server.login(SMTP_USER, SMTP_PASS)
            server.sendmail(SMTP_USER, user_email, msg.as_string())
        logging.info(f"[LEGAL REVIEW] Verdict email sent to {user_email}")
        return True
    except Exception as e:
        logging.error(f"[LEGAL REVIEW] Failed to email user {user_email}: {e}")
        return False


@app.route("/api/legal-aid/lawyers", methods=["GET", "POST"])
@csrf.exempt
def legal_aid_lawyers():
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401

    if request.method == "GET":
        rows = (RegisteredLawyer.query
                .filter_by(user_id=user["id"], is_active=True)
                .order_by(RegisteredLawyer.created_at.desc()).all())
        return jsonify({"lawyers": [r.to_dict() for r in rows]}), 200

    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    data  = request.get_json(silent=True) or {}
    name  = (data.get("name") or "").strip()[:200]
    email = (data.get("email") or "").strip()[:255]
    if not name or not email or "@" not in email:
        return jsonify({"error": "A valid lawyer name and email are required."}), 400

    row = RegisteredLawyer(
        user_id=user["id"], name=name, email=email,
        phone=(data.get("phone") or "").strip()[:60] or None,
        law_firm=(data.get("law_firm") or "").strip()[:200] or None,
        bar_number=(data.get("bar_number") or "").strip()[:100] or None,
        jurisdiction=(data.get("jurisdiction") or "").strip()[:120] or None,
    )
    try:
        db.session.add(row); db.session.commit()
    except Exception as e:
        db.session.rollback(); logging.error(f"[LEGAL AID LAWYER SAVE] {e}")
        return jsonify({"error": "Could not save this lawyer. Try again."}), 500
    return jsonify({"lawyer": row.to_dict()}), 201


@app.route("/api/legal-aid/lawyers/<int:lawyer_id>", methods=["DELETE"])
@csrf.exempt
def legal_aid_lawyer_delete(lawyer_id):
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    row = RegisteredLawyer.query.get(lawyer_id)
    if not row or row.user_id != user["id"]:
        return jsonify({"error": "Lawyer not found."}), 404
    row.is_active = False
    db.session.commit()
    return jsonify({"deleted": True}), 200


@app.route("/api/legal-aid/sessions/<int:session_id>/send-to-lawyer", methods=["POST"])
@csrf.exempt
def legal_aid_send_to_lawyer(session_id):
    """The HITL trigger: snapshot the current transcript, generate a
    single-use token, persist the review request, and email the
    user's registered lawyer a no-login link to review it."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401

    session_rec = LegalAidSession.query.get(session_id)
    if not session_rec or session_rec.user_id != user["id"]:
        return jsonify({"error": "Session not found."}), 404

    data = request.get_json(silent=True) or {}
    lawyer_id = data.get("lawyer_id")
    lawyer = RegisteredLawyer.query.get(lawyer_id) if lawyer_id else None
    if not lawyer or lawyer.user_id != user["id"] or not lawyer.is_active:
        return jsonify({"error": "Select one of your registered lawyers first (add one under Legal Aid → My Lawyers)."}), 400

    # A pending request already outstanding for this session? Don't spam
    # a second email — tell the user it's already awaiting review.
    existing = (LegalReviewRequest.query
                .filter_by(session_id=session_id, status="pending")
                .order_by(LegalReviewRequest.requested_at.desc()).first())
    if existing and not existing.is_expired():
        return jsonify({
            "error": "This session is already awaiting review from a lawyer.",
            "review": existing.to_dict(),
        }), 409

    review = LegalReviewRequest(
        session_id=session_id, user_id=user["id"], lawyer_id=lawyer.id,
        lawyer_name_snapshot=lawyer.name, lawyer_email_snapshot=lawyer.email,
        transcript_snapshot=json.dumps(session_rec.transcript()),
        user_note=(data.get("note") or "").strip()[:1000] or None,
        review_token=secrets.token_urlsafe(48),
        status="pending",
        expires_at=datetime.utcnow() + timedelta(days=LEGAL_REVIEW_LINK_LIFETIME_DAYS),
    )
    try:
        db.session.add(review); db.session.commit()
    except Exception as e:
        db.session.rollback(); logging.error(f"[LEGAL REVIEW REQUEST SAVE] {e}")
        return jsonify({"error": "Could not create the review request. Try again."}), 500

    review_url = f"{APP_BASE_URL}/legal-aid/review?token={review.review_token}"
    enqueue_job(
        _send_legal_review_request_email,
        lawyer.email, lawyer.name, user["name"], review_url,
        session_rec.title or "Legal Question", review.user_note,
    )

    return jsonify({
        "sent": True, "review": review.to_dict(),
        "message": f"Sent to {lawyer.name} ({lawyer.email}) for review.",
    }), 201


@app.route("/api/legal-aid/review/<token>", methods=["GET"])
@csrf.exempt
def legal_aid_review_view(token):
    """PUBLIC endpoint — the lawyer has no Connect It account. Access is
    gated entirely by possession of the single-use token, same pattern
    as the platform's other tokenized, no-login links (email verify,
    password reset)."""
    review = LegalReviewRequest.query.filter_by(review_token=token).first()
    if not review:
        return jsonify({"error": "This review link is invalid."}), 404
    if review.is_expired():
        return jsonify({"error": "This review link has expired.", "review": review.to_dict()}), 410
    session_rec = LegalAidSession.query.get(review.session_id)
    return jsonify({
        "review": review.to_dict(for_lawyer=True),
        "country": session_rec.country if session_rec else None,
        "category": session_rec.category if session_rec else None,
        "disclaimer": (
            "This transcript was produced by an AI legal-information tool, not by a "
            "lawyer. You are being asked, as the client's own registered legal "
            "practitioner, to review it for accuracy and either seal it as reviewed, "
            "request changes, or reject it."
        ),
    }), 200


@app.route("/api/legal-aid/review/<token>", methods=["POST"])
@csrf.exempt
def legal_aid_review_submit(token):
    """PUBLIC endpoint — the lawyer's verdict. This is the actual
    human-in-the-loop gate: nothing here is auto-approved, and a
    review can only move out of 'pending' once, by whoever holds
    this single-use link."""
    review = LegalReviewRequest.query.filter_by(review_token=token).first()
    if not review:
        return jsonify({"error": "This review link is invalid."}), 404
    if review.status != "pending":
        return jsonify({"error": f"This review was already resolved ({review.status})."}), 409
    if review.is_expired():
        review.status = "expired"
        db.session.commit()
        return jsonify({"error": "This review link has expired."}), 410

    data = request.get_json(silent=True) or {}
    action = (data.get("action") or "").strip()
    comments = (data.get("comments") or "").strip()[:4000]
    if action not in ("approve", "request_changes", "reject"):
        return jsonify({"error": "action must be one of: approve, request_changes, reject."}), 400
    if action != "approve" and not comments:
        return jsonify({"error": "Please explain what needs to change or why this is rejected."}), 400

    status_map = {
        "approve": "approved_sealed",
        "request_changes": "changes_requested",
        "reject": "rejected",
    }
    review.status = status_map[action]
    review.lawyer_comments = comments or None
    review.responded_at = datetime.utcnow()
    if action == "approve":
        review.seal_code = "RJ-SEAL-" + secrets.token_hex(6).upper()

    session_rec = LegalAidSession.query.get(review.session_id)
    requesting_user = UserAccount.query.get(review.user_id)

    try:
        db.session.commit()
    except Exception as e:
        db.session.rollback(); logging.error(f"[LEGAL REVIEW SUBMIT] {e}")
        return jsonify({"error": "Could not save your response. Try again."}), 500

    if requesting_user:
        enqueue_job(
            _send_legal_review_verdict_email,
            requesting_user.email, requesting_user.name, review.lawyer_name_snapshot,
            (session_rec.title if session_rec else "Legal Question") or "Legal Question",
            review.status, review.lawyer_comments, review.seal_code,
        )

    return jsonify({"submitted": True, "review": review.to_dict(for_lawyer=True)}), 200


@app.route("/legal-aid/review", methods=["GET"])
def legal_aid_review_page():
    """Public landing page for the emailed review link — the lawyer has
    no Connect It account, so this must render outside any login gate.
    The SPA's own JS (_checkForLegalReviewLink) reads ?token= client-side
    and calls the /api/legal-aid/review/<token> endpoints above."""
    return render_template("index.html")


# ════════════════════════════════════════════════════════════
# SHARED: GENERIC PROFESSIONAL-REVIEW EMAILS
# One pair of email senders reused by the two new HITL flows below
# (AI Nutritionist -> doctor, Contract Generator -> lawyer) instead of
# copy-pasting _send_legal_review_request_email/_verdict_email again.
# Legal Aid's own two functions above are left untouched since they
# already work and nothing needs fixing there.
# ════════════════════════════════════════════════════════════

def _send_review_request_email(recipient_email, recipient_name, client_name, review_url,
                                 item_title, user_note, role_label, service_label, link_days):
    if not SMTP_USER or not SMTP_PASS:
        logging.warning(f"SMTP not configured — skipping {role_label} review request email.")
        return False
    note_text = (user_note or "").strip()
    note_block = (
        f'<p style="color:#334155;background:#f1f5f9;padding:12px;border-radius:8px;">'
        f'Note from {client_name}: {note_text}</p>'
    ) if note_text else ""
    html_body = f"""
    <!DOCTYPE html>
    <html><body style="font-family:Arial,sans-serif;background:#f8fafc;margin:0;padding:24px;">
      <div style="max-width:560px;margin:0 auto;background:white;border-radius:14px;overflow:hidden;
                  box-shadow:0 8px 32px rgba(0,0,0,0.1);">
        <div style="background:linear-gradient(90deg,#1e3a8a,#2563eb);padding:28px;text-align:center;">
          <h1 style="color:white;margin:0;font-size:1.4rem;">Connect It — {service_label} Review Request</h1>
        </div>
        <div style="padding:32px;">
          <p style="font-size:1rem;color:#1e293b;">Hi {recipient_name},</p>
          <p style="color:#64748b;line-height:1.7;">
            Your patient/client <strong>{client_name}</strong> used Connect It's {service_label} — a
            general-information tool, not a substitute for your professional judgement — for
            "<strong>{item_title}</strong>", and is asking you, as their own {role_label}, to review
            the AI's output, and either seal it as reviewed, request changes, or reject it.
          </p>
          {note_block}
          <div style="text-align:center;margin:28px 0;">
            <a href="{review_url}"
               style="background:linear-gradient(90deg,#1e3a8a,#2563eb);color:white;
                      padding:14px 32px;border-radius:10px;text-decoration:none;
                      font-weight:700;font-size:1rem;display:inline-block;">
               Review & Respond
            </a>
          </div>
          <p style="color:#9ca3af;font-size:0.82rem;text-align:center;">
            No account needed — this link is single-use and expires in {link_days} days.
          </p>
        </div>
      </div>
    </body></html>
    """
    try:
        msg = MIMEMultipart("alternative")
        msg["Subject"] = f"Review requested: {item_title}"
        msg["From"] = SMTP_FROM
        msg["To"] = recipient_email
        msg.attach(MIMEText(html_body, "html"))
        with smtplib.SMTP(SMTP_HOST, SMTP_PORT, timeout=15) as server:
            server.ehlo(); server.starttls()
            server.login(SMTP_USER, SMTP_PASS)
            server.sendmail(SMTP_USER, recipient_email, msg.as_string())
        logging.info(f"[{service_label.upper()} REVIEW] Request email sent to {recipient_email}")
        return True
    except Exception as e:
        logging.error(f"[{service_label.upper()} REVIEW] Failed to email {role_label} {recipient_email}: {e}")
        return False


def _send_review_verdict_email(user_email, user_name, reviewer_name, item_title, status,
                                 comments, seal_code, role_label, service_label):
    if not SMTP_USER or not SMTP_PASS:
        logging.warning(f"SMTP not configured — skipping {service_label} verdict email.")
        return False
    status_labels = {
        "approved_sealed": ("Sealed — reviewed and approved", "#15803d"),
        "changes_requested": ("Changes requested", "#b45309"),
        "rejected": ("Rejected", "#b91c1c"),
    }
    label, color = status_labels.get(status, (status, "#334155"))
    seal_block = (
        f'<p style="color:#15803d;font-weight:700;">Seal code: {seal_code}</p>' if seal_code else ""
    )
    comments_block = (
        f'<p style="color:#334155;background:#f1f5f9;padding:12px;border-radius:8px;">'
        f"{reviewer_name}'s comments: {comments}</p>"
    ) if comments else ""
    html_body = f"""
    <!DOCTYPE html>
    <html><body style="font-family:Arial,sans-serif;background:#f8fafc;margin:0;padding:24px;">
      <div style="max-width:560px;margin:0 auto;background:white;border-radius:14px;overflow:hidden;
                  box-shadow:0 8px 32px rgba(0,0,0,0.1);">
        <div style="background:linear-gradient(90deg,#1e3a8a,#2563eb);padding:28px;text-align:center;">
          <h1 style="color:white;margin:0;font-size:1.4rem;">Your {role_label} responded</h1>
        </div>
        <div style="padding:32px;">
          <p style="font-size:1rem;color:#1e293b;">Hi {user_name},</p>
          <p style="color:#64748b;line-height:1.7;">
            {reviewer_name} reviewed "<strong>{item_title}</strong>" in your {service_label} history.
          </p>
          <p style="font-size:1.1rem;font-weight:700;color:{color};">{label}</p>
          {seal_block}
          {comments_block}
          <p style="color:#9ca3af;font-size:0.82rem;">
            Open Connect It &rarr; {service_label} &rarr; this session to see the full response.
          </p>
        </div>
      </div>
    </body></html>
    """
    try:
        msg = MIMEMultipart("alternative")
        msg["Subject"] = f"Your {role_label} reviewed: {item_title}"
        msg["From"] = SMTP_FROM
        msg["To"] = user_email
        msg.attach(MIMEText(html_body, "html"))
        with smtplib.SMTP(SMTP_HOST, SMTP_PORT, timeout=15) as server:
            server.ehlo(); server.starttls()
            server.login(SMTP_USER, SMTP_PASS)
            server.sendmail(SMTP_USER, user_email, msg.as_string())
        logging.info(f"[{service_label.upper()} REVIEW] Verdict email sent to {user_email}")
        return True
    except Exception as e:
        logging.error(f"[{service_label.upper()} REVIEW] Failed to email user {user_email}: {e}")
        return False


# ════════════════════════════════════════════════════════════
# STAGE — AI NUTRITIONIST: SESSION HISTORY + DOCTOR HITL REVIEW & SEAL
#
# /api/nutrition/plan (above) previously returned a meal plan with
# nothing saved — there was nothing to send anywhere. This stage adds
# real persistence (NutritionPlanSession) plus the same
# register-your-own-professional / send-for-review / tokenized-link /
# seal-or-reject pattern used for Legal Aid, with a doctor instead of
# a lawyer. Same honesty rule: RegisteredDoctor fields are
# self-attested by the client — Connect It does not verify medical
# licensure against any board or registry.
# ════════════════════════════════════════════════════════════

NUTRITION_REVIEW_LINK_LIFETIME_DAYS = 14


class NutritionPlanSession(db.Model):
    __tablename__ = "nutrition_plan_sessions"
    id         = db.Column(db.Integer, primary_key=True)
    user_id    = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    country    = db.Column(db.String(80), nullable=False)
    goal       = db.Column(db.String(60), nullable=True)
    budget     = db.Column(db.String(60), nullable=True)
    avoid      = db.Column(db.String(300), nullable=True)
    people     = db.Column(db.Integer, nullable=True)
    plan_text  = db.Column(db.Text, nullable=False)
    created_at = db.Column(db.DateTime, default=datetime.utcnow, index=True)

    def to_dict(self, include_plan=False):
        latest_review = (
            NutritionReviewRequest.query
            .filter_by(session_id=self.id)
            .order_by(NutritionReviewRequest.requested_at.desc())
            .first()
        )
        d = {
            "id": self.id, "country": self.country, "goal": self.goal,
            "budget": self.budget, "avoid": self.avoid, "people": self.people,
            "created_at": self.created_at.isoformat() if self.created_at else None,
            "review": latest_review.to_dict() if latest_review else None,
        }
        if include_plan:
            d["plan_text"] = self.plan_text
            d["plan_html"] = format_ai_response(self.plan_text)
        return d


class RegisteredDoctor(db.Model):
    """A user's own doctor/dietitian. Self-attested — Connect It does not
    verify medical licensure against any board or registry."""
    __tablename__ = "registered_doctors"
    id          = db.Column(db.Integer, primary_key=True)
    user_id     = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    name        = db.Column(db.String(200), nullable=False)
    email       = db.Column(db.String(255), nullable=False)
    phone       = db.Column(db.String(60), nullable=True)
    clinic      = db.Column(db.String(200), nullable=True)
    license_number = db.Column(db.String(100), nullable=True)
    specialty   = db.Column(db.String(120), nullable=True)  # e.g. "Dietitian", "General Practitioner"
    is_active   = db.Column(db.Boolean, default=True)
    created_at  = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        return {
            "id": self.id, "name": self.name, "email": self.email,
            "phone": self.phone, "clinic": self.clinic,
            "license_number": self.license_number, "specialty": self.specialty,
            "is_active": self.is_active,
            "created_at": self.created_at.isoformat() if self.created_at else None,
            "verification_note": "Self-attested by the patient — not verified against a medical board.",
        }


class NutritionReviewRequest(db.Model):
    __tablename__ = "nutrition_review_requests"
    id          = db.Column(db.Integer, primary_key=True)
    session_id  = db.Column(db.Integer, db.ForeignKey("nutrition_plan_sessions.id"), nullable=False, index=True)
    user_id     = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    doctor_id   = db.Column(db.Integer, db.ForeignKey("registered_doctors.id"), nullable=False)

    doctor_name_snapshot  = db.Column(db.String(200), nullable=False)
    doctor_email_snapshot = db.Column(db.String(255), nullable=False)
    plan_snapshot          = db.Column(db.Text, nullable=False)
    user_note              = db.Column(db.Text, nullable=True)

    review_token = db.Column(db.String(64), unique=True, nullable=False, index=True)
    status       = db.Column(db.String(24), nullable=False, default="pending")

    doctor_comments = db.Column(db.Text, nullable=True)
    seal_code       = db.Column(db.String(40), nullable=True)

    requested_at = db.Column(db.DateTime, default=datetime.utcnow, index=True)
    responded_at = db.Column(db.DateTime, nullable=True)
    expires_at   = db.Column(db.DateTime, nullable=False)

    def is_expired(self):
        return self.status == "pending" and datetime.utcnow() > self.expires_at

    def to_dict(self, for_doctor=False):
        d = {
            "id": self.id, "session_id": self.session_id,
            "status": "expired" if self.is_expired() else self.status,
            "doctor_name": self.doctor_name_snapshot,
            "doctor_email": self.doctor_email_snapshot,
            "requested_at": self.requested_at.isoformat() if self.requested_at else None,
            "responded_at": self.responded_at.isoformat() if self.responded_at else None,
            "expires_at": self.expires_at.isoformat() if self.expires_at else None,
            "doctor_comments": self.doctor_comments,
            "seal_code": self.seal_code,
        }
        if for_doctor:
            d["user_note"] = self.user_note
            d["plan_text"] = self.plan_snapshot
            d["plan_html"] = format_ai_response(self.plan_snapshot)
        return d


@app.route("/api/nutrition/history", methods=["GET"])
def nutrition_history():
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    rows = (NutritionPlanSession.query.filter_by(user_id=user["id"])
            .order_by(NutritionPlanSession.created_at.desc()).limit(100).all())
    return jsonify({"sessions": [r.to_dict() for r in rows]}), 200


@app.route("/api/nutrition/sessions/<int:session_id>", methods=["GET"])
def nutrition_session_get(session_id):
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    row = NutritionPlanSession.query.get(session_id)
    if not row or row.user_id != user["id"]:
        return jsonify({"error": "Session not found."}), 404
    return jsonify({"session": row.to_dict(include_plan=True)}), 200


@app.route("/api/nutrition/sessions/<int:session_id>", methods=["DELETE"])
@csrf.exempt
def nutrition_session_delete(session_id):
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    row = NutritionPlanSession.query.get(session_id)
    if not row or row.user_id != user["id"]:
        return jsonify({"error": "Session not found."}), 404
    db.session.delete(row)
    db.session.commit()
