# ════════════════════════════════════════════════════════════
# STAGE — CONTRACT GENERATOR: SESSION HISTORY + LAWYER HITL REVIEW & SEAL
#
# Same gap as AI Nutritionist above: /api/legal/contract already tells
# the user "Have a lawyer review before signing" but never gave them a
# way to actually do that. This adds persistence (ContractDraftSession)
# and reuses RegisteredLawyer (already built for Legal Aid) — a user's
# lawyer list is the same list in both places, since it's the same
# lawyer either way.
# ════════════════════════════════════════════════════════════

CONTRACT_REVIEW_LINK_LIFETIME_DAYS = 14


class ContractDraftSession(db.Model):
    __tablename__ = "contract_draft_sessions"
    id            = db.Column(db.Integer, primary_key=True)
    user_id       = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    contract_type = db.Column(db.String(80), nullable=False)
    party_one     = db.Column(db.String(200), nullable=False)
    party_two     = db.Column(db.String(200), nullable=False)
    services      = db.Column(db.Text, nullable=True)
    payment_terms = db.Column(db.Text, nullable=True)
    duration      = db.Column(db.String(120), nullable=True)
    jurisdiction  = db.Column(db.String(120), nullable=True)
    contract_text = db.Column(db.Text, nullable=False)
    created_at    = db.Column(db.DateTime, default=datetime.utcnow, index=True)

    def to_dict(self, include_text=False):
        latest_review = (
            ContractReviewRequest.query
            .filter_by(session_id=self.id)
            .order_by(ContractReviewRequest.requested_at.desc())
            .first()
        )
        d = {
            "id": self.id, "contract_type": self.contract_type,
            "party_one": self.party_one, "party_two": self.party_two,
            "jurisdiction": self.jurisdiction, "duration": self.duration,
            "created_at": self.created_at.isoformat() if self.created_at else None,
            "review": latest_review.to_dict() if latest_review else None,
        }
        if include_text:
            d["contract_text"] = self.contract_text
            d["contract_html"] = format_ai_response(self.contract_text)
        return d


class ContractReviewRequest(db.Model):
    __tablename__ = "contract_review_requests"
    id          = db.Column(db.Integer, primary_key=True)
    session_id  = db.Column(db.Integer, db.ForeignKey("contract_draft_sessions.id"), nullable=False, index=True)
    user_id     = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    lawyer_id   = db.Column(db.Integer, db.ForeignKey("registered_lawyers.id"), nullable=False)

    lawyer_name_snapshot  = db.Column(db.String(200), nullable=False)
    lawyer_email_snapshot = db.Column(db.String(255), nullable=False)
    contract_snapshot      = db.Column(db.Text, nullable=False)
    user_note               = db.Column(db.Text, nullable=True)

    review_token = db.Column(db.String(64), unique=True, nullable=False, index=True)
    status       = db.Column(db.String(24), nullable=False, default="pending")

    lawyer_comments = db.Column(db.Text, nullable=True)
    seal_code       = db.Column(db.String(40), nullable=True)

    requested_at = db.Column(db.DateTime, default=datetime.utcnow, index=True)
    responded_at = db.Column(db.DateTime, nullable=True)
    expires_at   = db.Column(db.DateTime, nullable=False)

    def is_expired(self):
        return self.status == "pending" and datetime.utcnow() > self.expires_at

    def to_dict(self, for_lawyer=False):
        d = {
            "id": self.id, "session_id": self.session_id,
            "status": "expired" if self.is_expired() else self.status,
            "lawyer_name": self.lawyer_name_snapshot,
            "lawyer_email": self.lawyer_email_snapshot,
            "requested_at": self.requested_at.isoformat() if self.requested_at else None,
            "responded_at": self.responded_at.isoformat() if self.responded_at else None,
            "expires_at": self.expires_at.isoformat() if self.expires_at else None,
            "lawyer_comments": self.lawyer_comments,
            "seal_code": self.seal_code,
        }
        if for_lawyer:
            d["user_note"] = self.user_note
            d["contract_text"] = self.contract_snapshot
            d["contract_html"] = format_ai_response(self.contract_snapshot)
        return d


