@app.route("/api/legal/contract/sessions/<int:session_id>/send-to-lawyer", methods=["POST"])
@csrf.exempt
def contract_send_to_lawyer(session_id):
    """Same HITL trigger as Legal Aid's send-to-lawyer, reusing the same
    RegisteredLawyer list — a user's lawyer is the same person whether
    they're reviewing a Legal Aid answer or a generated contract."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401

    session_rec = ContractDraftSession.query.get(session_id)
    if not session_rec or session_rec.user_id != user["id"]:
        return jsonify({"error": "Session not found."}), 404

    data = request.get_json(silent=True) or {}
    lawyer_id = data.get("lawyer_id")
    lawyer = RegisteredLawyer.query.get(lawyer_id) if lawyer_id else None
    if not lawyer or lawyer.user_id != user["id"] or not lawyer.is_active:
        return jsonify({"error": "Select one of your registered lawyers first (add one under Legal Aid → My Lawyers)."}), 400

    existing = (ContractReviewRequest.query
                .filter_by(session_id=session_id, status="pending")
                .order_by(ContractReviewRequest.requested_at.desc()).first())
    if existing and not existing.is_expired():
        return jsonify({
            "error": "This contract is already awaiting review from a lawyer.",
            "review": existing.to_dict(),
        }), 409

    review = ContractReviewRequest(
        session_id=session_id, user_id=user["id"], lawyer_id=lawyer.id,
        lawyer_name_snapshot=lawyer.name, lawyer_email_snapshot=lawyer.email,
        contract_snapshot=session_rec.contract_text,
        user_note=(data.get("note") or "").strip()[:1000] or None,
        review_token=secrets.token_urlsafe(48),
        status="pending",
        expires_at=datetime.utcnow() + timedelta(days=CONTRACT_REVIEW_LINK_LIFETIME_DAYS),
    )
    try:
        db.session.add(review); db.session.commit()
    except Exception as e:
        db.session.rollback(); logging.error(f"[CONTRACT REVIEW REQUEST SAVE] {e}")
        return jsonify({"error": "Could not create the review request. Try again."}), 500

    review_url = f"{APP_BASE_URL}/legal/contract/review?token={review.review_token}"
    title = f"{session_rec.contract_type} — {session_rec.party_one} / {session_rec.party_two}"
    enqueue_job(
        _send_review_request_email,
        lawyer.email, lawyer.name, user["name"], review_url,
        title, review.user_note, "lawyer", "Contract Generator", CONTRACT_REVIEW_LINK_LIFETIME_DAYS,
    )

    return jsonify({
        "sent": True, "review": review.to_dict(),
        "message": f"Sent to {lawyer.name} ({lawyer.email}) for review.",
    }), 201


@app.route("/api/legal/contract/review/<token>", methods=["GET"])
@csrf.exempt
def contract_review_view(token):
    review = ContractReviewRequest.query.filter_by(review_token=token).first()
    if not review:
        return jsonify({"error": "This review link is invalid."}), 404
    if review.is_expired():
        return jsonify({"error": "This review link has expired.", "review": review.to_dict()}), 410
    session_rec = ContractDraftSession.query.get(review.session_id)
    return jsonify({
        "review": review.to_dict(for_lawyer=True),
        "contract_type": session_rec.contract_type if session_rec else None,
        "jurisdiction": session_rec.jurisdiction if session_rec else None,
        "disclaimer": (
            "This contract draft was produced by an AI drafting tool, not by a lawyer. "
            "You are being asked, as one party's own registered legal practitioner, to "
            "review it and either seal it as reviewed, request changes, or reject it."
        ),
    }), 200


@app.route("/api/legal/contract/review/<token>", methods=["POST"])
@csrf.exempt
def contract_review_submit(token):
    review = ContractReviewRequest.query.filter_by(review_token=token).first()
    if not review:
        return jsonify({"error": "This review link is invalid."}), 404
    if review.status != "pending":
        return jsonify({"error": f"This review was already resolved ({review.status})."}), 409
    if review.is_expired():
        review.status = "expired"
        db.session.commit()
        return jsonify({"error": "This review link has expired."}), 410

    data = request.get_json(silent=True) or {}
    action = (data.get("action") or "").strip()
    comments = (data.get("comments") or "").strip()[:4000]
    if action not in ("approve", "request_changes", "reject"):
        return jsonify({"error": "action must be one of: approve, request_changes, reject."}), 400
    if action != "approve" and not comments:
        return jsonify({"error": "Please explain what needs to change or why this is rejected."}), 400

    status_map = {"approve": "approved_sealed", "request_changes": "changes_requested", "reject": "rejected"}
    review.status = status_map[action]
    review.lawyer_comments = comments or None
    review.responded_at = datetime.utcnow()
    if action == "approve":
        review.seal_code = "RJ-SEAL-" + secrets.token_hex(6).upper()

    session_rec = ContractDraftSession.query.get(review.session_id)
    requesting_user = UserAccount.query.get(review.user_id)

    try:
        db.session.commit()
    except Exception as e:
        db.session.rollback(); logging.error(f"[CONTRACT REVIEW SUBMIT] {e}")
        return jsonify({"error": "Could not save your response. Try again."}), 500

    if requesting_user:
        title = f"{(session_rec.contract_type if session_rec else 'Contract')}"
        enqueue_job(
            _send_review_verdict_email,
            requesting_user.email, requesting_user.name, review.lawyer_name_snapshot,
            title, review.status, review.lawyer_comments, review.seal_code,
            "lawyer", "Contract Generator",
        )

    return jsonify({"submitted": True, "review": review.to_dict(for_lawyer=True)}), 200


