@app.route("/api/legal-aid/sessions", methods=["GET", "POST"])
@csrf.exempt
def legal_aid_sessions():
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401

    if request.method == "GET":
        rows = (LegalAidSession.query.filter_by(user_id=user["id"])
                .order_by(LegalAidSession.updated_at.desc()).limit(50).all())
        return jsonify({"sessions": [r.to_dict() for r in rows]}), 200

    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    data     = request.get_json(silent=True) or {}
    country  = (data.get("country") or "General").strip()[:80]
    category = (data.get("category") or "custom").strip()[:40]
    question = (data.get("question") or "").strip()

    if category == "custom":
        if not question or len(question) < 5:
            return jsonify({"error": "Enter your legal question."}), 400
    else:
        question = LEGAL_AID_CATEGORY_PROMPTS.get(category)
        if not question:
            return jsonify({"error": "Unknown category."}), 400

    title = LEGAL_AID_CATEGORY_TITLES.get(category, "Legal Question")
    gate_result = gate_ai_usage(user, "legal_aid_sessions")
    if gate_result is not None:
        return gate_result
    system_prompt = _legal_aid_system_prompt(country)
    result, _ = generate_ai_reply(question, [], user_id=user["id"], system_prompt=system_prompt)
    reply = format_ai_response(result)

    now_iso = datetime.utcnow().isoformat()
    transcript = [
        {"role": "user", "content": question, "at": now_iso},
        {"role": "assistant", "content": result, "at": now_iso},
    ]

    try:
        rec = LegalAidSession(
            user_id=user["id"], country=country, category=category,
            title=title, transcript_json=json.dumps(transcript),
        )
        db.session.add(rec); db.session.commit()
    except Exception as e:
        db.session.rollback(); logging.error(f"[LEGAL AID SESSION SAVE] {e}")
        return jsonify({
            "reply": reply, "reply_text": result, "country": country,
            "category": category, "title": title, "saved": False,
            "directory_entry": LEGAL_AID_DIRECTORY.get(country),
            "powered_by": "Connect It",
        }), 200

    return jsonify({
        "reply": reply, "reply_text": result, "saved": True,
        "session": rec.to_dict(include_transcript=True),
        "directory_entry": LEGAL_AID_DIRECTORY.get(country),
        "powered_by": "Connect It",
    }), 200


