@app.route("/api/wellbeing/checkins/<int:checkin_id>/send-to-professional", methods=["POST"])
@csrf.exempt
def wellbeing_send_to_professional(checkin_id):
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401

    checkin = WellbeingCheckIn.query.get(checkin_id)
    if not checkin or checkin.owner_user_id != user["id"]:
        return jsonify({"error": "Check-in not found."}), 404

    data = request.get_json(silent=True) or {}
    professional_id = data.get("professional_id")
    professional = RegisteredMentalHealthProfessional.query.get(professional_id) if professional_id else None
    if not professional or professional.user_id != user["id"] or not professional.is_active:
        return jsonify({"error": "Select one of your registered mental health professionals first (add one under Stress Score → My Professionals)."}), 400

    existing = (WellbeingReviewRequest.query
                .filter_by(checkin_id=checkin_id, status="pending")
                .order_by(WellbeingReviewRequest.requested_at.desc()).first())
    if existing and not existing.is_expired():
        return jsonify({
            "error": "This reading is already awaiting review from a professional.",
            "review": existing.to_dict(),
        }), 409

    review = WellbeingReviewRequest(
        checkin_id=checkin_id, user_id=user["id"], professional_id=professional.id,
        professional_name_snapshot=professional.name, professional_email_snapshot=professional.email,
        checkin_snapshot_json=json.dumps(checkin.to_dict()),
        user_note=(data.get("note") or "").strip()[:1000] or None,
        review_token=secrets.token_urlsafe(48),
        status="pending",
        expires_at=datetime.utcnow() + timedelta(days=WELLBEING_REVIEW_LINK_LIFETIME_DAYS),
    )
    try:
        db.session.add(review); db.session.commit()
    except Exception as e:
        db.session.rollback(); logging.error(f"[WELLBEING REVIEW REQUEST SAVE] {e}")
        return jsonify({"error": "Could not create the review request. Try again."}), 500

    review_url = f"{APP_BASE_URL}/wellbeing/review?token={review.review_token}"
    enqueue_job(
        _send_review_request_email,
        professional.email, professional.name, user["name"], review_url,
        f"Stress Score reading ({checkin.level})", review.user_note,
        "mental health professional", "Stress Score", WELLBEING_REVIEW_LINK_LIFETIME_DAYS,
    )

    return jsonify({
        "sent": True, "review": review.to_dict(),
        "message": f"Sent to {professional.name} ({professional.email}) for review.",
    }), 201


