GRANT_REVIEW_LINK_LIFETIME_DAYS = 14

GRANT_FINDER_DISCLAIMER = (
    "These funding matches were produced by an AI tool, not by a financial advisor. "
    "Verify eligibility, terms, and legitimacy directly with each funder before applying, "
    "paying any fee, or signing anything."
)


class GrantFinderSession(db.Model):
    __tablename__ = "grant_finder_sessions"
    id          = db.Column(db.Integer, primary_key=True)
    user_id     = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    country     = db.Column(db.String(80), nullable=False)
    purpose     = db.Column(db.String(300), nullable=True)
    amount      = db.Column(db.String(60), nullable=True)
    profile     = db.Column(db.Text, nullable=True)
    stage       = db.Column(db.String(40), nullable=True)
    grants_text = db.Column(db.Text, nullable=False)
    created_at  = db.Column(db.DateTime, default=datetime.utcnow, index=True)

    def to_dict(self, include_grants=False):
        latest_review = (
            GrantReviewRequest.query
            .filter_by(session_id=self.id)
            .order_by(GrantReviewRequest.requested_at.desc())
            .first()
        )
        d = {
            "id": self.id, "country": self.country, "purpose": self.purpose,
            "amount": self.amount, "stage": self.stage,
            "created_at": self.created_at.isoformat() if self.created_at else None,
            "review": latest_review.to_dict() if latest_review else None,
        }
        if include_grants:
            d["profile"] = self.profile
            d["grants_text"] = self.grants_text
            d["grants_html"] = format_ai_response(self.grants_text)
        return d


class RegisteredFinancialAdvisor(db.Model):
    """A user's own financial advisor / loan officer / grant officer /
    accountant. Self-attested — Connect It does not verify any
    credential or accreditation against a registry."""
    __tablename__ = "registered_financial_advisors"
    id          = db.Column(db.Integer, primary_key=True)
    user_id     = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    name        = db.Column(db.String(200), nullable=False)
    email       = db.Column(db.String(255), nullable=False)
    phone       = db.Column(db.String(60), nullable=True)
    firm_name   = db.Column(db.String(200), nullable=True)
    license_number = db.Column(db.String(100), nullable=True)
    advisor_type = db.Column(db.String(120), nullable=True)  # e.g. "Loan Officer", "Grant Officer", "Financial Advisor", "Accountant"
    country     = db.Column(db.String(80), nullable=True)
    is_active   = db.Column(db.Boolean, default=True)
    created_at  = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        return {
            "id": self.id, "name": self.name, "email": self.email,
            "phone": self.phone, "firm_name": self.firm_name,
            "license_number": self.license_number, "advisor_type": self.advisor_type,
            "country": self.country, "is_active": self.is_active,
            "created_at": self.created_at.isoformat() if self.created_at else None,
            "verification_note": "Self-attested by the user — not verified against a licensing or accreditation registry.",
        }


class GrantReviewRequest(db.Model):
    __tablename__ = "grant_review_requests"
    id          = db.Column(db.Integer, primary_key=True)
    session_id  = db.Column(db.Integer, db.ForeignKey("grant_finder_sessions.id"), nullable=False, index=True)
    user_id     = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    advisor_id  = db.Column(db.Integer, db.ForeignKey("registered_financial_advisors.id"), nullable=False)

    advisor_name_snapshot  = db.Column(db.String(200), nullable=False)
    advisor_email_snapshot = db.Column(db.String(255), nullable=False)
    grants_snapshot         = db.Column(db.Text, nullable=False)
    user_note               = db.Column(db.Text, nullable=True)

    review_token = db.Column(db.String(64), unique=True, nullable=False, index=True)
    status       = db.Column(db.String(24), nullable=False, default="pending")

    advisor_comments = db.Column(db.Text, nullable=True)
    seal_code         = db.Column(db.String(40), nullable=True)

    requested_at = db.Column(db.DateTime, default=datetime.utcnow, index=True)
    responded_at = db.Column(db.DateTime, nullable=True)
    expires_at   = db.Column(db.DateTime, nullable=False)

    def is_expired(self):
        return self.status == "pending" and datetime.utcnow() > self.expires_at

    def to_dict(self, for_advisor=False):
        d = {
            "id": self.id, "session_id": self.session_id,
            "status": "expired" if self.is_expired() else self.status,
            "advisor_name": self.advisor_name_snapshot,
            "advisor_email": self.advisor_email_snapshot,
            "requested_at": self.requested_at.isoformat() if self.requested_at else None,
            "responded_at": self.responded_at.isoformat() if self.responded_at else None,
            "expires_at": self.expires_at.isoformat() if self.expires_at else None,
            "advisor_comments": self.advisor_comments,
            "seal_code": self.seal_code,
        }
        if for_advisor:
            d["user_note"] = self.user_note
            d["grants_text"] = self.grants_snapshot
            d["grants_html"] = format_ai_response(self.grants_snapshot)
        return d


