# ── STAGE 134: PRODUCT RECALL CHECKER ───────────────────────
# Live query against the real US CPSC recall database
# (saferproducts.gov REST API, public + documented) plus a real deep link
# into the official EU Safety Gate portal search for the same product name.
CPSC_RECALL_API = "https://www.saferproducts.gov/RestWebServices/Recall"
EU_SAFETY_GATE_SEARCH = "https://ec.europa.eu/safety-gate-alerts/screen/webReport"

@app.route("/api/compliance/recall-check", methods=["POST"])
@csrf.exempt
def product_recall_check():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    product_name = (data.get("product_name") or "").strip()
    if not product_name:
        return jsonify({"error": "product_name is required."}), 400

    matches = []
    cpsc_error = None
    try:
        resp = requests.get(CPSC_RECALL_API, params={"ProductName": product_name, "format": "json"}, timeout=12)
        if resp.ok:
            raw = resp.json() if resp.text.strip() else []
            for r in raw[:25]:
                products = r.get("Products") or []
                hazards = r.get("Hazards") or []
                matches.append({
                    "recall_number": r.get("RecallNumber"),
                    "recall_date": r.get("RecallDate"),
                    "title": r.get("Title"),
                    "description": (r.get("Description") or "")[:500],
                    "product_names": [p.get("Name") for p in products if p.get("Name")],
                    "hazards": [h.get("Name") for h in hazards if h.get("Name")],
                    "url": r.get("URL"),
                })
        else:
            cpsc_error = f"CPSC API returned status {resp.status_code}"
    except Exception as e:
        logging.error(f"[RECALL CHECK CPSC] {e}")
        cpsc_error = "Could not reach the CPSC recall database right now."

    eu_url = EU_SAFETY_GATE_SEARCH + "?text=" + quote(product_name)

    try:
        rec = ProductRecallCheck(
            user_id=user["id"], product_name=product_name[:300],
            cpsc_match_count=len(matches), cpsc_matches_json=json.dumps(matches),
            eu_search_url=eu_url,
        )
        db.session.add(rec); db.session.commit()
        saved = True
    except Exception as e:
        db.session.rollback(); logging.error(f"[RECALL CHECK SAVE] {e}")
        saved = False

    return jsonify({
        "product_name": product_name, "cpsc_matches": matches, "cpsc_match_count": len(matches),
        "cpsc_error": cpsc_error, "eu_search_url": eu_url, "saved": saved,
    }), 200


