# ── STAGE 135: HS CODE CLASSIFIER ───────────────────────────
# Live keyword search against the official USITC Harmonized Tariff
# Schedule REST API (hts.usitc.gov/reststop/search) — public, free, no
# API key. Returns real tariff-line matches; the first 6 digits of any
# result are the globally recognized HS code.
USITC_HTS_SEARCH = "https://hts.usitc.gov/reststop/search"

@app.route("/api/compliance/hs-code-lookup", methods=["POST"])
@csrf.exempt
def hs_code_lookup():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    query = (data.get("product_query") or "").strip()
    if not query:
        return jsonify({"error": "product_query is required."}), 400

    results = []
    error = None
    try:
        resp = requests.get(USITC_HTS_SEARCH, params={"keyword": query}, timeout=12)
        if resp.ok:
            raw = resp.json() if resp.text.strip() else []
            # Keep only lines that actually carry a duty rate (real classifiable
            # tariff lines) rather than section/heading text-only rows, and cap
            # to the most relevant first results.
            for r in raw:
                if r.get("general") not in (None, "") or r.get("special") not in (None, ""):
                    results.append({
                        "hts_number": r.get("htsno"),
                        "hs_code_6digit": (r.get("htsno") or "").replace(".", "")[:6],
                        "description": r.get("description"),
                        "general_duty": r.get("general"),
                        "special_duty": r.get("special"),
                        "other_duty": r.get("other"),
                        "units": r.get("units"),
                    })
                if len(results) >= 20:
                    break
        else:
            error = f"USITC HTS API returned status {resp.status_code}"
    except Exception as e:
        logging.error(f"[HS CODE LOOKUP] {e}")
        error = "Could not reach the USITC tariff database right now."

    try:
        rec = HsCodeLookup(user_id=user["id"], product_query=query[:300], results_json=json.dumps(results))
        db.session.add(rec); db.session.commit()
        saved = True
    except Exception as e:
        db.session.rollback(); logging.error(f"[HS CODE LOOKUP SAVE] {e}")
        saved = False

    return jsonify({"product_query": query, "results": results, "error": error, "saved": saved}), 200


