# ── STAGE 136: CARBON FOOTPRINT FROM REAL LEDGER DATA ───────
# Real published EPA/EIA emission factors + average prices (see model
# docstring above for sources). Spend-based estimate from real ErpExpense
# rows already in the ledger — no simulated data.
_CARBON_FACTORS = {
    # category_keyword: (price_per_unit_usd, kg_co2_per_unit, unit_label)
    "fuel":        (3.69,   8.887,  "gallon of gasoline"),
    "gasoline":    (3.69,   8.887,  "gallon of gasoline"),
    "petrol":      (3.69,   8.887,  "gallon of gasoline"),
    "diesel":      (3.85,   10.180, "gallon of diesel"),
    "electricity": (0.1609, 0.394,  "kWh"),
    "power":       (0.1609, 0.394,  "kWh"),
    "utility":     (0.1609, 0.394,  "kWh"),
    "natural_gas": (0.01523, 0.0550, "cubic foot of natural gas"),  # $15.23 per 1000 cu ft
    "gas_heating": (0.01523, 0.0550, "cubic foot of natural gas"),
}

@app.route("/api/sustainability/carbon-footprint", methods=["POST"])
@csrf.exempt
def carbon_footprint_calc():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    start = _erp_parse_date(data.get("period_start"), None)
    end = _erp_parse_date(data.get("period_end"), None)

    q = ErpExpense.query.filter_by(owner_user_id=user["id"])
    if start: q = q.filter(ErpExpense.expense_date >= start)
    if end: q = q.filter(ErpExpense.expense_date <= end)
    expenses = q.all()

    totals = {}   # category -> {usd, kg_co2e, unit_qty, unit_label}
    unmatched_usd = 0.0
    for e in expenses:
        cat_key = (e.category or "").strip().lower().replace(" ", "_")
        factor = _CARBON_FACTORS.get(cat_key)
        if not factor:
            unmatched_usd += e.amount or 0
            continue
        price_per_unit, kg_per_unit, unit_label = factor
        qty = (e.amount or 0) / price_per_unit
        kg = qty * kg_per_unit
        bucket = totals.setdefault(cat_key, {"usd": 0.0, "kg_co2e": 0.0, "unit_qty": 0.0, "unit_label": unit_label})
        bucket["usd"] += e.amount or 0
        bucket["kg_co2e"] += kg
        bucket["unit_qty"] += qty

    breakdown = [
        {"category": k, "spend_usd": round(v["usd"], 2), "estimated_units": round(v["unit_qty"], 2),
         "unit_label": v["unit_label"], "kg_co2e": round(v["kg_co2e"], 2)}
        for k, v in totals.items()
    ]
    total_kg = round(sum(v["kg_co2e"] for v in totals.values()), 2)

    try:
        rec = CarbonFootprintReport(
            user_id=user["id"], period_start=start, period_end=end,
            total_kg_co2e=total_kg, breakdown_json=json.dumps(breakdown),
            expenses_scanned=len(expenses),
        )
        db.session.add(rec); db.session.commit()
        saved = True
    except Exception as e:
        db.session.rollback(); logging.error(f"[CARBON FOOTPRINT SAVE] {e}")
        saved = False

    return jsonify({
        "total_kg_co2e": total_kg, "breakdown": breakdown, "expenses_scanned": len(expenses),
        "unmatched_spend_usd": round(unmatched_usd, 2), "saved": saved,
        "methodology": "Spend-based estimate: $ spent \u00f7 EIA average price per unit \u00d7 EPA published kg CO2 per unit. Categories matched: fuel/gasoline/diesel, electricity/power/utility, natural_gas/gas_heating. Other expense categories are not included in the estimate.",
    }), 200


