# ── STAGE 137: MEETING-TO-ACTION-ITEMS ──────────────────────
# Chains: real Whisper transcription (existing integration) → AI
# translation if needed → AI structured action-item extraction → real
# UserTodo rows created with owner + due date. Every step uses real
# services already wired into this app; nothing here is simulated.
@app.route("/api/productivity/meeting-transcribe", methods=["POST"])
@csrf.exempt
def meeting_transcribe():
    if 'audio' not in request.files:
        return jsonify({'error': 'No audio file provided'}), 400
    audio_file = request.files['audio']
    if not audio_file.filename:
        return jsonify({'error': 'Empty audio file'}), 400

    current_user = _get_current_user()
    current_uid = current_user.get('id') if current_user else None
    byok_key = get_effective_credential(current_uid, 'openai', 'api_key', None)
    client = OpenAI(api_key=byok_key) if byok_key else openai_client
    if not client:
        return jsonify({'error': 'OpenAI client not initialised. Add your own OpenAI key under Settings > Integrations.'}), 503

    with tempfile.NamedTemporaryFile(delete=False, suffix='.webm') as tmp:
        audio_file.save(tmp.name)
        tmp_path = tmp.name
    try:
        # No language forced — Whisper auto-detects the spoken language,
        # which is what lets this work for a meeting in any language.
        with open(tmp_path, 'rb') as f:
            result = client.audio.transcriptions.create(
                model='whisper-1', file=f, response_format='verbose_json'
            )
        transcript = result.text
        detected_language = getattr(result, 'language', None)
        return jsonify({'transcript': transcript, 'detected_language': detected_language}), 200
    except Exception as e:
        logging.error(f'[MEETING TRANSCRIBE] {e}')
        return jsonify({'error': str(e)}), 500
    finally:
        try: os.unlink(tmp_path)
        except Exception: pass


@app.route("/api/productivity/meeting-extract-actions", methods=["POST"])
@csrf.exempt
def meeting_extract_actions():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    transcript = (data.get("transcript") or "").strip()
    meeting_title = data.get("meeting_title") or "Untitled meeting"
    detected_language = data.get("detected_language")
    target_language = (data.get("target_language") or "").strip()  # e.g. "English" — optional
    if not transcript or len(transcript) < 20:
        return jsonify({"error": "A meeting transcript is required (record or paste one first)."}), 400

    gate_result = gate_ai_usage(user, "meeting_extract_actions")
    if gate_result is not None:
        return gate_result

    working_text = transcript
    translated_text = None
    if target_language:
        translate_prompt = (
            f"Translate the following meeting transcript into {target_language}. "
            f"Output ONLY the translated text, nothing else.\n\nTRANSCRIPT:\n{transcript[:8000]}"
        )
        translated_text, _ = generate_ai_reply(translate_prompt, [])
        working_text = translated_text

    extract_system_prompt = (
        "You extract action items from a meeting transcript. Respond with ONLY valid JSON, "
        "no markdown fences, no commentary. Format: "
        '{"action_items": [{"task": "...", "owner": "name or null", "due_date": "YYYY-MM-DD or null"}]}. '
        "Only include real, concrete action items actually discussed. If a due date isn't stated, use null. "
        "If no owner is named for a task, use null."
    )
    extract_result, _ = generate_ai_reply(
        f"MEETING TRANSCRIPT:\n{working_text[:8000]}", [], system_prompt=extract_system_prompt
    )

    action_items = []
    try:
        cleaned = re.sub(r"^```(json)?|```$", "", extract_result.strip(), flags=re.MULTILINE).strip()
        parsed = json.loads(cleaned)
        action_items = parsed.get("action_items", []) if isinstance(parsed, dict) else []
    except Exception as e:
        logging.error(f"[MEETING EXTRACT PARSE] {e}")

    todos_created = 0
    for item in action_items:
        task = (item.get("task") or "").strip()
        if not task:
            continue
        due = None
        try:
            if item.get("due_date"):
                due = datetime.strptime(item["due_date"], "%Y-%m-%d").date()
        except Exception:
            due = None
        try:
            db.session.add(UserTodo(
                user_id=user["id"], text=task[:500], due_date=due,
                owner_name=(item.get("owner") or None), source=f"meeting:{meeting_title[:60]}",
            ))
            todos_created += 1
        except Exception as e:
            logging.error(f"[MEETING TODO CREATE] {e}")

    try:
        rec = MeetingActionExtraction(
            user_id=user["id"], meeting_title=meeting_title[:200], transcript=transcript,
            translated_text=translated_text, detected_language=detected_language,
            action_items_json=json.dumps(action_items), todos_created=todos_created,
        )
        db.session.add(rec); db.session.commit()
    except Exception as e:
        db.session.rollback(); logging.error(f"[MEETING EXTRACT SAVE] {e}")
        return jsonify({"error": "Could not save meeting record."}), 500

    return jsonify({
        "action_items": action_items, "todos_created": todos_created,
        "translated_text": translated_text, "meeting": rec.to_dict(),
    }), 200


