# ── 27. FILE INTELLIGENCE — REAL CONTENT EXTRACTION ─────────
MAX_CHARS_PER_FILE = 20000

# Core extraction (txt/md/py/js/html/css/json/csv/zip) needs no external
# libraries at all, so it's always available. PDF/DOCX/XLSX each depend on
# their own optional library and are guarded individually below.
FILE_INTEL_AVAILABLE = True

def _fi_truncate(text):
    if len(text) > MAX_CHARS_PER_FILE:
        return text[:MAX_CHARS_PER_FILE] + f"\n\n...[truncated, {len(text) - MAX_CHARS_PER_FILE} more characters omitted]"
    return text

def _fi_extract_pdf(b):
    if not PDF_AVAILABLE:
        return "[PDF analysis library (PyPDF2) not installed on server — contact admin]"
    reader = PdfReader(io.BytesIO(b))
    pages = [f"--- Page {i+1} ---\n{p.extract_text() or ''}" for i, p in enumerate(reader.pages)]
    return _fi_truncate("\n".join(pages))

def _fi_extract_docx(b):
    if not DOCX_AVAILABLE:
        return "[DOCX analysis library (python-docx) not installed on server — contact admin]"
    doc = Document(io.BytesIO(b))
    parts = [p.text for p in doc.paragraphs if p.text.strip()]
    for table in doc.tables:
        for row in table.rows:
            parts.append(" | ".join(c.text for c in row.cells))
    return _fi_truncate("\n".join(parts))

def _fi_extract_xlsx(b):
    if not OPENPYXL_AVAILABLE:
        return "[XLSX analysis library (openpyxl) not installed on server — contact admin]"
    wb = load_workbook(io.BytesIO(b), data_only=True)
    out = []
    for sheet in wb.worksheets:
        out.append(f"--- Sheet: {sheet.title} ---")
        for row in sheet.iter_rows(values_only=True):
            if any(c is not None for c in row):
                out.append(", ".join(str(c) if c is not None else "" for c in row))
    return _fi_truncate("\n".join(out))

def _fi_extract_csv(b):
    text = b.decode("utf-8", errors="replace")
    return _fi_truncate("\n".join(", ".join(r) for r in csv.reader(io.StringIO(text))))

def _fi_extract_json(b):
    try:
        parsed = json.loads(b.decode("utf-8", errors="replace"))
        return _fi_truncate(json.dumps(parsed, indent=2))
    except json.JSONDecodeError as e:
        return f"[INVALID JSON — could not parse: {e}]\n\nRaw content:\n" + _fi_truncate(b.decode("utf-8", errors="replace"))

def _fi_extract_zip(b):
    out = []
    with zipfile.ZipFile(io.BytesIO(b)) as z:
        names = z.namelist()
        out.append(f"ZIP contains {len(names)} entries:")
        out.append("\n".join(names[:200]))
        for name in names:
            if name.endswith("/"):
                continue
            if name.lower().endswith((".txt", ".md", ".py", ".js", ".html", ".css", ".json", ".csv")):
                info = z.getinfo(name)
                if info.file_size > 50_000:
                    continue
                try:
                    out.append(f"\n--- {name} ---\n{_fi_truncate(z.read(name).decode('utf-8', errors='replace'))}")
                except Exception as e:
                    out.append(f"\n--- {name} (could not read: {e}) ---")
    return _fi_truncate("\n".join(out))

def _fi_extract_text(b):
    return _fi_truncate(b.decode("utf-8", errors="replace"))

_FI_EXTRACTORS = {
    "pdf": _fi_extract_pdf, "docx": _fi_extract_docx,
    "xlsx": _fi_extract_xlsx, "xls": _fi_extract_xlsx,
    "csv": _fi_extract_csv, "json": _fi_extract_json, "zip": _fi_extract_zip,
    "txt": _fi_extract_text, "md": _fi_extract_text, "py": _fi_extract_text,
    "js": _fi_extract_text, "html": _fi_extract_text, "css": _fi_extract_text,
}

def fi_extract(filename, file_bytes):
    if not FILE_INTEL_AVAILABLE:
        return "[File analysis is disabled on this server]"
    ext = filename.rsplit(".", 1)[-1].lower() if "." in filename else ""
    fn = _FI_EXTRACTORS.get(ext)
    if not fn:
        return f"[Unsupported file type '.{ext}' — could not extract content for analysis]"
    try:
        return fn(file_bytes)
    except Exception as e:
        return f"[Failed to parse {filename}: {e}]"


# ===========================================================
# ATTACH FILE CONTENT TO THE ACTUAL CONVERSATION
# Extraction alone isn't enough — the extracted text has to be threaded
# into the message that actually reaches generate_ai_reply(), or Connect It
# AI never "sees" what was uploaded. This helper pulls attachments from
# either a multipart/form-data upload or a JSON body (base64 or
# already-extracted text) on the SAME request as the chat message, and
# turns them into a clearly-labelled block to prepend to the user's text.
# ===========================================================

MAX_ATTACHMENT_BYTES = 15 * 1024 * 1024

def _extract_request_attachments() -> str:
    blocks = []

    # Case 1: multipart/form-data upload — request.files
    for key in ("files", "file", "attachments"):
        if key in request.files:
            for f in request.files.getlist(key):
                raw = f.read()
                if not raw:
                    continue
                if len(raw) > MAX_ATTACHMENT_BYTES:
                    blocks.append(f"[Attached file: {f.filename} — too large to analyze (15MB limit)]")
                    continue
                blocks.append(f"[Attached file: {f.filename}]\n{fi_extract(f.filename, raw)}")

    # Case 2: JSON body carrying already-extracted text or base64 bytes
    json_body = request.get_json(silent=True) or {}
    for att in (json_body.get("attachments") or []):
        filename = att.get("filename", "file")
        if att.get("content"):
            blocks.append(f"[Attached file: {filename}]\n{att['content']}")
        elif att.get("base64"):
            try:
                raw = base64.b64decode(att["base64"])
                if len(raw) > MAX_ATTACHMENT_BYTES:
                    blocks.append(f"[Attached file: {filename} — too large to analyze (15MB limit)]")
                else:
                    blocks.append(f"[Attached file: {filename}]\n{fi_extract(filename, raw)}")
            except Exception as e:
                blocks.append(f"[Attached file: {filename} — could not decode: {e}]")

    return "\n\n".join(blocks)


def _merge_content_with_attachments(user_content: str) -> str:
    """Combine typed text with any attached file content into one message
    Connect It actually receives, so it can analyze exactly what was shared."""
    attachments_block = _extract_request_attachments()
    if not attachments_block:
        return user_content
    if user_content:
        return f"{attachments_block}\n\nThe user says about the file(s) above: {user_content}"
    return f"{attachments_block}\n\nPlease analyze the attached file(s) above and tell me what you find."


