def connectit_json_response(data, status=200):
    """Standardised JSON response with CORS headers."""
    from flask import jsonify, make_response
    resp = make_response(jsonify(data), status)
    resp.headers["Content-Type"] = "application/json"
    resp.headers["X-Powered-By"]  = "Connect It"
    return resp

def validate_amount(amount, min_val=0.50, max_val=10000.00):
    """Validate payment amount is within acceptable range."""
    try:
        amt = float(amount)
        return min_val <= amt <= max_val
    except (TypeError, ValueError):
        return False

def generate_tx_ref(prefix="REJ"):
    """Generate a unique transaction reference."""
    ts  = str(int(time.time()))[-8:]
    rnd = base64.urlsafe_b64encode(os.urandom(4)).decode()[:4].upper()
    return f"{prefix}-{ts}-{rnd}"

def sanitize_email(email):
    """Basic email sanitization."""
    if not email or "@" not in email or "." not in email.split("@")[-1]:
        return None
    return email.strip().lower()[:254]

def sanitize_phone(phone):
    """Normalize phone number for Africa's Talking."""
    digits = "".join(c for c in str(phone) if c.isdigit() or c == "+")
    if not digits.startswith("+"):
        digits = "+" + digits
    return digits if len(digits) >= 10 else None

def get_paypal_access_token():
    """Get PayPal OAuth access token."""
    if not PAYPAL_CLIENT_ID or not PAYPAL_CLIENT_SECRET:
        return None
    base = ("https://api-m.paypal.com"
            if PAYPAL_MODE == "live"
            else "https://api-m.sandbox.paypal.com")
    try:
        resp = requests.post(
            f"{base}/v1/oauth2/token",
            headers={"Accept": "application/json"},
            auth=(PAYPAL_CLIENT_ID, PAYPAL_CLIENT_SECRET),
            data={"grant_type": "client_credentials"},
            timeout=10
        )
        if resp.ok:
            return resp.json().get("access_token")
    except Exception as e:
        logger.error(f"PayPal token error: {e}")
    return None

def send_payment_notification_whatsapp(tx_ref, method, amount, name=""):
    """Notify Connect It team of a new payment via Twilio WhatsApp."""
    message = (
        f" NEW PAYMENT RECEIVED\n\n"
        f"Method: {method}\n"
        f"Amount: ${amount:.2f}\n"
        f"Reference: {tx_ref}\n"
        f"Name: {name or 'Anonymous'}\n"
        f"Time: {datetime.utcnow().strftime('%Y-%m-%d %H:%M UTC')}"
    )
    if TWILIO_AVAILABLE and TWILIO_ACCOUNT_SID and TWILIO_AUTH_TOKEN:
        try:
            from twilio.rest import Client as TwilioClient
            client = TwilioClient(TWILIO_ACCOUNT_SID, TWILIO_AUTH_TOKEN)
            client.messages.create(
                from_=f"whatsapp:{TWILIO_PHONE_NUMBER}",
                to=f"whatsapp:{CONNECTIT_WHATSAPP}",
                body=message
            )
        except Exception as e:
            logging.error(f"WhatsApp notification failed: {e}")
    else:
        logging.info(f"[PAYMENT NOTIFICATION]\n{message}")


