@app.route("/api/payments/stripe/create-session", methods=["POST"])
@csrf.exempt
def stripe_create_session():
    """Create a Stripe Checkout Session for card payments."""
    if not STRIPE_AVAILABLE:
        return connectit_json_response(
            {"error": "Stripe not installed on server. "
                      "Contact smile.again.tec@gmail.com"}, 503)
    if not STRIPE_SECRET_KEY:
        return connectit_json_response(
            {"error": "Stripe not configured. "
                      "Use EcoCash/Mukuru: +263772578565"}, 503)
    try:
        data        = request.get_json(force=True) or {}
        amount      = data.get("amount", 0)
        currency    = data.get("currency", "usd").lower()
        description = data.get("description", "Connect It Payment")
        cust_email  = sanitize_email(data.get("customer_email", ""))
        metadata    = data.get("metadata", {})
        success_url = data.get(
            "success_url",
            f"{request.host_url}?payment=success")
        cancel_url  = data.get(
            "cancel_url",
            f"{request.host_url}?payment=cancelled")

        if not validate_amount(amount / 100):
            return connectit_json_response({"error": "Invalid amount"}, 400)

        session_params = {
            "payment_method_types": ["card"],
            "line_items": [{
                "price_data": {
                    "currency": currency,
                    "unit_amount": int(amount),
                    "product_data": {
                        "name": "Connect It",
                        "description": description,
                        "images": []
                    }
                },
                "quantity": 1
            }],
            "mode": "payment",
            "success_url": success_url + "&session_id={CHECKOUT_SESSION_ID}",
            "cancel_url":  cancel_url,
            "metadata":    {**metadata, "platform": "connectit_ai"},
            "payment_intent_data": {
                "description": description,
                "receipt_email": cust_email or None
            }
        }
        if cust_email:
            session_params["customer_email"] = cust_email

        session = stripe.checkout.Session.create(**session_params)
        logging.info(f"[STRIPE] Session created: {session.id} for ${amount/100:.2f}")
        return connectit_json_response({
            "url":        session.url,
            "session_id": session.id
        })
    except stripe.error.StripeError as e:
        logging.error(f"[STRIPE ERROR] {e}")
        return connectit_json_response(
            {"error": str(e.user_message or e)}, 400)
    except Exception as e:
        logging.error(f"[STRIPE UNEXPECTED] {e}")
        return connectit_json_response({"error": str(e)}, 500)


# ════════════════════════════════════════════════════════════
# AUTO-REGISTER THE STRIPE WEBHOOK ENDPOINT
# Previously this needed a manual step: create a webhook endpoint in
# the Stripe Dashboard pointing at /api/payments/stripe/webhook, pick
# the events, copy the signing secret into STRIPE_WEBHOOK_SECRET. Two
# problems with that: (1) it's a step someone can forget, same failure
# mode the auto-migrate columns comment above describes; (2) every time
# a new event type gets handled here (most recently STAGE 303's
# account.updated, for Marketplace Connect payouts) the Dashboard
# subscription has to be updated too, by hand, or the new code never
# fires. This registers/repairs it automatically instead:
#   • If STRIPE_WEBHOOK_SECRET is already set via env, that's treated
#     as an explicit manual override and left alone.
#   • Else it looks for an existing endpoint (by URL) on the Stripe
#     account. If found, it's patched to include every event this app
#     handles (safe/idempotent) — but its secret can't be recovered
#     from Stripe after creation, so that case still logs a one-time
#     instruction to copy it from the Dashboard.
#   • If no endpoint exists yet, one is created via the API and its
#     freshly-issued signing secret is stored encrypted in
#     PlatformInfraSecret — no Dashboard visit needed at all.
# ════════════════════════════════════════════════════════════

STRIPE_WEBHOOK_EVENTS = [
    "checkout.session.completed",
    "payment_intent.payment_failed",
    "customer.subscription.created",
    "customer.subscription.updated",
    "customer.subscription.deleted",
    "account.updated",  # STAGE 303: Marketplace Connect payout status
    # STAGE 525: card-network chargebacks/disputes — see
    # PaymentChargeback below and the "chargeback_automation" flag.
    "charge.dispute.created",
    "charge.dispute.updated",
    "charge.dispute.funds_withdrawn",
    "charge.dispute.funds_reinstated",
    "charge.dispute.closed",
]


def _get_stripe_webhook_secret():
    """Effective webhook signing secret: env var wins if set, otherwise
    whatever _ensure_stripe_webhook_registered() auto-provisioned."""
    if STRIPE_WEBHOOK_SECRET:
        return STRIPE_WEBHOOK_SECRET
    row = PlatformInfraSecret.query.filter_by(key="stripe_webhook").first()
    if not row:
        return ""
    try:
        return decrypt_secret_blob(row.value_encrypted).get("secret", "")
    except Exception as e:
        logging.error(f"[STRIPE WEBHOOK SECRET DECRYPT ERROR] {e}")
        return ""


def _ensure_stripe_webhook_registered():
    if STRIPE_WEBHOOK_SECRET:
        logging.info("[STRIPE WEBHOOK] STRIPE_WEBHOOK_SECRET set via env — skipping auto-registration.")
        return
    if not (STRIPE_AVAILABLE and STRIPE_SECRET_KEY):
        return
    target_url = APP_BASE_URL.rstrip("/") + "/api/payments/stripe/webhook"
    try:
        import stripe as _stripe
        _stripe.api_key = STRIPE_SECRET_KEY
        existing = None
        for ep in _stripe.WebhookEndpoint.list(limit=100).auto_paging_iter():
            if ep.get("url") == target_url:
                existing = ep
                break
        if existing:
            missing = [e for e in STRIPE_WEBHOOK_EVENTS if e not in (existing.get("enabled_events") or [])]
            if missing:
                _stripe.WebhookEndpoint.modify(
                    existing["id"],
                    enabled_events=sorted(set((existing.get("enabled_events") or []) + STRIPE_WEBHOOK_EVENTS)),
                )
                logging.info(f"[STRIPE WEBHOOK] Added missing events to existing endpoint: {missing}")
            if not PlatformInfraSecret.query.filter_by(key="stripe_webhook").first():
                logging.warning(
                    "[STRIPE WEBHOOK] An endpoint already exists for this URL but its signing "
                    "secret isn't on file (Stripe only shows it once, at creation). Copy it from "
                    "the Dashboard → Developers → Webhooks and set STRIPE_WEBHOOK_SECRET, or "
                    "delete that endpoint and restart the app to have one auto-created with a "
                    "secret this app stores itself.")
            return
        created = _stripe.WebhookEndpoint.create(url=target_url, enabled_events=STRIPE_WEBHOOK_EVENTS)
        secret = created.get("secret")
        if secret:
            blob = encrypt_secret_blob({"secret": secret})
            row = PlatformInfraSecret(key="stripe_webhook", value_encrypted=blob)
            db.session.add(row)
            db.session.commit()
            logging.info(f"[STRIPE WEBHOOK] Auto-created endpoint {created['id']} and stored its signing secret.")
    except Exception as e:
        logging.error(f"[STRIPE WEBHOOK AUTO-REGISTER ERROR] {e}")


@app.route("/api/payments/stripe/webhook", methods=["POST"])
@csrf.exempt
def stripe_webhook():
    """Handle Stripe webhook events."""
    payload    = request.get_data(as_text=False)
    sig_header = request.headers.get("Stripe-Signature", "")
    try:
        effective_secret = _get_stripe_webhook_secret()
        if effective_secret:
            event = stripe.Webhook.construct_event(
                payload, sig_header, effective_secret)
        else:
            event = json.loads(payload)

        if event["type"] == "checkout.session.completed":
            session  = event["data"]["object"]
            _invoice_link_webhook_hint("stripe", session.get("id"))
            amount   = session.get("amount_total", 0) / 100
            tx_ref   = session.get("metadata", {}).get("ref", session["id"])
            customer = session.get("customer_email", "")
            logging.info(f"[STRIPE PAID] ${amount:.2f} | ref={tx_ref} | customer={customer}")
            # Subscription-mode Checkout (STAGE 204 billing portal) has no
            # "ref" and doesn't want a payment-received WhatsApp ping —
            # only route it through the subscription sync below instead.
            if session.get("mode") == "subscription":
                session_kind = (session.get("metadata") or {}).get("kind")
                try:
                    if session_kind == "user_subscription":
                        _user_subscription_handle_event(event)
                    else:
                        _billing_handle_subscription_event(event)
                except Exception as e:
                    logging.error(f"[BILLING WEBHOOK ERROR] {e}")
            else:
                send_payment_notification_whatsapp(tx_ref, "Stripe Card", amount, customer)
                metadata = session.get("metadata", {}) or {}
                # STAGE 310: shipping_address_collection on the Checkout
                # Session (see _create_product_order_checkout/cart_checkout)
                # returns the buyer's delivery address here — captured
                # once per session, applied to every order it funded.
                shipping_details = session.get("shipping_details") or session.get("customer_details") or {}
                shipping_addr = shipping_details.get("address") or {}
                shipping_address = None
                if shipping_addr.get("line1"):
                    shipping_address = {
                        "name": shipping_details.get("name"), "phone": session.get("customer_details", {}).get("phone"),
                        "street": shipping_addr.get("line1"), "street2": shipping_addr.get("line2"),
                        "city": shipping_addr.get("city"), "postal_code": shipping_addr.get("postal_code"),
                        "country_code": shipping_addr.get("country"), "state": shipping_addr.get("state"),
                    }
                if metadata.get("kind") == "marketplace_product":
                    try:
                        _handle_marketplace_order_paid(metadata.get("order_id"), session.get("payment_intent"), shipping_address)
                    except Exception as e:
                        logging.error(f"[MARKETPLACE ORDER WEBHOOK ERROR] {e}")
                    if metadata.get("bnpl_plan") == "pay_in_4":
                        # STAGE 524: order is now marked paid in full
                        # above (normal Trade Assurance hold) — this
                        # builds the installment schedule from the
                        # deposit session that was actually charged.
                        try:
                            _bnpl_finalize_plan_from_session(metadata.get("order_id"), session)
                        except Exception as e:
                            logging.error(f"[BNPL FINALIZE WEBHOOK ERROR] {e}")
                elif metadata.get("kind") == "marketplace_cart":
                    order_ids = (metadata.get("order_ids") or "").split(",")
                    for oid in order_ids:
                        if not oid.strip():
                            continue
                        try:
                            _handle_marketplace_order_paid(oid.strip(), session.get("payment_intent"), shipping_address)
                        except Exception as e:
                            logging.error(f"[MARKETPLACE CART WEBHOOK ERROR] order={oid}: {e}")
                elif metadata.get("kind") == "gift_card_purchase":
                    # STAGE 328: buyer's card cleared — activate the code
                    # so it can actually be redeemed, and email it to the
                    # recipient (or the purchaser, if it's a self-buy).
                    try:
                        gift_card = GiftCard.query.get(int(metadata.get("gift_card_id")))
                        if gift_card and gift_card.status == "pending":
                            gift_card.status = "active"
                            db.session.commit()
                            _send_gift_card_email(gift_card)
                    except Exception as e:
                        logging.error(f"[GIFT CARD WEBHOOK ERROR] {e}")
                elif metadata.get("kind") == "carbon_offset_purchase":
                    # STAGE 330: mark the voluntary contribution as paid.
                    try:
                        contribution = CarbonOffsetContribution.query.get(int(metadata.get("contribution_id")))
                        if contribution and contribution.status == "pending":
                            contribution.status = "paid"
                            db.session.commit()
                    except Exception as e:
                        logging.error(f"[CARBON OFFSET WEBHOOK ERROR] {e}")
                elif metadata.get("kind") == "sponsored_listing_purchase":
                    # STAGE 337: seller's card cleared — start the boost window now.
                    try:
                        listing = SponsoredListing.query.get(int(metadata.get("sponsored_listing_id")))
                        if listing and listing.status == "pending_payment":
                            listing.status = "active"
                            listing.start_at = datetime.utcnow()
                            listing.end_at = listing.start_at + timedelta(days=listing.days)
                            db.session.commit()
                    except Exception as e:
                        logging.error(f"[SPONSORED LISTING WEBHOOK ERROR] {e}")

        elif event["type"] == "account.updated":
            # STAGE 303: Stripe Connect onboarding status for a marketplace
            # seller changed (e.g. they finished KYC and payouts_enabled
            # flipped to true) — keep our local flags in sync so
            # product_buy() knows it can route straight to them.
            acct = event["data"]["object"]
            try:
                seller = UserAccount.query.filter_by(
                    stripe_connect_account_id=acct.get("id")).first()
                if seller:
                    seller.stripe_connect_charges_enabled = bool(acct.get("charges_enabled"))
                    seller.stripe_connect_payouts_enabled = bool(acct.get("payouts_enabled"))
                    db.session.commit()
            except Exception as e:
                logging.error(f"[CONNECT WEBHOOK ERROR] {e}")

        elif event["type"] == "payment_intent.payment_failed":
            pi = event["data"]["object"]
            logging.warning(
                f"[STRIPE FAILED] {pi.get('last_payment_error', {}).get('message')}")

        elif event["type"] in ("customer.subscription.updated", "customer.subscription.created",
                                "customer.subscription.deleted"):
            # Route to the individual-user handler or the org/workspace
            # handler (STAGE 204) depending on which one created this
            # subscription, so Organization.plan and UserAccount.plan
            # each only get touched by their own billing flow.
            sub_kind = ((event["data"]["object"].get("metadata")) or {}).get("kind")
            try:
                if sub_kind == "user_subscription":
                    _user_subscription_handle_event(event)
                else:
                    _billing_handle_subscription_event(event)
            except Exception as e:
                logging.error(f"[BILLING WEBHOOK ERROR] {e}")

        elif event["type"].startswith("charge.dispute."):
            # STAGE 525: CARD-NETWORK CHARGEBACK AUTOMATION — a real
            # dispute filed with the buyer's bank/card issuer, distinct
            # from the buyer<->seller EscrowDispute mediation flow above
            # (that one is a platform-mediated conversation; this one is
            # binding, deadline-driven, and decided by the card network,
            # not by Connect It). See _chargeback_handle_webhook_event.
            try:
                _chargeback_handle_webhook_event(event)
            except Exception as e:
                logging.error(f"[CHARGEBACK WEBHOOK ERROR] {e}")

        return connectit_json_response({"received": True})
    except Exception as e:
        logging.error(f"[STRIPE WEBHOOK ERROR] {e}")
        return connectit_json_response({"error": str(e)}, 500)


@app.route("/api/payments/stripe/verify/<session_id>", methods=["GET"])
@csrf.exempt
def stripe_verify_session(session_id):
    """Verify a completed Stripe session."""
    if not STRIPE_AVAILABLE or not STRIPE_SECRET_KEY:
        return connectit_json_response({"error": "Stripe not configured"}, 503)
    try:
        session = stripe.checkout.Session.retrieve(session_id)
        return connectit_json_response({
            "status":         session.payment_status,
            "amount":         session.amount_total / 100,
            "currency":       session.currency.upper(),
            "customer_email": session.customer_email,
            "paid":           session.payment_status == "paid"
        })
    except Exception as e:
        return connectit_json_response({"error": str(e)}, 400)


