# FLUTTERWAVE ROUTES
# ════════════════════════════════════════════════════════════

@app.route("/api/payments/flutterwave/initiate", methods=["POST"])
@csrf.exempt
def flutterwave_initiate():
    """Initiate a Flutterwave payment."""
    if not FLUTTERWAVE_SECRET_KEY:
        return connectit_json_response({
            "error": "Flutterwave not configured. Use EcoCash/Mukuru +263772578565",
            "fallback": "ecocash"
        }, 503)
    try:
        data         = request.get_json(force=True) or {}
        amount       = float(data.get("amount", 0))
        currency     = data.get("currency", "USD").upper()
        customer     = data.get("customer", {})
        tx_ref       = data.get("tx_ref") or generate_tx_ref("FLW")
        redirect_url = data.get("redirect_url", f"{request.host_url}?payment=success")
        meta         = data.get("meta", {})

        if not validate_amount(amount):
            return connectit_json_response({"error": "Invalid amount"}, 400)
        if not customer.get("email"):
            return connectit_json_response({"error": "Customer email required"}, 400)

        payload = {
            "tx_ref":       tx_ref,
            "amount":       amount,
            "currency":     currency,
            "redirect_url": redirect_url,
            "payment_options": "card,mobilemoneyghana,mpesa,ecocash,account,barter,nqr",
            "customer": {
                "email":        customer.get("email"),
                "name":         customer.get("name", "Connect It User"),
                "phonenumber":  customer.get("phone", "")
            },
            "customizations": {
                "title":       "Connect It",
                "description": meta.get("description", "Connect It Payment"),
                "logo": "https://connectit.ai/icon.png"
            },
            "meta": {**meta, "platform": "connectit_ai", "ref": tx_ref}
        }
        resp = requests.post(
            "https://api.flutterwave.com/v3/payments",
            headers={
                "Authorization": f"Bearer {FLUTTERWAVE_SECRET_KEY}",
                "Content-Type":  "application/json"
            },
            json=payload,
            timeout=15
        )
        fw_data = resp.json()
        if resp.ok and fw_data.get("status") == "success":
            logging.info(f"[FLUTTERWAVE] Initiated: {tx_ref} | {currency} {amount:.2f}")
            return connectit_json_response({
                "link":   fw_data["data"]["link"],
                "tx_ref": tx_ref
            })
        else:
            raise ValueError(fw_data.get("message", "Flutterwave error"))
    except Exception as e:
        logging.error(f"[FLUTTERWAVE ERROR] {e}")
        return connectit_json_response({"error": str(e)}, 500)


@app.route("/api/payments/flutterwave/webhook", methods=["POST"])
@csrf.exempt
def flutterwave_webhook():
    """Handle Flutterwave webhook events."""
    secret_hash = os.environ.get("FLUTTERWAVE_WEBHOOK_HASH", "")
    verif_hash  = request.headers.get("verif-hash", "")
    if secret_hash and verif_hash != secret_hash:
        return connectit_json_response({"error": "Invalid hash"}, 401)
    try:
        data  = request.get_json(force=True) or {}
        event = data.get("event", "")
        if event == "charge.completed":
            tx_data = data.get("data", {})
            if tx_data.get("status") == "successful":
                amount   = tx_data.get("amount", 0)
                currency = tx_data.get("currency", "USD")
                tx_ref   = tx_data.get("tx_ref", "")
                _invoice_link_webhook_hint("flutterwave", tx_ref)
                customer = tx_data.get("customer", {})
                logging.info(
                    f"[FLUTTERWAVE PAID] {currency} {amount} | "
                    f"ref={tx_ref} | {customer.get('email')}")
                send_payment_notification_whatsapp(
                    tx_ref, "Flutterwave", amount,
                    customer.get("name", customer.get("email", "")))
        return connectit_json_response({"status": "received"})
    except Exception as e:
        logging.error(f"[FLUTTERWAVE WEBHOOK ERROR] {e}")
        return connectit_json_response({"error": str(e)}, 500)


@app.route("/api/payments/flutterwave/verify/<tx_ref>", methods=["GET"])
@csrf.exempt
def flutterwave_verify(tx_ref):
    """Verify a Flutterwave transaction by tx_ref."""
    if not FLUTTERWAVE_SECRET_KEY:
        return connectit_json_response({"error": "Not configured"}, 503)
    try:
        resp = requests.get(
            f"https://api.flutterwave.com/v3/transactions/verify_by_reference?tx_ref={tx_ref}",
            headers={"Authorization": f"Bearer {FLUTTERWAVE_SECRET_KEY}"},
            timeout=10
        )
        data = resp.json()
        if data.get("status") == "success":
            tx = data["data"]
            return connectit_json_response({
                "verified": tx.get("status") == "successful",
                "amount":   tx.get("amount"),
                "currency": tx.get("currency"),
                "email":    tx.get("customer", {}).get("email")
            })
        return connectit_json_response(
            {"error": data.get("message", "Verification failed")}, 400)
    except Exception as e:
        return connectit_json_response({"error": str(e)}, 500)


