# PAYSTACK ROUTES — BYOK: a business user's own Paystack secret/public
# key wins over the platform's shared key. Best for Nigeria/Ghana.
# ════════════════════════════════════════════════════════════

def _paystack_key_for_user(user_id):
    """Return (secret_key, public_key) — user's own BYOK Paystack keys
    if configured, otherwise the platform's shared keys."""
    secret = get_effective_credential(user_id, "paystack", "secret_key", PAYSTACK_SECRET_KEY)
    public = get_effective_credential(user_id, "paystack", "public_key", PAYSTACK_PUBLIC_KEY)
    return secret, public


@app.route("/api/payments/paystack/initialize", methods=["POST"])
@csrf.exempt
def paystack_initialize():
    """Initialize a Paystack transaction and return the checkout link."""
    current_user = _get_current_user()
    current_uid  = current_user.get("id") if current_user else None
    secret_key, _ = _paystack_key_for_user(current_uid)
    if not secret_key:
        return connectit_json_response({"error": "Paystack not configured"}, 503)
    try:
        data     = request.get_json(force=True) or {}
        amount   = float(data.get("amount", 0))
        currency = data.get("currency", "NGN").upper()
        email    = sanitize_email(data.get("email", ""))
        tx_ref   = data.get("tx_ref") or generate_tx_ref("PSK")
        callback = data.get("callback_url", f"{request.host_url}?payment=success")

        if not validate_amount(amount):
            return connectit_json_response({"error": "Invalid amount"}, 400)
        if not email:
            return connectit_json_response({"error": "Valid customer email required"}, 400)

        # Paystack expects amount in the smallest currency unit (kobo/cents)
        payload = {
            "email":        email,
            "amount":       int(round(amount * 100)),
            "currency":     currency,
            "reference":    tx_ref,
            "callback_url": callback,
            "metadata":     data.get("meta", {}),
        }
        resp = requests.post(
            "https://api.paystack.co/transaction/initialize",
            headers={
                "Authorization": f"Bearer {secret_key}",
                "Content-Type":  "application/json",
            },
            json=payload, timeout=15
        )
        pk_data = resp.json()
        if resp.ok and pk_data.get("status"):
            logging.info(f"[PAYSTACK] Initiated: {tx_ref} | {currency} {amount:.2f}")
            return connectit_json_response({
                "link":   pk_data["data"]["authorization_url"],
                "tx_ref": tx_ref,
            })
        raise ValueError(pk_data.get("message", "Paystack error"))
    except Exception as e:
        logging.error(f"[PAYSTACK ERROR] {e}")
        return connectit_json_response({"error": str(e)}, 500)


