@app.route("/api/whatsapp-cloud/business-profile", methods=["POST"])
@csrf.exempt
def whatsapp_cloud_update_business_profile():
    """Update the connected WhatsApp Business Profile fields."""
    if not _csrf_ok():
        return connectit_json_response({"error": "CSRF token invalid or missing."}, 403)
    current_user = _get_current_user()
    if not current_user:
        return connectit_json_response({"error": "Login required"}, 401)
    creds = _whatsapp_cloud_creds_for_user(current_user["id"])
    if not creds["phone_number_id"] or not creds["access_token"]:
        return connectit_json_response({"error": "WhatsApp Cloud API is not configured."}, 503)

    data = request.get_json(force=True) or {}
    allowed = {"about", "address", "description", "email", "vertical"}
    payload = {k: (data.get(k) or "").strip() for k in allowed if k in data}
    websites = data.get("websites")
    if isinstance(websites, list):
        payload["websites"] = [w.strip() for w in websites if isinstance(w, str) and w.strip()][:2]
    if not payload:
        return connectit_json_response({"error": "No fields to update."}, 400)
    payload["messaging_product"] = "whatsapp"

    try:
        resp = requests.post(
            f"https://graph.facebook.com/{WHATSAPP_CLOUD_API_VERSION}/{creds['phone_number_id']}/whatsapp_business_profile",
            headers={"Authorization": f"Bearer {creds['access_token']}", "Content-Type": "application/json"},
            json=payload, timeout=15,
        )
        body = resp.json()
        if resp.status_code >= 400:
            return connectit_json_response(
                {"error": (body.get("error") or {}).get("message", "Could not update business profile.")}, 502)
        return connectit_json_response({"ok": True})
    except Exception as e:
        logging.error(f"[WA BUSINESS PROFILE UPDATE ERROR] {e}")
        return connectit_json_response({"error": str(e)}, 500)


@app.route("/api/whatsapp-cloud/business-profile/photo", methods=["POST"])
@csrf.exempt
def whatsapp_cloud_update_business_profile_photo():
    """Upload a new WhatsApp Business Profile picture. Meta requires this as
    a two-step Resumable Upload: (1) open an upload session against the
    Meta app tied to the access token and get a session ID, (2) PUT the raw
    image bytes to that session and get back an upload 'handle', which is
    then what whatsapp_business_profile accepts as profile_picture_handle
    (NOT a plain URL)."""
    if not _csrf_ok():
        return connectit_json_response({"error": "CSRF token invalid or missing."}, 403)
    current_user = _get_current_user()
    if not current_user:
        return connectit_json_response({"error": "Login required"}, 401)
    creds = _whatsapp_cloud_creds_for_user(current_user["id"])
    if not creds["phone_number_id"] or not creds["access_token"]:
        return connectit_json_response({"error": "WhatsApp Cloud API is not configured."}, 503)

    meta_app_id = get_effective_credential(
        current_user["id"], "whatsapp_cloud", "meta_app_id", os.environ.get("META_APP_ID", ""))
    if not meta_app_id:
        return connectit_json_response(
            {"error": "Add your Meta App ID under WhatsApp Cloud API settings first — profile photo uploads need it."}, 503)

    if "file" not in request.files:
        return connectit_json_response({"error": "no_file"}, 400)
    f = request.files["file"]
    if f.mimetype not in ("image/jpeg", "image/png"):
        return connectit_json_response({"error": "Profile photo must be a JPEG or PNG image."}, 400)
    image_bytes = f.read()
    if len(image_bytes) > 5 * 1024 * 1024:
        return connectit_json_response({"error": "Image must be under 5MB."}, 400)

    try:
        # Step 1: open a resumable upload session.
        session_resp = requests.post(
            f"https://graph.facebook.com/{WHATSAPP_CLOUD_API_VERSION}/{meta_app_id}/uploads",
            params={
                "file_length": len(image_bytes),
                "file_type": f.mimetype,
                "access_token": creds["access_token"],
            },
            timeout=15,
        )
        session_body = session_resp.json()
        if session_resp.status_code >= 400:
            return connectit_json_response(
                {"error": (session_body.get("error") or {}).get("message", "Could not open upload session.")}, 502)
        upload_session_id = session_body.get("id", "")

        # Step 2: PUT the raw bytes to that session and get back a handle.
        upload_resp = requests.post(
            f"https://graph.facebook.com/{WHATSAPP_CLOUD_API_VERSION}/{upload_session_id}",
            headers={
                "Authorization": f"OAuth {creds['access_token']}",
                "file_offset": "0",
            },
            data=image_bytes, timeout=30,
        )
        upload_body = upload_resp.json()
        if upload_resp.status_code >= 400:
            return connectit_json_response(
                {"error": (upload_body.get("error") or {}).get("message", "Could not upload image.")}, 502)
        handle = upload_body.get("h", "")
        if not handle:
            return connectit_json_response({"error": "Upload did not return a usable image handle."}, 502)

        # Step 3: apply the handle to the business profile.
        apply_resp = requests.post(
            f"https://graph.facebook.com/{WHATSAPP_CLOUD_API_VERSION}/{creds['phone_number_id']}/whatsapp_business_profile",
            headers={"Authorization": f"Bearer {creds['access_token']}", "Content-Type": "application/json"},
            json={"messaging_product": "whatsapp", "profile_picture_handle": handle},
            timeout=15,
        )
        apply_body = apply_resp.json()
        if apply_resp.status_code >= 400:
            return connectit_json_response(
                {"error": (apply_body.get("error") or {}).get("message", "Could not set profile picture.")}, 502)
        return connectit_json_response({"ok": True})
    except Exception as e:
        logging.error(f"[WA BUSINESS PROFILE PHOTO ERROR] {e}")
        return connectit_json_response({"error": str(e)}, 500)


