@app.route("/api/whatsapp-cloud/send-template", methods=["POST"])
@csrf.exempt
def whatsapp_cloud_send_template():
    """Send a WhatsApp template (HSM) message — works anytime, not just
    inside the 24-hour customer-initiated session window."""
    current_user = _get_current_user()
    if not current_user:
        return connectit_json_response({"error": "Login required"}, 401)
    data = request.get_json(force=True) or {}
    to = sanitize_phone(data.get("to", ""))
