# ════════════════════════════════════════════════════════════
# WHATSAPP TEMPLATE CREATION & SUBMISSION — until now this platform could
# only READ templates a business had already built by hand in Meta's
# Business Manager (list_whatsapp_templates above). This lets a business
# author a template (header/body/footer/buttons + sample values) right
# here and submit it straight to Meta for review via the Graph API.
# ════════════════════════════════════════════════════════════

def _whatsapp_waba_creds_or_error(current_user):
    creds = _whatsapp_cloud_creds_for_user(current_user["id"])
    if not creds["access_token"] or not creds["business_account_id"]:
        return None, connectit_json_response(
            {"error": "WhatsApp Cloud API is not configured (need a Business Account / WABA ID)."}, 503)
    return creds, None


@app.route("/api/whatsapp-cloud/templates", methods=["POST"])
@csrf.exempt
def whatsapp_cloud_create_template():
    """Creates and submits a new WhatsApp message template (HSM) to Meta
    for review. `components` follows Meta's template component schema
    directly, e.g.:
      [{"type": "HEADER", "format": "TEXT", "text": "Order #{{1}}"},
       {"type": "BODY", "text": "Hi {{1}}, your order is on its way!",
        "example": {"body_text": [["Tendai"]]}},
       {"type": "FOOTER", "text": "Connect It"},
       {"type": "BUTTONS", "buttons": [{"type": "QUICK_REPLY", "text": "Track order"}]}]
    Review typically takes minutes to a day; check status via
    GET /api/whatsapp-cloud/templates (already returns each template's
    status: PENDING, APPROVED, REJECTED)."""
    current_user = _get_current_user()
    if not current_user:
        return connectit_json_response({"error": "Login required"}, 401)
    creds, err = _whatsapp_waba_creds_or_error(current_user)
    if err:
        return err

    data = request.get_json(force=True) or {}
    name = (data.get("name") or "").strip().lower()
    name = re.sub(r"[^a-z0-9_]", "_", name)
    category = (data.get("category") or "").strip().upper()
    language = (data.get("language") or "en_US").strip()
    components = data.get("components") or []

    if not name:
        return connectit_json_response({"error": "Template name is required (letters, numbers, underscores only)."}, 400)
    if category not in ("AUTHENTICATION", "MARKETING", "UTILITY"):
        return connectit_json_response({"error": "category must be one of AUTHENTICATION, MARKETING, UTILITY."}, 400)
    if not isinstance(components, list) or not components:
        return connectit_json_response({"error": "components (a list with at least a BODY component) is required."}, 400)

    try:
        resp = requests.post(
            f"https://graph.facebook.com/{WHATSAPP_CLOUD_API_VERSION}/{creds['business_account_id']}/message_templates",
            headers={"Authorization": f"Bearer {creds['access_token']}", "Content-Type": "application/json"},
            json={"name": name, "category": category, "language": language, "components": components},
            timeout=20,
        )
        body = resp.json()
        if resp.status_code >= 400:
            return connectit_json_response(
                {"error": (body.get("error") or {}).get("message", "Template submission was rejected by Meta.")}, 502)
        logging.info(f"[WA TEMPLATE CREATE] user={current_user['id']} name={name} -> id={body.get('id')}")
        return connectit_json_response({
            "submitted": True, "template_id": body.get("id"),
            "status": body.get("status", "PENDING"), "category": body.get("category", category),
        })
    except Exception as e:
        logging.error(f"[WA TEMPLATE CREATE ERROR] {e}")
        return connectit_json_response({"error": str(e)}, 500)


@app.route("/api/whatsapp-cloud/templates/<path:template_name>", methods=["DELETE"])
@csrf.exempt
def whatsapp_cloud_delete_template(template_name):
    """Deletes a template by name (all language variants of that name)."""
    current_user = _get_current_user()
    if not current_user:
        return connectit_json_response({"error": "Login required"}, 401)
    creds, err = _whatsapp_waba_creds_or_error(current_user)
    if err:
        return err
    try:
        resp = requests.delete(
            f"https://graph.facebook.com/{WHATSAPP_CLOUD_API_VERSION}/{creds['business_account_id']}/message_templates",
            headers={"Authorization": f"Bearer {creds['access_token']}"},
            params={"name": template_name},
            timeout=15,
        )
        body = resp.json()
        if resp.status_code >= 400:
            return connectit_json_response(
                {"error": (body.get("error") or {}).get("message", "Could not delete template.")}, 502)
        logging.info(f"[WA TEMPLATE DELETE] user={current_user['id']} name={template_name}")
        return connectit_json_response({"deleted": True})
    except Exception as e:
        logging.error(f"[WA TEMPLATE DELETE ERROR] {e}")
        return connectit_json_response({"error": str(e)}, 500)


@app.route("/api/whatsapp-cloud/templates/<path:template_name>/edit", methods=["POST"])
@csrf.exempt
def whatsapp_cloud_edit_template(template_name):
    """Edits an existing (usually already-APPROVED) template's components.
    Meta re-reviews the template after an edit; edits are rate-limited to
    a small number per template per day on Meta's side. Needs the
    template's numeric id, not just its name -- pass it as template_id."""
    current_user = _get_current_user()
    if not current_user:
        return connectit_json_response({"error": "Login required"}, 401)
    creds, err = _whatsapp_waba_creds_or_error(current_user)
    if err:
        return err
    data = request.get_json(force=True) or {}
    template_id = (data.get("template_id") or "").strip()
    components = data.get("components") or []
    category = (data.get("category") or "").strip().upper()
    if not template_id:
        return connectit_json_response({"error": "template_id (Meta's numeric id for this template) is required."}, 400)
    payload = {}
    if components:
        payload["components"] = components
    if category:
        payload["category"] = category
    if not payload:
        return connectit_json_response({"error": "Nothing to update -- provide components and/or category."}, 400)
    try:
        resp = requests.post(
            f"https://graph.facebook.com/{WHATSAPP_CLOUD_API_VERSION}/{template_id}",
            headers={"Authorization": f"Bearer {creds['access_token']}", "Content-Type": "application/json"},
            json=payload, timeout=20,
        )
        body = resp.json()
        if resp.status_code >= 400:
            return connectit_json_response(
                {"error": (body.get("error") or {}).get("message", "Could not edit template.")}, 502)
        logging.info(f"[WA TEMPLATE EDIT] user={current_user['id']} template_id={template_id}")
        return connectit_json_response({"updated": True})
    except Exception as e:
        logging.error(f"[WA TEMPLATE EDIT ERROR] {e}")
        return connectit_json_response({"error": str(e)}, 500)


# ════════════════════════════════════════════════════════════
# WHATSAPP BLOCK / UNBLOCK CONTACTS — lets a business stop a specific
# customer's messages from reaching them (and from being billed as a
# conversation) without deleting any message history. Uses Meta's
# block_users Graph API endpoint on the phone number resource.
# ════════════════════════════════════════════════════════════

@app.route("/api/whatsapp-cloud/blocked-contacts", methods=["GET"])
def whatsapp_cloud_list_blocked_contacts():
    """Lists WhatsApp users currently blocked on this business's number."""
    current_user = _get_current_user()
    if not current_user:
        return connectit_json_response({"error": "Login required"}, 401)
    creds = _whatsapp_cloud_creds_for_user(current_user["id"])
    if not creds["access_token"] or not creds["phone_number_id"]:
        return connectit_json_response({"error": "WhatsApp Cloud API is not configured."}, 503)
    try:
        resp = requests.get(
            f"https://graph.facebook.com/{WHATSAPP_CLOUD_API_VERSION}/{creds['phone_number_id']}/block_users",
            headers={"Authorization": f"Bearer {creds['access_token']}"},
            params={"limit": 100},
            timeout=15,
        )
        body = resp.json()
        if resp.status_code >= 400:
            return connectit_json_response(
                {"error": (body.get("error") or {}).get("message", "Could not list blocked contacts.")}, 502)
        return connectit_json_response({"blocked": body.get("block_users", body.get("data", []))})
    except Exception as e:
        logging.error(f"[WA BLOCK LIST ERROR] {e}")
        return connectit_json_response({"error": str(e)}, 500)


def _whatsapp_block_payload(numbers):
    return {"messaging_product": "whatsapp", "block_users": [{"user": re.sub(r"\D", "", n)} for n in numbers if n]}


@app.route("/api/whatsapp-cloud/blocked-contacts/block", methods=["POST"])
@csrf.exempt
def whatsapp_cloud_block_contacts():
    """Blocks one or more customer numbers so their messages stop arriving."""
    current_user = _get_current_user()
    if not current_user:
        return connectit_json_response({"error": "Login required"}, 401)
    creds = _whatsapp_cloud_creds_for_user(current_user["id"])
    if not creds["access_token"] or not creds["phone_number_id"]:
        return connectit_json_response({"error": "WhatsApp Cloud API is not configured."}, 503)
    data = request.get_json(force=True) or {}
    numbers = data.get("numbers")
    if numbers is None:
        single = (data.get("number") or "").strip()
        numbers = [single] if single else []
    if not numbers:
        return connectit_json_response({"error": "At least one number is required."}, 400)
    try:
        resp = requests.post(
            f"https://graph.facebook.com/{WHATSAPP_CLOUD_API_VERSION}/{creds['phone_number_id']}/block_users",
            headers={"Authorization": f"Bearer {creds['access_token']}", "Content-Type": "application/json"},
            json=_whatsapp_block_payload(numbers),
            timeout=15,
        )
        body = resp.json()
        if resp.status_code >= 400:
            return connectit_json_response(
                {"error": (body.get("error") or {}).get("message", "Could not block contact(s).")}, 502)
        logging.info(f"[WA BLOCK] user={current_user['id']} blocked={numbers}")
        return connectit_json_response({"blocked": True, "result": body})
    except Exception as e:
        logging.error(f"[WA BLOCK ERROR] {e}")
        return connectit_json_response({"error": str(e)}, 500)


@app.route("/api/whatsapp-cloud/blocked-contacts/unblock", methods=["POST"])
@csrf.exempt
def whatsapp_cloud_unblock_contacts():
    """Unblocks one or more previously-blocked customer numbers."""
    current_user = _get_current_user()
    if not current_user:
        return connectit_json_response({"error": "Login required"}, 401)
    creds = _whatsapp_cloud_creds_for_user(current_user["id"])
    if not creds["access_token"] or not creds["phone_number_id"]:
        return connectit_json_response({"error": "WhatsApp Cloud API is not configured."}, 503)
    data = request.get_json(force=True) or {}
    numbers = data.get("numbers")
    if numbers is None:
        single = (data.get("number") or "").strip()
        numbers = [single] if single else []
    if not numbers:
        return connectit_json_response({"error": "At least one number is required."}, 400)
    try:
        # requests.delete supports a JSON body via the `json=` kwarg same as post/put.
        resp = requests.delete(
            f"https://graph.facebook.com/{WHATSAPP_CLOUD_API_VERSION}/{creds['phone_number_id']}/block_users",
            headers={"Authorization": f"Bearer {creds['access_token']}", "Content-Type": "application/json"},
            json=_whatsapp_block_payload(numbers),
            timeout=15,
        )
        body = resp.json()
        if resp.status_code >= 400:
            return connectit_json_response(
                {"error": (body.get("error") or {}).get("message", "Could not unblock contact(s).")}, 502)
        logging.info(f"[WA UNBLOCK] user={current_user['id']} unblocked={numbers}")
        return connectit_json_response({"unblocked": True, "result": body})
    except Exception as e:
        logging.error(f"[WA UNBLOCK ERROR] {e}")
        return connectit_json_response({"error": str(e)}, 500)


# ════════════════════════════════════════════════════════════
# WHATSAPP WEBHOOK FIELD SUBSCRIPTIONS — which change types this
# platform's Meta App receives (messages, message_template_status_update,
# account_alerts, phone_number_quality_update, etc). This is configured
# at the App level (Meta App Dashboard → Webhooks) rather than per-WABA,
# so calls here use an App Access Token (app_id|app_secret), not a
# user's BYOK WhatsApp access token.
# ════════════════════════════════════════════════════════════

WHATSAPP_WEBHOOK_FIELDS = [
    "messages", "message_template_status_update", "message_template_quality_update",
    "phone_number_quality_update", "phone_number_name_update", "account_update",
    "account_alerts", "business_capability_update", "template_category_update",
    "security", "smb_message_echoes", "smb_app_state_sync", "user_preferences",
    "flows", "calls",
]


def _meta_app_access_token_or_error():
    if not META_APP_ID or not META_APP_SECRET:
        return None, connectit_json_response(
            {"error": "Webhook field configuration needs META_APP_ID and META_APP_SECRET set on this platform."}, 503)
    return f"{META_APP_ID}|{META_APP_SECRET}", None


@app.route("/api/whatsapp-cloud/webhook-fields", methods=["GET"])
def whatsapp_cloud_webhook_fields_list():
    """Lists which webhook fields this platform's Meta App is currently
    subscribed to for each webhook object type (whatsapp_business_account,
    whatsapp_business_management, etc.)."""
    current_user = _get_current_user()
    if not current_user:
        return connectit_json_response({"error": "Login required"}, 401)
    app_token, err = _meta_app_access_token_or_error()
    if err:
        return err
    try:
        resp = requests.get(
            f"https://graph.facebook.com/{WHATSAPP_CLOUD_API_VERSION}/{META_APP_ID}/subscriptions",
            params={"access_token": app_token},
            timeout=15,
        )
        body = resp.json()
        if resp.status_code >= 400:
            return connectit_json_response(
                {"error": (body.get("error") or {}).get("message", "Could not list webhook subscriptions.")}, 502)
        return connectit_json_response({
            "subscriptions": body.get("data", []),
            "available_fields": WHATSAPP_WEBHOOK_FIELDS,
        })
    except Exception as e:
        logging.error(f"[WA WEBHOOK FIELDS LIST ERROR] {e}")
        return connectit_json_response({"error": str(e)}, 500)


@app.route("/api/whatsapp-cloud/webhook-fields", methods=["POST"])
@csrf.exempt
def whatsapp_cloud_webhook_fields_update():
    """Updates which fields the whatsapp_business_account webhook object
    subscribes to. `fields` is a list drawn from WHATSAPP_WEBHOOK_FIELDS;
    this REPLACES the full field set for that object (matches Meta's own
    App Dashboard behavior), so pass every field that should stay active."""
    current_user = _get_current_user()
    if not current_user:
        return connectit_json_response({"error": "Login required"}, 401)
    app_token, err = _meta_app_access_token_or_error()
    if err:
        return err
    data = request.get_json(force=True) or {}
    fields = [f for f in (data.get("fields") or []) if f in WHATSAPP_WEBHOOK_FIELDS]
    obj = (data.get("object") or "whatsapp_business_account").strip()
    if not fields:
        return connectit_json_response({"error": "At least one valid field is required."}, 400)
    callback_url = url_for("whatsapp_cloud_webhook_receive", _external=True)
    try:
        resp = requests.post(
            f"https://graph.facebook.com/{WHATSAPP_CLOUD_API_VERSION}/{META_APP_ID}/subscriptions",
            data={
                "object": obj,
                "callback_url": callback_url,
                "fields": ",".join(fields),
                "verify_token": WHATSAPP_CLOUD_VERIFY_TOKEN,
                "access_token": app_token,
            },
            timeout=15,
        )
        body = resp.json()
        if resp.status_code >= 400:
            return connectit_json_response(
                {"error": (body.get("error") or {}).get("message", "Could not update webhook subscription.")}, 502)
        logging.info(f"[WA WEBHOOK FIELDS] user={current_user['id']} object={obj} fields={fields}")
        return connectit_json_response({"updated": True, "object": obj, "fields": fields})
    except Exception as e:
        logging.error(f"[WA WEBHOOK FIELDS UPDATE ERROR] {e}")
        return connectit_json_response({"error": str(e)}, 500)


# ════════════════════════════════════════════════════════════
# WHATSAPP CONVERSATION-BASED ANALYTICS — Meta's per-WABA `analytics`
# (message counts/state) and `conversation_analytics` (billable
# conversation counts, broken down by category/type/cost) Graph API
# fields, surfaced as their own endpoints instead of requiring a
# business to dig through Meta's Business Manager UI.
# ════════════════════════════════════════════════════════════

@app.route("/api/whatsapp-cloud/analytics/messages", methods=["GET"])
def whatsapp_cloud_message_analytics():
    """Sent/delivered message counts over a time range, from Meta's WABA
    `analytics` field. start/end are unix timestamps (seconds); granularity
    is one of HALF_HOUR, DAY, MONTH."""
    current_user = _get_current_user()
    if not current_user:
        return connectit_json_response({"error": "Login required"}, 401)
    creds, err = _whatsapp_waba_creds_or_error(current_user)
    if err:
        return err
    now = int(time.time())
    start = int(request.args.get("start", now - 7 * 86400))
    end = int(request.args.get("end", now))
    granularity = (request.args.get("granularity") or "DAY").upper()
    if granularity not in ("HALF_HOUR", "DAY", "MONTH"):
        return connectit_json_response({"error": "granularity must be HALF_HOUR, DAY, or MONTH."}, 400)
    try:
        fields = (f"analytics.start({start}).end({end}).granularity({granularity})")
        resp = requests.get(
            f"https://graph.facebook.com/{WHATSAPP_CLOUD_API_VERSION}/{creds['business_account_id']}",
            headers={"Authorization": f"Bearer {creds['access_token']}"},
            params={"fields": fields},
            timeout=20,
        )
        body = resp.json()
        if resp.status_code >= 400:
            return connectit_json_response(
                {"error": (body.get("error") or {}).get("message", "Could not fetch message analytics.")}, 502)
        return connectit_json_response({"analytics": body.get("analytics", {})})
    except Exception as e:
        logging.error(f"[WA MESSAGE ANALYTICS ERROR] {e}")
        return connectit_json_response({"error": str(e)}, 500)


@app.route("/api/whatsapp-cloud/analytics/conversations", methods=["GET"])
def whatsapp_cloud_conversation_analytics():
    """Billable conversation counts/costs over a time range, from Meta's
    WABA `conversation_analytics` field — broken down by conversation
    category (marketing/utility/authentication/service) and type
    (free_tier/regular)."""
    current_user = _get_current_user()
    if not current_user:
        return connectit_json_response({"error": "Login required"}, 401)
    creds, err = _whatsapp_waba_creds_or_error(current_user)
    if err:
        return err
    now = int(time.time())
    start = int(request.args.get("start", now - 7 * 86400))
    end = int(request.args.get("end", now))
    granularity = (request.args.get("granularity") or "DAILY").upper()
    if granularity not in ("HALF_HOUR", "DAILY", "MONTHLY"):
        return connectit_json_response({"error": "granularity must be HALF_HOUR, DAILY, or MONTHLY."}, 400)
    dimensions = request.args.get("dimensions", "conversation_category,conversation_type")
    dims_arr = json.dumps([d.strip() for d in dimensions.split(",") if d.strip()])
    try:
        fields = (f"conversation_analytics.start({start}).end({end}).granularity({granularity})"
                  f".dimensions({dims_arr})")
        resp = requests.get(
            f"https://graph.facebook.com/{WHATSAPP_CLOUD_API_VERSION}/{creds['business_account_id']}",
            headers={"Authorization": f"Bearer {creds['access_token']}"},
            params={"fields": fields},
            timeout=20,
        )
        body = resp.json()
        if resp.status_code >= 400:
            return connectit_json_response(
                {"error": (body.get("error") or {}).get("message", "Could not fetch conversation analytics.")}, 502)
        return connectit_json_response({"conversation_analytics": body.get("conversation_analytics", {})})
    except Exception as e:
        logging.error(f"[WA CONVERSATION ANALYTICS ERROR] {e}")
        return connectit_json_response({"error": str(e)}, 500)


# ════════════════════════════════════════════════════════════
# WHATSAPP BUSINESS ENCRYPTION — public key management for WhatsApp
# Flows that use the encrypted data channel (Flows with server-side
# endpoints exchanging encrypted payloads). A business generates an
# RSA keypair, keeps the private key on their own Flow endpoint server,
# and uploads only the public key to Meta via this endpoint.
# ════════════════════════════════════════════════════════════

@app.route("/api/whatsapp-cloud/encryption/public-key", methods=["GET"])
def whatsapp_cloud_get_business_public_key():
    """Returns the business public key currently on file with Meta for
    this phone number, plus its signature-verification status."""
    current_user = _get_current_user()
    if not current_user:
        return connectit_json_response({"error": "Login required"}, 401)
    creds = _whatsapp_cloud_creds_for_user(current_user["id"])
    if not creds["access_token"] or not creds["phone_number_id"]:
        return connectit_json_response({"error": "WhatsApp Cloud API is not configured."}, 503)
    try:
        resp = requests.get(
            f"https://graph.facebook.com/{WHATSAPP_CLOUD_API_VERSION}/{creds['phone_number_id']}/whatsapp_business_encryption",
            headers={"Authorization": f"Bearer {creds['access_token']}"},
            timeout=15,
        )
        body = resp.json()
        if resp.status_code >= 400:
            return connectit_json_response(
                {"error": (body.get("error") or {}).get("message", "Could not fetch the business public key.")}, 502)
        return connectit_json_response({
            "business_public_key": body.get("business_public_key", ""),
            "business_public_key_signature_status": body.get("business_public_key_signature_status", "UNKNOWN"),
        })
    except Exception as e:
        logging.error(f"[WA ENCRYPTION KEY GET ERROR] {e}")
        return connectit_json_response({"error": str(e)}, 500)


@app.route("/api/whatsapp-cloud/encryption/public-key", methods=["POST"])
@csrf.exempt
def whatsapp_cloud_set_business_public_key():
    """Uploads/rotates the business public key (PEM-encoded RSA key,
    -----BEGIN PUBLIC KEY----- ... -----END PUBLIC KEY-----) used to
    encrypt data exchanged with encrypted-channel WhatsApp Flows. The
    matching private key must live only on the business's own Flow
    endpoint server — it is never sent to or stored by this platform."""
    current_user = _get_current_user()
    if not current_user:
        return connectit_json_response({"error": "Login required"}, 401)
    creds = _whatsapp_cloud_creds_for_user(current_user["id"])
    if not creds["access_token"] or not creds["phone_number_id"]:
        return connectit_json_response({"error": "WhatsApp Cloud API is not configured."}, 503)
    data = request.get_json(force=True) or {}
    public_key = (data.get("business_public_key") or "").strip()
    if "BEGIN PUBLIC KEY" not in public_key:
        return connectit_json_response(
            {"error": "business_public_key must be a PEM-encoded public key "
                      "(-----BEGIN PUBLIC KEY----- ... -----END PUBLIC KEY-----)."}, 400)
    try:
        resp = requests.post(
            f"https://graph.facebook.com/{WHATSAPP_CLOUD_API_VERSION}/{creds['phone_number_id']}/whatsapp_business_encryption",
            headers={"Authorization": f"Bearer {creds['access_token']}"},
            data={"business_public_key": public_key},
            timeout=15,
        )
        body = resp.json()
        if resp.status_code >= 400:
            return connectit_json_response(
                {"error": (body.get("error") or {}).get("message", "Could not upload the business public key.")}, 502)
        logging.info(f"[WA ENCRYPTION KEY SET] user={current_user['id']} phone_number_id={creds['phone_number_id']}")
        return connectit_json_response({"uploaded": bool(body.get("success", True))})
    except Exception as e:
        logging.error(f"[WA ENCRYPTION KEY SET ERROR] {e}")
        return connectit_json_response({"error": str(e)}, 500)


# ════════════════════════════════════════════════════════════
# WHATSAPP BUSINESS CALLING API — lets a Cloud API phone number make/
# receive real-time voice calls over WhatsApp (WebRTC), in addition to
# messaging. `settings` control whether calling is enabled at all and
# who can request a callback; `connect`/`pre-accept`/`reject`/`terminate`
# drive the call session itself. The SDP offer/answer exchange for the
# actual audio stream is generated by the caller's own WebRTC stack
# (e.g. the browser's RTCPeerConnection) — these endpoints relay that
# SDP to/from Meta's Graph API rather than reimplementing WebRTC.
# ════════════════════════════════════════════════════════════

@app.route("/api/whatsapp-cloud/calling/settings", methods=["GET"])
def whatsapp_cloud_calling_settings_get():
    """Returns this phone number's current calling configuration
    (whether calling is enabled, call icon visibility, callback
    permission policy, business hours, call hours)."""
    current_user = _get_current_user()
    if not current_user:
        return connectit_json_response({"error": "Login required"}, 401)
    creds = _whatsapp_cloud_creds_for_user(current_user["id"])
    if not creds["access_token"] or not creds["phone_number_id"]:
        return connectit_json_response({"error": "WhatsApp Cloud API is not configured."}, 503)
    try:
        resp = requests.get(
            f"https://graph.facebook.com/{WHATSAPP_CLOUD_API_VERSION}/{creds['phone_number_id']}/settings",
            headers={"Authorization": f"Bearer {creds['access_token']}"},
            params={"fields": "calling"},
            timeout=15,
        )
        body = resp.json()
        if resp.status_code >= 400:
            return connectit_json_response(
                {"error": (body.get("error") or {}).get("message", "Could not fetch calling settings.")}, 502)
        return connectit_json_response({"calling": body.get("calling", {})})
    except Exception as e:
        logging.error(f"[WA CALLING SETTINGS GET ERROR] {e}")
        return connectit_json_response({"error": str(e)}, 500)


@app.route("/api/whatsapp-cloud/calling/settings", methods=["POST"])
@csrf.exempt
def whatsapp_cloud_calling_settings_update():
    """Updates calling configuration. Body may include: status
    ('ENABLED'/'DISABLED'), call_icon_visibility ('DEFAULT'/'DISABLE_ALL'),
    callback_permission_status ('ENABLED'/'DISABLED'), and optional
    call_hours / sip settings passed through as given."""
    current_user = _get_current_user()
    if not current_user:
        return connectit_json_response({"error": "Login required"}, 401)
    creds = _whatsapp_cloud_creds_for_user(current_user["id"])
    if not creds["access_token"] or not creds["phone_number_id"]:
        return connectit_json_response({"error": "WhatsApp Cloud API is not configured."}, 503)
    data = request.get_json(force=True) or {}
    calling = {}
    if data.get("status") in ("ENABLED", "DISABLED"):
        calling["status"] = data["status"]
    if data.get("call_icon_visibility") in ("DEFAULT", "DISABLE_ALL"):
        calling["call_icon_visibility"] = data["call_icon_visibility"]
    if data.get("callback_permission_status") in ("ENABLED", "DISABLED"):
        calling["callback_permission_status"] = data["callback_permission_status"]
    if isinstance(data.get("call_hours"), dict):
        calling["call_hours"] = data["call_hours"]
    if isinstance(data.get("sip"), dict):
        calling["sip"] = data["sip"]
    if not calling:
        return connectit_json_response({"error": "No valid calling settings provided."}, 400)
    try:
        resp = requests.post(
            f"https://graph.facebook.com/{WHATSAPP_CLOUD_API_VERSION}/{creds['phone_number_id']}/settings",
            headers={"Authorization": f"Bearer {creds['access_token']}", "Content-Type": "application/json"},
            json={"calling": calling},
            timeout=15,
        )
        body = resp.json()
        if resp.status_code >= 400:
            return connectit_json_response(
                {"error": (body.get("error") or {}).get("message", "Could not update calling settings.")}, 502)
        logging.info(f"[WA CALLING SETTINGS] user={current_user['id']} updated={calling}")
        return connectit_json_response({"updated": True, "calling": calling})
    except Exception as e:
        logging.error(f"[WA CALLING SETTINGS UPDATE ERROR] {e}")
        return connectit_json_response({"error": str(e)}, 500)


def _whatsapp_calling_creds_or_error(current_user):
    creds = _whatsapp_cloud_creds_for_user(current_user["id"])
    if not creds["access_token"] or not creds["phone_number_id"]:
        return None, connectit_json_response({"error": "WhatsApp Cloud API is not configured."}, 503)
    return creds, None


@app.route("/api/whatsapp-cloud/username", methods=["GET", "POST"])
@csrf.exempt
def whatsapp_cloud_username():
    """Business-scoped username (BSUID feature, rolling out from June 29,
    2026) — lets a business claim a friendly wa.me-style username for
    their number instead of only a phone number. GET returns the current
    status; POST claims/changes it."""
    current_user = _get_current_user()
    if not current_user:
        return connectit_json_response({"error": "Login required"}, 401)
    creds = _whatsapp_cloud_creds_for_user(current_user["id"])
    if not creds.get("access_token") or not creds.get("phone_number_id"):
        return connectit_json_response({"error": "WhatsApp Cloud API is not configured."}, 503)
    base = f"https://graph.facebook.com/{WHATSAPP_CLOUD_API_VERSION}/{creds['phone_number_id']}/username"
    headers = {"Authorization": f"Bearer {creds['access_token']}"}
    try:
        if request.method == "GET":
            resp = requests.get(base, headers=headers, timeout=15)
        else:
            if not _csrf_ok():
                return connectit_json_response({"error": "CSRF token invalid or missing."}, 403)
            username = ((request.get_json(silent=True) or {}).get("username") or "").strip()
            if not username:
                return connectit_json_response({"error": "username is required."}, 400)
            resp = requests.post(base, headers={**headers, "Content-Type": "application/json"},
                                  json={"username": username}, timeout=15)
        body = resp.json() if resp.content else {}
        if resp.status_code >= 400:
            return connectit_json_response({
                "error": (body.get("error") or {}).get("message")
                         or "Meta rejected the request — this feature rolled out June 29, 2026 and may "
                            "not be available on every account/number yet.",
                "raw": body,
            }, 502)
        return connectit_json_response({"ok": True, **body}), 200
    except Exception as e:
        return connectit_json_response({"error": str(e)}), 502


