@app.route("/api/meta-business-agent/status", methods=["GET"])
def meta_business_agent_status():
    """Eligibility (Meta's own agent_eligibility endpoint) plus this
    platform's own recent standby/handoff activity log, so a business can
    see at a glance whether Meta Business Agent is active on their number
    and when it last handed a conversation back."""
    current_user = _get_current_user()
    if not current_user:
        return connectit_json_response({"error": "Login required"}, 401)
    creds = _whatsapp_cloud_creds_for_user(current_user["id"])
    eligibility = None
    if creds.get("access_token") and creds.get("phone_number_id"):
        try:
            resp = requests.get(
                f"https://api.facebook.com/{creds['phone_number_id']}/agent_eligibility",
                headers={"Authorization": f"Bearer {creds['access_token']}"},
                timeout=15,
            )
            eligibility = resp.json() if resp.status_code < 400 else {"error": resp.text[:300]}
        except Exception as e:
            eligibility = {"error": str(e)}

    recent = (MetaBusinessAgentEvent.query
              .filter_by(owner_user_id=current_user["id"])
              .order_by(MetaBusinessAgentEvent.id.desc())
              .limit(50).all())
    return connectit_json_response({
        "ok": True,
        "eligibility": eligibility,
        "standby_subscribed": any(e.event_type == "standby_message" for e in recent),
        "recent_events": [e.to_dict() for e in recent],
    }), 200


@app.route("/api/meta-business-agent/reclaim", methods=["POST"])
@csrf.exempt
def meta_business_agent_reclaim():
    """Best-effort: ask Meta to release a conversation from the agent back
    to this business early (thread_control). This part of Meta's API is
    newer and less stabilized than the rest of the Cloud API — if the
    exact endpoint/payload below has since changed, this will surface
    Meta's real error message rather than a fake success."""
    current_user = _get_current_user()
    if not current_user:
        return connectit_json_response({"error": "Login required"}, 401)
    if not _csrf_ok():
        return connectit_json_response({"error": "CSRF token invalid or missing."}, 403)
    creds, err = _whatsapp_calling_creds_or_error(current_user)
    if err:
        return err
    data = request.get_json(silent=True) or {}
    customer_wa_id = re.sub(r"\D", "", data.get("customer_wa_id", ""))
    if not customer_wa_id:
        return connectit_json_response({"error": "customer_wa_id is required."}, 400)
    try:
        resp = requests.post(
            f"https://graph.facebook.com/{WHATSAPP_CLOUD_API_VERSION}/{creds['phone_number_id']}/thread_control",
            headers={"Authorization": f"Bearer {creds['access_token']}", "Content-Type": "application/json"},
            json={"messaging_product": "whatsapp", "thread_control": "release", "to": customer_wa_id},
            timeout=15,
        )
        body = resp.json() if resp.content else {}
        if resp.status_code >= 400:
            return connectit_json_response({
                "error": (body.get("error") or {}).get("message")
                         or "Meta rejected the reclaim request — verify thread_control's current "
                            "endpoint/payload shape in your Meta dashboard; this API is still evolving.",
                "raw": body,
            }, 502)
        db.session.add(MetaBusinessAgentEvent(
            owner_user_id=current_user["id"], phone_number_id=creds["phone_number_id"],
            customer_wa_id=customer_wa_id, event_type="reclaim_requested",
        ))
        db.session.commit()
        return connectit_json_response({"ok": True, "raw": body}), 200
    except Exception as e:
        return connectit_json_response({"error": str(e)}, 502)


# ════════════════════════════════════════════════════════════
# SHARED HELPERS — BSUID-aware identifiers
# ════════════════════════════════════════════════════════════
_WA_BSUID_RE = re.compile(r"^[A-Za-z]{2}\.[A-Za-z0-9]{6,}$")


def _wa_is_bsuid(value) -> bool:
    return bool(value) and bool(_WA_BSUID_RE.match(str(value).strip()))


def _wa_session_key(wa_id: str) -> str:
    """Key used for chat history / inbox: '+digits' for phones, the raw
    BSUID otherwise (never digit-stripped — that would destroy it)."""
    wa_id = (wa_id or "").strip()
    if _wa_is_bsuid(wa_id):
        return wa_id[:64]
    return ("+" + re.sub(r"\D", "", wa_id))[:64]


def _wa_sender_key(msg: dict) -> str:
    """Who sent this inbound message. Prefer the phone number; when the
    customer has adopted a username Meta may omit it, so fall back to
    their BSUID rather than producing a bare '+'."""
    if msg.get("from"):
        return "+" + str(msg["from"])
    return str(msg.get("from_user_id") or msg.get("user_id") or "")


def _wa_capture_identity(owner_uid, contacts, msg: dict) -> None:
    """Remember bsuid ↔ username ↔ phone ↔ profile name from an inbound
    webhook. Defensive about field names: Meta's username rollout is
    recent, so every plausible key is checked and nothing is invented."""
    if not owner_uid:
        return
    try:
        sender_phone = str(msg.get("from") or "")
        sender_bsuid = str(msg.get("from_user_id") or msg.get("user_id") or "")
        for c in (contacts or []):
            c_bsuid = str(c.get("user_id") or c.get("bsuid") or "")
            c_phone = str(c.get("wa_id") or "")
            if sender_bsuid and c_bsuid and c_bsuid != sender_bsuid:
                continue
            if not sender_bsuid and sender_phone and c_phone and c_phone != sender_phone:
                continue
            bsuid = c_bsuid or sender_bsuid
            if not bsuid:
                continue
            row = WhatsAppContactIdentity.query.filter_by(owner_user_id=owner_uid, bsuid=bsuid[:64]).first()
            if not row:
                row = WhatsAppContactIdentity(owner_user_id=owner_uid, bsuid=bsuid[:64])
                db.session.add(row)
            if c.get("username"):
                row.username = str(c["username"])[:64]
            if c_phone:
                row.wa_id = c_phone[:32]
            pname = ((c.get("profile") or {}).get("name") or "")[:120]
            if pname:
                row.profile_name = pname
            row.last_seen = datetime.utcnow()
            db.session.commit()
            return
    except Exception as e:
        db.session.rollback()
        logging.error(f"[WA IDENTITY CAPTURE ERROR] {e}")


def _wa_phone_tail(s) -> str:
    d = re.sub(r"\D", "", str(s or ""))
    return d[-9:] if len(d) >= 9 else d


def _wa_resolve_erp_customer(owner_uid, wa_id):
    """Match a WhatsApp identity to an ERP customer: via a linked BSUID
    identity first, otherwise by comparing the last 9 digits of the
    phone number (survives +263 / 0 / spaces formatting differences)."""
    phone = wa_id
    if _wa_is_bsuid(wa_id):
        ident = WhatsAppContactIdentity.query.filter_by(owner_user_id=owner_uid, bsuid=wa_id).first()
        if not ident:
            return None
        if ident.erp_customer_id:
            c = ErpCustomer.query.filter_by(id=ident.erp_customer_id, owner_user_id=owner_uid).first()
            if c:
                return c
        phone = ident.wa_id
    tail = _wa_phone_tail(phone)
    if len(tail) < 7:
        return None
    for c in (ErpCustomer.query.filter(ErpCustomer.owner_user_id == owner_uid,
                                       ErpCustomer.phone.isnot(None)).limit(20000).all()):
        if _wa_phone_tail(c.phone) == tail:
            return c
    return None


# ════════════════════════════════════════════════════════════
# META BUSINESS AGENT — HANDOFF RECEIVER
# ════════════════════════════════════════════════════════════
_MBA_STOPWORDS = {
    "what", "when", "where", "which", "have", "does", "your", "with", "this", "that", "there", "about",
    "much", "many", "price", "cost", "stock", "available", "please", "hello", "thanks", "thank", "need",
    "want", "would", "could", "order", "from", "they", "them", "just", "like", "know", "tell", "send",
}


def _mba_build_context(owner_uid, wa_id, topic_texts):
    """The packet Meta's agent can't see: real customer record, invoices
    and balance, WhatsApp orders, and live stock for what the customer
    mentioned. Reads only real rows — nothing is generated or guessed."""
    ctx = {"wa_id": wa_id, "customer": None, "invoices": [], "outstanding": {},
           "whatsapp_orders": [], "stock_matches": [],
           "built_at": datetime.utcnow().isoformat()}
    cust = _wa_resolve_erp_customer(owner_uid, wa_id)
    if cust:
        ctx["customer"] = {"id": cust.id, "name": cust.name, "email": cust.email, "phone": cust.phone,
                           "notes": (cust.notes or "")[:300] or None}
        invs = (ErpInvoice.query.filter_by(owner_user_id=owner_uid, customer_id=cust.id)
                .order_by(ErpInvoice.created_at.desc()).limit(25).all())
        for inv in invs:
            d = inv.to_dict()
            bal = d.get("balance_due")
            if bal is None:
                bal = (inv.total or 0) - (inv.amount_paid or 0)
            row = {"number": inv.invoice_number, "status": d.get("status") or inv.status,
                   "currency": inv.currency, "total": inv.total, "balance_due": bal,
                   "due_date": d.get("due_date")}
            if len(ctx["invoices"]) < 5:
                ctx["invoices"].append(row)
            if (row["status"] or "") not in ("paid", "void", "draft") and (bal or 0) > 0:
                ctx["outstanding"][inv.currency] = round(ctx["outstanding"].get(inv.currency, 0) + bal, 2)
    digits = re.sub(r"\D", "", wa_id or "")
    if digits:
        for o in (WhatsAppCatalogOrder.query.filter_by(owner_user_id=owner_uid, customer_wa_id=digits)
                  .order_by(WhatsAppCatalogOrder.id.desc()).limit(5).all()):
            od = o.to_dict()
            ctx["whatsapp_orders"].append({"status": od["status"], "items": len(od["items"]),
                                           "total": od["total_amount"], "currency": od["currency"],
                                           "placed": od["created_at"]})
    words = []
    for t in topic_texts or []:
        for w in re.findall(r"[A-Za-z0-9][A-Za-z0-9\-]{3,}", (t or "").lower()):
            if w not in _MBA_STOPWORDS and w not in words:
                words.append(w)
    seen = set()
    for w in words[:8]:
        for it in (InventoryItem.query.filter(InventoryItem.user_id == owner_uid, InventoryItem.active == True,  # noqa: E712
                                              InventoryItem.name.ilike(f"%{w}%")).limit(3).all()):
            if it.id in seen or len(ctx["stock_matches"]) >= 6:
                continue
            seen.add(it.id)
            ctx["stock_matches"].append({"name": it.name, "in_stock": it.quantity, "unit": it.unit or "units",
                                         "unit_price": it.unit_price, "low_stock": (it.quantity or 0) <= (it.threshold or 0)})
    return ctx


def _mba_render_context(ctx: dict) -> str:
    lines = []
    c = ctx.get("customer")
    if c:
        lines.append(f"Customer on file: {c['name']}" + (f" ({c['email']})" if c.get("email") else "") + ".")
        if c.get("notes"):
            lines.append(f"Account notes: {c['notes']}")
    else:
        lines.append("No matching customer record in the ERP (treat as a new/unknown customer).")
    if ctx.get("outstanding"):
        lines.append("Outstanding balance: " + ", ".join(f"{v} {k}" for k, v in ctx["outstanding"].items()) + ".")
    elif c:
        lines.append("No outstanding balance.")
    for i in ctx.get("invoices", [])[:3]:
        lines.append(f"Invoice {i['number']}: {i['status']}, total {i['total']} {i['currency']}, "
                     f"balance due {i['balance_due']}, due {i['due_date']}.")
    for o in ctx.get("whatsapp_orders", [])[:3]:
        lines.append(f"WhatsApp order ({o['status']}): {o['items']} item(s), total {o['total']} {o['currency']}.")
    for s in ctx.get("stock_matches", []):
        lines.append(f"Stock — {s['name']}: {s['in_stock']} {s['unit']} available"
                     + (f", price {s['unit_price']}" if s.get("unit_price") else "")
                     + (" (LOW STOCK)" if s.get("low_stock") else "") + ".")
    return "\n".join(lines)


def _mba_refresh_context(h: "MetaAgentHandoff", extra_text: str = "") -> None:
    try:
        transcript = json.loads(h.transcript_json or "[]")
    except Exception:
        transcript = []
    texts = [h.trigger_text or "", extra_text] + [t.get("text", "") for t in transcript if t.get("dir") == "customer"]
    ctx = _mba_build_context(h.owner_user_id, h.customer_wa_id, texts)
    h.context_json = json.dumps(ctx)
    h.context_text = _mba_render_context(ctx)
    h.context_built_at = datetime.utcnow()
    h.erp_customer_id = (ctx.get("customer") or {}).get("id")


def _mba_create_handoff(owner_uid, phone_number_id, cust_wa_id, msg: dict, contacts) -> None:
    """Called when a chat the agent was handling arrives as a normal
    'messages' event (the architectural handoff signal)."""
    try:
        open_row = (MetaAgentHandoff.query.filter_by(owner_user_id=owner_uid, customer_wa_id=cust_wa_id)
                    .filter(MetaAgentHandoff.status.in_(["open", "in_progress"])).first())
        if open_row:
            return
        events = (MetaBusinessAgentEvent.query
                  .filter_by(owner_user_id=owner_uid, phone_number_id=phone_number_id, customer_wa_id=cust_wa_id,
                             event_type="standby_message")
                  .order_by(MetaBusinessAgentEvent.id.desc()).limit(20).all())
        transcript = [{"dir": "customer" if e.direction == "inbound" else "agent",
                       "text": (e.body_text or "")[:500],
                       "at": e.created_at.isoformat() if e.created_at else None} for e in reversed(events)]
        name = None
        for c in (contacts or []):
            if str(c.get("wa_id") or "") == str(msg.get("from") or "") or \
               str(c.get("user_id") or "") == str(msg.get("from_user_id") or "_"):
                name = ((c.get("profile") or {}).get("name") or "")[:120] or None
                break
        h = MetaAgentHandoff(
            owner_user_id=owner_uid, phone_number_id=(phone_number_id or "")[:64] or None,
            customer_wa_id=cust_wa_id[:64], customer_name=name,
            trigger_text=((msg.get("text") or {}).get("body") or "")[:1000] or None,
            transcript_json=json.dumps(transcript), status="open")
        _mba_refresh_context(h)
        db.session.add(h)
        db.session.commit()
        cname = (h.customer_name or (json.loads(h.context_json).get("customer") or {}).get("name")
                 or h.customer_wa_id)
        notify_user(owner_uid, "whatsapp", f"Meta agent handed off: {cname}",
                    (h.context_text or "")[:400])
    except Exception as e:
        db.session.rollback()
        logging.error(f"[MBA HANDOFF CREATE ERROR] {e}")


def _mba_active_handoff(owner_uid, wa_id):
    """Latest open/in-progress handoff for this customer within 48h."""
    cutoff = datetime.utcnow() - timedelta(hours=48)
    return (MetaAgentHandoff.query.filter_by(owner_user_id=owner_uid, customer_wa_id=wa_id.lstrip("+"))
            .filter(MetaAgentHandoff.status.in_(["open", "in_progress"]), MetaAgentHandoff.created_at >= cutoff)
            .order_by(MetaAgentHandoff.id.desc()).first())


def _mba_context_for_ai(h: "MetaAgentHandoff", latest_text: str) -> str:
    """Live-refresh when the stored packet is stale (stock moves fast),
    then frame it so the model states only these facts."""
    try:
        if not h.context_built_at or (datetime.utcnow() - h.context_built_at).total_seconds() > 300:
            _mba_refresh_context(h, latest_text)
            db.session.commit()
    except Exception as e:
        db.session.rollback()
        logging.error(f"[MBA CONTEXT REFRESH ERROR] {e}")
    if not h.context_text:
        return ""
    return ("[Verified business records for this customer, handed over from Meta's WhatsApp agent. "
            "Use ONLY these facts for account, balance, order and stock questions; if something is not "
            "listed, say you will check rather than guessing.]\n" + h.context_text)


