# ════════════════════════════════════════════════════════════
# WHATSAPP INTERACTIVE MEDIA CAROUSEL
# Scrollable product cards over the Cloud API with no Meta catalog.
# Interactive (free-form) messages only deliver inside the 24h
# customer-service window; Meta's own error is surfaced if outside it.
# ════════════════════════════════════════════════════════════
def send_whatsapp_media_carousel(user_id, to_number: str, body_text: str, cards: list) -> dict:
    creds = _whatsapp_cloud_creds_for_user(user_id)
    if not creds["phone_number_id"] or not creds["access_token"]:
        raise ValueError("WhatsApp Cloud API not configured")
    if not (2 <= len(cards) <= 10):
        raise ValueError("A carousel needs between 2 and 10 cards.")
    out_cards = []
    for i, c in enumerate(cards):
        img = (c.get("image_url") or "").strip()
        url = (c.get("url") or "").strip()
        text = (c.get("body") or "").strip()
        btn = (c.get("button_text") or "View").strip()
        if not img.startswith("https://"):
            raise ValueError(f"Card {i + 1}: image_url must be an https:// link.")
        if not url.startswith("https://"):
            raise ValueError(f"Card {i + 1}: url must be an https:// link.")
        if not text:
            raise ValueError(f"Card {i + 1}: body text is required.")
        out_cards.append({
            "card_index": i, "type": "cta_url",
            "header": {"type": "image", "image": {"link": img}},
            "body": {"text": text[:160]},
            "action": {"name": "cta_url", "parameters": {"display_text": btn[:20], "url": url}},
        })
    payload = {"messaging_product": "whatsapp", "type": "interactive",
               "interactive": {"type": "carousel", "body": {"text": (body_text or "Here are some options for you")[:1024]},
                               "action": {"cards": out_cards}}}
    if _wa_is_bsuid(to_number):
        payload["recipient"] = to_number.strip()
    else:
        payload["to"] = re.sub(r"\D", "", to_number or "")
        if not payload["to"]:
            raise ValueError("Valid recipient required.")
    resp = requests.post(
        f"https://graph.facebook.com/{WHATSAPP_CLOUD_API_VERSION}/{creds['phone_number_id']}/messages",
        headers={"Authorization": f"Bearer {creds['access_token']}", "Content-Type": "application/json"},
        json=payload, timeout=20)
    data = resp.json()
    if not resp.ok:
        raise ValueError((data.get("error") or {}).get("message", "Carousel send failed."))
    return data


@app.route("/api/whatsapp-cloud/send-carousel", methods=["POST"])
@csrf.exempt
def whatsapp_cloud_send_carousel():
    """Body: {to, body, cards:[{image_url,url,body,button_text}]}.
    A card may instead carry {product_id,image_url,url}: its text is then
    filled from the real ERP product (name, price, live stock)."""
    current_user = _get_current_user()
    if not current_user:
        return connectit_json_response({"error": "Login required"}, 401)
    if not _csrf_ok():
        return connectit_json_response({"error": "CSRF token invalid or missing."}, 403)
    data = request.get_json(silent=True) or {}
    cards = []
    for c in (data.get("cards") or []):
        c = dict(c)
        pid = c.get("product_id")
        if pid:
            it = InventoryItem.query.filter_by(id=pid, user_id=current_user["id"]).first()
            if not it:
                return connectit_json_response({"error": f"Product {pid} not found."}, 404)
            price = f" — {it.unit_price:g}" if it.unit_price else ""
            stock = "in stock" if (it.quantity or 0) > 0 else "out of stock"
            c["body"] = c.get("body") or f"{it.name}{price} ({stock})"
        cards.append(c)
    try:
        res = send_whatsapp_media_carousel(current_user["id"], (data.get("to") or ""), data.get("body") or "", cards)
        return connectit_json_response({"ok": True, "message_id": ((res.get("messages") or [{}])[0]).get("id")})
    except ValueError as e:
        return connectit_json_response({"error": str(e)}, 400)
    except Exception as e:
        return connectit_json_response({"error": str(e)}, 502)


