# ════════════════════════════════════════════════════════════
# WHATSAPP CALL QUEUE — permission-gated order confirmations,
# appointment reminders and payment follow-ups
# ════════════════════════════════════════════════════════════
_WA_CALL_PURPOSES = ("order_confirmation", "appointment_reminder", "payment_followup", "custom")
_WA_CALL_MAX_ATTEMPTS = 3


def _wa_call_perm_row(owner_uid, wa_id):
    return WhatsAppCallPermission.query.filter_by(owner_user_id=owner_uid, customer_wa_id=wa_id).first()


def _wa_send_call_permission_request(owner_uid, wa_id):
    """Returns (ok, error). Keeps a local log so we don't exceed Meta's
    request frequency limits (about 1 per 24h and 2 per 7 days per
    customer — confirm current limits in Meta's docs)."""
    creds = _whatsapp_cloud_creds_for_user(owner_uid)
    if not creds["phone_number_id"] or not creds["access_token"]:
        return False, "WhatsApp Cloud API is not configured."
    row = _wa_call_perm_row(owner_uid, wa_id)
    now = datetime.utcnow()
    log = []
    if row and row.requested_log:
        try:
            log = [t for t in json.loads(row.requested_log)
                   if datetime.fromisoformat(t) > now - timedelta(days=7)]
        except Exception:
            log = []
    if log and datetime.fromisoformat(log[-1]) > now - timedelta(hours=24):
        return False, "A permission request was already sent in the last 24 hours."
    if len(log) >= 2:
        return False, "Two permission requests were already sent this week."
    payload = {"messaging_product": "whatsapp", "type": "interactive",
               "interactive": {"type": "call_permission_request", "action": {"name": "call_permission_request"}}}
    if _wa_is_bsuid(wa_id):
        payload["recipient"] = wa_id
    else:
        payload["to"] = re.sub(r"\D", "", wa_id)
    try:
        resp = requests.post(
            f"https://graph.facebook.com/{WHATSAPP_CLOUD_API_VERSION}/{creds['phone_number_id']}/messages",
            headers={"Authorization": f"Bearer {creds['access_token']}", "Content-Type": "application/json"},
            json=payload, timeout=15)
        body = resp.json()
        if resp.status_code >= 400:
            return False, (body.get("error") or {}).get("message", "Could not send permission request.")
        if not row:
            row = WhatsAppCallPermission(owner_user_id=owner_uid, customer_wa_id=wa_id[:64], status="requested")
            db.session.add(row)
        if row.status != "granted":
            row.status = "requested"
        log.append(now.isoformat())
        row.requested_log = json.dumps(log)
        db.session.commit()
        return True, None
    except Exception as e:
        db.session.rollback()
        return False, str(e)


def _wa_handle_call_permission_reply(owner_uid, msg: dict) -> None:
    reply = (msg.get("interactive") or {}).get("call_permission_reply") or {}
    wa_id = str(msg.get("from") or msg.get("from_user_id") or "")
    if not owner_uid or not wa_id:
        return
    accepted = str(reply.get("response") or "").lower() in ("accept", "accepted", "granted")
    row = _wa_call_perm_row(owner_uid, wa_id)
    if not row:
        row = WhatsAppCallPermission(owner_user_id=owner_uid, customer_wa_id=wa_id[:64])
        db.session.add(row)
    row.status = "granted" if accepted else "denied"
    row.is_permanent = bool(reply.get("is_permanent"))
    exp = reply.get("expiration_timestamp")
    try:
        row.expires_at = datetime.utcfromtimestamp(int(exp)) if exp else (
            None if row.is_permanent else datetime.utcnow() + timedelta(days=7))
    except (TypeError, ValueError):
        row.expires_at = None if row.is_permanent else datetime.utcnow() + timedelta(days=7)
    for t in WhatsAppCallTask.query.filter_by(owner_user_id=owner_uid, customer_wa_id=wa_id,
                                              status="awaiting_permission").all():
        if accepted:
            t.status = "ready"
        else:
            t.status, t.last_error = "skipped", "Customer declined call permission."
    db.session.commit()
    if accepted:
        notify_user(owner_uid, "whatsapp", "Customer allowed calls",
                    f"{wa_id} can now be called — see your Call queue.")


def queue_whatsapp_call(owner_uid, to, purpose, notes="", reference="", customer_name=None,
                        invoice_id=None, scheduled_for=None) -> dict:
    """Create a call task. Never raises for expected problems."""
    purpose = (purpose or "custom").strip()
    if purpose not in _WA_CALL_PURPOSES:
        return {"ok": False, "error": f"purpose must be one of {', '.join(_WA_CALL_PURPOSES)}."}
    wa_id = to.strip() if _wa_is_bsuid(to) else re.sub(r"\D", "", to or "")
    if not wa_id:
        return {"ok": False, "error": "A valid recipient is required."}
    if purpose == "payment_followup":
        # Guard rails: only for a real unpaid invoice, and capped so a
        # workflow can't turn into harassment. Debt collection calls are
        # regulated in many jurisdictions — the operator must also respect
        # local call-hour and contact-frequency rules.
        inv = ErpInvoice.query.filter_by(id=invoice_id, owner_user_id=owner_uid).first() if invoice_id else None
        if not inv:
            return {"ok": False, "error": "payment_followup requires an invoice_id for one of your invoices."}
        d = inv.to_dict()
        bal = d.get("balance_due")
        if bal is None:
            bal = (inv.total or 0) - (inv.amount_paid or 0)
        if inv.status in ("paid", "void", "draft") or bal <= 0:
            return {"ok": False, "error": "That invoice has no outstanding balance."}
        recent = (WhatsAppCallTask.query.filter_by(owner_user_id=owner_uid, customer_wa_id=wa_id,
                                                   purpose="payment_followup")
                  .filter(WhatsAppCallTask.created_at >= datetime.utcnow() - timedelta(days=7),
                          WhatsAppCallTask.status != "skipped").count())
        if recent >= _WA_CALL_MAX_ATTEMPTS:
            return {"ok": False, "error": "Payment follow-up call limit reached for this customer this week."}
        reference = reference or inv.invoice_number
    perm = _wa_call_perm_row(owner_uid, wa_id)
    status, err = "awaiting_permission", None
    if perm and perm.is_active_grant():
        status = "ready"
    elif perm and perm.status == "denied":
        status, err = "skipped", "Customer previously declined call permission."
    task = WhatsAppCallTask(owner_user_id=owner_uid, customer_wa_id=wa_id[:64], customer_name=customer_name,
                            purpose=purpose, notes=(notes or "")[:500] or None, reference=(reference or "")[:120] or None,
                            invoice_id=invoice_id, scheduled_for=scheduled_for, status=status, last_error=err)
    db.session.add(task)
    db.session.commit()
    if status == "awaiting_permission":
        ok, perr = _wa_send_call_permission_request(owner_uid, wa_id)
        if not ok:
            task.last_error = (perr or "")[:300]
            db.session.commit()
    return {"ok": True, "task": task.to_dict()}


def _automation_action_queue_whatsapp_call(owner_user_id, org_id, config, context):
    sched = None
    raw = _automation_render(config.get("scheduled_for"), context)
    if raw:
        try:
            sched = datetime.fromisoformat(str(raw).replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            return {"ok": False, "error": "scheduled_for must be an ISO date/time."}
    inv = _automation_render(config.get("invoice_id"), context)
    try:
        inv = int(inv) if inv else None
    except (TypeError, ValueError):
        return {"ok": False, "error": "invoice_id must be a number."}
    return queue_whatsapp_call(
        owner_user_id, _automation_render(config.get("to"), context) or "",
        _automation_render(config.get("purpose"), context) or "custom",
        notes=_automation_render(config.get("notes"), context) or "",
        reference=_automation_render(config.get("reference"), context) or "",
        customer_name=_automation_render(config.get("customer_name"), context),
        invoice_id=inv, scheduled_for=sched)


