@app.route("/api/whatsapp-cloud/call-tasks", methods=["POST"])
@csrf.exempt
def wa_call_tasks_create():
    current_user = _get_current_user()
    if not current_user:
        return connectit_json_response({"error": "Login required"}, 401)
    if not _csrf_ok():
        return connectit_json_response({"error": "CSRF token invalid or missing."}, 403)
    d = request.get_json(silent=True) or {}
    sched = None
    if d.get("scheduled_for"):
        try:
            sched = datetime.fromisoformat(str(d["scheduled_for"]).replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            return connectit_json_response({"error": "scheduled_for must be an ISO date/time."}, 400)
    res = queue_whatsapp_call(current_user["id"], d.get("to") or "", d.get("purpose"),
                              notes=d.get("notes") or "", reference=d.get("reference") or "",
                              customer_name=(d.get("customer_name") or None), invoice_id=d.get("invoice_id"),
                              scheduled_for=sched)
    return connectit_json_response(res, 201 if res.get("ok") else 400)


def _wa_task_or_404(owner_uid, task_id):
    return WhatsAppCallTask.query.filter_by(id=task_id, owner_user_id=owner_uid).first()


@app.route("/api/whatsapp-cloud/call-tasks/<int:task_id>/start", methods=["POST"])
@csrf.exempt
def wa_call_task_start(task_id):
    """Marks the task in progress. The browser then places the call via
    /calling/connect (pass task_id so the call is linked back)."""
    current_user = _get_current_user()
    if not current_user:
        return connectit_json_response({"error": "Login required"}, 401)
    if not _csrf_ok():
        return connectit_json_response({"error": "CSRF token invalid or missing."}, 403)
    t = _wa_task_or_404(current_user["id"], task_id)
    if not t:
        return connectit_json_response({"error": "Task not found."}, 404)
    perm = _wa_call_perm_row(current_user["id"], t.customer_wa_id)
    if not (perm and perm.is_active_grant()):
        return connectit_json_response({"error": "No active call permission from this customer."}, 409)
    if t.attempts >= _WA_CALL_MAX_ATTEMPTS:
        return connectit_json_response({"error": "Maximum call attempts reached."}, 409)
    t.status, t.attempts = "in_progress", t.attempts + 1
    db.session.commit()
    return connectit_json_response({"ok": True, "task": t.to_dict()})


@app.route("/api/whatsapp-cloud/call-tasks/<int:task_id>/complete", methods=["POST"])
@csrf.exempt
def wa_call_task_complete(task_id):
    current_user = _get_current_user()
    if not current_user:
        return connectit_json_response({"error": "Login required"}, 401)
    if not _csrf_ok():
        return connectit_json_response({"error": "CSRF token invalid or missing."}, 403)
    t = _wa_task_or_404(current_user["id"], task_id)
    if not t:
        return connectit_json_response({"error": "Task not found."}, 404)
    d = request.get_json(silent=True) or {}
    outcome = (d.get("outcome") or "other").strip()[:24]
    t.outcome, t.outcome_note = outcome, (d.get("note") or "")[:500] or None
    if outcome == "no_answer":
        t.status = "ready" if t.attempts < _WA_CALL_MAX_ATTEMPTS else "no_answer"
    else:
        t.status = "done"
    db.session.commit()
    return connectit_json_response({"ok": True, "task": t.to_dict()})


