# ════════════════════════════════════════════════════════════
# CLICK-TO-WHATSAPP AD ATTRIBUTION — capture, events, report
# ════════════════════════════════════════════════════════════
def _wa_ad_settings(owner_uid):
    return WhatsAppAdSettings.query.filter_by(owner_user_id=owner_uid).first()


def _wa_capture_ad_referral(owner_uid, msg: dict, contacts):
    """Store the `referral` object a click-to-WhatsApp ad attaches to the
    customer's first message. Returns the new row (or None)."""
    ref = msg.get("referral")
    if not owner_uid or not isinstance(ref, dict):
        return None
    try:
        who = (str(msg.get("from")) if msg.get("from") else "") or str(msg.get("from_user_id") or msg.get("user_id") or "")
        if not who:
            return None
        clid = (ref.get("ctwa_clid") or "")[:512] or None
        if clid and WhatsAppAdReferral.query.filter_by(owner_user_id=owner_uid, ctwa_clid=clid).first():
            return None
        name = None
        for c in (contacts or []):
            if str(c.get("wa_id") or "") == who or str(c.get("user_id") or "") == who:
                name = ((c.get("profile") or {}).get("name") or "")[:120] or None
                break
        row = WhatsAppAdReferral(
            owner_user_id=owner_uid, customer_wa_id=who[:64], ctwa_clid=clid,
            source_id=str(ref.get("source_id") or "")[:64] or None,
            source_type=str(ref.get("source_type") or "")[:16] or None,
            source_url=str(ref.get("source_url") or "")[:500] or None,
            headline=str(ref.get("headline") or "")[:300] or None, profile_name=name)
        db.session.add(row)
        db.session.commit()
        return row
    except Exception as e:
        db.session.rollback()
        logging.error(f"[WA AD REFERRAL CAPTURE ERROR] {e}")
        return None


def _wa_find_referral_for_customer(owner_uid, cust):
    """Latest ad referral belonging to this ERP customer — by phone tail,
    or via a BSUID identity linked to them."""
    tail = _wa_phone_tail(cust.phone)
    keys = {i.bsuid for i in WhatsAppContactIdentity.query.filter_by(owner_user_id=owner_uid, erp_customer_id=cust.id).all()}
    for r in (WhatsAppAdReferral.query.filter_by(owner_user_id=owner_uid)
              .order_by(WhatsAppAdReferral.id.desc()).limit(5000).all()):
        if r.customer_wa_id in keys or (len(tail) >= 7 and _wa_phone_tail(r.customer_wa_id) == tail):
            return r
    return None


def _wa_capi_record_and_send(owner_uid, ref, event_name, event_id, value=None, currency=None):
    """Always records the conversion locally (idempotent on event_id).
    Sends it to Meta only if a dataset + token are configured and the
    click is inside the attribution window."""
    try:
        log = WhatsAppAdConversion(owner_user_id=owner_uid, referral_id=ref.id, source_id=ref.source_id,
                                   event_name=event_name[:40], event_id=event_id[:80],
                                   value=value, currency=(currency or None), status="local_only")
        db.session.add(log)
        db.session.commit()
    except IntegrityError:
        db.session.rollback()
        return {"ok": True, "duplicate": True}
    except Exception as e:
        db.session.rollback()
        return {"ok": False, "error": str(e)}
    st = _wa_ad_settings(owner_uid)
    token = _meta_capi_creds_for_user(owner_uid).get("access_token")
    creds = _whatsapp_cloud_creds_for_user(owner_uid)
    if not (st and st.dataset_id and token and ref.ctwa_clid and creds.get("business_account_id")):
        return {"ok": True, "sent": False, "reason": "Recorded locally; Meta dataset, token, WABA ID or click ID missing."}
    if ref.created_at and ref.created_at < datetime.utcnow() - timedelta(days=st.window_days or 7):
        log.status, log.error = "expired", "Click is outside the attribution window."
        db.session.commit()
        return {"ok": True, "sent": False, "reason": log.error}
    event = {"event_name": event_name, "event_time": int(time.time()), "event_id": event_id,
             "action_source": "business_messaging", "messaging_channel": "whatsapp",
             "user_data": {"whatsapp_business_account_id": creds["business_account_id"], "ctwa_clid": ref.ctwa_clid}}
    if value is not None and currency:
        event["custom_data"] = {"currency": currency, "value": value}
    body = {"data": [event]}
    if st.test_event_code:
        body["test_event_code"] = st.test_event_code
    try:
        resp = requests.post(f"https://graph.facebook.com/{FACEBOOK_GRAPH_API_VERSION}/{st.dataset_id}/events",
                             params={"access_token": token}, json=body, timeout=15)
        result = resp.json()
        if resp.status_code >= 400:
            log.status, log.error = "failed", ((result.get("error") or {}).get("message") or "Meta rejected the event.")[:300]
        else:
            log.status = "sent"
        db.session.commit()
        return {"ok": log.status == "sent", "status": log.status, "error": log.error}
    except Exception as e:
        db.session.rollback()
        logging.error(f"[WA CAPI SEND ERROR] {e}")
        return {"ok": False, "error": str(e)}


def _wa_capi_lead_job(app_ref, owner_uid, referral_id):
    app_ref = app_ref or app
    with app_ref.app_context():
        st = _wa_ad_settings(owner_uid)
        if st is not None and not st.auto_lead:
            return
        ref = WhatsAppAdReferral.query.get(referral_id)
        if ref:
            _wa_capi_record_and_send(owner_uid, ref, "Lead", f"lead-{ref.id}")


def _wa_capi_purchase_job(app_ref, owner_uid, invoice_id, customer_id, total, currency):
    app_ref = app_ref or app
    with app_ref.app_context():
        try:
            st = _wa_ad_settings(owner_uid)
            if st is not None and not st.auto_purchase:
                return
            cust = ErpCustomer.query.filter_by(id=customer_id, owner_user_id=owner_uid).first() if customer_id else None
            ref = _wa_find_referral_for_customer(owner_uid, cust) if cust else None
            if ref:
                _wa_capi_record_and_send(owner_uid, ref, "Purchase", f"invoice-{invoice_id}-purchase", total, currency)
        except Exception as e:
            db.session.rollback()
            logging.error(f"[WA CAPI PURCHASE JOB ERROR] {e}")


@app.route("/api/whatsapp-cloud/ad-attribution/settings", methods=["GET", "POST"])
@csrf.exempt
def wa_ad_settings_endpoint():
    current_user = _get_current_user()
    if not current_user:
        return connectit_json_response({"error": "Login required"}, 401)
    st = _wa_ad_settings(current_user["id"])
    if request.method == "POST":
        if not _csrf_ok():
            return connectit_json_response({"error": "CSRF token invalid or missing."}, 403)
        d = request.get_json(silent=True) or {}
        if not st:
            st = WhatsAppAdSettings(owner_user_id=current_user["id"])
            db.session.add(st)
        if "dataset_id" in d:
            st.dataset_id = re.sub(r"\D", "", str(d["dataset_id"]))[:64] or None
        if "test_event_code" in d:
            st.test_event_code = (str(d["test_event_code"]).strip()[:64] or None)
        for k in ("auto_lead", "auto_purchase"):
            if k in d:
                setattr(st, k, bool(d[k]))
        if "window_days" in d:
            try:
                st.window_days = max(1, min(int(d["window_days"]), 90))
            except (TypeError, ValueError):
                pass
        db.session.commit()
    token_ok = bool(_meta_capi_creds_for_user(current_user["id"]).get("access_token"))
    return connectit_json_response({
        "ok": True, "token_configured": token_ok,
        "settings": {"dataset_id": st.dataset_id if st else None, "test_event_code": st.test_event_code if st else None,
                     "auto_lead": st.auto_lead if st else True, "auto_purchase": st.auto_purchase if st else True,
                     "window_days": st.window_days if st else 7}})


@app.route("/api/whatsapp-cloud/ad-attribution/report", methods=["GET"])
def wa_ad_report():
    """Per-ad: chats started, leads, purchases and revenue (per currency)."""
    current_user = _get_current_user()
    if not current_user:
        return connectit_json_response({"error": "Login required"}, 401)
    try:
        days = max(1, min(int(request.args.get("days", 30)), 365))
    except ValueError:
        days = 30
    since = datetime.utcnow() - timedelta(days=days)
    uid = current_user["id"]
    ads = {}
    for r in WhatsAppAdReferral.query.filter(WhatsAppAdReferral.owner_user_id == uid,
                                             WhatsAppAdReferral.created_at >= since).all():
        a = ads.setdefault(r.source_id or "unknown", {"source_id": r.source_id, "headline": r.headline,
                           "chats": 0, "leads": 0, "purchases": 0, "revenue": {}, "meta_sent": 0})
        a["chats"] += 1
        a["headline"] = a["headline"] or r.headline
    for c in WhatsAppAdConversion.query.filter(WhatsAppAdConversion.owner_user_id == uid,
                                               WhatsAppAdConversion.created_at >= since).all():
        a = ads.setdefault(c.source_id or "unknown", {"source_id": c.source_id, "headline": None, "chats": 0,
                           "leads": 0, "purchases": 0, "revenue": {}, "meta_sent": 0})
        if c.event_name == "Lead":
            a["leads"] += 1
        elif c.event_name == "Purchase":
            a["purchases"] += 1
            if c.value and c.currency:
                a["revenue"][c.currency] = round(a["revenue"].get(c.currency, 0) + c.value, 2)
        if c.status == "sent":
            a["meta_sent"] += 1
    rows = sorted(ads.values(), key=lambda x: (-x["purchases"], -x["chats"]))
    recent = (WhatsAppAdReferral.query.filter_by(owner_user_id=uid)
              .order_by(WhatsAppAdReferral.id.desc()).limit(20).all())
    return connectit_json_response({"ok": True, "days": days, "ads": rows,
                                    "recent_referrals": [r.to_dict() for r in recent]})


@app.route("/api/whatsapp-cloud/ad-attribution/send-event", methods=["POST"])
@csrf.exempt
def wa_ad_send_event():
    """Manually send a funnel event for one ad chat, e.g. QualifiedLead.
    Body: {referral_id, event_name, value?, currency?}"""
    current_user = _get_current_user()
    if not current_user:
        return connectit_json_response({"error": "Login required"}, 401)
    if not _csrf_ok():
        return connectit_json_response({"error": "CSRF token invalid or missing."}, 403)
    d = request.get_json(silent=True) or {}
    ref = WhatsAppAdReferral.query.filter_by(id=d.get("referral_id"), owner_user_id=current_user["id"]).first()
    name = re.sub(r"[^A-Za-z]", "", str(d.get("event_name") or ""))[:40]
    if not ref or not name:
        return connectit_json_response({"error": "A valid referral_id and event_name are required."}, 400)
    res = _wa_capi_record_and_send(current_user["id"], ref, name, f"manual-{ref.id}-{name}-{int(time.time())}",
                                   d.get("value"), d.get("currency"))
    return connectit_json_response(res, 200 if res.get("ok") else 502)


# ════════════════════════════════════════════════════════════
# WHATSAPP FLOWS — LIVE DATA ENDPOINT
# Meta calls this URL while a customer is inside a Flow, so screens can
# show real ERP data: in-stock products, free appointment slots, the
# customer's own balance. Requests/responses are encrypted (RSA-OAEP
# wrapped AES-128-GCM); the response uses the request's AES key with the
# IV bit-flipped. A Flow opts in by pointing its endpoint URL here.
#
# Contract (the Flow JSON sends these as data.action on a data_exchange):
#   get_products {}                       -> {products:[{id,title,description}]}
#   check_stock  {product_id, quantity}   -> {available, in_stock, message}
#   get_slots    {date:"YYYY-MM-DD"}      -> {slots:[{id,title}], message}
#   book_slot    {date,time,name,service?}-> navigates to the success screen
#   get_balance  {}                       -> {balance_text}  (needs flow token)
# ════════════════════════════════════════════════════════════
def _flow_secret() -> str:
    return str(app.secret_key or os.environ.get("SECRET_KEY") or "")


def _flow_token_make(owner_uid, wa_id) -> str:
    """Signed token sent with each Flow so the endpoint knows WHICH
    customer is on the other end (needed before showing any balance)."""
    secret = _flow_secret()
    if not secret or not wa_id:
        return "unused"
    raw = f"{owner_uid}|{wa_id}|{int(time.time())}"
    sig = hmac.new(secret.encode(), raw.encode(), hashlib.sha256).hexdigest()[:32]
    return base64.urlsafe_b64encode(raw.encode()).decode().rstrip("=") + "." + sig


def _flow_token_verify(token, owner_uid, max_age=86400):
    """Returns the customer's wa_id, or None if absent/forged/expired."""
    secret = _flow_secret()
    try:
        b64, sig = (token or "").split(".", 1)
        raw = base64.urlsafe_b64decode(b64 + "=" * (-len(b64) % 4)).decode()
        if not hmac.compare_digest(hmac.new(secret.encode(), raw.encode(), hashlib.sha256).hexdigest()[:32], sig):
            return None
        o, wa_id, ts = raw.split("|")
        if int(o) != int(owner_uid) or time.time() - int(ts) > max_age:
            return None
        return wa_id
    except Exception:
        return None


def _flow_decrypt_request(private_pem: str, body: dict):
    from cryptography.hazmat.primitives import hashes, serialization
    from cryptography.hazmat.primitives.asymmetric import padding
    from cryptography.hazmat.primitives.ciphers.aead import AESGCM
    key = serialization.load_pem_private_key(private_pem.encode(), password=None)
    aes_key = key.decrypt(
        base64.b64decode(body["encrypted_aes_key"]),
        padding.OAEP(mgf=padding.MGF1(algorithm=hashes.SHA256()), algorithm=hashes.SHA256(), label=None))
    iv = base64.b64decode(body["initial_vector"])
    plain = AESGCM(aes_key).decrypt(iv, base64.b64decode(body["encrypted_flow_data"]), None)
    return json.loads(plain.decode()), aes_key, iv


def _flow_encrypt_response(resp: dict, aes_key: bytes, iv: bytes) -> str:
    from cryptography.hazmat.primitives.ciphers.aead import AESGCM
    flipped = bytes(b ^ 0xFF for b in iv)
    return base64.b64encode(AESGCM(aes_key).encrypt(flipped, json.dumps(resp).encode(), None)).decode()


def _flow_slots(owner_uid, ep, date_str):
    """Free appointment slots for one day: business hours (from the
    Business Profile settings, else Mon-Fri 09:00-17:00) minus existing
    bookings and minus times already past."""
    try:
        day = datetime.strptime(date_str, "%Y-%m-%d").date()
    except (TypeError, ValueError):
        return None, "Please pick a valid date."
    now_local = datetime.utcnow() + timedelta(minutes=ep.tz_offset_minutes or 0)
    if day < now_local.date() or day > now_local.date() + timedelta(days=ep.slot_days_ahead or 14):
        return [], f"Bookings are open for the next {ep.slot_days_ahead or 14} days."
    hours = None
    s = BusinessProfileSyncSettings.query.filter_by(user_id=owner_uid).first()
    if s and s.business_hours_json:
        try:
            hours = json.loads(s.business_hours_json)
        except Exception:
            hours = None
    name = day.strftime("%A").upper()
    if hours:
        h = hours.get(name)
        if not h:
            return [], "We're closed that day."
        open_s, close_s = h.get("open", "09:00"), h.get("close", "17:00")
    else:
        if day.weekday() >= 5:
            return [], "We're closed that day."
        open_s, close_s = "09:00", "17:00"
    start = datetime.combine(day, datetime.strptime(open_s, "%H:%M").time())
    end = datetime.combine(day, datetime.strptime(close_s, "%H:%M").time())
    step = timedelta(minutes=max(10, ep.slot_minutes or 30))
    taken = CalendarBooking.query.filter(CalendarBooking.user_id == owner_uid, CalendarBooking.status != "cancelled",
                                         CalendarBooking.start_time < end, CalendarBooking.end_time > start).all()
    slots, t = [], start
    while t + step <= end:
        if t > now_local and not any(b.start_time < t + step and b.end_time > t for b in taken):
            slots.append({"id": t.strftime("%H:%M"), "title": t.strftime("%H:%M")})
        t += step
    return slots[:200], ("" if slots else "No free times that day — try another date.")


_FLOW_SCREEN_RE = re.compile(r"^[A-Za-z0-9_]{1,64}$")


def _flow_next(data, screen):
    """A Flow can name the screen to land on after a data-exchange with a
    constant `next_screen` in its payload (needed for 'fill the form, then
    see live slots on the NEXT screen'). Without it, the reply goes back
    to the requesting screen - the original behaviour - so Flows already
    built against this endpoint are unaffected."""
    nxt = str((data or {}).get("next_screen") or "")
    return nxt if _FLOW_SCREEN_RE.match(nxt) else screen


def _flow_echo(data):
    """Carries the customer's form values forward so a later screen can
    submit them (a data-exchange reply only contains what we send back)."""
    return {k: str((data or {}).get(k) or "")[:120] for k in ("date", "name", "service")}


def _flow_norm_date(v):
    """DatePicker values normally arrive as YYYY-MM-DD but can arrive as a
    millisecond timestamp; accept both."""
    s = str(v or "").strip()
    if s.isdigit() and len(s) >= 10:
        n = int(s)
        n = n / 1000 if n > 10 ** 11 else n
        return datetime.utcfromtimestamp(n).strftime("%Y-%m-%d")
    return s


def _flow_handle(owner_uid, ep, req: dict) -> dict:
    action = (req.get("action") or "").lower()
    screen = req.get("screen")
    data = req.get("data") or {}
    wa_id = _flow_token_verify(req.get("flow_token"), owner_uid)

    def err(msg):
        return {"screen": screen or ep.first_screen, "data": {"error_message": msg}}

    if action == "ping":
        return {"data": {"status": "active"}}
    if action in ("init", "back"):
        return {"screen": screen if action == "back" and screen else ep.first_screen, "data": {}}
    if action != "data_exchange":
        return err("Unsupported request.")
    op = (data.get("action") or "").strip()
    if data.get("date"):
        data["date"] = _flow_norm_date(data["date"])

    if op == "get_products":
        items = (InventoryItem.query.filter(InventoryItem.user_id == owner_uid, InventoryItem.active == True,  # noqa: E712
                                            InventoryItem.quantity > 0).order_by(InventoryItem.name).limit(200).all())
        return {"screen": _flow_next(data, screen), "data": {"products": [
            {"id": str(i.id), "title": i.name[:30],
             "description": (f"{i.unit_price:g} · " if i.unit_price else "") + f"{i.quantity:g} {i.unit or 'in stock'}"[:60]}
            for i in items]}}
    if op == "check_stock":
        it = InventoryItem.query.filter_by(id=data.get("product_id"), user_id=owner_uid).first() if str(data.get("product_id") or "").isdigit() else None
        if not it:
            return err("Product not found.")
        try:
            qty = float(data.get("quantity") or 1)
        except (TypeError, ValueError):
            return err("Enter a valid quantity.")
        ok = (it.quantity or 0) >= qty
        return {"screen": _flow_next(data, screen), "data": {"available": ok, "in_stock": it.quantity,
                "message": (f"{it.name}: {qty:g} available." if ok else f"Only {it.quantity:g} of {it.name} in stock.")}}
    if op == "get_slots":
        slots, msg = _flow_slots(owner_uid, ep, data.get("date"))
        if slots is None:
            return err(msg)
        nxt = _flow_next(data, screen)
        if not slots and nxt != screen:
            return err(msg)          # closed / fully booked: stay on the date screen with the reason
        return {"screen": nxt, "data": {"slots": slots, "message": msg or "Choose a time that suits you.",
                                        **_flow_echo(data)}}
    if op == "book_slot":
        name = (data.get("name") or "").strip()[:120]
        if not name:
            return err("Please enter your name.")
        slots, msg = _flow_slots(owner_uid, ep, data.get("date"))
        if not slots or data.get("time") not in {s["id"] for s in slots}:
            if slots:                # refresh the list so the customer can pick again
                return {"screen": screen, "data": {"slots": slots, "message": "Choose a time that suits you.",
                        "error_message": "That time was just taken — please pick another.", **_flow_echo(data)}}
            return err("That time was just taken — please pick another.")
        start = datetime.strptime(f"{data['date']} {data['time']}", "%Y-%m-%d %H:%M")
        booking = CalendarBooking(user_id=owner_uid, summary=f"{(data.get('service') or 'Appointment')[:80]} — {name}",
                                  description=f"Booked via WhatsApp Flow ({wa_id or 'unverified'})",
                                  client_name=name, start_time=start,
                                  end_time=start + timedelta(minutes=max(10, ep.slot_minutes or 30)), status="confirmed")
        db.session.add(booking)
        db.session.commit()
        try:
            org_id = _automation_org_id_for_user(owner_uid)
            if org_id:
                fire_automation_trigger(org_id, "new_booking", {"title": booking.summary,
                                        "start_time": start.isoformat(), "attendee_email": None})
        except Exception as e:
            logging.error(f"[FLOW BOOKING TRIGGER ERROR] {e}")
        return {"screen": ep.success_screen, "data": {"booking_summary": f"{start:%A %d %B, %H:%M}"}}
    if op == "get_balance":
        if not wa_id:
            return err("We couldn't verify who you are. Please message us to check your balance.")
        cust = _wa_resolve_erp_customer(owner_uid, wa_id)
        if not cust:
            return {"screen": screen, "data": {"balance_text": "No account found for this number."}}
        ctx = _mba_build_context(owner_uid, wa_id, [])
        out = ctx.get("outstanding") or {}
        text = ("Outstanding: " + ", ".join(f"{v} {k}" for k, v in out.items())) if out else "You have no outstanding balance."
        return {"screen": screen, "data": {"balance_text": text}}
    return err("Unknown action.")


@app.route("/whatsapp-flows/endpoint/<token>", methods=["POST"])
@csrf.exempt
def whatsapp_flows_data_endpoint(token):
    ep = WhatsAppFlowEndpoint.query.filter_by(url_token=token).first()
    if not ep:
        return "Not found", 404
    if WHATSAPP_CLOUD_APP_SECRET and not _verify_whatsapp_cloud_signature(
            WHATSAPP_CLOUD_APP_SECRET, request.get_data(), request.headers.get("X-Hub-Signature-256", "")):
        return "Signature mismatch", 432
    try:
        priv = decrypt_secret_blob(ep.private_key_enc).get("pem", "")
        req, aes_key, iv = _flow_decrypt_request(priv, request.get_json(force=True, silent=True) or {})
    except Exception as e:
        logging.error(f"[FLOW ENDPOINT DECRYPT ERROR] {e}")
        return "Decryption failed", 421      # tells Meta to re-fetch the public key
    try:
        resp = _flow_handle(ep.owner_user_id, ep, req)
    except Exception as e:
        db.session.rollback()
        logging.error(f"[FLOW ENDPOINT HANDLER ERROR] {e}")
        resp = {"screen": req.get("screen") or ep.first_screen, "data": {"error_message": "Something went wrong. Please try again."}}
    return Response(_flow_encrypt_response(resp, aes_key, iv), mimetype="text/plain")


def _flow_ep_public(ep):
    return {"endpoint_url": f"{APP_BASE_URL.rstrip('/')}/whatsapp-flows/endpoint/{ep.url_token}",
            "key_uploaded": ep.key_uploaded, "first_screen": ep.first_screen, "success_screen": ep.success_screen,
            "slot_minutes": ep.slot_minutes, "slot_days_ahead": ep.slot_days_ahead,
            "tz_offset_minutes": ep.tz_offset_minutes}


@app.route("/api/whatsapp-flows/endpoint", methods=["GET"])
def whatsapp_flows_endpoint_status():
    current_user = _get_current_user()
    if not current_user:
        return connectit_json_response({"error": "Login required"}, 401)
    ep = WhatsAppFlowEndpoint.query.filter_by(owner_user_id=current_user["id"]).first()
    return connectit_json_response({"ok": True, "configured": bool(ep), **(_flow_ep_public(ep) if ep else {})})


@app.route("/api/whatsapp-flows/endpoint/setup", methods=["POST"])
@csrf.exempt
def whatsapp_flows_endpoint_setup():
    """Creates (or with {rotate:true} replaces) this business's key pair,
    uploads the public key to Meta, and returns the endpoint URL to paste
    into the Flow. Rotating invalidates the old key at Meta."""
    current_user = _get_current_user()
    if not current_user:
        return connectit_json_response({"error": "Login required"}, 401)
    if not _csrf_ok():
        return connectit_json_response({"error": "CSRF token invalid or missing."}, 403)
    uid = current_user["id"]
    creds = _whatsapp_cloud_creds_for_user(uid)
    if not creds["access_token"] or not creds["phone_number_id"]:
        return connectit_json_response({"error": "WhatsApp Cloud API is not configured."}, 503)
    rotate = bool((request.get_json(silent=True) or {}).get("rotate"))
    ep = WhatsAppFlowEndpoint.query.filter_by(owner_user_id=uid).first()
    if ep and not rotate and ep.key_uploaded:
        return connectit_json_response({"ok": True, **_flow_ep_public(ep)})
    from cryptography.hazmat.primitives import serialization
    from cryptography.hazmat.primitives.asymmetric import rsa
    key = rsa.generate_private_key(public_exponent=65537, key_size=2048)
    priv_pem = key.private_bytes(serialization.Encoding.PEM, serialization.PrivateFormat.PKCS8,
                                 serialization.NoEncryption()).decode()
    pub_pem = key.public_key().public_bytes(serialization.Encoding.PEM,
                                            serialization.PublicFormat.SubjectPublicKeyInfo).decode()
    try:
        resp = requests.post(
            f"https://graph.facebook.com/{WHATSAPP_CLOUD_API_VERSION}/{creds['phone_number_id']}/whatsapp_business_encryption",
            headers={"Authorization": f"Bearer {creds['access_token']}"},
            data={"business_public_key": pub_pem}, timeout=15)
        body = resp.json()
        if resp.status_code >= 400:
            return connectit_json_response(
                {"error": (body.get("error") or {}).get("message", "Meta rejected the public key.")}, 502)
    except Exception as e:
        return connectit_json_response({"error": str(e)}, 502)
    if not ep:
        ep = WhatsAppFlowEndpoint(owner_user_id=uid, url_token=secrets.token_urlsafe(32),
                                  private_key_enc=encrypt_secret_blob({"pem": priv_pem}), public_key_pem=pub_pem)
        db.session.add(ep)
    else:
        ep.private_key_enc, ep.public_key_pem = encrypt_secret_blob({"pem": priv_pem}), pub_pem
    ep.key_uploaded = True
    db.session.commit()
    return connectit_json_response({"ok": True, **_flow_ep_public(ep)})


@app.route("/api/whatsapp-flows/endpoint/settings", methods=["POST"])
@csrf.exempt
def whatsapp_flows_endpoint_settings():
    current_user = _get_current_user()
    if not current_user:
        return connectit_json_response({"error": "Login required"}, 401)
    if not _csrf_ok():
        return connectit_json_response({"error": "CSRF token invalid or missing."}, 403)
    ep = WhatsAppFlowEndpoint.query.filter_by(owner_user_id=current_user["id"]).first()
    if not ep:
        return connectit_json_response({"error": "Set up the endpoint first."}, 400)
    d = request.get_json(silent=True) or {}
    for k in ("first_screen", "success_screen"):
        if d.get(k):
            setattr(ep, k, re.sub(r"[^A-Za-z0-9_]", "", str(d[k]))[:64] or getattr(ep, k))
    for k, lo, hi in (("slot_minutes", 10, 240), ("slot_days_ahead", 1, 90), ("tz_offset_minutes", -720, 840)):
        if k in d:
            try:
                setattr(ep, k, max(lo, min(int(d[k]), hi)))
            except (TypeError, ValueError):
                pass
    db.session.commit()
    return connectit_json_response({"ok": True, **_flow_ep_public(ep)})


# ════════════════════════════════════════════════════════════
# WHATSAPP FLOWS — ONE-CLICK BOOKING FLOW
# Builds a ready-made appointment Flow that talks to the live data
# endpoint above (get_slots -> book_slot), creates it in Meta as a DRAFT
# with this business's endpoint URL attached, and leaves publishing (which
# is irreversible) as a separate, confirmed step.
# ════════════════════════════════════════════════════════════
WHATSAPP_FLOW_JSON_VERSION = os.environ.get("WHATSAPP_FLOW_JSON_VERSION", "7.0")


def _flow_booking_json(heading: str = "Book an appointment") -> dict:
    """Three screens: WELCOME_SCREEN (name, service, date) -> SLOT_SCREEN
    (live free times from the ERP calendar) -> SUCCESS_SCREEN. Screen IDs
    match the WhatsAppFlowEndpoint defaults. The endpoint URL is NOT in this
    JSON: for Flow JSON 3.0+ Meta takes it as `endpoint_uri` on the Flow."""
    def _str(example):
        return {"type": "string", "__example__": example}
    return {
        "version": WHATSAPP_FLOW_JSON_VERSION,
        "data_api_version": "3.0",
        "routing_model": {"WELCOME_SCREEN": ["SLOT_SCREEN"], "SLOT_SCREEN": ["SUCCESS_SCREEN"], "SUCCESS_SCREEN": []},
        "screens": [
            {"id": "WELCOME_SCREEN", "title": "Book an appointment",
             "data": {"error_message": _str("")},
             "layout": {"type": "SingleColumnLayout", "children": [
                 {"type": "TextHeading", "text": (heading or "Book an appointment")[:80]},
                 {"type": "TextBody", "text": "Tell us who you are and pick a date. Next we'll show the times that are free."},
                 {"type": "Form", "name": "booking_form", "children": [
                     {"type": "TextInput", "name": "name", "label": "Your name", "input-type": "text", "required": True},
                     {"type": "TextInput", "name": "service", "label": "What is it for? (optional)", "input-type": "text", "required": False},
                     {"type": "DatePicker", "name": "date", "label": "Date", "required": True},
                     {"type": "Footer", "label": "See free times", "on-click-action": {
                         "name": "data_exchange",
                         "payload": {"action": "get_slots", "next_screen": "SLOT_SCREEN", "date": "${form.date}",
                                     "name": "${form.name}", "service": "${form.service}"}}}]}]}},
            {"id": "SLOT_SCREEN", "title": "Pick a time",
             "data": {
                 "slots": {"type": "array", "items": {"type": "object", "properties": {
                     "id": {"type": "string"}, "title": {"type": "string"}}},
                     "__example__": [{"id": "09:00", "title": "09:00"}, {"id": "09:30", "title": "09:30"}]},
                 "message": _str("Choose a time that suits you."),
                 "date": _str("2026-10-12"), "name": _str("Tendai"), "service": _str("Consultation"),
                 "error_message": _str("")},
             "layout": {"type": "SingleColumnLayout", "children": [
                 {"type": "TextHeading", "text": "Free times"},
                 {"type": "TextBody", "text": "${data.message}"},
                 {"type": "Form", "name": "slot_form", "children": [
                     {"type": "Dropdown", "name": "time", "label": "Time", "required": True, "data-source": "${data.slots}"},
                     {"type": "Footer", "label": "Confirm booking", "on-click-action": {
                         "name": "data_exchange",
                         "payload": {"action": "book_slot", "date": "${data.date}", "time": "${form.time}",
                                     "name": "${data.name}", "service": "${data.service}"}}}]}]}},
            {"id": "SUCCESS_SCREEN", "title": "Booked", "terminal": True, "success": True,
             "data": {"booking_summary": _str("Monday 12 October, 09:30")},
             "layout": {"type": "SingleColumnLayout", "children": [
                 {"type": "TextHeading", "text": "You're booked!"},
                 {"type": "TextBody", "text": "${data.booking_summary}"},
                 {"type": "Footer", "label": "Done", "on-click-action": {
                     "name": "complete", "payload": {"booking": "${data.booking_summary}"}}}]}},
        ],
    }


@app.route("/api/whatsapp-flows/endpoint/create-booking-flow", methods=["POST"])
@csrf.exempt
def whatsapp_flows_create_booking_flow():
    """Creates the booking Flow in Meta as a DRAFT, with the Flow JSON and
    this business's data-endpoint URL attached in one call. Body (all
    optional): {name, heading}. Returns {flow_id, validation_errors,
    default_set}. Publish separately via /api/whatsapp-cloud/flows/<id>/publish."""
    current_user = _get_current_user()
    if not current_user:
        return connectit_json_response({"error": "Login required"}, 401)
    if not _csrf_ok():
        return connectit_json_response({"error": "CSRF token invalid or missing."}, 403)
    creds, err = _whatsapp_waba_creds_or_error(current_user)
    if err:
        return err
    uid = current_user["id"]
    ep = WhatsAppFlowEndpoint.query.filter_by(owner_user_id=uid).first()
    if not ep or not ep.key_uploaded:
        return connectit_json_response(
            {"error": "Set up the data endpoint first - it uploads the encryption key Meta needs."}, 400)
    d = request.get_json(silent=True) or {}
    name = (str(d.get("name") or "").strip() or f"Appointment booking {datetime.utcnow():%Y%m%d-%H%M}")[:100]
    flow_json = _flow_booking_json(str(d.get("heading") or "").strip())
    endpoint_url = f"{APP_BASE_URL.rstrip('/')}/whatsapp-flows/endpoint/{ep.url_token}"
    try:
        resp = requests.post(
            f"https://graph.facebook.com/{WHATSAPP_CLOUD_API_VERSION}/{creds['business_account_id']}/flows",
            headers={"Authorization": f"Bearer {creds['access_token']}", "Content-Type": "application/json"},
            json={"name": name, "categories": ["APPOINTMENT_BOOKING"], "endpoint_uri": endpoint_url,
                  "flow_json": json.dumps(flow_json)},
            timeout=30)
        body = resp.json()
    except Exception as e:
        logging.error(f"[WA BOOKING FLOW CREATE ERROR] user={uid}: {e}")
        return connectit_json_response({"error": str(e)}, 502)
    if resp.status_code >= 400 or not body.get("id"):
        e = body.get("error") or {}
        return connectit_json_response(
            {"error": e.get("error_user_msg") or e.get("message") or "Meta rejected the Flow.",
             "validation_errors": body.get("validation_errors", [])}, 502)
    flow_id = str(body["id"])
    ep.first_screen, ep.success_screen = "WELCOME_SCREEN", "SUCCESS_SCREEN"
    default_set = False
    try:
        own = get_user_credentials(uid, "whatsapp_flows")
        if not own.get("flow_id"):       # never overwrite a Flow the business already chose as its default
            save_user_integration(uid, "whatsapp_flows", {**own, "flow_id": flow_id})
            default_set = True
    except Exception as e:
        logging.error(f"[WA BOOKING FLOW DEFAULT ERROR] user={uid}: {e}")
    db.session.commit()
    logging.info(f"[WA BOOKING FLOW CREATE] user={uid} flow_id={flow_id}")
    return connectit_json_response({"ok": True, "flow_id": flow_id, "name": name,
                                    "validation_errors": body.get("validation_errors", []),
                                    "default_set": default_set})


# ════════════════════════════════════════════════════════════
# WHATSAPP VOICE AGENT — control plane
# ════════════════════════════════════════════════════════════
VOICE_BRIDGE_TOKEN = os.environ.get("VOICE_BRIDGE_TOKEN", "")
_VOICE_HUMAN_RE = re.compile(
    r"\b(human|real person|person|agent|representative|operator|manager|someone|somebody|staff|speak to|talk to)\b", re.I)
_VOICE_OPENAI_VOICES = ("alloy", "ash", "ballad", "coral", "echo", "fable", "nova", "onyx", "sage", "shimmer", "verse")


def _wa_voice_settings(owner_uid):
    return WhatsAppVoiceAgentSettings.query.filter_by(owner_user_id=owner_uid).first()


def _wa_voice_agent_enabled(owner_uid) -> bool:
    if not owner_uid or not VOICE_BRIDGE_TOKEN:
        return False      # no bridge configured → never take calls away from humans
    st = _wa_voice_settings(owner_uid)
    return bool(st and st.enabled)


def _voice_bridge_auth() -> bool:
    got = request.headers.get("Authorization", "")
    return bool(VOICE_BRIDGE_TOKEN) and got.startswith("Bearer ") and \
        hmac.compare_digest(got[7:], VOICE_BRIDGE_TOKEN)


def _wa_call_meta_action(owner_uid, action, call_id, sdp=None):
    """Send a calls action to Meta for this business. Returns (ok, error)."""
    creds = _whatsapp_cloud_creds_for_user(owner_uid)
    if not creds["phone_number_id"] or not creds["access_token"]:
        return False, "WhatsApp Cloud API is not configured."
    payload = {"messaging_product": "whatsapp", "call_id": call_id, "action": action}
    if sdp:
        payload["session"] = {"sdp_type": "answer", "sdp": sdp}
    try:
        resp = requests.post(
            f"https://graph.facebook.com/{WHATSAPP_CLOUD_API_VERSION}/{creds['phone_number_id']}/calls",
            headers={"Authorization": f"Bearer {creds['access_token']}", "Content-Type": "application/json"},
            json=payload, timeout=20)
        body = resp.json() if resp.content else {}
        if resp.status_code >= 400:
            return False, (body.get("error") or {}).get("message", f"{action} failed.")
        return True, None
    except Exception as e:
        return False, str(e)


def voice_agent_turn(owner_uid, call_row, customer_text: str) -> dict:
    """One conversational turn. Grounded in the same verified ERP packet
    used for Meta-agent handoffs. Returns {reply, handoff, end_call}."""
    customer_text = (customer_text or "").strip()[:1000]
    cid = call_row.meta_call_id
    db.session.add(WhatsAppVoiceTurn(owner_user_id=owner_uid, meta_call_id=cid, role="customer", text=customer_text))
    db.session.commit()
    if _VOICE_HUMAN_RE.search(customer_text):
        reply = "Of course. I'll have a team member call you back shortly. Thank you for calling."
        db.session.add(WhatsAppVoiceTurn(owner_user_id=owner_uid, meta_call_id=cid, role="agent", text=reply))
        db.session.commit()
        return {"reply": reply, "handoff": True, "end_call": True}
    turns = (WhatsAppVoiceTurn.query.filter_by(owner_user_id=owner_uid, meta_call_id=cid)
             .order_by(WhatsAppVoiceTurn.id.desc()).limit(13).all())[::-1]
    history = [{"role": "user" if t.role == "customer" else "assistant", "content": t.text} for t in turns[:-1]]
    recent_customer = [t.text for t in turns if t.role == "customer"]
    ctx = _mba_render_context(_mba_build_context(owner_uid, call_row.counterparty_wa_id or "", recent_customer))
    system_prompt = (
        "You are a phone assistant answering a business's WhatsApp voice call. Speak in short, natural sentences "
        "(1-3 sentences, no lists, no markdown, no emojis). Use ONLY the verified business records below for account, "
        "balance, order and stock questions; if something is not listed, say you will have the team follow up. "
        "Never invent prices, stock or promises. If the caller wants to end the call, say a brief goodbye.\n\n"
        f"Verified business records:\n{ctx}")
    try:
        reply, _ = generate_ai_reply(customer_text, history, user_id=None, system_prompt=system_prompt)
    except Exception as e:
        logging.error(f"[VOICE AGENT TURN ERROR] {e}")
        reply = "Sorry, I'm having trouble right now. A team member will call you back."
        return {"reply": reply, "handoff": True, "end_call": True}
    reply = re.sub(r"[*_#`]", "", (reply or "").strip())[:500] or "Sorry, could you say that again?"
    db.session.add(WhatsAppVoiceTurn(owner_user_id=owner_uid, meta_call_id=cid, role="agent", text=reply))
    db.session.commit()
    bye = bool(re.search(r"\b(bye|goodbye|that's all|that is all|no thanks|nothing else)\b", customer_text, re.I))
    return {"reply": reply, "handoff": False, "end_call": bye}


@app.route("/api/voice-bridge/pending", methods=["GET"])
def voice_bridge_pending():
    """The bridge polls this. Claims each returned call so it's handed to
    exactly one bridge."""
    if not _voice_bridge_auth():
        return jsonify({"error": "unauthorized"}), 401
    out = []
    for c in (WhatsAppCall.query.filter_by(direction="inbound", status="agent_queued")
              .order_by(WhatsAppCall.id.asc()).limit(5).all()):
        st = _wa_voice_settings(c.owner_user_id)
        if not st or not st.enabled or not c.sdp_offer:
            c.status = "ringing"          # agent turned off meanwhile → humans get it
            continue
        c.status = "agent_handling"
        out.append({"meta_call_id": c.meta_call_id, "owner_id": c.owner_user_id, "sdp_offer": c.sdp_offer,
                    "greeting": st.greeting, "voice": st.voice, "language": st.language,
                    "max_seconds": st.max_call_seconds})
    db.session.commit()
    return jsonify({"calls": out})


@app.route("/api/voice-bridge/answer", methods=["POST"])
@csrf.exempt
def voice_bridge_answer():
    if not _voice_bridge_auth():
        return jsonify({"error": "unauthorized"}), 401
    d = request.get_json(silent=True) or {}
    c = WhatsAppCall.query.filter_by(meta_call_id=d.get("meta_call_id") or "").first()
    sdp = (d.get("sdp_answer") or "").strip()
    if not c or not sdp:
        return jsonify({"error": "meta_call_id and sdp_answer required"}), 400
    _wa_call_meta_action(c.owner_user_id, "pre_accept", c.meta_call_id, sdp)   # best-effort: avoids clipped first words
    ok, err = _wa_call_meta_action(c.owner_user_id, "accept", c.meta_call_id, sdp)
    if not ok:
        c.status, c.termination_reason = "failed", (err or "")[:64]
        db.session.commit()
        return jsonify({"error": err}), 502
    c.status, c.sdp_offer = "connected", None
    db.session.commit()
    return jsonify({"ok": True})


@app.route("/api/voice-bridge/turn", methods=["POST"])
@csrf.exempt
def voice_bridge_turn():
    if not _voice_bridge_auth():
        return jsonify({"error": "unauthorized"}), 401
    d = request.get_json(silent=True) or {}
    c = WhatsAppCall.query.filter_by(meta_call_id=d.get("meta_call_id") or "").first()
    if not c:
        return jsonify({"error": "unknown call"}), 404
    return jsonify(voice_agent_turn(c.owner_user_id, c, d.get("text") or ""))


@app.route("/api/voice-bridge/end", methods=["POST"])
@csrf.exempt
def voice_bridge_end():
    """The bridge reports the call finished. If the caller asked for a
    human (or the agent failed) we queue a callback and tell the owner."""
    if not _voice_bridge_auth():
        return jsonify({"error": "unauthorized"}), 401
    d = request.get_json(silent=True) or {}
    cid = d.get("meta_call_id") or ""
    c = WhatsAppCall.query.filter_by(meta_call_id=cid).first()
    if not c:
        return jsonify({"error": "unknown call"}), 404
    if d.get("terminate_at_meta"):
        _wa_call_meta_action(c.owner_user_id, "terminate", cid)
    c.status = "terminated"
    c.sdp_offer = None
    try:
        c.duration_seconds = int(d.get("duration_seconds")) if d.get("duration_seconds") is not None else c.duration_seconds
    except (TypeError, ValueError):
        pass
    db.session.commit()
    turns = (WhatsAppVoiceTurn.query.filter_by(meta_call_id=cid).order_by(WhatsAppVoiceTurn.id.asc()).all())
    summary = " | ".join(f"{'Caller' if t.role == 'customer' else 'AI'}: {t.text}" for t in turns)[:380]
    if d.get("handoff") and c.counterparty_wa_id:
        queue_whatsapp_call(c.owner_user_id, c.counterparty_wa_id, "custom",
                            notes=("Caller asked for a person. " + summary)[:500], reference=f"call {cid[-8:]}")
        notify_user(c.owner_user_id, "whatsapp", "Caller asked for a human — callback queued", summary)
    elif turns:
        notify_user(c.owner_user_id, "whatsapp", "AI answered a WhatsApp call", summary)
    return jsonify({"ok": True})


@app.route("/api/whatsapp-cloud/voice-agent", methods=["GET", "POST"])
@csrf.exempt
def wa_voice_agent_settings():
    current_user = _get_current_user()
    if not current_user:
        return connectit_json_response({"error": "Login required"}, 401)
    uid = current_user["id"]
    st = _wa_voice_settings(uid)
    if request.method == "POST":
        if not _csrf_ok():
            return connectit_json_response({"error": "CSRF token invalid or missing."}, 403)
        d = request.get_json(silent=True) or {}
        if not st:
            st = WhatsAppVoiceAgentSettings(owner_user_id=uid)
            db.session.add(st)
        if "enabled" in d:
            st.enabled = bool(d["enabled"])
        if d.get("greeting"):
            st.greeting = str(d["greeting"]).strip()[:300]
        if d.get("voice") in _VOICE_OPENAI_VOICES:
            st.voice = d["voice"]
        if d.get("language"):
            st.language = re.sub(r"[^a-z\-]", "", str(d["language"]).lower())[:16] or "en"
        if "max_call_seconds" in d:
            try:
                st.max_call_seconds = max(30, min(int(d["max_call_seconds"]), 900))
            except (TypeError, ValueError):
                pass
        db.session.commit()
    recent = (WhatsAppCall.query.filter_by(owner_user_id=uid, direction="inbound")
              .order_by(WhatsAppCall.id.desc()).limit(10).all())
    calls = []
    for c in recent:
        t = (WhatsAppVoiceTurn.query.filter_by(meta_call_id=c.meta_call_id)
             .order_by(WhatsAppVoiceTurn.id.asc()).limit(30).all())
        if t:
            calls.append({"call": c.to_dict(), "transcript": [{"role": x.role, "text": x.text} for x in t]})
    return connectit_json_response({
        "ok": True, "bridge_configured": bool(VOICE_BRIDGE_TOKEN), "voices": list(_VOICE_OPENAI_VOICES),
        "settings": {"enabled": bool(st and st.enabled), "greeting": st.greeting if st else None,
                     "voice": st.voice if st else "alloy", "language": st.language if st else "en",
                     "max_call_seconds": st.max_call_seconds if st else 300},
        "calls": calls})


# ════════════════════════════════════════════════════════════
# WHATSAPP VOICE AGENT — AUDIO BRIDGE (built into this file)
# Carries the audio of calls the AI voice agent answers: WebRTC media +
# speech-to-text + text-to-speech. Everything else (settings, AI replies
# grounded in the ERP, Meta call actions, transcripts, human callback) is
# the control plane above. Run it one of two ways:
#   1. Separate process (recommended):  python app.py --voice-bridge
#      e.g. a PythonAnywhere "Always-on task". Needs env vars set there too.
#   2. Inside the web process: set VOICE_BRIDGE_EMBEDDED=1. Only one worker
#      runs it (file lock). Fine on a normal server; unreliable on hosts
#      that recycle web workers or disable threads.
# Needs:  pip install aiortc av numpy   (+ OPENAI_API_KEY, VOICE_BRIDGE_TOKEN)
# Nothing here runs unless VOICE_BRIDGE_TOKEN is set AND one of the two
# modes above is started — otherwise calls keep ringing for your humans.
# ════════════════════════════════════════════════════════════
import asyncio
import wave
from fractions import Fraction

try:
    import numpy as _vb_np
except ImportError:                     # the bridge simply can't start without numpy
    _vb_np = None


def _vb_app_url() -> str:
    return (os.environ.get("APP_URL") or APP_BASE_URL or "").rstrip("/")


def _vb_openai_key() -> str:
    return os.environ.get("OPENAI_API_KEY") or OPENAI_API_KEY or ""


_VB_SPEECH_RMS = 450            # int16 RMS above this counts as speech
_VB_START_FRAMES = 3            # 3 x 20ms of speech to start an utterance
_VB_END_SILENCE_S = 0.8         # this much silence ends an utterance
_VB_MIN_UTTERANCE_S = 0.4
_VB_MAX_UTTERANCE_S = 15.0
_VB_STT_RATE = 16000
_VB_OUT_RATE = 48000
_VB_FRAME_SAMPLES = 960         # 20 ms at 48 kHz

_vb_log = logging.getLogger("voice_bridge")


# ── pure audio helpers (unit-testable, no WebRTC needed) ─────────────────────
def _vb_rms(samples) -> float:
    if samples.size == 0:
        return 0.0
    return float(_vb_np.sqrt(_vb_np.mean(samples.astype(_vb_np.float64) ** 2)))


def _vb_pcm24k_to_48k(pcm: bytes) -> bytes:
    """OpenAI 'pcm' output is 24 kHz, 16-bit, mono, little-endian."""
    a = _vb_np.frombuffer(pcm, dtype="<i2").astype(_vb_np.float32)
    if a.size < 2:
        return b""
    x_old = _vb_np.arange(a.size)
    x_new = _vb_np.linspace(0, a.size - 1, a.size * 2)
    return _vb_np.interp(x_new, x_old, a).astype("<i2").tobytes()


def _vb_wav_bytes(samples, rate: int = _VB_STT_RATE) -> bytes:
    buf = io.BytesIO()
    with wave.open(buf, "wb") as w:
        w.setnchannels(1)
        w.setsampwidth(2)
        w.setframerate(rate)
        w.writeframes(samples.astype("<i2").tobytes())
    return buf.getvalue()


class _VbSegmenter:
    """Energy-based utterance detector. Feed 16 kHz mono int16 chunks;
    returns a finished utterance (_vb_np.ndarray) or None."""

    def __init__(self):
        self.reset()

    def reset(self):
        self.active, self.speech_run, self.silence = False, 0, 0.0
        self.chunks = []
        self.preroll = []      # the last few chunks, so the first syllable isn't clipped

    def feed(self, chunk):
        dur = chunk.size / _VB_STT_RATE
        loud = _vb_rms(chunk) >= _VB_SPEECH_RMS
        if not self.active:
            self.speech_run = self.speech_run + 1 if loud else 0
            self.preroll = (self.preroll + [chunk])[-_VB_START_FRAMES:]
            if self.speech_run >= _VB_START_FRAMES:
                self.active, self.silence, self.chunks = True, 0.0, list(self.preroll)
            return None
        self.chunks.append(chunk)
        self.silence = 0.0 if loud else self.silence + dur
        total = sum(c.size for c in self.chunks) / _VB_STT_RATE
        if self.silence >= _VB_END_SILENCE_S or total >= _VB_MAX_UTTERANCE_S:
            speech_s = total - self.silence          # measure BEFORE reset() clears the silence counter
            utt = _vb_np.concatenate(self.chunks)
            self.reset()
            return utt if speech_s >= _VB_MIN_UTTERANCE_S else None
        return None


# ── HTTP helpers (blocking; always called via run_in_executor) ───────────────
def _vb_http(method, path, **kw):
    r = requests.request(method, _vb_app_url() + path, headers={"Authorization": f"Bearer {VOICE_BRIDGE_TOKEN}"}, timeout=25, **kw)
    r.raise_for_status()
    return r.json()


def _vb_stt(utterance, language: str) -> str:
    r = requests.post(
        "https://api.openai.com/v1/audio/transcriptions",
        headers={"Authorization": f"Bearer {_vb_openai_key()}"},
        files={"file": ("speech.wav", _vb_wav_bytes(utterance), "audio/wav")},
        data={"model": os.environ.get("OPENAI_STT_MODEL", "whisper-1"), "language": (language or "en")[:2]}, timeout=30)
    r.raise_for_status()
    return (r.json().get("text") or "").strip()


def _vb_tts(text: str, voice: str) -> bytes:
    r = requests.post(
        "https://api.openai.com/v1/audio/speech",
        headers={"Authorization": f"Bearer {_vb_openai_key()}"},
        json={"model": os.environ.get("OPENAI_TTS_MODEL", "tts-1"), "input": text[:600], "voice": voice, "response_format": "pcm"}, timeout=30)
    r.raise_for_status()
    return _vb_pcm24k_to_48k(r.content)


# ── WebRTC pieces (need aiortc + av) ─────────────────────────────────────────
def _vb_track_class():
    import av
    from aiortc import MediaStreamTrack

    class TTSTrack(MediaStreamTrack):
        """Outgoing audio: plays queued speech, silence otherwise, paced at 20 ms."""
        kind = "audio"

        def __init__(self):
            super().__init__()
            self.buffer = bytearray()
            self._t0, self._n = None, 0

        @property
        def speaking(self) -> bool:
            return len(self.buffer) > 0

        def say(self, pcm48k: bytes):
            self.buffer.extend(pcm48k)

        async def recv(self):
            if self._t0 is None:
                self._t0 = time.time()
            self._n += 1
            wait = self._t0 + self._n * 0.02 - time.time()
            if wait > 0:
                await asyncio.sleep(wait)
            need = _VB_FRAME_SAMPLES * 2
            data = bytes(self.buffer[:need])
            del self.buffer[:need]
            data = data.ljust(need, b"\x00")
            frame = av.AudioFrame(format="s16", layout="mono", samples=_VB_FRAME_SAMPLES)
            frame.planes[0].update(data)
            frame.sample_rate = _VB_OUT_RATE
            frame.pts = (self._n - 1) * _VB_FRAME_SAMPLES
            frame.time_base = Fraction(1, _VB_OUT_RATE)
            return frame

    return TTSTrack


async def _vb_handle_call(call: dict):
    from aiortc import RTCPeerConnection, RTCSessionDescription
    import av

    loop = asyncio.get_running_loop()
    cid, started = call["meta_call_id"], time.time()
    voice, lang = call.get("voice", "alloy"), call.get("language", "en")
    pc, out = RTCPeerConnection(), _vb_track_class()()
    pc.addTrack(out)
    done = asyncio.Event()
    result = {"handoff": False, "terminate": False}

    async def speak(text: str):
        pcm = await loop.run_in_executor(None, _vb_tts, text, voice)
        out.say(pcm)

    async def listen(track):
        resampler = av.AudioResampler(format="s16", layout="mono", rate=_VB_STT_RATE)
        seg = _VbSegmenter()
        while not done.is_set():
            try:
                frame = await track.recv()
            except Exception:
                break
            if out.speaking:                 # half-duplex: ignore the caller while we talk (avoids echo loops)
                seg.reset()
                continue
            frames = resampler.resample(frame)
            for f in (frames if isinstance(frames, list) else [frames]):
                if f is None:
                    continue
                utt = seg.feed(f.to_ndarray().reshape(-1))
                if utt is None:
                    continue
                try:
                    text = await loop.run_in_executor(None, _vb_stt, utt, lang)
                    if not text:
                        continue
                    _vb_log.info("call %s caller: %s", cid[-6:], text)
                    turn = await loop.run_in_executor(
                        None, lambda: _vb_http("POST", "/api/voice-bridge/turn", json={"meta_call_id": cid, "text": text}))
                    await speak(turn["reply"])
                    if turn.get("handoff") or turn.get("end_call"):
                        result["handoff"], result["terminate"] = bool(turn.get("handoff")), True
                        while out.speaking:
                            await asyncio.sleep(0.1)
                        await asyncio.sleep(0.5)
                        done.set()
                        return
                except Exception as e:
                    _vb_log.error("call %s turn failed: %s", cid[-6:], e)

    @pc.on("track")
    def on_track(track):
        if track.kind == "audio":
            asyncio.ensure_future(listen(track))

    @pc.on("connectionstatechange")
    async def on_state():
        if pc.connectionState in ("failed", "closed", "disconnected"):
            done.set()

    try:
        await pc.setRemoteDescription(RTCSessionDescription(sdp=call["sdp_offer"], type="offer"))
        await pc.setLocalDescription(await pc.createAnswer())
        await loop.run_in_executor(None, lambda: _vb_http(
            "POST", "/api/voice-bridge/answer", json={"meta_call_id": cid, "sdp_answer": pc.localDescription.sdp}))
        await speak(call.get("greeting") or "Hello, how can I help?")
        try:
            await asyncio.wait_for(done.wait(), timeout=call.get("max_seconds", 300))
        except asyncio.TimeoutError:
            await speak("I'm sorry, we're out of time. A team member will follow up. Goodbye.")
            while out.speaking:
                await asyncio.sleep(0.1)
            result["terminate"] = True
    except Exception as e:
        _vb_log.error("call %s failed: %s", cid[-6:], e)
        result["terminate"] = True
    finally:
        try:
            await loop.run_in_executor(None, lambda: _vb_http("POST", "/api/voice-bridge/end", json={
                "meta_call_id": cid, "handoff": result["handoff"], "terminate_at_meta": result["terminate"],
                "duration_seconds": int(time.time() - started)}))
        except Exception as e:
            _vb_log.error("call %s end report failed: %s", cid[-6:], e)
        await pc.close()


async def _vb_main():
    loop = asyncio.get_running_loop()
    active = set()
    max_calls = int(os.environ.get("VOICE_BRIDGE_MAX_CALLS", "5"))
    _vb_log.info("voice bridge polling %s", _vb_app_url())
    while True:
        try:
            if len(active) < max_calls:
                data = await loop.run_in_executor(None, lambda: _vb_http("GET", "/api/voice-bridge/pending"))
                for call in data.get("calls", []):
                    t = asyncio.ensure_future(_vb_handle_call(call))
                    active.add(t)
                    t.add_done_callback(active.discard)
        except Exception as e:
            _vb_log.error("poll failed: %s", e)
        await asyncio.sleep(1.0)


def _vb_run_forever():
    """Entry point for `python app.py --voice-bridge`."""
    logging.basicConfig(level=logging.INFO, format="%(asctime)s %(levelname)s %(message)s")
    missing = [n for n, v in (("VOICE_BRIDGE_TOKEN", VOICE_BRIDGE_TOKEN), ("OPENAI_API_KEY", _vb_openai_key())) if not v]
    if missing or _vb_np is None:
        raise SystemExit("Voice bridge cannot start. Missing: " + ", ".join(missing + ([] if _vb_np else ["numpy"])))
    try:
        import aiortc, av  # noqa: F401
    except ImportError:
        raise SystemExit("Voice bridge needs:  pip install aiortc av numpy")
    asyncio.run(_vb_main())


def _vb_start_embedded_thread():
    """Opt-in (VOICE_BRIDGE_EMBEDDED=1). A file lock keeps it to ONE worker
    so two workers never claim the same call."""
    if os.environ.get("VOICE_BRIDGE_EMBEDDED") != "1" or not VOICE_BRIDGE_TOKEN or _vb_np is None:
        return
    try:
        import fcntl
        lock = open(os.path.join(tempfile.gettempdir(), "connectit_voice_bridge.lock"), "w")
        fcntl.flock(lock, fcntl.LOCK_EX | fcntl.LOCK_NB)
    except Exception:
        return                           # another worker already runs it (or no flock on this OS)

    def _runner():
        time.sleep(20)                   # let the web server finish booting first
        try:
            asyncio.run(_vb_main())
        except Exception as e:
            logging.error(f"[VOICE BRIDGE THREAD STOPPED] {e}")
        finally:
            lock.close()
    threading.Thread(target=_runner, name="voice-bridge", daemon=True).start()


_vb_start_embedded_thread()


# ════════════════════════════════════════════════════════════
# MARKETING CONSENT (STOP / START) + MARKETING MESSAGES API
# ════════════════════════════════════════════════════════════
_WA_STOP_WORDS  = {"stop", "unsubscribe", "optout", "opt out", "stop all", "stop messages", "stop promotions"}
_WA_START_WORDS = {"start", "subscribe", "optin", "opt in", "unstop"}


def _wa_norm_cmd(text: str) -> str:
    return re.sub(r"[^a-z ]", "", (text or "").lower()).strip()


def _wa_optout_key(wa_id: str) -> str:
    wa_id = (wa_id or "").strip().lstrip("+")
    return wa_id[:64] if _wa_is_bsuid(wa_id) else re.sub(r"\D", "", wa_id)


def _wa_is_opted_out(owner_uid, wa_id) -> bool:
    key = _wa_optout_key(wa_id)
    if not key:
        return False
    return WhatsAppMarketingOptOut.query.filter_by(owner_user_id=owner_uid, wa_id=key).first() is not None


def _wa_set_opt_out(owner_uid, wa_id, opted_out: bool, source="customer") -> None:
    key = _wa_optout_key(wa_id)
    if not key:
        return
    row = WhatsAppMarketingOptOut.query.filter_by(owner_user_id=owner_uid, wa_id=key).first()
    if opted_out and not row:
        db.session.add(WhatsAppMarketingOptOut(owner_user_id=owner_uid, wa_id=key, source=source))
    elif not opted_out and row:
        db.session.delete(row)
    db.session.commit()


def _wa_handle_marketing_keyword(owner_uid, sender_num, text) -> bool:
    """STOP / START as the WHOLE message. Records consent and confirms.
    Returns True when the message was a consent keyword (nothing else to do)."""
    cmd = _wa_norm_cmd(text)
    if cmd in _WA_STOP_WORDS:
        _wa_set_opt_out(owner_uid, sender_num, True)
        reply = "You're unsubscribed from promotional messages. Reply START any time to receive them again."
    elif cmd in _WA_START_WORDS:
        _wa_set_opt_out(owner_uid, sender_num, False)
        reply = "You're subscribed to promotional messages again. Reply STOP any time to unsubscribe."
    else:
        return False
    try:
        send_whatsapp_cloud_message(owner_uid, sender_num, reply)
        _inbox_log(owner_uid, "whatsapp", _wa_session_key(sender_num), "out", reply)
    except Exception as e:
        logging.error(f"[WA MARKETING KEYWORD REPLY ERROR] {e}")
    return True


def _wa_use_mm_api(owner_uid) -> bool:
    st = WhatsAppMarketingSettings.query.filter_by(owner_user_id=owner_uid).first()
    return bool(st and st.use_mm_api)


@app.route("/api/whatsapp-cloud/marketing/settings", methods=["GET", "POST"])
@csrf.exempt
def wa_marketing_settings():
    current_user = _get_current_user()
    if not current_user:
        return connectit_json_response({"error": "Login required"}, 401)
    uid = current_user["id"]
    st = WhatsAppMarketingSettings.query.filter_by(owner_user_id=uid).first()
