# ════════════════════════════════════════════════════════════
# ORDER STATUS MESSAGES + PAY-IN-CHAT
# Payment options offered inside the conversation are only the ones that
# settle the ERP invoice automatically when paid: Paynow mobile money
# (EcoCash / OneMoney push to the customer's phone) and a Razorpay
# hosted link (UPI / cards, India). Anything else goes out as the
# owner's own "other ways to pay" instructions.
# ════════════════════════════════════════════════════════════
def _wa_order_settings(owner_uid):
    return WhatsAppOrderMsgSettings.query.filter_by(owner_user_id=owner_uid).first()


def _wa_msg_customer(owner_uid, wa_id, text, template_name=None, template_params=None, language="en_US"):
    """Free-text when the 24h window is open; otherwise the owner's approved
    template (if they set one). Raises if neither can be delivered."""
    try:
        return send_whatsapp_cloud_message(owner_uid, wa_id, text)
    except Exception as free_err:
        if not template_name:
            raise
        comps = [{"type": "body", "parameters": [{"type": "text", "text": str(p)[:200]} for p in (template_params or [])]}]
        logging.info(f"[WA MSG] free text failed ({free_err}); using template {template_name}")
        return send_whatsapp_template_message(owner_uid, wa_id, template_name, language, comps)


def _wa_send_cta_url(owner_uid, to, body_text, button_text, url):
    creds = _whatsapp_cloud_creds_for_user(owner_uid)
    if not creds["phone_number_id"] or not creds["access_token"]:
        raise ValueError("WhatsApp Cloud API not configured")
    resp = requests.post(
        f"https://graph.facebook.com/{WHATSAPP_CLOUD_API_VERSION}/{creds['phone_number_id']}/messages",
        headers={"Authorization": f"Bearer {creds['access_token']}", "Content-Type": "application/json"},
        json={"messaging_product": "whatsapp", "to": re.sub(r"\D", "", to or ""), "type": "interactive",
              "interactive": {"type": "cta_url", "body": {"text": body_text[:1024]},
                              "action": {"name": "cta_url", "parameters": {"display_text": button_text[:20], "url": url}}}},
        timeout=15)
    data = resp.json()
    if not resp.ok:
        raise ValueError((data.get("error") or {}).get("message", "CTA message failed."))
    return data


_WA_ORDER_STATUS_TEXT = {
    "confirmed": "is confirmed. We'll update you when it's ready.",
    "fulfilled": "is ready / on its way. Thank you!",
    "cancelled": "has been cancelled. Message us if you have any questions.",
}


def _wa_order_status_job(app_ref, owner_uid, order_id, status):
    app_ref = app_ref or app
    with app_ref.app_context():
        try:
            st = _wa_order_settings(owner_uid)
            if not st or not st.notify_order_status or status not in _WA_ORDER_STATUS_TEXT:
                return
            order = WhatsAppCatalogOrder.query.filter_by(id=order_id, owner_user_id=owner_uid).first()
            if not order or not order.customer_wa_id:
                return
            phrase = _WA_ORDER_STATUS_TEXT[status]
            text = f"Your order #{order.id} {phrase}"
            _wa_msg_customer(owner_uid, order.customer_wa_id, text, st.status_template,
                             [f"#{order.id}", phrase], st.language or "en_US")
            _inbox_log(owner_uid, "whatsapp", _wa_session_key(order.customer_wa_id), "out", text)
        except Exception as e:
            db.session.rollback()
            logging.error(f"[WA ORDER STATUS NOTIFY ERROR] {e}")


def _wa_receipt_job(app_ref, owner_uid, invoice_id, customer_id, total, currency, invoice_number):
    app_ref = app_ref or app
    with app_ref.app_context():
        try:
            st = _wa_order_settings(owner_uid)
            if not st or not st.notify_payment_receipt or not customer_id:
                return
            cust = ErpCustomer.query.filter_by(id=customer_id, owner_user_id=owner_uid).first()
            if not cust or not cust.phone:
                return
            amount_txt = f"{total:g} {currency}"
            text = f"Payment received: {amount_txt} for invoice {invoice_number}. Thank you!"
            _wa_msg_customer(owner_uid, cust.phone, text, st.receipt_template, [amount_txt, invoice_number],
                             st.language or "en_US")
            _inbox_log(owner_uid, "whatsapp", _wa_session_key(cust.phone), "out", text)
        except Exception as e:
            db.session.rollback()
            logging.error(f"[WA RECEIPT NOTIFY ERROR] {e}")


def _paynow_push_invoice(owner_uid, inv, phone, method):
    """Server-side twin of /api/payments/paynow/initiate for one ERP invoice:
    pushes the mobile-money prompt to `phone`. The reference encodes the
    invoice id, so Paynow's callback settles it automatically.
    Returns (ok, error)."""
    creds = _owner_creds(owner_uid, "paynow", "integration_id", "integration_key")
    if not creds:
        return False, "Paynow is not connected for this business."
    balance = round((inv.total or 0) - (inv.amount_paid or 0), 2)
    if not validate_amount(balance, min_val=0.20, max_val=5000.00):
        return False, "This invoice amount can't be paid through mobile money."
    phone = sanitize_phone(phone)
    if not phone or method not in ("ecocash", "onemoney"):
        return False, "A valid phone number and method are required."
    fields = {
        "id": creds["integration_id"], "reference": f"INV{inv.id}-{generate_tx_ref('PYNW')}",
        "amount": f"{balance:.2f}", "additionalinfo": f"Invoice {inv.invoice_number}"[:255],
        "returnurl": f"{APP_BASE_URL.rstrip('/')}/?payment=success",
        "resulturl": f"{APP_BASE_URL.rstrip('/')}/api/payments/paynow/webhook",
        "authemail": "customer@connectit.com", "phone": phone.lstrip("+"), "method": method, "status": "Message",
    }
    fields["hash"] = _paynow_hash(list(fields.values()), creds["integration_key"])
    try:
        resp = requests.post(f"{PAYNOW_BASE_URL}/remotetransaction", data=fields, timeout=15)
        parsed = dict(urllib.parse.parse_qsl(resp.text))
        if parsed.get("status", "").lower() != "ok" or not _paynow_verify_form(parsed, creds["integration_key"]):
            return False, parsed.get("error") or parsed.get("Error") or "Paynow rejected the request."
        return True, None
    except Exception as e:
        return False, str(e)


def _razorpay_link_for_invoice(owner_uid, inv, customer):
    """Hosted UPI/card link whose reference encodes the invoice id, so the
    Razorpay webhook settles it. Returns (url, error)."""
    rc = _owner_creds(owner_uid, "razorpay", "key_id", "key_secret")
    if not rc:
        return None, "Razorpay is not connected for this business."
    key_id, key_secret = rc["key_id"], rc["key_secret"]
    balance = round((inv.total or 0) - (inv.amount_paid or 0), 2)
    try:
        resp = requests.post("https://api.razorpay.com/v1/payment_links", auth=(key_id, key_secret), timeout=15, json={
            "amount": int(round(balance * 100)), "currency": (inv.currency or "INR").upper(),
            "description": f"Invoice {inv.invoice_number}"[:255],
            "reference_id": f"INV{inv.id}-{generate_tx_ref('RZP')}",
            "customer": {"name": (customer.name if customer else "Customer"), "contact": (customer.phone if customer else "")},
            "notify": {"sms": False, "email": False}})
        d = resp.json()
        if resp.ok and d.get("short_url"):
            return d["short_url"], None
        return None, (d.get("error") or {}).get("description", "Razorpay error")
    except Exception as e:
        return None, str(e)


def wa_send_payment_request(owner_uid, invoice_id, provider=None) -> dict:
    inv = ErpInvoice.query.filter_by(id=invoice_id, owner_user_id=owner_uid).first() if invoice_id else None
    if not inv:
        return {"ok": False, "error": "Invoice not found."}
    balance = round((inv.total or 0) - (inv.amount_paid or 0), 2)
    if inv.status in ("paid", "void", "draft") or balance <= 0:
        return {"ok": False, "error": "This invoice has no outstanding balance."}
    cust = ErpCustomer.query.filter_by(id=inv.customer_id, owner_user_id=owner_uid).first() if inv.customer_id else None
    if not cust or not cust.phone:
        return {"ok": False, "error": "The invoice's customer has no phone number on file."}
    st = _wa_order_settings(owner_uid)
    sent = []
    head = f"Invoice {inv.invoice_number}: {balance:g} {inv.currency} due."
    try:
        # One hosted link, from the first connected provider that can create it.
        order = [provider] if provider in ("razorpay", "stripe", "flutterwave") else (
            (["razorpay"] if (inv.currency or "").upper() == "INR" else []) + ["stripe", "flutterwave", "razorpay"])
        link = None
        for p in dict.fromkeys(order):
            link = (_razorpay_link_for_invoice(owner_uid, inv, cust)[0] if p == "razorpay"
                    else _invoice_link_create(owner_uid, inv, cust, p)[0])
            if link:
                break
        if link:
            _wa_send_cta_url(owner_uid, cust.phone, head + " Pay securely online:", "Pay now", link)
            sent.append("online_link")
        buttons = []
        if _owner_creds(owner_uid, "paynow", "integration_id", "integration_key"):
            buttons += [{"id": f"pay_ecocash:{inv.id}", "title": "Pay with EcoCash"},
                        {"id": f"pay_onemoney:{inv.id}", "title": "Pay with OneMoney"}]
        if st and st.payment_instructions:
            buttons.append({"id": f"pay_info:{inv.id}", "title": "Other ways to pay"})
        if buttons:
            send_whatsapp_button_message(owner_uid, cust.phone, head + " How would you like to pay?", buttons[:3])
            sent.append("buttons")
    except Exception as e:
        return {"ok": False, "error": str(e), "sent": sent}
    if not sent:
        return {"ok": False, "error": "No payment method is available. Connect Paynow or Razorpay, or add payment instructions."}
    return {"ok": True, "sent": sent}


def _wa_payment_handle_button_reply(owner_uid, sender_num, button_id) -> bool:
    m = re.match(r"^pay_(ecocash|onemoney|info):(\d+)$", button_id or "")
    if not m or not owner_uid:
        return False
    kind, inv_id = m.group(1), int(m.group(2))

    def say(t):
        try:
            send_whatsapp_cloud_message(owner_uid, sender_num, t)
        except Exception as e:
            logging.error(f"[WA PAYMENT REPLY ERROR] {e}")

    inv = ErpInvoice.query.filter_by(id=inv_id, owner_user_id=owner_uid).first()
    cust = ErpCustomer.query.filter_by(id=inv.customer_id, owner_user_id=owner_uid).first() if inv and inv.customer_id else None
    # Only the invoice's own customer may act on it (also keeps balances private).
    if not inv or not cust or _wa_phone_tail(cust.phone) != _wa_phone_tail(sender_num):
        say("Sorry, we couldn't match that invoice to this number. Please contact us directly.")
        return True
    if inv.status in ("paid", "void") or (inv.total or 0) - (inv.amount_paid or 0) <= 0:
        say("That invoice is already settled. Thank you!")
        return True
    if kind == "info":
        st = _wa_order_settings(owner_uid)
        say((st.payment_instructions if st and st.payment_instructions else "Please contact us for payment details."))
        return True
    ok, err = _paynow_push_invoice(owner_uid, inv, sender_num, kind)
    if ok:
        say(f"A {'EcoCash' if kind == 'ecocash' else 'OneMoney'} prompt is on its way to your phone. Enter your PIN to pay, and we'll confirm here once it goes through.")
    else:
        logging.error(f"[WA PAYNOW PUSH FAILED] {err}")
        say("We couldn't start that payment. Please try another method or contact us.")
    return True


def _automation_action_send_whatsapp_payment_request(owner_user_id, org_id, config, context):
    inv = _automation_render(config.get("invoice_id"), context)
    try:
        inv = int(inv)
    except (TypeError, ValueError):
        return {"ok": False, "error": "invoice_id must be a number."}
    return wa_send_payment_request(owner_user_id, inv)


@app.route("/api/whatsapp-cloud/payments/request", methods=["POST"])
@csrf.exempt
def wa_payment_request_endpoint():
    current_user = _get_current_user()
    if not current_user:
        return connectit_json_response({"error": "Login required"}, 401)
    if not _csrf_ok():
        return connectit_json_response({"error": "CSRF token invalid or missing."}, 403)
    d = request.get_json(silent=True) or {}
    res = wa_send_payment_request(current_user["id"], d.get("invoice_id"), (d.get("provider") or "").lower() or None)
    return connectit_json_response(res, 200 if res.get("ok") else 400)


@app.route("/api/whatsapp-cloud/order-messages/settings", methods=["GET", "POST"])
@csrf.exempt
def wa_order_msg_settings():
    current_user = _get_current_user()
    if not current_user:
        return connectit_json_response({"error": "Login required"}, 401)
    uid = current_user["id"]
    st = _wa_order_settings(uid)
    if request.method == "POST":
        if not _csrf_ok():
            return connectit_json_response({"error": "CSRF token invalid or missing."}, 403)
        d = request.get_json(silent=True) or {}
        if not st:
            st = WhatsAppOrderMsgSettings(owner_user_id=uid)
            db.session.add(st)
        for k in ("notify_order_status", "notify_payment_receipt"):
            if k in d:
                setattr(st, k, bool(d[k]))
        for k, n in (("status_template", 100), ("receipt_template", 100), ("payment_instructions", 600)):
            if k in d:
                setattr(st, k, (str(d[k]).strip()[:n] or None))
        if d.get("language"):
            st.language = re.sub(r"[^A-Za-z_]", "", str(d["language"]))[:16] or "en_US"
        db.session.commit()
    pn_ok = bool(_owner_creds(uid, "paynow", "integration_id", "integration_key"))
    rz_ok = bool(_owner_creds(uid, "razorpay", "key_id", "key_secret"))
    st_ok = bool(_owner_creds(uid, "stripe", "secret_key"))
    fw_ok = bool(_owner_creds(uid, "flutterwave", "secret_key"))
    return connectit_json_response({
        "ok": True, "stripe_configured": st_ok, "flutterwave_configured": fw_ok,
        "settings": {"notify_order_status": bool(st and st.notify_order_status),
                     "notify_payment_receipt": bool(st and st.notify_payment_receipt),
                     "status_template": st.status_template if st else None,
                     "receipt_template": st.receipt_template if st else None,
                     "language": st.language if st else "en_US",
                     "payment_instructions": st.payment_instructions if st else None},
        "paynow_configured": pn_ok, "razorpay_configured": rz_ok})


# ════════════════════════════════════════════════════════════
# STRIPE + FLUTTERWAVE INVOICE LINKS (BYOK-only) AND SETTLEMENT
# These use ONLY the business's own keys. There is deliberately no
# fallback to the platform's keys: a payment taken with a platform key
# would land in the platform's account while marking the business's
# invoice paid.
# ════════════════════════════════════════════════════════════
def _owner_creds(owner_uid, provider, *fields):
    """The business's own saved credentials for `provider`, or None if any
    field is missing. Never falls back to platform-wide keys."""
    c = get_user_credentials(owner_uid, provider) or {}
    return {f: c[f] for f in fields} if all(c.get(f) for f in fields) else None


def _invoice_balance(inv) -> float:
    return round((inv.total or 0) - (inv.amount_paid or 0), 2)


def _invoice_link_create(owner_uid, inv, cust, provider):
    """Returns (url, error)."""
    balance = _invoice_balance(inv)
    cur = (inv.currency or "USD").upper()
    ref = f"INV{inv.id}-{generate_tx_ref('LNK')}"
    if provider == "stripe":
        creds = _owner_creds(owner_uid, "stripe", "secret_key")
        if not creds or not STRIPE_AVAILABLE:
            return None, "Stripe is not connected."
        try:
            import stripe as stripe_lib
            session = stripe_lib.checkout.Session.create(
                api_key=creds["secret_key"], mode="payment", payment_method_types=["card"],
                line_items=[{"price_data": {"currency": cur.lower(), "product_data": {"name": f"Invoice {inv.invoice_number}"},
                                            "unit_amount": int(round(balance * 100))}, "quantity": 1}],
                success_url=f"{APP_BASE_URL.rstrip('/')}/pay/invoice-return?ref={ref}",
                cancel_url=f"{APP_BASE_URL.rstrip('/')}/?payment=cancelled",
                metadata={"invoice_link": ref, "business_user_id": str(owner_uid)})
            provider_ref, url = session.id, session.url
        except Exception as e:
            return None, str(e)
    elif provider == "flutterwave":
        creds = _owner_creds(owner_uid, "flutterwave", "secret_key")
        if not creds:
            return None, "Flutterwave is not connected."
        try:
            r = requests.post("https://api.flutterwave.com/v3/payments", timeout=15,
                              headers={"Authorization": f"Bearer {creds['secret_key']}"},
                              json={"tx_ref": ref, "amount": str(balance), "currency": cur,
                                    "redirect_url": f"{APP_BASE_URL.rstrip('/')}/pay/invoice-return?ref={ref}",
                                    "customer": {"email": (cust.email if cust and cust.email else "customer@example.com"),
                                                 "name": (cust.name if cust else "Customer"),
                                                 "phonenumber": (cust.phone if cust else "")},
                                    "customizations": {"title": f"Invoice {inv.invoice_number}"}})
            body = r.json()
            if not (r.ok and body.get("status") == "success"):
                return None, body.get("message", "Flutterwave request failed.")
            provider_ref, url = ref, body["data"]["link"]
        except Exception as e:
            return None, str(e)
    else:
        return None, "Unknown provider."
    db.session.add(InvoicePaymentLink(owner_user_id=owner_uid, invoice_id=inv.id, provider=provider, reference=ref,
                                      provider_ref=provider_ref, currency=cur, amount_expected=balance, url=url))
    db.session.commit()
    return url, None


def _invoice_link_confirm(link):
    """Ask the provider (with the business's own key) whether this link was
    paid. Returns (paid_amount, error); paid_amount is None if not paid."""
    if link.provider == "stripe":
        creds = _owner_creds(link.owner_user_id, "stripe", "secret_key")
        if not creds or not STRIPE_AVAILABLE:
            return None, "Stripe key unavailable."
        try:
            import stripe as stripe_lib
            s = stripe_lib.checkout.Session.retrieve(link.provider_ref, api_key=creds["secret_key"])
            if s.get("payment_status") != "paid":
                return None, None
            if (s.get("currency") or "").upper() != link.currency:
                return None, "currency mismatch"
            return (s.get("amount_total") or 0) / 100.0, None
        except Exception as e:
            return None, str(e)
    creds = _owner_creds(link.owner_user_id, "flutterwave", "secret_key")
    if not creds:
        return None, "Flutterwave key unavailable."
    try:
        r = requests.get("https://api.flutterwave.com/v3/transactions/verify_by_reference",
                         params={"tx_ref": link.provider_ref}, headers={"Authorization": f"Bearer {creds['secret_key']}"}, timeout=15)
        b = r.json()
        tx = b.get("data") or {}
        if b.get("status") != "success" or tx.get("status") != "successful" or tx.get("tx_ref") != link.provider_ref:
            return None, None
        if (tx.get("currency") or "").upper() != link.currency:
            return None, "currency mismatch"
        return float(tx.get("amount") or 0), None
    except Exception as e:
        return None, str(e)


def _invoice_link_check(link) -> dict:
    """Confirm with the provider, then settle the invoice EXACTLY once."""
    if link.status == "paid":
        return {"status": "paid"}
    amount, err = _invoice_link_confirm(link)
    if err:
        logging.error(f"[INVOICE LINK CHECK] {link.provider} {link.reference}: {err}")
        return {"status": link.status, "error": err}
    if amount is None:
        return {"status": "pending"}
    # Claim the transition atomically so webhook + return page + sweep can't double-apply.
    claimed = (InvoicePaymentLink.query.filter_by(id=link.id, status="pending")
               .update({"status": "paid", "paid_at": datetime.utcnow()}, synchronize_session=False))
    if not claimed:
        db.session.rollback()
        return {"status": "paid"}
    inv = ErpInvoice.query.filter_by(id=link.invoice_id, owner_user_id=link.owner_user_id).first()
    if inv and inv.status != "paid":
        credit = min(amount, max(_invoice_balance(inv), 0))
        if credit > 0:
            _erp_apply_invoice_payment(inv, credit, link.provider)
        if amount + 0.01 < link.amount_expected:
            logging.warning(f"[INVOICE LINK] part payment {amount} of {link.amount_expected} on {link.reference}")
    db.session.commit()
    return {"status": "paid"}


def _invoice_link_webhook_hint(provider, provider_ref):
    """A provider webhook arrived: use it only as a nudge to verify."""
    try:
        link = InvoicePaymentLink.query.filter_by(provider=provider, provider_ref=provider_ref or "", status="pending").first()
        if link:
            _invoice_link_check(link)
    except Exception as e:
        db.session.rollback()
        logging.error(f"[INVOICE LINK WEBHOOK HINT ERROR] {e}")


def invoice_links_sweep(owner_uid=None, max_age_days=3, limit=100) -> int:
    q = InvoicePaymentLink.query.filter(InvoicePaymentLink.status == "pending",
                                        InvoicePaymentLink.created_at >= datetime.utcnow() - timedelta(days=max_age_days))
    if owner_uid:
        q = q.filter_by(owner_user_id=owner_uid)
    n = 0
    for link in q.order_by(InvoicePaymentLink.id.asc()).limit(limit).all():
        try:
            if _invoice_link_check(link).get("status") == "paid":
                n += 1
        except Exception as e:
            db.session.rollback()
            logging.error(f"[INVOICE LINK SWEEP ERROR] {e}")
    return n


@app.route("/pay/invoice-return", methods=["GET"])
def invoice_link_return():
    """Where Stripe/Flutterwave send the customer after paying. Verifies with
    the provider right now, so the invoice is settled by the time they land."""
    ref = (request.args.get("ref") or "")[:80]
    link = InvoicePaymentLink.query.filter_by(reference=ref).first()
    status = "pending"
    if link:
        try:
            status = _invoice_link_check(link).get("status", "pending")
        except Exception as e:
            db.session.rollback()
            logging.error(f"[INVOICE LINK RETURN ERROR] {e}")
    return redirect(f"{APP_BASE_URL.rstrip('/')}/?payment={'success' if status == 'paid' else 'pending'}")


@app.route("/api/whatsapp-cloud/payments/links", methods=["GET"])
def wa_payment_links_list():
    current_user = _get_current_user()
    if not current_user:
        return connectit_json_response({"error": "Login required"}, 401)
    invoice_links_sweep(current_user["id"], limit=20)       # refresh anything still pending
    rows = (InvoicePaymentLink.query.filter_by(owner_user_id=current_user["id"])
            .order_by(InvoicePaymentLink.id.desc()).limit(50).all())
    return connectit_json_response({"ok": True, "links": [r.to_dict() for r in rows]})


@app.route("/api/whatsapp-cloud/calling/connect", methods=["POST"])
@csrf.exempt
def whatsapp_cloud_calling_connect():
    """Initiates (or answers, via action='pre_accept'/'accept') a WebRTC
    call session. Requires `to` (customer wa_id) and `sdp` (the caller's
    own SDP offer, generated client-side by RTCPeerConnection) — Meta
    responds with the SDP answer to feed back into that same
    RTCPeerConnection. `call_id` is required when answering an inbound
    call rather than placing an outbound one."""
    current_user = _get_current_user()
    if not current_user:
        return connectit_json_response({"error": "Login required"}, 401)
    creds, err = _whatsapp_calling_creds_or_error(current_user)
    if err:
        return err
    data = request.get_json(force=True) or {}
    to = re.sub(r"\D", "", data.get("to", ""))
    sdp = (data.get("sdp") or "").strip()
    action = (data.get("action") or "connect").strip()
    call_id = (data.get("call_id") or "").strip()
    if action not in ("connect", "pre_accept", "accept"):
        return connectit_json_response({"error": "action must be connect, pre_accept, or accept."}, 400)
    if not sdp:
        return connectit_json_response({"error": "sdp (this client's WebRTC offer/answer) is required."}, 400)
    if action == "connect" and not to:
        return connectit_json_response({"error": "to (recipient wa_id) is required to place a call."}, 400)
    if action in ("pre_accept", "accept") and not call_id:
        return connectit_json_response({"error": "call_id is required to answer an inbound call."}, 400)
    payload = {
        "messaging_product": "whatsapp",
        "action": action,
        "session": {"sdp_type": "offer" if action == "connect" else "answer", "sdp": sdp},
    }
    if action == "connect":
        payload["to"] = to
    else:
        payload["call_id"] = call_id
    try:
        resp = requests.post(
            f"https://graph.facebook.com/{WHATSAPP_CLOUD_API_VERSION}/{creds['phone_number_id']}/calls",
            headers={"Authorization": f"Bearer {creds['access_token']}", "Content-Type": "application/json"},
            json=payload,
            timeout=20,
        )
        body = resp.json()
        if resp.status_code >= 400:
            return connectit_json_response(
                {"error": (body.get("error") or {}).get("message", "Call request failed.")}, 502)
        result_call_id = body.get("calls", [{}])[0].get("id") if body.get("calls") else body.get("id")
        logging.info(f"[WA CALL {action.upper()}] user={current_user['id']} to={to or call_id}")
        # Log outbound calls the same way inbound ones get logged from the
        # webhook, so /api/whatsapp-cloud/calls/history shows both
        # directions in one place. Answering an inbound call (pre_accept/
        # accept) updates the row the webhook already created instead.
        try:
            if action == "connect" and result_call_id:
                db.session.add(WhatsAppCall(
                    owner_user_id=current_user["id"], meta_call_id=str(result_call_id)[:128],
                    direction="outbound", phone_number_id=creds["phone_number_id"][:64] if creds["phone_number_id"] else None,
                    counterparty_wa_id=to[:32] or None, status="ringing",
                ))
                if data.get("task_id"):
                    _task = WhatsAppCallTask.query.filter_by(id=data.get("task_id"), owner_user_id=current_user["id"]).first()
                    if _task:
                        _task.meta_call_id = str(result_call_id)[:128]
                db.session.commit()
            elif action in ("pre_accept", "accept") and call_id:
                existing_call = WhatsAppCall.query.filter_by(meta_call_id=call_id).first()
                if existing_call:
                    existing_call.status = "connected"
                    existing_call.sdp_offer = None
                    db.session.commit()
        except Exception as log_err:
            db.session.rollback()
            logging.error(f"[WA CALL LOG ERROR] {log_err}")
        return connectit_json_response({"ok": True, "call_id": result_call_id, "raw": body})
    except Exception as e:
        logging.error(f"[WA CALL CONNECT ERROR] {e}")
        return connectit_json_response({"error": str(e)}, 500)


@app.route("/api/whatsapp-cloud/calling/terminate", methods=["POST"])
@csrf.exempt
def whatsapp_cloud_calling_terminate():
    """Ends an active or ringing call. Also used to reject an inbound
    call by passing the same call_id before accepting it."""
    current_user = _get_current_user()
    if not current_user:
        return connectit_json_response({"error": "Login required"}, 401)
    creds, err = _whatsapp_calling_creds_or_error(current_user)
    if err:
        return err
    data = request.get_json(force=True) or {}
    call_id = (data.get("call_id") or "").strip()
    if not call_id:
        return connectit_json_response({"error": "call_id is required."}, 400)
    try:
        resp = requests.post(
            f"https://graph.facebook.com/{WHATSAPP_CLOUD_API_VERSION}/{creds['phone_number_id']}/calls",
            headers={"Authorization": f"Bearer {creds['access_token']}", "Content-Type": "application/json"},
            json={"messaging_product": "whatsapp", "call_id": call_id, "action": "terminate"},
            timeout=15,
        )
        body = resp.json()
        if resp.status_code >= 400:
            return connectit_json_response(
                {"error": (body.get("error") or {}).get("message", "Could not terminate the call.")}, 502)
        try:
            existing_call = WhatsAppCall.query.filter_by(meta_call_id=call_id).first()
            if existing_call:
                existing_call.status = "terminated"
                existing_call.sdp_offer = None
                db.session.commit()
        except Exception as log_err:
            db.session.rollback()
            logging.error(f"[WA CALL LOG ERROR] {log_err}")
        logging.info(f"[WA CALL TERMINATE] user={current_user['id']} call_id={call_id}")
        return connectit_json_response({"terminated": True})
    except Exception as e:
        logging.error(f"[WA CALL TERMINATE ERROR] {e}")
        return connectit_json_response({"error": str(e)}, 500)


# ════════════════════════════════════════════════════════════
# WHATSAPP INBOUND CALL HANDLING — an inbound call arrives at the
# /whatsapp-cloud/webhook (field="calls") with an SDP offer that only a
# human operator's browser can actually answer (answering means opening
# THIS business's own microphone). These endpoints let the frontend poll
# for a ringing call, then post back a browser-generated SDP answer to
# accept it, or reject it outright — completing the loop the webhook
# handler above starts.
# ════════════════════════════════════════════════════════════

@app.route("/api/whatsapp-cloud/calls/incoming", methods=["GET"])
def whatsapp_cloud_calls_incoming():
    """Polls for calls currently ringing on this user's number(s). The
    frontend is expected to poll this every few seconds while the
    Business Calling panel is open."""
    current_user = _get_current_user()
    if not current_user:
        return connectit_json_response({"error": "Login required"}, 401)
    try:
        # If the voice bridge hasn't claimed a call within 15s (bridge down),
        # hand it to the humans instead of letting it ring out.
        (WhatsAppCall.query.filter_by(owner_user_id=current_user["id"], direction="inbound", status="agent_queued")
         .filter(WhatsAppCall.updated_at < datetime.utcnow() - timedelta(seconds=15))
         .update({"status": "ringing"}, synchronize_session=False))
        db.session.commit()
        calls = (WhatsAppCall.query
                 .filter_by(owner_user_id=current_user["id"], direction="inbound", status="ringing")
                 .order_by(WhatsAppCall.created_at.desc()).limit(10).all())
        return connectit_json_response({"calls": [c.to_dict(include_sdp=True) for c in calls]})
    except Exception as e:
        logging.error(f"[WA CALLS INCOMING ERROR] {e}")
        return connectit_json_response({"error": str(e)}, 500)


