@app.route("/api/contact-lists/<int:list_id>/members", methods=["POST"])
@csrf.exempt
def contact_list_members_add(list_id):
    """Body: either {"crm_contact_id": N} to pull a live CRM contact in,
    or {"crm_contact_ids": [N, ...]} to add several at once, or
    {"name","phone","email"} for a standalone manual entry."""
    if not _csrf_ok():
        return connectit_json_response({"error": "CSRF token invalid or missing."}, 403)
    user = _get_current_user()
    if not user:
        return connectit_json_response({"error": "Login required"}, 401)
    cl = ContactList.query.filter_by(id=list_id, user_id=user["id"]).first()
    if not cl:
        return connectit_json_response({"error": "List not found."}, 404)
    data = request.get_json(silent=True) or {}

    crm_ids = data.get("crm_contact_ids")
    if crm_ids is None and data.get("crm_contact_id"):
        crm_ids = [data.get("crm_contact_id")]

    added = []
    if crm_ids:
        existing = {m.crm_contact_id for m in ContactListMember.query.filter_by(list_id=cl.id).all() if m.crm_contact_id}
        for cid in crm_ids:
            if cid in existing:
                continue
            contact = CrmContact.query.filter_by(id=cid, user_id=user["id"]).first()
            if not contact:
                continue
            m = ContactListMember(list_id=cl.id, crm_contact_id=contact.id)
            db.session.add(m)
            added.append(m)
    else:
        name  = (data.get("name") or "").strip()
        phone = sanitize_phone(data.get("phone")) if data.get("phone") else None
        email = sanitize_email(data.get("email")) if data.get("email") else None
        if not name or (not phone and not email):
            return connectit_json_response({"error": "Name plus a phone or email is required for a manual entry."}, 400)
        m = ContactListMember(list_id=cl.id, name=name, phone=phone, email=email)
        db.session.add(m)
        added.append(m)

    db.session.commit()
    return connectit_json_response({"added": [m.to_dict() for m in added]}, 201)


