# ════════════════════════════════════════════════════════════
# TEMPLATE BROADCAST TO A SAVED CONTACT LIST — real "many
# individual sends": this loop fires one genuine outbound API call
# per list member (WhatsApp Cloud template send / Twilio SMS /
# SMTP email, reusing the exact same functions already used for
# single-recipient sends), and records what actually happened to
# each one in TemplateBroadcastRecipient. There is no group-blast
# call on any of these providers being simulated here — WhatsApp
# Cloud API only accepts one `to` number per request, Twilio the
# same, and SMTP is dispatched per message so each recipient gets
# their own envelope. Capped per HTTP call since each send is a
# blocking round-trip inside one request; a larger list finishes
# across a few calls, same pattern as the existing product-broadcast
# (Stage 312) cap.
# ════════════════════════════════════════════════════════════

TEMPLATE_BROADCAST_MAX_PER_CALL = 100


def _render_personalized(text, name):
    if not text:
        return text
    first_name = (name or "").split(" ")[0] if name else ""
    return text.replace("{name}", name or "").replace("{first_name}", first_name)


@app.route("/api/broadcast/template-send", methods=["POST"])
@csrf.exempt
def broadcast_template_send():
    """Body:
      list_id       (required) — a ContactList this user owns
      channel       (required) — "whatsapp" | "sms" | "email"
      offset        (optional) — resume point for lists bigger than
                     TEMPLATE_BROADCAST_MAX_PER_CALL; call again with
                     the returned next_offset to reach the rest
      WhatsApp: template_name, language_code (default en_US),
                components (optional Meta-format list, applied
                identically to every recipient — templates whose
                {{1}} etc need to vary a real name should keep that
                variable out of the header/body and rely on the
                template's own personalization slot, same limitation
                as the existing single-send endpoint)
      SMS:      message (supports {name}/{first_name})
      Email:    subject, body (supports {name}/{first_name})
    """
    if not _csrf_ok():
        return connectit_json_response({"error": "CSRF token invalid or missing."}, 403)
    user = _get_current_user()
    if not user:
        return connectit_json_response({"error": "Login required"}, 401)
    data = request.get_json(silent=True) or {}

    list_id = data.get("list_id")
    channel = (data.get("channel") or "").strip().lower()
    if channel not in ("whatsapp", "sms", "email"):
        return connectit_json_response({"error": "channel must be whatsapp, sms, or email."}, 400)
    cl = ContactList.query.filter_by(id=list_id, user_id=user["id"]).first()
    if not cl:
        return connectit_json_response({"error": "Contact list not found."}, 404)

    all_members = ContactListMember.query.filter_by(list_id=cl.id).order_by(ContactListMember.id.asc()).all()
    if not all_members:
        return connectit_json_response({"error": "This contact list has no members yet."}, 400)

    offset = int(data.get("offset") or 0)
    batch = all_members[offset: offset + TEMPLATE_BROADCAST_MAX_PER_CALL]
    if not batch:
        return connectit_json_response({"error": "offset is beyond the end of this list."}, 400)

    template_name = (data.get("template_name") or "").strip() or None
    language_code = (data.get("language_code") or "en_US").strip()
    components    = data.get("components") or []
    subject       = (data.get("subject") or "").strip()
    message       = (data.get("message") or "").strip()
    body          = (data.get("body") or "").strip()

    if channel == "whatsapp" and not template_name:
        return connectit_json_response({"error": "template_name is required for a WhatsApp broadcast — pick one of your approved templates."}, 400)
    if channel == "sms" and not message:
        return connectit_json_response({"error": "message is required for an SMS broadcast."}, 400)
    if channel == "email" and (not subject or not body):
        return connectit_json_response({"error": "subject and body are required for an email broadcast."}, 400)

    bc = TemplateBroadcast(
        user_id=user["id"], list_id=cl.id, channel=channel,
        template_name=template_name, subject=subject or None,
        body_preview=(f"{template_name} ({language_code})" if channel == "whatsapp" else (message or body))[:2000],
        total_recipients=len(all_members),
    )
    db.session.add(bc)
    db.session.commit()

    active_client, active_wa_number = None, None
    if channel == "sms":
        active_client, active_wa_number, _ = get_twilio_client_for_user(user["id"])

    sent, failed, skipped = 0, 0, 0
    use_mm_api = (channel == "whatsapp") and _wa_use_mm_api(user["id"])
    for member in batch:
        name, phone, email = member.resolved()
        rec = TemplateBroadcastRecipient(broadcast_id=bc.id, name=name, phone=phone, email=email)
        try:
            if channel == "whatsapp":
                if not phone:
                    raise ValueError("No phone number on file for this contact.")
                if _wa_is_opted_out(user["id"], phone):
                    rec.status, rec.error = "skipped", "Contact opted out of marketing messages."
                    skipped += 1
                    db.session.add(rec)
                    continue
                result = send_whatsapp_template_message(user["id"], phone, template_name, language_code, components,
                                                        marketing_api=use_mm_api)
                rec.provider_message_id = ((result.get("messages") or [{}])[0]).get("id")
            elif channel == "sms":
                if not phone:
                    raise ValueError("No phone number on file for this contact.")
                if not (active_client and active_wa_number):
                    raise ValueError("No SMS provider configured — connect Twilio in Integrations first.")
                twilio_msg = active_client.messages.create(
                    body=_render_personalized(message, name), from_=active_wa_number, to=phone)
                rec.provider_message_id = getattr(twilio_msg, "sid", None)
            else:  # email
                if not email:
                    raise ValueError("No email address on file for this contact.")
                if not (SMTP_USER and SMTP_PASS):
                    raise ValueError("No email provider configured — set SMTP credentials first.")
                msg = MIMEMultipart("alternative")
                msg["Subject"] = subject
                msg["From"]    = f"Connect It <{SMTP_USER}>"
                msg["To"]      = email
                rendered = _render_personalized(body, name).replace(chr(10), "<br/>")
                msg.attach(MIMEText(f"<div style='font-family:Arial,sans-serif;'>{rendered}</div>", "html"))
                with smtplib.SMTP(SMTP_HOST, SMTP_PORT, timeout=15) as server:
                    server.ehlo()
                    server.starttls()
                    server.login(SMTP_USER, SMTP_PASS)
                    server.sendmail(SMTP_USER, email, msg.as_string())
                rec.provider_message_id = None
            rec.status = "sent"
            sent += 1
        except Exception as e:
            rec.status = "failed"
            rec.error = str(e)[:500]
            failed += 1
            logging.error(f"[TEMPLATE BROADCAST] {channel} to member {member.id} failed: {e}")
        db.session.add(rec)

    bc.sent_count = sent
    bc.failed_count = failed
    next_offset = offset + len(batch)
    bc.status = "completed" if next_offset >= len(all_members) else "running"
    db.session.commit()

    return connectit_json_response({
        "broadcast_id": bc.id, "sent": sent, "failed": failed,
        "skipped_opted_out": skipped,
        "batch_size": len(batch), "total_recipients": len(all_members),
        "next_offset": next_offset if next_offset < len(all_members) else None,
        "status": bc.status,
    })


