# ════════════════════════════════════════════════════════════
# WHATSAPP GROUPS API — see model comments above (WhatsAppGroup /
# WhatsAppGroupEvent) for the full, verified 2026 capability set this
# is built against.
# ════════════════════════════════════════════════════════════

def create_whatsapp_group(user_id, name: str) -> dict:
    """Real call to Meta's Groups API create-group endpoint. Raises with
    Meta's own error text if the account isn't an Official Business
    Account — this platform cannot grant OBA status or fake success."""
    creds = _whatsapp_cloud_creds_for_user(user_id)
    if not creds["phone_number_id"] or not creds["access_token"]:
        raise ValueError("WhatsApp Cloud API not configured")
    if not name or not name.strip():
        raise ValueError("Group name is required")
    resp = requests.post(
        f"https://graph.facebook.com/{WHATSAPP_CLOUD_API_VERSION}/{creds['phone_number_id']}/groups",
        headers={
            "Authorization": f"Bearer {creds['access_token']}",
            "Content-Type": "application/json",
        },
        json={"subject": name.strip()[:200]},
        timeout=15,
    )
    data = resp.json()
    if not resp.ok:
        err = (data.get("error") or {}).get("message", "WhatsApp Groups API error")
        raise ValueError(
            f"{err} (this usually means the connected number isn't an Official Business Account yet — "
            f"Groups API requires OBA status set up directly in Meta Business Manager)"
        )
    return data


def send_whatsapp_group_message(user_id, meta_group_id: str, text: str = None,
                                 template_name: str = None, language_code: str = "en_US",
                                 components=None) -> dict:
    """Real call to the Messages API with recipient_type=group. Unlike
    send_whatsapp_cloud_message, the recipient is NOT a phone number —
    it must never be run through the digit-stripping phone sanitizer,
    or a real group ID would get silently mangled into garbage."""
    creds = _whatsapp_cloud_creds_for_user(user_id)
    if not creds["phone_number_id"] or not creds["access_token"]:
        raise ValueError("WhatsApp Cloud API not configured")
    if not meta_group_id:
        raise ValueError("meta_group_id is required")
    if template_name:
        payload = {
            "messaging_product": "whatsapp",
            "recipient_type": "group",
            "to": meta_group_id,
            "type": "template",
            "template": {"name": template_name, "language": {"code": language_code or "en_US"}},
        }
        if components:
            payload["template"]["components"] = components
    else:
        if not text or not text.strip():
            raise ValueError("text is required when not sending a template")
        payload = {
            "messaging_product": "whatsapp",
            "recipient_type": "group",
            "to": meta_group_id,
            "type": "text",
            "text": {"body": text},
        }
    resp = requests.post(
        f"https://graph.facebook.com/{WHATSAPP_CLOUD_API_VERSION}/{creds['phone_number_id']}/messages",
        headers={
            "Authorization": f"Bearer {creds['access_token']}",
            "Content-Type": "application/json",
        },
        json=payload,
        timeout=15,
    )
    data = resp.json()
    if not resp.ok:
        raise ValueError((data.get("error") or {}).get("message", "WhatsApp group message failed"))
    return data


@app.route("/api/whatsapp-cloud/groups", methods=["GET"])
def whatsapp_cloud_groups_list():
    """Lists groups from this platform's own record, not a Meta 'list
    groups' call — Meta's Groups API does not publish a list-all
    endpoint, only create + message + webhook-driven state, so the
    local record created at group-creation time (and kept current by
    webhooks below) is the real source of truth here."""
    current_user = _get_current_user()
    if not current_user:
        return connectit_json_response({"error": "Login required"}, 401)
    rows = (WhatsAppGroup.query.filter_by(user_id=current_user["id"])
            .order_by(WhatsAppGroup.created_at.desc()).all())
    return connectit_json_response({"groups": [g.to_dict() for g in rows]})


@app.route("/api/whatsapp-cloud/groups", methods=["POST"])
@csrf.exempt
def whatsapp_cloud_groups_create():
    current_user = _get_current_user()
    if not current_user:
        return connectit_json_response({"error": "Login required"}, 401)
    data = request.get_json(silent=True) or {}
    name = (data.get("name") or "").strip()
    if not name:
        return connectit_json_response({"error": "Group name is required"}, 400)
    try:
        result = create_whatsapp_group(current_user["id"], name)
        row = WhatsAppGroup(
            user_id=current_user["id"], meta_group_id=result.get("id") or result.get("group_id"),
            name=name[:200], invite_link=result.get("invite_link") or result.get("wa_invite_link"),
            status="active",
        )
        db.session.add(row)
        db.session.commit()
        logging.info(f"[WA GROUPS] created '{name}' | id={row.meta_group_id}")
        return connectit_json_response({"ok": True, "group": row.to_dict()}), 201
    except Exception as e:
        db.session.rollback()
        logging.error(f"[WA GROUPS CREATE ERROR] {e}")
        return connectit_json_response({"error": str(e)}, 500)


@app.route("/api/whatsapp-cloud/groups/<int:group_id>/send", methods=["POST"])
@csrf.exempt
def whatsapp_cloud_groups_send(group_id):
    current_user = _get_current_user()
    if not current_user:
        return connectit_json_response({"error": "Login required"}, 401)
    row = WhatsAppGroup.query.filter_by(id=group_id, user_id=current_user["id"]).first()
    if not row:
        return connectit_json_response({"error": "Group not found"}, 404)
    if row.status != "active":
        return connectit_json_response({"error": f"This group is {row.status}."}, 400)
    data = request.get_json(silent=True) or {}
    text = (data.get("text") or "").strip()
    template_name = (data.get("template_name") or "").strip()
    try:
        if template_name:
            result = send_whatsapp_group_message(
                current_user["id"], row.meta_group_id, template_name=template_name,
                language_code=(data.get("language_code") or "en_US").strip(),
                components=data.get("components") or [])
        else:
            if not text:
                return connectit_json_response({"error": "text is required (or pass template_name)"}, 400)
            result = send_whatsapp_group_message(current_user["id"], row.meta_group_id, text=text)
        msg_id = ((result.get("messages") or [{}])[0]).get("id")
        logging.info(f"[WA GROUPS] message sent to group {row.meta_group_id} | id={msg_id}")
        return connectit_json_response({"sent": True, "message_id": msg_id})
    except Exception as e:
        logging.error(f"[WA GROUPS SEND ERROR] {e}")
        return connectit_json_response({"error": str(e)}, 500)


