@app.route("/api/whatsapp-cloud/groups/<int:group_id>/invite", methods=["POST"])
@csrf.exempt
def whatsapp_cloud_groups_send_invite(group_id):
    """Sales/community funnel: send this group's real invite link to a
    customer 1:1 (groups are invite-link-only; there is no add-member call)."""
    current_user = _get_current_user()
    if not current_user:
        return connectit_json_response({"error": "Login required"}, 401)
    if not _csrf_ok():
        return connectit_json_response({"error": "CSRF token invalid or missing."}, 403)
    row = WhatsAppGroup.query.filter_by(id=group_id, user_id=current_user["id"]).first()
    if not row:
        return connectit_json_response({"error": "Group not found"}, 404)
    if row.status != "active" or not row.invite_link:
        return connectit_json_response({"error": "This group has no active invite link."}, 400)
    d = request.get_json(silent=True) or {}
    to = (d.get("to") or "").strip()
    if not to:
        return connectit_json_response({"error": "to is required."}, 400)
    msg = (d.get("message") or f"Join our WhatsApp group \"{row.name}\":").strip()
    try:
        send_whatsapp_cloud_message(current_user["id"], to, f"{msg}\n{row.invite_link}")
        return connectit_json_response({"ok": True})
    except Exception as e:
        return connectit_json_response({"error": str(e)}, 502)


@app.route("/api/whatsapp-cloud/groups/broadcast", methods=["POST"])
@csrf.exempt
def whatsapp_cloud_groups_broadcast():
    """Send one text to several of the business's active groups. Body: {group_ids:[...], text}."""
    current_user = _get_current_user()
    if not current_user:
        return connectit_json_response({"error": "Login required"}, 401)
    if not _csrf_ok():
        return connectit_json_response({"error": "CSRF token invalid or missing."}, 403)
    d = request.get_json(silent=True) or {}
    text = (d.get("text") or "").strip()
    ids = d.get("group_ids") or []
    if not text or not ids or len(ids) > 20:
        return connectit_json_response({"error": "text and 1-20 group_ids are required."}, 400)
    results = []
    for g in WhatsAppGroup.query.filter(WhatsAppGroup.user_id == current_user["id"],
                                        WhatsAppGroup.id.in_(ids), WhatsAppGroup.status == "active").all():
        try:
            send_whatsapp_group_message(current_user["id"], g.meta_group_id, text=text)
            results.append({"group_id": g.id, "sent": True})
        except Exception as e:
            results.append({"group_id": g.id, "sent": False, "error": str(e)})
    return connectit_json_response({"ok": True, "results": results})


