# ════════════════════════════════════════════════════════════
# STAGE 167: WHATSAPP VOICE-NOTE-TO-LEDGER — HELPERS
# ════════════════════════════════════════════════════════════

def _wa_cloud_download_media(user_id, media_id: str):
    """Downloads a WhatsApp Cloud media attachment (voice note, photo)
    by its media_id. Two-step Graph API dance: first resolve the
    short-lived media_id to a real URL, then fetch the bytes from that
    URL — both requests need the same bearer token."""
    creds = _whatsapp_cloud_creds_for_user(user_id)
    if not creds["access_token"]:
        return None
    try:
        meta = requests.get(
            f"https://graph.facebook.com/{WHATSAPP_CLOUD_API_VERSION}/{media_id}",
            headers={"Authorization": f"Bearer {creds['access_token']}"}, timeout=15,
        ).json()
        media_url = meta.get("url")
        if not media_url:
            return None
        resp = requests.get(media_url, headers={"Authorization": f"Bearer {creds['access_token']}"}, timeout=30)
        if resp.status_code == 200:
            return resp.content
        return None
    except Exception as e:
        logging.error(f"[WA MEDIA DOWNLOAD ERROR] user={user_id} media={media_id}: {e}")
        return None


def _voice_ledger_row(uid, create_if_missing=False):
    row = VoiceLedgerSetting.query.filter_by(owner_user_id=uid).first()
    if not row and create_if_missing:
        row = VoiceLedgerSetting(owner_user_id=uid, enabled=False)
        db.session.add(row); db.session.commit()
    return row


def _voice_ledger_authorized(owner_uid, sender_num: str) -> bool:
    row = _voice_ledger_row(owner_uid)
    if not row or not row.enabled:
        return False
    sender_digits = re.sub(r"\D", "", sender_num or "")
    authorized = [re.sub(r"\D", "", n) for n in (row.authorized_numbers or "").split(",") if n.strip()]
    return sender_digits in authorized


def _voice_ledger_extract(transcript: str) -> dict:
    """AI-parses a transcribed voice note into structured sale/expense
    fields. Mirrors the same 'raw JSON only' extraction pattern used by
    Stage 110's receipt scanner, just from text instead of an image."""
    if not anthropic_client:
        return {}
    try:
        response = anthropic_client.messages.create(
            model="claude-sonnet-4-5", max_tokens=400,
            messages=[{
                "role": "user",
                "content": (
                    "A small business owner sent this WhatsApp voice note about something that just "
                    "happened in their business. Decide if it describes a SALE (they sold something to "
                    "a customer) or an EXPENSE (they paid/bought something), then extract fields. "
                    "Reply with ONLY raw JSON, no markdown fences:\n"
                    '{"type": "sale" or "expense", "item_description": "...", "quantity": 1.0, '
                    '"customer_or_vendor": "..." or null, "amount": 0.0, "currency": "USD", '
                    '"payment_method": "cash"/"ecocash"/"card"/"bank"/"credit", "category": "..." (expenses only)}\n\n'
                    f"Voice note transcript: \"{transcript}\""
                ),
            }],
        )
        raw = response.content[0].text.strip()
        raw = re.sub(r"^```(?:json)?|```$", "", raw.strip(), flags=re.MULTILINE).strip()
        return json.loads(raw)
    except Exception as e:
        logging.error(f"[VOICE LEDGER EXTRACT] {e}")
        return {}


def _voice_ledger_summary_text(extracted: dict) -> str:
    kind = extracted.get("type", "entry")
    who = extracted.get("customer_or_vendor")
    amount = extracted.get("amount", 0)
    currency = extracted.get("currency", "USD")
    item = extracted.get("item_description", "")
    if kind == "sale":
        return (f"I heard: sold {item} {'to ' + who if who else ''} for {currency} {amount} "
                f"({extracted.get('payment_method', 'cash')}). Reply YES to log this sale, or NO to cancel.")
    return (f"I heard: paid {currency} {amount} for {item}{' to ' + who if who else ''} "
            f"({extracted.get('category', 'general')}). Reply YES to log this expense, or NO to cancel.")


def _voice_ledger_post(log: "VoiceLedgerLog") -> dict:
    """Posts a confirmed voice-note entry as a real PosSale (+ inventory
    decrement if the item matches by name) or ErpExpense, exactly like
    the equivalent manually-entered records elsewhere in the ERP."""
    extracted = json.loads(log.extracted_json) if log.extracted_json else {}
    today = datetime.utcnow().date()
    try:
        amount = float(extracted.get("amount") or 0)
    except Exception:
        amount = 0
    if amount <= 0:
        return {"ok": False, "error": "Could not determine a valid amount."}
    currency = (extracted.get("currency") or "USD").upper()[:8]

    if log.entry_type == "sale":
        item_desc = (extracted.get("item_description") or "item")[:300]
        try:
            qty = float(extracted.get("quantity") or 1)
        except Exception:
            qty = 1
        product = None
        last_word = item_desc.split(" ")[-1].strip() if item_desc else ""
        if len(last_word) >= 3:
            product = (InventoryItem.query.filter_by(user_id=log.owner_user_id, active=True)
                       .filter(InventoryItem.name.ilike(f"%{last_word}%")).first())
        sale = PosSale(
            owner_user_id=log.owner_user_id, sale_number=_erp_gen_number("VN"),
            currency=currency, subtotal=amount, total=amount,
            payment_method=(extracted.get("payment_method") or "cash")[:20],
        )
        db.session.add(sale); db.session.flush()
        db.session.add(PosSaleItem(
            sale_id=sale.id, product_id=product.id if product else None,
            description=item_desc, quantity=qty, unit_price=round(amount / qty, 2) if qty else amount,
            line_total=amount,
        ))
        if product:
            _erp_apply_stock_delta(product.id, -abs(qty))
        _erp_post_ledger(
            owner_user_id=log.owner_user_id, entry_date=today, kind="income", account="Sales",
            description=f"WhatsApp voice note sale: {item_desc}", amount=amount,
            ref_type="voice_ledger", ref_id=log.id,
        )
        db.session.commit()
        return {"ok": True, "ref_type": "pos_sale", "ref_id": sale.id}

    else:  # expense
        vendor = (extracted.get("customer_or_vendor") or "").strip()[:200] or None
        category = (extracted.get("category") or "general")[:80]
        expense = ErpExpense(
            owner_user_id=log.owner_user_id, expense_date=today, category=category,
            vendor=vendor, amount=amount, currency=currency,
            payment_method=(extracted.get("payment_method") or "cash")[:20],
            notes="Posted via WhatsApp voice-note-to-ledger.",
        )
        db.session.add(expense); db.session.flush()
        _erp_post_ledger(
            owner_user_id=log.owner_user_id, entry_date=today, kind="expense", account=category,
            description=f"WhatsApp voice note expense: {extracted.get('item_description', '')}",
            amount=-abs(amount), ref_type="voice_ledger", ref_id=log.id,
        )
        db.session.commit()
        return {"ok": True, "ref_type": "expense", "ref_id": expense.id}


def _voice_ledger_handle_incoming_audio(owner_uid, sender_num: str, media_id: str) -> None:
    """Full pipeline: authorize → download → transcribe → AI-extract →
    log as pending → ask for a WhatsApp confirmation. Never posts
    anything to the ledger on its own."""
    if not owner_uid or not _voice_ledger_authorized(owner_uid, sender_num):
        return
    audio_bytes = _wa_cloud_download_media(owner_uid, media_id)
    if not audio_bytes:
        send_whatsapp_cloud_message(owner_uid, sender_num, "Sorry, I couldn't download that voice note. Please try again.")
        return
    # STAGE (metering gap fix): this fires from an inbound WhatsApp
    # webhook with no browser session, but there IS a clear billable
    # party — the business account owner — so gate on them, same
    # pattern as the automation engine and widget_chat. Gated before
    # speech_to_text (also a paid call) so a blocked owner incurs
    # neither cost.
    owner_acct = UserAccount.query.get(owner_uid)
    if owner_acct:
        gate_result = gate_ai_usage({"id": owner_acct.id, "plan": owner_acct.plan}, "voice_ledger_extract")
        if gate_result is not None:
            send_whatsapp_cloud_message(owner_uid, sender_num, "You've hit your plan's monthly limit for voice-note ledger entries. Please upgrade to continue, or type the entry instead.")
            return
    stt = speech_to_text(audio_bytes, owner_uid, encoding="OGG_OPUS", sample_rate_hertz=16000)
    transcript = (stt.get("transcript") or "").strip() if stt.get("ok") else ""
    if not transcript:
        send_whatsapp_cloud_message(owner_uid, sender_num, "Sorry, I couldn't make out that voice note clearly. Please try again or type it instead.")
        return
    extracted = _voice_ledger_extract(transcript)
    if not extracted or not extracted.get("amount"):
        send_whatsapp_cloud_message(owner_uid, sender_num, f"I heard: \"{transcript}\" — but couldn't pick out a clear amount. Could you resend with the amount, e.g. 'sold 3 bags of cement for $40 cash'?")
        return
    entry_type = "sale" if extracted.get("type") == "sale" else "expense"
    log = VoiceLedgerLog(
        owner_user_id=owner_uid, sender_phone=sender_num, transcript=transcript,
        extracted_json=json.dumps(extracted), entry_type=entry_type, status="pending_confirmation",
    )
    db.session.add(log); db.session.commit()
    summary = _voice_ledger_summary_text(extracted)
    try:
        # Real tappable Confirm/Cancel buttons — the id encodes this specific
        # log's row, so a sender with more than one pending voice note at once
        # (e.g. sent two in a row before answering either) can't accidentally
        # confirm/cancel the wrong one, unlike matching on "most recent pending".
        send_whatsapp_button_message(
            owner_uid, sender_num, summary,
            buttons=[
                {"id": f"vl_confirm_{log.id}", "title": " Confirm"},
                {"id": f"vl_cancel_{log.id}",  "title": " Cancel"},
            ],
        )
    except Exception as btn_send_err:
        # Graceful degradation (matches this codebase's pattern elsewhere):
        # buttons can fail to send for reasons unrelated to the ledger entry
        # itself (account not yet upgraded for interactive messages, etc) —
        # fall back to the original typed YES/NO flow rather than losing the
        # pending entry silently.
        logging.warning(f"[VOICE LEDGER BUTTON SEND FAILED, falling back to text] {btn_send_err}")
        send_whatsapp_cloud_message(owner_uid, sender_num, summary + "\n\nReply YES to confirm or NO to cancel.")


def _voice_ledger_resolve(pending, confirm: bool) -> str:
    """Shared confirm/cancel logic used by both the typed-text path
    (_voice_ledger_handle_incoming_text) and the button-tap path
    (_voice_ledger_handle_button_reply), so the two entry points can never
    drift apart in behavior. Returns the WhatsApp reply text to send back."""
    if confirm:
        result = _voice_ledger_post(pending)
        pending.status = "confirmed" if result.get("ok") else "failed"
        pending.linked_ref_type = result.get("ref_type"); pending.linked_ref_id = result.get("ref_id")
        pending.resolved_at = datetime.utcnow()
        db.session.commit()
        return "Logged! Thanks." if result.get("ok") else f"Sorry, couldn't log that: {result.get('error', 'unknown error')}"
    pending.status = "rejected"; pending.resolved_at = datetime.utcnow()
    db.session.commit()
    return "Cancelled — nothing was logged."


def _voice_ledger_handle_incoming_text(owner_uid, sender_num: str, text: str) -> bool:
    """Checks for a pending voice-note confirmation from this sender
    before the normal AI chatbot pipeline runs. Returns True if this
    message was consumed as a confirmation/cancellation (caller should
    skip the normal AI reply), False otherwise. Kept as a fallback for
    senders replying to the older plain-text prompt, or if button sending
    failed for this particular message (see _voice_ledger_handle_incoming_audio)."""
    if not owner_uid:
        return False
    pending = (VoiceLedgerLog.query.filter_by(owner_user_id=owner_uid, sender_phone=sender_num, status="pending_confirmation")
               .order_by(VoiceLedgerLog.created_at.desc()).first())
    if not pending:
        return False
    reply = (text or "").strip().lower()
    if reply in ("yes", "y", "confirm", "confirmed"):
        send_whatsapp_cloud_message(owner_uid, sender_num, _voice_ledger_resolve(pending, confirm=True))
        return True
    if reply in ("no", "n", "cancel", "stop"):
        send_whatsapp_cloud_message(owner_uid, sender_num, _voice_ledger_resolve(pending, confirm=False))
        return True
    return False


def _voice_ledger_handle_button_reply(owner_uid, sender_num: str, button_id: str) -> bool:
    """Handles a tap on the Confirm/Cancel buttons sent alongside the voice-
    note summary. Targets the exact log id encoded in the button (see
    _voice_ledger_handle_incoming_audio) rather than 'most recent pending',
    so this stays correct even with multiple pending entries for one sender.
    Returns True if the tap was handled (caller should not fall through to
    the normal AI chatbot reply), False if the button id wasn't ours."""
    if not owner_uid or not button_id:
        return False
    match = re.match(r"^vl_(confirm|cancel)_(\d+)$", button_id)
    if not match:
        return False
    action, log_id = match.group(1), int(match.group(2))
    pending = VoiceLedgerLog.query.filter_by(
        id=log_id, owner_user_id=owner_uid, sender_phone=sender_num, status="pending_confirmation"
    ).first()
    if not pending:
        send_whatsapp_cloud_message(
            owner_uid, sender_num,
            "That voice note entry isn't pending anymore (already handled, or it expired)."
        )
        return True
    send_whatsapp_cloud_message(owner_uid, sender_num, _voice_ledger_resolve(pending, confirm=(action == "confirm")))
    return True


def _order_confirmation_handle_button_reply(owner_uid, sender_num: str, button_id: str) -> bool:
    """Handles a tap on the Confirm Receipt / Report Issue buttons sent
    when a marketplace order shows as delivered (see the tracking-check
    branch in product_order_tracking below). Runs the exact same core
    logic as the in-app 'Mark received' / 'Open dispute' buttons
    (product_order_mark_received / product_order_dispute) so a buyer
    gets a real payment release or a real dispute either way, without
    needing to open the app. Returns True if the tap was handled
    (caller should not fall through to the normal AI chatbot reply),
    False if the button id wasn't ours."""
    if not owner_uid or not button_id:
        return False
    match = re.match(r"^order-(confirm|dispute)-(\d+)$", button_id)
    if not match:
        return False
    action, order_id = match.group(1), int(match.group(2))
    order = ProductOrder.query.get(order_id)
    # Only the buyer's own WhatsApp number can act on their order -- the
    # owner_uid resolved from the receiving phone_number_id is the
    # BUSINESS, so match sender_num against the buyer's stored number
    # rather than owner_uid, which would be wrong here.
    buyer = UserAccount.query.get(order.buyer_id) if order else None
    if not order or not buyer or (buyer.whatsapp_number or "") != sender_num:
        send_whatsapp_cloud_message(
            owner_uid, sender_num,
            "That order confirmation link isn't valid anymore, or doesn't belong to this number."
        )
        return True
    if action == "confirm":
        if order.escrow_status == "disputed":
            send_whatsapp_cloud_message(owner_uid, sender_num,
                f"Order #{order.id} has an open dispute -- an admin will resolve it.")
            return True
        if order.escrow_status != "holding":
            send_whatsapp_cloud_message(owner_uid, sender_num,
                f"Order #{order.id} isn't awaiting confirmation (status: {order.escrow_status or order.status}).")
            return True
        ok, error = _release_product_order_escrow(order)
        if not ok:
            send_whatsapp_cloud_message(owner_uid, sender_num, f"Couldn't confirm receipt: {error or 'unknown error'}")
            return True
        _ensure_deal_confirmation("product_order", order.id, order.buyer_id, order.seller_id)
        deal = DealConfirmation.query.filter_by(deal_type="product_order", ref_id=order.id).first()
        if deal:
            deal.party_a_confirmed = True; deal.party_b_confirmed = True
            deal.status = "confirmed"; deal.confirmed_at = deal.confirmed_at or datetime.utcnow()
            db.session.commit()
        send_whatsapp_cloud_message(owner_uid, sender_num,
            f"Thanks -- receipt confirmed for order #{order.id}. Payment has been released to the seller.")
        return True
    # action == "dispute"
    if order.escrow_status != "holding":
        send_whatsapp_cloud_message(owner_uid, sender_num,
            f"Can't open a dispute on order #{order.id} (status: {order.escrow_status or order.status}).")
        return True
    order.escrow_status = "disputed"
    order.dispute_reason = "Reported via WhatsApp -- buyer tapped 'Report Issue', no reason text yet."
    db.session.commit()
    _ensure_deal_confirmation("product_order", order.id, order.buyer_id, order.seller_id)
    deal = DealConfirmation.query.filter_by(deal_type="product_order", ref_id=order.id).first()
    if deal:
        deal.status = "disputed"; deal.dispute_reason = order.dispute_reason
        db.session.commit()
    seller = UserAccount.query.get(order.seller_id)
    if seller and seller.whatsapp_number:
        try:
            send_whatsapp_cloud_message(
                seller.id, seller.whatsapp_number,
                f"A buyer opened a dispute on order #{order.id} via WhatsApp. "
                f"An admin will review it -- payment stays held until then.")
        except Exception as e:
            logging.error(f"[ORDER WA BUTTON DISPUTE SELLER NOTIFY ERROR] order={order.id}: {e}")
    send_whatsapp_cloud_message(owner_uid, sender_num,
        f"Got it -- we've flagged order #{order.id} for review. Payment stays held until an admin resolves it. "
        f"Reply here with what went wrong so the seller and our team have the details.")
    return True


def _verify_whatsapp_cloud_signature(app_secret: str, raw_body: bytes, signature_header: str) -> bool:
    """Verifies Meta's X-Hub-Signature-256 header against the raw request
    body using the Meta App Secret. Constant-time compare (hmac.compare_digest)
    to avoid timing side-channels. Returns False (never raises) on any
    malformed input so a caller can safely treat any False as 'reject'."""
    if not app_secret or not signature_header:
        return False
    if not signature_header.startswith("sha256="):
        return False
    provided_sig = signature_header.split("=", 1)[1].strip()
    if not provided_sig:
        return False
    expected_sig = hmac.new(app_secret.encode("utf-8"), raw_body, hashlib.sha256).hexdigest()
    try:
        return hmac.compare_digest(expected_sig, provided_sig)
    except Exception:
        return False


@app.route("/whatsapp-cloud/webhook", methods=["GET"])
@csrf.exempt
def whatsapp_cloud_webhook_verify():
    """Meta's one-time handshake to verify this webhook URL when you
    register it in the Meta App Dashboard."""
    mode      = request.args.get("hub.mode", "")
    token     = request.args.get("hub.verify_token", "")
    challenge = request.args.get("hub.challenge", "")
    expected  = WHATSAPP_CLOUD_VERIFY_TOKEN
    if mode == "subscribe" and expected and hmac.compare_digest(token, expected):
        return challenge, 200
    return "Forbidden", 403


@app.route("/whatsapp-cloud/webhook", methods=["POST"])
@csrf.exempt
def whatsapp_cloud_webhook_receive():
    """Incoming WhatsApp Cloud API messages. Runs the same AI-reply pipeline
    as the Twilio WhatsApp webhook, then replies via the Graph API using
    whichever business's BYOK credentials own the receiving number."""
    # SECURITY: verify this really came from Meta before trusting a single
    # byte of it. Must read the raw body BEFORE request.get_json() below —
    # Flask parses form/json lazily but the signature is computed over the
    # exact raw bytes Meta sent, not a re-serialized version of them.
    raw_body = request.get_data()
    if WHATSAPP_CLOUD_APP_SECRET:
        signature_header = request.headers.get("X-Hub-Signature-256", "")
        if not _verify_whatsapp_cloud_signature(WHATSAPP_CLOUD_APP_SECRET, raw_body, signature_header):
            logging.warning("[WA CLOUD WEBHOOK] Rejected POST — missing or invalid X-Hub-Signature-256.")
            return connectit_json_response({"error": "Invalid signature"}, 403)
    else:
        # Fails open (matches this codebase's graceful-degradation pattern for
        # unconfigured optional integrations) but logs loudly on every single
        # request, since an unset secret here is a real security gap, not a
        # missing nice-to-have feature.
        logging.warning("[WA CLOUD WEBHOOK] WHATSAPP_CLOUD_APP_SECRET is not set — "
                         "incoming webhook requests are NOT signature-verified. Anyone who "
                         "finds this URL can inject fake WhatsApp messages/status updates. "
                         "Set WHATSAPP_CLOUD_APP_SECRET (Meta App Dashboard → Settings → Basic "
                         "→ App Secret) to close this gap.")
    try:
        payload = request.get_json(force=True) or {}
        for entry in payload.get("entry", []):
            for change in entry.get("changes", []):
                value = change.get("value", {}) or {}
                # WhatsApp Groups API: group_lifecycle_update, group_participants_update,
                # group_settings_update, group_status_update all arrive here with the
                # group's ID in value.get("id") — update the real local record rather
                # than estimating anything, and keep the raw event for audit purposes.
                field = change.get("field", "")
                if field in ("group_lifecycle_update", "group_participants_update",
                             "group_settings_update", "group_status_update"):
                    try:
                        wa_group_id = value.get("id") or value.get("group_id")
                        group_row = WhatsAppGroup.query.filter_by(meta_group_id=wa_group_id).first() if wa_group_id else None
                        if group_row:
                            if "participants" in value and isinstance(value.get("participants"), list):
                                group_row.participant_count = len(value["participants"])
                            if field == "group_status_update" and value.get("status"):
                                mapped = {"active": "active", "archived": "archived", "deleted": "deleted"}
                                group_row.status = mapped.get(value["status"], group_row.status)
                            db.session.add(WhatsAppGroupEvent(
                                group_id=group_row.id, event_type=field,
                                payload_json=json.dumps(value)[:8000],
                            ))
                            db.session.commit()
                    except Exception as group_evt_err:
                        logging.error(f"[WA GROUP EVENT ERROR] {group_evt_err}")
                    continue
                if field == "standby":
                    # Meta Business Agent's live conversation feed — only
                    # delivered if this app is subscribed to "standby" in
                    # the Meta dashboard. Read-only: we never reply here,
                    # since the agent — not this platform — owns the
                    # conversation while it's in standby. Payload schema
                    # for this field is new and not fully stabilized
                    # industry-wide, so every message found is logged
                    # defensively (raw body_text kept even if a field name
                    # assumption below turns out wrong for your account).
                    try:
                        sb_phone_number_id = (value.get("metadata") or {}).get("phone_number_id", "")
                        sb_owner_uid = _find_user_for_whatsapp_cloud_phone(sb_phone_number_id)
                        for sb_msg in (value.get("messages") or []):
                            db.session.add(MetaBusinessAgentEvent(
                                owner_user_id=sb_owner_uid, phone_number_id=sb_phone_number_id,
                                customer_wa_id=sb_msg.get("from") or sb_msg.get("from_user_id"), event_type="standby_message",
                                direction="inbound" if sb_msg.get("from") else "outbound",
                                body_text=((sb_msg.get("text") or {}).get("body")
                                           or json.dumps(sb_msg)[:2000]),
                            ))
                        if not value.get("messages"):
                            # Unrecognized shape for this account — still
                            # capture something rather than silently drop it.
                            db.session.add(MetaBusinessAgentEvent(
                                owner_user_id=sb_owner_uid, phone_number_id=sb_phone_number_id,
                                event_type="standby_message", body_text=json.dumps(value)[:2000],
                            ))
                        db.session.commit()
                    except Exception as standby_err:
                        logging.error(f"[META BUSINESS AGENT STANDBY ERROR] {standby_err}")
                    continue
                phone_number_id = (value.get("metadata") or {}).get("phone_number_id", "")
                owner_uid = _find_user_for_whatsapp_cloud_phone(phone_number_id)
                if owner_uid and phone_number_id and value.get("messages"):
                    # Per-customer handoff check: if this exact customer's
                    # most recent Meta Business Agent event was a standby
                    # message (i.e. more recent than any handoff already
                    # logged for them), a normal "messages" event now means
                    # Meta just released the conversation back — log the
                    # handoff once per cycle, not once ever per number, so a
                    # customer who goes through agent -> human -> agent ->
                    # human again is tracked correctly each time.
                    for _msg in value.get("messages") or []:
                        cust_wa_id = _msg.get("from") or _msg.get("from_user_id")
                        if not cust_wa_id:
                            continue
                        try:
                            last_mba_event = (MetaBusinessAgentEvent.query
                                .filter_by(owner_user_id=owner_uid, phone_number_id=phone_number_id,
                                           customer_wa_id=cust_wa_id)
                                .filter(MetaBusinessAgentEvent.event_type.in_(["standby_message", "handoff_detected"]))
                                .order_by(MetaBusinessAgentEvent.id.desc()).first())
                            if last_mba_event and last_mba_event.event_type == "standby_message":
                                db.session.add(MetaBusinessAgentEvent(
                                    owner_user_id=owner_uid, phone_number_id=phone_number_id,
                                    event_type="handoff_detected", customer_wa_id=cust_wa_id,
                                ))
                                db.session.commit()
                                # Receive the handoff: freeze the ERP context
                                # (customer, balance, orders, stock) the agent
                                # could not see, and alert the owner.
                                _mba_create_handoff(owner_uid, phone_number_id, cust_wa_id, _msg,
                                                    value.get("contacts"))
                        except Exception as handoff_err:
                            logging.error(f"[META BUSINESS AGENT HANDOFF LOG ERROR] {handoff_err}")
                if field == "calls":
                    # Inbound call ringing (event="connect", carries the
                    # customer's SDP offer) or a status transition
                    # (event="terminate" / "ringing" / etc) for a call
                    # already in progress. Never auto-answer here — only
                    # persist state so a human operator's browser can pick
                    # it up via /api/whatsapp-cloud/calls/incoming.
                    for call_evt in value.get("calls", []) or []:
                        try:
                            meta_call_id = call_evt.get("id") or ""
                            if not meta_call_id:
                                continue
                            event_type = (call_evt.get("event") or "").lower()
                            session_obj = call_evt.get("session") or {}
                            call_row = WhatsAppCall.query.filter_by(meta_call_id=meta_call_id).first()
                            if not call_row:
                                call_row = WhatsAppCall(
                                    owner_user_id=owner_uid,
                                    meta_call_id=meta_call_id[:128],
                                    direction="inbound",
                                    phone_number_id=phone_number_id[:64] if phone_number_id else None,
                                    counterparty_wa_id=(call_evt.get("from") or "")[:32] or None,
                                    raw_timestamp=str(call_evt.get("timestamp") or "")[:20] or None,
                                )
                                db.session.add(call_row)
                            if event_type == "connect" and session_obj.get("sdp"):
                                call_row.status = "ringing"
                                call_row.sdp_offer = session_obj.get("sdp")
                                # AI voice agent takes the call only when the
                                # owner enabled it AND a bridge is configured;
                                # otherwise it rings for a human as before.
                                if _wa_voice_agent_enabled(owner_uid):
                                    call_row.status = "agent_queued"
                            elif event_type == "terminate":
                                call_row.status = (call_evt.get("status") or "terminated").lower()
                                call_row.termination_reason = (call_evt.get("status") or "")[:64] or None
                                if call_evt.get("duration") is not None:
                                    try:
                                        call_row.duration_seconds = int(call_evt.get("duration"))
                                    except (TypeError, ValueError):
                                        pass
                                call_row.sdp_offer = None  # no longer needed once the call has ended
                            elif event_type:
                                call_row.status = event_type
                            db.session.commit()
                        except Exception as call_evt_err:
                            db.session.rollback()
                            logging.error(f"[WA CALL EVENT ERROR] {call_evt_err}")
                    continue
                if field == "smb_message_echoes":
                    # A message the human operator sent by hand from the
                    # regular WhatsApp Business App on their phone (this
                    # number runs Cloud API + the phone app side-by-side,
                    # aka "coexistence"). Mirror it into this platform's
                    # own chat history so a conversation started on the
                    # phone doesn't look incomplete here, and log it as
                    # its own event for the coexistence activity feed.
                    for echo in value.get("message_echoes", []) or []:
                        try:
                            counterparty = str(echo.get("to") or echo.get("from") or "")
                            text_body = ((echo.get("text") or {}).get("body") or "")
                            summary = (text_body or f"[{echo.get('type', 'message')}]")[:255]
                            db.session.add(WhatsAppCoexistenceEvent(
                                owner_user_id=owner_uid, event_type="message_echo",
                                counterparty_wa_id=counterparty[:32] or None,
                                summary=summary, payload_json=json.dumps(echo)[:8000],
                            ))
                            if owner_uid and counterparty and text_body:
                                session_key = ("+" + counterparty)[:64]
                                if session_key not in whatsapp_store:
                                    whatsapp_store[session_key] = _db_get_history(session_key, channel="whatsapp")
                                _db_save_turn(session_key, "whatsapp", "assistant", text_body, owner_user_id=owner_uid)
                            db.session.commit()
                        except Exception as echo_err:
                            db.session.rollback()
                            logging.error(f"[WA MESSAGE ECHO ERROR] {echo_err}")
                    continue
                if field == "smb_app_state_sync":
                    # Contact/chat metadata changed on the phone app side
                    # (a chat archived, a contact added/removed, a chat
                    # marked read) — nothing this platform needs to act
                    # on automatically, but logged so an operator can see
                    # what changed on the phone without picking it up.
                    for state_evt in value.get("state_sync", []) or []:
                        try:
                            evt_type = state_evt.get("type", "state_change")
                            contact = (state_evt.get("contact") or {})
                            counterparty = str(contact.get("wa_id") or state_evt.get("wa_id") or "")
                            db.session.add(WhatsAppCoexistenceEvent(
                                owner_user_id=owner_uid, event_type="state_sync",
                                counterparty_wa_id=counterparty[:32] or None,
                                summary=str(evt_type)[:255], payload_json=json.dumps(state_evt)[:8000],
                            ))
                            db.session.commit()
                        except Exception as state_err:
                            db.session.rollback()
                            logging.error(f"[WA STATE SYNC ERROR] {state_err}")
                    continue

                # Delivery/read receipts for messages WE sent. Arrives as its
                # own "statuses" array, a sibling of "messages" on this same
                # change -- one entry per state transition (sent -> delivered
                # -> read, or failed), not a resend of the message itself.
                for status_evt in value.get("statuses", []) or []:
                    try:
                        wa_message_id = status_evt.get("id") or ""
                        status_val = (status_evt.get("status") or "").lower()
                        if not wa_message_id or status_val not in ("sent", "delivered", "read", "failed"):
                            continue
                        errors = status_evt.get("errors") or []
                        first_error = errors[0] if errors else {}
                        pricing = status_evt.get("pricing") or {}
                        db.session.add(WhatsAppMessageStatus(
                            owner_user_id=owner_uid,
                            wa_message_id=wa_message_id[:128],
                            recipient_id=(status_evt.get("recipient_id") or "")[:32] or None,
                            status=status_val,
                            error_code=str(first_error.get("code")) if first_error.get("code") is not None else None,
                            error_title=(first_error.get("title") or "")[:200] or None,
                            conversation_id=((status_evt.get("conversation") or {}).get("id") or "")[:128] or None,
                            pricing_category=(pricing.get("category") or "")[:24] or None,
                            raw_timestamp=str(status_evt.get("timestamp") or "")[:20] or None,
                        ))
                        db.session.commit()
                    except Exception as status_evt_err:
                        db.session.rollback()
                        logging.error(f"[WA MESSAGE STATUS ERROR] {status_evt_err}")

                # Detect whether these messages were posted INSIDE one of this
                # business's own registered WhatsApp groups. A message sent TO
                # a group carries the group's opaque ID as "to" (see
                # send_whatsapp_group_message); inbound "contacts" mirrors that
                # same ID format. Checked up front, before any 1:1 handling
                # runs — getting this wrong would mean replying to a group
                # participant's PERSONAL number just because they posted in a
                # shared group, when they never messaged the business directly.
                inbound_group_row = None
                if owner_uid:
                    contact_ids = {c.get("wa_id") for c in (value.get("contacts") or []) if c.get("wa_id")}
                    if contact_ids:
                        inbound_group_row = (WhatsAppGroup.query
                            .filter(WhatsAppGroup.user_id == owner_uid,
                                    WhatsAppGroup.meta_group_id.in_(contact_ids)).first())

                for msg in value.get("messages", []) or []:
                    _wa_capture_identity(owner_uid, value.get("contacts"), msg)
                    if msg.get("referral"):
                        _new_ref = _wa_capture_ad_referral(owner_uid, msg, value.get("contacts"))
                        if _new_ref is not None:
                            enqueue_job(_wa_capi_lead_job, app, owner_uid, _new_ref.id)
                    if inbound_group_row is not None:
                        # Group-context message — handled entirely separately
                        # from the 1:1 branches below, which all assume the
                        # sender is messaging the business directly. Only
                        # plain text is auto-replied to, and only when this
                        # specific group has opted in (off by default).
                        if (msg.get("type") == "text" and inbound_group_row.status == "active"
                                and inbound_group_row.auto_reply_enabled):
                            incoming_msg = ((msg.get("text") or {}).get("body") or "").strip()
                            sender_num = "+" + str(msg.get("from", ""))
                            if incoming_msg:
                                try:
                                    # session_id is VARCHAR(64) and channel is
                                    # VARCHAR(16) on ChatLog — use the group ID
                                    # itself (already unique) as session_id,
                                    # truncated defensively, with a short
                                    # dedicated channel value rather than a
                                    # prefixed key that could overflow either
                                    # column and get silently cut off.
                                    group_key = inbound_group_row.meta_group_id[:64]
                                    if group_key not in whatsapp_store:
                                        whatsapp_store[group_key] = _db_get_history(group_key, channel="wa_group")
                                    history = _get_history(whatsapp_store, group_key)
                                    ai_reply_raw, updated_history = generate_ai_reply(incoming_msg, history, user_id=owner_uid)
                                    _save_history(whatsapp_store, group_key, updated_history)
                                    _db_save_turn(group_key, "wa_group", "user", f"{sender_num}: {incoming_msg}", owner_user_id=owner_uid)
                                    _db_save_turn(group_key, "wa_group", "assistant", ai_reply_raw, owner_user_id=owner_uid)
                                    send_whatsapp_group_message(owner_uid, inbound_group_row.meta_group_id, text=ai_reply_raw)
                                except Exception as group_reply_err:
                                    logging.error(f"[WA GROUP AUTO-REPLY ERROR] {group_reply_err}")
                        # Whether or not auto-reply fired, never fall through to
                        # the 1:1 branches below for a message posted in a group.
                        continue
                    # Customer answered a call-permission request (see
                    # _wa_send_call_permission_request) — record it and release
                    # any call tasks that were waiting on it.
                    if msg.get("type") == "interactive" and \
                            (msg.get("interactive") or {}).get("type") == "call_permission_reply":
                        try:
                            _wa_handle_call_permission_reply(owner_uid, msg)
                        except Exception as perm_err:
                            db.session.rollback()
                            logging.error(f"[WA CALL PERMISSION REPLY ERROR] {perm_err}")
                        continue
                    # STAGE 19: a completed WhatsApp Flow submission arrives as an
                    # 'interactive' message of subtype 'nfm_reply' instead of plain
                    # text — capture it separately, then move on to the next message.
                    if msg.get("type") == "interactive" and \
                            (msg.get("interactive") or {}).get("type") == "nfm_reply":
                        _save_whatsapp_flow_response(owner_uid, msg)
                        continue
                    # STAGE 315: a tap on a catalog-list row (see
                    # send_whatsapp_catalog_list) arrives as a
                    # 'list_reply' — reply with that one product's full
                    # rich card instead of leaving the tap unanswered.
                    if msg.get("type") == "interactive" and \
                            (msg.get("interactive") or {}).get("type") == "list_reply":
                        row_id = ((msg.get("interactive") or {}).get("list_reply") or {}).get("id", "")
                        sender_num = "+" + str(msg.get("from", ""))
                        if row_id.startswith("prod-") and owner_uid:
                            try:
                                send_whatsapp_catalog_product(owner_uid, sender_num, row_id)
                            except Exception as list_err:
                                logging.error(f"[WA CATALOG LIST REPLY ERROR] {list_err}")
                        continue
                    # Tap on a Confirm/Cancel button (see send_whatsapp_button_message,
                    # currently used by the voice-ledger flow) arrives as a
                    # 'button_reply' — route it and stop, same as list_reply above.
                    # Kept as a small dispatcher (rather than hardcoding the
                    # voice-ledger prefix check inline) so a future second use of
                    # buttons elsewhere just adds another _handle_* call here.
                    if msg.get("type") == "interactive" and \
                            (msg.get("interactive") or {}).get("type") == "button_reply":
                        btn = (msg.get("interactive") or {}).get("button_reply") or {}
                        sender_num = _wa_sender_key(msg)
                        btn_id = btn.get("id", "")
                        try:
                            handled = _wa_payment_handle_button_reply(owner_uid, sender_num, btn_id)
                            if not handled:
                                handled = _voice_ledger_handle_button_reply(owner_uid, sender_num, btn_id)
                            if not handled:
                                _order_confirmation_handle_button_reply(owner_uid, sender_num, btn_id)
                        except Exception as btn_reply_err:
                            logging.error(f"[WA BUTTON REPLY ERROR] {btn_reply_err}")
                        continue
                    # A customer completing checkout inside a catalog/product
                    # message (see /messages/product-list, send_whatsapp_catalog_product)
                    # arrives as message type "order" — Meta's own cart summary,
                    # not something this platform's chatbot should try to answer
                    # conversationally. Persist it and stop.
                    if msg.get("type") == "order":
                        order_obj = msg.get("order") or {}
                        sender_num = str(msg.get("from", ""))
                        try:
                            items = order_obj.get("product_items") or []
                            total_cents = 0
                            currency = None
                            for it in items:
                                price = it.get("item_price")
                                qty = it.get("quantity") or 0
                                cur = it.get("currency")
                                if price is not None and qty:
                                    total_cents += int(round(float(price) * 100)) * int(qty)
                                if cur and not currency:
                                    currency = cur
                            db.session.add(WhatsAppCatalogOrder(
                                owner_user_id=owner_uid,
                                wa_message_id=(msg.get("id") or "")[:128] or None,
                                customer_wa_id=sender_num[:32] or None,
                                catalog_id=(order_obj.get("catalog_id") or "")[:64] or None,
                                order_text=(order_obj.get("text") or "") or None,
                                items_json=json.dumps(items),
                                currency=currency,
                                total_amount_cents=total_cents or None,
                                status="new",
                            ))
                            db.session.commit()
                            logging.info(f"[WA ORDER] from {sender_num}: {len(items)} item(s)")
                            # Real acknowledgment reaction on the customer's own
                            # order message -- a small but genuine touch (real
                            # Meta reaction, not a text auto-reply) confirming
                            # the order landed, before staff even open the app.
                            if owner_uid:
                                try:
                                    _whatsapp_cloud_react_raw(
                                        owner_uid, sender_num, (msg.get("id") or ""), "\U0001F44D")
                                except Exception as react_err:
                                    logging.error(f"[WA ORDER REACT ERROR] {react_err}")
                        except Exception as order_err:
                            db.session.rollback()
                            logging.error(f"[WA ORDER SAVE ERROR] {order_err}")
                        continue
                    # A customer changed their WhatsApp number. Meta sends this
                    # as a "system" message: msg.from is the customer's NEW
                    # number, msg.system.wa_id / customer is their OLD number.
                    # Re-point any stored records that referenced the old
                    # number so history/orders/call log don't silently orphan.
                    if msg.get("type") == "system":
                        system_obj = msg.get("system") or {}
                        if (system_obj.get("type") or "").lower() == "user_changed_number":
                            new_wa_id = str(msg.get("from") or "").strip()
                            old_wa_id = str(system_obj.get("wa_id") or system_obj.get("customer") or "").strip()
                            try:
                                if old_wa_id and new_wa_id and old_wa_id != new_wa_id:
                                    (WhatsAppCatalogOrder.query
                                     .filter_by(customer_wa_id=old_wa_id)
                                     .update({"customer_wa_id": new_wa_id}))
                                    (WhatsAppCall.query
                                     .filter_by(counterparty_wa_id=old_wa_id)
                                     .update({"counterparty_wa_id": new_wa_id}))
                                    db.session.add(WhatsAppCoexistenceEvent(
                                        owner_user_id=owner_uid, event_type="state_sync",
                                        counterparty_wa_id=new_wa_id[:32],
                                        summary=f"Customer changed number: {old_wa_id} -> {new_wa_id}",
                                        payload_json=json.dumps(system_obj)[:8000],
                                    ))
                                    db.session.commit()
                                    logging.info(f"[WA NUMBER CHANGE] {old_wa_id} -> {new_wa_id}")
                            except Exception as num_change_err:
                                db.session.rollback()
                                logging.error(f"[WA NUMBER CHANGE ERROR] {num_change_err}")
                        continue
                    # STAGE 167: voice-note-to-ledger — only ever runs for numbers
                    # the owner has explicitly authorized; every other sender's
                    # audio message is ignored exactly as before (no behavior
                    # change for ordinary customers).
                    if msg.get("type") == "audio":
                        sender_num = "+" + str(msg.get("from", ""))
                        media_id = (msg.get("audio") or {}).get("id")
                        if media_id and _voice_ledger_authorized(owner_uid, sender_num):
                            try:
                                _voice_ledger_handle_incoming_audio(owner_uid, sender_num, media_id)
                            except Exception as vl_err:
                                logging.error(f"[VOICE LEDGER ERROR] {vl_err}")
                        continue
                    if msg.get("type") != "text":
                        continue
                    sender_num   = _wa_sender_key(msg)
                    incoming_msg = ((msg.get("text") or {}).get("body") or "").strip()
                    # Meta's own id for THIS inbound message -- the value a
                    # reply must echo back in its "context.message_id" to
                    # render as a quoted reply in the customer's WhatsApp
                    # app. Captured here (not reconstructed later) because
                    # this is the only point where it's guaranteed to be
                    # attached to the right message.
                    inbound_wa_message_id = (msg.get("id") or "")[:128] or None
                    if not incoming_msg:
                        continue
                    logging.info(f"[WA CLOUD] from {sender_num}: '{incoming_msg}'")

                    # Marketing consent: STOP / START as the whole message.
                    if owner_uid and _wa_handle_marketing_keyword(owner_uid, sender_num, incoming_msg):
                        continue

                    # Real read receipt (blue ticks) + typing indicator the
                    # instant the message is processed, exactly like a human
                    # agent's WhatsApp Business app would show -- not just an
                    # internal unread counter. Best-effort: never blocks the
                    # reply pipeline if BYOK isn't configured for this number.
                    if owner_uid and inbound_wa_message_id:
                        try:
                            _whatsapp_cloud_mark_read_raw(owner_uid, inbound_wa_message_id, show_typing=True)
                        except Exception as mark_read_err:
                            logging.error(f"[WA CLOUD MARK READ ERROR] {mark_read_err}")

                    # STAGE 167: a pending voice-note entry takes priority over
                    # the normal chatbot reply — "YES"/"NO" confirms or cancels
                    # it instead of being answered as a generic question.
                    try:
                        if _voice_ledger_handle_incoming_text(owner_uid, sender_num, incoming_msg):
                            continue
                    except Exception as vl_err:
                        logging.error(f"[VOICE LEDGER TEXT ERROR] {vl_err}")

                    # STAGE 227: a reply from a customer/supplier who is
                    # mid-conversation with the AI invoice-chase / supplier-
                    # negotiation agent gets routed there instead of the
                    # generic chatbot reply below.
                    try:
                        active_thread = _find_active_negotiation_thread(owner_uid, sender_num)
                        if active_thread:
                            _negotiation_agent_handle_reply(active_thread, incoming_msg)
                            continue
                    except Exception as neg_err:
                        logging.error(f"[NEGOTIATION AGENT REPLY ERROR] {neg_err}")

                    if sender_num not in whatsapp_store:
                        whatsapp_store[sender_num] = _db_get_history(sender_num, channel="whatsapp_cloud")
                    history = _get_history(whatsapp_store, sender_num)

                    # Meta Business Agent handoff: if this customer was just handed
                    # over, a human who claimed the chat pauses the AI entirely;
                    # otherwise the AI reply is grounded in the ERP context packet.
                    ai_input = incoming_msg
                    if owner_uid:
                        try:
                            _h = _mba_active_handoff(owner_uid, sender_num)
                            if _h is not None:
                                if _h.status == "in_progress":
                                    _db_save_turn(sender_num, "whatsapp_cloud", "user", incoming_msg, owner_user_id=owner_uid)
                                    _inbox_log(owner_uid, "whatsapp", sender_num, "in", incoming_msg,
                                               wa_message_id=inbound_wa_message_id)
                                    notify_user(owner_uid, "whatsapp", "Customer replied (you have the chat)",
                                                incoming_msg[:200])
                                    continue
                                _ctx = _mba_context_for_ai(_h, incoming_msg)
                                if _ctx:
                                    ai_input = incoming_msg + "\n\n" + _ctx
                        except Exception as handoff_ctx_err:
                            logging.error(f"[MBA HANDOFF CONTEXT ERROR] {handoff_ctx_err}")

                    ai_reply_raw, updated_history = generate_ai_reply(ai_input, history)
                    _save_history(whatsapp_store, sender_num, updated_history)
                    _db_save_turn(sender_num, "whatsapp_cloud", "user",      incoming_msg, owner_user_id=owner_uid)
                    _db_save_turn(sender_num, "whatsapp_cloud", "assistant", ai_reply_raw,  owner_user_id=owner_uid)
                    _db_add_gratitude(f"WhatsApp Cloud ({sender_num})", incoming_msg)
                    _db_add_gratitude(AI_DISPLAY_NAME, ai_reply_raw)

                    # Feed the same turn into the Unified Customer Inbox
                    # (Stage 106) so a business sees WhatsApp conversations
                    # alongside SMS/email/Messenger threads instead of only
                    # in the separate WhatsApp chat log -- this webhook never
                    # wrote to that table before. Only when we actually
                    # resolved which business owns the receiving number;
                    # a platform-default send with no BYOK owner has no
                    # single business inbox to file it under.
                    if owner_uid:
                        wa_contact_name = None
                        for c in (value.get("contacts") or []):
                            if c.get("wa_id") == str(msg.get("from", "")):
                                wa_contact_name = ((c.get("profile") or {}).get("name") or "")[:120] or None
                                break
                        try:
                            _inbox_log(owner_uid, "whatsapp", sender_num, "in", incoming_msg,
                                       contact_name=wa_contact_name, wa_message_id=inbound_wa_message_id)
                        except Exception as inbox_err:
                            logging.error(f"[WA CLOUD INBOX LOG ERROR] {inbox_err}")

                    try:
                        send_result = send_whatsapp_cloud_message(owner_uid, sender_num, ai_reply_raw)
                        if owner_uid:
                            try:
                                out_wa_message_id = ((send_result.get("messages") or [{}])[0]).get("id")
                                _inbox_log(owner_uid, "whatsapp", sender_num, "out", ai_reply_raw,
                                           wa_message_id=out_wa_message_id)
                            except Exception as inbox_out_err:
                                logging.error(f"[WA CLOUD INBOX LOG OUT ERROR] {inbox_out_err}")
                    except Exception as send_err:
                        logging.error(f"[WA CLOUD REPLY ERROR] {send_err}")
        return connectit_json_response({"status": "received"})
    except Exception as e:
        logging.error(f"[WHATSAPP CLOUD WEBHOOK ERROR] {e}")
        return connectit_json_response({"error": str(e)}, 500)


# ════════════════════════════════════════════════════════════
# STAGE 19: WHATSAPP FLOWS
# Structured forms rendered *inside* the WhatsApp chat itself (booking,
# surveys, lead capture) instead of free-text back-and-forth. Free —
# reuses the same whatsapp_cloud phone_number_id/access_token BYOK
# credentials; the only new field is the Flow ID itself, created in
# Meta's Flow Builder (business.facebook.com/wa/manage/flows).
# ════════════════════════════════════════════════════════════

def _whatsapp_flow_id_for_user(user_id) -> str:
    return get_effective_credential(user_id, "whatsapp_flows", "flow_id", WHATSAPP_FLOWS_DEFAULT_FLOW_ID)


def send_whatsapp_flow(user_id, to_number: str, flow_cta: str, body_text: str = "",
                        header_text: str = "", flow_id: str = "", screen: str = "WELCOME_SCREEN") -> dict:
    """Sends an interactive 'flow' message — the customer taps the CTA and a
    native form opens inline in WhatsApp, no leaving the chat."""
    creds = _whatsapp_cloud_creds_for_user(user_id)
    resolved_flow_id = flow_id or _whatsapp_flow_id_for_user(user_id)
    if not creds["phone_number_id"] or not creds["access_token"]:
        return {"ok": False, "error": "WhatsApp Cloud API is not configured. Add your Phone Number ID and Access Token under Integrations."}
    if not resolved_flow_id:
        return {"ok": False, "error": "No Flow ID configured. Create a Flow in Meta's Flow Builder and add its ID under Integrations."}
    to_clean = re.sub(r"\D", "", to_number or "")
    if not to_clean:
        return {"ok": False, "error": "Valid recipient phone number required."}
    interactive = {
        "type": "flow",
        "body": {"text": body_text or "Please fill out this quick form."},
        "action": {
            "name": "flow",
            "parameters": {
                "flow_message_version": "3",
                "flow_token": _flow_token_make(user_id, to_clean),
                "flow_id": resolved_flow_id,
                "flow_cta": (flow_cta or "Start")[:20],
                "flow_action": "navigate",
                "flow_action_payload": {"screen": screen},
            },
        },
    }
    if header_text:
        interactive["header"] = {"type": "text", "text": header_text}
    try:
        r = requests.post(
            f"https://graph.facebook.com/{WHATSAPP_CLOUD_API_VERSION}/{creds['phone_number_id']}/messages",
            headers={"Authorization": f"Bearer {creds['access_token']}", "Content-Type": "application/json"},
            json={"messaging_product": "whatsapp", "to": to_clean, "type": "interactive", "interactive": interactive},
            timeout=15,
        )
        body = r.json()
        if r.status_code >= 400:
            return {"ok": False, "error": (body.get("error") or {}).get("message", "Could not send Flow.")}
        return {"ok": True, "message_id": ((body.get("messages") or [{}])[0]).get("id")}
    except Exception as e:
        logging.error(f"[WHATSAPP FLOW SEND ERROR] user={user_id}: {e}")
        return {"ok": False, "error": str(e)}


def _save_whatsapp_flow_response(user_id, msg: dict) -> None:
    """Persists a completed Flow submission from the 'nfm_reply' webhook payload."""
    try:
        nfm = (msg.get("interactive") or {}).get("nfm_reply") or {}
        response_raw = nfm.get("response_json") or "{}"
        row = WhatsAppFlowResponse(
            user_id=user_id,
            from_number="+" + str(msg.get("from", "")),
            flow_id=_whatsapp_flow_id_for_user(user_id) or "",
            flow_name=nfm.get("name", ""),
            response_json=response_raw,
        )
        db.session.add(row)
        db.session.commit()
        logging.info(f"[WHATSAPP FLOW RESPONSE] from {row.from_number} user={user_id}")
        # STAGE 36: fire a "new_lead" event to the user's Zapier/Make
        # webhook, if they've connected one — no-op otherwise.
        lead_payload = {
            "source": "whatsapp_flow",
            "from_number": row.from_number,
            "flow_name": row.flow_name,
            "response": response_raw,
        }
        trigger_zapier_event(user_id, "new_lead", lead_payload)
        # STAGE 300: also fire any workspace automation workflows
        # listening for "new_lead" — no-op if no workspace/workflow.
        fire_automation_trigger(_automation_org_id_for_user(user_id), "new_lead", lead_payload)

        # STAGE 315: if this looks like the documented RFQ intake shape
        # (see WHATSAPP_RFQ_FLOW_SCREEN above), ping the seller right
        # away with a readable summary instead of leaving it sitting as
        # inert JSON they'd only see by checking Flow responses later.
        try:
            parsed = json.loads(response_raw)
        except Exception:
            parsed = {}
        if isinstance(parsed, dict) and parsed.get("product_name") and parsed.get("quantity"):
            seller = UserAccount.query.get(user_id)
            if seller and seller.whatsapp_number:
                try:
                    send_whatsapp_cloud_message(
                        user_id, seller.whatsapp_number,
                        f" New RFQ from {row.from_number}: {parsed.get('quantity')} x {parsed.get('product_name')}"
                        + (f" ({parsed.get('unit')})" if parsed.get("unit") else "")
                        + (f" — target price {parsed.get('target_price')}" if parsed.get("target_price") else "")
                        + (f". Notes: {parsed.get('notes')}" if parsed.get("notes") else ""))
                except Exception as notify_err:
                    logging.error(f"[RFQ FLOW SELLER NOTIFY ERROR] {notify_err}")
    except Exception as e:
        logging.error(f"[WHATSAPP FLOW RESPONSE SAVE ERROR] {e}")


# ════════════════════════════════════════════════════════════
# WHATSAPP FLOW DEFINITIONS — CRUD for the Flow itself (the JSON form
# structure shown in Meta's Flow Builder), as opposed to send_whatsapp_flow()
# above which just sends an *existing* published Flow to a customer.
# Lets a business create/update a Flow's screens from this platform
# instead of only through business.facebook.com/wa/manage/flows.
# ════════════════════════════════════════════════════════════

@app.route("/api/whatsapp-cloud/flows", methods=["GET"])
def whatsapp_cloud_flows_list():
    """Lists Flows that exist under this WABA, with their current status
    (DRAFT, PUBLISHED, DEPRECATED)."""
    current_user = _get_current_user()
    if not current_user:
        return connectit_json_response({"error": "Login required"}, 401)
    creds, err = _whatsapp_waba_creds_or_error(current_user)
    if err:
        return err
    try:
        resp = requests.get(
            f"https://graph.facebook.com/{WHATSAPP_CLOUD_API_VERSION}/{creds['business_account_id']}/flows",
            headers={"Authorization": f"Bearer {creds['access_token']}"},
            params={"fields": "id,name,status,categories,validation_errors,json_version"},
            timeout=15,
        )
        body = resp.json()
        if resp.status_code >= 400:
            return connectit_json_response(
                {"error": (body.get("error") or {}).get("message", "Could not list Flows.")}, 502)
        return connectit_json_response({"flows": body.get("data", [])})
    except Exception as e:
        logging.error(f"[WA FLOWS LIST ERROR] {e}")
