@app.route("/api/whatsapp-cloud/flows", methods=["POST"])
@csrf.exempt
def whatsapp_cloud_flows_create():
    """Creates a new (DRAFT) Flow. `categories` is a list drawn from
    Meta's set (SIGN_UP, SIGN_IN, APPOINTMENT_BOOKING, LEAD_GENERATION,
    CONTACT_US, CUSTOMER_SUPPORT, SURVEY, OTHER)."""
    current_user = _get_current_user()
    if not current_user:
        return connectit_json_response({"error": "Login required"}, 401)
    creds, err = _whatsapp_waba_creds_or_error(current_user)
    if err:
        return err
    data = request.get_json(force=True) or {}
    name = (data.get("name") or "").strip()
    categories = data.get("categories") or []
    if not name:
        return connectit_json_response({"error": "name is required."}, 400)
    if not categories:
        return connectit_json_response({"error": "At least one category is required."}, 400)
    try:
        resp = requests.post(
            f"https://graph.facebook.com/{WHATSAPP_CLOUD_API_VERSION}/{creds['business_account_id']}/flows",
            headers={"Authorization": f"Bearer {creds['access_token']}", "Content-Type": "application/json"},
            json={"name": name, "categories": categories},
            timeout=15,
        )
        body = resp.json()
        if resp.status_code >= 400:
            return connectit_json_response(
                {"error": (body.get("error") or {}).get("message", "Could not create Flow.")}, 502)
        logging.info(f"[WA FLOW CREATE] user={current_user['id']} name={name} id={body.get('id')}")
        return connectit_json_response({"flow_id": body.get("id")})
    except Exception as e:
        logging.error(f"[WA FLOW CREATE ERROR] {e}")
        return connectit_json_response({"error": str(e)}, 500)


@app.route("/api/whatsapp-cloud/flows/<path:flow_id>/preview", methods=["GET"])
def whatsapp_cloud_flows_preview(flow_id):
    """Returns a short-lived preview URL for this Flow — lets a business
    check how it renders before publishing. Works for both DRAFT and
    PUBLISHED Flows. Pass ?invalidate=true to force a fresh link instead
    of reusing a still-valid cached one."""
    current_user = _get_current_user()
    if not current_user:
        return connectit_json_response({"error": "Login required"}, 401)
    creds, err = _whatsapp_waba_creds_or_error(current_user)
    if err:
        return err
    invalidate = (request.args.get("invalidate", "false").lower() == "true")
    try:
        resp = requests.get(
            f"https://graph.facebook.com/{WHATSAPP_CLOUD_API_VERSION}/{flow_id}",
            headers={"Authorization": f"Bearer {creds['access_token']}"},
            params={"fields": f"preview.invalidate({'true' if invalidate else 'false'})"},
            timeout=15,
        )
        body = resp.json()
        if resp.status_code >= 400:
            return connectit_json_response(
                {"error": (body.get("error") or {}).get("message", "Could not fetch Flow preview.")}, 502)
        preview = body.get("preview", {})
        return connectit_json_response({
            "preview_url": preview.get("preview_url"), "expires_at": preview.get("expires_at"),
        })
    except Exception as e:
        logging.error(f"[WA FLOW PREVIEW ERROR] {e}")
        return connectit_json_response({"error": str(e)}, 500)


@app.route("/api/whatsapp-cloud/flows/<path:flow_id>/json", methods=["POST"])
@csrf.exempt
def whatsapp_cloud_flows_update_json(flow_id):
    """Uploads the Flow's screen JSON (the form structure) — only
    possible while the Flow is still in DRAFT status. `flow_json` is
    the full Flow JSON object per Meta's Flow JSON schema."""
    current_user = _get_current_user()
    if not current_user:
        return connectit_json_response({"error": "Login required"}, 401)
    creds, err = _whatsapp_waba_creds_or_error(current_user)
    if err:
        return err
    data = request.get_json(force=True) or {}
    flow_json = data.get("flow_json")
    if not isinstance(flow_json, dict):
        return connectit_json_response({"error": "flow_json must be a JSON object."}, 400)
    try:
        import io as _io
        json_bytes = json.dumps(flow_json).encode("utf-8")
        resp = requests.post(
            f"https://graph.facebook.com/{WHATSAPP_CLOUD_API_VERSION}/{flow_id}/assets",
            headers={"Authorization": f"Bearer {creds['access_token']}"},
            data={"name": "flow.json", "asset_type": "FLOW_JSON"},
            files={"file": ("flow.json", _io.BytesIO(json_bytes), "application/json")},
            timeout=20,
        )
        body = resp.json()
        if resp.status_code >= 400:
            return connectit_json_response(
                {"error": (body.get("error") or {}).get("message", "Could not upload Flow JSON.")}, 502)
        logging.info(f"[WA FLOW JSON UPLOAD] user={current_user['id']} flow_id={flow_id}")
        return connectit_json_response({"uploaded": True, "validation_errors": body.get("validation_errors", [])})
    except Exception as e:
        logging.error(f"[WA FLOW JSON UPLOAD ERROR] {e}")
        return connectit_json_response({"error": str(e)}, 500)


