@app.route("/api/whatsapp-cloud/qr-codes", methods=["POST"])
@csrf.exempt
def whatsapp_cloud_qr_codes_create():
    """Creates a new QR code / short link with a prefilled message."""
    current_user = _get_current_user()
    if not current_user:
        return connectit_json_response({"error": "Login required"}, 401)
    creds = _whatsapp_cloud_creds_for_user(current_user["id"])
    if not creds["access_token"] or not creds["phone_number_id"]:
        return connectit_json_response({"error": "WhatsApp Cloud API is not configured."}, 503)
    data = request.get_json(force=True) or {}
    prefilled_message = (data.get("prefilled_message") or "").strip()
    image_format = (data.get("generate_qr_image") or "PNG").strip().upper()
    if not prefilled_message:
        return connectit_json_response({"error": "prefilled_message is required."}, 400)
    if image_format not in ("PNG", "SVG"):
        image_format = "PNG"
    try:
        resp = requests.post(
            f"https://graph.facebook.com/{WHATSAPP_CLOUD_API_VERSION}/{creds['phone_number_id']}/message_qrdls",
            headers={"Authorization": f"Bearer {creds['access_token']}", "Content-Type": "application/json"},
            json={"prefilled_message": prefilled_message, "generate_qr_image": image_format},
            timeout=15,
        )
        body = resp.json()
        if resp.status_code >= 400:
            return connectit_json_response(
                {"error": (body.get("error") or {}).get("message", "Could not create QR code.")}, 502)
        logging.info(f"[WA QR CREATE] user={current_user['id']} code={body.get('code')}")
        return connectit_json_response(body)
    except Exception as e:
        logging.error(f"[WA QR CREATE ERROR] {e}")
        return connectit_json_response({"error": str(e)}, 500)


