# ════════════════════════════════════════════════════════════
# ACCOUNT STATUS — business verification status (WABA-level) and
# messaging throughput / quality tier (phone-number-level). Read-only:
# Meta reviews and assigns these; nothing here can change them, but a
# business needs to see them to understand sending limits and why a
# number might be quality-flagged.
# ════════════════════════════════════════════════════════════

@app.route("/api/whatsapp-cloud/account/status", methods=["GET"])
def whatsapp_cloud_account_status():
    """Combines WABA-level business verification/review status with this
    phone number's quality rating and messaging throughput tier."""
    current_user = _get_current_user()
    if not current_user:
        return connectit_json_response({"error": "Login required"}, 401)
    creds = _whatsapp_cloud_creds_for_user(current_user["id"])
    if not creds["access_token"] or not creds["phone_number_id"]:
        return connectit_json_response({"error": "WhatsApp Cloud API is not configured."}, 503)
    business_account_id = get_effective_credential(current_user["id"], "whatsapp_cloud", "business_account_id", "") \
        or WHATSAPP_CLOUD_BUSINESS_ID
    result = {}
    try:
        if business_account_id:
            waba_resp = requests.get(
                f"https://graph.facebook.com/{WHATSAPP_CLOUD_API_VERSION}/{business_account_id}",
                headers={"Authorization": f"Bearer {creds['access_token']}"},
                params={"fields": "account_review_status,business_verification_status,name"},
                timeout=15,
            )
            waba_body = waba_resp.json()
            if waba_resp.status_code < 400:
                result["account_review_status"] = waba_body.get("account_review_status")
                result["business_verification_status"] = waba_body.get("business_verification_status")
                result["business_name"] = waba_body.get("name")
        phone_resp = requests.get(
            f"https://graph.facebook.com/{WHATSAPP_CLOUD_API_VERSION}/{creds['phone_number_id']}",
            headers={"Authorization": f"Bearer {creds['access_token']}"},
            params={"fields": "verified_name,code_verification_status,quality_rating,"
                               "throughput,status,messaging_limit_tier,health_status"},
            timeout=15,
        )
        phone_body = phone_resp.json()
        if phone_resp.status_code >= 400:
            return connectit_json_response(
                {"error": (phone_body.get("error") or {}).get("message", "Could not fetch phone number status.")}, 502)
        health = phone_body.get("health_status") or {}
        result.update({
            "verified_name": phone_body.get("verified_name"),
            "code_verification_status": phone_body.get("code_verification_status"),
            "quality_rating": phone_body.get("quality_rating"),
            "throughput_level": (phone_body.get("throughput") or {}).get("level"),
            "status": phone_body.get("status"),
            "messaging_limit_tier": phone_body.get("messaging_limit_tier"),
            "health_status": health.get("can_send_message"),
            "health_status_entities": health.get("entities", []),
        })
        return connectit_json_response(result)
    except Exception as e:
        logging.error(f"[WA ACCOUNT STATUS ERROR] {e}")
        return connectit_json_response({"error": str(e)}, 500)


