# CONVERSATIONAL AUTOMATION — ice breakers (tappable conversation
# starters shown before a customer's first message) and a commands
# menu (the "/" slash-command list inside a chat). Both live under this
# phone number's `conversational_automation` field. A dedicated "away
# message" API does not exist for Cloud API numbers (it's a
# WhatsApp Business App-only setting) — not implemented here since
# there's no real endpoint behind it to wire up.
# ════════════════════════════════════════════════════════════

@app.route("/api/whatsapp-cloud/conversational-automation", methods=["GET"])
def whatsapp_cloud_conversational_automation_get():
    """Returns this number's current ice breakers and commands menu."""
    current_user = _get_current_user()
    if not current_user:
        return connectit_json_response({"error": "Login required"}, 401)
    creds = _whatsapp_cloud_creds_for_user(current_user["id"])
    if not creds["access_token"] or not creds["phone_number_id"]:
        return connectit_json_response({"error": "WhatsApp Cloud API is not configured."}, 503)
    try:
        resp = requests.get(
            f"https://graph.facebook.com/{WHATSAPP_CLOUD_API_VERSION}/{creds['phone_number_id']}",
            headers={"Authorization": f"Bearer {creds['access_token']}"},
            params={"fields": "conversational_automation"},
            timeout=15,
        )
        body = resp.json()
        if resp.status_code >= 400:
            return connectit_json_response(
                {"error": (body.get("error") or {}).get("message", "Could not fetch conversational automation settings.")}, 502)
        return connectit_json_response({"conversational_automation": body.get("conversational_automation", {})})
    except Exception as e:
        logging.error(f"[WA CONV AUTOMATION GET ERROR] {e}")
        return connectit_json_response({"error": str(e)}, 500)


@app.route("/api/whatsapp-cloud/conversational-automation", methods=["POST"])
@csrf.exempt
def whatsapp_cloud_conversational_automation_update():
    """Updates ice breakers (`prompts`, up to 4 short strings) and the
    commands menu (`commands`, up to 30 {command_name, command_description}
    entries). `enable_welcome_message` turns the whole greeting screen
    on/off."""
    current_user = _get_current_user()
    if not current_user:
        return connectit_json_response({"error": "Login required"}, 401)
    creds = _whatsapp_cloud_creds_for_user(current_user["id"])
    if not creds["access_token"] or not creds["phone_number_id"]:
        return connectit_json_response({"error": "WhatsApp Cloud API is not configured."}, 503)
    data = request.get_json(force=True) or {}
    payload = {}
    if "enable_welcome_message" in data:
        payload["enable_welcome_message"] = bool(data["enable_welcome_message"])
    if "prompts" in data:
        prompts = [p[:80] for p in (data.get("prompts") or []) if p][:4]
        payload["prompts"] = prompts
    if "commands" in data:
        commands = [{
            "command_name": (c.get("command_name") or "")[:32],
            "command_description": (c.get("command_description") or "")[:256],
        } for c in (data.get("commands") or [])][:30]
        payload["commands"] = commands
    if not payload:
        return connectit_json_response({"error": "Nothing to update — provide enable_welcome_message, prompts, and/or commands."}, 400)
    try:
        resp = requests.post(
            f"https://graph.facebook.com/{WHATSAPP_CLOUD_API_VERSION}/{creds['phone_number_id']}",
            headers={"Authorization": f"Bearer {creds['access_token']}", "Content-Type": "application/json"},
            json={"conversational_automation": payload},
            timeout=15,
        )
        body = resp.json()
        if resp.status_code >= 400:
            return connectit_json_response(
                {"error": (body.get("error") or {}).get("message", "Could not update conversational automation settings.")}, 502)
        logging.info(f"[WA CONV AUTOMATION UPDATE] user={current_user['id']} fields={list(payload.keys())}")
        return connectit_json_response({"updated": bool(body.get("success", True))})
    except Exception as e:
        logging.error(f"[WA CONV AUTOMATION UPDATE ERROR] {e}")
        return connectit_json_response({"error": str(e)}, 500)


