# ════════════════════════════════════════════════════════════
# STAGE 11: WHATSAPP BUSINESS CATALOG
# Reuses the same whatsapp_cloud BYOK credentials (access_token) plus
# a catalog_id — lets a seller list products that customers browse
# and buy right inside the WhatsApp chat. Free; Meta only charges for
# the messages themselves, same as every other Cloud API message.
# ════════════════════════════════════════════════════════════

def list_whatsapp_catalog_products(user_id) -> dict:
    creds = _whatsapp_cloud_creds_for_user(user_id)
    catalog_id = get_effective_credential(user_id, "whatsapp_cloud", "catalog_id", "")
    if not catalog_id or not creds["access_token"]:
        return {"ok": False, "error": "Add your Meta Catalog ID under WhatsApp Cloud settings first."}
    try:
        r = requests.get(
            f"https://graph.facebook.com/{WHATSAPP_CLOUD_API_VERSION}/{catalog_id}/products",
            params={"fields": "id,name,retailer_id,price,currency,availability,image_url", "limit": 50},
            headers={"Authorization": f"Bearer {creds['access_token']}"},
            timeout=15,
        )
        body = r.json()
        if r.status_code >= 400:
            return {"ok": False, "error": (body.get("error") or {}).get("message", "Meta Catalog error.")}
        products = [{
            "id": p.get("id"), "name": p.get("name"), "retailer_id": p.get("retailer_id"),
            "price": p.get("price"), "currency": p.get("currency"),
            "availability": p.get("availability"), "image_url": p.get("image_url"),
        } for p in body.get("data", [])]
        return {"ok": True, "products": products}
    except Exception as e:
        logging.error(f"[WA CATALOG LIST ERROR] user={user_id}: {e}")
        return {"ok": False, "error": str(e)}


def add_whatsapp_catalog_product(user_id, name: str, price_cents: int, currency: str,
                                  retailer_id: str, image_url: str = "", url: str = "",
                                  description: str = "") -> dict:
    creds = _whatsapp_cloud_creds_for_user(user_id)
    catalog_id = get_effective_credential(user_id, "whatsapp_cloud", "catalog_id", "")
    if not catalog_id or not creds["access_token"]:
        return {"ok": False, "error": "Add your Meta Catalog ID under WhatsApp Cloud settings first."}
    if not (name and retailer_id and price_cents and currency):
        return {"ok": False, "error": "name, retailer_id, price, and currency are required."}
    try:
        r = requests.post(
            f"https://graph.facebook.com/{WHATSAPP_CLOUD_API_VERSION}/{catalog_id}/products",
            headers={"Authorization": f"Bearer {creds['access_token']}"},
            data={
                "retailer_id": retailer_id,
                "name": name,
                "description": description,
                "price": int(price_cents),
                "currency": currency.upper(),
                "image_url": image_url,
                "url": url,
                "availability": "in stock",
                "condition": "new",
            },
            timeout=15,
        )
        body = r.json()
        if r.status_code >= 400:
            return {"ok": False, "error": (body.get("error") or {}).get("message", "Could not add product.")}
        return {"ok": True, "product_id": body.get("id")}
    except Exception as e:
        logging.error(f"[WA CATALOG ADD ERROR] user={user_id}: {e}")
        return {"ok": False, "error": str(e)}


def send_whatsapp_catalog_product(user_id, to_number: str, retailer_id: str, body_text: str = "") -> dict:
    """Sends a single product from the catalog directly inside a WhatsApp
    chat — the customer sees a rich card with photo, name, and price."""
    creds = _whatsapp_cloud_creds_for_user(user_id)
    catalog_id = get_effective_credential(user_id, "whatsapp_cloud", "catalog_id", "")
    if not catalog_id or not creds["phone_number_id"] or not creds["access_token"]:
        return {"ok": False, "error": "WhatsApp Cloud + Catalog not fully configured."}
    to_clean = re.sub(r"\D", "", to_number or "")
    try:
        r = requests.post(
            f"https://graph.facebook.com/{WHATSAPP_CLOUD_API_VERSION}/{creds['phone_number_id']}/messages",
            headers={"Authorization": f"Bearer {creds['access_token']}", "Content-Type": "application/json"},
            json={
                "messaging_product": "whatsapp",
                "to": to_clean,
                "type": "interactive",
                "interactive": {
                    "type": "product",
                    "body": {"text": body_text or "Take a look at this!"},
                    "action": {"catalog_id": catalog_id, "product_retailer_id": retailer_id},
                },
            },
            timeout=15,
        )
        body = r.json()
        if r.status_code >= 400:
            return {"ok": False, "error": (body.get("error") or {}).get("message", "Could not send product.")}
        return {"ok": True, "message_id": ((body.get("messages") or [{}])[0]).get("id")}
    except Exception as e:
        logging.error(f"[WA CATALOG SEND ERROR] user={user_id}: {e}")
        return {"ok": False, "error": str(e)}


# STAGE 315: CATALOG BROWSING VIA INTERACTIVE LIST MESSAGE
# send_whatsapp_catalog_product() above sends ONE product card at a
# time — fine once a customer already knows what they want, but not
# for "show me what you've got." This sends up to 10 of the seller's
# own active Marketplace listings as a single tappable list (WhatsApp's
# hard cap per list message); the reply handler in the webhook below
# turns a tapped row into the same single-product card.
def send_whatsapp_catalog_list(user_id, to_number: str, header_text: str = "", body_text: str = "") -> dict:
    creds = _whatsapp_cloud_creds_for_user(user_id)
    if not creds["phone_number_id"] or not creds["access_token"]:
        return {"ok": False, "error": "WhatsApp Cloud API is not configured."}
    to_clean = re.sub(r"\D", "", to_number or "")
    if not to_clean:
        return {"ok": False, "error": "Valid recipient phone number required."}
    products = (Product.query.filter_by(seller_id=user_id, is_active=True)
                .order_by(Product.created_at.desc()).limit(10).all())
    if not products:
        return {"ok": False, "error": "No active listings to show — list a product first."}
    rows = [{
        "id": f"prod-{p.id}",
        "title": (p.name or "Product")[:24],
        "description": f"{p.currency} {p.price:,.2f}"[:72],
    } for p in products]
    interactive = {
        "type": "list",
        "header": {"type": "text", "text": (header_text or "Our Catalog")[:60]},
        "body": {"text": body_text or "Tap a product below to see details."},
        "action": {"button": "View Products", "sections": [{"title": "Available Products", "rows": rows}]},
    }
    try:
        r = requests.post(
            f"https://graph.facebook.com/{WHATSAPP_CLOUD_API_VERSION}/{creds['phone_number_id']}/messages",
            headers={"Authorization": f"Bearer {creds['access_token']}", "Content-Type": "application/json"},
            json={"messaging_product": "whatsapp", "to": to_clean, "type": "interactive", "interactive": interactive},
            timeout=15,
        )
        body = r.json()
        if r.status_code >= 400:
            return {"ok": False, "error": (body.get("error") or {}).get("message", "Could not send catalog list.")}
        return {"ok": True, "message_id": ((body.get("messages") or [{}])[0]).get("id")}
    except Exception as e:
        logging.error(f"[WA CATALOG LIST SEND ERROR] user={user_id}: {e}")
        return {"ok": False, "error": str(e)}


@app.route("/api/whatsapp-cloud/send-catalog-list", methods=["POST"])
@csrf.exempt
def whatsapp_cloud_send_catalog_list():
    current_user = _get_current_user()
    if not current_user:
        return connectit_json_response({"error": "Login required"}, 401)
    data = request.get_json(silent=True) or {}
    to = sanitize_phone(data.get("to", ""))
    if not to:
        return connectit_json_response({"error": "Valid recipient phone number required"}, 400)
    result = send_whatsapp_catalog_list(
        current_user["id"], to, header_text=data.get("header_text", ""), body_text=data.get("body_text", ""))
    return connectit_json_response(result, 200 if result.get("ok") else 400)


@app.route("/api/whatsapp-catalog/products", methods=["GET"])
@csrf.exempt
def whatsapp_catalog_products_get():
    current_user = _get_current_user()
