@app.route("/api/whatsapp-cloud/messages/contacts", methods=["POST"])
@csrf.exempt
def whatsapp_cloud_send_contacts():
    """Sends one or more vCard-style contact cards. `contacts` follows
    Meta's contacts[] schema: [{name:{formatted_name,first_name},
    phones:[{phone,type}], emails:[{email,type}], ...}]."""
    current_user = _get_current_user()
    if not current_user:
        return connectit_json_response({"error": "Login required"}, 401)
    data = request.get_json(force=True) or {}
    to = sanitize_phone(data.get("to", ""))
    contacts = data.get("contacts") or []
    if not to:
        return connectit_json_response({"error": "Valid recipient phone number required."}, 400)
    if not contacts:
        return connectit_json_response({"error": "At least one contact is required."}, 400)
    clean_contacts = []
    for c in contacts:
        name = c.get("name") or {}
        formatted = (name.get("formatted_name") or "").strip()
        if not formatted:
            return connectit_json_response({"error": "Each contact needs name.formatted_name."}, 400)
        entry = {"name": {"formatted_name": formatted[:200], "first_name": (name.get("first_name") or formatted)[:100]}}
        if c.get("phones"):
            entry["phones"] = [{"phone": p.get("phone", ""), "type": p.get("type", "CELL")} for p in c["phones"]]
        if c.get("emails"):
            entry["emails"] = [{"email": e.get("email", ""), "type": e.get("type", "WORK")} for e in c["emails"]]
        if c.get("org"):
            entry["org"] = {"company": (c["org"].get("company") or "")[:200]}
        clean_contacts.append(entry)
    body, err = _whatsapp_send_or_error(current_user, {
        "messaging_product": "whatsapp", "to": to, "type": "contacts", "contacts": clean_contacts,
    })
    if err:
        return err
    return connectit_json_response({"sent": True, "message_id": ((body.get("messages") or [{}])[0]).get("id")})


