@app.route("/api/payments/paypal/create-order", methods=["POST"])
@csrf.exempt
def paypal_create_order():
    """Create a PayPal order for JavaScript SDK integration."""
    if not PAYPAL_CLIENT_ID or not PAYPAL_CLIENT_SECRET:
        return connectit_json_response({
            "error": "PayPal not configured",
            "paypal_email": CONNECTIT_PAYPAL_EMAIL,
            "instructions": "Send payment directly to " + CONNECTIT_PAYPAL_EMAIL
        }, 503)
    try:
        data     = request.get_json(force=True) or {}
        amount   = float(data.get("amount", 0))
        currency = data.get("currency", "USD").upper()
        desc     = data.get("description", "Connect It Payment")
        tx_ref   = generate_tx_ref("PP")

        if not validate_amount(amount):
            return connectit_json_response({"error": "Invalid amount"}, 400)

        access_token = get_paypal_access_token()
        if not access_token:
            return connectit_json_response({"error": "PayPal authentication failed"}, 503)

        base = ("https://api-m.paypal.com"
                if PAYPAL_MODE == "live"
                else "https://api-m.sandbox.paypal.com")
        resp = requests.post(
            f"{base}/v2/checkout/orders",
            headers={
                "Authorization": f"Bearer {access_token}",
                "Content-Type":  "application/json"
            },
            json={
                "intent": "CAPTURE",
                "purchase_units": [{
                    "amount": {
                        "currency_code": currency,
                        "value": f"{amount:.2f}"
                    },
                    "description": desc,
                    "custom_id":   tx_ref,
                    "payee": {"email_address": CONNECTIT_PAYPAL_EMAIL}
                }]
            },
            timeout=15
        )
        order = resp.json()
        if resp.ok:
            approval_url = next(
                (l.get("href") for l in order.get("links", []) if l.get("rel") == "approve"),
                None
            )
            logging.info(f"[PAYPAL] Order created: {order['id']} | {currency} {amount:.2f}")
            return connectit_json_response({
                "order_id":     order["id"],
                "tx_ref":       tx_ref,
                "approval_url": approval_url,
                "url":          approval_url
            })
        raise ValueError(order.get("message", "PayPal order creation failed"))
    except Exception as e:
        logging.error(f"[PAYPAL ERROR] {e}")
        return connectit_json_response({"error": str(e)}, 500)


@app.route("/api/payments/paypal/capture/<order_id>", methods=["POST"])
@csrf.exempt
def paypal_capture_order(order_id):
    """Capture an approved PayPal order."""
    try:
        access_token = get_paypal_access_token()
        if not access_token:
            return connectit_json_response({"error": "PayPal auth failed"}, 503)
        base = ("https://api-m.paypal.com"
                if PAYPAL_MODE == "live"
                else "https://api-m.sandbox.paypal.com")
        resp = requests.post(
            f"{base}/v2/checkout/orders/{order_id}/capture",
            headers={
                "Authorization": f"Bearer {access_token}",
                "Content-Type":  "application/json"
            },
            timeout=15
        )
        data = resp.json()
        if resp.ok and data.get("status") == "COMPLETED":
            unit   = data["purchase_units"][0]
            amount = float(unit["payments"]["captures"][0]["amount"]["value"])
            tx_ref = unit.get("custom_id", order_id)
            logging.info(f"[PAYPAL CAPTURED] ${amount:.2f} | ref={tx_ref}")
            send_payment_notification_whatsapp(tx_ref, "PayPal", amount)
            return connectit_json_response({
                "captured": True,
                "amount":   amount,
                "tx_ref":   tx_ref,
                "order_id": order_id
            })
        return connectit_json_response(
            {"error": data.get("message", "Capture failed")}, 400)
    except Exception as e:
        logging.error(f"[PAYPAL CAPTURE ERROR] {e}")
        return connectit_json_response({"error": str(e)}, 500)


