# ════════════════════════════════════════════════════════════
# STAGE 45: SAVINGS GROUP (VSLA / STOKVEL) TRACKER — real, persisted
# contribution and payout ledger for informal community savings
# groups. Every group belongs to whichever signed-in user created it
# (the treasurer); all endpoints below check that ownership before
# allowing any read or write, so one treasurer can never see or touch
# another's group.
# ════════════════════════════════════════════════════════════

def _savings_group_or_404(group_id, user_id):
    group = SavingsGroup.query.filter_by(id=group_id, owner_user_id=user_id).first()
    return group


def _savings_member_balances(group_id) -> list:
    """Live per-member balance = sum(contributions) - sum(loans+payouts).
    Computed fresh every call so the ledger can never silently drift."""
    members = SavingsGroupMember.query.filter_by(group_id=group_id).order_by(SavingsGroupMember.name.asc()).all()
    out = []
    for m in members:
        txns = SavingsTransaction.query.filter_by(member_id=m.id).all()
        contributed = sum(t.amount for t in txns if t.kind == "contribution")
        taken_out   = sum(t.amount for t in txns if t.kind in ("loan", "payout"))
        row = m.to_dict()
        row.update({
            "total_contributed": round(contributed, 2),
            "total_taken_out":   round(taken_out, 2),
            "balance":           round(contributed - taken_out, 2),
        })
        out.append(row)
    return out


