def savings_group_ledger(group_id):
    current_user = _get_current_user()
    if not current_user:
        return jsonify({"ok": False, "error": "Login required."}), 401
    group = _savings_group_or_404(group_id, current_user["id"])
    if not group:
        return jsonify({"ok": False, "error": "Group not found."}), 404
    limit = int(request.args.get("limit", 100))
    txns = (
        SavingsTransaction.query.filter_by(group_id=group_id)
        .order_by(SavingsTransaction.created_at.desc())
        .limit(min(limit, 500)).all()
    )
    members_by_id = {m.id: m.name for m in SavingsGroupMember.query.filter_by(group_id=group_id).all()}
    ledger = []
    for t in txns:
        row = t.to_dict()
        row["member_name"] = members_by_id.get(t.member_id, "Unknown")
        ledger.append(row)
    return jsonify({"ok": True, "ledger": ledger}), 200


