def _at_send_sms_simple(to_number: str, message: str) -> bool:
    """Minimal helper (used by the SMS chat fallback and tax-deadline
    reminders) around the same Africa's Talking client the /api/sms/at/send
    route already uses, without duplicating its full BYOK-override logic."""
    try:
        if not (AT_AVAILABLE and at_sms):
            return False
        s = sanitize_phone(to_number)
        if not s:
            return False
        at_sms.send(message[:459], [s])
        return True
    except Exception as e:
        logging.error(f"[AT SMS SIMPLE ERROR] {e}")
        return False


@app.route("/api/sms/at/incoming", methods=["POST"])
@csrf.exempt
def at_incoming_sms():
    """Receive incoming SMS from Africa's Talking. STAGE 55: this is the
    offline/low-data mode — customers without smartphones or affordable
    data can chat with Connect It purely over SMS. The inbound text is
    routed through the normal AI pipeline and the reply is sent back as
    an SMS (kept short, since a single SMS segment is ~160 chars)."""
    data     = request.form.to_dict()
    from_num = data.get("from", "")
    text     = (data.get("text", "") or "").strip()
    logging.info(f"[AT INCOMING SMS] From: {from_num} | Text: {text}")
    if text and from_num:
        try:
            sms_prompt = (
                "You are Connect It, replying over SMS to a user with no "
                "internet access. Keep the reply under 300 characters, "
                "plain text, no markdown, no emojis.\n\nUser: " + text
            )
            reply, _ = generate_ai_reply(sms_prompt, [])
            _at_send_sms_simple(from_num, (reply or "Sorry, I couldn't process that. Please try again.")[:300])
        except Exception as e:
            logging.error(f"[SMS CHAT FALLBACK ERROR] {e}")
    return connectit_json_response({"received": True})


# ===========================================================
# VIRTUAL NUMBERS — search, purchase, list, release
# Lets a business user provision a dedicated phone number for their
# customer-facing SMS/voice. Uses the caller's own BYOK Twilio account
# if they have one configured (get_twilio_client_for_user), otherwise
# the platform's shared Twilio account (billed to the platform).
#
# NOTE: Twilio does not sell local Zimbabwe (+263) numbers for lease —
# only "international" numbers (US/UK/etc.) can be provisioned via API
# for use from Zimbabwe. The search endpoint defaults to US/UK/CA/ZA
# because those are reliably in stock; other countries can be passed
# in but may return empty results depending on Twilio's inventory.
# ===========================================================

@app.route("/api/virtual-numbers/search", methods=["GET"])
def virtual_numbers_search():
    """Search Twilio's inventory of numbers available to purchase.
    Query params: country (ISO-2, default 'US'), area_code (optional,
    US/CA only), sms (bool, default true), voice (bool, default true)."""
    current_user = _get_current_user()
    current_uid  = current_user.get("id") if current_user else None
    if not current_uid:
        return connectit_json_response({"error": "Login required"}, 401)

    active_client, _, _ = get_twilio_client_for_user(current_uid)
    if not active_client:
        return connectit_json_response({"error": "Twilio not configured"}, 503)

    country   = (request.args.get("country") or "US").upper()
    area_code = request.args.get("area_code")
    want_sms  = request.args.get("sms", "true").lower() != "false"
    want_voice = request.args.get("voice", "true").lower() != "false"

    try:
        search_kwargs = {"sms_enabled": want_sms, "voice_enabled": want_voice, "limit": 10}
        if area_code and country in ("US", "CA"):
            search_kwargs["area_code"] = area_code
        numbers = active_client.available_phone_numbers(country).local.list(**search_kwargs)
        results = [{
            "phone_number":  n.phone_number,
            "friendly_name": n.friendly_name,
            "locality":      getattr(n, "locality", None),
            "region":        getattr(n, "region", None),
            "capabilities":  {k: v for k, v in (n.capabilities or {}).items()},
        } for n in numbers]
        return connectit_json_response({"country": country, "results": results})
    except Exception as e:
        logging.error(f"[VNUM SEARCH ERROR] {e}")
        return connectit_json_response({"error": str(e)}, 500)


@app.route("/api/virtual-numbers/purchase", methods=["POST"])
@csrf.exempt
def virtual_numbers_purchase():
    """Buy a specific number found via search and assign it to the
    current user. Sets the SMS/voice webhook to point back at this app
    so incoming messages route into that user's inbox."""
    current_user = _get_current_user()
    current_uid  = current_user.get("id") if current_user else None
    if not current_uid:
        return connectit_json_response({"error": "Login required"}, 401)

    active_client, _, _ = get_twilio_client_for_user(current_uid)
    if not active_client:
        return connectit_json_response({"error": "Twilio not configured"}, 503)

    data         = request.get_json(force=True) or {}
    phone_number = data.get("phone_number", "").strip()
    friendly     = data.get("friendly_name", "").strip() or None
    if not phone_number:
        return connectit_json_response({"error": "phone_number required"}, 400)

    try:
        base_url    = request.url_root.rstrip("/")
        sms_url     = f"{base_url}/api/virtual-numbers/incoming/sms"
        voice_url   = f"{base_url}/api/virtual-numbers/incoming/voice"

        purchased = active_client.incoming_phone_numbers.create(
            phone_number=phone_number,
            friendly_name=friendly or phone_number,
            sms_url=sms_url,
            voice_url=voice_url,
        )

        vnum = VirtualNumber(
            user_id=current_uid,
            phone_number=purchased.phone_number,
            twilio_sid=purchased.sid,
            friendly_name=friendly,
            country_code=(data.get("country") or "US").upper(),
            capabilities="sms,voice",
            provider="twilio",
            status="active",
        )
        db.session.add(vnum)
        db.session.commit()

        logging.info(f"[VNUM PURCHASE] user={current_uid} number={purchased.phone_number}")
        return connectit_json_response({"purchased": True, "number": vnum.to_dict()})
    except Exception as e:
        logging.error(f"[VNUM PURCHASE ERROR] user={current_uid}: {e}")
        return connectit_json_response({"error": str(e)}, 500)


