@app.route("/api/virtual-numbers/<int:vnum_id>/release", methods=["POST"])
@csrf.exempt
def virtual_numbers_release(vnum_id):
    """Release (cancel) a number so it stops being billed."""
    current_user = _get_current_user()
    current_uid  = current_user.get("id") if current_user else None
    if not current_uid:
        return connectit_json_response({"error": "Login required"}, 401)

    vnum = VirtualNumber.query.filter_by(id=vnum_id, user_id=current_uid).first()
    if not vnum:
        return connectit_json_response({"error": "Number not found"}, 404)

    active_client, _, _ = get_twilio_client_for_user(current_uid)
    try:
        if active_client:
            try:
                active_client.incoming_phone_numbers(vnum.twilio_sid).delete()
            except Exception as e:
                logging.warning(f"[VNUM RELEASE] Twilio delete failed (continuing): {e}")
        vnum.status = "released"
        vnum.released_at = datetime.utcnow()
        db.session.commit()
        return connectit_json_response({"released": True})
    except Exception as e:
        logging.error(f"[VNUM RELEASE ERROR] {e}")
        return connectit_json_response({"error": str(e)}, 500)


@app.route("/api/virtual-numbers/incoming/sms", methods=["POST"])
@csrf.exempt
def virtual_numbers_incoming_sms():
    """Twilio webhook for a virtual number's incoming SMS. Matches the
    'To' number back to the owning business user and drops the message
    into their memory/CRM inbox (UserMemory, content_type='sms_inbox')."""
    to_num   = request.form.get("To", "")
    from_num = request.form.get("From", "")
    body     = request.form.get("Body", "")

    vnum = VirtualNumber.query.filter_by(phone_number=to_num, status="active").first()
    if vnum:
        try:
            entry = UserMemory(
                user_id=vnum.user_id,
                role="user",
                content_type="sms_inbox",
                content=body,
                extra_json=json.dumps({"from": from_num, "to": to_num}),
            )
            db.session.add(entry)
            db.session.commit()
            logging.info(f"[VNUM SMS IN] user={vnum.user_id} from={from_num} to={to_num}")
        except Exception as e:
            logging.error(f"[VNUM SMS ROUTE ERROR] {e}")
    else:
        logging.warning(f"[VNUM SMS IN] No owner found for number {to_num}")

    resp = MessagingResponse()
    return str(resp), 200, {"Content-Type": "text/xml"}


@app.route("/api/virtual-numbers/incoming/voice", methods=["POST"])
@csrf.exempt
def virtual_numbers_incoming_voice():
    """STAGE 151: AI Phone Agent entry point. Twilio webhook for a
    virtual number's incoming call — greets with the business's own
    name (from PublicBookingPage if configured), then offers a real
    3-option menu: business info, book an appointment, or leave a
    message. Every call gets logged with an AI summary so the owner
    can catch up even if they never pick up."""
    from twilio.twiml.voice_response import VoiceResponse, Gather
    to_num   = request.form.get("To", "")
    from_num = request.form.get("From", "")
    call_sid = request.form.get("CallSid", "")
    vnum = VirtualNumber.query.filter_by(phone_number=to_num, status="active").first()
    resp = VoiceResponse()

    if not vnum:
        resp.say("Thank you for calling. Please leave a message after the tone.")
        resp.record(max_length=60)
        return Response(str(resp), mimetype="text/xml")

    setting = PhoneAgentSetting.query.filter_by(owner_user_id=vnum.user_id).first()
    if setting and not setting.enabled:
        resp.say("Thank you for calling. Please leave a message after the tone.")
        resp.record(max_length=60, action="/api/ivr/agent/message-record?vnum_id=" + str(vnum.id))
        return Response(str(resp), mimetype="text/xml")

    page = PublicBookingPage.query.filter_by(owner_user_id=vnum.user_id).first()
    biz_name = (page.business_name if page else None) or (vnum.friendly_name or "this business")
    greeting = (setting.greeting_text if setting and setting.greeting_text else None) or \
        ("Thank you for calling " + biz_name + ".")

    booking_on = bool(page and (not setting or setting.booking_enabled))
    gather = Gather(num_digits=1, action="/api/ivr/agent/menu?vnum_id=" + str(vnum.id), method="POST", timeout=8)
    menu_text = greeting + " Press 1 for business hours."
    if booking_on:
        menu_text += " Press 2 to book an appointment."
    menu_text += " Press 3 to leave a message. Press 0 to repeat this menu."
    gather.say(menu_text)
    resp.append(gather)
    resp.redirect("/api/virtual-numbers/incoming/voice")
    logging.info(f"[PHONE AGENT] incoming call user={vnum.user_id} from={from_num} sid={call_sid}")
    return Response(str(resp), mimetype="text/xml")


@app.route("/api/ivr/agent/menu", methods=["POST"])
@csrf.exempt
def ivr_agent_menu():
    from twilio.twiml.voice_response import VoiceResponse
    vnum_id = request.args.get("vnum_id", type=int)
    digit   = request.values.get("Digits", "")
    resp = VoiceResponse()
    vnum = VirtualNumber.query.get(vnum_id) if vnum_id else None
    if not vnum:
        resp.say("Sorry, something went wrong. Goodbye.")
        resp.hangup()
        return Response(str(resp), mimetype="text/xml")

    page = PublicBookingPage.query.filter_by(owner_user_id=vnum.user_id).first()
    if digit == "1":
        hours_text = "Please check our booking page for exact hours, or leave a message and we will call you back."
        if page and page.hours():
            days = {"0": "Monday", "1": "Tuesday", "2": "Wednesday", "3": "Thursday", "4": "Friday", "5": "Saturday", "6": "Sunday"}
            parts = [days[k] + " " + v for k, v in page.hours().items() if v]
            if parts:
                hours_text = "Our hours are: " + "; ".join(parts) + "."
        resp.say(hours_text)
        resp.redirect("/api/virtual-numbers/incoming/voice")
    elif digit == "2" and page:
        resp.say("Please say your name, the service you'd like, and your preferred day and time after the beep. "
                  "Then stay on the line.")
        resp.record(max_length=30, action="/api/ivr/agent/booking-record?vnum_id=" + str(vnum.id), play_beep=True)
    elif digit == "3":
        resp.say("Please leave your message after the beep, then stay on the line.")
        resp.record(max_length=60, action="/api/ivr/agent/message-record?vnum_id=" + str(vnum.id), play_beep=True)
    else:
        resp.redirect("/api/virtual-numbers/incoming/voice")
    return Response(str(resp), mimetype="text/xml")


def _phone_agent_notify(owner_user_id, from_num, summary, intent):
    """Best-effort SMS notification to the business owner after a call,
    plus a durable log entry either way."""
    setting = PhoneAgentSetting.query.filter_by(owner_user_id=owner_user_id).first()
    notify_number = setting.notify_number if setting else None
    if notify_number:
        try:
            client, _, from_number = get_twilio_client_for_user(owner_user_id)
            if client and from_number:
                client.messages.create(
                    to=notify_number, from_=from_number,
                    body=f"[Smile Again Phone Agent] {intent.upper()} call from {from_num}: {summary}"[:1500],
                )
        except Exception as e:
            logging.error(f"[PHONE AGENT NOTIFY] {e}")


@app.route("/api/ivr/agent/booking-record", methods=["POST"])
@csrf.exempt
def ivr_agent_booking_record():
    """Parses the caller's spoken booking request with AI, matches it
    to a real service on the business's Public Booking Page, and books
    the next available slot in that window — a genuine appointment,
    not just a note for someone to call back."""
    from twilio.twiml.voice_response import VoiceResponse
    vnum_id = request.args.get("vnum_id", type=int)
    from_num = request.values.get("From", "")
    transcript = request.values.get("TranscriptionText", "")
    resp = VoiceResponse()
    vnum = VirtualNumber.query.get(vnum_id) if vnum_id else None
    page = PublicBookingPage.query.filter_by(owner_user_id=vnum.user_id).first() if vnum else None

    if not vnum or not page or not transcript:
        resp.say("Sorry, I couldn't catch that booking request. Please try calling again, or leave a message.")
        resp.hangup()
        if vnum:
            db.session.add(PhoneAgentCallLog(owner_user_id=vnum.user_id, caller_number=from_num,
                                              intent="booking", transcript=transcript,
                                              summary="Booking request could not be understood."))
            db.session.commit()
        return Response(str(resp), mimetype="text/xml")

    services = PublicBookingService.query.filter_by(page_id=page.id, active=True).all()
    service_names = ", ".join(s.name for s in services) or "a general appointment"
    prompt = (
        f"A caller left this spoken voicemail requesting an appointment: \"{transcript}\". "
        f"Available services: {service_names}. Today's date is {datetime.utcnow().date().isoformat()}. "
        f"Reply with ONLY a raw JSON object (no markdown) shaped exactly like: "
        f'{{"customer_name": "name or \\"Caller\\" if unclear", "matched_service": "closest matching service name or empty string", '
        f'"preferred_date": "YYYY-MM-DD best guess, use tomorrow if unclear", "preferred_time": "HH:MM 24-hour best guess, use 09:00 if unclear"}}'
    )
    raw, _ = generate_ai_reply(prompt, [])
    try:
        text = re.sub(r"^```(?:json)?\s*", "", (raw or "").strip())
        text = re.sub(r"\s*```$", "", text)
        parsed = json.loads(text)
    except Exception:
        parsed = {}

    matched = next((s for s in services if s.name.lower() == str(parsed.get("matched_service", "")).lower()), None) \
        or (services[0] if services else None)
    duration = matched.duration_minutes if matched else page.slot_minutes
    try:
        start_dt = datetime.strptime(
            str(parsed.get("preferred_date", "")) + " " + str(parsed.get("preferred_time", "")), "%Y-%m-%d %H:%M")
    except Exception:
        start_dt = datetime.utcnow() + timedelta(days=1)
    end_dt = start_dt + timedelta(minutes=duration)
    customer_name = str(parsed.get("customer_name") or "Phone caller")[:200]

    appt = PublicBookingAppointment(
        page_id=page.id, service_id=matched.id if matched else None,
        customer_name=customer_name, customer_phone=from_num,
        start_time=start_dt, end_time=end_dt, status="confirmed",
        notes="Booked via AI Phone Agent from spoken request: " + transcript[:300],
    )
    db.session.add(appt)
    db.session.flush()
    summary = f"Booked {customer_name} for {(matched.name if matched else 'an appointment')} on {start_dt.strftime('%a %d %b, %H:%M')}."
    db.session.add(PhoneAgentCallLog(owner_user_id=vnum.user_id, caller_number=from_num, intent="booking",
                                      transcript=transcript, summary=summary, booked_appointment_id=appt.id))
    db.session.commit()
    _phone_agent_notify(vnum.user_id, from_num, summary, "booking")

    resp.say(f"You're booked for {start_dt.strftime('%A at %I:%M %p')}. "
             "We'll also try to send you a text confirmation. Goodbye.")
    resp.hangup()
    return Response(str(resp), mimetype="text/xml")


@app.route("/api/ivr/agent/message-record", methods=["POST"])
@csrf.exempt
def ivr_agent_message_record():
    """Records a general message, transcribes + summarises it with AI,
    and logs it so the owner sees a one-line summary instead of having
    to listen to every voicemail."""
    from twilio.twiml.voice_response import VoiceResponse
    vnum_id = request.args.get("vnum_id", type=int)
    from_num = request.values.get("From", "")
    transcript = request.values.get("TranscriptionText", "")
    resp = VoiceResponse()
    vnum = VirtualNumber.query.get(vnum_id) if vnum_id else None

    summary = "No message left."
    if transcript:
        try:
            summary, _ = generate_ai_reply(
                "Summarise this voicemail transcript in one short sentence for a busy business owner: " + transcript, [])
        except Exception:
            summary = transcript[:200]
    if vnum:
        db.session.add(PhoneAgentCallLog(owner_user_id=vnum.user_id, caller_number=from_num, intent="message",
                                          transcript=transcript, summary=(summary or "")[:1000]))
        db.session.commit()
        _phone_agent_notify(vnum.user_id, from_num, summary or "New voicemail.", "message")

    resp.say("Thank you, your message has been recorded. Goodbye.")
    resp.hangup()
    return Response(str(resp), mimetype="text/xml")


