@app.route("/api/iot-devices/register", methods=["POST"])
@csrf.exempt
def iot_device_register():
    current_user = _get_current_user()
    current_uid  = current_user.get("id") if current_user else None
    if not current_uid:
        return connectit_json_response({"error": "Login required"}, 401)

    data = request.get_json(force=True) or {}
    name = (data.get("device_name") or "").strip()
    if not name:
        return connectit_json_response({"error": "device_name required"}, 400)

    device = IotDevice(
        user_id=current_uid,
        device_name=name,
        device_type=data.get("device_type", "").strip() or None,
        sim_iccid=data.get("sim_iccid", "").strip() or None,
        report_token=secrets.token_hex(20),
        status="unregistered",
    )
    db.session.add(device)
    db.session.commit()
    return connectit_json_response({"registered": True, "device": device.to_dict(include_token=True)})


