@app.route("/api/sms/twilio/whatsapp", methods=["POST"])
@csrf.exempt
def twilio_send_whatsapp():
    """Send WhatsApp message via Twilio — uses the caller's own Twilio /
    WhatsApp Business account if they have one configured, otherwise the
    platform's shared account."""
    current_user = _get_current_user()
