def build_email_html(body, subject, from_name="Connect It"):
    """Wrap plain text / HTML body in a branded email template."""
    if "<" in body and ">" in body:
        content = body
    else:
        content = "<br/>".join(body.split("\n"))
    return f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8"/>
<meta name="viewport" content="width=device-width,initial-scale=1"/>
<title>{subject}</title>
</head>
<body style="margin:0;padding:0;background:#f1f5f9;font-family:Poppins,Arial,sans-serif;">
<table width="100%" cellpadding="0" cellspacing="0"
  style="background:#f1f5f9;padding:30px 0;">
  <tr><td align="center">
    <table width="600" cellpadding="0" cellspacing="0"
      style="background:white;border-radius:16px;overflow:hidden;
      max-width:600px;box-shadow:0 4px 24px rgba(0,0,0,0.08);">
      <tr>
        <td style="background:linear-gradient(90deg,#1e3a8a,#2563eb);
          padding:24px 32px;text-align:center;">
          <div style="font-size:2.5rem;"></div>
          <div style="font-family:'Georgia',serif;font-size:1.6rem;
            color:#f97316;font-weight:700;margin-top:4px;">Connect It</div>
          <div style="color:rgba(255,255,255,0.7);font-size:0.82rem;
            margin-top:2px;">Hope · Inspiration · Real AI Power</div>
        </td>
      </tr>
      <tr>
        <td style="padding:32px;color:#1e293b;font-size:15px;line-height:1.8;">
          {content}
        </td>
      </tr>
      <tr>
        <td style="background:#1e293b;padding:20px 32px;text-align:center;">
          <div style="color:rgba(255,255,255,0.5);font-size:0.75rem;line-height:1.7;">
            Built with  by the Nzombe Family in Zimbabwe<br/>
            <a href="mailto:{CONNECTIT_EMAIL}"
              style="color:#f97316;text-decoration:none;">{CONNECTIT_EMAIL}</a>
            &nbsp;·&nbsp;
            <a href="https://wa.me/263710482155"
              style="color:#25d366;text-decoration:none;">WhatsApp</a>
            <br/>
            <a href="#" style="color:rgba(255,255,255,0.3);font-size:0.7rem;">Unsubscribe</a>
          </div>
        </td>
      </tr>
    </table>
  </td></tr>
</table>
</body>
</html>"""


@app.route("/api/email/sendgrid/send", methods=["POST"])
@csrf.exempt
def sendgrid_send_email():
    """Send a single email via SendGrid."""
    if not SENDGRID_AVAILABLE:
        return connectit_json_response(
            {"error": "SendGrid not installed. pip install sendgrid"}, 503)
    user = _get_current_user()
    if not user:
        return connectit_json_response({"error": "Login required."}, 401)
    try:
        data       = request.get_json(force=True) or {}
        api_key    = get_effective_credential(user["id"], "sendgrid", "apiKey", SENDGRID_API_KEY)
        from_email = get_effective_credential(user["id"], "sendgrid", "fromEmail", CONNECTIT_EMAIL)
        from_name  = get_effective_credential(user["id"], "sendgrid", "fromName", "Connect It")
        to_email   = sanitize_email(data.get("to_email", ""))
        subject    = data.get("subject",    "Message from Connect It")
        html_body  = data.get("html_body",  "")
        text_body  = data.get("text_body",  "")

        if not api_key:
            return connectit_json_response({"error": "Connect SendGrid in Integrations first."}, 400)
        if not to_email:
            return connectit_json_response({"error": "Valid recipient email required"}, 400)
        if not html_body and not text_body:
            return connectit_json_response({"error": "Email body required"}, 400)

        final_html = build_email_html(html_body or text_body, subject, from_name)
        message    = Mail(
            from_email=(from_email, from_name),
            to_emails=to_email,
            subject=subject,
            html_content=final_html
        )
        if text_body:
            message.plain_text_content = text_body

        sg_client = SendGridAPIClient(api_key)
        response  = sg_client.send(message)
        logging.info(f"[SENDGRID] Email sent to {to_email} | Status: {response.status_code}")
        return connectit_json_response({
            "sent":        True,
            "status_code": response.status_code,
            "to":          to_email
        })
    except Exception as e:
        logging.error(f"[SENDGRID SINGLE ERROR] {e}")
        return connectit_json_response({"error": str(e)}, 500)


@app.route("/api/email/sendgrid/campaign", methods=["POST"])
@csrf.exempt
def sendgrid_send_campaign():
    """Send a campaign email to multiple subscribers via SendGrid."""
    if not SENDGRID_AVAILABLE:
        return connectit_json_response({"error": "SendGrid not installed"}, 503)
    user = _get_current_user()
    if not user:
        return connectit_json_response({"error": "Login required."}, 401)
    try:
        data        = request.get_json(force=True) or {}
        api_key     = get_effective_credential(user["id"], "sendgrid", "apiKey", SENDGRID_API_KEY)
        from_email  = get_effective_credential(user["id"], "sendgrid", "fromEmail", CONNECTIT_EMAIL)
        from_name   = get_effective_credential(user["id"], "sendgrid", "fromName", "Connect It")
        subject     = data.get("subject",    "Message from Connect It")
        html_body   = data.get("html_body",  "")
        subscribers = data.get("subscribers", [])

        if not api_key:
            return connectit_json_response({"error": "Connect SendGrid in Integrations first."}, 400)
        if not subscribers:
            return connectit_json_response({"error": "No subscribers provided"}, 400)
        if not html_body:
            return connectit_json_response({"error": "Email body required"}, 400)

        valid_subs = []
        for sub in subscribers:
            email = sanitize_email(sub.get("email", ""))
            if email:
                valid_subs.append({
                    "email": email,
                    "name":  sub.get("name", email.split("@")[0])
                })
        if not valid_subs:
            return connectit_json_response({"error": "No valid subscriber emails"}, 400)

        final_html   = build_email_html(html_body, subject, from_name)
        sg_client    = SendGridAPIClient(api_key)
        sent_count   = 0
        failed_count = 0
        batch_size   = 50

        for i in range(0, len(valid_subs), batch_size):
            batch   = valid_subs[i:i + batch_size]
            to_list = [sub["email"] for sub in batch]
            try:
                message  = Mail(
                    from_email=(from_email, from_name),
                    to_emails=to_list,
                    subject=subject,
                    html_content=final_html
                )
                response = sg_client.send(message)
                if response.status_code in (200, 202):
                    sent_count += len(batch)
                else:
                    failed_count += len(batch)
                time.sleep(0.2)
            except Exception as batch_err:
                failed_count += len(batch)
                logging.error(f"[SENDGRID BATCH ERROR] {batch_err}")

        return connectit_json_response({
            "sent":   sent_count,
            "failed": failed_count,
            "total":  len(valid_subs)
        })
    except Exception as e:
        logging.error(f"[SENDGRID CAMPAIGN ERROR] {e}")
        return connectit_json_response({"error": str(e)}, 500)


@app.route("/api/email/sendgrid/webhook", methods=["POST"])
@csrf.exempt
def sendgrid_webhook():
    """Handle SendGrid event webhooks."""
    events = request.get_json(force=True) or []
    for event in events:
        ev_type = event.get("event", "")
        email   = event.get("email", "")
        if ev_type == "open":
            logging.info(f"[SENDGRID OPEN] {email}")
        elif ev_type == "click":
            logging.info(f"[SENDGRID CLICK] {email} | URL: {event.get('url')}")
        elif ev_type in ("bounce", "blocked", "unsubscribe"):
            logging.warning(f"[SENDGRID {ev_type.upper()}] {email}")
    return connectit_json_response({"received": True})


