def get_gspread_client(api_key_json=None):
    """Get an authenticated gspread client."""
    if not GSPREAD_AVAILABLE:
        return None
    creds_json = api_key_json or GOOGLE_SHEETS_CREDS
    if not creds_json:
        return None
    try:
        creds_dict = (json.loads(creds_json)
                      if isinstance(creds_json, str) else creds_json)
        scopes = [
            "https://spreadsheets.google.com/feeds",
            "https://www.googleapis.com/auth/drive"
        ]
        creds  = Credentials.from_service_account_info(creds_dict, scopes=scopes)
        return gspread.authorize(creds)
    except Exception as e:
        logging.error(f"[GSPREAD AUTH ERROR] {e}")
        return None


def prepare_sheet_data(table_key, raw_data):
    """Convert raw JSON data to rows suitable for Google Sheets."""
    if not raw_data:
        return [], []

    headers_map = {
        "budget": ["ID", "Description", "Amount", "Type", "Category", "Date", "Timestamp"],
        "todos":  ["ID", "Task", "Priority", "Done", "Created", "Completed"],
        "crm":    ["ID", "Name", "Contact", "Stage", "Value", "Notes", "Created"],
        "habits": ["ID", "Name", "Streak", "Best Streak", "Last Done", "Created"],
        "gallery":["ID", "Author", "Message", "Date", "User ID"]
    }
    field_map = {
        "budget": lambda r: [
            r.get("id",""), r.get("desc",""), r.get("amount",0),
            r.get("type",""), r.get("cat",""), r.get("date",""), r.get("timestamp","")],
        "todos": lambda r: [
            r.get("id",""), r.get("text",""), r.get("priority","normal"),
            "Yes" if r.get("done") else "No", r.get("created",""), r.get("completed","")],
        "crm": lambda r: [
            r.get("id",""), r.get("name",""), r.get("contact",""), r.get("stage",""),
            r.get("value",0), r.get("notes",""), r.get("created","")],
        "habits": lambda r: [
            r.get("id",""), r.get("name",""), r.get("streak",0), r.get("best",0),
            r.get("lastDone",""), r.get("created","")],
        "gallery": lambda r: [
            r.get("id",""), r.get("author",""), r.get("message","")[:200],
            str(r.get("ts","")), r.get("userId","")]
    }
    headers = headers_map.get(table_key, list(raw_data[0].keys()) if raw_data else [])
    fn      = field_map.get(table_key)
    rows    = []
    for r in raw_data:
        if fn:
            rows.append(fn(r))
        else:
            rows.append([str(v) for v in r.values()])
    return headers, rows


@app.route("/api/integrations/sheets/sync", methods=["POST"])
@csrf.exempt
def sheets_sync():
    """Sync data from Connect It to Google Sheets."""
    user = _get_current_user()
    if not user:
        return connectit_json_response({"error": "Login required."}, 401)
    try:
        data           = request.get_json(force=True) or {}
        spreadsheet_id = data.get("spreadsheet_id", "")
        api_key_json   = get_effective_credential(user["id"], "google_sheets", "service_account_json", None)
        sheet_name     = data.get("sheet_name", "Data")
        table_key      = data.get("table_key", "custom")
        raw_data       = data.get("data", [])

        if not spreadsheet_id:
            return connectit_json_response({"error": "Spreadsheet ID required"}, 400)
        if not raw_data:
            return connectit_json_response({
                "synced": True, "rows": 0, "message": "No data to sync"})

        client = get_gspread_client(api_key_json)
        if not client:
            return connectit_json_response({
                "error": "Google Sheets isn't connected yet. Add your service-account "
                         "JSON in Integrations, or download CSV instead.",
                "csv_fallback": True,
                "data":         raw_data
            }, 503)

        try:
            spreadsheet = client.open_by_key(spreadsheet_id)
        except gspread.SpreadsheetNotFound:
            return connectit_json_response(
                {"error": "Spreadsheet not found. Check the ID and sharing permissions."}, 404)

        try:
            worksheet = spreadsheet.worksheet(sheet_name)
        except gspread.WorksheetNotFound:
            worksheet = spreadsheet.add_worksheet(
                title=sheet_name, rows="1000", cols="26")

        headers, rows = prepare_sheet_data(table_key, raw_data)
        sync_time = datetime.utcnow().strftime("%Y-%m-%d %H:%M UTC")
        all_rows  = (
            [[f"Connect It — {sheet_name} — Synced: {sync_time}"]] +
            [[""] * max(len(headers), 1)] +
            [headers] +
            rows
        )
        worksheet.clear()
        worksheet.update("A1", all_rows, value_input_option="USER_ENTERED")

        try:
            worksheet.format("A3:Z3", {
                "textFormat":      {"bold": True},
                "backgroundColor": {"red": 0.12, "green": 0.23, "blue": 0.54}
            })
        except Exception:
            pass

        logging.info(f"[SHEETS SYNC] {table_key} → {sheet_name} | {len(rows)} rows")
        return connectit_json_response({
            "synced":    True,
            "rows":      len(rows),
            "sheet":     sheet_name,
            "columns":   len(headers),
            "synced_at": sync_time
        })
    except Exception as e:
        logging.error(f"[SHEETS SYNC ERROR] {e}")
        return connectit_json_response({"error": str(e)}, 500)


@app.route("/api/integrations/sheets/export-csv", methods=["POST"])
@csrf.exempt
def sheets_export_csv():
    """Export data as CSV when Sheets is not configured."""
    data      = request.get_json(force=True) or {}
    table_key = data.get("table_key", "data")
    raw_data  = data.get("data", [])
    if not raw_data:
        return connectit_json_response({"error": "No data"}, 400)
    headers, rows = prepare_sheet_data(table_key, raw_data)
    import csv, io as _io
    output = _io.StringIO()
    writer = csv.writer(output)
    if headers:
        writer.writerow(headers)
    writer.writerows(rows)
    csv_content = output.getvalue()
    filename    = f"connectit_{table_key}_{datetime.utcnow().strftime('%Y%m%d')}.csv"
    return Response(
        csv_content,
        mimetype="text/csv",
        headers={"Content-Disposition": f"attachment; filename={filename}"}
    )


# ════════════════════════════════════════════════════════════
# GOOGLE CALENDAR OAUTH & CLOUD STORAGE ROUTES
# ════════════════════════════════════════════════════════════

# --- Calendar: OAuth helpers ---

def _save_google_token(user_id, token_json):
    expires_in = token_json.get("expires_in", 3600)
    expires_at = datetime.utcnow() + timedelta(seconds=int(expires_in) - 60)
    row = GoogleOAuthToken.query.filter_by(user_id=user_id).first()
    if not row:
        row = GoogleOAuthToken(user_id=user_id)
        db.session.add(row)
    row.access_token = token_json["access_token"]
    if token_json.get("refresh_token"):
        row.refresh_token = token_json["refresh_token"]
    row.expires_at = expires_at
    row.scope = token_json.get("scope", "")
    db.session.commit()
    return row


def get_valid_google_token(user_id, required_scope: str | None = None):
    """Return a valid access token for this user, refreshing if expired.
    None if not connected, or if connected but missing `required_scope`
    (e.g. a user who only ever granted Calendar access shouldn't get a
    token handed to Gmail code paths)."""
    row = GoogleOAuthToken.query.filter_by(user_id=user_id).first()
    if not row:
        return None
    if required_scope and required_scope not in (row.scope or ""):
        return None
    if row.expires_at > datetime.utcnow():
        return row.access_token
    if not row.refresh_token:
        return None
    try:
        resp = requests.post("https://oauth2.googleapis.com/token", data={
            "client_id":     CLIENT_ID,
            "client_secret": CLIENT_SECRET,
            "refresh_token": row.refresh_token,
            "grant_type":    "refresh_token",
        }, timeout=10)
        if resp.status_code != 200:
            logging.error(f"[GOOGLE TOKEN REFRESH ERROR] {resp.text}")
            return None
        _save_google_token(user_id, resp.json())
        return resp.json()["access_token"]
    except Exception as e:
        logging.error(f"[GOOGLE TOKEN REFRESH EXCEPTION] {e}")
        return None


def get_valid_calendar_token(user_id):
    """Back-compat alias — existing Calendar code calls this name."""
    return get_valid_google_token(user_id, required_scope="calendar")


def _google_oauth_scope_for_service(service: str) -> str:
    """'calendar' (default) keeps the original Calendar-only scope so
    existing connections don't change; 'gmail' requests Calendar+Gmail
    together so one consent screen covers both. 'forms' only requests the
    Forms-specific scopes — it doesn't need Calendar/Gmail bundled in
    because google_auth_url now passes include_granted_scopes=true, so
    Google itself merges in whatever this user already granted before
    (rather than us having to re-request everything every time, which
    would otherwise silently downgrade an existing Gmail/Calendar grant
    when GoogleOAuthToken's single scope column gets overwritten)."""
    if service == "gmail":
        return f"{GOOGLE_CALENDAR_SCOPES} {GOOGLE_GMAIL_SCOPES}"
    if service == "forms":
        return GOOGLE_FORMS_SCOPES
    if service == "drive_appdata":
        return GOOGLE_DRIVE_APPDATA_SCOPES
    if service == "business_profile":
        return " ".join(_BUSINESS_PROFILE_SCOPES)
    return GOOGLE_CALENDAR_SCOPES


@app.route("/api/google/auth-url", methods=["GET"])
@csrf.exempt
def google_auth_url():
    """Builds the real Google consent screen URL for Calendar (and,
    optionally, Gmail) access."""
    if not CLIENT_ID or not GOOGLE_OAUTH_REDIRECT_URI:
        return connectit_json_response({
            "url": "about:blank",
            "message": "Set CLIENT_ID and GOOGLE_OAUTH_REDIRECT_URI to enable Calendar."
        })
    user_id = request.args.get("user_id", "")
    service = request.args.get("service", "calendar")
    params = {
        "client_id":     CLIENT_ID,
        "redirect_uri":  GOOGLE_OAUTH_REDIRECT_URI,
        "response_type": "code",
        "scope":         _google_oauth_scope_for_service(service),
        "access_type":   "offline",
        "prompt":        "consent",
        "include_granted_scopes": "true",
        "state":         f"{user_id}:{service}",
    }
    url = "https://accounts.google.com/o/oauth2/v2/auth?" + "&".join(
        f"{k}={requests.utils.quote(str(v))}" for k, v in params.items()
    )
    return connectit_json_response({"url": url})


@app.route("/api/google/oauth/callback", methods=["GET"])
def google_oauth_callback():
    code       = request.args.get("code", "")
    state      = request.args.get("state", "")
    error      = request.args.get("error", "")
    user_id, _, service = state.partition(":")
    service    = service or "calendar"

    if error or not code or not user_id:
        return "<html><body style='font-family:sans-serif;padding:40px;text-align:center;'>" \
               "<h2>Google connection cancelled or failed.</h2>" \
               "<script>setTimeout(function(){window.close();},2000);</script></body></html>", 200

    try:
        resp = requests.post("https://oauth2.googleapis.com/token", data={
            "client_id":     CLIENT_ID,
            "client_secret": CLIENT_SECRET,
            "code":          code,
            "grant_type":    "authorization_code",
            "redirect_uri":  GOOGLE_OAUTH_REDIRECT_URI,
        }, timeout=10)
        if resp.status_code != 200:
            logging.error(f"[GOOGLE OAUTH TOKEN EXCHANGE ERROR] {resp.text}")
            raise Exception("Token exchange failed")

        _save_google_token(int(user_id), resp.json())

        label = ("Gmail" if service == "gmail" else
                  "Google Forms" if service == "forms" else
                  "Google Drive Backup" if service == "drive_appdata" else
                  "Google Business Profile" if service == "business_profile" else
                  "Google Calendar")
        return f"""
        <html><body style='font-family:sans-serif;padding:40px;text-align:center;background:#f0fdf4;'>
        <h2 style='color:#16a34a;'> {label} Connected!</h2>
        <p>You can close this window.</p>
        <script>setTimeout(function(){{window.close();}},2000);</script>
        </body></html>
        """, 200
    except Exception as e:
        logging.error(f"[GOOGLE OAUTH CALLBACK ERROR] {e}")
        return "<html><body style='font-family:sans-serif;padding:40px;text-align:center;'>" \
               "<h2>Something went wrong connecting your Google account.</h2>" \
               "<script>setTimeout(function(){window.close();},2500);</script></body></html>", 200


# --- STAGE 516: BYOS — Drive appDataFolder helpers -------------------
# appDataFolder is a real Drive special folder that's hidden from the
# user's normal "My Drive" view and only readable/writable by the app
# that created a file in it — so this can't collide with or expose
# anything else in the user's Drive. Everything this app ever writes
# here is opaque ciphertext produced client-side; the server only ever
# ferries bytes, it never has the key to read them.

def _drive_appdata_find(user_id, filename):
    token = get_valid_google_token(user_id, required_scope="drive.appdata")
    if not token:
        return None, "Not connected to Google Drive."
    try:
        resp = requests.get(
            "https://www.googleapis.com/drive/v3/files",
            params={"spaces": "appDataFolder", "q": f"name='{filename}'", "fields": "files(id)"},
            headers={"Authorization": f"Bearer {token}"}, timeout=15
        )
        if resp.status_code != 200:
            return None, f"Drive error: {resp.text[:300]}"
        files = resp.json().get("files", [])
        return (files[0]["id"] if files else None), None
    except Exception as e:
        return None, str(e)


def _drive_appdata_upsert(user_id, filename, raw_bytes):
    token = get_valid_google_token(user_id, required_scope="drive.appdata")
    if not token:
        return False, "Not connected to Google Drive."
    file_id, err = _drive_appdata_find(user_id, filename)
    if err:
        return False, err
    headers = {"Authorization": f"Bearer {token}"}
    try:
        if file_id:
            resp = requests.patch(
                f"https://www.googleapis.com/upload/drive/v3/files/{file_id}?uploadType=media",
                headers={**headers, "Content-Type": "application/octet-stream"},
                data=raw_bytes, timeout=30
            )
        else:
            boundary = "connectitbyosboundary"
            metadata = json.dumps({"name": filename, "parents": ["appDataFolder"]})
            body = (
                f"--{boundary}\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n{metadata}\r\n"
                f"--{boundary}\r\nContent-Type: application/octet-stream\r\n\r\n"
            ).encode("utf-8") + raw_bytes + f"\r\n--{boundary}--".encode("utf-8")
            resp = requests.post(
                "https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart",
                headers={**headers, "Content-Type": f"multipart/related; boundary={boundary}"},
                data=body, timeout=30
            )
        if resp.status_code not in (200, 201):
            return False, f"Drive error: {resp.text[:300]}"
        return True, resp.json()
    except Exception as e:
        return False, str(e)


def _drive_appdata_download(user_id, filename):
    token = get_valid_google_token(user_id, required_scope="drive.appdata")
    if not token:
        return False, "Not connected to Google Drive."
    file_id, err = _drive_appdata_find(user_id, filename)
    if err:
        return False, err
    if not file_id:
        return False, "No backup found yet."
    try:
        resp = requests.get(
            f"https://www.googleapis.com/drive/v3/files/{file_id}",
            params={"alt": "media"},
            headers={"Authorization": f"Bearer {token}"}, timeout=30
        )
        if resp.status_code != 200:
            return False, f"Drive error: {resp.text[:300]}"
        return True, resp.content
    except Exception as e:
        return False, str(e)


# ════════════════════════════════════════════════════════════
# STAGE 30: MICROSOFT GRAPH — OAuth, Outlook Mail, Outlook
# Calendar, Excel, OneDrive, Teams meetings.
# One consent screen/token (MicrosoftOAuthToken) powers all five,
# mirroring the Google OAuth pattern immediately above.
# ════════════════════════════════════════════════════════════

_MS_AUTH_BASE  = f"https://login.microsoftonline.com/{MS_TENANT_ID}/oauth2/v2.0"
_MS_GRAPH_BASE = "https://graph.microsoft.com/v1.0"


def _save_microsoft_token(user_id, token_json):
    expires_in = token_json.get("expires_in", 3600)
    expires_at = datetime.utcnow() + timedelta(seconds=int(expires_in) - 60)
    row = MicrosoftOAuthToken.query.filter_by(user_id=user_id).first()
    if not row:
        row = MicrosoftOAuthToken(user_id=user_id)
        db.session.add(row)
    row.access_token = token_json["access_token"]
    if token_json.get("refresh_token"):
        row.refresh_token = token_json["refresh_token"]
    row.expires_at = expires_at
    row.scope = token_json.get("scope", "")
    db.session.commit()
    return row


def get_valid_microsoft_token(user_id):
    """Return a valid Microsoft Graph access token for this user,
    refreshing it via the stored refresh_token if it has expired.
    Returns None if the user has never connected Microsoft 365."""
    row = MicrosoftOAuthToken.query.filter_by(user_id=user_id).first()
    if not row:
        return None
    if row.expires_at > datetime.utcnow():
        return row.access_token
    if not row.refresh_token:
        return None
    try:
        resp = requests.post(f"{_MS_AUTH_BASE}/token", data={
            "client_id":     MS_CLIENT_ID,
            "client_secret": MS_CLIENT_SECRET,
            "refresh_token": row.refresh_token,
            "grant_type":    "refresh_token",
            "scope":         MS_GRAPH_SCOPES,
        }, timeout=10)
        if resp.status_code != 200:
            logging.error(f"[MICROSOFT TOKEN REFRESH ERROR] {resp.text}")
            return None
        _save_microsoft_token(user_id, resp.json())
        return resp.json()["access_token"]
    except Exception as e:
        logging.error(f"[MICROSOFT TOKEN REFRESH EXCEPTION] {e}")
        return None


def _microsoft_headers(user_id, json_body=True):
    """Returns Graph auth headers for this user, or None if not connected."""
    token = get_valid_microsoft_token(user_id)
    if not token:
        return None
    headers = {"Authorization": f"Bearer {token}"}
    if json_body:
        headers["Content-Type"] = "application/json"
    return headers


@app.route("/api/microsoft/auth-url", methods=["GET"])
@csrf.exempt
def microsoft_auth_url():
    """Builds the real Microsoft consent screen URL covering Outlook Mail,
    Outlook Calendar, OneDrive/Excel and Teams meetings in one grant."""
    if not MS_CLIENT_ID or not MS_OAUTH_REDIRECT_URI:
        return connectit_json_response({
            "url": "about:blank",
            "message": "Set MS_CLIENT_ID, MS_CLIENT_SECRET and MS_OAUTH_REDIRECT_URI to enable Microsoft 365."
        })
    user_id = request.args.get("user_id", "")
    params = {
        "client_id":     MS_CLIENT_ID,
        "redirect_uri":  MS_OAUTH_REDIRECT_URI,
        "response_type": "code",
        "response_mode": "query",
        "scope":         MS_GRAPH_SCOPES,
        "state":         f"{user_id}:microsoft",
    }
    url = f"{_MS_AUTH_BASE}/authorize?" + "&".join(
        f"{k}={requests.utils.quote(str(v))}" for k, v in params.items()
    )
    return connectit_json_response({"url": url})


@app.route("/api/microsoft/oauth/callback", methods=["GET"])
def microsoft_oauth_callback():
    code  = request.args.get("code", "")
    state = request.args.get("state", "")
    error = request.args.get("error", "")
    user_id, _, _service = state.partition(":")

    if error or not code or not user_id:
        return "<html><body style='font-family:sans-serif;padding:40px;text-align:center;'>" \
               "<h2>Microsoft connection cancelled or failed.</h2>" \
               "<script>setTimeout(function(){window.close();},2000);</script></body></html>", 200

    try:
        resp = requests.post(f"{_MS_AUTH_BASE}/token", data={
            "client_id":     MS_CLIENT_ID,
            "client_secret": MS_CLIENT_SECRET,
            "code":          code,
            "grant_type":    "authorization_code",
            "redirect_uri":  MS_OAUTH_REDIRECT_URI,
            "scope":         MS_GRAPH_SCOPES,
        }, timeout=10)
        if resp.status_code != 200:
            logging.error(f"[MICROSOFT OAUTH TOKEN EXCHANGE ERROR] {resp.text}")
            raise Exception("Token exchange failed")

        _save_microsoft_token(int(user_id), resp.json())

        return """
        <html><body style='font-family:sans-serif;padding:40px;text-align:center;background:#f0fdf4;'>
        <h2 style='color:#16a34a;'> Microsoft 365 Connected!</h2>
        <p>You can close this window.</p>
        <script>setTimeout(function(){window.close();},2000);</script>
        </body></html>
        """, 200
    except Exception as e:
        logging.error(f"[MICROSOFT OAUTH CALLBACK ERROR] {e}")
        return "<html><body style='font-family:sans-serif;padding:40px;text-align:center;'>" \
               "<h2>Something went wrong connecting your Microsoft account.</h2>" \
               "<script>setTimeout(function(){window.close();},2500);</script></body></html>", 200


