# --- Outlook Mail ---

@app.route("/api/outlook/inbox", methods=["GET"])
@csrf.exempt
def outlook_inbox():
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Not signed in."}), 401
    headers = _microsoft_headers(user["id"], json_body=False)
    if not headers:
        return jsonify({"error": "Not connected to Microsoft 365."}), 400
    try:
        resp = requests.get(
            f"{_MS_GRAPH_BASE}/me/mailFolders/inbox/messages"
            "?$top=15&$select=id,subject,from,bodyPreview,receivedDateTime,isRead",
            headers=headers, timeout=15
        )
        if resp.status_code != 200:
            return jsonify({"error": f"Graph error: {resp.text}"}), 502
        items = resp.json().get("value", [])
        messages = [{
            "id":       m.get("id"),
            "subject":  m.get("subject", "(no subject)"),
            "from":     ((m.get("from") or {}).get("emailAddress") or {}).get("address", ""),
            "preview":  m.get("bodyPreview", ""),
            "received": m.get("receivedDateTime"),
            "is_read":  m.get("isRead", False),
        } for m in items]
        return jsonify({"ok": True, "messages": messages})
    except Exception as e:
        logging.error(f"[OUTLOOK INBOX ERROR] {e}")
        return jsonify({"error": str(e)}), 500


@app.route("/api/outlook/send", methods=["POST"])
@csrf.exempt
def outlook_send():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Not signed in."}), 401
    data = request.get_json(force=True) or {}
    to_email = data.get("to", "").strip()
    subject  = data.get("subject", "").strip()
    body     = data.get("body", "").strip()
    if not to_email or not body:
        return jsonify({"error": "'to' and 'body' are required."}), 400
    headers = _microsoft_headers(user["id"])
    if not headers:
        return jsonify({"error": "Not connected to Microsoft 365."}), 400
    try:
        payload = {
            "message": {
                "subject": subject or "(no subject)",
                "body": {"contentType": "Text", "content": body},
                "toRecipients": [{"emailAddress": {"address": to_email}}],
            },
            "saveToSentItems": "true",
        }
        resp = requests.post(f"{_MS_GRAPH_BASE}/me/sendMail", headers=headers,
                              json=payload, timeout=15)
        if resp.status_code not in (200, 202):
            return jsonify({"error": f"Graph error: {resp.text}"}), 502
        return jsonify({"ok": True})
    except Exception as e:
        logging.error(f"[OUTLOOK SEND ERROR] {e}")
        return jsonify({"error": str(e)}), 500


# --- Outlook Calendar ---

@app.route("/api/outlook/calendar/book", methods=["POST"])
@csrf.exempt
def outlook_calendar_book():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Not signed in."}), 401
    data           = request.get_json(force=True) or {}
    title          = data.get("title", "Meeting")
    start_time     = data.get("start_time")
    end_time       = data.get("end_time")
    attendee_email = data.get("attendee_email", "")
    if not start_time or not end_time:
        return jsonify({"error": "start_time and end_time are required."}), 400
    headers = _microsoft_headers(user["id"])
    if not headers:
        return jsonify({"error": "Not connected to Microsoft 365."}), 400
    event_body = {
        "subject": title,
        "start": {"dateTime": start_time, "timeZone": "UTC"},
        "end":   {"dateTime": end_time,   "timeZone": "UTC"},
        "isOnlineMeeting": True,
        "onlineMeetingProvider": "teamsForBusiness",
    }
    if attendee_email:
        event_body["attendees"] = [{
            "emailAddress": {"address": attendee_email},
            "type": "required",
        }]
    try:
        resp = requests.post(f"{_MS_GRAPH_BASE}/me/events", headers=headers,
                              json=event_body, timeout=15)
        if resp.status_code not in (200, 201):
            return jsonify({"error": f"Graph error: {resp.text}"}), 502
        event = resp.json()
        return jsonify({
            "ok": True,
            "event_id": event.get("id"),
            "join_url": ((event.get("onlineMeeting") or {}).get("joinUrl")),
        })
    except Exception as e:
        logging.error(f"[OUTLOOK CALENDAR BOOK ERROR] {e}")
        return jsonify({"error": str(e)}), 500


