# ════════════════════════════════════════════════════════════
# STAGE 34: WORD ONLINE + POWERPOINT ONLINE — "generate then push".
# Connect It already generates .docx (python-docx) and can now also
# generate .pptx (python-pptx) locally from AI-written content. This
# stage closes the gap the user asked about: instead of stopping at a
# local download, the generated file is pushed straight into the
# user's own OneDrive via the SAME Microsoft Graph OAuth connection
# already used for Outlook/Excel/Teams above (no new BYOK provider —
# it reuses "microsoft_graph"), and Graph's webUrl for a .docx/.pptx
# stored in OneDrive opens directly in Word Online / PowerPoint Online
# in the browser, so the user can keep co-editing there.
# ════════════════════════════════════════════════════════════

def _build_docx_bytes(title: str, sections: list) -> bytes:
    """Builds a real .docx in memory from a title + a list of sections,
    where each section is {"heading": str, "body": str}. Mirrors the
    style already used by Connect It's other python-docx output."""
    doc = Document()
    if title:
        h = doc.add_heading(title, level=0)
    for sec in (sections or []):
        heading = (sec.get("heading") or "").strip()
        body    = (sec.get("body") or "").strip()
        if heading:
            doc.add_heading(heading, level=1)
        if body:
            for para in body.split("\n"):
                doc.add_paragraph(para)
    buf = io.BytesIO()
    doc.save(buf)
    return buf.getvalue()


def _build_pptx_bytes(title: str, slides: list) -> bytes:
    """Builds a real .pptx in memory from a title + a list of slides,
    where each slide is {"title": str, "bullets": [str, ...]}."""
    prs = Presentation()
    title_layout   = prs.slide_layouts[0]
    content_layout = prs.slide_layouts[1]

    first = prs.slides.add_slide(title_layout)
    first.shapes.title.text = title or "Connect It Presentation"
    if slides and slides[0].get("subtitle"):
        try:
            first.placeholders[1].text = slides[0]["subtitle"]
        except Exception:
            pass

    for sl in (slides or []):
        slide = prs.slides.add_slide(content_layout)
        slide.shapes.title.text = (sl.get("title") or "").strip() or "Slide"
        body = slide.placeholders[1].text_frame
        bullets = sl.get("bullets") or []
        if bullets:
            body.text = str(bullets[0])
            for b in bullets[1:]:
                p = body.add_paragraph()
                p.text = str(b)
        buf_check = None  # no-op, keeps structure explicit
    buf = io.BytesIO()
    prs.save(buf)
    return buf.getvalue()


def _onedrive_put_bytes(user_id, filename: str, file_bytes: bytes):
    """Shared helper: PUTs raw bytes to the user's OneDrive root via
    Graph and returns (ok, webUrl_or_error). Used by both the Word and
    PowerPoint push endpoints below, and mirrors /api/onedrive/upload."""
    headers = _microsoft_headers(user_id, json_body=False)
    if not headers:
        return False, "Not connected to Microsoft 365. Connect it under Integrations first."
    try:
        upload_headers = dict(headers)
        upload_headers["Content-Type"] = "application/octet-stream"
        resp = requests.put(
            f"{_MS_GRAPH_BASE}/me/drive/root:/{requests.utils.quote(filename)}:/content",
            headers=upload_headers, data=file_bytes, timeout=30
        )
        if resp.status_code not in (200, 201):
            return False, f"Graph error: {resp.text[:300]}"
        item = resp.json()
        return True, {"file_id": item.get("id"), "web_url": item.get("webUrl")}
    except Exception as e:
        logging.error(f"[ONEDRIVE PUT ERROR] user={user_id}: {e}")
        return False, str(e)


# --- STAGE 516: BYOS — OneDrive "approot" helpers ---------------------
# special/approot is OneDrive's real equivalent of Drive's appDataFolder:
# a per-app hidden folder, not the user's visible OneDrive root that
# /api/onedrive/upload above writes to. Reuses the same MicrosoftOAuthToken
# grant already covering Outlook/Excel/OneDrive/Teams — no separate
# consent needed for anyone already connected.

def _onedrive_approot_put_bytes(user_id, filename: str, raw_bytes: bytes):
    headers = _microsoft_headers(user_id, json_body=False)
    if not headers:
        return False, "Not connected to Microsoft 365."
    try:
        upload_headers = dict(headers)
        upload_headers["Content-Type"] = "application/octet-stream"
        resp = requests.put(
            f"{_MS_GRAPH_BASE}/me/drive/special/approot:/{requests.utils.quote(filename)}:/content",
            headers=upload_headers, data=raw_bytes, timeout=30
        )
        if resp.status_code not in (200, 201):
            return False, f"Graph error: {resp.text[:300]}"
        return True, resp.json()
    except Exception as e:
        logging.error(f"[ONEDRIVE APPROOT PUT ERROR] user={user_id}: {e}")
        return False, str(e)


def _onedrive_approot_get_bytes(user_id, filename: str):
    headers = _microsoft_headers(user_id, json_body=False)
    if not headers:
        return False, "Not connected to Microsoft 365."
    try:
        resp = requests.get(
            f"{_MS_GRAPH_BASE}/me/drive/special/approot:/{requests.utils.quote(filename)}:/content",
            headers=headers, timeout=30
        )
        if resp.status_code == 404:
            return False, "No backup found yet."
        if resp.status_code != 200:
            return False, f"Graph error: {resp.text[:300]}"
        return True, resp.content
    except Exception as e:
        logging.error(f"[ONEDRIVE APPROOT GET ERROR] user={user_id}: {e}")
        return False, str(e)


