@app.route("/api/google/disconnect", methods=["DELETE"])
@csrf.exempt
def google_disconnect():
    """Removes this user's Google OAuth grant entirely. One consent
    screen/token row (GoogleOAuthToken) backs Drive backup, Calendar,
    and Gmail alike, so disconnecting here disconnects all three —
    the frontend warns the user about that before calling this."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    row = GoogleOAuthToken.query.filter_by(user_id=user["id"]).first()
    if not row:
        return jsonify({"error": "Google was not connected."}), 404
    db.session.delete(row)
    db.session.commit()
    logging.info(f"[GOOGLE OAUTH DISCONNECT] user={user['id']}")
    return jsonify({"ok": True}), 200


