@app.route("/api/byos/push", methods=["POST"])
@csrf.exempt
def byos_push():
    """Stores an opaque ciphertext blob in the user's own Google Drive
    appDataFolder, OneDrive approot, AWS S3, or Azure Blob Storage. The
    blob is produced entirely client-side (AES-GCM, key derived from a
    passphrase that never leaves the browser) — this endpoint never
    sees plaintext and has no way to decrypt what it stores."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Not signed in."}), 401
    data = request.get_json(force=True) or {}
    provider = data.get("provider", "")
    blob_b64 = data.get("blob", "")
    if provider not in ("google_drive", "onedrive", "aws_s3", "azure_blob", "ipfs") or not blob_b64:
        return jsonify({"error": "provider and blob are required."}), 400
    try:
        raw = base64.b64decode(blob_b64)
    except Exception:
        return jsonify({"error": "Invalid blob encoding."}), 400
    # No size cap here by design — this goes straight into the user's
    # own cloud storage, not a shared table, so an arbitrary app-level
    # ceiling doesn't protect anything that isn't already the user's
    # own account/quota to manage.
    if provider == "google_drive":
        ok, result = _drive_appdata_upsert(user["id"], "connectit_byos_backup.enc", raw)
    elif provider == "onedrive":
        ok, result = _onedrive_approot_put_bytes(user["id"], "connectit_byos_backup.enc", raw)
    elif provider == "aws_s3":
        res = _byos_upload_s3(user["id"], "connectit_byos_backup.enc", raw, "application/octet-stream")
        ok, result = res.get("ok", False), res.get("error")
    elif provider == "azure_blob":
        res = _byos_upload_azure(user["id"], "connectit_byos_backup.enc", raw, "application/octet-stream")
        ok, result = res.get("ok", False), res.get("error")
    else:
        res = _byos_upload_ipfs(user["id"], "connectit_byos_backup.enc", raw, "application/octet-stream")
        ok, result = res.get("ok", False), res.get("error")
    if not ok:
        return jsonify({"error": result}), 502
    return jsonify({"ok": True, "synced_at": datetime.utcnow().isoformat()})


@app.route("/api/byos/pull", methods=["GET"])
@csrf.exempt
def byos_pull():
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Not signed in."}), 401
    provider = request.args.get("provider", "")
    if provider not in ("google_drive", "onedrive", "aws_s3", "azure_blob", "ipfs"):
        return jsonify({"error": "Unknown provider."}), 400
    if provider == "google_drive":
        ok, result = _drive_appdata_download(user["id"], "connectit_byos_backup.enc")
    elif provider == "onedrive":
        ok, result = _onedrive_approot_get_bytes(user["id"], "connectit_byos_backup.enc")
    elif provider == "aws_s3":
        ok, result = _byos_download_s3(user["id"], "connectit_byos_backup.enc")
    elif provider == "azure_blob":
        ok, result = _byos_download_azure(user["id"], "connectit_byos_backup.enc")
    else:
        ok, result = _byos_download_ipfs(user["id"], "connectit_byos_backup.enc")
    if not ok:
        return jsonify({"error": result}), 404
    return jsonify({"ok": True, "blob": base64.b64encode(result).decode("ascii")})


@app.route("/api/word/push", methods=["POST"])
@csrf.exempt
def word_push_online():
    """Generates a real .docx from AI-written content and pushes it into
    the user's OneDrive, returning a link that opens directly in Word
    Online. Body: {"title": str, "sections": [{"heading","body"}, ...],
    "filename": optional str}."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    if not DOCX_AVAILABLE:
        return jsonify({"error": "python-docx not installed on the server. Run: pip install python-docx"}), 500
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Not signed in."}), 401
    data     = request.get_json(force=True, silent=True) or {}
    title    = (data.get("title") or "Untitled Document").strip()
    sections = data.get("sections") or []
    filename = (data.get("filename") or "").strip() or f"{title[:60] or 'document'}.docx"
    if not filename.lower().endswith(".docx"):
        filename += ".docx"
    try:
        file_bytes = _build_docx_bytes(title, sections)
    except Exception as e:
        logging.error(f"[WORD PUSH BUILD ERROR] user={user['id']}: {e}")
        return jsonify({"error": f"Could not build the document: {e}"}), 500
    ok, result = _onedrive_put_bytes(user["id"], filename, file_bytes)
    if not ok:
        return jsonify({"error": result}), 400
    return jsonify({
        "ok": True,
        "file_id": result["file_id"],
        "word_online_url": result["web_url"],
    })


@app.route("/api/powerpoint/push", methods=["POST"])
@csrf.exempt
def powerpoint_push_online():
    """Generates a real .pptx from AI-written content and pushes it into
    the user's OneDrive, returning a link that opens directly in
    PowerPoint Online. Body: {"title": str, "slides": [{"title",
    "bullets": [str,...]}, ...], "filename": optional str}."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    if not PPTX_AVAILABLE:
        return jsonify({"error": "python-pptx not installed on the server. Run: pip install python-pptx"}), 500
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Not signed in."}), 401
    data     = request.get_json(force=True, silent=True) or {}
    title    = (data.get("title") or "Untitled Presentation").strip()
    slides   = data.get("slides") or []
    filename = (data.get("filename") or "").strip() or f"{title[:60] or 'presentation'}.pptx"
    if not filename.lower().endswith(".pptx"):
        filename += ".pptx"
    try:
        file_bytes = _build_pptx_bytes(title, slides)
    except Exception as e:
        logging.error(f"[PPTX PUSH BUILD ERROR] user={user['id']}: {e}")
        return jsonify({"error": f"Could not build the presentation: {e}"}), 500
    ok, result = _onedrive_put_bytes(user["id"], filename, file_bytes)
    if not ok:
        return jsonify({"error": result}), 400
    return jsonify({
        "ok": True,
        "file_id": result["file_id"],
        "powerpoint_online_url": result["web_url"],
    })


