@app.route("/api/google-play/verify-purchase", methods=["POST"])
@csrf.exempt
def google_play_verify_purchase():
    """Verify a one-time product purchase or a subscription receipt handed
    up by the Android app after a Play Billing checkout, so server-side
    entitlement (Pro unlock, credits, etc.) is never trusted client-side."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    svc = _play_service(user["id"])
    package_name = _play_package(user["id"])
    if not svc or not package_name:
        return jsonify({"error": "Google Play is not configured."}), 503

    data = request.get_json(force=True) or {}
    product_id = (data.get("product_id") or "").strip()
    purchase_token = (data.get("purchase_token") or "").strip()
    kind = (data.get("kind") or "product").strip()  # "product" or "subscription"
    if not product_id or not purchase_token:
        return jsonify({"error": "product_id and purchase_token are required."}), 400

    try:
        if kind == "subscription":
            result = svc.purchases().subscriptions().get(
                packageName=package_name, subscriptionId=product_id, token=purchase_token
            ).execute()
            valid = int(result.get("expiryTimeMillis", 0)) > int(time.time() * 1000)
        else:
            result = svc.purchases().products().get(
                packageName=package_name, productId=product_id, token=purchase_token
            ).execute()
            valid = result.get("purchaseState") == 0  # 0 = purchased
        return jsonify({"valid": valid, "details": result}), 200
    except Exception as e:
        logging.error(f"[GOOGLE PLAY PURCHASE VERIFY ERROR] {e}")
        return jsonify({"valid": False, "error": str(e)}), 200


# ════════════════════════════════════════════════════════════
# STAGE 519: GOOGLE CLOUD CONSOLE VISIBILITY (Service Usage API)
# Admin-only. Shows which Google APIs are enabled on the configured
# project and lets an admin enable/disable one without opening
# console.cloud.google.com.
# ════════════════════════════════════════════════════════════

def _cloud_console_service():
    if not GCALENDAR_AVAILABLE or not GOOGLE_CLOUD_CONSOLE_CREDS_JSON or not GOOGLE_CLOUD_PROJECT_ID:
        return None
    try:
        creds_dict = json.loads(GOOGLE_CLOUD_CONSOLE_CREDS_JSON) if isinstance(GOOGLE_CLOUD_CONSOLE_CREDS_JSON, str) else GOOGLE_CLOUD_CONSOLE_CREDS_JSON
        creds = Credentials.from_service_account_info(
            creds_dict, scopes=["https://www.googleapis.com/auth/cloud-platform.read-only"])
        return google_api_build("serviceusage", "v1", credentials=creds, cache_discovery=False)
    except Exception as e:
        logging.error(f"[CLOUD CONSOLE AUTH ERROR] {e}")
        return None


@app.route("/api/google-cloud/services", methods=["GET"])
def google_cloud_list_services():
    """Admin-only: list every Google API enabled/disabled on the project,
    the closest read-only equivalent to the Cloud Console 'APIs & Services'
    dashboard."""
    user = _get_current_user()
    if not user or not _sdk_is_admin(user["id"]):
        return jsonify({"error": "Admin access required."}), 403
    svc = _cloud_console_service()
    if not svc:
        return jsonify({"error": "Set GOOGLE_CLOUD_PROJECT_ID (and optionally GOOGLE_CLOUD_CONSOLE_CREDS_JSON) to enable this."}), 503
    state_filter = request.args.get("state", "ENABLED")  # ENABLED, DISABLED, or blank for all
    try:
        services = []
        req = svc.services().list(
            parent=f"projects/{GOOGLE_CLOUD_PROJECT_ID}",
            filter=f"state:{state_filter}" if state_filter else None,
            pageSize=200,
        )
        while req is not None:
            resp = req.execute()
            services.extend(resp.get("services", []))
            req = svc.services().list_next(req, resp)
        cleaned = [{
            "name": s.get("config", {}).get("name", s.get("name", "")),
            "title": s.get("config", {}).get("title", ""),
            "state": s.get("state", ""),
        } for s in services]
        return jsonify({"project": GOOGLE_CLOUD_PROJECT_ID, "services": cleaned}), 200
    except Exception as e:
        logging.error(f"[CLOUD CONSOLE SERVICES ERROR] {e}")
        return jsonify({"error": str(e)}), 500


@app.route("/api/google-cloud/services/toggle", methods=["POST"])
@csrf.exempt
def google_cloud_toggle_service():
    """Admin-only: enable or disable a specific Google API on the project."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user or not _sdk_is_admin(user["id"]):
        return jsonify({"error": "Admin access required."}), 403
    svc = _cloud_console_service()
    if not svc:
        return jsonify({"error": "Google Cloud Console visibility is not configured."}), 503
    data = request.get_json(force=True) or {}
    service_name = (data.get("service_name") or "").strip()  # e.g. "androidpublisher.googleapis.com"
    action = (data.get("action") or "").strip()  # "enable" or "disable"
    if not service_name or action not in ("enable", "disable"):
        return jsonify({"error": "service_name and action ('enable'/'disable') are required."}), 400
    try:
        full_name = f"projects/{GOOGLE_CLOUD_PROJECT_ID}/services/{service_name}"
        if action == "enable":
            svc.services().enable(name=full_name, body={}).execute()
        else:
            svc.services().disable(name=full_name, body={}).execute()
        return jsonify({"ok": True}), 200
    except Exception as e:
        logging.error(f"[CLOUD CONSOLE TOGGLE ERROR] {e}")
        return jsonify({"error": str(e)}), 500


# ════════════════════════════════════════════════════════════
# STAGE 519: PYTHONANYWHERE CONSOLES API (SSH-style admin access)
# PythonAnywhere does not expose a public raw-socket SSH endpoint, even on
# paid plans — the Consoles API (driving one of the account's real bash/
# Python web consoles over HTTPS) is the actual documented mechanism for
# remote command execution, so this wraps that: create a console, feed it
# input, and read back its output. Admin-only, since this can run anything
# the PythonAnywhere account can.
# ════════════════════════════════════════════════════════════

def _pa_headers():
    return {"Authorization": f"Token {PYTHONANYWHERE_API_TOKEN}"}


def _pa_base_url():
    return f"https://{PYTHONANYWHERE_API_HOST}/api/v0/user/{PYTHONANYWHERE_USERNAME}/consoles/"


@app.route("/api/pythonanywhere/consoles", methods=["GET"])
def pythonanywhere_list_consoles():
    user = _get_current_user()
    if not user or not _sdk_is_admin(user["id"]):
        return jsonify({"error": "Admin access required."}), 403
    if not PYTHONANYWHERE_API_TOKEN or not PYTHONANYWHERE_USERNAME:
        return jsonify({"error": "Set PYTHONANYWHERE_API_TOKEN and PYTHONANYWHERE_USERNAME to enable this."}), 503
    try:
        resp = requests.get(_pa_base_url(), headers=_pa_headers(), timeout=15)
        return jsonify({"consoles": resp.json()}), resp.status_code
    except Exception as e:
        logging.error(f"[PA CONSOLES LIST ERROR] {e}")
        return jsonify({"error": str(e)}), 500


@app.route("/api/pythonanywhere/consoles", methods=["POST"])
@csrf.exempt
def pythonanywhere_create_console():
    """Open a new bash console on the PythonAnywhere account."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user or not _sdk_is_admin(user["id"]):
        return jsonify({"error": "Admin access required."}), 403
    if not PYTHONANYWHERE_API_TOKEN or not PYTHONANYWHERE_USERNAME:
        return jsonify({"error": "PythonAnywhere console access is not configured."}), 503
    data = request.get_json(force=True) or {}
    executable = (data.get("executable") or "bash").strip()
    try:
        resp = requests.post(
            _pa_base_url(), headers=_pa_headers(),
            data={"executable": executable, "arguments": ""}, timeout=15,
        )
        return jsonify({"console": resp.json()}), resp.status_code
    except Exception as e:
        logging.error(f"[PA CONSOLE CREATE ERROR] {e}")
        return jsonify({"error": str(e)}), 500


@app.route("/api/pythonanywhere/consoles/<int:console_id>/input", methods=["POST"])
@csrf.exempt
def pythonanywhere_send_input(console_id):
    """Send a command line to an open console and return the output so far.
    Every command run here is written to the platform audit log."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user or not _sdk_is_admin(user["id"]):
        return jsonify({"error": "Admin access required."}), 403
    if not PYTHONANYWHERE_API_TOKEN or not PYTHONANYWHERE_USERNAME:
        return jsonify({"error": "PythonAnywhere console access is not configured."}), 503
    data = request.get_json(force=True) or {}
    command = data.get("input", "")
    if not command:
        return jsonify({"error": "input is required."}), 400
    try:
        requests.post(
            f"{_pa_base_url()}{console_id}/send_input/",
            headers=_pa_headers(), data={"input": command + "\n"}, timeout=15,
        )
        out = requests.get(
            f"{_pa_base_url()}{console_id}/get_latest_output/",
            headers=_pa_headers(), timeout=15,
        )
        logging.info(f"[PA CONSOLE COMMAND] admin_user={user['id']} console={console_id} cmd={command[:500]!r}")
        _log_terminal_command(user["id"], "pythonanywhere", console_id, command)
        return jsonify(out.json()), out.status_code
    except Exception as e:
        logging.error(f"[PA CONSOLE INPUT ERROR] {e}")
        return jsonify({"error": str(e)}), 500


@app.route("/api/pythonanywhere/consoles/<int:console_id>", methods=["DELETE"])
@csrf.exempt
def pythonanywhere_close_console(console_id):
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user or not _sdk_is_admin(user["id"]):
        return jsonify({"error": "Admin access required."}), 403
    try:
        resp = requests.delete(f"{_pa_base_url()}{console_id}/", headers=_pa_headers(), timeout=15)
        return jsonify({"ok": resp.status_code in (200, 204)}), resp.status_code
    except Exception as e:
        logging.error(f"[PA CONSOLE CLOSE ERROR] {e}")
        return jsonify({"error": str(e)}), 500


