# ══════════════════════════════════════════════════════════
# 1. WHISPER TRANSCRIPTION
#    Used by: Voice to WhatsApp, Meeting Companion
#    BYOK: a user's own OpenAI API key (if configured under Settings >
#    Integrations) is used for their transcriptions instead of the
#    platform's shared key — same "openai" provider already used for
#    chat, so no separate key to manage.
# ══════════════════════════════════════════════════════════
@app.route('/api/transcribe', methods=['POST'])
@csrf.exempt
def transcribe_audio():
    if 'audio' not in request.files:
        return jsonify({'error': 'No audio file provided', 'transcript': ''}), 400

    audio_file = request.files['audio']
    if not audio_file.filename:
        return jsonify({'error': 'Empty audio file', 'transcript': ''}), 400

    current_user = _get_current_user()
    current_uid  = current_user.get('id') if current_user else None
    byok_key = get_effective_credential(current_uid, 'openai', 'api_key', None)
    client = OpenAI(api_key=byok_key) if byok_key else openai_client
    language = (request.form.get('language') or 'en').strip() or 'en'

    suffix = '.webm'
    with tempfile.NamedTemporaryFile(delete=False, suffix=suffix) as tmp:
        audio_file.save(tmp.name)
        tmp_path = tmp.name

    try:
        if client:
            with open(tmp_path, 'rb') as f:
                result = client.audio.transcriptions.create(
                    model='whisper-1',
                    file=f,
                    language=language
                )
            transcript = result.text
            return jsonify({'transcript': transcript})
        else:
            return jsonify({
                'error': 'OpenAI client not initialised. Set OPENAI_API_KEY in .env, '
                         'or add your own OpenAI key under Settings > Integrations.',
                'transcript': ''
            }), 503
    except Exception as e:
        logging.error(f'Whisper transcription failed: {e}')
        return jsonify({'error': str(e), 'transcript': ''}), 500
    finally:
        try:
            os.unlink(tmp_path)
        except Exception:
            pass


