# 2. NEWS API PROXY
#    Used by: Competitor Monitor, News Briefing
# ══════════════════════════════════════════════════════════
@app.route('/api/news', methods=['GET'])
@csrf.exempt
def get_news():
    q      = request.args.get('q', 'Africa business')
    topics = request.args.getlist('topics') or [q]

    if not NEWS_API_KEY:
        return jsonify([]), 200

    try:
        query = ' OR '.join(f'"{t}"' for t in topics if t)

        resp = requests.get(
            'https://newsapi.org/v2/everything',
            params={
                'q':        query,
                'apiKey':   NEWS_API_KEY,
                'language': 'en',
                'sortBy':   'publishedAt',
                'pageSize': 10,
                'page':     1,
            },
            timeout=10
        )
        if not resp.ok:
            logging.warning(f'NewsAPI returned {resp.status_code}')
            return jsonify([]), 200

        articles = resp.json().get('articles', [])
        cleaned  = []
        for a in articles:
            cleaned.append({
                'title':       a.get('title',       ''),
                'description': a.get('description', ''),
                'url':         a.get('url',         ''),
                'source':      a.get('source', {}).get('name', 'News'),
                'publishedAt': a.get('publishedAt', '')[:10],
                'urlToImage':  a.get('urlToImage',  ''),
            })
        return jsonify(cleaned), 200

    except Exception as e:
        logging.error(f'NewsAPI proxy failed: {e}')
        return jsonify([]), 200


# ══════════════════════════════════════════════════════════
# 2b. DISCOVER FEED — REAL, LIVE EXTERNAL CONTENT
# Replaces the old frontend-only feed (a hardcoded array of stock
# Unsplash photo URLs and made-up headlines). Every item below comes
# from a real external service at request time. Nothing here is
# stored or faked — an empty category just means that provider isn't
# configured (or genuinely has no fresh results right now), not a
# placeholder pretending to be live.
# ══════════════════════════════════════════════════════════
_DISCOVER_TIMEOUT = 6

def _discover_fetch_news(topic, limit):
    """Real news headlines. Uses NewsAPI if a key is configured;
    otherwise falls back to Google News' public RSS feed, which needs
    no API key at all, so this category still works out of the box."""
    items = []
    try:
        if NEWS_API_KEY:
            r = requests.get(
                "https://newsapi.org/v2/everything",
                params={"q": topic, "apiKey": NEWS_API_KEY, "language": "en",
                        "sortBy": "publishedAt", "pageSize": limit},
                timeout=_DISCOVER_TIMEOUT,
            )
            if r.ok:
                for a in (r.json().get("articles") or [])[:limit]:
                    items.append({
                        "type": "news", "source": a.get("source", {}).get("name", "News"),
                        "title": a.get("title", ""), "desc": a.get("description") or "",
                        "thumb": a.get("urlToImage") or "",
                        "url": a.get("url", ""), "published": a.get("publishedAt", ""),
                    })
                return items
            logging.warning(f"NewsAPI returned {r.status_code}")
        # Keyless fallback — Google News RSS, real live headlines.
        rss_url = "https://news.google.com/rss/search"
        r = requests.get(rss_url, params={"q": topic, "hl": "en-US", "gl": "US", "ceid": "US:en"},
                          timeout=_DISCOVER_TIMEOUT)
        if r.ok:
            root = ET.fromstring(r.content)
            for entry in root.findall(".//item")[:limit]:
                title = (entry.findtext("title") or "").strip()
                link = (entry.findtext("link") or "").strip()
                pub = (entry.findtext("pubDate") or "").strip()
                source_el = entry.find("source")
                source_name = source_el.text if source_el is not None else "Google News"
                items.append({
                    "type": "news", "source": source_name, "title": title,
                    "desc": "", "thumb": "", "url": link, "published": pub,
                })
    except Exception as e:
        logging.error(f"Discover news fetch failed: {e}")
    return items


def _discover_fetch_videos(topic, limit):
    """Real YouTube search results. Uses the platform's own YouTube
    Data API key (no login required — this is a public feed), skipped
    entirely if that key isn't configured."""
    if not YOUTUBE_DATA_API_KEY:
        return []
    try:
        r = requests.get(
            "https://www.googleapis.com/youtube/v3/search",
            params={"part": "snippet", "q": topic, "type": "video",
                    "maxResults": limit, "order": "date", "key": YOUTUBE_DATA_API_KEY},
            timeout=_DISCOVER_TIMEOUT,
        )
        if not r.ok:
            logging.warning(f"YouTube discover fetch returned {r.status_code}")
            return []
        items = []
        for v in (r.json().get("items") or [])[:limit]:
            vid = (v.get("id") or {}).get("videoId")
            snip = v.get("snippet") or {}
            items.append({
                "type": "video", "source": snip.get("channelTitle", "YouTube"),
                "title": snip.get("title", ""), "desc": snip.get("description") or "",
                "thumb": ((snip.get("thumbnails") or {}).get("medium") or {}).get("url", ""),
                "url": f"https://youtube.com/watch?v={vid}" if vid else "",
                "published": snip.get("publishedAt", ""),
            })
        return items
    except Exception as e:
        logging.error(f"Discover video fetch failed: {e}")
        return []


def _discover_fetch_images(topic, limit):
    """Real photos. Uses Unsplash if a key is configured; otherwise
    falls back to Openverse (openverse.org), a free, keyless search
    over openly-licensed images, so this category also works with
    zero setup."""
    try:
        if UNSPLASH_ACCESS_KEY:
            r = requests.get(
                "https://api.unsplash.com/search/photos",
                params={"query": topic, "per_page": limit, "orientation": "landscape"},
                headers={"Authorization": f"Client-ID {UNSPLASH_ACCESS_KEY}"},
                timeout=_DISCOVER_TIMEOUT,
            )
            if r.ok:
                items = []
                for p in (r.json().get("results") or [])[:limit]:
                    items.append({
                        "type": "image", "source": (p.get("user") or {}).get("name", "Unsplash"),
                        "title": p.get("alt_description") or p.get("description") or "Photo",
                        "desc": "", "thumb": (p.get("urls") or {}).get("small", ""),
                        "url": (p.get("links") or {}).get("html", ""), "published": p.get("created_at", ""),
                    })
                return items
            logging.warning(f"Unsplash discover fetch returned {r.status_code}")
        # Keyless fallback — Openverse, openly-licensed real photos.
        r = requests.get(
            "https://api.openverse.org/v1/images/",
            params={"q": topic, "page_size": limit, "license_type": "commercial"},
            timeout=_DISCOVER_TIMEOUT,
        )
        items = []
        if r.ok:
            for p in (r.json().get("results") or [])[:limit]:
                items.append({
                    "type": "image", "source": p.get("source", "Openverse"),
                    "title": p.get("title") or "Photo", "desc": "",
                    "thumb": p.get("thumbnail") or p.get("url", ""),
                    "url": p.get("foreign_landing_url") or p.get("url", ""),
                    "published": "",
                })
        return items
    except Exception as e:
        logging.error(f"Discover image fetch failed: {e}")
        return []


@app.route("/api/discover-feed", methods=["GET"])
@csrf.exempt
def discover_feed():
    """Public — no login required, same as the old fake feed. Pulls
    real, live content from News, YouTube, and image providers in
    parallel and interleaves them so the feed doesn't read as three
    separate blocks."""
    topic = (request.args.get("topic") or "Africa business entrepreneurship").strip()
    try:
        limit = min(int(request.args.get("limit", 6)), 12)
    except ValueError:
        limit = 6

    fetchers = {
        "news":   lambda: _discover_fetch_news(topic, limit),
        "video":  lambda: _discover_fetch_videos(topic, limit),
        "image":  lambda: _discover_fetch_images(topic, limit),
    }
    results = {}
    with ThreadPoolExecutor(max_workers=len(fetchers)) as pool:
        future_map = {pool.submit(fn): key for key, fn in fetchers.items()}
        for future in as_completed(future_map, timeout=_DISCOVER_TIMEOUT + 2):
            key = future_map[future]
            try:
                results[key] = future.result() or []
            except Exception as e:
                logging.error(f"Discover feed provider '{key}' failed: {e}")
                results[key] = []

    # Interleave news/video/image round-robin so the grid mixes types
    # instead of showing all of one kind before the next.
    buckets = [results.get("news", []), results.get("video", []), results.get("image", [])]
    items = []
    i = 0
    while any(buckets):
        b = buckets[i % 3]
        if b:
            items.append(b.pop(0))
        i += 1
        if i > 500:
            break

    return jsonify({
        "items": items,
        "count": len(items),
        "sources": {
            "news":  True,  # always available (NewsAPI or keyless Google News RSS)
            "video": bool(YOUTUBE_DATA_API_KEY),
            "image": True,  # always available (Unsplash or keyless Openverse)
        },
    }), 200


