# 3. PROPOSAL PDF DOWNLOAD
#    Used by: AI Proposal Builder
# ══════════════════════════════════════════════════════════
@app.route('/api/proposal/pdf', methods=['POST'])
@csrf.exempt
def proposal_pdf():
    if not _csrf_ok():
        return jsonify({'error': 'CSRF check failed'}), 403

    data         = request.get_json() or {}
    html_content = data.get('html', '')
    proposal_data = data.get('data', {})

    client_name = proposal_data.get('Client Name', 'client').replace(' ', '_')
    filename    = f"proposal_{client_name}_{datetime.utcnow().strftime('%Y%m%d')}.pdf"

    # Clean HTML to plain text for PDF
    clean = re.sub(r'<br\s*/?>', '\n',   html_content, flags=re.IGNORECASE)
    clean = re.sub(r'</p>',      '\n\n', clean,         flags=re.IGNORECASE)
    clean = re.sub(r'</h[1-6]>', '\n\n', clean,         flags=re.IGNORECASE)
    clean = re.sub(r'<[^>]+>',   '',     clean)
    clean = clean.replace('&amp;','&').replace('&lt;','<').replace('&gt;','>').replace('&nbsp;',' ')
    clean = re.sub(r'\n{3,}', '\n\n', clean).strip()

    # Try WeasyPrint first (best quality)
    if WEASYPRINT_AVAILABLE:
        try:
            styled_html = f"""
            <!DOCTYPE html><html><head>
            <meta charset="UTF-8"/>
            <style>
              body{{font-family:Georgia,serif;max-width:800px;margin:40px auto;
                   color:#1e293b;line-height:1.8;font-size:14px;}}
              h1,h2,h3{{color:#1e3a8a;border-bottom:2px solid #e2e8f0;padding-bottom:6px;}}
              table{{width:100%;border-collapse:collapse;margin:16px 0;}}
              th{{background:#1e3a8a;color:white;padding:10px;text-align:left;}}
              td{{padding:8px 10px;border-bottom:1px solid #e2e8f0;}}
              .header{{background:linear-gradient(90deg,#1e3a8a,#2563eb);
                       color:white;padding:30px;text-align:center;border-radius:8px;
                       margin-bottom:30px;}}
            </style>
            </head><body>
            <div class="header">
              <h1 style="color:white;border:none;margin:0">Business Proposal</h1>
              <p style="margin:6px 0 0;opacity:0.8">Powered by Connect It</p>
            </div>
            {html_content}
            </body></html>"""
            pdf_bytes = WeasyHTML(string=styled_html).write_pdf()
            return Response(
                pdf_bytes,
                mimetype='application/pdf',
                headers={'Content-Disposition': f'attachment; filename="{filename}"'}
            )
        except Exception as e:
            logging.warning(f'WeasyPrint failed, falling back to ReportLab: {e}')

    # Fallback: ReportLab
    if REPORTLAB_AVAILABLE:
        try:
            buf    = io.BytesIO()
            styles = getSampleStyleSheet()
            doc    = SimpleDocTemplate(
                buf, pagesize=A4,
                rightMargin=50, leftMargin=50, topMargin=60, bottomMargin=50
            )
            story = []
            story.append(Paragraph('Business Proposal', styles['Title']))
            story.append(Spacer(1, 20))
            for para in clean.split('\n\n'):
                para = para.strip()
                if not para:
                    continue
                safe = para.replace('&','&amp;').replace('<','&lt;').replace('>','&gt;')
                story.append(Paragraph(safe, styles['Normal']))
                story.append(Spacer(1, 8))
            doc.build(story)
            buf.seek(0)
            return Response(
                buf,
                mimetype='application/pdf',
                headers={'Content-Disposition': f'attachment; filename="{filename}"'}
            )
        except Exception as e:
            logging.error(f'ReportLab PDF failed: {e}')

    # Last resort: plain text
    txt_buf = io.BytesIO(clean.encode('utf-8'))
    return Response(
        txt_buf,
        mimetype='text/plain',
        headers={'Content-Disposition': f'attachment; filename="{filename.replace(".pdf",".txt")}"'}
    )


