# 5. DIASPORA PROFILES
#    Used by: Diaspora Hub panel
# ══════════════════════════════════════════════════════════
@app.route('/api/diaspora/profiles', methods=['GET', 'POST'])
@csrf.exempt
def diaspora_profiles():
    if request.method == 'GET':
        rows = DiasporaProfile.query.order_by(DiasporaProfile.posted_at.desc()).all()
        return jsonify([r.to_dict() for r in rows]), 200

    data = request.get_json() or {}
    name = (data.get('name') or '').strip()
    if not name:
        return jsonify({'error': 'name is required'}), 400

    tags = data.get('tags', [])
    if not isinstance(tags, list):
        tags = []

    try:
        row = DiasporaProfile(
            public_id = str(uuid.uuid4())[:8],
            name      = name,
            location  = (data.get('location') or '').strip(),
            bio       = (data.get('bio') or '').strip(),
            email     = (data.get('email') or '').strip(),
            wa        = (data.get('wa') or '').strip(),
            tags_json = json.dumps(tags),
        )
        db.session.add(row)
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        logging.error(f'[DIASPORA SAVE ERROR] {e}')
        return jsonify({'error': 'Could not save profile'}), 500

    logging.info(f'[DIASPORA] New profile posted: {name}')
    return jsonify({'ok': True, 'profile': row.to_dict()}), 201


