# 6. LOAD SHEDDING SCHEDULE
#    Used by: Load Shedding Planner panel
# ══════════════════════════════════════════════════════════
@app.route('/api/loadshedding', methods=['GET'])
@csrf.exempt
@requires_feature_flag("loadshedding_tracker")
def loadshedding_schedule():
    """
    Attempt to fetch a real national utility/PowerAlert schedule.
    Falls back to returning empty so the frontend uses manual input.
    """
    suburb = request.args.get('suburb', '').strip()

    # Check cache first (15-minute cache per suburb)
    cache_key = suburb.lower() if suburb else '_default'
    cached    = ls_cache.get(cache_key)
    if cached and (time.time() - cached['ts']) < 900:
        return jsonify(cached['schedule']), 200

    schedule = []

    # Try to scrape PowerAlert Zimbabwe (best effort)
    try:
        resp = requests.get(
            'https://zetdc.co.zw/power-outages/',
            timeout=8,
            headers={'User-Agent': 'Mozilla/5.0 RejoyceAI/1.0'}
        )
        if resp.ok and suburb:
            text = resp.text.lower()
            if suburb.lower() in text:
                # Very basic: if suburb mentioned, flag an outage is likely
                schedule = [
                    {'start': '06:00', 'end': '10:00', 'on': False},
                    {'start': '10:00', 'end': '18:00', 'on': True},
                    {'start': '18:00', 'end': '22:00', 'on': False},
                    {'start': '22:00', 'end': '06:00', 'on': True},
                ]
    except Exception as e:
        logging.warning(f'Load shedding scrape failed: {e}')

    # Cache whatever we got (even empty)
    ls_cache[cache_key] = {'schedule': schedule, 'ts': time.time()}
    return jsonify(schedule), 200


