# 8. GOOGLE CALENDAR TODAY
#    Used by: AI Daily Planner panel
# ══════════════════════════════════════════════════════════
@app.route('/api/calendar/today', methods=['GET'])
@csrf.exempt
def calendar_today():
    """Returns today's calendar events. FIX: this previously always
    returned [] regardless of whether Google Calendar OAuth was
    connected -- the OAuth flow was built later (get_valid_calendar_token,
    /api/calendar/events) but this route was never updated to use it."""
    user = _get_current_user()
    if not user:
        return jsonify([]), 200
    token = get_valid_calendar_token(user["id"])
    if not token:
        return jsonify([]), 200
    try:
        today_start = datetime.utcnow().replace(hour=0, minute=0, second=0, microsecond=0)
        today_end   = today_start + timedelta(days=1)
        resp = requests.get(
            "https://www.googleapis.com/calendar/v3/calendars/primary/events",
            headers={"Authorization": f"Bearer {token}"},
            params={
                "timeMin": today_start.isoformat() + "Z",
                "timeMax": today_end.isoformat() + "Z",
                "singleEvents": "true",
                "orderBy": "startTime",
            }, timeout=12,
        )
        items = resp.json().get("items", []) if resp.status_code == 200 else []
        events = [{
            "id": e.get("id"),
            "title": e.get("summary", "(No title)"),
            "start": e.get("start", {}).get("dateTime") or e.get("start", {}).get("date"),
            "end": e.get("end", {}).get("dateTime") or e.get("end", {}).get("date"),
        } for e in items]
        return jsonify(events), 200
    except Exception as e:
        logging.error(f"[GCAL TODAY ERROR] user={user['id']}: {e}")
        return jsonify([]), 200


