# 27. MEETING NOTES EXPORT
#     Used by: Meeting Companion panel
# ══════════════════════════════════════════════════════════
@app.route('/api/meeting/export', methods=['POST'])
@csrf.exempt
def meeting_export():
    """Export meeting notes as a downloadable text or PDF file."""
    if not _csrf_ok():
        return jsonify({'error': 'CSRF check failed'}), 403

    data      = request.get_json() or {}
    summary   = data.get('summary',   '')
    actions   = data.get('actions',   [])
    decisions = data.get('decisions', [])
    date_str  = datetime.utcnow().strftime('%Y-%m-%d %H:%M UTC')

    content = (
        f'MEETING NOTES\n'
        f'Generated by Connect It · {date_str}\n'
        f'{"="*50}\n\n'
        f'SUMMARY\n{"-"*30}\n{summary}\n\n'
        f'ACTION ITEMS\n{"-"*30}\n'
        + '\n'.join(f'- [{a.get("assignee","")}] {a.get("task","")}' for a in actions) +
        f'\n\nDECISIONS\n{"-"*30}\n'
        + '\n'.join(f'- {d}' for d in decisions)
    )

    buf = io.BytesIO(content.encode('utf-8'))
    return Response(
        buf,
        mimetype='text/plain',
        headers={'Content-Disposition': f'attachment; filename="meeting_notes_{datetime.utcnow().strftime("%Y%m%d")}.txt"'}
    )


