#     Used by: Receipt Scanner panel
# ══════════════════════════════════════════════════════════
@app.route('/api/receipts/export', methods=['POST'])
@csrf.exempt
def receipts_export():
    """Export saved receipts as CSV."""
    if not _csrf_ok():
        return jsonify({'error': 'CSRF check failed'}), 403

    data     = request.get_json() or {}
    receipts = data.get('receipts', [])

    if not receipts:
        return jsonify({'error': 'No receipts provided'}), 400

    import csv as _csv
    buf    = io.StringIO()
    writer = _csv.writer(buf)
    writer.writerow(['Date', 'Store', 'Category', 'Currency', 'Total', 'Items Count'])
    for r in receipts:
        writer.writerow([
            r.get('date',     ''),
            r.get('store',    ''),
            r.get('category', ''),
            r.get('currency', 'USD'),
            r.get('total',    0),
            len(r.get('items', [])),
        ])

    csv_str  = buf.getvalue()
    filename = f'receipts_{datetime.utcnow().strftime("%Y%m%d")}.csv'
    return Response(
        csv_str,
        mimetype='text/csv',
        headers={'Content-Disposition': f'attachment; filename="{filename}"'}
    )


# ══════════════════════════════════════════════════════════
# 29. PROPOSAL SAVE (DB)
#     Used by: AI Proposal Builder panel
# ══════════════════════════════════════════════════════════
@app.route('/api/proposals/save', methods=['POST'])
@csrf.exempt
def proposals_save():
    """Save a generated proposal to server-side storage."""
    if not _csrf_ok():
        return jsonify({'error': 'CSRF check failed'}), 403

    user = _get_current_user()
    data = request.get_json() or {}
    name = data.get('client_name', 'Client')

    logging.info(f'[PROPOSAL SAVE] user={user["id"] if user else "anon"} | client={name}')
    return jsonify({'ok': True, 'saved_at': datetime.utcnow().isoformat()}), 200


# ══════════════════════════════════════════════════════════
# 30. FEATURE USAGE ANALYTICS
#     Used by: All new panels (optional telemetry)
# ══════════════════════════════════════════════════════════
@app.route('/api/features/log', methods=['POST'])
@csrf.exempt
def features_log():
    """
    Log which features are being used.
    Lightweight telemetry — no personal data stored.
    """
    data    = request.get_json() or {}
    feature = data.get('feature', 'unknown')
    action  = data.get('action',  'open')

    logging.info(f'[FEATURE LOG] {feature} | {action}')
    return jsonify({'ok': True}), 200


