# 32. UPGRADE MODE — Pro subscription vs. bring-your-own-key
#     A user can either pay Connect It for the Pro plan (billed by us,
#     runs on our shared keys), or switch to BYOK mode (they pay their
#     own AI/Twilio/storage bills directly, so platform rate limits
#     no longer apply to them).
# ═══════════════════════════════════════════════════════════

@app.route('/api/account/upgrade-mode', methods=['GET'])
@csrf.exempt
def account_get_upgrade_mode():
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    return jsonify({
        "plan": user.get("plan", "free"),
        "mode": get_user_mode(user["id"]),
    }), 200


@app.route('/api/account/upgrade-mode', methods=['POST'])
@csrf.exempt
def account_set_upgrade_mode():
    """mode = 'pro'  → redirect to Stripe checkout for the platform's Pro plan.
       mode = 'byok' → switch this account to bring-your-own-key mode. They
                        should also POST their keys to /api/integrations/keys."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401

    data = request.get_json(force=True, silent=True) or {}
    mode = (data.get("mode") or "").strip().lower()

    if mode == "pro":
        # Reuse the existing Stripe subscription checkout flow.
        return payments_create_checkout()

    if mode == "byok":
        row = UserAccountTier.query.filter_by(user_id=user["id"]).first()
        if row:
            row.mode = "byok"
        else:
            row = UserAccountTier(user_id=user["id"], mode="byok")
            db.session.add(row)
        db.session.commit()
        has_any_key = UserIntegration.query.filter_by(user_id=user["id"], active=True).first() is not None
        return jsonify({
            "ok":   True,
            "mode": "byok",
            "note": (
                "You're now in bring-your-own-key mode — no platform rate limits. "
                "Add your API keys at /api/integrations/keys to activate each feature."
                if not has_any_key else
                "You're now in bring-your-own-key mode using your saved keys."
            ),
        }), 200

    return jsonify({"error": "mode must be 'pro' or 'byok'."}), 400


