# ═══════════════════════════════════════════════════════════
# 34. BYOK PAYMENT COLLECTION (Payment Hub / Invoices / E-Sign)
#     Unlike /api/payments/create-checkout (which bills the Pro
#     subscription to Connect It's own Stripe/Flutterwave account),
#     this lets a business collect payment from THEIR OWN customers
#     using THEIR OWN Stripe or Flutterwave account.
# ═══════════════════════════════════════════════════════════

@app.route('/api/business/collect-payment', methods=['POST'])
@csrf.exempt
def business_collect_payment():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401

    data      = request.get_json(force=True, silent=True) or {}
    provider  = (data.get("provider") or "stripe").strip().lower()
    amount    = data.get("amount")
    currency  = data.get("currency", "USD")
    reference = data.get("reference", f"inv_{secrets.token_hex(4)}")
    customer_email = data.get("customer_email", "")

    if not amount:
        return jsonify({"error": "amount is required."}), 400

    if provider == "stripe":
        byok_key = get_effective_credential(user["id"], "stripe", "secret_key", STRIPE_SECRET_KEY)
        if not byok_key or not STRIPE_AVAILABLE:
            return jsonify({"error": "Stripe not configured. Add your Stripe secret key in Integrations."}), 503
        try:
            import stripe as stripe_lib
            stripe_lib.api_key = byok_key
            checkout = stripe_lib.checkout.Session.create(
                payment_method_types = ["card"],
                line_items = [{
                    "price_data": {
                        "currency": currency.lower(),
                        "product_data": {"name": f"Invoice {reference}"},
                        "unit_amount": int(float(amount) * 100),
                    },
                    "quantity": 1,
                }],
                mode        = "payment",
                success_url = APP_BASE_URL + "/payment-success?ref=" + reference,
                cancel_url  = APP_BASE_URL + "/?payment=cancelled",
                customer_email = customer_email or None,
                metadata    = {"business_user_id": str(user["id"]), "reference": reference},
            )
            return jsonify({"checkout_url": checkout.url, "provider": "stripe", "reference": reference}), 200
        except Exception as e:
            logging.error(f"[BYOK STRIPE ERROR] {e}")
            return jsonify({"error": str(e)}), 500

    elif provider == "flutterwave":
        byok_key = get_effective_credential(user["id"], "flutterwave", "secret_key", FLUTTERWAVE_SECRET_KEY)
        if not byok_key:
            return jsonify({"error": "Flutterwave not configured. Add your Flutterwave secret key in Integrations."}), 503
        try:
            r = requests.post(
                "https://api.flutterwave.com/v3/payments",
                headers={"Authorization": f"Bearer {byok_key}"},
                json={
                    "tx_ref":        reference,
                    "amount":        str(amount),
                    "currency":      currency,
                    "redirect_url":  APP_BASE_URL + "/payment-success?ref=" + reference,
                    "customer":      {"email": customer_email or "customer@example.com"},
                    "customizations": {"title": f"Invoice {reference}", "description": "Payment via Connect It"},
                },
                timeout=15,
            )
            body = r.json()
            if r.status_code == 200 and body.get("status") == "success":
                return jsonify({
                    "checkout_url": body["data"]["link"], "provider": "flutterwave", "reference": reference
                }), 200
            return jsonify({"error": body.get("message", "Flutterwave request failed.")}), 502
        except Exception as e:
            logging.error(f"[BYOK FLUTTERWAVE ERROR] {e}")
            return jsonify({"error": str(e)}), 500

    return jsonify({"error": "provider must be 'stripe' or 'flutterwave'."}), 400


