@app.route("/api/calendar/service-book", methods=["POST"])
def calendar_book_endpoint():
    """Service-account variant of /api/calendar/book above (used when a
    platform-level Google Calendar is configured rather than the user's
    own OAuth-connected calendar). Kept at its own URL — it previously
    shared the exact same route+method as calendar_book() above, which
    meant Werkzeug only ever matched the first-registered one and this
    version was silently unreachable."""
    user_id = _current_user_id()
    if not user_id:
        return jsonify({"error": "Login required."}), 401

    data = request.get_json(silent=True) or {}
    summary        = (data.get("summary") or "Consultation with Connect It").strip()
    description    = data.get("description") or ""
    start_iso      = data.get("start_time")
    end_iso        = data.get("end_time")
    client_name    = data.get("client_name")
    client_email   = data.get("client_email")
    timezone_name  = data.get("timezone", "Africa/Harare")

    if not start_iso or not end_iso:
        return jsonify({"error": "'start_time' and 'end_time' (ISO 8601) are required."}), 400

    result = create_calendar_event(
        user_id, summary, description, start_iso, end_iso,
        attendee_email=client_email, timezone=timezone_name,
    )
    if not result.get("ok"):
        return jsonify(result), 502

    try:
        booking = CalendarBooking(
            user_id=user_id,
            calendar_event_id=result.get("event_id"),
            summary=summary,
            description=description,
            client_name=client_name,
            client_email=client_email,
            start_time=datetime.fromisoformat(start_iso.replace("Z", "+00:00")),
            end_time=datetime.fromisoformat(end_iso.replace("Z", "+00:00")),
            meet_link=result.get("meet_link"),
        )
        db.session.add(booking)
        db.session.commit()
    except Exception as e:
        logging.error(f"[CALENDAR BOOKING SAVE ERROR] user={user_id}: {e}")

    return jsonify({
        "ok": True,
        "event_id": result.get("event_id"),
        "html_link": result.get("html_link"),
        "meet_link": result.get("meet_link"),
    }), 200


