@app.route("/api/code/patch", methods=["POST"])
@csrf.exempt
def code_patch_endpoint():
    """Surgical edit — replaces exactly one occurrence of old_str inside
    current_content. Use this instead of /api/code/edit for large files:
    only old_str plus a few lines of context ever reach the model, so
    cost and risk don't scale with file size, and nothing outside
    old_str can be touched. See ai_patch_code() for the full contract."""
    user, err = _erp_user_or_401()
    if err: return err
    gate_result = gate_ai_usage(user, "code_patch_endpoint")
    if gate_result is not None:
        return gate_result
    user_id = user["id"]
    data = request.get_json(silent=True) or {}
    language     = (data.get("language") or "python").strip()
    current      = data.get("current_content") or ""
    old_str      = data.get("old_str") or ""
    new_str      = data.get("new_str")
    instructions = (data.get("instructions") or "").strip()

    if not current.strip():
        return jsonify({"error": "'current_content' is required — send the file's existing content."}), 400
    if not old_str:
        return jsonify({"error": "'old_str' is required — the exact snippet to replace."}), 400
    if new_str is None and not instructions:
        return jsonify({"error": "Provide either 'new_str' (exact replacement) or 'instructions' (let the AI write it)."}), 400

    try:
        result = ai_patch_code(language, current, old_str, instructions=instructions,
                                new_str=new_str, user_id=user_id)
        status = 200 if result.get("ok") else 400
        return jsonify({"language": language, **result}), status
    except Exception as e:
        logging.error(f"[CODE PATCH ERROR] user={user_id}: {e}")
        return jsonify({"ok": False, "error": str(e)}), 502


