@app.route("/api/code/unzip", methods=["POST"])
@csrf.exempt
def code_unzip_endpoint():
    """Extracts a zip's text files so the AI (or the user) can view/edit
    each one individually. Accepts a multipart file OR {"zip_base64": ...}."""
    zip_bytes = None
    if "file" in request.files:
        zip_bytes = request.files["file"].read()
    else:
        data = request.get_json(silent=True) or {}
        b64 = data.get("zip_base64")
        if b64:
            try:
                zip_bytes = base64.b64decode(b64)
            except Exception:
                return jsonify({"error": "zip_base64 could not be decoded."}), 400

    if not zip_bytes:
        return jsonify({"error": "Send a 'file' upload or 'zip_base64' in JSON."}), 400

    text_exts = (".txt", ".md", ".py", ".js", ".jsx", ".ts", ".tsx", ".html", ".css",
                 ".json", ".csv", ".java", ".c", ".cpp", ".cs", ".go", ".rb", ".php",
                 ".sql", ".yml", ".yaml", ".sh", ".xml")
    try:
        out = []
        with zipfile.ZipFile(io.BytesIO(zip_bytes)) as z:
            for name in z.namelist():
                if name.endswith("/"):
                    continue
                info = z.getinfo(name)
                entry = {"filename": name, "size": info.file_size}
                if name.lower().endswith(text_exts) and info.file_size <= 500_000:
                    entry["content"] = z.read(name).decode("utf-8", errors="replace")
                else:
                    entry["content"] = None
                    entry["note"] = "binary or too large to inline"
                out.append(entry)
        return jsonify({"ok": True, "files": out}), 200
    except Exception as e:
        logging.error(f"[CODE UNZIP ERROR] {e}")
        return jsonify({"ok": False, "error": str(e)}), 400


