@app.route("/api/business-profile/oauth-status", methods=["GET"])
@csrf.exempt
def business_profile_oauth_status():
    """STAGE 517: tells the frontend which connection mode is active —
    real per-user OAuth (preferred) vs. the legacy pasted
    service-account JSON (still supported as a fallback) — so the
    Local Discovery panel can show the right UI without guessing."""
    user_id = _current_user_id()
    if not user_id:
        return jsonify({"error": "Login required."}), 401
    oauth_connected = bool(get_valid_google_token(
        user_id, required_scope=_google_oauth_scope_for_service("business_profile")
    ))
    legacy_row = UserIntegration.query.filter_by(
        user_id=user_id, provider="google_business_profile", active=True
    ).first() if not oauth_connected else None
    return jsonify({
        "ok": True,
        "oauth_connected": oauth_connected,
        "legacy_service_account_connected": bool(legacy_row),
        "connected": oauth_connected or bool(legacy_row),
    })


