# STAGE: Enterprise Roadmap Part 2.6 — deeper OAuth API integrations.
# Closes the doc's "manual copy-paste" gap for Google Business Profile:
# this pushes real field updates (hours, phone, website, description)
# straight to Google via the Business Information API's patch endpoint,
# and the bulk variant applies the same patch across every location a
# multi-branch business manages in one call — no copy-pasting text
# into Google's own dashboard per location.
@app.route("/api/business-profile/locations/update", methods=["POST"])
@csrf.exempt
def business_profile_location_update_endpoint():
    user_id = _current_user_id()
    if not user_id:
        return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    location_name = (data.get("location_name") or "").strip()
    patch = data.get("patch") or {}
    if not isinstance(patch, dict):
        return jsonify({"error": "'patch' must be an object of fields to update."}), 400
    result = update_business_profile_location(user_id, location_name, patch)
    return jsonify(result), (200 if result.get("ok") else 502)


@app.route("/api/business-profile/locations/bulk-update", methods=["POST"])
@csrf.exempt
def business_profile_locations_bulk_update_endpoint():
    """Body: {"location_names": ["accounts/1/locations/2", ...], "patch": {...}}
    Applies the same patch (e.g. new hours, new phone number) to every
    listed location — the "automated multi-location update" the roadmap
    doc asked for, instead of updating each listing by hand in Google's
    own dashboard."""
    user_id = _current_user_id()
    if not user_id:
        return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    location_names = data.get("location_names") or []
    patch = data.get("patch") or {}
    if not isinstance(location_names, list) or not location_names:
        return jsonify({"error": "'location_names' must be a non-empty array."}), 400
    if not isinstance(patch, dict) or not patch:
        return jsonify({"error": "'patch' must be a non-empty object of fields to update."}), 400
    if len(location_names) > 100:
        return jsonify({"error": "Max 100 locations per bulk update call."}), 400

    results = []
    succeeded = 0
    for loc_name in location_names:
        res = update_business_profile_location(user_id, str(loc_name).strip(), patch)
        results.append(res)
        if res.get("ok"):
            succeeded += 1
    notify_user(user_id, "business_profile", "Multi-location update complete",
                f"{succeeded}/{len(location_names)} listings updated.")
    return jsonify({"ok": succeeded > 0, "succeeded": succeeded, "total": len(location_names), "results": results}), 200


