@app.route("/api/location/reverse-geocode", methods=["POST"])
@csrf.exempt
def reverse_geocode_endpoint():
    """Frontend sends the browser's real GPS/network location (lat, lng);
    we resolve it to a real city + country via Google — used for the
    city/country shown next to the live clock."""
    user_id = _current_user_id()
    data = request.get_json(silent=True) or {}
    try:
        lat = float(data.get("lat"))
        lng = float(data.get("lng"))
    except (TypeError, ValueError):
        return jsonify({"error": "'lat' and 'lng' (numbers) are required."}), 400

    result = reverse_geocode(lat, lng, user_id=user_id)
    return jsonify(result), (200 if result.get("ok") else 502)


@app.route("/api/location/ip-lookup", methods=["GET"])
def ip_lookup_endpoint():
    """Fallback for when browser Geolocation is blocked/denied — resolves
    city/country from the request's IP address instead. No permission
    prompt, no Google API key required."""
    ip = request.headers.get("X-Forwarded-For", request.remote_addr) or ""
    if "," in ip:
        ip = ip.split(",")[0].strip()
    result = ip_geolocate(ip)
    return jsonify(result), (200 if result.get("ok") else 502)


