# NEW BLOCK: "CREATE MEMORY" — permanent per-user archive
# Everything a logged-in user generates lives here forever. Users can
# remove their own single entries; only an admin account can wipe a
# user's entire archive (see /api/admin/memory/wipe below).
# ===========================================================

@app.route("/api/memory/list", methods=["GET"])
def memory_list_endpoint():
    current_user = _get_current_user()
    if not current_user:
        return jsonify({"error": "Login required."}), 401
    user_id = current_user["id"]

    entries = (
        UserMemory.query
        .filter_by(user_id=user_id, deleted_at=None)
        .order_by(UserMemory.created_at.asc())
        .limit(2000)
        .all()
    )
    return jsonify({"entries": [e.to_dict() for e in entries]}), 200


@app.route("/api/memory/save", methods=["POST"])
@csrf.exempt
def memory_save_endpoint():
    """For content generated OUTSIDE the normal chat flow (code, docs,
    bookings, receipts...) that the frontend wants archived into the same
    permanent log book."""
    user_id = None
    current_user = _get_current_user()
    if current_user:
        user_id = current_user["id"]
    if not user_id:
        return jsonify({"error": "Login required."}), 401

    data = request.get_json(silent=True) or {}
    role         = (data.get("role") or "assistant").strip()
    content_type = (data.get("content_type") or "chat").strip()
    content      = data.get("content") or ""
    extra        = data.get("extra")

    if not content.strip():
        return jsonify({"error": "'content' is required."}), 400

    save_to_memory(user_id, role, content, content_type=content_type, extra=extra)
    return jsonify({"ok": True}), 200


# NOTE: _require_admin() (shared helper: returns (admin_user, None) for a
# recognized admin, or (None, error_response) otherwise) is defined once,
# below, near the Broadcast Channels routes — reused here.

@app.route("/api/memory/<int:entry_id>", methods=["DELETE"])
@csrf.exempt
def memory_delete_entry_endpoint(entry_id):
    """ADMIN ONLY. Regular users can view their permanent Memory log but
    can never delete an entry — that's what keeps this log trustworthy as
    an audit trail for tracing fraudulent activity and for legal action.
    Only a recognized admin (is_admin=True or email in ADMIN_EMAILS) may
    remove a single entry; every deletion is logged with the reason given."""
    admin_user, err = _require_admin()
    if err:
        return err

    data   = request.get_json(silent=True) or {}
    reason = (data.get("reason") or "").strip()

    entry = UserMemory.query.filter_by(id=entry_id).first()
    if not entry:
        return jsonify({"error": "Entry not found."}), 404

    entry.deleted_at = datetime.utcnow()
    db.session.commit()

    logging.warning(
        f"[ADMIN MEMORY ENTRY DELETE] admin_id={admin_user.id} ({admin_user.email}) "
        f"deleted entry_id={entry_id} (user_id={entry.user_id}). Reason: {reason or 'not given'}"
    )
    return jsonify({"ok": True}), 200


@app.route("/api/admin/memory/list", methods=["GET"])
def admin_memory_list_endpoint():
    """ADMIN ONLY. Cross-user view into the Memory log — lets an admin
    pull one user's full record (by user_id or email), or search by
    keyword, to trace fraudulent activity and prepare records for legal
    action. Every lookup is logged."""
    admin_user, err = _require_admin()
    if err:
        return err

    target_user_id = request.args.get("user_id", type=int)
    target_email    = (request.args.get("email") or "").strip().lower()
    q               = (request.args.get("q") or "").strip()
    limit           = min(request.args.get("limit", 500, type=int) or 500, 5000)

    if target_email and not target_user_id:
        target_user = UserAccount.query.filter_by(email=target_email).first()
        if not target_user:
            return jsonify({"error": "No account found with that email."}), 404
        target_user_id = target_user.id

    query = UserMemory.query.filter(UserMemory.deleted_at.is_(None))
    if target_user_id:
        query = query.filter_by(user_id=target_user_id)
    if q:
        query = query.filter(UserMemory.content.ilike(f"%{q}%"))

    entries = query.order_by(UserMemory.created_at.asc()).limit(limit).all()

    logging.info(
        f"[ADMIN MEMORY VIEW] admin_id={admin_user.id} ({admin_user.email}) viewed {len(entries)} "
        f"entries (target_user_id={target_user_id}, q={q!r})"
    )
    return jsonify({"entries": [e.to_admin_dict() for e in entries]}), 200


@app.route("/api/admin/memory/pdf", methods=["GET"])
def admin_memory_pdf_endpoint():
    """ADMIN ONLY. Renders a target user's Memory log (or a keyword-filtered
    slice of it) as a PDF — for the admin's own Print dialog or as a
    downloadable record to hand to legal/compliance. Same filters as
    /api/admin/memory/list. Every export is logged."""
    admin_user, err = _require_admin()
    if err:
        return err

    target_user_id = request.args.get("user_id", type=int)
    target_email    = (request.args.get("email") or "").strip().lower()
    q               = (request.args.get("q") or "").strip()
    reason         = (request.args.get("reason") or "").strip()

    target_user = None
    if target_email and not target_user_id:
        target_user = UserAccount.query.filter_by(email=target_email).first()
        if not target_user:
            return jsonify({"error": "No account found with that email."}), 404
        target_user_id = target_user.id
    if target_user_id and not target_user:
        target_user = UserAccount.query.get(target_user_id)

    if not target_user_id:
        return jsonify({"error": "'user_id' or 'email' (the target account) is required."}), 400

    query = UserMemory.query.filter_by(user_id=target_user_id).filter(UserMemory.deleted_at.is_(None))
    if q:
        query = query.filter(UserMemory.content.ilike(f"%{q}%"))
    entries = query.order_by(UserMemory.created_at.asc()).limit(5000).all()

    target_label = (target_user.email if target_user else f"user_id {target_user_id}")
    generated_at = datetime.utcnow().strftime("%Y-%m-%d %H:%M UTC")
    filename = f"memory_log_{target_user_id}_{datetime.utcnow().strftime('%Y%m%d%H%M%S')}.pdf"

    rows_html = ""
    for e in entries:
        d = e.to_dict()
        ts = d["created_at"] or ""
        role = "User" if d["role"] == "user" else "Connect It"
        content_esc = escape(d["content"] or "")
        rows_html += (
            f'<div class="entry"><div class="meta">{escape(ts)} &middot; {escape(role)}'
            f' &middot; {escape(d["content_type"] or "")} &middot; entry #{d["id"]}</div>'
            f'<div class="body">{content_esc}</div></div>'
        )

    styled_html = f"""
    <!DOCTYPE html><html><head><meta charset="UTF-8"/>
    <style>
      body{{font-family:Georgia,serif;max-width:800px;margin:30px auto;color:#1e293b;font-size:12px;line-height:1.6;}}
      .header{{background:linear-gradient(90deg,#1e3a8a,#2563eb);color:white;padding:20px;border-radius:8px;margin-bottom:20px;}}
      .header h1{{margin:0;font-size:18px;}}
      .header p{{margin:6px 0 0;opacity:0.85;font-size:11px;}}
      .entry{{border-bottom:1px solid #e2e8f0;padding:10px 0;}}
      .meta{{color:#64748b;font-size:10px;margin-bottom:4px;}}
      .body{{white-space:pre-wrap;word-break:break-word;}}
    </style></head><body>
    <div class="header">
      <h1>Connect It — Activity Log Audit Trail</h1>
      <p>Account: {escape(target_label)} (user_id {target_user_id}) &middot; Generated {escape(generated_at)}
      by admin {escape(admin_user.email)}{(' &middot; Reason: ' + escape(reason)) if reason else ''}</p>
    </div>
    {rows_html or '<p>No entries found for this account/filter.</p>'}
    </body></html>"""

    logging.warning(
        f"[ADMIN MEMORY PDF EXPORT] admin_id={admin_user.id} ({admin_user.email}) exported "
        f"{len(entries)} entries for user_id={target_user_id}. Reason: {reason or 'not given'}"
    )

    if WEASYPRINT_AVAILABLE:
        try:
            pdf_bytes = WeasyHTML(string=styled_html).write_pdf()
            return Response(
                pdf_bytes,
                mimetype='application/pdf',
                headers={'Content-Disposition': f'inline; filename="{filename}"'}
            )
        except Exception as e:
            logging.warning(f'WeasyPrint failed for memory PDF export, falling back: {e}')

    if REPORTLAB_AVAILABLE:
        buf = io.BytesIO()
        doc = SimpleDocTemplate(buf, pagesize=A4)
        styles = getSampleStyleSheet()
        story = [Paragraph("Connect It — Activity Log Audit Trail", styles["Title"]),
                 Paragraph(f"Account: {target_label} (user_id {target_user_id}) — Generated {generated_at} by {admin_user.email}", styles["Normal"]),
                 Spacer(1, 12)]
        for e in entries:
            d = e.to_dict()
            story.append(Paragraph(f"<b>{d['created_at']} &middot; {d['role']} &middot; {d['content_type']} &middot; #{d['id']}</b>", styles["Normal"]))
            story.append(Paragraph((d["content"] or "").replace("\n", "<br/>"), styles["Normal"]))
            story.append(Spacer(1, 8))
        doc.build(story)
        pdf_bytes = buf.getvalue()
        return Response(
            pdf_bytes,
            mimetype='application/pdf',
            headers={'Content-Disposition': f'inline; filename="{filename}"'}
        )

    return jsonify({"error": "PDF generation is unavailable on this server (install reportlab or weasyprint)."}), 500


@app.route("/api/admin/memory/wipe", methods=["POST"])
@csrf.exempt
def admin_memory_wipe_endpoint():
    """ADMIN ONLY. Permanently and irreversibly erases every UserMemory row
    for a target user — used only when that user has requested full
    erasure, or when required by a law-enforcement/legal request. Requires
    the caller's own account to be a recognized admin: either is_admin =
    True on the account, or the account's email is one of the hardcoded
    ADMIN_EMAILS (nzombet43@gmail.com, connectitnzombe@gmail.com,
    peacemakernzombe@gmail.com, mhereapey@gmail.com, nzombemercy@gmail.com)."""
    current_user = _get_current_user()
    if not current_user:
        return jsonify({"error": "Login required."}), 401
    admin_id = current_user["id"]

    admin_user = UserAccount.query.get(admin_id)
    is_recognized_admin = bool(admin_user) and (
        admin_user.is_admin or (admin_user.email or "").strip().lower() in ADMIN_EMAILS
    )
    if not is_recognized_admin:
        return jsonify({"error": "Admin privileges required."}), 403

    data           = request.get_json(silent=True) or {}
    target_user_id = data.get("user_id")
    target_email    = (data.get("target_email") or "").strip().lower()
    reason         = (data.get("reason") or "").strip()

    if not target_user_id and not target_email:
        return jsonify({"error": "'user_id' or 'target_email' (the target account) is required."}), 400
    if not reason:
        return jsonify({"error": "'reason' is required (e.g. 'user request' or 'legal order') — this is logged."}), 400

    if not target_user_id:
        target_user = UserAccount.query.filter_by(email=target_email).first()
        if not target_user:
            return jsonify({"error": "No account found with that email."}), 404
        target_user_id = target_user.id

    deleted_count = UserMemory.query.filter_by(user_id=target_user_id).delete()
    db.session.commit()

    logging.warning(
        f"[ADMIN MEMORY WIPE] admin_id={admin_id} ({admin_user.email}) wiped {deleted_count} "
        f"entries for user_id={target_user_id}. Reason: {reason}"
    )
    return jsonify({"ok": True, "deleted_count": deleted_count}), 200


# ===========================================================
# NEW BLOCK: BROADCAST CHANNELS — ROUTES
# Generating and sending hope/positivity content is admin-only (it posts
# publicly under the app's name to real external channels). The RSS feed
# itself is fully public — that's the whole point of a feed.
# ===========================================================

# SOC 2 CC6 (logical access control) gap fix: admin privileges must
# actually require MFA, not just make it available. Enforced centrally
# in _require_admin() below rather than at login, so an admin can still
# log in with just a password and immediately complete
# /api/auth/2fa/setup (session-only, not admin-gated) to unblock every
# admin-only route — no chicken-and-egg lockout. Set
# ADMIN_MFA_ENFORCEMENT=false as an emergency escape hatch only if an
# admin is locked out with no way to re-enroll.
ADMIN_MFA_ENFORCEMENT = os.environ.get("ADMIN_MFA_ENFORCEMENT", "true").strip().lower() != "false"


def _require_admin():
    admin_id = _current_user_id()
    if not admin_id:
        return None, (jsonify({"error": "Login required."}), 401)
    admin_user = UserAccount.query.get(admin_id)
    is_recognized_admin = bool(admin_user) and (
        admin_user.is_admin or (admin_user.email or "").strip().lower() in ADMIN_EMAILS
    )
    if not is_recognized_admin:
        return None, (jsonify({"error": "Admin privileges required."}), 403)
    if ADMIN_MFA_ENFORCEMENT:
        has_mfa = bool(admin_user.totp_enabled) or bool(
            WebAuthnCredential.query.filter_by(user_id=admin_user.id).first()
        )
        if not has_mfa:
            return None, (jsonify({
                "error": "Admin access requires two-factor authentication. "
                         "Set it up under Settings \u2192 Two-Factor Authentication, then try again.",
                "admin_mfa_required": True,
            }), 403)
    return admin_user, None


# ════════════════════════════════════════════════════════════
# ADMIN — OPTIONAL DEPENDENCY / STARTUP DIAGNOSTICS
# Every optional import in this file (qrcode, pyotp, Pillow, etc.) sets
# a module-level `<NAME>_AVAILABLE` bool at startup, wrapped in a
# try/except so a missing package degrades a feature instead of
# crashing the whole app. That's great for uptime, but it means a
# missing package on PythonAnywhere (usually installed into the wrong
# virtualenv — see the flask_cors/qrcode history) is otherwise only
# visible in the server error log. This walks module globals for any
# `_AVAILABLE` flag and reports it here instead, so a fresh reload can
# be checked from inside the app.
# ════════════════════════════════════════════════════════════

@app.route("/api/admin/debug/deps", methods=["GET"])
def admin_debug_deps():
    admin_user, err = _require_admin()
    if err:
        return err
    deps = {
        key: value for key, value in globals().items()
        if key.endswith("_AVAILABLE") and isinstance(value, bool)
    }
    missing = sorted(k for k, v in deps.items() if not v)
    return jsonify({
        "dependencies":  dict(sorted(deps.items())),
        "total":         len(deps),
        "missing_count": len(missing),
        "missing":       missing,
    }), 200


# ════════════════════════════════════════════════════════════
# Security & Sovereign Trust roadmap, item 4: ACCELERATED
# CERTIFICATION (SOC 2 Type II / ISO 27001) — COMPLIANCE READINESS
# CENTER.
#
# Honesty about what this is and isn't:
#   - SOC 2 Type II and ISO 27001 are certifications issued by an
#     independent, accredited third-party auditor after a real audit
#     (SOC 2 Type II specifically requires observing controls operate
#     over a period of months). No amount of code in this file can
#     issue that certificate — anything that claimed otherwise would
#     be exactly the kind of fabricated trust signal this whole
#     roadmap section exists to move away from.
#   - What software CAN genuinely do, and what this builds, is track
#     and evidence audit readiness: a real checklist against the
#     actual public control catalogs (SOC 2's Trust Services Criteria
#     and ISO 27001:2022's Annex A control themes), with a status and
#     an evidence note/link per control, kept by whoever owns
#     compliance at Connect It. That checklist — plus the exportable
#     JSON — is a genuine artifact an auditor can start from; it
#     shortens the path to certification, it does not stand in for it.
#   - The public trust page therefore only ever shows an honest
#     "working toward" state and aggregate percentages — never a claim
#     of certification unless an admin has recorded a real
#     certificate_ref (e.g. an auditor's report/certificate number),
#     which this app has no way to verify on its own and simply
#     displays as provided.
# ════════════════════════════════════════════════════════════

class ComplianceControl(db.Model):
    __tablename__     = "compliance_controls"
    id                = db.Column(db.Integer, primary_key=True)
    framework         = db.Column(db.String(24), nullable=False, index=True)  # "soc2" or "iso27001"
    control_ref       = db.Column(db.String(24), nullable=False)   # e.g. "CC6.1" or "A.5.1"
    category          = db.Column(db.String(120), nullable=False)
    title             = db.Column(db.String(200), nullable=False)
    description       = db.Column(db.Text, nullable=True)
    status            = db.Column(db.String(16), nullable=False, default="not_started", index=True)  # not_started, in_progress, implemented
    evidence_note     = db.Column(db.Text, nullable=True)
    evidence_link     = db.Column(db.String(500), nullable=True)
    updated_by_email  = db.Column(db.String(128), nullable=True)
    updated_at        = db.Column(db.DateTime, default=datetime.utcnow, onupdate=datetime.utcnow)

    def to_dict(self):
        return {
            "id": self.id, "framework": self.framework, "control_ref": self.control_ref,
            "category": self.category, "title": self.title, "description": self.description,
            "status": self.status, "evidence_note": self.evidence_note, "evidence_link": self.evidence_link,
            "updated_by_email": self.updated_by_email,
            "updated_at": self.updated_at.isoformat() if self.updated_at else None,
        }


class ComplianceSettings(db.Model):
    """Single-row settings: the honest 'certificate_ref' field described
    above, plus the public-facing commitment text an admin can edit."""
    __tablename__      = "compliance_settings"
    id                 = db.Column(db.Integer, primary_key=True)
    soc2_certificate_ref    = db.Column(db.String(200), nullable=True)
    iso27001_certificate_ref = db.Column(db.String(200), nullable=True)
    security_contact_email = db.Column(db.String(128), nullable=True)
    trust_page_summary      = db.Column(db.Text, nullable=True)
    updated_at         = db.Column(db.DateTime, default=datetime.utcnow, onupdate=datetime.utcnow)


class DatabaseBackupLog(db.Model):
    """One row per attempted platform database backup — evidence for
    SOC 2 CC9 (availability / disaster recovery), whether triggered by
    the daily cron or an admin's manual 'Run Backup Now'."""
    __tablename__    = "database_backup_logs"
    id               = db.Column(db.Integer, primary_key=True)
    started_at       = db.Column(db.DateTime, default=datetime.utcnow, nullable=False)
    finished_at      = db.Column(db.DateTime, nullable=True)
    status           = db.Column(db.String(16), nullable=False, default="running")  # running, success, failed
    method           = db.Column(db.String(24), nullable=True)   # mysqldump, sqlalchemy_fallback
    destination      = db.Column(db.String(16), nullable=True)   # local, s3
    location         = db.Column(db.String(500), nullable=True)  # local path or s3:// url
    size_bytes       = db.Column(db.Integer, nullable=True)
    triggered_by     = db.Column(db.String(120), nullable=True)  # "cron" or an admin's email
    error_message    = db.Column(db.Text, nullable=True)

    def to_dict(self):
        return {
            "id": self.id,
            "started_at": self.started_at.isoformat() if self.started_at else None,
            "finished_at": self.finished_at.isoformat() if self.finished_at else None,
            "status": self.status, "method": self.method, "destination": self.destination,
            "location": self.location, "size_bytes": self.size_bytes,
            "triggered_by": self.triggered_by, "error_message": self.error_message,
        }


# Real, publicly-documented control catalogs — SOC 2's Trust Services
# Criteria common-criteria series (CC1-CC9) and ISO/IEC 27001:2022's
# Annex A control themes. These are the standard reference points any
# real audit against either framework starts from; nothing here is
# invented. Kept intentionally at category/theme granularity (not the
# full sub-control text of either paid standard) since that's what a
# tracked-readiness checklist needs, not a redistribution of the
# copyrighted standard documents themselves.
_SOC2_CONTROL_SEED = [
    ("CC1", "Control Environment", "Control Environment", "Governance structure, ethical values, and board/management oversight of the security program."),
    ("CC2", "Communication & Information", "Communication and Information", "Internal and external communication of security policies, roles, and incident information."),
    ("CC3", "Risk Assessment", "Risk Assessment", "Identification, analysis, and management of risks to the achievement of security objectives."),
    ("CC4", "Monitoring Activities", "Monitoring Activities", "Ongoing and separate evaluations to ascertain whether controls are present and functioning."),
    ("CC5", "Control Activities", "Control Activities", "Policies and procedures that help ensure management directives are carried out."),
    ("CC6", "Logical & Physical Access Controls", "Logical and Physical Access Controls", "Access provisioning, authentication (including MFA/hardware keys), encryption, and physical safeguards."),
    ("CC7", "System Operations", "System Operations", "Detection and management of security events, vulnerabilities, and operational anomalies."),
    ("CC8", "Change Management", "Change Management", "Authorization, design, testing, and approval of changes to infrastructure and software."),
    ("CC9", "Risk Mitigation", "Risk Mitigation", "Business continuity, disaster recovery, and vendor/subprocessor risk management."),
]
_ISO27001_CONTROL_SEED = [
    ("A.5", "Organizational Controls", "Organizational Controls", "Policies for information security, roles/responsibilities, supplier relationships, incident management."),
    ("A.6", "People Controls", "People Controls", "Screening, terms of employment, security awareness/training, disciplinary process."),
    ("A.7", "Physical Controls", "Physical Controls", "Physical security perimeters, equipment security, secure disposal, clear desk/screen."),
    ("A.8", "Technological Controls", "Technological Controls", "Access control, cryptography, malware protection, backup, logging/monitoring, secure development."),
]


def _compliance_seed_controls():
    """Idempotent — inserts each catalog row exactly once, keyed on
    (framework, control_ref). Safe to call on every startup."""
    try:
        existing = {(c.framework, c.control_ref) for c in ComplianceControl.query.all()}
        added = False
        for ref, category, title, desc in _SOC2_CONTROL_SEED:
            if ("soc2", ref) not in existing:
                db.session.add(ComplianceControl(framework="soc2", control_ref=ref, category=category, title=title, description=desc))
                added = True
        for ref, category, title, desc in _ISO27001_CONTROL_SEED:
            if ("iso27001", ref) not in existing:
                db.session.add(ComplianceControl(framework="iso27001", control_ref=ref, category=category, title=title, description=desc))
                added = True
        if added:
            db.session.commit()
        if not ComplianceSettings.query.first():
            db.session.add(ComplianceSettings(
                trust_page_summary="Connect It is actively building its security and compliance program toward SOC 2 Type II and ISO 27001 readiness."))
            db.session.commit()
    except Exception as e:
        db.session.rollback()
        logging.warning(f"[COMPLIANCE SEED] skipped: {e}")


with app.app_context():
    try:
        db.create_all()
        _compliance_seed_controls()
    except Exception as _compliance_init_err:
        app.logger.warning("compliance controls init failed: %s", _compliance_init_err)


def _compliance_readiness(framework):
    rows = ComplianceControl.query.filter_by(framework=framework).all()
    if not rows:
        return {"total": 0, "implemented": 0, "in_progress": 0, "not_started": 0, "percent_ready": 0}
    counts = {"implemented": 0, "in_progress": 0, "not_started": 0}
    for r in rows:
        counts[r.status] = counts.get(r.status, 0) + 1
    total = len(rows)
    # A control "in progress" counts as half-credit toward the readiness
    # percentage — a standard, defensible way to show partial progress
    # without rounding it up to the same weight as a fully implemented
    # and evidenced control.
    percent = round(((counts["implemented"] + counts["in_progress"] * 0.5) / total) * 100, 1)
    return {"total": total, "implemented": counts["implemented"], "in_progress": counts["in_progress"],
            "not_started": counts["not_started"], "percent_ready": percent}


# ════════════════════════════════════════════════════════════
# AUTOMATED DATABASE BACKUP — SOC 2 CC9 (availability / disaster
# recovery) gap fix. Real mysqldump when available, a portable
# SQLAlchemy row-by-row JSON fallback when it isn't (e.g. the binary
# missing on a given PythonAnywhere plan), gzipped either way, kept
# locally on a rotating basis and optionally mirrored to S3. Every
# attempt — success or failure — is logged to DatabaseBackupLog so
# there's a real evidence trail, not just a "we run backups" claim.
# ════════════════════════════════════════════════════════════

def _backup_local_dir():
    """Local directory for rotating DB backup dumps. Falls back to the
    system tempdir if the app-relative folder can't be created (same
    disk-quota-fragility lesson as the earlier tribute-video fix) —
    never raises."""
    try:
        d = os.path.join(os.path.dirname(os.path.abspath(__file__)), "db_backups")
        os.makedirs(d, exist_ok=True)
        return d
    except Exception:
        try:
            d = os.path.join(tempfile.gettempdir(), "connectit_db_backups")
            os.makedirs(d, exist_ok=True)
            return d
        except Exception:
            return tempfile.gettempdir()


def _backup_parse_mysql_uri(uri):
    """Extracts (user, password, host, port, dbname) from a
    mysql+pymysql://user:pass@host/db SQLAlchemy URI. Returns None for
    anything that isn't MySQL (e.g. a local sqlite fallback)."""
    try:
        if not uri or not uri.startswith("mysql"):
            return None
        from urllib.parse import urlparse, unquote
        parsed = urlparse(uri.replace("mysql+pymysql://", "mysql://", 1))
        if not parsed.hostname:
            return None
        return {
            "user": unquote(parsed.username or ""),
            "password": unquote(parsed.password or ""),
            "host": parsed.hostname or "",
            "port": parsed.port or 3306,
            "dbname": (parsed.path or "").lstrip("/"),
        }
    except Exception:
        return None


def _backup_dump_mysql(conn_info, out_path):
    """Runs mysqldump via subprocess, gzipping the output straight to
    out_path. Returns (ok, error_message)."""
    try:
        cmd = [
            "mysqldump",
            "-h", conn_info["host"], "-P", str(conn_info["port"]),
            "-u", conn_info["user"], "-p" + conn_info["password"],
            "--single-transaction", "--quick", "--no-tablespaces",
            conn_info["dbname"],
        ]
        result = subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=600)
        if result.returncode != 0 or not result.stdout:
            return False, (result.stderr or b"").decode("utf-8", "ignore")[:2000] or "mysqldump produced no output."
        with gzip.open(out_path, "wb") as gz:
            gz.write(result.stdout)
        return True, None
    except FileNotFoundError:
        return False, "mysqldump binary not found on this server."
    except subprocess.TimeoutExpired:
        return False, "mysqldump timed out after 10 minutes."
    except Exception as e:
        return False, str(e)


def _backup_dump_sqlalchemy_fallback(out_path):
    """Portable fallback when mysqldump isn't available: walks every
    real table via SQLAlchemy reflection and writes each table's rows
    as JSON, gzipped. Not a byte-identical mysqldump restore file, but
    every row of every table is captured for a scripted restore.
    default=str handles datetime/Decimal/bytes columns that json can't
    natively serialize."""
    try:
        from sqlalchemy import inspect as _sa_inspect, text as _sa_text
        inspector = _sa_inspect(db.engine)
        table_names = inspector.get_table_names()
        with gzip.open(out_path, "wt", encoding="utf-8") as gz:
            gz.write('{"generated_at": %s, "method": "sqlalchemy_fallback", "tables": {' % json.dumps(datetime.utcnow().isoformat()))
            with db.engine.connect() as conn:
                for i, tname in enumerate(table_names):
                    if i:
                        gz.write(",")
                    gz.write(json.dumps(tname) + ":[")
                    result = conn.execute(_sa_text(f"SELECT * FROM `{tname}`"))
                    cols = result.keys()
                    for j, row in enumerate(result):
                        if j:
                            gz.write(",")
                        gz.write(json.dumps(dict(zip(cols, row)), default=str))
                    gz.write("]")
            gz.write("}}")
        return True, None
    except Exception as e:
        return False, str(e)


def _backup_upload_to_s3(local_path, filename):
    try:
        import boto3
    except ImportError:
        return False, "boto3 is not installed."
    try:
        s3 = boto3.client(
            "s3", aws_access_key_id=BACKUP_S3_ACCESS_KEY_ID,
            aws_secret_access_key=BACKUP_S3_SECRET_ACCESS_KEY, region_name=BACKUP_S3_REGION,
        )
        key = f"connectit-ai-platform-backups/{filename}"
        s3.upload_file(local_path, BACKUP_S3_BUCKET, key)
        return True, f"s3://{BACKUP_S3_BUCKET}/{key}"
    except Exception as e:
        logging.error(f"[DB BACKUP S3 UPLOAD ERROR] {e}")
        return False, str(e)


def _backup_prune_local(backup_dir):
    """Keeps only the newest BACKUP_RETENTION_COUNT local dump files —
    applies even when S3 is the durable destination, since the local
    copy is then just a cache, not the system of record."""
    try:
        files = [os.path.join(backup_dir, f) for f in os.listdir(backup_dir)
                 if f.startswith("connectit_db_backup_") and f.endswith(".sql.gz")]
        files.sort(key=os.path.getmtime, reverse=True)
        for stale in files[BACKUP_RETENTION_COUNT:]:
            try:
                os.remove(stale)
            except Exception:
                pass
    except Exception as e:
        logging.warning(f"[DB BACKUP PRUNE] {e}")


def _backup_alert_admins_on_failure(log_row):
    """Best-effort email to ADMIN_EMAILS on a failed backup, reusing
    the existing SendGrid integration. Silently no-ops if SendGrid
    isn't configured — a failed alert must never crash the cron
    sweep, and a missing SendGrid key shouldn't hide the failure from
    /api/admin/backups either, since that's logged regardless."""
    if not (SENDGRID_AVAILABLE and SENDGRID_API_KEY):
        return
    try:
        sg_client = SendGridAPIClient(SENDGRID_API_KEY)
        for admin_email in ADMIN_EMAILS:
            message = Mail(
                from_email=(CONNECTIT_EMAIL, "Connect It"),
                to_emails=admin_email,
                subject="Connect It — database backup failed",
                html_content=(
                    f"<p>The database backup starting at {log_row.started_at} failed.</p>"
                    f"<p>Error: {xml_escape((log_row.error_message or 'unknown')[:1000])}</p>"
                    f"<p>Check /api/admin/backups in the admin panel for the full log.</p>"
                ),
            )
            sg_client.send(message)
    except Exception as e:
        logging.warning(f"[DB BACKUP ALERT] could not notify admins: {e}")


def _run_database_backup(triggered_by="cron"):
    """Orchestrates one backup attempt end-to-end and returns the
    DatabaseBackupLog row. Never raises — every failure path is caught
    and logged so a bad backup run can't take the whole cron sweep (or
    the calling request) down with it."""
    log_row = DatabaseBackupLog(triggered_by=triggered_by, status="running")
    db.session.add(log_row)
    db.session.commit()

    try:
        backup_dir = _backup_local_dir()
        filename = f"connectit_db_backup_{datetime.utcnow().strftime('%Y%m%d_%H%M%S')}.sql.gz"
        local_path = os.path.join(backup_dir, filename)

        ok = False
        method = None
        error = None

        conn_info = _backup_parse_mysql_uri(app.config.get("SQLALCHEMY_DATABASE_URI", ""))
        if conn_info and conn_info["host"] and conn_info["password"]:
            ok, error = _backup_dump_mysql(conn_info, local_path)
            method = "mysqldump"

        if not ok:
            fallback_ok, fallback_error = _backup_dump_sqlalchemy_fallback(local_path)
            if fallback_ok:
                ok, error = True, None
                method = "sqlalchemy_fallback"
            elif error is None:
                error = fallback_error

        if not ok:
            log_row.status = "failed"
            log_row.method = method
            log_row.error_message = (error or "Unknown backup failure.")[:2000]
            log_row.finished_at = datetime.utcnow()
            db.session.commit()
            _backup_alert_admins_on_failure(log_row)
            return log_row

        size_bytes = os.path.getsize(local_path) if os.path.exists(local_path) else None
        destination = "local"
        location = local_path

        if BACKUP_S3_BUCKET and BACKUP_S3_ACCESS_KEY_ID and BACKUP_S3_SECRET_ACCESS_KEY:
            s3_ok, s3_result = _backup_upload_to_s3(local_path, filename)
            if s3_ok:
                destination = "s3"
                location = s3_result
            # A failed S3 upload still leaves a real local backup in
            # place — that's logged as-is rather than treated as an
            # overall failure, since the data is genuinely safe either way.

        _backup_prune_local(backup_dir)

        log_row.status = "success"
        log_row.method = method
        log_row.destination = destination
        log_row.location = location
        log_row.size_bytes = size_bytes
        log_row.finished_at = datetime.utcnow()
        db.session.commit()
        return log_row
    except Exception as e:
        db.session.rollback()
        logging.error(f"[DB BACKUP] unexpected error: {e}")
        try:
            log_row.status = "failed"
            log_row.error_message = str(e)[:2000]
            log_row.finished_at = datetime.utcnow()
            db.session.commit()
            _backup_alert_admins_on_failure(log_row)
        except Exception:
            db.session.rollback()
        return log_row


@app.route("/api/cron/db-backup", methods=["POST"])
@csrf.exempt
def cron_db_backup():
    """System-wide daily backup trigger — point a PythonAnywhere
    Scheduled Task here (see BACKUP_S3_BUCKET comment near the top of
    this file). No login; guarded by CRON_SECRET like every other cron
    endpoint in this file."""
    if not CRON_SECRET or request.headers.get("X-Cron-Secret") != CRON_SECRET:
        return jsonify({"error": "Forbidden."}), 403
    log_row = _run_database_backup(triggered_by="cron")
    return jsonify(log_row.to_dict()), (200 if log_row.status == "success" else 500)


@app.route("/api/cron/key-rotation-check", methods=["POST"])
@csrf.exempt
def cron_key_rotation_check():
    """System-wide sweep for BYOK credentials due for rotation (SOC 2
    CC6 gap fix). Point a PythonAnywhere Scheduled Task here, e.g.
    weekly, same X-Cron-Secret pattern as every other cron endpoint.
    Notifies each owner at most once per KEY_ROTATION_REMINDER_COOLDOWN_DAYS
    via the existing in-app Notification system, so re-running this
    daily doesn't spam anyone — and the reminder naturally stops firing
    the moment the user actually re-saves the key, since that resets
    updated_at (and therefore age_days) to zero."""
    if not CRON_SECRET or request.headers.get("X-Cron-Secret") != CRON_SECRET:
        return jsonify({"error": "Forbidden."}), 403
    cutoff_age = datetime.utcnow() - timedelta(days=KEY_ROTATION_REMINDER_DAYS)
    cooldown_cutoff = datetime.utcnow() - timedelta(days=KEY_ROTATION_REMINDER_COOLDOWN_DAYS)
    rows = (UserIntegration.query
            .filter(UserIntegration.active == True)
            .filter(UserIntegration.updated_at <= cutoff_age)
            .filter(db.or_(UserIntegration.last_rotation_reminder_at.is_(None),
                            UserIntegration.last_rotation_reminder_at <= cooldown_cutoff))
            .all())
    notified = 0
    for row in rows:
        try:
            age_days = (datetime.utcnow() - row.updated_at).days
            notify_user(
                row.user_id, "integrations", f"{row.provider} key is due for rotation",
                body=f"Your saved {row.provider} credentials are {age_days} days old. "
                     f"Consider rotating them under Integrations for better security hygiene.",
                link="/api/integrations/keys",
            )
            row.last_rotation_reminder_at = datetime.utcnow()
            notified += 1
        except Exception as e:
            logging.warning(f"[KEY ROTATION CRON] could not notify user={row.user_id} provider={row.provider}: {e}")
    db.session.commit()
    logging.info(f"[CRON KEY ROTATION] {len(rows)} due, notified {notified}")
    return jsonify({"ok": True, "due": len(rows), "notified": notified}), 200


