@app.route("/api/admin/backups/<int:backup_id>/download", methods=["GET"])
def admin_db_backup_download(backup_id):
    """Lets an admin retrieve a specific backup file directly — for a
    local-destination backup this streams the gzip; for an S3-destination
    backup it hands back the s3:// location (the admin's own AWS console
    or CLI, using their configured BACKUP_S3_* credentials, is the
    intended way to actually pull that one down)."""
    admin_user, err = _require_admin()
    if err: return err
    row = DatabaseBackupLog.query.get(backup_id)
    if not row or row.status != "success":
        return jsonify({"error": "Backup not found."}), 404
    if row.destination == "local":
        if not row.location or not os.path.exists(row.location):
            return jsonify({"error": "Local backup file no longer exists (it may have been pruned)."}), 404
        return send_file(row.location, as_attachment=True, download_name=os.path.basename(row.location))
    return jsonify({"ok": True, "destination": "s3", "location": row.location,
                     "note": "Download this directly from your S3 bucket using your BACKUP_S3_* credentials."}), 200


