@app.route("/api/trust-center", methods=["GET"])
def trust_center_public():
    """Public, no login required — the honest external-facing summary:
    aggregate readiness percentages and category-level status only,
    never the individual control checklist (that level of detail is an
    internal roadmap of exactly what isn't done yet, which is useful to
    an attacker and not to a prospective customer). A certificate_ref
    only ever appears here if an admin has actually recorded one — this
    endpoint has no way to independently verify it and does not claim
    to."""
    settings = ComplianceSettings.query.first()
    soc2 = _compliance_readiness("soc2")
    iso = _compliance_readiness("iso27001")
    categories = {}
    for row in ComplianceControl.query.all():
        key = f"{row.framework}:{row.category}"
        bucket = categories.setdefault(key, {"framework": row.framework, "category": row.category, "statuses": []})
        bucket["statuses"].append(row.status)
    category_summary = []
    for bucket in categories.values():
        statuses = bucket["statuses"]
        if all(s == "implemented" for s in statuses):
            overall = "implemented"
        elif any(s in ("implemented", "in_progress") for s in statuses):
            overall = "in_progress"
        else:
            overall = "not_started"
        category_summary.append({"framework": bucket["framework"], "category": bucket["category"], "status": overall})
    return jsonify({
        "summary": (settings.trust_page_summary if settings else None) or
                   "Connect It is actively building its security and compliance program toward SOC 2 Type II and ISO 27001 readiness.",
        "security_contact_email": settings.security_contact_email if settings else None,
        "soc2": {"percent_ready": soc2["percent_ready"], "certificate_ref": settings.soc2_certificate_ref if settings else None},
        "iso27001": {"percent_ready": iso["percent_ready"], "certificate_ref": settings.iso27001_certificate_ref if settings else None},
        "category_summary": category_summary,
    }), 200


