def admin_firewall_add_blocked_ip():
    admin_user, err = _require_admin()
    if err:
        return err
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    data = request.get_json(silent=True) or {}
    ip_address = (data.get("ip_address") or "").strip()
    reason     = (data.get("reason") or "").strip() or None
    if not ip_address:
        return jsonify({"error": "ip_address is required."}), 400

    try:
        existing = BlockedIp.query.filter_by(ip_address=ip_address).first()
        if existing:
            existing.active = True
            existing.reason = reason or existing.reason
        else:
            db.session.add(BlockedIp(
                ip_address=ip_address, reason=reason,
                active=True, blocked_by_id=admin_user.id,
            ))
        db.session.commit()
    except Exception as e:
        db.session.rollback(); logging.error(f"[FIREWALL BLOCK IP] {e}")
        return jsonify({"error": "Could not block that IP."}), 500

    _refresh_blocked_ips_cache()
    return jsonify({"message": f"{ip_address} is now blocked."}), 200


