@app.route("/api/partnership/apply", methods=["POST"])
@csrf.exempt
def partnership_apply():
    """Public — no login required. Rate-limited per IP since it's an
    unauthenticated form anyone on the internet can hit."""
    if _rate_limited(f"partner:ip:{_client_ip()}", max_attempts=5, window_seconds=3600):
        return jsonify({"error": "Too many applications submitted from this network. Please try again later."}), 429

    data = request.get_json(silent=True) or {}
    applicant_type = (data.get("applicant_type") or "individual").strip().lower()
    if applicant_type not in ("individual", "company"):
        applicant_type = "individual"
    contact_name = (data.get("contact_name") or "").strip()
    email        = (data.get("email") or "").strip().lower()

    if not contact_name or not email:
        return jsonify({"error": "contact_name and email are required."}), 400
    if "@" not in email or "." not in email:
        return jsonify({"error": "Please enter a valid email address."}), 400

    try:
        app_row = PartnershipApplication(
            applicant_type   = applicant_type,
            contact_name     = contact_name,
            company_name     = (data.get("company_name") or "").strip() or None,
            email            = email,
            phone            = (data.get("phone") or "").strip() or None,
            address          = (data.get("address") or "").strip() or None,
            city             = (data.get("city") or "").strip() or None,
            country          = (data.get("country") or "").strip() or None,
            website          = (data.get("website") or "").strip() or None,
            vision           = (data.get("vision") or "").strip() or None,
            mission          = (data.get("mission") or "").strip() or None,
            contributions    = (data.get("contributions") or "").strip() or None,
            assets_pledged   = (data.get("assets_pledged") or "").strip() or None,
            additional_notes = (data.get("additional_notes") or "").strip() or None,
            status           = "pending",
        )
        db.session.add(app_row)
        db.session.commit()
    except Exception as e:
        db.session.rollback(); logging.error(f"[PARTNERSHIP APPLY] {e}")
        return jsonify({"error": "Could not submit your application. Please try again."}), 500

    return jsonify({
        "message": "Thank you — your partnership application has been received. Our team will review it and reach out to you.",
        "application_id": app_row.id,
    }), 201


