# ════════════════════════════════════════════════════════════
# STAGE 152: GLOBAL LEGAL ENTITY VERIFICATION (GLEIF) — ROUTES
# ════════════════════════════════════════════════════════════

GLEIF_LEI_RECORDS = "https://api.gleif.org/api/v1/lei-records"

def _gleif_simplify(record):
    """Pulls out the fields a business user actually needs from GLEIF's
    JSON:API response, defensively (.get() everywhere) since not every
    LEI record populates every field."""
    attrs   = record.get("attributes", {}) or {}
    entity  = attrs.get("entity", {}) or {}
    reg     = attrs.get("registration", {}) or {}
    legal_name = (entity.get("legalName") or {}).get("name")
    legal_addr = entity.get("legalAddress") or {}
    hq_addr    = entity.get("headquartersAddress") or {}
    legal_form = (entity.get("legalForm") or {}).get("id")
    return {
        "lei": attrs.get("lei"),
        "legal_name": legal_name,
        "entity_status": entity.get("status"),          # ACTIVE | INACTIVE
        "registration_status": reg.get("status"),        # ISSUED | LAPSED | ...
        "legal_form_code": legal_form,
        "jurisdiction": entity.get("jurisdiction"),
        "legal_address": {
            "country": legal_addr.get("country"), "city": legal_addr.get("city"),
            "region": legal_addr.get("region"), "postal_code": legal_addr.get("postalCode"),
        },
        "headquarters_address": {
            "country": hq_addr.get("country"), "city": hq_addr.get("city"),
        },
        "initial_registration_date": reg.get("initialRegistrationDate"),
        "last_update_date": reg.get("lastUpdateDate"),
        "next_renewal_date": reg.get("nextRenewalDate"),
        "managing_lou": reg.get("managingLou"),
    }


# ════════════════════════════════════════════════════════════
# STAGE 175: ZIMRA FISCALISATION (Virtual Fiscal Device / FDMS)
# All VAT-registered operators in Zimbabwe are legally required to
# fiscalise sales through ZIMRA's Fiscalisation Data Management System
# (SI 104 of 2010; Section 90 of the Income Tax Act). ZIMRA offers a
# "Virtual Fiscalisation" path — a direct software API interface — as an
# alternative to a physical fiscal hardware device, which is exactly the
# shape of a server-based platform like this one.
#
# Real references (fetched, not guessed):
#   - Onboarding process: https://www.zimra.co.zw/domestic-taxes/corporate/fiscalisation-explained
#   - Full Gateway API spec (registerDevice, getConfig, openDay,
#     submitReceipt, closeDay, etc.): ZIMRA's own "Fiscal Device Gateway
#     API v7.2" document, downloadable from
#     https://www.zimra.co.zw/downloads/category/9-domestic-taxes
#   - Verification portal (buyers/auditors can check any fiscalised
#     invoice): https://fdms.zimra.co.zw
#
# We use the published `zimra` PyPI package (MIT licensed) for the actual
# device registration (CSR + certificate issuance) and receipt signing
# (RSA-2048/SHA-256 per the spec) rather than reimplementing that
# cryptography in-house — see the ZIMRA_AVAILABLE import above for why.
# A business gets its own device_id + activation_key directly from ZIMRA
# (self-service portal or a ZIMRA office) — this is a BYOK-style
# integration, same as Paystack/Flutterwave/etc: we never fabricate or
# guess these credentials, the taxpayer supplies their own real ones.
# ════════════════════════════════════════════════════════════
class ZimraFiscalDevice(db.Model):
    __tablename__       = "zimra_fiscal_devices"
    id                  = db.Column(db.Integer, primary_key=True)
    user_id             = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, unique=True, index=True)
    device_id           = db.Column(db.String(40), nullable=False)
    serial_no           = db.Column(db.String(80), nullable=False)
    model_name           = db.Column(db.String(60), nullable=False, default="Server")
    model_version         = db.Column(db.String(20), nullable=False, default="v1")
    is_production        = db.Column(db.Boolean, nullable=False, default=False)  # False = ZIMRA test env
    # Encrypted blob: {"activation_key", "certificate_pem", "private_key_pem"}
    # — the activation key is only needed once at registration time but we
    # keep it for cert renewal; the cert+key are what sign every receipt.
    credentials_encrypted = db.Column(db.Text, nullable=True)
    registered_at        = db.Column(db.DateTime, nullable=True)
    # Cached from getConfig() — taxpayer name/TIN/VAT number, branch
    # address, applicable tax table, cert expiry, qrUrl. Real ZIMRA data,
    # refreshed on demand, never invented client-side.
    config_json           = db.Column(db.Text, nullable=True)
    config_fetched_at      = db.Column(db.DateTime, nullable=True)
    # FDMS is a stateful system — WE are responsible for tracking these
    # (per the zimra library's own README warning), so they live here,
    # not recomputed from guesses.
    fiscal_day_no          = db.Column(db.Integer, nullable=False, default=0)
    fiscal_day_status       = db.Column(db.String(30), nullable=False, default="FiscalDayClosed")
    fiscal_day_opened_at    = db.Column(db.DateTime, nullable=True)
    last_receipt_counter    = db.Column(db.Integer, nullable=False, default=0)   # resets each fiscal day
    last_receipt_global_no  = db.Column(db.Integer, nullable=False, default=0)   # never resets
    created_at              = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        config = {}
        if self.config_json:
            try: config = json.loads(self.config_json)
            except Exception: config = {}
        return {
            "device_id": self.device_id, "serial_no": self.serial_no,
            "model_name": self.model_name, "model_version": self.model_version,
            "is_production": self.is_production,
            "registered": bool(self.registered_at),
            "registered_at": self.registered_at.isoformat() if self.registered_at else None,
            "config": config,
            "config_fetched_at": self.config_fetched_at.isoformat() if self.config_fetched_at else None,
            "fiscal_day_no": self.fiscal_day_no, "fiscal_day_status": self.fiscal_day_status,
            "last_receipt_counter": self.last_receipt_counter,
            "last_receipt_global_no": self.last_receipt_global_no,
        }


# NEW: per-invoice fiscalisation record — the audit trail that says "this
# ERP invoice was actually submitted to ZIMRA and accepted", separate from
# the invoice itself so an invoice can exist (draft/sent) before it's
# fiscalised, and so we never overwrite ZIMRA's own response data.
class ZimraFiscalReceipt(db.Model):
    __tablename__     = "zimra_fiscal_receipts"
    id                = db.Column(db.Integer, primary_key=True)
    user_id           = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    invoice_id        = db.Column(db.Integer, db.ForeignKey("erp_invoices.id"), nullable=False, index=True)
    fiscal_day_no     = db.Column(db.Integer, nullable=False)
    receipt_counter   = db.Column(db.Integer, nullable=False)
    receipt_global_no = db.Column(db.Integer, nullable=False)
    receipt_type      = db.Column(db.String(20), nullable=False, default="FISCALINVOICE")
    tax_percent        = db.Column(db.Float, nullable=True)   # dominant/only tax rate used
    tax_amount          = db.Column(db.Float, nullable=True)
    total_amount         = db.Column(db.Float, nullable=True)
    currency             = db.Column(db.String(8), nullable=False, default="USD")
    zimra_receipt_id      = db.Column(db.String(60), nullable=True)   # ZIMRA's own receiptID
    server_signature_json = db.Column(db.Text, nullable=True)         # ZIMRA's serverSignature, verbatim
    qr_code_url            = db.Column(db.String(500), nullable=True)  # printable/scannable, from ZIMRA
    created_at              = db.Column(db.DateTime, default=datetime.utcnow)
    # STAGE 176: the real payment method/moneyTypeCode actually reported to
    # ZIMRA for this receipt (audit trail — separate from whatever the
    # invoice's payment_method is later changed to).
    payment_method          = db.Column(db.String(40), nullable=True)
    money_type_code         = db.Column(db.Integer, nullable=True)

    def to_dict(self):
        return {
            "id": self.id, "invoice_id": self.invoice_id, "fiscal_day_no": self.fiscal_day_no,
            "receipt_counter": self.receipt_counter, "receipt_global_no": self.receipt_global_no,
            "receipt_type": self.receipt_type, "tax_percent": self.tax_percent,
            "tax_amount": self.tax_amount, "total_amount": self.total_amount, "currency": self.currency,
            "zimra_receipt_id": self.zimra_receipt_id, "qr_code_url": self.qr_code_url,
            "payment_method": self.payment_method, "money_type_code": self.money_type_code,
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }


def _zimra_device_client(row: "ZimraFiscalDevice"):
    """Rehydrates a live zimra.Device client from a DB row: decrypts the
    stored cert+key, writes them to short-lived temp files (never left on
    disk longer than the request), and returns (device, tmpdir) — caller
    must clean up tmpdir."""
    creds = decrypt_secret_blob(row.credentials_encrypted)
    cert_pem = creds.get("certificate_pem")
    key_pem  = creds.get("private_key_pem")
    if not cert_pem or not key_pem:
        raise ValueError("This device hasn't completed registration yet (no certificate on file).")
    tmpdir = tempfile.mkdtemp(prefix="zimra_")
    cert_path = os.path.join(tmpdir, "certificate.crt")
    key_path  = os.path.join(tmpdir, "private_key.key")
    with open(cert_path, "w") as f: f.write(cert_pem)
    with open(key_path, "w") as f: f.write(key_pem)
    device = ZimraDevice(
        device_id=row.device_id, serialNo=row.serial_no, activationKey=creds.get("activation_key", ""),
        cert_path=cert_path, private_key_path=key_path, test_mode=(not row.is_production),
        deviceModelName=row.model_name, deviceModelVersion=row.model_version,
    )
    return device, tmpdir


@app.route("/api/compliance/zimra/register", methods=["POST"])
@csrf.exempt
def zimra_register_device():
    """Registers a real fiscal device with ZIMRA using credentials the
    taxpayer obtained directly from ZIMRA (self-service portal or a ZIMRA
    office) — never generated or guessed here. This calls ZIMRA's live
    API (test or production) to issue a genuine X.509 certificate for
    this device; that certificate is what signs every future receipt."""
    if not ZIMRA_AVAILABLE:
        return jsonify({"error": "The 'zimra' package isn't installed on the server yet. Run: pip install zimra"}), 500
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err

    data = request.get_json(silent=True) or {}
    device_id      = (data.get("device_id") or "").strip()
    activation_key = (data.get("activation_key") or "").strip()
    serial_no      = (data.get("serial_no") or "").strip()
    model_name     = (data.get("model_name") or "Server").strip()[:60]
    model_version  = (data.get("model_version") or "v1").strip()[:20]
    is_production  = bool(data.get("is_production"))

    if not (device_id and activation_key and serial_no):
        return jsonify({"error": "'device_id', 'activation_key', and 'serial_no' (all from ZIMRA) are required."}), 400

    tmpdir = tempfile.mkdtemp(prefix="zimra_reg_")
    try:
        zimra_register_new_device(
            fiscal_device_serial_no=serial_no, device_id=device_id, activation_key=activation_key,
            model_name=model_name, folder_name=tmpdir,
            certificate_filename="certificate", private_key_filename="private_key",
            prod=is_production,
        )
        with open(os.path.join(tmpdir, "certificate.crt")) as f: cert_pem = f.read()
        with open(os.path.join(tmpdir, "private_key.key")) as f: key_pem = f.read()
    except Exception as e:
        logging.error(f"[ZIMRA REGISTER] user_id={user['id']} {e}")
        return jsonify({"error": f"ZIMRA device registration failed: {e}"}), 502
    finally:
        shutil.rmtree(tmpdir, ignore_errors=True)

    encrypted = encrypt_secret_blob({
        "activation_key": activation_key, "certificate_pem": cert_pem, "private_key_pem": key_pem,
    })
    row = ZimraFiscalDevice.query.filter_by(user_id=user["id"]).first()
    if not row:
        row = ZimraFiscalDevice(user_id=user["id"])
        db.session.add(row)
    row.device_id = device_id; row.serial_no = serial_no
    row.model_name = model_name; row.model_version = model_version
    row.is_production = is_production
    row.credentials_encrypted = encrypted
    row.registered_at = datetime.utcnow()
    db.session.commit()

    logging.info(f"[ZIMRA REGISTER] user_id={user['id']} device_id={device_id} production={is_production} — certificate issued")
    return jsonify({"device": row.to_dict(), "note": "Certificate issued and stored. Next: fetch config, then open a fiscal day."}), 200


@app.route("/api/compliance/zimra/config", methods=["GET"])
def zimra_get_config():
    """Refreshes and caches this business's real taxpayer/branch/tax-table
    data straight from ZIMRA (getConfig)."""
    if not ZIMRA_AVAILABLE:
        return jsonify({"error": "The 'zimra' package isn't installed on the server yet."}), 500
    user, err = _erp_user_or_401()
    if err: return err
    row = ZimraFiscalDevice.query.filter_by(user_id=user["id"]).first()
    if not row or not row.registered_at:
        return jsonify({"error": "Register a fiscal device first."}), 400

    tmpdir = None
    try:
        device, tmpdir = _zimra_device_client(row)
        config = device.getConfig()
    except Exception as e:
        logging.error(f"[ZIMRA CONFIG] user_id={user['id']} {e}")
        return jsonify({"error": f"Could not fetch config from ZIMRA: {e}"}), 502
    finally:
        if tmpdir: shutil.rmtree(tmpdir, ignore_errors=True)

    row.config_json = json.dumps(config)
    row.config_fetched_at = datetime.utcnow()
    db.session.commit()
    return jsonify({"device": row.to_dict()}), 200


@app.route("/api/compliance/zimra/open-day", methods=["POST"])
@csrf.exempt
def zimra_open_day():
    """Opens the next fiscal day. We track fiscal_day_no ourselves (FDMS
    is stateful) and always increment from our own last-known value, so
    a business can't accidentally reuse or skip a day number."""
    if not ZIMRA_AVAILABLE:
        return jsonify({"error": "The 'zimra' package isn't installed on the server yet."}), 500
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    row = ZimraFiscalDevice.query.filter_by(user_id=user["id"]).first()
    if not row or not row.registered_at:
        return jsonify({"error": "Register a fiscal device first."}), 400
    if row.fiscal_day_status == "FiscalDayOpened":
        return jsonify({"error": "A fiscal day is already open. Close it before opening a new one."}), 400

    next_day_no = row.fiscal_day_no + 1
    tmpdir = None
    try:
        device, tmpdir = _zimra_device_client(row)
        result = device.openDay(fiscalDayNo=next_day_no)
    except Exception as e:
        logging.error(f"[ZIMRA OPEN DAY] user_id={user['id']} {e}")
        return jsonify({"error": f"Could not open fiscal day with ZIMRA: {e}"}), 502
    finally:
        if tmpdir: shutil.rmtree(tmpdir, ignore_errors=True)

    if isinstance(result, dict) and result.get("error"):
        return jsonify({"error": result["error"]}), 400

    row.fiscal_day_no = next_day_no
    row.fiscal_day_status = "FiscalDayOpened"
    row.fiscal_day_opened_at = datetime.utcnow()
    row.last_receipt_counter = 0
    db.session.commit()
    logging.info(f"[ZIMRA OPEN DAY] user_id={user['id']} fiscal_day_no={next_day_no}")
    return jsonify({"device": row.to_dict(), "zimra_response": result}), 200


@app.route("/api/compliance/zimra/fiscalize/<int:invoice_id>", methods=["POST"])
@csrf.exempt
def zimra_fiscalize_invoice(invoice_id):
    """Submits a real ERP invoice to ZIMRA as a fiscal tax invoice —
    signed with this business's actual device certificate, returned with
    ZIMRA's own server signature and a scannable QR code. Requires an
    open fiscal day. This is the core of the feature: an invoice you
    already created in Connect It's ERP becomes a legally fiscalised
    document, no separate POS/device needed."""
    if not ZIMRA_AVAILABLE:
        return jsonify({"error": "The 'zimra' package isn't installed on the server yet."}), 500
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err

    row = ZimraFiscalDevice.query.filter_by(user_id=user["id"]).first()
    if not row or not row.registered_at:
        return jsonify({"error": "Register a fiscal device first."}), 400
    if row.fiscal_day_status != "FiscalDayOpened":
        return jsonify({"error": "Open a fiscal day before fiscalising invoices."}), 400

    invoice = ErpInvoice.query.filter_by(id=invoice_id, owner_user_id=user["id"]).first()
    if not invoice:
        return jsonify({"error": "Invoice not found."}), 404
    if ZimraFiscalReceipt.query.filter_by(invoice_id=invoice_id).first():
        return jsonify({"error": "This invoice has already been fiscalised."}), 400

    # STAGE 176: use the invoice's REAL payment method instead of assuming
    # cash. Only "cash" (0) and "card" (1) have a documented moneyTypeCode
    # in the `zimra` library's own README — every other method (EcoCash/
    # mobile money, bank transfer, etc.) isn't yet published by ZIMRA for
    # this library, so we refuse to guess rather than silently mis-report
    # a legally fiscalised receipt. An explicit override can be passed in
    # the request body for this one submission without changing the
    # invoice's stored payment_method.
    ZIMRA_MONEY_TYPE_CODES = {"cash": 0, "card": 1}
    body = request.get_json(silent=True) or {}
    payment_method = (body.get("payment_method") or invoice.payment_method or "cash").strip().lower()
    if payment_method not in ZIMRA_MONEY_TYPE_CODES:
        return jsonify({
            "error": f"Payment method '{payment_method}' doesn't have a ZIMRA-documented moneyTypeCode yet "
                     f"(only 'cash' and 'card' are confirmed). Set the invoice's payment method to one of "
                     f"those, or pass {{\"payment_method\": \"cash\"|\"card\"}} in this request, to fiscalise it — "
                     f"we won't guess a code ZIMRA hasn't published.",
            "supported_payment_methods": list(ZIMRA_MONEY_TYPE_CODES.keys()),
        }), 400
    money_type_code = ZIMRA_MONEY_TYPE_CODES[payment_method]

    items = ErpInvoiceItem.query.filter_by(invoice_id=invoice_id).all()
    if not items:
        return jsonify({"error": "This invoice has no line items to fiscalise."}), 400

    tax_percent = invoice.tax_rate or 0
    receipt_lines = [{
        "item_name": (it.description or "Item")[:200], "tax_percent": tax_percent,
        "quantity": it.quantity or 1, "unit_price": it.unit_price or 0,
    } for it in items]

    next_counter = row.last_receipt_counter + 1
    next_global  = row.last_receipt_global_no + 1
    receipt_data = {
        "receiptType": "FISCALINVOICE", "receiptCurrency": invoice.currency or "USD",
        "receiptCounter": next_counter, "receiptGlobalNo": next_global,
        "invoiceNo": invoice.invoice_number, "receiptDate": datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%S"),
        "receiptLines": receipt_lines,
        "receiptPayments": [{"moneyTypeCode": money_type_code, "paymentAmount": invoice.total or 0}],
    }

    tmpdir = None
    try:
        device, tmpdir = _zimra_device_client(row)
        # Connect It stores unit_price as tax-EXCLUSIVE (subtotal + tax_amount = total),
        # so this uses the tax-exclusive preparer to match how the invoice was actually priced.
        prepared = device.prepareReceiptTaxExclusive(receipt_data)
        result = device.submitReceipt(prepared)
    except Exception as e:
        logging.error(f"[ZIMRA FISCALIZE] user_id={user['id']} invoice_id={invoice_id} {e}")
        return jsonify({"error": f"ZIMRA rejected or could not process this receipt: {e}"}), 502
    finally:
        if tmpdir: shutil.rmtree(tmpdir, ignore_errors=True)

    if isinstance(result, dict) and (result.get("error") or 400 in result or "errors" in result):
        return jsonify({"error": "ZIMRA rejected this receipt.", "zimra_response": result}), 400

    server_sig = (result or {}).get("serverSignature") or {}
    qr_url = None
    try:
        qr_url = device.generate_qr_code(
            signature=server_sig.get("signature"), receipt_global_no=next_global,
            receipt_date=datetime.utcnow().date(),
        )
    except Exception as e:
        logging.warning(f"[ZIMRA QR] could not generate QR string: {e}")

    receipt = ZimraFiscalReceipt(
        user_id=user["id"], invoice_id=invoice_id, fiscal_day_no=row.fiscal_day_no,
        receipt_counter=next_counter, receipt_global_no=next_global, receipt_type="FISCALINVOICE",
        tax_percent=tax_percent, tax_amount=invoice.tax_amount, total_amount=invoice.total,
        currency=invoice.currency or "USD", zimra_receipt_id=str((result or {}).get("receiptID") or ""),
        server_signature_json=json.dumps(server_sig), qr_code_url=qr_url,
        payment_method=payment_method, money_type_code=money_type_code,
    )
    db.session.add(receipt)
    row.last_receipt_counter = next_counter
    row.last_receipt_global_no = next_global
    db.session.commit()

    logging.info(f"[ZIMRA FISCALIZE] user_id={user['id']} invoice_id={invoice_id} receiptID={receipt.zimra_receipt_id}")
    return jsonify({"receipt": receipt.to_dict(), "zimra_response": result}), 200


@app.route("/api/compliance/zimra/close-day", methods=["POST"])
@csrf.exempt
def zimra_close_day():
    """Closes the currently open fiscal day, submitting real aggregated
    counters (built from every receipt actually fiscalised today via
    zimra_fiscalize_invoice above — never invented totals)."""
    if not ZIMRA_AVAILABLE:
        return jsonify({"error": "The 'zimra' package isn't installed on the server yet."}), 500
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    row = ZimraFiscalDevice.query.filter_by(user_id=user["id"]).first()
    if not row or row.fiscal_day_status != "FiscalDayOpened":
        return jsonify({"error": "No fiscal day is currently open."}), 400

    todays_receipts = ZimraFiscalReceipt.query.filter_by(
        user_id=user["id"], fiscal_day_no=row.fiscal_day_no
    ).all()

    # Aggregate real totals by (currency, tax_percent) — no placeholders.
    by_tax = {}
    by_money_type = {}
    for r in todays_receipts:
        key = (r.currency, r.tax_percent or 0)
        by_tax.setdefault(key, {"sale": 0.0, "tax": 0.0})
        by_tax[key]["sale"] += (r.total_amount or 0) - (r.tax_amount or 0)
        by_tax[key]["tax"] += (r.tax_amount or 0)
        by_money_type.setdefault(r.currency, 0.0)
        by_money_type[r.currency] += (r.total_amount or 0)

    fiscal_day_counters = []
    for (currency, tax_percent), vals in by_tax.items():
        fiscal_day_counters.append({
            "fiscalCounterType": "SaleByTax", "fiscalCounterCurrency": currency,
            "fiscalCounterTaxPercent": tax_percent, "fiscalCounterValue": round(vals["sale"], 2),
        })
        if tax_percent:
            fiscal_day_counters.append({
                "fiscalCounterType": "SaleTaxByTax", "fiscalCounterCurrency": currency,
                "fiscalCounterTaxPercent": tax_percent, "fiscalCounterValue": round(vals["tax"], 2),
            })
    for currency, total in by_money_type.items():
        fiscal_day_counters.append({
            "fiscalCounterType": "BalanceByMoneyType", "fiscalCounterCurrency": currency,
            "fiscalCounterMoneyType": 0, "fiscalCounterValue": round(total, 2),
        })

    tmpdir = None
    try:
        device, tmpdir = _zimra_device_client(row)
        result = device.closeDay(
            fiscalDayNo=row.fiscal_day_no,
            fiscalDayDate=datetime.utcnow().strftime("%Y-%m-%d"),
            lastReceiptCounterValue=(row.last_receipt_counter or None),
            fiscalDayCounters=fiscal_day_counters,
        )
    except Exception as e:
        logging.error(f"[ZIMRA CLOSE DAY] user_id={user['id']} {e}")
        return jsonify({"error": f"Could not close fiscal day with ZIMRA: {e}"}), 502
    finally:
        if tmpdir: shutil.rmtree(tmpdir, ignore_errors=True)

    if isinstance(result, dict) and result.get("error"):
        return jsonify({"error": result["error"]}), 400

    row.fiscal_day_status = "FiscalDayClosed"
    db.session.commit()
    logging.info(f"[ZIMRA CLOSE DAY] user_id={user['id']} fiscal_day_no={row.fiscal_day_no} receipts={len(todays_receipts)}")
    return jsonify({"device": row.to_dict(), "receipts_today": len(todays_receipts), "zimra_response": result}), 200


@app.route("/api/compliance/zimra/status", methods=["GET"])
def zimra_status():
    """Current device + fiscal day state, plus today's fiscalised receipts."""
    user, err = _erp_user_or_401()
    if err: return err
    row = ZimraFiscalDevice.query.filter_by(user_id=user["id"]).first()
    if not row:
        return jsonify({"device": None}), 200
    receipts = ZimraFiscalReceipt.query.filter_by(
        user_id=user["id"], fiscal_day_no=row.fiscal_day_no
    ).order_by(ZimraFiscalReceipt.receipt_counter.asc()).all()
    return jsonify({"device": row.to_dict(), "receipts_today": [r.to_dict() for r in receipts]}), 200


@app.route("/api/compliance/gleif-verify", methods=["POST"])
@csrf.exempt
def gleif_verify():
    """Verifies a business against GLEIF's real, global Legal Entity
    Identifier database. Accepts a lei code directly, OR a legal_name
    (optionally narrowed by a country ISO-2 code). Public GLEIF API,
    free, no key required."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401

    data       = request.get_json(silent=True) or {}
    lei        = (data.get("lei") or "").strip().upper()
    legal_name = (data.get("legal_name") or "").strip()
    country    = (data.get("country") or "").strip().upper()[:2] or None

    if not lei and not legal_name:
        return jsonify({"error": "Provide either an LEI code or a legal_name to search."}), 400

    if _rate_limited(f"gleif:user:{user['id']}", max_attempts=30, window_seconds=60):
        return jsonify({"error": "Too many verification requests. Please wait a moment and try again."}), 429

    params = {"page[size]": 10}
    if lei:
        query_type, query_value = "lei", lei
        params["filter[lei]"] = lei
    else:
        query_type, query_value = "name", legal_name
        params["filter[entity.legalName]"] = legal_name
        if country:
            params["filter[entity.legalAddress.country]"] = country

    results = []
    error = None
    try:
        resp = requests.get(GLEIF_LEI_RECORDS, params=params, timeout=12,
                             headers={"Accept": "application/vnd.api+json"})
        if resp.ok:
            body = resp.json() if resp.text.strip() else {}
            for rec in (body.get("data") or [])[:10]:
                results.append(_gleif_simplify(rec))
        else:
            error = f"GLEIF API returned status {resp.status_code}"
    except Exception as e:
        logging.error(f"[GLEIF VERIFY] {e}")
        error = "Could not reach the GLEIF Global LEI database right now."

    try:
        rec = GleifVerificationCheck(
            user_id=user["id"], query_type=query_type, query_value=query_value[:300],
            country_filter=country, match_count=len(results), results_json=json.dumps(results),
        )
        db.session.add(rec); db.session.commit()
        saved = True
    except Exception as e:
        db.session.rollback(); logging.error(f"[GLEIF VERIFY SAVE] {e}")
        saved = False

    return jsonify({
        "query_type": query_type, "query_value": query_value, "country_filter": country,
        "results": results, "match_count": len(results), "error": error, "saved": saved,
        "coverage_note": "Only entities holding an LEI are found here. A business without an LEI "
                          "simply won't appear \u2014 that's not the same as it being unverified elsewhere.",
    }), 200


