# ════════════════════════════════════════════════════════════
# STAGE 153: MULTI-CURRENCY FX ENGINE — ROUTES
# ════════════════════════════════════════════════════════════

FRANKFURTER_LATEST = "https://api.frankfurter.dev/v1/latest"

@app.route("/api/finance/fx-rates", methods=["POST"])
@csrf.exempt
def fx_rates_lookup():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    data    = request.get_json(silent=True) or {}
    base    = (data.get("base") or "USD").strip().upper()[:5]
    symbols = (data.get("symbols") or "").strip().upper()
    try:
        amount = float(data.get("amount") or 1)
    except (TypeError, ValueError):
        amount = 1.0

    params = {"base": base, "amount": amount}
    if symbols:
        params["symbols"] = symbols

    rates, rate_date, error = {}, None, None
    try:
        resp = requests.get(FRANKFURTER_LATEST, params=params, timeout=10)
        if resp.ok:
            body = resp.json() if resp.text.strip() else {}
            rates = body.get("rates", {})
            rate_date = body.get("date")
        else:
            error = f"Frankfurter API returned status {resp.status_code}"
    except Exception as e:
        logging.error(f"[FX RATES] {e}")
        error = "Could not reach the Frankfurter exchange-rate service right now."

    try:
        rec = FxRateQuery(user_id=user["id"], base_currency=base, symbols=symbols or None,
                           amount=amount, rate_date=rate_date, rates_json=json.dumps(rates))
        db.session.add(rec); db.session.commit()
        saved = True
    except Exception as e:
        db.session.rollback(); logging.error(f"[FX RATES SAVE] {e}")
        saved = False

    return jsonify({
        "base": base, "amount": amount, "date": rate_date, "rates": rates,
        "error": error, "saved": saved,
    }), 200


