@app.route("/api/scheduling/public-holidays", methods=["POST"])
@csrf.exempt
def public_holidays_lookup():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    data    = request.get_json(silent=True) or {}
    country = (data.get("country") or "").strip().upper()[:5]
    try:
        year = int(data.get("year") or datetime.utcnow().year)
    except (TypeError, ValueError):
        year = datetime.utcnow().year
    if not country:
        return jsonify({"error": "country (ISO 3166-1 alpha-2, e.g. US, GB, ZA) is required."}), 400

    holidays, error = [], None
    try:
        resp = requests.get(f"https://date.nager.at/api/v3/PublicHolidays/{year}/{country}", timeout=10)
        if resp.status_code == 200:
            raw = resp.json() if resp.text.strip() else []
            for h in raw:
                holidays.append({
                    "date": h.get("date"), "local_name": h.get("localName"),
                    "name": h.get("name"), "types": h.get("types"),
                    "global": h.get("global"), "counties": h.get("counties"),
                })
        elif resp.status_code == 404:
            error = f"No holiday data available for country code '{country}'."
        else:
            error = f"Nager.Date API returned status {resp.status_code}"
    except Exception as e:
        logging.error(f"[PUBLIC HOLIDAYS] {e}")
        error = "Could not reach the public holidays service right now."

    try:
        rec = HolidayLookup(user_id=user["id"], country_code=country, year=year,
                             holiday_count=len(holidays), holidays_json=json.dumps(holidays))
        db.session.add(rec); db.session.commit()
        saved = True
    except Exception as e:
        db.session.rollback(); logging.error(f"[PUBLIC HOLIDAYS SAVE] {e}")
        saved = False

    return jsonify({
        "country": country, "year": year, "holidays": holidays,
        "holiday_count": len(holidays), "error": error, "saved": saved,
    }), 200


