# ════════════════════════════════════════════════════════════
# STAGE 155: VENDOR / DOMAIN TRUST CHECK — ROUTES
# ════════════════════════════════════════════════════════════

def _rdap_domain_lookup(domain):
    """Uses rdap.org's public bootstrap redirector, which forwards to the
    correct registry's RDAP server for any TLD — one endpoint works
    worldwide instead of needing a per-registry integration."""
    resp = requests.get(f"https://rdap.org/domain/{domain}", timeout=10,
                         headers={"Accept": "application/rdap+json"})
    if not resp.ok:
        return None, f"RDAP lookup returned status {resp.status_code}"
    body = resp.json() if resp.text.strip() else {}
    reg_date = None
    for ev in (body.get("events") or []):
        if ev.get("eventAction") == "registration":
            reg_date = ev.get("eventDate")
            break
    registrar = None
    for ent in (body.get("entities") or []):
        if "registrar" in (ent.get("roles") or []):
            vcard = ent.get("vcardArray") or []
            if len(vcard) > 1:
                for field in vcard[1]:
                    if field and field[0] == "fn":
                        registrar = field[3]
                        break
            registrar = registrar or ent.get("handle")
            break
    return {"registration_date": reg_date, "registrar": registrar}, None


def _crtsh_cert_count(domain):
    """Public Certificate Transparency log search — counts certificates
    issued for this domain in the last 90 days. A burst of brand-new
    certs on a brand-new domain is a classic phishing/lookalike signal."""
    resp = requests.get("https://crt.sh/", params={"q": domain, "output": "json"}, timeout=15)
    if not resp.ok:
        return None
    try:
        rows = resp.json() if resp.text.strip() else []
    except Exception:
        return None
    cutoff = datetime.utcnow() - timedelta(days=90)
    count = 0
    for r in rows:
        try:
            issued = datetime.strptime((r.get("entry_timestamp") or "")[:19], "%Y-%m-%dT%H:%M:%S")
            if issued >= cutoff:
                count += 1
        except Exception:
            continue
    return count


@app.route("/api/compliance/domain-trust-check", methods=["POST"])
@csrf.exempt
def domain_trust_check():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    data   = request.get_json(silent=True) or {}
    domain = (data.get("domain") or "").strip().lower()
    domain = re.sub(r"^https?://", "", domain).split("/")[0]
    if not domain or "." not in domain:
        return jsonify({"error": "Enter a valid domain, e.g. example.com"}), 400

    if _rate_limited(f"domaintrust:user:{user['id']}", max_attempts=20, window_seconds=3600):
        return jsonify({"error": "Too many domain checks. Please wait a moment and try again."}), 429

    rdap_data, rdap_error = None, None
    age_days = None
    try:
        rdap_data, rdap_error = _rdap_domain_lookup(domain)
    except Exception as e:
        logging.error(f"[DOMAIN TRUST RDAP] {e}")
        rdap_error = "Could not reach the RDAP registration lookup right now."

    if rdap_data and rdap_data.get("registration_date"):
        try:
            reg_dt = datetime.strptime(rdap_data["registration_date"][:19], "%Y-%m-%dT%H:%M:%S")
            age_days = (datetime.utcnow() - reg_dt).days
        except Exception:
            pass

    cert_count, cert_error = None, None
    try:
        cert_count = _crtsh_cert_count(domain)
    except Exception as e:
        logging.error(f"[DOMAIN TRUST CRTSH] {e}")
        cert_error = "Could not reach the certificate transparency log right now."

    flags = []
    if age_days is not None and age_days < 90:
        flags.append(f"Domain was registered only {age_days} day(s) ago \u2014 verify independently before paying an invoice or onboarding this vendor.")
    if cert_count is not None and cert_count >= 5:
        flags.append(f"{cert_count} new TLS certificates issued for this domain in the last 90 days \u2014 unusually high churn can indicate a lookalike/phishing setup.")
    if not flags and (age_days is not None or cert_count is not None):
        flags.append("No immediate red flags from registration age or certificate activity.")

    try:
        rec = DomainTrustCheck(
            user_id=user["id"], domain=domain,
            registration_date=(rdap_data or {}).get("registration_date"),
            domain_age_days=age_days, registrar=(rdap_data or {}).get("registrar"),
            cert_count_90d=cert_count, risk_flags_json=json.dumps(flags),
        )
        db.session.add(rec); db.session.commit()
        saved = True
    except Exception as e:
        db.session.rollback(); logging.error(f"[DOMAIN TRUST SAVE] {e}")
        saved = False

    return jsonify({
        "domain": domain, "registration_date": (rdap_data or {}).get("registration_date"),
        "domain_age_days": age_days, "registrar": (rdap_data or {}).get("registrar"),
        "cert_count_90d": cert_count, "risk_flags": flags,
        "rdap_error": rdap_error, "cert_error": cert_error, "saved": saved,
    }), 200


