@app.route("/api/trade/comtrade-lookup", methods=["POST"])
@csrf.exempt
def comtrade_lookup():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    key = get_effective_credential(user["id"], "un_comtrade", "subscription_key", None)
    if not key:
        return jsonify({"error": "Connect your free UN Comtrade subscription key under Integrations first (register at comtradeplus.un.org)."}), 400

    data     = request.get_json(silent=True) or {}
    reporter = (data.get("reporter") or "").strip().upper()
    hs_code  = (data.get("hs_code") or "").strip()
    flow     = (data.get("flow") or "M").strip().upper()[:1]
    flow     = flow if flow in ("M", "X") else "M"
    try:
        period = str(int(data.get("period") or (datetime.utcnow().year - 1)))
    except (TypeError, ValueError):
        period = str(datetime.utcnow().year - 1)

    reporter_code = COMTRADE_COUNTRY_CODES.get(reporter, reporter if reporter.isdigit() else None)
    if not reporter_code or not hs_code:
        return jsonify({"error": "Provide a reporter country (name or UN numeric code) and an HS code."}), 400

    results, error = [], None
    try:
        resp = requests.get(
            "https://comtradeapi.un.org/data/v1/get/C/A/HS",
            params={"reporterCode": reporter_code, "period": period, "cmdCode": hs_code, "flowCode": flow, "partnerCode": 0},
            headers={"Ocp-Apim-Subscription-Key": key}, timeout=20,
        )
        if resp.ok:
            body = resp.json() if resp.text.strip() else {}
            for r in (body.get("data") or [])[:25]:
                results.append({
                    "reporter": r.get("reporterDesc"), "partner": r.get("partnerDesc"),
                    "period": r.get("period"), "flow": r.get("flowDesc"),
                    "hs_code": r.get("cmdCode"), "description": r.get("cmdDesc"),
                    "trade_value_usd": r.get("primaryValue"), "net_weight_kg": r.get("netWgt"),
                })
        else:
            error = f"UN Comtrade API returned status {resp.status_code}"
    except Exception as e:
        logging.error(f"[COMTRADE LOOKUP] {e}")
        error = "Could not reach the UN Comtrade API right now."

    try:
        rec = TradeIntelQuery(user_id=user["id"], reporter_code=reporter_code, hs_code=hs_code[:20],
                               flow=flow, period=period, results_json=json.dumps(results))
        db.session.add(rec); db.session.commit()
        saved = True
    except Exception as e:
        db.session.rollback(); logging.error(f"[COMTRADE LOOKUP SAVE] {e}")
        saved = False

    return jsonify({
        "reporter_code": reporter_code, "hs_code": hs_code, "flow": flow, "period": period,
        "results": results, "error": error, "saved": saved,
    }), 200


# ════════════════════════════════════════════════════════════
# STAGE: PUBLIC LEGAL-RESEARCH LOOKUPS
# Real, public legal databases so users can research statutes/case law
# from inside the app. All are genuine public endpoints — no fabricated
# ones. Each was checked against its own real, documented shape before
# being added, the same way the first two were:
#
# 1. CourtListener (US) — federal & state case law search.
#    Docs: https://www.courtlistener.com/help/api/rest/
#    Public search works unauthenticated but is rate-limited (5/min,
#    50/hour, 125/day). A free account token raises those limits — stored
#    as a BYOK credential, same pattern as every other keyed provider here.
# 2. legislation.gov.uk (UK) — primary & secondary legislation search.
#    Fully public, no API key required, no auth needed.
# 3. EUR-Lex / Cellar (EU) — real SPARQL endpoint over the EU Publications
#    Office's semantic repository. Endpoint:
#    https://publications.europa.eu/webapi/rdf/sparql — open, no key,
#    SPARQL 1.1 over GET, content-negotiated to JSON via the Accept header.
#    Queried with the real "cdm" (Common Data Model) ontology terms the
#    EU Publications Office documents and the `eurlex` R package (the
#    closest thing to a canonical client) uses under the hood — not a
#    guessed schema.
# 4. AustLII (Australia) — no JSON/REST API exists (checked; AustLII only
#    exposes its SINO search engine via a CGI form meant for HTML pages:
#    https://www.austlii.edu.au/cgi-bin/sinosrch.cgi, documented at
#    https://www.austlii.edu.au/techlib/webdev/cgiapi.html). This calls
#    that real, public, no-key CGI endpoint and parses the HTML it
#    returns — an honest scrape of a real free-text search, not an
#    invented API surface.
# 5. Zimbabwe legislation — the Laws.Africa Content API
#    (https://developers.laws.africa), scoped to place code "zw". This is
#    the same open Indigo/Laws.Africa platform that powers ZimLII and the
#    wider African LII network; ZimLII's own terms of use point to "our
#    APIs" for programmatic access. Free for non-commercial/academic use
#    on request, but token-gated (BYOK, provider "lawsafrica") — no
#    unkeyed fallback exists for it.
#
# NOT implemented — checked and deliberately left out rather than faked:
# - India Code (indiacode.nic.in): confirmed to have no public developer
#   API of its own; only third-party paid scraper wrappers exist. Nothing
#   real and free to plug in here yet.
# - "BSUID": not a legal-data source — the only real-world hits for this
#   term are WhatsApp/Zendesk business-scoped user IDs, unrelated to
#   legal research. Left out rather than guessed at.
# - University of Zimbabwe Faculty of Law: checked its site directly —
#   it's a standard course-listing page with no developer API of any kind.
# ════════════════════════════════════════════════════════════

@app.route("/api/legal/us-case-law-search", methods=["POST"])
@csrf.exempt
def legal_us_case_law_search():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401

    data  = request.get_json(silent=True) or {}
    query = (data.get("query") or "").strip()
    if not query:
        return jsonify({"error": "Provide a search query (case name, topic, or citation)."}), 400

    # Optional BYOK token — raises CourtListener's rate limits. Works fine
    # without one for light/occasional use.
    token = get_effective_credential(user["id"], "courtlistener", "api_token", None)
    headers = {"Authorization": f"Token {token}"} if token else {}

    results, error = [], None
    try:
        resp = requests.get(
            "https://www.courtlistener.com/api/rest/v4/search/",
            params={"q": query, "type": "o", "order_by": "score desc"},
            headers=headers, timeout=20,
        )
        if resp.ok:
            body = resp.json() if resp.text.strip() else {}
            for r in (body.get("results") or [])[:20]:
                results.append({
                    "case_name":  r.get("caseName"),
                    "court":      r.get("court"),
                    "date_filed": r.get("dateFiled"),
                    "citation":   (r.get("citation") or [None])[0],
                    "snippet":    r.get("snippet"),
                    "url":        f"https://www.courtlistener.com{r.get('absolute_url')}" if r.get("absolute_url") else None,
                })
        elif resp.status_code == 429:
            error = "CourtListener rate limit hit. Connect a free API token under Integrations for higher limits."
        else:
            error = f"CourtListener API returned status {resp.status_code}"
    except Exception as e:
        logging.error(f"[US CASE LAW SEARCH] {e}")
        error = "Could not reach the CourtListener API right now."

    try:
        rec = LegalLookupQuery(user_id=user["id"], jurisdiction="us_case_law",
                                query_text=query[:500], results_json=json.dumps(results))
        db.session.add(rec); db.session.commit()
        saved = True
    except Exception as e:
        db.session.rollback(); logging.error(f"[US CASE LAW SEARCH SAVE] {e}")
        saved = False

    return jsonify({"query": query, "results": results, "error": error, "saved": saved}), 200


@app.route("/api/legal/ca-case-law-search", methods=["POST"])
@csrf.exempt
def legal_ca_case_law_search():
    """CanLII's public API is metadata-only and does not offer free-text
    search across all databases in one call — you browse a specific
    database (e.g. the Supreme Court, "csc-scc") and can look up one case's
    metadata by its ID within that database. That's the real, documented
    shape (https://github.com/canlii/API_documentation), so that's what
    this implements — no invented "search everything" endpoint."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401

    key = get_effective_credential(user["id"], "canlii", "api_key", None)
    if not key:
        return jsonify({"error": "Connect your free CanLII API key under Integrations first (request one via canlii.org's feedback form)."}), 400

    data        = request.get_json(silent=True) or {}
    database_id = (data.get("database_id") or "csc-scc").strip()  # default: Supreme Court of Canada
    case_id     = (data.get("case_id") or "").strip()
    language    = "fr" if (data.get("language") or "en").strip().lower() == "fr" else "en"

    results, error = [], None
    try:
        if case_id:
            # Look up one specific case's metadata.
            resp = requests.get(
                f"https://api.canlii.org/v1/caseBrowse/{language}/{database_id}/{case_id}/",
                params={"api_key": key}, timeout=20,
            )
            if resp.ok:
                body = resp.json() if resp.text.strip() else {}
                if body:
                    results.append({
                        "title": body.get("title"), "citation": body.get("citation"),
                        "decision_date": body.get("decisionDate"), "docket_number": body.get("docketNumber"),
                        "keywords": body.get("keywords"), "url": body.get("url"),
                    })
            else:
                error = f"CanLII API returned status {resp.status_code}"
        else:
            # Browse recent decisions in the given database.
            resp = requests.get(
                f"https://api.canlii.org/v1/caseBrowse/{language}/{database_id}/",
                params={"api_key": key, "offset": 0, "resultCount": 20}, timeout=20,
            )
            if resp.ok:
                body = resp.json() if resp.text.strip() else {}
                for c in (body.get("cases") or [])[:20]:
                    results.append({
                        "title": c.get("title"), "citation": c.get("citation"),
                        "case_id": (c.get("caseId") or {}).get(language),
                    })
            else:
                error = f"CanLII API returned status {resp.status_code}"
    except Exception as e:
        logging.error(f"[CA CASE LAW SEARCH] {e}")
        error = "Could not reach the CanLII API right now."

    query_label = f"{database_id}/{case_id}" if case_id else f"{database_id} (recent)"
    try:
        rec = LegalLookupQuery(user_id=user["id"], jurisdiction="ca_case_law",
                                query_text=query_label[:500], results_json=json.dumps(results))
        db.session.add(rec); db.session.commit()
        saved = True
    except Exception as e:
        db.session.rollback(); logging.error(f"[CA CASE LAW SEARCH SAVE] {e}")
        saved = False

    return jsonify({"database_id": database_id, "case_id": case_id or None,
                     "results": results, "error": error, "saved": saved}), 200


@app.route("/api/legal/uk-legislation-search", methods=["POST"])
@csrf.exempt
def legal_uk_legislation_search():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401

    data  = request.get_json(silent=True) or {}
    query = (data.get("query") or "").strip()
    if not query:
        return jsonify({"error": "Provide a search query (act name or keyword)."}), 400

    results, error = [], None
    try:
        # legislation.gov.uk's search supports an Atom feed; requesting it as
        # data.feed via the .json-adjacent endpoint keeps parsing simple.
        resp = requests.get(
            "https://www.legislation.gov.uk/search/data.feed",
            params={"text": query}, timeout=20,
        )
        if resp.ok:
            import xml.etree.ElementTree as ET
            ns = {"atom": "http://www.w3.org/2005/Atom"}
            root = ET.fromstring(resp.content)
            for entry in root.findall("atom:entry", ns)[:20]:
                title_el   = entry.find("atom:title", ns)
                link_el    = entry.find("atom:link", ns)
                updated_el = entry.find("atom:updated", ns)
                results.append({
                    "title":   title_el.text if title_el is not None else None,
                    "url":     link_el.attrib.get("href") if link_el is not None else None,
                    "updated": updated_el.text if updated_el is not None else None,
                })
        else:
            error = f"legislation.gov.uk returned status {resp.status_code}"
    except Exception as e:
        logging.error(f"[UK LEGISLATION SEARCH] {e}")
        error = "Could not reach legislation.gov.uk right now."

    try:
        rec = LegalLookupQuery(user_id=user["id"], jurisdiction="uk_legislation",
                                query_text=query[:500], results_json=json.dumps(results))
        db.session.add(rec); db.session.commit()
        saved = True
    except Exception as e:
        db.session.rollback(); logging.error(f"[UK LEGISLATION SEARCH SAVE] {e}")
        saved = False

    return jsonify({"query": query, "results": results, "error": error, "saved": saved}), 200


@app.route("/api/legal/eu-legislation-search", methods=["POST"])
@csrf.exempt
def legal_eu_legislation_search():
    """EUR-Lex / Cellar — real public SPARQL endpoint, no key required.
    Queries the actual CDM ontology (cdm:expression_title / cdm:resource_legal_id_celex)
    over publications.europa.eu, not an invented schema."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401

    data  = request.get_json(silent=True) or {}
    query = (data.get("query") or "").strip()
    if not query:
        return jsonify({"error": "Provide a search query (keyword from an act's title)."}), 400

    # Escape for safe embedding in a SPARQL string literal.
    safe_query = query.replace("\\", "\\\\").replace('"', '\\"')[:200]
    sparql = f"""
PREFIX cdm: <http://publications.europa.eu/ontology/cdm#>
SELECT DISTINCT ?celex ?title ?date WHERE {{
  ?work cdm:resource_legal_id_celex ?celex .
  ?exp cdm:expression_belongs_to_work ?work ;
       cdm:expression_uses_language <http://publications.europa.eu/resource/authority/language/ENG> ;
       cdm:expression_title ?title .
  OPTIONAL {{ ?work cdm:work_date_document ?date }}
  FILTER(CONTAINS(LCASE(STR(?title)), LCASE("{safe_query}")))
}}
LIMIT 20
"""

    results, error = [], None
    try:
        resp = requests.get(
            "https://publications.europa.eu/webapi/rdf/sparql",
            params={"query": sparql, "format": "application/sparql-results+json"},
            headers={"Accept": "application/sparql-results+json"},
            timeout=25,
        )
        if resp.ok:
            body = resp.json() if resp.text.strip() else {}
            bindings = ((body.get("results") or {}).get("bindings")) or []
            for b in bindings[:20]:
                celex = (b.get("celex") or {}).get("value")
                results.append({
                    "celex": celex,
                    "title": (b.get("title") or {}).get("value"),
                    "date":  (b.get("date") or {}).get("value"),
                    "url":   f"https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:{celex}" if celex else None,
                })
        else:
            error = f"EUR-Lex SPARQL endpoint returned status {resp.status_code}"
    except Exception as e:
        logging.error(f"[EU LEGISLATION SEARCH] {e}")
        error = "Could not reach the EUR-Lex SPARQL endpoint right now."

    try:
        rec = LegalLookupQuery(user_id=user["id"], jurisdiction="eu_legislation",
                                query_text=query[:500], results_json=json.dumps(results))
        db.session.add(rec); db.session.commit()
        saved = True
    except Exception as e:
        db.session.rollback(); logging.error(f"[EU LEGISLATION SEARCH SAVE] {e}")
        saved = False

    return jsonify({"query": query, "results": results, "error": error, "saved": saved}), 200


@app.route("/api/legal/au-case-law-search", methods=["POST"])
@csrf.exempt
def legal_au_case_law_search():
    """AustLII (Australia) — has no JSON/REST API. Calls its real, public,
    no-key SINO search CGI (sinosrch.cgi) and parses the HTML results.
    This is an honest scrape of a real search, not a fabricated endpoint —
    AustLII simply doesn't offer anything more structured than this."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401

    data  = request.get_json(silent=True) or {}
    query = (data.get("query") or "").strip()
    if not query:
        return jsonify({"error": "Provide a search query (case name, topic, or citation)."}), 400
    # /au covers all Australian federal + state databases in one search.
    meta = (data.get("database") or "/au").strip()

    results, error = [], None
    try:
        resp = requests.get(
            "https://www.austlii.edu.au/cgi-bin/sinosrch.cgi",
            params={"method": "auto", "query": query, "meta": meta, "results": 20, "rank": "on"},
            headers={
                "User-Agent": ("Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 "
                                "(KHTML, like Gecko) Chrome/120.0 Safari/537.36"),
                "Referer": "https://www.austlii.edu.au/forms/search1.html",
            },
            timeout=25,
        )
        if resp.ok:
            html = resp.text
            seen_urls = set()
            # Real AustLII search results render as <a href="/au/...">Title</a>
            # inside the results list. No JSON is available, so this parses
            # the actual HTML rather than guessing at a structured shape.
            for m in re.finditer(r'<a\s+href="(/(?:cgi-bin/viewdoc|au)/[^"?#]+\.html[^"]*)"[^>]*>(.*?)</a>',
                                   html, re.IGNORECASE | re.DOTALL):
                href, raw_title = m.group(1), m.group(2)
                title = re.sub(r"<[^>]+>", "", raw_title).strip()
                if not title or href in seen_urls:
                    continue
                seen_urls.add(href)
                full_url = href if href.startswith("http") else f"https://www.austlii.edu.au{href}"
                results.append({"title": title, "url": full_url})
                if len(results) >= 20:
                    break
        else:
            error = f"AustLII returned status {resp.status_code}"
    except Exception as e:
        logging.error(f"[AU CASE LAW SEARCH] {e}")
        error = "Could not reach AustLII right now."

    try:
        rec = LegalLookupQuery(user_id=user["id"], jurisdiction="au_case_law",
                                query_text=query[:500], results_json=json.dumps(results))
        db.session.add(rec); db.session.commit()
        saved = True
    except Exception as e:
        db.session.rollback(); logging.error(f"[AU CASE LAW SEARCH SAVE] {e}")
        saved = False

    return jsonify({"query": query, "database": meta, "results": results, "error": error, "saved": saved}), 200


@app.route("/api/legal/africa-places", methods=["GET"])
@csrf.exempt
def legal_africa_places():
    """Lists every country/locality the real Laws.Africa Content API
    actually supports right now (GET /v3/places.json), rather than a
    hardcoded guess at ISO codes — the API's own place list is the only
    reliable source, since some entries (e.g. Zanzibar) don't use a
    plain ISO 3166-1 alpha-2 code. Confirmed live and documented at
    developers.laws.africa/content-api/reference/countries-and-localities
    before building. Same lawsafrica BYOK token as the legislation search
    below."""
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    token = get_effective_credential(user["id"], "lawsafrica", "api_token", None)
    if not token:
        return jsonify({"error": "Connect your Laws.Africa Content API token first."}), 200

    places, error = [], None
    try:
        resp = requests.get("https://api.laws.africa/v3/places.json",
                             headers={"Authorization": f"Token {token}"}, timeout=20)
        if resp.status_code in (401, 403):
            error = "Laws.Africa rejected the API token."
        elif not resp.ok:
            error = f"Laws.Africa API returned status {resp.status_code}"
        else:
            body = resp.json() if resp.text.strip() else {}
            entries = body if isinstance(body, list) else (body.get("results") or [])
            for p in entries:
                code = p.get("code") if isinstance(p, dict) else None
                name = p.get("name") if isinstance(p, dict) else None
                if code:
                    places.append({"code": code, "name": name or code.upper()})
    except Exception as e:
        logging.error(f"[AFRICA PLACES] {e}")
        error = "Could not reach the Laws.Africa API right now."

    # Zimbabwe first (the jurisdiction most requests will use), then the
    # rest alphabetically by name.
    places.sort(key=lambda p: (p["code"] != "zw", p["name"]))
    return jsonify({"places": places, "error": error}), 200


@app.route("/api/legal/africa-legislation-search", methods=["POST"])
@csrf.exempt
def legal_africa_legislation_search():
    """The real Laws.Africa Content API, generalised to any place code the
    API supports (Zimbabwe, South Africa, Kenya, Uganda, Tanzania, Zambia,
    Malawi, Ghana, Namibia, and more — see /api/legal/africa-places for
    the live list). Accepts a `place` parameter on top of the same
    listing/filtering logic used elsewhere in this file."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401

    token = get_effective_credential(user["id"], "lawsafrica", "api_token", None)
    if not token:
        return jsonify({"error": "Connect your Laws.Africa Content API token under Integrations first. "
                                  "Laws.Africa grants free access for non-commercial/academic use on request "
                                  "at https://laws.africa/api"}), 400

    data  = request.get_json(silent=True) or {}
    place = re.sub(r"[^a-z0-9\-]", "", (data.get("place") or "zw").strip().lower())[:16] or "zw"
    query = (data.get("query") or "").strip()
    year  = re.sub(r"\D", "", (data.get("year") or ""))[:4]

    results, error = [], None
    try:
        path = f"https://api.laws.africa/v3/akn/{place}/{year}.json" if year else f"https://api.laws.africa/v3/akn/{place}/.json"
        headers = {"Authorization": f"Token {token}"}
        scanned = 0
        while path and scanned < 200 and len(results) < 20:
            resp = requests.get(path, headers=headers, timeout=20)
            if not resp.ok:
                if resp.status_code in (401, 403):
                    error = "Laws.Africa rejected the API token. Check it under Integrations."
                elif resp.status_code == 404:
                    error = f"No legislation found for place code '{place}'. Check /api/legal/africa-places for valid codes."
                else:
                    error = f"Laws.Africa API returned status {resp.status_code}"
                break
            body = resp.json() if resp.text.strip() else {}
            for w in (body.get("results") or []):
                scanned += 1
                title = w.get("title")
                if query and query.lower() not in (title or "").lower():
                    continue
                frbr = w.get("frbr_uri")
                results.append({
                    "title":    title,
                    "frbr_uri": frbr,
                    "year":     w.get("year"),
                    "place":    place,
                    "url":      f"https://africanlii.org{frbr}" if frbr else None,
                })
                if len(results) >= 20:
                    break
            path = body.get("next") if len(results) < 20 else None
    except Exception as e:
        logging.error(f"[AFRICA LEGISLATION SEARCH] {e}")
        error = "Could not reach the Laws.Africa API right now."

    try:
        rec = LegalLookupQuery(user_id=user["id"], jurisdiction="africa_legislation",
                                query_text=f"[{place}] {query or year or 'all'}"[:500],
                                results_json=json.dumps(results))
        db.session.add(rec); db.session.commit()
        saved = True
    except Exception as e:
        db.session.rollback(); logging.error(f"[AFRICA LEGISLATION SEARCH SAVE] {e}")
        saved = False

    return jsonify({"place": place, "query": query, "year": year, "results": results,
                     "error": error, "saved": saved}), 200


