@app.route("/api/legal/lookup-history", methods=["GET"])
def legal_lookup_history():
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    jurisdiction = (request.args.get("jurisdiction") or "").strip()
    q = LegalLookupQuery.query.filter_by(user_id=user["id"])
    if jurisdiction:
        q = q.filter_by(jurisdiction=jurisdiction)
    rows = q.order_by(LegalLookupQuery.created_at.desc()).limit(50).all()
    return jsonify({"queries": [r.to_dict() for r in rows]}), 200


# ════════════════════════════════════════════════════════════
# STAGE: PUBLIC ACADEMIC & PROFESSIONAL RESEARCH LOOKUPS
# Real, public subject-area APIs so users can research each field from
# inside the app, same "no fabricated endpoints" rule as the legal-research
# section above. Every one of these was checked against its own real,
# documented shape before being added:
#
# 1. Computer Science / Computer Engineering — Stack Exchange API.
#    Docs: https://api.stackexchange.com/docs. Public, unauthenticated
#    search works at a lower daily quota; a free app key (BYOK, provider
#    "stackexchange") raises it. Site is selectable (stackoverflow,
#    electronics, softwareengineering, superuser) so both CS and computer
#    engineering topics are covered by the same real endpoint family.
# 2. Data Science — Kaggle's public Datasets API.
#    Docs: https://www.kaggle.com/docs/api. Requires a free Kaggle
#    username + API token (BYOK, provider "kaggle") — Kaggle doesn't offer
#    unauthenticated access, so there's no unkeyed fallback here.
# 3. Maths — math.js's public expression-evaluation API.
#    Docs: https://api.mathjs.org. Fully public, no key, evaluates a real
#    expression server-side (not a canned answer).
# 4. Commerce — Frankfurter, the open-source ECB foreign-exchange rate API.
#    Docs: https://www.frankfurter.app/docs. Fully public, no key.
# 5. Science — PubChem's compound lookup API (chemistry).
#    Docs: https://pubchem.ncbi.nlm.nih.gov/docs/pug-rest. Fully public,
#    no key, run by the US National Library of Medicine.
# 6. English — the Free Dictionary API.
#    Docs: https://dictionaryapi.dev. Fully public, no key.
# 7. Accounts (accounting / financial reporting) — SEC EDGAR full-text
#    search. Docs: https://www.sec.gov/edgar/search/. Fully public, no
#    key, but SEC's fair-access policy requires a descriptive User-Agent
#    identifying the requester, which is set on every call below.
#
# NOT implemented — checked and deliberately left out rather than faked:
# - "dpf": not a recognizable subject or public API — could mean the PDF
#   file format, a Diesel Particulate Filter, or something specific to
#   this app that wasn't specified. Left out rather than guessed at; happy
#   to build this out once it's clear what it should refer to.
# ════════════════════════════════════════════════════════════

ACADEMIC_STACKEXCHANGE_SITES = ("stackoverflow", "electronics", "softwareengineering", "superuser")

@app.route("/api/academic/cs-search", methods=["POST"])
@csrf.exempt
def academic_cs_search():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401

    data  = request.get_json(silent=True) or {}
    query = (data.get("query") or "").strip()
    if not query:
        return jsonify({"error": "Provide a search query (topic, error message, or keyword)."}), 400
    site = (data.get("site") or "stackoverflow").strip().lower()
    if site not in ACADEMIC_STACKEXCHANGE_SITES:
        site = "stackoverflow"

    app_key = get_effective_credential(user["id"], "stackexchange", "app_key", None)
    params = {"q": query, "site": site, "pagesize": 20, "order": "desc", "sort": "relevance"}
    if app_key:
        params["key"] = app_key

    results, error = [], None
    try:
        resp = requests.get("https://api.stackexchange.com/2.3/search/advanced", params=params, timeout=20)
        if resp.ok:
            body = resp.json() if resp.text.strip() else {}
            from html import unescape as _html_unescape
            for it in (body.get("items") or [])[:20]:
                results.append({
                    "title":       _html_unescape(it.get("title") or ""),
                    "link":        it.get("link"),
                    "score":       it.get("score"),
                    "answers":     it.get("answer_count"),
                    "is_answered": it.get("is_answered"),
                    "tags":        it.get("tags"),
                })
        elif resp.status_code in (429, 502):
            error = "Stack Exchange rate limit hit. Connect a free app key under Integrations for higher limits."
        else:
            error = f"Stack Exchange API returned status {resp.status_code}"
    except Exception as e:
        logging.error(f"[CS SEARCH] {e}")
        error = "Could not reach the Stack Exchange API right now."

    try:
        rec = AcademicLookupQuery(user_id=user["id"], subject="computer_science",
                                   query_text=query[:500], results_json=json.dumps(results))
        db.session.add(rec); db.session.commit()
        saved = True
    except Exception as e:
        db.session.rollback(); logging.error(f"[CS SEARCH SAVE] {e}")
        saved = False

    return jsonify({"query": query, "site": site, "results": results, "error": error, "saved": saved}), 200


