@app.route("/api/academic/maths-calculate", methods=["POST"])
@csrf.exempt
def academic_maths_calculate():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401

    data       = request.get_json(silent=True) or {}
    expression = (data.get("expression") or "").strip()
    if not expression:
        return jsonify({"error": "Provide a math expression, e.g. sqrt(16) + 2^3"}), 400

    results, error = [], None
    try:
        resp = requests.get("https://api.mathjs.org/v4/", params={"expr": expression[:500]}, timeout=15)
        if resp.ok:
            results.append({"expression": expression, "result": resp.text.strip()})
        else:
            error = (resp.text or "").strip()[:300] or f"math.js API returned status {resp.status_code}"
    except Exception as e:
        logging.error(f"[MATHS CALCULATE] {e}")
        error = "Could not reach the math.js API right now."

    try:
        rec = AcademicLookupQuery(user_id=user["id"], subject="maths",
                                   query_text=expression[:500], results_json=json.dumps(results))
        db.session.add(rec); db.session.commit()
        saved = True
    except Exception as e:
        db.session.rollback(); logging.error(f"[MATHS CALCULATE SAVE] {e}")
        saved = False

    return jsonify({"expression": expression, "results": results, "error": error, "saved": saved}), 200


@app.route("/api/academic/commerce-fx", methods=["POST"])
@csrf.exempt
def academic_commerce_fx():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401

    data = request.get_json(silent=True) or {}
    base = (data.get("from") or "USD").strip().upper()[:3]
    to   = (data.get("to") or "").strip().upper()[:3]
    try:
        amount = float(data.get("amount") or 1)
    except (TypeError, ValueError):
        amount = 1.0

    results, error = [], None
    base_out, date_out = None, None
    try:
        params = {"amount": amount, "from": base}
        if to:
            params["to"] = to
        resp = requests.get("https://api.frankfurter.app/latest", params=params, timeout=15)
        if resp.ok:
            body = resp.json() if resp.text.strip() else {}
            rates = body.get("rates") or {}
            for ccy, rate in list(rates.items())[:30]:
                results.append({"currency": ccy, "converted_amount": rate})
            base_out = body.get("base")
            date_out = body.get("date")
        else:
            error = f"Frankfurter API returned status {resp.status_code}"
    except Exception as e:
        logging.error(f"[COMMERCE FX] {e}")
        error = "Could not reach the Frankfurter FX API right now."

    try:
        rec = AcademicLookupQuery(user_id=user["id"], subject="commerce",
                                   query_text=f"{amount} {base} -> {to or 'all'}"[:500],
                                   results_json=json.dumps(results))
        db.session.add(rec); db.session.commit()
        saved = True
    except Exception as e:
        db.session.rollback(); logging.error(f"[COMMERCE FX SAVE] {e}")
        saved = False

    return jsonify({"from": base, "to": to or None, "amount": amount, "base": base_out,
                     "date": date_out, "results": results, "error": error, "saved": saved}), 200


