@app.route("/api/academic/geography-search", methods=["POST"])
@csrf.exempt
def academic_geography_search():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401

    data  = request.get_json(silent=True) or {}
    query = (data.get("query") or "").strip()
    if not query:
        return jsonify({"error": "Provide a country name (e.g. Zimbabwe) or region (e.g. Africa)."}), 400

    results, error = [], None
    try:
        resp = requests.get(f"https://restcountries.com/v3.1/name/{quote(query)}", timeout=15)
        if resp.status_code == 404:
            resp = requests.get(f"https://restcountries.com/v3.1/region/{quote(query)}", timeout=15)
        if resp.ok:
            body = resp.json() if resp.text.strip() else []
            for c in (body or [])[:20]:
                currencies = list((c.get("currencies") or {}).keys())
                languages  = list((c.get("languages") or {}).values())
                capitals   = c.get("capital") or []
                results.append({
                    "name":        ((c.get("name") or {}).get("common")),
                    "official":    ((c.get("name") or {}).get("official")),
                    "capital":     capitals[0] if capitals else None,
                    "region":      c.get("region"),
                    "subregion":   c.get("subregion"),
                    "population":  c.get("population"),
                    "area_km2":    c.get("area"),
                    "currencies":  currencies,
                    "languages":   languages,
                    "flag_url":    ((c.get("flags") or {}).get("png")),
                })
        elif resp.status_code == 404:
            error = "No country or region found for that search."
        else:
            error = f"REST Countries API returned status {resp.status_code}"
    except Exception as e:
        logging.error(f"[GEOGRAPHY SEARCH] {e}")
        error = "Could not reach the REST Countries API right now."

    try:
        rec = AcademicLookupQuery(user_id=user["id"], subject="geography",
                                   query_text=query[:500], results_json=json.dumps(results))
        db.session.add(rec); db.session.commit()
        saved = True
    except Exception as e:
        db.session.rollback(); logging.error(f"[GEOGRAPHY SEARCH SAVE] {e}")
        saved = False

    return jsonify({"query": query, "results": results, "error": error, "saved": saved}), 200


@app.route("/api/academic/history-on-this-day", methods=["POST"])
@csrf.exempt
def academic_history_on_this_day():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401

    data  = request.get_json(silent=True) or {}
    try:
        month = int(data.get("month") or 0)
        day   = int(data.get("day") or 0)
    except (TypeError, ValueError):
        month, day = 0, 0
    if not (1 <= month <= 12 and 1 <= day <= 31):
        return jsonify({"error": "Provide a valid month (1-12) and day (1-31)."}), 400

    results, error = [], None
    try:
        resp = requests.get(f"https://history.muffinlabs.com/date/{month}/{day}", timeout=15)
        if resp.ok:
            body = resp.json() if resp.text.strip() else {}
            data_block = body.get("data") or {}
            for kind in ("Events", "Births", "Deaths"):
                for item in (data_block.get(kind) or [])[:8]:
                    links = item.get("links") or []
                    results.append({
                        "type":  kind,
                        "year":  item.get("year"),
                        "text":  item.get("text"),
                        "url":   links[0].get("link") if links else None,
                    })
        else:
            error = f"History API returned status {resp.status_code}"
    except Exception as e:
        logging.error(f"[HISTORY ON THIS DAY] {e}")
        error = "Could not reach the history.muffinlabs.com API right now."

    try:
        rec = AcademicLookupQuery(user_id=user["id"], subject="history",
                                   query_text=f"{month}/{day}", results_json=json.dumps(results))
        db.session.add(rec); db.session.commit()
        saved = True
    except Exception as e:
        db.session.rollback(); logging.error(f"[HISTORY ON THIS DAY SAVE] {e}")
        saved = False

    return jsonify({"month": month, "day": day, "results": results, "error": error, "saved": saved}), 200


# ════════════════════════════════════════════════════════════
# STAGE: BANKING & FINANCE + TOURISM & HOSPITALITY RESEARCH
# Two new AcademicLookupQuery subjects, real APIs, BYOK (see the
# BYOK_PROVIDERS comment above "zimrate"/"opentripmap" for source docs
# and what was actually confirmed before building):
#
#   banking_finance — ZimRate (official RBZ interbank exchange rates,
#   inflation, and Mosi-oa-Tunya gold coin prices for Zimbabwe), with an
#   optional region switch to the sibling AfriRate product (same login,
#   28 African countries) for the exchange-rates endpoint specifically —
#   covering "Zimbabwe and other countries" honestly, on real vendor
#   infrastructure rather than an invented aggregator.
#
#   tourism_hospitality — OpenTripMap (worldwide tourist attractions,
#   museums, cultural/natural sites, and accommodation/hospitality
#   venues), geocoded from a free-text place name via OpenTripMap's own
#   geoname endpoint so it works for any city/country, Zimbabwe
#   included, not just a hardcoded list.
# ════════════════════════════════════════════════════════════

_ZIMRATE_REGION_BASE = {
    "zimbabwe": "https://zimrate.statotec.com/api/v1",
    "africa":   "https://afrirate.statotec.com/api/v1",
}


def _zimrate_get(user_id, path: str, params: dict = None):
    """Calls a ZimRate/AfriRate v1 endpoint with the user's own key (BYOK)
    or the platform's fallback key. Returns (data_dict_or_None, error_str_or_None)."""
    api_key = get_effective_credential(user_id, "zimrate", "api_key",
                                        platform_fallback=os.environ.get("ZIMRATE_API_KEY"))
    if not api_key:
        return None, ("Connect a free ZimRate API key (zimrate.statotec.com/signup) "
                       "to use Zimbabwe/Africa banking data.")
    base = _ZIMRATE_REGION_BASE.get((params or {}).pop("_region", "zimbabwe"), _ZIMRATE_REGION_BASE["zimbabwe"])
    try:
        resp = requests.get(f"{base}{path}", params=params or {},
                             headers={"Authorization": f"Bearer {api_key}"}, timeout=15)
        if resp.status_code == 401:
            return None, "ZimRate rejected that API key — check it's still valid."
        if resp.status_code == 429:
            return None, "ZimRate rate limit reached — try again shortly, or upgrade your ZimRate plan."
        if not resp.ok:
            return None, f"ZimRate API returned status {resp.status_code}"
        body = resp.json() if resp.text.strip() else {}
        if body.get("error"):
            return None, body["error"].get("message", "ZimRate API error")
        return body.get("data") or {}, None
    except Exception as e:
        logging.error(f"[ZIMRATE] {e}")
        return None, "Could not reach the ZimRate API right now."


