_OPENTRIPMAP_KINDS_PRESETS = {
    "attractions":  "tourist_attractions,museums,theatres_and_entertainments,cultural,natural",
    "hospitality":  "accomodations",
}


@app.route("/api/academic/tourism-search", methods=["POST"])
@csrf.exempt
def academic_tourism_search():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401

    data   = request.get_json(silent=True) or {}
    place  = (data.get("place") or "").strip()[:200]
    preset = (data.get("preset") or "attractions").strip().lower()
    kinds  = _OPENTRIPMAP_KINDS_PRESETS.get(preset, _OPENTRIPMAP_KINDS_PRESETS["attractions"])
    try:
        radius = max(1000, min(int(data.get("radius") or 20000), 200000))
    except (TypeError, ValueError):
        radius = 20000

    if not place:
        return jsonify({"error": "Enter a place name (city, town, or landmark)."}), 400

    api_key = get_effective_credential(user["id"], "opentripmap", "api_key",
                                        platform_fallback=os.environ.get("OPENTRIPMAP_API_KEY"))
    if not api_key:
        return jsonify({"error": "Connect a free OpenTripMap API key (opentripmap.io) "
                                  "to search tourism and hospitality venues."}), 200

    results, error = [], None
    try:
        geo = requests.get("https://api.opentripmap.com/0.1/en/places/geoname",
                            params={"name": place, "apikey": api_key}, timeout=15)
        if not geo.ok:
            error = f"OpenTripMap geocoding returned status {geo.status_code}"
        else:
            geo_body = geo.json() if geo.text.strip() else {}
            lat, lon = geo_body.get("lat"), geo_body.get("lon")
            if lat is None or lon is None:
                error = f"Could not find a location named '{place}'."
            else:
                poi = requests.get("https://api.opentripmap.com/0.1/en/places/radius",
                                    params={"radius": radius, "lat": lat, "lon": lon,
                                            "kinds": kinds, "limit": 30, "format": "json",
                                            "apikey": api_key}, timeout=15)
                if not poi.ok:
                    error = f"OpenTripMap search returned status {poi.status_code}"
                else:
                    for row in (poi.json() or [])[:30]:
                        results.append({
                            "name": row.get("name") or "(unnamed)",
                            "kinds": row.get("kinds"),
                            "dist_m": round(row.get("dist"), 0) if row.get("dist") is not None else None,
                            "point": row.get("point"),
                            "xid": row.get("xid"),
                        })
    except Exception as e:
        logging.error(f"[TOURISM SEARCH] {e}")
        error = "Could not reach the OpenTripMap API right now."

    try:
        rec = AcademicLookupQuery(user_id=user["id"], subject="tourism_hospitality",
                                   query_text=f"{preset} near {place} ({radius}m)"[:500],
                                   results_json=json.dumps(results))
        db.session.add(rec); db.session.commit()
        saved = True
    except Exception as e:
        db.session.rollback(); logging.error(f"[TOURISM SEARCH SAVE] {e}")
        saved = False

    return jsonify({"place": place, "preset": preset, "radius": radius,
                     "results": results, "error": error, "saved": saved}), 200


# ════════════════════════════════════════════════════════════
# STAGE: AUTOMOTIVE / DIESEL ENGINE MECHANIC RESEARCH
# Real, public automotive-engineering data — VIN decoding, recall/safety
# history, and diagnostic trouble codes (including DPF/emissions codes) —
# for studying engine mechanics end to end: identify the vehicle and its
# engine, see its real-world reliability/recall record, then look up what
# a specific fault code (including diesel-particulate-filter codes such
# as P2002, P244A, P246C) actually means. Checked before being added:
#
# 1. NHTSA vPIC (VIN decode) — https://vpic.nhtsa.dot.gov/api. Official
#    US Dept. of Transportation vehicle database. Fully public, no key,
#    no registration. Returns engine, fuel type, cylinders, displacement,
#    transmission, drivetrain, plant, and 100+ other real fields for any
#    valid VIN, covering diesel as well as gasoline/electric vehicles.
# 2. NHTSA Safety API (recalls) — https://api.nhtsa.gov. Same agency,
#    separate public no-key endpoint. Returns real recall campaigns
#    (component, summary, consequence, remedy) for a given make/model/year
#    — this is where real DPF and emissions-system recalls show up.
# 3. OBDex (diagnostic trouble codes) — https://foerbsnavi.github.io/obdex.
#    An open, CC0-licensed, machine-readable database of all 9,533 generic
#    OBD-II codes (SAE J2012 / ISO 15031-6), including causes, symptoms,
#    and repair estimates. Served as static JSON over GitHub Pages — no
#    key, no rate limit. Cached in memory for 24h per process since it's
#    a large, slow-changing static dataset, not a live query API.
#
# NOT implemented — checked and deliberately left out rather than faked:
# - "Cambridge all subjects": Cambridge International (CAIE) has no public
#   developer API. Past papers and syllabi are copyrighted PDFs distributed
#   only through Cambridge's own site or paid resellers — nothing real,
#   free, and legally redistributable to plug in here.
# ════════════════════════════════════════════════════════════

_OBDEX_CACHE = {"data": None, "fetched_at": 0}
_OBDEX_CACHE_TTL_SECONDS = 24 * 60 * 60

def _get_obdex_dataset():
    """Fetches (and caches for 24h) the full 9,533-entry OBDex generic DTC
    dataset from its real public GitHub Pages CDN. Returns (list, error)."""
    now = time.time()
    if _OBDEX_CACHE["data"] is not None and (now - _OBDEX_CACHE["fetched_at"]) < _OBDEX_CACHE_TTL_SECONDS:
        return _OBDEX_CACHE["data"], None
    try:
        resp = requests.get("https://foerbsnavi.github.io/obdex/generic.min.json", timeout=25)
        if resp.ok:
            data = resp.json() if resp.text.strip() else []
            _OBDEX_CACHE["data"] = data
            _OBDEX_CACHE["fetched_at"] = now
            return data, None
        return (_OBDEX_CACHE["data"] or []), f"OBDex dataset returned status {resp.status_code}"
    except Exception as e:
        logging.error(f"[OBDEX FETCH] {e}")
        return (_OBDEX_CACHE["data"] or []), "Could not reach the OBDex dataset right now."


@app.route("/api/automotive/vin-decode", methods=["POST"])
@csrf.exempt
def automotive_vin_decode():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401

    data = request.get_json(silent=True) or {}
    vin  = (data.get("vin") or "").strip().upper()
    if not vin:
        return jsonify({"error": "Provide a 17-character VIN."}), 400

    results, error = [], None
    try:
        resp = requests.get(
            f"https://vpic.nhtsa.dot.gov/api/vehicles/DecodeVinValuesExtended/{quote(vin)}",
            params={"format": "json"}, timeout=20,
        )
        if resp.ok:
            body = resp.json() if resp.text.strip() else {}
            rows = body.get("Results") or []
            if rows:
                r = rows[0]
                fields = ["Make", "Model", "ModelYear", "VehicleType", "BodyClass",
                          "EngineCylinders", "DisplacementL", "EngineHP", "FuelTypePrimary",
                          "FuelTypeSecondary", "TransmissionStyle", "DriveType",
                          "PlantCountry", "PlantCity", "Manufacturer", "ErrorText"]
                entry = {f: r.get(f) for f in fields if r.get(f)}
                if entry:
                    results.append(entry)
                else:
                    error = "NHTSA had no data for that VIN."
        else:
            error = f"NHTSA vPIC API returned status {resp.status_code}"
    except Exception as e:
        logging.error(f"[VIN DECODE] {e}")
        error = "Could not reach the NHTSA vPIC API right now."

    try:
        rec = AcademicLookupQuery(user_id=user["id"], subject="automotive_vin",
                                   query_text=vin[:500], results_json=json.dumps(results))
        db.session.add(rec); db.session.commit()
        saved = True
    except Exception as e:
        db.session.rollback(); logging.error(f"[VIN DECODE SAVE] {e}")
        saved = False

    return jsonify({"vin": vin, "results": results, "error": error, "saved": saved}), 200


