@app.route("/api/automotive/dtc-lookup", methods=["POST"])
@csrf.exempt
def automotive_dtc_lookup():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401

    data  = request.get_json(silent=True) or {}
    query = (data.get("query") or "").strip()
    if not query:
        return jsonify({"error": "Provide a diagnostic trouble code (e.g. P2002) or a keyword "
                                  "(e.g. diesel particulate filter)."}), 400

    dataset, error = _get_obdex_dataset()
    results = []
    if dataset:
        looks_like_code = bool(re.match(r"^[PBCU][0-9A-Fa-f]{4}$", query.replace(" ", "")))
        if looks_like_code:
            code_norm = query.replace(" ", "").upper()
            for entry in dataset:
                if (entry.get("code") or "").upper() == code_norm:
                    results.append(entry)
                    break
        else:
            q_lower = query.lower()
            for entry in dataset:
                title = ((entry.get("title") or {}).get("en") or "")
                desc  = ((entry.get("description") or {}).get("en") or "")
                if q_lower in title.lower() or q_lower in desc.lower():
                    results.append(entry)
                    if len(results) >= 20:
                        break
    elif not error:
        error = "OBDex dataset unavailable right now."

    trimmed = []
    for entry in results:
        title = (entry.get("title") or {}).get("en")
        desc  = (entry.get("description") or {}).get("en")
        causes = [ (c.get("label") or {}).get("en") for c in (entry.get("common_causes") or [])[:5] ]
        symptoms = [ (s.get("en")) for s in (entry.get("symptoms") or [])[:5] ]
        repair = entry.get("repair") or {}
        trimmed.append({
            "code": entry.get("code"),
            "category": entry.get("category"),
            "title": title,
            "description": desc,
            "causes": [c for c in causes if c],
            "symptoms": [s for s in symptoms if s],
            "repair_difficulty": repair.get("difficulty"),
            "estimated_cost_eur": repair.get("estimated_cost_eur"),
            "flags": entry.get("flags"),
            "related_codes": entry.get("related_codes"),
        })

    try:
        rec = AcademicLookupQuery(user_id=user["id"], subject="automotive_dtc",
                                   query_text=query[:500], results_json=json.dumps(trimmed))
        db.session.add(rec); db.session.commit()
        saved = True
    except Exception as e:
        db.session.rollback(); logging.error(f"[DTC LOOKUP SAVE] {e}")
        saved = False

    return jsonify({"query": query, "results": trimmed, "error": error, "saved": saved}), 200


