# ════════════════════════════════════════════════════════════

@app.route("/api/security/ip-reputation-check", methods=["POST"])
@csrf.exempt
def ip_reputation_check():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    key = get_effective_credential(user["id"], "abuseipdb", "api_key", None)
    if not key:
        return jsonify({"error": "Connect your free AbuseIPDB API key under Integrations first (register at abuseipdb.com)."}), 400

    data = request.get_json(silent=True) or {}
    ip_address = (data.get("ip_address") or "").strip()
    if not ip_address:
        return jsonify({"error": "ip_address is required."}), 400

    if _rate_limited(f"ipcheck:user:{user['id']}", max_attempts=60, window_seconds=3600):
        return jsonify({"error": "Too many IP checks this hour. Please wait a moment and try again."}), 429

    result, error = None, None
    try:
        resp = requests.get(
            "https://api.abuseipdb.com/api/v2/check",
            params={"ipAddress": ip_address, "maxAgeInDays": 90},
            headers={"Key": key, "Accept": "application/json"}, timeout=12,
        )
        if resp.ok:
            body = (resp.json() if resp.text.strip() else {}).get("data", {})
            result = {
                "abuse_score": body.get("abuseConfidenceScore"),
                "total_reports": body.get("totalReports"),
                "country_code": body.get("countryCode"),
                "is_tor": body.get("isTor"),
                "isp": body.get("isp"),
                "last_reported_at": body.get("lastReportedAt"),
                "is_whitelisted": body.get("isWhitelisted"),
                "domain": body.get("domain"),
            }
        else:
            error = f"AbuseIPDB returned status {resp.status_code}"
    except Exception as e:
        logging.error(f"[IP REPUTATION] {e}")
        error = "Could not reach AbuseIPDB right now."

    saved = False
    if result:
        try:
            rec = IpReputationCheck(
                user_id=user["id"], ip_address=ip_address[:64], abuse_score=result.get("abuse_score"),
                total_reports=result.get("total_reports"), country_code=result.get("country_code"),
                is_tor=result.get("is_tor"), isp=(result.get("isp") or "")[:200] or None,
                last_reported_at=result.get("last_reported_at"),
            )
            db.session.add(rec); db.session.commit()
            saved = True
        except Exception as e:
            db.session.rollback(); logging.error(f"[IP REPUTATION SAVE] {e}")

    return jsonify({"ip_address": ip_address, "result": result, "error": error, "saved": saved}), 200


