# STAGE 159: GLOBAL ADDRESS VALIDATION — ROUTES
# ════════════════════════════════════════════════════════════

NOMINATIM_SEARCH = "https://nominatim.openstreetmap.org/search"
NOMINATIM_HEADERS = {"User-Agent": "ConnectIt-BusinessSuite/1.0 (address-validation-feature)"}

@app.route("/api/logistics/address-validate", methods=["POST"])
@csrf.exempt
def address_validate():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    data    = request.get_json(silent=True) or {}
    address = (data.get("address") or "").strip()
    if not address:
        return jsonify({"error": "address is required."}), 400

    if _rate_limited(f"addrvalid:user:{user['id']}", max_attempts=30, window_seconds=60):
        return jsonify({"error": "Too many address checks. Please wait a moment and try again."}), 429

    matched, formatted, lat, lon, addr_type, raw, error = False, None, None, None, None, {}, None
    try:
        resp = requests.get(NOMINATIM_SEARCH, params={"q": address, "format": "jsonv2", "limit": 1, "addressdetails": 1},
                             headers=NOMINATIM_HEADERS, timeout=12)
        if resp.ok:
            rows = resp.json() if resp.text.strip() else []
            if rows:
                top = rows[0]
                matched = True
                formatted = top.get("display_name")
                lat = float(top.get("lat")) if top.get("lat") else None
                lon = float(top.get("lon")) if top.get("lon") else None
                addr_type = top.get("type")
                raw = top
        else:
            error = f"Nominatim returned status {resp.status_code}"
    except Exception as e:
        logging.error(f"[ADDRESS VALIDATE] {e}")
        error = "Could not reach the address validation service right now."

    try:
        rec = AddressValidationCheck(
            user_id=user["id"], query_address=address[:500], matched=matched,
            formatted_address=(formatted or "")[:500] or None, latitude=lat, longitude=lon,
            address_type=addr_type, raw_json=json.dumps(raw),
        )
        db.session.add(rec); db.session.commit()
        saved = True
    except Exception as e:
        db.session.rollback(); logging.error(f"[ADDRESS VALIDATE SAVE] {e}")
        saved = False

    return jsonify({
        "query_address": address, "matched": matched, "formatted_address": formatted,
        "latitude": lat, "longitude": lon, "address_type": addr_type,
        "error": error, "saved": saved,
    }), 200


