# ════════════════════════════════════════════════════════════
# STAGE 161: ENVIRONMENTAL / AIR QUALITY RISK CHECK (OPENAQ) — ROUTES
# ════════════════════════════════════════════════════════════

@app.route("/api/environment/air-quality-check", methods=["POST"])
@csrf.exempt
def air_quality_check():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    key = get_effective_credential(user["id"], "openaq", "api_key", None)
    if not key:
        return jsonify({"error": "Connect your free OpenAQ API key under Integrations first (register at explore.openaq.org/register)."}), 400

    data = request.get_json(silent=True) or {}
    try:
        lat = float(data.get("latitude"))
        lon = float(data.get("longitude"))
    except (TypeError, ValueError):
        return jsonify({"error": "Provide latitude and longitude (use the Address Validation tool to geocode a location first)."}), 400
    location_label = (data.get("location_label") or f"{lat},{lon}").strip()

    nearest_station, readings, error = None, [], None
    try:
        loc_resp = requests.get("https://api.openaq.org/v3/locations",
                                 params={"coordinates": f"{lat},{lon}", "radius": 25000, "limit": 1},
                                 headers={"X-API-Key": key}, timeout=12)
        if loc_resp.ok:
            locs = (loc_resp.json() if loc_resp.text.strip() else {}).get("results", [])
            if locs:
                station = locs[0]
                nearest_station = station.get("name")
                station_id = station.get("id")
                sensors = station.get("sensors", [])
                for sensor in sensors[:10]:
                    latest_resp = requests.get(f"https://api.openaq.org/v3/sensors/{sensor.get('id')}/measurements/latest",
                                                headers={"X-API-Key": key}, timeout=10)
                    if latest_resp.ok:
                        latest = (latest_resp.json() if latest_resp.text.strip() else {}).get("results", [])
                        for m in latest[:1]:
                            readings.append({
                                "parameter": (sensor.get("parameter") or {}).get("displayName"),
                                "value": m.get("value"),
                                "unit": (sensor.get("parameter") or {}).get("units"),
                                "datetime": (m.get("datetime") or {}).get("utc"),
                            })
            else:
                error = "No air quality monitoring station found within 25km of that location."
        else:
            error = f"OpenAQ API returned status {loc_resp.status_code}"
    except Exception as e:
        logging.error(f"[AIR QUALITY CHECK] {e}")
        error = "Could not reach OpenAQ right now."

    try:
        rec = AirQualityCheck(user_id=user["id"], query_location=location_label[:300], latitude=lat,
                               longitude=lon, nearest_station=nearest_station, readings_json=json.dumps(readings))
        db.session.add(rec); db.session.commit()
        saved = True
    except Exception as e:
        db.session.rollback(); logging.error(f"[AIR QUALITY CHECK SAVE] {e}")
        saved = False

    return jsonify({
        "location_label": location_label, "latitude": lat, "longitude": lon,
        "nearest_station": nearest_station, "readings": readings, "error": error, "saved": saved,
    }), 200


