    if keyword:
        payload["query"] = {"value": keyword}
    if filters:
        payload["filter"] = filters[0] if len(filters) == 1 else {"conditions": filters, "operator": "AND"}

    results, error = [], None
    try:
        resp = requests.post(RELIEFWEB_REPORTS, json=payload, timeout=15)
        if resp.ok:
            body = resp.json() if resp.text.strip() else {}
            for item in (body.get("data") or [])[:15]:
                fields = item.get("fields", {})
                countries = fields.get("country") or []
                disasters = fields.get("disaster_type") or []
                results.append({
                    "title": fields.get("title"),
                    "date": (fields.get("date") or {}).get("created"),
                    "countries": [c.get("name") for c in countries],
                    "disaster_types": [d.get("name") for d in disasters],
                    "url": fields.get("url_alias"),
                })
        else:
            error = f"ReliefWeb API returned status {resp.status_code}"
    except Exception as e:
        logging.error(f"[DISASTER ALERTS] {e}")
        error = "Could not reach the ReliefWeb humanitarian data service right now."

    try:
        rec = DisasterAlertQuery(user_id=user["id"], country=country[:100] or None,
                                  keyword=keyword[:200] or None, result_count=len(results),
                                  results_json=json.dumps(results))
        db.session.add(rec); db.session.commit()
        saved = True
    except Exception as e:
        db.session.rollback(); logging.error(f"[DISASTER ALERTS SAVE] {e}")
        saved = False

    return jsonify({"country": country, "keyword": keyword, "results": results,
                     "result_count": len(results), "error": error, "saved": saved}), 200


