# ════════════════════════════════════════════════════════════
# STAGE 163: REAL-TIME EARTHQUAKE ALERTS (USGS) — ROUTES
# ════════════════════════════════════════════════════════════

USGS_EARTHQUAKE_QUERY = "https://earthquake.usgs.gov/fdsnws/event/1/query"

@app.route("/api/environment/earthquake-check", methods=["POST"])
@csrf.exempt
def earthquake_check():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    try:
        lat = float(data.get("latitude"))
        lon = float(data.get("longitude"))
    except (TypeError, ValueError):
        return jsonify({"error": "Provide latitude and longitude (use the Global Address Validation tool to geocode a location first)."}), 400
    location_label = (data.get("location_label") or f"{lat},{lon}").strip()
    try:
        radius_km = int(data.get("radius_km") or 500)
    except (TypeError, ValueError):
        radius_km = 500
    try:
        min_magnitude = float(data.get("min_magnitude") or 4.0)
    except (TypeError, ValueError):
        min_magnitude = 4.0

    results, error = [], None
    try:
        resp = requests.get(USGS_EARTHQUAKE_QUERY, params={
            "format": "geojson", "latitude": lat, "longitude": lon,
            "maxradiuskm": radius_km, "minmagnitude": min_magnitude,
            "starttime": (datetime.utcnow() - timedelta(days=365)).strftime("%Y-%m-%d"),
            "orderby": "time", "limit": 20,
        }, timeout=15)
        if resp.ok:
            body = resp.json() if resp.text.strip() else {}
            for feat in (body.get("features") or [])[:20]:
                props = feat.get("properties", {})
                coords = (feat.get("geometry") or {}).get("coordinates", [])
                results.append({
                    "place": props.get("place"), "magnitude": props.get("mag"),
                    "time": props.get("time"), "depth_km": coords[2] if len(coords) > 2 else None,
                    "url": props.get("url"),
                })
        else:
            error = f"USGS API returned status {resp.status_code}"
    except Exception as e:
        logging.error(f"[EARTHQUAKE CHECK] {e}")
        error = "Could not reach the USGS earthquake service right now."

    try:
        rec = EarthquakeAlertQuery(user_id=user["id"], query_location=location_label[:300], latitude=lat,
                                    longitude=lon, radius_km=radius_km, min_magnitude=min_magnitude,
                                    result_count=len(results), results_json=json.dumps(results))
        db.session.add(rec); db.session.commit()
        saved = True
    except Exception as e:
        db.session.rollback(); logging.error(f"[EARTHQUAKE CHECK SAVE] {e}")
        saved = False

    return jsonify({
        "location_label": location_label, "latitude": lat, "longitude": lon,
        "radius_km": radius_km, "min_magnitude": min_magnitude, "results": results,
        "result_count": len(results), "error": error, "saved": saved,
    }), 200


