@app.route("/api/compliance/accessibility-check", methods=["POST"])
@csrf.exempt
def accessibility_check():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    key = get_effective_credential(user["id"], "wave_accessibility", "api_key", None)
    if not key:
        return jsonify({"error": "Connect your free WAVE API key under Integrations first (register at wave.webaim.org/api, 100 free credits)."}), 400

    data = request.get_json(silent=True) or {}
    url  = (data.get("url") or "").strip()
    if not url:
        return jsonify({"error": "url is required."}), 400
    if not url.startswith("http"):
        url = "https://" + url

    result, error = None, None
    try:
        resp = requests.get("https://wave.webaim.org/api/request",
                             params={"key": key, "url": url, "format": "json", "reporttype": 1}, timeout=20)
        if resp.ok:
            body = resp.json() if resp.text.strip() else {}
            if body.get("status", {}).get("success"):
                cats = body.get("categories", {})
                result = {
                    "error_count": (cats.get("error") or {}).get("count", 0),
                    "contrast_errors": (cats.get("contrast") or {}).get("count", 0),
                    "alert_count": (cats.get("alert") or {}).get("count", 0),
                    "feature_count": (cats.get("feature") or {}).get("count", 0),
                    "structure_count": (cats.get("structure") or {}).get("count", 0),
                    "aria_count": (cats.get("aria") or {}).get("count", 0),
                }
            else:
                error = (body.get("status") or {}).get("error") or "WAVE could not analyze that URL."
        else:
            error = f"WAVE API returned status {resp.status_code}"
    except Exception as e:
        logging.error(f"[ACCESSIBILITY CHECK] {e}")
        error = "Could not reach the WAVE accessibility service right now."

    saved = False
    if result:
        try:
            rec = AccessibilityCheck(
                user_id=user["id"], checked_url=url[:500], error_count=result.get("error_count"),
                contrast_errors=result.get("contrast_errors"), alert_count=result.get("alert_count"),
                feature_count=result.get("feature_count"), raw_json=json.dumps(result),
            )
            db.session.add(rec); db.session.commit()
            saved = True
        except Exception as e:
            db.session.rollback(); logging.error(f"[ACCESSIBILITY CHECK SAVE] {e}")

    return jsonify({"url": url, "result": result, "error": error, "saved": saved}), 200


