# ════════════════════════════════════════════════════════════
# STAGE 165: GOVERNANCE & CORRUPTION RISK INDEX (CPI) — ROUTES
# ════════════════════════════════════════════════════════════

OWID_CPI_CSV = "https://ourworldindata.org/grapher/ti-corruption-perception-index.csv"

@app.route("/api/trade/governance-risk-check", methods=["POST"])
@csrf.exempt
def governance_risk_check():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    data    = request.get_json(silent=True) or {}
    country = (data.get("country") or "").strip()
    if not country:
        return jsonify({"error": "country is required (e.g. Kenya, Brazil, Germany)."}), 400

    history, error = [], None
    try:
        resp = requests.get(OWID_CPI_CSV, params={"v": 1, "csvType": "full", "useColumnShortNames": "true"}, timeout=20)
        if resp.ok:
            reader = csv.DictReader(io.StringIO(resp.text))
            for row in reader:
                if row.get("Entity", "").strip().lower() == country.lower():
                    try:
                        history.append({"year": int(row["Year"]), "score": int(float(row["Corruption Perceptions Index"]))})
                    except (ValueError, KeyError):
                        continue
            history.sort(key=lambda r: r["year"])
            if not history:
                error = f"No CPI data found for '{country}' — check the spelling matches the official country name."
        else:
            error = f"Data source returned status {resp.status_code}"
    except Exception as e:
        logging.error(f"[GOVERNANCE RISK CHECK] {e}")
        error = "Could not reach the corruption index data source right now."

    latest_year, latest_score = None, None
    if history:
        latest_year, latest_score = history[-1]["year"], history[-1]["score"]

    try:
        rec = GovernanceRiskQuery(user_id=user["id"], country=country[:100], latest_year=latest_year,
                                   latest_score=latest_score, history_json=json.dumps(history))
        db.session.add(rec); db.session.commit()
        saved = True
    except Exception as e:
        db.session.rollback(); logging.error(f"[GOVERNANCE RISK CHECK SAVE] {e}")
        saved = False

    return jsonify({
        "country": country, "latest_year": latest_year, "latest_score": latest_score,
        "history": history, "error": error, "saved": saved,
        "scale_note": "Scale: 0 (highly corrupt) to 100 (very clean). Source: Transparency International's Corruption Perceptions Index.",
    }), 200


