# ===========================================================
# STAGE 29: TIKTOK CONTENT POSTING API — flagging this one honestly:
# unaudited apps (the default, before TikTok's app-review process) can
# only push a video into the CREATOR'S OWN TikTok inbox as a draft —
# they still have to open the TikTok app and tap "Post" themselves.
# Direct-to-public posting needs TikTok's audit, which is a separate,
# slower process outside this codebase. This wires up the "draft to
# inbox" flow, which is the free, un-audited part.
# ===========================================================

def _tiktok_creds_for_user(user_id) -> dict:
    return {
        "client_key": get_effective_credential(user_id, "tiktok", "client_key", TIKTOK_CLIENT_KEY),
        "client_secret": get_effective_credential(user_id, "tiktok", "client_secret", TIKTOK_CLIENT_SECRET),
        "access_token": get_effective_credential(user_id, "tiktok", "access_token", ""),
        "open_id": get_effective_credential(user_id, "tiktok", "open_id", ""),
    }


def post_tiktok_draft(user_id, video_url: str, title: str = "") -> dict:
    """Sends a video to the creator's TikTok inbox as a draft (pull-from-URL
    flow). The creator still opens their TikTok app to review and publish it —
    that manual last step is a TikTok platform requirement for unaudited apps,
    not a limitation of this integration."""
    creds = _tiktok_creds_for_user(user_id)
    if not creds["access_token"]:
        return {"ok": False, "error": "TikTok is not configured. Complete TikTok's login once and add the access_token/open_id under Integrations."}
    if not video_url:
        return {"ok": False, "error": "'video_url' is required (must be a publicly reachable HTTPS URL)."}
    try:
        r = requests.post(
            "https://open.tiktokapis.com/v2/post/publish/inbox/video/init/",
            headers={"Authorization": f"Bearer {creds['access_token']}", "Content-Type": "application/json"},
            json={
                "post_info": {"title": title[:150]} if title else {},
                "source_info": {"source": "PULL_FROM_URL", "video_url": video_url},
            },
            timeout=20,
        )
        body = r.json()
        error = body.get("error") or {}
        if r.status_code >= 400 or (error.get("code") and error.get("code") != "ok"):
            return {"ok": False, "error": error.get("message", "TikTok draft upload failed.")}
        publish_id = (body.get("data") or {}).get("publish_id")
        return {"ok": True, "publish_id": publish_id,
                "note": "Sent to the creator's TikTok inbox as a draft — open the TikTok app to review and post it."}
    except Exception as e:
        logging.error(f"[TIKTOK ERROR] user={user_id}: {e}")
        return {"ok": False, "error": str(e)}


@app.route("/api/tiktok/post-draft", methods=["POST"])
@csrf.exempt
def tiktok_post_draft_endpoint():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user_id = _current_user_id()
    if not user_id:
        return jsonify({"ok": False, "error": "Login required."}), 401
    data = request.get_json(force=True, silent=True) or {}
    result = post_tiktok_draft(user_id, (data.get("video_url") or "").strip(), title=(data.get("title") or "").strip())
    return jsonify(result), (201 if result.get("ok") else 502)


# ===========================================================
# STAGE 34: TIKTOK ANALYTICS — read-only account + video performance
# metrics via the TikTok Display API. Reuses the exact same access_token
# already stored under the "tiktok" provider (no new BYOK fields needed)
# — it just needs that token to also carry the user.info.basic and
# video.list scopes when the creator completes TikTok's own login/
# consent step (same out-of-band flow noted in Stage 29 above).
# ===========================================================

def get_tiktok_account_stats(user_id) -> dict:
    creds = _tiktok_creds_for_user(user_id)
    if not creds["access_token"]:
        return {"ok": False, "error": "TikTok is not configured."}
    try:
        r = requests.get(
            "https://open.tiktokapis.com/v2/user/info/",
            headers={"Authorization": f"Bearer {creds['access_token']}"},
            params={"fields": "display_name,follower_count,following_count,likes_count,video_count"},
            timeout=15,
        )
        body  = r.json()
        error = body.get("error") or {}
        if r.status_code >= 400 or (error.get("code") and error.get("code") != "ok"):
            return {"ok": False, "error": error.get("message", "Could not load TikTok account stats.")}
        user = (body.get("data") or {}).get("user", {})
        return {"ok": True, "stats": {
            "display_name":    user.get("display_name"),
            "follower_count":  user.get("follower_count"),
            "following_count": user.get("following_count"),
            "likes_count":     user.get("likes_count"),
            "video_count":     user.get("video_count"),
        }}
    except Exception as e:
        logging.error(f"[TIKTOK ACCOUNT STATS ERROR] user={user_id}: {e}")
        return {"ok": False, "error": str(e)}


def get_tiktok_video_insights(user_id, max_count: int = 20) -> dict:
    """Lists the creator's most recent videos with per-video performance
    (views/likes/comments/shares) — the closest free equivalent to
    'TikTok Analytics' available without the paid Business/Ads API."""
    creds = _tiktok_creds_for_user(user_id)
    if not creds["access_token"]:
        return {"ok": False, "error": "TikTok is not configured."}
    try:
        r = requests.post(
            "https://open.tiktokapis.com/v2/video/list/",
            headers={"Authorization": f"Bearer {creds['access_token']}", "Content-Type": "application/json"},
            params={"fields": "id,title,view_count,like_count,comment_count,share_count,create_time,share_url"},
            json={"max_count": max(1, min(max_count, 20))},
            timeout=15,
        )
        body  = r.json()
        error = body.get("error") or {}
        if r.status_code >= 400 or (error.get("code") and error.get("code") != "ok"):
            return {"ok": False, "error": error.get("message", "Could not load TikTok video insights.")}
        videos = (body.get("data") or {}).get("videos", [])
        return {"ok": True, "videos": [
            {
                "id":            v.get("id"),
                "title":         v.get("title"),
                "views":         v.get("view_count"),
                "likes":         v.get("like_count"),
                "comments":      v.get("comment_count"),
                "shares":        v.get("share_count"),
                "created":       v.get("create_time"),
                "url":           v.get("share_url"),
            }
            for v in videos
        ]}
    except Exception as e:
        logging.error(f"[TIKTOK VIDEO INSIGHTS ERROR] user={user_id}: {e}")
        return {"ok": False, "error": str(e)}


@app.route("/api/tiktok/analytics/account", methods=["GET"])
@csrf.exempt
def tiktok_analytics_account_endpoint():
    user_id = _current_user_id()
    if not user_id:
        return jsonify({"ok": False, "error": "Login required."}), 401
    result = get_tiktok_account_stats(user_id)
    return jsonify(result), (200 if result.get("ok") else 502)


@app.route("/api/tiktok/analytics/videos", methods=["GET"])
@csrf.exempt
def tiktok_analytics_videos_endpoint():
    user_id = _current_user_id()
    if not user_id:
        return jsonify({"ok": False, "error": "Login required."}), 401
    result = get_tiktok_video_insights(user_id)
    return jsonify(result), (200 if result.get("ok") else 502)


# ===========================================================
# STAGE 30: INSTAGRAM REELS/STORIES — same Graph API + facebook_pages
# credentials as the existing Instagram image-post flow; just a
# different media_type + video_url instead of image_url. Not a new
# BYOK provider — it reuses facebook_pages.
# ===========================================================

def post_instagram_video(user_id, video_url: str, caption: str = "", media_type: str = "REELS") -> dict:
    """media_type: 'REELS' or 'STORIES'. Two-step Graph API flow same as
    post_to_instagram: create a media container, poll until it's
    finished processing, then publish it."""
    creds = _facebook_creds_for_user(user_id)
    ig_id = creds["instagram_business_id"]
    if not ig_id or not creds["page_access_token"]:
        return {"ok": False, "error": "Instagram is not configured. Add your Instagram Business Account ID under Integrations."}
    if not video_url:
        return {"ok": False, "error": "'video_url' is required."}
    media_type = media_type.upper() if media_type.upper() in ("REELS", "STORIES") else "REELS"
    try:
        create_payload = {
            "video_url": video_url, "media_type": media_type,
            "access_token": creds["page_access_token"],
        }
        if media_type == "REELS" and caption:
            create_payload["caption"] = caption
        create_r = requests.post(
            f"https://graph.facebook.com/{FACEBOOK_GRAPH_API_VERSION}/{ig_id}/media",
            data=create_payload, timeout=30,
        )
        create_body = create_r.json()
        if create_r.status_code >= 400:
            return {"ok": False, "error": (create_body.get("error") or {}).get("message", "Could not create Instagram video media.")}
        creation_id = create_body.get("id")

        # Video processing is async — poll status_code before publishing.
        for _ in range(10):
            status_r = requests.get(
                f"https://graph.facebook.com/{FACEBOOK_GRAPH_API_VERSION}/{creation_id}",
                params={"fields": "status_code", "access_token": creds["page_access_token"]}, timeout=15,
            )
            status = (status_r.json() or {}).get("status_code")
            if status == "FINISHED":
                break
            if status == "ERROR":
                return {"ok": False, "error": "Instagram video processing failed."}
            time.sleep(3)

        publish_r = requests.post(
            f"https://graph.facebook.com/{FACEBOOK_GRAPH_API_VERSION}/{ig_id}/media_publish",
            data={"creation_id": creation_id, "access_token": creds["page_access_token"]}, timeout=20,
        )
        publish_body = publish_r.json()
        if publish_r.status_code >= 400:
            return {"ok": False, "error": (publish_body.get("error") or {}).get("message", "Could not publish to Instagram.")}
        return {"ok": True, "media_id": publish_body.get("id"), "media_type": media_type}
    except Exception as e:
        logging.error(f"[INSTAGRAM VIDEO ERROR] user={user_id}: {e}")
        return {"ok": False, "error": str(e)}


