# ===========================================================
# STAGE 31: FACEBOOK PAGE + INSTAGRAM INSIGHTS — read-only performance
# metrics, reusing the facebook_pages token (no new provider). Ads
# Insights/Ads Management are NOT wired up here — Meta requires Business
# Verification for ads access, which is an account-level review process
# outside this codebase, not a one-key BYOK integration.
# ===========================================================

def get_facebook_page_insights(user_id, metrics: str = "page_impressions,page_engaged_users,page_fans") -> dict:
    creds = _facebook_creds_for_user(user_id)
    if not creds["page_id"] or not creds["page_access_token"]:
        return {"ok": False, "error": "Facebook Page is not configured."}
    try:
        r = requests.get(
            f"https://graph.facebook.com/{FACEBOOK_GRAPH_API_VERSION}/{creds['page_id']}/insights",
            params={"metric": metrics, "period": "day", "access_token": creds["page_access_token"]}, timeout=15,
        )
        body = r.json()
        if r.status_code >= 400:
            return {"ok": False, "error": (body.get("error") or {}).get("message", "Could not load Page insights.")}
        parsed = {}
        for item in body.get("data", []):
            values = item.get("values", [])
            parsed[item.get("name")] = values[-1].get("value") if values else None
        return {"ok": True, "insights": parsed}
    except Exception as e:
        logging.error(f"[FACEBOOK INSIGHTS ERROR] user={user_id}: {e}")
        return {"ok": False, "error": str(e)}


def get_instagram_insights(user_id, metrics: str = "impressions,reach,profile_views") -> dict:
    creds = _facebook_creds_for_user(user_id)
