# ════════════════════════════════════════════════════════════
# STAGE 32: GOOGLE FORMS — real per-user OAuth, reusing the same
# GoogleOAuthToken row as Calendar/Gmail (see google_auth_url /
# google_oauth_callback above; call with ?service=forms). Lets a user
# create a form with questions, fetch its structure + live link, list
# their forms, and pull back responses. Like Gmail, forms.body /
# forms.responses.readonly are "sensitive" scopes — fine for up to 100
# named test users in Google's "Testing" publishing status, but a fully
# public launch needs Google's verification review, same as Gmail.
# ════════════════════════════════════════════════════════════

_FORMS_REQUIRED_SCOPE = "forms.body"
_FORMS_API_BASE       = "https://forms.googleapis.com/v1/forms"
_DRIVE_FILES_API_BASE = "https://www.googleapis.com/drive/v3/files"


def _forms_headers(user_id):
    token = get_valid_google_token(user_id, required_scope=_FORMS_REQUIRED_SCOPE)
    if not token:
        return None
    return {"Authorization": f"Bearer {token}", "Content-Type": "application/json"}


@app.route("/api/googleforms/check_auth_status", methods=["GET"])
@csrf.exempt
def google_forms_check_auth():
    user = _get_current_user()
    if not user:
        return jsonify({"authenticated": False}), 200
    token = get_valid_google_token(user["id"], required_scope=_FORMS_REQUIRED_SCOPE)
    return jsonify({"authenticated": bool(token)}), 200


def _forms_question_item(q: dict, index: int) -> dict:
    """Maps a simplified {title, type, options, required} dict from the
    frontend into a Google Forms API 'Item' object. Supported types:
    short_answer, paragraph, multiple_choice, checkboxes, dropdown."""
    qtype    = (q.get("type") or "short_answer").lower()
    required = bool(q.get("required", False))
    title    = q.get("title") or f"Question {index + 1}"
    options  = q.get("options") or []

    if qtype == "paragraph":
        question = {"required": required, "textQuestion": {"paragraph": True}}
    elif qtype in ("multiple_choice", "checkboxes", "dropdown"):
        choice_type = {"multiple_choice": "RADIO", "checkboxes": "CHECKBOX",
                       "dropdown": "DROP_DOWN"}[qtype]
        question = {
            "required": required,
            "choiceQuestion": {
                "type": choice_type,
                "options": [{"value": str(opt)} for opt in options] or [{"value": "Option 1"}],
            },
        }
    else:  # short_answer / fallback
        question = {"required": required, "textQuestion": {"paragraph": False}}

    return {"title": title, "questionItem": {"question": question}}


def create_google_form(user_id, title: str, description: str = "", questions: list | None = None) -> dict:
    headers = _forms_headers(user_id)
    if not headers:
        return {"ok": False, "error": "Not connected to Google Forms."}
    try:
        resp = requests.post(_FORMS_API_BASE, headers=headers,
                              json={"info": {"title": title or "Untitled form"}}, timeout=15)
        if resp.status_code >= 400:
            logging.error(f"[GOOGLE FORMS CREATE ERROR] {resp.text}")
            return {"ok": False, "error": "Could not create the form."}
        form    = resp.json()
        form_id = form["formId"]

        batch = []
        if description:
            batch.append({
                "updateFormInfo": {
                    "info": {"description": description},
                    "updateMask": "description",
                }
            })
        for i, q in enumerate(questions or []):
            batch.append({
                "createItem": {
                    "item": _forms_question_item(q, i),
                    "location": {"index": i},
                }
            })
        if batch:
            bu = requests.post(f"{_FORMS_API_BASE}/{form_id}:batchUpdate", headers=headers,
                                json={"requests": batch}, timeout=15)
            if bu.status_code >= 400:
                logging.error(f"[GOOGLE FORMS BATCHUPDATE ERROR] {bu.text}")

        return {
            "ok":            True,
            "form_id":       form_id,
            "responder_uri": form.get("responderUri"),
            "edit_uri":      f"https://docs.google.com/forms/d/{form_id}/edit",
        }
    except Exception as e:
        logging.error(f"[GOOGLE FORMS CREATE EXCEPTION] user={user_id}: {e}")
        return {"ok": False, "error": str(e)}


@app.route("/api/googleforms/create", methods=["POST"])
@csrf.exempt
def google_forms_create_endpoint():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user_id = _current_user_id()
    if not user_id:
        return jsonify({"ok": False, "error": "Login required."}), 401
    data = request.get_json(force=True, silent=True) or {}
    result = create_google_form(
        user_id,
        (data.get("title") or "").strip(),
        description=(data.get("description") or "").strip(),
        questions=data.get("questions") or [],
    )
    return jsonify(result), (201 if result.get("ok") else 502)


def list_google_forms(user_id) -> dict:
    """The Forms API has no 'list my forms' endpoint, so this goes
    through Drive (drive.metadata.readonly) filtering for Forms mime
    type."""
    headers = _forms_headers(user_id)
    if not headers:
        return {"ok": False, "error": "Not connected to Google Forms."}
    try:
        resp = requests.get(_DRIVE_FILES_API_BASE, headers=headers, params={
            "q":        "mimeType='application/vnd.google-apps.form' and trashed=false",
            "fields":   "files(id,name,createdTime,modifiedTime)",
            "orderBy":  "modifiedTime desc",
            "pageSize": 50,
        }, timeout=15)
        if resp.status_code >= 400:
            logging.error(f"[GOOGLE FORMS LIST ERROR] {resp.text}")
            return {"ok": False, "error": "Could not list your forms."}
        files = resp.json().get("files", [])
        return {"ok": True, "forms": [
            {
                "form_id":  f["id"],
                "title":    f.get("name"),
                "created":  f.get("createdTime"),
                "modified": f.get("modifiedTime"),
                "edit_uri": f"https://docs.google.com/forms/d/{f['id']}/edit",
            }
            for f in files
        ]}
    except Exception as e:
        logging.error(f"[GOOGLE FORMS LIST EXCEPTION] user={user_id}: {e}")
        return {"ok": False, "error": str(e)}


@app.route("/api/googleforms/list", methods=["GET"])
@csrf.exempt
def google_forms_list_endpoint():
    user_id = _current_user_id()
    if not user_id:
        return jsonify({"ok": False, "error": "Login required."}), 401
    result = list_google_forms(user_id)
    return jsonify(result), (200 if result.get("ok") else 502)


