@csrf.exempt
def google_forms_get_endpoint(form_id):
    user_id = _current_user_id()
    if not user_id:
        return jsonify({"ok": False, "error": "Login required."}), 401
    headers = _forms_headers(user_id)
    if not headers:
        return jsonify({"ok": False, "error": "Not connected to Google Forms."}), 400
    try:
        resp = requests.get(f"{_FORMS_API_BASE}/{form_id}", headers=headers, timeout=15)
        if resp.status_code >= 400:
            logging.error(f"[GOOGLE FORMS GET ERROR] {resp.text}")
            return jsonify({"ok": False, "error": "Could not load the form."}), 502
        return jsonify({"ok": True, "form": resp.json()}), 200
    except Exception as e:
        logging.error(f"[GOOGLE FORMS GET EXCEPTION] user={user_id}: {e}")
        return jsonify({"ok": False, "error": str(e)}), 502


