# STAGE 48: WORLD BANK OPEN DATA
# Free, no key. Two endpoints: a general per-country/indicator lookup
# (economic content, business-advice grounding), and a real fix for
# the Agriculture Assistant's commodity-price stub below, which
# previously fetched the World Bank Pink Sheet index and then threw
# the response away — it now returns actual per-commodity prices.
# ════════════════════════════════════════════════════════════

WORLD_BANK_BASE = "https://api.worldbank.org/v2"

@app.route("/api/worldbank/indicator/<country_code>/<indicator_code>", methods=["GET"])
@csrf.exempt
def worldbank_indicator(country_code, indicator_code):
    """Fetches a World Bank indicator series for one country (ISO2/ISO3,
    or 'all'). Common indicators: NY.GDP.MKTP.CD (GDP), FP.CPI.TOTL.ZG
    (inflation), SL.UEM.TOTL.ZS (unemployment). Full catalog:
    https://data.worldbank.org/indicator"""
    try:
        resp = requests.get(
            f"{WORLD_BANK_BASE}/country/{country_code}/indicator/{indicator_code}",
            params={"format": "json", "per_page": 20, "mrnev": 10}, timeout=12,
        )
        if resp.status_code != 200:
            return jsonify({"ok": False, "error": f"World Bank error: {resp.text[:200]}"}), 502
        body = resp.json()
        rows = body[1] if isinstance(body, list) and len(body) > 1 and body[1] else []
        points = [{"country": r.get("country", {}).get("value"), "year": r.get("date"),
                    "value": r.get("value")} for r in rows if r.get("value") is not None]
        return jsonify({"ok": True, "indicator": indicator_code, "points": points})
    except Exception as e:
        logging.error(f"[WORLD BANK ERROR] {e}")
        return jsonify({"ok": False, "error": str(e)}), 500


# World Bank Pink Sheet commodity indicator codes, keyed by the crop/
# commodity names the Agriculture Assistant panel already uses.
_WORLD_BANK_COMMODITY_INDICATORS = {
    "maize":   "PMAIZMT",
    "wheat":   "PWHEAMT",
    "rice":    "PRICENPQ",
    "soybean": "PSOYB",
    "sugar":   "PSUGAISA",
    "coffee":  "PCOFFOTM",
    "cotton":  "PCOTTIND",
    "cocoa":   "PCOCO",
}

def _fetch_world_bank_commodity_prices() -> list:
    """Real replacement for the old dead-end stub: fetches the latest
    published price for each tracked commodity from the World Bank's
    monthly Pink Sheet indicators, no key needed."""
    out = []
    for crop, code in _WORLD_BANK_COMMODITY_INDICATORS.items():
        try:
            resp = requests.get(
                f"{WORLD_BANK_BASE}/country/all/indicator/{code}",
                params={"format": "json", "per_page": 1, "mrnev": 1}, timeout=8,
            )
            if not resp.ok:
                continue
            body = resp.json()
            rows = body[1] if isinstance(body, list) and len(body) > 1 and body[1] else []
            if rows and rows[0].get("value") is not None:
                out.append({"crop": crop, "price": rows[0]["value"], "period": rows[0].get("date"),
                             "source": "World Bank Pink Sheet"})
        except Exception as e:
            logging.warning(f"[WORLD BANK COMMODITY {crop}] {e}")
    return out


