def _nasa_api_key_for_user(user_id) -> str:
    if user_id:
        return get_effective_credential(user_id, "nasa", "api_key", NASA_API_KEY) or NASA_API_KEY
    return NASA_API_KEY


@app.route("/api/nasa/apod", methods=["GET"])
@csrf.exempt
def nasa_apod():
    """Astronomy Picture of the Day — a real photo/illustration with a
    short expert-written explanation. ?date=YYYY-MM-DD for a specific
    day, otherwise today's."""
    user_id = _current_user_id()
    api_key = _nasa_api_key_for_user(user_id)
    params = {"api_key": api_key}
    date = request.args.get("date")
    if date:
        params["date"] = date
    try:
        resp = requests.get("https://api.nasa.gov/planetary/apod", params=params, timeout=12)
        if resp.status_code != 200:
            return jsonify({"ok": False, "error": f"NASA API error: {resp.text[:200]}"}), 502
        d = resp.json()
        return jsonify({"ok": True, "title": d.get("title"), "date": d.get("date"),
                         "explanation": d.get("explanation"), "image_url": d.get("url"),
                         "hd_image_url": d.get("hdurl"), "media_type": d.get("media_type")})
    except Exception as e:
        logging.error(f"[NASA APOD ERROR] {e}")
        return jsonify({"ok": False, "error": str(e)}), 500


@app.route("/api/nasa/image-search", methods=["GET"])
@csrf.exempt
def nasa_image_search():
    """Searches NASA's public image/video library (nasa.gov imagery,
    not the DEMO_KEY-limited planetary APIs — this endpoint needs no
    key at all)."""
    q = (request.args.get("q") or "").strip()
    if not q:
        return jsonify({"ok": False, "error": "q is required."}), 400
    try:
        resp = requests.get("https://images-api.nasa.gov/search",
                             params={"q": q, "media_type": "image"}, timeout=12)
        if resp.status_code != 200:
            return jsonify({"ok": False, "error": f"NASA image search error: {resp.text[:200]}"}), 502
        items = []
        for item in resp.json().get("collection", {}).get("items", [])[:12]:
            data = (item.get("data") or [{}])[0]
            links = item.get("links") or []
            items.append({"title": data.get("title"), "description": data.get("description_508") or data.get("description"),
                           "date": data.get("date_created"), "thumbnail": links[0].get("href") if links else None})
        return jsonify({"ok": True, "results": items})
    except Exception as e:
        logging.error(f"[NASA IMAGE SEARCH ERROR] {e}")
        return jsonify({"ok": False, "error": str(e)}), 500


