# STAGE 51: E-SIGNATURE CAPTURE
# Built-in signature pad + PDF stamping for contracts/invoices/quotes,
# no DocuSign dependency. Uses reportlab (overlay) + PyPDF2 (merge),
# both already available elsewhere in this file.
# ════════════════════════════════════════════════════════════

@app.route("/api/esign/capture", methods=["POST"])
@csrf.exempt
def esign_capture():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    signer_name   = (data.get("signer_name") or "").strip()
    document_name = (data.get("document_name") or "").strip()
    signature_png = data.get("signature_png") or ""  # base64 data-URL or raw base64
    if not signer_name or not signature_png:
        return jsonify({"error": "signer_name and signature_png are required."}), 400
    try:
        rec = SignatureRecord(
            user_id=user["id"], signer_name=signer_name[:200],
            document_name=document_name[:200] or None, signature_png=signature_png,
        )
        db.session.add(rec)
        db.session.commit()
        return jsonify({"signature": rec.to_dict()}), 201
    except Exception as e:
        db.session.rollback()
        return jsonify({"error": str(e)}), 500


@app.route("/api/esign/list", methods=["GET"])
def esign_list():
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    rows = (SignatureRecord.query.filter_by(user_id=user["id"])
            .order_by(SignatureRecord.created_at.desc()).limit(100).all())
    return jsonify({"signatures": [r.to_dict() for r in rows]}), 200


@app.route("/api/esign/stamp-pdf", methods=["POST"])
@csrf.exempt
def esign_stamp_pdf():
    """Stamps a captured signature image onto an existing PDF (e.g. an
    invoice/quote/contract already generated elsewhere in Connect It)."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    if not REPORTLAB_AVAILABLE:
        return jsonify({"error": "reportlab is not installed on the server."}), 503
    data = request.get_json(silent=True) or {}
    pdf_b64       = data.get("pdf_base64") or ""
    signature_id  = data.get("signature_id")
    signature_png = data.get("signature_png") or ""
    page_index    = int(data.get("page_index", 0) or 0)
    x, y          = float(data.get("x", 60)), float(data.get("y", 60))
    width, height = float(data.get("width", 160)), float(data.get("height", 60))
    if not pdf_b64:
        return jsonify({"error": "pdf_base64 is required."}), 400
    if signature_id and not signature_png:
        rec = SignatureRecord.query.filter_by(id=signature_id, user_id=user["id"]).first()
        if not rec:
            return jsonify({"error": "signature_id not found."}), 404
        signature_png = rec.signature_png
    if not signature_png:
        return jsonify({"error": "signature_png or signature_id is required."}), 400
    try:
        import io as _io
        from PyPDF2 import PdfReader as _PdfReader, PdfWriter as _PdfWriter
        raw_sig = signature_png.split(",", 1)[1] if "," in signature_png[:40] else signature_png
        sig_bytes = base64.b64decode(raw_sig)
        src_bytes = base64.b64decode(pdf_b64)
        reader = _PdfReader(_io.BytesIO(src_bytes))
        page_size = reader.pages[page_index].mediabox
        page_w, page_h = float(page_size.width), float(page_size.height)

        from reportlab.lib.utils import ImageReader as _ImageReader
        overlay_buf = _io.BytesIO()
        c = canvas.Canvas(overlay_buf, pagesize=(page_w, page_h))
        img_reader = _ImageReader(_io.BytesIO(sig_bytes))
        c.drawImage(img_reader, x, y, width=width, height=height, mask='auto')
        c.save()
        overlay_buf.seek(0)
        overlay_reader = _PdfReader(overlay_buf)

        writer = _PdfWriter()
        for i, page in enumerate(reader.pages):
            if i == page_index:
                page.merge_page(overlay_reader.pages[0])
            writer.add_page(page)

        out_buf = _io.BytesIO()
        writer.write(out_buf)
        out_b64 = base64.b64encode(out_buf.getvalue()).decode("ascii")
        return jsonify({"ok": True, "pdf_base64": out_b64}), 200
    except Exception as e:
        logging.error(f"[ESIGN STAMP PDF ERROR] {e}")
        return jsonify({"error": str(e)}), 500


