# STAGE 52: INVENTORY LOW-STOCK ALERTS
# Extends the existing Inventory Manager (InventoryItem already has a
# `threshold` column) with a dedicated low-stock query and an optional
# push notification over the user's already-connected WhatsApp/SMS.
# ════════════════════════════════════════════════════════════

@app.route("/api/inventory/low-stock", methods=["GET"])
def inventory_low_stock():
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    items = (InventoryItem.query.filter_by(user_id=user["id"])
             .filter(InventoryItem.quantity <= InventoryItem.threshold).all())
    return jsonify({"low_stock_items": [i.to_dict() for i in items]}), 200


@app.route("/api/inventory/low-stock/notify", methods=["POST"])
@csrf.exempt
def inventory_low_stock_notify():
    """Sends a single WhatsApp (or SMS) alert listing all items currently
    at/under their reorder threshold."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    data    = request.get_json(silent=True) or {}
    channel = (data.get("channel") or "whatsapp").lower()
    contact = (data.get("contact") or "").strip()
    if not contact:
        return jsonify({"error": "contact is required."}), 400
    items = (InventoryItem.query.filter_by(user_id=user["id"])
             .filter(InventoryItem.quantity <= InventoryItem.threshold).all())
    if not items:
        return jsonify({"ok": True, "sent": False, "message": "No items are currently low on stock."}), 200
    lines = [f"- {i.name}: {i.quantity} left (reorder at {i.threshold})" for i in items]
    text = "Connect It — Low Stock Alert:\n" + "\n".join(lines)
    try:
        if channel == "whatsapp":
            result = send_whatsapp_cloud_message(user["id"], contact, text)
        else:
            result = {"sent": _at_send_sms_simple(contact, text)}
        return jsonify({"ok": True, "sent": True, "items": [i.to_dict() for i in items], "result": result}), 200
    except Exception as e:
        return jsonify({"error": str(e)}), 500


# ════════════════════════════════════════════════════════════
# STAGE 53: COMPLIANCE / TAX DEADLINE REMINDERS
# A simple country-specific tax/compliance calendar with automated
# alerts pushed via WhatsApp, SMS, or email, and recurrence logic that
# rolls a deadline forward once its reminder has gone out.
#
# check-and-notify (below) only ever looks at the logged-in user's own
# deadlines, so on its own it's a manual "send now" button — it only
# becomes a genuinely *recurring* reminder once something calls it
# regularly without a person having to open the app. That's what the
# separate /api/cron/tax-deadlines endpoint is for: it sweeps every
# user's due deadlines in one pass, protected by CRON_SECRET instead of
# a login, so it's safe to trigger from an external scheduler (see the
# CRON_SECRET comment near the top of this file for the PythonAnywhere
# Scheduled Task setup — one daily curl call is all it takes).
# ════════════════════════════════════════════════════════════

def _send_plain_email(to_email: str, subject: str, body_text: str) -> bool:
    """Lightweight branded HTML email using the platform's own SMTP
    credentials — for system notifications (like this one) rather than
    a specific BYOK-connected provider."""
    if not SMTP_USER or not SMTP_PASS:
        logging.warning("SMTP not configured — skipping email.")
        return False
    html_body = f"""
    <!DOCTYPE html><html><body style="font-family:Arial,sans-serif;background:#f1f5f9;padding:30px;">
      <div style="max-width:520px;margin:0 auto;background:white;border-radius:16px;overflow:hidden;box-shadow:0 8px 32px rgba(0,0,0,0.1);">
        <div style="background:linear-gradient(90deg,#1e3a8a,#2563eb);padding:24px;text-align:center;">
          <h1 style="color:white;margin:0;font-size:1.4rem;"> Connect It</h1>
        </div>
        <div style="padding:28px;">
          <p style="color:#1e293b;white-space:pre-line;line-height:1.7;">{body_text}</p>
        </div>
        <div style="background:#f8fafc;padding:14px;text-align:center;font-size:0.72rem;color:#9ca3af;">
          © 2025 Connect It
        </div>
      </div>
    </body></html>
    """
    try:
        msg = MIMEMultipart("alternative")
        msg["Subject"] = subject
        msg["From"]    = SMTP_FROM
        msg["To"]      = to_email
        msg.attach(MIMEText(html_body, "html"))
        with smtplib.SMTP(SMTP_HOST, SMTP_PORT, timeout=15) as server:
            server.ehlo(); server.starttls(); server.login(SMTP_USER, SMTP_PASS)
            server.sendmail(SMTP_USER, to_email, msg.as_string())
        return True
    except Exception as e:
        logging.error(f"[TAX DEADLINE EMAIL ERROR] {to_email}: {e}")
        return False


def _tax_deadline_notify_row(row) -> bool:
    """Sends one reminder over row's saved channel, rolls recurrence
    forward, and stamps last_notified. Returns True if a send was
    attempted (regardless of whether it actually succeeded — a failed
    send still shouldn't be retried every minute)."""
    if not row.contact:
        return False
    text = f"Connect It — Compliance Reminder: '{row.label}' ({row.country}) is due {row.due_date.isoformat()}."
    try:
        if row.channel == "whatsapp":
            send_whatsapp_cloud_message(row.user_id, row.contact, text)
        elif row.channel == "email":
            _send_plain_email(row.contact, f"Compliance Reminder: {row.label} due {row.due_date.isoformat()}", text)
        else:
            _at_send_sms_simple(row.contact, text)
        row.last_notified = datetime.utcnow().date()
        if row.recurrence == "monthly":
            row.due_date = row.due_date + timedelta(days=30)
        elif row.recurrence == "quarterly":
            row.due_date = row.due_date + timedelta(days=91)
        elif row.recurrence == "annual":
            row.due_date = row.due_date + timedelta(days=365)
        return True
    except Exception as e:
        logging.error(f"[TAX DEADLINE NOTIFY ERROR] deadline={row.id}: {e}")
        return False


