@app.route("/api/tax/deadlines/<int:deadline_id>/renew", methods=["POST"])
@csrf.exempt
def tax_deadlines_renew(deadline_id):
    """Real proof-of-renewal, independent of whether a reminder ever
    fired: the user confirms they actually renewed this, optionally
    with the real reference number they got back, and (for recurring
    deadlines) the due date advances from today — the actual renewal
    date — rather than staying pinned to whatever the old schedule
    said. Nothing here invents a due date; the recurrence interval is
    exactly what the user already set on the deadline itself."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    row = TaxDeadline.query.filter_by(id=deadline_id, user_id=user["id"]).first()
    if not row:
        return jsonify({"error": "Not found."}), 404
    data = request.get_json(silent=True) or {}
    today = datetime.utcnow().date()
    previous_due = row.due_date
    new_due = None
    if row.recurrence == "monthly":
        new_due = today + timedelta(days=30)
    elif row.recurrence == "quarterly":
        new_due = today + timedelta(days=91)
    elif row.recurrence == "annual":
        new_due = today + timedelta(days=365)
    log = DeadlineRenewalLog(
        deadline_id=row.id, user_id=user["id"],
        reference_number=(data.get("reference_number") or "").strip()[:120] or None,
        renewed_on=today, previous_due_date=previous_due, new_due_date=new_due,
        note=(data.get("note") or "").strip()[:500] or None,
    )
    db.session.add(log)
    if new_due:
        row.due_date = new_due
    row.last_notified = None  # a real renewal just happened; a stale reminder shouldn't fire again until the new date approaches
    db.session.commit()
    return jsonify({"ok": True, "deadline": row.to_dict(), "log": log.to_dict()}), 200


