@app.route("/api/tax/deadlines/check-and-notify", methods=["POST"])
@csrf.exempt
def tax_deadlines_check_and_notify():
    """Manual 'send now' for the logged-in user: finds their deadlines
    due within the next N days (default 7) that haven't already been
    notified today, sends a reminder over the saved channel (WhatsApp,
    SMS, or email), and rolls recurring deadlines forward. For reminders
    that fire on their own without anyone opening the app, see
    /api/cron/tax-deadlines below."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    window_days = int(data.get("window_days", 7) or 7)
    today = datetime.utcnow().date()
    horizon = today + timedelta(days=window_days)
    rows = (TaxDeadline.query.filter_by(user_id=user["id"])
            .filter(TaxDeadline.due_date <= horizon)
            .filter((TaxDeadline.last_notified.is_(None)) | (TaxDeadline.last_notified < today))
            .all())
    notified = [row.label for row in rows if _tax_deadline_notify_row(row)]
    db.session.commit()
    return jsonify({"ok": True, "notified": notified}), 200


@app.route("/api/cron/tax-deadlines", methods=["POST"])
@csrf.exempt
def cron_tax_deadlines():
    """System-wide sweep across EVERY user's due tax/compliance
    deadlines — this is what makes reminders actually recurring instead
    of a button someone has to remember to press. No login; guarded by
    CRON_SECRET (see the constant's comment near the top of this file
    for how to point a PythonAnywhere Scheduled Task at this daily)."""
    if not CRON_SECRET or request.headers.get("X-Cron-Secret") != CRON_SECRET:
        return jsonify({"error": "Forbidden."}), 403
    window_days = int((request.get_json(silent=True) or {}).get("window_days", 3) or 3)
    today = datetime.utcnow().date()
    horizon = today + timedelta(days=window_days)
    rows = (TaxDeadline.query
            .filter(TaxDeadline.due_date <= horizon)
            .filter((TaxDeadline.last_notified.is_(None)) | (TaxDeadline.last_notified < today))
            .all())
    notified = 0
    for row in rows:
        if _tax_deadline_notify_row(row):
            notified += 1
    db.session.commit()
    logging.info(f"[CRON TAX DEADLINES] swept {len(rows)} due, sent {notified}")
    return jsonify({"ok": True, "checked": len(rows), "notified": notified}), 200


