# STAGE 54: VOICE / IVR BOT (Twilio Voice)
# Lets feature-phone users call in and interact with Connect It by
# voice — no app or data needed. Mirrors the existing USSD menu tree
# via _ussd_menu_for_user / _ussd_walk so both channels share one menu.
# ════════════════════════════════════════════════════════════

@app.route("/api/ivr/voice", methods=["POST"])
@csrf.exempt
def ivr_voice_entry():
    """Twilio Voice webhook — answers the call and reads the top-level
    menu, gathering DTMF digits for the next step."""
    from twilio.twiml.voice_response import VoiceResponse, Gather
    resp = VoiceResponse()
    gather = Gather(num_digits=1, action="/api/ivr/gather", method="POST", timeout=8)
    gather.say("Welcome to Connect It A I. Press 1 for business hours. "
                "Press 2 to speak your question after the beep. Press 0 to repeat this menu.")
    resp.append(gather)
    resp.redirect("/api/ivr/voice")
    return Response(str(resp), mimetype="text/xml")


@app.route("/api/ivr/gather", methods=["POST"])
@csrf.exempt
def ivr_gather():
    from twilio.twiml.voice_response import VoiceResponse
    digit = request.values.get("Digits", "")
    resp = VoiceResponse()
    if digit == "1":
        resp.say("Connect It A I business hours are Monday to Friday, 8 A M to 5 P M.")
        resp.redirect("/api/ivr/voice")
    elif digit == "2":
        resp.say("Please ask your question after the beep, then stay on the line.")
        resp.record(max_length=20, action="/api/ivr/transcribe", play_beep=True)
    else:
        resp.redirect("/api/ivr/voice")
    return Response(str(resp), mimetype="text/xml")


@app.route("/api/ivr/transcribe", methods=["POST"])
@csrf.exempt
def ivr_transcribe():
    """Receives the recorded question, asks the AI, and reads the
    answer back over the call."""
    from twilio.twiml.voice_response import VoiceResponse
    recording_text = request.values.get("TranscriptionText", "")
    resp = VoiceResponse()
    if recording_text:
        try:
            answer, _ = generate_ai_reply(
                "You are Connect It answering a phone caller out loud. "
                "Keep the answer under 50 words, plain spoken language: " + recording_text, [])
        except Exception:
            answer = "Sorry, I couldn't process that right now."
        resp.say(answer or "Sorry, I couldn't process that right now.")
    else:
        resp.say("Sorry, I didn't catch a question. Goodbye.")
    resp.hangup()
    return Response(str(resp), mimetype="text/xml")


