@app.route("/api/reliefweb/check-and-push", methods=["POST"])
@csrf.exempt
def reliefweb_check_and_push():
    """For every subscription, fetches the latest ReliefWeb report for
    that country and pushes it if it's newer than the last one sent."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    subs = DisasterSubscription.query.filter_by(user_id=user["id"]).all()
    pushed = []
    for sub in subs:
        try:
            resp = requests.post(
                "https://api.reliefweb.int/v1/reports",
                json={"appname": "connectit-ai", "limit": 1,
                      "fields": {"include": ["title", "url", "date.created"]},
                      "sort": ["date.created:desc"],
                      "filter": {"field": "country", "value": sub.country}},
                timeout=12,
            )
            if resp.status_code != 200:
                continue
            items = resp.json().get("data", [])
            if not items:
                continue
            f = items[0].get("fields", {})
            url = f.get("url")
            if not url or url == sub.last_sent_report_url:
                continue
            text = f"Connect It Early Warning ({sub.country}): {f.get('title')}\n{url}"
            if sub.channel == "telegram":
                send_telegram_message(user["id"], sub.contact, text)
            else:
                send_whatsapp_cloud_message(user["id"], sub.contact, text)
            sub.last_sent_report_url = url
            pushed.append({"country": sub.country, "title": f.get("title")})
        except Exception as e:
            logging.error(f"[RELIEFWEB PUSH ERROR] {e}")
    db.session.commit()
    return jsonify({"ok": True, "pushed": pushed}), 200


