def _get_or_create_referral_code(user_id: int) -> str:
    row = ReferralCode.query.filter_by(user_id=user_id).first()
    if row:
        return row.code
    code = ("RJ" + secrets.token_hex(4)).upper()
    while ReferralCode.query.filter_by(code=code).first():
        code = ("RJ" + secrets.token_hex(4)).upper()
    row = ReferralCode(user_id=user_id, code=code)
    db.session.add(row)
    db.session.commit()
    return code


@app.route("/api/referral/me", methods=["GET"])
def referral_me():
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    code = _get_or_create_referral_code(user["id"])
    rows = Referral.query.filter_by(referrer_user_id=user["id"]).all()
    total_credits = sum(r.credits_awarded for r in rows)
    return jsonify({
        "code": code,
        "referral_url": request.host_url.rstrip("/") + "/?ref=" + code,
        "referrals_count": len(rows),
        "converted_count": sum(1 for r in rows if r.status == "converted"),
        "credits": total_credits,
    }), 200


