# ---- Badges ----
# Each definition's check() runs against real, server-tracked usage —
# not a client-side counter — so a badge earned here reflects something
# the user actually did.
def _badge_definitions():
    return [
        {"id": "first_signature", "name": "First Signature", "icon": "",
         "check": lambda uid: SignatureRecord.query.filter_by(user_id=uid).count() >= 1},
        {"id": "inventory_master", "name": "Inventory Master", "icon": "",
         "check": lambda uid: InventoryItem.query.filter_by(user_id=uid).count() >= 10},
        {"id": "community_organiser", "name": "Community Organiser", "icon": "",
         "check": lambda uid: VolunteerTask.query.filter_by(user_id=uid).count() >= 1},
        {"id": "early_warning_ready", "name": "Early Warning Ready", "icon": "",
         "check": lambda uid: DisasterSubscription.query.filter_by(user_id=uid).count() >= 1},
        {"id": "compliance_conscious", "name": "Compliance Conscious", "icon": "",
         "check": lambda uid: TaxDeadline.query.filter_by(user_id=uid).count() >= 1},
        {"id": "referral_starter", "name": "Referral Starter", "icon": "",
         "check": lambda uid: Referral.query.filter_by(referrer_user_id=uid).count() >= 1},
        {"id": "referral_champion", "name": "Referral Champion", "icon": "",
         "check": lambda uid: Referral.query.filter_by(referrer_user_id=uid).count() >= 5},
        {"id": "builder", "name": "Builder", "icon": "",
         "check": lambda uid: UserMemory.query.filter_by(user_id=uid).filter(UserMemory.deleted_at.is_(None)).count() >= 25},
    ]


