@app.route("/api/buyer-reputation/public/<token>", methods=["GET"])
def buyer_reputation_public(token):
    """No login required — what a new supplier or lender opens from the
    shared link. Same restraint as the Trust Score public view: score,
    grade, and category weights only, no raw order or contact data."""
    share = BuyerReputationShare.query.filter_by(token=token).first()
    if not share or share.revoked:
        return jsonify({"error": "This link is invalid or has been revoked."}), 404
    if share.expires_at and datetime.utcnow() > share.expires_at:
        return jsonify({"error": "This link has expired."}), 410
    owner = UserAccount.query.get(share.user_id)
    if not owner:
        return jsonify({"error": "Account not found."}), 404
    result = compute_buyer_reputation(share.user_id)
    return jsonify({
        "name": owner.name,
        "score": result["score"],
        "grade": result["grade"],
        "categories": {k: {"label": v["label"], "score": v["score"], "max": v["max"]}
                        for k, v in result["breakdown"].items()},
        "computed_at": result["computed_at"],
        "label": share.label,
        "powered_by": "Connect It Buyer Reputation",
    }), 200


# ════════════════════════════════════════════════════════════
# STAGE 93: BUSINESS PASSPORT — ROUTES
# ════════════════════════════════════════════════════════════

def compute_business_passport(user_id: int) -> dict:
    """Aggregates real, already-tracked platform activity into one
    portable summary. Every figure here is computed from data that
    already exists elsewhere on the platform (Trust Score, confirmed
    Deals, Deal Reviews, warranty/return records) — nothing new is
    invented or self-reported for this view."""
    user  = UserAccount.query.get(user_id)
    trust = compute_trust_score(user_id)

    deals = (DealConfirmation.query
             .filter(db.or_(DealConfirmation.party_a_id == user_id,
                            DealConfirmation.party_b_id == user_id))
             .filter(DealConfirmation.status == "confirmed").all())

    reviews      = DealReview.query.filter_by(reviewee_id=user_id).all()
    review_count = len(reviews)
    avg_rating   = round(sum(r.rating for r in reviews) / review_count, 2) if review_count else None

    warranties       = WarrantyRecord.query.filter_by(owner_id=user_id).all()
    claims           = ReturnClaim.query.filter_by(owner_id=user_id).all()
    resolved_claims  = [c for c in claims if c.status == "resolved"]
    claim_resolution_rate = round(len(resolved_claims) / len(claims) * 100, 1) if claims else None

    return {
        "business_name":         user.name if user else None,
        "member_since":          user.created_at.isoformat() if user and user.created_at else None,
        "months_on_platform":    trust["breakdown"]["account_tenure"]["months_on_platform"],
        "trust_score":           trust["score"],
        "trust_grade":           trust["grade"],
        "completed_deals":       len(deals),
        "review_count":          review_count,
        "average_rating":        avg_rating,
        "warranties_issued":     len(warranties),
        "return_claims_total":   len(claims),
        "return_claims_resolved": len(resolved_claims),
        "claim_resolution_rate": claim_resolution_rate,
        "computed_at":           datetime.utcnow().isoformat(),
    }


