# NEXT-06: CAPITAL MARKETPLACE AUTO-MATCHER
# The LoanListing (peer-funded loans) and FactoringListing (invoice
# factoring) marketplaces already exist and already let any platform
# user — including diaspora investors — browse and fund a listing by
# hand. This turns that browsing into a ranked feed: an investor sets
# what they're actually looking for once, and this scores every open
# opportunity against it using the same Credit Score and cash-flow
# signals already computed elsewhere on the platform, instead of them
# scrolling every open listing themselves.
# ════════════════════════════════════════════════════════════

class CapitalInvestorPreference(db.Model):
    __tablename__  = "capital_investor_preferences"
    id             = db.Column(db.Integer, primary_key=True)
    owner_user_id  = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, unique=True, index=True)
    min_amount     = db.Column(db.Float,   nullable=False, default=0)
    max_amount     = db.Column(db.Float,   nullable=False, default=1000000)
    product_pref   = db.Column(db.String(16), nullable=False, default="both")  # loan, factoring, po_financing, both (both = all products)
    risk_appetite  = db.Column(db.String(12), nullable=False, default="medium")  # low, medium, high
    sector_pref    = db.Column(db.String(60), nullable=True)  # matches ErpCompanyProfile.industry, null/"any" = no preference
    updated_at     = db.Column(db.DateTime, default=datetime.utcnow, onupdate=datetime.utcnow)

    def to_dict(self):
        return {
            "min_amount": self.min_amount, "max_amount": self.max_amount, "product_pref": self.product_pref,
            "risk_appetite": self.risk_appetite, "sector_pref": self.sector_pref,
            "updated_at": self.updated_at.isoformat() if self.updated_at else None,
        }


RISK_APPETITE_MIN_SCORE = {"low": 700, "medium": 600, "high": 0}  # min 300-850 credit score an investor will accept


@app.route("/api/capital-marketplace/preferences", methods=["GET"])
def capital_marketplace_preferences_get():
    user, err = _erp_user_or_401()
    if err: return err
    row = CapitalInvestorPreference.query.filter_by(owner_user_id=user["id"]).first()
    return jsonify({"preferences": row.to_dict() if row else None}), 200


@app.route("/api/capital-marketplace/preferences", methods=["PUT"])
@csrf.exempt
def capital_marketplace_preferences_set():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    row = CapitalInvestorPreference.query.filter_by(owner_user_id=user["id"]).first()
    if not row:
        row = CapitalInvestorPreference(owner_user_id=user["id"])
        db.session.add(row)
    row.min_amount = float(data.get("min_amount", row.min_amount) or 0)
    row.max_amount = float(data.get("max_amount", row.max_amount) or 1000000)
    if data.get("product_pref") in ("loan", "factoring", "po_financing", "both"):
        row.product_pref = data["product_pref"]
    if data.get("risk_appetite") in ("low", "medium", "high"):
        row.risk_appetite = data["risk_appetite"]
    row.sector_pref = (data.get("sector_pref") or None)
    try:
        db.session.commit()
    except Exception as e:
        db.session.rollback(); logging.error(f"[CAPITAL PREFS SAVE] {e}")
        return jsonify({"error": "Could not save preferences."}), 500
    return jsonify({"preferences": row.to_dict()}), 200


def _capital_match_score(amount, min_amount, max_amount, borrower_score, min_score_threshold,
                          borrower_sector, sector_pref):
    reasons = []
    if min_amount <= amount <= max_amount:
        amount_fit = 1.0
    else:
        span = max((max_amount - min_amount), 1.0)
        distance = min(abs(amount - min_amount), abs(amount - max_amount))
        amount_fit = max(0.0, 1.0 - distance / span)
    if amount_fit < 0.99:
        reasons.append(f"Amount (${amount:,.0f}) is {'above' if amount > max_amount else 'below'} your usual range")

    if borrower_score is None:
        risk_fit = 0.5
        reasons.append("Borrower has insufficient history to score yet")
    elif borrower_score >= min_score_threshold:
        risk_fit = 1.0
        reasons.append(f"Credit score {borrower_score} meets your risk appetite")
    else:
        risk_fit = max(0.0, 1.0 - (min_score_threshold - borrower_score) / 300.0)
        reasons.append(f"Credit score {borrower_score} is below your usual threshold ({min_score_threshold})")

    if not sector_pref or sector_pref == "any":
        sector_fit = 0.8
    elif borrower_sector == sector_pref:
        sector_fit = 1.0
        reasons.append(f"Matches your preferred sector ({sector_pref})")
    else:
        sector_fit = 0.4

    score = round((amount_fit * 0.4 + risk_fit * 0.4 + sector_fit * 0.2) * 100, 1)
    return score, reasons


@app.route("/api/capital-marketplace/matches", methods=["GET"])
def capital_marketplace_matches():
    """Ranked open opportunities (peer-funded loan requests + invoice
    factoring listings) for the calling user as an investor, scored
    against their saved preferences (or sane defaults if they haven't
    set any yet)."""
    user, err = _erp_user_or_401()
    if err: return err
    uid = user["id"]
    prefs = CapitalInvestorPreference.query.filter_by(owner_user_id=uid).first()
    min_amount = prefs.min_amount if prefs else 0
    max_amount = prefs.max_amount if prefs else 1000000
    product_pref = prefs.product_pref if prefs else "both"
    risk_appetite = prefs.risk_appetite if prefs else "medium"
    sector_pref = prefs.sector_pref if prefs else None
    min_score_threshold = RISK_APPETITE_MIN_SCORE.get(risk_appetite, 600)

    matches = []

    if product_pref in ("loan", "both"):
        open_loans = LoanListing.query.filter_by(status="open").filter(LoanListing.borrower_user_id != uid).all()
        for loan in open_loans:
            already_funded = round(sum(f.amount_funded for f in LoanFunding.query.filter_by(loan_id=loan.id).all()), 2)
            remaining = round((loan.amount_requested or 0) - already_funded, 2)
            if remaining <= 0:
                continue
            profile = ErpCompanyProfile.query.filter_by(owner_user_id=loan.borrower_user_id).first()
            borrower_sector = profile.industry if profile else None
            try:
                borrower_score = compute_credit_score(loan.borrower_user_id).get("score")
            except Exception:
                borrower_score = loan.trust_score_snapshot
            score, reasons = _capital_match_score(remaining, min_amount, max_amount, borrower_score,
                                                    min_score_threshold, borrower_sector, sector_pref)
            matches.append({
                "type": "loan", "id": loan.id, "amount": remaining, "currency": loan.currency,
                "purpose": loan.purpose, "term_months": loan.term_months,
                "interest_rate_pct": loan.interest_rate_pct, "borrower_credit_score": borrower_score,
                "borrower_sector": borrower_sector, "match_score": score, "reasons": reasons,
            })

    if product_pref in ("factoring", "both"):
        open_listings = (FactoringListing.query.filter_by(status="listed")
                          .filter(FactoringListing.seller_user_id != uid).all())
        for listing in open_listings:
            profile = ErpCompanyProfile.query.filter_by(owner_user_id=listing.seller_user_id).first()
            seller_sector = profile.industry if profile else None
            try:
                seller_score = compute_credit_score(listing.seller_user_id).get("score")
            except Exception:
                seller_score = None
            score, reasons = _capital_match_score(listing.advance_amount, min_amount, max_amount, seller_score,
                                                    min_score_threshold, seller_sector, sector_pref)
            matches.append({
                "type": "factoring", "id": listing.id, "amount": listing.advance_amount,
                "face_value": listing.face_value, "potential_return": round(listing.face_value - listing.advance_amount, 2),
                "advance_rate": listing.advance_rate, "seller_credit_score": seller_score,
                "seller_sector": seller_sector, "match_score": score, "reasons": reasons,
            })

    if product_pref in ("po_financing", "both"):
        open_pos = (POFinancingRequest.query.filter(POFinancingRequest.status.in_(["open", "funded"]))
                    .filter(POFinancingRequest.buyer_user_id != uid).all())
        for po in open_pos:
            already_funded = round(sum(f.amount_funded for f in POFinancingFunding.query.filter_by(request_id=po.id).all()), 2)
            remaining = round((po.advance_amount or 0) - already_funded, 2)
            if remaining <= 0:
                continue
            profile = ErpCompanyProfile.query.filter_by(owner_user_id=po.buyer_user_id).first()
            buyer_sector = profile.industry if profile else None
            try:
                buyer_score = compute_credit_score(po.buyer_user_id).get("score")
            except Exception:
                buyer_score = po.trust_score_snapshot
            score, reasons = _capital_match_score(remaining, min_amount, max_amount, buyer_score,
                                                    min_score_threshold, buyer_sector, sector_pref)
            matches.append({
                "type": "po_financing", "id": po.id, "amount": remaining, "currency": po.currency,
                "description": po.description, "term_days": po.term_days, "fee_pct": po.fee_pct,
                "potential_return": round(po.amount_owed() - po.advance_amount, 2),
                "buyer_credit_score": buyer_score, "buyer_sector": buyer_sector,
                "match_score": score, "reasons": reasons,
            })

    matches.sort(key=lambda m: m["match_score"], reverse=True)
    return jsonify({
        "preferences_used": {"min_amount": min_amount, "max_amount": max_amount, "product_pref": product_pref,
                              "risk_appetite": risk_appetite, "sector_pref": sector_pref,
                              "is_default": prefs is None},
        "matches": matches[:30],
    }), 200


# ════════════════════════════════════════════════════════════
# PURCHASE ORDER FINANCING — endpoints
# ════════════════════════════════════════════════════════════

PO_FINANCING_MIN_ADVANCE_RATE = 0.50
PO_FINANCING_MAX_ADVANCE_RATE = 0.95


@app.route("/api/po-financing/requests", methods=["POST"])
@csrf.exempt
def po_financing_request_create():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}

    try:
        amount = float(data.get("amount"))
        if amount <= 0:
            raise ValueError()
    except (TypeError, ValueError):
        return jsonify({"error": "A valid, positive PO 'amount' is required."}), 400

    advance_rate = data.get("advance_rate", 0.90)
    try:
        advance_rate = float(advance_rate)
    except (TypeError, ValueError):
        return jsonify({"error": "'advance_rate' must be a number."}), 400
    if not (PO_FINANCING_MIN_ADVANCE_RATE <= advance_rate <= PO_FINANCING_MAX_ADVANCE_RATE):
        return jsonify({"error": f"'advance_rate' must be between {PO_FINANCING_MIN_ADVANCE_RATE} and {PO_FINANCING_MAX_ADVANCE_RATE} — the remainder is held back until you confirm delivery."}), 400

    try:
        term_days = int(data.get("term_days", 60))
        if term_days < 7 or term_days > 365:
            raise ValueError()
    except (TypeError, ValueError):
        return jsonify({"error": "'term_days' must be an integer between 7 and 365."}), 400

    fee_pct = data.get("fee_pct")
    try:
        fee_pct = float(fee_pct) if fee_pct not in (None, "") else 6.0
        if fee_pct < 0:
            raise ValueError()
    except (TypeError, ValueError):
        return jsonify({"error": "'fee_pct' must be a non-negative number."}), 400

    seller_user_id = None
    seller_name_external = (data.get("seller_name_external") or "").strip()[:150] or None
    product_order_id = data.get("product_order_id")
    if product_order_id:
        order = ProductOrder.query.get(int(product_order_id))
        if not order or order.buyer_id != user["id"]:
            return jsonify({"error": "That order doesn't belong to you."}), 400
        product = Product.query.get(order.product_id)
        seller_user_id = product.seller_id if product else None
        if not seller_name_external:
            seller = UserAccount.query.get(seller_user_id) if seller_user_id else None
            seller_name_external = seller.name if seller else None
    else:
        seller_email = (data.get("seller_email") or "").strip().lower()
        if seller_email:
            seller = UserAccount.query.filter(db.func.lower(UserAccount.email) == seller_email).first()
            if seller:
                seller_user_id = seller.id
                seller_name_external = seller_name_external or seller.name

    if seller_user_id == user["id"]:
        return jsonify({"error": "You can't request financing to pay yourself."}), 400

    try:
        credit = compute_credit_score(user["id"])
        trust_score = credit.get("score")
        trust_grade = credit.get("risk_grade")
    except Exception:
        trust_score, trust_grade = None, None

    advance_amount = round(amount * advance_rate, 2)
    po = POFinancingRequest(
        buyer_user_id=user["id"], seller_user_id=seller_user_id, product_order_id=int(product_order_id) if product_order_id else None,
        po_reference=(data.get("po_reference") or "").strip()[:80] or None,
        seller_name_external=seller_name_external,
        description=(data.get("description") or "").strip()[:2000] or None,
        amount=amount, currency=(data.get("currency") or "USD").strip()[:8].upper(),
        advance_rate=advance_rate, advance_amount=advance_amount, fee_pct=fee_pct, term_days=term_days,
        trust_score_snapshot=trust_score, trust_grade_snapshot=trust_grade, status="open",
    )
    db.session.add(po)
    db.session.commit()
    return jsonify({"ok": True, "request": po.to_dict()}), 201


