@app.route("/api/po-financing/requests/<int:request_id>/fund", methods=["POST"])
@csrf.exempt
def po_financing_request_fund(request_id):
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    po = POFinancingRequest.query.get(request_id)
    if not po:
        return jsonify({"error": "Request not found."}), 404
    if po.buyer_user_id == user["id"]:
        return jsonify({"error": "You can't fund your own PO financing request."}), 403
    if po.status not in ("open", "funded"):
        return jsonify({"error": "This request is no longer open for funding."}), 409

    data = request.get_json(silent=True) or {}
    try:
        amount_funded = float(data.get("amount"))
        if amount_funded <= 0:
            raise ValueError()
    except (TypeError, ValueError):
        return jsonify({"error": "A valid, positive funding 'amount' is required."}), 400

    already_funded = round(sum(f.amount_funded for f in POFinancingFunding.query.filter_by(request_id=po.id).all()), 2)
    remaining = round(po.advance_amount - already_funded, 2)
    if amount_funded > remaining + 0.01:
        return jsonify({"error": f"Only {po.currency} {remaining:,.2f} is left to fund on this request."}), 400

    funding = POFinancingFunding(request_id=po.id, investor_user_id=user["id"], amount_funded=amount_funded)
    db.session.add(funding)
    new_total = already_funded + amount_funded
    today = datetime.utcnow().date()
    _erp_post_ledger(user["id"], today, "expense", "PO Financing Investment",
                      f"Funded PO financing request #{po.id}", -abs(amount_funded),
                      "po_financing_request", po.id)
    if po.seller_user_id:
        _erp_post_ledger(po.seller_user_id, today, "revenue", "PO Financing Advance",
                          f"Advance for PO financing request #{po.id}", amount_funded,
                          "po_financing_request", po.id)
    if new_total >= po.advance_amount - 0.01:
        po.status = "funded"
        po.funded_at = datetime.utcnow()
        po.due_date = (datetime.utcnow() + timedelta(days=po.term_days)).date()
    db.session.commit()
    return jsonify({"ok": True, "request": po.to_dict()}), 200


