@app.route("/api/po-financing/requests/<int:request_id>/repay", methods=["POST"])
@csrf.exempt
def po_financing_repay(request_id):
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    po = POFinancingRequest.query.get(request_id)
    if not po:
        return jsonify({"error": "Request not found."}), 404
    if po.buyer_user_id != user["id"]:
        return jsonify({"error": "Only the buyer can make a repayment on this request."}), 403
    if po.status not in ("delivered", "repaying"):
        return jsonify({"error": "This request isn't ready for repayment yet — confirm delivery first."}), 409

    data = request.get_json(silent=True) or {}
    try:
        amount = float(data.get("amount"))
        if amount <= 0:
            raise ValueError()
    except (TypeError, ValueError):
        return jsonify({"error": "A valid, positive repayment 'amount' is required."}), 400

    repayment = POFinancingRepayment(request_id=po.id, amount=amount, note=(data.get("note") or "").strip()[:200] or None)
    db.session.add(repayment)
    repaid_total = round(sum(r.amount for r in POFinancingRepayment.query.filter_by(request_id=po.id).all()) + amount, 2)
    if repaid_total >= po.amount_owed() - 0.01:
        po.status = "completed"
        po.completed_at = datetime.utcnow()
    else:
        po.status = "repaying"
    db.session.commit()
    return jsonify({"ok": True, "request": po.to_dict(include_detail=True)}), 200


