# ════════════════════════════════════════════════════════════
# STAGE 344: SUPPLY CHAIN FINANCING CASCADE — endpoints
# Extends PO financing one tier down: a seller who was advanced funds
# above doesn't have to wait on their own margin to pay their own raw
# material suppliers. They can push a slice of the advance they just
# received straight back out to the same investor pool, this time as
# the buyer, financing early payment to one of their registered
# ErpSupplier records. Nothing here re-implements the funding/repayment
# mechanics — a cascade request is a normal POFinancingRequest with
# cascade_parent_id/cascade_tier set, so it goes through the exact same
# fund/confirm-delivery/repay routes above. What's new is just: who is
# allowed to open one, how big it's allowed to be (capped at what the
# parent actually paid out), and a chain view to show the tiers.
# ════════════════════════════════════════════════════════════

@app.route("/api/po-financing/requests/mine-as-seller-cascadable", methods=["GET"])
def po_financing_cascadable_mine():
    """Requests where the calling user was the seller being advanced
    funds, and still has room to cascade some of that advance down to
    their own suppliers. Feeds the 'Cascade to My Suppliers' tab."""
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    rows = (POFinancingRequest.query.filter_by(seller_user_id=user["id"])
            .filter(POFinancingRequest.status.in_(["funded", "delivered", "repaying", "completed"]))
            .order_by(POFinancingRequest.created_at.desc()).all())
    cascadable = [r.to_dict() for r in rows if r.cascade_available() > 0]
    return jsonify({"requests": cascadable}), 200


@app.route("/api/po-financing/requests/<int:request_id>/cascade", methods=["POST"])
@csrf.exempt
def po_financing_cascade_create(request_id):
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    parent = POFinancingRequest.query.get(request_id)
    if not parent:
        return jsonify({"error": "Request not found."}), 404
    if parent.seller_user_id != user["id"]:
        return jsonify({"error": "Only the seller who was advanced funds on this request can cascade it."}), 403
    if parent.status not in ("funded", "delivered", "repaying", "completed"):
        return jsonify({"error": "This request hasn't been funded yet — there's nothing to cascade."}), 409

    available = parent.cascade_available()
    if available <= 0:
        return jsonify({"error": "No advance remaining to cascade — it's already fully committed to your own suppliers."}), 409

    data = request.get_json(silent=True) or {}
    try:
        amount = float(data.get("amount"))
        if amount <= 0:
            raise ValueError()
    except (TypeError, ValueError):
        return jsonify({"error": "A valid, positive 'amount' is required."}), 400
    if amount > available:
        return jsonify({"error": f"You can cascade at most {available} — the rest of your advance is already committed."}), 400

    supplier = None
    supplier_id = data.get("supplier_id")
    supplier_name_external = (data.get("supplier_name_external") or "").strip()[:150] or None
    if supplier_id:
        supplier = ErpSupplier.query.get(int(supplier_id))
        if not supplier or supplier.owner_user_id != user["id"]:
            return jsonify({"error": "That supplier isn't on your own supplier list."}), 400
        if not supplier_name_external:
            supplier_name_external = supplier.name
    elif not supplier_name_external:
        return jsonify({"error": "Provide either 'supplier_id' (from your supplier list) or 'supplier_name_external'."}), 400

    advance_rate = data.get("advance_rate", 0.90)
    try:
        advance_rate = float(advance_rate)
    except (TypeError, ValueError):
        return jsonify({"error": "'advance_rate' must be a number."}), 400
    if not (PO_FINANCING_MIN_ADVANCE_RATE <= advance_rate <= PO_FINANCING_MAX_ADVANCE_RATE):
        return jsonify({"error": f"'advance_rate' must be between {PO_FINANCING_MIN_ADVANCE_RATE} and {PO_FINANCING_MAX_ADVANCE_RATE}."}), 400

    try:
        term_days = int(data.get("term_days", parent.term_days or 60))
        if term_days < 7 or term_days > 365:
            raise ValueError()
    except (TypeError, ValueError):
        return jsonify({"error": "'term_days' must be an integer between 7 and 365."}), 400

    fee_pct = data.get("fee_pct")
    try:
        fee_pct = float(fee_pct) if fee_pct not in (None, "") else 6.0
        if fee_pct < 0:
            raise ValueError()
    except (TypeError, ValueError):
        return jsonify({"error": "'fee_pct' must be a non-negative number."}), 400

    # The PO value backing a cascade request is the amount being pushed
    # out to the supplier grossed back up by the advance rate — same
    # convention as a normal PO financing request, just derived rather
    # than typed in, since there's no separate "total PO" for an
    # internal restock the seller is initiating themselves.
    po_amount = round(amount / advance_rate, 2) if advance_rate else amount

    try:
        credit = compute_credit_score(user["id"])
        trust_score = credit.get("score")
        trust_grade = credit.get("risk_grade")
    except Exception:
        trust_score, trust_grade = None, None

    child = POFinancingRequest(
        buyer_user_id=user["id"], seller_user_id=None,
        seller_name_external=supplier_name_external,
        po_reference=(data.get("po_reference") or f"Cascade of PO #{parent.id}")[:80],
        description=(data.get("description") or f"Supply chain cascade — early payment to {supplier_name_external}").strip()[:2000],
        amount=po_amount, currency=parent.currency,
        advance_rate=advance_rate, advance_amount=round(amount, 2), fee_pct=fee_pct, term_days=term_days,
        trust_score_snapshot=trust_score, trust_grade_snapshot=trust_grade, status="open",
        cascade_parent_id=parent.id, cascade_tier=parent.cascade_tier + 1, cascade_supplier_id=supplier.id if supplier else None,
    )
    db.session.add(child)
    db.session.commit()
    return jsonify({"ok": True, "request": child.to_dict()}), 201


@app.route("/api/po-financing/requests/<int:request_id>/cascade-chain", methods=["GET"])
def po_financing_cascade_chain(request_id):
    """Walks a request's cascade lineage both up (to the original
    buyer-to-seller PO) and down (every tier a seller has since pushed
    on to their own suppliers), so the UI can render the full chain —
    who ultimately financed whom, hop by hop."""
    node = POFinancingRequest.query.get(request_id)
    if not node:
        return jsonify({"error": "Request not found."}), 404

    ancestors = []
    cur = node
    seen_ids = {node.id}
    while cur.cascade_parent_id and cur.cascade_parent_id not in seen_ids:
        parent = POFinancingRequest.query.get(cur.cascade_parent_id)
        if not parent:
            break
        ancestors.append(parent.to_dict())
        seen_ids.add(parent.id)
        cur = parent
    ancestors.reverse()

    def _descendants(pid, depth=0):
        if depth > 10:
            return []
        kids = POFinancingRequest.query.filter_by(cascade_parent_id=pid).order_by(POFinancingRequest.created_at.asc()).all()
        out = []
        for k in kids:
            out.append(k.to_dict())
            out.extend(_descendants(k.id, depth + 1))
        return out

    return jsonify({
        "requested_id": request_id,
        "root": ancestors[0] if ancestors else node.to_dict(),
        "ancestors": ancestors,
        "node": node.to_dict(),
        "descendants": _descendants(node.id),
    }), 200



# ════════════════════════════════════════════════════════════
# SMILE AGAIN CAPITAL — PLATFORM-ORIGINATED LENDING
# ("Become the underwriter, not just the ledger")
# Different mechanic to the peer-funded LoanListing marketplace above,
# where another member's cash funds the loan: here the platform itself
# is the lender of record, decisions are made automatically off the
# same real ERP data compute_credit_score() already turns into a
# bankable file, and the platform takes an origination fee at
# disbursement plus a servicing fee on every repayment collected. No
# external bank/warehouse-facility API is called anywhere below — that
# integration is a capital/legal step (whose balance sheet actually
# funds the loan) the business can plug in later, not a coding one.
# What's built here is the underwriting + offer + servicing rails so
# that plug-in is a config change, not a rewrite.
# ════════════════════════════════════════════════════════════

CAPITAL_APPLICATION_STATUSES = {
    "submitted", "declined", "offer_sent", "offer_declined", "offer_expired", "disbursed",
}
CAPITAL_LOAN_STATUSES = {"disbursed", "repaying", "completed", "defaulted"}

# Floor below which this platform won't underwrite at all — a decline,
# not a rate, comes back below this.
CAPITAL_MIN_SCORE = 500
CAPITAL_ORIGINATION_FEE_PCT = 3.0   # taken off the top at disbursement
CAPITAL_SERVICING_FEE_PCT = 10.0    # platform's cut of each repayment collected
CAPITAL_OFFER_VALID_DAYS = 14


def _capital_risk_tier(score: int) -> dict:
    """The platform's own rate card, keyed off the existing 300-850
    credit score — not a re-derivation of the score itself."""
    if score >= 740:
        return {"tier": "A", "interest_rate_pct": 14.0, "max_revenue_multiple": 3.0, "max_term_months": 24}
    if score >= 640:
        return {"tier": "B", "interest_rate_pct": 20.0, "max_revenue_multiple": 2.0, "max_term_months": 18}
    if score >= CAPITAL_MIN_SCORE:
        return {"tier": "C", "interest_rate_pct": 28.0, "max_revenue_multiple": 1.0, "max_term_months": 12}
    return {"tier": "D", "interest_rate_pct": 0.0, "max_revenue_multiple": 0.0, "max_term_months": 0}


def _capital_avg_monthly_revenue(user_id: int) -> float:
    today = datetime.utcnow().date()
    since = today - timedelta(days=180)
    entries = (ErpLedgerEntry.query.filter_by(owner_user_id=user_id)
               .filter(ErpLedgerEntry.entry_date >= since, ErpLedgerEntry.amount > 0).all())
    if not entries:
        return 0.0
    monthly = defaultdict(float)
    for e in entries:
        monthly[(e.entry_date.year, e.entry_date.month)] += e.amount
    return sum(monthly.values()) / max(len(monthly), 1)


def underwrite_capital_application(user_id: int, amount_requested: float, term_months: int) -> dict:
    """The actual auto-decision engine. Pure function — returns a
    decision dict, never touches the DB itself; the route layer below
    decides what to persist from it."""
    credit = compute_credit_score(user_id)
    score = credit["score"]
    tier = _capital_risk_tier(score)
    avg_rev = _capital_avg_monthly_revenue(user_id)

    if score < CAPITAL_MIN_SCORE:
        return {
            "decision": "declined",
            "reason": f"Credit score {score} is below the {CAPITAL_MIN_SCORE} minimum this platform underwrites against.",
            "credit_score": score, "risk_grade": credit["risk_grade"],
        }
    if avg_rev <= 0:
        return {
            "decision": "declined",
            "reason": "No positive revenue trend on file over the last 6 months to size a loan against.",
            "credit_score": score, "risk_grade": credit["risk_grade"],
        }

    max_amount = round(avg_rev * tier["max_revenue_multiple"], 2)
    if max_amount <= 0:
        return {
            "decision": "declined", "reason": "Not enough revenue history yet to size an offer.",
            "credit_score": score, "risk_grade": credit["risk_grade"],
        }

    notes = []
    approved_amount = round(min(amount_requested, max_amount), 2)
    if approved_amount < amount_requested:
        notes.append(f"Amount reduced to {approved_amount} based on average monthly revenue of {round(avg_rev, 2)}.")
    approved_term = min(term_months, tier["max_term_months"]) if tier["max_term_months"] else term_months
    if approved_term < term_months:
        notes.append(f"Term reduced to {approved_term} months for this risk tier.")

    return {
        "decision": "approved", "tier": tier["tier"], "credit_score": score, "risk_grade": credit["risk_grade"],
        "interest_rate_pct": tier["interest_rate_pct"], "approved_amount": approved_amount,
        "approved_term_months": approved_term, "avg_monthly_revenue": round(avg_rev, 2),
        "max_eligible_amount": max_amount, "notes": notes,
    }


class CapitalLoanApplication(db.Model):
    __tablename__  = "capital_loan_applications"
    id             = db.Column(db.Integer, primary_key=True)
    applicant_user_id = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    amount_requested = db.Column(db.Float, nullable=False)
    term_months_requested = db.Column(db.Integer, nullable=False, default=6)
    purpose        = db.Column(db.String(300), nullable=False)
    currency       = db.Column(db.String(8), nullable=False, default="USD")
    status         = db.Column(db.String(20), nullable=False, default="submitted", index=True)
    credit_score_snapshot = db.Column(db.Integer, nullable=True)
    risk_grade_snapshot = db.Column(db.String(20), nullable=True)
    decision_reason = db.Column(db.String(500), nullable=True)
    decided_at     = db.Column(db.DateTime, nullable=True)
    decided_by     = db.Column(db.String(10), nullable=True)   # auto, admin
    created_at     = db.Column(db.DateTime, default=datetime.utcnow, index=True)
    updated_at     = db.Column(db.DateTime, default=datetime.utcnow, onupdate=datetime.utcnow)

    def to_dict(self):
        offer = (CapitalLoanOffer.query.filter_by(application_id=self.id)
                 .order_by(CapitalLoanOffer.created_at.desc()).first())
        loan = CapitalLoan.query.filter_by(application_id=self.id).first()
        return {
            "id": self.id, "applicant_user_id": self.applicant_user_id,
            "amount_requested": self.amount_requested, "term_months_requested": self.term_months_requested,
            "purpose": self.purpose, "currency": self.currency, "status": self.status,
            "credit_score_snapshot": self.credit_score_snapshot, "risk_grade_snapshot": self.risk_grade_snapshot,
            "decision_reason": self.decision_reason,
            "decided_at": self.decided_at.isoformat() if self.decided_at else None,
            "decided_by": self.decided_by,
            "created_at": self.created_at.isoformat() if self.created_at else None,
            "offer": offer.to_dict() if offer else None,
            "loan_id": loan.id if loan else None,
        }


class CapitalLoanOffer(db.Model):
    __tablename__  = "capital_loan_offers"
    id             = db.Column(db.Integer, primary_key=True)
    application_id = db.Column(db.Integer, db.ForeignKey("capital_loan_applications.id"), nullable=False, index=True)
    amount_offered = db.Column(db.Float, nullable=False)
    term_months    = db.Column(db.Integer, nullable=False)
    interest_rate_pct = db.Column(db.Float, nullable=False)
    origination_fee_pct = db.Column(db.Float, nullable=False, default=CAPITAL_ORIGINATION_FEE_PCT)
    risk_tier      = db.Column(db.String(4), nullable=True)
    status         = db.Column(db.String(16), nullable=False, default="pending", index=True)  # pending, accepted, declined, expired
    expires_at     = db.Column(db.DateTime, nullable=True)
    created_at     = db.Column(db.DateTime, default=datetime.utcnow)
    responded_at   = db.Column(db.DateTime, nullable=True)

    def to_dict(self):
        origination_fee = round(self.amount_offered * self.origination_fee_pct / 100, 2)
        return {
            "id": self.id, "application_id": self.application_id,
            "amount_offered": self.amount_offered,
            "net_disbursement": round(self.amount_offered - origination_fee, 2),
            "term_months": self.term_months, "interest_rate_pct": self.interest_rate_pct,
            "origination_fee_pct": self.origination_fee_pct, "origination_fee_amount": origination_fee,
            "risk_tier": self.risk_tier, "status": self.status,
            "total_repayable": round(self.amount_offered * (1 + self.interest_rate_pct / 100), 2),
            "expires_at": self.expires_at.isoformat() if self.expires_at else None,
            "created_at": self.created_at.isoformat() if self.created_at else None,
            "responded_at": self.responded_at.isoformat() if self.responded_at else None,
        }


class CapitalLoan(db.Model):
    __tablename__  = "capital_loans"
    id             = db.Column(db.Integer, primary_key=True)
    application_id = db.Column(db.Integer, db.ForeignKey("capital_loan_applications.id"), nullable=False, unique=True, index=True)
    borrower_user_id = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    principal      = db.Column(db.Float, nullable=False)
    interest_rate_pct = db.Column(db.Float, nullable=False)
    term_months    = db.Column(db.Integer, nullable=False)
    origination_fee_amount = db.Column(db.Float, nullable=False, default=0)
    currency       = db.Column(db.String(8), nullable=False, default="USD")
    status         = db.Column(db.String(16), nullable=False, default="disbursed", index=True)
    payout_status  = db.Column(db.String(24), nullable=False, default="pending_manual_transfer")  # pending_manual_transfer, paid_out
    disbursed_at   = db.Column(db.DateTime, default=datetime.utcnow)
    due_date       = db.Column(db.DateTime, nullable=True)
    updated_at     = db.Column(db.DateTime, default=datetime.utcnow, onupdate=datetime.utcnow)

    def to_dict(self, include_repayments=False):
        repayments = CapitalLoanRepayment.query.filter_by(loan_id=self.id).all()
        repaid_total = round(sum(r.amount for r in repayments), 2)
        servicing_fee_collected = round(sum(r.platform_servicing_fee for r in repayments), 2)
        total_owed = round(self.principal * (1 + self.interest_rate_pct / 100), 2)
        borrower = UserAccount.query.get(self.borrower_user_id)
        d = {
            "id": self.id, "application_id": self.application_id,
            "borrower_user_id": self.borrower_user_id, "borrower_name": borrower.name if borrower else None,
            "principal": self.principal, "interest_rate_pct": self.interest_rate_pct, "term_months": self.term_months,
            "origination_fee_amount": self.origination_fee_amount, "currency": self.currency,
            "status": self.status, "payout_status": self.payout_status,
            "total_owed": total_owed, "repaid_total": repaid_total,
            "balance_remaining": round(max(total_owed - repaid_total, 0), 2),
            "platform_revenue_to_date": round(self.origination_fee_amount + servicing_fee_collected, 2),
            "disbursed_at": self.disbursed_at.isoformat() if self.disbursed_at else None,
            "due_date": self.due_date.isoformat() if self.due_date else None,
        }
        if include_repayments:
            d["repayments"] = [r.to_dict() for r in repayments]
        return d


class CapitalLoanRepayment(db.Model):
    __tablename__  = "capital_loan_repayments"
    id             = db.Column(db.Integer, primary_key=True)
    loan_id        = db.Column(db.Integer, db.ForeignKey("capital_loans.id"), nullable=False, index=True)
    amount         = db.Column(db.Float, nullable=False)
    platform_servicing_fee = db.Column(db.Float, nullable=False, default=0)
    note           = db.Column(db.String(200), nullable=True)
    paid_at        = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        return {
            "id": self.id, "loan_id": self.loan_id, "amount": self.amount,
            "platform_servicing_fee": self.platform_servicing_fee, "note": self.note,
            "paid_at": self.paid_at.isoformat() if self.paid_at else None,
        }


def _capital_is_admin(user_id: int) -> bool:
    account = UserAccount.query.get(user_id)
    return bool(account) and (
        account.is_admin or (account.email or "").strip().lower() in ADMIN_EMAILS
    )


@app.route("/api/capital/apply", methods=["POST"])
@csrf.exempt
@requires_feature_flag("capital_loan_program")
def capital_apply():
    """Submits an application and runs the auto-underwrite immediately
    — no queue, no waiting on a human, same instant feel as the rest
    of this platform's AI features."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    try:
        amount_requested = float(data.get("amount_requested"))
    except (TypeError, ValueError):
        return jsonify({"error": "amount_requested must be a number."}), 400
    if not validate_amount(amount_requested):
        return jsonify({"error": "Invalid amount_requested."}), 400
    try:
        term_months = int(data.get("term_months", 6))
    except (TypeError, ValueError):
        term_months = 6
    term_months = max(1, min(term_months, 36))
    purpose = (data.get("purpose") or "").strip()[:300]
    if not purpose:
        return jsonify({"error": "purpose is required."}), 400
    currency = (data.get("currency") or "USD").strip().upper()[:8]

    if CapitalLoanApplication.query.filter_by(
        applicant_user_id=user["id"], status="submitted"
    ).first() or CapitalLoan.query.filter(
        CapitalLoan.borrower_user_id == user["id"],
        CapitalLoan.status.in_(["disbursed", "repaying"]),
    ).first():
        return jsonify({"error": "You already have an application or loan in progress."}), 400

    application = CapitalLoanApplication(
        applicant_user_id=user["id"], amount_requested=amount_requested,
        term_months_requested=term_months, purpose=purpose, currency=currency,
    )
    db.session.add(application)
    db.session.flush()

    decision = underwrite_capital_application(user["id"], amount_requested, term_months)
    application.credit_score_snapshot = decision.get("credit_score")
    application.risk_grade_snapshot = decision.get("risk_grade")
    application.decided_at = datetime.utcnow()
    application.decided_by = "auto"

    offer = None
    if decision["decision"] == "approved":
        application.status = "offer_sent"
        application.decision_reason = "; ".join(decision.get("notes") or []) or "Approved."
        offer = CapitalLoanOffer(
            application_id=application.id, amount_offered=decision["approved_amount"],
            term_months=decision["approved_term_months"], interest_rate_pct=decision["interest_rate_pct"],
            risk_tier=decision["tier"], expires_at=datetime.utcnow() + timedelta(days=CAPITAL_OFFER_VALID_DAYS),
        )
        db.session.add(offer)
    else:
        application.status = "declined"
        application.decision_reason = decision.get("reason")

    db.session.commit()
    return jsonify({
        "ok": True, "application": application.to_dict(), "decision": decision,
    }), 201


