@app.route("/api/capital/offer/<int:offer_id>/accept", methods=["POST"])
@csrf.exempt
@requires_feature_flag("capital_loan_program")
def capital_offer_accept(offer_id):
    """Borrower accepts → this is the disbursement moment. Actual
    money movement to the borrower is the same 'pending manual
    transfer' pattern used for escrow seller payouts elsewhere on this
    platform (see EscrowTransaction.payout_status) until a funding
    partner's payout API is wired in."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    offer = CapitalLoanOffer.query.get(offer_id)
    if not offer:
        return jsonify({"error": "Offer not found."}), 404
    application = CapitalLoanApplication.query.filter_by(
        id=offer.application_id, applicant_user_id=user["id"]
    ).first()
    if not application:
        return jsonify({"error": "Offer not found."}), 404
    if offer.status != "pending":
        return jsonify({"error": f"This offer is already {offer.status}."}), 400
    if offer.expires_at and datetime.utcnow() > offer.expires_at:
        offer.status = "expired"
        db.session.commit()
        return jsonify({"error": "This offer has expired."}), 410

    origination_fee = round(offer.amount_offered * offer.origination_fee_pct / 100, 2)
    loan = CapitalLoan(
        application_id=application.id, borrower_user_id=user["id"],
        principal=offer.amount_offered, interest_rate_pct=offer.interest_rate_pct,
        term_months=offer.term_months, origination_fee_amount=origination_fee,
        currency=application.currency,
        due_date=datetime.utcnow() + timedelta(days=30 * offer.term_months),
    )
    offer.status = "accepted"
    offer.responded_at = datetime.utcnow()
    application.status = "disbursed"
    db.session.add(loan)
    db.session.commit()
    logging.info(f"[CAPITAL] Loan #{loan.id} disbursed to user {user['id']} | "
                 f"{loan.currency} {loan.principal:.2f} @ {loan.interest_rate_pct}% | "
                 f"origination fee {origination_fee:.2f}")
    return jsonify({"ok": True, "loan": loan.to_dict(), "application": application.to_dict()}), 201


