@app.route("/api/capital/loan/<int:loan_id>/repay", methods=["POST"])
@csrf.exempt
def capital_loan_repay(loan_id):
    """Records a repayment against a live loan. This just books the
    repayment ledger entry (same manual/off-platform settlement model
    used for LoanRepayment above) — it doesn't move money itself."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    loan = CapitalLoan.query.filter_by(id=loan_id, borrower_user_id=user["id"]).first()
    if not loan:
        return jsonify({"error": "Loan not found."}), 404
    if loan.status not in ("disbursed", "repaying"):
        return jsonify({"error": f"This loan is {loan.status} and can't take repayments."}), 400
    data = request.get_json(silent=True) or {}
    try:
        amount = float(data.get("amount"))
    except (TypeError, ValueError):
        return jsonify({"error": "amount must be a number."}), 400
    if not validate_amount(amount):
        return jsonify({"error": "Invalid amount."}), 400
    note = (data.get("note") or "").strip()[:200] or None

    total_owed = loan.principal * (1 + loan.interest_rate_pct / 100)
    interest_portion_total = total_owed - loan.principal
    # Servicing fee is the platform's cut, proportional to how much of
    # this repayment represents interest collected (vs. principal).
    interest_share_of_repayment = amount * (interest_portion_total / total_owed) if total_owed else 0
    servicing_fee = round(interest_share_of_repayment * CAPITAL_SERVICING_FEE_PCT / 100, 2)

    repayment = CapitalLoanRepayment(
        loan_id=loan.id, amount=amount, platform_servicing_fee=servicing_fee, note=note,
    )
    db.session.add(repayment)

    repaid_total = round(sum(r.amount for r in CapitalLoanRepayment.query.filter_by(loan_id=loan.id).all()) + amount, 2)
    loan.status = "completed" if repaid_total >= round(total_owed, 2) else "repaying"
    loan.updated_at = datetime.utcnow()
    db.session.commit()
    return jsonify({"ok": True, "loan": loan.to_dict(include_repayments=True), "repayment": repayment.to_dict()}), 201


@app.route("/api/capital/admin/portfolio", methods=["GET"])
def capital_admin_portfolio():
    """The 'underwriter' business dashboard: total outstanding
    principal, fee revenue earned so far, and a naive default rate —
    admin-only, since this is the platform's own book, not any one
    borrower's data."""
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    if not _capital_is_admin(user["id"]):
        return jsonify({"error": "Admin access required."}), 403

    loans = CapitalLoan.query.all()
    total_disbursed = round(sum(l.principal for l in loans), 2)
    total_origination_fees = round(sum(l.origination_fee_amount for l in loans), 2)
    total_servicing_fees = round(sum(
        r.platform_servicing_fee for l in loans for r in CapitalLoanRepayment.query.filter_by(loan_id=l.id).all()
    ), 2)
    outstanding = round(sum(
        max(l.principal * (1 + l.interest_rate_pct / 100) -
            sum(r.amount for r in CapitalLoanRepayment.query.filter_by(loan_id=l.id).all()), 0)
        for l in loans if l.status in ("disbursed", "repaying")
    ), 2)
    defaulted = len([l for l in loans if l.status == "defaulted"])
    completed_or_active = len([l for l in loans if l.status != "defaulted"])
    default_rate = round(defaulted / len(loans) * 100, 1) if loans else 0.0

    return jsonify({
        "loan_count": len(loans), "total_disbursed": total_disbursed,
        "outstanding_balance": outstanding,
        "platform_revenue": round(total_origination_fees + total_servicing_fees, 2),
        "origination_fees_earned": total_origination_fees, "servicing_fees_earned": total_servicing_fees,
        "defaulted_loans": defaulted, "default_rate_pct": default_rate,
        "pending_applications": CapitalLoanApplication.query.filter_by(status="submitted").count(),
    }), 200


