@app.route("/api/succession/plan", methods=["POST"])
@csrf.exempt
def succession_plan_save():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    plan = SuccessionPlan.query.filter_by(user_id=user["id"]).first()
    if not plan:
        plan = SuccessionPlan(user_id=user["id"])
        db.session.add(plan)
    plan.successor_name         = (data.get("successor_name") or "").strip()[:200] or None
    plan.successor_relationship = (data.get("successor_relationship") or "").strip()[:100] or None
    plan.successor_phone        = (data.get("successor_phone") or "").strip()[:64] or None
    plan.successor_email        = (data.get("successor_email") or "").strip()[:200] or None
    plan.notes                  = (data.get("notes") or "").strip()[:4000] or None
    _succession_touch_checkin(user["id"])
    db.session.commit()
    return jsonify({"ok": True, "plan": plan.to_dict()}), 200


