@app.route("/api/succession/generate-brief", methods=["POST"])
@csrf.exempt
def succession_generate_brief():
    """Drafts a continuity brief from the plan's real data — successor
    details, checklist progress, and the live ERP snapshot. Routed
    through the platform's own secured AI helper (never called directly
    from the browser)."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401

    _succession_seed_defaults_if_empty(user["id"])
    plan = SuccessionPlan.query.filter_by(user_id=user["id"]).first()
    items = SuccessionChecklistItem.query.filter_by(user_id=user["id"]).order_by(SuccessionChecklistItem.sort_order).all()
    snapshot = compute_succession_snapshot(user["id"])
    owner = UserAccount.query.get(user["id"])

    done_items    = [i.label for i in items if i.is_done]
    pending_items = [i.label for i in items if not i.is_done]

    gate_result = gate_ai_usage(user, "succession_generate_brief")
    if gate_result is not None:
        return gate_result

    prompt = (
        f"You are helping a small business owner in Zimbabwe/Southern Africa draft a business "
        f"continuity brief — a short document a successor or family member could read to understand "
        f"what needs to happen if the owner is suddenly unavailable.\n\n"
        f"Business owner: {owner.name if owner else 'the owner'}\n"
        f"Designated successor: {plan.successor_name if plan and plan.successor_name else 'not yet named'} "
        f"({plan.successor_relationship if plan and plan.successor_relationship else 'relationship not specified'})\n"
        f"Successor contact: {plan.successor_phone if plan and plan.successor_phone else 'not on file'} / "
        f"{plan.successor_email if plan and plan.successor_email else 'not on file'}\n\n"
        f"Current business snapshot (real, as of today):\n"
        f"- Active employees: {snapshot['active_employees']} (est. monthly payroll: {snapshot['estimated_monthly_payroll']})\n"
        f"- Active customers on file: {snapshot['active_customers']}\n"
        f"- Outstanding receivables (owed TO the business): {snapshot['outstanding_receivables']}\n"
        f"- Outstanding payables (owed BY the business): {snapshot['outstanding_payables']}\n"
        f"- Inventory value at cost: {snapshot['inventory_value_at_cost']}\n\n"
        f"Continuity steps already completed: {'; '.join(done_items) if done_items else 'none yet'}\n"
        f"Continuity steps still outstanding: {'; '.join(pending_items) if pending_items else 'none'}\n\n"
        f"Write a clear, practical continuity brief (not generic advice) that: (1) opens with what the "
        f"successor needs to know first, (2) summarizes the financial position in plain language, "
        f"(3) lists the outstanding steps as concrete next actions, (4) closes with who to contact for what. "
        f"Keep it grounded only in the facts given above — do not invent details that weren't provided."
    )
    narrative_raw, _ = generate_ai_reply(prompt, [])
    narrative_html   = format_ai_response(narrative_raw)

    return jsonify({
        "brief_html": narrative_html,
        "brief_text": narrative_raw,
        "snapshot":   snapshot,
        "powered_by": "Smile Again API",
    }), 200


# ---- STAGE 94B ROUTES: asset register, key contacts, and the real
# access-grant mechanism (see model comments above for the full
# design). ----

def _succession_touch_checkin(user_id: int) -> None:
    """Real, honest 'still active' signal: called whenever the owner
    actually opens or saves their own succession data. No separate
    ritual required, and nothing here is simulated — it's the same
    kind of last-activity timestamp any real system uses."""
    grant = SuccessionAccessGrant.query.filter_by(user_id=user_id, status="active").first()
    if grant:
        grant.last_checkin_at = datetime.utcnow()
        db.session.commit()


