@app.route("/api/succession/access-grant", methods=["POST"])
@csrf.exempt
def succession_access_grant_save():
    """Creates or updates the owner's single trusted-access grant. Every
    save resets last_checkin_at to now and re-activates a revoked grant
    — same reasoning as _succession_touch_checkin: touching this feature
    at all is a real, honest sign of life."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    trusted_name = (data.get("trusted_name") or "").strip()
    trusted_email = (data.get("trusted_email") or "").strip()
    if not trusted_name or not trusted_email:
        return jsonify({"error": "trusted_name and trusted_email are required."}), 400
    try:
        interval = max(7, int(data.get("checkin_interval_days", 90) or 90))
    except (TypeError, ValueError):
        return jsonify({"error": "checkin_interval_days must be a number."}), 400
    grant = SuccessionAccessGrant.query.filter_by(user_id=user["id"]).first()
    if not grant:
        grant = SuccessionAccessGrant(user_id=user["id"], access_token=secrets.token_hex(24))
        db.session.add(grant)
    grant.trusted_name = trusted_name[:200]
    grant.trusted_email = trusted_email[:200]
    grant.checkin_interval_days = interval
    grant.last_checkin_at = datetime.utcnow()
    grant.status = "active"
    grant.triggered_at = None
    grant.notified_at = None
    db.session.commit()
    return jsonify({"ok": True, "grant": grant.to_dict()}), 200


@app.route("/api/succession/access-grant/checkin", methods=["POST"])
@csrf.exempt
def succession_access_grant_checkin():
    """Explicit 'I'm okay' button, for an owner who wants to check in
    without touching anything else."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
