@app.route("/api/succession/access/<string:token>", methods=["GET"])
def succession_public_access(token):
    """No login required — this is the link the trusted contact actually
    receives. Real overdue check happens right here, on every visit: a
    grant only ever unlocks if it's genuinely past its check-in
    interval, evaluated fresh against real elapsed time, not a stored
    flag someone could have gotten wrong."""
    grant = SuccessionAccessGrant.query.filter_by(access_token=token).first()
    if not grant or grant.status == "revoked":
        return jsonify({"error": "This link is invalid or has been revoked."}), 404
    if not grant.is_overdue() and grant.status != "triggered":
        return jsonify({
            "unlocked": False,
            "message": "This plan is not yet accessible — the business owner has checked in recently.",
        }), 200
    if grant.status == "active":
        grant.status = "triggered"
        grant.triggered_at = datetime.utcnow()
        db.session.commit()
    plan = SuccessionPlan.query.filter_by(user_id=grant.user_id).first()
    checklist = SuccessionChecklistItem.query.filter_by(user_id=grant.user_id).order_by(SuccessionChecklistItem.sort_order).all()
    assets = SuccessionAsset.query.filter_by(user_id=grant.user_id).all()
    contacts = SuccessionContact.query.filter_by(user_id=grant.user_id).all()
    owner = UserAccount.query.get(grant.user_id)
    return jsonify({
        "unlocked": True,
        "business_owner_name": owner.name if owner else None,
        "plan": plan.to_dict() if plan else None,
        "checklist": [i.to_dict() for i in checklist],
        "assets": [a.to_dict() for a in assets],
        "contacts": [c.to_dict() for c in contacts],
        "snapshot": compute_succession_snapshot(grant.user_id),
    }), 200


@app.route("/api/admin/succession/sweep-overdue", methods=["POST"])
@csrf.exempt
def admin_succession_sweep_overdue():
    """Point a PythonAnywhere Scheduled Task at this endpoint (daily is
    plenty) — there's no background job runner in this codebase, so
    this is what actually sends the real notification email once a
    grant goes overdue; without something calling this on a schedule,
    overdue grants still unlock correctly the moment someone visits
    their access link, but the trusted contact won't get emailed to
    know they should. Requires the admin API key, same as other
    service endpoints — see _status_admin_or_401."""
    user, err = _status_admin_or_401()
    if err: return err
    swept = 0
    emailed = 0
    grants = SuccessionAccessGrant.query.filter_by(status="active").all()
    for grant in grants:
        if grant.is_overdue():
            grant.status = "triggered"
            grant.triggered_at = datetime.utcnow()
            swept += 1
            owner = UserAccount.query.get(grant.user_id)
            access_url = f"{request.url_root.rstrip('/')}/succession-access?token={grant.access_token}"
            sent = _send_platform_email(
                grant.trusted_email,
                f"Business continuity plan access — {owner.name if owner else 'a business on this platform'}",
                f"<p>{escape(grant.trusted_name)},</p>"
                f"<p>{escape(owner.name if owner else 'A business owner')} listed you as their trusted contact "
                f"for their business continuity plan. They haven't checked in for over "
                f"{grant.checkin_interval_days} days, so this plan is now unlocked for you to view:</p>"
                f"<p><a href=\"{escape(access_url)}\">{escape(access_url)}</a></p>",
            )
            grant.notified_at = datetime.utcnow() if sent else None
            if sent:
                emailed += 1
    db.session.commit()
    return jsonify({"ok": True, "grants_triggered": swept, "emails_sent": emailed}), 200


