@app.route("/api/equipment-pool/create", methods=["POST"])
@csrf.exempt
def equipment_pool_create():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    data  = request.get_json(silent=True) or {}
    title = (data.get("title") or "").strip()[:160]
    if not title:
        return jsonify({"error": "title is required."}), 400
    try:
        total_cost = float(data.get("total_cost", 0) or 0)
    except (TypeError, ValueError):
        return jsonify({"error": "total_cost must be a number."}), 400
    if total_cost <= 0:
        return jsonify({"error": "total_cost must be greater than zero."}), 400

    deadline = None
    if data.get("deadline"):
        try:
            deadline = datetime.fromisoformat(data["deadline"])
        except (TypeError, ValueError):
            deadline = None

    pool = EquipmentPool(
        organizer_id=user["id"], title=title,
        equipment_type=(data.get("equipment_type") or "Solar system").strip()[:100],
        description=(data.get("description") or "").strip()[:2000] or None,
        total_cost=total_cost, currency=(data.get("currency") or "USD").strip()[:8],
        area=(data.get("area") or "").strip()[:120] or None,
        deadline=deadline, notes=(data.get("notes") or "").strip()[:2000] or None,
    )
    db.session.add(pool)
    db.session.commit()
    return jsonify({"ok": True, "pool": pool.to_dict()}), 201


