# STAGE 69: GROUP-BUYING POOL
# Lets small/informal traders pool stock orders to reach a supplier's
# minimum order quantity and unlock bulk pricing none of them could
# get alone — same "organiser + members pledge in" mechanic the
# savings-group tooling already uses, applied to stock instead of cash.
# ════════════════════════════════════════════════════════════

@app.route("/api/groupbuy/create", methods=["POST"])
@csrf.exempt
def groupbuy_create():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    title        = (data.get("title") or "").strip()
    product_name = (data.get("product_name") or "").strip()
    area         = (data.get("area") or "").strip() or None
    notes        = (data.get("notes") or "").strip() or None
    try:
        unit_price = float(data.get("unit_price", 0) or 0)
        moq        = max(1, int(data.get("moq", 1) or 1))
    except (TypeError, ValueError):
        return jsonify({"error": "unit_price and moq must be numeric."}), 400
    currency = (data.get("currency") or "USD").strip()[:8]

    deadline = None
    if data.get("deadline"):
        try:
            deadline = datetime.fromisoformat(data["deadline"])
        except ValueError:
            pass

    if not title or not product_name:
        return jsonify({"error": "title and product_name are required."}), 400

    gb = GroupBuy(
        organizer_id=user["id"], title=title[:160], product_name=product_name[:160],
        unit_price=unit_price, currency=currency, moq=moq, area=area[:120] if area else None,
        deadline=deadline, notes=notes,
    )
    db.session.add(gb)
    db.session.commit()
    return jsonify({"ok": True, "group_buy": gb.to_dict()}), 201


@app.route("/api/groupbuy/list", methods=["GET"])
def groupbuy_list():
    area   = (request.args.get("area") or "").strip()
    status = (request.args.get("status") or "open").strip()
    q = GroupBuy.query
    if status != "all":
        q = q.filter_by(status=status)
    if area:
        q = q.filter(GroupBuy.area.ilike(f"%{area}%"))
    rows = q.order_by(GroupBuy.created_at.desc()).limit(100).all()
    return jsonify({"group_buys": [g.to_dict() for g in rows]}), 200


@app.route("/api/groupbuy/<int:gb_id>", methods=["GET"])
def groupbuy_detail(gb_id):
    gb = GroupBuy.query.get(gb_id)
    if not gb:
        return jsonify({"error": "Not found."}), 404
    return jsonify({"group_buy": gb.to_dict(include_pledges=True)}), 200


@app.route("/api/groupbuy/<int:gb_id>/pledge", methods=["POST"])
@csrf.exempt
def groupbuy_pledge(gb_id):
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    gb = GroupBuy.query.get(gb_id)
    if not gb:
        return jsonify({"error": "Not found."}), 404
    if gb.status != "open":
        return jsonify({"error": f"This group buy is {gb.status}, not accepting new pledges."}), 400

    data = request.get_json(silent=True) or {}
    try:
        quantity = max(1, int(data.get("quantity", 1) or 1))
    except (TypeError, ValueError):
        return jsonify({"error": "quantity must be a positive integer."}), 400
    contact = (data.get("contact") or "").strip()[:120] or None

    existing = GroupBuyPledge.query.filter_by(group_buy_id=gb_id, user_id=user["id"]).first()
    if existing:
        existing.quantity = quantity
        if contact:
            existing.contact = contact
    else:
        db.session.add(GroupBuyPledge(group_buy_id=gb_id, user_id=user["id"], quantity=quantity, contact=contact))
    db.session.commit()
    return jsonify({"ok": True, "group_buy": gb.to_dict()}), 200


@app.route("/api/groupbuy/<int:gb_id>/status", methods=["POST"])
@csrf.exempt
def groupbuy_set_status(gb_id):
    """Organiser-only: mark a pool fulfilled or cancelled once the order
    has actually been placed with the supplier (or abandoned)."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    gb = GroupBuy.query.filter_by(id=gb_id, organizer_id=user["id"]).first()
    if not gb:
        return jsonify({"error": "Not found or you're not the organiser."}), 404
    status = (request.get_json(silent=True) or {}).get("status", "")
    if status not in ("open", "fulfilled", "cancelled"):
        return jsonify({"error": "status must be open, fulfilled, or cancelled."}), 400
    gb.status = status
    db.session.commit()
    return jsonify({"ok": True, "group_buy": gb.to_dict()}), 200


