@app.route("/api/wage-advance", methods=["POST"])
@csrf.exempt
@requires_feature_flag("earned_wage_access")
def wage_advance_request():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    try:
        earned = float(data.get("earned_to_date_amount", 0) or 0)
        requested = float(data.get("requested_amount", 0) or 0)
    except (TypeError, ValueError):
        return jsonify({"error": "amounts must be numbers."}), 400
    if requested <= 0 or requested > earned:
        return jsonify({"error": "requested_amount must be positive and cannot exceed earned_to_date_amount."}), 400
    status = "pending_partner" if not _integration_configured("payroll_advance_partner") else "approved"
    row = WageAdvanceRequest(
        user_id=user["id"], employer_name=(data.get("employer_name") or "").strip()[:200] or None,
        earned_to_date_amount=earned, requested_amount=requested,
        currency=(data.get("currency") or "USD")[:8], status=status,
    )
    db.session.add(row)
    db.session.commit()
    return jsonify({"ok": True, "request": row.to_dict(),
                     "partner_configured": _integration_configured("payroll_advance_partner")}), 201


