@app.route("/api/skill-certifications/<int:cert_id>/verify", methods=["POST"])
@csrf.exempt
def skill_certification_verify(cert_id):
    """Any signed-in user other than the certificate holder can vouch for
    it (mentor/employer-style peer verification) — never self-verified."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    row = SkillCertification.query.get(cert_id)
    if not row:
        return jsonify({"error": "Not found."}), 404
    if row.user_id == user["id"]:
        return jsonify({"error": "You can't verify your own certification."}), 400
    row.verified = True
    row.verified_by_email = user.get("email")
    db.session.commit()
    return jsonify({"ok": True, "certification": row.to_dict()}), 200


