# Businesses already running HR/payroll here can post real openings
# instead of a third-party board. /api/jobs/match closes the loop the
# existing CV Builder + ATS Score tools started: it AI-ranks a job
# seeker's CV against every open listing and returns the best fits
# with a plain-language reason, instead of leaving them to search
# and re-paste their CV one listing at a time.
# ════════════════════════════════════════════════════════════

# ════════════════════════════════════════════════════════════
# STAGE 70: AI CV MATCHING against the existing job board
# The job board (internal Job postings + external Adzuna/Jooble/
# Arbeitnow aggregation) already exists — this closes the loop with
# the CV Builder + ATS Score tools by AI-ranking every open listing
# (internal and external) against a candidate's actual CV, instead of
# leaving them to search and re-paste their CV one listing at a time.
# ════════════════════════════════════════════════════════════

@app.route("/api/jobs/match", methods=["POST"])
@csrf.exempt
def jobs_match():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    gate_result = gate_ai_usage(user, "jobs_match")
    if gate_result is not None:
        return gate_result
    data = request.get_json(silent=True) or {}
    cv = (data.get("cv") or "").strip()
    if not cv:
        return jsonify({"error": "cv is required — paste your CV or a summary of your skills/experience."}), 400

    location = (data.get("location") or "").strip()
    internal = Job.query.filter_by(active=True)
    if location:
        internal = internal.filter(Job.location.ilike(f"%{location}%"))
    internal_jobs = [j.to_dict() for j in internal.order_by(Job.created_at.desc()).limit(20).all()]

    external_jobs = []
    try:
        external_jobs = fetch_external_jobs(cv[:60], location, False, limit=20)
    except Exception as e:
        logging.warning(f"[JOBS MATCH EXTERNAL] {e}")

    all_jobs = internal_jobs + external_jobs
    if not all_jobs:
        return jsonify({"ok": True, "matches": [], "message": "No open listings found right now — check back soon, or widen your search."}), 200

    # Give each candidate listing a stable index for the AI to reference,
    # since external listings don't have a DB id.
    for idx, j in enumerate(all_jobs):
        j["_match_idx"] = idx

    listing_block = "\n\n".join(
        f"[LISTING {j['_match_idx']}] {j.get('title')} at {j.get('company')} "
        f"({j.get('type') or j.get('job_type', 'full-time')}, {j.get('location') or 'location not specified'})\n"
        f"{(j.get('description') or '')[:400]}"
        for j in all_jobs
    )
    prompt = (
        "You are a job-matching assistant. Given this candidate's CV/skills and a list of open job "
        "listings, rank the top 5 best-fitting listings (or fewer if fewer than 5 are genuinely relevant). "
        "Respond ONLY with a valid JSON array, each item: "
        '{"match_idx": <int>, "fit_score": 0-100, "reason": "one sentence why this fits"}\n\n'
        f"CANDIDATE CV/SKILLS:\n{cv[:3000]}\n\n---\n\nOPEN LISTINGS:\n{listing_block}"
    )
    try:
        raw, _ = generate_ai_reply(prompt, [])
        cleaned = re.sub(r"^```json|```$", "", raw.strip(), flags=re.MULTILINE).strip()
        ranked = json.loads(cleaned)
    except Exception as e:
        logging.warning(f"[JOBS MATCH PARSE] {e}")
        return jsonify({"error": "Could not rank matches right now. Please try again."}), 502

    by_idx = {j["_match_idx"]: j for j in all_jobs}
    matches = []
    for r in ranked:
        job = by_idx.get(r.get("match_idx"))
        if job:
            clean_job = {k: v for k, v in job.items() if k != "_match_idx"}
            matches.append({**clean_job, "fit_score": r.get("fit_score"), "reason": r.get("reason")})
    return jsonify({"ok": True, "matches": matches}), 200


# ════════════════════════════════════════════════════════════
# STAGE 71: APIFY WEB DATA EXTRACTOR
# A generic BYOK bridge into Apify (apify.com) — used specifically for
# pulling data from pages that have no free public API: supplier price
# lists, tender/government portals, competitor sites, local business
# directories. More reliable than the ad-hoc requests.get() scraping
# used elsewhere in this file (e.g. the outage page), because
# Apify actors handle JS rendering, retries and blocking for you.
# /api/apify/scrape wraps the general-purpose "Website Content
# Crawler" actor for one-off lookups; /api/apify/run-actor is a raw
# bridge for any actor a power user already has, same shape as the
# Pivot Command Center bridge below.
# ════════════════════════════════════════════════════════════

def _apify_run_sync(user_id, actor_id: str, run_input: dict, timeout: int = 90):
    token = get_effective_credential(user_id, "apify", "api_token", None)
    if not token:
        return None, "Apify is not configured. Add your Apify API token under Integrations."
    try:
        # actor_id like "apify/website-content-crawler" must be
        # tilde-separated in the URL path per Apify's API convention.
        url = f"https://api.apify.com/v2/acts/{actor_id.replace('/', '~')}/run-sync-get-dataset-items"
        resp = requests.post(url, params={"token": token}, json=run_input, timeout=timeout)
        if resp.status_code >= 400:
            return None, f"Apify returned HTTP {resp.status_code}: {resp.text[:300]}"
        return resp.json(), None
    except requests.exceptions.Timeout:
        return None, "Apify run timed out — try a smaller crawl (fewer pages) or check back for results in the Apify console."
    except Exception as e:
        logging.error(f"[APIFY ERROR] user={user_id} actor={actor_id}: {e}")
        return None, str(e)


@app.route("/api/apify/scrape", methods=["POST"])
@csrf.exempt
def apify_scrape():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    target_url = (data.get("url") or "").strip()
    if not target_url:
        return jsonify({"error": "url is required."}), 400
    try:
        max_pages = max(1, min(int(data.get("max_pages", 1) or 1), 10))
    except (TypeError, ValueError):
        max_pages = 1

    items, err = _apify_run_sync(user["id"], "apify/website-content-crawler", {
        "startUrls": [{"url": target_url}],
        "maxCrawlPages": max_pages,
        "crawlerType": "cheerio",
    })
    if err:
        return jsonify({"error": err}), 502

    pages = []
    for item in (items or [])[:max_pages]:
        pages.append({
            "url": item.get("url"),
            "title": (item.get("metadata") or {}).get("title") or item.get("title"),
            "text": (item.get("text") or item.get("markdown") or "")[:6000],
        })
    return jsonify({"ok": True, "pages": pages}), 200


@app.route("/api/apify/run-actor", methods=["POST"])
@csrf.exempt
def apify_run_actor():
    """Raw bridge for any Apify actor a power user already runs
    themselves — same philosophy as the Pivot Command Center bridge:
    Connect It never hard-codes what the actor does, just relays the
    call and logs it."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    actor_id = (data.get("actor_id") or "").strip()
    run_input = data.get("input") or {}
    if not actor_id:
        return jsonify({"error": "actor_id is required (e.g. 'apify/website-content-crawler')."}), 400
    if not isinstance(run_input, dict):
        return jsonify({"error": "input must be a JSON object."}), 400

    items, err = _apify_run_sync(user["id"], actor_id, run_input)
    if err:
        return jsonify({"error": err}), 502
    return jsonify({"ok": True, "items": (items or [])[:50]}), 200


