# STAGE 61: PIVOT COMMAND CENTER
# A generic BYOK bridge for irrigation-pivot controllers. Never talks
# to one hard-coded vendor — the user supplies their own controller's
# base_url + bearer access_token (irrigation_pivot BYOK provider), and
# every command is written to PivotCommandLog for audit.
# ════════════════════════════════════════════════════════════

_PIVOT_ACTIONS = {"start", "stop", "rotate", "set_depth_mm", "set_runtime_hours"}


@app.route("/api/pivot/command", methods=["POST"])
@csrf.exempt
def pivot_command():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    data     = request.get_json(silent=True) or {}
    pivot_id = (data.get("pivot_id") or "").strip()
    action   = (data.get("action") or "").strip()
    value    = data.get("value")
    if not pivot_id or action not in _PIVOT_ACTIONS:
        return jsonify({"error": f"pivot_id is required and action must be one of {sorted(_PIVOT_ACTIONS)}."}), 400
    if action in ("set_depth_mm", "set_runtime_hours") and value is None:
        return jsonify({"error": f"'{action}' requires a numeric value."}), 400

    base_url = get_effective_credential(user["id"], "irrigation_pivot", "base_url", None)
    token    = get_effective_credential(user["id"], "irrigation_pivot", "access_token", None)
    if not base_url or not token:
        return jsonify({"error": "Connect your pivot controller under Integrations first (base_url + access_token)."}), 400

    log = PivotCommandLog(user_id=user["id"], pivot_id=pivot_id[:120], action=action, value=str(value) if value is not None else None)
    try:
        payload = {"action": action}
        if value is not None:
            payload["value"] = value
        resp = requests.post(
            base_url.rstrip("/") + f"/api/pivots/{pivot_id}/command",
            json=payload, headers={"Authorization": f"Bearer {token}"}, timeout=15,
        )
        log.status_code = resp.status_code
        log.success = resp.status_code < 300
        db.session.add(log)
        db.session.commit()
        return jsonify({"ok": log.success, "status_code": resp.status_code,
                         "controller_response": (resp.text or "")[:500]}), (200 if log.success else 502)
    except Exception as e:
        log.success = False
        db.session.add(log)
        db.session.commit()
        logging.error(f"[PIVOT COMMAND ERROR] {e}")
        return jsonify({"error": str(e)}), 500


@app.route("/api/pivot/history", methods=["GET"])
def pivot_history():
    user = _get_current_user()
