# STAGE 62: SMART HOME (Home Assistant)
# Home Assistant's REST API already normalises Tuya/SmartThings/
# Zigbee/Z-Wave devices behind one endpoint, so this is real, working
# device control rather than a vendor-specific integration guess.
# ════════════════════════════════════════════════════════════

def _ha_creds(user_id):
    base_url = get_effective_credential(user_id, "home_assistant", "base_url", None)
    token    = get_effective_credential(user_id, "home_assistant", "long_lived_token", None)
    return base_url, token


@app.route("/api/smarthome/devices", methods=["GET"])
def smarthome_devices():
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    base_url, token = _ha_creds(user["id"])
    if not base_url or not token:
        return jsonify({"error": "Connect Home Assistant under Integrations first (base_url + long_lived_token)."}), 400
    try:
        resp = requests.get(base_url.rstrip("/") + "/api/states",
                             headers={"Authorization": f"Bearer {token}"}, timeout=15)
        resp.raise_for_status()
        states = resp.json()
        controllable_domains = {"light", "switch", "media_player", "climate", "fan", "cover"}
        devices = [
            {"entity_id": s["entity_id"], "state": s.get("state"),
             "name": (s.get("attributes") or {}).get("friendly_name", s["entity_id"])}
            for s in states if s["entity_id"].split(".")[0] in controllable_domains
        ]
        return jsonify({"devices": devices}), 200
    except Exception as e:
        logging.error(f"[SMARTHOME DEVICES ERROR] {e}")
        return jsonify({"error": str(e)}), 500


@app.route("/api/smarthome/command", methods=["POST"])
@csrf.exempt
def smarthome_command():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    base_url, token = _ha_creds(user["id"])
    if not base_url or not token:
        return jsonify({"error": "Connect Home Assistant under Integrations first."}), 400
    data      = request.get_json(silent=True) or {}
    entity_id = (data.get("entity_id") or "").strip()
    service   = (data.get("service") or "").strip()  # e.g. turn_on, turn_off, toggle
    extra     = data.get("service_data") or {}
    if not entity_id or "." not in entity_id or not service:
        return jsonify({"error": "entity_id and service are required."}), 400
    domain = entity_id.split(".")[0]
    try:
        body = {"entity_id": entity_id}
        body.update(extra)
        resp = requests.post(
            base_url.rstrip("/") + f"/api/services/{domain}/{service}",
            json=body, headers={"Authorization": f"Bearer {token}"}, timeout=15,
        )
        return jsonify({"ok": resp.status_code < 300, "status_code": resp.status_code}), (200 if resp.status_code < 300 else 502)
    except Exception as e:
        logging.error(f"[SMARTHOME COMMAND ERROR] {e}")
        return jsonify({"error": str(e)}), 500


# ════════════════════════════════════════════════════════════
# STAGE 323: SOLAR & BACKUP POWER MONITORING (Victron VRM)
# First of the IoT/device-management build-out — solar/inverter
# monitoring, picked first per the roadmap since Victron publishes the
# best-documented public API of the major inverter brands (Growatt,
# Deye, Huawei FusionSolar, SolarEdge are BYOK candidates for later
# stages, same shape: token + site id -> read-only status calls).
# Real, working reads against VRM API v2 (token auth via the
# X-Authorization header) — no scraping, no guessed endpoints.
# ════════════════════════════════════════════════════════════

VRM_API_BASE = "https://vrmapi.victronenergy.com/v2"

# VRM diagnostic "code" values this feature reads. These are the stable
# identifiers VRM documents (unlike the numeric "idbis" field ids, which
# Victron has said can shift between installations/firmware versions).
_VRM_CODE_SOC          = "SOC"                 # battery state of charge, %
_VRM_CODE_BATTERY_POWER = "TTG"                # kept for time-to-go if present
_VRM_CODE_PV_POWER     = "PvPowerOutput"       # solar yield right now, W
_VRM_CODE_BATTERY_W    = "BatteryPower"        # +charging / -discharging, W
_VRM_CODE_LOAD_W       = "AcConsumptionL1"     # household load, W
_VRM_CODE_GRID_W       = "GridL1"              # grid draw, W (0/absent off-grid)


class SolarAlertLog(db.Model):
    """One row per anomaly alert actually sent for a business's solar/
    backup-power site, so /api/solar/alerts/history can show what fired
    and when, and so check-alerts can avoid re-sending the same alert
    every time it's polled (see _solar_recent_alert_exists)."""
    __tablename__  = "solar_alert_log"
    id             = db.Column(db.Integer, primary_key=True)
    user_id        = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    alert_code     = db.Column(db.String(40), nullable=False)   # e.g. low_battery, depleting_soon, inverter_fault
    message        = db.Column(db.String(400), nullable=False)
    sent_via       = db.Column(db.String(20), nullable=True)    # whatsapp, none (no destination on file)
    created_at     = db.Column(db.DateTime, default=datetime.utcnow, index=True)

    def to_dict(self):
        return {
            "id": self.id, "alert_code": self.alert_code, "message": self.message,
            "sent_via": self.sent_via,
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }


def _vrm_creds(user_id):
    token = get_effective_credential(user_id, "victron_vrm", "api_token", None)
    site_id = get_effective_credential(user_id, "victron_vrm", "installation_id", None)
    return token, site_id


def _vrm_get(token, path):
    """GET against VRM API v2. Raises on transport/HTTP error so callers
    can turn it into one clear error response instead of a partial/odd
    payload silently reaching the dashboard."""
    resp = requests.get(
        VRM_API_BASE + path,
        headers={"X-Authorization": f"Token {token}"},
        timeout=15,
    )
    resp.raise_for_status()
    return resp.json()


def _vrm_diagnostics_map(token, site_id):
    """VRM's /diagnostics endpoint returns a flat list of the latest
    reading per data point, each tagged with a stable 'code'. Reducing
    it to {code: value} once here keeps every reader below simple,
    instead of each one re-scanning the raw list."""
    data = _vrm_get(token, f"/installations/{site_id}/diagnostics")
    records = data.get("records") or data.get("data") or []
    out = {}
    for rec in records:
        code = rec.get("code")
        if code:
            out[code] = rec.get("formattedValue", rec.get("rawValue", rec.get("value")))
    return out


def _solar_status_for(user_id):
    """STAGE 329: Dispatches to whichever inverter/solar provider this
    business actually has connected — Victron VRM (Stage 323, checked
    first since it was already live), then SolarEdge, Growatt, Deye,
    or Huawei FusionSolar, in that order, first-configured-wins. Every
    provider function below normalizes to the exact same status_dict
    shape VRM already returns, so the dashboard, alert scanner, and
    energy-cost estimate (Stage 328) work identically regardless of
    which brand a business actually has installed — none of them had
    to change to support this.
    Returns (status_dict, error), status_dict is None on failure."""
    token, site_id = _vrm_creds(user_id)
    if token and site_id:
        return _victron_status(token, site_id)
    api_key, se_site = _solaredge_creds(user_id)
    if api_key and se_site:
        return _solaredge_status(api_key, se_site)
    gw_token, gw_plant = _growatt_creds(user_id)
    if gw_token and gw_plant:
        return _growatt_status(gw_token, gw_plant)
    app_id, app_secret, deye_user, deye_pass, station_id = _deye_creds(user_id)
    if app_id and app_secret and deye_user and deye_pass and station_id:
        return _deye_status(app_id, app_secret, deye_user, deye_pass, station_id)
    hw_user, hw_pass, hw_domain, hw_station = _huawei_creds(user_id)
    if hw_user and hw_pass and hw_domain and hw_station:
        return _huawei_status(hw_user, hw_pass, hw_domain, hw_station)
    return None, ("Connect a solar/inverter provider under Integrations first "
                   "(Victron VRM, SolarEdge, Growatt, Deye, or Huawei FusionSolar).")


def _victron_status(token, site_id):
    """The original Stage 323 implementation — unchanged behaviour,
    just extracted so the multi-provider dispatcher above can call it
    alongside the newer brands."""
    try:
        diag = _vrm_diagnostics_map(token, site_id)

        def _num(code):
            v = diag.get(code)
            if v is None:
                return None
            try:
                return float(str(v).split()[0].replace(",", ""))
            except (ValueError, IndexError):
                return None

        soc        = _num(_VRM_CODE_SOC)
        pv_w       = _num(_VRM_CODE_PV_POWER) or 0.0
        battery_w  = _num(_VRM_CODE_BATTERY_W) or 0.0
        load_w     = _num(_VRM_CODE_LOAD_W) or 0.0
        grid_w     = _num(_VRM_CODE_GRID_W) or 0.0

        if grid_w and grid_w > 5:
            source = "grid"
        elif pv_w and pv_w > load_w:
            source = "solar"
        elif battery_w and battery_w < 0:
            source = "battery"
        else:
            source = "solar" if pv_w > 0 else "battery"

        minutes_to_empty = None
        if soc is not None and battery_w is not None and battery_w < 0:
            capacity_wh = _num("CapacityWh") or 5000.0
            remaining_wh = capacity_wh * (soc / 100.0)
            draw_w = abs(battery_w)
            if draw_w > 1:
                minutes_to_empty = round((remaining_wh / draw_w) * 60)

        return {
            "provider": "victron_vrm",
            "battery_soc_pct": soc, "pv_power_w": pv_w, "battery_power_w": battery_w,
            "load_power_w": load_w, "grid_power_w": grid_w, "source": source,
            "minutes_to_empty_estimate": minutes_to_empty,
            "fetched_at": datetime.utcnow().isoformat(),
        }, None
    except requests.exceptions.HTTPError as e:
        logging.error(f"[VRM STATUS ERROR] {e}")
        return None, "VRM rejected the request — check the API token and installation id under Integrations."
    except Exception as e:
        logging.error(f"[VRM STATUS ERROR] {e}")
        return None, str(e)


# ────────────────────────────────────────────────────────────
# STAGE 329: ADDITIONAL INVERTER BRANDS (SolarEdge, Growatt, Deye,
# Huawei FusionSolar) — extends Stage 323's single-provider (Victron
# VRM) solar monitoring to the rest of the roadmap's named brands.
# Each of these vendor APIs has a different auth scheme and none is as
# cleanly documented/stable as VRM's, so every reader below is written
# defensively: it treats a missing/renamed field as "unknown" (None)
# rather than raising, and callers already handle a mostly-empty status
# dict gracefully (the dashboard shows "—" for anything not returned).
# If a vendor changes a field name or endpoint path, that shows up as
# blank readings rather than a broken dashboard — same trade-off VRM's
# own capacity-estimate fallback already makes above.
# ────────────────────────────────────────────────────────────

def _solaredge_creds(user_id):
    api_key = get_effective_credential(user_id, "solaredge", "api_key", None)
    site_id = get_effective_credential(user_id, "solaredge", "site_id", None)
    return api_key, site_id


def _solaredge_status(api_key, site_id):
    """SolarEdge Monitoring API — api_key auth via query param, real
    documented endpoint (monitoringapi.solaredge.com). currentPowerFlow
    reports PV/load/grid/storage in kW; storage (battery) is only
    present for sites with a battery attached, hence the .get() guards."""
    try:
        resp = requests.get(
            f"https://monitoringapi.solaredge.com/site/{site_id}/currentPowerFlow.json",
            params={"api_key": api_key}, timeout=15,
        )
        resp.raise_for_status()
        flow = (resp.json() or {}).get("siteCurrentPowerFlow", {})
        unit = (flow.get("unit") or "kW").lower()
        mult = 1000.0 if unit == "kw" else 1.0

        def _w(key):
            node = flow.get(key) or {}
            val = node.get("currentPower")
            return round(float(val) * mult, 1) if val is not None else None

        pv_w = _w("PV") or 0.0
        load_w = _w("LOAD") or 0.0
        grid_node = flow.get("GRID") or {}
        grid_w = (_w("GRID") or 0.0) if grid_node.get("status") != "Disabled" else 0.0
        storage_node = flow.get("STORAGE") or {}
        battery_w_raw = _w("STORAGE")
        # SolarEdge reports storage as a magnitude + separate charging
        # flag rather than a signed wattage like VRM — normalize to the
        # same signed convention (+charging / -discharging) other
        # providers use so the dashboard's single formatter works for all.
        battery_w = None
        if battery_w_raw is not None:
            battery_w = battery_w_raw if storage_node.get("status") == "Charging" else -battery_w_raw
        soc = storage_node.get("chargeLevel")

        source = "grid" if grid_w and grid_w > 5 else ("solar" if pv_w > load_w else "battery")
        return {
            "provider": "solaredge",
            "battery_soc_pct": float(soc) if soc is not None else None,
            "pv_power_w": pv_w, "battery_power_w": battery_w,
            "load_power_w": load_w, "grid_power_w": grid_w, "source": source,
            "minutes_to_empty_estimate": None,  # SolarEdge doesn't expose usable battery capacity via this endpoint
            "fetched_at": datetime.utcnow().isoformat(),
        }, None
    except requests.exceptions.HTTPError as e:
        logging.error(f"[SOLAREDGE STATUS ERROR] {e}")
        return None, "SolarEdge rejected the request — check the API key and site id under Integrations."
    except Exception as e:
        logging.error(f"[SOLAREDGE STATUS ERROR] {e}")
        return None, str(e)


def _growatt_creds(user_id):
    token = get_effective_credential(user_id, "growatt", "api_token", None)
    plant_id = get_effective_credential(user_id, "growatt", "plant_id", None)
    return token, plant_id


def _growatt_status(token, plant_id):
    """Growatt's Open Platform API (server.growatt.com/v1) — bearer
    token issued by Growatt for a registered app, scoped to a plant_id.
    Growatt's API has historically shifted between an unofficial
    cookie-session API and this token-based Open API; this targets the
    documented Open API endpoint (plant/data). Field names below follow
    Growatt's own docs (pac = current AC power output, soc = battery
    state of charge on hybrid/storage plants only)."""
    try:
        resp = requests.get(
            f"https://server.growatt.com/v1/plant/{plant_id}/data",
            headers={"Authorization": f"Bearer {token}"}, timeout=15,
        )
        resp.raise_for_status()
        data = (resp.json() or {}).get("data", resp.json() or {})
        pv_w = float(data.get("pac", 0) or 0) * 1000  # Growatt reports pac in kW
        load_w = float(data.get("userLoad", data.get("pLoad", 0)) or 0) * 1000
        grid_w = float(data.get("pToGrid", data.get("pFromGrid", 0)) or 0) * 1000
        soc = data.get("soc")
        battery_w = data.get("pBattery")
        battery_w = float(battery_w) * 1000 if battery_w is not None else None
        source = "grid" if grid_w and grid_w > 5 else ("solar" if pv_w > load_w else "battery")
        return {
            "provider": "growatt",
            "battery_soc_pct": float(soc) if soc is not None else None,
            "pv_power_w": round(pv_w, 1), "battery_power_w": round(battery_w, 1) if battery_w is not None else None,
            "load_power_w": round(load_w, 1), "grid_power_w": round(grid_w, 1), "source": source,
            "minutes_to_empty_estimate": None,
            "fetched_at": datetime.utcnow().isoformat(),
        }, None
    except requests.exceptions.HTTPError as e:
        logging.error(f"[GROWATT STATUS ERROR] {e}")
        return None, "Growatt rejected the request — check the API token and plant id under Integrations."
    except Exception as e:
        logging.error(f"[GROWATT STATUS ERROR] {e}")
        return None, str(e)


def _deye_creds(user_id):
    app_id = get_effective_credential(user_id, "deye", "app_id", None)
    app_secret = get_effective_credential(user_id, "deye", "app_secret", None)
    username = get_effective_credential(user_id, "deye", "username", None)
    password = get_effective_credential(user_id, "deye", "password", None)
    station_id = get_effective_credential(user_id, "deye", "station_id", None)
    return app_id, app_secret, username, password, station_id


def _deye_status(app_id, app_secret, username, password, station_id):
    """Deye inverters are commonly monitored via the Solarman Business
    API (open.dessmonitor.com / global.solarmanpv.com), which Deye's
    own app is white-labeled on top of. Auth is a two-step OAuth-style
    flow: exchange app_id/app_secret + the user's own portal
    username/password (SHA256-hashed, per Solarman's spec) for a short-
    lived access token, then call the station's realtime endpoint."""
    try:
        pw_hash = hashlib.sha256(password.encode()).hexdigest()
        token_resp = requests.post(
            "https://globalapi.solarmanpv.com/account/v1.0/token",
            params={"appId": app_id},
            json={"appSecret": app_secret, "email": username, "password": pw_hash},
            timeout=15,
        )
        token_resp.raise_for_status()
        access_token = (token_resp.json() or {}).get("access_token")
        if not access_token:
            return None, "Deye/Solarman login did not return an access token — check credentials."

        realtime_resp = requests.post(
            f"https://globalapi.solarmanpv.com/station/v1.0/realTime?language=en",
            headers={"Authorization": f"bearer {access_token}"},
            json={"stationId": int(station_id)}, timeout=15,
        )
        realtime_resp.raise_for_status()
        data = realtime_resp.json() or {}
        pv_w = float(data.get("generationPower", 0) or 0)
        load_w = float(data.get("usePower", 0) or 0)
        grid_w = float(data.get("gridPower", 0) or 0)
        battery_w = data.get("chargePower")
        soc = data.get("batterySoc")
        source = "grid" if grid_w and grid_w > 5 else ("solar" if pv_w > load_w else "battery")
        return {
            "provider": "deye",
            "battery_soc_pct": float(soc) if soc is not None else None,
            "pv_power_w": round(pv_w, 1), "battery_power_w": float(battery_w) if battery_w is not None else None,
            "load_power_w": round(load_w, 1), "grid_power_w": round(grid_w, 1), "source": source,
            "minutes_to_empty_estimate": None,
            "fetched_at": datetime.utcnow().isoformat(),
        }, None
    except requests.exceptions.HTTPError as e:
        logging.error(f"[DEYE STATUS ERROR] {e}")
        return None, "Deye/Solarman rejected the request — check app_id/app_secret/username/password/station id."
    except Exception as e:
        logging.error(f"[DEYE STATUS ERROR] {e}")
        return None, str(e)


def _huawei_creds(user_id):
    username = get_effective_credential(user_id, "huawei_fusionsolar", "username", None)
    password = get_effective_credential(user_id, "huawei_fusionsolar", "password", None)
    domain = get_effective_credential(user_id, "huawei_fusionsolar", "region_domain", None)
    station_code = get_effective_credential(user_id, "huawei_fusionsolar", "station_code", None)
    return username, password, domain, station_code


def _huawei_status(username, password, domain, station_code):
    """Huawei FusionSolar's Northbound (OpenAPI) interface — session
    auth via username/password against the region-specific domain (e.g.
    'sg5' for Southeast Asia, 'eu5' for Europe — shown in the installer
    portal's own URL), returning an xsrf token used on the follow-up
    real-time KPI call. Northbound access has to be requested from
    Huawei/the installer separately from a normal FusionSolar login."""
    try:
        base = f"https://{domain}.fusionsolar.huawei.com"
        login_resp = requests.post(
            f"{base}/thirdData/login",
            json={"userName": username, "systemCode": password}, timeout=15,
        )
        login_resp.raise_for_status()
        xsrf = login_resp.cookies.get("XSRF-TOKEN")
        if not xsrf or not login_resp.json().get("success"):
            return None, "Huawei FusionSolar login failed — check username/password and region domain."

        kpi_resp = requests.post(
            f"{base}/thirdData/getStationRealKpi",
            json={"stationCodes": station_code},
            headers={"XSRF-TOKEN": xsrf}, cookies=login_resp.cookies, timeout=15,
        )
        kpi_resp.raise_for_status()
        rows = kpi_resp.json().get("data") or []
        kpi = (rows[0].get("dataItemMap") if rows else {}) or {}
        pv_w = float(kpi.get("day_power", 0) or 0) * 1000
        load_w = float(kpi.get("use_power", 0) or 0) * 1000
        grid_w = float(kpi.get("on_grid_power", 0) or 0) * 1000
        soc = kpi.get("battery_soc")
        source = "grid" if grid_w and grid_w > 5 else ("solar" if pv_w > load_w else "battery")
        return {
            "provider": "huawei_fusionsolar",
            "battery_soc_pct": float(soc) if soc is not None else None,
            "pv_power_w": round(pv_w, 1), "battery_power_w": None,
            "load_power_w": round(load_w, 1), "grid_power_w": round(grid_w, 1), "source": source,
            "minutes_to_empty_estimate": None,
            "fetched_at": datetime.utcnow().isoformat(),
        }, None
    except requests.exceptions.HTTPError as e:
        logging.error(f"[HUAWEI STATUS ERROR] {e}")
        return None, "Huawei FusionSolar rejected the request — check credentials and region domain."
    except Exception as e:
        logging.error(f"[HUAWEI STATUS ERROR] {e}")
        return None, str(e)


@app.route("/api/solar/status", methods=["GET"])
def solar_status():
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    status, err = _solar_status_for(user["id"])
    if err:
        return jsonify({"error": err}), 400
    return jsonify({"status": status}), 200


@app.route("/api/solar/history", methods=["GET"])
def solar_history():
    """Battery SOC / PV yield over a lookback window, for a simple
    trend chart — thin pass-through of VRM's own overallstats endpoint
    rather than a re-implementation of its aggregation logic."""
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    token, site_id = _vrm_creds(user["id"])
    if not token or not site_id:
        return jsonify({"error": "Connect Victron VRM under Integrations first."}), 400
    try:
        data = _vrm_get(token, f"/installations/{site_id}/stats?type=live_feed")
        return jsonify({"history": data.get("records", data)}), 200
    except Exception as e:
        logging.error(f"[VRM HISTORY ERROR] {e}")
        return jsonify({"error": str(e)}), 500


def _solar_recent_alert_exists(user_id, alert_code, within_minutes=60):
    cutoff = datetime.utcnow() - timedelta(minutes=within_minutes)
    return SolarAlertLog.query.filter(
        SolarAlertLog.user_id == user_id, SolarAlertLog.alert_code == alert_code,
        SolarAlertLog.created_at >= cutoff,
    ).first() is not None


@app.route("/api/solar/check-alerts", methods=["POST"])
@csrf.exempt
def solar_check_alerts():
    """Compares live status against fixed, sane thresholds (battery
    critically low, or predicted to run out soon) and sends a WhatsApp
    alert the first time each condition is seen in a rolling hour —
    reuses the platform's existing WhatsApp Cloud rails rather than
    standing up a new notification channel for this one feature."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    status, err = _solar_status_for(user["id"])
    if err:
        return jsonify({"error": err}), 400

    fired = []
    checks = []
    soc = status.get("battery_soc_pct")
    mins = status.get("minutes_to_empty_estimate")
    if soc is not None and soc <= 15:
        checks.append(("low_battery", f"⚠️ Battery at {soc:.0f}% — critically low."))
    if mins is not None and mins <= 60:
        checks.append(("depleting_soon", f"⚠️ Battery estimated to run out in about {mins} minutes at the current draw."))

    account = UserAccount.query.get(user["id"])
    to_number = getattr(account, "whatsapp_number", None)

    for code, message in checks:
        if _solar_recent_alert_exists(user["id"], code):
            continue
        sent_via = None
        if to_number:
            try:
                send_whatsapp_cloud_message(user["id"], to_number, message)
                sent_via = "whatsapp"
            except Exception as e:
                logging.error(f"[SOLAR ALERT WHATSAPP ERROR] {e}")
        log = SolarAlertLog(user_id=user["id"], alert_code=code, message=message, sent_via=sent_via)
        db.session.add(log)
        fired.append(log)
    if fired:
        db.session.commit()
    return jsonify({"ok": True, "alerts_fired": [f.to_dict() for f in fired]}), 200


@app.route("/api/solar/alerts/history", methods=["GET"])
def solar_alerts_history():
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    rows = (SolarAlertLog.query.filter_by(user_id=user["id"])
            .order_by(SolarAlertLog.created_at.desc()).limit(50).all())
    return jsonify({"alerts": [r.to_dict() for r in rows]}), 200


# ════════════════════════════════════════════════════════════
# STAGE 324: PRINTER/SCANNER MONITORING (SNMP)
# Second IoT stage. Unlike Victron VRM (one cloud API), printers are
# reached directly over the LAN via SNMP — the vendor-agnostic standard
# protocol nearly every network printer speaks (RFC 3805 Printer MIB),
# so this covers HP/Canon/Epson/Brother/etc. with one client instead of
# per-brand integrations. A DeviceMaintenanceTicket model is introduced
# here rather than scoped just to printers, since the roadmap's next
# stage (full IT asset register) will raise the same kind of ticket for
# laptops/desktops and should share one ticket queue, not a second one.
# ════════════════════════════════════════════════════════════

# Standard Printer MIB (RFC 3805) OIDs — stable across vendors that
# implement the standard, which is effectively all network printers.
SNMP_OID_SYS_DESCR      = "1.3.6.1.2.1.1.1.0"
SNMP_OID_PRINTER_STATUS = "1.3.6.1.2.1.25.3.5.1.1.1.1"   # hrPrinterStatus: 1=other,2=unknown,3=idle,4=printing,5=warmup
SNMP_OID_DEVICE_STATUS  = "1.3.6.1.2.1.25.3.2.1.5.1"     # hrDeviceStatus: 1=unknown,2=running,3=warning,4=testing,5=down
SNMP_OID_TONER_LEVEL    = "1.3.6.1.2.1.43.11.1.1.9.1.1"  # prtMarkerSuppliesLevelValue (black/default, index .1)
SNMP_OID_TONER_MAX      = "1.3.6.1.2.1.43.11.1.1.8.1.1"  # prtMarkerSuppliesMaxCapacity
SNMP_OID_PAGE_COUNT     = "1.3.6.1.2.1.43.10.2.1.4.1.1"  # prtMarkerLifeCount
SNMP_OID_ALERT_DESC     = "1.3.6.1.2.1.43.18.1.1.8.1.1"  # prtAlertDescription (first active alert, e.g. "Paper Jam")

_HR_PRINTER_STATUS_LABELS = {1: "other", 2: "unknown", 3: "idle", 4: "printing", 5: "warmup"}
_HR_DEVICE_STATUS_LABELS  = {1: "unknown", 2: "running", 3: "warning", 4: "testing", 5: "down"}


class PrinterDevice(db.Model):
    """A network printer/scanner a business has registered for
    monitoring. SNMP has no concept of an account, so unlike the VRM/HA
    integrations above there's nothing to authenticate against a cloud
    API — the community string is effectively a shared local password,
    stored the same encrypted way as any other credential via the
    existing BYOK helpers isn't applicable here (it's per-device, not
    per-provider), so it's stored directly on the row."""
    __tablename__   = "printer_devices"
    id              = db.Column(db.Integer, primary_key=True)
    user_id         = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    name            = db.Column(db.String(120), nullable=False)
    host            = db.Column(db.String(255), nullable=False)
    port            = db.Column(db.Integer, nullable=False, default=161)
    community       = db.Column(db.String(120), nullable=False, default="public")
    snmp_version    = db.Column(db.String(4), nullable=False, default="2c")  # "1" or "2c"
    last_status     = db.Column(db.String(20), nullable=True)   # idle, printing, warmup, offline, fault
    last_toner_pct  = db.Column(db.Float, nullable=True)
    last_page_count = db.Column(db.Integer, nullable=True)
    last_checked_at = db.Column(db.DateTime, nullable=True)
    created_at      = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        return {
            "id": self.id, "name": self.name, "host": self.host, "port": self.port,
            "snmp_version": self.snmp_version, "last_status": self.last_status,
            "last_toner_pct": self.last_toner_pct, "last_page_count": self.last_page_count,
            "last_checked_at": self.last_checked_at.isoformat() if self.last_checked_at else None,
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }


class DeviceMaintenanceTicket(db.Model):
    """Shared ticket queue for any monitored device reporting a fault —
    starts here with printers, meant to be reused (not re-modeled) once
    the IT asset register stage adds laptops/desktops."""
    __tablename__  = "device_maintenance_tickets"
    id             = db.Column(db.Integer, primary_key=True)
    user_id        = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    device_kind    = db.Column(db.String(20), nullable=False)   # printer, solar, it_asset (future)
    device_ref_id  = db.Column(db.Integer, nullable=True)       # e.g. PrinterDevice.id
    device_label   = db.Column(db.String(120), nullable=False)
    issue          = db.Column(db.String(300), nullable=False)
    severity       = db.Column(db.String(10), nullable=False, default="warning")  # warning, critical
    status         = db.Column(db.String(15), nullable=False, default="open", index=True)  # open, resolved
    created_at     = db.Column(db.DateTime, default=datetime.utcnow, index=True)
    resolved_at    = db.Column(db.DateTime, nullable=True)

    def to_dict(self):
        return {
            "id": self.id, "device_kind": self.device_kind, "device_ref_id": self.device_ref_id,
            "device_label": self.device_label, "issue": self.issue, "severity": self.severity,
            "status": self.status,
            "created_at": self.created_at.isoformat() if self.created_at else None,
            "resolved_at": self.resolved_at.isoformat() if self.resolved_at else None,
        }


def _snmp_get(host, community, oid, port=161, version="2c", timeout=3):
    """Single SNMP GET. Returns the value as a string, or None if the
    device didn't return that OID (common — not every printer exposes
    every MIB branch, e.g. toner tables on some Brother models)."""
    mp_model = 0 if version == "1" else 1  # 0=SNMPv1, 1=SNMPv2c
    iterator = getCmd(
        SnmpEngine(),
        CommunityData(community, mpModel=mp_model),
        UdpTransportTarget((host, port), timeout=timeout, retries=1),
        ContextData(),
        ObjectType(ObjectIdentity(oid)),
    )
    error_indication, error_status, error_index, var_binds = next(iterator)
    if error_indication or error_status:
        return None
    for _, value in var_binds:
        return str(value)
    return None


def _printer_poll(device: "PrinterDevice"):
    """Polls one registered printer and returns a status dict without
    writing to the DB — callers decide whether to persist (the list
    endpoint refreshes+saves; a future scheduled job could poll without
    saving if ever needed)."""
    if not PYSNMP_AVAILABLE:
        return {"error": "SNMP support is not installed on the server (pip install pysnmp)."}
    try:
        raw_status = _snmp_get(device.host, device.community, SNMP_OID_PRINTER_STATUS, device.port, device.snmp_version)
        raw_device = _snmp_get(device.host, device.community, SNMP_OID_DEVICE_STATUS, device.port, device.snmp_version)
        toner_val  = _snmp_get(device.host, device.community, SNMP_OID_TONER_LEVEL, device.port, device.snmp_version)
        toner_max  = _snmp_get(device.host, device.community, SNMP_OID_TONER_MAX, device.port, device.snmp_version)
        page_count = _snmp_get(device.host, device.community, SNMP_OID_PAGE_COUNT, device.port, device.snmp_version)
        alert_desc = _snmp_get(device.host, device.community, SNMP_OID_ALERT_DESC, device.port, device.snmp_version)

        if raw_status is None and raw_device is None:
            return {"status": "offline", "toner_pct": None, "page_count": None, "alert": None}

        status = _HR_PRINTER_STATUS_LABELS.get(int(raw_status), "unknown") if raw_status else \
                 _HR_DEVICE_STATUS_LABELS.get(int(raw_device), "unknown") if raw_device else "unknown"
        if alert_desc:
            status = "fault"

        toner_pct = None
        try:
            if toner_val is not None and toner_max is not None and float(toner_max) > 0:
                toner_pct = round((float(toner_val) / float(toner_max)) * 100, 1)
        except (ValueError, TypeError):
            pass

        return {
            "status": status, "toner_pct": toner_pct,
            "page_count": int(page_count) if page_count and page_count.isdigit() else None,
            "alert": alert_desc,
        }
    except Exception as e:
        logging.error(f"[SNMP POLL ERROR] {device.host}: {e}")
        return {"status": "offline", "toner_pct": None, "page_count": None, "alert": None}


def _printer_raise_ticket_if_needed(user_id, device, poll_result):
    """Auto-creates a maintenance ticket on jam/fault/critically-low
    toner or an offline device — skips if an open ticket for the same
    device+issue already exists, so polling every dashboard load doesn't
    spam duplicate tickets."""
    issue = None
    severity = "warning"
    if poll_result.get("alert"):
        issue = f"Alert reported: {poll_result['alert']}"
        severity = "critical"
    elif poll_result.get("status") == "offline":
        issue = "Device is not responding (offline)."
        severity = "warning"
    elif poll_result.get("status") == "fault":
        issue = "Device reporting a fault condition."
        severity = "critical"
    elif poll_result.get("toner_pct") is not None and poll_result["toner_pct"] <= 10:
        issue = f"Toner critically low ({poll_result['toner_pct']:.0f}%)."
        severity = "warning"
    if not issue:
        return None
    existing = DeviceMaintenanceTicket.query.filter_by(
        user_id=user_id, device_kind="printer", device_ref_id=device.id, issue=issue, status="open").first()
    if existing:
        return None
    ticket = DeviceMaintenanceTicket(
        user_id=user_id, device_kind="printer", device_ref_id=device.id,
        device_label=device.name, issue=issue, severity=severity,
    )
    db.session.add(ticket)
    return ticket


