    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    device = PrinterDevice.query.filter_by(id=device_id, user_id=user["id"]).first()
    if not device:
        return jsonify({"error": "Printer not found."}), 404
    if not PYSNMP_AVAILABLE:
        return jsonify({"error": "SNMP support is not installed on the server."}), 503
    result = _printer_poll(device)
    if "error" in result:
        return jsonify(result), 503
    device.last_status     = result["status"]
    device.last_toner_pct  = result["toner_pct"]
    device.last_page_count = result["page_count"]
    device.last_checked_at = datetime.utcnow()
    ticket = _printer_raise_ticket_if_needed(user["id"], device, result)
    db.session.commit()
    return jsonify({"printer": device.to_dict(), "alert": result.get("alert"),
                     "ticket_raised": ticket.to_dict() if ticket else None}), 200


