# ════════════════════════════════════════════════════════════
# STAGE 325: IT ASSET REGISTER (laptops/desktops/other equipment)
# Third IoT stage. Honestly scoped: a real agent-based fleet-monitoring
# product (like NinjaOne/Atera) needs an installed background service
# per machine, which this platform can't push out on its own. What's
# built instead is real and useful without that: a full asset register
# (serials, warranty, assigned employee, straight-line depreciation
# posted to the existing ERP ledger) plus an optional lightweight
# heartbeat — a one-line script run on a schedule (cron / Task
# Scheduler) that POSTs disk-free% and pending-patch status with the
# asset's own agent key. No installed agent; a plain HTTP call is
# enough for the two health signals in scope (disk, patch status),
# and it fires into the same DeviceMaintenanceTicket queue Stage 324
# introduced rather than a third ticket table.
# ════════════════════════════════════════════════════════════

IT_ASSET_CATEGORIES = ("laptop", "desktop", "monitor", "printer_hardware", "network", "other")


class ITAsset(db.Model):
    __tablename__       = "it_assets"
    id                  = db.Column(db.Integer, primary_key=True)
    user_id             = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    name                = db.Column(db.String(120), nullable=False)
    category            = db.Column(db.String(20), nullable=False, default="laptop")
    serial_number       = db.Column(db.String(120), nullable=True)
    assigned_to         = db.Column(db.String(120), nullable=True)   # employee name/email, free text
    purchase_date       = db.Column(db.Date, nullable=True)
    purchase_cost       = db.Column(db.Float, nullable=False, default=0.0)
    salvage_value       = db.Column(db.Float, nullable=False, default=0.0)
    useful_life_years   = db.Column(db.Integer, nullable=False, default=3)
    warranty_expiry     = db.Column(db.Date, nullable=True)
    agent_key           = db.Column(db.String(40), nullable=False, unique=True)  # heartbeat auth, not a user session
    last_heartbeat_at   = db.Column(db.DateTime, nullable=True)
    last_disk_free_pct  = db.Column(db.Float, nullable=True)
    last_patch_pending  = db.Column(db.Boolean, nullable=True)
    last_depreciation_month = db.Column(db.String(7), nullable=True)  # "YYYY-MM" of last posted entry, prevents double-posting
    created_at          = db.Column(db.DateTime, default=datetime.utcnow)

    def book_value(self):
        if not self.purchase_date:
            return self.purchase_cost
        months_elapsed = max(0, (datetime.utcnow().date().year - self.purchase_date.year) * 12 +
                             (datetime.utcnow().date().month - self.purchase_date.month))
        total_months = max(1, self.useful_life_years * 12)
        monthly_dep = (self.purchase_cost - self.salvage_value) / total_months
        value = self.purchase_cost - (monthly_dep * min(months_elapsed, total_months))
        return round(max(self.salvage_value, value), 2)

    def heartbeat_status(self):
        if not self.last_heartbeat_at:
            return "no_agent"
        return "online" if (datetime.utcnow() - self.last_heartbeat_at) < timedelta(hours=26) else "offline"

    def to_dict(self, include_agent_key=False):
        d = {
            "id": self.id, "name": self.name, "category": self.category,
            "serial_number": self.serial_number, "assigned_to": self.assigned_to,
            "purchase_date": self.purchase_date.isoformat() if self.purchase_date else None,
            "purchase_cost": self.purchase_cost, "salvage_value": self.salvage_value,
            "useful_life_years": self.useful_life_years,
            "warranty_expiry": self.warranty_expiry.isoformat() if self.warranty_expiry else None,
            "book_value": self.book_value(), "heartbeat_status": self.heartbeat_status(),
            "last_heartbeat_at": self.last_heartbeat_at.isoformat() if self.last_heartbeat_at else None,
            "last_disk_free_pct": self.last_disk_free_pct, "last_patch_pending": self.last_patch_pending,
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }
        if include_agent_key:
            d["agent_key"] = self.agent_key
        return d


