@app.route("/api/assets/it/<int:asset_id>/agent-key", methods=["GET"])
def it_assets_agent_key(asset_id):
    """Returns the one-line heartbeat command for this asset (the agent
    key is only ever shown to the asset's own owner, never on the list
    endpoint, so it isn't exposed by a casual GET /api/assets/it)."""
    user, err = _erp_user_or_401()
    if err: return err
    asset = ITAsset.query.filter_by(id=asset_id, user_id=user["id"]).first()
    if not asset:
        return jsonify({"error": "Asset not found."}), 404
    heartbeat_url = request.url_root.rstrip("/") + f"/api/assets/it/{asset.id}/heartbeat"
    script = (
        f'curl -s -X POST "{heartbeat_url}" -H "Content-Type: application/json" -d '
        f'"{{\\"agent_key\\":\\"{asset.agent_key}\\",'
        f'\\"disk_free_pct\\":$(df / | tail -1 | awk \'{{print 100-$5}}\' | tr -d \'%\'),'
        f'\\"patch_pending\\":false}}"'
    )
    return jsonify({
        "agent_key": asset.agent_key, "heartbeat_url": heartbeat_url,
        "example_cron_line": f"0 * * * * {script}",
        "note": "Run this on the machine itself (cron on Linux/Mac, Task Scheduler on Windows) — "
                "no installed agent, just a scheduled HTTP call reporting disk space. "
                "Adjust patch_pending to your own OS update check if you want that signal too.",
    }), 200


@app.route("/api/assets/it/<int:asset_id>/heartbeat", methods=["POST"])
@csrf.exempt
def it_assets_heartbeat(asset_id):
    """Authenticated by the asset's own agent_key, not a user session —
    this is called from a machine's cron job, which has no browser
    session/CSRF token to present."""
    data = request.get_json(silent=True) or {}
    agent_key = (data.get("agent_key") or "").strip()
    asset = ITAsset.query.filter_by(id=asset_id).first()
    if not asset or not agent_key or not hmac.compare_digest(agent_key, asset.agent_key):
        return jsonify({"error": "Invalid asset id or agent key."}), 403
    try:
        disk_free_pct = data.get("disk_free_pct")
        asset.last_disk_free_pct = float(disk_free_pct) if disk_free_pct is not None else asset.last_disk_free_pct
    except (TypeError, ValueError):
        pass
    asset.last_patch_pending = bool(data.get("patch_pending")) if "patch_pending" in data else asset.last_patch_pending
    asset.last_heartbeat_at = datetime.utcnow()

    ticket = None
    issue = None
    if asset.last_disk_free_pct is not None and asset.last_disk_free_pct <= 10:
        issue = f"Disk space critically low ({asset.last_disk_free_pct:.0f}% free)."
    elif asset.last_patch_pending:
        issue = "Pending OS/security updates not yet installed."
    if issue:
        existing = DeviceMaintenanceTicket.query.filter_by(
            user_id=asset.user_id, device_kind="it_asset", device_ref_id=asset.id, issue=issue, status="open").first()
        if not existing:
            ticket = DeviceMaintenanceTicket(
                user_id=asset.user_id, device_kind="it_asset", device_ref_id=asset.id,
                device_label=asset.name, issue=issue, severity="warning",
            )
            db.session.add(ticket)
    db.session.commit()
    return jsonify({"ok": True, "ticket_raised": ticket.to_dict() if ticket else None}), 200


@app.route("/api/assets/it/<int:asset_id>/post-depreciation", methods=["POST"])
@csrf.exempt
def it_assets_post_depreciation(asset_id):
    """Posts this calendar month's straight-line depreciation as an
    expense to the existing ERP ledger — guarded by
    last_depreciation_month so re-clicking (or a monthly cron hitting
    this) never double-posts the same month."""
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    asset = ITAsset.query.filter_by(id=asset_id, user_id=user["id"]).first()
    if not asset:
        return jsonify({"error": "Asset not found."}), 404
    this_month = datetime.utcnow().strftime("%Y-%m")
    if asset.last_depreciation_month == this_month:
        return jsonify({"error": f"Depreciation for {this_month} was already posted for this asset."}), 400
    total_months = max(1, asset.useful_life_years * 12)
    monthly_dep = round((asset.purchase_cost - asset.salvage_value) / total_months, 2)
    if monthly_dep <= 0:
        return jsonify({"error": "Nothing to depreciate (cost already at or below salvage value)."}), 400
    _erp_post_ledger(
        user["id"], datetime.utcnow().date(), "expense", "Depreciation",
        f"Monthly depreciation — {asset.name}" + (f" (S/N {asset.serial_number})" if asset.serial_number else ""),
        -monthly_dep, ref_type="it_asset", ref_id=asset.id,
    )
    asset.last_depreciation_month = this_month
    db.session.commit()
    return jsonify({"ok": True, "amount_posted": monthly_dep, "book_value": asset.book_value()}), 200


# ════════════════════════════════════════════════════════════
# STAGE 328: UNIFIED DEVICES DASHBOARD
# The four device integrations above (Smart Home, Solar/VRM, Printer/
# SNMP, IT Asset Register) each already work as standalone panels, but
# a business with several of them connected had to click into each one
# separately to see if anything needed attention. This stage adds one
# aggregate view: a single overview call that pulls a summary from
# whichever integrations are actually connected (skipping the rest
# rather than erroring), a merged view of DeviceMaintenanceTicket
# across all device kinds, and an energy-cost estimate that combines
# solar/grid load (VRM) with any Home Assistant power/energy sensors
# using the business's own electricity rate — the one genuinely new
# piece of data (rate) needed to turn raw watts into an actual cost.
# ════════════════════════════════════════════════════════════

def _devices_smarthome_summary(user_id):
    base_url, token = _ha_creds(user_id)
    if not base_url or not token:
        return {"connected": False}
    try:
        resp = requests.get(base_url.rstrip("/") + "/api/states",
                             headers={"Authorization": f"Bearer {token}"}, timeout=10)
        resp.raise_for_status()
        states = resp.json()
        controllable_domains = {"light", "switch", "media_player", "climate", "fan", "cover"}
        devices = [s for s in states if s["entity_id"].split(".")[0] in controllable_domains]
        on_count = sum(1 for s in devices if s.get("state") in ("on", "playing", "open", "heat", "cool"))
        return {"connected": True, "device_count": len(devices), "on_count": on_count}
    except Exception as e:
        logging.error(f"[DEVICES OVERVIEW - SMARTHOME ERROR] {e}")
        return {"connected": True, "error": "Could not reach Home Assistant."}


def _devices_solar_summary(user_id):
    token, site_id = _vrm_creds(user_id)
    se_key, se_site = _solaredge_creds(user_id)
    gw_token, gw_plant = _growatt_creds(user_id)
    deye_creds = _deye_creds(user_id)
    hw_creds = _huawei_creds(user_id)
    any_connected = (
        (token and site_id) or (se_key and se_site) or (gw_token and gw_plant)
        or all(deye_creds) or all(hw_creds)
    )
    if not any_connected:
        return {"connected": False}
    status, err = _solar_status_for(user_id)
    if err:
        return {"connected": True, "error": err}
    return {
        "connected": True, "provider": status.get("provider"),
        "battery_soc_pct": status.get("battery_soc_pct"),
        "source": status.get("source"), "load_power_w": status.get("load_power_w"),
        "minutes_to_empty_estimate": status.get("minutes_to_empty_estimate"),
    }


def _devices_printers_summary(user_id):
    rows = PrinterDevice.query.filter_by(user_id=user_id).all()
    if not rows:
        return {"connected": False}
    faults = sum(1 for r in rows if r.last_status in ("fault", "offline"))
    low_toner = sum(1 for r in rows if r.last_toner_pct is not None and r.last_toner_pct <= 10)
    return {"connected": True, "device_count": len(rows), "faults": faults, "low_toner": low_toner}


def _devices_it_assets_summary(user_id):
    rows = ITAsset.query.filter_by(user_id=user_id).all()
    if not rows:
        return {"connected": False}
    offline = sum(1 for r in rows if r.heartbeat_status() == "offline")
    total_book_value = round(sum(r.book_value() for r in rows), 2)
    return {"connected": True, "device_count": len(rows), "offline": offline, "total_book_value": total_book_value}


