@app.route("/api/devices/energy-summary", methods=["GET"])
def devices_energy_summary():
    """Combines whatever power/energy sources are actually connected —
    VRM's current household load, and any Home Assistant sensor entity
    that looks like a power meter (device_class power/energy, or a W/kW
    unit_of_measurement — smart-plug integrations commonly expose this
    without a device_class set) — into one daily cost estimate using
    the business's own electricity_rate_per_kwh. Any source that isn't
    connected is simply omitted rather than treated as an error, since
    a business may only have one of the two connected."""
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    account = UserAccount.query.get(user["id"])
    rate = account.electricity_rate_per_kwh or 0.0

    total_load_w = 0.0
    sources = []

    solar_status, solar_err = _solar_status_for(user["id"])
    if solar_status and not solar_err:
        load_w = solar_status.get("load_power_w") or 0.0
        total_load_w += load_w
        sources.append({"source": "solar_site_load", "watts": load_w})

    base_url, token = _ha_creds(user["id"])
    plug_devices = []
    if base_url and token:
        try:
            resp = requests.get(base_url.rstrip("/") + "/api/states",
                                 headers={"Authorization": f"Bearer {token}"}, timeout=10)
            resp.raise_for_status()
            for s in resp.json():
                if s["entity_id"].split(".")[0] != "sensor":
                    continue
                attrs = s.get("attributes") or {}
                unit = (attrs.get("unit_of_measurement") or "").lower()
                device_class = (attrs.get("device_class") or "").lower()
                if device_class != "power" and unit not in ("w", "kw"):
                    continue
                try:
                    val = float(s.get("state"))
                except (TypeError, ValueError):
                    continue
                watts = val * 1000 if unit == "kw" else val
                plug_devices.append({
                    "entity_id": s["entity_id"],
                    "name": attrs.get("friendly_name", s["entity_id"]),
                    "watts": round(watts, 1),
                })
                total_load_w += watts
        except Exception as e:
            logging.error(f"[DEVICES ENERGY SUMMARY - HA ERROR] {e}")

    daily_kwh = round((total_load_w * 24) / 1000, 2)
    daily_cost = round(daily_kwh * rate, 2)
    return jsonify({
        "total_load_w": round(total_load_w, 1),
        "estimated_daily_kwh": daily_kwh,
        "estimated_daily_cost": daily_cost,
        "currency": account.electricity_currency,
        "rate_per_kwh": rate,
        "sources": sources,
        "power_sensors": plug_devices,
        "note": "Estimate assumes the current load holds steady over 24h — a rough figure for trend-spotting, not a bill.",
    }), 200


# ════════════════════════════════════════════════════════════
# STAGE 63: PRINT-TO-PRINTER (email-to-print)
# The scoped-down, safe version of "control my printer from the
# platform" — sends a document as an email attachment to the
# printer's own email address, which HP ePrint, Canon PIXMA Cloud
# Link, Epson Email Print and Brother iPrint&Scan all support
# natively. No local agent, no remote shell, nothing installed.
# ════════════════════════════════════════════════════════════

@app.route("/api/print/send-to-printer", methods=["POST"])
@csrf.exempt
def print_send_to_printer():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    if not SENDGRID_AVAILABLE:
        return jsonify({"error": "Email sending is not configured on the server."}), 503
    data          = request.get_json(silent=True) or {}
    printer_email = sanitize_email(data.get("printer_email", ""))
    subject       = (data.get("subject") or "Document from Connect It")[:200]
    pdf_base64    = data.get("pdf_base64") or ""
    filename      = (data.get("filename") or "document.pdf")[:120]
    if not printer_email or not pdf_base64:
        return jsonify({"error": "printer_email and pdf_base64 are required."}), 400
    try:
        from sendgrid.helpers.mail import Attachment, FileContent, FileName, FileType, Disposition
        api_key    = get_effective_credential(user["id"], "sendgrid", "api_key", SENDGRID_API_KEY)
        from_email = get_effective_credential(user["id"], "sendgrid", "from_email", CONNECTIT_EMAIL)
        if not api_key:
            return jsonify({"error": "No email provider configured — connect SendGrid under Integrations."}), 400
        message = Mail(from_email=(from_email, "Connect It"), to_emails=printer_email,
                        subject=subject, html_content="Sent for printing via Connect It.")
        message.attachment = Attachment(
            FileContent(pdf_base64), FileName(filename), FileType("application/pdf"), Disposition("attachment"))
        sg_client = SendGridAPIClient(api_key)
        resp = sg_client.send(message)
        return jsonify({"ok": True, "status_code": resp.status_code}), 200
    except Exception as e:
        logging.error(f"[PRINT SEND ERROR] {e}")
        return jsonify({"error": str(e)}), 500


