def _erp_user_or_401():
    user = _get_current_user()
    if not user:
        return None, (jsonify({"error": "Login required."}), 401)
    return user, None


def _erp_parse_date(value, default=None):
    if not value:
        return default
    try:
        return datetime.strptime(value[:10], "%Y-%m-%d").date()
    except Exception:
        return default


def _erp_parse_datetime(value, default=None):
    if not value:
        return default
    try:
        return datetime.fromisoformat(value.replace("Z", "+00:00")).replace(tzinfo=None)
    except Exception:
        return default


def _erp_gen_number(prefix: str) -> str:
    return f"{prefix}-{datetime.utcnow().strftime('%y%m')}-{secrets.token_hex(3).upper()}"


def _erp_post_ledger(owner_user_id, entry_date, kind, account, description, amount, ref_type=None, ref_id=None):
    try:
        db.session.add(ErpLedgerEntry(
            owner_user_id=owner_user_id, entry_date=entry_date or datetime.utcnow().date(),
            kind=kind, account=account, description=description[:300] if description else None,
            amount=amount, reference_type=ref_type, reference_id=ref_id,
        ))
    except Exception as e:
        logging.error(f"[ERP LEDGER POST ERROR] {e}")


def _erp_apply_stock_delta(product_id, delta_qty):
    """Adjusts InventoryItem.quantity by delta_qty (positive=stock in,
    negative=stock out) when a line item references a product. Silently
    no-ops for free-text line items with no product_id."""
    if not product_id:
        return
    try:
        item = InventoryItem.query.get(product_id)
        if item:
            was_above_threshold = (item.threshold or 0) <= 0 or (item.quantity or 0) > (item.threshold or 0)
            item.quantity = (item.quantity or 0) + delta_qty
            # STAGE 300: fire "low_stock" the moment a stock-decreasing
            # change crosses the reorder threshold (only fires once per
            # crossing, not on every sale while already below it).
            if (delta_qty < 0 and (item.threshold or 0) > 0
                    and was_above_threshold and item.quantity <= item.threshold):
                fire_automation_trigger(_automation_org_id_for_user(item.user_id), "low_stock", {
                    "product_id": item.id,
                    "product_name": item.name,
                    "quantity": item.quantity,
                    "reorder_threshold": item.threshold,
                })
    except Exception as e:
        logging.error(f"[ERP STOCK ADJUST ERROR] product={product_id}: {e}")


def _erp_items_from_payload(items_payload, product_field="product_id"):
    """Shared line-item parsing for quotes/invoices/POs. Returns
    (parsed_items, subtotal). Pulls unit price from the linked product
    when the caller didn't supply one."""
    parsed, subtotal = [], 0.0
    for raw in (items_payload or []):
        desc = (raw.get("description") or "").strip()
        if not desc:
            continue
        product_id = raw.get(product_field)
        qty = float(raw.get("quantity", 1) or 1)
        price = raw.get("unit_price", raw.get("unit_cost"))
        if price is None and product_id:
            prod = InventoryItem.query.get(product_id)
            price = (prod.unit_price if prod and prod.unit_price is not None else 0) if prod else 0
        price = float(price or 0)
        line_total = round(qty * price, 2)
        subtotal += line_total
        parsed.append({"product_id": product_id, "description": desc[:300], "quantity": qty,
                        "price": price, "line_total": line_total})
    return parsed, round(subtotal, 2)


