@app.route("/api/erp/customers/<int:cid>", methods=["PUT", "DELETE"])
@csrf.exempt
def erp_customers_update(cid):
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    c = ErpCustomer.query.get(cid)
    if not c or c.owner_user_id != user["id"]: return jsonify({"error": "Customer not found."}), 404
    try:
        if request.method == "DELETE":
            c.active = False
        else:
            data = request.get_json(silent=True) or {}
            for f in ("name", "email", "phone", "address", "notes"):
                if f in data: setattr(c, f, data[f])
            if "active" in data: c.active = bool(data["active"])
        db.session.commit()
    except Exception as e:
        db.session.rollback(); logging.error(f"[ERP CUSTOMER UPDATE] {e}")
        return jsonify({"error": "Could not update customer."}), 500
    return jsonify({"customer": c.to_dict()}), 200


