@app.route("/api/erp/suppliers/<int:sid>", methods=["PUT", "DELETE"])
@csrf.exempt
def erp_suppliers_update(sid):
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    s = ErpSupplier.query.get(sid)
    if not s or s.owner_user_id != user["id"]: return jsonify({"error": "Supplier not found."}), 404
    try:
        if request.method == "DELETE":
            s.active = False
        else:
            data = request.get_json(silent=True) or {}
            for f in ("name", "email", "phone", "address", "notes"):
                if f in data: setattr(s, f, data[f])
            if "active" in data: s.active = bool(data["active"])
            # STAGE 132: if bank details are being changed and this supplier
            # already had bank details on file, log the change before
            # overwriting — this history is what the fraud scan checks.
            new_bank_name = data.get("bank_name", s.bank_name)
            new_bank_acct = data.get("bank_account_number", s.bank_account_number)
            if (s.bank_name or s.bank_account_number) and (
                new_bank_name != s.bank_name or new_bank_acct != s.bank_account_number
            ):
                db.session.add(SupplierBankChangeLog(
                    owner_user_id=user["id"], supplier_id=s.id,
                    old_bank_name=s.bank_name, old_account_number=s.bank_account_number,
                    new_bank_name=new_bank_name, new_account_number=new_bank_acct,
                ))
            if "bank_name" in data: s.bank_name = data["bank_name"]
            if "bank_account_number" in data: s.bank_account_number = data["bank_account_number"]
        db.session.commit()
    except Exception as e:
        db.session.rollback(); logging.error(f"[ERP SUPPLIER UPDATE] {e}")
        return jsonify({"error": "Could not update supplier."}), 500
    return jsonify({"supplier": s.to_dict()}), 200


