@app.route("/api/erp/products/barcode-lookup-external/<code>", methods=["GET"])
def erp_products_barcode_lookup_external(code):
    """Best-effort autofill for a barcode this business hasn't stocked
    before, using Open Food Facts' free public database (no key needed,
    strong coverage for packaged groceries/FMCG common in spaza/retail
    stock). Purely a convenience — if it's not found or the lookup
    fails, the merchant just types the product name themselves."""
    user, err = _erp_user_or_401()
    if err: return err
    code = (code or "").strip()
    if not code: return jsonify({"error": "barcode is required."}), 400
    try:
        resp = requests.get(f"https://world.openfoodfacts.org/api/v2/product/{code}.json", timeout=6)
        data = resp.json() if resp.ok else {}
        if data.get("status") == 1 and data.get("product"):
            p = data["product"]
            return jsonify({
                "found": True,
                "name": p.get("product_name") or p.get("generic_name") or "",
                "brand": p.get("brands", ""),
                "category": (p.get("categories", "").split(",")[0] or "").strip(),
                "image_url": p.get("image_front_small_url", ""),
            }), 200
    except Exception as e:
        logging.warning(f"[BARCODE EXTERNAL LOOKUP] {code}: {e}")
    return jsonify({"found": False}), 200


