# ════════════════════════════════════════════════════════════
# STAGE 524: BUY NOW, PAY LATER (BNPL) AT CHECKOUT — the genuinely
# missing consumer-facing installment option. BuyerFinancingApplication
# above is B2B trade financing (an apply-and-wait-for-a-confirmed-
# lender flow); this is a one-click checkout payment method with two
# real implementations, both gated behind the "bnpl_checkout" feature
# flag (see _seed_feature_flag above) so an admin has to explicitly
# unlock it:
#   1. Stripe-native Klarna / Afterpay-Clearpay / Affirm — Stripe is
#      the actual lender and funds the platform immediately, same as a
#      card. Zero balance-sheet risk to this platform. Just a
#      different payment_method_types entry on the Checkout Session.
#   2. "Pay in 4" — platform-native, self-funded. The seller is paid
#      the FULL order total up front (normal Trade Assurance escrow
#      hold + release, same as any other order) while the buyer only
#      pays 25% at checkout; the remaining 3 installments are charged
#      off-session, biweekly, straight to Connect It's own Stripe
#      balance via /api/cron/bnpl-installments-run. That means THIS
#      platform is the one carrying the receivable between now and the
#      last installment — real credit risk, which is exactly why this
#      whole feature (not just this one path) defaults locked.
# ════════════════════════════════════════════════════════════

BNPL_NATIVE_METHODS = {"klarna", "afterpay_clearpay", "affirm"}
BNPL_PAY_IN_4_NUM_INSTALLMENTS = 4
BNPL_INSTALLMENT_INTERVAL_DAYS = 14  # biweekly
BNPL_PAY_IN_4_MIN_AMOUNT = 30.0
BNPL_PAY_IN_4_CURRENCY = "USD"  # scope note below
BNPL_CHECKOUT_NOTE = ("'Pay in 4' splits this order into 4 equal payments every 2 weeks, charged "
                       "automatically to the card used today. Klarna/Afterpay/Affirm are billed and "
                       "serviced directly by that provider, not by Connect It.")


def _bnpl_checkout_enabled() -> bool:
    return _feature_enabled("bnpl_checkout")


def _bnpl_pay_in_4_max_amount(reputation_score: float) -> float:
    """Cap scales with the buyer's existing on-platform reputation score
    (see compute_buyer_reputation) rather than an external credit
    bureau — the same "use the platform's own real signals" approach
    as every other financial feature in this file. A brand-new buyer
    sits at the neutral 50-point baseline and still qualifies for the
    smaller cap; a track record of completed, undisputed, promptly-
    paid orders raises it."""
    if reputation_score >= 75:
        return 3000.0
    if reputation_score >= 50:
        return 1000.0
    return 0.0  # below neutral baseline — not eligible


def _bnpl_pay_in_4_eligibility(user_id: int, amount: float, currency: str):
    """Returns (eligible: bool, reason_if_not: str|None, reputation: dict).
    Checked both by the read-only /api/bnpl/eligibility quote endpoint
    and, again, server-side at the moment of checkout — never trust the
    frontend's earlier quote alone."""
    reputation = compute_buyer_reputation(user_id)
    if not _bnpl_checkout_enabled():
        return False, "Buy Now, Pay Later is not enabled on this account yet.", reputation
    if (currency or "USD").upper() != BNPL_PAY_IN_4_CURRENCY:
        # Honest scope note: 'Pay in 4' schedules 3 future off-session
        # charges over 6 weeks. Doing that safely across a live FX rate
        # that can move between installments is a separate, harder
        # problem (which rate applies to a late/retried charge?) — so
        # for now this is deliberately USD-only, unlike Klarna/Afterpay/
        # Affirm above (Stripe carries that FX risk for those, not us).
        return False, f"Pay in 4 is currently only available for {BNPL_PAY_IN_4_CURRENCY}-priced orders.", reputation
    if amount < BNPL_PAY_IN_4_MIN_AMOUNT:
        return False, f"Pay in 4 requires an order total of at least ${BNPL_PAY_IN_4_MIN_AMOUNT:.0f}.", reputation
    cap = _bnpl_pay_in_4_max_amount(reputation["score"])
    if cap <= 0:
        return False, "Your buyer standing doesn't yet qualify for Pay in 4 — complete a few orders first.", reputation
    if amount > cap:
        return False, f"This order exceeds what your current buyer standing qualifies for (${cap:,.0f}).", reputation
    return True, None, reputation


def _bnpl_build_pay_in_4_installment_amounts(total_amount: float):
    """Splits total_amount into BNPL_PAY_IN_4_NUM_INSTALLMENTS equal
    parts, with any rounding remainder folded into the last installment
    so the parts always sum exactly to total_amount (same pattern as
    the discount-collapse math in _create_product_order_checkout)."""
    n = BNPL_PAY_IN_4_NUM_INSTALLMENTS
    base = round(total_amount / n, 2)
    amounts = [base] * (n - 1)
    amounts.append(round(total_amount - sum(amounts), 2))
    return amounts


class BnplInstallmentPlan(db.Model):
    __tablename__       = "bnpl_installment_plans"
    id                  = db.Column(db.Integer, primary_key=True)
    order_id            = db.Column(db.Integer, db.ForeignKey("product_orders.id"), nullable=False, unique=True, index=True)
    buyer_id            = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    seller_id           = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    currency            = db.Column(db.String(8), nullable=False, default="USD")
    total_amount        = db.Column(db.Float, nullable=False)
    num_installments    = db.Column(db.Integer, nullable=False, default=4)
    installment_amount  = db.Column(db.Float, nullable=False)  # amount of installment #1 (later ones may differ by a cent — see .installments())
    # Saved off the deposit PaymentIntent's Checkout Session
    # (setup_future_usage='off_session') so the remaining installments
    # can be charged with the buyer offline — see the cron job below.
    stripe_customer_id       = db.Column(db.String(120), nullable=True)
    stripe_payment_method_id = db.Column(db.String(120), nullable=True)
    status               = db.Column(db.String(16), nullable=False, default="active", index=True)  # active, completed, defaulted, cancelled
    created_at           = db.Column(db.DateTime, default=datetime.utcnow, index=True)

    def installments(self):
        return (BnplInstallment.query.filter_by(plan_id=self.id)
                .order_by(BnplInstallment.seq.asc()).all())

    def to_dict(self):
        return {
            "id": self.id, "order_id": self.order_id, "currency": self.currency,
            "total_amount": self.total_amount, "num_installments": self.num_installments,
            "status": self.status, "created_at": self.created_at.isoformat() if self.created_at else None,
            "installments": [i.to_dict() for i in self.installments()],
            "note": BNPL_CHECKOUT_NOTE,
        }


class BnplInstallment(db.Model):
    __tablename__    = "bnpl_installments"
    id               = db.Column(db.Integer, primary_key=True)
    plan_id          = db.Column(db.Integer, db.ForeignKey("bnpl_installment_plans.id"), nullable=False, index=True)
    seq              = db.Column(db.Integer, nullable=False)  # 1-based position in the schedule
    amount           = db.Column(db.Float, nullable=False)
    due_date         = db.Column(db.Date, nullable=False, index=True)
    status           = db.Column(db.String(16), nullable=False, default="pending", index=True)  # pending, paid, retrying, failed
    stripe_payment_intent_id = db.Column(db.String(120), nullable=True)
    attempt_count    = db.Column(db.Integer, nullable=False, default=0)
    paid_at          = db.Column(db.DateTime, nullable=True)
    created_at       = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        return {
            "id": self.id, "seq": self.seq, "amount": self.amount,
            "due_date": self.due_date.isoformat() if self.due_date else None,
            "status": self.status, "attempt_count": self.attempt_count,
            "paid_at": self.paid_at.isoformat() if self.paid_at else None,
        }


def _bnpl_finalize_plan_from_session(order_id, session):
    """Called from the Stripe webhook right after a 'pay_in_4' Checkout
    Session completes — after _handle_marketplace_order_paid has already
    marked the order paid in full and opened its normal Trade Assurance
    hold. Builds the installment schedule and saves the Customer /
    PaymentMethod pair Stripe just captured (off-session-usable because
    the session set setup_future_usage='off_session') so the remaining
    installments can be charged later with the buyer offline. Idempotent
    — a webhook retry that hits this twice is a no-op the second time."""
    if not order_id:
        return
    try:
        order = ProductOrder.query.get(int(order_id))
    except (TypeError, ValueError):
        return
    if not order or BnplInstallmentPlan.query.filter_by(order_id=order.id).first():
        return
    metadata = session.get("metadata", {}) or {}
    try:
        total_amount = float(metadata.get("bnpl_total_amount") or order.total_price)
    except (TypeError, ValueError):
        total_amount = order.total_price
    customer_id = session.get("customer")
    payment_method_id = None
    pi_id = session.get("payment_intent")
    if pi_id and STRIPE_SECRET_KEY:
        try:
            import stripe
            stripe.api_key = STRIPE_SECRET_KEY
            pi = stripe.PaymentIntent.retrieve(pi_id)
            payment_method_id = pi.get("payment_method")
        except Exception as e:
            logging.error(f"[BNPL FINALIZE] Could not retrieve payment_intent {pi_id}: {e}")
    if not customer_id or not payment_method_id:
        logging.error(f"[BNPL FINALIZE] order={order.id} missing Stripe customer/payment_method — "
                       f"remaining installments cannot be auto-charged until this is fixed manually.")
    amounts = _bnpl_build_pay_in_4_installment_amounts(total_amount)
    plan = BnplInstallmentPlan(
        order_id=order.id, buyer_id=order.buyer_id, seller_id=order.seller_id,
        currency=order.currency, total_amount=total_amount, num_installments=len(amounts),
        installment_amount=amounts[0], stripe_customer_id=customer_id,
        stripe_payment_method_id=payment_method_id, status="active",
    )
    db.session.add(plan)
    db.session.flush()
    today = datetime.utcnow().date()
    for i, amt in enumerate(amounts):
        is_first = (i == 0)
        db.session.add(BnplInstallment(
            plan_id=plan.id, seq=i + 1, amount=amt,
            due_date=(today + timedelta(days=BNPL_INSTALLMENT_INTERVAL_DAYS * i)),
            status=("paid" if is_first else "pending"),
            stripe_payment_intent_id=(pi_id if is_first else None),
            paid_at=(datetime.utcnow() if is_first else None),
            attempt_count=(1 if is_first else 0),
        ))
    db.session.commit()
    logging.info(f"[BNPL] Pay-in-4 plan {plan.id} created for order {order.id} ({len(amounts)} installments).")


@app.route("/api/bnpl/eligibility", methods=["GET"])
def bnpl_eligibility():
    """Read-only quote for the checkout UI: given an amount + currency,
    what's available (Stripe-native rails need only the flag; 'pay_in_4'
    also needs a real eligibility check) — lets the Buy modal show or
    hide each option before the buyer ever clicks Buy Now."""
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    if not _bnpl_checkout_enabled():
        return jsonify({"enabled": False}), 200
    try:
        amount = float(request.args.get("amount", 0))
    except (TypeError, ValueError):
        amount = 0.0
    currency = (request.args.get("currency") or "USD").strip().upper()[:8]
    eligible, reason, reputation = _bnpl_pay_in_4_eligibility(user["id"], amount, currency)
    amounts = _bnpl_build_pay_in_4_installment_amounts(amount) if eligible else None
    return jsonify({
        "enabled": True,
        "native_methods": sorted(BNPL_NATIVE_METHODS),
        "pay_in_4": {
            "eligible": eligible, "reason": reason,
            "reputation_score": reputation["score"], "reputation_grade": reputation["grade"],
            "num_installments": BNPL_PAY_IN_4_NUM_INSTALLMENTS,
            "interval_days": BNPL_INSTALLMENT_INTERVAL_DAYS,
            "installment_amounts": amounts,
        },
        "note": BNPL_CHECKOUT_NOTE,
    }), 200


@app.route("/api/bnpl/plans/mine", methods=["GET"])
def bnpl_plans_mine():
    """Every 'Pay in 4' plan the current user is the buyer on, most
    recent first — includes the full installment schedule so the
    frontend can render due dates/status without a second round trip
    per plan."""
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    plans = (BnplInstallmentPlan.query.filter_by(buyer_id=user["id"])
             .order_by(BnplInstallmentPlan.created_at.desc()).limit(100).all())
    return jsonify({"ok": True, "plans": [p.to_dict() for p in plans]}), 200


def _platform_admin_or_401():
    """Shared admin gate for small platform-ops endpoints (BNPL exposure,
    chargebacks, etc.) that don't warrant their own bespoke admin-check
    each — same is_admin/ADMIN_EMAILS logic used across the file."""
    user, err = _erp_user_or_401()
    if err: return None, err
    email = (user.get("email") or "").strip().lower()
    is_admin = email in ADMIN_EMAILS
    if not is_admin:
        try:
            account = UserAccount.query.get(user["id"])
            is_admin = bool(account and account.is_admin)
        except Exception:
            is_admin = False
    if not is_admin:
        return None, (jsonify({"error": "Admin access required."}), 403)
    return user, None


@app.route("/api/admin/bnpl/plans", methods=["GET"])
def admin_bnpl_plans():
    """Admin visibility into the platform's own 'Pay in 4' receivable
    exposure — how much is still outstanding and owed to the platform
    by buyers, and which installments are overdue. This is the balance-
    sheet risk the bnpl_checkout flag's locked_reason warns about, made
    visible rather than left implicit."""
    user, err = _platform_admin_or_401()
    if err: return err
    plans = (BnplInstallmentPlan.query.order_by(BnplInstallmentPlan.created_at.desc()).limit(300).all())
    today = datetime.utcnow().date()
    outstanding_total = 0.0
    overdue_count = 0
    plan_dicts = []
    for p in plans:
        d = p.to_dict()
        for inst in d["installments"]:
            if inst["status"] in ("pending", "retrying"):
                outstanding_total += inst["amount"]
            if inst["status"] in ("pending", "retrying", "failed") and inst["due_date"] and inst["due_date"] < today.isoformat():
                overdue_count += 1
        plan_dicts.append(d)
    return jsonify({
        "ok": True, "plans": plan_dicts,
        "outstanding_total": round(outstanding_total, 2),
        "overdue_installment_count": overdue_count,
        "active_plan_count": len([p for p in plans if p.status == "active"]),
    }), 200


@app.route("/api/cron/bnpl-installments-run", methods=["POST"])
@csrf.exempt
def cron_bnpl_installments_run():
    """Charges every 'Pay in 4' installment that's now due, off-session,
    using the card saved on the plan's deposit PaymentIntent. Protected
    by CRON_SECRET, same pattern as every other /api/cron/* job on this
    server — see the CRON_SECRET comment near the top of this file.
    Meant to be pinged daily by an external scheduler (PythonAnywhere
    Task, system cron, etc.) since this server has no built-in one."""
    if not CRON_SECRET or request.headers.get("X-Cron-Secret") != CRON_SECRET:
        return jsonify({"error": "Not found."}), 403
    if not STRIPE_SECRET_KEY:
        return jsonify({"ok": True, "charged": 0, "failed": 0, "note": "Stripe not configured."}), 200
    import stripe
    stripe.api_key = STRIPE_SECRET_KEY
    today = datetime.utcnow().date()
    due = (BnplInstallment.query
           .filter(BnplInstallment.status.in_(["pending", "retrying"]))
           .filter(BnplInstallment.due_date <= today)
           .limit(500).all())
    charged, failed = 0, 0
    touched_plan_ids = set()
    for inst in due:
        plan = BnplInstallmentPlan.query.get(inst.plan_id)
        touched_plan_ids.add(inst.plan_id)
        if not plan or not plan.stripe_customer_id or not plan.stripe_payment_method_id:
            inst.status = "failed"
            failed += 1
            db.session.commit()
            continue
        try:
            pi = stripe.PaymentIntent.create(
                amount=int(round(inst.amount * 100)), currency=(plan.currency or "USD").lower(),
                customer=plan.stripe_customer_id, payment_method=plan.stripe_payment_method_id,
                off_session=True, confirm=True,
                metadata={"kind": "bnpl_installment", "plan_id": str(plan.id), "installment_id": str(inst.id)},
            )
            inst.status = "paid"
            inst.stripe_payment_intent_id = pi.id
            inst.paid_at = datetime.utcnow()
            inst.attempt_count = (inst.attempt_count or 0) + 1
            charged += 1
            try:
                notify_user(plan.buyer_id, "bnpl", "Pay in 4 installment charged",
                            f"Installment {inst.seq} of {plan.num_installments} "
                            f"({plan.currency} {inst.amount:.2f}) was charged successfully.")
            except Exception:
                pass
        except Exception as e:
            inst.attempt_count = (inst.attempt_count or 0) + 1
            inst.status = "failed" if inst.attempt_count >= 3 else "retrying"
            failed += 1
            logging.error(f"[BNPL INSTALLMENT CHARGE FAILED] installment={inst.id} attempt={inst.attempt_count}: {e}")
            try:
                notify_user(plan.buyer_id, "bnpl",
                            "Pay in 4 installment failed" if inst.status == "failed" else "Pay in 4 installment retry scheduled",
                            (f"We couldn't charge installment {inst.seq} of {plan.num_installments} after "
                             f"{inst.attempt_count} attempts. Please update your payment method.") if inst.status == "failed"
                            else f"We couldn't charge installment {inst.seq} — we'll try again soon.")
            except Exception:
                pass
        db.session.commit()
    # Mark plans complete once every installment on them is paid.
    try:
        for pid in touched_plan_ids:
            remaining = BnplInstallment.query.filter_by(plan_id=pid).filter(BnplInstallment.status != "paid").count()
            if remaining == 0:
                p = BnplInstallmentPlan.query.get(pid)
                if p and p.status == "active":
                    p.status = "completed"
        db.session.commit()
    except Exception as e:
        logging.error(f"[BNPL PLAN COMPLETE SWEEP ERROR] {e}")
    return jsonify({"ok": True, "charged": charged, "failed": failed, "checked": len(due)}), 200


# ════════════════════════════════════════════════════════════
# STAGE 525: CARD-NETWORK CHARGEBACK / PAYMENT-DISPUTE AUTOMATION
# Distinct from EscrowDispute above (a platform-mediated buyer<->seller
# conversation Connect It itself resolves) — a chargeback is filed by
# the buyer directly with their bank/card issuer, decided by the card
# network under its own rules and deadlines, and Connect It's only real
# lever is submitting evidence before evidence_due_by. Ingestion (the
# charge.dispute.* webhook branch above) and manual seller/admin
# response always work, regardless of the "chargeback_automation" flag
# — a seller needs to see and respond to a live case whether or not an
# admin has unlocked auto-response. The flag only gates whether the
# platform is ALSO allowed to auto-submit evidence on the seller's
# behalf for one narrow, well-evidenced case (see
# _chargeback_maybe_auto_respond).
# ════════════════════════════════════════════════════════════

CHARGEBACK_STRIPE_STATUSES = {
    "needs_response", "warning_needs_response", "warning_under_review", "warning_closed",
    "under_review", "charge_refunded", "won", "lost",
}


class PaymentChargeback(db.Model):
    __tablename__ = "payment_chargebacks"
    id                      = db.Column(db.Integer, primary_key=True)
    stripe_dispute_id       = db.Column(db.String(120), nullable=False, unique=True, index=True)
    stripe_charge_id        = db.Column(db.String(120), nullable=True)
    stripe_payment_intent_id = db.Column(db.String(120), nullable=True, index=True)
    order_id                = db.Column(db.Integer, db.ForeignKey("product_orders.id"), nullable=True, index=True)
    buyer_id                = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=True, index=True)
    seller_id               = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=True, index=True)
    amount                  = db.Column(db.Float, nullable=False)
    currency                = db.Column(db.String(8), nullable=False, default="USD")
    # Stripe's own reason code, kept verbatim (duplicate, fraudulent,
    # product_not_received, product_unacceptable, subscription_canceled,
    # unrecognized, credit_not_processed, general, etc.) — no invented
    # taxonomy on top of the card network's own classification.
    reason                  = db.Column(db.String(60), nullable=True)
    # Kept identical to Stripe's own dispute.status values — see
    # CHARGEBACK_STRIPE_STATUSES — rather than inventing a parallel
    # vocabulary that would drift from what Stripe's dashboard says.
    status                  = db.Column(db.String(32), nullable=False, default="needs_response", index=True)
    evidence_due_by         = db.Column(db.DateTime, nullable=True)
    funds_withdrawn         = db.Column(db.Boolean, nullable=False, default=False)
    funds_reinstated        = db.Column(db.Boolean, nullable=False, default=False)
    auto_response_submitted = db.Column(db.Boolean, nullable=False, default=False)
    auto_response_note      = db.Column(db.Text, nullable=True)
    seller_evidence_text    = db.Column(db.Text, nullable=True)
    seller_evidence_submitted_at = db.Column(db.DateTime, nullable=True)
    created_at              = db.Column(db.DateTime, default=datetime.utcnow, index=True)
    updated_at              = db.Column(db.DateTime, default=datetime.utcnow, onupdate=datetime.utcnow)

    def to_dict(self):
        return {
            "id": self.id, "stripe_dispute_id": self.stripe_dispute_id, "order_id": self.order_id,
            "amount": self.amount, "currency": self.currency, "reason": self.reason, "status": self.status,
            "evidence_due_by": self.evidence_due_by.isoformat() if self.evidence_due_by else None,
            "funds_withdrawn": self.funds_withdrawn, "funds_reinstated": self.funds_reinstated,
            "auto_response_submitted": self.auto_response_submitted, "auto_response_note": self.auto_response_note,
            "seller_evidence_text": self.seller_evidence_text,
            "seller_evidence_submitted_at": self.seller_evidence_submitted_at.isoformat() if self.seller_evidence_submitted_at else None,
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }


def _chargeback_order_for_payment_intent(payment_intent_id):
    if not payment_intent_id:
        return None
    return ProductOrder.query.filter_by(stripe_payment_intent_id=payment_intent_id).first()


def _chargeback_auto_evidence_text(order):
    """Builds a factual evidence narrative from data already recorded on
    the order — nothing invented, nothing the seller didn't already log
    through normal use of the platform (shipping/tracking, buyer's own
    receipt confirmation, the store policy they acknowledged before
    paying). Returns None if there isn't enough on file to say anything
    useful, so the caller falls back to manual review instead of
    submitting a thin/empty response."""
    lines = []
    if order.tracking_number:
        lines.append(f"Shipped via {order.carrier or 'carrier'}, tracking number {order.tracking_number}"
                      + (f", shipped {order.shipped_at.date().isoformat()}" if order.shipped_at else "") + ".")
    if order.last_tracking_status:
        lines.append(f"Most recent carrier tracking status on file: \"{order.last_tracking_status}\""
                      + (f" (checked {order.last_tracking_checked_at.date().isoformat()})" if order.last_tracking_checked_at else "") + ".")
    if order.escrow_status == "released" and order.released_at:
        lines.append(f"Order marked released/complete on {order.released_at.date().isoformat()} with no dispute "
                      f"raised on this platform before this chargeback.")
    if order.shipping_address:
        lines.append("Shipping address on file matches the address the cardholder provided at checkout "
                      "(collected directly by Stripe Checkout, not entered by the seller).")
    if not lines:
        return None
    lines.append(f"Order #{order.id} placed {order.created_at.date().isoformat() if order.created_at else 'N/A'} "
                 f"for {order.currency} {order.total_price:.2f}.")
    return " ".join(lines)


def _chargeback_maybe_auto_respond(cb: "PaymentChargeback", order):
    """Only fires when chargeback_automation is unlocked, and only for
    the single narrowest case: reason is 'product_not_received' and the
    order shows real, on-platform evidence of delivery/completion. Every
    other reason (fraudulent, product_unacceptable, duplicate, etc.)
    needs a human — this deliberately does not try to auto-argue product
    quality, authorization, or duplicate-charge disputes."""
    if not _feature_enabled("chargeback_automation"):
        return
    if cb.auto_response_submitted or cb.reason != "product_not_received" or not order:
        return
    delivered_signal = (
        (order.last_tracking_status and "deliver" in order.last_tracking_status.lower())
        or (order.escrow_status == "released" and order.released_at is not None)
    )
    if not delivered_signal:
        return
    evidence_text = _chargeback_auto_evidence_text(order)
    if not evidence_text:
        return
    if not STRIPE_SECRET_KEY:
        return
    try:
        import stripe
        stripe.api_key = STRIPE_SECRET_KEY
        stripe.Dispute.modify(
            cb.stripe_dispute_id,
            evidence={
                "product_description": f"Order #{order.id}" + (f" — {order.variant_label}" if order.variant_label else ""),
                "shipping_tracking_number": order.tracking_number or "",
                "shipping_carrier": order.carrier or "",
                "shipping_date": order.shipped_at.strftime("%Y-%m-%d") if order.shipped_at else "",
                "uncategorized_text": evidence_text,
            },
            submit=True,
        )
        cb.auto_response_submitted = True
        cb.auto_response_note = evidence_text
        db.session.commit()
        logging.info(f"[CHARGEBACK AUTO-RESPONSE] Submitted evidence for dispute {cb.stripe_dispute_id} (order {order.id}).")
        try:
            notify_user(order.seller_id, "chargeback", "Chargeback evidence auto-submitted",
                        f"Order #{order.id} was disputed by the buyer's bank as 'product not received'. "
                        f"Delivery was already confirmed on-platform, so evidence was submitted to Stripe "
                        f"automatically. You can add more detail from the Chargebacks tab before the case closes.")
        except Exception:
            pass
    except Exception as e:
        logging.error(f"[CHARGEBACK AUTO-RESPONSE ERROR] dispute={cb.stripe_dispute_id}: {e}")


def _chargeback_handle_webhook_event(event):
    """Handles every charge.dispute.* event type. Always runs regardless
    of the chargeback_automation flag — ingestion/tracking/notification
    is not the gated part (see the STAGE 525 comment block above)."""
    obj = event["data"]["object"]
    dispute_id = obj.get("id")
    if not dispute_id:
        return
    cb = PaymentChargeback.query.filter_by(stripe_dispute_id=dispute_id).first()
    is_new = cb is None
    if is_new:
        cb = PaymentChargeback(stripe_dispute_id=dispute_id)
        db.session.add(cb)
    cb.stripe_charge_id = obj.get("charge")
    pi = obj.get("payment_intent")
    cb.stripe_payment_intent_id = pi if isinstance(pi, str) else None
    cb.amount = (obj.get("amount") or 0) / 100.0
    cb.currency = (obj.get("currency") or "usd").upper()
    cb.reason = obj.get("reason")
    cb.status = obj.get("status") or cb.status
    due_by_ts = obj.get("evidence_details", {}).get("due_by") if obj.get("evidence_details") else None
    cb.evidence_due_by = datetime.utcfromtimestamp(due_by_ts) if due_by_ts else cb.evidence_due_by
    order = _chargeback_order_for_payment_intent(cb.stripe_payment_intent_id)
    if order:
        cb.order_id = order.id
        cb.buyer_id = order.buyer_id
        cb.seller_id = order.seller_id
    db.session.commit()

    event_type = event["type"]
    if event_type == "charge.dispute.created":
        if order:
            # Freeze exactly like a platform-mediated EscrowDispute would
            # — a live card-network case takes priority over the normal
            # auto-release sweep either way.
            if order.escrow_status == "holding":
                order.escrow_status = "disputed"
            if not order.dispute_reason:
                order.dispute_reason = f"Card-network chargeback filed (reason: {cb.reason})."
            db.session.commit()
            try:
                notify_user(order.seller_id, "chargeback", "A chargeback was filed against your order",
                            f"Order #{order.id} ({cb.currency} {cb.amount:.2f}) was disputed with the buyer's "
                            f"bank — reason: {cb.reason or 'unspecified'}. "
                            + (f"Respond by {cb.evidence_due_by.date().isoformat()}." if cb.evidence_due_by else "Respond as soon as possible."))
            except Exception:
                pass
        try:
            _fraud_flag_upsert(
                (order.seller_id if order else None) or 0, "chargeback", cb.id, "chargeback_filed", "high",
                "Card-network chargeback filed",
                f"Reason: {cb.reason or 'unspecified'}, amount {cb.currency} {cb.amount:.2f}."
                + (f" Order #{order.id}." if order else " Could not match this dispute to a platform order."),
                amount=cb.amount, currency=cb.currency, occurred_at=datetime.utcnow(),
            )
        except Exception as e:
            logging.error(f"[CHARGEBACK FRAUD FLAG ERROR] {e}")
        _chargeback_maybe_auto_respond(cb, order)

    elif event_type == "charge.dispute.funds_withdrawn":
        cb.funds_withdrawn = True
        db.session.commit()

    elif event_type == "charge.dispute.funds_reinstated":
        cb.funds_reinstated = True
        db.session.commit()

    elif event_type == "charge.dispute.closed":
        if order and order.escrow_status == "disputed":
            if cb.status == "won":
                # Seller prevailed at the card network — release the
                # hold the way an admin resolving an EscrowDispute in
                # the seller's favor would (or leave 'released' alone
                # if the payout already happened before the dispute).
                order.escrow_status = "released"
            elif cb.status == "lost":
                order.escrow_status = "refunded"
                order.refunded_at = order.refunded_at or datetime.utcnow()
            db.session.commit()
        try:
            if order:
                notify_user(order.seller_id, "chargeback", f"Chargeback case closed — {cb.status}",
                            f"Order #{order.id}'s chargeback case was closed by the card network: {cb.status}.")
        except Exception:
            pass


@app.route("/api/chargebacks/mine", methods=["GET"])
def chargebacks_mine():
    """Every chargeback where the current user is the seller — always
    available regardless of chargeback_automation (see STAGE 525
    comment above); that flag only gates auto-response, not visibility
    or manual response."""
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    rows = (PaymentChargeback.query.filter_by(seller_id=user["id"])
            .order_by(PaymentChargeback.created_at.desc()).limit(200).all())
    return jsonify({"ok": True, "chargebacks": [r.to_dict() for r in rows]}), 200


@app.route("/api/chargebacks/<int:chargeback_id>/evidence", methods=["POST"])
@csrf.exempt
def chargeback_submit_evidence(chargeback_id):
    """Seller's own manual evidence submission — works whether or not
    chargeback_automation is unlocked, and whether or not an auto-
    response already fired (this appends more detail before the
    evidence_due_by deadline; Stripe keeps the latest submission)."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    cb = PaymentChargeback.query.filter_by(id=chargeback_id, seller_id=user["id"]).first()
    if not cb:
        return jsonify({"error": "Chargeback not found."}), 404
    if cb.status not in ("needs_response", "warning_needs_response", "warning_under_review", "under_review"):
        return jsonify({"error": f"This case is '{cb.status}' and no longer accepts new evidence."}), 400
    data = request.get_json(silent=True) or {}
    text = (data.get("evidence_text") or "").strip()[:5000]
    if not text:
        return jsonify({"error": "Evidence text is required."}), 400
    combined = ((_chargeback_auto_evidence_text(ProductOrder.query.get(cb.order_id)) + " " if cb.order_id else "") + text).strip()
    if STRIPE_SECRET_KEY:
        try:
            import stripe
            stripe.api_key = STRIPE_SECRET_KEY
            stripe.Dispute.modify(cb.stripe_dispute_id, evidence={"uncategorized_text": combined}, submit=True)
        except Exception as e:
            logging.error(f"[CHARGEBACK MANUAL EVIDENCE ERROR] dispute={cb.stripe_dispute_id}: {e}")
            return jsonify({"error": f"Could not submit to Stripe: {e}"}), 502
    cb.seller_evidence_text = text
    cb.seller_evidence_submitted_at = datetime.utcnow()
    db.session.commit()
    return jsonify({"ok": True, "chargeback": cb.to_dict()}), 200


@app.route("/api/admin/chargebacks", methods=["GET"])
def admin_chargebacks_list():
    """Admin-wide view across every seller — the balance-sheet/dispute
    exposure this whole feature exists to surface, same spirit as
    /api/admin/bnpl/plans."""
    user, err = _platform_admin_or_401()
    if err: return err
    rows = (PaymentChargeback.query.order_by(PaymentChargeback.created_at.desc()).limit(300).all())
    outstanding = round(sum(r.amount for r in rows if r.status in
                             ("needs_response", "warning_needs_response", "warning_under_review", "under_review")), 2)
    return jsonify({
        "ok": True, "chargebacks": [r.to_dict() for r in rows],
        "outstanding_exposure": outstanding,
        "needs_response_count": len([r for r in rows if r.status in ("needs_response", "warning_needs_response")]),
        "automation_enabled": _feature_enabled("chargeback_automation"),
    }), 200


