@app.route("/api/tax/residency-profile", methods=["GET"])
def tax_residency_profile_get():
    user, err = _erp_user_or_401()
    if err: return err
    row = TaxResidencyProfile.query.filter_by(owner_user_id=user["id"]).first()
    if not row:
        acct = UserAccount.query.get(user["id"])
        return jsonify({"exists": False, "suggested_country_code": acct.country_code if acct else "ZW"}), 200
    return jsonify({"exists": True, "profile": row.to_dict()}), 200


@app.route("/api/tax/residency-profile", methods=["PUT"])
@csrf.exempt
def tax_residency_profile_set():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    country_code = (data.get("country_code") or "").strip().upper()[:4]
    if not country_code:
        return jsonify({"error": "country_code is required."}), 400
    row = TaxResidencyProfile.query.filter_by(owner_user_id=user["id"]).first()
    if not row:
        row = TaxResidencyProfile(owner_user_id=user["id"], country_code=country_code)
        db.session.add(row)
    row.country_code = country_code
    row.vat_registered = bool(data.get("vat_registered", row.vat_registered))
    if "vat_number" in data:
        row.vat_number = (data.get("vat_number") or "").strip()[:40] or None
    freq = (data.get("filing_frequency") or row.filing_frequency or "quarterly").strip().lower()
    if freq in ("monthly", "quarterly", "annual"):
        row.filing_frequency = freq
    if "notes" in data:
        row.notes = (data.get("notes") or "").strip()[:2000] or None
    row.updated_at = datetime.utcnow()
    db.session.commit()
    return jsonify({"ok": True, "profile": row.to_dict()}), 200


@app.route("/api/tax/vat-summary", methods=["GET"])
def tax_vat_summary():
    user, err = _erp_user_or_401()
    if err: return err
    today = datetime.utcnow().date()
    try:
        year = int(request.args.get("year", today.year))
        month = int(request.args.get("month", today.month))
        if not (1 <= month <= 12): raise ValueError
    except (TypeError, ValueError):
        return jsonify({"error": "year and month must be valid integers, month 1-12."}), 400

    profile = TaxResidencyProfile.query.filter_by(owner_user_id=user["id"]).first()
    country_code = profile.country_code if profile else (UserAccount.query.get(user["id"]).country_code)
    vat_rate = COUNTRY_VAT_STANDARD_RATES.get(country_code)

    period = f"{year:04d}-{month:02d}"
    start = date(year, month, 1)
    end = date(year + 1, 1, 1) if month == 12 else date(year, month + 1, 1)
    invoices = (ErpInvoice.query.filter_by(owner_user_id=user["id"], status="paid")
                .filter(ErpInvoice.paid_at.isnot(None))
                .filter(ErpInvoice.paid_at >= start, ErpInvoice.paid_at < end).all())
    revenue = sum(i.subtotal or 0 for i in invoices)
    output_vat = round(revenue * vat_rate, 2) if vat_rate else 0.0
    record = TaxRemittanceRecord.query.filter_by(owner_user_id=user["id"], period=period,
                                                   country_code=country_code).first()

    return jsonify({
        "period": period, "country_code": country_code, "vat_rate": vat_rate,
        "vat_rate_known": country_code in COUNTRY_VAT_STANDARD_RATES,
        "vat_registered": profile.vat_registered if profile else False,
        "invoice_count": len(invoices), "revenue": round(revenue, 2), "output_vat": output_vat,
        "net_vat_due": output_vat,
        "remittance_status": record.status if record else "not_recorded",
        "remitted_at": record.remitted_at.isoformat() if (record and record.remitted_at) else None,
    }), 200


@app.route("/api/tax/vat-summary/mark-remitted", methods=["POST"])
@csrf.exempt
def tax_vat_mark_remitted():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    period = (data.get("period") or "").strip()
    if not re.match(r"^\d{4}-\d{2}$", period):
        return jsonify({"error": "period must be in YYYY-MM format."}), 400
    profile = TaxResidencyProfile.query.filter_by(owner_user_id=user["id"]).first()
    country_code = profile.country_code if profile else UserAccount.query.get(user["id"]).country_code
    try:
        net_due = float(data.get("net_due", 0))
    except (TypeError, ValueError):
        net_due = 0.0
    record = TaxRemittanceRecord.query.filter_by(owner_user_id=user["id"], period=period,
                                                   country_code=country_code).first()
    if not record:
        record = TaxRemittanceRecord(owner_user_id=user["id"], period=period, country_code=country_code)
        db.session.add(record)
    record.output_vat = net_due
    record.net_due = net_due
    record.status = "remitted"
    record.remitted_at = datetime.utcnow()
    db.session.commit()
    return jsonify({"ok": True, "record": record.to_dict()}), 200


# ---- 18: AUTOMATED TAX FORM GENERATION -----------------------------

def _tax_annual_statement_compute(user_id, year):
    start = date(year, 1, 1)
    end = date(year + 1, 1, 1)
    invoices = (ErpInvoice.query.filter_by(owner_user_id=user_id, status="paid")
                .filter(ErpInvoice.paid_at.isnot(None))
                .filter(ErpInvoice.paid_at >= start, ErpInvoice.paid_at < end).all())
    monthly = defaultdict(float)
    for inv in invoices:
        monthly[inv.paid_at.month] += (inv.total or 0)
    total_revenue = sum(monthly.values())
    return {
        "tax_year": year, "total_revenue": round(total_revenue, 2),
        "invoice_count": len(invoices),
        "monthly_breakdown": [{"month": m, "revenue": round(monthly.get(m, 0.0), 2)} for m in range(1, 13)],
        "disclaimer": "Generated from this business's own recorded, paid invoices on the platform. This is a "
                       "summary statement to support the business's own tax filing, not an official government "
                       "tax form and not a substitute for advice from a qualified tax preparer.",
    }


@app.route("/api/tax/annual-statement", methods=["GET"])
def tax_annual_statement():
    user, err = _erp_user_or_401()
    if err: return err
    today = datetime.utcnow().date()
    try:
        year = int(request.args.get("year", today.year - 1))
    except (TypeError, ValueError):
        return jsonify({"error": "year must be a valid integer."}), 400
    fmt = (request.args.get("format") or "json").lower()
    result = _tax_annual_statement_compute(user["id"], year)
    business_name = (user.get("name") or "Business").strip()

    if fmt == "json":
        return jsonify(result), 200

    if fmt == "pdf":
        if not REPORTLAB_AVAILABLE:
            return jsonify({"error": "PDF generation isn't available on this server."}), 500
        try:
            from reportlab.lib import colors
            from reportlab.platypus import TableStyle
            buf = io.BytesIO()
            doc = SimpleDocTemplate(buf, pagesize=A4, rightMargin=40, leftMargin=40, topMargin=50, bottomMargin=40)
            styles = getSampleStyleSheet()
            story = [Paragraph(f"{business_name} — Annual Revenue Statement {year}", styles["Title"]),
                     Spacer(1, 16),
                     Paragraph(f"Total revenue: ${result['total_revenue']:,.2f} across "
                               f"{result['invoice_count']} paid invoices.", styles["Normal"]),
                     Spacer(1, 12)]
            rows = [["Month", "Revenue"]] + [
                [datetime(year, m["month"], 1).strftime("%B"), f"${m['revenue']:,.2f}"]
                for m in result["monthly_breakdown"]
            ]
            t = Table(rows, colWidths=[300, 120])
            t.setStyle(TableStyle([
                ("FONTSIZE", (0, 0), (-1, -1), 9),
                ("FONTNAME", (0, 0), (-1, 0), "Helvetica-Bold"),
                ("LINEBELOW", (0, 0), (-1, -1), 0.5, colors.HexColor("#e5e7eb")),
                ("TOPPADDING", (0, 0), (-1, -1), 4), ("BOTTOMPADDING", (0, 0), (-1, -1), 4),
            ]))
            story.append(t)
            story.append(Spacer(1, 16))
            story.append(Paragraph(result["disclaimer"], styles["Italic"]))
            doc.build(story)
            buf.seek(0)
            db.session.add(TaxStatementGeneration(owner_user_id=user["id"], tax_year=year,
                                                   total_revenue=result["total_revenue"]))
            db.session.commit()
            return Response(buf, mimetype="application/pdf",
                             headers={"Content-Disposition": f'attachment; filename="Annual-Statement-{year}.pdf"'})
        except Exception as e:
            logging.error(f"[TAX ANNUAL STATEMENT PDF] {e}")
            return jsonify({"error": "Could not generate the PDF."}), 500

    return jsonify({"error": "format must be json or pdf."}), 400


