# ---- 19: MULTI-CURRENCY TREASURY DASHBOARD -------------------------

@app.route("/api/treasury/dashboard", methods=["GET"])
def treasury_dashboard():
    user, err = _erp_user_or_401()
    if err: return err
    acct = UserAccount.query.get(user["id"])
    home_ccy = (acct.preferred_currency if acct and getattr(acct, "preferred_currency", None) else "USD").upper()

    since = datetime.utcnow() - timedelta(days=365)
    orders = (ProductOrder.query.filter_by(seller_id=user["id"])
              .filter(ProductOrder.status == "paid", ProductOrder.paid_at.isnot(None))
              .filter(ProductOrder.paid_at >= since).all())
    by_currency = defaultdict(float)
    for o in orders:
        by_currency[(o.currency or "USD").upper()] += (o.total_price or 0)

    open_receivables = defaultdict(float)
    inv_rows = (ErpInvoice.query.filter_by(owner_user_id=user["id"])
                .filter(ErpInvoice.status.in_(["sent", "overdue"])).all())
    for inv in inv_rows:
        open_receivables[(inv.currency or "USD").upper()] += max((inv.total or 0) - (inv.amount_paid or 0), 0)

    balances = []
    total_home_equiv = 0.0
    for ccy, amount in by_currency.items():
        rate = _fx_cross_rate(ccy, home_ccy)
        converted = round(amount * rate, 2) if rate else None
        if converted is not None:
            total_home_equiv += converted
        balances.append({
            "currency": ccy, "settled_last_365d": round(amount, 2),
            "converted_to_home": converted, "fx_rate_used": rate,
            "is_home_currency": ccy == home_ccy,
        })
    balances.sort(key=lambda b: -(b["converted_to_home"] or 0))

    receivables = []
    for ccy, amount in open_receivables.items():
        rate = _fx_cross_rate(ccy, home_ccy)
        receivables.append({
            "currency": ccy, "open_amount": round(amount, 2),
            "converted_to_home": round(amount * rate, 2) if rate else None,
        })

    foreign_exposure_pct = None
    home_amount = by_currency.get(home_ccy, 0.0)
    if total_home_equiv > 0:
        foreign_exposure_pct = round(100 * (total_home_equiv - (home_amount if home_ccy in by_currency else 0)) /
                                      total_home_equiv, 1)

    active_locks = FxRateLock.query.filter_by(user_id=user["id"], status="active").all()

    return jsonify({
        "home_currency": home_ccy,
        "balances_by_currency": balances,
        "total_home_currency_equivalent": round(total_home_equiv, 2),
        "foreign_exposure_pct": foreign_exposure_pct,
        "open_receivables_by_currency": receivables,
        "active_fx_rate_locks": [l.to_dict() for l in active_locks],
        "window_days": 365,
        "as_of": datetime.utcnow().isoformat(),
    }), 200


# ---- 20b: PREDICTIVE HEDGE SUGGESTIONS ------------------------------
# Builds directly on the existing FxRateLock / _fx_hedge_quote (STAGE
# above): looks at the seller's real, currently-open foreign-currency
# receivables (unpaid invoices, plus pending marketplace orders) and
# flags the ones with no active lock covering them yet.

FX_HEDGE_SUGGEST_MIN_EXPOSURE = 200.0  # ignore tiny foreign-currency balances


@app.route("/api/fx/hedge-suggestions", methods=["GET"])
def fx_hedge_suggestions():
    user, err = _erp_user_or_401()
    if err: return err
    acct = UserAccount.query.get(user["id"])
    home_ccy = (acct.preferred_currency if acct and getattr(acct, "preferred_currency", None) else "USD").upper()

    exposure = defaultdict(float)
    for inv in (ErpInvoice.query.filter_by(owner_user_id=user["id"])
                .filter(ErpInvoice.status.in_(["sent", "overdue"])).all()):
        ccy = (inv.currency or "USD").upper()
        if ccy != home_ccy:
            exposure[ccy] += max((inv.total or 0) - (inv.amount_paid or 0), 0)
    for o in (ProductOrder.query.filter_by(seller_id=user["id"])
              .filter(ProductOrder.status.in_(["pending", "paid"])).all()):
        ccy = (o.currency or "USD").upper()
        if ccy != home_ccy:
            exposure[ccy] += (o.total_price or 0)

    active_locked_pairs = {(l.from_currency, l.to_currency) for l in
                            FxRateLock.query.filter_by(user_id=user["id"], status="active").all()}

    suggestions = []
    for ccy, amount in exposure.items():
        if amount < FX_HEDGE_SUGGEST_MIN_EXPOSURE:
            continue
        already_locked = (ccy, home_ccy) in active_locked_pairs
        rate, fee_pct, spot = _fx_hedge_quote(ccy, home_ccy, 30)
        suggestions.append({
            "from_currency": ccy, "to_currency": home_ccy,
            "open_exposure": round(amount, 2), "already_has_active_lock": already_locked,
            "quote_30d": ({"locked_rate": rate, "fee_pct": fee_pct} if rate else None),
            "recommendation": ("no action needed — already hedged" if already_locked else
                                "consider a rate lock via /api/fx/rate-locks to protect this receivable"
                                if rate else "no live rate available for this pair right now"),
        })
    suggestions.sort(key=lambda s: -s["open_exposure"])
    return jsonify({"home_currency": home_ccy, "suggestions": suggestions,
                     "min_exposure_considered": FX_HEDGE_SUGGEST_MIN_EXPOSURE}), 200


# ---- 13: BUYER FINANCING / B2B "BUY NOW, PAY LATER" -----------------

def _bnpl_tier_for_score(score):
    for min_score, term, fee_pct, max_amount, deposit_pct in BNPL_TIERS:
        if score >= min_score:
            return term, fee_pct, max_amount, deposit_pct
    return None


def _bnpl_build_schedule(financed_amount, term_months, start_date):
    if term_months <= 0:
        return []
    per = round(financed_amount / term_months, 2)
    schedule = []
    running = 0.0
    for i in range(1, term_months + 1):
        due = start_date + timedelta(days=30 * i)
        amt = per
        running += per
        if i == term_months:
            amt = round(financed_amount - (running - per), 2)  # last one absorbs rounding
        schedule.append({"seq": i, "amount": amt, "due_date": due.isoformat(), "status": "pending", "paid_at": None})
    return schedule


@app.route("/api/buyer-financing/quote", methods=["POST"])
@csrf.exempt
def buyer_financing_quote():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    try:
        amount = float(data.get("amount"))
        if amount <= 0: raise ValueError
    except (TypeError, ValueError):
        return jsonify({"error": "amount must be a positive number."}), 400

    score_info = compute_credit_score(user["id"])
    score = score_info["score"]
    tier = _bnpl_tier_for_score(score)
    if not tier or amount > tier[2]:
        max_at_score = tier[2] if tier else 0
        return jsonify({
            "eligible": False, "credit_score": score, "risk_grade": score_info["risk_grade"],
            "reason": (f"Requested amount exceeds the maximum this score qualifies for (${max_at_score:,.0f})."
                       if tier else "Credit score is below the minimum threshold for buyer financing."),
            "lender_note": BNPL_LENDING_PARTNER_NOTE,
        }), 200

    term_months, fee_pct, max_amount, deposit_pct = tier
    deposit_amount = round(amount * deposit_pct, 2)
    financed_principal = amount - deposit_amount
    financed_amount = round(financed_principal * (1 + fee_pct), 2)
    return jsonify({
        "eligible": True, "credit_score": score, "risk_grade": score_info["risk_grade"],
        "amount": amount, "term_months": term_months, "fee_pct": fee_pct,
        "deposit_pct": deposit_pct, "deposit_amount": deposit_amount, "financed_amount": financed_amount,
        "estimated_installment": round(financed_amount / term_months, 2),
        "lender_note": BNPL_LENDING_PARTNER_NOTE,
    }), 200


@app.route("/api/buyer-financing/apply", methods=["POST"])
@csrf.exempt
def buyer_financing_apply():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    try:
        amount = float(data.get("amount"))
        if amount <= 0: raise ValueError
    except (TypeError, ValueError):
        return jsonify({"error": "amount must be a positive number."}), 400
    currency = (data.get("currency") or "USD").strip().upper()[:8]
    order_id = data.get("order_id")
    if order_id is not None:
        order = ProductOrder.query.filter_by(id=order_id, buyer_id=user["id"]).first()
        if not order:
            return jsonify({"error": "order_id not found for this buyer."}), 404

    score_info = compute_credit_score(user["id"])
    score = score_info["score"]
    tier = _bnpl_tier_for_score(score)

    app_row = BuyerFinancingApplication(
        buyer_id=user["id"], order_id=order_id, amount=amount, currency=currency,
        credit_score_at_apply=score,
    )
    if not tier or amount > tier[2]:
        app_row.status = "declined"
        app_row.decline_reason = ("amount exceeds qualifying maximum" if tier else
                                   "credit score below minimum threshold")
    else:
        term_months, fee_pct, max_amount, deposit_pct = tier
        deposit_amount = round(amount * deposit_pct, 2)
        financed_principal = amount - deposit_amount
        financed_amount = round(financed_principal * (1 + fee_pct), 2)
        app_row.status = "approved"
        app_row.term_months = term_months
        app_row.fee_pct = fee_pct
        app_row.deposit_pct = deposit_pct
        app_row.deposit_amount = deposit_amount
        app_row.financed_amount = financed_amount
        schedule = _bnpl_build_schedule(financed_amount, term_months, datetime.utcnow().date())
        app_row.schedule_json = json.dumps(schedule)
    db.session.add(app_row)
    db.session.commit()
    return jsonify({"ok": True, "application": app_row.to_dict()}), 201


