@app.route("/api/buyer-financing/<int:app_id>/pay-installment", methods=["POST"])
@csrf.exempt
def buyer_financing_pay_installment(app_id):
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    row = BuyerFinancingApplication.query.filter_by(id=app_id, buyer_id=user["id"]).first()
    if not row:
        return jsonify({"error": "Application not found."}), 404
    if row.status not in ("approved", "lender_confirmed", "active"):
        return jsonify({"error": f"This application is {row.status} and has no payable schedule."}), 400
    schedule = row.schedule()
    next_due = next((s for s in schedule if s["status"] == "pending"), None)
    if not next_due:
        return jsonify({"error": "No pending installments remain."}), 400
    next_due["status"] = "paid"
    next_due["paid_at"] = datetime.utcnow().isoformat()
    row.schedule_json = json.dumps(schedule)
    row.status = "active" if any(s["status"] == "pending" for s in schedule) else "completed"
    db.session.commit()
    return jsonify({"ok": True, "application": row.to_dict()}), 200


