@app.route("/api/erp/quotes", methods=["POST"])
@csrf.exempt
def erp_quotes_create():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    items, subtotal = _erp_items_from_payload(data.get("items"))
    if not items: return jsonify({"error": "At least one line item is required."}), 400
    tax_rate = float(data.get("tax_rate", 0) or 0)
    tax_amount = round(subtotal * tax_rate / 100, 2)
    currency = data.get("currency", "USD") or "USD"
    exchange_rate = None
    if currency != "USD":
        rate_row = _erp_rate_row(user["id"], create_if_missing=False)
        if rate_row and rate_row.zwg_per_usd:
            exchange_rate = round(1 / rate_row.zwg_per_usd, 6)
    try:
        q = ErpQuote(
            owner_user_id=user["id"], customer_id=data.get("customer_id"),
            quote_number=data.get("quote_number") or _erp_gen_number("QUO"),
            currency=currency, exchange_rate=exchange_rate,
            issue_date=_erp_parse_date(data.get("issue_date"), datetime.utcnow().date()),
            expiry_date=_erp_parse_date(data.get("expiry_date")),
            subtotal=subtotal, tax_rate=tax_rate, tax_amount=tax_amount,
            total=round(subtotal + tax_amount, 2), notes=data.get("notes"),
        )
        db.session.add(q); db.session.flush()
        for it in items:
            db.session.add(ErpQuoteItem(quote_id=q.id, product_id=it["product_id"], description=it["description"],
                                          quantity=it["quantity"], unit_price=it["price"], line_total=it["line_total"]))
        db.session.commit()
    except Exception as e:
        db.session.rollback(); logging.error(f"[ERP QUOTE CREATE] {e}")
        return jsonify({"error": "Could not save quote."}), 500
    return jsonify({"quote": q.to_dict(include_items=True)}), 201


