@app.route("/api/erp/quotes/<int:qid>/convert-to-invoice", methods=["POST"])
@csrf.exempt
def erp_quotes_convert(qid):
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    q = ErpQuote.query.get(qid)
    if not q or q.owner_user_id != user["id"]: return jsonify({"error": "Quote not found."}), 404
    if q.converted_invoice_id: return jsonify({"error": "Quote was already converted."}), 400
    try:
        inv = ErpInvoice(
            owner_user_id=user["id"], customer_id=q.customer_id, invoice_number=_erp_gen_number("INV"),
            currency=q.currency, exchange_rate=q.exchange_rate, issue_date=datetime.utcnow().date(),
            due_date=datetime.utcnow().date() + timedelta(days=14),
            subtotal=q.subtotal, tax_rate=q.tax_rate, tax_amount=q.tax_amount, total=q.total,
            notes=q.notes, source_quote_id=q.id,
        )
        db.session.add(inv); db.session.flush()
        for qi in ErpQuoteItem.query.filter_by(quote_id=q.id).all():
            db.session.add(ErpInvoiceItem(invoice_id=inv.id, product_id=qi.product_id, description=qi.description,
                                            quantity=qi.quantity, unit_price=qi.unit_price, line_total=qi.line_total))
        q.status = "converted"; q.converted_invoice_id = inv.id
        db.session.commit()
    except Exception as e:
        db.session.rollback(); logging.error(f"[ERP QUOTE CONVERT] {e}")
        return jsonify({"error": "Could not convert quote."}), 500
    return jsonify({"invoice": inv.to_dict(include_items=True)}), 201


