@app.route("/api/erp/invoices", methods=["GET"])
def erp_invoices_list():
    user, err = _erp_user_or_401()
    if err: return err
    q = ErpInvoice.query.filter_by(owner_user_id=user["id"])
    status = request.args.get("status")
    if status: q = q.filter_by(status=status)
    rows = q.order_by(ErpInvoice.id.desc()).all()
    invoices = [r.to_dict() for r in rows]
    # NEW: attach ZIMRA fiscalisation status per invoice (one bulk query,
    # not one per invoice) so the invoice list can show a real "Fiscalise"
    # or " Fiscalised" button without a separate round trip.
    invoice_ids = [inv["id"] for inv in invoices]
    if invoice_ids:
        fiscal_rows = ZimraFiscalReceipt.query.filter(ZimraFiscalReceipt.invoice_id.in_(invoice_ids)).all()
        fiscal_by_invoice = {fr.invoice_id: fr for fr in fiscal_rows}
        for inv in invoices:
            fr = fiscal_by_invoice.get(inv["id"])
            inv["zimra_fiscalised"] = bool(fr)
            inv["zimra_qr_url"] = fr.qr_code_url if fr else None
    return jsonify({"invoices": invoices}), 200


# ════════════════════════════════════════════════════════════
# NEXT-03: DYNAMIC PAYMENT TERMS
# Not the platform-wide Credit Score (that scores the business owner's
# own account for lenders) — this scores an individual ErpCustomer's
# OWN payment history with this business, and turns that into an
# actionable default: reliable customers get looser terms, risky ones
# get tighter terms or an upfront-deposit flag, automatically, instead
# of every invoice defaulting to the same net-14 regardless of who it's
# for.
# ════════════════════════════════════════════════════════════

def _erp_customer_payment_profile(owner_user_id, customer_id):
    invoices = (ErpInvoice.query.filter_by(owner_user_id=owner_user_id, customer_id=customer_id)
                .filter(ErpInvoice.status.in_(["paid", "overdue", "sent"])).all())
    paid = [i for i in invoices if i.status == "paid" and i.paid_at and i.issue_date]
    days_to_pay = [(i.paid_at.date() - i.issue_date).days for i in paid if (i.paid_at.date() - i.issue_date).days >= 0]
    avg_days_to_pay = round(sum(days_to_pay) / len(days_to_pay), 1) if days_to_pay else None
    overdue_count = len([i for i in invoices if i.status == "overdue"])
    overdue_rate = round(overdue_count / len(invoices), 2) if invoices else None
    sample_size = len(invoices)

    if sample_size < 2:
        tier = "new_customer"
        net_days = 14
        deposit_required_pct = 0
        reason = "Not enough payment history with this customer yet — using the standard default (net 14)."
    elif (overdue_rate or 0) >= 0.5 or (avg_days_to_pay or 0) > 45:
        tier = "high_risk"
        net_days = 0
        deposit_required_pct = 50
        reason = f"{overdue_count} of {sample_size} invoices went overdue" + \
                 (f", averaging {avg_days_to_pay} days to pay" if avg_days_to_pay else "") + \
                 " — recommend an upfront deposit."
    elif (overdue_rate or 0) >= 0.25 or (avg_days_to_pay or 0) > 21:
        tier = "risky"
        net_days = 7
        deposit_required_pct = 0
        reason = "Payment history shows some late/overdue invoices — recommend shorter terms (net 7)."
    elif (avg_days_to_pay or 999) <= 7 and (overdue_rate or 0) == 0:
        tier = "reliable"
        net_days = 30
        deposit_required_pct = 0
        reason = "Consistently pays on time or early — recommend net 30."
    else:
        tier = "standard"
        net_days = 14
        deposit_required_pct = 0
        reason = "Payment history is unremarkable either way — standard terms (net 14)."

    return {
        "customer_id": customer_id, "tier": tier, "recommended_net_days": net_days,
        "deposit_required_pct": deposit_required_pct, "reason": reason,
        "avg_days_to_pay": avg_days_to_pay, "overdue_rate": overdue_rate, "invoice_sample_size": sample_size,
    }


@app.route("/api/erp/customers/<int:cid>/payment-terms", methods=["GET"])
def erp_customer_payment_terms(cid):
    user, err = _erp_user_or_401()
    if err: return err
    cust = ErpCustomer.query.get(cid)
    if not cust or cust.owner_user_id != user["id"]:
        return jsonify({"error": "Customer not found."}), 404
    return jsonify(_erp_customer_payment_profile(user["id"], cid)), 200


@app.route("/api/erp/invoices", methods=["POST"])
@csrf.exempt
def erp_invoices_create():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    items, subtotal = _erp_items_from_payload(data.get("items"))
    if not items: return jsonify({"error": "At least one line item is required."}), 400
    tax_rate = float(data.get("tax_rate", 0) or 0)
    tax_amount = round(subtotal * tax_rate / 100, 2)
    currency = data.get("currency", "USD") or "USD"
    exchange_rate = None
    if currency != "USD":
        rate_row = _erp_rate_row(user["id"], create_if_missing=False)
        if rate_row and rate_row.zwg_per_usd:
            exchange_rate = round(1 / rate_row.zwg_per_usd, 6)
    valid_payment_methods = {"cash", "card", "ecocash", "bank_transfer", "other"}
    payment_method = (data.get("payment_method") or "cash").strip().lower()
    if payment_method not in valid_payment_methods:
        payment_method = "other"
    try:
        explicit_due_date = data.get("due_date")
        payment_terms_note = None
        if not explicit_due_date and data.get("customer_id"):
            profile = _erp_customer_payment_profile(user["id"], data.get("customer_id"))
            computed_due_date = datetime.utcnow().date() + timedelta(days=profile["recommended_net_days"])
            if profile["deposit_required_pct"] > 0:
                payment_terms_note = (f"Dynamic payment terms: {profile['tier']} customer — "
                                       f"{profile['deposit_required_pct']}% deposit recommended before work begins. {profile['reason']}")
            elif profile["tier"] not in ("new_customer", "standard"):
                payment_terms_note = f"Dynamic payment terms: {profile['tier']} customer — net {profile['recommended_net_days']}. {profile['reason']}"
        else:
            computed_due_date = _erp_parse_date(explicit_due_date, datetime.utcnow().date() + timedelta(days=14))

        combined_notes = data.get("notes")
        if payment_terms_note:
            combined_notes = (combined_notes + "\n\n" + payment_terms_note) if combined_notes else payment_terms_note

        inv = ErpInvoice(
            owner_user_id=user["id"], customer_id=data.get("customer_id"),
            invoice_number=data.get("invoice_number") or _erp_gen_number("INV"),
            currency=currency, exchange_rate=exchange_rate,
            issue_date=_erp_parse_date(data.get("issue_date"), datetime.utcnow().date()),
            due_date=computed_due_date,
            subtotal=subtotal, tax_rate=tax_rate, tax_amount=tax_amount,
            total=round(subtotal + tax_amount, 2), notes=combined_notes,
            payment_method=payment_method,
        )
        db.session.add(inv); db.session.flush()
        for it in items:
            db.session.add(ErpInvoiceItem(invoice_id=inv.id, product_id=it["product_id"], description=it["description"],
                                            quantity=it["quantity"], unit_price=it["price"], line_total=it["line_total"]))
        db.session.commit()
    except Exception as e:
        db.session.rollback(); logging.error(f"[ERP INVOICE CREATE] {e}")
        return jsonify({"error": "Could not save invoice."}), 500
    return jsonify({"invoice": inv.to_dict(include_items=True)}), 201


