# STAGE 148: printable/scannable QR code for an invoice — encodes the
# invoice number, total, currency, and balance due as plain text so a
# customer (or the business owner filing paperwork) can scan a printed
# invoice with any phone camera and immediately see what's owed, without
# needing a login or an app. This does not initiate any payment itself;
# it is a lookup/reference code, same as a barcode on a paper bill.
@app.route("/api/erp/invoices/<int:iid>/qrcode", methods=["GET"])
def erp_invoice_qrcode(iid):
    user, err = _erp_user_or_401()
    if err: return err
    inv = ErpInvoice.query.get(iid)
    if not inv or inv.owner_user_id != user["id"]:
        return jsonify({"error": "Invoice not found."}), 404
    if not QRCODE_AVAILABLE:
        return jsonify({"error": "QR code generation isn't available on this server (qrcode library not installed)."}), 503

    d = inv.to_dict()
    lines = [
        "Smile Again — Invoice",
        f"Invoice #: {d['invoice_number']}",
        f"Status: {d['status']}",
        f"Total: {d['currency']} {d['total']:.2f}",
        f"Balance due: {d['currency']} {d['balance_due']:.2f}",
    ]
    if d.get("due_date"):
        lines.append(f"Due: {d['due_date']}")
    payload = "\n".join(lines)

    try:
        png_bytes = _generate_qr_png_bytes(payload)
    except RuntimeError as e:
        return jsonify({"error": str(e)}), 503
    except Exception as e:
        logging.error(f"[INVOICE QR] {e}")
        return jsonify({"error": "Could not generate QR code."}), 500

    return Response(
        png_bytes, mimetype="image/png",
        headers={"Content-Disposition": f'inline; filename="invoice-{iid}-qr.png"'},
    )


def _erp_invoice_pdf_bytes(inv) -> bytes:
    """Builds a real invoice PDF from the invoice's actual stored data
    (line items, totals, customer) using reportlab -- same library and
    pattern already used elsewhere in this file (e.g. the admin memory
    export PDF above). Raises RuntimeError if reportlab isn't installed."""
    if not REPORTLAB_AVAILABLE:
        raise RuntimeError("PDF generation is unavailable on this server (install reportlab).")
    d = inv.to_dict(include_items=True)
    customer = ErpCustomer.query.get(inv.customer_id) if inv.customer_id else None
    buf = io.BytesIO()
    doc = SimpleDocTemplate(buf, pagesize=A4, title=f"Invoice {d['invoice_number']}")
    styles = getSampleStyleSheet()
    story = [
        Paragraph(f"Invoice {d['invoice_number']}", styles["Title"]),
        Paragraph(f"Status: {d['status']} &middot; Issued: {d.get('issue_date') or 'N/A'} "
                  f"&middot; Due: {d.get('due_date') or 'Upon receipt'}", styles["Normal"]),
    ]
    if customer:
        story.append(Paragraph(f"Bill to: {escape(customer.name)}"
                                f"{(' &middot; ' + escape(customer.email)) if customer.email else ''}"
                                f"{(' &middot; ' + escape(customer.phone)) if customer.phone else ''}", styles["Normal"]))
    story.append(Spacer(1, 14))
    table_data = [["Description", "Qty", "Unit Price", "Line Total"]]
    for item in d.get("items", []):
        table_data.append([
            item["description"], f"{item['quantity']:g}",
            f"{d['currency']} {item['unit_price']:.2f}", f"{d['currency']} {item['line_total']:.2f}",
        ])
    table_data.append(["", "", "Subtotal", f"{d['currency']} {d['subtotal']:.2f}"])
    table_data.append(["", "", f"Tax ({d['tax_rate']:g}%)", f"{d['currency']} {d['tax_amount']:.2f}"])
    table_data.append(["", "", "Total", f"{d['currency']} {d['total']:.2f}"])
    table_data.append(["", "", "Balance due", f"{d['currency']} {d['balance_due']:.2f}"])
    invoice_table = Table(table_data, colWidths=[220, 60, 100, 100])
    story.append(invoice_table)
    if d.get("notes"):
        story.append(Spacer(1, 14))
        story.append(Paragraph(f"Notes: {escape(d['notes'])}", styles["Normal"]))
    doc.build(story)
    return buf.getvalue()


@app.route("/api/erp/invoices/<int:iid>/pdf", methods=["GET"])
def erp_invoice_pdf(iid):
    user, err = _erp_user_or_401()
    if err: return err
    inv = ErpInvoice.query.get(iid)
    if not inv or inv.owner_user_id != user["id"]:
        return jsonify({"error": "Invoice not found."}), 404
    try:
        pdf_bytes = _erp_invoice_pdf_bytes(inv)
    except RuntimeError as e:
        return jsonify({"error": str(e)}), 503
    except Exception as e:
        logging.error(f"[INVOICE PDF] {e}")
        return jsonify({"error": "Could not generate invoice PDF."}), 500
    return Response(
        pdf_bytes, mimetype="application/pdf",
        headers={"Content-Disposition": f'inline; filename="invoice-{inv.invoice_number}.pdf"'},
    )


@app.route("/api/erp/invoices/<int:iid>/send-whatsapp", methods=["POST"])
@csrf.exempt
def erp_invoice_send_whatsapp(iid):
    """Generates the invoice PDF and sends it as a real document
    attachment directly inside a WhatsApp message -- not a link to click
    out to -- using send_whatsapp_media_message's upload-then-send path
    since a freshly-built PDF has no public URL to link to."""
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    inv = ErpInvoice.query.get(iid)
    if not inv or inv.owner_user_id != user["id"]:
        return jsonify({"error": "Invoice not found."}), 404
    data = request.get_json(silent=True) or {}
    customer = ErpCustomer.query.get(inv.customer_id) if inv.customer_id else None
    to = sanitize_phone(data.get("to", "") or (customer.phone if customer else ""))
    if not to:
        return jsonify({"error": "No recipient phone number -- pass 'to' or set a phone on the customer."}), 400
    try:
        pdf_bytes = _erp_invoice_pdf_bytes(inv)
    except RuntimeError as e:
        return jsonify({"error": str(e)}), 503
    except Exception as e:
        logging.error(f"[INVOICE WA PDF GEN] {e}")
        return jsonify({"error": "Could not generate invoice PDF."}), 500
    try:
        result = send_whatsapp_media_message(
            user["id"], to, "document",
            caption=f"Invoice {inv.invoice_number} -- {inv.currency} {inv.total:.2f} due",
            filename=f"invoice-{inv.invoice_number}.pdf",
            file_bytes=pdf_bytes, mime_type="application/pdf",
        )
        msg_id = ((result.get("messages") or [{}])[0]).get("id")
        return jsonify({"ok": True, "message_id": msg_id}), 200
    except Exception as e:
        logging.error(f"[INVOICE WA SEND ERROR] invoice={iid}: {e}")
        return jsonify({"error": str(e)}), 500


def _erp_apply_invoice_payment(inv, amount, method="manual"):
    """Shared payment-recording logic for an ERP invoice. On full payment:
    posts a revenue ledger entry, decrements stock for any linked products
    (goods actually left the shelf once the sale is real), and marks the
    invoice paid. Used by the authenticated record-payment endpoint below
    AND by payment-gateway webhooks (e.g. Paynow) that confirm an invoice
    was paid via mobile money, so both paths stay consistent. Caller is
    responsible for db.session.commit()."""
    was_unpaid = inv.amount_paid < inv.total
    inv.amount_paid = round((inv.amount_paid or 0) + amount, 2)
    newly_fully_paid = was_unpaid and inv.amount_paid >= inv.total
    if newly_fully_paid:
        # Click-to-WhatsApp ad attribution: credit this sale to the ad that
        # started the customer's chat (no-op if they didn't come from one).
        try:
            enqueue_job(_wa_capi_purchase_job, app, inv.owner_user_id, inv.id, inv.customer_id,
                        float(inv.total or 0), inv.currency)
            enqueue_job(_wa_receipt_job, app, inv.owner_user_id, inv.id, inv.customer_id,
                        float(inv.total or 0), inv.currency, inv.invoice_number)
        except Exception as _capi_err:
            logging.error(f"[WA CAPI ENQUEUE ERROR] {_capi_err}")
    if inv.amount_paid >= inv.total:
        inv.status = "paid"; inv.paid_at = datetime.utcnow()
    elif inv.amount_paid > 0:
        inv.status = "sent"

    # GLOBAL-06: if this invoice was sold on the factoring marketplace,
    # the right to collect it belongs to whoever funded it — credit
    # their ledger instead of the original seller's, since the seller
    # already received their advance up front.
    listing = FactoringListing.query.filter_by(invoice_id=inv.id, status="funded").first()
    # Tokenized receivables: an invoice can have at most one active
    # tokenization (open or funded) alongside no active FactoringListing —
    # enforced at creation time, so this lookup is safe.
    token_receivable = TokenizedReceivable.query.filter_by(invoice_id=inv.id).filter(
        TokenizedReceivable.status.in_(["open", "funded"])).first()
    if listing:
        _erp_post_ledger(listing.buyer_user_id, datetime.utcnow().date(), "revenue", "Factoring Return",
                          f"Collection on factored invoice {inv.invoice_number}", amount, "invoice", inv.id)
        if newly_fully_paid:
            listing.status = "collected"; listing.collected_at = datetime.utcnow()
    elif token_receivable:
        tokenized_fraction = (token_receivable.amount_tokenized / token_receivable.face_value_at_listing
                               if token_receivable.face_value_at_listing else 0)
        tokenized_fraction = max(0.0, min(tokenized_fraction, 1.0))
        tokenized_share = round(amount * tokenized_fraction, 2)
        unsold_share = round(tokenized_share * ((TOKENIZED_RECEIVABLE_UNITS - token_receivable.units_sold)
                                                  / TOKENIZED_RECEIVABLE_UNITS), 2)
        untokenized_share = round(amount - tokenized_share, 2)
        seller_share = round(unsold_share + untokenized_share, 2)
        if seller_share:
            _erp_post_ledger(inv.owner_user_id, datetime.utcnow().date(), "revenue", "Sales",
                              f"Payment for invoice {inv.invoice_number} ({method}) — untokenized/unsold portion",
                              seller_share, "invoice", inv.id)
        if token_receivable.units_sold:
            per_unit_payment = tokenized_share / TOKENIZED_RECEIVABLE_UNITS if TOKENIZED_RECEIVABLE_UNITS else 0
            holdings = ReceivableTokenHolding.query.filter_by(
                tokenized_receivable_id=token_receivable.id).filter(ReceivableTokenHolding.units > 0).all()
            for h in holdings:
                holder_amount = round(per_unit_payment * h.units, 2)
                if holder_amount:
                    _erp_post_ledger(h.holder_user_id, datetime.utcnow().date(), "revenue", "Tokenized Receivable Return",
                                      f"Collection on tokenized invoice {inv.invoice_number} ({h.units} units)",
                                      holder_amount, "tokenized_receivable", token_receivable.id)
        if newly_fully_paid:
            token_receivable.status = "settled"; token_receivable.settled_at = datetime.utcnow()
            ReceivableTokenResaleListing.query.filter_by(
                tokenized_receivable_id=token_receivable.id, status="listed"
            ).update({"status": "cancelled"})
    else:
        _erp_post_ledger(inv.owner_user_id, datetime.utcnow().date(), "revenue", "Sales",
                          f"Payment for invoice {inv.invoice_number} ({method})", amount, "invoice", inv.id)
    if newly_fully_paid:
        for line in ErpInvoiceItem.query.filter_by(invoice_id=inv.id).all():
            _erp_apply_stock_delta(line.product_id, -line.quantity)
        _fire_webhook(inv.owner_user_id, "invoice.paid", inv.to_dict())
        # STAGE 300: fire any workspace automation workflows listening
        # for "invoice_paid" — no-op if no workspace/workflow.
        fire_automation_trigger(_automation_org_id_for_user(inv.owner_user_id), "invoice_paid", {
            "invoice_number": inv.invoice_number,
            "total": inv.total,
            "currency": inv.currency,
            "customer_id": inv.customer_id,
            "payment_method": method,
        })
    return newly_fully_paid


@app.route("/api/erp/invoices/<int:iid>/record-payment", methods=["POST"])
@csrf.exempt
def erp_invoices_record_payment(iid):
    """Records a payment against an invoice. On full payment: posts a
    revenue ledger entry, decrements stock for any linked products
    (goods actually left the shelf once the sale is real), and marks
    the invoice paid."""
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    inv = ErpInvoice.query.get(iid)
    if not inv or inv.owner_user_id != user["id"]: return jsonify({"error": "Invoice not found."}), 404
    data = request.get_json(silent=True) or {}
    try:
        amount = float(data.get("amount", inv.total - inv.amount_paid) or 0)
        _erp_apply_invoice_payment(inv, amount, data.get("method", "manual"))
        db.session.commit()
    except Exception as e:
        db.session.rollback(); logging.error(f"[ERP INVOICE PAYMENT] {e}")
        return jsonify({"error": "Could not record payment."}), 500
    return jsonify({"invoice": inv.to_dict(include_items=True)}), 200


# ════════════════════════════════════════════════════════════
# GLOBAL-06: INVOICE FACTORING MARKETPLACE — routes
# ════════════════════════════════════════════════════════════
@app.route("/api/factoring/listings", methods=["POST"])
@csrf.exempt
def factoring_listing_create():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    blocked = require_plan(user, "factoring")
    if blocked: return blocked
    data = request.get_json(silent=True) or {}
    inv = ErpInvoice.query.get(data.get("invoice_id"))
    if not inv or inv.owner_user_id != user["id"]:
        return jsonify({"error": "Invoice not found."}), 404
    if inv.status not in ("sent", "overdue"):
        return jsonify({"error": "Only unpaid, sent/overdue invoices can be listed for factoring."}), 400
    if FactoringListing.query.filter_by(invoice_id=inv.id).filter(FactoringListing.status.in_(["listed", "funded"])).first():
        return jsonify({"error": "This invoice already has an active factoring listing."}), 400
    try:
        advance_rate = float(data.get("advance_rate", 0.85))
    except (TypeError, ValueError):
        advance_rate = 0.85
    advance_rate = max(0.5, min(advance_rate, 0.95))
    face_value = round((inv.total or 0) - (inv.amount_paid or 0), 2)
    if face_value <= 0:
        return jsonify({"error": "This invoice has no outstanding balance to factor."}), 400
    try:
        listing = FactoringListing(
            invoice_id=inv.id, seller_user_id=user["id"], face_value=face_value,
            advance_rate=advance_rate, advance_amount=round(face_value * advance_rate, 2),
        )
        db.session.add(listing); db.session.commit()
    except Exception as e:
        db.session.rollback(); logging.error(f"[FACTORING LISTING CREATE] {e}")
        return jsonify({"error": "Could not create listing."}), 500
    return jsonify({"listing": listing.to_dict()}), 201


@app.route("/api/factoring/listings/marketplace", methods=["GET"])
def factoring_marketplace_browse():
    """Open listings any other user can fund. Includes the seller's
    credit score so an investor can weigh the risk before committing
    real cash — no invoice line-item or customer detail is exposed."""
    user, err = _erp_user_or_401()
    if err: return err
    rows = (FactoringListing.query.filter_by(status="listed")
            .filter(FactoringListing.seller_user_id != user["id"])
            .order_by(FactoringListing.listed_at.desc()).limit(100).all())
    out = []
    for l in rows:
        inv = ErpInvoice.query.get(l.invoice_id)
        seller_score = compute_credit_score(l.seller_user_id)
        d = l.to_dict()
        d["invoice_due_date"] = inv.due_date.isoformat() if inv and inv.due_date else None
        d["invoice_currency"] = inv.currency if inv else None
        d["seller_credit_score"] = seller_score["score"]
        d["seller_risk_grade"] = seller_score["risk_grade"]
        out.append(d)
    return jsonify({"listings": out}), 200


