@app.route("/api/factoring/listings/<int:lid>/fund", methods=["POST"])
@csrf.exempt
def factoring_listing_fund(lid):
    """Investor funds the listing: seller gets the advance amount in
    cash today; the buyer now owns the right to collect the invoice
    when it's eventually paid (see _erp_apply_invoice_payment)."""
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    listing = FactoringListing.query.get(lid)
    if not listing or listing.status != "listed":
        return jsonify({"error": "Listing not available."}), 404
    if listing.seller_user_id == user["id"]:
        return jsonify({"error": "You can't fund your own listing."}), 400
    try:
        listing.buyer_user_id = user["id"]
        listing.status = "funded"
        listing.funded_at = datetime.utcnow()
        today = datetime.utcnow().date()
        _erp_post_ledger(listing.seller_user_id, today, "revenue", "Factoring Advance",
                          f"Advance for factored invoice #{listing.invoice_id}", listing.advance_amount,
                          "factoring_listing", listing.id)
        _erp_post_ledger(user["id"], today, "expense", "Factoring Investment",
                          f"Funded factoring listing #{listing.id}", -abs(listing.advance_amount),
                          "factoring_listing", listing.id)
        db.session.commit()
    except Exception as e:
        db.session.rollback(); logging.error(f"[FACTORING FUND] {e}")
        return jsonify({"error": "Could not fund listing."}), 500
    return jsonify({"listing": listing.to_dict()}), 200


