@app.route("/api/tokenized-receivables", methods=["POST"])
@csrf.exempt
def tokenized_receivable_create():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    inv = ErpInvoice.query.get(data.get("invoice_id"))
    if not inv or inv.owner_user_id != user["id"]:
        return jsonify({"error": "Invoice not found."}), 404
    if inv.status not in ("sent", "overdue"):
        return jsonify({"error": "Only unpaid, sent/overdue invoices can be tokenized."}), 400
    if FactoringListing.query.filter_by(invoice_id=inv.id).filter(FactoringListing.status.in_(["listed", "funded"])).first():
        return jsonify({"error": "This invoice already has an active factoring listing."}), 400
    if TokenizedReceivable.query.filter_by(invoice_id=inv.id).filter(TokenizedReceivable.status.in_(["open", "funded"])).first():
        return jsonify({"error": "This invoice already has an active tokenized receivable."}), 400
    face_value = round((inv.total or 0) - (inv.amount_paid or 0), 2)
    if face_value <= 0:
        return jsonify({"error": "This invoice has no outstanding balance to tokenize."}), 400
    try:
        amount_tokenized = float(data.get("amount_tokenized", face_value))
    except (TypeError, ValueError):
        amount_tokenized = face_value
    amount_tokenized = round(max(0.01, min(amount_tokenized, face_value)), 2)
    try:
        advance_rate = float(data.get("advance_rate", 0.85))
    except (TypeError, ValueError):
        advance_rate = 0.85
    advance_rate = max(0.5, min(advance_rate, 0.95))
    unit_price = round((amount_tokenized / TOKENIZED_RECEIVABLE_UNITS) * advance_rate, 4)
    try:
        tr = TokenizedReceivable(
            invoice_id=inv.id, seller_user_id=user["id"], face_value_at_listing=face_value,
            amount_tokenized=amount_tokenized, advance_rate=advance_rate, unit_price=unit_price,
        )
        db.session.add(tr); db.session.commit()
    except Exception as e:
        db.session.rollback(); logging.error(f"[TOKENIZED RECEIVABLE CREATE] {e}")
        return jsonify({"error": "Could not create tokenized receivable."}), 500
    return jsonify({"tokenized_receivable": tr.to_dict()}), 201


@app.route("/api/tokenized-receivables/marketplace", methods=["GET"])
def tokenized_receivables_marketplace():
    """Open primary offerings any other user can buy units of. Includes
    the seller's credit score, same as the factoring marketplace —
    no invoice line-item or customer detail is exposed."""
    user, err = _erp_user_or_401()
    if err: return err
    rows = (TokenizedReceivable.query.filter_by(status="open")
            .filter(TokenizedReceivable.seller_user_id != user["id"])
            .order_by(TokenizedReceivable.listed_at.desc()).limit(100).all())
    out = []
    for tr in rows:
        inv = ErpInvoice.query.get(tr.invoice_id)
        seller_score = compute_credit_score(tr.seller_user_id)
        d = tr.to_dict()
        d["invoice_due_date"] = inv.due_date.isoformat() if inv and inv.due_date else None
        d["invoice_currency"] = inv.currency if inv else None
        d["seller_credit_score"] = seller_score["score"]
        d["seller_risk_grade"] = seller_score["risk_grade"]
        out.append(d)
    return jsonify({"tokenized_receivables": out}), 200


