@app.route("/api/tokenized-receivables/<int:trid>/buy", methods=["POST"])
@csrf.exempt
def tokenized_receivable_buy(trid):
    """Primary-market purchase: invests units_requested * unit_price in
    cash today; seller receives that cash immediately (pay-as-sold,
    not held until the offering fully sells out)."""
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    tr = TokenizedReceivable.query.get(trid)
    if not tr or tr.status != "open":
        return jsonify({"error": "This tokenized receivable is not open for investment."}), 404
    if tr.seller_user_id == user["id"]:
        return jsonify({"error": "You can't buy units of your own tokenized receivable."}), 400
    data = request.get_json(silent=True) or {}
    try:
        units = int(data.get("units", 0))
    except (TypeError, ValueError):
        units = 0
    units_remaining = TOKENIZED_RECEIVABLE_UNITS - tr.units_sold
    if units <= 0 or units > units_remaining:
        return jsonify({"error": f"Enter between 1 and {units_remaining} units."}), 400
    try:
        cost = round(units * tr.unit_price, 2)
        tr.units_sold += units
        if tr.units_sold >= TOKENIZED_RECEIVABLE_UNITS:
            tr.status = "funded"; tr.funded_at = datetime.utcnow()
        holding = ReceivableTokenHolding.query.filter_by(
            tokenized_receivable_id=tr.id, holder_user_id=user["id"]).first()
        if not holding:
            holding = ReceivableTokenHolding(tokenized_receivable_id=tr.id, holder_user_id=user["id"])
            db.session.add(holding)
        holding.units += units
        holding.total_cost += cost
        holding.last_acquired_at = datetime.utcnow()
        today = datetime.utcnow().date()
        _erp_post_ledger(tr.seller_user_id, today, "revenue", "Tokenized Receivable Advance",
                          f"{units} units sold on tokenized invoice #{tr.invoice_id}", cost,
                          "tokenized_receivable", tr.id)
        _erp_post_ledger(user["id"], today, "expense", "Tokenized Receivable Investment",
                          f"Bought {units} units of tokenized receivable #{tr.id}", -abs(cost),
                          "tokenized_receivable", tr.id)
        db.session.commit()
    except Exception as e:
        db.session.rollback(); logging.error(f"[TOKENIZED RECEIVABLE BUY] {e}")
        return jsonify({"error": "Could not complete purchase."}), 500
    return jsonify({"tokenized_receivable": tr.to_dict(), "holding": holding.to_dict()}), 200


