@app.route("/api/tokenized-receivables/resale-listings", methods=["POST"])
@csrf.exempt
def receivable_resale_listing_create():
    """Secondary market: a holder offers some of their units for resale
    to a different investor before the invoice is paid."""
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    blocked = require_plan(user, "tokenized_receivables")
    if blocked: return blocked
    data = request.get_json(silent=True) or {}
    tr = TokenizedReceivable.query.get(data.get("tokenized_receivable_id"))
    if not tr or tr.status not in ("open", "funded"):
        return jsonify({"error": "This tokenized receivable can't be resold on right now."}), 404
    holding = ReceivableTokenHolding.query.filter_by(
        tokenized_receivable_id=tr.id, holder_user_id=user["id"]).first()
    already_listed = db.session.query(db.func.coalesce(db.func.sum(ReceivableTokenResaleListing.units), 0)).filter_by(
        tokenized_receivable_id=tr.id, seller_user_id=user["id"], status="listed").scalar() or 0
    available_units = (holding.units if holding else 0) - already_listed
    try:
        units = int(data.get("units", 0))
        price_per_unit = float(data.get("price_per_unit", tr.unit_price))
    except (TypeError, ValueError):
        return jsonify({"error": "Invalid units or price."}), 400
    if units <= 0 or units > available_units:
        return jsonify({"error": f"You have {available_units} unlisted units available to resell."}), 400
    if price_per_unit <= 0:
        return jsonify({"error": "Price per unit must be positive."}), 400
    try:
        rl = ReceivableTokenResaleListing(
            tokenized_receivable_id=tr.id, seller_user_id=user["id"], units=units, price_per_unit=round(price_per_unit, 4),
        )
        db.session.add(rl); db.session.commit()
    except Exception as e:
        db.session.rollback(); logging.error(f"[RECEIVABLE RESALE CREATE] {e}")
        return jsonify({"error": "Could not create resale listing."}), 500
    return jsonify({"resale_listing": rl.to_dict()}), 201


