@app.route("/api/tokenized-receivables/resale-listings/<int:rlid>/buy", methods=["POST"])
@csrf.exempt
def receivable_resale_listing_buy(rlid):
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    rl = ReceivableTokenResaleListing.query.get(rlid)
    if not rl or rl.status != "listed":
        return jsonify({"error": "Resale listing not available."}), 404
    if rl.seller_user_id == user["id"]:
        return jsonify({"error": "You can't buy your own resale listing."}), 400
    seller_holding = ReceivableTokenHolding.query.filter_by(
        tokenized_receivable_id=rl.tokenized_receivable_id, holder_user_id=rl.seller_user_id).first()
    if not seller_holding or seller_holding.units < rl.units:
        rl.status = "cancelled"; db.session.commit()
        return jsonify({"error": "Seller no longer holds enough units; listing cancelled."}), 400
    try:
        total_price = round(rl.units * rl.price_per_unit, 2)
        avg_unit_cost = seller_holding.total_cost / seller_holding.units if seller_holding.units else 0
        seller_holding.units -= rl.units
        seller_holding.total_cost = max(0.0, round(seller_holding.total_cost - (avg_unit_cost * rl.units), 2))
        buyer_holding = ReceivableTokenHolding.query.filter_by(
            tokenized_receivable_id=rl.tokenized_receivable_id, holder_user_id=user["id"]).first()
        if not buyer_holding:
            buyer_holding = ReceivableTokenHolding(tokenized_receivable_id=rl.tokenized_receivable_id, holder_user_id=user["id"])
            db.session.add(buyer_holding)
        buyer_holding.units += rl.units
        buyer_holding.total_cost += total_price
        buyer_holding.last_acquired_at = datetime.utcnow()
        rl.status = "sold"; rl.buyer_user_id = user["id"]; rl.sold_at = datetime.utcnow()
        today = datetime.utcnow().date()
        _erp_post_ledger(rl.seller_user_id, today, "revenue", "Receivable Token Resale",
                          f"Sold {rl.units} units on secondary market (listing #{rl.id})", total_price,
                          "receivable_resale", rl.id)
        _erp_post_ledger(user["id"], today, "expense", "Receivable Token Purchase",
                          f"Bought {rl.units} units on secondary market (listing #{rl.id})", -abs(total_price),
                          "receivable_resale", rl.id)
        db.session.commit()
    except Exception as e:
        db.session.rollback(); logging.error(f"[RECEIVABLE RESALE BUY] {e}")
        return jsonify({"error": "Could not complete resale purchase."}), 500
    return jsonify({"resale_listing": rl.to_dict(), "holding": buyer_holding.to_dict()}), 200


