@app.route("/api/erp/purchase-orders", methods=["POST"])
@csrf.exempt
def erp_pos_create():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    items, subtotal = _erp_items_from_payload(data.get("items"), product_field="product_id")
    if not items: return jsonify({"error": "At least one line item is required."}), 400
    try:
        po = ErpPurchaseOrder(
            owner_user_id=user["id"], supplier_id=data.get("supplier_id"),
            po_number=data.get("po_number") or _erp_gen_number("PO"),
            currency=data.get("currency", "USD"),
            order_date=_erp_parse_date(data.get("order_date"), datetime.utcnow().date()),
            expected_date=_erp_parse_date(data.get("expected_date")),
            subtotal=subtotal, tax_amount=float(data.get("tax_amount", 0) or 0),
            total=round(subtotal + float(data.get("tax_amount", 0) or 0), 2), notes=data.get("notes"),
        )
        db.session.add(po); db.session.flush()
        for it in items:
            db.session.add(ErpPurchaseOrderItem(po_id=po.id, product_id=it["product_id"], description=it["description"],
                                                  quantity=it["quantity"], unit_cost=it["price"], line_total=it["line_total"]))
        db.session.commit()
    except Exception as e:
        db.session.rollback(); logging.error(f"[ERP PO CREATE] {e}")
        return jsonify({"error": "Could not save purchase order."}), 500
    return jsonify({"purchase_order": po.to_dict(include_items=True)}), 201


