@app.route("/api/erp/purchase-orders/<int:pid>/receive", methods=["POST"])
@csrf.exempt
def erp_pos_receive(pid):
    """Marks a PO received: adds each line's quantity into stock and
    posts a COGS ledger entry for the spend."""
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    po = ErpPurchaseOrder.query.get(pid)
    if not po or po.owner_user_id != user["id"]: return jsonify({"error": "Purchase order not found."}), 404
    if po.status == "received": return jsonify({"error": "Already received."}), 400
    try:
        for line in ErpPurchaseOrderItem.query.filter_by(po_id=po.id).all():
            _erp_apply_stock_delta(line.product_id, line.quantity)
        po.status = "received"; po.received_at = datetime.utcnow()
        _erp_post_ledger(user["id"], datetime.utcnow().date(), "cogs", "Stock Purchases",
                          f"Received PO {po.po_number}", -abs(po.total), "purchase_order", po.id)
        db.session.commit()
    except Exception as e:
        db.session.rollback(); logging.error(f"[ERP PO RECEIVE] {e}")
        return jsonify({"error": "Could not receive purchase order."}), 500
    return jsonify({"purchase_order": po.to_dict(include_items=True)}), 200


