@app.route("/api/fraud/flags/<int:flag_id>/resolve", methods=["POST"])
@csrf.exempt
def fraud_flag_resolve(flag_id):
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    flag = FraudFlag.query.get(flag_id)
    if not flag or flag.owner_user_id != user["id"]:
        return jsonify({"error": "Flag not found."}), 404
    data = request.get_json(silent=True) or {}
    new_status = (data.get("status") or "").strip()
    if new_status not in ("dismissed", "confirmed_fraud", "reviewing"):
        return jsonify({"error": "status must be 'dismissed', 'confirmed_fraud', or 'reviewing'."}), 400
    try:
        flag.status = new_status
        flag.resolution_note = (data.get("note") or "").strip()[:500] or None
        flag.resolved_by = user["id"]
        flag.resolved_at = datetime.utcnow()
        db.session.commit()
        org = _org_for_user(user["id"])
        if org:
            _audit(org.id, user["id"], user.get("email"), "fraud.flag_resolved", "fraud_flag", flag.id,
                   {"status": new_status})
        return jsonify({"flag": flag.to_dict()}), 200
    except Exception as e:
        db.session.rollback(); logging.error(f"[FRAUD FLAG RESOLVE] {e}")
        return jsonify({"error": "Could not update flag."}), 500


