@app.route("/api/erp/ledger", methods=["GET"])
def erp_ledger_list():
    user, err = _erp_user_or_401()
    if err: return err
    q = ErpLedgerEntry.query.filter_by(owner_user_id=user["id"])
    start = _erp_parse_date(request.args.get("start"))
    end = _erp_parse_date(request.args.get("end"))
    if start: q = q.filter(ErpLedgerEntry.entry_date >= start)
    if end: q = q.filter(ErpLedgerEntry.entry_date <= end)
