@app.route("/api/erp/ledger/summary", methods=["GET"])
def erp_ledger_summary():
    """Simple P&L: revenue vs. expenses+COGS+payroll, over an optional
    date range (defaults to the current calendar month)."""
    user, err = _erp_user_or_401()
    if err: return err
    today = datetime.utcnow().date()
    start = _erp_parse_date(request.args.get("start"), today.replace(day=1))
    end = _erp_parse_date(request.args.get("end"), today)
    rows = (ErpLedgerEntry.query.filter_by(owner_user_id=user["id"])
            .filter(ErpLedgerEntry.entry_date >= start, ErpLedgerEntry.entry_date <= end).all())
    revenue = sum(r.amount for r in rows if r.amount > 0)
    outflow = sum(-r.amount for r in rows if r.amount < 0)
    by_account = defaultdict(float)
    for r in rows:
        by_account[r.account] += r.amount
    return jsonify({
        "start": start.isoformat(), "end": end.isoformat(),
        "revenue": round(revenue, 2), "expenses": round(outflow, 2),
        "net_profit": round(revenue - outflow, 2),
        "by_account": {k: round(v, 2) for k, v in by_account.items()},
    }), 200


# ════════════════════════════════════════════════════════════
# NEXT-02: AUTO-GENERATED MONTH-END CLOSE
# One tap: P&L, a simplified balance sheet, and a cash-flow statement
# for a chosen month, computed live from ErpLedgerEntry/ErpInvoice/
# ErpPurchaseOrder/InventoryItem — the same source data the rest of the
# ERP already posts to, nothing separately maintained. Downloadable as
# PDF or Excel for an accountant or a loan application.
#
# Honesty note (also stated in the report itself): this ledger is
# single-entry, not full double-entry bookkeeping, so the "balance
# sheet" below is a simplified approximation — Cash, Accounts
# Receivable, and Inventory value on the asset side; open Purchase
# Orders as Accounts Payable on the liability side; Equity is a plug
# (Assets − Liabilities), not a tracked owner's-equity ledger. Good
# enough for a lender's first look or a bookkeeper's starting point;
# not a substitute for a qualified accountant's signed statements.
# ════════════════════════════════════════════════════════════

def _month_end_close_compute(uid, year, month):
    period_start = datetime(year, month, 1).date()
    period_end = (datetime(year + 1, 1, 1).date() if month == 12 else datetime(year, month + 1, 1).date()) - timedelta(days=1)
    today = datetime.utcnow().date()
    if period_end > today:
        period_end = today

    all_entries = ErpLedgerEntry.query.filter_by(owner_user_id=uid).order_by(ErpLedgerEntry.entry_date.asc()).all()
    period_entries = [e for e in all_entries if period_start <= e.entry_date <= period_end]
    prior_entries = [e for e in all_entries if e.entry_date < period_start]

    # ── P&L ──
    revenue = round(sum(e.amount for e in period_entries if e.kind == "revenue" and e.amount > 0), 2)
    cogs = round(sum(-e.amount for e in period_entries if e.kind == "cogs" and e.amount < 0), 2)
    payroll = round(sum(-e.amount for e in period_entries if e.kind == "payroll" and e.amount < 0), 2)
    opex = round(sum(-e.amount for e in period_entries
                      if e.kind == "expense" and e.amount < 0), 2)
    other_outflow = round(sum(-e.amount for e in period_entries
                               if e.kind not in ("revenue", "cogs", "payroll", "expense") and e.amount < 0), 2)
    other_inflow = round(sum(e.amount for e in period_entries
                              if e.kind not in ("revenue",) and e.amount > 0), 2)
    gross_profit = round(revenue - cogs, 2)
    total_opex = round(payroll + opex + other_outflow, 2)
    net_profit = round(gross_profit + other_inflow - total_opex, 2)

    by_account = defaultdict(float)
    for e in period_entries:
        by_account[e.account] += e.amount

    # ── Balance sheet, as of period_end ──
    cash_position = round(sum(e.amount for e in all_entries if e.entry_date <= period_end), 2)
    unpaid_invoices = (ErpInvoice.query.filter_by(owner_user_id=uid)
                        .filter(ErpInvoice.status.in_(["sent", "overdue"])).all())
    accounts_receivable = round(sum(max((inv.total or 0) - (inv.amount_paid or 0), 0)
                                     for inv in unpaid_invoices
                                     if not inv.issue_date or inv.issue_date <= period_end), 2)
    inventory_items = InventoryItem.query.filter_by(user_id=uid, active=True).all()
    inventory_value = round(sum((it.quantity or 0) * (it.cost_price or 0) for it in inventory_items), 2)
    total_assets = round(cash_position + accounts_receivable + inventory_value, 2)

    open_pos = (ErpPurchaseOrder.query.filter_by(owner_user_id=uid)
                .filter(ErpPurchaseOrder.status.in_(["draft", "ordered"])).all())
    accounts_payable = round(sum((po.total or 0) for po in open_pos
                                  if not po.order_date or po.order_date <= period_end), 2)
    total_liabilities = accounts_payable
    equity = round(total_assets - total_liabilities, 2)

    # ── Cash flow statement for the period ──
    beginning_cash = round(sum(e.amount for e in prior_entries), 2)
    net_operating_cash_flow = round(sum(e.amount for e in period_entries), 2)
    ending_cash = round(beginning_cash + net_operating_cash_flow, 2)

    return {
        "period": {"year": year, "month": month, "start": period_start.isoformat(), "end": period_end.isoformat()},
        "pnl": {
            "revenue": revenue, "cogs": cogs, "gross_profit": gross_profit,
            "payroll": payroll, "operating_expenses": opex, "other_expenses": other_outflow,
            "other_income": other_inflow, "total_operating_expenses": total_opex,
            "net_profit": net_profit, "by_account": {k: round(v, 2) for k, v in by_account.items()},
        },
        "balance_sheet": {
            "assets": {"cash": cash_position, "accounts_receivable": accounts_receivable,
                       "inventory_value": inventory_value, "total_assets": total_assets},
            "liabilities": {"accounts_payable": accounts_payable, "total_liabilities": total_liabilities},
            "equity": {"retained_earnings_plug": equity},
        },
        "cash_flow": {
            "beginning_cash": beginning_cash, "net_operating_cash_flow": net_operating_cash_flow,
            "ending_cash": ending_cash,
        },
    }


@app.route("/api/erp/month-end-close", methods=["GET"])
def erp_month_end_close():
    user, err = _erp_user_or_401()
    if err: return err
    today = datetime.utcnow().date()
    try:
        year = int(request.args.get("year", today.year))
        month = int(request.args.get("month", today.month))
        if not (1 <= month <= 12):
            raise ValueError
    except (TypeError, ValueError):
        return jsonify({"error": "year and month must be valid integers, month 1-12."}), 400
    fmt = (request.args.get("format") or "json").lower()

    result = _month_end_close_compute(user["id"], year, month)
    business_name = (user.get("name") or "Business").strip()
    period_label = result["period"]["start"] + " to " + result["period"]["end"]
    filename_base = f"Month-End-Close-{year}-{month:02d}"

    if fmt == "json":
        return jsonify(result), 200

    if fmt == "xlsx":
        try:
            from openpyxl import Workbook
            from openpyxl.styles import Font, Alignment
            wb = Workbook()
            ws = wb.active
            ws.title = "Month-End Close"
            bold = Font(bold=True)
            ws.append([f"{business_name} — Month-End Close"])
            ws["A1"].font = Font(bold=True, size=14)
            ws.append([period_label])
            ws.append([])
            ws.append(["Profit & Loss"]); ws[f"A{ws.max_row}"].font = bold
            p = result["pnl"]
            for label, val in [("Revenue", p["revenue"]), ("COGS", p["cogs"]), ("Gross Profit", p["gross_profit"]),
                                ("Payroll", p["payroll"]), ("Operating Expenses", p["operating_expenses"]),
                                ("Other Expenses", p["other_expenses"]), ("Other Income", p["other_income"]),
                                ("Net Profit", p["net_profit"])]:
                ws.append([label, val])
            ws.append([])
            ws.append(["Balance Sheet (simplified, single-entry approximation)"]); ws[f"A{ws.max_row}"].font = bold
            bs = result["balance_sheet"]
            ws.append(["Cash", bs["assets"]["cash"]])
            ws.append(["Accounts Receivable", bs["assets"]["accounts_receivable"]])
            ws.append(["Inventory Value", bs["assets"]["inventory_value"]])
            ws.append(["Total Assets", bs["assets"]["total_assets"]])
            ws.append(["Accounts Payable", bs["liabilities"]["accounts_payable"]])
            ws.append(["Total Liabilities", bs["liabilities"]["total_liabilities"]])
            ws.append(["Equity (retained earnings, plug)", bs["equity"]["retained_earnings_plug"]])
            ws.append([])
            ws.append(["Cash Flow Statement"]); ws[f"A{ws.max_row}"].font = bold
            cf = result["cash_flow"]
            ws.append(["Beginning Cash", cf["beginning_cash"]])
            ws.append(["Net Operating Cash Flow", cf["net_operating_cash_flow"]])
            ws.append(["Ending Cash", cf["ending_cash"]])
            ws.column_dimensions["A"].width = 34
            ws.column_dimensions["B"].width = 18
            buf = io.BytesIO()
            wb.save(buf)
            buf.seek(0)
            return Response(buf, mimetype="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
                             headers={"Content-Disposition": f'attachment; filename="{filename_base}.xlsx"'})
        except Exception as e:
            logging.error(f"[MONTH-END CLOSE XLSX] {e}")
            return jsonify({"error": "Could not generate the Excel file."}), 500

    if fmt == "pdf":
        if not REPORTLAB_AVAILABLE:
            return jsonify({"error": "PDF generation isn't available on this server."}), 500
        try:
            from reportlab.lib import colors
            from reportlab.platypus import TableStyle
            buf = io.BytesIO()
            doc = SimpleDocTemplate(buf, pagesize=A4, rightMargin=40, leftMargin=40, topMargin=50, bottomMargin=40)
            styles = getSampleStyleSheet()
            story = [Paragraph(f"{business_name} — Month-End Close", styles["Title"]),
                     Paragraph(period_label, styles["Normal"]), Spacer(1, 16)]

            def section(title, rows):
                story.append(Paragraph(title, styles["Heading2"]))
                t = Table([[r[0], f"${r[1]:,.2f}"] for r in rows], colWidths=[300, 120])
                t.setStyle(TableStyle([
                    ("FONTSIZE", (0, 0), (-1, -1), 9),
                    ("LINEBELOW", (0, 0), (-1, -1), 0.5, colors.HexColor("#e5e7eb")),
                    ("TOPPADDING", (0, 0), (-1, -1), 4), ("BOTTOMPADDING", (0, 0), (-1, -1), 4),
                ]))
                story.append(t)
                story.append(Spacer(1, 14))

            p = result["pnl"]
            section("Profit & Loss", [
                ("Revenue", p["revenue"]), ("COGS", p["cogs"]), ("Gross Profit", p["gross_profit"]),
                ("Payroll", p["payroll"]), ("Operating Expenses", p["operating_expenses"]),
                ("Other Expenses", p["other_expenses"]), ("Other Income", p["other_income"]),
                ("Net Profit", p["net_profit"]),
            ])
            bs = result["balance_sheet"]
            story.append(Paragraph(
                "Balance sheet is a simplified, single-entry approximation — see the note in the app for what this "
                "does and doesn't cover.", styles["Italic"]))
            story.append(Spacer(1, 6))
            section("Balance Sheet", [
                ("Cash", bs["assets"]["cash"]), ("Accounts Receivable", bs["assets"]["accounts_receivable"]),
                ("Inventory Value", bs["assets"]["inventory_value"]), ("Total Assets", bs["assets"]["total_assets"]),
                ("Accounts Payable", bs["liabilities"]["accounts_payable"]),
                ("Total Liabilities", bs["liabilities"]["total_liabilities"]),
                ("Equity (retained earnings, plug)", bs["equity"]["retained_earnings_plug"]),
            ])
            cf = result["cash_flow"]
            section("Cash Flow Statement", [
                ("Beginning Cash", cf["beginning_cash"]), ("Net Operating Cash Flow", cf["net_operating_cash_flow"]),
                ("Ending Cash", cf["ending_cash"]),
            ])
            doc.build(story)
            buf.seek(0)
            return Response(buf, mimetype="application/pdf",
                             headers={"Content-Disposition": f'attachment; filename="{filename_base}.pdf"'})
        except Exception as e:
            logging.error(f"[MONTH-END CLOSE PDF] {e}")
            return jsonify({"error": "Could not generate the PDF."}), 500

    return jsonify({"error": "format must be json, pdf, or xlsx."}), 400


# ── BANK STATEMENT RECONCILIATION ──────────────────────────
_RECONCILE_DATE_WINDOW_DAYS = 5   # bank clearing date vs ledger posting date can drift a few days
_RECONCILE_AMOUNT_TOLERANCE = 0.01

_RECONCILE_DATE_COL_HINTS   = ("date", "transaction date", "value date", "txn date", "posting date")
_RECONCILE_DESC_COL_HINTS   = ("description", "narrative", "details", "reference", "particulars", "narration")
_RECONCILE_AMOUNT_COL_HINTS = ("amount", "value")
_RECONCILE_DEBIT_COL_HINTS  = ("debit", "withdrawal", "money out", "paid out", "dr")
_RECONCILE_CREDIT_COL_HINTS = ("credit", "deposit", "money in", "paid in", "cr")


def _reconcile_find_col(header_row, hints):
    for i, col in enumerate(header_row):
        col_norm = (col or "").strip().lower()
        if any(h in col_norm for h in hints):
            return i
    return None


def _reconcile_parse_amount(raw):
    if raw is None:
        return None
    s = str(raw).strip().replace(",", "").replace("$", "").replace("USD", "").strip()
    if not s:
        return None
    negative = s.startswith("(") and s.endswith(")")
    if negative:
        s = s[1:-1]
    try:
        val = float(s)
    except ValueError:
        return None
    return -val if negative else val


def _reconcile_parse_date(raw):
    s = (raw or "").strip()
    if not s:
        return None
    for fmt in ("%Y-%m-%d", "%d/%m/%Y", "%d-%m-%Y", "%m/%d/%Y", "%d %b %Y", "%d %B %Y", "%d.%m.%Y"):
        try:
            return datetime.strptime(s, fmt).date()
        except ValueError:
            continue
    return None


def _reconcile_auto_match(owner_user_id, import_id):
    """Pairs each unmatched line in this import against an ErpLedgerEntry
    with the same amount (within a cent) inside a ±N day window, picking
    the closest date when more than one candidate qualifies. Ledger
    entries already claimed by another matched line are skipped."""
    already_matched_ledger_ids = {
        row.matched_ledger_id for row in
        BankStatementLine.query.filter_by(owner_user_id=owner_user_id, status="matched")
        .filter(BankStatementLine.matched_ledger_id.isnot(None)).all()
    }
    lines = BankStatementLine.query.filter_by(import_id=import_id, status="unmatched").all()
    matched = 0
    for line in lines:
        window_start = line.txn_date - timedelta(days=_RECONCILE_DATE_WINDOW_DAYS)
        window_end = line.txn_date + timedelta(days=_RECONCILE_DATE_WINDOW_DAYS)
        candidates = (ErpLedgerEntry.query.filter_by(owner_user_id=owner_user_id)
                      .filter(ErpLedgerEntry.entry_date >= window_start, ErpLedgerEntry.entry_date <= window_end)
                      .all())
        best = None
        best_diff_days = None
        for c in candidates:
            if c.id in already_matched_ledger_ids:
                continue
            if abs(c.amount - line.amount) > _RECONCILE_AMOUNT_TOLERANCE:
                continue
            diff_days = abs((c.entry_date - line.txn_date).days)
            if best is None or diff_days < best_diff_days:
                best, best_diff_days = c, diff_days
        if best:
            line.status = "matched"
            line.matched_ledger_id = best.id
            line.matched_auto = True
            already_matched_ledger_ids.add(best.id)
            matched += 1
    return matched


@app.route("/api/erp/reconcile/upload", methods=["POST"])
@csrf.exempt
def erp_reconcile_upload():
    """Accepts a bank statement CSV (form field 'file'), auto-detects
    date/description/amount columns (or separate debit/credit columns),
    stores each row as a BankStatementLine, then runs auto-match."""
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    if "file" not in request.files:
        return jsonify({"error": "Send the CSV under form field 'file'."}), 400
    f = request.files["file"]
    bank_name = (request.form.get("bank_name") or "").strip()[:100] or None
    try:
        raw = f.read().decode("utf-8-sig", errors="replace")
        reader = list(csv.reader(io.StringIO(raw)))
        if not reader:
            return jsonify({"error": "CSV file is empty."}), 400
        header = reader[0]
        date_col = _reconcile_find_col(header, _RECONCILE_DATE_COL_HINTS)
        desc_col = _reconcile_find_col(header, _RECONCILE_DESC_COL_HINTS)
        amount_col = _reconcile_find_col(header, _RECONCILE_AMOUNT_COL_HINTS)
        debit_col = _reconcile_find_col(header, _RECONCILE_DEBIT_COL_HINTS)
        credit_col = _reconcile_find_col(header, _RECONCILE_CREDIT_COL_HINTS)
        if date_col is None or (amount_col is None and debit_col is None and credit_col is None):
            return jsonify({"error": "Could not find a date column and an amount (or debit/credit) column in the CSV header. First row must be column headers."}), 400

        imp = BankStatementImport(owner_user_id=user["id"], filename=f.filename, bank_name=bank_name)
        db.session.add(imp); db.session.flush()

        line_count = 0
        for row in reader[1:]:
            if not row or all(not (c or "").strip() for c in row):
                continue
            txn_date = _reconcile_parse_date(row[date_col]) if date_col < len(row) else None
            if not txn_date:
                continue
            description = (row[desc_col].strip() if desc_col is not None and desc_col < len(row) else "")[:300]
            if amount_col is not None and amount_col < len(row):
                amount = _reconcile_parse_amount(row[amount_col])
            else:
                debit = _reconcile_parse_amount(row[debit_col]) if debit_col is not None and debit_col < len(row) else None
                credit = _reconcile_parse_amount(row[credit_col]) if credit_col is not None and credit_col < len(row) else None
                amount = (credit or 0) - abs(debit or 0)
            if amount is None:
                continue
            db.session.add(BankStatementLine(
                import_id=imp.id, owner_user_id=user["id"], txn_date=txn_date,
                description=description, amount=amount,
            ))
            line_count += 1

        imp.line_count = line_count
        db.session.flush()
        matched = _reconcile_auto_match(user["id"], imp.id)
        imp.matched_count = matched
        db.session.commit()
        return jsonify({"import": imp.to_dict()}), 201
    except Exception as e:
        db.session.rollback(); logging.error(f"[RECONCILE UPLOAD] {e}")
        return jsonify({"error": "Could not process that CSV. Check it has a header row with date/description/amount columns."}), 500


