@app.route("/api/erp/reconcile/lines/<int:line_id>/match", methods=["POST"])
@csrf.exempt
def erp_reconcile_line_match(line_id):
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    line = BankStatementLine.query.get(line_id)
    if not line or line.owner_user_id != user["id"]: return jsonify({"error": "Line not found."}), 404
    data = request.get_json(silent=True) or {}
    ledger_id = data.get("ledger_entry_id")
    ledger = ErpLedgerEntry.query.get(ledger_id) if ledger_id else None
    if not ledger or ledger.owner_user_id != user["id"]:
        return jsonify({"error": "ledger_entry_id must reference one of your ledger entries."}), 400
    try:
        line.status = "matched"; line.matched_ledger_id = ledger.id; line.matched_auto = False
        db.session.commit()
    except Exception as e:
        db.session.rollback(); logging.error(f"[RECONCILE MATCH] {e}")
        return jsonify({"error": "Could not match."}), 500
    return jsonify({"line": line.to_dict()}), 200


