@app.route("/api/erp/reconcile/unmatched-ledger", methods=["GET"])
def erp_reconcile_unmatched_ledger():
    """Ledger entries not currently claimed by any matched bank line —
    the candidate list for a manual match picker."""
    user, err = _erp_user_or_401()
    if err: return err
    matched_ledger_ids = {
        row.matched_ledger_id for row in
        BankStatementLine.query.filter_by(owner_user_id=user["id"], status="matched")
        .filter(BankStatementLine.matched_ledger_id.isnot(None)).all()
    }
    rows = (ErpLedgerEntry.query.filter_by(owner_user_id=user["id"])
            .order_by(ErpLedgerEntry.entry_date.desc()).limit(300).all())
    candidates = [r.to_dict() for r in rows if r.id not in matched_ledger_ids]
    return jsonify({"entries": candidates}), 200


