@app.route("/api/erp/employees/<int:eid>", methods=["PUT", "DELETE"])
@csrf.exempt
def erp_employees_update(eid):
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    e = ErpEmployee.query.get(eid)
    if not e or e.owner_user_id != user["id"]: return jsonify({"error": "Employee not found."}), 404
    try:
        if request.method == "DELETE":
            e.status = "inactive"
        else:
            data = request.get_json(silent=True) or {}
            for f in ("full_name", "email", "phone", "role", "pay_frequency", "status"):
                if f in data: setattr(e, f, data[f])
            if "salary" in data and data["salary"] is not None: e.salary = float(data["salary"])
            if "statutory_deductions" in data: e.statutory_deductions = bool(data["statutory_deductions"])
        db.session.commit()
    except Exception as ex:
        db.session.rollback(); logging.error(f"[ERP EMPLOYEE UPDATE] {ex}")
        return jsonify({"error": "Could not update employee."}), 500
    return jsonify({"employee": e.to_dict()}), 200


