@app.route("/api/hr/badges/issue", methods=["POST"])
@csrf.exempt
def hr_badges_issue():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    emp = ErpEmployee.query.get(data.get("employee_id"))
    if not emp or emp.owner_user_id != user["id"]:
        return jsonify({"error": "Employee not found."}), 404
    try:
        # Re-issuing deactivates any prior badge for this employee so an
        # old lost/printed badge can no longer be used to check in.
        StaffBadge.query.filter_by(owner_user_id=user["id"], employee_id=emp.id, active=True) \
            .update({"active": False})
        badge = StaffBadge(
            owner_user_id=user["id"], employee_id=emp.id,
            badge_code=secrets.token_hex(10), active=True,
        )
        db.session.add(badge); db.session.commit()
    except Exception as e:
        db.session.rollback(); logging.error(f"[HR BADGE ISSUE] {e}")
        return jsonify({"error": "Could not issue badge."}), 500
    d = badge.to_dict(); d["employee_name"] = emp.full_name
    return jsonify({"badge": d}), 201


@app.route("/api/hr/badges/<int:badge_id>/qrcode", methods=["GET"])
def hr_badge_qrcode(badge_id):
    user, err = _erp_user_or_401()
    if err: return err
    badge = StaffBadge.query.filter_by(id=badge_id, owner_user_id=user["id"]).first()
    if not badge:
        return jsonify({"error": "Badge not found."}), 404
    if not QRCODE_AVAILABLE:
        return jsonify({"error": "QR code generation isn't available on this server (qrcode library not installed)."}), 503
    emp = ErpEmployee.query.get(badge.employee_id)
    payload = f"STAFFBADGE:{badge.badge_code}"
    try:
        png_bytes = _generate_qr_png_bytes(payload)
    except RuntimeError as e:
        return jsonify({"error": str(e)}), 503
    except Exception as e:
        logging.error(f"[HR BADGE QR] {e}")
        return jsonify({"error": "Could not generate QR code."}), 500
    return Response(
        png_bytes, mimetype="image/png",
        headers={"Content-Disposition": f'inline; filename="badge-{badge_id}.png"'},
    )


@app.route("/api/hr/checkin", methods=["POST"])
@csrf.exempt
def hr_checkin():
    """Scanning (or manually entering) a badge code toggles that
    employee's attendance for today: first scan of the day sets
    check_in, a second scan sets check_out — same ErpAttendance row
    the manual attendance form already writes to."""
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    raw_code = (data.get("badge_code") or "").strip()
    code = raw_code.replace("STAFFBADGE:", "").strip()
    if not code:
        return jsonify({"error": "No badge code provided."}), 400
    badge = StaffBadge.query.filter_by(badge_code=code, owner_user_id=user["id"], active=True).first()
    if not badge:
        return jsonify({"error": "Badge not recognized or has been deactivated."}), 404
    emp = ErpEmployee.query.get(badge.employee_id)
    if not emp:
        return jsonify({"error": "Employee on this badge no longer exists."}), 404
    try:
        today = datetime.utcnow().date()
        now_str = datetime.utcnow().strftime("%H:%M")
        record = ErpAttendance.query.filter_by(employee_id=emp.id, work_date=today).first()
        if not record:
            record = ErpAttendance(employee_id=emp.id, work_date=today, check_in=now_str, status="present")
            db.session.add(record)
            action = "checked in"
        elif not record.check_out:
            record.check_out = now_str
            action = "checked out"
        else:
            # Already checked in and out today — treat as a fresh check-in.
            record.check_in = now_str; record.check_out = None
            action = "checked in"
        db.session.commit()
    except Exception as e:
        db.session.rollback(); logging.error(f"[HR CHECKIN] {e}")
        return jsonify({"error": "Could not record check-in."}), 500
    return jsonify({
        "ok": True, "action": action, "employee_name": emp.full_name,
        "time": now_str, "attendance": record.to_dict(),
    }), 200


@app.route("/api/hr/checkin/today", methods=["GET"])
def hr_checkin_today():
    user, err = _erp_user_or_401()
    if err: return err
    today = datetime.utcnow().date()
    emp_ids = [e.id for e in ErpEmployee.query.filter_by(owner_user_id=user["id"]).all()]
    rows = (ErpAttendance.query.filter(ErpAttendance.employee_id.in_(emp_ids), ErpAttendance.work_date == today)
            .order_by(ErpAttendance.id.desc()).all()) if emp_ids else []
    emps = {e: n for e, n in ErpEmployee.query.filter(ErpEmployee.id.in_(emp_ids)).with_entities(ErpEmployee.id, ErpEmployee.full_name)} if emp_ids else {}
    out = []
    for r in rows:
        d = r.to_dict()
        d["employee_name"] = emps.get(r.employee_id, "—")
        out.append(d)
    return jsonify({"today": out}), 200



# ═══════════════════════════════════════════════════════════
# ZIMBABWE STATUTORY PAYROLL DEDUCTIONS — PAYE (ZIMRA) + NSSA
#
# Source: ZIMRA "PAY AS YOU EARN (PAYE) FOREIGN CURRENCY TAX TABLES",
# official USD table effective Jan-Dec 2025 (zimra.co.zw/domestic-taxes/
# tax-tables). ZIMRA had not published a newer USD table as of mid-2026 —
# these bands have gone unchanged for several years and only move by
# government notice. AIDS Levy is a flat 3% of the PAYE amount (not of
# gross). NSSA (nssa.org.zw/contributions): Pension and Other Benefits
# Scheme, 4.5% employee + 4.5% employer of insurable earnings, capped at
# a USD 700/month ceiling (gazetted quarterly by NSSA, currently $700).
#
# ANNUAL UPDATE NOTE: re-check both tables every January (and any time
# ZIMRA or NSSA issues a new gazette) at the URLs above, and update the
# constants below — they are intentionally hardcoded rather than fetched
# live, since a payroll engine should never silently change what it
# deducts from someone's pay based on an unreviewed external source.
# ═══════════════════════════════════════════════════════════

# Each band: (upper_bound_of_this_bracket_or_None_for_top, rate, deduct)
ZW_PAYE_BANDS_MONTHLY = [
    (100.00,  0.00, 0.00),
    (300.00,  0.20, 20.00),
    (1000.00, 0.25, 35.00),
    (2000.00, 0.30, 85.00),
    (3000.00, 0.35, 185.00),
    (None,    0.40, 335.00),
]
ZW_PAYE_BANDS_WEEKLY = [
    (23.08,   0.00, 0.00),
    (69.23,   0.20, 4.62),
    (230.77,  0.25, 8.08),
    (461.54,  0.30, 19.62),
    (692.31,  0.35, 42.69),
    (None,    0.40, 77.31),
]
ZW_AIDS_LEVY_RATE       = 0.03    # 3% of PAYE payable
ZW_NSSA_RATE            = 0.045   # 4.5% employee + 4.5% employer (each)
ZW_NSSA_CEILING_MONTHLY = float(os.environ.get("ZW_NSSA_CEILING_MONTHLY", 700.00))
ZW_NSSA_CEILING_WEEKLY  = round(ZW_NSSA_CEILING_MONTHLY * 12 / 52, 2)


# ════════════════════════════════════════════════════════════
# GLOBAL-01: COUNTRY TAX PACK REGISTRY
# The platform no longer assumes every business is Zimbabwean. A "pack"
# describes one country's statutory payroll rules in a shape generic
# enough to cover income tax bands, flat levies (e.g. AIDS levy, a
# solidarity surcharge), and capped social-security contributions
# (split employee/employer) — the three ingredients nearly every
# country's payroll statute is built from. Zimbabwe's pack below
# reproduces the exact numbers calc_zimbabwe_paye always used; adding a
# country is adding a pack, not touching the payroll engine. Packs not
# yet researched fall back to GENERIC_NO_STATUTORY_PACK (0% everything,
# flagged so the UI can warn "verify local law" instead of silently
# showing wrong numbers).
#
# bands: list of (upper_bound_or_None, rate, cumulative_deduction) —
#   same "band ends at X, taxed at rate%, minus deduct" shape as before.
# levies: list of {name, rate, of} where of is "tax" (percent of the
#   income tax just computed) or "gross" (percent of gross pay).
# social_security: list of {name, employee_rate, employer_rate, ceiling}
#   — ceiling is the insurable/pensionable earnings cap for that period.
TAX_PACKS = {
    "ZW": {
        "label": "Zimbabwe", "currency": "USD",
        "income_tax": {"name": "PAYE", "bands_monthly": ZW_PAYE_BANDS_MONTHLY, "bands_weekly": ZW_PAYE_BANDS_WEEKLY},
        "levies": [{"name": "AIDS Levy", "rate": ZW_AIDS_LEVY_RATE, "of": "tax"}],
        "social_security": [{"name": "NSSA", "employee_rate": ZW_NSSA_RATE, "employer_rate": ZW_NSSA_RATE,
                              "ceiling_monthly": ZW_NSSA_CEILING_MONTHLY, "ceiling_weekly": ZW_NSSA_CEILING_WEEKLY}],
        "supported": True,
    },
    "ZA": {
        "label": "South Africa", "currency": "ZAR",
        "income_tax": {"name": "PAYE", "bands_monthly": [
            (7091, 0.18, 0), (11042, 0.26, 567), (15318, 0.31, 1119),
            (21243, 0.36, 1885), (33454, 0.39, 2522), (69848, 0.41, 3191), (None, 0.45, 5985),
        ], "bands_weekly": None},
        "levies": [],
        "social_security": [{"name": "UIF", "employee_rate": 0.01, "employer_rate": 0.01,
                              "ceiling_monthly": 17712.0, "ceiling_weekly": None}],
        "supported": True,
    },
    "UK": {
        "label": "United Kingdom", "currency": "GBP",
        "income_tax": {"name": "Income Tax", "bands_monthly": [
            (1047.5, 0.0, 0), (4189.17, 0.20, 209.5), (37500.0, 0.40, 838.13), (None, 0.45, 2713.13),
        ], "bands_weekly": None},
        "levies": [],
        "social_security": [{"name": "National Insurance", "employee_rate": 0.08, "employer_rate": 0.138,
                              "ceiling_monthly": None, "ceiling_weekly": None}],
        "supported": True,
    },
    "US": {
        "label": "United States (federal only — state tax not included)", "currency": "USD",
        "income_tax": {"name": "Federal Income Tax (simplified single-filer estimate)", "bands_monthly": [
            (958.0, 0.10, 0), (3897.0, 0.12, 19.16), (8299.0, 0.22, 408.86),
            (15850.0, 0.24, 574.84), (28400.0, 0.32, 1842.84), (35566.0, 0.35, 2900.84), (None, 0.37, 3611.16),
        ], "bands_weekly": None},
        "levies": [],
        "social_security": [{"name": "Social Security + Medicare (FICA)", "employee_rate": 0.0765,
                              "employer_rate": 0.0765, "ceiling_monthly": None, "ceiling_weekly": None}],
        "supported": True,
    },
    # Security & Sovereign Trust roadmap Section 2, item 1: Hyper-
    # Localised Compliance Engines — real, sourced payroll packs for
    # major African and Global South economies, the segment the
    # roadmap doc specifically called out as underserved by major ERP
    # providers. Bands below are derived from each country's published
    # 2025/2026 statutory bands (monthly, in that country's own
    # currency), converted where the source only gives annual figures.
    # Each is a genuine simplification, not a full statute — flagged
    # honestly in its label the same way the US pack already is, and
    # every one still reduces cleanly to the same gross/net/breakdown
    # shape as every other pack, so nothing downstream needs to change.
    "NG": {
        "label": "Nigeria (Nigeria Tax Act 2025, effective Jan 2026 — simplified estimate)", "currency": "NGN",
        "income_tax": {"name": "PAYE (Personal Income Tax)", "bands_monthly": [
            (66666.67, 0.00, 0), (250000.0, 0.15, 10000.0), (1000000.0, 0.18, 17500.0),
            (2083333.33, 0.21, 47500.0), (4166666.67, 0.23, 89166.67), (None, 0.25, 172500.0),
        ], "bands_weekly": None},
        "levies": [],
        # PenCom pension is statutorily 8% employee / 10% employer of
        # Basic+Housing+Transport, not full gross — modeled here against
        # gross pay as a documented simplification (same basis the ZA/UK
        # packs above use for their own social contributions).
        "social_security": [{"name": "Pension (PenCom)", "employee_rate": 0.08, "employer_rate": 0.10,
                              "ceiling_monthly": None, "ceiling_weekly": None}],
        "supported": True,
    },
    "KE": {
        "label": "Kenya (KRA PAYE 2025/26 — simplified estimate)", "currency": "KES",
        "income_tax": {"name": "PAYE", "bands_monthly": [
            # Kenya's KES 2,400/month personal relief is folded into
            # each band's deduct value below (adds 2,400 to every band
            # uniformly), rather than modeled as a separate relief step.
            (24000.0, 0.10, 2400.0), (32333.0, 0.25, 6000.0), (500000.0, 0.30, 7616.65),
            (800000.0, 0.325, 20116.65), (None, 0.35, 40116.65),
        ], "bands_weekly": None},
        "levies": [{"name": "SHIF (Social Health Insurance Fund)", "rate": 0.0275, "of": "gross"}],
        "social_security": [
            {"name": "NSSF (Tier I & II)", "employee_rate": 0.06, "employer_rate": 0.06,
             "ceiling_monthly": 72000.0, "ceiling_weekly": None},
            {"name": "Affordable Housing Levy", "employee_rate": 0.015, "employer_rate": 0.015,
             "ceiling_monthly": None, "ceiling_weekly": None},
        ],
        "supported": True,
    },
    "GH": {
        "label": "Ghana (GRA PAYE 2025/26 — simplified estimate)", "currency": "GHS",
        "income_tax": {"name": "PAYE", "bands_monthly": [
            (490.0, 0.00, 0), (600.0, 0.05, 24.5), (730.0, 0.10, 54.5),
            (3896.67, 0.175, 109.25), (19896.67, 0.25, 401.5), (50416.67, 0.30, 1396.33), (None, 0.35, 3917.17),
        ], "bands_weekly": None},
        "levies": [],
        "social_security": [{"name": "SSNIT (Tier 1)", "employee_rate": 0.055, "employer_rate": 0.13,
                              "ceiling_monthly": 61000.0, "ceiling_weekly": None}],
        "supported": True,
    },
    "IN": {
        "label": "India (new tax regime, single-taxpayer FY 2025-26 — simplified estimate; "
                 "Section 87A rebate for total income up to Rs.12L not modeled)", "currency": "INR",
        "income_tax": {"name": "Income Tax (TDS)", "bands_monthly": [
            (33333.33, 0.00, 0), (66666.67, 0.05, 1666.67), (100000.0, 0.10, 5000.0),
            (133333.33, 0.15, 10000.0), (166666.67, 0.20, 16666.67), (200000.0, 0.25, 25000.0), (None, 0.30, 35000.0),
        ], "bands_weekly": None},
        "levies": [{"name": "Health & Education Cess", "rate": 0.04, "of": "tax"}],
        # EPF wage ceiling is statutorily Rs.15,000/month for the
        # mandatory scheme; many employers apply it to full basic above
        # that ceiling voluntarily, which this simplified pack does not
        # attempt to distinguish.
        "social_security": [{"name": "EPF (Employees' Provident Fund)", "employee_rate": 0.12, "employer_rate": 0.12,
                              "ceiling_monthly": 15000.0, "ceiling_weekly": None}],
        "supported": True,
    },
}

GENERIC_NO_STATUTORY_PACK = {
    "label": "Unrecognized country — statutory rules not yet configured",
    "currency": None, "income_tax": {"name": "Income Tax", "bands_monthly": [(None, 0.0, 0)], "bands_weekly": None},
    "levies": [], "social_security": [], "supported": False,
}


def get_tax_pack(country_code: str) -> dict:
    return TAX_PACKS.get((country_code or "").upper(), GENERIC_NO_STATUTORY_PACK)


def calc_payroll_deductions(gross: float, country_code: str = "ZW", pay_frequency: str = "monthly") -> dict:
    """Generic replacement for calc_zimbabwe_paye that works for any
    country with a registered pack. Returns the same legacy keys
    (paye/aids_levy/nssa_employee/nssa_employer) so existing dashboards
    and the ErpPayslip columns keep working unmodified — legacy fields
    map to "the income tax", "the first levy", and "the first social
    security line's employee/employer shares" respectively, whatever
    that country actually calls them. The full accurate picture (with
    real names, for countries whose statute doesn't reduce cleanly to
    those four buckets) is in "breakdown" and "supported"."""
    gross = max(float(gross or 0), 0.0)
    weekly = (pay_frequency == "weekly")
    pack = get_tax_pack(country_code)

    bands = (pack["income_tax"]["bands_weekly"] if weekly else pack["income_tax"]["bands_monthly"]) \
        or pack["income_tax"]["bands_monthly"]
    tax = 0.0
    for upper, rate, deduct in bands:
        if upper is None or gross <= upper:
            tax = max(gross * rate - deduct, 0.0)
            break
    tax = round(tax, 2)

    breakdown = [{"name": pack["income_tax"]["name"], "employee_amount": tax, "employer_amount": 0.0}]
    levy_total = 0.0
    for levy in pack["levies"]:
        amt = round((tax if levy["of"] == "tax" else gross) * levy["rate"], 2)
        breakdown.append({"name": levy["name"], "employee_amount": amt, "employer_amount": 0.0})
        levy_total += amt

    ss_employee_total = 0.0
    ss_employer_total = 0.0
    for ss in pack["social_security"]:
        ceiling = (ss.get("ceiling_weekly") if weekly else ss.get("ceiling_monthly"))
        insurable = min(gross, ceiling) if ceiling else gross
        emp_amt = round(insurable * ss["employee_rate"], 2)
        er_amt = round(insurable * ss["employer_rate"], 2)
        breakdown.append({"name": ss["name"], "employee_amount": emp_amt, "employer_amount": er_amt})
        ss_employee_total += emp_amt
        ss_employer_total += er_amt

    total_deductions = round(tax + levy_total + ss_employee_total, 2)
    net = round(gross - total_deductions, 2)

    first_levy = breakdown[1]["employee_amount"] if pack["levies"] else 0.0
    first_ss = next((b for b in breakdown[len(pack["levies"]) + 1:]), None)

    return {
        "gross": round(gross, 2), "net": net, "total_deductions": total_deductions,
        "country_code": (country_code or "").upper(), "pack_label": pack["label"],
        "supported": pack["supported"], "breakdown": breakdown,
        # legacy-compatible fields — keep old code paths (reports, CSV
        # exports, the payslip columns) working with zero changes:
        "paye": tax, "aids_levy": first_levy,
        "nssa_employee": first_ss["employee_amount"] if first_ss else 0.0,
        "nssa_employer": first_ss["employer_amount"] if first_ss else 0.0,
    }


@app.route("/api/account/country", methods=["GET"])
def account_country_get():
    user, err = _erp_user_or_401()
    if err: return err
    pack = get_tax_pack(user.get("country_code") or "ZW")
    return jsonify({
        "country_code": user.get("country_code") or "ZW",
        "pack_label": pack["label"], "currency": pack["currency"], "supported": pack["supported"],
        "available_packs": {code: p["label"] for code, p in TAX_PACKS.items()},
    }), 200


@app.route("/api/account/country", methods=["PATCH"])
@csrf.exempt
def account_country_set():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    code = (data.get("country_code") or "").strip().upper()
    if not code or len(code) > 4:
        return jsonify({"error": "A valid country_code is required (e.g. US, GB, ZA, ZW)."}), 400
    try:
        acct = UserAccount.query.get(user["id"])
        if not acct: return jsonify({"error": "Account not found."}), 404
        acct.country_code = code
        db.session.commit()
        # keep the in-memory/session cache in step with the DB so the next
        # request (e.g. running payroll) picks up the new country immediately
        user["country_code"] = code
    except Exception as e:
        db.session.rollback(); logging.error(f"[ACCOUNT COUNTRY SET] {e}")
        return jsonify({"error": "Could not update country."}), 500
    pack = get_tax_pack(code)
    return jsonify({"country_code": code, "pack_label": pack["label"],
                     "currency": pack["currency"], "supported": pack["supported"]}), 200


def calc_zimbabwe_paye(gross: float, pay_frequency: str = "monthly") -> dict:
    """Compute Zimbabwe PAYE + AIDS levy + NSSA for one pay period.
    Returns a dict with gross/paye/aids_levy/nssa_employee/nssa_employer/
    total_deductions/net. total_deductions only includes amounts actually
    withheld from the employee (PAYE + AIDS levy + their NSSA share) —
    nssa_employer is the business's own matching cost, tracked separately."""
    gross = max(float(gross or 0), 0.0)
    weekly = (pay_frequency == "weekly")
    bands = ZW_PAYE_BANDS_WEEKLY if weekly else ZW_PAYE_BANDS_MONTHLY
    nssa_ceiling = ZW_NSSA_CEILING_WEEKLY if weekly else ZW_NSSA_CEILING_MONTHLY

    paye = 0.0
    for upper, rate, deduct in bands:
        if upper is None or gross <= upper:
            paye = max(gross * rate - deduct, 0.0)
            break
    paye = round(paye, 2)
    aids_levy = round(paye * ZW_AIDS_LEVY_RATE, 2)

    insurable = min(gross, nssa_ceiling)
    nssa_employee = round(insurable * ZW_NSSA_RATE, 2)
    nssa_employer = round(insurable * ZW_NSSA_RATE, 2)

    total_deductions = round(paye + aids_levy + nssa_employee, 2)
    net = round(gross - total_deductions, 2)
    return {
        "gross": round(gross, 2), "paye": paye, "aids_levy": aids_levy,
        "nssa_employee": nssa_employee, "nssa_employer": nssa_employer,
        "total_deductions": total_deductions, "net": net,
    }


