@app.route("/api/erp/payroll-runs", methods=["POST"])
@csrf.exempt
def erp_payroll_create():
    """Creates a draft payroll run for a period; process it separately
    with /process once reviewed."""
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    start = _erp_parse_date(data.get("period_start"))
    end = _erp_parse_date(data.get("period_end"))
    if not start or not end: return jsonify({"error": "period_start and period_end are required."}), 400
    try:
        run = ErpPayrollRun(owner_user_id=user["id"], period_start=start, period_end=end)
        db.session.add(run); db.session.commit()
    except Exception as e:
        db.session.rollback(); logging.error(f"[ERP PAYROLL CREATE] {e}")
        return jsonify({"error": "Could not create payroll run."}), 500
    return jsonify({"payroll_run": run.to_dict()}), 201


@app.route("/api/erp/payroll-runs/<int:rid>", methods=["GET"])
def erp_payroll_get(rid):
    user, err = _erp_user_or_401()
    if err: return err
    run = ErpPayrollRun.query.get(rid)
    if not run or run.owner_user_id != user["id"]: return jsonify({"error": "Payroll run not found."}), 404
    return jsonify({"payroll_run": run.to_dict(include_payslips=True)}), 200


@app.route("/api/erp/payroll-runs/<int:rid>/process", methods=["POST"])
@csrf.exempt
def erp_payroll_process(rid):
    """Generates one payslip per active employee at their configured
    salary. Employees with statutory_deductions on (the default) get real
    Zimbabwe PAYE + AIDS levy + NSSA deductions via calc_zimbabwe_paye;
    others fall back to gross = net (contractors, non-Zimbabwe staff,
    etc). Posts two payroll ledger entries: net cash paid to staff, and
    the statutory amount owed to ZIMRA/NSSA (including the employer's own
    NSSA contribution, which is an additional cost, not a deduction)."""
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    blocked = require_plan(user, "payroll")
    if blocked: return blocked
    run = ErpPayrollRun.query.get(rid)
    if not run or run.owner_user_id != user["id"]: return jsonify({"error": "Payroll run not found."}), 404
    if run.status == "processed": return jsonify({"error": "Already processed."}), 400
    try:
        employees = ErpEmployee.query.filter_by(owner_user_id=user["id"], status="active").all()
        total_gross = 0.0
        total_net = 0.0
        total_statutory = 0.0
        for emp in employees:
            gross = float(emp.salary or 0)
            if gross <= 0: continue
            if emp.statutory_deductions:
                # GLOBAL-01: pick the tax pack from the account's own
                # operating country instead of assuming Zimbabwe.
                calc = calc_payroll_deductions(gross, user.get("country_code") or "ZW", emp.pay_frequency or "monthly")
                slip = ErpPayslip(
                    payroll_run_id=run.id, employee_id=emp.id, gross=calc["gross"],
                    deductions=calc["total_deductions"], net=calc["net"],
                    paye=calc["paye"], aids_levy=calc["aids_levy"],
                    nssa_employee=calc["nssa_employee"], nssa_employer=calc["nssa_employer"],
                    statutory_breakdown=json.dumps(calc["breakdown"]),
                )
                total_statutory += calc["paye"] + calc["aids_levy"] + calc["nssa_employee"] + calc["nssa_employer"]
                total_net += calc["net"]
            else:
                slip = ErpPayslip(payroll_run_id=run.id, employee_id=emp.id, gross=gross, deductions=0, net=gross)
                total_net += gross
            db.session.add(slip)
            total_gross += gross
        run.total_gross = round(total_gross, 2)
        run.total_net = round(total_net, 2)
        run.total_statutory = round(total_statutory, 2)
        run.status = "processed"; run.processed_at = datetime.utcnow()
        _erp_post_ledger(user["id"], run.period_end, "payroll", "Wages",
                          f"Net pay {run.period_start.isoformat()} to {run.period_end.isoformat()}",
                          -abs(total_net), "payroll", run.id)
        if total_statutory > 0:
            _erp_post_ledger(user["id"], run.period_end, "payroll", "Statutory Payroll (PAYE/AIDS/NSSA)",
                              f"PAYE + AIDS levy + NSSA (incl. employer match) {run.period_start.isoformat()} to {run.period_end.isoformat()}",
                              -abs(total_statutory), "payroll", run.id)
        db.session.commit()
    except Exception as e:
        db.session.rollback(); logging.error(f"[ERP PAYROLL PROCESS] {e}")
        return jsonify({"error": "Could not process payroll."}), 500
    return jsonify({"payroll_run": run.to_dict(include_payslips=True)}), 200


# ════════════════════════════════════════════════════════════
# STAGE 455: EXTERNAL PAYROLL PROVIDER SYNC (Gusto / ADP Workforce Now /
# Deel). Read-only pull of payslips a business already ran through one
# of these licensed payroll processors — this platform never initiates
# or moves any of that pay itself, it only mirrors what already
# happened. Gated to paid plans (subscription), same as every other
# revenue-generating integration on this platform.
# ════════════════════════════════════════════════════════════

def _require_paid_plan(user, feature_label: str):
    """Subscription gate for premium (non-AI-metered) integrations. Free
    plan gets a clear 402 pointing at checkout; pro/business/enterprise
    proceed. Call as the first line of a gated route and `return` the
    result immediately if it isn't None."""
    plan = (user.get("plan") or "free").lower()
    if plan == "free":
        return jsonify({
            "error": f"{feature_label} is available on paid plans.",
            "upgrade_url": "/api/billing/checkout",
        }), 402
    return None


def _parse_iso_date(s):
    if not s:
        return None
    try:
        return datetime.fromisoformat(str(s)[:10]).date()
    except Exception:
        return None


def _sync_gusto_payslips(user_id, creds: dict) -> list:
    """Gusto Payroll API v1 — GET /v1/companies/{company_id}/payrolls
    (processed=true) then each payroll's payslip line items. Uses the
    business's own OAuth access_token; refresh_token/client_id/
    client_secret are stored for when a caller wires up token refresh,
    not used on the happy path below."""
    company_id = creds.get("company_id")
    token = creds.get("access_token")
    if not company_id or not token:
        raise ValueError("Missing company_id or access_token for Gusto.")
    resp = requests.get(
        f"https://api.gusto.com/v1/companies/{company_id}/payrolls",
        headers={"Authorization": f"Bearer {token}"},
        params={"processed": "true", "per": 50},
        timeout=20,
    )
    resp.raise_for_status()
    out = []
    for run in resp.json() or []:
        for slip in (run.get("employee_compensations") or []):
            out.append({
                "provider_payslip_id": str(slip.get("employee_uuid", "")) + ":" + str(run.get("payroll_uuid", "")),
                "employee_name": slip.get("employee_name") or slip.get("employee_uuid"),
                "employee_external_id": slip.get("employee_uuid"),
                "period_start": _parse_iso_date(run.get("pay_period", {}).get("start_date")),
                "period_end": _parse_iso_date(run.get("pay_period", {}).get("end_date")),
                "pay_date": _parse_iso_date(run.get("check_date")),
                "gross_pay": float(slip.get("gross_pay") or 0),
                "net_pay": float(slip.get("net_pay") or 0),
                "currency": "USD",
                "raw": slip,
            })
    return out


def _sync_adp_payslips(user_id, creds: dict) -> list:
    """ADP Workforce Now — client-credentials OAuth2 PLUS mutual TLS: the
    cert pair is presented on every call, not just a bearer token. The
    business's PEM cert/key are written to short-lived temp files for
    `requests`' cert=(certfile, keyfile) argument, then removed."""
    client_id = creds.get("client_id"); client_secret = creds.get("client_secret")
    cert_pem = creds.get("ssl_cert_pem"); key_pem = creds.get("ssl_key_pem")
    org_oid = creds.get("organization_oid")
    if not all([client_id, client_secret, cert_pem, key_pem, org_oid]):
        raise ValueError("Missing client_id/client_secret/ssl_cert_pem/ssl_key_pem/organization_oid for ADP.")
    with tempfile.NamedTemporaryFile(mode="w", suffix=".pem", delete=False) as cf, \
         tempfile.NamedTemporaryFile(mode="w", suffix=".pem", delete=False) as kf:
        cf.write(cert_pem); kf.write(key_pem)
        cert_path, key_path = cf.name, kf.name
    try:
        token_resp = requests.post(
            "https://accounts.adp.com/auth/oauth/v2/token",
            data={"grant_type": "client_credentials", "client_id": client_id, "client_secret": client_secret},
            cert=(cert_path, key_path), timeout=20,
        )
        token_resp.raise_for_status()
        access_token = token_resp.json().get("access_token")
        resp = requests.get(
            "https://api.adp.com/payroll/v1/workers/payroll-output",
            headers={"Authorization": f"Bearer {access_token}"},
            params={"organizationOID": org_oid},
            cert=(cert_path, key_path), timeout=20,
        )
        resp.raise_for_status()
        out = []
        for item in (resp.json() or {}).get("payrollOutputs", []):
            out.append({
                "provider_payslip_id": str(item.get("itemID", "")),
                "employee_name": ((item.get("worker") or {}).get("displayName")),
                "employee_external_id": (item.get("worker") or {}).get("associateOID"),
                "period_start": _parse_iso_date((item.get("payPeriod") or {}).get("startDate")),
                "period_end": _parse_iso_date((item.get("payPeriod") or {}).get("endDate")),
                "pay_date": _parse_iso_date(item.get("checkDate")),
                "gross_pay": float((item.get("grossPay") or {}).get("amountValue") or 0),
                "net_pay": float((item.get("netPay") or {}).get("amountValue") or 0),
                "currency": (item.get("grossPay") or {}).get("currencyCode", "USD"),
                "raw": item,
            })
        return out
    finally:
        for p in (cert_path, key_path):
            try:
                os.remove(p)
            except Exception:
                pass


def _sync_deel_payslips(user_id, creds: dict) -> list:
    """Deel — simple Bearer API token, GET /rest/v2/payslips scoped to
    the business's own org_id."""
    token = creds.get("api_token"); org_id = creds.get("org_id")
    if not token:
        raise ValueError("Missing api_token for Deel.")
    resp = requests.get(
        "https://api.deel.com/rest/v2/payslips",
        headers={"Authorization": f"Bearer {token}"},
        params={"org_id": org_id} if org_id else {},
        timeout=20,
    )
    resp.raise_for_status()
    out = []
    for slip in (resp.json() or {}).get("data", []):
        out.append({
            "provider_payslip_id": str(slip.get("id", "")),
            "employee_name": (slip.get("contract") or {}).get("worker_name") or slip.get("full_name"),
            "employee_external_id": str((slip.get("contract") or {}).get("id", "")) or None,
            "period_start": _parse_iso_date(slip.get("payment_period_start") or slip.get("start_date")),
            "period_end": _parse_iso_date(slip.get("payment_period_end") or slip.get("end_date")),
            "pay_date": _parse_iso_date(slip.get("payment_date") or slip.get("paid_at")),
            "gross_pay": float(slip.get("gross_amount") or slip.get("total") or 0),
            "net_pay": float(slip.get("net_amount") or slip.get("total_net") or 0),
            "currency": slip.get("currency", "USD"),
            "raw": slip,
        })
    return out


_EXTERNAL_PAYROLL_SYNC_FUNCS = {
    "gusto": _sync_gusto_payslips,
    "adp_workforce_now": _sync_adp_payslips,
    "deel": _sync_deel_payslips,
}


@app.route("/api/payroll/external/sync", methods=["POST"])
@csrf.exempt
def payroll_external_sync():
    """Pull payslips from a connected provider (Gusto/ADP/Deel) and
    upsert them read-only into external_payslips. Requires that provider's
    credentials already be saved via /api/integrations/keys."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    gate = _require_paid_plan(user, "External payroll sync")
    if gate:
        return gate

    data = request.get_json(force=True, silent=True) or {}
    provider = (data.get("provider") or "").strip().lower()
    sync_func = _EXTERNAL_PAYROLL_SYNC_FUNCS.get(provider)
    if not sync_func:
        return jsonify({"error": f"Unsupported provider. Choose one of: {', '.join(_EXTERNAL_PAYROLL_SYNC_FUNCS)}"}), 400

    creds = get_user_credentials(user["id"], provider)
    if not creds:
        return jsonify({"error": f"Connect your {provider} account first (Save credentials at /api/integrations/keys)."}), 400

    try:
        slips = sync_func(user["id"], creds)
    except requests.exceptions.RequestException as e:
        logging.error(f"[EXTERNAL PAYROLL SYNC] provider={provider} user={user['id']}: {e}")
        return jsonify({"error": f"Could not reach {provider}. Check your credentials and try again."}), 502
    except ValueError as e:
        return jsonify({"error": str(e)}), 400
    except Exception as e:
        logging.error(f"[EXTERNAL PAYROLL SYNC] provider={provider} user={user['id']}: {e}")
        return jsonify({"error": "Sync failed."}), 500

    synced = 0
    try:
        for s in slips:
            row = ExternalPayslip.query.filter_by(
                user_id=user["id"], provider=provider, provider_payslip_id=s["provider_payslip_id"]
            ).first()
            if not row:
                row = ExternalPayslip(user_id=user["id"], provider=provider,
                                       provider_payslip_id=s["provider_payslip_id"])
                db.session.add(row)
            row.employee_name = s.get("employee_name")
            row.employee_external_id = s.get("employee_external_id")
            row.period_start = s.get("period_start")
            row.period_end = s.get("period_end")
            row.pay_date = s.get("pay_date")
            row.gross_pay = s.get("gross_pay")
            row.net_pay = s.get("net_pay")
            row.currency = s.get("currency") or "USD"
            row.raw_json = json.dumps(s.get("raw"))[:20000]
            row.synced_at = datetime.utcnow()
            synced += 1
        db.session.commit()
    except Exception as e:
        db.session.rollback(); logging.error(f"[EXTERNAL PAYROLL SYNC SAVE] {e}")
        return jsonify({"error": "Fetched from provider but could not save locally."}), 500

    return jsonify({"ok": True, "provider": provider, "synced": synced}), 200


@app.route("/api/payroll/external/payslips", methods=["GET"])
def payroll_external_list():
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    gate = _require_paid_plan(user, "External payroll sync")
    if gate:
        return gate
    q = ExternalPayslip.query.filter_by(user_id=user["id"])
    provider = request.args.get("provider")
    if provider:
        q = q.filter_by(provider=provider)
    rows = q.order_by(ExternalPayslip.pay_date.desc().nullslast(), ExternalPayslip.synced_at.desc()).limit(200).all()
    return jsonify({"payslips": [r.to_dict() for r in rows]}), 200


@app.route("/api/payroll/external/payslips/<int:pid>", methods=["GET"])
def payroll_external_detail(pid):
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    gate = _require_paid_plan(user, "External payroll sync")
    if gate:
        return gate
    row = ExternalPayslip.query.filter_by(id=pid, user_id=user["id"]).first()
    if not row:
        return jsonify({"error": "Not found."}), 404
    return jsonify({"payslip": row.to_dict(include_raw=True)}), 200


# ── DASHBOARD ───────────────────────────────────────────────
@app.route("/api/erp/dashboard", methods=["GET"])
def erp_dashboard():
    user, err = _erp_user_or_401()
    if err: return err
    uid = user["id"]
    today = datetime.utcnow().date()
    month_start = today.replace(day=1)
    unpaid_invoices = ErpInvoice.query.filter_by(owner_user_id=uid).filter(ErpInvoice.status.in_(["sent", "overdue", "draft"])).all()
    products = InventoryItem.query.filter_by(user_id=uid).all()
    low_stock = [p for p in products if (p.quantity or 0) <= (p.threshold or 0)]
    month_rows = (ErpLedgerEntry.query.filter_by(owner_user_id=uid)
                  .filter(ErpLedgerEntry.entry_date >= month_start, ErpLedgerEntry.entry_date <= today).all())
    revenue_mtd = sum(r.amount for r in month_rows if r.amount > 0)
    expenses_mtd = sum(-r.amount for r in month_rows if r.amount < 0)
    upcoming_payroll = (ErpPayrollRun.query.filter_by(owner_user_id=uid, status="draft")
                         .order_by(ErpPayrollRun.period_end.asc()).first())
    return jsonify({
        "customers": ErpCustomer.query.filter_by(owner_user_id=uid, active=True).count(),
        "products": len(products),
        "low_stock_count": len(low_stock),
        "low_stock_items": [p.to_dict() for p in low_stock[:10]],
        "outstanding_invoice_count": len(unpaid_invoices),
        "outstanding_invoice_total": round(sum((i.total - i.amount_paid) for i in unpaid_invoices), 2),
        "revenue_mtd": round(revenue_mtd, 2),
        "expenses_mtd": round(expenses_mtd, 2),
        "net_profit_mtd": round(revenue_mtd - expenses_mtd, 2),
        "employees_active": ErpEmployee.query.filter_by(owner_user_id=uid, status="active").count(),
        "upcoming_payroll": upcoming_payroll.to_dict() if upcoming_payroll else None,
    }), 200


# ════════════════════════════════════════════════════════════
# GLOBAL-02: CASH-FLOW FORECASTING & EARLY-WARNING SYSTEM
# The most requested thing small businesses everywhere say they wish
# they'd known sooner: "we're about to run short of cash." This is
# built entirely from data the ERP already has — no new integration,
# works in any currency/country:
#   • baseline daily burn/gain rate from the last 90 days of the ledger
#     (the same ErpLedgerEntry rows the P&L already sums)
#   • known future inflows — outstanding invoice balances, expected on
#     their due_date
#   • known future outflows — outstanding purchase orders (expected_date)
#     and the next draft payroll run (period_end)
#   • running cash position is approximated as the lifetime sum of the
#     ledger to date, since that ledger already nets every inflow/
#     outflow the business has recorded — this is an approximation
#     (it assumes the ledger started at zero cash), which the response
#     says explicitly rather than presenting it as bank-verified.
# Projected day-by-day balance flags the first date it would go
# negative, so the alert arrives weeks before the shortfall, not after.
@app.route("/api/erp/cashflow/forecast", methods=["GET"])
def erp_cashflow_forecast():
    user, err = _erp_user_or_401()
    if err: return err
    uid = user["id"]
    try:
        horizon_days = max(1, min(int(request.args.get("days", 30)), 180))
    except (TypeError, ValueError):
        horizon_days = 30
    today = datetime.utcnow().date()

    all_entries = ErpLedgerEntry.query.filter_by(owner_user_id=uid).order_by(ErpLedgerEntry.entry_date.asc()).all()
    current_cash_position = round(sum(e.amount for e in all_entries), 2)

    lookback_start = today - timedelta(days=90)
    recent = [e for e in all_entries if e.entry_date and e.entry_date >= lookback_start]
    if recent:
        span_days = max((today - min(e.entry_date for e in recent)).days, 1)
        avg_daily_net = round(sum(e.amount for e in recent) / span_days, 2)
    else:
        avg_daily_net = 0.0

    # Known future inflows: outstanding invoice balances, bucketed to
    # their due_date (undated ones are spread onto "today" so they still
    # show up rather than silently vanishing from the forecast).
    inflows_by_date = defaultdict(float)
    unpaid_invoices = (ErpInvoice.query.filter_by(owner_user_id=uid)
                        .filter(ErpInvoice.status.in_(["sent", "overdue"])).all())
    for inv in unpaid_invoices:
        bal = round((inv.total or 0) - (inv.amount_paid or 0), 2)
        if bal > 0:
            inflows_by_date[inv.due_date or today] += bal

    # Known future outflows: purchase orders not yet received, plus the
    # next draft payroll run if it falls inside the forecast window.
    outflows_by_date = defaultdict(float)
    open_pos = (ErpPurchaseOrder.query.filter_by(owner_user_id=uid)
                .filter(ErpPurchaseOrder.status.in_(["draft", "ordered"])).all())
    for po in open_pos:
        outflows_by_date[po.expected_date or today] += (po.total or 0)

    draft_payroll = (ErpPayrollRun.query.filter_by(owner_user_id=uid, status="draft")
                      .order_by(ErpPayrollRun.period_end.asc()).first())
    if draft_payroll and draft_payroll.period_end:
        est = draft_payroll.total_net or sum(
            float(e.salary or 0) for e in ErpEmployee.query.filter_by(owner_user_id=uid, status="active").all())
        outflows_by_date[draft_payroll.period_end] += est

    series = []
    running = current_cash_position
    crunch_date = None
    for i in range(horizon_days + 1):
        d = today + timedelta(days=i)
        day_known = inflows_by_date.get(d, 0.0) - outflows_by_date.get(d, 0.0)
        # day 0 is "today" — don't also apply the baseline run-rate to it,
        # since current_cash_position already reflects everything through today
        if i > 0:
            running = round(running + avg_daily_net + day_known, 2)
        else:
            running = round(running + day_known, 2)
        if running < 0 and crunch_date is None:
            crunch_date = d.isoformat()
        series.append({"date": d.isoformat(), "projected_balance": running,
                        "known_inflow": round(inflows_by_date.get(d, 0.0), 2),
                        "known_outflow": round(outflows_by_date.get(d, 0.0), 2)})

    return jsonify({
        "current_cash_position": current_cash_position,
        "current_cash_position_note": "Approximated as the lifetime sum of ledger entries, not a reconciled bank balance — use Bank Statement Reconciliation for a verified figure.",
        "avg_daily_net_last_90d": avg_daily_net,
        "horizon_days": horizon_days,
        "series": series,
        "cash_crunch_alert": ({"date": crunch_date, "message": f"Projected cash position goes negative on {crunch_date} at current trends."} if crunch_date else None),
    }), 200


# ════════════════════════════════════════════════════════════
# NEXT-01: SCENARIO SIMULATOR
# Reuses the exact baseline (current cash position + 90-day run-rate +
# known dated inflows/outflows) that /api/erp/cashflow/forecast already
# computes from real ErpLedgerEntry/ErpInvoice/ErpPurchaseOrder data,
# then replays it with one or more hypothetical "moves" layered on top
# — entirely in memory, nothing is written to the database. This is
# what turns the forecast from something you look at into something
# you can test a decision against before making it.
# ════════════════════════════════════════════════════════════

def _erp_gather_forecast_baseline(uid):
    """Returns (current_cash_position, avg_daily_net, inflows_by_date,
    outflows_by_date) — the same inputs erp_cashflow_forecast uses,
    factored out so the simulator can perturb them without touching
    that endpoint's own code path."""
    today = datetime.utcnow().date()
    all_entries = ErpLedgerEntry.query.filter_by(owner_user_id=uid).order_by(ErpLedgerEntry.entry_date.asc()).all()
    current_cash_position = round(sum(e.amount for e in all_entries), 2)

    lookback_start = today - timedelta(days=90)
    recent = [e for e in all_entries if e.entry_date and e.entry_date >= lookback_start]
    if recent:
        span_days = max((today - min(e.entry_date for e in recent)).days, 1)
        avg_daily_net = round(sum(e.amount for e in recent) / span_days, 2)
    else:
        avg_daily_net = 0.0

    inflows_by_date = defaultdict(float)
    unpaid_invoices = (ErpInvoice.query.filter_by(owner_user_id=uid)
                        .filter(ErpInvoice.status.in_(["sent", "overdue"])).all())
    for inv in unpaid_invoices:
        bal = round((inv.total or 0) - (inv.amount_paid or 0), 2)
        if bal > 0:
            inflows_by_date[inv.due_date or today] += bal

    outflows_by_date = defaultdict(float)
    open_pos = (ErpPurchaseOrder.query.filter_by(owner_user_id=uid)
                .filter(ErpPurchaseOrder.status.in_(["draft", "ordered"])).all())
    for po in open_pos:
        outflows_by_date[po.expected_date or today] += (po.total or 0)

    draft_payroll = (ErpPayrollRun.query.filter_by(owner_user_id=uid, status="draft")
                      .order_by(ErpPayrollRun.period_end.asc()).first())
    if draft_payroll and draft_payroll.period_end:
        est = draft_payroll.total_net or sum(
            float(e.salary or 0) for e in ErpEmployee.query.filter_by(owner_user_id=uid, status="active").all())
        outflows_by_date[draft_payroll.period_end] += est

    return current_cash_position, avg_daily_net, inflows_by_date, outflows_by_date, unpaid_invoices


def _erp_run_forecast_series(current_cash_position, avg_daily_net, inflows_by_date, outflows_by_date, horizon_days):
    """Pure projection loop, identical math to erp_cashflow_forecast's
    own series builder — shared so baseline and scenario runs can never
    silently drift apart."""
    today = datetime.utcnow().date()
    series = []
    running = current_cash_position
    crunch_date = None
    lowest_point = running
    for i in range(horizon_days + 1):
        d = today + timedelta(days=i)
        day_known = inflows_by_date.get(d, 0.0) - outflows_by_date.get(d, 0.0)
        if i > 0:
            running = round(running + avg_daily_net + day_known, 2)
        else:
            running = round(running + day_known, 2)
        if running < lowest_point:
            lowest_point = running
        if running < 0 and crunch_date is None:
            crunch_date = d.isoformat()
        series.append({"date": d.isoformat(), "projected_balance": running})
    return series, crunch_date, round(lowest_point, 2)


SCENARIO_MOVE_TYPES = {
    "hire_staff", "one_off_expense", "recurring_expense", "factoring_advance",
    "delay_customer_payment", "one_off_inflow", "revenue_change_pct", "new_loan",
}


def _erp_apply_scenario_move(move, current_cash_position, avg_daily_net, inflows_by_date, outflows_by_date,
                              unpaid_invoices, today, horizon_days):
    """Mutates the passed-in copies of the forecast inputs to reflect one
    hypothetical move. Returns a short human-readable description of what
    it did, for the response's move log."""
    mtype = move.get("type")
    label = ""

    if mtype == "hire_staff":
        monthly_salary = float(move.get("monthly_salary", 0) or 0)
        start_offset_days = int(move.get("start_in_days", 0) or 0)
        daily_cost = monthly_salary / 30.4
        start_date = today + timedelta(days=start_offset_days)
        days_active = max(horizon_days - start_offset_days + 1, 0)
        for i in range(days_active):
            outflows_by_date[start_date + timedelta(days=i)] += daily_cost
        label = f"Hire staff at ${monthly_salary:,.0f}/month starting in {start_offset_days} day(s)"

    elif mtype == "one_off_expense":
        amount = float(move.get("amount", 0) or 0)
        offset = int(move.get("in_days", 0) or 0)
        outflows_by_date[today + timedelta(days=offset)] += amount
        label = f"One-off expense of ${amount:,.0f} in {offset} day(s)"

    elif mtype == "recurring_expense":
        monthly_amount = float(move.get("monthly_amount", 0) or 0)
        start_offset_days = int(move.get("start_in_days", 0) or 0)
        daily_cost = monthly_amount / 30.4
        days_active = max(horizon_days - start_offset_days + 1, 0)
        for i in range(days_active):
            outflows_by_date[today + timedelta(days=start_offset_days + i)] += daily_cost
        label = f"New recurring expense of ${monthly_amount:,.0f}/month starting in {start_offset_days} day(s)"

    elif mtype == "factoring_advance":
        invoice_id = move.get("invoice_id")
        advance_rate = float(move.get("advance_rate", 0.85) or 0.85)
        inv = next((i for i in unpaid_invoices if i.id == invoice_id), None)
        if inv:
            bal = round((inv.total or 0) - (inv.amount_paid or 0), 2)
            advance_amount = round(bal * advance_rate, 2)
            due = inv.due_date or today
            inflows_by_date[due] = max(0.0, inflows_by_date.get(due, 0.0) - bal)  # buyer collects it now, not you
            current_cash_position = round(current_cash_position + advance_amount, 2)
            label = f"Factor invoice #{invoice_id} (${bal:,.0f} face) at {advance_rate:.0%} advance — +${advance_amount:,.0f} today"
        else:
            label = f"Factoring advance requested for invoice #{invoice_id}, but that invoice wasn't found in your open receivables — ignored."

    elif mtype == "delay_customer_payment":
        invoice_id = move.get("invoice_id")
        delay_days = int(move.get("delay_days", 0) or 0)
        inv = next((i for i in unpaid_invoices if i.id == invoice_id), None)
        if inv:
            bal = round((inv.total or 0) - (inv.amount_paid or 0), 2)
            old_due = inv.due_date or today
            new_due = old_due + timedelta(days=delay_days)
            inflows_by_date[old_due] = max(0.0, inflows_by_date.get(old_due, 0.0) - bal)
            inflows_by_date[new_due] += bal
            label = f"Invoice #{invoice_id} (${bal:,.0f}) pays {delay_days} day(s) late — now expected {new_due.isoformat()}"
        else:
            label = f"Late-payment scenario requested for invoice #{invoice_id}, but it wasn't found — ignored."

    elif mtype == "one_off_inflow":
        amount = float(move.get("amount", 0) or 0)
        offset = int(move.get("in_days", 0) or 0)
        inflows_by_date[today + timedelta(days=offset)] += amount
        label = f"One-off inflow of ${amount:,.0f} in {offset} day(s)"

    elif mtype == "revenue_change_pct":
        pct = float(move.get("pct", 0) or 0)
        avg_daily_net = round(avg_daily_net + avg_daily_net * (pct / 100.0), 2) if avg_daily_net > 0 else avg_daily_net
        label = f"Revenue run-rate {'+' if pct >= 0 else ''}{pct:.0f}%"

    elif mtype == "new_loan":
        principal = float(move.get("principal", 0) or 0)
        monthly_repayment = float(move.get("monthly_repayment", 0) or 0)
        current_cash_position = round(current_cash_position + principal, 2)
        daily_repayment = monthly_repayment / 30.4
        for i in range(horizon_days + 1):
            outflows_by_date[today + timedelta(days=i)] += daily_repayment
        label = f"Take a loan of ${principal:,.0f}, repaying ${monthly_repayment:,.0f}/month"

    else:
        label = f"Unrecognized move type '{mtype}' — ignored."

    return current_cash_position, avg_daily_net, label


@app.route("/api/erp/scenario-simulator", methods=["POST"])
def erp_scenario_simulator():
    """Body: {"moves": [{"type": "hire_staff", "monthly_salary": 800, "start_in_days": 14}, ...],
              "days": 90}
    Returns baseline vs scenario projected cash-flow series plus headline
    deltas, so a business owner can see the actual consequence of a
    decision on their real numbers before making it. Supports stacking
    multiple moves (e.g. "hire 2 staff AND take a factoring advance")."""
    user, err = _erp_user_or_401()
    if err: return err
    uid = user["id"]
    data = request.get_json(silent=True) or {}
    moves = data.get("moves")
    if not isinstance(moves, list) or not moves:
        return jsonify({"error": "moves must be a non-empty array of scenario moves."}), 400
    if len(moves) > 20:
        return jsonify({"error": "Too many moves — send at most 20 per simulation."}), 400
    try:
        horizon_days = max(1, min(int(data.get("days", 90)), 365))
    except (TypeError, ValueError):
        horizon_days = 90

    today = datetime.utcnow().date()
    base_cash, base_avg, base_inflows, base_outflows, unpaid_invoices = _erp_gather_forecast_baseline(uid)

    baseline_series, baseline_crunch, baseline_low = _erp_run_forecast_series(
        base_cash, base_avg, base_inflows, base_outflows, horizon_days)

    # Deep-copy the dated maps so applying moves never mutates the baseline.
    scenario_cash = base_cash
    scenario_avg = base_avg
    scenario_inflows = defaultdict(float, base_inflows)
    scenario_outflows = defaultdict(float, base_outflows)

    move_log = []
    for move in moves:
        if not isinstance(move, dict):
            continue
        scenario_cash, scenario_avg, label = _erp_apply_scenario_move(
            move, scenario_cash, scenario_avg, scenario_inflows, scenario_outflows,
            unpaid_invoices, today, horizon_days)
        move_log.append({"type": move.get("type"), "description": label})

    scenario_series, scenario_crunch, scenario_low = _erp_run_forecast_series(
        scenario_cash, scenario_avg, scenario_inflows, scenario_outflows, horizon_days)

    baseline_end = baseline_series[-1]["projected_balance"] if baseline_series else base_cash
    scenario_end = scenario_series[-1]["projected_balance"] if scenario_series else scenario_cash

    verdict = "safe"
    if scenario_crunch and not baseline_crunch:
        verdict = "creates_a_cash_crunch"
    elif scenario_crunch and baseline_crunch and scenario_crunch < baseline_crunch:
        verdict = "brings_the_crunch_forward"
    elif scenario_low < baseline_low - 0.01:
        verdict = "tighter_but_no_crunch"
    elif scenario_end > baseline_end + 0.01:
        verdict = "improves_position"

    return jsonify({
        "horizon_days": horizon_days,
        "moves_applied": move_log,
        "baseline": {
            "series": baseline_series,
            "ending_balance": baseline_end,
            "lowest_point": baseline_low,
            "cash_crunch_date": baseline_crunch,
        },
        "scenario": {
            "series": scenario_series,
            "ending_balance": scenario_end,
            "lowest_point": scenario_low,
            "cash_crunch_date": scenario_crunch,
        },
        "impact": {
            "ending_balance_delta": round(scenario_end - baseline_end, 2),
            "lowest_point_delta": round(scenario_low - baseline_low, 2),
            "verdict": verdict,
        },
    }), 200


# ════════════════════════════════════════════════════════════
# GLOBAL-03: OFFLINE-FIRST SYNC — batch push + pull
# Built for spotty-connectivity conditions anywhere in the world, not
# just poor-network regions: a client queues operations locally while
# offline and replays them here in one request once connectivity
# returns. Supports the three actions a business most needs to capture
# in the moment even with no signal: recording an expense, adding a
# customer, and posting a free-form ledger entry (e.g. a cash sale).
# Invoice/payroll creation stay online-only (too many linked side
# effects — invoice items, statutory calculations — to safely replay
# blind); those can wait for connectivity.
SYNC_SUPPORTED_ENTITIES = {"expense", "customer", "ledger_entry"}


def _sync_apply_operation(user_id: int, entity_type: str, payload: dict):
    """Returns (server_id, dict_for_response). Raises ValueError on bad payload."""
    if entity_type == "customer":
        name = (payload.get("name") or "").strip()
        if not name: raise ValueError("name is required.")
        c = ErpCustomer(owner_user_id=user_id, name=name[:200], email=payload.get("email"),
                         phone=payload.get("phone"), address=payload.get("address"), notes=payload.get("notes"))
        db.session.add(c); db.session.flush()
        return c.id, c.to_dict()

    if entity_type == "expense":
        amount = float(payload.get("amount", 0) or 0)
        if amount <= 0: raise ValueError("amount must be greater than zero.")
        exp = ErpExpense(
            owner_user_id=user_id, expense_date=_erp_parse_date(payload.get("expense_date"), datetime.utcnow().date()),
            category=(payload.get("category") or "general")[:80], vendor=payload.get("vendor"),
            amount=amount, currency=payload.get("currency", "USD"), payment_method=payload.get("payment_method"),
            notes=payload.get("notes"),
        )
        db.session.add(exp); db.session.flush()
        _erp_post_ledger(user_id, exp.expense_date, "expense", exp.category,
                          exp.vendor or exp.notes, -abs(amount), "expense", exp.id)
        return exp.id, exp.to_dict()

    if entity_type == "ledger_entry":
        amount = float(payload.get("amount", 0) or 0)
        if amount == 0: raise ValueError("amount must be non-zero.")
        entry_date = _erp_parse_date(payload.get("entry_date"), datetime.utcnow().date())
        entry = ErpLedgerEntry(
            owner_user_id=user_id, entry_date=entry_date, kind=(payload.get("kind") or "revenue")[:20],
            account=(payload.get("account") or "Sales")[:80], description=payload.get("description"), amount=amount,
        )
        db.session.add(entry); db.session.flush()
        return entry.id, entry.to_dict()

    raise ValueError(f"Unsupported entity_type '{entity_type}'.")


@app.route("/api/sync/batch", methods=["POST"])
@csrf.exempt
def sync_batch():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    ops = data.get("operations")
    if not isinstance(ops, list) or not ops:
        return jsonify({"error": "operations must be a non-empty array."}), 400
    if len(ops) > 200:
        return jsonify({"error": "Batch too large — send at most 200 operations per request."}), 400

    results = []
    for op in ops:
        client_op_id = str(op.get("client_op_id") or "").strip()
        entity_type = op.get("entity_type")
        payload = op.get("payload") or {}
        if not client_op_id:
            results.append({"client_op_id": None, "status": "error", "error": "client_op_id is required."})
            continue

        existing = SyncedOperation.query.filter_by(owner_user_id=user["id"], client_op_id=client_op_id).first()
        if existing:
            results.append(existing.to_dict())  # already applied — safe replay
            continue

        try:
            if entity_type not in SYNC_SUPPORTED_ENTITIES:
                raise ValueError(f"Unsupported entity_type '{entity_type}'.")
            server_id, _ = _sync_apply_operation(user["id"], entity_type, payload)
            db.session.commit()
            rec = SyncedOperation(owner_user_id=user["id"], client_op_id=client_op_id,
                                   entity_type=entity_type, status="ok", server_id=server_id)
        except Exception as e:
            db.session.rollback()
            rec = SyncedOperation(owner_user_id=user["id"], client_op_id=client_op_id,
                                   entity_type=entity_type or "unknown", status="error", error_message=str(e)[:300])
        db.session.add(rec)
        try:
            db.session.commit()
        except Exception as e:
            db.session.rollback(); logging.error(f"[SYNC BATCH RECORD] {e}")
        results.append(rec.to_dict())

    return jsonify({"results": results}), 200


@app.route("/api/sync/pull", methods=["GET"])
def sync_pull():
    """Two-way half: returns anything created/changed on the server since
    a given timestamp so a client that was offline can reconcile its
    local copy (e.g. another device added a customer meanwhile)."""
    user, err = _erp_user_or_401()
    if err: return err
    since_raw = request.args.get("since")
    try:
        since = datetime.fromisoformat(since_raw) if since_raw else datetime.utcnow() - timedelta(days=7)
    except ValueError:
        return jsonify({"error": "since must be an ISO 8601 datetime."}), 400
    uid = user["id"]
    customers = ErpCustomer.query.filter_by(owner_user_id=uid).filter(ErpCustomer.created_at >= since).all()
    expenses = ErpExpense.query.filter_by(owner_user_id=uid).filter(ErpExpense.created_at >= since).all()
    ledger = ErpLedgerEntry.query.filter_by(owner_user_id=uid).filter(ErpLedgerEntry.created_at >= since).all()
    return jsonify({
        "server_time": datetime.utcnow().isoformat(),
        "customers": [c.to_dict() for c in customers],
        "expenses": [e.to_dict() for e in expenses],
        "ledger_entries": [l.to_dict() for l in ledger],
    }), 200


# ════════════════════════════════════════════════════════════
# GLOBAL-04: VOICE-NOTE-TO-LEDGER
# For anyone who'd rather speak a transaction than type it — on the
# move, low-literacy, or just faster. Two steps on purpose, never one:
#   1. /parse transcribes (Whisper auto-detects the spoken language, so
#      this works worldwide, not just in English) and an AI pass extracts
#      a structured transaction, returned for the person to review/edit.
#      Nothing is written to the books yet — money data parsed from a
#      voice note is exactly the kind of thing that deserves a human
#      glance before it hits the ledger.
#   2. /confirm takes the (possibly corrected) structured fields and
#      actually posts them, reusing the same idempotent dispatcher and
#      SyncedOperation table Stage 2 already built — a voice entry is
#      just another sync operation, so it also works queued offline.
VOICE_ENTRY_SYSTEM_PROMPT = (
    "You extract one business transaction from a spoken voice-note transcript, in any "
    "language. Respond with ONLY a JSON object, no other text, no markdown fences, "
    "matching exactly this shape: "
    '{"entity_type": "expense" or "ledger_entry", "amount": <positive number>, '
    '"currency": "<ISO 4217 code, guess from context, default USD if unclear>", '
    '"category_or_account": "<short label, e.g. \'Fuel\' or \'Sales\'>", '
    '"vendor_or_description": "<who it was paid to, or what was sold>", '
    '"is_income": <true if money was received (a sale), false if money went out (an expense)>, '
    '"confidence": "high" or "low"}. '
    "If the transcript doesn't clearly describe a transaction, set confidence to \"low\" and "
    "make your best-effort guess anyway — never refuse or add commentary outside the JSON."
)


def _parse_voice_transaction_json(raw_text: str) -> dict:
    cleaned = re.sub(r"^```(?:json)?|```$", "", (raw_text or "").strip(), flags=re.MULTILINE).strip()
    parsed = json.loads(cleaned)
    amount = float(parsed.get("amount", 0) or 0)
    if amount <= 0:
        raise ValueError("Could not identify a positive amount in the voice note.")
    return {
        "entity_type": "ledger_entry" if parsed.get("is_income") else "expense",
        "amount": round(amount, 2),
        "currency": (parsed.get("currency") or "USD")[:8],
        "category_or_account": (parsed.get("category_or_account") or "General")[:80],
        "vendor_or_description": (parsed.get("vendor_or_description") or "")[:300],
        "is_income": bool(parsed.get("is_income")),
        "confidence": parsed.get("confidence", "low"),
    }


@app.route("/api/erp/voice-entry/parse", methods=["POST"])
@csrf.exempt
def voice_entry_parse():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    if "audio" not in request.files:
        return jsonify({"error": "No audio file provided."}), 400
    audio_file = request.files["audio"]
    if not audio_file.filename:
        return jsonify({"error": "Empty audio file."}), 400

    byok_key = get_effective_credential(user["id"], "openai", "api_key", None)
    client = OpenAI(api_key=byok_key) if byok_key else openai_client
    if not client:
        return jsonify({"error": "Voice transcription isn't configured. Add an OpenAI key under Settings > Integrations."}), 503

    suffix = os.path.splitext(audio_file.filename)[1] or ".webm"
    with tempfile.NamedTemporaryFile(delete=False, suffix=suffix) as tmp:
        audio_file.save(tmp.name)
        tmp_path = tmp.name
    try:
        with open(tmp_path, "rb") as f:
            result = client.audio.transcriptions.create(model="whisper-1", file=f, response_format="verbose_json")
        transcript = result.text
        detected_language = getattr(result, "language", None)
    except Exception as e:
        logging.error(f"[VOICE ENTRY TRANSCRIBE] {e}")
        return jsonify({"error": "Could not transcribe the voice note."}), 500
    finally:
        try: os.unlink(tmp_path)
        except Exception: pass

    ai_reply = _one_round(
        [{"role": "user", "content": f"Voice-note transcript:\n{transcript}"}],
        user_id=user["id"], system_prompt=VOICE_ENTRY_SYSTEM_PROMPT,
    )
    if not ai_reply:
        return jsonify({"error": "Could not parse the transcript into a transaction.", "transcript": transcript}), 502
    try:
        parsed = _parse_voice_transaction_json(ai_reply)
    except Exception as e:
        return jsonify({"error": f"Could not parse a valid transaction: {e}", "transcript": transcript}), 422

    return jsonify({"transcript": transcript, "detected_language": detected_language, "parsed": parsed}), 200


@app.route("/api/erp/voice-entry/confirm", methods=["POST"])
@csrf.exempt
def voice_entry_confirm():
    """Takes the (possibly user-edited) parsed fields from /parse and
    actually posts them — same idempotent path as offline sync, so a
    voice entry made with no signal replays safely too."""
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    client_op_id = str(data.get("client_op_id") or "").strip()
    if not client_op_id:
        return jsonify({"error": "client_op_id is required."}), 400

    existing = SyncedOperation.query.filter_by(owner_user_id=user["id"], client_op_id=client_op_id).first()
    if existing:
        return jsonify(existing.to_dict()), 200

    is_income = bool(data.get("is_income"))
    entity_type = "ledger_entry" if is_income else "expense"
    amount = data.get("amount")
    account_or_category = data.get("category_or_account") or ("Sales" if is_income else "General")
    description = data.get("vendor_or_description") or "Voice-note entry"

    payload = ({"amount": amount, "kind": "revenue", "account": account_or_category, "description": description}
               if is_income else
               {"amount": amount, "category": account_or_category, "vendor": description, "currency": data.get("currency", "USD")})

    try:
        server_id, _ = _sync_apply_operation(user["id"], entity_type, payload)
        db.session.commit()
        rec = SyncedOperation(owner_user_id=user["id"], client_op_id=client_op_id,
                               entity_type=entity_type, status="ok", server_id=server_id)
    except Exception as e:
        db.session.rollback()
        rec = SyncedOperation(owner_user_id=user["id"], client_op_id=client_op_id,
                               entity_type=entity_type, status="error", error_message=str(e)[:300])
    db.session.add(rec)
    try:
        db.session.commit()
    except Exception as e:
        db.session.rollback(); logging.error(f"[VOICE ENTRY CONFIRM RECORD] {e}")
    return jsonify(rec.to_dict()), (201 if rec.status == "ok" else 500)


# ── PUBLIC BOOKING LINK — owner-side setup/management ──────
def _booking_slugify(name: str, owner_user_id: int) -> str:
    base = re.sub(r"[^a-z0-9]+", "-", (name or "").lower()).strip("-") or f"user-{owner_user_id}"
    slug = base
    n = 1
    while PublicBookingPage.query.filter(PublicBookingPage.slug == slug,
                                          PublicBookingPage.owner_user_id != owner_user_id).first():
        n += 1
        slug = f"{base}-{n}"
    return slug


def _booking_page_for_user(uid, create_if_missing=True):
    page = PublicBookingPage.query.filter_by(owner_user_id=uid).first()
    if not page and create_if_missing:
        user = UserAccount.query.get(uid)
        name = (user.name if user else None) or "My Business"
        page = PublicBookingPage(owner_user_id=uid, slug=_booking_slugify(name, uid),
                                  business_name=name, hours_json=json.dumps({
                                      "0": "08:00-17:00", "1": "08:00-17:00", "2": "08:00-17:00",
                                      "3": "08:00-17:00", "4": "08:00-17:00",
                                  }))
        db.session.add(page)
        db.session.commit()
    return page


@app.route("/api/erp/booking-page", methods=["GET"])
def erp_booking_page_get():
    user, err = _erp_user_or_401()
    if err: return err
    page = _booking_page_for_user(user["id"])
    d = page.to_dict()
    d["public_url"] = f"{request.host_url.rstrip('/')}/book/{page.slug}"
    d["services"] = [s.to_dict() for s in PublicBookingService.query.filter_by(page_id=page.id).all()]
    return jsonify(d), 200


@app.route("/api/erp/booking-page", methods=["PUT"])
@csrf.exempt
def erp_booking_page_update():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    page = _booking_page_for_user(user["id"])
    data = request.get_json(silent=True) or {}
    try:
        if "business_name" in data and (data["business_name"] or "").strip():
            page.business_name = data["business_name"].strip()[:200]
        if "welcome_note" in data:
            page.welcome_note = (data.get("welcome_note") or "")[:500] or None
        if "slug" in data and (data["slug"] or "").strip():
            new_slug = re.sub(r"[^a-z0-9\-]+", "-", data["slug"].strip().lower()).strip("-")
            if new_slug and new_slug != page.slug:
                clash = PublicBookingPage.query.filter(PublicBookingPage.slug == new_slug,
                                                        PublicBookingPage.owner_user_id != user["id"]).first()
                if clash:
                    return jsonify({"error": "That link is already taken."}), 400
                page.slug = new_slug
        if "hours" in data and isinstance(data["hours"], dict):
            page.hours_json = json.dumps(data["hours"])
        if "slot_minutes" in data:
            page.slot_minutes = max(5, int(data.get("slot_minutes") or 30))
        if "timezone" in data and data["timezone"]:
            page.timezone = data["timezone"][:64]
        if "active" in data:
            page.active = bool(data["active"])
        db.session.commit()
        return jsonify(page.to_dict()), 200
    except Exception as e:
        db.session.rollback()
        return jsonify({"error": str(e)}), 500


