# ── PUBLIC BOOKING LINK — no-login customer-facing API ─────
def _booking_day_window(page, service, day):
    """Returns (open_dt, close_dt, duration_minutes) for one calendar day,
    or (None, None, duration) if the business is closed that day."""
    hours = page.hours()
    span = hours.get(str(day.weekday()))
    duration = (service.duration_minutes if service else page.slot_minutes) or 30
    if not span or "-" not in span:
        return None, None, duration
    try:
        open_s, close_s = span.split("-")
        open_t = datetime.strptime(open_s.strip(), "%H:%M").time()
        close_t = datetime.strptime(close_s.strip(), "%H:%M").time()
    except Exception:
        return None, None, duration
    return (datetime.combine(day, open_t), datetime.combine(day, close_t), duration)


