@app.route("/api/driving-school/road-signs", methods=["GET"])
@requires_feature_flag("road_rules_driving_school")
def ds_road_signs():
    return jsonify({"categories": DS_ROAD_SIGN_CATEGORIES, "disclaimer": _DS_DISCLAIMER}), 200


@app.route("/api/driving-school/quiz", methods=["GET"])
@requires_feature_flag("road_rules_driving_school")
def ds_quiz_get():
    """Returns a quiz without revealing correct answers; grading happens
    server-side in /quiz/submit against DS_QUIZ_BANK."""
    category = request.args.get("category")
    bank = [q for q in DS_QUIZ_BANK if not category or category == "mixed" or q["category"] == category]
    random.shuffle(bank)
    limit = min(int(request.args.get("limit", 15) or 15), len(bank))
    picked = bank[:limit]
    questions = [{"id": q["id"], "category": q["category"], "question": q["question"], "options": q["options"]} for q in picked]
    return jsonify({"questions": questions, "disclaimer": _DS_DISCLAIMER}), 200


@app.route("/api/driving-school/quiz/submit", methods=["POST"])
@csrf.exempt
@requires_feature_flag("road_rules_driving_school")
def ds_quiz_submit():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _ds_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    answers = data.get("answers") or []  # [{id, selected}]
    by_id = {q["id"]: q for q in DS_QUIZ_BANK}
    graded, score = [], 0
    for a in answers:
        q = by_id.get(a.get("id"))
        if not q: continue
        correct = (a.get("selected") == q["correct"])
        if correct: score += 1
        graded.append({"id": q["id"], "question": q["question"], "correct": correct,
                        "correct_index": q["correct"], "explanation": q["explanation"]})
    try:
        attempt = DsQuizAttempt(
            owner_user_id=user["id"], learner_id=data.get("learner_id"),
            category=data.get("category", "mixed"), score=score, total_questions=len(graded),
        )
        db.session.add(attempt); db.session.commit()
    except Exception as e:
        db.session.rollback(); logging.error(f"[DS QUIZ SUBMIT] {e}")
        return jsonify({"error": "Could not save quiz attempt."}), 500
    return jsonify({"attempt": attempt.to_dict(), "results": graded}), 200


@app.route("/api/driving-school/quiz/history", methods=["GET"])
@requires_feature_flag("road_rules_driving_school")
def ds_quiz_history():
    user, err = _ds_user_or_401()
    if err: return err
    q = DsQuizAttempt.query.filter_by(owner_user_id=user["id"])
    learner_id = request.args.get("learner_id")
    if learner_id: q = q.filter_by(learner_id=int(learner_id))
    rows = q.order_by(DsQuizAttempt.taken_at.desc()).limit(50).all()
    return jsonify({"attempts": [r.to_dict() for r in rows]}), 200


