@app.route("/api/driving-school/instructors", methods=["POST"])
@csrf.exempt
@requires_feature_flag("road_rules_driving_school")
def ds_instructors_create():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _ds_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    name = (data.get("full_name") or "").strip()
    if not name: return jsonify({"error": "full_name is required."}), 400
    try:
        i = DsInstructor(owner_user_id=user["id"], full_name=name[:200], phone=data.get("phone"),
                          email=data.get("email"), license_number=data.get("license_number"),
                          bio=data.get("bio"), hourly_rate=data.get("hourly_rate"))
        db.session.add(i); db.session.commit()
    except Exception as e:
        db.session.rollback(); logging.error(f"[DS INSTRUCTOR CREATE] {e}")
        return jsonify({"error": "Could not save instructor."}), 500
    return jsonify({"instructor": i.to_dict()}), 201


@app.route("/api/driving-school/instructors/<int:iid>", methods=["PUT", "DELETE"])
@csrf.exempt
@requires_feature_flag("road_rules_driving_school")
def ds_instructors_update(iid):
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _ds_user_or_401()
    if err: return err
    i = DsInstructor.query.get(iid)
    if not i or i.owner_user_id != user["id"]: return jsonify({"error": "Instructor not found."}), 404
    try:
        if request.method == "DELETE":
            i.active = False
        else:
            data = request.get_json(silent=True) or {}
            for f in ("full_name", "phone", "email", "license_number", "bio"):
                if f in data: setattr(i, f, data[f])
            if "hourly_rate" in data and data["hourly_rate"] is not None: i.hourly_rate = float(data["hourly_rate"])
            if "active" in data: i.active = bool(data["active"])
        db.session.commit()
    except Exception as e:
        db.session.rollback(); logging.error(f"[DS INSTRUCTOR UPDATE] {e}")
        return jsonify({"error": "Could not update instructor."}), 500
    return jsonify({"instructor": i.to_dict()}), 200


