@app.route("/api/driving-school/bookings", methods=["POST"])
@csrf.exempt
@requires_feature_flag("road_rules_driving_school")
def ds_bookings_create():
    """Books a lesson. Rejects the request if the chosen instructor is
    already booked (status requested/confirmed) over an overlapping
    window, so the same instructor can't be double-booked."""
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _ds_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    start = _ds_parse_dt(data.get("scheduled_start"))
    end = _ds_parse_dt(data.get("scheduled_end"))
    learner = DsLearner.query.get(data.get("learner_id"))
    if not learner or learner.owner_user_id != user["id"]: return jsonify({"error": "Learner not found."}), 404
    if not start or not end or end <= start: return jsonify({"error": "Valid scheduled_start and scheduled_end are required."}), 400
    instructor_id = data.get("instructor_id")
    if instructor_id:
        clash = (DsBooking.query.filter_by(owner_user_id=user["id"], instructor_id=instructor_id)
                 .filter(DsBooking.status.in_(["requested", "confirmed"]))
                 .filter(DsBooking.scheduled_start < end, DsBooking.scheduled_end > start).first())
        if clash:
            return jsonify({"error": "That instructor already has a lesson booked in this time window."}), 409
    try:
        b = DsBooking(owner_user_id=user["id"], learner_id=learner.id, instructor_id=instructor_id,
                       vehicle_id=data.get("vehicle_id"), scheduled_start=start, scheduled_end=end,
                       lesson_topic=data.get("lesson_topic"), notes=data.get("notes"))
        db.session.add(b); db.session.commit()
    except Exception as e:
        db.session.rollback(); logging.error(f"[DS BOOKING CREATE] {e}")
        return jsonify({"error": "Could not save booking."}), 500
    return jsonify({"booking": b.to_dict()}), 201


