# ===========================================================
# STAGE 53: KJV HOLY BIBLE — verse/passage lookup and verse-of-the-day.
# Proxies bible-api.com (free, keyless, public-domain KJV text) with a
# 24h in-memory cache since scripture text never changes and the
# upstream service is rate-limited (15 req/30s) and asks callers not
# to hammer it — caching here protects it and speeds up repeats.
# ===========================================================

_BIBLE_CACHE = {}
_BIBLE_CACHE_TTL_SECONDS = 86400

_BIBLE_VERSE_OF_DAY_LIST = [
    "John 3:16", "Psalm 23:1", "Philippians 4:13", "Proverbs 3:5-6", "Romans 8:28",
    "Joshua 1:9", "Isaiah 41:10", "Jeremiah 29:11", "Psalm 46:1", "Matthew 6:33",
    "Romans 12:2", "Psalm 121:1-2", "Proverbs 16:3", "1 Corinthians 13:4-7", "Psalm 27:1",
    "Isaiah 40:31", "Philippians 4:6-7", "2 Timothy 1:7", "Psalm 118:24", "Matthew 11:28",
    "Galatians 5:22-23", "Psalm 91:1-2", "James 1:5", "Proverbs 22:6", "1 Peter 5:7",
    "Psalm 34:18", "Hebrews 11:1", "Matthew 5:16", "Psalm 37:4", "Romans 15:13",
]


def _bible_fetch(reference: str, translation: str = "kjv") -> dict:
    key = (reference.strip().lower(), translation)
    cached = _BIBLE_CACHE.get(key)
    if cached and (time.time() - cached[0]) < _BIBLE_CACHE_TTL_SECONDS:
        return cached[1]
    url = "https://bible-api.com/" + quote(reference.strip())
    resp = requests.get(url, params={"translation": translation}, timeout=8)
    resp.raise_for_status()
    data = resp.json()
    if data.get("error"):
        raise ValueError(data["error"])
    _BIBLE_CACHE[key] = (time.time(), data)
    return data


@app.route("/api/bible/passage", methods=["GET"])
def bible_passage():
    """Looks up a verse, verse range, or chapter — e.g. 'John 3:16',
    'Genesis 1:1-3', or 'Psalm 23'. KJV by default (public domain);
    other free public-domain translations (web, bbe, etc.) also work
    via ?translation=."""
    reference = (request.args.get("reference") or "").strip()
    if not reference:
        return jsonify({"error": "reference is required, e.g. 'John 3:16'."}), 400
    translation = (request.args.get("translation") or "kjv").strip().lower()
    try:
        data = _bible_fetch(reference, translation)
    except requests.exceptions.RequestException as e:
        logging.error(f"[BIBLE FETCH ERROR] {e}")
        return jsonify({"error": "Could not reach the Bible text service. Try again shortly."}), 502
    except ValueError as e:
        return jsonify({"error": str(e) or "Reference not found."}), 404
    return jsonify({
        "reference": data.get("reference"),
        "translation": (data.get("translation_name") or translation.upper()),
        "text": (data.get("text") or "").strip(),
        "verses": data.get("verses", []),
    }), 200


@app.route("/api/bible/verse-of-day", methods=["GET"])
def bible_verse_of_day():
    """Same reference all day (rotates daily off day-of-year), so
    everyone sees the same verse of the day and repeat calls hit cache."""
    idx = datetime.utcnow().timetuple().tm_yday % len(_BIBLE_VERSE_OF_DAY_LIST)
    reference = _BIBLE_VERSE_OF_DAY_LIST[idx]
    try:
        data = _bible_fetch(reference, "kjv")
    except Exception as e:
        logging.error(f"[BIBLE VOTD ERROR] {e}")
        return jsonify({"error": "Could not load today's verse."}), 502
    return jsonify({
        "reference": data.get("reference"),
        "translation": data.get("translation_name") or "King James Version",
        "text": (data.get("text") or "").strip(),
    }), 200


