@app.route("/api/gemini/image/generate", methods=["POST"])
@csrf.exempt
def gemini_image_generate():
    """Nano Banana Pro / Nano Banana 2 image generation-and-editing.
    multipart/form-data: prompt (required), aspect_ratio, resolution
    ("1K"/"2K"/"4K", Pro only), tier ("pro" default or "fast"), and up to
    6 reference_images files for multi-image composition/editing."""
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user_id = _current_user_id()
    if not user_id:
        return jsonify({"error": "Login required."}), 401
    prompt = (request.form.get("prompt") or (request.get_json(silent=True) or {}).get("prompt") or "").strip()
    if not prompt:
        return jsonify({"error": "prompt is required, e.g. 'Studio product photo of a ceramic mug on a wood table.'"}), 400
    reference_images = []
    for f in request.files.getlist("reference_images")[:6]:
        if f and f.filename:
            reference_images.append({"bytes": f.read(), "mime_type": f.mimetype or "image/png"})
    result = generate_gemini_image(
        user_id, prompt,
        reference_images = reference_images or None,
        aspect_ratio      = (request.form.get("aspect_ratio") or "1:1").strip(),
        resolution         = (request.form.get("resolution") or "2K").strip(),
        use_pro           = (request.form.get("tier") or "pro").strip().lower() != "fast",
    )
    if not result["ok"]:
        return jsonify({"error": result["error"]}), 502
    return jsonify({"images": result["images"], "model": result["model"]}), 200


