@app.route("/api/cron/gemini-agent-triggers", methods=["POST"])
@csrf.exempt
def cron_gemini_agent_triggers():
    """System-wide sweep for due GeminiAgentTrigger rows — point a
    PythonAnywhere Scheduled Task here (e.g. every 15 minutes), same
    X-Cron-Secret pattern as every other cron endpoint in this file.
    Each trigger fires at most once per its own interval_minutes,
    regardless of how often this sweep itself runs."""
    if not CRON_SECRET or request.headers.get("X-Cron-Secret") != CRON_SECRET:
        return jsonify({"error": "Forbidden."}), 403
    now = datetime.utcnow()
    due = [t for t in GeminiAgentTrigger.query.filter_by(enabled=True).all() if t.is_due(now)]
    ran, failed = 0, 0
    for trigger in due:
        try:
            mcp_servers = json.loads(trigger.mcp_servers_json or "[]")
        except Exception:
            mcp_servers = []
        run_row = GeminiAgentRun(owner_user_id=trigger.owner_user_id, trigger_id=trigger.id,
                                  input_text=trigger.prompt, triggered_by="cron", status="pending")
        db.session.add(run_row); db.session.commit()
        result = run_gemini_agent_interaction(trigger.owner_user_id, trigger.prompt,
                                               mcp_servers=mcp_servers, model=trigger.model)
        run_row.status = "success" if result["ok"] else "error"
        run_row.output_text = result.get("output_text")
        run_row.interaction_id = result.get("interaction_id")
        run_row.error_message = None if result["ok"] else result.get("error")
        trigger.last_run_at = now
        trigger.last_status = run_row.status
        db.session.commit()
        ran += 1
        if not result["ok"]:
            failed += 1
    logging.info(f"[CRON GEMINI AGENT TRIGGERS] {ran} run, {failed} failed, out of {GeminiAgentTrigger.query.filter_by(enabled=True).count()} enabled")
    return jsonify({"ran": ran, "failed": failed}), 200


