@app.route("/api/prices/report", methods=["POST"])
@csrf.exempt
def prices_report_create():
    """Crowd-sourced entry — any logged-in user can report a real price
    they paid, same mechanic as the load-shedding tracker."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401

    data      = request.get_json(silent=True) or {}
    area_name = (data.get("area_name") or "").strip()
    item_name = (data.get("item_name") or "").strip()
    country   = (data.get("country") or "ZW").strip().upper()[:2]
    unit      = (data.get("unit") or "").strip()[:40] or None
    store     = (data.get("store_name") or "").strip()[:160] or None
    notes     = (data.get("notes") or "").strip()[:300] or None
    currency  = (data.get("currency") or "USD").strip()[:8]

    try:
        price = float(data.get("price"))
    except (TypeError, ValueError):
        return jsonify({"error": "price must be a number."}), 400
    if not area_name or not item_name:
        return jsonify({"error": "area_name and item_name are required."}), 400
    if price <= 0 or price > 1_000_000:
        return jsonify({"error": "price must be a realistic positive amount."}), 400
    if country not in ("ZW", "ZA"):
        country = "ZW"

    report = PriceReport(
        user_id=user["id"], country=country, area_name=area_name[:120],
        item_name=item_name[:120], unit=unit, price=price, currency=currency,
        store_name=store, notes=notes,
    )
    db.session.add(report)
    db.session.commit()
    return jsonify({"ok": True, "report": report.to_dict()}), 200


@app.route("/api/prices/list", methods=["GET"])
def prices_list():
    """Recent reports for an item (optionally scoped to an area), plus
    the average — the day-to-day number that diverges from official
    inflation stats."""
    item_name = (request.args.get("item_name") or "").strip()
    area_name = (request.args.get("area_name") or "").strip()
    country   = (request.args.get("country") or "").strip().upper()[:2]
    if not item_name:
        return jsonify({"error": "item_name query param is required."}), 400

    q = PriceReport.query.filter(PriceReport.item_name.ilike(f"%{item_name}%"))
    if area_name:
        q = q.filter(PriceReport.area_name.ilike(f"%{area_name}%"))
    if country in ("ZW", "ZA"):
        q = q.filter(PriceReport.country == country)
    rows = q.order_by(PriceReport.created_at.desc()).limit(50).all()
    prices = [r.price for r in rows]
    avg_price = round(sum(prices) / len(prices), 2) if prices else None
    return jsonify({
        "item_name": item_name, "area_name": area_name or None,
        "average_price": avg_price, "sample_size": len(prices),
        "reports": [r.to_dict() for r in rows],
    }), 200


@app.route("/api/prices/trend", methods=["GET"])
def prices_trend():
    """Weekly average price for an item/area over the recent reporting
    history — a real, informal cost-of-living trend line."""
    item_name = (request.args.get("item_name") or "").strip()
    area_name = (request.args.get("area_name") or "").strip()
    if not item_name:
        return jsonify({"error": "item_name query param is required."}), 400

    q = PriceReport.query.filter(PriceReport.item_name.ilike(f"%{item_name}%"))
    if area_name:
        q = q.filter(PriceReport.area_name.ilike(f"%{area_name}%"))
    rows = q.order_by(PriceReport.created_at.asc()).limit(500).all()

    buckets = {}
    for r in rows:
        if not r.created_at:
            continue
        year, week, _ = r.created_at.isocalendar()
        key = f"{year}-W{week:02d}"
        buckets.setdefault(key, []).append(r.price)

    trend = [
        {"week": k, "average_price": round(sum(v) / len(v), 2), "sample_size": len(v)}
        for k, v in sorted(buckets.items())
    ]
    return jsonify({"item_name": item_name, "area_name": area_name or None, "trend": trend}), 200


@app.route("/api/prices/compare", methods=["GET"])
def prices_compare():
    """Average price per area for a given item, so people can see how
    much cost-of-living actually diverges area to area."""
    item_name = (request.args.get("item_name") or "").strip()
    if not item_name:
        return jsonify({"error": "item_name query param is required."}), 400
    rows = (PriceReport.query
            .filter(PriceReport.item_name.ilike(f"%{item_name}%"))
            .order_by(PriceReport.created_at.desc()).limit(300).all())
    by_area = {}
    for r in rows:
        by_area.setdefault(r.area_name, []).append(r.price)
    comparison = sorted(
        [{"area_name": a, "average_price": round(sum(v) / len(v), 2), "sample_size": len(v)}
         for a, v in by_area.items()],
        key=lambda x: x["average_price"],
    )
    return jsonify({"item_name": item_name, "areas": comparison}), 200


