def _send_loyalty_sms(to_phone: str, message: str) -> dict:
    """Best-effort SMS notification for loyalty milestones/rewards.
    Never raises — a failed SMS should never block a checkin/redeem."""
    try:
        clean = sanitize_phone(to_phone)
        if not clean:
            return {"ok": False, "error": "invalid phone"}
        if AT_AVAILABLE and at_sms:
            result = at_sms.send(message=message, recipients=[clean])
            return {"ok": True, "result": result}
        return {"ok": False, "error": "Africa's Talking not configured"}
    except Exception as e:
        logging.warning(f"[LOYALTY SMS] Failed to notify {to_phone}: {e}")
        return {"ok": False, "error": str(e)}


