@app.route("/api/loyalty/checkin", methods=["POST"])
@csrf.exempt
def loyalty_checkin():
    """Record a purchase/visit for a customer under a program. Creates
    the customer record on first checkin, notifies by SMS once the
    reward threshold is reached."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401

    data = request.get_json(silent=True) or {}
    program_id = data.get("program_id")
    phone = sanitize_phone((data.get("phone") or "").strip())
    name = (data.get("name") or "").strip()[:120] or None

    program = LoyaltyProgram.query.get(program_id)
    if not program or program.owner_id != user["id"]:
        return jsonify({"error": "Program not found."}), 404
    if not program.active:
        return jsonify({"error": "This loyalty program is not active."}), 400
    if not phone:
        return jsonify({"error": "A valid customer phone number is required."}), 400

    try:
        amount = int(data.get("amount", program.points_per_visit) or program.points_per_visit)
    except (TypeError, ValueError):
        amount = program.points_per_visit
    amount = max(1, amount)

    customer = LoyaltyCustomer.query.filter_by(program_id=program.id, phone=phone).first()
    if not customer:
        customer = LoyaltyCustomer(program_id=program.id, phone=phone, name=name)
        db.session.add(customer)
        db.session.flush()
    elif name:
        customer.name = name

    customer.balance += amount
    customer.total_earned += amount
    db.session.add(LoyaltyTransaction(customer_id=customer.id, kind="earn", amount=amount,
                                       note=f"Checkin at {user.get('name') or user.get('email') or 'business'}"))
    db.session.commit()

    sms_result = None
    if customer.balance >= program.threshold:
        msg = (f"Great news! You've earned enough with us for: {program.reward_text}. "
               f"Show this message next visit to redeem. - Connect It")
        sms_result = _send_loyalty_sms(phone, msg)
    else:
        remaining = program.threshold - customer.balance
        unit = "point" if program.program_type == "points" else "visit"
        msg = f"Thanks for your visit! {remaining} more {unit}(s) until: {program.reward_text}. - Connect It"
        sms_result = _send_loyalty_sms(phone, msg)

    return jsonify({"ok": True, "customer": customer.to_dict(), "sms": sms_result}), 200


@app.route("/api/loyalty/redeem", methods=["POST"])
@csrf.exempt
def loyalty_redeem():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    customer = LoyaltyCustomer.query.get(data.get("customer_id"))
    if not customer:
        return jsonify({"error": "Customer not found."}), 404
    program = LoyaltyProgram.query.get(customer.program_id)
    if not program or program.owner_id != user["id"]:
        return jsonify({"error": "Not authorized for this program."}), 403
    if customer.balance < program.threshold:
        return jsonify({"error": "Customer has not reached the reward threshold yet."}), 400

    customer.balance -= program.threshold
    customer.rewards_claimed += 1
    db.session.add(LoyaltyTransaction(customer_id=customer.id, kind="redeem", amount=program.threshold,
                                       note=f"Redeemed: {program.reward_text}"))
    db.session.commit()
    sms_result = _send_loyalty_sms(customer.phone, f"Reward redeemed: {program.reward_text}. Thank you for your loyalty! - Connect It")
    return jsonify({"ok": True, "customer": customer.to_dict(), "sms": sms_result}), 200


