@app.route("/api/delivery/requests/<int:request_id>/accept", methods=["POST"])
@csrf.exempt
def delivery_request_accept(request_id):
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    rider = DeliveryRider.query.filter_by(user_id=user["id"]).first()
    if not rider:
        return jsonify({"error": "Register as a rider first."}), 404
    req_row = DeliveryRequest.query.get(request_id)
    if not req_row:
        return jsonify({"error": "Delivery request not found."}), 404
    if req_row.status != "open":
        return jsonify({"error": "This request is no longer open."}), 400

    req_row.rider_id = rider.id
    req_row.status = "accepted"
    req_row.accepted_at = datetime.utcnow()
    _ensure_deal_confirmation("delivery", req_row.id, req_row.requester_id, rider.user_id)
    db.session.commit()
    if req_row.contact_phone:
        _send_loyalty_sms(req_row.contact_phone,
                           f"{rider.name} ({rider.phone}) accepted your delivery request "
                           f"from {req_row.pickup_area} to {req_row.dropoff_area}. - Connect It")
    return jsonify({"ok": True, "request": req_row.to_dict()}), 200


@app.route("/api/delivery/requests/<int:request_id>/complete", methods=["POST"])
@csrf.exempt
def delivery_request_complete(request_id):
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    req_row = DeliveryRequest.query.get(request_id)
    if not req_row:
        return jsonify({"error": "Delivery request not found."}), 404
    if req_row.requester_id != user["id"]:
        return jsonify({"error": "Only the requester can mark a delivery complete."}), 403
    if req_row.status != "accepted":
        return jsonify({"error": "This request has not been accepted by a rider yet."}), 400

    data = request.get_json(silent=True) or {}
    rating = data.get("rating")
    req_row.status = "completed"
    req_row.completed_at = datetime.utcnow()
    if rating:
        try:
            rating = max(1, min(5, int(rating)))
            req_row.rider_rating = rating
            rider = DeliveryRider.query.get(req_row.rider_id)
            if rider:
                rider.rating_sum += rating
                rider.rating_count += 1
                rider.deliveries_completed += 1
        except (TypeError, ValueError):
            pass
    else:
        rider = DeliveryRider.query.get(req_row.rider_id)
        if rider:
            rider.deliveries_completed += 1
    db.session.commit()
    return jsonify({"ok": True, "request": req_row.to_dict()}), 200


@app.route("/api/delivery/requests/<int:request_id>/cancel", methods=["POST"])
@csrf.exempt
def delivery_request_cancel(request_id):
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    req_row = DeliveryRequest.query.get(request_id)
    if not req_row:
        return jsonify({"error": "Delivery request not found."}), 404
    if req_row.requester_id != user["id"]:
        return jsonify({"error": "Only the requester can cancel this request."}), 403
    if req_row.status == "completed":
        return jsonify({"error": "Cannot cancel a completed delivery."}), 400
    req_row.status = "cancelled"
    db.session.commit()
    return jsonify({"ok": True, "request": req_row.to_dict()}), 200


# ════════════════════════════════════════════════════════════
# STAGE 76: POSITIVE VIBES — full-page daily uplift hub
# Reuses generate_hope_content() (already powers the admin broadcast
# feed) as a user-facing, on-demand endpoint, plus the existing
# Bible verse-of-the-day, so the page shows something real and fresh
# instead of static filler.
# ════════════════════════════════════════════════════════════

@app.route("/api/positivevibes/today", methods=["GET"])
def positivevibes_today():
    """On-demand uplifting content for any signed-in or anonymous
    visitor — no admin gate, nothing gets posted publicly."""
    category = (request.args.get("category") or "positive_vibes").strip()
    if category not in ("hope", "positive_vibes", "thought_provoking", "healing", "thinking_big", "unleash_greatness"):
        category = "positive_vibes"
    user_id = _current_user_id()
    # STAGE (metering gap fix): anonymous access here is intentional (see
    # docstring above), same as /api/chat — so meter only when signed in,
    # and rate-limit anonymous callers by IP instead, since previously
    # they had no cap of any kind.
    if user_id:
        gate_result = gate_ai_usage(_get_current_user(), "positivevibes_today")
        if gate_result is not None:
            return gate_result
    elif _rate_limited(f"positivevibes:ip:{_client_ip()}", max_attempts=10, window_seconds=3600):
        return jsonify({"error": "Too many requests. Please try again later."}), 429
    try:
        content = generate_hope_content(category, user_id=user_id)
    except Exception as e:
        logging.error(f"[POSITIVE VIBES ERROR] {e}")
        return jsonify({"error": "Could not generate content right now. Try again in a moment."}), 502
    return jsonify({"ok": True, **content}), 200


# ════════════════════════════════════════════════════════════
# STAGE 531: "SMILE AGAIN" REFLECTION CARD GENERATOR
# Real AI generation, not a template: takes whatever subject/premise
# the user types and generates a genuine philosophical/reflective
# essay-style response in the same poetic persona voice used for the
# hope/positivity broadcast content above — this is the second place
# in the app where that voice is intentionally correct. The frontend
# renders it into a shareable card (see openSmileAgainPanel in
# index.html) and exports that card as a real downloaded image via
# html2canvas — nothing here is a mockup or placeholder image.
# ════════════════════════════════════════════════════════════

@app.route("/api/smileagain/reflect", methods=["POST"])
@csrf.exempt
def smileagain_reflect():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    # Platform admins always have full access, no subscription or quota
    # required — checked first so nothing below ever blocks them.
    if not _is_platform_admin(user["id"]):
        # All-or-nothing subscription gate — free plan can't use this at
        # all, separate from (and checked before) the monthly-quota
        # metering below.
        plan_result = require_plan(user, "smileagain_reflect")
        if plan_result is not None:
            return plan_result
        gate_result = gate_ai_usage(user, "smileagain_reflect")
        if gate_result is not None:
            return gate_result

    data = request.get_json(silent=True) or {}
    subject = (data.get("subject") or "").strip()[:300]
    if not subject:
        return jsonify({"error": "'subject' is required."}), 400

    prompt = (
        "Write a short, dense, philosophical reflection inspired by this subject or premise:\n\n"
        f"\"{subject}\"\n\n"
        "Write it as a single flowing paragraph of continuous, elevated, thought-provoking prose — "
        "the kind of writing that treats the subject as a doorway into questions of identity, duality, "
        "belonging, sacrifice, or destiny, whatever the subject naturally opens onto. Use rich, precise, "
        "slightly poetic vocabulary. No headings, no bullet points, no quotation marks around the whole "
        "thing, just the paragraph itself. 130-190 words."
    )
    try:
        reply, _ = generate_ai_reply(prompt, [], user_id=user["id"])
    except Exception as e:
        logging.error(f"[SMILE AGAIN REFLECT ERROR] {e}")
        return jsonify({"error": "Could not generate a reflection right now. Try again in a moment."}), 502

    return jsonify({"ok": True, "subject": subject, "content": reply.strip()}), 200


