    """Side-by-side comparison across all of an owner's branches —
    the actual franchise/multi-location dashboard view."""
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    branches = Branch.query.filter_by(owner_id=user["id"]).all()
    rows = [b.to_dict(include_totals=True) for b in branches]
    rows.sort(key=lambda r: r["profit"], reverse=True)
    totals = {
        "total_revenue": round(sum(r["total_revenue"] for r in rows), 2),
        "total_expenses": round(sum(r["total_expenses"] for r in rows), 2),
        "total_profit": round(sum(r["profit"] for r in rows), 2),
        "branch_count": len(rows),
    }
    return jsonify({"branches": rows, "totals": totals}), 200


