# STAGE 148: printable QR label for a personal device. Encodes the
# device's own record — label, category, serial number, and a
# human-readable warranty-expiry date — as plain text, so scanning it
# with any phone camera (no app needed) shows what the item is and
# when cover runs out, e.g. for a sticker on the underside of a laptop.
@app.route("/api/warranty/devices/<int:device_id>/qrcode", methods=["GET"])
def device_registry_qrcode(device_id):
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    item = DeviceRegistryItem.query.filter_by(id=device_id, owner_id=user["id"]).first()
    if not item:
        return jsonify({"error": "Device not found."}), 404
    if not QRCODE_AVAILABLE:
        return jsonify({"error": "QR code generation isn't available on this server (qrcode library not installed)."}), 503

    d = item.to_dict()
    lines = [f"Smile Again — Device Registry", f"Item: {d['device_label']}"]
    if d.get("category"):
        lines.append(f"Category: {d['category']}")
    if d.get("serial_number"):
        lines.append(f"Serial: {d['serial_number']}")
    if d.get("purchase_date"):
        lines.append(f"Purchased: {d['purchase_date']}")
    if d.get("expiry_date"):
        lines.append(f"Warranty until: {d['expiry_date']}")
    lines.append(f"Registry ID: {d['id']}")
    payload = "\n".join(lines)

    try:
        png_bytes = _generate_qr_png_bytes(payload)
    except RuntimeError as e:
        return jsonify({"error": str(e)}), 503
    except Exception as e:
        logging.error(f"[DEVICE QR] {e}")
        return jsonify({"error": "Could not generate QR code."}), 500

    return Response(
        png_bytes, mimetype="image/png",
        headers={"Content-Disposition": f'inline; filename="device-{device_id}-qr.png"'},
    )


