    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    blocked = gate_ai_usage(user, "kyc_submit")
    if blocked: return blocked

    # Accept either multipart/form-data (with files) or plain JSON (no files).
    if request.content_type and "multipart/form-data" in request.content_type:
        form = request.form
        subject_name = (form.get("subject_name") or "").strip()
        subject_phone = form.get("subject_phone")
        id_type = (form.get("id_type") or "national_id").strip()
        id_number = (form.get("id_number") or "").strip()[:80] or None
    else:
        data = request.get_json(silent=True) or {}
        subject_name = (data.get("subject_name") or "").strip()
        subject_phone = data.get("subject_phone")
        id_type = (data.get("id_type") or "national_id").strip()
        id_number = (data.get("id_number") or "").strip()[:80] or None

    if id_type not in ("national_id", "passport", "drivers_license"):
        id_type = "national_id"
    if not subject_name:
        return jsonify({"error": "subject_name is required."}), 400

    id_document_url = None
    selfie_url = None
    if request.files:
        if "id_document" in request.files and request.files["id_document"].filename:
            id_document_url = _upload_to_cloudinary(
                file_bytes=request.files["id_document"].read(), resource_type="image", folder="connect it/kyc")
        if "selfie" in request.files and request.files["selfie"].filename:
            selfie_url = _upload_to_cloudinary(
                file_bytes=request.files["selfie"].read(), resource_type="image", folder="connect it/kyc")

    record = KYCVerification(
        owner_id=user["id"], subject_name=subject_name[:120],
        subject_phone=sanitize_phone(subject_phone) if subject_phone else None,
        id_type=id_type, id_number=id_number,
        id_document_url=id_document_url, selfie_url=selfie_url,
    )
    db.session.add(record)
    db.session.commit()
    return jsonify({
        "ok": True, "verification": record.to_dict(),
        "note": "Submitted for manual review. This is a document/photo record for the "
                "business owner to review — not automated identity verification.",
    }), 201


