@app.route("/api/kyc/<int:verification_id>/review", methods=["POST"])
@csrf.exempt
def kyc_review(verification_id):
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    record = KYCVerification.query.get(verification_id)
    if not record or record.owner_id != user["id"]:
        return jsonify({"error": "Verification record not found."}), 404
    # STAGE 333: a 'marketplace_buyer' row is the buyer's OWN document —
    # letting them approve it themselves here would defeat the point of
    # review. Those go through the admin-only route further down instead.
    if record.context == "marketplace_buyer":
        return jsonify({"error": "Marketplace buyer identity verifications are reviewed by platform staff, not self-approved."}), 403
    data = request.get_json(silent=True) or {}
    status = (data.get("status") or "").strip()
    if status not in ("approved", "rejected"):
        return jsonify({"error": "status must be 'approved' or 'rejected'."}), 400
    record.status = status
    record.reviewer_notes = (data.get("notes") or "").strip()[:300] or None
    record.reviewed_at = datetime.utcnow()
    db.session.commit()
    return jsonify({"ok": True, "verification": record.to_dict()}), 200


# STAGE 321: REAL IDENTITY VERIFICATION (SMILE IDENTITY)
# kyc_submit() above only ever created a document/photo record for a
# HUMAN to review — no document authenticity check, no liveness
# detection, no database cross-check. This adds an actual automated
# verifier call as an extra step a business can run before (or
# instead of) manual review, using their own connected Smile Identity
# account. It never runs on its own — status still only changes via
# kyc_review() above unless the caller explicitly acts on the result.
def _smile_identity_signature(partner_id: str, api_key: str, timestamp: str) -> str:
    """Per Smile Identity's REST API auth spec: HMAC-SHA256 of
    timestamp+partner_id+"sid_request", keyed with the partner's API
    key, base64-encoded."""
    digest = hmac.new(api_key.encode(), (timestamp + partner_id + "sid_request").encode(), hashlib.sha256).digest()
    return base64.b64encode(digest).decode()


@app.route("/api/kyc/<int:verification_id>/verify", methods=["POST"])
@csrf.exempt
def kyc_verify_smile_identity(verification_id):
    """Body: country_code (ISO 2-letter, required — Smile Identity
    verifies against that country's ID registry). Submits the already-
    uploaded ID document + selfie for real document/liveness checking."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    record = KYCVerification.query.get(verification_id)
    if not record or record.owner_id != user["id"]:
        return jsonify({"error": "Verification record not found."}), 404
    if not record.id_document_url or not record.selfie_url:
        return jsonify({"error": "Both an ID document and a selfie are required for automated verification."}), 400
    data = request.get_json(silent=True) or {}
    country_code = (data.get("country_code") or "").strip().upper()
    if not country_code:
        return jsonify({"error": "country_code is required — Smile Identity verifies against that country's ID registry."}), 400

    creds = get_user_credentials(user["id"], "smile_identity")
    if not (creds.get("partner_id") and creds.get("api_key")):
        return jsonify({"error": "Connect Smile Identity under Integrations first."}), 400

    try:
        doc_bytes = requests.get(record.id_document_url, timeout=15).content
        selfie_bytes = requests.get(record.selfie_url, timeout=15).content
        timestamp = datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%S.%f")[:-3] + "Z"
        signature = _smile_identity_signature(creds["partner_id"], creds["api_key"], timestamp)
        sid_server = creds.get("sid_server", "0")
        base_url = "https://testapi.smileidentity.com/v1" if sid_server == "0" else "https://api.smileidentity.com/v1"
        payload = {
            "partner_id": creds["partner_id"], "sid_server": sid_server,
            "timestamp": timestamp, "signature": signature,
            "job_id": f"kyc-{record.id}-{int(datetime.utcnow().timestamp())}",
            "user_id": f"connectit-user-{record.owner_id}",
            "id_info": {"country": country_code, "id_type": record.id_type.upper().replace("_", ""),
                        "id_number": record.id_number or ""},
            "images": [
                {"image_type_id": "1", "image": base64.b64encode(selfie_bytes).decode()},
                {"image_type_id": "3", "image": base64.b64encode(doc_bytes).decode()},
            ],
        }
        r = requests.post(f"{base_url}/id_verification", json=payload, timeout=30)
        r.raise_for_status()
        body = r.json()
    except Exception as e:
        logging.error(f"[SMILE IDENTITY VERIFY ERROR] kyc={verification_id}: {e}")
        return jsonify({"error": f"Smile Identity verification failed: {e}"}), 502

    result_text = str(body.get("ResultText") or "").lower()
    if "not verified" in result_text or "no match" in result_text or "not match" in result_text:
        outcome = "not_verified"
    elif "verified" in result_text or ("match" in result_text and "no" not in result_text):
        outcome = "verified"
    else:
        outcome = "review_needed"
    confidence = body.get("ConfidenceValue")
    record.verifier = "smile_identity"
    record.verifier_result = outcome
    record.verifier_confidence = float(confidence) if confidence not in (None, "") else None
    record.verifier_raw = json.dumps(body)[:8000]
    db.session.commit()
    return jsonify({"ok": True, "verification": record.to_dict()}), 200


# ════════════════════════════════════════════════════════════
# STAGE 333: MARKETPLACE BUYER ID VERIFICATION
# A buyer isn't a "business" with BYOK integrations, so the Stage 321
# Smile Identity path above stays available to them (it's already
# purely per-user_id, not business-specific — a buyer who happens to
# connect Smile Identity credentials under Integrations can still use
# kyc_verify_smile_identity() on their own record unchanged) but isn't
# assumed. What every buyer DOES get is the honest Stage 79 baseline:
# upload an ID document, get a real human at Connect It to review it,
# earn a "Verified Buyer" badge sellers can see on their orders. Kept
# as its own context on the existing KYCVerification model rather than
# a parallel table, per this project's "extend, don't recreate" rule.
# ════════════════════════════════════════════════════════════

def _buyer_is_id_verified(buyer_id):
    """True once a buyer has an approved manual-review record, OR a
    Smile Identity 'verified' automated result, on their own
    context='marketplace_buyer' submission. Used by the risk scan below
    and surfaced as a badge on ProductOrder.to_dict()."""
    row = (KYCVerification.query
           .filter_by(owner_id=buyer_id, context="marketplace_buyer")
           .filter(db.or_(KYCVerification.status == "approved", KYCVerification.verifier_result == "verified"))
           .first())
    return row is not None


def _seller_is_id_verified(seller_id):
    """STAGE 362: AML — used to decide whether a seller's payout can
    settle above the unverified-seller threshold. Unlike the buyer
    check above (scoped to context='marketplace_buyer'), this counts
    ANY approved KYC record for this account regardless of which
    product first collected it — a seller who's already completed ID
    verification for, say, Trade Credit Insurance or Factoring has
    genuinely proven who they are, and shouldn't have to redo it just
    because this particular check looks at a different context string."""
    row = (KYCVerification.query
           .filter_by(owner_id=seller_id)
           .filter(db.or_(KYCVerification.status == "approved", KYCVerification.verifier_result == "verified"))
           .first())
    return row is not None


@app.route("/api/marketplace/verify-identity", methods=["POST"])
@csrf.exempt
def marketplace_verify_identity_submit():
    """Buyer self-submits an ID document for the platform-wide Verified
    Buyer badge. Multipart (with an id_document file, optional selfie)
    or plain JSON without files — same acceptance pattern as
    kyc_submit(). One pending/approved submission at a time."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    account = UserAccount.query.get(user["id"])
    if not account:
        return jsonify({"error": "Account not found."}), 404

    existing = (KYCVerification.query
                .filter_by(owner_id=user["id"], context="marketplace_buyer")
                .filter(KYCVerification.status.in_(("pending", "approved")))
                .order_by(KYCVerification.created_at.desc()).first())
    if existing and existing.status == "approved":
        return jsonify({"error": "You're already ID-verified.", "verification": existing.to_dict()}), 400
    if existing and existing.status == "pending":
        return jsonify({"error": "Your last submission is still awaiting review.", "verification": existing.to_dict()}), 400

    if request.content_type and "multipart/form-data" in request.content_type:
        form = request.form
        id_type = (form.get("id_type") or "national_id").strip()
        id_number = (form.get("id_number") or "").strip()[:80] or None
    else:
        data = request.get_json(silent=True) or {}
        id_type = (data.get("id_type") or "national_id").strip()
        id_number = (data.get("id_number") or "").strip()[:80] or None
    if id_type not in ("national_id", "passport", "drivers_license"):
        id_type = "national_id"

    id_document_url = None
    selfie_url = None
    if request.files:
        if "id_document" in request.files and request.files["id_document"].filename:
            id_document_url = _upload_to_cloudinary(
                file_bytes=request.files["id_document"].read(), resource_type="image", folder="connect it/marketplace_kyc")
        if "selfie" in request.files and request.files["selfie"].filename:
            selfie_url = _upload_to_cloudinary(
                file_bytes=request.files["selfie"].read(), resource_type="image", folder="connect it/marketplace_kyc")
    if not id_document_url:
        return jsonify({"error": "A photo of your ID document is required."}), 400

    record = KYCVerification(
        owner_id=user["id"], subject_name=(account.name or "")[:120],
        subject_phone=getattr(account, "whatsapp_number", None),
        id_type=id_type, id_number=id_number,
        id_document_url=id_document_url, selfie_url=selfie_url,
        context="marketplace_buyer",
    )
    db.session.add(record)
    db.session.commit()
    return jsonify({
        "ok": True, "verification": record.to_dict(),
        "note": "Submitted for review by Connect It staff — you'll see your Verified Buyer badge once it's approved.",
    }), 201


