@app.route("/api/barter/offers/<int:offer_id>/respond", methods=["POST"])
@csrf.exempt
def barter_offer_respond(offer_id):
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    offer = BarterOffer.query.get(offer_id)
    if not offer:
        return jsonify({"error": "Offer not found."}), 404
    listing = BarterListing.query.get(offer.listing_id)
    if not listing or listing.user_id != user["id"]:
        return jsonify({"error": "Not authorized for this listing."}), 403
    data = request.get_json(silent=True) or {}
    status = (data.get("status") or "").strip()
    if status not in ("accepted", "declined"):
        return jsonify({"error": "status must be 'accepted' or 'declined'."}), 400
    offer.status = status
    if status == "accepted":
        listing.status = "matched"
        _ensure_deal_confirmation("barter", listing.id, listing.user_id, offer.offerer_id)
    db.session.commit()
    return jsonify({"ok": True, "offer": offer.to_dict(), "listing": listing.to_dict()}), 200


