@app.route("/api/consortiums", methods=["POST"])
@csrf.exempt
def consortium_create():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    title = (data.get("title") or "").strip()
    if not title:
        return jsonify({"error": "title is required."}), 400
    try:
        max_members = max(2, int(data.get("max_members", 5) or 5))
    except (TypeError, ValueError):
        max_members = 5
    target_value = None
    if data.get("target_contract_value") not in (None, ""):
        try:
            target_value = float(data["target_contract_value"])
        except (TypeError, ValueError):
            target_value = None

    consortium = Consortium(
        creator_id=user["id"], title=title[:200],
        description=(data.get("description") or "").strip()[:500] or None,
        target_contract_value=target_value,
        currency=(data.get("currency") or "USD").strip()[:8],
        max_members=max_members,
    )
    db.session.add(consortium)
    db.session.flush()
    # Creator automatically joins as the first member.
    creator_contribution = (data.get("creator_contribution") or "Consortium organizer").strip()[:200]
    db.session.add(ConsortiumMember(consortium_id=consortium.id, user_id=user["id"],
                                     role_contribution=creator_contribution))
    db.session.commit()
    return jsonify({"ok": True, "consortium": consortium.to_dict()}), 201


