    if not user:
        return jsonify({"error": "Login required."}), 401
    consortium = Consortium.query.get(consortium_id)
    if not consortium:
        return jsonify({"error": "Consortium not found."}), 404
    if consortium.status != "forming":
        return jsonify({"error": "This consortium is no longer accepting members."}), 400
    current_count = ConsortiumMember.query.filter_by(consortium_id=consortium.id).count()
    if current_count >= consortium.max_members:
        return jsonify({"error": "This consortium is already full."}), 400
    if ConsortiumMember.query.filter_by(consortium_id=consortium.id, user_id=user["id"]).first():
        return jsonify({"error": "You have already joined this consortium."}), 400
    data = request.get_json(silent=True) or {}
    contribution = (data.get("role_contribution") or "").strip()
    if not contribution:
        return jsonify({"error": "role_contribution is required — what will you bring?"}), 400
    member = ConsortiumMember(consortium_id=consortium.id, user_id=user["id"], role_contribution=contribution[:200])
    db.session.add(member)
    db.session.commit()
    return jsonify({"ok": True, "consortium": consortium.to_dict()}), 200


