@app.route("/api/deals/<int:deal_id>/confirm", methods=["POST"])
@csrf.exempt
def deal_confirm(deal_id):
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    deal = DealConfirmation.query.get(deal_id)
    if not deal or user["id"] not in (deal.party_a_id, deal.party_b_id):
        return jsonify({"error": "Deal not found."}), 404
    if deal.deal_type == "escrow":
        return jsonify({"error": "This deal is tied to an escrow — confirm receipt from the escrow itself, not here."}), 400
    if deal.status == "disputed":
        return jsonify({"error": "This deal is under dispute — resolve it before confirming."}), 400

    if user["id"] == deal.party_a_id:
        deal.party_a_confirmed = True
    else:
        deal.party_b_confirmed = True

    if deal.party_a_confirmed and deal.party_b_confirmed:
        deal.status = "confirmed"
        deal.confirmed_at = datetime.utcnow()
        # Reflect completion back onto the underlying record.
        if deal.deal_type == "barter":
            listing = BarterListing.query.get(deal.ref_id)
            if listing:
                listing.status = "completed"
        elif deal.deal_type == "delivery":
            req_row = DeliveryRequest.query.get(deal.ref_id)
            if req_row and req_row.status == "accepted":
                req_row.status = "completed"
                req_row.completed_at = datetime.utcnow()
                rider = DeliveryRider.query.get(req_row.rider_id)
                if rider:
                    rider.deliveries_completed += 1
    db.session.commit()
    return jsonify({"ok": True, "deal": deal.to_dict(viewer_id=user["id"])}), 200


@app.route("/api/deals/<int:deal_id>/dispute", methods=["POST"])
@csrf.exempt
def deal_dispute(deal_id):
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    deal = DealConfirmation.query.get(deal_id)
    if not deal or user["id"] not in (deal.party_a_id, deal.party_b_id):
        return jsonify({"error": "Deal not found."}), 404
    if deal.deal_type == "escrow":
        return jsonify({"error": "This deal is tied to an escrow — open the dispute from the escrow itself, not here."}), 400
    data = request.get_json(silent=True) or {}
    reason = (data.get("reason") or "").strip()
    if not reason:
        return jsonify({"error": "A reason is required to raise a dispute."}), 400
    deal.status = "disputed"
    deal.dispute_reason = reason[:300]
    db.session.commit()
    return jsonify({"ok": True, "deal": deal.to_dict(viewer_id=user["id"])}), 200


