@app.route("/api/esign/documents", methods=["POST"])
@csrf.exempt
def esign_document_create():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    title = (data.get("title") or "").strip()
    document_text = (data.get("document_text") or "").strip()
    signers_in = data.get("signers") or []
    if not title or not document_text:
        return jsonify({"error": "title and document_text are required."}), 400
    if not signers_in:
        return jsonify({"error": "At least one signer is required."}), 400

    doc = ESignDocument(owner_id=user["id"], title=title[:200], document_text=document_text)
    db.session.add(doc)
    db.session.flush()
    for s in signers_in:
        name = (s.get("name") or "").strip()
        if not name:
            continue
        signer = ESignSigner(
            document_id=doc.id, name=name[:120],
            email=(s.get("email") or "").strip()[:160] or None,
            phone=sanitize_phone(s.get("phone")) if s.get("phone") else None,
            sign_token=uuid.uuid4().hex + secrets.token_hex(8),
        )
        db.session.add(signer)
    db.session.commit()
    return jsonify({"ok": True, "document": doc.to_dict()}), 201


