@app.route("/api/esign/sign/<token>", methods=["GET"])
def esign_sign_view(token):
    """Public — a signer opens their unique link. No login required,
    since signers are frequently people outside the platform."""
    signer = ESignSigner.query.filter_by(sign_token=token).first()
    if not signer:
        return jsonify({"error": "Signing link not found or expired."}), 404
    doc = ESignDocument.query.get(signer.document_id)
    if not doc:
        return jsonify({"error": "Document not found."}), 404
    return jsonify({
        "document": {"id": doc.id, "title": doc.title, "document_text": doc.document_text, "status": doc.status},
        "signer": signer.to_dict(),
    }), 200


@app.route("/api/esign/sign/<token>", methods=["POST"])
@csrf.exempt
def esign_sign_submit(token):
    """Public — a signer submits their typed signature. Records IP and
    timestamp for a real audit trail."""
    signer = ESignSigner.query.filter_by(sign_token=token).first()
    if not signer:
        return jsonify({"error": "Signing link not found or expired."}), 404
    if signer.signed:
        return jsonify({"error": "This signature has already been submitted."}), 400
    doc = ESignDocument.query.get(signer.document_id)
    if not doc or doc.status == "voided":
        return jsonify({"error": "This document is no longer available for signature."}), 400

    data = request.get_json(silent=True) or {}
    signature_text = (data.get("signature_text") or "").strip()
    if not signature_text:
        return jsonify({"error": "signature_text (your typed full name) is required."}), 400

    signer.signed = True
    signer.signature_text = signature_text[:300]
    signer.signed_at = datetime.utcnow()
    signer.ip_address = request.headers.get("X-Forwarded-For", request.remote_addr or "")[:64]
    db.session.flush()

    remaining = ESignSigner.query.filter_by(document_id=doc.id, signed=False).count()
    if remaining == 0:
        doc.status = "completed"
    db.session.commit()
    return jsonify({"ok": True, "signer": signer.to_dict(), "document_status": doc.status}), 200


