@app.route("/api/admin/gratitude/<int:entry_id>", methods=["DELETE"])
@csrf.exempt
def admin_gratitude_delete(entry_id):
    """Admin-only moderation delete: unlike gratitude_delete above (which
    only lets the author remove their own post), this lets a recognized
    platform admin remove ANY Gratitude Gallery post that violates the
    rules. On removal, the "Connect It" agent automatically sends the
    author a warning notification explaining why their post was taken
    down, via the same real Notification system already used platform-
    wide (bell icon / Notifications panel) — no fabricated DM identity
    required."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    admin_user, err = _require_admin()
    if err:
        return err
    entry = GratitudeEntry.query.get(entry_id)
    if not entry:
        return jsonify({"error": "Post not found."}), 404

    data = request.get_json(silent=True) or {}
    reason = (data.get("reason") or "").strip()[:500]

    author_user_id = entry.user_id
    author_display = entry.user

    GalleryReaction.query.filter_by(entry_id=entry.id).delete()
    GalleryComment.query.filter_by(entry_id=entry.id).delete()
    db.session.delete(entry)
    db.session.commit()

    # Auto-send the warning — attributed to the Connect It agent — only
    # when the post actually belonged to a real signed-in account.
    # Anonymous/guest posts (author_user_id is None) have nowhere to
    # deliver a notification.
    if author_user_id:
        warning_body = (
            f"Your Gratitude Gallery post was removed by a Connect It moderator "
            f"for not following our community guidelines."
            + (f" Reason given: {reason}" if reason else "")
            + " Please review the guidelines before posting again — repeated "
              "violations may affect your account."
        )
        notify_user(
            author_user_id, module="gallery_moderation",
            title=f"{AI_DISPLAY_NAME} — Gallery post removed",
            body=warning_body,
        )

    logging.warning(
        f"[ADMIN GALLERY MODERATION] admin_id={admin_user.id} ({admin_user.email}) "
        f"deleted gratitude entry_id={entry_id} (author='{author_display}', "
        f"author_user_id={author_user_id}). Reason: {reason or '(none given)'}"
    )
    return jsonify({"ok": True, "notified": bool(author_user_id)}), 200


@app.route("/api/admin/gratitude/clear-all", methods=["POST"])
@csrf.exempt
def admin_gratitude_clear_all():
    """Admin-only: wipes every post currently in the Gratitude Gallery,
    including old entries created before reactions/comments existed
    (the ones with no delete button in the UI because they predate
    per-post ownership checks). This does NOT send individual warning
    notifications — it's a one-time cleanup of the whole board, not a
    per-post moderation action, so blasting every past poster with a
    notification would be noise, not a warning about their own conduct."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    admin_user, err = _require_admin()
    if err:
        return err
    deleted_count = GratitudeEntry.query.count()
    GalleryReaction.query.delete()
    GalleryComment.query.delete()
    GratitudeEntry.query.delete()
    db.session.commit()
    logging.warning(
        f"[ADMIN GALLERY MODERATION] admin_id={admin_user.id} ({admin_user.email}) "
        f"cleared the entire Gratitude Gallery ({deleted_count} posts removed)."
    )
    return jsonify({"ok": True, "deleted_count": deleted_count}), 200


@app.route("/api/gratitude/<int:entry_id>/react", methods=["POST"])
@csrf.exempt
def gratitude_react(entry_id):
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    entry = GratitudeEntry.query.get(entry_id)
    if not entry:
        return jsonify({"error": "Post not found."}), 404
    data = request.get_json(silent=True) or {}
    reaction = (data.get("reaction") or "").strip()
    if reaction not in ("like", "dislike"):
        return jsonify({"error": "reaction must be 'like' or 'dislike'."}), 400

    existing = GalleryReaction.query.filter_by(entry_id=entry.id, user_id=user["id"]).first()
    if existing and existing.reaction == reaction:
        db.session.delete(existing)  # tapping the same reaction again removes it
    elif existing:
        existing.reaction = reaction
    else:
        db.session.add(GalleryReaction(entry_id=entry.id, user_id=user["id"], reaction=reaction))
    db.session.commit()
    return jsonify({"ok": True, "entry": entry.to_dict(viewer_id=user["id"])}), 200


