@app.route("/api/habits/<int:habit_id>/checkin", methods=["POST"])
@csrf.exempt
def habits_checkin(habit_id):
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    habit = UserHabit.query.get(habit_id)
    if not habit or habit.user_id != user["id"]:
        return jsonify({"error": "Habit not found."}), 404
    today = datetime.utcnow().date()
    if habit.last_checkin == today:
        return jsonify({"error": "Already checked in today."}), 400
    if habit.last_checkin == today - timedelta(days=1):
        habit.streak += 1
    else:
        habit.streak = 1
    habit.last_checkin = today
    db.session.commit()
    return jsonify({"ok": True, "habit": habit.to_dict()}), 200


