@app.route("/api/budget", methods=["POST"])
@csrf.exempt
def budget_create():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    description = (data.get("description") or "").strip()
    try:
        amount = float(data.get("amount"))
    except (TypeError, ValueError):
        return jsonify({"error": "amount must be numeric."}), 400
    if not description or amount <= 0:
        return jsonify({"error": "description and a positive amount are required."}), 400
    kind = (data.get("kind") or "expense").strip()
    if kind not in ("income", "expense"):
        kind = "expense"
    entry_date = datetime.utcnow().date()
    if data.get("entry_date"):
        try:
            entry_date = datetime.fromisoformat(data["entry_date"]).date()
        except ValueError:
            pass
    entry = UserBudgetEntry(user_id=user["id"], description=description[:200], amount=amount, kind=kind, entry_date=entry_date)
    db.session.add(entry)
    db.session.commit()
    return jsonify({"ok": True, "entry": entry.to_dict()}), 201


