@app.route("/api/crm/contacts", methods=["GET"])
def crm_contacts_list():
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    stage = (request.args.get("stage") or "").strip()
    q = CrmContact.query.filter_by(user_id=user["id"])
    if stage and stage != "all":
        q = q.filter(CrmContact.stage == stage)
    rows = q.order_by(CrmContact.created_at.desc()).limit(300).all()
    return jsonify({"contacts": [c.to_dict() for c in rows]}), 200


@app.route("/api/crm/contacts", methods=["POST"])
@csrf.exempt
def crm_contact_create():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    name = (data.get("name") or "").strip()
    if not name:
        return jsonify({"error": "name is required."}), 400
    stage = (data.get("stage") or "lead").strip()
    if stage not in ("lead", "contacted", "negotiating", "won", "lost"):
        stage = "lead"
    contact = CrmContact(
        user_id=user["id"], name=name[:160],
        phone=sanitize_phone(data.get("phone")) if data.get("phone") else None,
        email=(data.get("email") or "").strip()[:160] or None,
        company=(data.get("company") or "").strip()[:160] or None,
        stage=stage, notes=(data.get("notes") or "").strip() or None,
    )
    db.session.add(contact)
    db.session.commit()
    return jsonify({"ok": True, "contact": contact.to_dict()}), 201


@app.route("/api/crm/contacts/<int:contact_id>", methods=["PUT"])
@csrf.exempt
def crm_contact_update(contact_id):
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    contact = CrmContact.query.get(contact_id)
    if not contact or contact.user_id != user["id"]:
        return jsonify({"error": "Contact not found."}), 404
    data = request.get_json(silent=True) or {}
    for field, maxlen in (("name", 160), ("company", 160), ("email", 160)):
        if data.get(field):
            setattr(contact, field, data[field].strip()[:maxlen])
    if data.get("phone"):
        contact.phone = sanitize_phone(data["phone"])
    if "notes" in data:
        contact.notes = (data["notes"] or "").strip() or None
    if data.get("stage") in ("lead", "contacted", "negotiating", "won", "lost"):
        contact.stage = data["stage"]
        contact.last_contacted = datetime.utcnow().date()
    db.session.commit()
    return jsonify({"ok": True, "contact": contact.to_dict()}), 200


@app.route("/api/crm/contacts/<int:contact_id>", methods=["DELETE"])
@csrf.exempt
def crm_contact_delete(contact_id):
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    contact = CrmContact.query.get(contact_id)
    if not contact or contact.user_id != user["id"]:
        return jsonify({"error": "Contact not found."}), 404
    db.session.delete(contact)
    db.session.commit()
    return jsonify({"ok": True}), 200


