def get_user_review_stats(user_id: int):
    """Real average rating + count, computed live from confirmed-deal
    reviews only. Returns None average when there are no reviews yet
    (never fabricate a starting score)."""
    rows = DealReview.query.filter_by(reviewee_id=user_id).all()
    if not rows:
        return {"average_rating": None, "review_count": 0}
    avg = sum(r.rating for r in rows) / len(rows)
    return {"average_rating": round(avg, 2), "review_count": len(rows)}


@app.route("/api/reviews/pending", methods=["GET"])
def reviews_pending():
    """Confirmed deals the viewer took part in but hasn't reviewed yet —
    drives a 'leave a review' prompt instead of making people hunt for it."""
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    confirmed = (DealConfirmation.query
                 .filter(DealConfirmation.status == "confirmed")
                 .filter(db.or_(DealConfirmation.party_a_id == user["id"], DealConfirmation.party_b_id == user["id"]))
                 .order_by(DealConfirmation.confirmed_at.desc()).limit(100).all())
    already_reviewed_ids = {r.deal_confirmation_id for r in
                             DealReview.query.filter_by(reviewer_id=user["id"]).all()}
    pending = []
    for deal in confirmed:
        if deal.id in already_reviewed_ids:
            continue
        other_id = deal.party_b_id if user["id"] == deal.party_a_id else deal.party_a_id
        other = UserAccount.query.get(other_id)
        pending.append({
            "deal_confirmation_id": deal.id, "deal_type": deal.deal_type, "ref_id": deal.ref_id,
            "other_party_id": other_id, "other_party_name": other.name if other else "A Connect It member",
            "confirmed_at": deal.confirmed_at.isoformat() if deal.confirmed_at else None,
        })
    return jsonify({"pending_reviews": pending}), 200


@app.route("/api/reviews/create", methods=["POST"])
@csrf.exempt
def review_create():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    deal_confirmation_id = data.get("deal_confirmation_id")
    rating = data.get("rating")
    comment = (data.get("comment") or "").strip()

    deal = DealConfirmation.query.get(deal_confirmation_id) if deal_confirmation_id else None
    if not deal:
        return jsonify({"error": "Deal not found."}), 404
    if deal.status != "confirmed":
        return jsonify({"error": "Reviews can only be left once both parties have confirmed the deal happened."}), 400
    if user["id"] not in (deal.party_a_id, deal.party_b_id):
        return jsonify({"error": "You weren't a party to this deal."}), 403
    try:
        rating = int(rating)
    except (TypeError, ValueError):
        return jsonify({"error": "Rating must be a whole number from 1 to 5."}), 400
    if rating < 1 or rating > 5:
        return jsonify({"error": "Rating must be between 1 and 5."}), 400

    existing = DealReview.query.filter_by(deal_confirmation_id=deal.id, reviewer_id=user["id"]).first()
    if existing:
        return jsonify({"error": "You've already reviewed this deal."}), 400

    reviewee_id = deal.party_b_id if user["id"] == deal.party_a_id else deal.party_a_id
    product_id = None
    if deal.deal_type == "product_order":
        order = ProductOrder.query.get(deal.ref_id)
        if order:
            product_id = order.product_id
    row = DealReview(
        deal_confirmation_id=deal.id, reviewer_id=user["id"], reviewee_id=reviewee_id,
        rating=rating, comment=comment[:600] or None, product_id=product_id,
    )
    db.session.add(row)
    db.session.commit()
    return jsonify({"ok": True, "review": row.to_dict()}), 201


@app.route("/api/products/<int:product_id>/reviews", methods=["GET"])
def product_reviews(product_id):
    """Product-level reviews — separate from a seller's overall Trust
    Score. Anyone can view these (no login required), same as browsing
    the listing itself."""
    rows = (DealReview.query.filter_by(product_id=product_id)
            .order_by(DealReview.created_at.desc()).limit(100).all())
    if not rows:
        return jsonify({"reviews": [], "average_rating": None, "review_count": 0}), 200
    avg = round(sum(r.rating for r in rows) / len(rows), 2)
    return jsonify({"reviews": [r.to_dict() for r in rows], "average_rating": avg, "review_count": len(rows)}), 200


@app.route("/api/reviews/user/<int:target_user_id>", methods=["GET"])
def reviews_for_user(target_user_id):
    rows = (DealReview.query.filter_by(reviewee_id=target_user_id)
            .order_by(DealReview.created_at.desc()).limit(100).all())
    stats = get_user_review_stats(target_user_id)
    return jsonify({"reviews": [r.to_dict() for r in rows], **stats}), 200


# ════════════════════════════════════════════════════════════
# STAGE 92: GOVERNMENT TENDER ALERT & AUTO-MATCH — ROUTES
# Real data, two real official sources, no fabricated listings.
# ════════════════════════════════════════════════════════════

def _strip_html_tags(raw: str) -> str:
    """Extracts visible page text for search/retrieval. Previously this
    only replaced tags with a space, which left the raw JavaScript/CSS
    inside <script>/<style> blocks as "text" — on any real webpage that
    JS/CSS soup dwarfs the actual page content, drowning out genuine
    words a Research Notebook question would need to match against.
    Script/style/comment blocks are now dropped entirely (tag AND
    contents) before the generic tag strip runs."""
    import html as _html_mod
    txt = raw or ""
    txt = re.sub(r"<!--.*?-->", " ", txt, flags=re.DOTALL)
    txt = re.sub(r"<script[^>]*>.*?</script>", " ", txt, flags=re.DOTALL | re.IGNORECASE)
    txt = re.sub(r"<style[^>]*>.*?</style>", " ", txt, flags=re.DOTALL | re.IGNORECASE)
    txt = re.sub(r"<noscript[^>]*>.*?</noscript>", " ", txt, flags=re.DOTALL | re.IGNORECASE)
    txt = re.sub(r"<[^>]+>", " ", txt)
    txt = _html_mod.unescape(txt)
    return re.sub(r"\s+", " ", txt).strip()


def _parse_praz_datetime(raw: str):
    """PRAZ dates look like '17-Oct-2025 07:00 PM'."""
    raw = (raw or "").strip()
    if not raw:
        return None
    for fmt in ("%d-%b-%Y %I:%M %p", "%d-%b-%Y"):
        try:
            return datetime.strptime(raw, fmt)
        except ValueError:
            continue
    return None


def fetch_praz_tenders(max_pages: int = 3):
    """Scrapes the official PRAZ eGP System 'Latest Tenders' board
    (egp.praz.org.zw) — Zimbabwe's real government e-procurement system.
    Table-row regex parsing, no bs4 dependency. Returns [] (never fake
    data) if the site is unreachable or its markup changes."""
    tenders = []
    headers = {"User-Agent": "Mozilla/5.0 (compatible; ConnectIt-TenderMonitor/1.0)"}
    try:
        for page in range(1, max_pages + 1):
            if page == 1:
                url = "https://egp.praz.org.zw/Indexes/index"
            else:
                url = (f"https://egp.praz.org.zw/index?url=egp-SW5kZXhlcy9pbmRleA=="
                       f"&page={page}&direction=BulletinBoardLive.id")
            resp = requests.get(url, timeout=20, headers=headers)
            if resp.status_code != 200:
                break
            rows = re.findall(r"<tr[^>]*>(.*?)</tr>", resp.text, re.S)
            page_had_tenders = False
            for row in rows:
                m = re.search(r"viewLiveTenderDetails/(\d+)", row)
                if not m:
                    continue
                tender_id = m.group(1)
                cells = re.findall(r"<td[^>]*>(.*?)</td>", row, re.S)
                if len(cells) < 8:
                    continue
                c = [_strip_html_tags(x) for x in cells]
                page_had_tenders = True
                tenders.append({
                    "external_id": tender_id,
                    "reference": c[1] if len(c) > 1 else "",
                    "title": c[2] if len(c) > 2 else ("Untitled tender #" + tender_id),
                    "description": None,
                    "category": c[4] if len(c) > 4 else (c[3] if len(c) > 3 else None),
                    "procuring_entity": c[5] if len(c) > 5 else None,
                    "publish_date": _parse_praz_datetime(c[7] if len(c) > 7 else ""),
                    "closing_date": _parse_praz_datetime(c[8] if len(c) > 8 else ""),
                    "value_amount": None, "value_currency": None,
                    "url": f"https://egp.praz.org.zw/Indexes/viewLiveTenderDetails/{tender_id}",
                })
            if not page_had_tenders:
                break
    except Exception as e:
        logging.error(f"[PRAZ TENDER FETCH ERROR] {e}")
    return tenders


def fetch_etenders_za(days_back: int = 5):
    """Pulls real, current tender releases from South Africa's National
    Treasury eTenders OCDS Public API (ocds-api.etenders.gov.za) — open
    government procurement data, official and free. Returns [] (never
    fake data) on any failure."""
    tenders = []
    try:
        date_to = datetime.utcnow().date()
        date_from = date_to - timedelta(days=days_back)
        resp = requests.get(
            "https://ocds-api.etenders.gov.za/api/OCDSReleases",
            params={"PageNumber": 1, "PageSize": 300,
                    "dateFrom": date_from.isoformat(), "dateTo": date_to.isoformat()},
            timeout=20, headers={"User-Agent": "Mozilla/5.0 (compatible; ConnectIt-TenderMonitor/1.0)"},
        )
        resp.raise_for_status()
        data = resp.json()
        for rel in (data.get("releases") or []):
            tender = rel.get("tender") or {}
            tid = tender.get("id") or rel.get("ocid")
            if not tid or not tender.get("title"):
                continue
            value = tender.get("value") or {}
            procuring = tender.get("procuringEntity") or {}
            period = tender.get("tenderPeriod") or {}
            closing = None
            for key in ("endDate",):
                raw = period.get(key)
                if raw:
                    try:
                        closing = datetime.fromisoformat(raw.replace("Z", "+00:00")).replace(tzinfo=None)
                    except Exception:
                        closing = None
            tenders.append({
                "external_id": str(tid),
                "reference": rel.get("ocid") or "",
                "title": tender.get("title") or "Untitled tender",
                "description": (tender.get("description") or "")[:1500] or None,
                "category": tender.get("mainProcurementCategory") or None,
                "procuring_entity": procuring.get("name") or None,
                "publish_date": None,
                "closing_date": closing,
                "value_amount": value.get("amount"),
                "value_currency": value.get("currency"),
                "url": "https://www.etenders.gov.za/",
            })
    except Exception as e:
        logging.error(f"[ETENDERS ZA FETCH ERROR] {e}")
    return tenders


def _tender_upsert_all():
    """Fetches both real sources and upserts into TenderListing. Returns
    (new_count, total_fetched). Idempotent — safe to run repeatedly."""
    new_count = 0
    fetched = []
    for row in fetch_praz_tenders():
        row["source"], row["country"] = "praz_zw", "ZW"
        fetched.append(row)
    for row in fetch_etenders_za():
        row["source"], row["country"] = "etenders_za", "ZA"
        fetched.append(row)

    for row in fetched:
        try:
            existing = TenderListing.query.filter_by(source=row["source"], external_id=row["external_id"]).first()
            if existing:
                existing.title = row["title"][:400]
                existing.closing_date = row["closing_date"]
                existing.fetched_at = datetime.utcnow()
                continue
            listing = TenderListing(
                source=row["source"], external_id=row["external_id"],
                reference=(row.get("reference") or "")[:160] or None,
                title=row["title"][:400], description=(row.get("description") or None),
                category=(row.get("category") or None), procuring_entity=(row.get("procuring_entity") or None),
                country=row["country"], closing_date=row.get("closing_date"), publish_date=row.get("publish_date"),
                value_amount=row.get("value_amount"), value_currency=row.get("value_currency"),
                url=row.get("url"),
            )
            db.session.add(listing)
            new_count += 1
        except Exception as e:
            logging.error(f"[TENDER UPSERT ERROR] {row.get('external_id')}: {e}")
    db.session.commit()
    return new_count, len(fetched)


def _tender_matches_subscription(listing, sub) -> bool:
    if sub.country and sub.country != listing.country:
        return False
    haystack = " ".join(filter(None, [listing.title, listing.description, listing.category])).lower()
    keywords = [k.strip().lower() for k in (sub.keywords or "").split(",") if k.strip()]
    return any(k in haystack for k in keywords)


@app.route("/api/tenders/search", methods=["GET"])
@requires_feature_flag("government_tender_alerts")
def tenders_search():
    """Searches already-fetched real tender listings — no login required,
    same as browsing a public tender board."""
    query = (request.args.get("query") or "").strip().lower()
    country = (request.args.get("country") or "").strip().upper() or None
    open_only = request.args.get("open_only", "true").lower() != "false"
    q = TenderListing.query
    if country in ("ZW", "ZA"):
        q = q.filter(TenderListing.country == country)
    if open_only:
        q = q.filter(db.or_(TenderListing.closing_date == None, TenderListing.closing_date > datetime.utcnow()))
    rows = q.order_by(TenderListing.closing_date.asc().nullslast()).limit(300).all()
    if query:
        rows = [r for r in rows if query in (r.title or "").lower()
                or query in (r.description or "").lower() or query in (r.category or "").lower()]
    return jsonify({"tenders": [r.to_dict() for r in rows[:100]],
                     "total_cached": TenderListing.query.count()}), 200


@app.route("/api/tenders/subscribe", methods=["POST"])
@csrf.exempt
@requires_feature_flag("government_tender_alerts")
def tender_subscribe():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    keywords = (data.get("keywords") or "").strip()
    if not keywords:
        return jsonify({"error": "At least one keyword is required, e.g. 'construction, fencing'."}), 400
    country = (data.get("country") or "").strip().upper() or None
