@app.route("/api/grants/matches", methods=["GET"])
def grants_matches():
    """Runs the logged-in user's active keyword subscriptions against
    real cached grant listings — the 'auto-match' half of the feature."""
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    subs = GrantAlertSubscription.query.filter_by(user_id=user["id"], active=True).all()
    if not subs:
        return jsonify({"matches": [], "note": "No active alert subscriptions yet."}), 200
    open_listings = (GrantListing.query
                     .filter(db.or_(GrantListing.submission_date == None, GrantListing.submission_date > datetime.utcnow()))
                     .order_by(GrantListing.submission_date.asc().nullslast()).limit(500).all())
    matches = []
    for listing in open_listings:
        for sub in subs:
            if _grant_matches_subscription(listing, sub):
                matches.append(dict(listing.to_dict(), matched_keywords=sub.keywords))
                break
    return jsonify({"matches": matches[:100]}), 200


@app.route("/api/grants/<int:grant_id>/draft-response", methods=["POST"])
@csrf.exempt
def grant_draft_response(grant_id):
    """Feeds a real fetched grant/funding notice into the AI for a
    first-pass expression-of-interest / proposal draft."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
