@app.route("/api/cron/grants-fetch", methods=["POST"])
@csrf.exempt
def cron_grants_fetch():
    """Scheduled refresh of real World Bank grant/funding data, then
    emails each subscriber whose keywords match anything newly fetched.
    Protected by CRON_SECRET, same pattern as the tenders cron job."""
    if not CRON_SECRET or request.headers.get("X-Cron-Secret") != CRON_SECRET:
        return jsonify({"error": "Not found."}), 404

    before_ids = {row.id for row in GrantListing.query.with_entities(GrantListing.id).all()}
    new_count, total_fetched = _grant_upsert_all()

    emails_sent = 0
    new_listings = GrantListing.query.filter(~GrantListing.id.in_(before_ids)).all() if before_ids else GrantListing.query.all()
    if new_listings:
        subs = GrantAlertSubscription.query.filter_by(active=True).all()
        by_user = {}
        for sub in subs:
            for listing in new_listings:
                if _grant_matches_subscription(listing, sub):
                    by_user.setdefault(sub.user_id, []).append(listing)
        for user_id, listings in by_user.items():
            u = UserAccount.query.get(user_id)
            if not u or not u.email:
                continue
            lines = [f"- {l.title} ({l.country or 'Multiple countries'}) — closes "
                     f"{l.submission_date.strftime('%d %b %Y') if l.submission_date else 'TBC'}\n  {l.url}"
                     for l in listings[:10]]
            body = ("New grants/funding opportunities matching your alerts:\n\n" + "\n\n".join(lines) +
                    "\n\nOpen Connect It → Global Grants Matcher to see full details and draft a response.")
            if _send_plain_email(u.email, "New Funding Opportunities Matching Your Alerts — Connect It", body):
                emails_sent += 1

    return jsonify({"ok": True, "new_grants": new_count, "total_fetched": total_fetched, "emails_sent": emails_sent}), 200


# ════════════════════════════════════════════════════════════
# STAGE 171: AI NEGOTIATION ASSISTANT — ROUTES
# Drafts an opening position (target / acceptable / walk-away) for
# any negotiation, then lets the owner stress-test it against an AI
# playing the counterparty before the real conversation happens.
# ════════════════════════════════════════════════════════════

def _negotiation_user_or_401():
    user = _get_current_user()
    if not user:
        return None, (jsonify({"error": "Login required."}), 401)
    return user, None


@app.route("/api/negotiation/sessions", methods=["POST"])
@csrf.exempt
def negotiation_session_create():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _negotiation_user_or_401()
    if err:
        return err
    data = request.get_json(silent=True) or {}
    subject = (data.get("subject") or "").strip()
    if not subject:
        return jsonify({"error": "subject is required, e.g. 'Renewing our warehouse lease'."}), 400
    counterparty = (data.get("counterparty") or "").strip()[:200] or None
    our_goals = (data.get("our_goals") or "").strip()[:2000] or None
    context = (data.get("context") or "").strip()[:2000] or None

    gate_result = gate_ai_usage(user, "negotiation_session_create")
    if gate_result is not None:
        return gate_result

    prompt = (
        f"You are a skilled negotiation coach advising a small business owner, anywhere in the world. "
        f"Subject of negotiation: {subject}\n"
        f"Counterparty: {counterparty or 'not specified'}\n"
        f"Our goals: {our_goals or 'not specified'}\n"
        f"Background/context: {context or 'not specified'}\n\n"
        f"Reply with ONLY raw JSON, no markdown fences, shaped exactly like: "
        '{"target": "our ideal outcome, one or two sentences", '
        '"acceptable": "a fallback outcome we would still accept, one or two sentences", '
        '"walk_away": "the point below which we should walk away, one or two sentences", '
        '"opening_message": "a short, professional opening message we could actually send to the counterparty, '
        'ready to use, 3-6 sentences"}'
    )
    raw, _ = generate_ai_reply(prompt, [])
    try:
        text = re.sub(r"^```(?:json)?\s*", "", (raw or "").strip())
        text = re.sub(r"\s*```$", "", text)
        opening_position = json.loads(text)
    except Exception:
        opening_position = {"opening_message": raw}

    try:
        session = NegotiationSession(
            owner_user_id=user["id"], counterparty=counterparty, subject=subject[:300],
            our_goals=our_goals, context=context,
            opening_position_json=json.dumps(opening_position), transcript_json=json.dumps([]),
        )
        db.session.add(session); db.session.commit()
    except Exception as e:
        db.session.rollback(); logging.error(f"[NEGOTIATION SESSION CREATE] {e}")
        return jsonify({"error": "Could not start the negotiation session."}), 500
    return jsonify({"session": session.to_dict()}), 201


