@app.route("/api/negotiation/sessions/<int:session_id>/simulate", methods=["POST"])
@csrf.exempt
def negotiation_session_simulate(session_id):
    """Two modes: pass counterparty_reply (what they actually said) to
    get a suggested response; leave it blank to have the AI play a
    realistic, moderately tough counterparty first, so the owner can
    rehearse before the real conversation."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _negotiation_user_or_401()
    if err:
        return err
    session = NegotiationSession.query.filter_by(id=session_id, owner_user_id=user["id"]).first()
    if not session:
        return jsonify({"error": "Session not found."}), 404
    data = request.get_json(silent=True) or {}
    counterparty_reply = (data.get("counterparty_reply") or "").strip()
    gate_result = gate_ai_usage(user, "negotiation_session_simulate")
    if gate_result is not None:
        return gate_result
    transcript = json.loads(session.transcript_json) if session.transcript_json else []
    opening = json.loads(session.opening_position_json) if session.opening_position_json else {}

    history_text = "\n".join(f"{m['role']}: {m['content']}" for m in transcript[-10:])

    if not counterparty_reply:
        prompt = (
            f"Play the counterparty in this negotiation — realistic and moderately tough, not a pushover, "
            f"but not unreasonable either. Subject: {session.subject}. "
            f"Counterparty: {session.counterparty or 'not specified'}. "
            f"Our opening message was: {opening.get('opening_message', '')}\n"
            f"Conversation so far:\n{history_text}\n\n"
            f"Reply with ONLY the counterparty's next message — no labels, no notes, 2-5 sentences."
        )
        reply_raw, _ = generate_ai_reply(prompt, [])
        transcript.append({"role": "counterparty", "content": reply_raw.strip()})
        session.transcript_json = json.dumps(transcript)
        db.session.commit()
        return jsonify({"session": session.to_dict()}), 200

    transcript.append({"role": "counterparty", "content": counterparty_reply})
    prompt = (
        f"You are coaching a small business owner through this live negotiation. "
        f"Subject: {session.subject}. Our target: {opening.get('target', '')}. "
        f"Our acceptable fallback: {opening.get('acceptable', '')}. "
        f"Our walk-away point: {opening.get('walk_away', '')}.\n"
        f"Conversation so far:\n{history_text}\n"
        f"counterparty: {counterparty_reply}\n\n"
        f"Suggest the owner's next message: professional, advances toward our target without breaching our "
        f"walk-away point, 3-6 sentences. Then on a new line starting with 'COACH NOTE:', add one short "
        f"sentence flagging anything in the counterparty's message the owner should watch out for."
    )
    advice_raw, _ = generate_ai_reply(prompt, [])
    transcript.append({"role": "advisor", "content": advice_raw.strip()})
    session.transcript_json = json.dumps(transcript)
    db.session.commit()
    return jsonify({"session": session.to_dict()}), 200


# ════════════════════════════════════════════════════════════
# STAGE 96: CURRENCY VOLATILITY PRICING ADVISOR — ROUTES
# Model is FxVolatilityAdvisorSetting (see near the other STAGE 96
# comment, above the PivotCommandLog model). Uses the same free,
# no-key open.er-api.com source as the ERP exchange-rate setting, via
# _fetch_live_fx_rate(). Products come straight from InventoryItem
# (unit_price) — no separate product table, matching the ERP pattern.
# ════════════════════════════════════════════════════════════

def _fx_advisor_row(uid, create_if_missing=True):
    row = FxVolatilityAdvisorSetting.query.filter_by(owner_user_id=uid).first()
    if not row and create_if_missing:
        row = FxVolatilityAdvisorSetting(owner_user_id=uid)
        db.session.add(row); db.session.commit()
    return row


def _fx_advisor_compute(row, live_rate):
    """Shared math for the status/refresh/cron endpoints: how far has
    home_currency depreciated against USD since the anchor rate was
    captured, and what would each priced product cost today if it were
    repriced to keep pace. Returns None for drift fields if there's no
    anchor yet (first-time use)."""
    drift_pct = None
    lagging = False
    if row.anchor_rate and live_rate:
        # A HIGHER "currency units per USD" rate means the currency has
        # weakened — that's depreciation, and local prices set against
        # the old (lower) rate are now worth fewer real USD.
        drift_pct = round((live_rate - row.anchor_rate) / row.anchor_rate * 100, 2)
        lagging = drift_pct >= (row.alert_threshold_pct or 5.0)

    products = []
    if drift_pct is not None and drift_pct > 0:
        items = (InventoryItem.query
                 .filter_by(user_id=row.owner_user_id, active=True)
                 .filter(InventoryItem.unit_price.isnot(None))
                 .order_by(InventoryItem.name.asc()).limit(200).all())
        for it in items:
            suggested = round(it.unit_price * (1 + drift_pct / 100), 2)
            if suggested > it.unit_price:
                products.append({
                    "id": it.id, "name": it.name,
                    "current_price": it.unit_price,
                    "suggested_price": suggested,
                    "shortfall": round(suggested - it.unit_price, 2),
                })

    return {
        "home_currency": row.home_currency,
        "alert_threshold_pct": row.alert_threshold_pct,
        "anchor_rate": row.anchor_rate,
        "anchor_captured_at": row.anchor_captured_at.isoformat() if row.anchor_captured_at else None,
        "live_rate": live_rate,
        "checked_at": datetime.utcnow().isoformat(),
        "drift_pct": drift_pct,
        "lagging": lagging,
        "needs_anchor": row.anchor_rate is None,
        "products_lagging": products,
        "products_lagging_count": len(products),
    }


@app.route("/api/fx-advisor/settings", methods=["GET"])
def fx_advisor_settings_get():
    user, err = _erp_user_or_401()
    if err: return err
    row = _fx_advisor_row(user["id"])
    return jsonify(row.to_dict()), 200


@app.route("/api/fx-advisor/settings", methods=["PUT"])
@csrf.exempt
def fx_advisor_settings_set():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    row = _fx_advisor_row(user["id"])
    currency = (data.get("home_currency") or "").strip().upper()
    if currency:
        row.home_currency = currency[:8]
    if "alert_threshold_pct" in data:
        try:
            pct = float(data.get("alert_threshold_pct"))
            if pct <= 0: raise ValueError
            row.alert_threshold_pct = pct
        except Exception:
            return jsonify({"error": "alert_threshold_pct must be a positive number."}), 400
    db.session.commit()
    return jsonify(row.to_dict()), 200


@app.route("/api/fx-advisor/status", methods=["GET"])
def fx_advisor_status():
    """Live check — does NOT change the anchor. Safe to call as often
    as the panel likes (e.g. every time it's opened)."""
    user, err = _erp_user_or_401()
    if err: return err
    row = _fx_advisor_row(user["id"])
    live_rate = _fetch_live_fx_rate(row.home_currency)
    if live_rate is None:
        return jsonify({
            "error": f"Live {row.home_currency} rate isn't available from our FX source right now.",
            "fetched": False,
            "home_currency": row.home_currency,
            "anchor_rate": row.anchor_rate,
            "needs_anchor": row.anchor_rate is None,
        }), 502
    row.last_checked_rate = live_rate
    row.last_checked_at = datetime.utcnow()
    db.session.commit()
    return jsonify(_fx_advisor_compute(row, live_rate)), 200


@app.route("/api/fx-advisor/confirm-repriced", methods=["POST"])
@csrf.exempt
def fx_advisor_confirm_repriced():
    """User has just reviewed/updated their price list to match today's
    real cost — resets the anchor to the current live rate so future
    drift is measured from here, not from whenever they first set up
    the advisor."""
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    row = _fx_advisor_row(user["id"])
    live_rate = _fetch_live_fx_rate(row.home_currency)
    if live_rate is None:
        return jsonify({"error": f"Live {row.home_currency} rate isn't available right now — try again shortly."}), 502
    row.anchor_rate = live_rate
    row.anchor_captured_at = datetime.utcnow()
    row.last_checked_rate = live_rate
    row.last_checked_at = datetime.utcnow()
    row.last_alert_sent_at = None
    db.session.commit()
    return jsonify(row.to_dict()), 200


@app.route("/api/cron/fx-advisor-check", methods=["POST"])
@csrf.exempt
def cron_fx_advisor_check():
    """Scheduled sweep across every business using the advisor — emails
    once per breach (throttled via last_alert_sent_at) when their home
    currency has depreciated past their threshold since the last
    confirmed repricing. Protected by CRON_SECRET, same as the other
    scheduled tasks — see the PythonAnywhere Scheduled Task setup near
    the CRON_SECRET constant near the top of this file."""
    if not CRON_SECRET or request.headers.get("X-Cron-Secret") != CRON_SECRET:
        return jsonify({"error": "Not found."}), 404

    rows = FxVolatilityAdvisorSetting.query.filter(FxVolatilityAdvisorSetting.anchor_rate.isnot(None)).all()
    checked = 0
    alerted = 0
    for row in rows:
        live_rate = _fetch_live_fx_rate(row.home_currency)
        if live_rate is None:
            continue
        checked += 1
        row.last_checked_rate = live_rate
        row.last_checked_at = datetime.utcnow()
        status = _fx_advisor_compute(row, live_rate)
        if status["lagging"] and not row.last_alert_sent_at:
            u = UserAccount.query.get(row.owner_user_id)
            if u and u.email:
                body = (
                    f"Your {row.home_currency} has weakened {status['drift_pct']}% against the USD "
                    f"since you last confirmed your price list "
                    f"({row.anchor_captured_at.strftime('%d %b %Y') if row.anchor_captured_at else 'unknown date'}).\n\n"
                    f"{status['products_lagging_count']} priced product(s) may be under-priced relative to today's rate.\n\n"
                    "Open Connect It → Currency Volatility Pricing Advisor to review suggested prices "
                    "and confirm once you've repriced."
                )
                if _send_plain_email(u.email, f"Your {row.home_currency} prices may be lagging — Connect It", body):
                    row.last_alert_sent_at = datetime.utcnow()
                    alerted += 1
        db.session.commit()

    return jsonify({"ok": True, "checked": checked, "alerts_sent": alerted}), 200


def _send_sms_simple(to_phone: str, body: str) -> bool:
    """Plain (non-WhatsApp) SMS via Twilio, for invoice-chase nudges and
    inbox replies. Mirrors the ad-hoc Twilio client pattern used
    elsewhere in this file rather than assuming a single shared client."""
    if not (TWILIO_AVAILABLE and TWILIO_ACCOUNT_SID and TWILIO_AUTH_TOKEN and TWILIO_PHONE_NUMBER and to_phone):
        logging.info(f"[SMS SKIPPED — Twilio not configured] to {to_phone}: {body[:60]}")
        return False
    try:
        client = TwilioClient(TWILIO_ACCOUNT_SID, TWILIO_AUTH_TOKEN)
        client.messages.create(from_=TWILIO_PHONE_NUMBER, to=to_phone, body=body)
        return True
    except Exception as e:
        logging.error(f"[SMS SEND] {to_phone}: {e}")
        return False


def _inbox_log(owner_user_id, channel, contact_identifier, direction, body, contact_name=None, wa_message_id=None):
    try:
        msg = UnifiedInboxMessage(
            owner_user_id=owner_user_id, channel=channel, contact_identifier=(contact_identifier or "")[:200],
            contact_name=contact_name, direction=direction, body=body[:4000],
            wa_message_id=(wa_message_id or "")[:128] or None,
            read_at=datetime.utcnow() if direction == "out" else None,
        )
        db.session.add(msg); db.session.commit()
        return msg
    except Exception as e:
        db.session.rollback(); logging.error(f"[INBOX LOG] {e}")
        return None


# ════════════════════════════════════════════════════════════
# STAGE 97/500: DIGITAL POS / TILL — ROUTES
# ════════════════════════════════════════════════════════════

def _pos_emit(event, payload, till_id=None, owner_user_id=None):
    """Broadcasts a real-time update to a till's customer display / other
    registers watching it, and/or to the owner's multi-till dashboard.
    No-op if flask-socketio isn't installed — every caller already has a
    complete REST response, so nothing is lost, it just won't be
    real-time for anyone else watching."""
    if not FLASK_SOCKETIO_AVAILABLE or not socketio_app:
        return
    try:
        if till_id:
            socketio_app.emit(event, payload, room=f"pos_till_{till_id}", namespace="/pos")
        if owner_user_id:
            socketio_app.emit(event, payload, room=f"pos_owner_{owner_user_id}", namespace="/pos")
    except Exception as e:
        logging.error(f"[POS WS EMIT] {e}")


def _pos_process_sale(user, data):
    """Shared checkout logic used by both the live register
    (/api/pos/checkout) and the offline-queue replay (/api/pos/sync) —
    one code path so a sale rung up while offline is validated and
    posted exactly the same way as one rung up live.

    Idempotency: if the caller sent a client_txn_id (generated on the
    device BEFORE the request leaves it — see posCheckout() in the
    frontend), a duplicate replay of the same request (e.g. the offline
    queue retrying a request whose response got lost) returns the
    already-created sale instead of ringing it up twice.

    Returns (response_dict, status_code).
    """
    cart = data.get("items") or []
    if not cart:
        return {"error": "Cart is empty."}, 400

    client_txn_id = (data.get("client_txn_id") or "").strip()[:64] or None
    if client_txn_id:
        existing = PosSale.query.filter_by(owner_user_id=user["id"], client_txn_id=client_txn_id).first()
        if existing:
            return {"sale": existing.to_dict(include_items=True, include_tenders=True),
                    "loyalty_note": None, "duplicate": True}, 200

    currency = (data.get("currency") or "USD").strip().upper()[:8]
    payment_method = (data.get("payment_method") or "cash").strip().lower()
    employee_id = data.get("employee_id")
    customer_id = data.get("customer_id")
    till_id = data.get("till_id")
    till_session_id = data.get("till_session_id")

    till_session = None
    if till_session_id:
        till_session = PosTillSession.query.get(till_session_id)
        if not till_session or till_session.owner_user_id != user["id"]:
            return {"error": "Till session not found."}, 404
        if till_session.status != "open":
            return {"error": "That till session is already closed — open a new one to keep selling."}, 409
        if not till_id:
            till_id = till_session.till_id

    line_items = []
    subtotal = 0.0
    stock_updates = []
    for line in cart:
        try:
            qty = float(line.get("quantity") or 0)
        except Exception:
            qty = 0
        if qty <= 0:
            continue
        product = InventoryItem.query.get(line.get("product_id")) if line.get("product_id") else None
        if product and product.user_id == user["id"]:
            if (product.quantity or 0) < qty:
                return {"error": f"Not enough stock for '{product.name}' — only {product.quantity} left."}, 400
            unit_price = product.unit_price if product.unit_price is not None else float(line.get("unit_price") or 0)
            desc = product.name
            stock_updates.append((product, qty))
        else:
            unit_price = float(line.get("unit_price") or 0)
            desc = (line.get("description") or "Item").strip()[:300]
        line_total = round(unit_price * qty, 2)
        subtotal += line_total
        line_items.append({"product_id": product.id if product else None, "description": desc,
                            "quantity": qty, "unit_price": unit_price, "line_total": line_total})

    if not line_items:
        return {"error": "No valid items in cart."}, 400

    tax_rate = float(data.get("tax_rate") or 0)
    tax_amount = round(subtotal * tax_rate / 100, 2)
    total = round(subtotal + tax_amount, 2)

    # Split tender: a list of {method, amount[, reference]} lines that
    # must add up to the sale total. Falls back to the original
    # single-method shape (payment_method + amount_tendered) when the
    # caller doesn't send tenders — every existing integration/frontend
    # call keeps working unchanged.
    tenders_in = data.get("tenders")
    tendered = data.get("amount_tendered")
    tendered = float(tendered) if tendered not in (None, "") else None
    change_due = None
    tender_rows = []
    if isinstance(tenders_in, list) and tenders_in:
        tender_total = 0.0
        for t in tenders_in:
            try:
                amt = round(float(t.get("amount") or 0), 2)
            except Exception:
                amt = 0
            method = (t.get("method") or "cash").strip().lower()[:20]
            if amt <= 0:
                continue
            tender_total += amt
            tender_rows.append({"method": method, "amount": amt, "reference": (t.get("reference") or "").strip()[:120] or None})
        if not tender_rows:
            return {"error": "At least one tender line with a positive amount is required."}, 400
        if round(tender_total, 2) < total - 0.01:
            return {"error": f"Tenders add up to {currency} {round(tender_total,2)}, short of the {currency} {total} total."}, 400
        change_due = round(tender_total - total, 2)
        payment_method = "split" if len(tender_rows) > 1 else tender_rows[0]["method"]
        if tender_rows[0]["method"] == "cash":
            tendered = tender_total
    else:
        change_due = round(tendered - total, 2) if tendered is not None else None
        tender_rows = [{"method": payment_method, "amount": total, "reference": None}]

    sale = PosSale(
        owner_user_id=user["id"], sale_number=f"POS-{datetime.utcnow().strftime('%y%m%d')}-{secrets.token_hex(3).upper()}",
        employee_id=employee_id, customer_id=customer_id, currency=currency,
        subtotal=round(subtotal, 2), tax_amount=tax_amount, total=total,
        payment_method=payment_method, amount_tendered=tendered, change_due=change_due,
        till_id=till_id, till_session_id=till_session_id, client_txn_id=client_txn_id,
    )
    db.session.add(sale); db.session.flush()
    for li in line_items:
        db.session.add(PosSaleItem(sale_id=sale.id, **li))
    for tr in tender_rows:
        db.session.add(PosSaleTender(sale_id=sale.id, method=tr["method"], amount=tr["amount"], reference=tr["reference"]))
    for product, qty in stock_updates:
        product.quantity = (product.quantity or 0) - qty
    db.session.add(ErpLedgerEntry(
        owner_user_id=user["id"], entry_date=datetime.utcnow().date(), kind="revenue", account="POS Sales",
        description=f"POS sale {sale.sale_number}", amount=total, reference_type="pos_sale", reference_id=sale.id,
    ))

    loyalty_note = None
    customer_phone = (data.get("customer_phone") or "").strip()
    if customer_phone:
        lc = LoyaltyCustomer.query.filter_by(phone=customer_phone).first()
        if lc:
            program = LoyaltyProgram.query.get(lc.program_id)
            earned = (program.points_per_visit if program else 1)
            lc.balance += earned; lc.total_earned += earned
            db.session.add(LoyaltyTransaction(customer_id=lc.id, kind="earn", amount=earned, note=f"POS sale {sale.sale_number}"))
            loyalty_note = f"+{earned} loyalty points"

    try:
        db.session.commit()
    except IntegrityError:
        # Two near-simultaneous requests carrying the same client_txn_id
        # (e.g. a double-tap Checkout while the first request was still
        # in flight) — the unique index caught it, not a real failure.
        db.session.rollback()
        if client_txn_id:
            existing = PosSale.query.filter_by(owner_user_id=user["id"], client_txn_id=client_txn_id).first()
            if existing:
                return {"sale": existing.to_dict(include_items=True, include_tenders=True),
                        "loyalty_note": None, "duplicate": True}, 200
        return {"error": "Could not complete this sale — please retry."}, 409

    result = {"sale": sale.to_dict(include_items=True, include_tenders=True), "loyalty_note": loyalty_note}
    _pos_emit("sale_completed", result["sale"], till_id=till_id, owner_user_id=user["id"])
    return result, 201


@app.route("/api/pos/checkout", methods=["POST"])
@csrf.exempt
def pos_checkout():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    result, status = _pos_process_sale(user, data)
    return jsonify(result), status


@app.route("/api/pos/sync", methods=["POST"])
@csrf.exempt
def pos_sync_offline_queue():
    """Batch replay endpoint for sales rung up while the till device had
    no connection (see the frontend's queuedFetch()/_offlineReplayQueue()
    in Stage 118, and posQueueOfflineSale() below which uses this
    instead of the generic queue so several offline sales can be sent —
    and deduplicated by client_txn_id — in one request once back online).
    Each sale is processed independently so one bad line doesn't block
    the rest of the batch from posting."""
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    sales_in = data.get("sales") or []
    if not isinstance(sales_in, list) or not sales_in:
        return jsonify({"error": "sales must be a non-empty list."}), 400
    results = []
    for sale_data in sales_in[:50]:
        result, status = _pos_process_sale(user, sale_data or {})
        results.append({
            "client_txn_id": (sale_data or {}).get("client_txn_id"),
            "ok": status < 400, "status": status,
            "sale_id": (result.get("sale") or {}).get("id") if status < 400 else None,
            "duplicate": result.get("duplicate", False), "error": result.get("error"),
        })
    synced = sum(1 for r in results if r["ok"])
    return jsonify({"ok": True, "synced": synced, "failed": len(results) - synced, "results": results}), 200


