@app.route("/api/pos/sales/<int:sale_id>/receipt", methods=["GET"])
def pos_sale_receipt(sale_id):
    user, err = _erp_user_or_401()
    if err: return err
    sale = PosSale.query.get(sale_id)
    if not sale or sale.owner_user_id != user["id"]:
        return jsonify({"error": "Sale not found."}), 404
    items = PosSaleItem.query.filter_by(sale_id=sale.id).all()
    tenders = PosSaleTender.query.filter_by(sale_id=sale.id).all()
    lines = [f"{i.description} x{i.quantity} @ {sale.currency} {i.unit_price} = {sale.currency} {i.line_total}" for i in items]
    tender_lines = [f"{t.method}: {sale.currency} {t.amount}" for t in tenders] if len(tenders) > 1 else []
    receipt = (
        (f"REFUND / RETURN\n" if sale.is_return else "") +
        f"Receipt {sale.sale_number}\n{sale.created_at.strftime('%d %b %Y %H:%M')}\n\n" +
        "\n".join(lines) +
        f"\n\nSubtotal: {sale.currency} {sale.subtotal}\nTax: {sale.currency} {sale.tax_amount}\n" +
        f"TOTAL: {sale.currency} {sale.total}\nPaid via {sale.payment_method}" +
        ("\n" + "\n".join(tender_lines) if tender_lines else "") +
        (f"\nTendered: {sale.currency} {sale.amount_tendered}\nChange: {sale.currency} {sale.change_due}" if sale.amount_tendered is not None else "")
    )
    branding = BusinessBranding.query.filter_by(owner_user_id=user["id"]).first()
    if branding and branding.footer_text:
        receipt += f"\n\n{branding.footer_text}"
    return jsonify({"receipt_text": receipt, "sale": sale.to_dict(include_items=True, include_tenders=True)}), 200


@app.route("/api/pos/till/<int:till_id>/cart-preview", methods=["POST"])
@csrf.exempt
def pos_cart_preview(till_id):
    """Pushes the register's current (not-yet-finalized) cart to anyone
    watching this till — the customer-facing display and any other
    register dashboards — without persisting anything. Called on every
    cart change from the register screen; a no-op response if nobody's
    watching (see _pos_emit)."""
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    till = PosTill.query.get(till_id)
    if not till or till.owner_user_id != user["id"]:
        return jsonify({"error": "Till not found."}), 404
    data = request.get_json(silent=True) or {}
    _pos_emit("cart_update", {
        "till_id": till_id, "items": data.get("items") or [],
        "subtotal": data.get("subtotal"), "tax_amount": data.get("tax_amount"), "total": data.get("total"),
    }, till_id=till_id)
    return jsonify({"ok": True}), 200


