# ---- Shift / cashier login + till-level audit trail ----

@app.route("/api/pos/till/open", methods=["POST"])
@csrf.exempt
def pos_till_open():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    blocked = require_plan(user, "pos")
    if blocked: return blocked
    data = request.get_json(silent=True) or {}
    till_id = data.get("till_id")
    till = PosTill.query.get(till_id) if till_id else None
    if not till or till.owner_user_id != user["id"]:
        return jsonify({"error": "Select a valid till (create one first if you haven't)."}), 404
    already_open = PosTillSession.query.filter_by(till_id=till.id, status="open").first()
    if already_open:
        return jsonify({"error": f"{till.name} already has an open shift — close it before starting a new one."}), 409
    employee_id = data.get("employee_id")
    if employee_id:
        employee = ErpEmployee.query.get(employee_id)
        if not employee or employee.owner_user_id != user["id"]:
            return jsonify({"error": "Employee not found."}), 404
    try:
        opening_float = float(data.get("opening_float") or 0)
    except Exception:
        opening_float = 0
    session_row = PosTillSession(
        owner_user_id=user["id"], till_id=till.id, employee_id=employee_id,
        cashier_name=(data.get("cashier_name") or "").strip()[:120] or None,
        opening_float=round(opening_float, 2), opening_note=(data.get("opening_note") or "").strip()[:300] or None,
    )
    db.session.add(session_row); db.session.commit()
    _pos_emit("till_opened", session_row.to_dict(), till_id=till.id, owner_user_id=user["id"])
    return jsonify({"session": session_row.to_dict()}), 201


@app.route("/api/pos/till/<int:session_id>/close", methods=["POST"])
@csrf.exempt
def pos_till_close(session_id):
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    session_row = PosTillSession.query.get(session_id)
    if not session_row or session_row.owner_user_id != user["id"]:
        return jsonify({"error": "Till session not found."}), 404
    if session_row.status != "open":
        return jsonify({"error": "This shift is already closed."}), 409
    data = request.get_json(silent=True) or {}
    try:
        counted = float(data.get("counted_cash"))
    except Exception:
        return jsonify({"error": "counted_cash is required (physical cash count for this drawer)."}), 400
    summary = session_row.summary()
    session_row.closing_counted_cash = round(counted, 2)
    session_row.closing_expected_cash = summary["expected_cash"]
    session_row.closing_variance = round(counted - summary["expected_cash"], 2)
    session_row.closing_note = (data.get("note") or "").strip()[:300] or None
    session_row.status = "closed"
    session_row.closed_at = datetime.utcnow()
    db.session.commit()
    _pos_emit("till_closed", session_row.to_dict(), till_id=session_row.till_id, owner_user_id=user["id"])
    return jsonify({"session": session_row.to_dict()}), 200


