@app.route("/api/pos/returns", methods=["POST"])
@csrf.exempt
def pos_return_create():
    """Processes a return or exchange against a real original PosSale:
    restocks Inventory (unless flagged not to — e.g. damaged goods),
    posts a refund PosSale (is_return=True) so the ledger and till
    reconciliation both see it, and logs a PosReturn audit row. For an
    exchange, ring up the replacement item(s) as a normal
    /api/pos/checkout call afterwards (pass the same till_session_id) —
    kind='exchange' here is for reporting; the two transactions stay
    independently auditable rather than silently netted together."""
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    original = PosSale.query.get(data.get("original_sale_id"))
    if not original or original.owner_user_id != user["id"]:
        return jsonify({"error": "Original sale not found."}), 404
    if original.is_return:
        return jsonify({"error": "Can't return a refund transaction."}), 400

    sale_item = None
    sale_item_id = data.get("sale_item_id")
    if sale_item_id:
        sale_item = PosSaleItem.query.get(sale_item_id)
        if not sale_item or sale_item.sale_id != original.id:
            return jsonify({"error": "That line item doesn't belong to the original sale."}), 400

    try:
        quantity = float(data.get("quantity") or (sale_item.quantity if sale_item else 1))
        if quantity <= 0: raise ValueError
    except Exception:
        return jsonify({"error": "A positive quantity is required."}), 400
    try:
        refund_amount = float(data.get("refund_amount")) if data.get("refund_amount") not in (None, "") else (
            round((sale_item.unit_price or 0) * quantity, 2) if sale_item else None)
        if refund_amount is None or refund_amount < 0: raise ValueError
    except Exception:
        return jsonify({"error": "A non-negative refund_amount is required."}), 400

    description = (data.get("description") or (sale_item.description if sale_item else "Return")).strip()[:300]
    refund_method = (data.get("refund_method") or original.payment_method or "cash").strip().lower()[:20]
    kind = "exchange" if (data.get("kind") or "").strip().lower() == "exchange" else "return"
    restock = bool(data.get("restock", True))
    till_session_id = data.get("till_session_id")
    till_session = None
    if till_session_id:
        till_session = PosTillSession.query.get(till_session_id)
        if not till_session or till_session.owner_user_id != user["id"]:
            return jsonify({"error": "Till session not found."}), 404

    refund_sale = PosSale(
        owner_user_id=user["id"], sale_number=f"RTN-{datetime.utcnow().strftime('%y%m%d')}-{secrets.token_hex(3).upper()}",
        currency=original.currency, subtotal=round(refund_amount, 2), tax_amount=0, total=round(refund_amount, 2),
        payment_method=refund_method, is_return=True, original_sale_id=original.id,
        till_id=(till_session.till_id if till_session else original.till_id),
        till_session_id=till_session_id,
    )
    db.session.add(refund_sale); db.session.flush()
    db.session.add(PosSaleItem(sale_id=refund_sale.id, product_id=(sale_item.product_id if sale_item else None),
                                description=description, quantity=quantity, unit_price=round(refund_amount / quantity, 2) if quantity else 0,
                                line_total=round(refund_amount, 2)))
    db.session.add(PosSaleTender(sale_id=refund_sale.id, method=refund_method, amount=round(refund_amount, 2)))

    if restock and sale_item and sale_item.product_id:
        product = InventoryItem.query.get(sale_item.product_id)
        if product and product.user_id == user["id"]:
            product.quantity = (product.quantity or 0) + quantity

    db.session.add(ErpLedgerEntry(
        owner_user_id=user["id"], entry_date=datetime.utcnow().date(), kind="expense", account="POS Returns",
        description=f"Refund for {original.sale_number}", amount=round(refund_amount, 2),
        reference_type="pos_sale", reference_id=refund_sale.id,
    ))

    ret = PosReturn(
        owner_user_id=user["id"], original_sale_id=original.id, refund_sale_id=refund_sale.id,
        till_session_id=till_session_id, sale_item_id=(sale_item.id if sale_item else None),
        description=description, quantity=quantity, refund_amount=round(refund_amount, 2),
        refund_method=refund_method, reason=(data.get("reason") or "").strip()[:300] or None,
        kind=kind, restocked=bool(restock and sale_item and sale_item.product_id),
    )
    db.session.add(ret)
    db.session.commit()
    _pos_emit("return_processed", ret.to_dict(), till_id=refund_sale.till_id, owner_user_id=user["id"])
    return jsonify({"return": ret.to_dict(), "refund_sale": refund_sale.to_dict(include_items=True, include_tenders=True)}), 201


@app.route("/api/pos/returns", methods=["GET"])
def pos_returns_list():
    user, err = _erp_user_or_401()
    if err: return err
    q = PosReturn.query.filter_by(owner_user_id=user["id"])
    original_sale_id = request.args.get("original_sale_id")
    if original_sale_id: q = q.filter_by(original_sale_id=original_sale_id)
    rows = q.order_by(PosReturn.created_at.desc()).limit(100).all()
    return jsonify({"returns": [r.to_dict() for r in rows]}), 200


# ════════════════════════════════════════════════════════════
# STAGE 500: REAL POS HARDWARE PROVIDERS — Square, Clover, Toast
# Deliberately catalog + sales SYNC only, not a replacement for the
# merchant's physical terminal (which is what actually takes the card
# tap/dip and does the PCI-scope payment) — same "sync, don't replace"
# framing as the Shopify/WooCommerce integration above. A business
# connects its own account (Settings -> Integrations, BYOK — see
# provider_fields in /api/integrations/providers for exactly which
# fields each one needs and where to find them) and can then: pull
# that provider's catalog into InventoryItem (so Connect It's own POS/
# ERP/reporting sees the same products), and push a Connect It POS sale
# to the provider as an external/manual order for unified sales
# reporting on their side.
# ════════════════════════════════════════════════════════════

def _square_creds(user_id) -> dict:
    return get_user_credentials(user_id, "square")


def _square_request(user_id, method: str, path: str, **kwargs) -> dict:
    creds = _square_creds(user_id)
    token = creds.get("access_token")
    if not token:
        return {"ok": False, "error": "Square isn't connected. Add your access token under Settings -> Integrations."}
    env = (creds.get("environment") or "production").strip().lower()
    base = "https://connect.squareupsandbox.com" if env == "sandbox" else "https://connect.squareup.com"
    try:
        r = requests.request(
            method, f"{base}{path}",
            headers={"Authorization": f"Bearer {token}", "Content-Type": "application/json", "Square-Version": "2024-06-04"},
            timeout=15, **kwargs,
        )
        if r.status_code >= 400:
            return {"ok": False, "error": f"Square API error ({r.status_code}): {r.text[:300]}"}
        return {"ok": True, "data": r.json() if r.text else {}}
    except Exception as e:
        logging.error(f"[SQUARE REQUEST ERROR] user={user_id}: {e}")
        return {"ok": False, "error": str(e)}


def square_sync_catalog_to_inventory(user_id) -> dict:
    """Pulls Square's item catalog and upserts InventoryItem rows keyed
    by SKU (falling back to name when a variation has no SKU)."""
    result = _square_request(user_id, "GET", "/v2/catalog/list?types=ITEM")
    if not result.get("ok"):
        return result
    created, updated = 0, 0
    for obj in (result["data"] or {}).get("objects", []):
        item_data = obj.get("item_data") or {}
        name = item_data.get("name")
        if not name:
            continue
        variations = item_data.get("variations") or []
        price_cents = None
        sku = None
        if variations:
            vdata = (variations[0] or {}).get("item_variation_data") or {}
            sku = vdata.get("sku")
            money = vdata.get("price_money") or {}
            price_cents = money.get("amount")
        unit_price = round(price_cents / 100, 2) if price_cents is not None else None
        existing = InventoryItem.query.filter_by(user_id=user_id, sku=sku).first() if sku else \
                   InventoryItem.query.filter_by(user_id=user_id, name=name).first()
        if existing:
            existing.unit_price = unit_price if unit_price is not None else existing.unit_price
            updated += 1
        else:
            db.session.add(InventoryItem(user_id=user_id, name=name[:200], sku=(sku or None), unit_price=unit_price, quantity=0))
            created += 1
    db.session.commit()
    return {"ok": True, "created": created, "updated": updated}


def square_push_sale(user_id, sale: "PosSale") -> dict:
    """Records a Connect It POS sale in Square as a completed order with
    a matching payment note, for unified reporting on the Square side —
    money already moved on Connect It's own tender, this is a mirror
    entry, not a real charge."""
    items = PosSaleItem.query.filter_by(sale_id=sale.id).all()
    line_items = [{
        "name": i.description[:255], "quantity": str(int(i.quantity)) if float(i.quantity).is_integer() else str(i.quantity),
        "base_price_money": {"amount": int(round((i.unit_price or 0) * 100)), "currency": sale.currency},
    } for i in items]
    body = {"order": {"location_id": _square_creds(user_id).get("location_id"), "line_items": line_items,
                       "reference_id": sale.sale_number}}
    if not body["order"]["location_id"]:
        return {"ok": False, "error": "Add your Square location_id under Settings -> Integrations first."}
    return _square_request(user_id, "POST", "/v2/orders", json=body)


def _clover_creds(user_id) -> dict:
    return get_user_credentials(user_id, "clover")


def _clover_request(user_id, method: str, path: str, **kwargs) -> dict:
    creds = _clover_creds(user_id)
    token = creds.get("api_token")
    merchant_id = creds.get("merchant_id")
    if not (token and merchant_id):
        return {"ok": False, "error": "Clover isn't connected. Add your API token and merchant ID under Settings -> Integrations."}
    env = (creds.get("environment") or "production").strip().lower()
    base = "https://apisandbox.dev.clover.com" if env == "sandbox" else "https://api.clover.com"
    try:
        r = requests.request(
            method, f"{base}/v3/merchants/{merchant_id}{path}",
            headers={"Authorization": f"Bearer {token}", "Content-Type": "application/json"},
            timeout=15, **kwargs,
        )
        if r.status_code >= 400:
            return {"ok": False, "error": f"Clover API error ({r.status_code}): {r.text[:300]}"}
        return {"ok": True, "data": r.json() if r.text else {}}
    except Exception as e:
        logging.error(f"[CLOVER REQUEST ERROR] user={user_id}: {e}")
        return {"ok": False, "error": str(e)}


def clover_sync_catalog_to_inventory(user_id) -> dict:
    result = _clover_request(user_id, "GET", "/items?expand=categories&limit=200")
    if not result.get("ok"):
        return result
    created, updated = 0, 0
    for item in ((result["data"] or {}).get("elements") or []):
        name = item.get("name")
        if not name:
            continue
        sku = item.get("sku") or item.get("code")
        price_cents = item.get("price")
        unit_price = round(price_cents / 100, 2) if price_cents is not None else None
        existing = InventoryItem.query.filter_by(user_id=user_id, sku=sku).first() if sku else \
                   InventoryItem.query.filter_by(user_id=user_id, name=name).first()
        if existing:
            existing.unit_price = unit_price if unit_price is not None else existing.unit_price
            updated += 1
        else:
            db.session.add(InventoryItem(user_id=user_id, name=name[:200], sku=(sku or None), unit_price=unit_price, quantity=0))
            created += 1
    db.session.commit()
    return {"ok": True, "created": created, "updated": updated}


def _toast_creds(user_id) -> dict:
    return get_user_credentials(user_id, "toast")


def _toast_get_access_token(user_id) -> dict:
    """Toast is client-credentials OAuth2 only — no long-lived pasted
    token like Square/Clover. Exchanges client_id/client_secret for a
    short-lived token on each sync (same shape as the Zoom/WPS
    Server-to-Server integrations elsewhere in this file)."""
    creds = _toast_creds(user_id)
    client_id, client_secret = creds.get("client_id"), creds.get("client_secret")
    if not (client_id and client_secret):
        return {"ok": False, "error": "Toast isn't connected. Add your client_id/client_secret under Settings -> Integrations."}
    env = (creds.get("environment") or "production").strip().lower()
    base = "https://ws-sandbox-api.toasttab.com" if env == "sandbox" else "https://ws-api.toasttab.com"
    try:
        r = requests.post(f"{base}/authentication/v1/authentication/login", json={
            "clientId": client_id, "clientSecret": client_secret, "userAccessType": "TOAST_MACHINE_CLIENT",
        }, timeout=15)
        if r.status_code >= 400:
            return {"ok": False, "error": f"Toast auth error ({r.status_code}): {r.text[:300]}"}
        token = ((r.json() or {}).get("token") or {}).get("accessToken")
        if not token:
            return {"ok": False, "error": "Toast auth succeeded but returned no access token."}
        return {"ok": True, "token": token, "base": base}
    except Exception as e:
        logging.error(f"[TOAST AUTH ERROR] user={user_id}: {e}")
        return {"ok": False, "error": str(e)}


def toast_sync_catalog_to_inventory(user_id) -> dict:
    auth = _toast_get_access_token(user_id)
    if not auth.get("ok"):
        return auth
    restaurant_guid = _toast_creds(user_id).get("restaurant_guid")
    if not restaurant_guid:
        return {"ok": False, "error": "Add your restaurant_guid under Settings -> Integrations."}
    try:
        r = requests.get(f"{auth['base']}/menus/v2/menus",
                          headers={"Authorization": f"Bearer {auth['token']}", "Toast-Restaurant-External-ID": restaurant_guid},
                          timeout=20)
        if r.status_code >= 400:
            return {"ok": False, "error": f"Toast API error ({r.status_code}): {r.text[:300]}"}
        menus = r.json() or []
    except Exception as e:
        logging.error(f"[TOAST MENU FETCH ERROR] user={user_id}: {e}")
        return {"ok": False, "error": str(e)}
    created, updated = 0, 0
    for menu in menus:
        for group in (menu.get("menuGroups") or []):
            for item in (group.get("menuItems") or []):
                name = item.get("name")
                if not name:
                    continue
                price = item.get("price")
                unit_price = round(price, 2) if price is not None else None
                existing = InventoryItem.query.filter_by(user_id=user_id, name=name).first()
                if existing:
                    existing.unit_price = unit_price if unit_price is not None else existing.unit_price
                    updated += 1
                else:
                    db.session.add(InventoryItem(user_id=user_id, name=name[:200], unit_price=unit_price, quantity=0))
                    created += 1
    db.session.commit()
    return {"ok": True, "created": created, "updated": updated}


_POS_PROVIDER_CATALOG_SYNC = {
    "square": square_sync_catalog_to_inventory,
    "clover": clover_sync_catalog_to_inventory,
    "toast": toast_sync_catalog_to_inventory,
}


@app.route("/api/pos/integrations/<provider>/sync-catalog", methods=["POST"])
@csrf.exempt
def pos_integration_sync_catalog(provider):
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    provider = (provider or "").strip().lower()
    fn = _POS_PROVIDER_CATALOG_SYNC.get(provider)
    if not fn:
        return jsonify({"error": f"Unknown POS provider '{provider}'. Use square, clover, or toast."}), 400
    result = fn(user["id"])
    if not result.get("ok"):
        return jsonify({"error": result.get("error") or "Sync failed."}), 400
    return jsonify(result), 200


@app.route("/api/pos/integrations/square/sync-sale/<int:sale_id>", methods=["POST"])
@csrf.exempt
def pos_integration_square_sync_sale(sale_id):
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    sale = PosSale.query.get(sale_id)
    if not sale or sale.owner_user_id != user["id"]:
        return jsonify({"error": "Sale not found."}), 404
    result = square_push_sale(user["id"], sale)
    if not result.get("ok"):
        return jsonify({"error": result.get("error") or "Push to Square failed."}), 400
    return jsonify(result), 200


