@app.route("/api/erp/recurring-invoices", methods=["GET"])
def recurring_invoices_list():
    user, err = _erp_user_or_401()
    if err: return err
    rows = RecurringInvoiceSchedule.query.filter_by(owner_user_id=user["id"]).order_by(RecurringInvoiceSchedule.next_run_date.asc()).all()
    return jsonify({"schedules": [r.to_dict() for r in rows]}), 200


@app.route("/api/erp/recurring-invoices", methods=["POST"])
@csrf.exempt
def recurring_invoices_create():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    description = (data.get("description") or "").strip()
    if not description:
        return jsonify({"error": "Description is required."}), 400
    try:
        amount = float(data.get("amount") or 0)
        if amount <= 0: raise ValueError
    except Exception:
        return jsonify({"error": "Amount must be a positive number."}), 400
    frequency = data.get("frequency") if data.get("frequency") in ("weekly", "monthly") else "monthly"
    next_run = _erp_parse_date(data.get("next_run_date"), default=datetime.utcnow().date())
    row = RecurringInvoiceSchedule(
        owner_user_id=user["id"], customer_id=data.get("customer_id"), description=description[:300],
        amount=amount, currency=(data.get("currency") or "USD").upper()[:8], frequency=frequency, next_run_date=next_run,
    )
    db.session.add(row); db.session.commit()
    return jsonify({"schedule": row.to_dict()}), 201


@app.route("/api/erp/recurring-invoices/<int:sid>", methods=["PUT"])
@csrf.exempt
def recurring_invoices_update(sid):
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    row = RecurringInvoiceSchedule.query.get(sid)
    if not row or row.owner_user_id != user["id"]:
        return jsonify({"error": "Schedule not found."}), 404
    data = request.get_json(silent=True) or {}
    if "active" in data: row.active = bool(data.get("active"))
    if "amount" in data:
        try: row.amount = float(data.get("amount"))
        except Exception: pass
    if data.get("next_run_date"): row.next_run_date = _erp_parse_date(data.get("next_run_date"), default=row.next_run_date)
    db.session.commit()
    return jsonify({"schedule": row.to_dict()}), 200


@app.route("/api/erp/recurring-invoices/<int:sid>", methods=["DELETE"])
@csrf.exempt
def recurring_invoices_delete(sid):
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    row = RecurringInvoiceSchedule.query.get(sid)
    if not row or row.owner_user_id != user["id"]:
        return jsonify({"error": "Schedule not found."}), 404
    db.session.delete(row); db.session.commit()
    return jsonify({"ok": True}), 200


def _recurring_advance(schedule):
    if schedule.frequency == "weekly":
        schedule.next_run_date = schedule.next_run_date + timedelta(days=7)
    else:
        month = schedule.next_run_date.month % 12 + 1
        year = schedule.next_run_date.year + (1 if schedule.next_run_date.month == 12 else 0)
        day = min(schedule.next_run_date.day, 28)
        schedule.next_run_date = schedule.next_run_date.replace(year=year, month=month, day=day)


@app.route("/api/cron/recurring-invoices-run", methods=["POST"])
@csrf.exempt
def cron_recurring_invoices_run():
    if not CRON_SECRET or request.headers.get("X-Cron-Secret") != CRON_SECRET:
        return jsonify({"error": "Not found."}), 404
    today = datetime.utcnow().date()
    due = RecurringInvoiceSchedule.query.filter(RecurringInvoiceSchedule.active == True,
                                                 RecurringInvoiceSchedule.next_run_date <= today).all()
    created = 0
    for sch in due:
        inv = ErpInvoice(
            owner_user_id=sch.owner_user_id, customer_id=sch.customer_id,
            invoice_number=_erp_gen_number("INV"), status="sent", currency=sch.currency,
            issue_date=today, due_date=today + timedelta(days=14),
            subtotal=sch.amount, tax_amount=0, total=sch.amount, notes="Auto-generated recurring invoice.",
        )
        db.session.add(inv); db.session.flush()
        db.session.add(ErpInvoiceItem(invoice_id=inv.id, description=sch.description, quantity=1,
                                       unit_price=sch.amount, line_total=sch.amount))
        sch.last_invoice_id = inv.id
        _recurring_advance(sch)
        created += 1
        db.session.commit()
        customer = ErpCustomer.query.get(sch.customer_id) if sch.customer_id else None
        if customer and customer.email:
            _send_plain_email(customer.email, f"New Invoice {inv.invoice_number}",
                               f"A new invoice for {sch.currency} {sch.amount} ({sch.description}) has been generated. Due {inv.due_date.strftime('%d %b %Y')}.")
    return jsonify({"ok": True, "invoices_created": created}), 200


# ════════════════════════════════════════════════════════════
# STAGE 99: AUTOMATED INVOICE CHASING — ROUTES
# ════════════════════════════════════════════════════════════

def _chase_row(uid, create_if_missing=True):
    row = InvoiceChaseSetting.query.filter_by(owner_user_id=uid).first()
    if not row and create_if_missing:
        row = InvoiceChaseSetting(
            owner_user_id=uid,
            message_template=(
                "Hi {customer_name}, this is a friendly reminder that invoice {invoice_number} "
                "for {currency} {balance_due} is now overdue. Please arrange payment when you're able. Thank you!"
            ),
            # STAGE 166: tier 2 (firm) and tier 3 (final notice) defaults —
            # the owner can edit these, but the tone already escalates
            # out of the box instead of repeating the polite message.
            tier2_template=(
                "Hello {customer_name}, invoice {invoice_number} for {currency} {balance_due} "
                "is still unpaid and now significantly overdue. Please settle this as soon as possible "
                "to avoid further action."
            ),
            tier3_template=(
                "FINAL NOTICE — {customer_name}, invoice {invoice_number} for {currency} {balance_due} "
                "remains unpaid despite previous reminders. Please pay in full immediately, or contact us "
                "to arrange a payment plan."
            ),
        )
        db.session.add(row); db.session.commit()
    return row


def _chase_tier_for_days(setting, days_overdue: int) -> str:
    """Which escalation tier applies for a given number of days overdue."""
    if days_overdue >= setting.tier3_days:
        return "tier3"
    if days_overdue >= setting.tier2_days:
        return "tier2"
    if days_overdue >= setting.days_after_due:
        return "tier1"
    return ""


def _chase_template_for_tier(setting, tier: str) -> str:
    return {
        "tier1": setting.message_template,
        "tier2": setting.tier2_template or setting.message_template,
        "tier3": setting.tier3_template or setting.message_template,
    }.get(tier) or setting.message_template


def _chase_send(owner_user_id, customer, text: str) -> str:
    """Tries WhatsApp (if the owner has a connected WhatsApp Cloud
    number — same BYOK integration used elsewhere), then falls back to
    SMS, then email. Returns the channel that succeeded, or "" if none did."""
    if customer.phone:
        try:
            if send_whatsapp_cloud_message(owner_user_id, customer.phone, text):
                return "whatsapp"
        except Exception as e:
            logging.info(f"[CHASE WHATSAPP SKIP] {e}")
        if _send_sms_simple(customer.phone, text):
            return "sms"
    if customer.email and _send_plain_email(customer.email, "Payment reminder", text):
        return "email"
    return ""


