@app.route("/api/erp/invoice-chase/settings", methods=["PUT"])
@csrf.exempt
def invoice_chase_settings_set():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    row = _chase_row(user["id"])
    data = request.get_json(silent=True) or {}
    if "enabled" in data: row.enabled = bool(data.get("enabled"))
    if "days_after_due" in data:
        try: row.days_after_due = max(1, int(data.get("days_after_due")))
        except Exception: pass
    if data.get("message_template"): row.message_template = data.get("message_template")[:1000]
    # STAGE 166: tier 2 / tier 3 escalation settings
    if "tier2_days" in data:
        try: row.tier2_days = max(row.days_after_due + 1, int(data.get("tier2_days")))
        except Exception: pass
    if data.get("tier2_template"): row.tier2_template = data.get("tier2_template")[:1000]
    if "tier3_days" in data:
        try: row.tier3_days = max(row.tier2_days + 1, int(data.get("tier3_days")))
        except Exception: pass
    if data.get("tier3_template"): row.tier3_template = data.get("tier3_template")[:1000]
    # STAGE 166: auto-installment-offer settings
    if "installment_enabled" in data: row.installment_enabled = bool(data.get("installment_enabled"))
    if "installment_trigger_days" in data:
        try: row.installment_trigger_days = max(row.tier3_days, int(data.get("installment_trigger_days")))
        except Exception: pass
    if "installment_num_parts" in data:
        try: row.installment_num_parts = max(2, min(12, int(data.get("installment_num_parts"))))
        except Exception: pass
    if "installment_frequency_days" in data:
        try: row.installment_frequency_days = max(3, int(data.get("installment_frequency_days")))
        except Exception: pass
    db.session.commit()
    return jsonify(row.to_dict()), 200


