def _create_installment_plan(inv, customer, setting):
    """STAGE 166: auto-proposes an equal-split instalment plan for an
    invoice that has reached final notice and stayed unpaid past the
    configured trigger. Returns the new InstallmentPlan, or None if one
    already exists for this invoice."""
    existing = InstallmentPlan.query.filter_by(invoice_id=inv.id).filter(
        InstallmentPlan.status.in_(["proposed", "active"])).first()
    if existing:
        return None
    balance = round((inv.total or 0) - (inv.amount_paid or 0), 2)
    if balance <= 0:
        return None
    num_parts = max(2, setting.installment_num_parts)
    per_part = round(balance / num_parts, 2)
    plan = InstallmentPlan(
        invoice_id=inv.id, owner_user_id=inv.owner_user_id, customer_id=inv.customer_id,
        token=secrets.token_urlsafe(24), total_amount=balance, currency=inv.currency,
        num_installments=num_parts, installment_amount=per_part,
        frequency_days=setting.installment_frequency_days, status="proposed",
    )
    db.session.add(plan)
    db.session.flush()  # get plan.id before building the schedule
    running_total = 0.0
    for i in range(num_parts):
        due = datetime.utcnow().date() + timedelta(days=setting.installment_frequency_days * (i + 1))
        # last instalment absorbs any rounding remainder
        amount = balance - running_total if i == num_parts - 1 else per_part
        running_total += per_part
        db.session.add(InstallmentPayment(plan_id=plan.id, sequence_number=i + 1, due_date=due, amount=round(amount, 2)))
    return plan


@app.route("/api/cron/invoice-chase-run", methods=["POST"])
@csrf.exempt
def cron_invoice_chase_run():
    if not CRON_SECRET or request.headers.get("X-Cron-Secret") != CRON_SECRET:
        return jsonify({"error": "Not found."}), 404
    today = datetime.utcnow().date()
    settings_by_owner = {s.owner_user_id: s for s in InvoiceChaseSetting.query.filter_by(enabled=True).all()}
    rows = (ErpInvoice.query.filter(ErpInvoice.status.in_(["sent", "overdue"]))
            .filter(ErpInvoice.due_date < today).all())
    sent = 0
    plans_offered = 0
    for inv in rows:
        balance = (inv.total or 0) - (inv.amount_paid or 0)
        if balance <= 0: continue
        setting = settings_by_owner.get(inv.owner_user_id)
        if not setting: continue
        customer = ErpCustomer.query.get(inv.customer_id) if inv.customer_id else None
        if not customer: continue

        days_overdue = (today - inv.due_date).days
        tier = _chase_tier_for_days(setting, days_overdue)
        if not tier:
            continue

        last = (InvoiceChaseLog.query.filter_by(invoice_id=inv.id).order_by(InvoiceChaseLog.sent_at.desc()).first())
        # STAGE 166: send when the tier has escalated since the last nudge,
        # OR (same tier) once the cadence window has passed — instead of
        # only ever repeating the tier-1 cadence forever.
        if last:
            already_at_or_past_tier = last.tier in ("tier1", "tier2", "tier3") and (
                (last.tier == tier) or
                (["tier1", "tier2", "tier3"].index(last.tier) >= ["tier1", "tier2", "tier3"].index(tier))
            )
            if already_at_or_past_tier and (datetime.utcnow() - last.sent_at).days < setting.days_after_due:
                continue

        msg = (_chase_template_for_tier(setting, tier) or "").format(
            customer_name=customer.name, invoice_number=inv.invoice_number,
            currency=inv.currency, balance_due=round(balance, 2))
        channel = _chase_send(inv.owner_user_id, customer, msg)
        if channel:
            db.session.add(InvoiceChaseLog(invoice_id=inv.id, channel=channel, tier=tier))
            if inv.status == "sent": inv.status = "overdue"
            db.session.commit()
            sent += 1

        # STAGE 166: at final notice, past the installment trigger, with
        # auto-offer enabled and no existing plan — propose one.
        if (setting.installment_enabled and tier == "tier3"
                and days_overdue >= setting.installment_trigger_days):
            plan = _create_installment_plan(inv, customer, setting)
            if plan:
                link = f"{APP_BASE_URL}/?installment_plan={plan.token}"
                offer_msg = (
                    f"We'd like to offer you a payment plan for invoice {inv.invoice_number} "
                    f"({inv.currency} {round(balance, 2)}): {plan.num_installments} instalments of "
                    f"{inv.currency} {plan.installment_amount}, every {plan.frequency_days} days. "
                    f"Review and accept here: {link}"
                )
                offer_channel = _chase_send(inv.owner_user_id, customer, offer_msg)
                if offer_channel:
                    db.session.add(InvoiceChaseLog(invoice_id=inv.id, channel=offer_channel, tier="installment_offer"))
                    plans_offered += 1
                db.session.commit()

    return jsonify({"ok": True, "chases_sent": sent, "installment_plans_offered": plans_offered}), 200


