@app.route("/api/erp/installment-plans/<int:plan_id>/payments/<int:seq>/mark-paid", methods=["POST"])
@csrf.exempt
def installment_plan_mark_paid(plan_id, seq):
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    plan = InstallmentPlan.query.filter_by(id=plan_id, owner_user_id=user["id"]).first()
    if not plan:
        return jsonify({"error": "Plan not found."}), 404
    installment = InstallmentPayment.query.filter_by(plan_id=plan.id, sequence_number=seq).first()
    if not installment:
        return jsonify({"error": "Instalment not found."}), 404
    if installment.paid:
        return jsonify({"error": "Already marked paid."}), 400
    installment.paid = True
    installment.paid_at = datetime.utcnow()

    inv = ErpInvoice.query.get(plan.invoice_id)
    if inv:
        inv.amount_paid = round((inv.amount_paid or 0) + installment.amount, 2)
        _erp_post_ledger(
            owner_user_id=user["id"], entry_date=datetime.utcnow().date(), kind="income",
            account="Accounts Receivable", description=f"Instalment {seq}/{plan.num_installments} — invoice {inv.invoice_number}",
            amount=installment.amount, ref_type="installment_plan", ref_id=plan.id,
        )
        if (inv.total or 0) - (inv.amount_paid or 0) <= 0.01:
            inv.status = "paid"
            inv.paid_at = datetime.utcnow()
            try:
                enqueue_job(_wa_capi_purchase_job, app, inv.owner_user_id, inv.id, inv.customer_id,
                            float(inv.total or 0), inv.currency)
                enqueue_job(_wa_receipt_job, app, inv.owner_user_id, inv.id, inv.customer_id,
                            float(inv.total or 0), inv.currency, inv.invoice_number)
            except Exception as _capi_err:
                logging.error(f"[WA CAPI ENQUEUE ERROR] {_capi_err}")

    remaining_unpaid = InstallmentPayment.query.filter_by(plan_id=plan.id, paid=False).count()
    if remaining_unpaid == 0:
        plan.status = "completed"
    db.session.commit()
    return jsonify({"ok": True, "plan": plan.to_dict(include_schedule=True)}), 200


