    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    row = ExpenseApprovalRequest.query.get(req_id)
    if not row or row.owner_user_id != user["id"]:
        return jsonify({"error": "Request not found."}), 404
    if row.status != "pending":
        return jsonify({"error": "Already decided."}), 400
    expense = ErpExpense(
        owner_user_id=user["id"], expense_date=datetime.utcnow().date(), category=row.category or "petty cash",
        vendor=row.submitted_by_name, amount=row.amount, currency=row.currency,
        payment_method="petty cash", notes=row.description,
    )
    db.session.add(expense); db.session.flush()
    db.session.add(ErpLedgerEntry(
        owner_user_id=user["id"], entry_date=datetime.utcnow().date(), kind="expense", account="Petty Cash",
        description=row.description, amount=-abs(row.amount), reference_type="expense", reference_id=expense.id,
    ))
    row.status = "approved"; row.linked_expense_id = expense.id; row.decided_at = datetime.utcnow()
    db.session.commit()
    return jsonify({"request": row.to_dict()}), 200


