# STAGE 102: STAFF PERFORMANCE LEADERBOARD — ROUTES
# ════════════════════════════════════════════════════════════

@app.route("/api/staff/leaderboard", methods=["GET"])
def staff_leaderboard():
    user, err = _erp_user_or_401()
    if err: return err
    days = int(request.args.get("days") or 30)
    since = datetime.utcnow() - timedelta(days=days)
    employees = ErpEmployee.query.filter_by(owner_user_id=user["id"], status="active").all()
    board = []
    for emp in employees:
        sales = PosSale.query.filter_by(employee_id=emp.id).filter(PosSale.created_at >= since).all()
        sales_total = round(sum(s.total for s in sales), 2)
        attendance_rows = ErpAttendance.query.filter_by(employee_id=emp.id).filter(ErpAttendance.work_date >= since.date()).all()
        present = sum(1 for a in attendance_rows if a.status == "present")
        attendance_pct = round(present / len(attendance_rows) * 100, 1) if attendance_rows else None
        board.append({
            "employee_id": emp.id, "name": emp.full_name, "role": emp.role,
            "sales_count": len(sales), "sales_total": sales_total, "attendance_pct": attendance_pct,
        })
    board.sort(key=lambda r: r["sales_total"], reverse=True)
    return jsonify({"period_days": days, "leaderboard": board}), 200


