# STAGE 103: DELIVERY ROUTE OPTIMIZER — ROUTES
# ════════════════════════════════════════════════════════════

@app.route("/api/delivery/optimize-route", methods=["POST"])
@csrf.exempt
def delivery_optimize_route():
    """Heuristic only — groups a rider's open/accepted stops by dropoff
    area so nearby drops are handled together. No mapping/geocoding API
    is configured, so this is not a true shortest-path solve; see the
    STAGE 103 comment near DeliveryRider/DeliveryRequest above."""
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user: return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    rider = DeliveryRider.query.filter_by(user_id=user["id"]).first()
    rider_id = data.get("rider_id") or (rider.id if rider else None)
    if not rider_id:
        return jsonify({"error": "rider_id is required (or register as a rider first)."}), 400
    stops = (DeliveryRequest.query.filter_by(rider_id=rider_id)
             .filter(DeliveryRequest.status == "accepted").all())
    if not stops:
        return jsonify({"route": [], "note": "No accepted deliveries to route right now."}), 200
    grouped = defaultdict(list)
    for s in stops:
        grouped[s.dropoff_area.strip().lower()].append(s)
    ordered_route = []
    for area in sorted(grouped.keys()):
        for s in grouped[area]:
            ordered_route.append(s.to_dict())
    return jsonify({
        "route": ordered_route, "stop_count": len(ordered_route),
        "note": "Grouped by drop-off area (heuristic — no live mapping is wired in, so this isn't a true shortest-path route).",
    }), 200


