@app.route("/api/fleet/vehicles", methods=["POST"])
@csrf.exempt
def fleet_vehicles_create():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    label = (data.get("label") or data.get("name") or "").strip()
    if not label:
        return jsonify({"error": "Vehicle name is required."}), 400
