# ── VEHICLE & FLEET DIAGNOSTICS EXPANSION — ROUTES ──
# DTC decoding reuses _GENERIC_DTC_CODES / _decode_dtc, defined further
# below alongside the personal OBD2 tool. Since Python resolves names
# at call time (not at function-definition time), calling _decode_dtc
# from these routes works fine even though its definition appears
# later in this file.

def _fleet_vehicle_or_404(vid, user):
    row = FleetVehicle.query.filter_by(id=vid, owner_user_id=user["id"]).first()
    return row


@app.route("/api/fleet/dtc-lookup/<code>", methods=["GET"])
def fleet_dtc_lookup(code):
    user, err = _erp_user_or_401()
    if err: return err
    decoded = _decode_dtc(code)
    decoded["plain_language"] = f"{decoded['description']}. {decoded['recommended_action']}"
    return jsonify(decoded), 200


@app.route("/api/fleet/diagnostics", methods=["POST"])
@csrf.exempt
def fleet_diagnostics_create():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    vehicle = _fleet_vehicle_or_404(data.get("vehicle_id"), user)
    if not vehicle:
        return jsonify({"error": "Vehicle not found."}), 404

    def _f(key):
        try:
            return float(data[key]) if data.get(key) not in (None, "") else None
        except (TypeError, ValueError):
            return None

    codes = data.get("dtc_codes") or []
    if isinstance(codes, str):
        codes = [c.strip() for c in codes.split(",") if c.strip()]
    codes = [c.upper() for c in codes[:20]]
    readiness = data.get("readiness")

    row = FleetDiagnosticReading(
        vehicle_id=vehicle.id, owner_user_id=user["id"],
        adapter_kind=(data.get("adapter_kind") or "manual")[:20],
        rpm=_f("rpm"), coolant_temp_c=_f("coolant_temp_c"),
        fuel_trim_short_pct=_f("fuel_trim_short_pct"), fuel_trim_long_pct=_f("fuel_trim_long_pct"),
        o2_sensor_v=_f("o2_sensor_v"), intake_temp_c=_f("intake_temp_c"), throttle_pct=_f("throttle_pct"),
        dtc_codes=",".join(codes) or None,
        readiness_json=json.dumps(readiness) if isinstance(readiness, dict) else None,
    )
    db.session.add(row); db.session.commit()

    dtc_explained = []
    for c in codes:
        d = _decode_dtc(c)
        d["plain_language"] = f"{d['description']}. {d['recommended_action']}"
        dtc_explained.append(d)
    return jsonify({"reading": row.to_dict(), "dtc_explained": dtc_explained}), 201


