def _fleet_predictive_alerts(vehicle, readings, schedules):
    """readings: most-recent-first FleetDiagnosticReading rows for this
    vehicle. Rule-based trend detection against real stored data —
    mirrors the personal OBD2 tool's _run_diagnosis_rules pattern, just
    scoped to a fleet vehicle and folding in overdue scheduled tasks."""
    alerts = []

    code_counts = {}
    for r in readings:
        for c in (r.dtc_codes or "").split(","):
            c = c.strip().upper()
            if c:
                code_counts[c] = code_counts.get(c, 0) + 1
    for code, count in code_counts.items():
        d = _decode_dtc(code)
        if count >= 2:
            alerts.append({"severity": d["severity"],
                            "message": f"Fault code {code} ({d['description']}) has appeared in {count} of the last "
                                       f"{len(readings)} readings — a recurring code, not a one-off. {d['recommended_action']}"})
        elif d["severity"] == "critical":
            alerts.append({"severity": "critical",
                            "message": f"Fault code {code} ({d['description']}). {d['recommended_action']}"})

    coolant_series = [r.coolant_temp_c for r in readings if r.coolant_temp_c is not None]
    if len(coolant_series) >= 4:
        half = len(coolant_series) // 2
        recent_avg = sum(coolant_series[:half]) / half
        older_avg = sum(coolant_series[half:]) / (len(coolant_series) - half)
        if recent_avg - older_avg > 5:
            alerts.append({"severity": "warning",
                            "message": f"Coolant temperature is trending upward across recent readings "
                                       f"(avg {round(recent_avg,1)}°C now vs {round(older_avg,1)}°C earlier) — "
                                       f"worth a cooling-system check before it becomes a breakdown."})

    trim_series = [r.fuel_trim_long_pct for r in readings[:5] if r.fuel_trim_long_pct is not None]
    if trim_series:
        avg_abs_trim = sum(abs(t) for t in trim_series) / len(trim_series)
        if avg_abs_trim > 10:
            alerts.append({"severity": "warning",
                            "message": f"Long-term fuel trim has averaged {round(avg_abs_trim,1)}% (out of the "
                                       f"normal ±10% band) over recent readings — possible vacuum leak or fuel "
                                       f"delivery issue developing."})

    for s in schedules:
        d = s.to_dict()
        if d["overdue"]:
            alerts.append({"severity": "warning",
                            "message": f"Scheduled task \"{d['task_name']}\" is overdue."})

    order = {"critical": 0, "warning": 1, "info": 2}
    alerts.sort(key=lambda a: order.get(a["severity"], 2))
    return alerts


@app.route("/api/fleet/diagnostics/<int:vehicle_id>/predictive", methods=["GET"])
def fleet_diagnostics_predictive(vehicle_id):
    user, err = _erp_user_or_401()
    if err: return err
    vehicle = _fleet_vehicle_or_404(vehicle_id, user)
    if not vehicle:
        return jsonify({"error": "Vehicle not found."}), 404
    readings = (FleetDiagnosticReading.query.filter_by(vehicle_id=vehicle_id)
                .order_by(FleetDiagnosticReading.recorded_at.desc()).limit(30).all())
    schedules = FleetMaintenanceSchedule.query.filter_by(vehicle_id=vehicle_id, active=True).all()
    alerts = _fleet_predictive_alerts(vehicle, readings, schedules)
    return jsonify({"alerts": alerts}), 200


