@app.route("/api/fleet/fuel-efficiency/<int:vehicle_id>", methods=["GET"])
def fleet_fuel_efficiency(vehicle_id):
    user, err = _erp_user_or_401()
    if err: return err
    vehicle = _fleet_vehicle_or_404(vehicle_id, user)
    if not vehicle:
        return jsonify({"error": "Vehicle not found."}), 404
    logs = (FleetFuelLog.query.filter_by(vehicle_id=vehicle_id)
            .order_by(FleetFuelLog.odometer_km.asc()).all())
    segments = []
    total_distance = 0.0
    total_litres = 0.0
    for prev, cur in zip(logs, logs[1:]):
        distance = cur.odometer_km - prev.odometer_km
        if distance <= 0:
            continue
        l_per_100km = round(cur.litres / distance * 100, 2)
        segments.append({"distance_km": distance, "litres": cur.litres, "l_per_100km": l_per_100km})
        total_distance += distance
        total_litres += cur.litres
    average = round(total_litres / total_distance * 100, 2) if total_distance > 0 else None
    return jsonify({"average_l_per_100km": average, "segments": segments}), 200


