@app.route("/api/fleet/driver-behavior/<int:vehicle_id>/score", methods=["GET"])
def fleet_driver_behavior_score(vehicle_id):
    user, err = _erp_user_or_401()
    if err: return err
    vehicle = _fleet_vehicle_or_404(vehicle_id, user)
    if not vehicle:
        return jsonify({"error": "Vehicle not found."}), 404
    since = datetime.utcnow() - timedelta(days=30)
    events = (FleetDriverBehaviorEvent.query
              .filter(FleetDriverBehaviorEvent.vehicle_id == vehicle_id,
                      FleetDriverBehaviorEvent.recorded_at >= since).all())
    event_counts = {"harsh_brake": 0, "harsh_accel": 0, "idling": 0, "speeding": 0}
    for e in events:
        if e.event_type in event_counts:
            event_counts[e.event_type] += 1
    penalties = {"harsh_brake": 3, "harsh_accel": 3, "idling": 1, "speeding": 2}
    score = 100
    for k, count in event_counts.items():
        score -= penalties.get(k, 1) * count
    score = max(0, min(100, score))
    return jsonify({"score": score, "event_counts": event_counts, "period_days": 30}), 200


