# ════════════════════════════════════════════════════════════
# STAGE — FLEET DISPATCH → THIRD-PARTY COURIER (Sendy, Kenya)
#
# Honesty note, read before touching _send_dispatch_to_sendy:
# Sendy is a real, self-serve courier with a confirmed BYOK-style
# credential flow (api_key + username, sandbox/production
# environments). What is NOT independently confirmed from public
# docs is the exact server-to-server REST endpoint path and JSON
# response shape for order creation/tracking/cancellation — Sendy's
# reference docs are a JS-rendered Apiary page that couldn't be
# fully read in this session. The call below is a best-effort
# mapping using the fields Sendy's own client-side integration
# widget is confirmed to use (from_name/from_lat/from_long,
# recipient_name/recipient_phone/recipient_email, notes) sent to a
# base URL that is the confirmed sandbox host for Sendy's own
# script, not independently confirmed as the REST API root.
#
# This is deliberately NOT hidden behind a fake success response.
# If the endpoint path is wrong, the HTTP call will fail with a
# real error (404/auth error/etc.) and that real error is what
# gets stored in courier_last_error and shown to the user — never
# a fabricated "sent!" confirmation. Before routing real dispatch
# traffic through this in "production", confirm the endpoint
# path/schema against your own Sendy Business dashboard's API
# reference and update SENDY_API_BASE_URLS / the payload below.
# ════════════════════════════════════════════════════════════

SENDY_API_BASE_URLS = {
    "sandbox":    "https://apibuttontest.sendyit.com",
    "production": "https://apibutton.sendyit.com",
}
SENDY_INTEGRATION_CONFIDENCE_NOTE = (
    "This Sendy integration uses a best-effort field mapping. The exact "
    "REST endpoint path was not independently verified from public docs — "
    "test thoroughly in 'sandbox' before relying on 'production'."
)

# Registry so adding a second courier later (e.g. a Nigerian or South
# African provider) is a matter of writing one function and adding it
# here — the endpoints below don't need to change.
_COURIER_SENDERS = {}
_COURIER_TRACKERS = {}
_COURIER_CANCELLERS = {}


def _send_dispatch_to_sendy(user_id, dispatch):
    """Returns (ok: bool, message: str). On success, mutates dispatch's
    courier_* fields in place; does not commit — caller commits."""
    api_key  = get_effective_credential(user_id, "sendy_courier", "api_key")
    username = get_effective_credential(user_id, "sendy_courier", "username")
    env      = get_effective_credential(user_id, "sendy_courier", "environment", "sandbox") or "sandbox"
    if not api_key or not username:
        return False, "No Sendy account connected. Add your Sendy API key and username under Integrations first."
    if not (dispatch.pickup_lat and dispatch.pickup_lng and dispatch.dropoff_lat and dispatch.dropoff_lng):
        return False, "Pickup and drop-off coordinates are both required to book a Sendy rider."
    if not dispatch.recipient_phone:
        return False, "A recipient phone number is required."

    base = SENDY_API_BASE_URLS.get(env, SENDY_API_BASE_URLS["sandbox"])
    payload = {
        "api_key": api_key,
        "username": username,
        "from_name": dispatch.pickup_name or "Pickup point",
        "from_lat": dispatch.pickup_lat,
        "from_long": dispatch.pickup_lng,
        "to_name": dispatch.dropoff_name or "Drop-off point",
        "to_lat": dispatch.dropoff_lat,
        "to_long": dispatch.dropoff_lng,
        "recipient_name": dispatch.recipient_name or dispatch.driver_name or "Recipient",
        "recipient_phone": dispatch.recipient_phone,
        "recipient_email": dispatch.recipient_email or "",
        "notes": dispatch.route_note or "",
    }
    try:
        resp = requests.post(f"{base}/api/orders/create", json=payload, timeout=20)
    except requests.RequestException as e:
        dispatch.courier_last_error = f"Could not reach Sendy: {e}"
        return False, dispatch.courier_last_error

    if not resp.ok:
        dispatch.courier_last_error = f"Sendy rejected the request (HTTP {resp.status_code}): {resp.text[:300]}"
        return False, dispatch.courier_last_error

    try:
        body = resp.json()
    except ValueError:
        dispatch.courier_last_error = f"Sendy returned a non-JSON response: {resp.text[:300]}"
        return False, dispatch.courier_last_error

    order_no = body.get("order_no") or body.get("id") or body.get("order_id")
    if not order_no:
        dispatch.courier_last_error = f"Sendy accepted the call but returned no order reference: {json.dumps(body)[:300]}"
        return False, dispatch.courier_last_error

    dispatch.courier_provider = "sendy"
    dispatch.courier_order_no = str(order_no)
    dispatch.courier_status = body.get("status") or "requested"
    dispatch.courier_fee = body.get("cost") or body.get("fee")
    dispatch.courier_currency = body.get("currency") or "KES"
    dispatch.courier_tracking_url = body.get("tracking_url") or body.get("track_url")
    dispatch.courier_last_error = None
    dispatch.courier_synced_at = datetime.utcnow()
    return True, "Sent to Sendy."


def _track_dispatch_on_sendy(user_id, dispatch):
    api_key  = get_effective_credential(user_id, "sendy_courier", "api_key")
    username = get_effective_credential(user_id, "sendy_courier", "username")
    env      = get_effective_credential(user_id, "sendy_courier", "environment", "sandbox") or "sandbox"
    if not api_key or not username:
        return False, "No Sendy account connected."
    if not dispatch.courier_order_no:
        return False, "This dispatch has no Sendy order to track."
    base = SENDY_API_BASE_URLS.get(env, SENDY_API_BASE_URLS["sandbox"])
    try:
        resp = requests.get(
            f"{base}/api/orders/{dispatch.courier_order_no}/status",
            params={"api_key": api_key, "username": username},
            timeout=15,
        )
    except requests.RequestException as e:
        dispatch.courier_last_error = f"Could not reach Sendy: {e}"
        return False, dispatch.courier_last_error
    if not resp.ok:
        dispatch.courier_last_error = f"Sendy rejected the tracking request (HTTP {resp.status_code}): {resp.text[:300]}"
        return False, dispatch.courier_last_error
    try:
        body = resp.json()
    except ValueError:
        dispatch.courier_last_error = f"Sendy returned a non-JSON response: {resp.text[:300]}"
        return False, dispatch.courier_last_error
    dispatch.courier_status = body.get("status") or dispatch.courier_status
    dispatch.courier_tracking_url = body.get("tracking_url") or body.get("track_url") or dispatch.courier_tracking_url
    dispatch.courier_last_error = None
    dispatch.courier_synced_at = datetime.utcnow()
    return True, "Status refreshed."


def _cancel_dispatch_on_sendy(user_id, dispatch):
    api_key  = get_effective_credential(user_id, "sendy_courier", "api_key")
    username = get_effective_credential(user_id, "sendy_courier", "username")
    env      = get_effective_credential(user_id, "sendy_courier", "environment", "sandbox") or "sandbox"
    if not api_key or not username:
        return False, "No Sendy account connected."
    if not dispatch.courier_order_no:
        return False, "This dispatch has no Sendy order to cancel."
    base = SENDY_API_BASE_URLS.get(env, SENDY_API_BASE_URLS["sandbox"])
    try:
        resp = requests.post(
            f"{base}/api/orders/{dispatch.courier_order_no}/cancel",
            json={"api_key": api_key, "username": username},
            timeout=15,
        )
    except requests.RequestException as e:
        dispatch.courier_last_error = f"Could not reach Sendy: {e}"
        return False, dispatch.courier_last_error
    if not resp.ok:
        dispatch.courier_last_error = f"Sendy rejected the cancellation (HTTP {resp.status_code}): {resp.text[:300]}"
        return False, dispatch.courier_last_error
    dispatch.courier_status = "cancelled"
    dispatch.courier_last_error = None
    dispatch.courier_synced_at = datetime.utcnow()
    return True, "Cancelled with Sendy."


_COURIER_SENDERS["sendy"] = _send_dispatch_to_sendy
_COURIER_TRACKERS["sendy"] = _track_dispatch_on_sendy
_COURIER_CANCELLERS["sendy"] = _cancel_dispatch_on_sendy


@app.route("/api/fleet/dispatch/<int:did>/send-to-courier", methods=["POST"])
@csrf.exempt
def fleet_dispatch_send_to_courier(did):
    """Book a real third-party courier (currently: Sendy) for an
    existing fleet dispatch. See the confidence note above
    _send_dispatch_to_sendy before routing production traffic."""
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    row = FleetDispatch.query.filter_by(id=did, owner_user_id=user["id"]).first()
    if not row:
        return jsonify({"error": "Dispatch not found."}), 404

    data = request.get_json(silent=True) or {}
    provider = (data.get("provider") or "sendy").strip().lower()
    sender = _COURIER_SENDERS.get(provider)
    if not sender:
        return jsonify({"error": f"No courier integration for '{provider}'. Available: {', '.join(_COURIER_SENDERS)}"}), 400

    def _f(key):
        try:
            return float(data[key]) if data.get(key) not in (None, "") else None
        except (TypeError, ValueError):
            return None

    row.pickup_name     = (data.get("pickup_name") or "").strip()[:160] or row.pickup_name
    row.pickup_lat       = _f("pickup_lat") if data.get("pickup_lat") is not None else row.pickup_lat
    row.pickup_lng       = _f("pickup_lng") if data.get("pickup_lng") is not None else row.pickup_lng
    row.dropoff_name     = (data.get("dropoff_name") or "").strip()[:160] or row.dropoff_name
    row.dropoff_lat      = _f("dropoff_lat") if data.get("dropoff_lat") is not None else row.dropoff_lat
    row.dropoff_lng      = _f("dropoff_lng") if data.get("dropoff_lng") is not None else row.dropoff_lng
    row.recipient_name   = (data.get("recipient_name") or "").strip()[:160] or row.recipient_name
    row.recipient_phone  = (data.get("recipient_phone") or "").strip()[:40] or row.recipient_phone
    row.recipient_email  = (data.get("recipient_email") or "").strip()[:255] or row.recipient_email

    ok, message = sender(user["id"], row)
    try:
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        logging.error(f"[COURIER DISPATCH SAVE] {e}")
        return jsonify({"error": "Could not save the courier booking. Try again."}), 500

    status_code = 201 if ok else 502
    return jsonify({"ok": ok, "message": message, "dispatch": row.to_dict()}), status_code


@app.route("/api/fleet/dispatch/<int:did>/courier-status", methods=["GET"])
def fleet_dispatch_courier_status(did):
    user, err = _erp_user_or_401()
    if err: return err
    row = FleetDispatch.query.filter_by(id=did, owner_user_id=user["id"]).first()
    if not row:
        return jsonify({"error": "Dispatch not found."}), 404
    if not row.courier_provider:
        return jsonify({"dispatch": row.to_dict()}), 200
    tracker = _COURIER_TRACKERS.get(row.courier_provider)
    if tracker:
        ok, message = tracker(user["id"], row)
        try:
            db.session.commit()
        except Exception as e:
            db.session.rollback()
            logging.error(f"[COURIER TRACK SAVE] {e}")
            return jsonify({"error": "Could not save the refreshed status."}), 500
        return jsonify({"ok": ok, "message": message, "dispatch": row.to_dict()}), 200
    return jsonify({"dispatch": row.to_dict()}), 200


@app.route("/api/fleet/dispatch/<int:did>/cancel-courier", methods=["POST"])
@csrf.exempt
def fleet_dispatch_cancel_courier(did):
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    row = FleetDispatch.query.filter_by(id=did, owner_user_id=user["id"]).first()
    if not row:
        return jsonify({"error": "Dispatch not found."}), 404
    if not row.courier_provider:
        return jsonify({"error": "This dispatch was never sent to a courier."}), 400
    canceller = _COURIER_CANCELLERS.get(row.courier_provider)
    if not canceller:
        return jsonify({"error": f"No cancellation support for '{row.courier_provider}'."}), 400
    ok, message = canceller(user["id"], row)
    try:
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        logging.error(f"[COURIER CANCEL SAVE] {e}")
        return jsonify({"error": "Could not save the cancellation."}), 500
    return jsonify({"ok": ok, "message": message, "dispatch": row.to_dict()}), (200 if ok else 502)


