@app.route("/api/inbox/threads", methods=["GET"])
def inbox_threads():
    user, err = _erp_user_or_401()
    if err: return err
    rows = (UnifiedInboxMessage.query.filter_by(owner_user_id=user["id"])
            .order_by(UnifiedInboxMessage.created_at.desc()).limit(500).all())
    threads = {}
    for m in rows:
        key = m.contact_identifier
        if key not in threads:
            threads[key] = {"contact_identifier": key, "contact_name": m.contact_name, "channel": m.channel,
                             "last_message": m.body[:120], "last_at": m.created_at.isoformat(),
                             "unread": 0}
        if m.direction == "in" and not m.read_at:
            threads[key]["unread"] += 1
    # Attach staff assignment (Stage 106 <-> Stage 101 pairing) to each
    # thread in one batch query rather than one lookup per thread.
    if threads:
        assignments = (InboxThreadAssignment.query
                        .filter(InboxThreadAssignment.owner_user_id == user["id"],
                                InboxThreadAssignment.contact_identifier.in_(threads.keys())).all())
        by_contact = {a.contact_identifier: a for a in assignments}
        for key, t in threads.items():
            a = by_contact.get(key)
            t["assignment"] = a.to_dict() if a else None
    return jsonify({"threads": list(threads.values())}), 200


@app.route("/api/inbox/thread/<path:contact_identifier>/assign", methods=["POST"])
@csrf.exempt
def inbox_thread_assign(contact_identifier):
    """Assign (or reassign) a conversation thread to a staff member, or
    pass employee_id=null to unassign. Cross-references ShiftSchedule so
    the response reflects whether that employee is on shift right now --
    the pairing between Stage 106 (inbox) and Stage 101 (rota) that
    previously didn't exist."""
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    channel = (data.get("channel") or "whatsapp").strip()[:16]
    employee_id = data.get("employee_id")
    status = (data.get("status") or "open").strip()[:16]
    if status not in ("open", "snoozed", "closed"):
        return jsonify({"error": "status must be open, snoozed, or closed."}), 400
    if employee_id is not None:
        employee = ErpEmployee.query.filter_by(id=employee_id, owner_user_id=user["id"]).first()
        if not employee:
            return jsonify({"error": "Employee not found."}), 404
    row = InboxThreadAssignment.query.filter_by(
        owner_user_id=user["id"], channel=channel, contact_identifier=contact_identifier
    ).first()
    if not row:
        row = InboxThreadAssignment(owner_user_id=user["id"], channel=channel, contact_identifier=contact_identifier)
        db.session.add(row)
    row.assigned_employee_id = employee_id
    row.assigned_by_user_id = user["id"]
    row.status = status
    row.assigned_at = datetime.utcnow() if employee_id else None
    db.session.commit()
    return jsonify({"ok": True, "assignment": row.to_dict()}), 200


