@app.route("/api/inbox/thread/<path:contact_identifier>", methods=["GET"])
def inbox_thread(contact_identifier):
    user, err = _erp_user_or_401()
    if err: return err
    rows = (UnifiedInboxMessage.query.filter_by(owner_user_id=user["id"], contact_identifier=contact_identifier)
            .order_by(UnifiedInboxMessage.created_at.asc()).all())
    # Real read receipts: when this operator actually opens the thread,
    # tell Meta the customer's WhatsApp Cloud API messages were read (blue
    # ticks in their app), not just flip a local read_at flag. Best-effort
    # -- only the newest unread inbound Cloud API message needs marking
    # (Meta treats mark-read as "read up to and including this message"),
    # and a failure here (e.g. BYOK not configured) must never block the
    # thread from loading.
    newest_unread_wa_id = None
    for m in rows:
        if m.direction == "in" and not m.read_at:
            m.read_at = datetime.utcnow()
            if m.channel == "whatsapp" and m.wa_message_id:
                newest_unread_wa_id = m.wa_message_id
    db.session.commit()
    if newest_unread_wa_id:
        try:
            _whatsapp_cloud_mark_read_raw(user["id"], newest_unread_wa_id)
        except Exception as mark_read_err:
            logging.error(f"[INBOX MARK READ ERROR] {mark_read_err}")
    assignment = InboxThreadAssignment.query.filter_by(
        owner_user_id=user["id"], contact_identifier=contact_identifier
    ).first()
    return jsonify({
        "messages": [m.to_dict() for m in rows],
        "assignment": assignment.to_dict() if assignment else None,
    }), 200


