@app.route("/api/inbox/reply", methods=["POST"])
@csrf.exempt
def inbox_reply():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    contact = (data.get("contact_identifier") or "").strip()
    body = (data.get("body") or "").strip()
    channel = (data.get("channel") or "email").strip().lower()
    reply_to_message_id = (data.get("reply_to_message_id") or "").strip() or None
    if not contact or not body:
        return jsonify({"error": "contact_identifier and body are required."}), 400
    sent = False
    out_wa_message_id = None
    if channel == "email":
        sent = _send_plain_email(contact, "Message from us", body)
    elif channel == "sms":
        sent = _send_sms_simple(contact, body)
    elif channel == "whatsapp":
        try:
            result = send_whatsapp_cloud_message(user["id"], contact, body, reply_to_message_id=reply_to_message_id)
            out_wa_message_id = ((result.get("messages") or [{}])[0]).get("id")
            sent = True
        except Exception as e:
            logging.error(f"[INBOX WHATSAPP REPLY] {e}")
    elif channel in XC_CHANNELS:
        try:
            out_wa_message_id = xc_send(user["id"], channel, contact, body) or None
            sent = True
        except Exception as e:
            logging.error(f"[INBOX {channel.upper()} REPLY] {e}")
            return jsonify({"error": str(e)}), 502
    if not sent:
        return jsonify({"error": "Could not send via that channel — check it's configured."}), 502
    msg = _inbox_log(user["id"], channel, contact, "out", body, wa_message_id=out_wa_message_id)
    return jsonify({"message": msg.to_dict() if msg else None}), 201


