@app.route("/api/referrals/redemptions/<int:red_id>/reward", methods=["POST"])
@csrf.exempt
def referrals_reward(red_id):
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    red = CustomerReferralRedemption.query.get(red_id)
    if not red:
        return jsonify({"error": "Redemption not found."}), 404
    ref = CustomerReferralCode.query.get(red.referral_code_id)
