@app.route("/api/insurance/policies/<int:policy_id>/pay-premium", methods=["POST"])
@csrf.exempt
@requires_feature_flag("parametric_insurance")
def insurance_policy_pay_premium(policy_id):
    """Records that the premium has been paid. Deliberately does not
    itself charge a card/mobile-money account -- which payment gateway
    to use varies per business (Stripe/Flutterwave/Paystack/etc.), so
    call this from that gateway's own success webhook/callback once the
    charge clears, rather than assuming one gateway here."""
    user, err = _erp_user_or_401()
    if err: return err
    policy = InsurancePolicy.query.filter_by(id=policy_id, owner_user_id=user["id"]).first()
    if not policy:
        return jsonify({"error": "Policy not found."}), 404
    if policy.status != "pending_quote":
        return jsonify({"error": f"Policy is not awaiting premium payment (status: {policy.status})."}), 400

    policy.premium_paid_at = datetime.utcnow()
    partner = InsurancePartner.query.filter_by(active=True).first()
    if partner:
        policy.underwriting_partner_id = partner.id
        policy.status = "active"
    else:
        policy.status = "pending_partner"
    db.session.commit()

    if policy.status == "pending_partner":
        return jsonify({
            "ok": True, "policy": policy.to_dict(),
            "note": ("Premium recorded, but this policy cannot bind/activate until an admin configures "
                      "a licensed underwriting partner (see /admin/insurance/partner)."),
        }), 200
    return jsonify({"ok": True, "policy": policy.to_dict()}), 200


