@app.route("/admin/insurance/partner", methods=["POST"])
@csrf.exempt
def admin_set_insurance_partner():
    """Configures the licensed insurer/reinsurer that actually bears
    policy risk. This is the structural gate that keeps Connect It from
    ever self-underwriting: no policy can move to 'active' status
    without a row here."""
    user, err = _status_admin_or_401()
