# ════════════════════════════════════════════════════════════

@app.route("/api/bookkeeping/scan-receipt", methods=["POST"])
@csrf.exempt
def bookkeeping_scan_receipt():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    if not anthropic_client:
        return jsonify({"error": "Receipt scanning isn't configured right now."}), 502
    data = request.get_json(silent=True) or {}
    image_b64 = data.get("image_base64")
    media_type = data.get("media_type", "image/jpeg")
    if not image_b64:
        return jsonify({"error": "image_base64 is required."}), 400
    gate_result = gate_ai_usage(user, "bookkeeping_scan_receipt")
    if gate_result is not None:
        return gate_result
    try:
        response = anthropic_client.messages.create(
            model="claude-sonnet-4-5", max_tokens=500,
            messages=[{
                "role": "user",
                "content": [
                    {"type": "image", "source": {"type": "base64", "media_type": media_type, "data": image_b64}},
                    {"type": "text", "text": (
                        "This is a photo of a business receipt or handwritten expense note. "
                        "Extract the vendor name, total amount, currency (guess USD if unclear), date "
                        "(YYYY-MM-DD, guess today if unreadable), and a short category "
                        "(e.g. 'stock', 'transport', 'utilities', 'rent'). "
                        "Reply with ONLY raw JSON, no markdown fences: "
                        '{"vendor": "...", "amount": 0.0, "currency": "USD", "date": "YYYY-MM-DD", "category": "..."}'
                    )},
                ],
            }],
        )
        raw = response.content[0].text.strip()
        raw = re.sub(r"^```(?:json)?|```$", "", raw.strip(), flags=re.MULTILINE).strip()
        extracted = json.loads(raw)
    except Exception as e:
        logging.error(f"[RECEIPT SCAN] {e}")
        return jsonify({"error": "Could not read that receipt — try a clearer photo."}), 502

    log = ReceiptScanLog(owner_user_id=user["id"], extracted_json=json.dumps(extracted))
    db.session.add(log); db.session.commit()
    return jsonify({"scan_id": log.id, "extracted": extracted}), 200


@app.route("/api/bookkeeping/confirm-scan", methods=["POST"])
@csrf.exempt
def bookkeeping_confirm_scan():
    """User has reviewed the OCR result (and can edit any field) — post
    it as a real ErpExpense + ledger entry."""
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    log = ReceiptScanLog.query.get(data.get("scan_id")) if data.get("scan_id") else None
    if log and log.owner_user_id != user["id"]:
        return jsonify({"error": "Scan not found."}), 404
    try:
        amount = float(data.get("amount") or 0)
        if amount <= 0: raise ValueError
    except Exception:
        return jsonify({"error": "amount must be a positive number."}), 400
    expense_date = _erp_parse_date(data.get("date"), default=datetime.utcnow().date())
    expense = ErpExpense(
        owner_user_id=user["id"], expense_date=expense_date, category=(data.get("category") or "general")[:80],
        vendor=(data.get("vendor") or "").strip()[:200] or None, amount=amount,
        currency=(data.get("currency") or "USD").upper()[:8], payment_method="scanned receipt",
        notes="Posted via OCR Bookkeeping scan.",
    )
    db.session.add(expense); db.session.flush()
    db.session.add(ErpLedgerEntry(
        owner_user_id=user["id"], entry_date=expense_date, kind="expense", account=expense.category or "General",
        description=f"Scanned receipt: {expense.vendor or 'expense'}", amount=-abs(amount),
        reference_type="expense", reference_id=expense.id,
    ))
    if log:
        log.confirmed = True; log.linked_expense_id = expense.id
    db.session.commit()
    return jsonify({"expense": expense.to_dict()}), 201


