@app.route("/api/inventory/forecast", methods=["GET"])
def inventory_forecast():
    user, err = _erp_user_or_401()
    if err: return err
    days = 30
    since = datetime.utcnow() - timedelta(days=days)
    items = InventoryItem.query.filter_by(user_id=user["id"], active=True).all()
    forecasts = []
    for item in items:
        sold_qty = (db.session.query(db.func.sum(PosSaleItem.quantity))
                    .join(PosSale, PosSale.id == PosSaleItem.sale_id)
                    .filter(PosSaleItem.product_id == item.id, PosSale.created_at >= since).scalar()) or 0
        daily_rate = sold_qty / days
        days_left = round(item.quantity / daily_rate, 1) if daily_rate > 0 else None
        suggested_reorder_qty = round(daily_rate * 30, 1) if daily_rate > 0 else None  # cover next 30 days
        if daily_rate > 0 and (days_left is None or days_left <= 14):
            forecasts.append({
                "product_id": item.id, "name": item.name, "current_stock": item.quantity,
                "daily_sales_rate": round(daily_rate, 2), "days_until_stockout": days_left,
                "suggested_reorder_qty": suggested_reorder_qty,
            })
    forecasts.sort(key=lambda f: (f["days_until_stockout"] is None, f["days_until_stockout"]))
    return jsonify({"reorder_suggestions": forecasts, "period_days": days}), 200


