# STAGE 112: CASH-CRISIS EARLY WARNING — ROUTES
# ════════════════════════════════════════════════════════════

def _cash_crisis_check(uid):
    since30 = datetime.utcnow().date() - timedelta(days=30)
    all_time = ErpLedgerEntry.query.filter_by(owner_user_id=uid).all()
    cash_position = round(sum(e.amount for e in all_time), 2)
    recent = [e for e in all_time if e.entry_date and e.entry_date >= since30]
    net_30d = round(sum(e.amount for e in recent), 2)
    daily_burn = round(-net_30d / 30, 2) if net_30d < 0 else 0
    days_until_zero = round(cash_position / daily_burn, 1) if daily_burn > 0 and cash_position > 0 else None
    at_risk = daily_burn > 0 and (days_until_zero is not None and days_until_zero <= 21)
    return {
        "cash_position_estimate": cash_position, "net_change_30d": net_30d,
        "daily_burn_rate": daily_burn, "days_until_zero": days_until_zero, "at_risk": at_risk,
    }


