@app.route("/api/cron/cash-crisis-alert", methods=["POST"])
@csrf.exempt
def cron_cash_crisis_alert():
    if not CRON_SECRET or request.headers.get("X-Cron-Secret") != CRON_SECRET:
        return jsonify({"error": "Not found."}), 404
    owners = {e.owner_user_id for e in ErpLedgerEntry.query.with_entities(ErpLedgerEntry.owner_user_id).distinct().all()}
    alerted = 0
    for uid in owners:
        status = _cash_crisis_check(uid)
        if status["at_risk"]:
            u = UserAccount.query.get(uid)
            if u and u.email:
                _send_plain_email(u.email, "Cash flow warning — Connect It",
                    f"At your current spending rate, your cash on hand may run out in about {status['days_until_zero']} days. "
                    f"Estimated cash position: ${status['cash_position_estimate']}. Open Connect It → Business Health Score for the full picture.")
                alerted += 1
    return jsonify({"ok": True, "alerts_sent": alerted}), 200


