# STAGE 113: DYNAMIC PRICE OPTIMIZATION — ROUTES
# ════════════════════════════════════════════════════════════

@app.route("/api/pricing/optimize", methods=["GET"])
def pricing_optimize():
    """Heuristic sell-through analysis, not true demand elasticity
    modelling — fast-selling + low-stock items get a raise suggestion,
    slow-moving + high-stock items get a discount suggestion."""
    user, err = _erp_user_or_401()
    if err: return err
    since = datetime.utcnow() - timedelta(days=30)
    items = InventoryItem.query.filter_by(user_id=user["id"], active=True).filter(InventoryItem.unit_price.isnot(None)).all()
    suggestions = []
    for item in items:
        sold_qty = (db.session.query(db.func.sum(PosSaleItem.quantity))
                    .join(PosSale, PosSale.id == PosSaleItem.sale_id)
                    .filter(PosSaleItem.product_id == item.id, PosSale.created_at >= since).scalar()) or 0
        stock = item.quantity or 0
        sell_through = (sold_qty / (sold_qty + stock)) if (sold_qty + stock) > 0 else 0
        if sold_qty >= 10 and sell_through > 0.7:
            suggestions.append({"product_id": item.id, "name": item.name, "current_price": item.unit_price,
                                 "suggested_price": round(item.unit_price * 1.08, 2), "reason": "Selling fast and running low — demand supports a small increase."})
        elif stock > 0 and sold_qty < stock * 0.15 and sold_qty < 3:
            suggestions.append({"product_id": item.id, "name": item.name, "current_price": item.unit_price,
                                 "suggested_price": round(item.unit_price * 0.9, 2), "reason": "Moving slowly with high stock — a discount may clear it faster."})
    return jsonify({"suggestions": suggestions, "period_days": 30}), 200


