# ════════════════════════════════════════════════════════════
# STAGE 116: MULTI-PARTY BARTER CLEARING HOUSE — ROUTES
# Heuristic cycle-finder over open BarterListing rows: an edge exists
# from listing A to listing B when they share a category and A's
# "seeking" text overlaps meaningfully with B's "offering" text. This
# is keyword overlap, not semantic matching — flagged as a starting
# point for the parties to confirm, not an automatic trade.
# ════════════════════════════════════════════════════════════

def _text_overlap(a: str, b: str) -> bool:
    wa = set(re.findall(r"[a-z]{3,}", (a or "").lower()))
    wb = set(re.findall(r"[a-z]{3,}", (b or "").lower()))
    stop = {"the", "and", "for", "with", "any", "some"}
    wa -= stop; wb -= stop
    return len(wa & wb) > 0


@app.route("/api/barter/find-cycles", methods=["GET"])
def barter_find_cycles():
    listings = BarterListing.query.filter_by(status="open").all()
    by_id = {l.id: l for l in listings}
    edges = defaultdict(list)
    for a in listings:
        for b in listings:
            if a.id == b.id or a.user_id == b.user_id: continue
            if a.category and b.category and a.category != b.category: continue
            if _text_overlap(a.seeking, b.offering):
                edges[a.id].append(b.id)

    cycles_found = []
    seen_sets = set()

    def dfs(start, current, path, depth):
        if depth > 4: return
        for nxt in edges.get(current, []):
            if nxt == start and len(path) >= 2:
                key = frozenset(path)
                if key not in seen_sets:
                    seen_sets.add(key)
                    cycles_found.append([by_id[i].to_dict() for i in path])
            elif nxt not in path:
                dfs(start, nxt, path + [nxt], depth + 1)

    for l in listings:
        dfs(l.id, l.id, [l.id], 1)
        if len(cycles_found) >= 20: break

    return jsonify({
        "cycles": cycles_found[:20],
        "note": "Keyword-based matching, not guaranteed — confirm details with the other parties before trading.",
    }), 200


