@app.route("/api/timebank/exchange", methods=["POST"])
@csrf.exempt
def timebank_exchange():
    """Log a completed exchange: the giver provided `hours` of `skill`
    to the receiver. Hours move for real — the receiver must have
    enough balance."""
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user: return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    receiver_id = data.get("receiver_user_id")
    try:
        hours = float(data.get("hours") or 1)
        if hours <= 0: raise ValueError
    except Exception:
        return jsonify({"error": "hours must be a positive number."}), 400
    skill = (data.get("skill") or "").strip()
    if not receiver_id or not skill:
        return jsonify({"error": "receiver_user_id and skill are required."}), 400
    receiver_member = _timebank_member(receiver_id)
    if receiver_member.hours_balance < hours:
        return jsonify({"error": "Receiver doesn't have enough time-bank hours for this exchange."}), 400
    giver_member = _timebank_member(user["id"])
    receiver_member.hours_balance -= hours
    giver_member.hours_balance += hours
    db.session.add(TimeBankTransaction(giver_user_id=user["id"], receiver_user_id=receiver_id, hours=hours,
                                        skill=skill[:160], note=(data.get("note") or "").strip()[:300] or None))
    db.session.commit()
    return jsonify({"my_balance": giver_member.hours_balance}), 201


