# ════════════════════════════════════════════════════════════
# STAGE 119: SAVINGS ROTATION ENGINE
# The existing Savings Group already tracks real contributions and
# payouts (SavingsGroup / SavingsGroupMember / SavingsTransaction).
# This adds the piece that was missing: a fixed rotation order so the
# group always knows whose turn it is to receive the pooled payout,
# plus a short integrity signature the organizer can read aloud, text,
# or forward over SMS/WhatsApp so members without data can verify the
# ledger hasn't been tampered with — a digital version of a stokvel
# book, without requiring everyone to be online at once.
# ════════════════════════════════════════════════════════════

def _erp_owns_savings_group(uid, group_id):
    g = SavingsGroup.query.get(group_id)
    return g if (g and g.owner_user_id == uid) else None


@app.route("/api/savings/groups/<int:group_id>/rotation-order", methods=["PUT"])
@csrf.exempt
def savings_group_set_rotation(group_id):
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user: return jsonify({"error": "Login required."}), 401
    group = _erp_owns_savings_group(user["id"], group_id)
    if not group: return jsonify({"error": "Savings group not found."}), 404
    data = request.get_json(silent=True) or {}
    ordered_ids = data.get("member_ids") or []
    if not ordered_ids:
        return jsonify({"error": "member_ids (ordered list) is required."}), 400
    members = {m.id: m for m in SavingsGroupMember.query.filter_by(group_id=group_id).all()}
    for pos, mid in enumerate(ordered_ids, start=1):
        if mid in members:
            members[mid].payout_position = pos
    db.session.commit()
    return jsonify({"members": [m.to_dict() for m in sorted(members.values(), key=lambda m: m.payout_position or 999)]}), 200


@app.route("/api/savings/groups/<int:group_id>/rotation-status", methods=["GET"])
def savings_group_rotation_status(group_id):
    user = _get_current_user()
    if not user: return jsonify({"error": "Login required."}), 401
    group = _erp_owns_savings_group(user["id"], group_id)
    if not group: return jsonify({"error": "Savings group not found."}), 404
    round_num = int(request.args.get("round") or 1)
    members = sorted(
        [m for m in SavingsGroupMember.query.filter_by(group_id=group_id, active=True).all() if m.payout_position],
        key=lambda m: m.payout_position,
    )
    if not members:
        return jsonify({"error": "Set a rotation order first (payout_position) before checking status."}), 400

    active_index = (round_num - 1) % len(members)
    recipient = members[active_index]
    contribution_due = group.contribution_amount or 0
    ledger_state = [{
        "member_id": m.id, "name": m.name, "payout_position": m.payout_position,
        "is_recipient_this_round": (m.id == recipient.id),
        "contribution_due": contribution_due,
    } for m in members]

    # Deterministic integrity signature — lets an organizer read/SMS a
    # short code that members can independently recompute (same
    # algorithm, same inputs) to confirm the ledger they were told
    # about matches what's actually recorded, without needing a live
    # connection to verify it.
    serialized = json.dumps(ledger_state, sort_keys=True) + f"|round={round_num}"
    digest = hashlib.sha256(serialized.encode("utf-8")).hexdigest()[:10].upper()

    return jsonify({
        "round": round_num, "recipient": recipient.to_dict(), "ledger": ledger_state,
        "total_pool_estimate": round(contribution_due * len(members), 2),
        "integrity_signature": f"ROTATION-{digest}",
    }), 200


# ════════════════════════════════════════════════════════════
# STAGE 120: VOICE TO DIGNITY ENGINE
# A founder records a voice note in their own words — no forms, no
# jargon. It's transcribed via the existing /api/transcribe (Whisper)
# route, then Claude structures the *content actually said* into a
# proper document. Nothing is invented: if a term wasn't mentioned, the
# generated document says "to be mutually agreed" rather than guessing.
# ════════════════════════════════════════════════════════════

@app.route("/api/voice-to-dignity/generate", methods=["POST"])
@csrf.exempt
def voice_to_dignity_generate():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user: return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    transcript = (data.get("transcribed_text") or "").strip()
    if not transcript:
        return jsonify({"error": "transcribed_text is required."}), 400
    doc_type = data.get("document_type") or "partnership agreement"
    founder_name = (data.get("founder_name") or "First Party").strip()
    partner_name = (data.get("partner_name") or "Second Party").strip()

    gate_result = gate_ai_usage(user, "voice_to_dignity_generate")
    if gate_result is not None:
        return gate_result

    prompt = (
        f"A small business founder recorded a spoken voice note describing their business terms in "
        f"plain, conversational language, without legal or business jargon. Your job is to honor exactly "
        f"what they said — do not invent terms, numbers, or conditions they didn't mention; where something "
        f"wasn't specified, write 'to be mutually agreed' rather than guessing.\n\n"
        f"Turn this into a complete, professional {doc_type} between {founder_name} and {partner_name}.\n\n"
        f"What the founder said, transcribed:\n\"{transcript}\"\n\n"
        f"Structure the document with clear sections (Parties, Intent, Terms, Payment, Duration, "
        f"Dispute Resolution, Signatures) written in plain but professional language that any bank, "
        f"lawyer, or institution would take seriously — while staying true to the founder's actual words."
    )
    generated, _ = generate_ai_reply(prompt, [])
    return jsonify({"document_html": format_ai_response(generated), "document_text": generated,
                     "source_transcript": transcript}), 200


# ════════════════════════════════════════════════════════════
# STAGE 121: PLOT-TWIST RADAR
# Real cash-buffer math from the founder's own numbers, combined with
# an AI-generated set of three concrete pivot options grounded in
# those specific numbers — not a generic risk essay.
# ════════════════════════════════════════════════════════════

PLOT_TWIST_RISK_LABELS = {
    "currency_devaluation": "a sudden local currency devaluation",
    "supply_chain_disruption": "a supply chain disruption (import delays, supplier shortage)",
    "infrastructure_failure": "infrastructure failure (power cuts, water shortages, fuel shortage)",
    "seasonal_drop": "a seasonal drop in foot traffic or demand",
}


@app.route("/api/plot-twist-radar/analyze", methods=["POST"])
@csrf.exempt
def plot_twist_radar_analyze():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user: return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    try:
        revenue = float(data.get("monthly_revenue") or 0)
        costs = float(data.get("operational_costs") or 0)
        if revenue <= 0 or costs <= 0: raise ValueError
    except Exception:
        return jsonify({"error": "monthly_revenue and operational_costs must be positive numbers."}), 400
    risk_key = (data.get("risk_factor") or "currency_devaluation").strip().lower()
    risk_label = PLOT_TWIST_RISK_LABELS.get(risk_key, risk_key.replace("_", " "))

    net_profit = round(revenue - costs, 2)
    margin_pct = round(net_profit / revenue * 100, 1) if revenue else 0
    cash_buffer_months = round(max(net_profit, 0) * 3 / costs, 1) if costs else 0
    if margin_pct <= 0:
        risk_level = "CRITICAL"
    elif margin_pct < 15:
        risk_level = "HIGH"
    elif margin_pct < 30:
        risk_level = "MEDIUM"
    else:
        risk_level = "LOW"

    gate_result = gate_ai_usage(user, "plot_twist_radar_analyze")
    if gate_result is not None:
        return gate_result

    prompt = (
        f"A small business has monthly revenue of ${revenue}, monthly operating costs of ${costs} "
        f"(net profit ${net_profit}, margin {margin_pct}%), and an estimated cash buffer of "
        f"{cash_buffer_months} months. They're stress-testing against {risk_label}.\n\n"
        f"Give exactly three short, concrete, numbered pivot strategies this specific business could act "
        f"on THIS WEEK if that risk hit — one operational, one financial, one focused on their customers/"
        f"community. Be specific and actionable (e.g. name a percentage, a timeframe, an action), not generic "
        f"advice. Keep the whole reply under 180 words."
    )
    pivots, _ = generate_ai_reply(prompt, [])

    return jsonify({
        "risk_level": risk_level, "net_profit": net_profit, "margin_pct": margin_pct,
        "cash_buffer_months": cash_buffer_months, "risk_factor": risk_label,
        "pivot_strategies": format_ai_response(pivots),
    }), 200


