# STAGE 124: VAT / COMPANY REGISTRY VALIDATION — ROUTES
# VIES (EU VAT validation) is genuinely public, free, no key. UK
# Companies House needs a free key from developer.company-information.
# service.gov.uk — gated honestly, same pattern as everywhere else.
# ════════════════════════════════════════════════════════════

@app.route("/api/compliance/vat-validate", methods=["GET"])
def compliance_vat_validate():
    country = (request.args.get("country") or "").strip().upper()
    vat_number = re.sub(r"[^0-9A-Za-z]", "", request.args.get("vat_number") or "")
    if not country or not vat_number:
        return jsonify({"error": "country and vat_number are required."}), 400
    try:
        resp = requests.get(
            f"https://ec.europa.eu/taxation_customs/vies/rest-api/ms/{country}/vat/{vat_number}", timeout=12,
        )
        body = resp.json()
        if resp.status_code >= 400:
            return jsonify({"error": body.get("userError", "VAT validation failed — check the country code and number.")}), 502
        return jsonify({
            "valid": body.get("isValid", False), "country": country, "vat_number": vat_number,
            "name": body.get("name"), "address": body.get("address"),
            "request_date": body.get("requestDate"),
        }), 200
    except Exception as e:
        logging.error(f"[VIES VAT VALIDATE] {e}")
        return jsonify({"error": "Could not reach the EU VAT validation service (VIES)."}), 502


@app.route("/api/compliance/uk-company-check", methods=["GET"])
def compliance_uk_company_check():
    if not COMPANIES_HOUSE_API_KEY:
        return jsonify({"error": "UK company lookup isn't configured — needs a free key from Companies House."}), 502
    company_number = (request.args.get("company_number") or "").strip()
    if not company_number:
        return jsonify({"error": "company_number is required."}), 400
    try:
        resp = requests.get(
            f"https://api.company-information.service.gov.uk/company/{company_number}",
            auth=(COMPANIES_HOUSE_API_KEY, ""), timeout=12,
        )
        if resp.status_code == 404:
            return jsonify({"error": "No company found with that number."}), 404
        body = resp.json()
        if resp.status_code >= 400:
            return jsonify({"error": "Companies House lookup failed."}), 502
        return jsonify({
            "company_name": body.get("company_name"), "company_number": body.get("company_number"),
            "status": body.get("company_status"), "type": body.get("type"),
            "incorporated_on": body.get("date_of_creation"),
            "registered_office": (body.get("registered_office_address") or {}),
        }), 200
    except Exception as e:
        logging.error(f"[COMPANIES HOUSE] {e}")
        return jsonify({"error": "Could not reach Companies House."}), 502


