@app.route("/api/tax/rates", methods=["GET"])
def tax_rates_lookup():
    country = (request.args.get("country") or "").strip().upper()
    if not country:
        return jsonify({"error": "country (ISO code, e.g. DE, US, ZA) is required."}), 400
    if country in NON_EU_TAX_REFERENCE:
        name, rate, snapshot = NON_EU_TAX_REFERENCE[country]
        return jsonify({
            "country": country, "tax_name": name, "standard_rate_pct": rate,
            "source": "static reference table", "snapshot_date": snapshot,
            "note": "Reference only — confirm the current rate with the local tax authority before filing.",
        }), 200
    try:
        resp = requests.get("https://api.vatcomply.com/rates", params={"country": country}, timeout=12)
        body = resp.json()
        if resp.status_code >= 400 or not body.get("rates"):
            return jsonify({"error": f"No live rate found for '{country}' — try the ISO 2-letter code."}), 404
        return jsonify({
            "country": country, "tax_name": "VAT", "standard_rate_pct": (body.get("rates") or {}).get("standard"),
            "reduced_rates": {k: v for k, v in (body.get("rates") or {}).items() if k != "standard"},
            "source": "vatcomply.com (live EU rate table)",
        }), 200
    except Exception as e:
        logging.error(f"[TAX RATES] {e}")
        return jsonify({"error": "Could not reach the tax rate service."}), 502


# ════════════════════════════════════════════════════════════
# STAGE 127: CROSS-BORDER PAYMENT COST COMPARATOR — ROUTES
# Wise's public comparisons endpoint (the same one their own public
# "compare providers" page uses) — no key required, real published fee
# data from multiple providers, not a guess.
# ════════════════════════════════════════════════════════════

@app.route("/api/payments/compare-transfer", methods=["GET"])
def payments_compare_transfer():
    source = (request.args.get("source") or "USD").strip().upper()
    target = (request.args.get("target") or "EUR").strip().upper()
    try:
        amount = float(request.args.get("amount") or 1000)
        if amount <= 0: raise ValueError
    except Exception:
        return jsonify({"error": "amount must be a positive number."}), 400
    try:
        resp = requests.get(
            "https://api.transferwise.com/v3/comparisons/",
            params={"sourceCurrency": source, "targetCurrency": target, "sendAmount": amount}, timeout=12,
        )
        body = resp.json()
        if resp.status_code >= 400:
            return jsonify({"error": "Could not fetch comparison data for that currency pair."}), 502
        providers = []
        for p in (body.get("providers") or []):
            for q in (p.get("quotes") or []):
                providers.append({
                    "provider": p.get("name"), "received_amount": q.get("receivedAmount"),
                    "fee": q.get("fee"), "rate": q.get("rate"), "delivery_estimate": q.get("deliveryEstimation"),
                })
        providers.sort(key=lambda x: (x["received_amount"] is None, -(x["received_amount"] or 0)))
        return jsonify({"source": source, "target": target, "send_amount": amount, "providers": providers[:15]}), 200
    except Exception as e:
        logging.error(f"[PAYMENT COMPARE] {e}")
        return jsonify({"error": "Could not reach the payment comparison service."}), 502


