# STAGE 128: WEATHER SUPPLY-CHAIN RISK — ROUTES
# Reuses the existing get_current_weather() OpenWeatherMap integration
# (Stage 23) against real supplier/customer city names — works for any
# location worldwide, not tied to one region.
# ════════════════════════════════════════════════════════════

SUPPLY_CHAIN_RISK_KEYWORDS = ["storm", "thunderstorm", "heavy", "extreme", "hurricane", "cyclone", "blizzard", "flood", "tornado"]


@app.route("/api/supply-chain/weather-risk", methods=["GET"])
def supply_chain_weather_risk():
    user = _get_current_user()
    if not user: return jsonify({"error": "Login required."}), 401
    locations = [l.strip() for l in (request.args.get("locations") or "").split(",") if l.strip()]
    if not locations:
        return jsonify({"error": "locations (comma-separated city names) is required."}), 400
    results = []
    for loc in locations[:10]:
        w = get_current_weather(user["id"], loc)
        if not w.get("ok"):
            results.append({"location": loc, "error": w.get("error")})
            continue
        weather = w["weather"]
        desc = (weather.get("description") or "").lower()
        at_risk = any(kw in desc for kw in SUPPLY_CHAIN_RISK_KEYWORDS) or (weather.get("wind_speed") or 0) > 15
        results.append({
            "location": weather.get("location") or loc, "country": weather.get("country"),
            "description": weather.get("description"), "temp": weather.get("temp"),
            "wind_speed": weather.get("wind_speed"), "at_risk": at_risk,
        })
    return jsonify({"locations": results}), 200


