# STAGE 130: TRADEMARK / BUSINESS-NAME CONFLICT CHECK — ROUTES
# US trademark search only (USPTO) — real conflicts within US
# jurisdiction, clearly scoped as such. Needs a free key from
# developer.uspto.gov; USPTO has changed API platforms before, so this
# surfaces the real HTTP error if the endpoint shape has moved rather
# than ever inventing a "no conflicts found" result.
# ════════════════════════════════════════════════════════════

@app.route("/api/legal/trademark-check", methods=["GET"])
def legal_trademark_check():
    if not USPTO_API_KEY:
        return jsonify({"error": "Trademark search isn't configured — needs a free API key from developer.uspto.gov."}), 502
    name = (request.args.get("name") or "").strip()
    if not name:
        return jsonify({"error": "name is required."}), 400
    try:
        resp = requests.get(
            "https://tmsearch.uspto.gov/api-v1/search",
            params={"q": name}, headers={"X-API-KEY": USPTO_API_KEY}, timeout=15,
        )
        body = resp.json()
        if resp.status_code >= 400:
            return jsonify({"error": f"USPTO search failed (HTTP {resp.status_code}) — the API may have changed; verify against uspto.gov directly."}), 502
        hits = body.get("results") or body.get("hits") or []
        return jsonify({
            "query": name, "jurisdiction": "United States (USPTO) only",
            "potential_conflicts": len(hits), "results": hits[:10],
            "note": "US trademark search only — for global clearance, also check WIPO Global Brand Database and consult a trademark attorney.",
        }), 200
    except Exception as e:
        logging.error(f"[TRADEMARK CHECK] {e}")
        return jsonify({"error": "Could not reach the USPTO trademark search service."}), 502


# ════════════════════════════════════════════════════════════
# STAGE 131: WPS OFFICE (KINGSOFT) INTEGRATION
# Same Server-to-Server OAuth shape as the existing Zoom integration:
# an App ID + App Secret (registered free at open.wps.cn) are
# exchanged for a short-lived access token on each call, BYOK-first.
#
# HONESTY NOTE (read before relying on this in production): WPS Open
# Platform's documentation is primarily published in Chinese and is
# less represented in this model's training data than Google's, Zoom's,
# or Twilio's equivalents — the OAuth flow shape below is correct in
# spirit (App ID + App Secret -> access token -> Bearer-authenticated
# API calls), but the exact token endpoint and conversion endpoint
# paths should be verified against open.wps.cn's current docs before
# depending on this in production. Every call here surfaces the real
# HTTP response on failure — it never fabricates a converted file or a
# "success" that didn't happen.
# ════════════════════════════════════════════════════════════

def _wps_get_access_token(user_id) -> tuple[str | None, str | None]:
    app_id = get_effective_credential(user_id, "wps_office", "app_id", WPS_APP_ID)
    app_secret = get_effective_credential(user_id, "wps_office", "app_secret", WPS_APP_SECRET)
    if not (app_id and app_secret):
        return None, "WPS Office is not configured. Add your WPS Open Platform App ID and App Secret under Integrations."
    try:
        r = requests.post(
            "https://openapi.wps.cn/oauthapi/v2/token",
            json={"app_id": app_id, "app_secret": app_secret, "grant_type": "client_credentials"},
            timeout=12,
        )
        body = r.json()
        token = body.get("access_token") or (body.get("data") or {}).get("access_token")
        if r.status_code >= 400 or not token:
            return None, body.get("msg") or body.get("message") or "WPS Office authentication failed — verify your App ID/Secret and the token endpoint in WPS Open Platform's current docs."
        return token, None
    except Exception as e:
        logging.error(f"[WPS AUTH ERROR] user={user_id}: {e}")
        return None, str(e)


@app.route("/api/wps/status", methods=["GET"])
def wps_status():
    user = _get_current_user()
    if not user: return jsonify({"error": "Login required."}), 401
    token, err = _wps_get_access_token(user["id"])
    if not token:
        return jsonify({"connected": False, "error": err}), 200
    return jsonify({"connected": True}), 200


@app.route("/api/wps/convert", methods=["POST"])
@csrf.exempt
def wps_convert_document():
    """Converts a document Connect It already generated (e.g. a
    contract, invoice, or report) to another format via WPS Office's
    cloud conversion — real API call, real file back, or a real error
    if the endpoint/credentials aren't right. See the honesty note
    above the token-exchange helper."""
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user: return jsonify({"error": "Login required."}), 401
    token, err = _wps_get_access_token(user["id"])
    if not token:
        return jsonify({"error": err}), 502
    data = request.get_json(silent=True) or {}
    file_url = (data.get("file_url") or "").strip()
    target_format = (data.get("target_format") or "pdf").strip().lower()
    if not file_url:
        return jsonify({"error": "file_url is required (a URL to the document to convert)."}), 400
    try:
        r = requests.post(
            "https://solution.wps.cn/api/developer/v1/office/convert",
            headers={"Authorization": f"Bearer {token}"},
            json={"url": file_url, "target_type": target_format},
            timeout=30,
        )
        body = r.json()
        if r.status_code >= 400:
            return jsonify({"error": body.get("msg") or f"WPS conversion failed (HTTP {r.status_code})."}), 502
        result_url = body.get("result_url") or (body.get("data") or {}).get("url")
        if not result_url:
            return jsonify({"error": "WPS Office didn't return a converted file URL."}), 502
        return jsonify({"converted_file_url": result_url, "target_format": target_format}), 200
    except Exception as e:
        logging.error(f"[WPS CONVERT] {e}")
        return jsonify({"error": "Could not reach WPS Office's conversion service."}), 502


# ── STAGE 138: ENGINE DIAGNOSIS — VEHICLE/DEVICE MANAGEMENT ─
# Read-only diagnostics scope: this stage only registers which vehicle
# a user's own OBD2 dongle belongs to, so later telemetry/readings can
# be grouped per car. No control commands anywhere in this module.
@app.route("/api/diagnostics/devices", methods=["POST"])
@csrf.exempt
def obd2_device_create():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    label = (data.get("device_label") or "").strip()
    if not label:
        return jsonify({"error": "device_label is required."}), 400
    vin = (data.get("vin") or "").strip().upper()
    if vin and len(vin) not in (0, 17):
        return jsonify({"error": "VIN should be 17 characters (or leave it blank)."}), 400
    try:
        year = int(data["vehicle_year"]) if data.get("vehicle_year") else None
    except (TypeError, ValueError):
        return jsonify({"error": "vehicle_year must be a number."}), 400

    try:
        dev = Obd2Device(
            user_id=user["id"], device_label=label[:120],
            vehicle_make=(data.get("vehicle_make") or "").strip()[:80] or None,
            vehicle_model=(data.get("vehicle_model") or "").strip()[:80] or None,
            vehicle_year=year, vin=vin[:32] or None,
        )
        db.session.add(dev); db.session.commit()
    except Exception as e:
        db.session.rollback(); logging.error(f"[OBD2 DEVICE CREATE] {e}")
        return jsonify({"error": "Could not save the vehicle/device."}), 500

    return jsonify({"device": dev.to_dict()}), 201


