# ── STAGE 144: ENGINE DIAGNOSIS — MAINTENANCE REMINDERS ─
# Mileage and/or date-based service reminders per vehicle. Due-soon logic
# lives in _maintenance_due_check() (defined near the model) so both the
# API and to_dict() stay in sync. Purely informational — nothing here
# schedules a real-world action on its own; it's up to the person to act.
@app.route("/api/diagnostics/maintenance", methods=["POST"])
@csrf.exempt
def maintenance_reminder_create():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    device_id = data.get("device_id")
    dev = Obd2Device.query.filter_by(id=device_id, user_id=user["id"]).first()
    if not dev:
        return jsonify({"error": "Device not found."}), 404
    task_name = (data.get("task_name") or "").strip()
    if not task_name:
        return jsonify({"error": "task_name is required (e.g. 'Oil change')."}), 400
    interval_km = data.get("interval_km")
    interval_months = data.get("interval_months")
    if not interval_km and not interval_months:
        return jsonify({"error": "Set at least one of interval_km or interval_months."}), 400

    def _i(key):
        try:
            return int(data[key]) if data.get(key) not in (None, "") else None
        except (TypeError, ValueError):
            return None

    try:
        rem = MaintenanceReminder(
            device_id=dev.id, user_id=user["id"], task_name=task_name[:120],
            interval_km=_i("interval_km"), interval_months=_i("interval_months"),
            last_done_km=_i("last_done_km"), current_km=_i("current_km"),
            last_done_at=datetime.utcnow() if data.get("last_done_now") else None,
        )
        db.session.add(rem); db.session.commit()
    except Exception as e:
        db.session.rollback(); logging.error(f"[MAINTENANCE CREATE] {e}")
        return jsonify({"error": "Could not save the reminder."}), 500
    return jsonify({"reminder": rem.to_dict()}), 201


