# ── STAGE 145: ENGINE DIAGNOSIS — FUEL EFFICIENCY TREND ─
# Real full-to-full fuel economy calculation: consumption between two
# consecutive full-tank fill-ups is the amount added at the *later* fill,
# divided by the distance covered since the *earlier* one. This is the
# standard method used by fuel-log apps and is accurate as long as fills
# are marked "full tank" honestly — partial fills are stored but skipped
# in the efficiency math since they can't be measured this way.
@app.route("/api/diagnostics/fuel", methods=["POST"])
@csrf.exempt
def fuel_entry_create():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    device_id = data.get("device_id")
    dev = Obd2Device.query.filter_by(id=device_id, user_id=user["id"]).first()
    if not dev:
        return jsonify({"error": "Device not found."}), 404
    try:
        odometer_km = float(data["odometer_km"])
        fuel_added_l = float(data["fuel_added_l"])
    except (KeyError, TypeError, ValueError):
        return jsonify({"error": "odometer_km and fuel_added_l are required numbers."}), 400
    if odometer_km <= 0 or fuel_added_l <= 0:
        return jsonify({"error": "odometer_km and fuel_added_l must be positive."}), 400
    try:
        cost = float(data["cost"]) if data.get("cost") not in (None, "") else None
    except (TypeError, ValueError):
        cost = None

    try:
        entry = FuelEfficiencyEntry(
            device_id=dev.id, user_id=user["id"], odometer_km=odometer_km,
            fuel_added_l=fuel_added_l, cost=cost,
            full_tank=bool(data.get("full_tank", True)),
        )
        db.session.add(entry); db.session.commit()
    except Exception as e:
        db.session.rollback(); logging.error(f"[FUEL ENTRY CREATE] {e}")
        return jsonify({"error": "Could not save the fuel entry."}), 500
    return jsonify({"entry": entry.to_dict()}), 201


@app.route("/api/diagnostics/fuel/<int:device_id>", methods=["GET"])
def fuel_entry_list(device_id):
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    dev = Obd2Device.query.filter_by(id=device_id, user_id=user["id"]).first()
    if not dev:
        return jsonify({"error": "Device not found."}), 404
    rows = (FuelEfficiencyEntry.query.filter_by(device_id=device_id, user_id=user["id"])
            .order_by(FuelEfficiencyEntry.odometer_km.asc()).all())

    trend = []
    full_rows = [r for r in rows if r.full_tank]
    for prev, cur in zip(full_rows, full_rows[1:]):
        dist_km = cur.odometer_km - prev.odometer_km
        if dist_km <= 0:
            continue
        l_per_100km = round(cur.fuel_added_l / (dist_km / 100.0), 2)
        km_per_l = round(dist_km / cur.fuel_added_l, 2)
        mpg_us = round(km_per_l * 2.35215, 1)
        trend.append({
            "from_km": prev.odometer_km, "to_km": cur.odometer_km, "distance_km": round(dist_km, 1),
            "fuel_added_l": cur.fuel_added_l, "l_per_100km": l_per_100km,
            "km_per_l": km_per_l, "mpg_us": mpg_us, "recorded_at": cur.recorded_at.isoformat() if cur.recorded_at else None,
            "cost": cur.cost, "cost_per_km": round(cur.cost / dist_km, 3) if cur.cost else None,
        })

    avg_l_per_100km = round(sum(t["l_per_100km"] for t in trend) / len(trend), 2) if trend else None

    return jsonify({
        "entries": [r.to_dict() for r in rows],
        "trend": trend,
        "average_l_per_100km": avg_l_per_100km,
    }), 200


