# ════════════════════════════════════════════════════════════
# STAGE 168: ESG / CARBON FOOTPRINT TRACKER — ROUTES
# Two ways in: (1) auto-scan existing ErpExpense records with a
# spend-based factor per category, (2) log a real activity (fuel,
# electricity, flights, freight) for a more accurate number. Both
# roll into one running total, category breakdown, and a downloadable
# PDF report any business can hand to a customer or lender asking
# "what's your carbon footprint."
# ════════════════════════════════════════════════════════════

# kg CO2e per unit for activities a business can measure directly.
# These are illustrative global averages (IPCC/DEFRA-style order of
# magnitude) meant for internal tracking, not a certified inventory —
# a business needing assurance-grade numbers should use factors from
# its own national inventory or a licensed carbon accountant.
ESG_ACTIVITY_FACTORS = {
    "fuel_litres_petrol":     2.31,
    "fuel_litres_diesel":     2.68,
    "electricity_kwh":        0.45,
    "flight_km_short_haul":   0.15,
    "flight_km_long_haul":    0.11,
    "road_freight_tonne_km":  0.10,
}

# kg CO2e per $1 of spend, by expense category — the fallback method
# for anything a business can't meter directly (used the same way as
# spend-based Scope 3 tools like Watershed/Normative for SMEs).
ESG_DEFAULT_SPEND_FACTORS = {
    "general":               0.40,
    "rent":                  0.30,
    "utilities":             0.60,
    "transport":             0.50,
    "stock":                 0.45,
    "inventory":             0.45,
    "travel":                0.90,
    "professional services": 0.20,
    "marketing":             0.25,
    "equipment":             0.35,
    "payroll":               0.10,
    "salaries":              0.10,
    "food":                  0.50,
    "catering":              0.50,
}


def _esg_seed_default_factors():
    if CarbonEmissionFactor.query.first():
        return
    for cat, factor in ESG_DEFAULT_SPEND_FACTORS.items():
        db.session.add(CarbonEmissionFactor(
            category=cat, kg_co2e_per_usd=factor,
            source="Illustrative global average — replace with your national inventory factors for compliance-grade reporting.",
        ))
    db.session.commit()


@app.route("/api/esg/emission-factors", methods=["GET"])
def esg_emission_factors_list():
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    _esg_seed_default_factors()
    factors = CarbonEmissionFactor.query.order_by(CarbonEmissionFactor.category.asc()).all()
    return jsonify({"factors": [f.to_dict() for f in factors],
                     "activity_factors": ESG_ACTIVITY_FACTORS}), 200


@app.route("/api/esg/scan-expenses", methods=["POST"])
@csrf.exempt
def esg_scan_expenses():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err:
        return err
    _esg_seed_default_factors()
    data = request.get_json(silent=True) or {}
    start = _erp_parse_date(data.get("start_date"), default=(datetime.utcnow().date() - timedelta(days=30)))
    end = _erp_parse_date(data.get("end_date"), default=datetime.utcnow().date())
    # Optional {"ZWG": 0.026, ...} currency->USD rates for non-USD expenses.
    # Anything not USD and not supplied here is treated 1:1 with USD, since
    # this app has no built-in FX feed — the trend and category shape are
    # still meaningful, but pass real rates for an accurate absolute total.
    fx_rates = data.get("fx_rates") or {}

    factors = {f.category.lower(): f.kg_co2e_per_usd for f in CarbonEmissionFactor.query.all()}
    already_scanned = {
        e.source_expense_id for e in
        CarbonFootprintEntry.query.filter_by(owner_user_id=user["id"], method="spend").all()
        if e.source_expense_id
    }
    expenses = ErpExpense.query.filter(
        ErpExpense.owner_user_id == user["id"],
        ErpExpense.expense_date >= start, ErpExpense.expense_date <= end,
    ).all()

    created = []
    try:
        for exp in expenses:
            if exp.id in already_scanned:
                continue
            currency = (exp.currency or "USD").upper()
            rate = 1.0 if currency == "USD" else float(fx_rates.get(currency, 1.0))
            usd_amount = (exp.amount or 0) * rate
            factor = factors.get((exp.category or "").lower(), factors.get("general", 0.4))
            entry = CarbonFootprintEntry(
                owner_user_id=user["id"], entry_date=exp.expense_date, category=exp.category or "general",
                description=exp.vendor, amount_spent=exp.amount, currency=currency,
                co2e_kg=usd_amount * factor, method="spend", source_expense_id=exp.id,
            )
            db.session.add(entry)
            created.append(entry)
        db.session.commit()
    except Exception as e:
        db.session.rollback(); logging.error(f"[ESG SCAN EXPENSES] {e}")
        return jsonify({"error": "Could not scan expenses."}), 500
    return jsonify({"created": len(created), "entries": [e.to_dict() for e in created]}), 201


@app.route("/api/esg/manual-entry", methods=["POST"])
@csrf.exempt
def esg_manual_entry():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err:
        return err
    data = request.get_json(silent=True) or {}
    activity = (data.get("activity_type") or "").strip()
    factor = ESG_ACTIVITY_FACTORS.get(activity)
    if not factor:
        return jsonify({"error": "Unknown activity_type.", "valid_types": list(ESG_ACTIVITY_FACTORS.keys())}), 400
    try:
        quantity = float(data.get("quantity") or 0)
        if quantity <= 0:
            raise ValueError()
    except (TypeError, ValueError):
        return jsonify({"error": "quantity must be a positive number."}), 400

    entry_date = _erp_parse_date(data.get("date"), default=datetime.utcnow().date())
    try:
        entry = CarbonFootprintEntry(
            owner_user_id=user["id"], entry_date=entry_date, category=activity,
            description=(data.get("description") or "").strip()[:300] or None,
            quantity=quantity, unit=activity, co2e_kg=quantity * factor, method="activity",
        )
        db.session.add(entry); db.session.commit()
    except Exception as e:
        db.session.rollback(); logging.error(f"[ESG MANUAL ENTRY] {e}")
        return jsonify({"error": "Could not log that activity."}), 500
    return jsonify({"entry": entry.to_dict()}), 201


