@app.route("/api/esg/summary", methods=["GET"])
def esg_summary():
    user, err = _erp_user_or_401()
    if err:
        return err
    entries = CarbonFootprintEntry.query.filter_by(owner_user_id=user["id"]).all()
    total_kg = sum(e.co2e_kg for e in entries)
    by_category, by_month = defaultdict(float), defaultdict(float)
    for e in entries:
        by_category[e.category] += e.co2e_kg
        month_key = e.entry_date.strftime("%Y-%m") if e.entry_date else "unknown"
        by_month[month_key] += e.co2e_kg
    return jsonify({
        "total_co2e_kg": round(total_kg, 2),
        "total_co2e_tonnes": round(total_kg / 1000, 3),
        "by_category": {k: round(v, 2) for k, v in by_category.items()},
        "by_month": dict(sorted(by_month.items())),
        "entry_count": len(entries),
    }), 200


@app.route("/api/esg/report.pdf", methods=["GET"])
def esg_report_pdf():
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    if not REPORTLAB_AVAILABLE:
        return jsonify({"error": "PDF generation isn't available on this server."}), 503

    entries = (CarbonFootprintEntry.query.filter_by(owner_user_id=user["id"])
               .order_by(CarbonFootprintEntry.entry_date.asc()).all())
    total_kg = sum(e.co2e_kg for e in entries)
    by_category = defaultdict(float)
    for e in entries:
        by_category[e.category] += e.co2e_kg

    buf = io.BytesIO()
    doc = SimpleDocTemplate(buf, pagesize=A4, rightMargin=40, leftMargin=40, topMargin=50, bottomMargin=40)
    styles = getSampleStyleSheet()
    story = [
        Paragraph("Carbon Footprint Estimate", styles["Title"]),
        Spacer(1, 6),
        Paragraph(f"Generated {datetime.utcnow().strftime('%d %b %Y')} — spend-based and activity-based estimate, "
                  f"not a certified audit.", styles["Normal"]),
        Spacer(1, 14),
        Paragraph(f"<b>Total: {round(total_kg/1000, 3)} tonnes CO2e</b> ({round(total_kg, 1)} kg) "
                  f"across {len(entries)} logged entries.", styles["Normal"]),
        Spacer(1, 14),
    ]
    if by_category:
        table_data = [["Category", "kg CO2e"]] + [[cat, f"{round(v, 1)}"] for cat, v in
                                                    sorted(by_category.items(), key=lambda x: -x[1])]
        story.append(Table(table_data, hAlign="LEFT"))
    else:
        story.append(Paragraph("No entries logged yet.", styles["Normal"]))
    doc.build(story)
    buf.seek(0)
    return Response(buf, mimetype="application/pdf",
                     headers={"Content-Disposition": 'attachment; filename="carbon-footprint-report.pdf"'})


# ════════════════════════════════════════════════════════════
# STAGE 169: KYC AUTO-FILL — AI DOCUMENT FIELD EXTRACTION
# Adds the one thing Stage 79's manual KYC record didn't have: reading
# the ID photo so the owner isn't typing the name/ID number by hand.
# It does NOT verify identity, authenticate the document, or approve
# anyone — it only returns a best-effort reading for the owner to
# check and correct before they submit via the existing, unchanged
# /api/kyc/submit review workflow. Regulated businesses that need
# legally-binding identity verification/AML checks should still use a
# licensed provider for that — this is a typing-time saver, not that.
# ════════════════════════════════════════════════════════════

@app.route("/api/kyc/extract", methods=["POST"])
@csrf.exempt
def kyc_extract():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    if not anthropic_client:
        return jsonify({"error": "Document reading isn't configured right now."}), 502

    image_b64, media_type = None, "image/jpeg"
    if request.content_type and "multipart/form-data" in request.content_type:
        f = request.files.get("id_document")
        if f and f.filename:
            image_b64 = base64.b64encode(f.read()).decode("utf-8")
            media_type = f.mimetype or media_type
    else:
        data = request.get_json(silent=True) or {}
        image_b64 = data.get("image_base64")
        media_type = data.get("media_type", media_type)

    if not image_b64:
        return jsonify({"error": "An ID document image is required."}), 400

    gate_result = gate_ai_usage(user, "kyc_extract")
    if gate_result is not None:
        return gate_result

    try:
        response = anthropic_client.messages.create(
            model="claude-sonnet-4-5", max_tokens=400,
            messages=[{
                "role": "user",
                "content": [
                    {"type": "image", "source": {"type": "base64", "media_type": media_type, "data": image_b64}},
                    {"type": "text", "text": (
                        "This is a photo of a government-issued ID document (passport, national ID, or "
                        "driver's licence) from any country. Extract what you can read. "
                        "Reply with ONLY raw JSON, no markdown fences: "
                        '{"full_name": "...", "id_type": "national_id|passport|drivers_license", '
                        '"id_number": "...", "date_of_birth": "YYYY-MM-DD or empty string", '
                        '"expiry_date": "YYYY-MM-DD or empty string", "issuing_country": "..."}. '
                        "Use an empty string for any field you cannot read clearly. Never guess an ID number."
                    )},
                ],
            }],
        )
        raw = response.content[0].text.strip()
        raw = re.sub(r"^```(?:json)?|```$", "", raw, flags=re.MULTILINE).strip()
        extracted = json.loads(raw)
    except Exception as e:
        logging.error(f"[KYC EXTRACT] {e}")
        return jsonify({"error": "Could not read that document — try a clearer photo, or fill it in by hand."}), 502

    if extracted.get("id_type") not in ("national_id", "passport", "drivers_license"):
        extracted["id_type"] = "national_id"
    return jsonify({
        "extracted": extracted,
        "note": "AI-read suggestion — please check it against the document before submitting.",
    }), 200


# ════════════════════════════════════════════════════════════
# STAGE 174: PARTNER & DEVELOPER API PLATFORM — ROUTES
# Read-only, scoped REST API + webhooks so a foreign bank, fintech,
# accounting platform, or government trade portal can integrate with
# a business's own data — with that business's own consent, via a key
# they generate and hand out themselves. Every key/webhook is scoped
# to its owner_user_id only; there is no cross-user data access. This
# is the self-serve path that actually gets outside developers to
# integrate, versus a sales conversation.
# ════════════════════════════════════════════════════════════

def _generate_api_key_pair():
    key_id = "pk_" + secrets.token_hex(12)
    secret = "sk_" + secrets.token_hex(24)
    secret_hash = hashlib.sha256(secret.encode()).hexdigest()
    return key_id, secret, secret_hash


def _require_partner_api_key(required_scope):
    """Returns (owner_user_id, is_test_mode, None) on success or
    (None, None, error_response). is_test_mode tells the caller whether to
    query/write real rows or sandbox rows (is_sandbox_demo=True) — see
    Stage 178."""
    auth = request.headers.get("Authorization", "")
    if not auth.startswith("Bearer "):
        return None, None, (jsonify({"error": "Missing Authorization: Bearer <key_id>.<secret> header."}), 401)
    token = auth[len("Bearer "):].strip()
    if "." not in token:
        return None, None, (jsonify({"error": "Malformed API key."}), 401)
    key_id, secret = token.split(".", 1)
    row = PartnerApiKey.query.filter_by(key_id=key_id, active=True).first()
    if not row or hashlib.sha256(secret.encode()).hexdigest() != row.secret_hash:
        return None, None, (jsonify({"error": "Invalid or revoked API key."}), 401)
    if required_scope not in (row.scopes or "").split(","):
        return None, None, (jsonify({"error": f"This key does not have the '{required_scope}' scope."}), 403)
    row.last_used_at = datetime.utcnow()
    db.session.commit()
    return row.owner_user_id, bool(row.is_test_mode), None


# STAGE 178: seeds a small, clearly-labelled set of real (but isolated)
