# NEW: durable delivery log + retry queue for outbound webhooks. Before
# this, a failed delivery just logged an error once and was gone — fine
# for a demo, not for a real integrator's production system, which
# expects retries and a way to see delivery history. Every attempt
# (success or failure) is recorded here.
class WebhookDelivery(db.Model):
    __tablename__    = "webhook_deliveries"
    id               = db.Column(db.Integer, primary_key=True)
    subscription_id  = db.Column(db.Integer, db.ForeignKey("webhook_subscriptions.id"), nullable=False, index=True)
    owner_user_id    = db.Column(db.Integer, nullable=False, index=True)
    event_type       = db.Column(db.String(60), nullable=False)
    payload_json      = db.Column(db.Text, nullable=False)
    status            = db.Column(db.String(20), nullable=False, default="pending")  # pending, delivered, failed (exhausted)
    attempt_count      = db.Column(db.Integer, nullable=False, default=0)
    last_status_code    = db.Column(db.Integer, nullable=True)
    last_error           = db.Column(db.String(500), nullable=True)
    next_retry_at         = db.Column(db.DateTime, nullable=True, index=True)
    created_at             = db.Column(db.DateTime, default=datetime.utcnow, index=True)
    delivered_at            = db.Column(db.DateTime, nullable=True)

    def to_dict(self):
        return {
            "id": self.id, "subscription_id": self.subscription_id, "event_type": self.event_type,
            "status": self.status, "attempt_count": self.attempt_count,
            "last_status_code": self.last_status_code, "last_error": self.last_error,
            "next_retry_at": self.next_retry_at.isoformat() if self.next_retry_at else None,
            "created_at": self.created_at.isoformat() if self.created_at else None,
            "delivered_at": self.delivered_at.isoformat() if self.delivered_at else None,
        }


# Exponential backoff schedule (minutes after each failed attempt) —
# 5 attempts total spread over ~a day, standard practice for webhook
# systems (roughly mirrors Stripe's retry cadence).
_WEBHOOK_RETRY_SCHEDULE_MINUTES = [5, 30, 120, 360, 1440]


def _attempt_webhook_delivery(sub: "WebhookSubscription", delivery: "WebhookDelivery") -> bool:
    """Makes exactly one HTTP attempt for a delivery row, updates the row
    in place, and returns True if it succeeded (2xx)."""
    body = delivery.payload_json
    signature = hmac.new(sub.secret.encode(), body.encode(), hashlib.sha256).hexdigest()
    delivery.attempt_count += 1
    try:
        resp = requests.post(sub.url, data=body, timeout=10,
                              headers={"Content-Type": "application/json", "X-Webhook-Signature": signature})
        delivery.last_status_code = resp.status_code
        if 200 <= resp.status_code < 300:
            delivery.status = "delivered"
            delivery.delivered_at = datetime.utcnow()
            delivery.next_retry_at = None
            delivery.last_error = None
            return True
        delivery.last_error = f"HTTP {resp.status_code}"
    except Exception as e:
        delivery.last_error = str(e)[:500]

    # Failed — schedule (or exhaust) a retry.
    idx = delivery.attempt_count - 1
    if idx < len(_WEBHOOK_RETRY_SCHEDULE_MINUTES):
        delivery.status = "pending"
        delivery.next_retry_at = datetime.utcnow() + timedelta(minutes=_WEBHOOK_RETRY_SCHEDULE_MINUTES[idx])
    else:
        delivery.status = "failed"
        delivery.next_retry_at = None
    return False


def _fire_webhook(owner_user_id, event_type, payload):
    """Best-effort outbound webhook delivery — never raises, so a
    delivery failure can never break the caller's real request. Makes
    one immediate attempt (most webhooks succeed on the first try, so
    this keeps the common case fast); on failure, the delivery is
    recorded and left for /api/cron/retry-webhooks to retry with
    backoff — see WebhookDelivery above."""
    _notify_team_channels(owner_user_id, event_type, payload)
    try:
        subs = WebhookSubscription.query.filter_by(owner_user_id=owner_user_id, active=True).all()
    except Exception:
        return
    for sub in subs:
        if event_type not in (sub.event_types or "").split(","):
            continue
        body = json.dumps({"event": event_type, "data": payload, "sent_at": datetime.utcnow().isoformat()})
        delivery = WebhookDelivery(
            subscription_id=sub.id, owner_user_id=owner_user_id,
            event_type=event_type, payload_json=body, status="pending",
        )
        db.session.add(delivery)
        ok = _attempt_webhook_delivery(sub, delivery)
        sub.last_status = str(delivery.last_status_code) if delivery.last_status_code else "error"
        sub.last_fired_at = datetime.utcnow()
    if subs:
        try:
            db.session.commit()
        except Exception:
            db.session.rollback()


@app.route("/api/cron/retry-webhooks", methods=["POST"])
@csrf.exempt
def cron_retry_webhooks():
    """Scheduled sweep of due webhook retries. Protected by CRON_SECRET,
    same pattern as the other cron jobs — point an external scheduler
    (cron, Render/Railway scheduled task, etc.) at this every few minutes."""
    if not CRON_SECRET or request.headers.get("X-Cron-Secret") != CRON_SECRET:
        return jsonify({"error": "Not found."}), 404

    due = (WebhookDelivery.query.filter_by(status="pending")
           .filter(WebhookDelivery.next_retry_at <= datetime.utcnow())
           .order_by(WebhookDelivery.next_retry_at.asc()).limit(200).all())
    delivered, still_failing, exhausted = 0, 0, 0
    for delivery in due:
        sub = WebhookSubscription.query.get(delivery.subscription_id)
        if not sub or not sub.active:
            delivery.status = "failed"
            delivery.next_retry_at = None
            exhausted += 1
            continue
        ok = _attempt_webhook_delivery(sub, delivery)
        if ok:
            delivered += 1
        elif delivery.status == "failed":
            exhausted += 1
        else:
            still_failing += 1
    db.session.commit()
    logging.info(f"[WEBHOOK RETRY SWEEP] processed={len(due)} delivered={delivered} "
                 f"still_pending={still_failing} exhausted={exhausted}")
    return jsonify({"processed": len(due), "delivered": delivered,
                     "still_pending": still_failing, "exhausted": exhausted}), 200


@app.route("/api/partner/webhooks/<int:webhook_id>/deliveries", methods=["GET"])
def partner_webhook_deliveries(webhook_id):
    """The delivery log a real integrator expects: every attempt for
    their webhook, success or failure, with status codes/errors."""
    user, err = _erp_user_or_401()
    if err: return err
    sub = WebhookSubscription.query.filter_by(id=webhook_id, owner_user_id=user["id"]).first()
    if not sub:
        return jsonify({"error": "Webhook not found."}), 404
    rows = (WebhookDelivery.query.filter_by(subscription_id=webhook_id)
            .order_by(WebhookDelivery.created_at.desc()).limit(100).all())
    return jsonify({"deliveries": [r.to_dict() for r in rows]}), 200


# --- Key & webhook management (session-authenticated, the business's own user) ---

@app.route("/api/partner/api-keys", methods=["POST"])
@csrf.exempt
def partner_api_key_create():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    valid_scopes = {"read:customers", "read:invoices", "read:expenses", "read:inventory",
                     "write:customers", "write:expenses", "write:inventory",
                     "read:marketplace_products", "write:marketplace_products",
                     "read:marketplace_orders", "write:marketplace_orders"}
    requested = data.get("scopes")
    if requested:
        scopes = [s.strip() for s in requested if s.strip() in valid_scopes]
        if not scopes:
            return jsonify({"error": "No valid scopes given.", "valid_scopes": list(valid_scopes)}), 400
    else:
        scopes = list(valid_scopes)
    is_test_mode = bool(data.get("is_test_mode"))
    key_id, secret, secret_hash = _generate_api_key_pair()
    key = PartnerApiKey(owner_user_id=user["id"], key_id=key_id, secret_hash=secret_hash,
                         label=(data.get("label") or "").strip()[:120] or None, scopes=",".join(scopes),
                         is_test_mode=is_test_mode)
    db.session.add(key); db.session.commit()
    if is_test_mode:
        _seed_partner_sandbox_demo_data(user["id"])
    return jsonify({
        "key": key.to_dict(mask_key=False), "api_key": f"{key_id}.{secret}",
        "note": "This is the only time the full key is shown — store it now. "
                "Use it as: Authorization: Bearer <api_key>." + (
                " This is a TEST-MODE key — it only sees isolated sandbox demo data, "
                "never your real business records." if is_test_mode else ""),
    }), 201


