@app.route("/api/partner/webhooks", methods=["POST"])
@csrf.exempt
def partner_webhook_create():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    url = (data.get("url") or "").strip()
    if not url.startswith("https://"):
        return jsonify({"error": "url must be a valid https:// endpoint."}), 400
    valid_events = {"invoice.paid", "customer.created", "expense.created", "inventory.low_stock"}
    events = [e.strip() for e in (data.get("event_types") or ["invoice.paid"]) if e.strip() in valid_events]
    if not events:
        return jsonify({"error": "No valid event_types given.", "valid_events": list(valid_events)}), 400
    sub = WebhookSubscription(owner_user_id=user["id"], url=url[:500], event_types=",".join(events),
                               secret=secrets.token_hex(20))
    db.session.add(sub); db.session.commit()
    return jsonify({
        "webhook": sub.to_dict(), "secret": sub.secret,
        "note": "Verify deliveries using the X-Webhook-Signature header "
                "(HMAC-SHA256 of the raw request body with this secret).",
    }), 201


