# --- Scoped read-only REST endpoints for external integrators (foreign
# banks, fintechs, accounting platforms, trade portals) ---

@app.route("/api/v1/partner/ping", methods=["GET"])
def partner_v1_ping():
    """Connectivity check for a user's own server/desktop app or agent —
    confirms the API key works before wiring up real sync logic. No
    scope required beyond a valid, active key."""
    auth = request.headers.get("Authorization", "")
    if not auth.startswith("Bearer ") or "." not in auth[7:]:
        return jsonify({"error": "Missing Authorization: Bearer <key_id>.<secret> header."}), 401
    key_id, secret = auth[7:].strip().split(".", 1)
    row = PartnerApiKey.query.filter_by(key_id=key_id, active=True).first()
    if not row or hashlib.sha256(secret.encode()).hexdigest() != row.secret_hash:
        return jsonify({"error": "Invalid or revoked API key."}), 401
    row.last_used_at = datetime.utcnow()
    db.session.commit()
    return jsonify({"ok": True, "scopes": (row.scopes or "").split(","),
                     "test_mode": bool(row.is_test_mode),
                     "server_time": datetime.utcnow().isoformat()}), 200


