@app.route("/api/v1/partner/customers", methods=["POST"])
@csrf.exempt
def partner_v1_customers_create():
    """Lets a user's OWN server, desktop app, or POS push a new customer
    record into Connect It — the write half of "connect your own server",
    scoped to write:customers. A test-mode key writes to the sandbox only."""
    owner_user_id, is_test, err = _require_partner_api_key("write:customers")
    if err: return err
    if _rate_limited(f"partner-write:customers:{owner_user_id}", max_attempts=60, window_seconds=60):
        return jsonify({"error": "Rate limit exceeded — max 60 write requests per minute per account."}), 429
    data = request.get_json(silent=True) or {}
    name = (data.get("name") or "").strip()
    if not name:
        return jsonify({"error": "'name' is required."}), 400
    row = ErpCustomer(owner_user_id=owner_user_id, name=name[:200],
                       email=(data.get("email") or "").strip()[:200] or None,
                       phone=(data.get("phone") or "").strip()[:64] or None,
                       address=(data.get("address") or "").strip()[:400] or None,
                       notes=(data.get("notes") or "").strip() or None,
                       is_sandbox_demo=is_test)
    db.session.add(row); db.session.commit()
    if not is_test:
        _fire_webhook(owner_user_id, "customer.created", row.to_dict())
    return jsonify({"customer": row.to_dict()}), 201


@app.route("/api/v1/partner/expenses", methods=["POST"])
@csrf.exempt
def partner_v1_expenses_create():
    """Push an expense/receipt record from an external accounting tool or
    desktop app running on the user's own machine. Scope: write:expenses."""
    owner_user_id, is_test, err = _require_partner_api_key("write:expenses")
    if err: return err
    if _rate_limited(f"partner-write:expenses:{owner_user_id}", max_attempts=60, window_seconds=60):
        return jsonify({"error": "Rate limit exceeded — max 60 write requests per minute per account."}), 429
    data = request.get_json(silent=True) or {}
    try:
        amount = float(data.get("amount") or 0)
    except (TypeError, ValueError):
        return jsonify({"error": "'amount' must be a number."}), 400
    try:
        expense_date = datetime.strptime(data.get("expense_date") or "", "%Y-%m-%d").date()
    except ValueError:
        expense_date = datetime.utcnow().date()
    row = ErpExpense(owner_user_id=owner_user_id, expense_date=expense_date,
                      category=(data.get("category") or "general").strip()[:80],
                      vendor=(data.get("vendor") or "").strip()[:200] or None,
                      amount=amount, currency=(data.get("currency") or "USD").strip()[:8],
                      payment_method=(data.get("payment_method") or "").strip()[:40] or None,
                      notes=(data.get("notes") or "").strip() or None,
                      is_sandbox_demo=is_test)
    db.session.add(row); db.session.commit()
    if not is_test:
        _fire_webhook(owner_user_id, "expense.created", row.to_dict())
    return jsonify({"expense": row.to_dict()}), 201


@app.route("/api/v1/partner/inventory/sync", methods=["POST"])
@csrf.exempt
def partner_v1_inventory_sync():
    """Lets a user's own POS, warehouse system, or desktop app push stock
    levels into Connect It (create-or-update by SKU). This is the core of
    real server/desktop integration: their system stays the source of
    truth, Connect It just mirrors it. Scope: write:inventory."""
    owner_user_id, is_test, err = _require_partner_api_key("write:inventory")
    if err: return err
    if _rate_limited(f"partner-write:inventory:{owner_user_id}", max_attempts=20, window_seconds=60):
        return jsonify({"error": "Rate limit exceeded — max 20 sync requests per minute per account (batch more items per call instead)."}), 429
    data = request.get_json(silent=True) or {}
    items = data.get("items")
    if not isinstance(items, list) or not items:
        return jsonify({"error": "'items' must be a non-empty array of {sku or name, quantity, ...}."}), 400

    synced, low_stock = [], []
    for it in items[:500]:
        sku  = (it.get("sku") or "").strip()[:64] or None
        name = (it.get("name") or "").strip()[:200]
        if not sku and not name:
            continue
        row = None
        if sku:
            row = InventoryItem.query.filter_by(user_id=owner_user_id, sku=sku, is_sandbox_demo=is_test).first()
        if not row and name:
            row = InventoryItem.query.filter_by(user_id=owner_user_id, name=name, is_sandbox_demo=is_test).first()
        if not row:
            row = InventoryItem(user_id=owner_user_id, name=name or sku, sku=sku, is_sandbox_demo=is_test)
            db.session.add(row)
        try:
            row.quantity = float(it.get("quantity", row.quantity or 0))
        except (TypeError, ValueError):
            pass
        if it.get("threshold") is not None:
            try: row.threshold = float(it["threshold"])
            except (TypeError, ValueError): pass
        if it.get("unit"): row.unit = str(it["unit"])[:32]
        if it.get("cost_price") is not None:
            try: row.cost_price = float(it["cost_price"])
            except (TypeError, ValueError): pass
        if it.get("unit_price") is not None:
            try: row.unit_price = float(it["unit_price"])
            except (TypeError, ValueError): pass
        row.updated_at = datetime.utcnow()
        synced.append(row)
        if row.threshold and row.quantity is not None and row.quantity <= row.threshold:
            low_stock.append(row)

    db.session.commit()
    if not is_test:
        for row in low_stock:
            _fire_webhook(owner_user_id, "inventory.low_stock", row.to_dict())
    return jsonify({"synced_count": len(synced), "low_stock_count": len(low_stock), "test_mode": is_test}), 200


