@app.route("/api/v1/partner/marketplace/products", methods=["POST"])
@csrf.exempt
def partner_v1_marketplace_products_create():
    """Creates a new Marketplace listing from a seller's own catalog
    system. Scope: write:marketplace_products. Same field validation as
    the in-app listing form (_product_fields_from) — no parallel
    validation path."""
    owner_user_id, is_test, err = _require_partner_api_key("write:marketplace_products")
    if err: return err
    if is_test:
        return jsonify({"error": "Marketplace endpoints aren't sandboxed yet — use a non-test-mode key."}), 400
    if _rate_limited(f"partner-write:marketplace_products:{owner_user_id}", max_attempts=20, window_seconds=60):
        return jsonify({"error": "Rate limit exceeded — max 20 requests per minute per account."}), 429
    data = request.get_json(silent=True) or {}
    fields = _product_fields_from(data)
    if not fields["name"] or fields["price"] is None or fields["price"] <= 0:
        return jsonify({"error": "name and a positive price are required."}), 400
    product = Product(seller_id=owner_user_id, **fields)
    db.session.add(product); db.session.commit()
    meilisearch_index_product(product)
    return jsonify({"product": product.to_dict(viewer_id=owner_user_id)}), 201


@app.route("/api/v1/partner/marketplace/products/<int:product_id>", methods=["PUT"])
@csrf.exempt
def partner_v1_marketplace_product_update(product_id):
    """The core POS/ERP sync operation: push a price and/or stock-level
    change for a listing this seller already owns. Scope:
    write:marketplace_products. Deliberately narrower than the in-app
    PUT (no image upload / price-tier editing here) — those stay a
    dashboard action."""
    owner_user_id, is_test, err = _require_partner_api_key("write:marketplace_products")
    if err: return err
    if is_test:
        return jsonify({"error": "Marketplace endpoints aren't sandboxed yet — use a non-test-mode key."}), 400
    product = Product.query.filter_by(id=product_id, seller_id=owner_user_id).first()
    if not product:
        return jsonify({"error": "Product not found (or not owned by this key's account)."}), 404
    data = request.get_json(silent=True) or {}
    if "name" in data and (data.get("name") or "").strip():
        product.name = data["name"].strip()[:150]
    if "description" in data:
        product.description = (data.get("description") or "").strip() or None
    if "price" in data:
        try:
            price = float(data["price"])
            if price > 0:
                product.price = price
        except (TypeError, ValueError):
            return jsonify({"error": "price must be a positive number."}), 400
    if "quantity_available" in data:
        try:
            product.quantity_available = max(0, int(data["quantity_available"]))
        except (TypeError, ValueError):
            return jsonify({"error": "quantity_available must be a whole number."}), 400
    if "is_active" in data:
        product.is_active = bool(data["is_active"])
    product.updated_at = datetime.utcnow()
    db.session.commit()
    meilisearch_index_product(product)
    return jsonify({"product": product.to_dict(viewer_id=owner_user_id)}), 200


@app.route("/api/v1/partner/marketplace/orders", methods=["GET"])
def partner_v1_marketplace_orders_list():
    """Lets a seller's own POS/ERP pull new Marketplace sales for
    fulfillment/bookkeeping. Scope: read:marketplace_orders. Optional
    ?since=<ISO datetime> and ?status= filters for incremental polling."""
    owner_user_id, is_test, err = _require_partner_api_key("read:marketplace_orders")
    if err: return err
    if is_test:
        return jsonify({"error": "Marketplace endpoints aren't sandboxed yet — use a non-test-mode key."}), 400
    q = ProductOrder.query.filter_by(seller_id=owner_user_id)
    status = (request.args.get("status") or "").strip()
    if status:
        q = q.filter(ProductOrder.status == status)
    since = (request.args.get("since") or "").strip()
    if since:
        try:
            q = q.filter(ProductOrder.created_at >= datetime.fromisoformat(since))
        except ValueError:
            return jsonify({"error": "since must be an ISO 8601 datetime."}), 400
    rows = q.order_by(ProductOrder.created_at.desc()).limit(500).all()
    return jsonify({"orders": [o.to_dict() for o in rows], "test_mode": False}), 200


@app.route("/api/v1/partner/marketplace/orders/<int:order_id>/tracking", methods=["POST"])
@csrf.exempt
def partner_v1_marketplace_order_set_tracking(order_id):
    """Reports a tracking number from the seller's own carrier account —
    distinct from /api/products/orders/<id>/ship, which buys a NEW label
    through Connect It's own DHL/FedEx/UPS integration. This route is for
    a seller whose own POS/ERP already shipped the order and just needs
    to tell Connect It the real tracking number. Scope:
    write:marketplace_orders. Same one-time guard as the in-app ship
    route: only a paid order with no tracking number yet."""
    owner_user_id, is_test, err = _require_partner_api_key("write:marketplace_orders")
    if err: return err
    if is_test:
        return jsonify({"error": "Marketplace endpoints aren't sandboxed yet — use a non-test-mode key."}), 400
    order = ProductOrder.query.filter_by(id=order_id, seller_id=owner_user_id).first()
    if not order:
        return jsonify({"error": "Order not found (or not owned by this key's account)."}), 404
    if order.status != "paid":
        return jsonify({"error": f"Can't add tracking to an order that isn't paid yet (status: {order.status})."}), 400
    if order.tracking_number:
        return jsonify({"error": f"This order already has a tracking number ({order.tracking_number})."}), 400
    data = request.get_json(silent=True) or {}
    carrier = (data.get("carrier") or "").strip()[:40]
    tracking_number = (data.get("tracking_number") or "").strip()[:120]
    if not carrier or not tracking_number:
        return jsonify({"error": "carrier and tracking_number are required."}), 400
    order.carrier = carrier
    order.tracking_number = tracking_number
    order.shipped_at = datetime.utcnow()
    db.session.commit()
    _escrow_maybe_release_milestone(order.id, "shipped")

    buyer = UserAccount.query.get(order.buyer_id)
    if buyer and buyer.whatsapp_number:
        try:
            send_whatsapp_cloud_message(
                buyer.id, buyer.whatsapp_number,
                f" Your order #{order.id} has shipped via {carrier} — tracking number {tracking_number}. "
                f"Check My Purchases for live status.")
        except Exception as e:
            logging.error(f"[PARTNER API SHIP WA NOTIFY ERROR] order={order.id}: {e}")
    _fire_webhook(owner_user_id, "marketplace.order_status_changed", order.to_dict())
    return jsonify({"ok": True, "order": order.to_dict()}), 200


