# --- Integration Partner Directory: submission, public list, admin review ---

@app.route("/api/partner/directory/submit", methods=["POST"])
@csrf.exempt
def partner_directory_submit():
    """A logged-in user (their own team, or a foreign bank/fintech/trade
    portal representative who signed up) submits an integration listing.
    Goes live only after an admin approves it."""
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    company_name = (data.get("company_name") or "").strip()
    if not company_name:
        return jsonify({"error": "'company_name' is required."}), 400
    valid_categories = {"bank", "fintech", "accounting_software", "trade_portal", "pos_desktop", "government", "other"}
    category = (data.get("category") or "other").strip().lower()
    if category not in valid_categories:
        category = "other"
    listing = IntegrationListing(
        submitted_by_id=user["id"], company_name=company_name[:200],
        country=(data.get("country") or "").strip()[:100] or None, category=category,
        website=(data.get("website") or "").strip()[:300] or None,
        contact_email=(data.get("contact_email") or "").strip()[:200] or None,
        description=(data.get("description") or "").strip() or None,
    )
    db.session.add(listing); db.session.commit()
    return jsonify({"listing": listing.to_dict(), "note": "Submitted for admin review."}), 201


@app.route("/api/partner/directory/<int:listing_id>/verify-gleif", methods=["POST"])
@csrf.exempt
def partner_directory_verify_gleif(listing_id):
    """Attaches a real, live GLEIF Legal Entity Identifier match to a
    directory listing — the "Verified" badge shown publicly. Callable by
    the listing's own submitter or an admin. Re-checks GLEIF live every
    time rather than trusting a stored value, and only sets the badge if
    the entity is currently ACTIVE with an ISSUED registration, so it
    can't go stale or be typed in by hand."""
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err

    listing = IntegrationListing.query.get(listing_id)
    if not listing:
        return jsonify({"error": "Listing not found."}), 404

    admin_user = UserAccount.query.get(user["id"])
    is_owner = listing.submitted_by_id == user["id"]
    is_admin = bool(admin_user) and (admin_user.is_admin or (admin_user.email or "").strip().lower() in ADMIN_EMAILS)
    if not (is_owner or is_admin):
        return jsonify({"error": "Only the listing's submitter or an admin can verify it."}), 403

    data = request.get_json(silent=True) or {}
    lei  = (data.get("lei") or "").strip().upper()
    if not lei:
        return jsonify({"error": "Provide the company's LEI code (from GLEIF, or your own compliance records)."}), 400

    if _rate_limited(f"gleif:user:{user['id']}", max_attempts=30, window_seconds=60):
        return jsonify({"error": "Too many verification requests. Please wait a moment and try again."}), 429

    try:
        resp = requests.get(GLEIF_LEI_RECORDS, params={"filter[lei]": lei}, timeout=12,
                             headers={"Accept": "application/vnd.api+json"})
    except Exception as e:
        logging.error(f"[DIRECTORY GLEIF VERIFY] {e}")
        return jsonify({"error": "Could not reach the GLEIF Global LEI database right now."}), 502

    if not resp.ok:
        return jsonify({"error": f"GLEIF API returned status {resp.status_code}"}), 502

    body = resp.json() if resp.text.strip() else {}
    records = body.get("data") or []
    if not records:
        return jsonify({"error": "No GLEIF record found for that LEI. Double-check the code, or note that not every business holds an LEI."}), 404

    simplified = _gleif_simplify(records[0])
    if simplified.get("entity_status") != "ACTIVE" or simplified.get("registration_status") != "ISSUED":
        return jsonify({
            "error": "This LEI's GLEIF record isn't currently ACTIVE/ISSUED, so it can't be used for the badge.",
            "gleif_record": simplified,
        }), 400

    listing.verified_lei = simplified.get("lei")
    listing.verified_legal_name = simplified.get("legal_name")
    listing.verified_at = datetime.utcnow()
    db.session.commit()

    logging.info(f"[DIRECTORY GLEIF VERIFY] listing_id={listing_id} verified as LEI={listing.verified_lei} by user_id={user['id']}")
    return jsonify({"listing": listing.to_dict(), "gleif_record": simplified}), 200


@app.route("/api/partner/directory", methods=["GET"])
def partner_directory_public_list():
    """Public — no login required. Shows only approved listings, so this
    page can genuinely be used to attract foreign businesses browsing
    what already integrates with Connect It."""
    category = (request.args.get("category") or "").strip().lower()
    verified_only = (request.args.get("verified_only") or "").strip() in ("1", "true", "yes")
    q = IntegrationListing.query.filter_by(status="approved")
    if category:
        q = q.filter_by(category=category)
    if verified_only:
        q = q.filter(IntegrationListing.verified_at.isnot(None))
    # Verified listings first (real GLEIF match), then most recently approved.
    rows = q.order_by(IntegrationListing.verified_at.isnot(None).desc(),
                       IntegrationListing.reviewed_at.desc()).limit(200).all()
    return jsonify({"listings": [r.to_dict() for r in rows]}), 200


@app.route("/api/admin/partner/directory", methods=["GET"])
def admin_partner_directory_list():
    """ADMIN ONLY. Review queue — defaults to pending listings."""
    admin_user, err = _require_admin()
    if err: return err
    status = (request.args.get("status") or "pending").strip().lower()
    q = IntegrationListing.query
    if status != "all":
        q = q.filter_by(status=status)
    rows = q.order_by(IntegrationListing.created_at.desc()).limit(500).all()
    return jsonify({"listings": [r.to_dict() for r in rows]}), 200


@app.route("/api/admin/partner/directory/<int:listing_id>/decide", methods=["POST"])
@csrf.exempt
def admin_partner_directory_decide(listing_id):
    """ADMIN ONLY. Approve or reject a submitted listing."""
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    admin_user, err = _require_admin()
    if err: return err
    data = request.get_json(silent=True) or {}
    decision = (data.get("decision") or "").strip().lower()
    if decision not in ("approved", "rejected"):
        return jsonify({"error": "'decision' must be 'approved' or 'rejected'."}), 400
    listing = IntegrationListing.query.get(listing_id)
    if not listing:
        return jsonify({"error": "Listing not found."}), 404
    listing.status = decision
    listing.reviewed_by_id = admin_user.id
    listing.review_note = (data.get("note") or "").strip() or None
    listing.reviewed_at = datetime.utcnow()
    db.session.commit()
    logging.info(f"[PARTNER DIRECTORY] admin_id={admin_user.id} {decision} listing_id={listing_id} ({listing.company_name})")
    return jsonify({"listing": listing.to_dict()}), 200


# ════════════════════════════════════════════════════════════
# STAGE 179: ACCOUNTING SYNC — XERO + QUICKBOOKS ONLINE
# Pushes a real ERP invoice to the user's own connected Xero or
# QuickBooks Online organisation via each platform's real REST API.
# Both use short-lived OAuth access tokens refreshed automatically from
# the stored refresh_token before every call.
# ════════════════════════════════════════════════════════════

def get_valid_xero_token(user_id):
    """Returns a live Xero access_token + tenant_id, refreshing the
    token first (Xero access tokens live 30 minutes)."""
    creds = get_user_credentials(user_id, "xero_accounting")
    if not creds:
        return None, None, "No Xero account connected. Add your Xero credentials under Integrations first."
    refresh_token = creds.get("refresh_token")
    client_id = creds.get("client_id")
    client_secret = creds.get("client_secret")
    tenant_id = creds.get("tenant_id")
    if not (refresh_token and client_id and client_secret and tenant_id):
        return None, None, "Xero connection is missing refresh_token/client_id/client_secret/tenant_id."
    try:
        resp = requests.post(
            "https://identity.xero.com/connect/token",
            data={"grant_type": "refresh_token", "refresh_token": refresh_token,
                  "client_id": client_id, "client_secret": client_secret},
            timeout=15,
        )
        if not resp.ok:
            return None, None, f"Xero token refresh failed: {resp.status_code} {resp.text[:200]}"
        body = resp.json()
        creds["access_token"] = body.get("access_token")
        creds["refresh_token"] = body.get("refresh_token", refresh_token)
        save_user_integration(user_id, "xero_accounting", creds)
        return creds["access_token"], tenant_id, None
    except Exception as e:
        logging.error(f"[XERO TOKEN REFRESH ERROR] user={user_id}: {e}")
        return None, None, f"Could not refresh Xero token: {e}"


def push_invoice_to_xero(user_id, invoice):
    """Creates (or updates, if already synced) this invoice as a real
    Xero ACCREC invoice in the user's connected Xero organisation."""
    access_token, tenant_id, err = get_valid_xero_token(user_id)
    if err:
        return None, err
    customer = ErpCustomer.query.get(invoice.customer_id) if invoice.customer_id else None
    contact_name = (customer.name if customer else None) or "Walk-in customer"
    items = ErpInvoiceItem.query.filter_by(invoice_id=invoice.id).all()
    line_items = [{
        "Description": (i.description or "Item")[:4000],
        "Quantity": i.quantity or 1, "UnitAmount": i.unit_price or 0, "AccountCode": "200",
    } for i in items] or [{
        "Description": invoice.notes or f"Invoice {invoice.invoice_number}",
        "Quantity": 1, "UnitAmount": invoice.total or 0, "AccountCode": "200",
    }]
    body = {"Invoices": [{
        "Type": "ACCREC", "Contact": {"Name": contact_name}, "LineItems": line_items,
        "Date": invoice.issue_date.isoformat() if invoice.issue_date else datetime.utcnow().date().isoformat(),
        "DueDate": invoice.due_date.isoformat() if invoice.due_date else None,
        "InvoiceNumber": invoice.invoice_number, "Status": "AUTHORISED",
        "CurrencyCode": invoice.currency or "USD",
    }]}
    if invoice.xero_invoice_id:
        body["Invoices"][0]["InvoiceID"] = invoice.xero_invoice_id
    try:
        resp = requests.post(
            "https://api.xero.com/api.xro/2.0/Invoices",
            headers={"Authorization": f"Bearer {access_token}", "Xero-tenant-id": tenant_id,
                     "Accept": "application/json", "Content-Type": "application/json"},
            json=body, timeout=20,
        )
        if not resp.ok:
            return None, f"Xero rejected the invoice: {resp.status_code} {resp.text[:400]}"
        result = resp.json()
        synced = (result.get("Invoices") or [{}])[0]
        if synced.get("InvoiceID"):
            invoice.xero_invoice_id = synced["InvoiceID"]
            db.session.commit()
        return synced, None
    except Exception as e:
        logging.error(f"[XERO PUSH INVOICE ERROR] user={user_id} invoice={invoice.id}: {e}")
        return None, f"Could not reach Xero: {e}"


@app.route("/api/integrations/xero/push-invoice/<int:invoice_id>", methods=["POST"])
@csrf.exempt
def xero_push_invoice(invoice_id):
    user, err = _erp_user_or_401()
    if err: return err
    invoice = ErpInvoice.query.filter_by(id=invoice_id, owner_user_id=user["id"]).first()
    if not invoice:
        return jsonify({"error": "Invoice not found."}), 404
    result, error = push_invoice_to_xero(user["id"], invoice)
    if error:
        return jsonify({"error": error}), 502
    return jsonify({"xero_invoice": result, "invoice": invoice.to_dict()}), 200


def get_valid_quickbooks_token(user_id):
    """Returns a live QuickBooks access_token + the right API host for
    the user's environment, refreshing the token first (QBO tokens
    live 60 minutes)."""
    creds = get_user_credentials(user_id, "quickbooks_accounting")
    if not creds:
        return None, None, None, "No QuickBooks account connected. Add your QuickBooks credentials under Integrations first."
    refresh_token = creds.get("refresh_token")
    client_id = creds.get("client_id")
    client_secret = creds.get("client_secret")
    realm_id = creds.get("realm_id")
    environment = (creds.get("environment") or "production").strip().lower()
    if not (refresh_token and client_id and client_secret and realm_id):
        return None, None, None, "QuickBooks connection is missing refresh_token/client_id/client_secret/realm_id."
    try:
        resp = requests.post(
            "https://oauth.platform.intuit.com/oauth2/v1/tokens/bearer",
            data={"grant_type": "refresh_token", "refresh_token": refresh_token},
            auth=(client_id, client_secret), timeout=15,
        )
        if not resp.ok:
            return None, None, None, f"QuickBooks token refresh failed: {resp.status_code} {resp.text[:200]}"
        body = resp.json()
        creds["access_token"] = body.get("access_token")
        creds["refresh_token"] = body.get("refresh_token", refresh_token)
        save_user_integration(user_id, "quickbooks_accounting", creds)
        host = "sandbox-quickbooks.api.intuit.com" if environment == "sandbox" else "quickbooks.api.intuit.com"
        return creds["access_token"], realm_id, host, None
    except Exception as e:
        logging.error(f"[QUICKBOOKS TOKEN REFRESH ERROR] user={user_id}: {e}")
        return None, None, None, f"Could not refresh QuickBooks token: {e}"


def _quickbooks_find_or_create_customer(access_token, realm_id, host, display_name):
    """QBO invoices require an existing CustomerRef id — looks the
    customer up by display name, creating one if this is their first
    invoice through this integration."""
    headers = {"Authorization": f"Bearer {access_token}", "Accept": "application/json"}
    safe_name = display_name.replace("'", "\\'")
    resp = requests.get(
        f"https://{host}/v3/company/{realm_id}/query", headers=headers,
        params={"query": f"select Id from Customer where DisplayName = '{safe_name}'"}, timeout=15,
    )
    if resp.ok:
        rows = (resp.json().get("QueryResponse") or {}).get("Customer") or []
        if rows:
            return rows[0]["Id"], None
    create_resp = requests.post(
        f"https://{host}/v3/company/{realm_id}/customer",
        headers={**headers, "Content-Type": "application/json"},
        json={"DisplayName": display_name}, timeout=15,
    )
    if not create_resp.ok:
        return None, f"Could not create QuickBooks customer: {create_resp.status_code} {create_resp.text[:300]}"
    return create_resp.json().get("Customer", {}).get("Id"), None


def push_invoice_to_quickbooks(user_id, invoice):
    access_token, realm_id, host, err = get_valid_quickbooks_token(user_id)
    if err:
        return None, err
    customer = ErpCustomer.query.get(invoice.customer_id) if invoice.customer_id else None
    contact_name = (customer.name if customer else None) or "Walk-in customer"
    customer_ref_id, cust_err = _quickbooks_find_or_create_customer(access_token, realm_id, host, contact_name)
    if cust_err:
        return None, cust_err
    items = ErpInvoiceItem.query.filter_by(invoice_id=invoice.id).all()
    lines = [{
        "Amount": (i.line_total if i.line_total else (i.quantity or 1) * (i.unit_price or 0)),
        "DetailType": "SalesItemLineDetail", "Description": (i.description or "Item")[:4000],
        "SalesItemLineDetail": {"Qty": i.quantity or 1, "UnitPrice": i.unit_price or 0},
    } for i in items] or [{
        "Amount": invoice.total or 0, "DetailType": "SalesItemLineDetail",
        "Description": invoice.notes or f"Invoice {invoice.invoice_number}",
        "SalesItemLineDetail": {"Qty": 1, "UnitPrice": invoice.total or 0},
    }]
    body = {
        "Line": lines, "CustomerRef": {"value": customer_ref_id},
        "DocNumber": invoice.invoice_number,
        "TxnDate": invoice.issue_date.isoformat() if invoice.issue_date else None,
        "DueDate": invoice.due_date.isoformat() if invoice.due_date else None,
        "CurrencyRef": {"value": invoice.currency or "USD"},
    }
    if invoice.quickbooks_invoice_id:
        get_resp = requests.get(
            f"https://{host}/v3/company/{realm_id}/invoice/{invoice.quickbooks_invoice_id}",
            headers={"Authorization": f"Bearer {access_token}", "Accept": "application/json"}, timeout=15,
        )
        if get_resp.ok:
            body["Id"] = invoice.quickbooks_invoice_id
            body["SyncToken"] = get_resp.json().get("Invoice", {}).get("SyncToken", "0")
            body["sparse"] = True
    try:
        resp = requests.post(
            f"https://{host}/v3/company/{realm_id}/invoice?minorversion=65",
            headers={"Authorization": f"Bearer {access_token}", "Accept": "application/json", "Content-Type": "application/json"},
            json=body, timeout=20,
        )
        if not resp.ok:
            return None, f"QuickBooks rejected the invoice: {resp.status_code} {resp.text[:400]}"
        result = resp.json().get("Invoice", {})
        if result.get("Id"):
            invoice.quickbooks_invoice_id = result["Id"]
            db.session.commit()
        return result, None
    except Exception as e:
        logging.error(f"[QUICKBOOKS PUSH INVOICE ERROR] user={user_id} invoice={invoice.id}: {e}")
        return None, f"Could not reach QuickBooks: {e}"


@app.route("/api/integrations/quickbooks/push-invoice/<int:invoice_id>", methods=["POST"])
@csrf.exempt
def quickbooks_push_invoice(invoice_id):
    user, err = _erp_user_or_401()
    if err: return err
    invoice = ErpInvoice.query.filter_by(id=invoice_id, owner_user_id=user["id"]).first()
    if not invoice:
        return jsonify({"error": "Invoice not found."}), 404
    result, error = push_invoice_to_quickbooks(user["id"], invoice)
    if error:
        return jsonify({"error": error}), 502
    return jsonify({"quickbooks_invoice": result, "invoice": invoice.to_dict()}), 200


# ════════════════════════════════════════════════════════════
# STAGE 180: TEAM ALERTS — SLACK + MICROSOFT TEAMS
# Posts a real, formatted message to the user's connected Slack or
# Teams channel whenever a genuine business event fires — reuses the
# exact same event hook (_fire_webhook) already driving the Partner
# API webhooks, so any event that already fires a webhook
# (invoice.paid, customer.created, expense.created,
# inventory.low_stock) now also alerts the team, with no new trigger
# points needed.
# ════════════════════════════════════════════════════════════

_TEAM_ALERT_MESSAGES = {
    "invoice.paid":        lambda p: f"Invoice {p.get('invoice_number', '')} was paid — {p.get('currency','')} {p.get('total','')}.",
    "customer.created":    lambda p: f"New customer added: {p.get('name', 'Unknown')}.",
    "expense.created":     lambda p: f"New expense logged: {p.get('vendor','')} — {p.get('currency','')} {p.get('amount','')}.",
    "inventory.low_stock": lambda p: f"Low stock alert: {p.get('name', p.get('sku',''))} is below its reorder threshold.",
}


def notify_slack(user_id, text: str) -> bool:
    webhook_url = get_effective_credential(user_id, "slack_webhook", "webhook_url")
    if not webhook_url:
        return False
    try:
        resp = requests.post(webhook_url, json={"text": text}, timeout=10)
        return resp.ok
    except Exception as e:
        logging.error(f"[SLACK NOTIFY ERROR] user={user_id}: {e}")
        return False


def notify_teams(user_id, text: str, title: str = "Connect It") -> bool:
    webhook_url = get_effective_credential(user_id, "teams_webhook", "webhook_url")
    if not webhook_url:
        return False
    card = {
        "@type": "MessageCard", "@context": "http://schema.org/extensions",
        "summary": title, "themeColor": "1D9E75", "title": title, "text": text,
    }
    try:
        resp = requests.post(webhook_url, json=card, timeout=10)
        return resp.ok
    except Exception as e:
        logging.error(f"[TEAMS NOTIFY ERROR] user={user_id}: {e}")
        return False


def _notify_team_channels(owner_user_id, event_type, payload):
    """Best-effort — never raises, same guarantee as _fire_webhook
    itself, so a Slack/Teams/Zapier outage can never break the real
    request that triggered the event.

    Zapier/Make dispatch reuses the existing trigger_zapier_event()
    (STAGE 36 — has HMAC request signing and a platform-level fallback
    URL that per-user webhooks don't need to duplicate) and, unlike the
    Slack/Teams branch below, fires for every event type here, not just
    the ones with a text formatter — Zapier/Make consume the raw
    payload directly, no formatting needed. Previously trigger_zapier_event
    was only called from 3 hand-picked call sites (Shopify orders, new
    leads, new bookings); wiring it in here means it now fires for every
    event that already reaches _fire_webhook (invoice.paid,
    customer.created, expense.created, inventory.low_stock, and any
    future event added there) with no new call sites needed."""
    try:
        trigger_zapier_event(owner_user_id, event_type, payload)
    except Exception as e:
        logging.error(f"[ZAPIER DISPATCH ERROR] user={owner_user_id} event={event_type}: {e}")
    formatter = _TEAM_ALERT_MESSAGES.get(event_type)
    if not formatter:
        return
    try:
        text = formatter(payload or {})
    except Exception:
        text = f"{event_type} event fired."
    try:
        notify_slack(owner_user_id, text)
        notify_teams(owner_user_id, text)
    except Exception as e:
        logging.error(f"[TEAM ALERT DISPATCH ERROR] user={owner_user_id} event={event_type}: {e}")


