# ════════════════════════════════════════════════════════════
# STAGE 182: OPEN BANKING RECONCILIATION — MONO + OKRA
# Pulls real transactions from the user's linked bank account (via
# Mono or Okra) and matches them against logged ERP expenses by amount
# and date, so discrepancies (an expense with no matching bank debit,
# or a bank debit with no logged expense) surface automatically instead
# of being found manually at month-end.
# ════════════════════════════════════════════════════════════

class BankTransaction(db.Model):
    """STAGE 242: persisted history of every real bank transaction ever
    fetched via Mono/Okra for a business, so reconciliation has a real
    audit trail instead of re-deriving everything from a transient
    in-memory list on every run. Dedupe key is (owner_user_id, provider,
    ref) — re-fetching an overlapping date window (which the autonomous
    cron does on purpose, to survive a missed run) never creates a
    duplicate row for the same underlying bank transaction."""
    __tablename__       = "bank_transactions"
    id                  = db.Column(db.Integer,  primary_key=True)
    owner_user_id       = db.Column(db.Integer,  db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    provider            = db.Column(db.String(16), nullable=False)  # "mono" | "okra"
    ref                 = db.Column(db.String(120), nullable=True, index=True)  # provider's own transaction id, when it has one
    amount              = db.Column(db.Float,    nullable=False)
    direction           = db.Column(db.String(8), nullable=False)   # "debit" | "credit"
    txn_date            = db.Column(db.Date,     nullable=True)
    description         = db.Column(db.String(300), nullable=True)
    match_status        = db.Column(db.String(20), nullable=False, default="unmatched", index=True)  # unmatched, matched_expense, matched_invoice, flagged, ignored
    matched_source_type = db.Column(db.String(20), nullable=True)   # "expense" | "invoice"
    matched_source_id   = db.Column(db.Integer,  nullable=True)
    fetched_at          = db.Column(db.DateTime, default=datetime.utcnow)

    __table_args__ = (
        db.UniqueConstraint("owner_user_id", "provider", "ref", name="uix_bank_txn_owner_provider_ref"),
    )

    def to_dict(self):
        return {
            "id": self.id, "provider": self.provider, "ref": self.ref, "amount": self.amount,
            "direction": self.direction, "date": self.txn_date.isoformat() if self.txn_date else None,
            "description": self.description, "match_status": self.match_status,
            "matched_source_type": self.matched_source_type, "matched_source_id": self.matched_source_id,
            "fetched_at": self.fetched_at.isoformat() if self.fetched_at else None,
        }


def fetch_mono_transactions(user_id, start_date=None, end_date=None):
    secret_key = get_effective_credential(user_id, "mono_banking", "secret_key")
    account_id = get_effective_credential(user_id, "mono_banking", "account_id")
    if not (secret_key and account_id):
        return None, "No Mono account connected. Add your Mono secret key and account_id under Integrations first."
    params = {}
    if start_date: params["start"] = start_date
    if end_date: params["end"] = end_date
    try:
        resp = requests.get(
            f"https://api.withmono.com/v2/accounts/{account_id}/transactions",
            headers={"mono-sec-key": secret_key}, params=params, timeout=20,
        )
        if not resp.ok:
            return None, f"Mono API error: {resp.status_code} {resp.text[:300]}"
        body = resp.json()
        rows = (body.get("data") or {}).get("data") if isinstance(body.get("data"), dict) else (body.get("data") or [])
        transactions = [{
            "amount": (r.get("amount", 0) / 100.0), "date": (r.get("date") or "")[:10],
            "description": r.get("narration", ""), "type": r.get("type", ""),
            "ref": str(r.get("_id") or r.get("id") or ""),
        } for r in rows]
        return transactions, None
    except Exception as e:
        logging.error(f"[MONO FETCH ERROR] user={user_id}: {e}")
        return None, f"Could not reach Mono: {e}"


def fetch_okra_transactions(user_id):
    public_key = get_effective_credential(user_id, "okra_banking", "public_key")
    secret_key = get_effective_credential(user_id, "okra_banking", "secret_key")
    customer_id = get_effective_credential(user_id, "okra_banking", "customer_id")
    account_id = get_effective_credential(user_id, "okra_banking", "account_id")
    if not (public_key and secret_key and customer_id and account_id):
        return None, "No Okra account connected. Add your Okra credentials under Integrations first."
    try:
        resp = requests.post(
            "https://api.okra.ng/v2/transactions/get",
            json={"auth": {"public_key": public_key, "secret_key": secret_key},
                  "record": {"customer": customer_id, "account": account_id}},
            timeout=20,
        )
        if not resp.ok:
            return None, f"Okra API error: {resp.status_code} {resp.text[:300]}"
        rows = (resp.json().get("data") or {}).get("transactions") or []
        transactions = [{
            "amount": abs(float(r.get("amount", 0))), "date": (r.get("date") or "")[:10],
            "description": r.get("narration", r.get("description", "")),
            "type": "debit" if float(r.get("amount", 0)) < 0 else "credit",
            "ref": str(r.get("id") or r.get("_id") or ""),
        } for r in rows]
        return transactions, None
    except Exception as e:
        logging.error(f"[OKRA FETCH ERROR] user={user_id}: {e}")
        return None, f"Could not reach Okra: {e}"


def _reconcile_expenses_with_bank(user_id, bank_transactions, days_window=30):
    """Naive but real amount+date matching between bank debits and
    logged ERP expenses. Marks matched expenses so re-running this
    doesn't re-match the same pair twice."""
    cutoff = datetime.utcnow().date() - timedelta(days=days_window)
    expenses = ErpExpense.query.filter(
        ErpExpense.owner_user_id == user_id, ErpExpense.bank_matched.is_(False),
        ErpExpense.expense_date >= cutoff,
    ).all()
    matched, unmatched_bank = [], []
    used_expense_ids = set()
    for txn in bank_transactions:
        if txn.get("type") not in ("debit", "Debit", ""):
            continue
        try:
            txn_date = datetime.strptime(txn["date"], "%Y-%m-%d").date() if txn.get("date") else None
        except Exception:
            txn_date = None
        found = None
        for exp in expenses:
            if exp.id in used_expense_ids:
                continue
            if abs((exp.amount or 0) - txn["amount"]) > 0.01:
                continue
            if txn_date and exp.expense_date and abs((exp.expense_date - txn_date).days) > 3:
                continue
            found = exp
            break
        if found:
            found.bank_matched = True
            found.bank_transaction_ref = txn.get("ref")
            used_expense_ids.add(found.id)
            matched.append({"expense": found.to_dict(), "bank_transaction": txn})
        else:
            unmatched_bank.append(txn)
    db.session.commit()
    unmatched_expenses = [e.to_dict() for e in expenses if e.id not in used_expense_ids]
    return {
        "matched_count": len(matched), "matched": matched,
        "unmatched_bank_transactions": unmatched_bank,
        "unmatched_expenses": unmatched_expenses,
    }


# ════════════════════════════════════════════════════════════
# STAGE 242: AUTONOMOUS BANK RECONCILIATION AGENT
# Widens Stage 182 from "a button a human has to remember to press" to
# a real background agent, on three fronts:
#   1. Persists every fetched transaction as a BankTransaction row —
#      a real bank-feed history a business can review, not just a
#      transient result thrown away after each click.
#   2. Also matches CREDITS against unpaid ErpInvoice rows (Stage 182
#      only ever matched debits against expenses) — a real incoming
#      customer payment now marks its invoice paid via the same
#      _erp_apply_invoice_payment() used by the manual "record payment"
#      endpoint and by Paynow webhooks, so all three paths stay
#      consistent.
#   3. A bank debit with no matching expense is a real signal from a
#      real bank, not a self-reported ERP anomaly — feeds straight into
#      the Stage 240/241 fraud system as an "unmatched_bank_debit" flag
#      (gated on this business's own off-hours abs-floor threshold from
#      FraudSettings, reusing Stage 241's tunable rather than adding a
#      fourth threshold to configure), so the two systems act as one.
#   4. /api/cron/bank-reconcile-run makes the whole thing autonomous:
#      point a scheduler (PythonAnywhere Scheduled Task, same as
#      /api/cron/tax-deadlines) at it daily and every connected
#      business's bank feed reconciles itself with no button-press.
# ════════════════════════════════════════════════════════════

def _bank_txn_persist(owner_user_id, provider, txn):
    """Upserts one fetched transaction into BankTransaction. Returns
    (row, is_new). Dedupe is by (owner, provider, ref) when the
    provider gave a ref; transactions with no ref (rare, provider-
    dependent) are always inserted since there's no safe key to dedupe
    them on — a known limitation, not a silent data-loss risk."""
    ref = (txn.get("ref") or "").strip() or None
    if ref:
        existing = BankTransaction.query.filter_by(owner_user_id=owner_user_id, provider=provider, ref=ref).first()
        if existing:
            return existing, False
    try:
        txn_date = datetime.strptime(txn["date"], "%Y-%m-%d").date() if txn.get("date") else None
    except Exception:
        txn_date = None
    direction = "credit" if str(txn.get("type", "")).lower() == "credit" else "debit"
    row = BankTransaction(
        owner_user_id=owner_user_id, provider=provider, ref=ref, amount=txn.get("amount") or 0,
        direction=direction, txn_date=txn_date, description=(txn.get("description") or "")[:300],
    )
    db.session.add(row)
    return row, True


def _reconcile_invoices_with_bank(owner_user_id, bank_transactions, days_window=30):
    """Credit-side counterpart to _reconcile_expenses_with_bank: matches
    incoming bank credits against this business's own unpaid invoices
    by amount + date, and actually applies the payment via the same
    shared helper used everywhere else in the app — a matched invoice
    isn't just flagged as matched, it's really marked paid."""
    invoices = (ErpInvoice.query
                .filter(ErpInvoice.owner_user_id == owner_user_id, ErpInvoice.status != "void")
                .filter((ErpInvoice.total - ErpInvoice.amount_paid) > 0.01)
                .all())
    matched, used_invoice_ids = [], set()
    for txn in bank_transactions:
        if str(txn.get("type", "")).lower() != "credit":
            continue
        try:
            txn_date = datetime.strptime(txn["date"], "%Y-%m-%d").date() if txn.get("date") else None
        except Exception:
            txn_date = None
        found = None
        for inv in invoices:
            if inv.id in used_invoice_ids:
                continue
            balance_due = round((inv.total or 0) - (inv.amount_paid or 0), 2)
            if abs(balance_due - txn["amount"]) > 0.01:
                continue
            if txn_date and inv.issue_date and (txn_date - inv.issue_date).days < 0:
                continue  # a payment can't predate the invoice that caused it
            if txn_date and inv.issue_date and (txn_date - inv.issue_date).days > days_window:
                continue
            found = inv
            break
        if found:
            _erp_apply_invoice_payment(found, txn["amount"], method="bank_auto")
            used_invoice_ids.add(found.id)
            matched.append({"invoice": found.to_dict(), "bank_transaction": txn})
    return matched


def _bank_reconcile_run(owner_user_id, provider, bank_transactions, days_window=30):
    """The single entry point both the on-demand route and the
    autonomous cron job call: persists the fetch, matches debits
    against expenses (Stage 182 logic, unchanged), matches credits
    against invoices (new), and raises a real fraud flag for any debit
    that stays unmatched above this business's own threshold."""
    for txn in bank_transactions:
        _bank_txn_persist(owner_user_id, provider, txn)
    db.session.commit()

    expense_result = _reconcile_expenses_with_bank(owner_user_id, bank_transactions, days_window=days_window)
    invoice_matches = _reconcile_invoices_with_bank(owner_user_id, bank_transactions, days_window=days_window)

    settings = _fraud_settings_for(owner_user_id)
    flag_floor = settings["offhours_abs_floor"]
    new_flags = 0
    for txn in expense_result["unmatched_bank_transactions"]:
        if (txn.get("amount") or 0) < flag_floor:
            continue
        ref_key = txn.get("ref") or f"{txn.get('date','')}-{txn.get('amount','')}-{txn.get('description','')[:40]}"
        _, was_new = _fraud_flag_upsert(
            owner_user_id, "bank_transaction", ref_key, "unmatched_bank_debit", "medium",
            "Bank debit with no matching expense",
            f"A real bank debit of {txn.get('amount'):,.2f} on {txn.get('date','an unknown date')} "
            f"({txn.get('description') or 'no description'}) has no matching logged expense. "
            f"Confirm this was a legitimate business payment and log it, or investigate.",
            amount=txn.get("amount"),
            occurred_at=datetime.strptime(txn["date"], "%Y-%m-%d") if txn.get("date") else None,
        )
        if was_new: new_flags += 1
    db.session.commit()

    return {
        "matched_count": expense_result["matched_count"],
        "matched": expense_result["matched"],
        "unmatched_bank_transactions": expense_result["unmatched_bank_transactions"],
        "unmatched_expenses": expense_result["unmatched_expenses"],
        "matched_invoices_count": len(invoice_matches),
        "matched_invoices": invoice_matches,
        "new_fraud_flags": new_flags,
    }


@app.route("/api/banking/reconcile", methods=["POST"])
@csrf.exempt
def banking_reconcile():
    """Body: provider ('mono' or 'okra'), days (optional, default 30).
    Same response shape as before (matched_count/unmatched_*) plus new
    fields (matched_invoices_count/matched_invoices/new_fraud_flags) —
    additive, so any existing caller keeps working."""
    user, err = _erp_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    provider = (data.get("provider") or "").strip().lower()
    days = int(data.get("days") or 30)
    if provider not in ("mono", "okra"):
        return jsonify({"error": "provider must be 'mono' or 'okra'."}), 400
    end_date = datetime.utcnow().date().isoformat()
    start_date = (datetime.utcnow().date() - timedelta(days=days)).isoformat()
    if provider == "mono":
        transactions, error = fetch_mono_transactions(user["id"], start_date, end_date)
    else:
        transactions, error = fetch_okra_transactions(user["id"])
    if error:
        return jsonify({"error": error}), 502
    result = _bank_reconcile_run(user["id"], provider, transactions, days_window=days)
    return jsonify(result), 200


@app.route("/api/banking/transactions", methods=["GET"])
def banking_transactions_list():
    """Real persisted bank-feed history for this business — separate
    from the transient per-run result above, so a business can browse
    everything ever fetched, not just the last click's output."""
    user, err = _erp_user_or_401()
    if err: return err
    q = BankTransaction.query.filter_by(owner_user_id=user["id"])
    match_status = request.args.get("match_status")
