@app.route("/api/ssh/connections", methods=["POST"])
@csrf.exempt
def ssh_save_connection():
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    blocked = gate_ai_usage(user, "ssh_session")
    if blocked: return blocked
    user_id = user["id"]
    data = request.get_json(silent=True) or {}
    name        = (data.get("name") or "").strip()
    host        = (data.get("host") or "").strip()
    username    = (data.get("username") or "").strip()
    auth_method = (data.get("auth_method") or "password").strip()

    try:
        port = int(data.get("port") or 22)
    except (TypeError, ValueError):
        return jsonify({"error": "'port' must be a number."}), 400

    if not host or not username:
        return jsonify({"error": "'host' and 'username' are required."}), 400
    if auth_method not in ("password", "key"):
        return jsonify({"error": "'auth_method' must be 'password' or 'key'."}), 400

    creds = {}
    if auth_method == "password":
        password = data.get("password") or ""
        if not password:
            return jsonify({"error": "'password' is required for auth_method='password'."}), 400
        creds["password"] = password
    else:
        private_key = data.get("private_key") or ""
        if not private_key:
            return jsonify({"error": "'private_key' (PEM text) is required for auth_method='key'."}), 400
        creds["private_key"] = private_key
        creds["passphrase"] = data.get("passphrase") or ""

    row = SSHConnectionProfile(
        user_id=user_id,
        name=name or f"{username}@{host}",
        host=host, port=port, username=username, auth_method=auth_method,
        credentials_encrypted=encrypt_secret_blob(creds),
    )
    db.session.add(row)
    db.session.commit()
    return jsonify({"ok": True, "connection": row.to_dict()}), 200


@app.route("/api/ssh/connections/<int:conn_id>", methods=["DELETE"])
@csrf.exempt
def ssh_delete_connection(conn_id):
    user_id = _current_user_id()
    if not user_id:
        return jsonify({"error": "Login required."}), 401
    row = SSHConnectionProfile.query.filter_by(id=conn_id, user_id=user_id).first()
    if not row:
        return jsonify({"error": "Connection not found."}), 404
    db.session.delete(row)
    db.session.commit()
    return jsonify({"ok": True}), 200


if FLASK_SOCKETIO_AVAILABLE:

    @socketio_app.on("connect", namespace="/ssh")
    def ssh_ws_connect(auth=None):
        """Every browser tab opens one persistent socket to this
        namespace when the SSH Terminal panel loads; individual shells
        are then opened/closed as events on top of it (see ssh_open
        below) so multiple terminals can share one socket if needed."""
        user_id = _ssh_ws_resolve_user(auth)
        if not user_id:
            logging.warning("[SSH WS] rejected handshake — no authenticated user.")
            return False
        with _ssh_socket_lock:
            _ssh_socket_users[request.sid] = user_id

    @socketio_app.on("disconnect", namespace="/ssh")
    def ssh_ws_disconnect():
        """Tears down every shell this browser tab had open — covers the
        tab closing, navigating away, or losing connectivity, all of
        which used to just leave a shell to expire via the idle sweep."""
        sid = request.sid
        with _ssh_socket_lock:
            _ssh_socket_users.pop(sid, None)
        with _ssh_sessions_lock:
            owned = [s_id for s_id, sess in _ssh_sessions.items() if sess["sid"] == sid]
        for session_id in owned:
            with _ssh_sessions_lock:
                sess = _ssh_sessions.get(session_id)
            if sess:
                sess["stop_event"].set()

    @socketio_app.on("ssh_open", namespace="/ssh")
    def ssh_ws_open(data):
        data = data or {}
        sid = request.sid
        with _ssh_socket_lock:
            user_id = _ssh_socket_users.get(sid)
        if not user_id:
            _sio_emit("ssh_error", {"error": "Login required."})
            return
        if not PARAMIKO_AVAILABLE:
            _sio_emit("ssh_error", {"error": "SSH support isn't installed on the server yet (paramiko missing)."})
            return

        _ssh_sweep_idle_sessions()
        conn_id = data.get("connection_id")

        if conn_id:
            row = SSHConnectionProfile.query.filter_by(id=conn_id, user_id=user_id).first()
            if not row:
                _sio_emit("ssh_error", {"error": "Connection not found."})
                return
            creds = decrypt_secret_blob(row.credentials_encrypted)
            host, port, username, auth_method = row.host, row.port, row.username, row.auth_method
            password = creds.get("password")
            private_key_text = creds.get("private_key")
            passphrase = creds.get("passphrase") or None
            row.last_used_at = datetime.utcnow()
            db.session.commit()
        else:
            host        = (data.get("host") or "").strip()
            username    = (data.get("username") or "").strip()
            auth_method = (data.get("auth_method") or "password").strip()
            try:
                port = int(data.get("port") or 22)
            except (TypeError, ValueError):
                _sio_emit("ssh_error", {"error": "'port' must be a number."})
                return
            if not host or not username:
                _sio_emit("ssh_error", {"error": "'host' and 'username' are required (or send a saved connection_id)."})
                return
            password = data.get("password")
            private_key_text = data.get("private_key")
            passphrase = data.get("passphrase") or None

        try:
            cols = int(data.get("cols") or 80)
            rows_ = int(data.get("rows") or 24)
        except (TypeError, ValueError):
            cols, rows_ = 80, 24

        client = paramiko.SSHClient()
        client.set_missing_host_key_policy(paramiko.AutoAddPolicy())
        try:
            if auth_method == "key" and private_key_text:
                pkey, key_err = None, None
                for key_cls in (paramiko.RSAKey, paramiko.Ed25519Key, paramiko.ECDSAKey, paramiko.DSSKey):
                    try:
                        pkey = key_cls.from_private_key(io.StringIO(private_key_text), password=passphrase)
                        break
                    except Exception as e:
                        key_err = e
                if pkey is None:
                    raise ValueError(f"Could not parse the private key ({key_err}).")
                client.connect(hostname=host, port=port, username=username, pkey=pkey, timeout=12)
            else:
                client.connect(hostname=host, port=port, username=username, password=password, timeout=12)

            channel = client.invoke_shell(term="xterm-256color", width=cols, height=rows_)
            channel.settimeout(0.5)
        except Exception as e:
            try:
                client.close()
            except Exception:
                pass
            logging.error(f"[SSH OPEN ERROR] user={user_id} host={host}: {e}")
            _sio_emit("ssh_error", {"error": f"Could not connect: {e}"})
            return

        session_id = uuid.uuid4().hex
        stop_event = threading.Event()
        with _ssh_sessions_lock:
            _ssh_sessions[session_id] = {
                "user_id": user_id, "sid": sid, "client": client, "channel": channel,
                "created_at": time.time(), "last_active": time.time(), "stop_event": stop_event,
            }
        _sio_emit("ssh_opened", {"session_id": session_id})
        socketio_app.start_background_task(_ssh_pump_output, session_id, sid, channel, stop_event)

    @socketio_app.on("ssh_input", namespace="/ssh")
    def ssh_ws_input(data):
        data = data or {}
        with _ssh_socket_lock:
            user_id = _ssh_socket_users.get(request.sid)
        session_id = data.get("session_id")
        sess = _ssh_get_owned_session(session_id, user_id)
        if not sess:
            _sio_emit("ssh_error", {"session_id": session_id, "error": "Session not found or already closed.", "closed": True})
            return
        try:
            text = data.get("data")
            if text:
                sess["channel"].send(text)
            sess["last_active"] = time.time()
        except Exception as e:
            logging.error(f"[SSH WRITE ERROR] {e}")
            _sio_emit("ssh_error", {"session_id": session_id, "error": str(e)})

    @socketio_app.on("ssh_resize", namespace="/ssh")
    def ssh_ws_resize(data):
        data = data or {}
        with _ssh_socket_lock:
            user_id = _ssh_socket_users.get(request.sid)
        session_id = data.get("session_id")
        sess = _ssh_get_owned_session(session_id, user_id)
        if not sess:
            return
        try:
            cols = int(data.get("cols") or 80)
            rows_ = int(data.get("rows") or 24)
            sess["channel"].resize_pty(width=cols, height=rows_)
            sess["last_active"] = time.time()
        except Exception as e:
            logging.error(f"[SSH RESIZE ERROR] {e}")

    @socketio_app.on("ssh_close", namespace="/ssh")
    def ssh_ws_close(data):
        data = data or {}
        with _ssh_socket_lock:
            user_id = _ssh_socket_users.get(request.sid)
        session_id = data.get("session_id")
        sess = _ssh_get_owned_session(session_id, user_id)
        if sess:
            sess["stop_event"].set()

    def _ssh_pump_output(session_id, sid, channel, stop_event):
        """Runs as a Flask-SocketIO background task for the lifetime of
        one SSH shell, pushing output to the browser the moment it
        arrives instead of waiting for the client to poll — this is the
        whole point of moving to WebSockets. Exits (and tears the shell
        down) when the remote shell closes, the idle sweep fires, or the
        client sends ssh_close / disconnects."""
        try:
            while not stop_event.is_set():
                try:
                    if channel.recv_ready():
                        chunk = channel.recv(65536)
                        if not chunk:
                            break
                        socketio_app.emit(
                            "ssh_output",
                            {"session_id": session_id, "data": chunk.decode("utf-8", errors="replace")},
                            room=sid, namespace="/ssh",
                        )
                        with _ssh_sessions_lock:
                            sess = _ssh_sessions.get(session_id)
                            if sess:
                                sess["last_active"] = time.time()
                        continue
                    if channel.closed or channel.exit_status_ready():
                        break
                    socketio_app.sleep(0.05)
                except Exception as e:
                    logging.error(f"[SSH PUMP ERROR] {e}")
                    break
        finally:
            socketio_app.emit("ssh_closed", {"session_id": session_id}, room=sid, namespace="/ssh")
            with _ssh_sessions_lock:
                sess = _ssh_sessions.pop(session_id, None)
            if sess:
                _ssh_close_native(sess)


