def i18n_get_translations(locale: str) -> dict:
    """Merges a locale's pack over English so a partial translation
    (or an unknown locale) never leaves a key blank in the UI."""
    base = dict(TRANSLATIONS.get("en", {}))
    base.update(TRANSLATIONS.get(locale, {}))
    return base


def i18n_format_number(value, locale: str = "en") -> str:
    """Locale-aware thousands/decimal separators without requiring the
    optional 'babel' package — most locales here use '1,234.56'; a small
    set (fr/pt/es/sw) conventionally use '1.234,56'."""
    try:
        value = float(value)
    except (TypeError, ValueError):
        return str(value)
    grouped = f"{value:,.2f}"
    if locale in ("fr", "pt", "es"):
        grouped = grouped.replace(",", "\u0001").replace(".", ",").replace("\u0001", ".")
    return grouped


def i18n_format_date(dt, locale: str = "en") -> str:
    """Locale-aware date rendering: ISO order (YYYY-MM-DD) for locales
    that conventionally use it, day-first (DD/MM/YYYY) otherwise."""
    if not dt:
        return ""
    if locale in ("zh",):
        return dt.strftime("%Y年%m月%d日")
    if locale in ("en", "hi"):
        return dt.strftime("%d/%m/%Y")
    return dt.strftime("%d/%m/%Y")


@app.route("/api/i18n/locales", methods=["GET"])
def i18n_list_locales():
    """Public — the language picker needs this before login too."""
    return jsonify({
        "locales": [
            {"code": code, **meta} for code, meta in SUPPORTED_LOCALES.items()
        ],
        "rtl_locales": sorted(RTL_LOCALES),
    }), 200


@app.route("/api/i18n/translations/<locale>", methods=["GET"])
def i18n_translations(locale):
    """Public — translations must load before/without auth (login screen,
    marketing pages)."""
    locale = (locale or "en").lower()
    if locale not in SUPPORTED_LOCALES:
        locale = "en"
    return jsonify({
        "locale": locale,
        "rtl": locale in RTL_LOCALES,
        "translations": i18n_get_translations(locale),
    }), 200


@app.route("/api/i18n/set-locale", methods=["POST"])
def i18n_set_locale():
    """Persists the signed-in user's language preference so it follows
    them across devices, not just this browser's localStorage."""
    user, err = _erp_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    locale = (data.get("locale") or "").strip().lower()
    if locale not in SUPPORTED_LOCALES:
        return jsonify({"error": "Unsupported locale."}), 400
    row = UserAccount.query.get(user["id"])
    if not row:
        return jsonify({"error": "Account not found."}), 404
    row.locale = locale
    try:
        db.session.commit()
    except Exception as e:
        db.session.rollback(); logging.error(f"[I18N SET LOCALE] {e}")
        return jsonify({"error": "Could not save language preference."}), 500
    return jsonify({"locale": locale, "rtl": locale in RTL_LOCALES}), 200


# ═══════════════════════════════════════════════════════════
# STAGE 186: SHIPPING & CUSTOMS — DHL EXPRESS, FEDEX, UPS
# Real rate quotes, tracking, and label creation against each carrier's
# actual API, using credentials the business brings from their own free
# developer account with that carrier (same BYOK pattern as every other
# integration in this file). Pairs with the existing HS Code Classifier
# (Stage 135) for the customs side: look up the HS code there, then use
# it in the customs_items you pass to /api/shipping/label for
# international shipments.
# ═══════════════════════════════════════════════════════════

DHL_BASE_URLS = {
    "sandbox":    "https://express.api.dhl.com/mydhlapi/test",
    "production": "https://express.api.dhl.com/mydhlapi",
}
FEDEX_BASE_URLS = {
    "sandbox":    "https://apis-sandbox.fedex.com",
    "production": "https://apis.fedex.com",
}
UPS_BASE_URLS = {
    "sandbox":    "https://wwwcie.ups.com",
    "production": "https://onlinetools.ups.com",
}


def _shipping_creds_or_error(user_id, carrier):
    provider_map = {"dhl": "dhl_shipping", "fedex": "fedex_shipping", "ups": "ups_shipping"}
    provider = provider_map.get(carrier)
    if not provider:
        return None, ("carrier must be 'dhl', 'fedex', or 'ups'.", 400)
    creds = get_user_credentials(user_id, provider)
    if not creds:
        return None, (f"Connect your {carrier.upper()} account under Integrations first.", 400)
    return creds, None


def _fedex_get_token(creds):
    env = creds.get("environment", "production")
    base = FEDEX_BASE_URLS.get(env, FEDEX_BASE_URLS["production"])
    resp = requests.post(
        f"{base}/oauth/token",
        data={
            "grant_type": "client_credentials",
            "client_id": creds.get("client_id", ""),
            "client_secret": creds.get("client_secret", ""),
        },
        timeout=15,
    )
    resp.raise_for_status()
    return resp.json()["access_token"], base


def _ups_get_token(creds):
    env = creds.get("environment", "production")
    base = UPS_BASE_URLS.get(env, UPS_BASE_URLS["production"])
    resp = requests.post(
        f"{base}/security/v1/oauth/token",
        data={"grant_type": "client_credentials"},
        auth=(creds.get("client_id", ""), creds.get("client_secret", "")),
        headers={"Content-Type": "application/x-www-form-urlencoded"},
        timeout=15,
    )
    resp.raise_for_status()
    return resp.json()["access_token"], base


def _fetch_carrier_rate_quotes(creds, carrier, from_addr, to_addr, weight_kg, dims):
    """STAGE 341: pulled out of the /api/shipping/rate route below so the
    checkout-time multi-carrier freight comparison can call this once
    per carrier a seller has actually connected, without a self HTTP
    call. Returns (quotes, error_message); quotes is a list (possibly
    empty) of {service, total_price, currency, delivery_date} on
    success — the exact same real per-carrier response shape either
    caller gets, never a fabricated one."""
    try:
        if carrier == "dhl":
            base = DHL_BASE_URLS.get(creds.get("environment", "production"), DHL_BASE_URLS["production"])
            resp = requests.get(
                f"{base}/rates",
                params={
                    "accountNumber": creds.get("account_number", ""),
                    "originCountryCode": from_addr["country_code"], "originPostalCode": from_addr.get("postal_code", ""), "originCityName": from_addr.get("city", ""),
                    "destinationCountryCode": to_addr["country_code"], "destinationPostalCode": to_addr.get("postal_code", ""), "destinationCityName": to_addr.get("city", ""),
                    "weight": weight_kg, "length": dims.get("length", 10), "width": dims.get("width", 10), "height": dims.get("height", 10),
                    "plannedShippingDate": datetime.utcnow().date().isoformat(), "isCustomsDeclarable": from_addr["country_code"] != to_addr["country_code"],
                    "unitOfMeasurement": "metric",
                },
                auth=(creds.get("client_id", ""), creds.get("client_secret", "")), timeout=20,
            )
            resp.raise_for_status()
            products = resp.json().get("products", [])
            quotes = [{"service": p.get("productName"), "total_price": (p.get("totalPrice") or [{}])[0].get("price"),
                       "currency": (p.get("totalPrice") or [{}])[0].get("priceCurrency"),
                       "delivery_date": (p.get("deliveryCapabilities") or {}).get("estimatedDeliveryDateAndTime")} for p in products]

        elif carrier == "fedex":
            token, base = _fedex_get_token(creds)
            resp = requests.post(
                f"{base}/rate/v1/rates/quotes",
                headers={"Authorization": f"Bearer {token}", "Content-Type": "application/json"},
                json={
                    "accountNumber": {"value": creds.get("account_number", "")},
                    "requestedShipment": {
                        "shipper": {"address": {"postalCode": from_addr.get("postal_code", ""), "countryCode": from_addr["country_code"]}},
                        "recipient": {"address": {"postalCode": to_addr.get("postal_code", ""), "countryCode": to_addr["country_code"]}},
                        "pickupType": "DROPOFF_AT_FEDEX_LOCATION",
                        "rateRequestType": ["ACCOUNT"],
                        "requestedPackageLineItems": [{
                            "weight": {"units": "KG", "value": weight_kg},
                            "dimensions": {"length": dims.get("length", 10), "width": dims.get("width", 10), "height": dims.get("height", 10), "units": "CM"},
                        }],
                    },
                },
                timeout=20,
            )
            resp.raise_for_status()
            rate_details = resp.json().get("output", {}).get("rateReplyDetails", [])
            quotes = [{"service": r.get("serviceType"),
                       "total_price": ((r.get("ratedShipmentDetails") or [{}])[0].get("totalNetCharge")),
                       "currency": ((r.get("ratedShipmentDetails") or [{}])[0].get("currency")),
                       "delivery_date": r.get("commit", {}).get("dateDetail", {}).get("dayFormat")} for r in rate_details]

        elif carrier == "ups":
            token, base = _ups_get_token(creds)
            resp = requests.post(
                f"{base}/api/rating/v2/Shop",
                headers={"Authorization": f"Bearer {token}", "Content-Type": "application/json"},
                json={
                    "RateRequest": {
                        "Shipment": {
                            "Shipper": {"ShipperNumber": creds.get("account_number", ""), "Address": {"PostalCode": from_addr.get("postal_code", ""), "CountryCode": from_addr["country_code"]}},
                            "ShipFrom": {"Address": {"PostalCode": from_addr.get("postal_code", ""), "CountryCode": from_addr["country_code"]}},
                            "ShipTo": {"Address": {"PostalCode": to_addr.get("postal_code", ""), "CountryCode": to_addr["country_code"]}},
                            "Package": [{
                                "PackagingType": {"Code": "02"},
                                "Dimensions": {"UnitOfMeasurement": {"Code": "CM"}, "Length": str(dims.get("length", 10)), "Width": str(dims.get("width", 10)), "Height": str(dims.get("height", 10))},
                                "PackageWeight": {"UnitOfMeasurement": {"Code": "KGS"}, "Weight": str(weight_kg)},
                            }],
                        }
                    }
                },
                timeout=20,
            )
            resp.raise_for_status()
            rated = (resp.json().get("RateResponse", {}) or {}).get("RatedShipment", [])
            if isinstance(rated, dict):
                rated = [rated]
            quotes = [{"service": r.get("Service", {}).get("Code"),
                       "total_price": r.get("TotalCharges", {}).get("MonetaryValue"),
                       "currency": r.get("TotalCharges", {}).get("CurrencyCode"),
                       "delivery_date": (r.get("GuaranteedDelivery") or {}).get("Date")} for r in rated]
        else:
            return None, "carrier must be 'dhl', 'fedex', or 'ups'."
        return quotes, None
    except requests.HTTPError as e:
        body = e.response.text[:500] if e.response is not None else str(e)
        logging.error(f"[SHIPPING RATE ERROR] carrier={carrier}: {body}")
        return None, f"{carrier.upper()} rejected the rate request: {body}"
    except Exception as e:
        logging.error(f"[SHIPPING RATE ERROR] carrier={carrier}: {e}")
        return None, f"Could not get a rate quote from {carrier.upper()}: {e}"


@app.route("/api/shipping/rate", methods=["POST"])
@csrf.exempt
def shipping_rate_quote():
    """Body: carrier ('dhl'|'fedex'|'ups'), from_address, to_address
    (each {city, postal_code, country_code, [state]}), weight_kg,
    dims_cm ({length, width, height})."""
    user, err = _erp_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    carrier = (data.get("carrier") or "").strip().lower()
    from_addr = data.get("from_address") or {}
    to_addr = data.get("to_address") or {}
    weight_kg = data.get("weight_kg")
    dims = data.get("dims_cm") or {}

    if not weight_kg or not from_addr.get("country_code") or not to_addr.get("country_code"):
        return jsonify({"error": "carrier, from_address.country_code, to_address.country_code, and weight_kg are all required."}), 400

    creds, error = _shipping_creds_or_error(user["id"], carrier)
    if error:
        return jsonify({"error": error[0]}), error[1]

    quotes, err_msg = _fetch_carrier_rate_quotes(creds, carrier, from_addr, to_addr, weight_kg, dims)
    if err_msg:
        return jsonify({"error": err_msg}), 400 if err_msg.startswith("carrier must be") else 502

    return jsonify({"ok": True, "carrier": carrier, "quotes": quotes}), 200


# ════════════════════════════════════════════════════════════
# STAGE 341: FREIGHT FORWARDER MARKETPLACE — MULTI-CARRIER QUOTE
# COMPARISON AT CHECKOUT
# Extends Stage 186's DHL/FedEx/UPS integration from "one carrier at a
# time, looked up manually under Integrations" into a real side-by-
# side comparison shown to the BUYER right at checkout — built
# entirely from whichever of those carriers the SELLER has actually
# connected their own account for (get_user_credentials, same BYOK
# pattern as everywhere else). Deliberately does NOT fabricate a
# "local forwarder" quote — there's no free, universal API for
# arbitrary local forwarders to source that from honestly, and this
# codebase never invents a number it can't back with a real call. A
# seller who hasn't connected any carrier gets an honest "no live
# carrier connected" response instead of an empty comparison that
# looks like a search that just found nothing.
# ════════════════════════════════════════════════════════════

@app.route("/api/marketplace/products/<int:product_id>/freight-quotes", methods=["POST"])
@csrf.exempt
def marketplace_freight_quotes(product_id):
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    product = Product.query.get(product_id)
    if not product or not product.is_active:
        return jsonify({"error": "Product not found."}), 404
    seller = UserAccount.query.get(product.seller_id)
    if not seller:
        return jsonify({"error": "Seller not found."}), 404

    data = request.get_json(silent=True) or {}
    to_addr = data.get("to_address") or {}
    if not to_addr.get("country_code"):
        return jsonify({"error": "to_address.country_code is required."}), 400
    try:
        quantity = max(1, int(data.get("quantity", product.min_order_quantity or 1)))
    except (TypeError, ValueError):
        quantity = product.min_order_quantity or 1

    if not product.weight_kg_per_unit:
        return jsonify({"error": "The seller hasn't declared a per-unit weight for this listing yet — freight quotes need that to calculate a rate."}), 400
    weight_kg = round(product.weight_kg_per_unit * quantity, 3)
    dims = data.get("dims_cm") or {}

    from_addr = {"city": product.city, "country_code": product.country_code, "postal_code": (data.get("from_postal_code") or "")}
    if not from_addr["country_code"]:
        return jsonify({"error": "The seller hasn't declared an origin country for this listing yet."}), 400

    quotes_by_carrier = []
    any_connected = False
    for carrier, provider in (("dhl", "dhl_shipping"), ("fedex", "fedex_shipping"), ("ups", "ups_shipping")):
        creds = get_user_credentials(seller.id, provider)
        if not creds:
            continue
        any_connected = True
        quotes, err_msg = _fetch_carrier_rate_quotes(creds, carrier, from_addr, to_addr, weight_kg, dims)
        quotes_by_carrier.append({"carrier": carrier.upper(), "error": err_msg, "quotes": (quotes or [])})

    if not any_connected:
        return jsonify({
            "ok": True, "product_id": product.id, "quantity": quantity, "weight_kg": weight_kg,
            "quotes_by_carrier": [], "cheapest_first": [],
            "note": "This seller hasn't connected a carrier account yet — no live freight quotes available for this listing.",
        }), 200

    # Flatten every real quote across every connected carrier and sort
    # by price so the cheapest option — regardless of which carrier —
    # surfaces first. This is the actual comparison a buyer wants
    # instead of several separate per-carrier lists to eyeball.
    flat = []
    for entry in quotes_by_carrier:
        for q in entry["quotes"]:
            if q.get("total_price") is not None:
                flat.append(dict(q, carrier=entry["carrier"]))
    try:
        flat.sort(key=lambda q: float(q["total_price"]))
    except (TypeError, ValueError):
        pass

    return jsonify({
        "ok": True, "product_id": product.id, "quantity": quantity, "weight_kg": weight_kg,
        "quotes_by_carrier": quotes_by_carrier, "cheapest_first": flat,
    }), 200


def _shipping_track_core(user_id, carrier: str, tracking_number: str):
    """Returns (result_dict, None) on success or (None, (message, http_status))
    on failure. Shared by the /api/shipping/track route and the
    track_shipment MCP tool so the carrier-specific logic lives in one place."""
    creds, error = _shipping_creds_or_error(user_id, carrier)
    if error:
        return None, error

    try:
        if carrier == "dhl":
            resp = requests.get(
                "https://api-eu.dhl.com/track/shipments",
                params={"trackingNumber": tracking_number},
                headers={"DHL-API-Key": creds.get("client_id", "")}, timeout=20,
            )
            resp.raise_for_status()
            shipments = resp.json().get("shipments", [])
            s = shipments[0] if shipments else {}
            events = [{"timestamp": e.get("timestamp"), "description": e.get("description"), "location": (e.get("location") or {}).get("address", {}).get("addressLocality")}
                      for e in (s.get("events") or [])]
            status = {"status": (s.get("status") or {}).get("statusCode"), "description": (s.get("status") or {}).get("description")}

        elif carrier == "fedex":
            token, base = _fedex_get_token(creds)
            resp = requests.post(
                f"{base}/track/v1/trackingnumbers",
                headers={"Authorization": f"Bearer {token}", "Content-Type": "application/json"},
                json={"trackingInfo": [{"trackingNumberInfo": {"trackingNumber": tracking_number}}], "includeDetailedScans": True},
                timeout=20,
            )
            resp.raise_for_status()
            track_results = (resp.json().get("output", {}).get("completeTrackResults") or [{}])[0].get("trackResults", [{}])
            t = track_results[0] if track_results else {}
            events = [{"timestamp": e.get("date"), "description": e.get("eventDescription"), "location": (e.get("scanLocation") or {}).get("city")}
                      for e in (t.get("scanEvents") or [])]
            status = {"status": (t.get("latestStatusDetail") or {}).get("code"), "description": (t.get("latestStatusDetail") or {}).get("description")}

        elif carrier == "ups":
            token, base = _ups_get_token(creds)
            resp = requests.get(
                f"{base}/api/track/v1/details/{tracking_number}",
                headers={"Authorization": f"Bearer {token}", "transId": secrets.token_hex(8), "transactionSrc": "Connect It"},
                timeout=20,
            )
            resp.raise_for_status()
            shipments = resp.json().get("trackResponse", {}).get("shipment", [])
            pkg = ((shipments[0] if shipments else {}).get("package") or [{}])[0]
            events = [{"timestamp": a.get("date", "") + " " + a.get("time", ""), "description": a.get("status", {}).get("description"), "location": a.get("location", {}).get("address", {}).get("city")}
                      for a in (pkg.get("activity") or [])]
            status = {"status": (pkg.get("currentStatus") or {}).get("code"), "description": (pkg.get("currentStatus") or {}).get("description")}
        else:
            return None, ("carrier must be 'dhl', 'fedex', or 'ups'.", 400)
    except requests.HTTPError as e:
        body = e.response.text[:500] if e.response is not None else str(e)
        logging.error(f"[SHIPPING TRACK ERROR] carrier={carrier}: {body}")
        return None, (f"{carrier.upper()} rejected the tracking request: {body}", 502)
    except Exception as e:
        logging.error(f"[SHIPPING TRACK ERROR] carrier={carrier}: {e}")
        return None, (f"Could not track that shipment with {carrier.upper()}: {e}", 502)

    return {"carrier": carrier, "tracking_number": tracking_number, "status": status, "events": events}, None


@app.route("/api/shipping/track", methods=["POST"])
@csrf.exempt
def shipping_track():
    """Body: carrier ('dhl'|'fedex'|'ups'), tracking_number."""
    user, err = _erp_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    carrier = (data.get("carrier") or "").strip().lower()
    tracking_number = (data.get("tracking_number") or "").strip()
    if not tracking_number:
        return jsonify({"error": "tracking_number is required."}), 400

    result, error = _shipping_track_core(user["id"], carrier, tracking_number)
    if error:
        return jsonify({"error": error[0]}), error[1]
    return jsonify({"ok": True, **result}), 200


def _shipping_create_label_core(user_id, carrier, from_addr, to_addr, weight_kg, dims, description, customs_items, service_code=None):
    """Returns (tracking_number, label_base64, None) on success or
    (None, None, (message, http_status)) on failure. Shared by the
    /api/shipping/label route and the Trade-Assurance-aware
    /api/products/orders/<id>/ship endpoint so the carrier-specific
    payload logic lives in exactly one place."""
    is_international = from_addr.get("country_code") != to_addr.get("country_code")
    creds, error = _shipping_creds_or_error(user_id, carrier)
    if error:
        return None, None, error

    try:
        if carrier == "dhl":
            base = DHL_BASE_URLS.get(creds.get("environment", "production"), DHL_BASE_URLS["production"])
            payload = {
                "plannedShippingDateAndTime": datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%S GMT+00:00"),
                "productCode": service_code or "P",
                "accounts": [{"typeCode": "shipper", "number": creds.get("account_number", "")}],
                "customerDetails": {
                    "shipperDetails": {"postalAddress": {"cityName": from_addr["city"], "postalCode": from_addr["postal_code"], "countryCode": from_addr["country_code"], "addressLine1": from_addr["street"]}, "contactInformation": {"companyName": from_addr.get("company", from_addr["name"]), "fullName": from_addr["name"], "phone": from_addr.get("phone", "")}},
                    "receiverDetails": {"postalAddress": {"cityName": to_addr["city"], "postalCode": to_addr["postal_code"], "countryCode": to_addr["country_code"], "addressLine1": to_addr["street"]}, "contactInformation": {"companyName": to_addr.get("company", to_addr["name"]), "fullName": to_addr["name"], "phone": to_addr.get("phone", "")}},
                },
                "content": {
                    "packages": [{"weight": weight_kg, "dimensions": {"length": dims.get("length", 10), "width": dims.get("width", 10), "height": dims.get("height", 10)}}],
                    "isCustomsDeclarable": is_international,
                    "description": description,
                    "unitOfMeasurement": "metric",
                    **({"exportDeclaration": {"lineItems": [{"number": i + 1, "description": it.get("description"), "price": it.get("unit_value"), "quantity": {"value": it.get("quantity", 1), "unitOfMeasurement": "PCS"}, "commodityCodes": [{"typeCode": "outbound", "value": it.get("hs_code", "")}], "exportControlClassification": "EAR99", "manufacturerCountry": it.get("country_of_origin", "")} for i, it in enumerate(customs_items)]}} if is_international else {}),
                },
            }
            resp = requests.post(f"{base}/shipments", json=payload,
                                  auth=(creds.get("client_id", ""), creds.get("client_secret", "")), timeout=30)
            resp.raise_for_status()
            body = resp.json()
            tracking_number = body.get("shipmentTrackingNumber")
            docs = body.get("documents", [])
            label_b64 = next((d.get("content") for d in docs if d.get("typeCode") == "label"), None)

        elif carrier == "fedex":
            token, base = _fedex_get_token(creds)
            payload = {
                "labelResponseOptions": "URL_ONLY",
                "requestedShipment": {
                    "shipper": {"contact": {"personName": from_addr["name"], "phoneNumber": from_addr.get("phone", "")}, "address": {"streetLines": [from_addr["street"]], "city": from_addr["city"], "postalCode": from_addr["postal_code"], "countryCode": from_addr["country_code"]}},
                    "recipients": [{"contact": {"personName": to_addr["name"], "phoneNumber": to_addr.get("phone", "")}, "address": {"streetLines": [to_addr["street"]], "city": to_addr["city"], "postalCode": to_addr["postal_code"], "countryCode": to_addr["country_code"]}}],
                    "shipDatestamp": datetime.utcnow().date().isoformat(),
                    "serviceType": service_code or ("INTERNATIONAL_PRIORITY" if is_international else "FEDEX_GROUND"),
                    "packagingType": "YOUR_PACKAGING",
                    "pickupType": "DROPOFF_AT_FEDEX_LOCATION",
                    "requestedPackageLineItems": [{"weight": {"units": "KG", "value": weight_kg}, "dimensions": {"length": dims.get("length", 10), "width": dims.get("width", 10), "height": dims.get("height", 10), "units": "CM"}}],
                    **({"customsClearanceDetail": {"commodities": [{"description": it.get("description"), "quantity": it.get("quantity", 1), "quantityUnits": "PCS", "unitPrice": {"amount": it.get("unit_value"), "currency": it.get("currency", "USD")}, "countryOfManufacture": it.get("country_of_origin", ""), "harmonizedCode": it.get("hs_code", "")} for it in customs_items]}} if is_international else {}),
                    "shippingChargesPayment": {"paymentType": "SENDER"},
                    "accountNumber": {"value": creds.get("account_number", "")},
                },
            }
            resp = requests.post(f"{base}/ship/v1/shipments", headers={"Authorization": f"Bearer {token}", "Content-Type": "application/json"}, json=payload, timeout=30)
            resp.raise_for_status()
            body = resp.json()
            piece = (body.get("output", {}).get("transactionShipments", [{}])[0].get("pieceResponses") or [{}])[0]
            tracking_number = piece.get("trackingNumber")
            label_b64 = (piece.get("packageDocuments") or [{}])[0].get("encodedLabel") if piece.get("packageDocuments") else None

        elif carrier == "ups":
            token, base = _ups_get_token(creds)
            payload = {
                "ShipmentRequest": {
                    "Shipment": {
                        "Shipper": {"Name": from_addr["name"], "ShipperNumber": creds.get("account_number", ""), "Address": {"AddressLine": [from_addr["street"]], "City": from_addr["city"], "PostalCode": from_addr["postal_code"], "CountryCode": from_addr["country_code"]}, "Phone": {"Number": from_addr.get("phone", "")}},
                        "ShipTo": {"Name": to_addr["name"], "Address": {"AddressLine": [to_addr["street"]], "City": to_addr["city"], "PostalCode": to_addr["postal_code"], "CountryCode": to_addr["country_code"]}, "Phone": {"Number": to_addr.get("phone", "")}},
                        "ShipFrom": {"Name": from_addr["name"], "Address": {"AddressLine": [from_addr["street"]], "City": from_addr["city"], "PostalCode": from_addr["postal_code"], "CountryCode": from_addr["country_code"]}},
                        "PaymentInformation": {"ShipmentCharge": {"Type": "01", "BillShipper": {"AccountNumber": creds.get("account_number", "")}}},
                        "Service": {"Code": service_code or ("07" if is_international else "03")},
                        "Package": [{"Packaging": {"Code": "02"}, "Dimensions": {"UnitOfMeasurement": {"Code": "CM"}, "Length": str(dims.get("length", 10)), "Width": str(dims.get("width", 10)), "Height": str(dims.get("height", 10))}, "PackageWeight": {"UnitOfMeasurement": {"Code": "KGS"}, "Weight": str(weight_kg)}}],
                        **({"InternationalForms": {"FormType": "01", "Product": [{"Description": it.get("description"), "Unit": {"Number": str(it.get("quantity", 1)), "UnitOfMeasurement": {"Code": "PCS"}, "Value": str(it.get("unit_value"))}, "OriginCountryCode": it.get("country_of_origin", ""), "CommodityCode": it.get("hs_code", "")} for it in customs_items]}} if is_international else {}),
                    },
                    "LabelSpecification": {"LabelImageFormat": {"Code": "PNG"}},
                }
            }
            resp = requests.post(f"{base}/api/shipments/v1/ship", headers={"Authorization": f"Bearer {token}", "Content-Type": "application/json"}, json=payload, timeout=30)
            resp.raise_for_status()
            body = resp.json()
            results = body.get("ShipmentResponse", {}).get("ShipmentResults", {})
            tracking_number = (results.get("ShipmentIdentificationNumber") or (results.get("PackageResults") or [{}])[0].get("TrackingNumber"))
            pkg_results = results.get("PackageResults")
            if isinstance(pkg_results, dict): pkg_results = [pkg_results]
            label_b64 = ((pkg_results or [{}])[0].get("ShippingLabel") or {}).get("GraphicImage")
        else:
            return None, None, ("carrier must be 'dhl', 'fedex', or 'ups'.", 400)
    except requests.HTTPError as e:
        body_text = e.response.text[:800] if e.response is not None else str(e)
        logging.error(f"[SHIPPING LABEL ERROR] carrier={carrier}: {body_text}")
        return None, None, (f"{carrier.upper()} rejected the shipment request: {body_text}", 502)
    except Exception as e:
        logging.error(f"[SHIPPING LABEL ERROR] carrier={carrier}: {e}")
        return None, None, (f"Could not create the shipment with {carrier.upper()}: {e}", 502)

    return tracking_number, label_b64, None


@app.route("/api/shipping/label", methods=["POST"])
@csrf.exempt
def shipping_create_label():
    """Body: carrier, from_address, to_address (each {name, company, street,
    city, postal_code, country_code, phone}), weight_kg, dims_cm,
    package_description, and — required for international shipments —
    customs_items: [{description, hs_code, quantity, unit_value, currency,
    country_of_origin}] (use /api/customs/hs-code-lookup to find hs_code)."""
    user, err = _erp_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    carrier = (data.get("carrier") or "").strip().lower()
    from_addr = data.get("from_address") or {}
    to_addr = data.get("to_address") or {}
    weight_kg = data.get("weight_kg")
    dims = data.get("dims_cm") or {}
    description = (data.get("package_description") or "Merchandise").strip()
    customs_items = data.get("customs_items") or []
    is_international = from_addr.get("country_code") != to_addr.get("country_code")

    required_addr_fields = ("name", "street", "city", "postal_code", "country_code")
    for label, addr in (("from_address", from_addr), ("to_address", to_addr)):
        missing = [f for f in required_addr_fields if not addr.get(f)]
        if missing:
            return jsonify({"error": f"{label} is missing required field(s): {', '.join(missing)}."}), 400
    if not weight_kg:
        return jsonify({"error": "weight_kg is required."}), 400
    if is_international and not customs_items:
        return jsonify({"error": "customs_items is required for international shipments (look up hs_code via the HS Code Classifier first)."}), 400

    tracking_number, label_b64, error = _shipping_create_label_core(
        user["id"], carrier, from_addr, to_addr, weight_kg, dims, description, customs_items,
        service_code=data.get("service_code"))
    if error:
        return jsonify({"error": error[0]}), error[1]

    if user["id"]:
        save_to_memory(
            user["id"], "assistant",
            f"Created {carrier.upper()} shipment {tracking_number} to {to_addr.get('city', '')}, {to_addr.get('country_code', '')}",
            content_type="shipment",
            extra={"carrier": carrier, "tracking_number": tracking_number},
        )

    return jsonify({"ok": True, "carrier": carrier, "tracking_number": tracking_number, "label_base64": label_b64}), 200


# ===========================================================
# MCP CONNECTOR — lets Claude connect to Connect It as a custom MCP
# server with read-only access to ERP data (customers, invoices,
# inventory, ledger). Three pieces:
#   1. OAuth 2.1 authorization-code + PKCE flow (+ dynamic client
#      registration, which is how Claude auto-configures a custom
#      connector without the user hand-entering a client id/secret).
#   2. A tiny built-in login+consent page (this app's own login is a
#      JSON API consumed by the SPA, so there's no server-rendered
#      login form to reuse here).
#   3. /mcp — a single JSON-RPC endpoint (MCP "Streamable HTTP"
#      transport) exposing exactly 5 read-only tools. Every tool call
#      is scoped to the token's user_id, same as every other route in
#      this app — an MCP token can only ever see that one business's
#      data, never anyone else's.
# ===========================================================

MCP_TOKEN_TTL_SECONDS     = 3600
MCP_AUTH_CODE_TTL_SECONDS = 600
MCP_SCOPE                 = "mcp:read"
MCP_SCOPE_READ            = "mcp:read"
# A write grant also carries read access (scopes are space-separated; tool checks use .split()).
MCP_SCOPE_WRITE           = "mcp:read mcp:write"


def _mcp_b64url_decode(s: str) -> bytes:
    padding = "=" * (-len(s) % 4)
    return base64.urlsafe_b64decode(s + padding)


def _mcp_pkce_ok(code_verifier: str, code_challenge: str, method: str) -> bool:
    if not code_verifier:
        return False
    if method == "S256":
        digest = hashlib.sha256(code_verifier.encode("utf-8")).digest()
        computed = base64.urlsafe_b64encode(digest).rstrip(b"=").decode("ascii")
        return secrets.compare_digest(computed, code_challenge)
    # "plain" is technically legal per RFC 7636 but weak; only accept it
    # if that's literally what the client registered.
    return method == "plain" and secrets.compare_digest(code_verifier, code_challenge)


def _mcp_issue_tokens(client_id: str, user_id: int, scope: str = MCP_SCOPE_READ):
    access_token  = "mcp_at_" + secrets.token_urlsafe(40)
    refresh_token = "mcp_rt_" + secrets.token_urlsafe(40)
    tok = OAuthToken(
        access_token=access_token, refresh_token=refresh_token,
        client_id=client_id, user_id=user_id, scope=scope,
        expires_at=datetime.utcnow() + timedelta(seconds=MCP_TOKEN_TTL_SECONDS),
    )
    db.session.add(tok)
    db.session.commit()
    return access_token, refresh_token


def _mcp_authed_user_id():
    """Resolves the calling user from the MCP-specific Bearer token.
    Deliberately does NOT fall back to this app's own session cookie or
    AuthSessionToken — an MCP client only ever gets in via a token this
    OAuth flow issued."""
    auth_header = request.headers.get("Authorization", "")
    if not auth_header.startswith("Bearer "):
        return None, None
    token = auth_header[7:].strip()
    tok = OAuthToken.query.filter_by(access_token=token, revoked=False).first()
    if not tok or tok.expires_at < datetime.utcnow():
        return None, None
    return tok.user_id, tok.scope


@app.route("/.well-known/oauth-authorization-server", methods=["GET"])
@app.route("/.well-known/oauth-authorization-server/mcp", methods=["GET"])
@csrf.exempt
def mcp_oauth_discovery():
    base = request.url_root.rstrip("/")
    return jsonify({
        "issuer": base,
        "authorization_endpoint": f"{base}/oauth/authorize",
        "token_endpoint": f"{base}/oauth/token",
        "registration_endpoint": f"{base}/oauth/register",
        "response_types_supported": ["code"],
        "grant_types_supported": ["authorization_code", "refresh_token"],
        "code_challenge_methods_supported": ["S256"],
        "token_endpoint_auth_methods_supported": ["none", "client_secret_post"],
        "scopes_supported": list(MCP_ALLOWED_SCOPES),
    }), 200


@app.route("/.well-known/oauth-protected-resource", methods=["GET"])
@csrf.exempt
def mcp_protected_resource_metadata():
    base = request.url_root.rstrip("/")
    return jsonify({
        "resource": f"{base}/mcp",
        "authorization_servers": [base],
        "scopes_supported": list(MCP_ALLOWED_SCOPES),
    }), 200


@app.route("/oauth/register", methods=["POST"])
@csrf.exempt
def mcp_oauth_register():
    """Dynamic Client Registration (RFC 7591) — lets Claude register
    itself automatically instead of the user hand-entering a client
    id/secret. redirect_uris is the only thing we actually enforce
    later (at /oauth/authorize and /oauth/token)."""
    data = request.get_json(silent=True) or {}
    redirect_uris = data.get("redirect_uris") or []
    if not isinstance(redirect_uris, list) or not redirect_uris:
        return jsonify({"error": "invalid_client_metadata", "error_description": "redirect_uris is required."}), 400
    for uri in redirect_uris:
        if not isinstance(uri, str) or not uri.startswith("https://"):
            return jsonify({"error": "invalid_redirect_uri", "error_description": "redirect_uris must be https:// URLs."}), 400

    client_id = "mcp_" + secrets.token_urlsafe(16)
    client = OAuthClient(
        client_id=client_id,
        client_name=str(data.get("client_name") or "MCP Client")[:200],
        redirect_uris=json.dumps(redirect_uris),
    )
    db.session.add(client)
    db.session.commit()

    return jsonify({
        "client_id": client_id,
        "redirect_uris": redirect_uris,
        "client_name": client.client_name,
        "token_endpoint_auth_method": "none",
        "grant_types": ["authorization_code", "refresh_token"],
        "response_types": ["code"],
    }), 201


_MCP_AUTHORIZE_FORM = """
<!doctype html><html><head><title>Connect to Connect It</title>
<meta name="viewport" content="width=device-width, initial-scale=1">
<style>
body{{font-family:-apple-system,Segoe UI,Roboto,sans-serif;background:#faf7f5;display:flex;
     align-items:center;justify-content:center;min-height:100vh;margin:0}}
.card{{background:#fff;border-radius:16px;box-shadow:0 4px 24px rgba(0,0,0,.08);padding:32px;
       width:100%;max-width:380px}}
h1{{font-size:20px;margin:0 0 4px}}
p.sub{{color:#666;font-size:14px;margin:0 0 20px}}
input{{width:100%;box-sizing:border-box;padding:10px 12px;margin-bottom:12px;border:1px solid #ddd;
       border-radius:8px;font-size:15px}}
button{{width:100%;padding:11px;border:none;border-radius:8px;background:#e0668c;color:#fff;
        font-size:15px;font-weight:600;cursor:pointer}}
.err{{color:#c0392b;font-size:13px;margin-bottom:12px}}
.consent{{font-size:13px;color:#444;background:#f5f0ee;border-radius:8px;padding:12px;margin-bottom:16px}}
</style></head><body><div class="card">
<h1>Connect Claude to Connect It </h1>
<p class="sub">Signed in as {user_label}</p>
{error_html}
<form method="POST">
{login_fields}
<div class="consent">{consent_html}</div>
<input type="hidden" name="client_id" value="{client_id}">
<input type="hidden" name="redirect_uri" value="{redirect_uri}">
<input type="hidden" name="state" value="{state}">
<input type="hidden" name="code_challenge" value="{code_challenge}">
<input type="hidden" name="code_challenge_method" value="{code_challenge_method}">
<button type="submit" name="action" value="allow">{button_label}</button>
</form>
</div></body></html>
"""


@app.route("/oauth/authorize", methods=["GET", "POST"])
@csrf.exempt
def mcp_oauth_authorize():
    client_id             = request.values.get("client_id", "")
    redirect_uri          = request.values.get("redirect_uri", "")
    state                 = request.values.get("state", "")
    code_challenge        = request.values.get("code_challenge", "")
    code_challenge_method = request.values.get("code_challenge_method", "S256")
    response_type         = request.values.get("response_type", "code")
    requested_scope       = (request.values.get("scope") or MCP_SCOPE_READ).strip()
    grant_write           = "mcp:write" in requested_scope.split()
    granted_scope         = MCP_SCOPE_WRITE if grant_write else MCP_SCOPE_READ

    client = OAuthClient.query.filter_by(client_id=client_id).first()
    if not client or redirect_uri not in client.redirect_uri_list():
        return jsonify({"error": "invalid_client", "error_description": "Unknown client_id or redirect_uri not registered."}), 400
    if response_type != "code":
        return _mcp_oauth_redirect_error(redirect_uri, state, "unsupported_response_type")
    if not code_challenge or code_challenge_method != "S256":
        return _mcp_oauth_redirect_error(redirect_uri, state, "invalid_request", "PKCE (S256) is required.")

    error_html = ""
    user = None
    uid = session.get("user_id")
    if uid:
        user = UserAccount.query.get(uid)

    if request.method == "POST":
        if not user:
            email    = request.form.get("email", "").strip().lower()
            password = request.form.get("password", "").strip()
            candidate = UserAccount.query.filter_by(email=email).first()
            if not candidate or not candidate.check_password(password) or not candidate.is_active:
                error_html = '<div class="err">Invalid email or password.</div>'
            elif candidate.totp_enabled and not (
                PYOTP_AVAILABLE and candidate.totp_secret and
                pyotp.TOTP(candidate.totp_secret).verify(request.form.get("totp_code", "").strip())
            ):
                error_html = '<div class="err">Invalid or missing 2FA code.</div>'
            else:
                user = candidate

        if user and not error_html:
            code = secrets.token_urlsafe(32)
            db.session.add(OAuthAuthCode(
                code=code, client_id=client_id, user_id=user.id,
                redirect_uri=redirect_uri, scope=granted_scope,
                code_challenge=code_challenge, code_challenge_method=code_challenge_method,
                expires_at=datetime.utcnow() + timedelta(seconds=MCP_AUTH_CODE_TTL_SECONDS),
            ))
            db.session.commit()
            sep = "&" if "?" in redirect_uri else "?"
            qs = f"code={code}"
            if state:
                qs += f"&state={requests.utils.quote(state)}"
            return redirect(f"{redirect_uri}{sep}{qs}")

    if user:
        login_fields = ""
        user_label = user.email
    else:
        login_fields = (
            '<input type="email" name="email" placeholder="Email" required>'
            '<input type="password" name="password" placeholder="Password" required>'
            '<input type="text" name="totp_code" placeholder="2FA code (if enabled)">'
        )
        user_label = "— please log in below"

    if grant_write:
        consent_html = ('This lets the connecting app view your customers, invoices, inventory, '
                         'ledger, WhatsApp/Messenger/Telegram/email conversations, and calendar, '
                         'AND create customers and invoices and send WhatsApp messages on your '
                         'behalf. It still cannot delete anything or see payment/payroll details.')
        button_label = "Allow read + write access"
    else:
        consent_html = ('This lets the connecting app view your customers, invoices, inventory, and '
                         'ledger (read-only). It cannot create, edit, or delete anything, or see '
                         'payment/payroll details.')
        button_label = "Allow read-only access"
    return _MCP_AUTHORIZE_FORM.format(
        user_label=user_label, error_html=error_html, login_fields=login_fields,
        client_id=client_id, redirect_uri=redirect_uri, state=state,
        code_challenge=code_challenge, code_challenge_method=code_challenge_method,
        consent_html=consent_html, button_label=button_label,
    ), 200


def _mcp_oauth_redirect_error(redirect_uri, state, error, description=None):
    sep = "&" if "?" in redirect_uri else "?"
    qs = f"error={error}"
    if description:
        qs += f"&error_description={requests.utils.quote(description)}"
    if state:
        qs += f"&state={requests.utils.quote(state)}"
    return redirect(f"{redirect_uri}{sep}{qs}")


@app.route("/oauth/token", methods=["POST"])
@csrf.exempt
def mcp_oauth_token():
    grant_type = request.values.get("grant_type", "")

    if grant_type == "authorization_code":
        code          = request.values.get("code", "")
        redirect_uri  = request.values.get("redirect_uri", "")
        client_id     = request.values.get("client_id", "")
        code_verifier = request.values.get("code_verifier", "")

        auth_code = OAuthAuthCode.query.filter_by(code=code, used=False).first()
        if (not auth_code or auth_code.client_id != client_id or
                auth_code.redirect_uri != redirect_uri or
                auth_code.expires_at < datetime.utcnow()):
            return jsonify({"error": "invalid_grant"}), 400
        if not _mcp_pkce_ok(code_verifier, auth_code.code_challenge, auth_code.code_challenge_method):
            return jsonify({"error": "invalid_grant", "error_description": "PKCE verification failed."}), 400

        auth_code.used = True
        db.session.commit()
        # BUG FIX: this used to always issue MCP_SCOPE (read-only), silently
        # downgrading every write grant the user approved on the consent
        # screen — the token never actually carried the scope the auth code
        # recorded. Now the auth code's own stored scope is what gets issued.
        access_token, refresh_token = _mcp_issue_tokens(client_id, auth_code.user_id, auth_code.scope)
        return jsonify({
            "access_token": access_token, "token_type": "Bearer",
            "expires_in": MCP_TOKEN_TTL_SECONDS, "refresh_token": refresh_token,
            "scope": auth_code.scope,
        }), 200

    elif grant_type == "refresh_token":
        refresh_token = request.values.get("refresh_token", "")
        client_id     = request.values.get("client_id", "")
        old = OAuthToken.query.filter_by(refresh_token=refresh_token, client_id=client_id, revoked=False).first()
        if not old:
            return jsonify({"error": "invalid_grant"}), 400
        old.revoked = True
        db.session.commit()
        # Same fix as above: refresh must preserve the previously-granted
        # scope, not silently reset every connection back to read-only.
        access_token, new_refresh = _mcp_issue_tokens(client_id, old.user_id, old.scope)
        return jsonify({
            "access_token": access_token, "token_type": "Bearer",
            "expires_in": MCP_TOKEN_TTL_SECONDS, "refresh_token": new_refresh,
            "scope": old.scope,
        }), 200

    return jsonify({"error": "unsupported_grant_type"}), 400


# --- MCP tool implementations (all read-only, all scoped to owner_user_id) ---

def _mcp_tool_list_customers(user_id, args):
    q = ErpCustomer.query.filter_by(owner_user_id=user_id, is_sandbox_demo=False)
    search = (args.get("search") or "").strip()
    if search:
        q = q.filter(ErpCustomer.name.ilike(f"%{search}%"))
    rows = q.order_by(ErpCustomer.name.asc()).limit(int(args.get("limit") or 50)).all()
    return [c.to_dict() for c in rows]


def _mcp_tool_get_invoice(user_id, args):
    inv = ErpInvoice.query.filter_by(id=args.get("invoice_id"), owner_user_id=user_id).first()
    if not inv:
        return {"error": "Invoice not found."}
    return inv.to_dict(include_items=True)


def _mcp_tool_list_invoices(user_id, args):
    q = ErpInvoice.query.filter_by(owner_user_id=user_id, is_sandbox_demo=False)
    if args.get("status"):
        q = q.filter(ErpInvoice.status == args["status"])
    if args.get("customer_id"):
        q = q.filter(ErpInvoice.customer_id == args["customer_id"])
    rows = q.order_by(ErpInvoice.created_at.desc()).limit(int(args.get("limit") or 50)).all()
    return [i.to_dict() for i in rows]


def _mcp_tool_list_inventory(user_id, args):
    q = InventoryItem.query.filter_by(user_id=user_id, active=True)
    if args.get("low_stock_only"):
        q = q.filter(InventoryItem.quantity <= InventoryItem.threshold)
    rows = q.order_by(InventoryItem.name.asc()).limit(int(args.get("limit") or 100)).all()
    return [i.to_dict() for i in rows]


def _mcp_tool_get_ledger_summary(user_id, args):
    q = ErpLedgerEntry.query.filter_by(owner_user_id=user_id)
    if args.get("start_date"):
        q = q.filter(ErpLedgerEntry.entry_date >= args["start_date"])
    if args.get("end_date"):
        q = q.filter(ErpLedgerEntry.entry_date <= args["end_date"])
    rows = q.all()
    totals = {}
    for r in rows:
        totals[r.kind] = round(totals.get(r.kind, 0) + r.amount, 2)
    net = round(sum(r.amount for r in rows), 2)
    return {"totals_by_kind": totals, "net": net, "entry_count": len(rows)}


def _mcp_tool_list_whatsapp_conversations(user_id, args):
    q = ChatLog.query.filter(
        ChatLog.channel.in_(["whatsapp_cloud", "whatsapp"]), ChatLog.owner_user_id == user_id
    )
    if args.get("customer_phone"):
        q = q.filter(ChatLog.session_id == args["customer_phone"])
    rows = q.order_by(ChatLog.id.desc()).limit(int(args.get("limit") or 30)).all()
    return [
        {"customer_phone": r.session_id, "role": r.role, "content": r.content,
         "timestamp": r.created_at.isoformat() if r.created_at else None}
        for r in reversed(rows)
    ]


def _mcp_tool_list_calendar_events(user_id, args):
    token = get_valid_calendar_token(user_id)
    if not token:
        return {"error": "Google Calendar isn't connected for this account."}
    resp = requests.get(
        "https://www.googleapis.com/calendar/v3/calendars/primary/events",
        headers={"Authorization": f"Bearer {token}"},
        params={
            "timeMin": datetime.utcnow().isoformat() + "Z",
            "maxResults": int(args.get("limit") or 15),
            "singleEvents": "true", "orderBy": "startTime",
        }, timeout=12,
    )
    if resp.status_code != 200:
        return {"error": "Could not fetch calendar events."}
    items = resp.json().get("items", [])
    return [{
        "title": e.get("summary", "(No title)"),
        "start": e.get("start", {}).get("dateTime") or e.get("start", {}).get("date"),
        "end": e.get("end", {}).get("dateTime") or e.get("end", {}).get("date"),
    } for e in items]


def _mcp_tool_track_shipment(user_id, args):
    carrier = (args.get("carrier") or "").strip().lower()
    tracking_number = (args.get("tracking_number") or "").strip()
    if not carrier or not tracking_number:
        return {"error": "Both 'carrier' (dhl/fedex/ups) and 'tracking_number' are required."}
    result, error = _shipping_track_core(user_id, carrier, tracking_number)
    if error:
        return {"error": error[0]}
    return result


def _mcp_tool_list_outlook_emails(user_id, args):
    token = get_valid_microsoft_token(user_id)
    if not token:
        return {"error": "Outlook/Microsoft 365 isn't connected for this account."}
    resp = requests.get(
        f"{_MS_GRAPH_BASE}/me/mailFolders/inbox/messages"
        f"?$top={int(args.get('limit') or 15)}&$select=subject,from,bodyPreview,receivedDateTime,isRead",
        headers={"Authorization": f"Bearer {token}"}, timeout=12,
    )
    if resp.status_code != 200:
        return {"error": "Could not fetch Outlook messages."}
    items = resp.json().get("value", [])
    return [{
        "subject": m.get("subject", "(no subject)"),
        "from": ((m.get("from") or {}).get("emailAddress") or {}).get("address", ""),
        "preview": m.get("bodyPreview", ""),
        "received": m.get("receivedDateTime"),
        "is_read": m.get("isRead", False),
    } for m in items]


def _mcp_tool_list_messenger_conversations(user_id, args):
    q = ChatLog.query.filter_by(channel="messenger", owner_user_id=user_id)
    if args.get("customer_id"):
        q = q.filter(ChatLog.session_id == args["customer_id"])
    rows = q.order_by(ChatLog.id.desc()).limit(int(args.get("limit") or 30)).all()
    return [
        {"customer_psid": r.session_id, "role": r.role, "content": r.content,
         "timestamp": r.created_at.isoformat() if r.created_at else None}
        for r in reversed(rows)
    ]


def _mcp_tool_list_telegram_conversations(user_id, args):
    q = ChatLog.query.filter_by(channel="telegram", owner_user_id=user_id)
    if args.get("chat_id"):
        q = q.filter(ChatLog.session_id == f"telegram:{args['chat_id']}")
    rows = q.order_by(ChatLog.id.desc()).limit(int(args.get("limit") or 30)).all()
    return [
        {"chat_id": r.session_id, "role": r.role, "content": r.content,
         "timestamp": r.created_at.isoformat() if r.created_at else None}
        for r in reversed(rows)
    ]


def _mcp_tool_list_insurance_policies(user_id, args):
    if not _feature_enabled("parametric_insurance"):
        return {"error": "Parametric insurance is not currently enabled on this platform."}
    rows = (InsurancePolicy.query.filter_by(owner_user_id=user_id)
            .order_by(InsurancePolicy.created_at.desc()).limit(int(args.get("limit") or 20)).all())
    return [p.to_dict() for p in rows]


def _mcp_tool_create_customer(user_id, args):
    name = (args.get("name") or "").strip()
    if not name:
        return {"error": "name is required."}
    c = ErpCustomer(owner_user_id=user_id, name=name[:200], email=args.get("email"),
                     phone=args.get("phone"), address=args.get("address"), notes=args.get("notes"))
    db.session.add(c)
    db.session.commit()
    return {"customer": c.to_dict()}


def _mcp_tool_create_invoice(user_id, args):
    raw_items = args.get("items") or []
    items, subtotal = _erp_items_from_payload([
        {"description": it.get("description"), "quantity": it.get("quantity"), "unit_price": it.get("unit_price")}
        for it in raw_items
    ])
    if not items:
        return {"error": "At least one line item is required."}
    currency = args.get("currency") or "USD"
    due_date = _erp_parse_date(args.get("due_date"), datetime.utcnow().date() + timedelta(days=14))
    inv = ErpInvoice(
        owner_user_id=user_id, customer_id=args.get("customer_id"),
        invoice_number=_erp_gen_number("INV"), currency=currency,
        issue_date=datetime.utcnow().date(), due_date=due_date,
        subtotal=subtotal, tax_rate=0, tax_amount=0,
        total=round(subtotal, 2), notes=args.get("notes"), payment_method="other",
    )
    db.session.add(inv)
    db.session.flush()
    for it in items:
        db.session.add(ErpInvoiceItem(invoice_id=inv.id, product_id=it["product_id"], description=it["description"],
                                        quantity=it["quantity"], unit_price=it["price"], line_total=it["line_total"]))
    db.session.commit()
    return {"invoice": inv.to_dict(include_items=True)}


def _mcp_tool_send_whatsapp_message(user_id, args):
    to = (args.get("to") or "").strip()
    message = (args.get("message") or "").strip()
    if not to or not message:
        return {"error": "to and message are both required."}
    result = send_whatsapp_cloud_message(user_id, to, message)
    return {"sent": True, "whatsapp_response": result}


