@app.route("/api/products/<int:product_id>/ai-listing/apply", methods=["POST"])
@csrf.exempt
def listing_ai_apply_route(product_id):
    """Applies a specific draft to the live listing. Each of title/
    description/seo is opt-in separately (defaulting to true) so a
    seller can, say, keep their own hand-written description but still
    take the generated SEO metadata — nothing is force-overwritten."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    product = Product.query.get(product_id)
    if not product or product.seller_id != user["id"]:
        return jsonify({"error": "Listing not found."}), 404
    data = request.get_json(silent=True) or {}
    draft_id = data.get("draft_id")
    draft = ListingAiDraft.query.filter_by(id=draft_id, product_id=product_id).first() if draft_id else \
        ListingAiDraft.query.filter_by(product_id=product_id, status="pending").order_by(ListingAiDraft.created_at.desc()).first()
    if not draft:
        return jsonify({"error": "No AI-generated draft found for this listing."}), 404
    if draft.status == "applied":
        return jsonify({"error": "This draft was already applied."}), 400

    apply_title       = data.get("apply_title", True)
    apply_description = data.get("apply_description", True)
    apply_seo         = data.get("apply_seo", True)

    if apply_title and draft.generated_title:
        product.name = draft.generated_title
    if apply_description and draft.generated_description:
        bullets = json.loads(draft.generated_bullets_json) if draft.generated_bullets_json else []
        body = draft.generated_description
        if bullets:
            body += "\n\n" + "\n".join(f"• {b}" for b in bullets)
        product.description = body[:4000]
    if apply_seo:
        product.seo_title = draft.generated_seo_title
        product.seo_meta_description = draft.generated_seo_meta_description
        product.seo_keywords = draft.generated_seo_keywords_json
        if draft.generated_slug and not product.seo_slug:
            product.seo_slug = draft.generated_slug

    product.listing_ai_last_generated_at = datetime.utcnow()
    draft.status = "applied"
    draft.applied_at = datetime.utcnow()
    db.session.commit()
    return jsonify({"ok": True, "product": product.to_dict(viewer_id=user["id"])}), 200


