# ---- AUTO SEO: crawler-visible product page + sitemap ----
# The SPA at "/" never gets crawled meaningfully (a search engine sees
# an empty shell before JS runs), so a listing that has an assigned
# seo_slug also gets this second, server-rendered page — same pattern
# already used for the public /store/<slug> storefront above — with
# real <title>/meta description/Open Graph tags and JSON-LD Product
# structured data, plus a link into the full interactive SPA.

@app.route("/product/<slug>", methods=["GET"])
def public_product_seo_page(slug):
    product = Product.query.filter_by(seo_slug=slug, is_active=True).first()
    if not product:
        # Fall back to treating the slug as a raw numeric id, so old
        # /product/<id> links (e.g. shared before a slug existed) still
        # resolve — redirecting to the canonical slug URL once one exists.
        if slug.isdigit():
            product = Product.query.filter_by(id=int(slug), is_active=True).first()
            if product and product.seo_slug and product.seo_slug != slug:
                return redirect(f"/product/{product.seo_slug}", code=301)
        if not product:
            return render_template_string(
                "<!DOCTYPE html><html><head><meta charset=\"UTF-8\"/>"
                "<title>Listing not found</title></head><body style=\"font-family:sans-serif;"
                "text-align:center;padding:60px;color:#64748b;\"><h1>Listing not found</h1>"
                f"<p><a href=\"{escape(APP_BASE_URL)}/\">Back to the marketplace</a></p></body></html>"
            ), 404

    page_title = product.seo_title or product.name
    page_desc  = product.seo_meta_description or (product.description or "")[:160]
    keywords   = product.seo_keywords_list()
    images = []
    if product.image_urls:
        try:
            images = json.loads(product.image_urls)
        except Exception:
            images = []
    image_url = images[0] if images else None
    seller = UserAccount.query.get(product.seller_id)
    canonical_url = f"{APP_BASE_URL}/product/{product.seo_slug or product.id}"
    app_deep_link = f"{APP_BASE_URL}/?product={product.id}"
    json_ld = {
        "@context": "https://schema.org", "@type": "Product",
        "name": product.name, "description": product.description or page_desc,
        "sku": str(product.id),
        "offers": {
            "@type": "Offer", "priceCurrency": product.currency, "price": product.price,
            "availability": "https://schema.org/InStock" if product.quantity_available > 0 else "https://schema.org/OutOfStock",
            "url": canonical_url,
        },
    }
    if image_url:
        json_ld["image"] = image_url
    html = f"""
    <!DOCTYPE html><html><head><meta charset="UTF-8"/>
    <meta name="viewport" content="width=device-width,initial-scale=1"/>
    <title>{escape(page_title)}</title>
    <meta name="description" content="{escape(page_desc)}"/>
    {f'<meta name="keywords" content="{escape(", ".join(keywords))}"/>' if keywords else ''}
    <link rel="canonical" href="{escape(canonical_url)}"/>
    <meta property="og:type" content="product"/>
    <meta property="og:title" content="{escape(page_title)}"/>
    <meta property="og:description" content="{escape(page_desc)}"/>
    <meta property="og:url" content="{escape(canonical_url)}"/>
    {f'<meta property="og:image" content="{escape(image_url)}"/>' if image_url else ''}
    <meta name="twitter:card" content="{'summary_large_image' if image_url else 'summary'}"/>
    <meta name="twitter:title" content="{escape(page_title)}"/>
    <meta name="twitter:description" content="{escape(page_desc)}"/>
    <script type="application/ld+json">{json.dumps(json_ld)}</script>
    <style>
      *{{box-sizing:border-box;margin:0;padding:0;}}
      body{{font-family:'Segoe UI',sans-serif;background:#f8fafc;color:#1e293b;min-height:100vh;}}
      .wrap{{max-width:720px;margin:0 auto;padding:32px 20px;}}
      img.hero{{width:100%;max-height:360px;object-fit:cover;border-radius:12px;margin-bottom:18px;}}
      h1{{font-size:1.5rem;margin-bottom:6px;}}
      .price{{font-size:1.2rem;font-weight:800;color:#ea580c;margin-bottom:14px;}}
      .desc{{white-space:pre-line;color:#334155;line-height:1.6;margin-bottom:20px;}}
      .kw{{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:24px;}}
      .kw span{{background:#e2e8f0;color:#475569;font-size:0.72rem;padding:3px 9px;border-radius:10px;}}
      a.cta{{display:inline-block;background:#ea580c;color:#fff;text-decoration:none;font-weight:700;
             padding:12px 22px;border-radius:8px;}}
      footer{{text-align:center;color:#94a3b8;font-size:0.76rem;padding:24px;}}
    </style></head>
    <body><div class="wrap">
      {f'<img class="hero" src="{escape(image_url)}"/>' if image_url else ''}
      <h1>{escape(product.name)}</h1>
      <div class="price">{escape(product.currency)} {product.price:,.2f} per {escape(product.unit or 'unit')}</div>
      <div class="desc">{escape(product.description or '')}</div>
      {f'<div class="kw">' + "".join(f'<span>{escape(k)}</span>' for k in keywords) + '</div>' if keywords else ''}
      <a class="cta" href="{escape(app_deep_link)}">View full listing &amp; buy</a>
      <footer>Sold by {escape(seller.name if seller else "a verified seller")} on <a href="{escape(APP_BASE_URL)}/" style="color:#ea580c;">the Marketplace</a></footer>
    </div></body></html>"""
    return render_template_string(html)


@app.route("/sitemap.xml", methods=["GET"])
def sitemap_xml():
    products = (Product.query.filter(Product.is_active.is_(True), Product.seo_slug.isnot(None))
                .order_by(Product.updated_at.desc()).limit(5000).all())
    urls = [f"{APP_BASE_URL}/", f"{APP_BASE_URL}/store/"]
    entries = "".join(
        "<url>"
        f"<loc>{xml_escape(APP_BASE_URL)}/product/{xml_escape(p.seo_slug)}</loc>"
        f"<lastmod>{(p.updated_at or p.created_at or datetime.utcnow()).date().isoformat()}</lastmod>"
        "</url>"
        for p in products
    )
    xml = ('<?xml version="1.0" encoding="UTF-8"?>'
           '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'
           f'<url><loc>{xml_escape(APP_BASE_URL)}/</loc></url>'
           f'{entries}'
           '</urlset>')
    return Response(xml, mimetype="application/xml")


@app.route("/robots.txt", methods=["GET"])
def robots_txt():
    body = f"User-agent: *\nAllow: /\nSitemap: {APP_BASE_URL}/sitemap.xml\n"
    return Response(body, mimetype="text/plain")


# ════════════════════════════════════════════════════════════
# STAGE 361: RESTRICTED-GOODS / EXPORT-CONTROL MATRIX
# Stage 123's sanctions screening already checks WHO a buyer/seller is
# against denied-party lists. This is the other half of trade
# compliance: WHAT is being shipped. A category/HS-code x destination
# matrix an admin curates and keeps current, matched against every
# listing's own category/HS code/keywords. This is deliberately NOT
# presented as authoritative customs law — it is a screening flag with
# a plain-language reason, the same "informational estimate, verify
# yourself" honesty pattern as the Landed Cost Calculator and Carbon
# Label elsewhere in this file. A "prohibited" match blocks the order
# outright at checkout; "license_required"/"review" matches require the
# buyer to read the reason and explicitly acknowledge before the order
# can proceed, rather than silently letting it through.
# ════════════════════════════════════════════════════════════

class RestrictedGoodsRule(db.Model):
    __tablename__  = "restricted_goods_rules"
    id                        = db.Column(db.Integer, primary_key=True)
    category                  = db.Column(db.String(60), nullable=True, index=True)   # matches Product.category, case-insensitive
    hs_code_prefix            = db.Column(db.String(20), nullable=True, index=True)   # matches Product.hs_code.startswith(...)
    keyword                   = db.Column(db.String(60), nullable=True)               # matches Product.name/description substring, case-insensitive
    destination_country_code  = db.Column(db.String(4), nullable=True, index=True)    # null = applies to every destination
    level                     = db.Column(db.String(20), nullable=False, default="review")
    # 'prohibited' (blocks checkout outright), 'license_required' or
    # 'review' (both require buyer acknowledgment before checkout, kept
    # as two labels only so the UI can word the notice appropriately)
    reason                    = db.Column(db.String(400), nullable=False)
    active                    = db.Column(db.Boolean, nullable=False, default=True, index=True)
    created_by_admin_id       = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=True)
    created_at                = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        return {
            "id": self.id, "category": self.category, "hs_code_prefix": self.hs_code_prefix,
            "keyword": self.keyword, "destination_country_code": self.destination_country_code,
            "level": self.level, "reason": self.reason, "active": self.active,
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }


_RESTRICTED_GOODS_SEED = [
    # Deliberately broad, globally-hedged starter categories rather than
    # country-specific legal claims — a platform admin is expected to
    # refine/replace these with their own jurisdiction's actual export-
    # control list over time; this just means "new listing → not a blank
    # screening table on day one".
    {"category": "Weapons & Ammunition", "level": "prohibited",
     "reason": "Firearms, ammunition and weapon parts are commonly prohibited or tightly export-controlled worldwide. Not listable on this marketplace."},
    {"keyword": "explosive", "level": "prohibited",
     "reason": "Explosives and explosive precursors are commonly prohibited from ordinary freight/postal export."},
    {"category": "Military & Dual-Use Electronics", "level": "license_required",
     "reason": "Encryption hardware, surveillance equipment and other dual-use electronics commonly require an export license depending on destination — verify with your national export-control authority before shipping."},
    {"keyword": "night vision", "level": "license_required",
     "reason": "Night-vision and thermal-imaging equipment is commonly export-controlled as dual-use technology."},
    {"category": "Chemicals & Precursors", "level": "license_required",
     "reason": "Industrial and precursor chemicals may be subject to export licensing depending on the specific substance and destination — verify classification before shipping."},
    {"category": "Pharmaceuticals & Controlled Substances", "level": "review",
     "reason": "Pharmaceuticals and controlled substances commonly require import permits or licensed distributor handling at the destination — flagged for manual review before shipment."},
    {"category": "Wildlife & Endangered Species Products", "level": "prohibited",
     "reason": "Products derived from endangered or protected species (ivory, certain furs/skins, coral, etc.) are broadly restricted under CITES-aligned trade rules."},
    {"keyword": "ivory", "level": "prohibited",
     "reason": "Ivory and ivory products are broadly prohibited from international trade under CITES-aligned rules."},
    {"category": "Cultural Heritage & Antiquities", "level": "review",
     "reason": "Cultural artifacts and antiquities commonly require export permits from the country of origin — flagged for manual review before shipment."},
    {"keyword": "radioactive", "level": "prohibited",
     "reason": "Radioactive materials are prohibited from ordinary commercial freight/postal export."},
]


def _seed_restricted_goods_rules_if_empty():
    try:
        if RestrictedGoodsRule.query.first():
            return
        for rule in _RESTRICTED_GOODS_SEED:
            db.session.add(RestrictedGoodsRule(**rule))
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        logging.error(f"[RESTRICTED GOODS SEED ERROR] {e}")


_RESTRICTED_GOODS_LEVEL_RANK = {"prohibited": 3, "license_required": 2, "review": 1}


def _restricted_goods_check(product: "Product", destination_country_code: str | None) -> dict | None:
    """Returns the single strictest matching rule (as a dict), or None if
    nothing matches. destination_country_code=None only matches rules
    that themselves apply to every destination (destination_country_code
    is null on the rule)."""
    dest = (destination_country_code or "").strip().upper() or None
    rules = RestrictedGoodsRule.query.filter_by(active=True).all()
    category = (product.category or "").strip().lower()
    hs_code = (product.hs_code or "").strip().lower()
    haystack = ((product.name or "") + " " + (product.description or "")).lower()

    best = None
    for r in rules:
        if r.destination_country_code and r.destination_country_code.upper() != dest:
            continue
        matched = False
        if r.category and category and r.category.strip().lower() == category:
            matched = True
        if not matched and r.hs_code_prefix and hs_code and hs_code.startswith(r.hs_code_prefix.strip().lower()):
            matched = True
        if not matched and r.keyword and r.keyword.strip().lower() in haystack:
            matched = True
        if not matched:
            continue
        if best is None or _RESTRICTED_GOODS_LEVEL_RANK.get(r.level, 0) > _RESTRICTED_GOODS_LEVEL_RANK.get(best.level, 0):
            best = r
    if not best:
        return None
    return {"level": best.level, "reason": best.reason, "rule_id": best.id}


@app.route("/api/compliance/restricted-goods-check", methods=["GET"])
def restricted_goods_check_route():
    user = _get_current_user()
    product_id = request.args.get("product_id", type=int)
    product = Product.query.get(product_id) if product_id else None
    if not product:
        return jsonify({"error": "Listing not found."}), 404
    destination = (request.args.get("destination_country_code") or "").strip().upper() or None
    if not destination and user:
        viewer = UserAccount.query.get(user["id"])
        destination = viewer.country_code if viewer else None
    match = _restricted_goods_check(product, destination)
    return jsonify({"destination_country_code": destination, "restriction": match}), 200


# ---- Admin CRUD for the matrix ----

@app.route("/api/admin/restricted-goods/rules", methods=["GET"])
def admin_restricted_goods_list():
    admin_user, err = _require_admin()
    if err:
        return err
    rows = RestrictedGoodsRule.query.order_by(RestrictedGoodsRule.created_at.desc()).all()
    return jsonify({"rules": [r.to_dict() for r in rows]}), 200


@app.route("/api/admin/restricted-goods/rules", methods=["POST"])
@csrf.exempt
def admin_restricted_goods_create():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    admin_user, err = _require_admin()
    if err:
        return err
    data = request.get_json(silent=True) or {}
    category = (data.get("category") or "").strip()[:60] or None
    hs_code_prefix = (data.get("hs_code_prefix") or "").strip()[:20] or None
    keyword = (data.get("keyword") or "").strip()[:60] or None
    if not (category or hs_code_prefix or keyword):
        return jsonify({"error": "Provide at least one of category, HS code prefix, or keyword to match on."}), 400
    level = data.get("level") if data.get("level") in ("prohibited", "license_required", "review") else "review"
    reason = (data.get("reason") or "").strip()[:400]
    if not reason:
        return jsonify({"error": "A reason is required."}), 400
    destination = (data.get("destination_country_code") or "").strip().upper()[:4] or None
    rule = RestrictedGoodsRule(
        category=category, hs_code_prefix=hs_code_prefix, keyword=keyword,
        destination_country_code=destination, level=level, reason=reason,
        created_by_admin_id=admin_user.id,
    )
    db.session.add(rule)
    db.session.commit()
    return jsonify({"ok": True, "rule": rule.to_dict()}), 201


@app.route("/api/admin/restricted-goods/rules/<int:rule_id>/deactivate", methods=["POST"])
@csrf.exempt
def admin_restricted_goods_deactivate(rule_id):
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    admin_user, err = _require_admin()
    if err:
        return err
    rule = RestrictedGoodsRule.query.get(rule_id)
    if not rule:
        return jsonify({"error": "Rule not found."}), 404
    rule.active = False
    db.session.commit()
    return jsonify({"ok": True}), 200


# ════════════════════════════════════════════════════════════
# STAGE 330 (cont'd): CARBON OFFSET AT CHECKOUT
# The per-unit label above is informational; this is the "optional
# offset at checkout" half of the roadmap item — a buyer can pay a
# small amount to offset a specific order's estimated footprint.
# Built as its own standalone Stripe Checkout Session (not woven into
# the multi-line cart/Buy-Now checkout logic) so it's a simple,
# low-risk add-on: one line item, its own webhook branch (same pattern
# Stage 328's gift-card purchase already established), no changes to
# the existing pricing/discount/store-credit computation in the cart
# checkout. Honest about what this is: a recorded voluntary
# contribution at a fixed $/kg rate, not a real offset-registry
# retirement (Cloverly/Patch/Puro.earth etc. aren't integrated) — the
# UI and API response both say so.
# ════════════════════════════════════════════════════════════

CARBON_OFFSET_USD_PER_KG = 0.02  # rough voluntary-market average; flagged as such in the API response


class CarbonOffsetContribution(db.Model):
    __tablename__  = "carbon_offset_contributions"
    id             = db.Column(db.Integer, primary_key=True)
    buyer_id       = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    order_id       = db.Column(db.Integer, db.ForeignKey("product_orders.id"), nullable=True, index=True)
    kg_co2e        = db.Column(db.Float, nullable=False)
    amount_usd     = db.Column(db.Float, nullable=False)
    status         = db.Column(db.String(16), nullable=False, default="pending")  # pending, paid
    stripe_session_id = db.Column(db.String(120), nullable=True)
    created_at     = db.Column(db.DateTime, default=datetime.utcnow, index=True)

    def to_dict(self):
        return {
            "id": self.id, "order_id": self.order_id, "kg_co2e": self.kg_co2e,
            "amount_usd": self.amount_usd, "status": self.status,
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }


@app.route("/api/marketplace/carbon-offset/quote", methods=["GET"])
def carbon_offset_quote():
    """Given an order_id, returns the kg/cost quote for offsetting it —
    separated from the purchase call so the UI can show a price before
    the buyer commits."""
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    order_id = request.args.get("order_id", type=int)
    order = ProductOrder.query.get(order_id) if order_id else None
    if not order or order.buyer_id != user["id"]:
        return jsonify({"error": "Order not found."}), 404
    product = Product.query.get(order.product_id)
    kg, is_estimate = product.estimated_carbon_kg(order.quantity) if product else (0, True)
    return jsonify({
        "order_id": order.id, "kg_co2e": kg, "is_estimate": is_estimate,
        "amount_usd": round(kg * CARBON_OFFSET_USD_PER_KG, 2), "rate_usd_per_kg": CARBON_OFFSET_USD_PER_KG,
        "note": "A voluntary contribution recorded on the platform, not a certified offset-registry retirement.",
    }), 200


@app.route("/api/marketplace/carbon-offset/purchase", methods=["POST"])
@csrf.exempt
def carbon_offset_purchase():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    order_id = data.get("order_id")
    order = ProductOrder.query.get(order_id) if order_id else None
    if not order or order.buyer_id != user["id"]:
        return jsonify({"error": "Order not found."}), 404
    product = Product.query.get(order.product_id)
    kg, _ = product.estimated_carbon_kg(order.quantity) if product else (0, True)
    amount_usd = round(kg * CARBON_OFFSET_USD_PER_KG, 2)
    if amount_usd < 0.50:
        return jsonify({"error": "Offset amount is too small to process (minimum $0.50)."}), 400

    contribution = CarbonOffsetContribution(
        buyer_id=user["id"], order_id=order.id, kg_co2e=kg, amount_usd=amount_usd, status="pending")
    db.session.add(contribution)
    db.session.commit()
    try:
        import stripe
        stripe.api_key = STRIPE_SECRET_KEY
        session = stripe.checkout.Session.create(
            payment_method_types=["card"],
            line_items=[{
                "price_data": {
                    "currency": "usd",
                    "product_data": {"name": f"Carbon offset — {kg} kg CO2e (order #{order.id})"},
                    "unit_amount": int(round(amount_usd * 100)),
                },
                "quantity": 1,
            }],
            mode="payment",
            success_url=APP_BASE_URL + "/payment-success?session_id={CHECKOUT_SESSION_ID}",
            cancel_url=APP_BASE_URL + "/?offset=cancelled",
            metadata={"kind": "carbon_offset_purchase", "contribution_id": str(contribution.id)},
        )
        contribution.stripe_session_id = session.id
        db.session.commit()
        return jsonify({"ok": True, "checkout_url": session.url, "contribution": contribution.to_dict()}), 201
    except Exception as e:
        db.session.rollback(); logging.error(f"[CARBON OFFSET PURCHASE ERROR] {e}")
        return jsonify({"error": "Could not start offset checkout."}), 500


@app.route("/api/marketplace/carbon-offset/summary", methods=["GET"])
def carbon_offset_summary():
    """A buyer's own total contribution history — kept simple (one
    person's totals) rather than a platform-wide leaderboard, which
    would need its own moderation/verification concerns out of scope
    here."""
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    rows = (CarbonOffsetContribution.query.filter_by(buyer_id=user["id"], status="paid")
            .order_by(CarbonOffsetContribution.created_at.desc()).all())
    total_kg = round(sum(r.kg_co2e for r in rows), 2)
    total_usd = round(sum(r.amount_usd for r in rows), 2)
    return jsonify({"total_kg_offset": total_kg, "total_amount_usd": total_usd,
                     "contributions": [r.to_dict() for r in rows]}), 200


# ════════════════════════════════════════════════════════════
# STAGE 331: SELLER PERFORMANCE TIERS/BADGES + COUNTERFEIT/TAKEDOWN
# FLAGGING
# Tiers/badges are computed live from data the platform already has —
# ProductOrder history, escrow dispute outcomes (Stage 304), and
# DealReview ratings — rather than a separately-maintained score that
# could drift from reality. Counterfeit/takedown flagging reuses the
# same admin-check pattern as the existing escrow dispute admin-
# resolve endpoint, and upholding a flag deactivates the listing the
# same way a seller deactivating their own listing already does
# (is_active=False) rather than introducing a second "hidden" state.
# ════════════════════════════════════════════════════════════

PRODUCT_FLAG_REASONS = ("counterfeit", "prohibited_item", "misleading", "other")


class ProductFlag(db.Model):
    __tablename__      = "product_flags"
    id                 = db.Column(db.Integer, primary_key=True)
    product_id         = db.Column(db.Integer, db.ForeignKey("products.id"), nullable=False, index=True)
    reporter_id        = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    reason             = db.Column(db.String(20), nullable=False, default="other")
    details            = db.Column(db.String(500), nullable=True)
    status             = db.Column(db.String(12), nullable=False, default="open", index=True)  # open, upheld, dismissed
    created_at         = db.Column(db.DateTime, default=datetime.utcnow, index=True)
    resolved_at        = db.Column(db.DateTime, nullable=True)
    resolved_by_admin_id = db.Column(db.Integer, nullable=True)
    resolution_note    = db.Column(db.String(500), nullable=True)

    def to_dict(self):
        product = Product.query.get(self.product_id)
        return {
            "id": self.id, "product_id": self.product_id,
            "product_name": product.name if product else None,
            "seller_id": product.seller_id if product else None,
            "reason": self.reason, "details": self.details, "status": self.status,
            "created_at": self.created_at.isoformat() if self.created_at else None,
            "resolved_at": self.resolved_at.isoformat() if self.resolved_at else None,
            "resolution_note": self.resolution_note,
        }


def _seller_performance_stats(seller_id):
    """Live-computed tier + badges. Deliberately conservative: a seller
    starts at 'new_seller' with no history rather than an inflated
    default, and any upheld counterfeit/takedown flag overrides every
    other signal straight to 'under_review'."""
    orders = ProductOrder.query.filter_by(seller_id=seller_id).all()
    total = len(orders)
    disputes = [o for o in orders if o.escrow_status == "disputed" or o.escrow_status == "refunded"]
    dispute_rate = round(len(disputes) / total, 3) if total else 0.0
    stats = get_user_review_stats(seller_id)
    avg_rating = stats["average_rating"] or 0
    upheld_flags = (ProductFlag.query.join(Product, ProductFlag.product_id == Product.id)
                     .filter(Product.seller_id == seller_id, ProductFlag.status == "upheld").count())

    badges = []
    if upheld_flags > 0:
        tier = "under_review"
    elif total == 0:
        tier = "new_seller"
    elif total >= 20 and dispute_rate <= 0.02 and avg_rating >= 4.5:
        tier = "top_rated"
        badges.append("top_rated")
    elif total >= 5 and dispute_rate <= 0.10:
        tier = "established"
    else:
        tier = "growing"

    if total >= 50:
        badges.append("high_volume")
    if stats["review_count"] >= 10 and avg_rating >= 4.8:
        badges.append("highly_rated")
    if total >= 10 and dispute_rate == 0:
        badges.append("zero_disputes")

    # STAGE 341: VERIFIED FACTORY / SUPPLIER AUDITS — folded into the
    # same badges list every existing seller_badges consumer already
    # renders (Product.to_dict, MarketplaceListing.to_dict), rather
    # than wiring a second badge channel through the whole app.
    audit_summary = _seller_audit_public_summary(seller_id)
    if audit_summary["facility_verified"]:
        badges.append("verified_facility")
    if audit_summary["verified_certification_count"] > 0:
        badges.append("certified_supplier")

    # STAGE 342: NOTARIZED TRANSACTION HISTORY — a cheap count only
    # (no hash-chain walk) so it's safe to compute on every listing
    # render; full chain verification lives behind the dedicated
    # /api/ledger/* endpoints, run on demand rather than per-card.
    notarized_count = TransactionLedgerEntry.query.filter_by(seller_id=seller_id).count()
    if notarized_count > 0:
        badges.append("notarized_history")

    return {
        "tier": tier, "badges": badges, "total_orders": total,
        "dispute_count": len(disputes), "dispute_rate": dispute_rate,
        "average_rating": stats["average_rating"], "review_count": stats["review_count"],
        "upheld_flags": upheld_flags, "notarized_transaction_count": notarized_count,
    }


@app.route("/api/marketplace/sellers/<int:seller_id>/performance", methods=["GET"])
def marketplace_seller_performance(seller_id):
    seller = UserAccount.query.get(seller_id)
    if not seller:
        return jsonify({"error": "Seller not found."}), 404
    return jsonify({"seller_id": seller_id, "seller_name": seller.name, **_seller_performance_stats(seller_id)}), 200


@app.route("/api/products/<int:product_id>/flag", methods=["POST"])
@csrf.exempt
def product_flag_create(product_id):
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    product = Product.query.get(product_id)
    if not product:
        return jsonify({"error": "Product not found."}), 404
    data = request.get_json(silent=True) or {}
    reason = (data.get("reason") or "other").strip().lower()
    if reason not in PRODUCT_FLAG_REASONS:
        reason = "other"
    details = (data.get("details") or "").strip()[:500] or None
    flag = ProductFlag(product_id=product_id, reporter_id=user["id"], reason=reason, details=details)
    db.session.add(flag)
    db.session.commit()
    return jsonify({"ok": True, "flag": flag.to_dict()}), 201


@app.route("/api/admin/product-flags", methods=["GET"])
def admin_product_flags_list():
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    admin_account = UserAccount.query.get(user["id"])
    is_admin = bool(admin_account) and (
        admin_account.is_admin or (admin_account.email or "").strip().lower() in ADMIN_EMAILS)
    if not is_admin:
        return jsonify({"error": "Admin access required."}), 403
    status_filter = request.args.get("status", "open")
    q = ProductFlag.query
    if status_filter in ("open", "upheld", "dismissed"):
        q = q.filter_by(status=status_filter)
    rows = q.order_by(ProductFlag.created_at.desc()).limit(200).all()
    return jsonify({"flags": [f.to_dict() for f in rows]}), 200


@app.route("/api/admin/product-flags/<int:flag_id>/resolve", methods=["POST"])
@csrf.exempt
def admin_product_flags_resolve(flag_id):
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    admin_account = UserAccount.query.get(user["id"])
    is_admin = bool(admin_account) and (
        admin_account.is_admin or (admin_account.email or "").strip().lower() in ADMIN_EMAILS)
    if not is_admin:
        return jsonify({"error": "Admin access required."}), 403
    flag = ProductFlag.query.get(flag_id)
    if not flag:
        return jsonify({"error": "Flag not found."}), 404
    if flag.status != "open":
        return jsonify({"error": "This flag was already resolved."}), 400
    data = request.get_json(silent=True) or {}
    resolution = (data.get("resolution") or "").strip().lower()
    if resolution not in ("upheld", "dismissed"):
        return jsonify({"error": "resolution must be 'upheld' or 'dismissed'."}), 400
    flag.status = resolution
    flag.resolved_at = datetime.utcnow()
    flag.resolved_by_admin_id = user["id"]
    flag.resolution_note = (data.get("note") or "").strip()[:500] or None
    if resolution == "upheld":
        product = Product.query.get(flag.product_id)
        if product:
            product.is_active = False
    db.session.commit()
    return jsonify({"ok": True, "flag": flag.to_dict()}), 200


# ════════════════════════════════════════════════════════════
# STAGE 341: VERIFIED FACTORY / SUPPLIER AUDITS
# Real trust signals beyond a computed tier — a seller can submit a
# video-verified facility tour and upload real certifications (ISO
# 9001/14001, Fair Trade, BSCI, SA8000, HACCP, etc.), shown on the
# listing itself rather than only a badge. Nothing here is auto-
# approved: every video and every certificate sits at status="pending"
# until a recognized admin (_require_admin) reviews it — the same
# self-serve-then-admin-review shape the Stage 333 buyer ID
# verification and the Stage 79 KYC flow above already use.
#
# Once verified:
#   - a "verified_facility" / "certified_supplier" badge is folded
#     into the existing _seller_performance_stats() badges list, so
#     every place that already renders seller_badges (Product,
#     MarketplaceListing) picks it up with no separate wiring;
#   - the actual video + certificate list — not just the badge — is
#     served publicly via GET /api/audits/seller/<seller_id> so a
#     buyer can actually inspect them before a cross-border deal.
#
# Non-verified/rejected material is never exposed publicly — only the
# seller themself sees their own pending/rejected submissions, via
# GET /api/audits/mine.
# ════════════════════════════════════════════════════════════

SUPPLIER_CERT_TYPES = {
    "iso_9001":  "ISO 9001 (Quality Management)",
    "iso_14001": "ISO 14001 (Environmental Management)",
    "iso_45001": "ISO 45001 (Occupational Health & Safety)",
    "fair_trade": "Fair Trade Certified",
    "bsci":      "BSCI (Business Social Compliance Initiative)",
    "sa8000":    "SA8000 (Social Accountability)",
    "haccp":     "HACCP (Food Safety)",
    "gmp":       "GMP (Good Manufacturing Practice)",
    "organic":   "Organic Certification",
    "other":     "Other",
}


class FactoryAuditProfile(db.Model):
    __tablename__ = "factory_audit_profiles"
    id                     = db.Column(db.Integer, primary_key=True)
    seller_id              = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, unique=True, index=True)
    facility_name          = db.Column(db.String(150), nullable=True)
    facility_address       = db.Column(db.String(300), nullable=True)
    facility_city          = db.Column(db.String(120), nullable=True)
    facility_country_code  = db.Column(db.String(4),  nullable=True)
    video_url              = db.Column(db.String(500), nullable=True)
    video_status           = db.Column(db.String(12), nullable=False, default="none", index=True)  # none, pending, verified, rejected
    video_uploaded_at      = db.Column(db.DateTime, nullable=True)
    video_reviewed_at      = db.Column(db.DateTime, nullable=True)
    video_reviewed_by_admin_id = db.Column(db.Integer, nullable=True)
    video_review_note      = db.Column(db.String(500), nullable=True)
    created_at             = db.Column(db.DateTime, default=datetime.utcnow, index=True)
    updated_at             = db.Column(db.DateTime, default=datetime.utcnow, onupdate=datetime.utcnow)

    def to_dict(self, public=False):
        base = {
            "facility_name": self.facility_name,
            "facility_city": self.facility_city,
            "facility_country_code": self.facility_country_code,
            "video_status": self.video_status,
            "video_uploaded_at": self.video_uploaded_at.isoformat() if self.video_uploaded_at else None,
        }
        if public:
            # Only a verified video is ever exposed publicly; a pending
            # or rejected upload stays visible to the seller only.
            base["video_url"] = self.video_url if self.video_status == "verified" else None
        else:
            base.update({
                "id": self.id,
                "facility_address": self.facility_address,
                "video_url": self.video_url,
                "video_reviewed_at": self.video_reviewed_at.isoformat() if self.video_reviewed_at else None,
                "video_review_note": self.video_review_note,
            })
        return base


class SupplierCertification(db.Model):
    __tablename__ = "supplier_certifications"
    id                   = db.Column(db.Integer, primary_key=True)
    seller_id            = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    cert_type            = db.Column(db.String(20),  nullable=False, default="other")
    cert_type_label      = db.Column(db.String(80),  nullable=True)   # freeform label when cert_type == "other"
    issuing_body         = db.Column(db.String(150), nullable=True)
    cert_number          = db.Column(db.String(80),  nullable=True)
    file_url             = db.Column(db.String(500), nullable=True)
    issue_date           = db.Column(db.Date, nullable=True)
    expiry_date          = db.Column(db.Date, nullable=True)
    status               = db.Column(db.String(12), nullable=False, default="pending", index=True)  # pending, verified, rejected
    reviewed_at          = db.Column(db.DateTime, nullable=True)
    reviewed_by_admin_id = db.Column(db.Integer, nullable=True)
    review_note          = db.Column(db.String(500), nullable=True)
    created_at           = db.Column(db.DateTime, default=datetime.utcnow, index=True)

    def is_expired(self):
        return bool(self.expiry_date and self.expiry_date < datetime.utcnow().date())

    def label(self):
        if self.cert_type == "other" and self.cert_type_label:
            return self.cert_type_label
        return SUPPLIER_CERT_TYPES.get(self.cert_type, self.cert_type)

    def to_dict(self, public=False):
        base = {
            "cert_type": self.cert_type,
            "cert_label": self.label(),
            "issuing_body": self.issuing_body,
            "issue_date": self.issue_date.isoformat() if self.issue_date else None,
            "expiry_date": self.expiry_date.isoformat() if self.expiry_date else None,
            "is_expired": self.is_expired(),
        }
        if public:
            base["file_url"] = self.file_url
        else:
            base.update({
                "id": self.id,
                "cert_number": self.cert_number,
                "file_url": self.file_url,
                "status": self.status,
                "reviewed_at": self.reviewed_at.isoformat() if self.reviewed_at else None,
                "review_note": self.review_note,
                "created_at": self.created_at.isoformat() if self.created_at else None,
            })
        return base


def _seller_audit_public_summary(seller_id):
    """Lightweight, public-safe summary used to decorate listing cards —
    the boolean/count a card can show inline without a join-heavy
    payload. The full video + certificate list lives behind
    GET /api/audits/seller/<seller_id> for a genuine "view details"
    click-through."""
    profile = FactoryAuditProfile.query.filter_by(seller_id=seller_id).first()
    verified_cert_count = SupplierCertification.query.filter_by(seller_id=seller_id, status="verified").count()
    return {
        "facility_verified": bool(profile and profile.video_status == "verified"),
        "verified_certification_count": verified_cert_count,
    }


@app.route("/api/audits/mine", methods=["GET"])
def audits_mine():
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    profile = FactoryAuditProfile.query.filter_by(seller_id=user["id"]).first()
    certs = (SupplierCertification.query.filter_by(seller_id=user["id"])
             .order_by(SupplierCertification.created_at.desc()).all())
    return jsonify({
        "profile": profile.to_dict() if profile else None,
        "certifications": [c.to_dict() for c in certs],
        "cert_types": SUPPLIER_CERT_TYPES,
    }), 200


