@app.route("/api/audits/video-tour", methods=["POST"])
@csrf.exempt
def audits_video_tour_submit():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401

    video_url = None
    if request.files and "video" in request.files and request.files["video"].filename:
        video_url = _upload_to_cloudinary(
            file_bytes=request.files["video"].read(), resource_type="video", folder="connect it/factory_audits")
    else:
        data = request.get_json(silent=True) or {}
        submitted_url = (data.get("video_url") or "").strip()
        if submitted_url:
            video_url = _upload_to_cloudinary(file_url=submitted_url, resource_type="video", folder="connect it/factory_audits")

    if not video_url:
        return jsonify({"error": "A facility tour video (file upload or video_url) is required."}), 400

    profile = FactoryAuditProfile.query.filter_by(seller_id=user["id"]).first()
    if not profile:
        profile = FactoryAuditProfile(seller_id=user["id"])
        db.session.add(profile)
    profile.video_url = video_url
    profile.video_status = "pending"
    profile.video_uploaded_at = datetime.utcnow()
    # A resubmission clears any earlier review decision — it needs
    # fresh admin eyes, not a stale rejection note lingering.
    profile.video_reviewed_at = None
    profile.video_reviewed_by_admin_id = None
    profile.video_review_note = None
    db.session.commit()
    return jsonify({
        "ok": True, "profile": profile.to_dict(),
        "note": "Submitted for admin review. It won't show publicly as verified until approved.",
    }), 201


@app.route("/api/audits/certifications", methods=["POST"])
@csrf.exempt
def audits_certification_submit():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401

    if request.content_type and "multipart/form-data" in request.content_type:
        form = request.form
    else:
        form = request.get_json(silent=True) or {}

    cert_type = (form.get("cert_type") or "other").strip().lower()
    if cert_type not in SUPPLIER_CERT_TYPES:
        cert_type = "other"
    cert_type_label = (form.get("cert_type_label") or "").strip()[:80] or None
    issuing_body = (form.get("issuing_body") or "").strip()[:150] or None
    cert_number = (form.get("cert_number") or "").strip()[:80] or None

    def _parse_date(value):
        try:
            return datetime.strptime((value or "")[:10], "%Y-%m-%d").date()
        except (TypeError, ValueError):
            return None

    issue_date = _parse_date(form.get("issue_date"))
    expiry_date = _parse_date(form.get("expiry_date"))

    file_url = None
    if request.files and "file" in request.files and request.files["file"].filename:
        file_url = _upload_to_cloudinary(
            file_bytes=request.files["file"].read(), resource_type="image", folder="connect it/factory_audits/certs")
    elif isinstance(form, dict) and (form.get("file_url") or "").strip():
        file_url = _upload_to_cloudinary(file_url=form.get("file_url").strip(), resource_type="image", folder="connect it/factory_audits/certs")

    if not file_url:
        return jsonify({"error": "A certification document (file upload or file_url) is required."}), 400

    cert = SupplierCertification(
        seller_id=user["id"], cert_type=cert_type, cert_type_label=cert_type_label,
        issuing_body=issuing_body, cert_number=cert_number, file_url=file_url,
        issue_date=issue_date, expiry_date=expiry_date,
    )
    db.session.add(cert)
    db.session.commit()
    return jsonify({
        "ok": True, "certification": cert.to_dict(),
        "note": "Submitted for admin review. It won't show publicly as verified until approved.",
    }), 201


@app.route("/api/audits/certifications/<int:cert_id>", methods=["DELETE"])
@csrf.exempt
def audits_certification_delete(cert_id):
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    cert = SupplierCertification.query.filter_by(id=cert_id, seller_id=user["id"]).first()
    if not cert:
        return jsonify({"error": "Certification not found."}), 404
    if cert.status == "verified":
        return jsonify({"error": "A verified certification can't be removed — it's part of your trust record. Contact support if it's genuinely wrong."}), 400
    db.session.delete(cert)
    db.session.commit()
    return jsonify({"ok": True}), 200


@app.route("/api/audits/seller/<int:seller_id>", methods=["GET"])
def audits_seller_public(seller_id):
    seller = UserAccount.query.get(seller_id)
    if not seller:
        return jsonify({"error": "Seller not found."}), 404
    profile = FactoryAuditProfile.query.filter_by(seller_id=seller_id).first()
    verified_certs = (SupplierCertification.query
                       .filter_by(seller_id=seller_id, status="verified")
                       .order_by(SupplierCertification.created_at.desc()).all())
    return jsonify({
        "seller_id": seller_id, "seller_name": seller.name,
        "profile": profile.to_dict(public=True) if profile else None,
        "certifications": [c.to_dict(public=True) for c in verified_certs],
    }), 200


@app.route("/api/admin/audits/pending", methods=["GET"])
def admin_audits_pending():
    admin_user, err = _require_admin()
    if err:
        return err
    pending_videos = FactoryAuditProfile.query.filter_by(video_status="pending").order_by(FactoryAuditProfile.video_uploaded_at.asc()).all()
    pending_certs = SupplierCertification.query.filter_by(status="pending").order_by(SupplierCertification.created_at.asc()).all()

    def _video_row(p):
        seller = UserAccount.query.get(p.seller_id)
        d = p.to_dict()
        d["seller_id"] = p.seller_id
        d["seller_name"] = seller.name if seller else None
        return d

    def _cert_row(c):
        seller = UserAccount.query.get(c.seller_id)
        d = c.to_dict()
        d["seller_id"] = c.seller_id
        d["seller_name"] = seller.name if seller else None
        return d

    return jsonify({
        "pending_video_tours": [_video_row(p) for p in pending_videos],
        "pending_certifications": [_cert_row(c) for c in pending_certs],
    }), 200


@app.route("/api/admin/audits/video-tour/<int:seller_id>/review", methods=["POST"])
@csrf.exempt
def admin_audits_video_review(seller_id):
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    admin_user, err = _require_admin()
    if err:
        return err
    profile = FactoryAuditProfile.query.filter_by(seller_id=seller_id).first()
    if not profile:
        return jsonify({"error": "No facility audit submission for this seller."}), 404
    data = request.get_json(silent=True) or {}
    decision = (data.get("status") or "").strip().lower()
    if decision not in ("verified", "rejected"):
        return jsonify({"error": "status must be 'verified' or 'rejected'."}), 400
    profile.video_status = decision
    profile.video_reviewed_at = datetime.utcnow()
    profile.video_reviewed_by_admin_id = admin_user.id
    profile.video_review_note = (data.get("note") or "").strip()[:500] or None
    db.session.commit()
    return jsonify({"ok": True, "profile": profile.to_dict()}), 200


