# ════════════════════════════════════════════════════════════
# STAGE 327: COUPON CODES — seller-managed CRUD + a shared
# validate-and-price helper used by both Buy Now and cart checkout.
# ════════════════════════════════════════════════════════════

def _parse_coupon_fields(data):
    """Shared validation for create/update. Returns (fields_dict, error)."""
    code = (data.get("code") or "").strip().upper()[:40]
    if not code:
        return None, "'code' is required."
    discount_type = (data.get("discount_type") or "").strip().lower()
    if discount_type not in ("percent", "fixed"):
        return None, "'discount_type' must be 'percent' or 'fixed'."
    try:
        discount_value = float(data.get("discount_value"))
    except (TypeError, ValueError):
        return None, "'discount_value' must be a number."
    if discount_value <= 0:
        return None, "'discount_value' must be greater than zero."
    if discount_type == "percent" and discount_value > 90:
        return None, "Percent discounts can't exceed 90%."
    min_order_subtotal = None
    if data.get("min_order_subtotal") not in (None, ""):
        try:
            min_order_subtotal = max(0.0, float(data.get("min_order_subtotal")))
        except (TypeError, ValueError):
            return None, "'min_order_subtotal' must be a number if provided."
    max_redemptions = None
    if data.get("max_redemptions") not in (None, ""):
        try:
            max_redemptions = max(1, int(data.get("max_redemptions")))
        except (TypeError, ValueError):
            return None, "'max_redemptions' must be a whole number if provided."
    try:
        per_buyer_limit = max(1, int(data.get("per_buyer_limit", 1)))
    except (TypeError, ValueError):
        per_buyer_limit = 1

    def _parse_dt(key):
        raw = data.get(key)
        if not raw:
            return None
        try:
            return datetime.fromisoformat(raw.replace("Z", "+00:00")).replace(tzinfo=None)
        except (TypeError, ValueError):
            return None

    return {
        "code": code, "discount_type": discount_type, "discount_value": discount_value,
        "min_order_subtotal": min_order_subtotal, "max_redemptions": max_redemptions,
        "per_buyer_limit": per_buyer_limit,
        "valid_from": _parse_dt("valid_from"), "valid_until": _parse_dt("valid_until"),
    }, None


