@app.route("/api/coupons", methods=["POST"])
@csrf.exempt
def coupon_create():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    fields, error = _parse_coupon_fields(data)
    if error:
        return jsonify({"error": error}), 400
    if Coupon.query.filter_by(seller_id=user["id"], code=fields["code"]).first():
        return jsonify({"error": f'You already have a coupon with code "{fields["code"]}".'}), 400
    coupon = Coupon(seller_id=user["id"], is_active=True, **fields)
    db.session.add(coupon)
    db.session.commit()
    return jsonify({"ok": True, "coupon": coupon.to_dict()}), 201


@app.route("/api/coupons/<int:coupon_id>", methods=["PUT"])
@csrf.exempt
def coupon_update(coupon_id):
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    coupon = Coupon.query.get(coupon_id)
    if not coupon or coupon.seller_id != user["id"]:
        return jsonify({"error": "Coupon not found."}), 404
    data = request.get_json(silent=True) or {}
    if "is_active" in data and len(data) == 1:
        coupon.is_active = bool(data.get("is_active"))
        db.session.commit()
        return jsonify({"ok": True, "coupon": coupon.to_dict()}), 200
    fields, error = _parse_coupon_fields(data)
    if error:
        return jsonify({"error": error}), 400
    existing = Coupon.query.filter_by(seller_id=user["id"], code=fields["code"]).first()
    if existing and existing.id != coupon.id:
        return jsonify({"error": f'You already have a coupon with code "{fields["code"]}".'}), 400
    for key, value in fields.items():
        setattr(coupon, key, value)
    if "is_active" in data:
        coupon.is_active = bool(data.get("is_active"))
    db.session.commit()
    return jsonify({"ok": True, "coupon": coupon.to_dict()}), 200


