def _resolve_coupon_for_checkout(code, seller_id, buyer_id, eligible_subtotal):
    """Shared by Buy Now and cart checkout. code/seller_id identify the
    coupon; eligible_subtotal is the subtotal of THIS seller's line(s)
    only in the current checkout (a coupon never touches another
    seller's items in the same cart). Returns (coupon_or_None,
    discount_amount, error_or_None). No side effects — redemption is
    only recorded once the order is actually created, by the caller."""
    if not code:
        return None, 0.0, None
    coupon = Coupon.query.filter_by(
        seller_id=seller_id, code=code.strip().upper()).first()
    if not coupon:
        return None, 0.0, "That coupon code isn't valid for this seller."
    valid, reason = coupon.is_currently_valid()
    if not valid:
        return None, 0.0, reason
    if coupon.min_order_subtotal is not None and eligible_subtotal < coupon.min_order_subtotal:
        return None, 0.0, f"This coupon needs a minimum order of {coupon.min_order_subtotal} from this seller."
    prior_uses = CouponRedemption.query.filter_by(coupon_id=coupon.id, buyer_id=buyer_id).count()
    if prior_uses >= coupon.per_buyer_limit:
        return None, 0.0, "You've already used this coupon the maximum number of times."
    discount = coupon.discount_for_subtotal(eligible_subtotal)
    return coupon, discount, None


def _record_coupon_redemption(coupon, buyer_id, discount_amount):
    coupon.redemption_count += 1
    db.session.add(CouponRedemption(coupon_id=coupon.id, buyer_id=buyer_id, discount_amount=discount_amount))


# ════════════════════════════════════════════════════════════
# STAGE 311: BULK CSV LISTING IMPORT
# Sellers with a real catalog won't hand-type 200 products through the
# Sell tab one at a time. Reuses _product_fields_from unchanged (same
# create-endpoint validation applies to every row) and follows the same
# "tolerant" import pattern as the existing bank-statement CSV import
# (Stage 43957-ish reconcile upload) — bad rows are skipped and
# reported, not allowed to abort the whole batch.
# ════════════════════════════════════════════════════════════

PRODUCT_CSV_TEMPLATE_HEADERS = [
    "name", "description", "category", "price", "currency",
    "quantity_available", "unit", "min_order_quantity", "city", "country_code",
]


@app.route("/api/products/bulk-import/template", methods=["GET"])
def product_bulk_import_template():
    """Downloadable CSV a seller can fill in and re-upload. Not
    login-gated — it's just a static template, no seller data in it."""
    buf = io.StringIO()
    writer = csv.writer(buf)
    writer.writerow(PRODUCT_CSV_TEMPLATE_HEADERS)
    writer.writerow(["Sample Product Name", "A short description of the item", "Retail & Wholesale",
                      "19.99", "USD", "50", "each", "1", "Harare", "ZW"])
    return Response(
        buf.getvalue(), mimetype="text/csv",
        headers={"Content-Disposition": "attachment; filename=product_import_template.csv"},
    )


@app.route("/api/products/bulk-import", methods=["POST"])
@csrf.exempt
def product_bulk_import():
    """Multipart form field 'file' — a CSV matching
    PRODUCT_CSV_TEMPLATE_HEADERS (extra/reordered columns are fine,
    matched by header name; only name and price are required per row).
    Every valid row becomes an active listing for the current seller;
    invalid rows are skipped and reported by row number, not allowed to
    fail the whole batch."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    if "file" not in request.files:
        return jsonify({"error": "Send the CSV under form field 'file'."}), 400
    f = request.files["file"]

    try:
        raw = f.read().decode("utf-8-sig", errors="replace")
        reader = csv.DictReader(io.StringIO(raw))
        if not reader.fieldnames:
            return jsonify({"error": "CSV file is empty or has no header row."}), 400
        # Normalize headers so "Price", " price ", "PRICE" all match.
        normalized_fields = {(h or "").strip().lower(): h for h in reader.fieldnames}
        if "name" not in normalized_fields or "price" not in normalized_fields:
            return jsonify({"error": "CSV header row must include at least 'name' and 'price' columns."}), 400

        created = []
        skipped = []
        row_num = 1  # header is row 1, first data row is row 2
        for raw_row in reader:
            row_num += 1
            if row_num > 502:  # 500 data rows max per upload
                skipped.append({"row": row_num, "reason": "Stopped at 500 rows — split larger catalogs into multiple uploads."})
                break
            if not raw_row or all(not (v or "").strip() for v in raw_row.values()):
                continue  # silently skip fully blank rows, not worth reporting
            row = {norm: (raw_row.get(orig) or "").strip() for norm, orig in normalized_fields.items()}
            fields = _product_fields_from(row)
            if not fields["name"]:
                skipped.append({"row": row_num, "reason": "Missing name."})
                continue
            if fields["price"] is None or fields["price"] < 0:
                skipped.append({"row": row_num, "reason": f"Missing or invalid price for \"{fields['name']}\"."})
                continue
            product = Product(
                seller_id=user["id"], name=fields["name"], description=fields["description"],
                category=fields["category"], price=fields["price"], currency=fields["currency"],
                quantity_available=fields["quantity_available"], min_order_quantity=fields["min_order_quantity"],
                unit=fields["unit"], city=fields["city"], country_code=fields["country_code"],
                is_active=True,
            )
            db.session.add(product)
            created.append(product)
        db.session.commit()
        for p in created:
            meilisearch_index_product(p)
        return jsonify({
            "ok": True, "created_count": len(created), "skipped_count": len(skipped),
            "skipped": skipped[:50],  # cap the report — the count above is still accurate
            "products": [p.to_dict() for p in created],
        }), 201
    except Exception as e:
        db.session.rollback()
        logging.error(f"[PRODUCT BULK IMPORT ERROR] {e}")
        return jsonify({"error": "Could not process that CSV. Download the template to check the expected columns."}), 500


# STAGE 312: WhatsApp broadcast to a seller's own opted-in subscriber
# list (WhatsAppOptInLead, already existed — this is the "use it to
# announce new listings" half of that gap). Sends a pre-approved
# template message (required outside the 24h session window — Meta
# rejects free text here) to every consented lead. Capped low per call
# since each send is a blocking HTTP round-trip inside one request;
# a seller with more subscribers just broadcasts in a few batches.
PRODUCT_BROADCAST_MAX_RECIPIENTS = 30


@app.route("/api/products/<int:product_id>/broadcast", methods=["POST"])
@csrf.exempt
def product_broadcast_to_subscribers(product_id):
    """Body: template_name, language_code (optional, default en_US).
    Only templates with no variables are supported here — for anything
    with {{1}}-style placeholders, use the existing single-contact
    template sender per recipient instead."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    product = Product.query.filter_by(id=product_id, seller_id=user["id"]).first()
    if not product:
        return jsonify({"error": "Product not found."}), 404
    data = request.get_json(silent=True) or {}
    template_name = (data.get("template_name") or "").strip()
    language_code = (data.get("language_code") or "en_US").strip()
    if not template_name:
        return jsonify({"error": "template_name is required — pick one of your approved WhatsApp templates."}), 400

    leads = (WhatsAppOptInLead.query.filter_by(user_id=user["id"])
             .order_by(WhatsAppOptInLead.created_at.desc())
             .limit(PRODUCT_BROADCAST_MAX_RECIPIENTS).all())
    if not leads:
        return jsonify({"error": "No opted-in WhatsApp subscribers yet — set up your opt-in widget first."}), 400

    sent, failed = [], []
    for lead in leads:
        try:
            send_whatsapp_template_message(user["id"], lead.phone, template_name, language_code)
            sent.append(lead.phone)
        except Exception as e:
            failed.append({"phone": lead.phone, "reason": str(e)})
    return jsonify({
        "ok": True, "sent_count": len(sent), "failed_count": len(failed), "failed": failed[:10],
        "note": (f"Only broadcast to the {PRODUCT_BROADCAST_MAX_RECIPIENTS} most recent opt-ins per call — "
                 f"run again to reach older subscribers." if len(leads) == PRODUCT_BROADCAST_MAX_RECIPIENTS else None),
    }), 200


def _create_product_order_checkout(product, buyer_id, quantity, unit_price=None, currency=None, note=None,
                                    variant=None, discount_amount=0.0, coupon_code=None, store_credit_amount=0.0,
                                    pay_currency=None, payment_method="card"):
    """Shared by the plain Buy Now flow and RFQ winner-selection — creates
    the ProductOrder row and, if Stripe is configured, a Checkout Session
    that captures to the platform and holds the payment (Trade Assurance).
    unit_price/currency let a callsite (like an awarded RFQ quote)
    override the product's listed price without touching the listing
    itself. variant (STAGE 326) is an optional ProductVariant — when
    given, its own price (if set) wins over unit_price/product pricing,
    and the order's line item and record both carry its label.
    discount_amount/coupon_code (STAGE 327) are an already-validated,
    already-priced coupon discount off the line's pre-discount subtotal
    — this function just applies and records it, all validation happens
    in _resolve_coupon_for_checkout before this is called.
    store_credit_amount (STAGE 328) is an already-capped amount of the
    buyer's own store-credit balance to apply after the coupon — this
    function only records it on the order; the caller (product_buy) is
    responsible for actually deducting it from StoreCreditAccount, since
    that deduction should only happen once, at the very end, after every
    other validation in the request has already passed. If the coupon +
    store credit cover the full subtotal, no Stripe session is created
    at all and the order is marked paid immediately.
    pay_currency (STAGE 338 — MULTI-CURRENCY, MULTI-RAIL SETTLEMENT) is
    an optional ISO code the BUYER explicitly chose to actually pay in,
    e.g. a Kenyan buyer paying a Vietnamese seller's USD-listed goods in
    KES. When given and it differs from the listing's own currency, this
    locks a live FX rate right now, converts every downstream amount
    (subtotal, discount, store credit, total charge) into pay_currency
    at that locked rate, and creates the Stripe Checkout Session itself
    IN pay_currency — so the buyer's statement shows exactly the number
    they agreed to, not a card-network conversion applied after the
    fact. The seller still receives payout in whatever currency their
    Stripe Connect account settles in (see UserAccount.payout_currency);
    Stripe converts that leg automatically. Falls back to the listing's
    own currency (old behavior) if a live rate isn't available right
    now, rather than risk a mismatched charge.
    payment_method (STAGE 524 — BNPL AT CHECKOUT) is one of "card"
    (default), a Stripe-native BNPL rail ("klarna", "afterpay_clearpay",
    "affirm" — Stripe funds the platform in full immediately, same as a
    card, just a different payment_method_types entry), or "pay_in_4"
    (platform-native — collects 25% now with the card saved for
    off-session use, and creates the BnplInstallmentPlan/BnplInstallment
    schedule once the webhook confirms payment; see
    _bnpl_finalize_plan_from_session). Callers MUST have already run
    _bnpl_pay_in_4_eligibility (for "pay_in_4") and confirmed
    _bnpl_checkout_enabled() (for any non-"card" value) before calling
    this — this function trusts its caller and does not re-check either.
    Returns (order, checkout_url_or_None)."""
    # STAGE 514k: demo accounts never move real money — a return of
    # (None, None) here means every callsite's existing "no checkout
    # URL" fallback path runs (order still isn't created), same as
    # when Stripe itself isn't configured, so no new failure mode is
    # introduced at any of this helper's many call sites.
    buyer_account = UserAccount.query.get(buyer_id)
    if buyer_account and buyer_account.is_demo_account:
        logging.info(f"[DEMO GUARD] blocked real checkout attempt from demo account {buyer_id}")
        return None, None
    if variant is not None:
        price = variant.unit_price_for_quantity(product, quantity) if unit_price is None else unit_price
    else:
        price = unit_price if unit_price is not None else product.unit_price_for_quantity(quantity)
    ccy = currency or product.currency

    # STAGE 338: resolve real settlement currency + locked rate BEFORE
    # any amounts are computed, so every downstream number (subtotal,
    # discount, store credit, Stripe line items) is consistently in the
    # settlement currency rather than mixing currencies partway through.
    settlement_ccy, settlement_rate, settlement_locked = ccy, 1.0, False
    fx_hedge_lock_used = None
    pay_currency = (pay_currency or "").strip().upper()[:8] or None
    if pay_currency and pay_currency != (ccy or "USD").upper():
        # STAGE 353: if the buyer previously locked a rate for exactly
        # this currency pair and it's still active/unexpired, honor the
        # locked rate instead of today's spot — that's the entire point
        # of having booked the hedge. Only ever checked here, at the
        # one real chokepoint where a settlement rate gets fixed.
        hedge_lock = _fx_find_active_lock(buyer_id, ccy, pay_currency)
        if hedge_lock:
            settlement_ccy, settlement_rate, settlement_locked = pay_currency, hedge_lock.locked_rate, True
            fx_hedge_lock_used = hedge_lock
        else:
            rate = _fx_cross_rate(ccy, pay_currency)   # units of pay_currency per 1 unit of ccy
            if rate:
                settlement_ccy, settlement_rate, settlement_locked = pay_currency, rate, True
            else:
                logging.warning(f"[MULTI-CURRENCY SETTLEMENT] No live rate {ccy}->{pay_currency}; "
                                 f"falling back to listing currency {ccy}.")

    def _settle(amount):
        return round((amount or 0.0) * settlement_rate, 2)

    price_settled = _settle(price)
    subtotal = round(price_settled * quantity, 2)
    discount_amount = round(min(max(_settle(discount_amount), 0.0), subtotal), 2)
    store_credit_amount = round(min(max(_settle(store_credit_amount), 0.0), subtotal - discount_amount), 2)
    total_charge = round(subtotal - discount_amount - store_credit_amount, 2)
    order = ProductOrder(
        product_id=product.id, buyer_id=buyer_id, seller_id=product.seller_id,
        quantity=quantity, total_price=round(subtotal - discount_amount, 2), currency=settlement_ccy,
        note=(note or None), status="pending",
        variant_id=(variant.id if variant is not None else None),
        variant_label=(variant.label if variant is not None else None),
        coupon_code=(coupon_code if discount_amount > 0 else None),
        discount_amount=(discount_amount if discount_amount > 0 else None),
        store_credit_applied=(store_credit_amount if store_credit_amount > 0 else None),
    )
    if settlement_locked:
        # Real, actually-charged settlement: buyer_currency_* now records
        # exactly what left the buyer's card, not an estimate.
        order.buyer_currency = settlement_ccy
        order.buyer_currency_rate = settlement_rate
        order.buyer_currency_amount = order.total_price
        order.settlement_locked = True
    else:
        # MULTI-CURRENCY SETTLEMENT (informational path, unchanged from
        # before Stage 338): if the buyer has a preferred display
        # currency different from this order's own currency, lock in
        # today's rate now purely so their order history shows an
        # honest reference figure — the actual charge still runs in ccy.
        try:
            buyer_account = UserAccount.query.get(buyer_id)
            if buyer_account and buyer_account.preferred_currency and buyer_account.preferred_currency.upper() != (ccy or "USD").upper():
                fx_rate = _fx_cross_rate(ccy, buyer_account.preferred_currency)
                if fx_rate:
                    order.buyer_currency = buyer_account.preferred_currency.upper()
                    order.buyer_currency_rate = fx_rate
                    order.buyer_currency_amount = round(order.total_price * fx_rate, 2)
        except Exception as e:
            logging.warning(f"[MULTI-CURRENCY ORDER QUOTE] {e}")
    if fx_hedge_lock_used is not None:
        order.fx_hedge_lock_id = fx_hedge_lock_used.id
    db.session.add(order)
    db.session.commit()
    if fx_hedge_lock_used is not None:
        # STAGE 353: a lock is good for exactly one qualifying order —
        # consume it now that the order it protected actually exists.
        fx_hedge_lock_used.status = "used"
        fx_hedge_lock_used.used_at = datetime.utcnow()
        fx_hedge_lock_used.used_order_id = order.id
        db.session.commit()
    ccy = settlement_ccy
    price = price_settled

    # Store credit covered the whole thing (after the coupon) — no card
    # to charge, so there's nothing for Stripe to do. Mark it paid the
    # same way a completed Checkout Session would.
    if total_charge <= 0.005:
        order.status = "paid"
        order.paid_at = datetime.utcnow()
        db.session.commit()
        return order, None

    line_item_name = product.name + (f" ({variant.label})" if variant is not None else "")
    payment_method = (payment_method or "card").strip().lower()
    is_pay_in_4 = (payment_method == "pay_in_4")
    if STRIPE_SECRET_KEY:
        try:
            import stripe
            stripe.api_key = STRIPE_SECRET_KEY
            seller_account = UserAccount.query.get(product.seller_id)
            total_amount = int(round(total_charge * 100))  # full order total, in cents — always the fee/escrow basis
            # STAGE 524: 'pay_in_4' only actually charges the buyer's
            # card a 25% deposit today; the seller is still paid out on
            # the FULL total_amount above (Trade Assurance fee below is
            # computed off total_amount, not the deposit) because the
            # platform is fronting the rest — see the STAGE 524 comment
            # block near BnplInstallmentPlan for why that's real risk.
            deposit_amount_cents = int(round(total_amount / BNPL_PAY_IN_4_NUM_INSTALLMENTS)) if is_pay_in_4 else None
            stripe_charge_now_cents = deposit_amount_cents if is_pay_in_4 else total_amount
            # A discounted line collapses to a single quantity-1 Stripe
            # line item priced at the exact post-discount total — keeps
            # the math exact instead of trying to divide a discount
            # evenly across per-unit pricing and risking rounding drift.
            # STAGE 328: store credit is folded into the same collapse.
            # STAGE 524: 'pay_in_4' always collapses to one line item too
            # — it's charging a flat deposit, not per-unit pricing.
            if is_pay_in_4:
                stripe_line_items = [{
                    "price_data": {
                        "currency": (ccy or "usd").lower(),
                        "product_data": {"name": f"{line_item_name} × {quantity} — Pay in 4, installment 1 of "
                                                  f"{BNPL_PAY_IN_4_NUM_INSTALLMENTS} (order total {ccy} {total_charge:.2f})"},
                        "unit_amount": stripe_charge_now_cents,
                    },
                    "quantity": 1,
                }]
            elif discount_amount > 0 or store_credit_amount > 0:
                label_bits = []
                if coupon_code and discount_amount > 0:
                    label_bits.append(f"coupon {coupon_code} applied")
                if store_credit_amount > 0:
                    label_bits.append(f"{ccy} {store_credit_amount:.2f} store credit applied")
                suffix = f" ({', '.join(label_bits)})" if label_bits else ""
                stripe_line_items = [{
                    "price_data": {
                        "currency": (ccy or "usd").lower(),
                        "product_data": {"name": f"{line_item_name} × {quantity}{suffix}"},
                        "unit_amount": total_amount,
                    },
                    "quantity": 1,
                }]
            else:
                unit_amount = int(round(price * 100))
                stripe_line_items = [{
                    "price_data": {
                        "currency": (ccy or "usd").lower(),
                        "product_data": {"name": line_item_name},
                        "unit_amount": unit_amount,
                    },
                    "quantity": quantity,
                }]
            # STAGE 524: payment_method_types is the only thing that
            # changes for the Stripe-native BNPL rails (klarna/
            # afterpay_clearpay/affirm) — Stripe underwrites, funds the
            # platform in full, and services the buyer directly, exactly
            # like a card. 'pay_in_4' stays on "card" underneath (it's a
            # real card, just charged in installments by us).
            session_payment_method_types = (
                [payment_method] if payment_method in BNPL_NATIVE_METHODS else ["card"]
            )
            session_params = dict(
                payment_method_types=session_payment_method_types,
                line_items=stripe_line_items,
                mode="payment",
                success_url=APP_BASE_URL + "/payment-success?session_id={CHECKOUT_SESSION_ID}",
                cancel_url=APP_BASE_URL + "/?order=cancelled",
                metadata={"order_id": str(order.id), "product_id": str(product.id), "kind": "marketplace_product"},
                shipping_address_collection={"allowed_countries": SHIPPING_ALLOWED_COUNTRIES},
            )
            # STAGE 304: TRADE ASSURANCE — capture to the PLATFORM (no
            # transfer_data) and hold; see _release_product_order_escrow.
            session_params["payment_intent_data"] = {"transfer_group": f"order_{order.id}"}
            order.checkout_transfer_group = f"order_{order.id}"
            if is_pay_in_4:
                # STAGE 524: save this card for the 3 off-session charges
                # /api/cron/bnpl-installments-run will make later, and
                # request a persistent Customer object (a one-off
                # "payment" mode session doesn't create one by default)
                # so those future charges have somewhere to attach to.
                session_params["payment_intent_data"]["setup_future_usage"] = "off_session"
                session_params["customer_creation"] = "always"
                session_params["metadata"]["bnpl_plan"] = "pay_in_4"
                session_params["metadata"]["bnpl_total_amount"] = f"{total_charge:.2f}"
            if (seller_account and seller_account.stripe_connect_account_id
                    and seller_account.stripe_connect_payouts_enabled):
                # STAGE 388: subsidized micro-sellers get a reduced
                # effective fee here instead of the flat platform rate.
                # STAGE 524: fee is on the FULL order (total_amount), not
                # the deposit — the seller is being paid out in full.
                fee_amount = max(0, (total_amount * _effective_platform_fee_bps(product.seller_id)) // 10000)
                order.platform_fee = round(fee_amount / 100, 2)
            session = stripe.checkout.Session.create(**session_params)
            order.stripe_session_id = session.id
            db.session.commit()
            return order, session.url
        except Exception as e:
            logging.error(f"[PRODUCT ORDER CHECKOUT] Stripe checkout failed: {e}")
            # fall through — the order is already saved either way

    order.status = "contacted"
    db.session.commit()
    return order, None


@app.route("/api/products/<int:product_id>/buy", methods=["POST"])
@csrf.exempt
def product_buy(product_id):
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    product = Product.query.get(product_id)
    if not product or not product.is_active:
        return jsonify({"error": "Product not found."}), 404
    if product.seller_id == user["id"]:
        return jsonify({"error": "You can't buy your own listing."}), 400

    data = request.get_json(silent=True) or {}

    # STAGE 361: RESTRICTED-GOODS / EXPORT-CONTROL MATRIX — checked
    # against the buyer's own country as the shipping destination. A
    # "prohibited" match blocks the order outright; "license_required"/
    # "review" matches require the buyer to explicitly acknowledge the
    # notice (compliance_ack: true) before the order can proceed.
    buyer_account = UserAccount.query.get(user["id"])
    restriction = _restricted_goods_check(product, buyer_account.country_code if buyer_account else None)
    if restriction:
        if restriction["level"] == "prohibited":
            return jsonify({
                "error": "This item can't be shipped to your country: " + restriction["reason"],
                "is_prohibited": True,
            }), 403
        if not data.get("compliance_ack"):
            return jsonify({
                "error": restriction["reason"],
                "requires_compliance_ack": True,
                "restriction_level": restriction["level"],
            }), 409

    # STAGE 362: seller's Store Policy (payment terms / non-delivery /
    # compensation / privacy) must be read and acknowledged before a
    # first-time payment to this seller goes through, same 409-with-a-
    # flag pattern as the restricted-goods notice above.
    pending_policy = _store_policy_requires_ack(product.seller_id, user["id"])
    if pending_policy:
        if not data.get("policy_ack"):
            return jsonify({
                "error": "Please review this seller's store policy before paying.",
                "requires_policy_ack": True,
                "store_policy": pending_policy.to_dict(),
            }), 409
        _record_store_policy_ack(product.seller_id, user["id"], pending_policy.version, request.remote_addr)

    try:
        quantity = max(1, int(data.get("quantity", product.min_order_quantity or 1)))
    except (TypeError, ValueError):
        quantity = product.min_order_quantity or 1

    variant, variant_error = _resolve_variant_for_purchase(product, data.get("variant_id"))
    if variant_error:
        return jsonify({"error": variant_error}), 400
    available = variant.quantity_available if variant is not None else product.quantity_available
    if available and quantity > available:
        # STAGE 346: real cross-seller stock matching -- don't just dead-end
        # the buyer here; surface equivalent listings from other sellers
        # that can actually cover the quantity they wanted.
        alternatives = _mkt_stock_alternatives(product, quantity=quantity) if variant is None else []
        return jsonify({
            "error": f"Only {available} available.",
            "stock_alternatives": alternatives,
        }), 400
    if quantity < (product.min_order_quantity or 1):
        return jsonify({"error": f"Minimum order quantity is {product.min_order_quantity}."}), 400

    unit_price = variant.unit_price_for_quantity(product, quantity) if variant is not None else product.unit_price_for_quantity(quantity)
    coupon_code = (data.get("coupon_code") or "").strip() or None
    discount_amount, coupon = 0.0, None
    if coupon_code:
        coupon, discount_amount, coupon_error = _resolve_coupon_for_checkout(
            coupon_code, product.seller_id, user["id"], round(unit_price * quantity, 2))
        if coupon_error:
            return jsonify({"error": coupon_error}), 400

    # STAGE 338: MULTI-CURRENCY, MULTI-RAIL SETTLEMENT — buyer can pay in
    # any currency the live FX source carries, not just the listing's
    # own currency.
    pay_currency = (data.get("pay_currency") or "").strip().upper()[:8] or None

    # STAGE 328: buyer can opt to apply their platform store-credit
    # balance — capped by both what they have and what's left of the
    # order after the coupon. Not deducted until the order is
    # successfully created below. store_credit_amount here is always in
    # the listing's own NATIVE currency (like unit_price above) — if
    # pay_currency triggers real settlement conversion below, it gets
    # converted alongside everything else inside
    # _create_product_order_checkout, so the check here is against the
    # native currency, not whatever the order ultimately settles in —
    # avoids silently applying, say, a KES balance against a listing
    # priced (and credit-tracked) in USD.
    store_credit_amount = 0.0
    if data.get("use_store_credit"):
        credit_account = _get_or_create_store_credit_account(user["id"])
        if (credit_account.currency or "USD").upper() == (product.currency or "USD").upper():
            eligible_remaining = round(unit_price * quantity - discount_amount, 2)
            store_credit_amount = round(min(max(credit_account.balance, 0.0), max(eligible_remaining, 0.0)), 2)

    # STAGE 524: BNPL AT CHECKOUT — "card" (default) always passes
    # straight through. Anything else requires the admin-controlled
    # bnpl_checkout flag to be unlocked; "pay_in_4" additionally needs a
    # real-time eligibility check (buyer standing + amount + currency)
    # run again here server-side, never trusted from an earlier quote.
    payment_method = (data.get("payment_method") or "card").strip().lower()
    if payment_method != "card":
        if not _bnpl_checkout_enabled():
            return jsonify({
                "error": "Buy Now, Pay Later is not enabled on this account yet.",
                "feature_locked": True,
            }), 503
        if payment_method not in BNPL_NATIVE_METHODS and payment_method != "pay_in_4":
            return jsonify({"error": "Unknown payment method."}), 400
        if payment_method == "pay_in_4":
            if pay_currency and pay_currency != (product.currency or "USD").upper():
                return jsonify({"error": "Pay in 4 isn't available when paying in a different currency than the listing."}), 400
            estimated_total = round(unit_price * quantity - discount_amount - store_credit_amount, 2)
            eligible, reason, _rep = _bnpl_pay_in_4_eligibility(user["id"], estimated_total, product.currency)
            if not eligible:
                return jsonify({"error": reason, "bnpl_ineligible": True}), 400

    order, checkout_url = _create_product_order_checkout(
        product, user["id"], quantity, note=(data.get("note") or "").strip()[:500] or None, variant=variant,
        discount_amount=discount_amount, coupon_code=coupon_code, store_credit_amount=store_credit_amount,
        pay_currency=pay_currency, payment_method=payment_method)
    if coupon is not None:
        _record_coupon_redemption(coupon, user["id"], discount_amount)
    if order.store_credit_applied:
        # order.store_credit_applied is in the ORDER's settlement
        # currency (converted alongside everything else when
        # pay_currency triggered real settlement) — but the credit
        # account itself is always in its own native currency, so
        # convert back before deducting.
        native_applied = order.store_credit_applied
        if order.settlement_locked and order.buyer_currency_rate:
            native_applied = round(order.store_credit_applied / order.buyer_currency_rate, 2)
        _spend_store_credit(user["id"], native_applied, "order_payment", reference=f"order_{order.id}")
    db.session.commit()
    return jsonify({"ok": True, "order": order.to_dict(), "checkout_url": checkout_url}), 201


# ════════════════════════════════════════════════════════════
# STAGE 307: CART / MULTI-ITEM CHECKOUT
# "Buy Now" only ever handled one product at a time. This adds a real
# cart across any mix of sellers in one checkout. It only became
# straightforward to build cleanly because of Stage 304 (Trade
# Assurance): every card payment already captures to the PLATFORM
# account first and is held per-order rather than instant-transferred
# to a seller — so a single Checkout Session can legally contain line
# items from several different sellers (nothing needs to be split at
# payment time the way a destination charge would have forced). One
# ProductOrder is still created per line item — each gets its own
# independent escrow_status, its own Mark as Received / dispute
# lifecycle — the cart just bundles them under one Stripe payment.
# The cart itself lives client-side (see cartGet/cartAdd/etc. in
# index.html); nothing to persist server-side until checkout.
#
# STAGE 524 scope note: BNPL at checkout (payment_method on
# product_buy/_create_product_order_checkout) is deliberately NOT wired
# in here yet. "pay_in_4" schedules one saved card against one order;
# a cart can span several sellers/orders under one Stripe session, and
# splitting a single deposit charge back out across N independently-
# escrowed orders (each with its own eventual payout) needs its own
# design rather than a copy-paste of the single-item path. Card stays
# the only cart checkout method for now.
# ════════════════════════════════════════════════════════════

@app.route("/api/cart/checkout", methods=["POST"])
@csrf.exempt
def cart_checkout():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    items = data.get("items") or []
    if not items or not isinstance(items, list):
        return jsonify({"error": "Cart is empty."}), 400
    if len(items) > 30:
        return jsonify({"error": "Checkout up to 30 line items at a time."}), 400

    # Validate every line before creating anything — an all-or-nothing
    # checkout, not a partial one that leaves the buyer guessing which
    # items actually went through.
    lines = []
    for item in items:
        try:
            product_id = int(item.get("product_id"))
            quantity = max(1, int(item.get("quantity", 1)))
        except (TypeError, ValueError):
            return jsonify({"error": "Invalid cart item."}), 400
        product = Product.query.get(product_id)
        if not product or not product.is_active:
            return jsonify({"error": f"A product in your cart is no longer available (#{product_id})."}), 400
        if product.seller_id == user["id"]:
            return jsonify({"error": f'You can\'t buy your own listing ("{product.name}").'}), 400
        variant, variant_error = _resolve_variant_for_purchase(product, item.get("variant_id"))
        if variant_error:
            return jsonify({"error": f'{product.name}: {variant_error}'}), 400
        available = variant.quantity_available if variant is not None else product.quantity_available
        if available and quantity > available:
            return jsonify({"error": f'Only {available} available for "{product.name}"' +
                                      (f' ({variant.label})' if variant is not None else '') + '.'}), 400
        if quantity < (product.min_order_quantity or 1):
            return jsonify({"error": f'Minimum order quantity for "{product.name}" is {product.min_order_quantity}.'}), 400
        lines.append((product, variant, quantity))

    # ENTERPRISE PROCUREMENT PACK — PO APPROVAL WORKFLOWS: a 'member'-
    # role buyer whose workspace has an approval policy configured must
    # reference an approved, matching purchase requisition to check out
    # at all. No-op for buyers with no workspace, an owner/admin role,
    # or a workspace with no policy configured — see
    # _procurement_gate_checkout for the exact conditions.
    _po_gate = _procurement_gate_checkout(
        user, [(p.id, q) for p, _, q in lines], data.get("requisition_id"))
    if _po_gate:
        return _po_gate
    # Requisition is consumed the moment its gate passes and this cart
    # commits to creating real orders below (every path past this point
    # creates at least a 'contacted'/'pending' ProductOrder even if
    # Stripe itself later fails) — a used requisition can't authorize a
    # second, different checkout attempt.
    _procurement_mark_requisition_converted(data.get("requisition_id"))

    # STAGE 362: STORE POLICY ACKNOWLEDGMENT — every distinct seller in
    # this cart who has a published policy the buyer hasn't yet
    # acknowledged blocks checkout until acknowledged, same 409 pattern
    # as the single-item Buy Now flow. policy_ack_seller_ids lets the
    # frontend acknowledge several sellers' policies in one round trip
    # after the buyer reviews each modal.
    acked_seller_ids = set(data.get("policy_ack_seller_ids") or [])
    seller_ids_in_cart = {p.seller_id for p, _, _ in lines}
    still_pending = []
    for sid in seller_ids_in_cart:
        pending_policy = _store_policy_requires_ack(sid, user["id"])
        if pending_policy:
            if sid in acked_seller_ids:
                _record_store_policy_ack(sid, user["id"], pending_policy.version, request.remote_addr)
            else:
                still_pending.append(pending_policy.to_dict())
    if still_pending:
        return jsonify({
            "error": "Please review each seller's store policy before paying.",
            "requires_policy_ack": True,
            "store_policies": still_pending,
        }), 409

    currencies = {(p.currency or "USD").upper() for p, _, _ in lines}
    if len(currencies) > 1:
        return jsonify({"error": f"Your cart has items in different currencies ({', '.join(sorted(currencies))}) "
                                  f"— Stripe can only check out one currency at a time. Split into separate carts."}), 400

    def _line_subtotal(product, variant, quantity):
        unit_price = variant.unit_price_for_quantity(product, quantity) if variant is not None else product.unit_price_for_quantity(quantity)
        return round(unit_price * quantity, 2)

    # STAGE 327: COUPON CODES — a coupon belongs to exactly one seller,
    # so it only ever discounts THIS seller's own line(s) in the cart;
    # any other sellers' items are untouched. If the discount is
    # smaller than that seller's full subtotal (multiple lines from
    # them), it's spread proportionally across those lines so each
    # order's own total_price stays honest, with the last line
    # absorbing any rounding remainder so the sum is always exact.
    coupon_code = (data.get("coupon_code") or "").strip() or None
    coupon, coupon_discount_total, discount_by_line = None, 0.0, {}
    if coupon_code:
        seller_ids_in_cart = {p.seller_id for p, _, _ in lines}
        candidates = Coupon.query.filter(
            Coupon.seller_id.in_(seller_ids_in_cart), Coupon.code == coupon_code.strip().upper()).all()
        if not candidates:
            return jsonify({"error": "That coupon code doesn't match any seller in your cart."}), 400
        target_seller_id = candidates[0].seller_id
        eligible_indices = [i for i, (p, _, _) in enumerate(lines) if p.seller_id == target_seller_id]
        eligible_subtotal = round(sum(_line_subtotal(*lines[i]) for i in eligible_indices), 2)
        coupon, coupon_discount_total, coupon_error = _resolve_coupon_for_checkout(
            coupon_code, target_seller_id, user["id"], eligible_subtotal)
        if coupon_error:
            return jsonify({"error": coupon_error}), 400
        if coupon_discount_total > 0 and eligible_subtotal > 0:
            remaining = coupon_discount_total
            for pos, i in enumerate(eligible_indices):
                if pos == len(eligible_indices) - 1:
                    share = remaining
                else:
                    line_subtotal = _line_subtotal(*lines[i])
                    share = round(coupon_discount_total * (line_subtotal / eligible_subtotal), 2)
                    remaining = round(remaining - share, 2)
                discount_by_line[i] = share

    # STAGE 328: STORE CREDIT — unlike a coupon, store credit is a
    # platform-wide balance (the buyer's, not any one seller's), so it's
    # eligible against every line in the cart, spread proportionally by
    # each line's post-coupon subtotal, capped by the buyer's actual
    # balance. Same last-line-absorbs-the-remainder rounding approach as
    # the coupon spread above.
    credit_by_line = {}
    store_credit_total = 0.0
    if data.get("use_store_credit"):
        credit_account = _get_or_create_store_credit_account(user["id"])
        line_remaining = {i: round(_line_subtotal(*lines[i]) - discount_by_line.get(i, 0.0), 2) for i in range(len(lines))}
        eligible_total = round(sum(line_remaining.values()), 2)
        store_credit_total = round(min(max(credit_account.balance, 0.0), max(eligible_total, 0.0)), 2)
        if store_credit_total > 0 and eligible_total > 0:
            remaining = store_credit_total
            nonzero_indices = [i for i in range(len(lines)) if line_remaining[i] > 0]
            for pos, i in enumerate(nonzero_indices):
                if pos == len(nonzero_indices) - 1:
                    share = remaining
                else:
                    share = round(store_credit_total * (line_remaining[i] / eligible_total), 2)
                    remaining = round(remaining - share, 2)
                credit_by_line[i] = share

    orders = []
    line_items = []
    for i, (product, variant, quantity) in enumerate(lines):
        subtotal = _line_subtotal(product, variant, quantity)
        discount = discount_by_line.get(i, 0.0)
        credit = credit_by_line.get(i, 0.0)
        order = ProductOrder(
            product_id=product.id, buyer_id=user["id"], seller_id=product.seller_id,
            quantity=quantity, total_price=round(subtotal - discount, 2), currency=product.currency,
            status="pending",
            variant_id=(variant.id if variant is not None else None),
            variant_label=(variant.label if variant is not None else None),
            coupon_code=(coupon_code if discount > 0 else None),
            discount_amount=(discount if discount > 0 else None),
            store_credit_applied=(credit if credit > 0 else None),
        )
        db.session.add(order)
        orders.append((order, product, variant, quantity, discount, credit))
    db.session.commit()  # flush to get order.id for every line before building the session

    if coupon is not None:
        _record_coupon_redemption(coupon, user["id"], coupon_discount_total)
    if store_credit_total > 0:
        order_ids_for_credit = ",".join(str(o.id) for o, _, _, _, _, _ in orders)
        _spend_store_credit(user["id"], store_credit_total, "order_payment", reference=f"cart_{order_ids_for_credit}")
    db.session.commit()

    if not STRIPE_SECRET_KEY:
        for order, product, variant, quantity, discount, credit in orders:
            # Fully covered by coupon + store credit already — genuinely
            # paid, not just "contacted" (matches the single Buy Now
            # zero-total-charge branch in _create_product_order_checkout).
            if round(order.total_price - credit, 2) <= 0.005:
                order.status = "paid"
                order.paid_at = datetime.utcnow()
            else:
                order.status = "contacted"
        db.session.commit()
        return jsonify({"ok": True, "orders": [o.to_dict() for o, _, _, _, _, _ in orders], "checkout_url": None}), 201

    try:
        import stripe
        stripe.api_key = STRIPE_SECRET_KEY
        fully_credited_orders = []
        for order, product, variant, quantity, discount, credit in orders:
            unit_price = variant.unit_price_for_quantity(product, quantity) if variant is not None else product.unit_price_for_quantity(quantity)
            line_total_after_everything = round(_line_subtotal(product, variant, quantity) - discount - credit, 2)
            if line_total_after_everything <= 0.005:
                # Store credit (± coupon) covered this line entirely —
                # nothing for Stripe to charge on it. Mark it paid now
                # and leave it out of the Checkout Session's line items.
                order.status = "paid"
                order.paid_at = datetime.utcnow()
                fully_credited_orders.append(order)
                continue
            total_amount = int(round(line_total_after_everything * 100))
            # A discounted/credited line collapses to one quantity-1 item
            # priced at the exact remaining total (same reasoning as the
            # single Buy Now path) — avoids rounding drift from splitting
            # a discount across a per-unit price.
            if discount > 0 or credit > 0:
                label_bits = []
                if discount > 0:
                    label_bits.append(f"coupon {order.coupon_code} applied")
                if credit > 0:
                    label_bits.append(f"{product.currency} {credit:.2f} store credit applied")
                line_items.append({
                    "price_data": {
                        "currency": (product.currency or "usd").lower(),
                        "product_data": {"name": product.name + (f" ({variant.label})" if variant is not None else "") +
                                                  f" × {quantity} ({', '.join(label_bits)})"},
                        "unit_amount": total_amount,
                    },
                    "quantity": 1,
                })
            else:
                unit_amount = int(round(unit_price * 100))
                total_amount = unit_amount * quantity
                line_items.append({
                    "price_data": {
                        "currency": (product.currency or "usd").lower(),
                        "product_data": {"name": product.name + (f" ({variant.label})" if variant is not None else "")},
                        "unit_amount": unit_amount,
                    },
                    "quantity": quantity,
                })
            seller_account = UserAccount.query.get(product.seller_id)
            if seller_account and seller_account.stripe_connect_account_id and seller_account.stripe_connect_payouts_enabled:
                # STAGE 388: subsidized micro-sellers get a reduced
                # effective fee here instead of the flat platform rate.
                fee_amount = max(0, (total_amount * _effective_platform_fee_bps(product.seller_id)) // 10000)
                order.platform_fee = round(fee_amount / 100, 2)

        # Every line was fully covered by coupon + store credit — skip
        # Stripe entirely, same as the zero-line-items no-Stripe branch.
        if not line_items:
            db.session.commit()
            return jsonify({"ok": True, "orders": [o.to_dict() for o, _, _, _, _, _ in orders], "checkout_url": None}), 201

        order_ids_csv = ",".join(str(o.id) for o, _, _, _, _, _ in orders)
        session = stripe.checkout.Session.create(
            payment_method_types=["card"],
            line_items=line_items,
            mode="payment",
            success_url=APP_BASE_URL + "/payment-success?session_id={CHECKOUT_SESSION_ID}",
            cancel_url=APP_BASE_URL + "/?order=cancelled",
            metadata={"order_ids": order_ids_csv, "kind": "marketplace_cart"},
            payment_intent_data={"transfer_group": f"cart_{order_ids_csv}"},
            shipping_address_collection={"allowed_countries": SHIPPING_ALLOWED_COUNTRIES},
        )
        # Fully-credited lines never touch Stripe, so they don't get a
        # stripe_session_id — only the lines actually in this session do.
        for order, product, variant, quantity, discount, credit in orders:
            if order not in fully_credited_orders:
                order.stripe_session_id = session.id
                # STAGE 526: record the REAL transfer_group this order's
                # charge was created under (shared across every seller in
                # this cart) so its eventual payout Transfer references
                # the actual charge instead of a mismatched "order_<id>".
                order.checkout_transfer_group = f"cart_{order_ids_csv}"
        db.session.commit()
        return jsonify({"ok": True, "orders": [o.to_dict() for o, _, _, _, _, _ in orders], "checkout_url": session.url}), 201
    except Exception as e:
        logging.error(f"[CART CHECKOUT] Stripe checkout failed: {e}")
        for order, _, _, _, _, _ in orders:
            if order.status != "paid":
                order.status = "contacted"
        db.session.commit()
        return jsonify({"ok": True, "orders": [o.to_dict() for o, _, _, _, _, _ in orders], "checkout_url": None}), 201


@app.route("/api/products/orders/mine", methods=["GET"])
def product_orders_mine():
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    _auto_release_due_product_orders(user["id"])
    role = (request.args.get("role") or "buyer").strip()
    if role == "seller":
        rows = (ProductOrder.query.filter_by(seller_id=user["id"])
                .order_by(ProductOrder.created_at.desc()).limit(200).all())
    else:
        rows = (ProductOrder.query.filter_by(buyer_id=user["id"])
                .order_by(ProductOrder.created_at.desc()).limit(200).all())
    return jsonify({"orders": [r.to_dict() for r in rows]}), 200


# ════════════════════════════════════════════════════════════
# STAGE 303: STRIPE CONNECT PAYOUTS + WHATSAPP GATEWAY WIRING
# FOR THE PRODUCT MARKETPLACE
#
# Two separate follow-ups to Stage 302, both requested together:
#
# 1) Real per-seller payouts. Every seller gets their own Stripe
#    Express account (stripe.Account, type="express") via a one-click
#    onboarding link (stripe.AccountLink). Once Stripe reports the
#    account payouts_enabled, product_buy() above switches that
#    seller's checkouts from "settles into the platform account" to a
#    destination charge: the full sale amount is captured on the
#    platform's Checkout Session, but Stripe automatically transfers
#    it — minus a configurable platform fee — straight to the
#    seller's own account, same day, no manual payout step. Sellers
#    who never connect still get a working Buy Now button; nothing
#    breaks, it just settles the old way until they do.
#
# 2) WhatsApp gateway integration. This platform already has a full
#    WhatsApp Cloud API gateway (Stage 11: send_whatsapp_cloud_message,
#    add_whatsapp_catalog_product, send_whatsapp_catalog_product). The
#    Product Marketplace didn't use any of it. Now it does:
#      • order-paid / order-sold pings land on whichever WhatsApp
#        number each side has set for marketplace notifications
#        (UserAccount.whatsapp_number — separate from any WhatsApp
#        Cloud BYOK app credentials, which are about SENDING, not
#        where a person wants to be notified).
#      • a seller can push any listing into their own WhatsApp
#        Business Catalog with one click, so it's then also buyable
#        by anyone who messages their WhatsApp number directly — the
#        marketplace listing and the WhatsApp catalog entry are two
#        surfaces on the same product.
# ════════════════════════════════════════════════════════════

# Platform's cut of a Stripe Connect destination charge, in basis
# points (500 = 5%). Configurable via env without a code change.
MARKETPLACE_PLATFORM_FEE_BPS = int(os.environ.get("MARKETPLACE_PLATFORM_FEE_BPS", "500"))

# STAGE 310: Stripe Checkout requires an explicit country allowlist for
# shipping_address_collection (no wildcard) — Southern/East/West Africa
# (this platform's primary market) plus the major international trade
# partners a seller here is likely to ship to or receive orders from.
SHIPPING_ALLOWED_COUNTRIES = [
    "ZW", "ZA", "ZM", "BW", "MZ", "MW", "NA", "SZ", "LS",
    "KE", "TZ", "UG", "RW", "ET", "GH", "NG", "CI", "SN", "EG", "MA",
    "US", "GB", "CA", "AU", "DE", "FR", "NL", "AE", "CN", "IN",
]


def _stripe_marketplace_ready():
    return bool(STRIPE_AVAILABLE and STRIPE_SECRET_KEY)


# ════════════════════════════════════════════════════════════
# STAGE 309: SELLER STOREFRONT PAGE
# A branded, public, no-login mini-shop per seller at /store/<slug> —
# reuses BusinessBranding (Stage 154's white-labeling) for the look and
# Product/DealReview for the content, so there's no new branding system
# to build or keep in sync. Buying still requires an account (Trade
# Assurance needs someone to hold accountable), so product links here
# send the visitor into the main app to complete checkout after they
# sign in — this page's job is discovery, not a second checkout flow.
# ════════════════════════════════════════════════════════════

def _storefront_slugify(name, owner_user_id):
    base = re.sub(r"[^a-z0-9]+", "-", (name or "").lower()).strip("-") or f"shop-{owner_user_id}"
    slug = base
    n = 1
    while BusinessBranding.query.filter(BusinessBranding.storefront_slug == slug,
                                         BusinessBranding.owner_user_id != owner_user_id).first():
        n += 1
        slug = f"{base}-{n}"
    return slug


def _get_or_create_storefront_link(user_id):
    branding = BusinessBranding.query.filter_by(owner_user_id=user_id).first()
    if not branding:
        branding = BusinessBranding(owner_user_id=user_id)
        db.session.add(branding)
    if not branding.storefront_slug:
        user = UserAccount.query.get(user_id)
        name = branding.display_name or (user.name if user else None) or f"shop-{user_id}"
        branding.storefront_slug = _storefront_slugify(name, user_id)
        db.session.commit()
    return branding


@app.route("/api/marketplace/storefront/link", methods=["GET"])
def marketplace_storefront_link():
    """Returns (creating if needed) the current seller's shareable
    storefront URL. Editing the look itself still goes through the
    existing /api/branding/update — this only owns the slug/link."""
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    branding = _get_or_create_storefront_link(user["id"])
    return jsonify({"ok": True, "branding": branding.to_dict()}), 200


@app.route("/store/<slug>", methods=["GET"])
def seller_storefront_page(slug):
    """Public storefront — no login required, same spirit as the
    existing /feedback/<token> public page. Accepts either a slug or a
    raw numeric seller id (for a seller who hasn't been given a
    prettier link yet, or an old copy-pasted numeric link)."""
    branding = BusinessBranding.query.filter_by(storefront_slug=slug).first()
    seller = None
    if branding:
        seller = UserAccount.query.get(branding.owner_user_id)
    elif slug.isdigit():
        seller = UserAccount.query.get(int(slug))
        if seller:
            branding = BusinessBranding.query.filter_by(owner_user_id=seller.id).first()
    if not seller:
        return render_template_string("""
        <!DOCTYPE html><html><head><meta charset="UTF-8"/>
        <meta name="viewport" content="width=device-width,initial-scale=1"/>
        <title>Shop not found</title>
        <style>body{font-family:'Segoe UI',sans-serif;background:#0f172a;color:#fff;
          min-height:100vh;display:flex;align-items:center;justify-content:center;text-align:center;}</style>
        </head><body><div><h1>Shop not found</h1><p style="color:#94a3b8;">This storefront link isn't valid.</p></div></body></html>
        """), 404

    display_name = (branding.display_name if branding else None) or seller.name or "Shop"
    logo_url = branding.logo_url if branding else None
    primary = (branding.primary_color if branding else None) or "#ea580c"
    accent = (branding.accent_color if branding else None) or "#1e293b"
    products = (Product.query.filter_by(seller_id=seller.id, is_active=True)
                .order_by(Product.created_at.desc()).limit(60).all())
    stats = get_user_review_stats(seller.id)

    # Real, written reviews — only ones with actual comment text, since a
    # bare star rating with no words adds nothing a reader can't already
    # get from the aggregate score above. Newest first, capped for page
    # weight, product name attached where the review was for a specific
    # listing (STAGE 306 product_id) rather than the seller in general.
    review_rows = (DealReview.query.filter_by(reviewee_id=seller.id)
                   .filter(DealReview.comment.isnot(None), DealReview.comment != "")
                   .order_by(DealReview.created_at.desc()).limit(20).all())
    reviewed_product_ids = {r.product_id for r in review_rows if r.product_id}
    products_by_id = {p.id: p for p in Product.query.filter(Product.id.in_(reviewed_product_ids)).all()} if reviewed_product_ids else {}
    reviews_html = ""
    for r in review_rows:
        reviewer = UserAccount.query.get(r.reviewer_id)
        reviewer_name = (reviewer.name if reviewer else "A Connect It member") or "A Connect It member"
        stars = "★" * max(0, min(5, r.rating)) + "☆" * max(0, 5 - max(0, min(5, r.rating)))
        product_tag = ""
        p = products_by_id.get(r.product_id) if r.product_id else None
        if p:
            product_tag = f'<div style="font-size:0.7rem;color:#94a3b8;margin-top:2px;">on {escape(p.name)}</div>'
        reviews_html += f"""
        <div style="background:#fff;border-radius:10px;padding:14px;box-shadow:0 1px 4px rgba(0,0,0,0.06);">
          <div style="font-size:0.8rem;color:#f59e0b;letter-spacing:1px;">{stars}</div>
          <div style="font-size:0.84rem;color:#334155;margin-top:6px;line-height:1.5;">{escape(r.comment)}</div>
          <div style="font-size:0.74rem;color:#64748b;margin-top:8px;font-weight:600;">{escape(reviewer_name)}</div>
          {product_tag}
        </div>"""

    # Real click-to-WhatsApp, only shown when the seller has actually set
    # whatsapp_number (the field they use specifically for marketplace
    # contact — see /api/marketplace/whatsapp-number) — never guessed from
    # an unrelated phone field, so this button is never wrong.
    whatsapp_btn_html = ""
    if seller.whatsapp_number:
        wa_digits = seller.whatsapp_number.lstrip("+")
        wa_text = quote(f"Hi {display_name}, I found your shop on {APP_BASE_URL.replace('https://', '').replace('http://', '')} and I'm interested in your products.")
        whatsapp_btn_html = (
            f'<a href="https://wa.me/{escape(wa_digits)}?text={wa_text}" target="_blank" '
            f'style="display:inline-flex;align-items:center;gap:8px;margin-top:12px;background:#25d366;'
            f'color:#fff;padding:10px 18px;border-radius:24px;text-decoration:none;font-weight:700;font-size:0.86rem;">'
            f' Message on WhatsApp</a>'
        )

    cards_html = ""
    for p in products:
        review_rows = DealReview.query.filter_by(product_id=p.id).all()
        avg = round(sum(r.rating for r in review_rows) / len(review_rows), 2) if review_rows else None
        images = []
        if p.image_urls:
            try:
                images = json.loads(p.image_urls)
            except Exception:
                images = []
        img_tag = (f'<img src="{escape(images[0])}" style="width:100%;height:150px;object-fit:cover;border-radius:10px 10px 0 0;">'
                   if images else '<div style="width:100%;height:150px;background:#f1f5f9;border-radius:10px 10px 0 0;"></div>')
        tiers = p.price_tiers_list()
        tiers_html = ""
        if tiers:
            tiers_html = ('<div style="font-size:0.72rem;color:#0e7490;margin-top:4px;">Bulk: ' +
                           ", ".join(f'{t.get("min_qty")}+ @ {p.currency} {t.get("price")}' for t in tiers) + '</div>')
        cards_html += f"""
        <a href="{escape(APP_BASE_URL)}/?product={p.id}" style="text-decoration:none;color:inherit;">
        <div style="background:#fff;border-radius:10px;overflow:hidden;box-shadow:0 1px 4px rgba(0,0,0,0.08);">
          {img_tag}
          <div style="padding:10px;">
            <div style="font-weight:700;font-size:0.88rem;color:#1e293b;">{escape(p.name)}</div>
            <div style="font-weight:800;font-size:0.95rem;color:{escape(primary)};margin-top:2px;">{escape(p.currency)} {p.price:,.2f}</div>
            {f'<div style="font-size:0.76rem;color:#f59e0b;margin-top:2px;">★ {avg} ({len(review_rows)})</div>' if avg is not None else ''}
            {tiers_html}
          </div>
        </div></a>"""

    html = f"""
    <!DOCTYPE html><html><head><meta charset="UTF-8"/>
    <meta name="viewport" content="width=device-width,initial-scale=1"/>
    <title>{escape(display_name)} — Shop</title>
    <style>
      *{{box-sizing:border-box;margin:0;padding:0;}}
      body{{font-family:'Segoe UI',sans-serif;background:#f8fafc;min-height:100vh;}}
      header{{background:{escape(accent)};color:#fff;padding:28px 20px;text-align:center;}}
      header img{{height:56px;border-radius:10px;margin-bottom:10px;}}
      header h1{{font-size:1.4rem;}}
      header .stats{{font-size:0.82rem;opacity:0.85;margin-top:6px;}}
      .grid{{max-width:960px;margin:20px auto;padding:0 16px;display:grid;grid-template-columns:repeat(auto-fill,minmax(160px,1fr));gap:14px;}}
      .reviews{{max-width:960px;margin:8px auto 20px;padding:0 16px;}}
      .reviews h2{{font-size:1.05rem;color:#1e293b;margin-bottom:12px;}}
      .reviews-grid{{display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:12px;}}
      .empty{{text-align:center;color:#94a3b8;padding:60px 20px;}}
      footer{{text-align:center;color:#94a3b8;font-size:0.76rem;padding:24px;}}
      footer a{{color:{escape(primary)};}}
    </style></head>
    <body>
      <header>
        {f'<img src="{escape(logo_url)}"/>' if logo_url else ''}
        <h1>{escape(display_name)}</h1>
        <div class="stats">{f"★ {stats['average_rating']} Trust Score ({stats['review_count']} reviews)" if stats['average_rating'] is not None else "New seller — no reviews yet"}</div>
        {whatsapp_btn_html}
      </header>
      <div class="grid">
        {cards_html if cards_html else '<div class="empty" style="grid-column:1/-1;">No products listed yet — check back soon.</div>'}
      </div>
      {f'<div class="reviews"><h2>What buyers are saying</h2><div class="reviews-grid">{reviews_html}</div></div>' if reviews_html else ''}
      <div class="follow" style="max-width:960px;margin:8px auto 24px;padding:0 16px;">
        <div style="background:#fff;border-radius:10px;padding:16px;box-shadow:0 1px 4px rgba(0,0,0,0.06);">
          <div id="raiw-follow-form">
            <div style="font-weight:700;font-size:0.94rem;color:#1e293b;">Get notified of new stock & offers</div>
            <div style="font-size:0.78rem;color:#64748b;margin:4px 0 10px;">Leave your WhatsApp number and {escape(display_name)} can message you when they restock or list something new. No account needed.</div>
            <input id="raiw-follow-name" placeholder="Your name" style="width:100%;padding:9px 10px;border:1px solid #e2e8f0;border-radius:8px;font-size:0.84rem;margin-bottom:8px;"/>
            <input id="raiw-follow-phone" placeholder="Phone, e.g. +263771234567" style="width:100%;padding:9px 10px;border:1px solid #e2e8f0;border-radius:8px;font-size:0.84rem;margin-bottom:8px;"/>
            <label style="display:flex;align-items:flex-start;gap:6px;font-size:0.74rem;color:#64748b;margin-bottom:10px;">
              <input type="checkbox" id="raiw-follow-consent" style="margin-top:2px;"/>
              <span>I agree to receive WhatsApp messages from {escape(display_name)} about their products. I can stop anytime by telling them.</span>
            </label>
            <button id="raiw-follow-submit" style="width:100%;background:{escape(primary)};color:#fff;border:none;border-radius:8px;padding:10px;font-weight:700;font-size:0.84rem;cursor:pointer;">Follow this shop</button>
            <div id="raiw-follow-msg" style="font-size:0.76rem;margin-top:8px;"></div>
          </div>
        </div>
      </div>
      <script>
      (function(){{
        var btn = document.getElementById('raiw-follow-submit');
        if (!btn) return;
        btn.addEventListener('click', function(){{
          var name = document.getElementById('raiw-follow-name').value.trim();
          var phone = document.getElementById('raiw-follow-phone').value.trim();
          var consent = document.getElementById('raiw-follow-consent').checked;
          var msg = document.getElementById('raiw-follow-msg');
          if (!name || !phone) {{ msg.style.color='#dc2626'; msg.textContent='Please enter your name and phone number.'; return; }}
          if (!consent) {{ msg.style.color='#dc2626'; msg.textContent='Please agree to receive WhatsApp messages first.'; return; }}
          btn.disabled = true; btn.textContent = 'Following…';
          fetch('/api/public/storefront-follow', {{
            method:'POST', headers:{{'Content-Type':'application/json'}},
            body: JSON.stringify({{
              slug: {json.dumps(slug)}, name: name, phone: phone, consent: true,
              consent_text: 'I agree to receive WhatsApp messages from ' + {json.dumps(display_name)} + ' about their products.'
            }})
          }}).then(function(r){{ return r.json().then(function(d){{ return {{status:r.status, body:d}}; }}); }})
            .then(function(res){{
              if (res.status < 300 && res.body.ok) {{
                document.getElementById('raiw-follow-form').innerHTML =
                  '<div style="font-weight:700;color:#16a34a;font-size:0.86rem;">✓ You\\'re following {escape(display_name)} — they can now message you on WhatsApp about new stock.</div>';
              }} else {{
                btn.disabled = false; btn.textContent = 'Follow this shop';
                msg.style.color='#dc2626'; msg.textContent = (res.body && res.body.error) || 'Could not save right now. Please try again.';
              }}
            }}).catch(function(){{
              btn.disabled = false; btn.textContent = 'Follow this shop';
              msg.style.color='#dc2626'; msg.textContent = 'Network error — please try again.';
            }});
        }});
      }})();
      </script>
      <footer>Powered by <a href="{escape(APP_BASE_URL)}/">the Marketplace</a> — sign in there to buy, with Trade Assurance protecting every order.</footer>
    </body></html>
    """
    return render_template_string(html)


# ════════════════════════════════════════════════════════════
# STORE FOLLOW: lets a public /store/<slug> visitor opt in to a
# seller's WhatsApp audience with no account and no login — the
# storefront's own version of the WhatsApp opt-in widget (Stage
# above this one), but scoped to one seller's shop page instead of
# an externally embedded snippet, and landing directly in that
# seller's saved Contact Lists (not a separate table) so the exact
# same broadcast-to-list flow (/api/broadcast/template-send) they
# already use for restock/new-product announcements just works,
# with no new send pipeline to build or keep in sync.
# ════════════════════════════════════════════════════════════

STOREFRONT_FOLLOWERS_LIST_NAME = "Storefront Followers"


def _get_or_create_storefront_followers_list(seller_id):
    cl = ContactList.query.filter_by(user_id=seller_id, name=STOREFRONT_FOLLOWERS_LIST_NAME).first()
    if not cl:
        cl = ContactList(user_id=seller_id, name=STOREFRONT_FOLLOWERS_LIST_NAME,
                          description="Buyers who opted in from your public storefront page.")
        db.session.add(cl)
        db.session.commit()
    return cl


@app.route("/api/public/storefront-follow", methods=["POST", "OPTIONS"])
@csrf.exempt
def storefront_follow_submit():
    """Public, no-login endpoint the /store/<slug> follow form posts to.
    Resolved to a seller the same way seller_storefront_page resolves
    slug -> seller, so a follow always lands on the shop the visitor was
    actually looking at."""
    if request.method == "OPTIONS":
        return _widget_cors(jsonify({"ok": True}))

    data = request.get_json(silent=True) or {}
    slug = (data.get("slug") or "").strip()
    branding = BusinessBranding.query.filter_by(storefront_slug=slug).first()
    seller = UserAccount.query.get(branding.owner_user_id) if branding else None
    if not seller and slug.isdigit():
        seller = UserAccount.query.get(int(slug))
    if not seller:
        return _widget_cors(jsonify({"error": "Unknown storefront."})), 404

    if _rate_limited(f"storefront_follow:slug:{slug}:ip:{_client_ip()}", max_attempts=10, window_seconds=60):
        return _widget_cors(jsonify({"error": "Too many attempts. Please try again shortly."})), 429

    name = (data.get("name") or "").strip()
    phone = sanitize_phone(data.get("phone") or "")
    consent = bool(data.get("consent"))
    consent_text = (data.get("consent_text") or "").strip()

    if not name or not phone:
        return _widget_cors(jsonify({"error": "Name and phone are required."})), 400
    if not _WA_OPTIN_PHONE_RE.match(phone):
        return _widget_cors(jsonify({"error": "Phone must be in international format, e.g. +263771234567."})), 400
    if not consent or not consent_text:
        return _widget_cors(jsonify({"error": "Consent to receive WhatsApp messages is required."})), 400

    try:
        contact = CrmContact.query.filter_by(user_id=seller.id, phone=phone).first()
        if not contact:
            contact = CrmContact(user_id=seller.id, name=name[:160], phone=phone[:32], stage="lead",
                                  notes=f"Followed via storefront page. Consent: {consent_text[:300]}")
            db.session.add(contact)
            db.session.flush()
        cl = _get_or_create_storefront_followers_list(seller.id)
        already = ContactListMember.query.filter_by(list_id=cl.id, crm_contact_id=contact.id).first()
        is_new_follower = already is None
        if is_new_follower:
            db.session.add(ContactListMember(list_id=cl.id, crm_contact_id=contact.id))
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        logging.error(f"[STOREFRONT FOLLOW ERROR] slug={slug}: {e}")
        return _widget_cors(jsonify({"error": "Could not save right now. Please try again."})), 503

    # Reuses the existing notification pipeline (same bell the rest of
    # the app already writes to) instead of a bespoke alert — only on
    # an actual new follower, never on a repeat submission from someone
    # already on the list.
    if is_new_follower:
        try:
            notify_user(seller.id, "storefront_follow", "New storefront follower",
                        f"{name} started following your shop and can now get WhatsApp updates.")
        except Exception as e:
            logging.warning(f"[STOREFRONT FOLLOW NOTIFY] seller={seller.id}: {e}")

    return _widget_cors(jsonify({"ok": True})), 201


@app.route("/api/marketplace/connect/onboard", methods=["POST"])
@csrf.exempt
def marketplace_connect_onboard():
    """Creates (if needed) the seller's Stripe Express account and
    returns a fresh one-click onboarding link. Safe to call repeatedly —
    an existing account is reused, only the link is regenerated (Stripe
    account links expire after a few minutes)."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    if not _stripe_marketplace_ready():
        return jsonify({"error": "Stripe isn't configured on this platform yet."}), 503
    account = UserAccount.query.get(user["id"])
    try:
        import stripe
        stripe.api_key = STRIPE_SECRET_KEY
        if not account.stripe_connect_account_id:
            acct = stripe.Account.create(
                type="express",
                email=account.email,
                country=(account.country_code or "US")[:2].upper(),
                capabilities={
                    "card_payments": {"requested": True},
                    "transfers": {"requested": True},
                },
                business_type="individual",
                metadata={"user_id": str(account.id), "platform": "connectit_ai_marketplace"},
            )
            account.stripe_connect_account_id = acct.id
            db.session.commit()
        link = stripe.AccountLink.create(
            account=account.stripe_connect_account_id,
            refresh_url=APP_BASE_URL + "/?connect=refresh",
            return_url=APP_BASE_URL + "/?connect=done",
            type="account_onboarding",
        )
        return jsonify({"ok": True, "onboarding_url": link.url}), 200
    except Exception as e:
        logging.error(f"[CONNECT ONBOARD ERROR] user={user['id']}: {e}")
        return jsonify({"error": str(e)}), 400


@app.route("/api/marketplace/connect/status", methods=["GET"])
def marketplace_connect_status():
    """Live status for the Sell tab's payout banner. Re-checks with
    Stripe (cheap, cached locally after) rather than trusting a stale
    local flag, since onboarding happens on Stripe's own hosted pages
    where we don't otherwise get a synchronous callback."""
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    account = UserAccount.query.get(user["id"])
    if not account.stripe_connect_account_id:
        return jsonify({"ok": True, "connected": False, "charges_enabled": False,
                         "payouts_enabled": False,
                         "platform_fee_percent": MARKETPLACE_PLATFORM_FEE_BPS / 100}), 200
    if _stripe_marketplace_ready():
        try:
            import stripe
            stripe.api_key = STRIPE_SECRET_KEY
            acct = stripe.Account.retrieve(account.stripe_connect_account_id)
            account.stripe_connect_charges_enabled = bool(acct.get("charges_enabled"))
            account.stripe_connect_payouts_enabled = bool(acct.get("payouts_enabled"))
            db.session.commit()
        except Exception as e:
            logging.error(f"[CONNECT STATUS ERROR] user={user['id']}: {e}")
    return jsonify({
        "ok": True, "connected": True,
        "charges_enabled": account.stripe_connect_charges_enabled,
        "payouts_enabled": account.stripe_connect_payouts_enabled,
        "platform_fee_percent": MARKETPLACE_PLATFORM_FEE_BPS / 100,
    }), 200


@app.route("/api/marketplace/whatsapp-number", methods=["POST"])
@csrf.exempt
def marketplace_set_whatsapp_number():
    """Where THIS account wants marketplace order pings to land — separate
    from any WhatsApp Cloud BYOK app credentials, which control sending,
    not receiving."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    number = sanitize_phone(data.get("whatsapp_number", ""))
    account = UserAccount.query.get(user["id"])
    account.whatsapp_number = number or None
    db.session.commit()
    return jsonify({"ok": True, "whatsapp_number": account.whatsapp_number}), 200


@app.route("/api/products/<int:product_id>/whatsapp-sync", methods=["POST"])
@csrf.exempt
def product_whatsapp_sync(product_id):
    """Pushes one listing into the seller's own WhatsApp Business
    Catalog (Stage 11 gateway) so it's also buyable by anyone who
    messages their WhatsApp number directly. Requires the seller to
    already have a Meta Catalog ID configured under WhatsApp Cloud
    settings — reuses add_whatsapp_catalog_product() as-is."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    product = Product.query.get(product_id)
    if not product:
        return jsonify({"error": "Product not found."}), 404
    if product.seller_id != user["id"]:
        return jsonify({"error": "You can only sync your own listings."}), 403
    images = []
    if product.image_urls:
        try:
            images = json.loads(product.image_urls)
        except Exception:
            images = []
    result = add_whatsapp_catalog_product(
        user_id=user["id"], name=product.name,
        price_cents=int(round(product.price * 100)), currency=product.currency or "USD",
        retailer_id=f"prod-{product.id}",
        image_url=(images[0] if images else ""),
        url=f"{APP_BASE_URL}/?product={product.id}",
        description=(product.description or "")[:500],
    )
    return jsonify(result), (200 if result.get("ok") else 400)


# STAGE 314: FACEBOOK PAGE / INSTAGRAM AUTO-POST FOR NEW LISTINGS
# Note on scope: add_whatsapp_catalog_product() above already writes
# into the seller's Meta Commerce Catalog (POST .../{catalog_id}/products
# on the Graph API) — the same catalog object that also backs a
# Facebook/Instagram Shop when one's configured on the Page, so
# "sync to WhatsApp" already makes a listing shoppable there too. What
# it does NOT do is announce the listing to followers — that needs an
# actual feed/Reel-style post, which is what this endpoint adds, reusing
# post_to_facebook_page()/post_to_instagram() from Stage 13 as-is.
@app.route("/api/products/<int:product_id>/social-sync", methods=["POST"])
@csrf.exempt
def product_social_sync(product_id):
    """Body: platforms (optional list, default ["facebook","instagram"]).
    Posts a 'new listing' announcement to whichever of the seller's
    connected Page/Instagram they ask for — each platform's result is
    independent, so a Facebook success and an Instagram failure (e.g.
    no product image, which Instagram requires) don't block each other."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    product = Product.query.filter_by(id=product_id, seller_id=user["id"]).first()
    if not product:
        return jsonify({"error": "Product not found."}), 404
    data = request.get_json(silent=True) or {}
    platforms = data.get("platforms") or ["facebook", "instagram"]

    images = []
    if product.image_urls:
        try:
            images = json.loads(product.image_urls)
        except Exception:
            images = []
    image_url = images[0] if images else ""
    branding = BusinessBranding.query.filter_by(owner_user_id=user["id"]).first()
    link = (branding.storefront_slug and f"{APP_BASE_URL}/store/{branding.storefront_slug}") or f"{APP_BASE_URL}/?product={product.id}"
    caption = (f"🆕 New listing: {product.name} — {product.currency} {product.price:,.2f}. "
               f"{(product.description or '')[:200]} Shop now: {link}")

    results = {}
    if "facebook" in platforms:
        results["facebook"] = post_to_facebook_page(user["id"], caption, image_url)
    if "instagram" in platforms:
        if not image_url:
            results["instagram"] = {"ok": False, "error": "Instagram posts need at least one product image — add one to this listing first."}
        else:
            results["instagram"] = post_to_instagram(user["id"], image_url, caption)

    any_ok = any(r.get("ok") for r in results.values())
    return jsonify({"ok": any_ok, "results": results}), (200 if any_ok else 400)


# ════════════════════════════════════════════════════════════
# STAGE 313: EMAIL (GMAIL/SMTP) FOR PRODUCT ORDERS
# Reuses the same SMTP rail as verification/reset emails elsewhere in
# this file (SMTP_HOST defaults to smtp.gmail.com) rather than the
# per-user Gmail OAuth flow (_gmail_headers) — a receipt has to go out
# reliably regardless of whether that particular buyer or seller ever
# connected their own Gmail, so it can't depend on personal OAuth.
# Three gaps closed: (1) an automatic receipt on every paid order,
# (2) email as the fallback channel for a seller with no WhatsApp
# number on file, and (3) an on-demand weekly sales summary — there's
# no scheduler anywhere in this app (Trade Assurance's auto-release is
# lazy-checked for the same reason), so "weekly" here means a button
# the seller (or an external cron hitting the endpoint) can trigger,
# not a background job.
# ════════════════════════════════════════════════════════════

def _send_order_receipt_email(order, product_name):
    buyer = UserAccount.query.get(order.buyer_id)
    seller = UserAccount.query.get(order.seller_id)
    if not buyer or not buyer.email or not SMTP_USER or not SMTP_PASS:
        return False
    html_body = f"""
    <html><body style="font-family:'Segoe UI',sans-serif;background:#f4f4f4;margin:0;padding:20px;">
      <div style="max-width:480px;margin:0 auto;background:#fff;border-radius:10px;overflow:hidden;">
        <div style="background:linear-gradient(90deg,#1e3a8a,#2563eb);padding:20px;text-align:center;">
          <h1 style="color:#fff;margin:0;font-size:1.3rem;">Order Confirmed </h1>
        </div>
        <div style="padding:24px;color:#1e293b;line-height:1.7;font-size:0.9rem;">
          <p>Hi {escape(buyer.name or 'there')},</p>
          <p>Your order is confirmed and paid.</p>
          <table style="width:100%;border-collapse:collapse;margin:14px 0;">
            <tr><td style="padding:6px 0;color:#64748b;">Order</td><td style="padding:6px 0;text-align:right;">#{order.id}</td></tr>
            <tr><td style="padding:6px 0;color:#64748b;">Item</td><td style="padding:6px 0;text-align:right;">{escape(product_name)}</td></tr>
            <tr><td style="padding:6px 0;color:#64748b;">Quantity</td><td style="padding:6px 0;text-align:right;">{order.quantity}</td></tr>
            <tr><td style="padding:6px 0;color:#64748b;font-weight:700;">Total</td><td style="padding:6px 0;text-align:right;font-weight:700;">{escape(order.currency)} {order.total_price:,.2f}</td></tr>
            <tr><td style="padding:6px 0;color:#64748b;">Seller</td><td style="padding:6px 0;text-align:right;">{escape(seller.name if seller else 'N/A')}</td></tr>
          </table>
          {"<p>Your payment is held safely by Trade Assurance until you confirm you received your order — look for \"Mark as Received\" under My Purchases.</p>" if order.escrow_status == "holding" else ""}
        </div>
        <div style="background:#f8fafc;padding:14px;text-align:center;font-size:0.72rem;color:#9ca3af;">© 2026 Connect It</div>
      </div>
    </body></html>
    """
    try:
        msg = MIMEMultipart("alternative")
        msg["Subject"] = f"Order Confirmed — #{order.id}"
        msg["From"] = SMTP_FROM
        msg["To"] = buyer.email
        msg.attach(MIMEText(html_body, "html"))
        with smtplib.SMTP(SMTP_HOST, SMTP_PORT, timeout=15) as server:
            server.ehlo()
            server.starttls()
            server.login(SMTP_USER, SMTP_PASS)
            server.sendmail(SMTP_USER, buyer.email, msg.as_string())
        return True
    except Exception as e:
        logging.error(f"[ORDER RECEIPT EMAIL ERROR] order={order.id}: {e}")
        return False


def _send_seller_sale_email(order, product_name):
    """Fallback channel — only called when the seller has no WhatsApp
    number on file, so they still hear about the sale somehow."""
    seller = UserAccount.query.get(order.seller_id)
