# ════════════════════════════════════════════════════════════
# Security & Sovereign Trust roadmap, item 3: BLOCKCHAIN-VERIFIED
# AUDIT LOGS. Exactly the same real pattern as the ledger anchoring
# just above — this is not a second, different "blockchain" story,
# it's the same honest mechanism (hash chain + OpenTimestamps Bitcoin
# anchoring) applied to org.audit_logs instead of the seller
# transaction ledger. The hash-chain fields live directly on AuditLog
# (see its class + _audit() above); this section only adds the
# Merkle-root-over-the-chain + OpenTimestamps submission step, which
# an org admin triggers on demand for their own compliance/audit
# trail. Reuses OTS_CALENDAR_SERVERS defined above.
# ════════════════════════════════════════════════════════════

class AuditChainAnchor(db.Model):
    __tablename__ = "audit_chain_anchors"
    id                             = db.Column(db.Integer, primary_key=True)
    org_id                         = db.Column(db.Integer, db.ForeignKey("organizations.id"), nullable=False, index=True)
    merkle_root                    = db.Column(db.String(64), nullable=False)
    covers_through_sequence_index  = db.Column(db.Integer, nullable=False)
    entries_covered                = db.Column(db.Integer, nullable=False)
    calendar_server                = db.Column(db.String(200), nullable=True)
    ots_proof_b64                  = db.Column(db.Text, nullable=True)
    status                         = db.Column(db.String(16), nullable=False, default="pending", index=True)  # pending, submitted, failed
    error_message                  = db.Column(db.String(500), nullable=True)
    submitted_at                   = db.Column(db.DateTime, default=datetime.utcnow, index=True)

    def to_dict(self):
        return {
            "id": self.id, "org_id": self.org_id, "merkle_root": self.merkle_root,
            "covers_through_sequence_index": self.covers_through_sequence_index,
            "entries_covered": self.entries_covered,
            "calendar_server": self.calendar_server,
            "status": self.status, "error_message": self.error_message,
            "submitted_at": self.submitted_at.isoformat() if self.submitted_at else None,
            "has_proof": bool(self.ots_proof_b64),
        }


def _compute_org_audit_merkle_root(org_id):
    """Real binary Merkle tree over every chained AuditLog.entry_hash
    for this org, in sequence order — same batching rationale as the
    seller ledger: one Bitcoin commitment covers the whole chain to
    date, not one per log line."""
    entries = (AuditLog.query.filter_by(org_id=org_id)
               .filter(AuditLog.entry_hash.isnot(None))
               .order_by(AuditLog.sequence_index.asc()).all())
    if not entries:
        return None, 0, None
    level = [bytes.fromhex(e.entry_hash) for e in entries]
    while len(level) > 1:
        nxt = []
        for i in range(0, len(level), 2):
            left = level[i]
            right = level[i + 1] if i + 1 < len(level) else level[i]
            nxt.append(hashlib.sha256(left + right).digest())
        level = nxt
    return level[0].hex(), len(entries), entries[-1].sequence_index


def _anchor_org_audit_chain(org_id):
    """Submits the org's current audit-log Merkle root to a public
    OpenTimestamps calendar server. Same best-effort, graceful-
    degradation behavior as _anchor_seller_chain — degrades to
    status='failed' rather than raising if no calendar is reachable."""
    root_hex, entry_count, through_seq = _compute_org_audit_merkle_root(org_id)
    if not root_hex:
        return None, "No chained audit log entries for this org to anchor yet."
    anchor = AuditChainAnchor(
        org_id=org_id, merkle_root=root_hex,
        covers_through_sequence_index=through_seq, entries_covered=entry_count,
        status="pending",
    )
    digest_bytes = bytes.fromhex(root_hex)
    last_error = None
    for server in OTS_CALENDAR_SERVERS:
        try:
            resp = requests.post(
                f"{server}/digest", data=digest_bytes,
                headers={"Accept": "application/vnd.opentimestamps.v1",
                         "Content-Type": "application/x-www-form-urlencoded"},
                timeout=10,
            )
            if resp.status_code == 200 and resp.content:
                anchor.calendar_server = server
                anchor.ots_proof_b64 = base64.b64encode(resp.content).decode("ascii")
                anchor.status = "submitted"
                break
            last_error = f"{server} returned HTTP {resp.status_code}"
        except Exception as e:
            last_error = f"{server}: {e}"
    if anchor.status != "submitted":
        anchor.status = "failed"
        anchor.error_message = (last_error or "No OpenTimestamps calendar server was reachable.")[:500]
    db.session.add(anchor)
    db.session.commit()
    return anchor, None


