@app.route("/api/products/orders/<int:order_id>/mark-received", methods=["POST"])
@csrf.exempt
def product_order_mark_received(order_id):
    """Buyer confirms the order arrived as expected — releases the held
    payment to the seller right now instead of waiting for auto-release."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    order = ProductOrder.query.filter_by(id=order_id, buyer_id=user["id"]).first()
    if not order:
        return jsonify({"error": "Order not found."}), 404
    if order.escrow_status == "disputed":
        return jsonify({"error": "This order has an open dispute — it will be resolved by an admin."}), 400
    if order.escrow_status != "holding":
        return jsonify({"error": f"Nothing to release (status: {order.escrow_status or order.status})."}), 400
    ok, error = _release_product_order_escrow(order)
    if not ok:
        return jsonify({"error": error or "Could not release payment."}), 400
    _ensure_deal_confirmation("product_order", order.id, order.buyer_id, order.seller_id)
    deal = DealConfirmation.query.filter_by(deal_type="product_order", ref_id=order.id).first()
    if deal:
        deal.party_a_confirmed = True
        deal.party_b_confirmed = True
        deal.status = "confirmed"
        deal.confirmed_at = deal.confirmed_at or datetime.utcnow()
        db.session.commit()
    return jsonify({"ok": True, "order": order.to_dict()}), 200


@app.route("/api/products/orders/<int:order_id>/dispute", methods=["POST"])
@csrf.exempt
def product_order_dispute(order_id):
    """Buyer flags a problem — freezes the hold (blocks both manual
    release and auto-release) until an admin resolves it."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    order = ProductOrder.query.filter_by(id=order_id, buyer_id=user["id"]).first()
    if not order:
        return jsonify({"error": "Order not found."}), 404
    if order.escrow_status != "holding":
        return jsonify({"error": f"Can't open a dispute on this order (status: {order.escrow_status or order.status})."}), 400
    data = request.get_json(silent=True) or {}
    reason = (data.get("reason") or "").strip()[:500]
    if not reason:
        return jsonify({"error": "Please describe what went wrong."}), 400
    order.escrow_status = "disputed"
    order.dispute_reason = reason
    db.session.commit()
    _ensure_deal_confirmation("product_order", order.id, order.buyer_id, order.seller_id)
    deal = DealConfirmation.query.filter_by(deal_type="product_order", ref_id=order.id).first()
    if deal:
        deal.status = "disputed"
        deal.dispute_reason = reason
        db.session.commit()
    seller = UserAccount.query.get(order.seller_id)
    if seller and seller.whatsapp_number:
        try:
            send_whatsapp_cloud_message(
                seller.id, seller.whatsapp_number,
                f"⚠️ A buyer opened a Trade Assurance dispute on order #{order.id}: \"{reason}\". "
                f"An admin will review it — payment stays held until then.")
        except Exception as e:
            logging.error(f"[TRADE ASSURANCE DISPUTE WA NOTIFY ERROR] order={order.id}: {e}")
    return jsonify({"ok": True, "order": order.to_dict()}), 200


@app.route("/api/products/orders/<int:order_id>/dispute/resolve", methods=["POST"])
@csrf.exempt
def product_order_dispute_resolve(order_id):
    """Admin-only. Resolves an open dispute either by releasing the held
    funds to the seller or refunding the buyer via Stripe."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    admin_account = UserAccount.query.get(user["id"])
    is_admin = bool(admin_account) and (
        admin_account.is_admin or (admin_account.email or "").strip().lower() in ADMIN_EMAILS
    )
    if not is_admin:
        return jsonify({"error": "Admin access required."}), 403
    order = ProductOrder.query.get(order_id)
    if not order:
        return jsonify({"error": "Order not found."}), 404
    if order.escrow_status != "disputed":
        return jsonify({"error": "This order doesn't have an open dispute."}), 400
    data = request.get_json(silent=True) or {}
    resolution = (data.get("resolution") or "").strip().lower()
    if resolution not in ("release", "refund"):
        return jsonify({"error": "resolution must be release or refund."}), 400

    if resolution == "release":
        order.escrow_status = "holding"  # briefly, so _release_product_order_escrow's guard passes
        db.session.commit()
        ok, error = _release_product_order_escrow(order)
        if not ok:
            order.escrow_status = "disputed"
            db.session.commit()
            return jsonify({"error": error or "Could not release payment."}), 400
    else:
        if not order.stripe_payment_intent_id:
            return jsonify({"error": "No original payment on record to refund."}), 400
        # STAGE 328: order.total_price is the order's subtotal after any
        # coupon, but NOT after store credit — store_credit_applied never
        # touched Stripe in the first place (see
        # _create_product_order_checkout / cart_checkout), so only the
        # remainder actually charged to the card gets refunded via
        # Stripe; the store-credit portion goes back to the buyer's
        # StoreCreditAccount instead of a card refund.
        card_charged_amount = round(order.total_price - (order.store_credit_applied or 0.0), 2)
        try:
            if card_charged_amount > 0.005:
                import stripe
                stripe.api_key = STRIPE_SECRET_KEY
                # Partial refund scoped to this order's own amount — a cart
                # checkout can bundle several orders under one PaymentIntent
                # (see marketplace_cart in the webhook), so an unscoped
                # refund would wrongly refund every item in that cart.
                stripe.Refund.create(
                    payment_intent=order.stripe_payment_intent_id,
                    amount=int(round(card_charged_amount * 100)),
                )
        except Exception as e:
            logging.error(f"[TRADE ASSURANCE REFUND ERROR] order={order.id}: {e}")
            return jsonify({"error": str(e)}), 400
        if order.store_credit_applied:
            _grant_store_credit(order.buyer_id, order.store_credit_applied, "order_refund", reference=f"order_{order.id}")
        order.escrow_status = "refunded"
        order.refunded_at = datetime.utcnow()
        db.session.commit()
        buyer = UserAccount.query.get(order.buyer_id)
        if buyer and buyer.whatsapp_number:
            try:
                send_whatsapp_cloud_message(
                    buyer.id, buyer.whatsapp_number,
                    f"↩️ Your order #{order.id} was refunded following a Trade Assurance dispute review.")
            except Exception as e:
                logging.error(f"[TRADE ASSURANCE REFUND WA NOTIFY ERROR] order={order.id}: {e}")

    deal = DealConfirmation.query.filter_by(deal_type="product_order", ref_id=order.id).first()
    if deal:
        if resolution == "release":
            deal.party_a_confirmed = True
            deal.party_b_confirmed = True
            deal.status = "confirmed"
            deal.confirmed_at = deal.confirmed_at or datetime.utcnow()
        else:
            deal.status = "refunded"
        db.session.commit()
    return jsonify({"ok": True, "order": order.to_dict()}), 200


# STAGE 318: HELPDESK TICKET ESCALATION (ZENDESK / FRESHDESK)
# Formal, SLA-tracked support for when an unresolved Trade Assurance
# dispute needs more than the in-app buyer/seller/admin flow already
# built in Stage 304 — each business brings its own helpdesk account
# (BYOK, registered above) rather than this platform running one
# shared support queue for every seller on it.
def _create_helpdesk_ticket(user_id, subject, description, requester_email=None):
    """Tries the user's configured helpdesk (Zendesk first, then
    Freshdesk) and returns (ticket_url_or_None, error_or_None)."""
    zendesk_creds = get_user_credentials(user_id, "zendesk")
    if zendesk_creds.get("subdomain") and zendesk_creds.get("agent_email") and zendesk_creds.get("api_token"):
        try:
            payload = {"ticket": {"subject": subject, "comment": {"body": description}}}
            if requester_email:
                payload["ticket"]["requester"] = {"email": requester_email}
            r = requests.post(
                f"https://{zendesk_creds['subdomain']}.zendesk.com/api/v2/tickets.json",
                json=payload, timeout=15,
                auth=(f"{zendesk_creds['agent_email']}/token", zendesk_creds["api_token"]),
            )
            r.raise_for_status()
            ticket = r.json().get("ticket", {})
            return f"https://{zendesk_creds['subdomain']}.zendesk.com/agent/tickets/{ticket.get('id')}", None
        except Exception as e:
            logging.error(f"[ZENDESK TICKET ERROR] user={user_id}: {e}")
            return None, f"Zendesk rejected the ticket: {e}"

    freshdesk_creds = get_user_credentials(user_id, "freshdesk")
    if freshdesk_creds.get("domain") and freshdesk_creds.get("api_key"):
        try:
            payload = {"subject": subject, "description": description, "priority": 2, "status": 2,
                       "email": requester_email or "no-reply@marketplace.local"}
            r = requests.post(
                f"https://{freshdesk_creds['domain']}.freshdesk.com/api/v2/tickets",
                json=payload, timeout=15, auth=(freshdesk_creds["api_key"], "X"),
            )
            r.raise_for_status()
            ticket = r.json()
            return f"https://{freshdesk_creds['domain']}.freshdesk.com/a/tickets/{ticket.get('id')}", None
        except Exception as e:
            logging.error(f"[FRESHDESK TICKET ERROR] user={user_id}: {e}")
            return None, f"Freshdesk rejected the ticket: {e}"

    return None, "No helpdesk connected — add Zendesk or Freshdesk under Integrations first."


@app.route("/api/products/orders/<int:order_id>/dispute/escalate", methods=["POST"])
@csrf.exempt
def product_order_dispute_escalate(order_id):
    """Either party on a disputed order can escalate it to a formal
    helpdesk ticket on the SELLER's connected Zendesk/Freshdesk — it's
    their business, their support queue, their SLA."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    order = ProductOrder.query.get(order_id)
    if not order or user["id"] not in (order.buyer_id, order.seller_id):
        return jsonify({"error": "Order not found."}), 404
    if order.escrow_status != "disputed":
        return jsonify({"error": "This order doesn't have an open dispute to escalate."}), 400

    buyer = UserAccount.query.get(order.buyer_id)
    product = Product.query.get(order.product_id)
    subject = f"Trade Assurance dispute — order #{order.id}"
    description = (
        f"Order #{order.id}: {order.quantity} x {product.name if product else 'item'} "
        f"({order.currency} {order.total_price:.2f}).\nBuyer: {buyer.name if buyer else 'N/A'}.\n"
        f"Dispute reason: {order.dispute_reason or 'N/A'}"
    )
    ticket_url, error = _create_helpdesk_ticket(
        order.seller_id, subject, description, requester_email=(buyer.email if buyer else None))
    if error:
        return jsonify({"error": error}), 400
    return jsonify({"ok": True, "ticket_url": ticket_url}), 200


