# ════════════════════════════════════════════════════════════
# STAGE 310: SHIPPING & TRACKING FOR PRODUCT ORDERS
# Hooks ProductOrder up to the existing Stage 186 DHL/FedEx/UPS
# integration instead of building a second shipping system. The seller
# ships using their own already-connected carrier account
# (_shipping_creds_or_error, unchanged); tracking is order-scoped so
# the BUYER can also check status without needing carrier credentials
# of their own — _shipping_track_core is called with the seller's
# user_id looked up from the order, not the requester's.
# ════════════════════════════════════════════════════════════

@app.route("/api/products/orders/<int:order_id>/ship", methods=["POST"])
@csrf.exempt
def product_order_ship(order_id):
    """Seller-only. Body: carrier ('dhl'|'fedex'|'ups'), from_address
    ({name, company, street, city, postal_code, country_code, phone}),
    weight_kg, dims_cm, package_description, service_code (optional),
    customs_items (required for international). to_address comes from
    the buyer's Stripe-collected shipping_address on the order — no
    need to pass it."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    order = ProductOrder.query.filter_by(id=order_id, seller_id=user["id"]).first()
    if not order:
        return jsonify({"error": "Order not found."}), 404
    if order.status != "paid":
        return jsonify({"error": f"Can't ship an order that isn't paid yet (status: {order.status})."}), 400
    if order.tracking_number:
        return jsonify({"error": f"This order already has a {order.carrier.upper() if order.carrier else ''} "
                                  f"tracking number ({order.tracking_number})."}), 400
    if not order.shipping_address:
        return jsonify({"error": "No delivery address on file for this order — the buyer may have paid outside "
                                  "Stripe Checkout. Arrange shipping with them directly."}), 400

    data = request.get_json(silent=True) or {}
    carrier = (data.get("carrier") or "").strip().lower()
    from_addr = data.get("from_address") or {}
    weight_kg = data.get("weight_kg")
    dims = data.get("dims_cm") or {}
    description = (data.get("package_description") or (Product.query.get(order.product_id).name
                   if Product.query.get(order.product_id) else "Merchandise")).strip()
    customs_items = data.get("customs_items") or []

    to_addr = json.loads(order.shipping_address)
    to_addr = {"name": to_addr.get("name") or "", "street": to_addr.get("street") or "",
               "city": to_addr.get("city") or "", "postal_code": to_addr.get("postal_code") or "",
               "country_code": to_addr.get("country_code") or "", "phone": to_addr.get("phone") or ""}

    required_addr_fields = ("name", "street", "city", "postal_code", "country_code")
    missing_from = [f for f in required_addr_fields if not from_addr.get(f)]
    if missing_from:
        return jsonify({"error": f"from_address is missing required field(s): {', '.join(missing_from)}."}), 400
    missing_to = [f for f in required_addr_fields if not to_addr.get(f)]
    if missing_to:
        return jsonify({"error": f"The buyer's delivery address is missing {', '.join(missing_to)} — "
                                  f"ask them to confirm it directly before shipping."}), 400
    if not weight_kg:
        return jsonify({"error": "weight_kg is required."}), 400
    is_international = from_addr.get("country_code") != to_addr.get("country_code")
    if is_international and not customs_items:
        return jsonify({"error": "customs_items is required for international shipments (look up hs_code via the HS Code Classifier first)."}), 400

    tracking_number, label_b64, error = _shipping_create_label_core(
        user["id"], carrier, from_addr, to_addr, weight_kg, dims, description, customs_items,
        service_code=data.get("service_code"))
    if error:
        return jsonify({"error": error[0]}), error[1]

    order.carrier = carrier
    order.tracking_number = tracking_number
    order.shipped_at = datetime.utcnow()
    db.session.commit()
    _escrow_maybe_release_milestone(order.id, "shipped")

    buyer = UserAccount.query.get(order.buyer_id)
    if buyer and buyer.whatsapp_number:
        try:
            send_whatsapp_cloud_message(
                buyer.id, buyer.whatsapp_number,
                f" Your order #{order.id} has shipped via {carrier.upper()} — tracking number {tracking_number}. "
                f"Check My Purchases for live status.")
        except Exception as e:
            logging.error(f"[SHIP WA NOTIFY ERROR] order={order.id}: {e}")
    try:
        _fire_webhook(order.seller_id, "marketplace.order_status_changed", order.to_dict())
    except Exception as e:
        logging.error(f"[MARKETPLACE SHIP WEBHOOK DISPATCH ERROR] order={order.id}: {e}")
    return jsonify({"ok": True, "order": order.to_dict(), "label_base64": label_b64}), 200


@app.route("/api/products/orders/<int:order_id>/tracking", methods=["GET"])
def product_order_tracking(order_id):
    """Either the buyer or the seller on this order can check tracking —
    uses the SELLER's connected carrier credentials regardless of who's
    asking, since that's whose account the shipment was created under."""
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    order = ProductOrder.query.get(order_id)
    if not order or user["id"] not in (order.buyer_id, order.seller_id):
        return jsonify({"error": "Order not found."}), 404
    if not order.tracking_number or not order.carrier:
        return jsonify({"error": "This order hasn't shipped yet."}), 400

    result, error = _shipping_track_core(order.seller_id, order.carrier, order.tracking_number)
    if error:
        return jsonify({"error": error[0]}), error[1]

    was_delivered = "delivered" in (order.last_tracking_status or "").lower()
    new_description = (result.get("status") or {}).get("description") or ""
    order.last_tracking_status = new_description
    order.last_tracking_checked_at = datetime.utcnow()
    db.session.commit()

    # STAGE 312: close the paid -> shipped -> delivered WhatsApp chain —
    # only "paid" pinged before Stage 310/312. Fires once, the first
    # time a tracking check turns up a "delivered" description.
    if not was_delivered and "delivered" in new_description.lower():
        buyer = UserAccount.query.get(order.buyer_id)
        seller = UserAccount.query.get(order.seller_id)
        product = Product.query.get(order.product_id)
        product_name = product.name if product else "your order"
        if buyer and buyer.whatsapp_number:
            try:
                # Real Confirm Receipt / Report Issue buttons instead of a
                # "go to My Purchases" instruction -- the tap is handled
                # directly by _order_confirmation_handle_button_reply above,
                # which runs the same escrow-release/dispute logic as the
                # in-app buttons. Falls back to the old plain-text message
                # if the button send itself fails (e.g. outside the 24-hour
                # session window and no template configured).
                try:
                    send_whatsapp_button_message(
                        buyer.id, buyer.whatsapp_number,
                        f"Delivered! {product_name} has arrived. If everything looks good, tap below to "
                        f"release payment to the seller -- or let us know if there's a problem.",
                        buttons=[
                            {"id": f"order-confirm-{order.id}", "title": "Confirm Receipt"},
                            {"id": f"order-dispute-{order.id}", "title": "Report Issue"},
                        ],
                    )
                except Exception as btn_send_err:
                    logging.warning(f"[DELIVERED WA BUYER BUTTON FALLBACK] order={order.id}: {btn_send_err}")
                    send_whatsapp_cloud_message(
                        buyer.id, buyer.whatsapp_number,
                        f"Delivered! {product_name} has arrived. If everything looks good, "
                        f"confirm receipt in My Purchases to release payment to the seller.")
            except Exception as e:
                logging.error(f"[DELIVERED WA BUYER NOTIFY ERROR] order={order.id}: {e}")
        if seller and seller.whatsapp_number:
            try:
                send_whatsapp_cloud_message(
                    seller.id, seller.whatsapp_number,
                    f"Order #{order.id} ({product_name}) shows as delivered. "
                    f"Trade Assurance will release payment once the buyer confirms.")
            except Exception as e:
                logging.error(f"[DELIVERED WA SELLER NOTIFY ERROR] order={order.id}: {e}")

    return jsonify({"ok": True, **result}), 200


# ════════════════════════════════════════════════════════════
# STAGE 305: MARKETPLACE RFQ (REQUEST FOR QUOTE)
# The bulk-trade counterpart to "Buy Now" — a buyer posts what they
# need (quantity + specs, not a specific listing) and any seller on
# the platform can respond with a price. Distinct from the existing
# RfqRequest/RfqSupplierQuote (Stage 105): that tool is for a business
# logging quotes it collected off-platform from ITS OWN suppliers by
# phone/email — a private procurement notebook. This is the opposite
# direction: an open, on-platform request that other platform SELLERS
# can see and bid on, same as Alibaba's RFQ. Kept as separate models
# so neither tool's data or workflow gets tangled with the other's.
#
# A seller must quote against one of THEIR OWN existing Product
# listings (product_id required) rather than a free-text price —
# that's what lets "Select Winner" hand straight off to
# _create_product_order_checkout(), so an awarded RFQ gets exactly
# the same Trade Assurance-protected checkout as a normal purchase,
# instead of a second, parallel payment path to maintain.
# ════════════════════════════════════════════════════════════

class MarketplaceRfq(db.Model):
    __tablename__  = "marketplace_rfqs"
    id             = db.Column(db.Integer,  primary_key=True)
    buyer_id       = db.Column(db.Integer,  db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    title          = db.Column(db.String(150), nullable=False)
    description    = db.Column(db.Text,     nullable=True)
    category       = db.Column(db.String(60), nullable=True, index=True)
    quantity       = db.Column(db.Integer,  nullable=False, default=1)
    unit           = db.Column(db.String(32), nullable=True)
    target_price   = db.Column(db.Float,    nullable=True)   # buyer's ballpark, optional
    currency       = db.Column(db.String(8), nullable=False, default="USD")
    needed_by_date = db.Column(db.Date,     nullable=True)
    status         = db.Column(db.String(16), nullable=False, default="open", index=True)  # open, awarded, closed
    winning_quote_id = db.Column(db.Integer, nullable=True)
    winning_order_id = db.Column(db.Integer, nullable=True)
    created_at     = db.Column(db.DateTime, default=datetime.utcnow, index=True)

    def to_dict(self, viewer_id=None):
        quotes_q = MarketplaceRfqQuote.query.filter_by(rfq_id=self.id)
        buyer = UserAccount.query.get(self.buyer_id)
        d = {
            "id": self.id, "buyer_id": self.buyer_id,
            "buyer_name": buyer.name if buyer else None,
            "title": self.title, "description": self.description, "category": self.category,
            "quantity": self.quantity, "unit": self.unit, "target_price": self.target_price,
            "currency": self.currency,
            "needed_by_date": self.needed_by_date.isoformat() if self.needed_by_date else None,
            "status": self.status, "winning_quote_id": self.winning_quote_id,
            "winning_order_id": self.winning_order_id,
            "quote_count": quotes_q.count(),
            "is_mine": bool(viewer_id) and viewer_id == self.buyer_id,
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }
        # Full quote list only for the buyer who owns the RFQ; a seller
        # gets back just their own quote (if any) so competitors can't
        # see each other's pricing — the same asymmetry a real RFQ has.
        if viewer_id == self.buyer_id:
            d["quotes"] = [q.to_dict() for q in quotes_q.order_by(MarketplaceRfqQuote.price_per_unit.asc()).all()]
        elif viewer_id:
            mine = quotes_q.filter_by(seller_id=viewer_id).first()
            d["my_quote"] = mine.to_dict() if mine else None
        return d


class MarketplaceRfqQuote(db.Model):
    __tablename__  = "marketplace_rfq_quotes"
    id             = db.Column(db.Integer,  primary_key=True)
    rfq_id         = db.Column(db.Integer,  db.ForeignKey("marketplace_rfqs.id"), nullable=False, index=True)
    seller_id      = db.Column(db.Integer,  db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    product_id     = db.Column(db.Integer,  db.ForeignKey("products.id"), nullable=False)
    price_per_unit = db.Column(db.Float,    nullable=False)
    currency       = db.Column(db.String(8), nullable=False, default="USD")
    lead_time_days = db.Column(db.Integer,  nullable=True)
    notes          = db.Column(db.String(300), nullable=True)
    created_at     = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        seller = UserAccount.query.get(self.seller_id)
        product = Product.query.get(self.product_id)
        return {
            "id": self.id, "rfq_id": self.rfq_id, "seller_id": self.seller_id,
            "seller_name": seller.name if seller else None,
            "product_id": self.product_id, "product_name": product.name if product else None,
            "price_per_unit": self.price_per_unit, "currency": self.currency,
            "lead_time_days": self.lead_time_days, "notes": self.notes,
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }


@app.route("/api/marketplace-rfq", methods=["GET"])
def marketplace_rfq_list():
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    if (request.args.get("mine") or "") == "1":
        rows = (MarketplaceRfq.query.filter_by(buyer_id=user["id"])
                .order_by(MarketplaceRfq.created_at.desc()).limit(100).all())
    else:
        # open board for sellers to browse and quote against
        rows = (MarketplaceRfq.query.filter_by(status="open")
                .order_by(MarketplaceRfq.created_at.desc()).limit(100).all())
    return jsonify({"rfqs": [r.to_dict(viewer_id=user["id"]) for r in rows]}), 200


@app.route("/api/marketplace-rfq", methods=["POST"])
@csrf.exempt
def marketplace_rfq_create():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    title = (data.get("title") or "").strip()[:150]
    if not title:
        return jsonify({"error": "Title is required."}), 400
    try:
        quantity = max(1, int(data.get("quantity", 1)))
    except (TypeError, ValueError):
        quantity = 1
    needed_by = None
    if data.get("needed_by_date"):
        try:
            needed_by = datetime.fromisoformat(data["needed_by_date"]).date()
        except ValueError:
            needed_by = None
    rfq = MarketplaceRfq(
        buyer_id=user["id"], title=title, description=(data.get("description") or "").strip()[:2000] or None,
        category=(data.get("category") or "").strip()[:60] or None, quantity=quantity,
        unit=(data.get("unit") or "").strip()[:32] or None,
        target_price=float(data["target_price"]) if data.get("target_price") not in (None, "") else None,
        currency=(data.get("currency") or "USD").strip()[:8].upper(), needed_by_date=needed_by,
    )
    db.session.add(rfq)
    db.session.commit()
    # STAGE 348: AI-ASSISTED RFQ MATCHING — notify sellers whose own
    # listings are a real match instead of leaving this on the open
    # board for someone to happen to notice. Defined later in this
    # file; resolved at call time, so definition order doesn't matter.
    try:
        _rfq_notify_matching_sellers(rfq)
    except Exception as e:
        logging.error(f"[RFQ MATCH NOTIFY ERROR] rfq={rfq.id}: {e}")
    return jsonify({"ok": True, "rfq": rfq.to_dict(viewer_id=user["id"])}), 201


@app.route("/api/marketplace-rfq/<int:rfq_id>", methods=["GET"])
def marketplace_rfq_get(rfq_id):
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    rfq = MarketplaceRfq.query.get(rfq_id)
    if not rfq:
        return jsonify({"error": "RFQ not found."}), 404
    return jsonify({"rfq": rfq.to_dict(viewer_id=user["id"])}), 200


@app.route("/api/marketplace-rfq/<int:rfq_id>/quotes", methods=["POST"])
@csrf.exempt
def marketplace_rfq_add_quote(rfq_id):
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    rfq = MarketplaceRfq.query.get(rfq_id)
    if not rfq:
        return jsonify({"error": "RFQ not found."}), 404
    if rfq.buyer_id == user["id"]:
        return jsonify({"error": "You can't quote on your own request."}), 400
    if rfq.status != "open":
        return jsonify({"error": "This RFQ is no longer open."}), 400
    data = request.get_json(silent=True) or {}
    product = Product.query.get(data.get("product_id"))
    if not product or not product.is_active or product.seller_id != user["id"]:
        return jsonify({"error": "Quote against one of your own active listings — pick a product_id from Sell first."}), 400
    try:
        price_per_unit = float(data.get("price_per_unit"))
    except (TypeError, ValueError):
        price_per_unit = 0
    if price_per_unit <= 0:
        return jsonify({"error": "A valid price_per_unit is required."}), 400

    existing = MarketplaceRfqQuote.query.filter_by(rfq_id=rfq.id, seller_id=user["id"]).first()
    if existing:
        existing.product_id = product.id
        existing.price_per_unit = price_per_unit
        existing.currency = (data.get("currency") or product.currency or "USD").strip()[:8].upper()
        existing.lead_time_days = data.get("lead_time_days") or None
        existing.notes = (data.get("notes") or "").strip()[:300] or None
        db.session.commit()
        quote = existing
    else:
        quote = MarketplaceRfqQuote(
            rfq_id=rfq.id, seller_id=user["id"], product_id=product.id, price_per_unit=price_per_unit,
            currency=(data.get("currency") or product.currency or "USD").strip()[:8].upper(),
            lead_time_days=data.get("lead_time_days") or None,
            notes=(data.get("notes") or "").strip()[:300] or None,
        )
        db.session.add(quote)
        db.session.commit()

    buyer = UserAccount.query.get(rfq.buyer_id)
    if buyer and buyer.whatsapp_number:
        try:
            send_whatsapp_cloud_message(
                buyer.id, buyer.whatsapp_number,
                f" New quote on your RFQ \"{rfq.title}\": {quote.currency} {price_per_unit:.2f}/unit "
                f"from {UserAccount.query.get(user['id']).name}. Check Marketplace → RFQ to compare.")
        except Exception as e:
            logging.error(f"[RFQ QUOTE WA NOTIFY ERROR] rfq={rfq.id}: {e}")
    return jsonify({"ok": True, "quote": quote.to_dict()}), 201


@app.route("/api/marketplace-rfq/<int:rfq_id>/select-winner", methods=["POST"])
@csrf.exempt
def marketplace_rfq_select_winner(rfq_id):
    """Buyer picks a quote. If it's tied to an active listing with
    enough stock, this immediately creates the order + Trade
    Assurance-protected checkout, same as a normal Buy Now — the RFQ
    just negotiated the price and quantity first."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    rfq = MarketplaceRfq.query.filter_by(id=rfq_id, buyer_id=user["id"]).first()
    if not rfq:
        return jsonify({"error": "RFQ not found."}), 404
    if rfq.status != "open":
        return jsonify({"error": "This RFQ has already been decided."}), 400
    data = request.get_json(silent=True) or {}
    quote = MarketplaceRfqQuote.query.filter_by(id=data.get("quote_id"), rfq_id=rfq.id).first()
    if not quote:
        return jsonify({"error": "Quote not found on this RFQ."}), 404
    product = Product.query.get(quote.product_id)
    if not product or not product.is_active:
        return jsonify({"error": "That seller's listing is no longer available — ask them to re-quote."}), 400
    if product.quantity_available and rfq.quantity > product.quantity_available:
        return jsonify({"error": f"Seller only has {product.quantity_available} available, RFQ asked for {rfq.quantity}."}), 400

    order, checkout_url = _create_product_order_checkout(
        product, rfq.buyer_id, rfq.quantity, unit_price=quote.price_per_unit, currency=quote.currency,
        note=f"Awarded from RFQ #{rfq.id}: {rfq.title}")
    rfq.status = "awarded"
    rfq.winning_quote_id = quote.id
    rfq.winning_order_id = order.id
    db.session.commit()

    seller = UserAccount.query.get(quote.seller_id)
    if seller and seller.whatsapp_number:
        try:
            send_whatsapp_cloud_message(
                seller.id, seller.whatsapp_number,
                f" Your quote won the RFQ \"{rfq.title}\"! Order #{order.id} for {rfq.quantity} unit(s) "
                f"has been created — check Marketplace → My Sales.")
        except Exception as e:
            logging.error(f"[RFQ AWARD WA NOTIFY ERROR] rfq={rfq.id}: {e}")
    return jsonify({"ok": True, "rfq": rfq.to_dict(viewer_id=user["id"]), "order": order.to_dict(), "checkout_url": checkout_url}), 200


# ════════════════════════════════════════════════════════════
# STAGE 348: AI-ASSISTED RFQ MATCHING
# Stage 305 above already lets a buyer post an RFQ and any seller
# browse an open board to quote against it — but "browse and hope you
# notice it" is exactly the manual-search problem this is meant to fix.
# This layer adds the matching + notification half: the moment an RFQ
# is posted, sellers whose OWN listings are a real match get notified
# directly and see it surfaced first, instead of everyone relying on
# the open board.
#
# "AI-assisted" here means real, explainable matching signals — not a
# black-box model call: keyword overlap between the RFQ's own title/
# description and a listing's name/description/category, a category
# match, and the same two already-computed trust signals Stage 346
# reuses for stock-alternatives ranking (Verified Factory Audit, Trust
# Score) — no new, fabricated relevance score.
# ════════════════════════════════════════════════════════════

_RFQ_MATCH_STOPWORDS = {
    "the", "a", "an", "and", "or", "for", "with", "of", "to", "in", "on", "is", "are",
    "this", "that", "need", "needed", "looking", "want", "wanted", "please", "some",
    "any", "new", "used", "our", "your", "we", "us", "buy", "buying", "order", "orders",
}


def _rfq_tokenize(text) -> set:
    if not text:
        return set()
    words = re.findall(r"[a-zA-Z0-9]+", text.lower())
    return {w for w in words if len(w) > 2 and w not in _RFQ_MATCH_STOPWORDS}


def _rfq_find_matching_sellers(rfq: "MarketplaceRfq", limit=25) -> list:
    """Pure query/ranking function -- no DB writes. Category match and
    keyword overlap are both treated as ranking signals rather than a
    hard filter (many real listings are mis-categorized or just phrase
    things differently), so a candidate needs at least ONE of the two
    to surface at all -- pure trust/price signals alone never qualify
    a listing that has nothing else in common with the request."""
    rfq_tokens = _rfq_tokenize(rfq.title) | _rfq_tokenize(rfq.description)
    candidates = (Product.query
                  .filter(Product.is_active.is_(True), Product.seller_id != rfq.buyer_id)
                  .limit(500).all())
    best_by_seller = {}
    for p in candidates:
        product_tokens = _rfq_tokenize(p.name) | _rfq_tokenize(p.description) | _rfq_tokenize(p.category)
        overlap = rfq_tokens & product_tokens
        category_match = bool(rfq.category) and bool(p.category) and p.category == rfq.category
        if not overlap and not category_match:
            continue
        price_penalty = 0.0
        if rfq.target_price and p.price:
            price_penalty = min(abs(p.price - rfq.target_price) / rfq.target_price, 2.0) * 15
        audit = _seller_audit_public_summary(p.seller_id)
        trust = compute_trust_score(p.seller_id)
        score = (len(overlap) * 12) + (40 if category_match else 0) + \
                (15 if audit["facility_verified"] else 0) + (trust["score"] * 0.3) - price_penalty
        reasons = []
        if category_match:
            reasons.append("same category")
        if overlap:
            reasons.append("matches: " + ", ".join(sorted(overlap)[:4]))
        current = best_by_seller.get(p.seller_id)
        if current is None or score > current[0]:
            best_by_seller[p.seller_id] = (score, p, "; ".join(reasons) or "similar listing")
    ranked = sorted(best_by_seller.items(), key=lambda kv: -kv[1][0])[:limit]
    return [{"seller_id": sid, "product": p, "score": score, "reason": reason}
            for sid, (score, p, reason) in ranked]


# ════════════════════════════════════════════════════════════
# STAGE 519: RFQ MATCH NOTIFICATION — TEMPLATE-FIRST, SESSION-FREE-TEXT
# FALLBACK
# Stage 348 (above) already fires this the moment an RFQ is posted —
# but it was sending free-text via send_whatsapp_cloud_message(), which
# Meta's platform silently drops for any seller who hasn't personally
# messaged the platform's WhatsApp number in the last 24 hours (the
# exact "customer-initiated session window" rule this same file
# already documents and works around elsewhere for broadcasts —
# product_broadcast_to_subscribers uses a template for exactly this
# reason). A real buyer-driven RFQ arriving out of nowhere is the
# textbook case Meta built templates for: nobody messaged first, so
# free-text has no session to ride on. This makes the RFQ-match alert
# template-first, falling back to the old free-text send only if no
# template is configured/approved yet — so a seller who hasn't set one
# up still gets a chance at delivery instead of silence, but every
# seller who HAS one gets reliable delivery regardless of session
# state, which is the whole point of this stage.
# ════════════════════════════════════════════════════════════

def _rfq_match_whatsapp_notify(seller_id, to_number, summary_text):
    """Tries the seller's own approved template (BYOK override) or the
    platform default template first; only falls back to a free-text
    session message if no template name is configured at all, or the
    template send itself fails (e.g. not yet approved by Meta) — never
    silently gives up without attempting delivery some way."""
    template_name = get_effective_credential(
        seller_id, "whatsapp_cloud", "rfq_match_template_name", RFQ_MATCH_WHATSAPP_TEMPLATE_NAME)
    language_code = get_effective_credential(
        seller_id, "whatsapp_cloud", "rfq_match_template_language", RFQ_MATCH_WHATSAPP_TEMPLATE_LANG)
    if template_name:
        try:
            send_whatsapp_template_message(
                seller_id, to_number, template_name, language_code,
                components=[{"type": "body", "parameters": [{"type": "text", "text": summary_text[:1024]}]}])
            return True
        except Exception as e:
            logging.warning(f"[RFQ MATCH WA TEMPLATE FAILED, falling back to free-text] seller={seller_id}: {e}")
    # Fallback: only reaches the seller if they're inside an active
    # 24h session with the platform's WhatsApp number — better than
    # nothing, but this is the degraded path, not the intended one.
    send_whatsapp_cloud_message(seller_id, to_number, summary_text)
    return False


def _rfq_notify_matching_sellers(rfq: "MarketplaceRfq") -> None:
    """Called once, right after an RFQ is posted. Idempotent per
    (rfq, seller) via the MarketplaceRfqMatch unique constraint, so a
    retry or a later re-run never double-notifies the same seller."""
    try:
        matches = _rfq_find_matching_sellers(rfq)
    except Exception as e:
        logging.error(f"[RFQ MATCH FIND ERROR] rfq={rfq.id}: {e}")
        return
    for m in matches:
        if MarketplaceRfqMatch.query.filter_by(rfq_id=rfq.id, seller_id=m["seller_id"]).first():
            continue
        match_row = MarketplaceRfqMatch(
            rfq_id=rfq.id, seller_id=m["seller_id"], product_id=m["product"].id,
            match_score=round(m["score"], 2), match_reason=m["reason"][:300],
        )
        db.session.add(match_row)
        db.session.commit()
        try:
            send_user_push(
                m["seller_id"], "New RFQ matching your listing",
                f'"{rfq.title}" — {rfq.quantity} {rfq.unit or "units"} wanted. Quote now.')
        except Exception as e:
            logging.error(f"[RFQ MATCH PUSH ERROR] rfq={rfq.id} seller={m['seller_id']}: {e}")
        seller = UserAccount.query.get(m["seller_id"])
        if seller and seller.whatsapp_number:
            summary = (
                f"New buyer RFQ matches your listing \"{m['product'].name}\": \"{rfq.title}\" — "
                f"{rfq.quantity} {rfq.unit or 'units'} wanted"
                + (f", target price ~{rfq.currency} {rfq.target_price:.2f}" if rfq.target_price else "")
                + ". Check Marketplace -> RFQ -> Matched to You to quote."
            )
            try:
                used_template = _rfq_match_whatsapp_notify(m["seller_id"], seller.whatsapp_number, summary)
                match_row.notified_via_template = used_template
            except Exception as e:
                logging.error(f"[RFQ MATCH WA NOTIFY ERROR] rfq={rfq.id} seller={m['seller_id']}: {e}")
        match_row.notified_at = datetime.utcnow()
        db.session.commit()


class MarketplaceRfqMatch(db.Model):
    __tablename__  = "marketplace_rfq_matches"
    id             = db.Column(db.Integer, primary_key=True)
    rfq_id         = db.Column(db.Integer, db.ForeignKey("marketplace_rfqs.id"), nullable=False, index=True)
    seller_id      = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    product_id     = db.Column(db.Integer, db.ForeignKey("products.id"), nullable=False)
    match_score    = db.Column(db.Float, nullable=False, default=0.0)
    match_reason   = db.Column(db.String(300), nullable=True)
    notified_at    = db.Column(db.DateTime, nullable=True)
    # STAGE 519: new column, auto-migrated on startup (or run once on
    # production MySQL):
    #   ALTER TABLE marketplace_rfq_matches ADD COLUMN notified_via_template BOOLEAN NULL;
    # True = delivered through an approved WhatsApp template (reliable,
    # any time). False = fell back to a free-text session message
    # (only delivered if the seller was inside an active 24h window).
    # NULL = no WhatsApp number on file, so no WhatsApp attempt at all.
    notified_via_template = db.Column(db.Boolean, nullable=True)
    created_at     = db.Column(db.DateTime, default=datetime.utcnow, index=True)
    __table_args__ = (db.UniqueConstraint("rfq_id", "seller_id", name="uq_rfqmatch_rfq_seller"),)


@app.route("/api/marketplace-rfq/matched-to-me", methods=["GET"])
def marketplace_rfq_matched_to_me():
    """A seller's own matched view of the RFQ board -- ranked by real
    match signals instead of requiring them to manually scan every
    open RFQ, same complaint this whole stage exists to fix."""
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    rows = (db.session.query(MarketplaceRfqMatch, MarketplaceRfq)
            .join(MarketplaceRfq, MarketplaceRfq.id == MarketplaceRfqMatch.rfq_id)
            .filter(MarketplaceRfqMatch.seller_id == user["id"], MarketplaceRfq.status == "open")
            .order_by(MarketplaceRfqMatch.match_score.desc()).limit(50).all())
    out = []
    for match, rfq in rows:
        d = rfq.to_dict(viewer_id=user["id"])
        d["match_score"] = match.match_score
        d["match_reason"] = match.match_reason
        d["matched_product_id"] = match.product_id
        d["whatsapp_alert_via_template"] = match.notified_via_template
        out.append(d)
    return jsonify({"rfqs": out}), 200


@app.route("/api/marketplace-rfq/whatsapp-alert-template", methods=["GET"])
def marketplace_rfq_whatsapp_alert_template_get():
    """The effective template a seller's RFQ-match alerts will use right
    now — their own override if they've set one, else the platform
    default — plus whether it's currently overridden, so the settings
    UI can show 'using platform default' vs 'using your own template'."""
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    own = get_user_credentials(user["id"], "whatsapp_cloud")
    return jsonify({
        "ok": True,
        "template_name": own.get("rfq_match_template_name") or "",
        "language_code": own.get("rfq_match_template_language") or "",
        "platform_default_template_name": RFQ_MATCH_WHATSAPP_TEMPLATE_NAME,
        "platform_default_language_code": RFQ_MATCH_WHATSAPP_TEMPLATE_LANG,
        "is_overridden": bool(own.get("rfq_match_template_name")),
    }), 200


@app.route("/api/marketplace-rfq/whatsapp-alert-template", methods=["POST"])
@csrf.exempt
def marketplace_rfq_whatsapp_alert_template_set():
    """Body: template_name, language_code — both optional; leave blank
    to clear the override and go back to the platform default. Merges
    into the seller's existing whatsapp_cloud credentials rather than
    overwriting them, since save_user_integration() replaces the whole
    blob and this seller may already have a phone_number_id/access_token
    saved there for sending their own messages."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    template_name = (data.get("template_name") or "").strip()[:120]
    language_code = (data.get("language_code") or "").strip()[:10]

    merged = dict(get_user_credentials(user["id"], "whatsapp_cloud") or {})
    if template_name:
        merged["rfq_match_template_name"] = template_name
    else:
        merged.pop("rfq_match_template_name", None)
    if language_code:
        merged["rfq_match_template_language"] = language_code
    else:
        merged.pop("rfq_match_template_language", None)

    if merged:
        save_user_integration(user["id"], "whatsapp_cloud", merged)
    return jsonify({"ok": True, "template_name": template_name, "language_code": language_code}), 200


# ════════════════════════════════════════════════════════════
# STAGE 350: REAL FREIGHT MARKETPLACE — CONTAINER/LCL BOOKING VIA
# FREIGHT FORWARDER BIDDING
# Stage 341 above already gives a buyer live parcel-carrier quotes
# (DHL/FedEx/UPS) for small-package shipping. Real bulk B2B cargo moves
# by SEA FREIGHT — LCL (less-than-container-load, shared container) or
# FCL (full container load, 20ft/40ft) — which none of those three
# APIs quote at all; ocean freight pricing simply isn't available
# through a free, universal API the way parcel rates are. So instead of
# fabricating a number, this builds the real thing a container booking
# actually is offline: a buyer/seller posts what they need shipped,
# registered freight forwarders on the platform (a new, open role any
# user can take on) bid on it, and the requester picks a winner —
# exactly the same open-marketplace-bid pattern Stage 305/348 already
# uses for product RFQs, just applied to freight instead of goods.
#
# Once booked, there is still no free universal ocean-tracking API to
# honestly poll, so milestone tracking here is the winning forwarder's
# own self-attested updates — the same honesty bar as every other
# self-attested milestone already in this file (demand-pool handoff,
# escrow delivery confirmation), not a fabricated GPS feed.
# ════════════════════════════════════════════════════════════

FREIGHT_BOOKING_MILESTONES = [
    "booked", "departed_origin", "in_transit", "arrived_destination", "customs_cleared", "delivered",
]


class FreightForwarderProfile(db.Model):
    __tablename__       = "freight_forwarder_profiles"
    id                  = db.Column(db.Integer, primary_key=True)
    user_id             = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, unique=True, index=True)
    company_name        = db.Column(db.String(150), nullable=False)
    serviced_countries  = db.Column(db.String(400), nullable=True)  # comma-separated ISO country codes this forwarder handles a lane to/from
    container_types     = db.Column(db.String(100), nullable=True)  # comma-separated: lcl, fcl20, fcl40
    is_active           = db.Column(db.Boolean, nullable=False, default=True)
    created_at           = db.Column(db.DateTime, default=datetime.utcnow)

    def serviced_countries_list(self) -> list:
        return [c.strip().upper() for c in (self.serviced_countries or "").split(",") if c.strip()]

    def to_dict(self) -> dict:
        user = UserAccount.query.get(self.user_id)
        return {
            "id": self.id, "user_id": self.user_id, "user_name": user.name if user else None,
            "company_name": self.company_name, "serviced_countries": self.serviced_countries_list(),
            "container_types": [c.strip() for c in (self.container_types or "").split(",") if c.strip()],
            "is_active": self.is_active, "created_at": self.created_at.isoformat() if self.created_at else None,
        }


class FreightBookingRequest(db.Model):
    __tablename__        = "freight_booking_requests"
    id                   = db.Column(db.Integer, primary_key=True)
    requester_id         = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    product_order_id     = db.Column(db.Integer, db.ForeignKey("product_orders.id"), nullable=True)
    origin_country       = db.Column(db.String(4), nullable=False)
    origin_port          = db.Column(db.String(100), nullable=True)
    destination_country  = db.Column(db.String(4), nullable=False)
    destination_port     = db.Column(db.String(100), nullable=True)
    cargo_type           = db.Column(db.String(8), nullable=False, default="lcl")  # lcl or fcl
    container_type       = db.Column(db.String(16), nullable=True)  # 20ft / 40ft, only meaningful for fcl
    weight_kg            = db.Column(db.Float, nullable=True)
    volume_cbm           = db.Column(db.Float, nullable=True)
    cargo_description    = db.Column(db.String(300), nullable=True)
    ready_date           = db.Column(db.Date, nullable=True)
    status                = db.Column(db.String(16), nullable=False, default="open", index=True)  # open, booked, cancelled, expired
    winning_bid_id        = db.Column(db.Integer, nullable=True)
    created_at            = db.Column(db.DateTime, default=datetime.utcnow, index=True)

    def to_dict(self, viewer_id=None) -> dict:
        requester = UserAccount.query.get(self.requester_id)
        bids_q = FreightBookingBid.query.filter_by(request_id=self.id)
        d = {
            "id": self.id, "requester_id": self.requester_id, "requester_name": requester.name if requester else None,
            "product_order_id": self.product_order_id,
            "origin_country": self.origin_country, "origin_port": self.origin_port,
            "destination_country": self.destination_country, "destination_port": self.destination_port,
            "cargo_type": self.cargo_type, "container_type": self.container_type,
            "weight_kg": self.weight_kg, "volume_cbm": self.volume_cbm,
            "cargo_description": self.cargo_description,
            "ready_date": self.ready_date.isoformat() if self.ready_date else None,
            "status": self.status, "winning_bid_id": self.winning_bid_id,
            "bid_count": bids_q.count(),
            "is_mine": bool(viewer_id) and viewer_id == self.requester_id,
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }
        if viewer_id == self.requester_id:
            d["bids"] = [b.to_dict() for b in bids_q.order_by(FreightBookingBid.price.asc()).all()]
        elif viewer_id:
            mine = bids_q.filter_by(forwarder_id=viewer_id).first()
            d["my_bid"] = mine.to_dict() if mine else None
        if self.status == "booked":
            d["milestones"] = [m.to_dict() for m in
                                FreightBookingMilestone.query.filter_by(request_id=self.id)
                                .order_by(FreightBookingMilestone.created_at.asc()).all()]
        return d


class FreightBookingBid(db.Model):
    __tablename__  = "freight_booking_bids"
    id             = db.Column(db.Integer, primary_key=True)
    request_id     = db.Column(db.Integer, db.ForeignKey("freight_booking_requests.id"), nullable=False, index=True)
    forwarder_id   = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    carrier_name   = db.Column(db.String(100), nullable=True)  # forwarder's own self-declared carrier, e.g. Maersk, MSC
    price          = db.Column(db.Float, nullable=False)
    currency       = db.Column(db.String(8), nullable=False, default="USD")
    transit_days   = db.Column(db.Integer, nullable=True)
    notes          = db.Column(db.String(300), nullable=True)
    created_at     = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self) -> dict:
        forwarder = UserAccount.query.get(self.forwarder_id)
        profile = FreightForwarderProfile.query.filter_by(user_id=self.forwarder_id).first()
        trust = compute_trust_score(self.forwarder_id)
        return {
            "id": self.id, "request_id": self.request_id, "forwarder_id": self.forwarder_id,
            "forwarder_name": forwarder.name if forwarder else None,
            "forwarder_company": profile.company_name if profile else None,
            "forwarder_trust_score": trust["score"],
            "carrier_name": self.carrier_name, "price": self.price, "currency": self.currency,
            "transit_days": self.transit_days, "notes": self.notes,
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }


class FreightBookingMilestone(db.Model):
    __tablename__       = "freight_booking_milestones"
    id                  = db.Column(db.Integer, primary_key=True)
    request_id          = db.Column(db.Integer, db.ForeignKey("freight_booking_requests.id"), nullable=False, index=True)
    milestone           = db.Column(db.String(32), nullable=False)
    note                = db.Column(db.String(300), nullable=True)
    recorded_by_user_id = db.Column(db.Integer, nullable=True)
    created_at           = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self) -> dict:
        return {
            "id": self.id, "milestone": self.milestone, "note": self.note,
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }


def _freight_notify_matching_forwarders(req: "FreightBookingRequest") -> None:
    """Called once, right after a booking request is posted. Matches on
    real, structured lane data (origin/destination country appearing in
    a forwarder's own declared serviced_countries) rather than free-text
    keyword guessing — freight lanes are exact, not fuzzy."""
    try:
        forwarders = FreightForwarderProfile.query.filter_by(is_active=True).all()
    except Exception as e:
        logging.error(f"[FREIGHT MATCH FIND ERROR] request={req.id}: {e}")
        return
    for fwd in forwarders:
        lanes = fwd.serviced_countries_list()
        if req.origin_country not in lanes and req.destination_country not in lanes:
            continue
        try:
            send_user_push(
                fwd.user_id, "New freight booking request matching your lanes",
                f"{req.origin_country} → {req.destination_country}, {req.cargo_type.upper()}"
                + (f" ({req.container_type})" if req.container_type else "") + ". Submit a bid.")
        except Exception as e:
            logging.error(f"[FREIGHT MATCH PUSH ERROR] request={req.id} forwarder={fwd.user_id}: {e}")
        user = UserAccount.query.get(fwd.user_id)
        if user and user.whatsapp_number:
            try:
                send_whatsapp_cloud_message(
                    user.id, user.whatsapp_number,
                    f"New freight booking request on your lane: {req.origin_country} -> {req.destination_country}, "
                    f"{req.cargo_type.upper()}" + (f" ({req.container_type})" if req.container_type else "") +
                    ". Check Marketplace -> Freight Forwarders to bid.")
            except Exception as e:
                logging.error(f"[FREIGHT MATCH WA NOTIFY ERROR] request={req.id} forwarder={fwd.user_id}: {e}")


@app.route("/api/freight-forwarder/profile", methods=["POST"])
@csrf.exempt
def freight_forwarder_profile_set():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    company_name = (data.get("company_name") or "").strip()[:150]
    if not company_name:
        return jsonify({"error": "company_name is required."}), 400
    countries = ",".join(sorted({c.strip().upper()[:4] for c in (data.get("serviced_countries") or []) if c.strip()}))
    containers = ",".join(sorted({c.strip().lower()[:16] for c in (data.get("container_types") or []) if c.strip()}))
    profile = FreightForwarderProfile.query.filter_by(user_id=user["id"]).first()
    if profile:
        profile.company_name = company_name
        profile.serviced_countries = countries or None
        profile.container_types = containers or None
        profile.is_active = data.get("is_active", True)
    else:
        profile = FreightForwarderProfile(
            user_id=user["id"], company_name=company_name,
            serviced_countries=countries or None, container_types=containers or None,
            is_active=data.get("is_active", True))
        db.session.add(profile)
    db.session.commit()
    return jsonify({"ok": True, "profile": profile.to_dict()}), 200


@app.route("/api/freight-forwarder/profile/mine", methods=["GET"])
def freight_forwarder_profile_mine():
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    profile = FreightForwarderProfile.query.filter_by(user_id=user["id"]).first()
    return jsonify({"profile": profile.to_dict() if profile else None}), 200


@app.route("/api/freight-bookings", methods=["POST"])
@csrf.exempt
def freight_booking_create():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    origin_country = (data.get("origin_country") or "").strip().upper()[:4]
    destination_country = (data.get("destination_country") or "").strip().upper()[:4]
    if not origin_country or not destination_country:
        return jsonify({"error": "origin_country and destination_country are required."}), 400
    cargo_type = (data.get("cargo_type") or "lcl").strip().lower()
    if cargo_type not in ("lcl", "fcl"):
        return jsonify({"error": "cargo_type must be 'lcl' or 'fcl'."}), 400
    ready_date = None
    if data.get("ready_date"):
        try:
            ready_date = datetime.fromisoformat(data["ready_date"]).date()
        except ValueError:
            ready_date = None
    order_id = data.get("product_order_id")
    if order_id:
        order = ProductOrder.query.filter_by(id=order_id).first()
        if not order or user["id"] not in (order.buyer_id, order.seller_id):
            return jsonify({"error": "That order wasn't found on your account."}), 404

    req = FreightBookingRequest(
        requester_id=user["id"], product_order_id=order_id or None,
        origin_country=origin_country, origin_port=(data.get("origin_port") or "").strip()[:100] or None,
        destination_country=destination_country, destination_port=(data.get("destination_port") or "").strip()[:100] or None,
        cargo_type=cargo_type, container_type=(data.get("container_type") or "").strip()[:16] or None,
        weight_kg=float(data["weight_kg"]) if data.get("weight_kg") not in (None, "") else None,
        volume_cbm=float(data["volume_cbm"]) if data.get("volume_cbm") not in (None, "") else None,
        cargo_description=(data.get("cargo_description") or "").strip()[:300] or None,
        ready_date=ready_date,
    )
    db.session.add(req)
    db.session.commit()
    try:
        _freight_notify_matching_forwarders(req)
    except Exception as e:
        logging.error(f"[FREIGHT MATCH NOTIFY ERROR] request={req.id}: {e}")
    return jsonify({"ok": True, "request": req.to_dict(viewer_id=user["id"])}), 201


@app.route("/api/freight-bookings", methods=["GET"])
def freight_booking_list():
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    if (request.args.get("mine") or "") == "1":
        rows = (FreightBookingRequest.query.filter_by(requester_id=user["id"])
                .order_by(FreightBookingRequest.created_at.desc()).limit(100).all())
    else:
        rows = (FreightBookingRequest.query.filter_by(status="open")
                .order_by(FreightBookingRequest.created_at.desc()).limit(100).all())
    return jsonify({"requests": [r.to_dict(viewer_id=user["id"]) for r in rows]}), 200


@app.route("/api/freight-bookings/matched-to-me", methods=["GET"])
def freight_booking_matched_to_me():
    """A registered forwarder's own lane-matched view of the open board,
    same complaint this whole stage exists to fix for the RFQ board —
    plus (regardless of lane match) any request THIS forwarder has
    already won, so they have somewhere to post milestone updates."""
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    won_bid_request_ids = [b.request_id for b in FreightBookingBid.query.filter_by(forwarder_id=user["id"]).all()]
    won_rows = (FreightBookingRequest.query
                .filter(FreightBookingRequest.id.in_(won_bid_request_ids), FreightBookingRequest.status == "booked",
                        FreightBookingRequest.winning_bid_id.in_(
                            db.session.query(FreightBookingBid.id).filter_by(forwarder_id=user["id"])))
                .all()) if won_bid_request_ids else []

    profile = FreightForwarderProfile.query.filter_by(user_id=user["id"], is_active=True).first()
    open_rows = []
    note = None
    if not profile:
        note = "Register a Freight Forwarder profile to see lane-matched open requests." if not won_rows else None
    else:
        lanes = profile.serviced_countries_list()
        if not lanes:
            note = "Add serviced countries to your forwarder profile to see lane-matched open requests." if not won_rows else None
        else:
            open_rows = (FreightBookingRequest.query.filter_by(status="open")
                         .filter(db.or_(FreightBookingRequest.origin_country.in_(lanes),
                                         FreightBookingRequest.destination_country.in_(lanes)))
                         .order_by(FreightBookingRequest.created_at.desc()).limit(100).all())
    combined = won_rows + [r for r in open_rows if r.id not in {w.id for w in won_rows}]
    resp = {"requests": [r.to_dict(viewer_id=user["id"]) for r in combined]}
    if note:
        resp["note"] = note
    return jsonify(resp), 200


