@app.route("/api/freight-bookings/<int:request_id>/bids", methods=["POST"])
@csrf.exempt
def freight_booking_add_bid(request_id):
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    req = FreightBookingRequest.query.get(request_id)
    if not req:
        return jsonify({"error": "Freight booking request not found."}), 404
    if req.requester_id == user["id"]:
        return jsonify({"error": "You can't bid on your own request."}), 400
    if req.status != "open":
        return jsonify({"error": "This booking request is no longer open."}), 400
    profile = FreightForwarderProfile.query.filter_by(user_id=user["id"], is_active=True).first()
    if not profile:
        return jsonify({"error": "Register a Freight Forwarder profile before bidding."}), 400
    data = request.get_json(silent=True) or {}
    try:
        price = float(data.get("price"))
    except (TypeError, ValueError):
        price = 0
    if price <= 0:
        return jsonify({"error": "A valid price is required."}), 400

    existing = FreightBookingBid.query.filter_by(request_id=req.id, forwarder_id=user["id"]).first()
    if existing:
        existing.carrier_name = (data.get("carrier_name") or "").strip()[:100] or None
        existing.price = price
        existing.currency = (data.get("currency") or "USD").strip()[:8].upper()
        existing.transit_days = data.get("transit_days") or None
        existing.notes = (data.get("notes") or "").strip()[:300] or None
        db.session.commit()
        bid = existing
    else:
        bid = FreightBookingBid(
            request_id=req.id, forwarder_id=user["id"],
            carrier_name=(data.get("carrier_name") or "").strip()[:100] or None,
            price=price, currency=(data.get("currency") or "USD").strip()[:8].upper(),
            transit_days=data.get("transit_days") or None, notes=(data.get("notes") or "").strip()[:300] or None,
        )
        db.session.add(bid)
        db.session.commit()

    requester = UserAccount.query.get(req.requester_id)
    if requester and requester.whatsapp_number:
        try:
            send_whatsapp_cloud_message(
                requester.id, requester.whatsapp_number,
                f"New freight bid on your {req.origin_country}->{req.destination_country} request: "
                f"{bid.currency} {price:.2f} from {profile.company_name}. Check Marketplace -> Freight Forwarders to compare.")
        except Exception as e:
            logging.error(f"[FREIGHT BID WA NOTIFY ERROR] request={req.id}: {e}")
    return jsonify({"ok": True, "bid": bid.to_dict()}), 201


@app.route("/api/freight-bookings/<int:request_id>/select-winner", methods=["POST"])
@csrf.exempt
def freight_booking_select_winner(request_id):
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    req = FreightBookingRequest.query.filter_by(id=request_id, requester_id=user["id"]).first()
    if not req:
        return jsonify({"error": "Freight booking request not found."}), 404
    if req.status != "open":
        return jsonify({"error": "This request has already been decided."}), 400
    data = request.get_json(silent=True) or {}
    bid = FreightBookingBid.query.filter_by(id=data.get("bid_id"), request_id=req.id).first()
    if not bid:
        return jsonify({"error": "Bid not found on this request."}), 404

    req.status = "booked"
    req.winning_bid_id = bid.id
    db.session.add(FreightBookingMilestone(
        request_id=req.id, milestone="booked",
        note=f"Booked with {bid.carrier_name or 'winning forwarder'} at {bid.currency} {bid.price:.2f}.",
        recorded_by_user_id=user["id"]))
    db.session.commit()

    forwarder = UserAccount.query.get(bid.forwarder_id)
    if forwarder and forwarder.whatsapp_number:
        try:
            send_whatsapp_cloud_message(
                forwarder.id, forwarder.whatsapp_number,
                f"Your bid won the freight booking {req.origin_country}->{req.destination_country}! "
                f"Post milestone updates from Marketplace -> Freight Forwarders as the shipment moves.")
        except Exception as e:
            logging.error(f"[FREIGHT AWARD WA NOTIFY ERROR] request={req.id}: {e}")
    return jsonify({"ok": True, "request": req.to_dict(viewer_id=user["id"])}), 200


@app.route("/api/freight-bookings/<int:request_id>/milestones", methods=["POST"])
@csrf.exempt
def freight_booking_add_milestone(request_id):
    """Self-attested tracking update from the winning forwarder — the
    honest substitute for a universal ocean-tracking API that doesn't
    exist for free, same pattern as every other self-attested milestone
    in this file."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    req = FreightBookingRequest.query.get(request_id)
    if not req:
        return jsonify({"error": "Freight booking request not found."}), 404
    if req.status != "booked":
        return jsonify({"error": "This request isn't booked yet."}), 400
    winning_bid = FreightBookingBid.query.get(req.winning_bid_id) if req.winning_bid_id else None
    if not winning_bid or winning_bid.forwarder_id != user["id"]:
        return jsonify({"error": "Only the winning forwarder can post milestone updates."}), 403
    data = request.get_json(silent=True) or {}
    milestone = (data.get("milestone") or "").strip().lower()
    if milestone not in FREIGHT_BOOKING_MILESTONES:
        return jsonify({"error": f"milestone must be one of: {', '.join(FREIGHT_BOOKING_MILESTONES)}."}), 400
    row = FreightBookingMilestone(
        request_id=req.id, milestone=milestone, note=(data.get("note") or "").strip()[:300] or None,
        recorded_by_user_id=user["id"])
    db.session.add(row)
    db.session.commit()
    if milestone == "customs_cleared" and req.product_order_id:
        # STAGE 354: PROGRAMMABLE ESCROW — a real logistics event
        # (this freight booking is linked to an actual marketplace
        # order) can trigger that order's customs-clearance tranche.
        _escrow_maybe_release_milestone(req.product_order_id, "customs_cleared")
    requester = UserAccount.query.get(req.requester_id)
    if requester and requester.whatsapp_number:
        try:
            send_whatsapp_cloud_message(
                requester.id, requester.whatsapp_number,
                f"Freight update ({req.origin_country}->{req.destination_country}): {milestone.replace('_', ' ')}.")
        except Exception as e:
            logging.error(f"[FREIGHT MILESTONE WA NOTIFY ERROR] request={req.id}: {e}")
    return jsonify({"ok": True, "milestone": row.to_dict()}), 201


# ════════════════════════════════════════════════════════════
# STAGE 351: PLATFORM/PARTNERED FULFILLMENT CENTERS (WAREHOUSING)
# The Cainiao-equivalent: a seller can ship inventory to a platform-run
# or partnered warehouse instead of fulfilling every order from their
# own premises, and orders against that stock get picked/packed/shipped
# from the center instead. FulfillmentCenter rows are admin-managed —
# same reasoning as InsurancePartner and the freight-forwarder
# onboarding gate elsewhere in this file: a real warehouse is a real
# physical/legal relationship this platform has to actually have, not
# something any user can self-declare into existence.
#
# Once a listing's inbound shipment is confirmed received, its
# product.quantity_available becomes a MIRROR of the center's own
# FulfillmentInventory row rather than a second, divergent number —
# every place that already reads/writes quantity_available (buy flow,
# stock alternatives, low-stock alerts) keeps working unchanged; this
# stage just keeps the mirror in sync on both sides.
#
# Center-side pick/pack/ship progress is admin-recorded (the center
# operator's own staff aren't independent platform accounts in this
# version) — self-attested the same honest way as every other
# warehouse/logistics milestone in this file, not a fabricated
# warehouse-management-system integration.
# ════════════════════════════════════════════════════════════

FULFILLMENT_ORDER_TASK_STATUSES = ["pending", "picked", "packed", "shipped"]


class FulfillmentCenter(db.Model):
    __tablename__   = "fulfillment_centers"
    id              = db.Column(db.Integer, primary_key=True)
    name            = db.Column(db.String(150), nullable=False)
    operator_name   = db.Column(db.String(150), nullable=True)  # platform's own ops team, or the partnered 3PL's name
    country_code    = db.Column(db.String(4), nullable=False)
    city            = db.Column(db.String(100), nullable=True)
    address         = db.Column(db.String(300), nullable=True)
    capacity_note   = db.Column(db.String(300), nullable=True)
    per_unit_storage_fee = db.Column(db.Float, nullable=False, default=0.0)  # charged monthly per unit on hand, seller's own currency
    currency        = db.Column(db.String(8), nullable=False, default="USD")
    is_active       = db.Column(db.Boolean, nullable=False, default=True)
    created_at       = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self) -> dict:
        return {
            "id": self.id, "name": self.name, "operator_name": self.operator_name,
            "country_code": self.country_code, "city": self.city, "address": self.address,
            "capacity_note": self.capacity_note,
            "per_unit_storage_fee": self.per_unit_storage_fee, "currency": self.currency,
            "is_active": self.is_active, "created_at": self.created_at.isoformat() if self.created_at else None,
        }


class FulfillmentInboundShipment(db.Model):
    __tablename__       = "fulfillment_inbound_shipments"
    id                  = db.Column(db.Integer, primary_key=True)
    seller_id           = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    product_id          = db.Column(db.Integer, db.ForeignKey("products.id"), nullable=False, index=True)
    fulfillment_center_id = db.Column(db.Integer, db.ForeignKey("fulfillment_centers.id"), nullable=False, index=True)
    quantity_shipped    = db.Column(db.Integer, nullable=False)
    quantity_received   = db.Column(db.Integer, nullable=True)
    tracking_note       = db.Column(db.String(300), nullable=True)  # seller's own self-attested "how it's getting there"
    status               = db.Column(db.String(16), nullable=False, default="requested", index=True)  # requested, received, rejected
    rejection_note        = db.Column(db.String(300), nullable=True)
    requested_at          = db.Column(db.DateTime, default=datetime.utcnow)
    received_at           = db.Column(db.DateTime, nullable=True)

    def to_dict(self) -> dict:
        product = Product.query.get(self.product_id)
        center = FulfillmentCenter.query.get(self.fulfillment_center_id)
        return {
            "id": self.id, "seller_id": self.seller_id, "product_id": self.product_id,
            "product_name": product.name if product else None,
            "fulfillment_center_id": self.fulfillment_center_id, "fulfillment_center_name": center.name if center else None,
            "quantity_shipped": self.quantity_shipped, "quantity_received": self.quantity_received,
            "tracking_note": self.tracking_note, "status": self.status, "rejection_note": self.rejection_note,
            "requested_at": self.requested_at.isoformat() if self.requested_at else None,
            "received_at": self.received_at.isoformat() if self.received_at else None,
        }


class FulfillmentInventory(db.Model):
    __tablename__       = "fulfillment_inventory"
    id                  = db.Column(db.Integer, primary_key=True)
    fulfillment_center_id = db.Column(db.Integer, db.ForeignKey("fulfillment_centers.id"), nullable=False, index=True)
    product_id          = db.Column(db.Integer, db.ForeignKey("products.id"), nullable=False, index=True)
    seller_id           = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    quantity_available   = db.Column(db.Integer, nullable=False, default=0)
    updated_at           = db.Column(db.DateTime, default=datetime.utcnow)
    __table_args__       = (db.UniqueConstraint("fulfillment_center_id", "product_id", name="uq_fulfillment_inventory_center_product"),)

    def to_dict(self) -> dict:
        center = FulfillmentCenter.query.get(self.fulfillment_center_id)
        return {
            "id": self.id, "fulfillment_center_id": self.fulfillment_center_id,
            "fulfillment_center_name": center.name if center else None,
            "product_id": self.product_id, "quantity_available": self.quantity_available,
            "updated_at": self.updated_at.isoformat() if self.updated_at else None,
        }


class FulfillmentOrderTask(db.Model):
    __tablename__       = "fulfillment_order_tasks"
    id                  = db.Column(db.Integer, primary_key=True)
    order_id            = db.Column(db.Integer, db.ForeignKey("product_orders.id"), nullable=False, unique=True, index=True)
    fulfillment_center_id = db.Column(db.Integer, db.ForeignKey("fulfillment_centers.id"), nullable=False, index=True)
    status               = db.Column(db.String(16), nullable=False, default="pending", index=True)
    tracking_number       = db.Column(db.String(100), nullable=True)
    carrier                = db.Column(db.String(50), nullable=True)
    created_at             = db.Column(db.DateTime, default=datetime.utcnow)
    shipped_at              = db.Column(db.DateTime, nullable=True)

    def to_dict(self) -> dict:
        center = FulfillmentCenter.query.get(self.fulfillment_center_id)
        return {
            "id": self.id, "order_id": self.order_id,
            "fulfillment_center_id": self.fulfillment_center_id, "fulfillment_center_name": center.name if center else None,
            "status": self.status, "tracking_number": self.tracking_number, "carrier": self.carrier,
            "created_at": self.created_at.isoformat() if self.created_at else None,
            "shipped_at": self.shipped_at.isoformat() if self.shipped_at else None,
        }


def _fulfillment_sync_product_stock(product_id: int) -> None:
    """Keeps Product.quantity_available in sync with its fulfillment
    center's own stock the moment either side changes, so every other
    part of this file that already reads quantity_available (buy flow,
    Stage 346 stock-alternatives, low-stock alerts) never has to know
    the listing is warehouse-fulfilled at all."""
    product = Product.query.get(product_id)
    if not product or not product.fulfillment_center_id:
        return
    inv = FulfillmentInventory.query.filter_by(
        fulfillment_center_id=product.fulfillment_center_id, product_id=product_id).first()
    product.quantity_available = inv.quantity_available if inv else 0
    db.session.commit()


def _fulfillment_sync_order_paid(order: "ProductOrder") -> None:
    """Called from _handle_marketplace_order_paid, right after the
    ordinary quantity_available decrement. If this order was against a
    warehouse-fulfilled listing, decrements the center's own inventory
    row the same amount (keeping the mirror honest) and opens a
    pick/pack/ship task for the center to work."""
    product = Product.query.get(order.product_id)
    if not product or not product.fulfillment_center_id:
        return
    inv = FulfillmentInventory.query.filter_by(
        fulfillment_center_id=product.fulfillment_center_id, product_id=product.id).first()
    if inv:
        inv.quantity_available = max(0, inv.quantity_available - order.quantity)
        inv.updated_at = datetime.utcnow()
        db.session.commit()
    if not FulfillmentOrderTask.query.filter_by(order_id=order.id).first():
        db.session.add(FulfillmentOrderTask(order_id=order.id, fulfillment_center_id=product.fulfillment_center_id))
        db.session.commit()


