@app.route("/api/marketplace/products/<int:product_id>/fulfillment/inbound", methods=["POST"])
@csrf.exempt
def fulfillment_inbound_create(product_id):
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    product = Product.query.filter_by(id=product_id, seller_id=user["id"]).first()
    if not product:
        return jsonify({"error": "Listing not found on your account."}), 404
    data = request.get_json(silent=True) or {}
    center = FulfillmentCenter.query.filter_by(id=data.get("fulfillment_center_id"), is_active=True).first()
    if not center:
        return jsonify({"error": "Fulfillment center not found."}), 404
    try:
        quantity = max(1, int(data.get("quantity")))
    except (TypeError, ValueError):
        return jsonify({"error": "quantity must be a whole number."}), 400
    shipment = FulfillmentInboundShipment(
        seller_id=user["id"], product_id=product.id, fulfillment_center_id=center.id,
        quantity_shipped=quantity, tracking_note=(data.get("tracking_note") or "").strip()[:300] or None)
    db.session.add(shipment)
    db.session.commit()
    return jsonify({"ok": True, "shipment": shipment.to_dict()}), 201


