@app.route("/api/surplus-matching/inquiry", methods=["POST"])
@csrf.exempt
def surplus_inquiry_create():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    try:
        surplus_listing_id = int(data.get("surplus_listing_id"))
    except (TypeError, ValueError):
        return jsonify({"error": "surplus_listing_id is required."}), 400
    message = (data.get("message") or "").strip()[:1000]
    if not message:
        return jsonify({"error": "message is required."}), 400

    listing = SurplusListing.query.get(surplus_listing_id)
    if not listing or not listing.is_active:
        return jsonify({"error": "Listing not found."}), 404
    if listing.user_id == user["id"]:
        return jsonify({"error": "You can't send an inquiry to your own listing."}), 400

    inquiry = SurplusInquiry(
        surplus_listing_id=surplus_listing_id, from_user_id=user["id"], to_user_id=listing.user_id, message=message,
    )
    db.session.add(inquiry)
    db.session.commit()
    return jsonify({"ok": True, "inquiry": inquiry.to_dict()}), 201


