@app.route("/api/surplus-matching/inquiries/<int:inquiry_id>/reply", methods=["POST"])
@csrf.exempt
def surplus_inquiry_reply(inquiry_id):
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    inquiry = SurplusInquiry.query.filter_by(id=inquiry_id, to_user_id=user["id"]).first()
