@app.route("/api/surplus-matching/inquiries/<int:inquiry_id>/close", methods=["POST"])
@csrf.exempt
def surplus_inquiry_close(inquiry_id):
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    inquiry = SurplusInquiry.query.filter(
        SurplusInquiry.id == inquiry_id,
        db.or_(SurplusInquiry.from_user_id == user["id"], SurplusInquiry.to_user_id == user["id"]),
    ).first()
    if not inquiry:
        return jsonify({"error": "Inquiry not found."}), 404
    inquiry.status = "closed"
    db.session.commit()
    return jsonify({"ok": True}), 200


# ════════════════════════════════════════════════════════════
# STAGE 224: ESCROW & DISPUTE RESOLUTION
# Third piece of the network-effect layer, closing the loop opened by
# Stage 222 (B2B Marketplace Directory) and Stage 223 (Smart Surplus
# Matching): once two strangers have found each other through the
# platform, this is what makes it safe to actually pay one another.
#
# Design choices, all deliberate:
#   • The PLATFORM, not the seller, is the Paystack merchant of record
#     for an escrow payment — funds are collected into Connect It's own
#     platform account (PAYSTACK_SECRET_KEY), never a BYOK key. A BYOK
#     key belongs to whoever is *receiving* the money, and in escrow
#     that has to be the platform until release. This is the one
#     payment flow on the platform that deliberately bypasses
#     get_effective_credential/BYOK — by design, not by omission.
#   • An escrow can optionally reference a real MarketplaceInquiry or
#     SurplusInquiry (trade_type + ref_id), tying it to an actual
#     conversation already on the platform — the same "gives a later
#     stage something to hang off" hook Stage 222's comment called out
#     — or it can stand alone for any other agreed trade between two
#     account holders.
#   • Release requires the buyer's explicit confirmation of delivery —
#     never automatic just because payment succeeded. Opening a dispute
#     freezes release until it's resolved.
#   • Two honest asymmetric capabilities, not one fake symmetric one:
#     a REFUND is fully automated (Paystack's refund API needs only the
#     platform's own secret key + tx_ref — no counterparty setup), so a
#     dispute resolved in the buyer's favor actually moves money back
#     immediately. A SELLER PAYOUT is NOT automated — there's no
#     recipient/bank-account infrastructure built yet anywhere on this
#     platform (the existing Wise transfer flow is the closest thing,
#     and it isn't wired to sellers here) — so "released" and
#     "resolved_split" set payout_status="pending_manual_transfer"
#     rather than pretending a transfer happened. Same honesty
#     principle as the rest of the platform: make the real gap visible
#     instead of faking a rail that doesn't exist.
#   • Disputes: either party can open one while an escrow is funded.
#     Both sides post evidence/messages to a shared thread. Either side
#     can PROPOSE a resolution (release/refund/split); if the other
#     side ACCEPTS that same proposal it resolves immediately — mutual
#     resolution, no admin needed. If they don't agree, any is_admin
#     account can force-resolve it — the same admin gate already used
#     for AuditLog/PrivacyRequest elsewhere on the platform.
# ════════════════════════════════════════════════════════════

ESCROW_TRADE_TYPES  = ["marketplace", "surplus", "barter", "tender", "custom", "carbon_credit"]
ESCROW_RESOLUTIONS  = ["release", "refund", "split"]


def _platform_paystack_secret():
    """Escrow always uses the PLATFORM's own Paystack secret key — never
    BYOK — because the platform, not the buyer or seller, must be the
    account actually holding the funds while they're in escrow."""
    return PAYSTACK_SECRET_KEY


class EscrowTransaction(db.Model):
    __tablename__ = "escrow_transactions"
    id             = db.Column(db.Integer, primary_key=True)
    trade_type     = db.Column(db.String(20), nullable=False, default="custom", index=True)
    ref_id         = db.Column(db.Integer, nullable=True, index=True)  # MarketplaceInquiry.id / SurplusInquiry.id
    buyer_id       = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    seller_id      = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    description    = db.Column(db.String(300), nullable=False)
    amount         = db.Column(db.Float, nullable=False)
    currency       = db.Column(db.String(8), nullable=False, default="NGN")
    status         = db.Column(db.String(20), nullable=False, default="pending_payment", index=True)
    # pending_payment, funded, released, refunded, resolved_split, disputed, cancelled
    payout_status  = db.Column(db.String(24), nullable=False, default="not_due")
    # not_due, pending_manual_transfer, paid_out
    payment_tx_ref = db.Column(db.String(64), nullable=True, index=True)
    buyer_confirmed_at = db.Column(db.DateTime, nullable=True)
    created_at     = db.Column(db.DateTime, default=datetime.utcnow, index=True)
    funded_at      = db.Column(db.DateTime, nullable=True)
    released_at    = db.Column(db.DateTime, nullable=True)
    refunded_at    = db.Column(db.DateTime, nullable=True)
    updated_at     = db.Column(db.DateTime, default=datetime.utcnow, onupdate=datetime.utcnow)

    def to_dict(self, viewer_id=None):
        buyer   = UserAccount.query.get(self.buyer_id)
        seller  = UserAccount.query.get(self.seller_id)
        dispute = (EscrowDispute.query.filter_by(escrow_id=self.id)
                   .order_by(EscrowDispute.created_at.desc()).first())
        # STAGE 345: lightweight embedded summary (not the full policy
        # dict) so "My Escrows" can show insurance status without an
        # extra fetch per row, the same way active_dispute is embedded.
        tci_policy = TradeCreditInsurancePolicy.query.filter_by(escrow_id=self.id).first()
        lc = LetterOfCredit.query.filter_by(escrow_id=self.id).first()
        return {
            "id": self.id, "trade_type": self.trade_type, "ref_id": self.ref_id,
            "buyer_id": self.buyer_id, "buyer_name": buyer.name if buyer else None,
            "seller_id": self.seller_id, "seller_name": seller.name if seller else None,
            "description": self.description, "amount": self.amount, "currency": self.currency,
            "status": self.status, "payout_status": self.payout_status,
            "role": ("buyer" if viewer_id == self.buyer_id else
                     "seller" if viewer_id == self.seller_id else None),
            "your_confirmation_needed": bool(viewer_id) and viewer_id == self.buyer_id and self.status == "funded",
            "active_dispute": (dispute.to_dict() if dispute and dispute.status != "resolved" else None),
            "trade_credit_insurance": ({
                "status": tci_policy.status, "coverage_amount": tci_policy.coverage_amount,
                "premium_amount": tci_policy.premium_amount, "coverage_pct": tci_policy.coverage_pct,
            } if tci_policy else None),
            "letter_of_credit": ({
                "id": lc.id, "status": lc.status,
                "outstanding_documents": [d for d in lc.required_documents_list()
                                          if d not in {doc.document_type for doc in
                                                       LetterOfCreditDocument.query.filter_by(lc_id=lc.id).all()}],
            } if lc else None),
            "created_at":  self.created_at.isoformat() if self.created_at else None,
            "funded_at":   self.funded_at.isoformat() if self.funded_at else None,
            "released_at": self.released_at.isoformat() if self.released_at else None,
            "refunded_at": self.refunded_at.isoformat() if self.refunded_at else None,
        }


class EscrowDispute(db.Model):
    __tablename__ = "escrow_disputes"
    id             = db.Column(db.Integer, primary_key=True)
    escrow_id      = db.Column(db.Integer, db.ForeignKey("escrow_transactions.id"), nullable=False, index=True)
    opened_by_id   = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False)
    reason         = db.Column(db.String(500), nullable=False)
    status         = db.Column(db.String(16), nullable=False, default="open", index=True)  # open, resolved
    proposed_resolution = db.Column(db.String(10), nullable=True)  # release, refund, split
    proposed_by_id = db.Column(db.Integer, nullable=True)
    resolution     = db.Column(db.String(10), nullable=True)
    resolved_by    = db.Column(db.String(10), nullable=True)   # mutual, admin, peer_jury
    resolved_by_admin_id = db.Column(db.Integer, nullable=True)
    resolution_note = db.Column(db.String(500), nullable=True)
    created_at     = db.Column(db.DateTime, default=datetime.utcnow, index=True)
    resolved_at    = db.Column(db.DateTime, nullable=True)
    # STAGE 517: COMMUNITY-LED (PEER JURY) DISPUTE RESOLUTION — new
    # column, auto-migrated on startup (or run once on production MySQL):
    #   ALTER TABLE escrow_disputes ADD COLUMN jury_status VARCHAR(20) NOT NULL DEFAULT 'none';
    # "none" (default, unaffected for every dispute created before this
    # stage) -> "pending_votes" once escalated -> "decided" once the
    # panel has voted and a majority resolution has been applied.
    jury_status    = db.Column(db.String(20), nullable=False, default="none")

    def to_dict(self):
        opener = UserAccount.query.get(self.opened_by_id)
        d = {
            "id": self.id, "escrow_id": self.escrow_id,
            "opened_by_id": self.opened_by_id, "opened_by_name": opener.name if opener else None,
            "reason": self.reason, "status": self.status,
            "proposed_resolution": self.proposed_resolution, "proposed_by_id": self.proposed_by_id,
            "resolution": self.resolution, "resolved_by": self.resolved_by,
            "resolution_note": self.resolution_note,
            "created_at": self.created_at.isoformat() if self.created_at else None,
            "resolved_at": self.resolved_at.isoformat() if self.resolved_at else None,
            "jury_status": self.jury_status,
        }
        if self.jury_status != "none":
            assignments = PeerJuryAssignment.query.filter_by(dispute_id=self.id).all()
            d["jury"] = {
                "panel_size": len(assignments),
                "votes_cast": len([a for a in assignments if a.voted_at]),
            }
            if self.jury_status == "decided":
                tally = {}
                for a in assignments:
                    if a.vote_resolution:
                        tally[a.vote_resolution] = tally.get(a.vote_resolution, 0) + 1
                d["jury"]["tally"] = tally
        return d


class EscrowDisputeMessage(db.Model):
    __tablename__ = "escrow_dispute_messages"
    id          = db.Column(db.Integer, primary_key=True)
    dispute_id  = db.Column(db.Integer, db.ForeignKey("escrow_disputes.id"), nullable=False, index=True)
    sender_id   = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False)
    message     = db.Column(db.String(1000), nullable=False)
    created_at  = db.Column(db.DateTime, default=datetime.utcnow, index=True)

    def to_dict(self):
        sender = UserAccount.query.get(self.sender_id)
        return {
            "id": self.id, "dispute_id": self.dispute_id,
            "sender_id": self.sender_id, "sender_name": sender.name if sender else None,
            "message": self.message,
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }


def _escrow_counterparty_from_ref(trade_type, ref_id, buyer_id):
    """For an escrow tied to a real MarketplaceInquiry/SurplusInquiry,
    derive the seller as 'whichever side of that inquiry isn't the
    buyer' — never trust a client-supplied seller_id for these two
    trade types, only the real inquiry row."""
    if trade_type == "marketplace":
        inquiry = MarketplaceInquiry.query.get(ref_id)
    elif trade_type == "surplus":
        inquiry = SurplusInquiry.query.get(ref_id)
    else:
        return None
    if not inquiry:
        return None
    if inquiry.from_user_id == buyer_id:
        return inquiry.to_user_id
    if inquiry.to_user_id == buyer_id:
        return inquiry.from_user_id
    return None


# ════════════════════════════════════════════════════════════
# ESCROW → DEAL CONFIRMATION / DEAL REVIEW WIRING
# Smart Surplus Matching's sibling (the B2B Marketplace Directory) and
# Escrow above all connect into the same network layer — this closes
# the loop by feeding an escrow's own outcome into the same trust rail
# barter and delivery deals already use, instead of running escrow
# trust as a disconnected island. Reuses _ensure_deal_confirmation()
# (Stage 83, defined earlier in this file) rather than a parallel
# mechanism, so an escrow-brokered trade shows up in /api/deals/mine
# and becomes eligible for a real DealReview the same way any other
# confirmed deal on this platform does.
# ════════════════════════════════════════════════════════════

def _sync_deal_confirmation_from_escrow(escrow, dispute_reason=None):
    """Call this at every point an escrow's status changes. Idempotent
    and safe to call even while the escrow is still pending_payment or
    funded — it just leaves the DealConfirmation at its default
    'pending' status until there's an actual outcome to reflect."""
    deal = _ensure_deal_confirmation("escrow", escrow.id, escrow.buyer_id, escrow.seller_id)
    if not deal:
        return
    if escrow.status in ("released", "resolved_split"):
        # The buyer's own confirmation (or an accepted/admin dispute
        # resolution) is stronger proof of completion than the generic
        # mutual-click flow other deal types rely on — both sides are
        # marked confirmed directly rather than waiting on a second click.
        deal.party_a_confirmed = True
        deal.party_b_confirmed = True
        deal.status = "confirmed"
        deal.confirmed_at = deal.confirmed_at or datetime.utcnow()
    elif escrow.status == "disputed":
        deal.status = "disputed"
        if dispute_reason:
            deal.dispute_reason = dispute_reason[:300]
    elif escrow.status == "refunded":
        # Money went back to the buyer — nothing was actually
        # delivered, so this deliberately does NOT become "confirmed"
        # (no DealReview should be possible for it). Kept distinct
        # from "disputed" so the UI can tell "still unresolved" apart
        # from "resolved, and the resolution was a refund".
        deal.status = "refunded"
        deal.dispute_reason = deal.dispute_reason or "Escrow refunded to buyer — no goods/service confirmed received."
    try:
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        logging.error(f"[DEAL CONFIRMATION SYNC ERROR] escrow #{escrow.id}: {e}")
    # STAGE 345: if this escrow carries an active trade credit insurance
    # policy, its outcome either files a claim or retires the policy.
    # Defined later in this file (Stage 345 block) — resolved at call
    # time, so definition order here doesn't matter.
    _trade_credit_insurance_check_claim(escrow)
    # STAGE 352: DIGITIZED LETTERS OF CREDIT — a draft LC becomes
    # 'issued' the moment its underlying escrow is actually funded.
    try:
        _lc_check_issue(escrow)
    except Exception as e:
        logging.error(f"[LC ISSUE CHECK ERROR] escrow #{escrow.id}: {e}")


@app.route("/api/escrow/create", methods=["POST"])
@csrf.exempt
def escrow_create():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}

    trade_type = (data.get("trade_type") or "custom").strip().lower()
    if trade_type not in ESCROW_TRADE_TYPES:
        return jsonify({"error": "Invalid trade_type."}), 400

    ref_id = None
    seller_id = None
    if trade_type in ("marketplace", "surplus"):
        try:
            ref_id = int(data.get("ref_id"))
        except (TypeError, ValueError):
            return jsonify({"error": "ref_id (the inquiry id) is required for this trade_type."}), 400
        seller_id = _escrow_counterparty_from_ref(trade_type, ref_id, user["id"])
        if not seller_id:
            return jsonify({"error": "Could not match that inquiry to you as buyer."}), 404
    else:
        try:
            seller_id = int(data.get("seller_id"))
        except (TypeError, ValueError):
            return jsonify({"error": "seller_id is required."}), 400
        if seller_id == user["id"]:
            return jsonify({"error": "You can't open an escrow with yourself."}), 400
        if not UserAccount.query.get(seller_id):
            return jsonify({"error": "Seller account not found."}), 404

    description = (data.get("description") or "").strip()[:300]
    if not description:
        return jsonify({"error": "description is required."}), 400
    try:
        amount = float(data.get("amount"))
    except (TypeError, ValueError):
        return jsonify({"error": "amount must be a number."}), 400
    if not validate_amount(amount):
        return jsonify({"error": "Invalid amount."}), 400
    currency = (data.get("currency") or "NGN").strip().upper()[:8]

    escrow = EscrowTransaction(
        trade_type=trade_type, ref_id=ref_id, buyer_id=user["id"], seller_id=seller_id,
        description=description, amount=amount, currency=currency,
    )
    db.session.add(escrow)
    db.session.commit()
    _sync_deal_confirmation_from_escrow(escrow)
    return jsonify({"ok": True, "escrow": escrow.to_dict(viewer_id=user["id"])}), 201


@app.route("/api/escrow/mine", methods=["GET"])
def escrow_mine():
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    role = (request.args.get("role") or "").strip()
    q = EscrowTransaction.query
    if role == "buyer":
        q = q.filter_by(buyer_id=user["id"])
    elif role == "seller":
        q = q.filter_by(seller_id=user["id"])
    else:
        q = q.filter(db.or_(EscrowTransaction.buyer_id == user["id"], EscrowTransaction.seller_id == user["id"]))
    rows = q.order_by(EscrowTransaction.created_at.desc()).limit(200).all()
    return jsonify({"escrows": [e.to_dict(viewer_id=user["id"]) for e in rows]}), 200


def _escrow_for_party(escrow_id, user_id):
    return EscrowTransaction.query.filter(
        EscrowTransaction.id == escrow_id,
        db.or_(EscrowTransaction.buyer_id == user_id, EscrowTransaction.seller_id == user_id),
    ).first()


