@app.route("/api/escrow/<int:escrow_id>/cancel", methods=["POST"])
@csrf.exempt
def escrow_cancel(escrow_id):
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    escrow = EscrowTransaction.query.filter_by(id=escrow_id, buyer_id=user["id"]).first()
    if not escrow:
        return jsonify({"error": "Escrow not found."}), 404
    if escrow.status != "pending_payment":
        return jsonify({"error": "Only an unfunded escrow can be cancelled."}), 400
    escrow.status = "cancelled"
    db.session.commit()
    if escrow.trade_type == "carbon_credit" and escrow.ref_id:
        order = CarbonCreditOrder.query.get(escrow.ref_id)
        if order and order.status == "pending_escrow":
            order.status = "cancelled"
            _carbon_credit_restore_tonnes(order)
            db.session.commit()
    # STAGE 345: an insurance policy on a trade that never got funded has
    # nothing left to cover — retire it rather than leave it dangling.
    tci_policy = TradeCreditInsurancePolicy.query.filter_by(escrow_id=escrow.id).first()
    if tci_policy and tci_policy.status in ("pending_quote", "pending_partner", "active"):
        tci_policy.status = "cancelled"
        db.session.commit()
    return jsonify({"ok": True}), 200


@app.route("/api/escrow/<int:escrow_id>/fund/initialize", methods=["POST"])
@csrf.exempt
def escrow_fund_initialize(escrow_id):
    """Buyer pays into the PLATFORM's Paystack account — this is what
    'funds the escrow'. Uses the platform secret key, never BYOK; see
    the Stage 224 header comment for why."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    escrow = EscrowTransaction.query.filter_by(id=escrow_id, buyer_id=user["id"]).first()
    if not escrow:
        return jsonify({"error": "Escrow not found."}), 404
    if escrow.status != "pending_payment":
        return jsonify({"error": f"Escrow is already {escrow.status}."}), 400

    secret_key = _platform_paystack_secret()
    if not secret_key:
        return jsonify({"error": "Escrow payments aren't configured on this platform yet."}), 503

    buyer_account = UserAccount.query.get(user["id"])
    email = sanitize_email(buyer_account.email if buyer_account else "")
    if not email:
        return jsonify({"error": "A valid account email is required to fund escrow."}), 400

    tx_ref = generate_tx_ref("ESC")
    try:
        resp = requests.post(
            "https://api.paystack.co/transaction/initialize",
            headers={"Authorization": f"Bearer {secret_key}", "Content-Type": "application/json"},
            json={
                "email": email,
                "amount": int(round(escrow.amount * 100)),
                "currency": escrow.currency,
                "reference": tx_ref,
                "callback_url": f"{request.host_url}?escrow=funded&id={escrow.id}",
                "metadata": {"escrow_id": escrow.id, "purpose": "escrow_fund"},
            },
            timeout=15,
        )
        pk_data = resp.json()
        if not (resp.ok and pk_data.get("status")):
            raise ValueError(pk_data.get("message", "Paystack error"))
        escrow.payment_tx_ref = tx_ref
        db.session.commit()
        logging.info(f"[ESCROW] Fund initiated: escrow #{escrow.id} | {escrow.currency} {escrow.amount:.2f} | {tx_ref}")
        return jsonify({"ok": True, "link": pk_data["data"]["authorization_url"], "tx_ref": tx_ref}), 200
    except Exception as e:
        logging.error(f"[ESCROW FUND ERROR] escrow #{escrow.id}: {e}")
        return jsonify({"error": str(e)}), 500


@app.route("/api/escrow/<int:escrow_id>/fund/verify", methods=["GET"])
def escrow_fund_verify(escrow_id):
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    escrow = _escrow_for_party(escrow_id, user["id"])
    if not escrow:
        return jsonify({"error": "Escrow not found."}), 404
    if escrow.status == "funded":
        return jsonify({"ok": True, "escrow": escrow.to_dict(viewer_id=user["id"])}), 200
    if not escrow.payment_tx_ref:
        return jsonify({"error": "No payment has been initiated for this escrow yet."}), 400

    secret_key = _platform_paystack_secret()
    if not secret_key:
        return jsonify({"error": "Escrow payments aren't configured on this platform yet."}), 503
    try:
        resp = requests.get(
            f"https://api.paystack.co/transaction/verify/{escrow.payment_tx_ref}",
            headers={"Authorization": f"Bearer {secret_key}"}, timeout=10,
        )
        pk_data = resp.json()
        if not pk_data.get("status"):
            return jsonify({"error": pk_data.get("message", "Verification failed")}), 400
        tx = pk_data["data"]
        paid_ok = tx.get("status") == "success" and abs((tx.get("amount", 0) / 100) - escrow.amount) < 0.01
        if paid_ok and escrow.status == "pending_payment":
            escrow.status = "funded"
            escrow.funded_at = datetime.utcnow()
            db.session.commit()
        return jsonify({"ok": True, "verified": paid_ok, "escrow": escrow.to_dict(viewer_id=user["id"])}), 200
    except Exception as e:
        return jsonify({"error": str(e)}), 500


@app.route("/api/escrow/<int:escrow_id>/confirm", methods=["POST"])
@csrf.exempt
def escrow_confirm(escrow_id):
    """Buyer confirms goods/service were received as agreed → releases
    the escrow. Never triggered by payment success alone."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    escrow = EscrowTransaction.query.filter_by(id=escrow_id, buyer_id=user["id"]).first()
    if not escrow:
        return jsonify({"error": "Escrow not found."}), 404
    if escrow.status != "funded":
        return jsonify({"error": f"Escrow must be funded to confirm (currently {escrow.status})."}), 400
    open_dispute = EscrowDispute.query.filter_by(escrow_id=escrow.id, status="open").first()
    if open_dispute:
        return jsonify({"error": "This escrow has an open dispute — resolve it before releasing."}), 400

    escrow.status = "released"
    escrow.buyer_confirmed_at = datetime.utcnow()
    escrow.released_at = datetime.utcnow()
    escrow.payout_status = "pending_manual_transfer"
    db.session.commit()
    _sync_deal_confirmation_from_escrow(escrow)
    _carbon_credit_on_escrow_settled(escrow)
    return jsonify({"ok": True, "escrow": escrow.to_dict(viewer_id=user["id"])}), 200


def _escrow_refund_via_paystack(escrow) -> bool:
    """Real automated refund — Paystack's /refund endpoint needs only
    the platform's own secret key + the original tx_ref, no recipient
    setup, so this actually moves money back to the buyer (unlike a
    seller payout, which this platform can't automate yet)."""
    secret_key = _platform_paystack_secret()
    if not secret_key or not escrow.payment_tx_ref:
        return False
    try:
        resp = requests.post(
            "https://api.paystack.co/refund",
            headers={"Authorization": f"Bearer {secret_key}", "Content-Type": "application/json"},
            json={"transaction": escrow.payment_tx_ref, "amount": int(round(escrow.amount * 100))},
            timeout=15,
        )
        data = resp.json()
        return bool(resp.ok and data.get("status"))
    except Exception as e:
        logging.error(f"[ESCROW REFUND ERROR] escrow #{escrow.id}: {e}")
        return False


def _apply_escrow_resolution(escrow, resolution, resolved_by, admin_id=None, note=None):
    if resolution == "refund":
        refunded = _escrow_refund_via_paystack(escrow)
        escrow.status = "refunded"
        escrow.refunded_at = datetime.utcnow()
        escrow.payout_status = "not_due" if refunded else "pending_manual_transfer"
    elif resolution == "release":
        escrow.status = "released"
        escrow.released_at = datetime.utcnow()
        escrow.payout_status = "pending_manual_transfer"
    elif resolution == "split":
        escrow.status = "resolved_split"
        escrow.payout_status = "pending_manual_transfer"
    escrow.updated_at = datetime.utcnow()
    db.session.commit()
    _sync_deal_confirmation_from_escrow(escrow)
    _carbon_credit_on_escrow_settled(escrow)


@app.route("/api/escrow/<int:escrow_id>/dispute", methods=["POST"])
@csrf.exempt
def escrow_dispute_open(escrow_id):
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    escrow = _escrow_for_party(escrow_id, user["id"])
    if not escrow:
        return jsonify({"error": "Escrow not found."}), 404
    if escrow.status != "funded":
        return jsonify({"error": "Only a funded escrow can be disputed."}), 400
    if EscrowDispute.query.filter_by(escrow_id=escrow.id, status="open").first():
        return jsonify({"error": "A dispute is already open on this escrow."}), 400
    data = request.get_json(silent=True) or {}
    reason = (data.get("reason") or "").strip()[:500]
    if not reason:
        return jsonify({"error": "reason is required."}), 400

    dispute = EscrowDispute(escrow_id=escrow.id, opened_by_id=user["id"], reason=reason)
    escrow.status = "disputed"
    db.session.add(dispute)
    db.session.commit()
    _sync_deal_confirmation_from_escrow(escrow, dispute_reason=reason)
    return jsonify({"ok": True, "dispute": dispute.to_dict()}), 201


def _dispute_for_party(dispute_id, user_id):
    dispute = EscrowDispute.query.get(dispute_id)
    if not dispute:
        return None, None
    escrow = _escrow_for_party(dispute.escrow_id, user_id)
    if not escrow:
        return None, None
    return dispute, escrow


