@app.route("/api/escrow/dispute/<int:dispute_id>/propose", methods=["POST"])
@csrf.exempt
def escrow_dispute_propose(dispute_id):
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    dispute, escrow = _dispute_for_party(dispute_id, user["id"])
    if not dispute:
        return jsonify({"error": "Dispute not found."}), 404
    if dispute.status != "open":
        return jsonify({"error": "This dispute is already resolved."}), 400
    if dispute.jury_status == "pending_votes":
        return jsonify({"error": "This dispute is currently with a peer jury — wait for their decision."}), 400
    data = request.get_json(silent=True) or {}
    resolution = (data.get("resolution") or "").strip().lower()
    if resolution not in ESCROW_RESOLUTIONS:
        return jsonify({"error": "resolution must be release, refund, or split."}), 400
    dispute.proposed_resolution = resolution
    dispute.proposed_by_id = user["id"]
    db.session.commit()
    return jsonify({"ok": True, "dispute": dispute.to_dict()}), 200


@app.route("/api/escrow/dispute/<int:dispute_id>/accept", methods=["POST"])
@csrf.exempt
def escrow_dispute_accept(dispute_id):
    """The OTHER party accepts the standing proposal → resolves the
    dispute immediately without any admin involvement (mutual
    resolution)."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    dispute, escrow = _dispute_for_party(dispute_id, user["id"])
    if not dispute:
        return jsonify({"error": "Dispute not found."}), 404
    if dispute.status != "open" or not dispute.proposed_resolution:
        return jsonify({"error": "There's no standing proposal to accept."}), 400
    if dispute.jury_status == "pending_votes":
        return jsonify({"error": "This dispute is currently with a peer jury — wait for their decision."}), 400
    if dispute.proposed_by_id == user["id"]:
        return jsonify({"error": "The other party needs to accept your proposal, not you."}), 400

    _apply_escrow_resolution(escrow, dispute.proposed_resolution, resolved_by="mutual")
    dispute.status = "resolved"
    dispute.resolution = dispute.proposed_resolution
    dispute.resolved_by = "mutual"
    dispute.resolved_at = datetime.utcnow()
    db.session.commit()
    return jsonify({"ok": True, "dispute": dispute.to_dict(), "escrow": escrow.to_dict(viewer_id=user["id"])}), 200


@app.route("/api/escrow/dispute/<int:dispute_id>/admin-resolve", methods=["POST"])
@csrf.exempt
def escrow_dispute_admin_resolve(dispute_id):
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    admin_account = UserAccount.query.get(user["id"])
    is_admin = bool(admin_account) and (
        admin_account.is_admin or (admin_account.email or "").strip().lower() in ADMIN_EMAILS
    )
    if not is_admin:
        return jsonify({"error": "Admin access required."}), 403
    dispute = EscrowDispute.query.get(dispute_id)
    if not dispute:
        return jsonify({"error": "Dispute not found."}), 404
    escrow = EscrowTransaction.query.get(dispute.escrow_id)
    if not escrow:
        return jsonify({"error": "Escrow not found."}), 404
    if dispute.status != "open":
        return jsonify({"error": "This dispute is already resolved."}), 400
    data = request.get_json(silent=True) or {}
    resolution = (data.get("resolution") or "").strip().lower()
    if resolution not in ESCROW_RESOLUTIONS:
        return jsonify({"error": "resolution must be release, refund, or split."}), 400
    note = (data.get("note") or "").strip()[:500] or None

    _apply_escrow_resolution(escrow, resolution, resolved_by="admin")
    dispute.status = "resolved"
    dispute.resolution = resolution
    dispute.resolved_by = "admin"
    dispute.resolved_by_admin_id = user["id"]
    dispute.resolution_note = note
    dispute.resolved_at = datetime.utcnow()
    db.session.commit()
    return jsonify({"ok": True, "dispute": dispute.to_dict(), "escrow": escrow.to_dict(viewer_id=user["id"])}), 200


# ════════════════════════════════════════════════════════════
# STAGE 226: AUTONOMOUS BACK-OFFICE AGENT
# A daily sweep across the signals the platform already computes
# elsewhere (cash-crisis check, overdue invoices, low stock, churn-risk
# customers, open escrow disputes, FX drift) that pushes a single
# proactive WhatsApp (or email, if WhatsApp isn't configured/fails)
# digest to the owner instead of making them open five different
# panels to find out something needs attention. Optionally goes beyond
# "telling" into "doing": if auto_reorder_drafts_enabled, it drafts
# (never submits) a Purchase Order for low-stock items so the owner
# only has to review and send it, not build it from scratch. Follows
# the same CRON_SECRET-protected external-scheduler pattern already
# used by tax-deadlines / invoice-chase / cash-crisis-alert above.
# ════════════════════════════════════════════════════════════

class BackOfficeAgentSetting(db.Model):
    __tablename__ = "back_office_agent_settings"
    id             = db.Column(db.Integer, primary_key=True)
    owner_user_id  = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, unique=True, index=True)
    enabled        = db.Column(db.Boolean, nullable=False, default=False)
    whatsapp_number = db.Column(db.String(32), nullable=True)   # owner's own number — alerts land here
    channel        = db.Column(db.String(16), nullable=False, default="whatsapp")  # whatsapp, email, both
    daily_digest_enabled = db.Column(db.Boolean, nullable=False, default=True)
    # Auto-action: drafts (never places) a Purchase Order for low-stock
    # items instead of just flagging them in the digest text.
    auto_reorder_drafts_enabled = db.Column(db.Boolean, nullable=False, default=False)
    low_stock_reorder_multiplier = db.Column(db.Float, nullable=False, default=2.0)
    last_run_at    = db.Column(db.DateTime, nullable=True)
    created_at     = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        return {
            "enabled": self.enabled, "whatsapp_number": self.whatsapp_number, "channel": self.channel,
            "daily_digest_enabled": self.daily_digest_enabled,
            "auto_reorder_drafts_enabled": self.auto_reorder_drafts_enabled,
            "low_stock_reorder_multiplier": self.low_stock_reorder_multiplier,
            "last_run_at": self.last_run_at.isoformat() if self.last_run_at else None,
        }


class BackOfficeAgentRunLog(db.Model):
    __tablename__ = "back_office_agent_run_logs"
    id             = db.Column(db.Integer, primary_key=True)
    owner_user_id  = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    run_at         = db.Column(db.DateTime, default=datetime.utcnow, index=True)
    items_flagged  = db.Column(db.Integer, nullable=False, default=0)
    actions_taken  = db.Column(db.Integer, nullable=False, default=0)
    summary_text   = db.Column(db.Text, nullable=True)
    channel_used   = db.Column(db.String(16), nullable=True)
    delivered      = db.Column(db.Boolean, nullable=False, default=False)

    def to_dict(self):
        return {
            "id": self.id, "run_at": self.run_at.isoformat() if self.run_at else None,
            "items_flagged": self.items_flagged, "actions_taken": self.actions_taken,
            "summary_text": self.summary_text, "channel_used": self.channel_used, "delivered": self.delivered,
        }


def _run_back_office_agent_for_user(uid, settings):
    """Gathers today's flags (and optionally takes the low-stock
    reorder-draft action) for one business. Read-mostly aside from that
    one opt-in action — nothing here sends money or confirms a deal."""
    lines, flagged, actions = [], 0, 0
    today = datetime.utcnow().date()

    cash = _cash_crisis_check(uid)
    if cash.get("at_risk"):
        lines.append(f"Cash may run out in about {cash.get('days_until_zero')} days (est. cash position ${cash.get('cash_position_estimate')}).")
        flagged += 1

    overdue = (ErpInvoice.query.filter_by(owner_user_id=uid)
               .filter(ErpInvoice.status.in_(["sent", "overdue"]))
               .filter(ErpInvoice.due_date.isnot(None), ErpInvoice.due_date < today).all())
    if overdue:
        total_overdue = round(sum((i.total or 0) - (i.amount_paid or 0) for i in overdue), 2)
        lines.append(f"{len(overdue)} overdue invoice(s) worth roughly {total_overdue}.")
        flagged += 1

    low_items = (InventoryItem.query.filter_by(user_id=uid, active=True)
                 .filter(InventoryItem.quantity <= InventoryItem.threshold).all())
    if low_items:
        names = ", ".join(i.name for i in low_items[:5]) + ("…" if len(low_items) > 5 else "")
        lines.append(f"{len(low_items)} item(s) at or below reorder threshold: {names}.")
        flagged += 1
        if settings.auto_reorder_drafts_enabled:
            already_drafted = {
                poi.product_id for poi in
                ErpPurchaseOrderItem.query.join(ErpPurchaseOrder, ErpPurchaseOrder.id == ErpPurchaseOrderItem.po_id)
                .filter(ErpPurchaseOrder.owner_user_id == uid, ErpPurchaseOrder.status == "draft").all()
            }
            new_items = [i for i in low_items if i.id not in already_drafted]
            if new_items:
                po = ErpPurchaseOrder(
                    owner_user_id=uid, po_number=f"AUTO-{int(datetime.utcnow().timestamp())}",
                    status="draft", currency="USD", order_date=today,
                    notes="Auto-drafted by the Back-Office Agent from a low-stock alert. Review supplier, quantities, and pricing before sending.")
                db.session.add(po); db.session.flush()
                subtotal = 0.0
                for item in new_items:
                    target = (item.threshold or 0) * (settings.low_stock_reorder_multiplier or 2.0)
                    qty = max(target - (item.quantity or 0), item.threshold or 1) or 1
                    cost = item.cost_price or 0
                    line_total = round(qty * cost, 2)
                    subtotal += line_total
                    db.session.add(ErpPurchaseOrderItem(po_id=po.id, product_id=item.id, description=item.name,
                                                          quantity=qty, unit_cost=cost, line_total=line_total))
                po.subtotal = round(subtotal, 2); po.total = round(subtotal, 2)
                actions += 1
                lines.append(f"Drafted Purchase Order {po.po_number} for {len(new_items)} low-stock item(s) — open Purchase Orders to review and send it.")

    at_risk = _compute_churn_risk(uid)
    if at_risk:
        lines.append(f"{len(at_risk)} customer(s) look at risk of churning — no repeat purchase in longer than usual.")
        flagged += 1

    open_disputes = (EscrowDispute.query.join(EscrowTransaction, EscrowTransaction.id == EscrowDispute.escrow_id)
                      .filter(EscrowDispute.status == "open",
                              db.or_(EscrowTransaction.buyer_id == uid, EscrowTransaction.seller_id == uid)).all())
    if open_disputes:
        lines.append(f"{len(open_disputes)} open escrow dispute(s) waiting on you in Escrow & Disputes.")
        flagged += 1

    fx = FxVolatilityAdvisorSetting.query.filter_by(owner_user_id=uid).first()
    if fx and fx.anchor_rate and fx.last_checked_rate:
        drift = (fx.last_checked_rate - fx.anchor_rate) / fx.anchor_rate * 100
        if drift >= fx.alert_threshold_pct:
            lines.append(f"Currency has drifted {round(drift, 1)}% since your last repricing — worth reviewing prices.")
            flagged += 1

    summary = ("All clear today — no cash, stock, invoice, customer, or dispute issues flagged."
               if not lines else
               "Connect It Back-Office Agent — today's flags:\n\n" + "\n".join(f"• {l}" for l in lines))

    db.session.commit()
    return {"flagged": flagged, "actions": actions, "summary": summary}


def _deliver_back_office_agent_result(uid, settings, result):
    delivered = False
    channel_used = settings.channel or "whatsapp"
    if settings.daily_digest_enabled:
        if channel_used in ("whatsapp", "both") and settings.whatsapp_number:
            try:
                send_whatsapp_cloud_message(uid, settings.whatsapp_number, result["summary"][:4000])
                delivered = True
            except Exception as e:
                logging.error(f"[BACK-OFFICE AGENT] WhatsApp send failed for user {uid}: {e}")
        if channel_used in ("email", "both") or (channel_used == "whatsapp" and not delivered):
            u = UserAccount.query.get(uid)
            if u and u.email:
                try:
                    if _send_plain_email(u.email, "Your daily back-office brief — Connect It", result["summary"]):
                        delivered = True
                except Exception as e:
                    logging.error(f"[BACK-OFFICE AGENT] Email send failed for user {uid}: {e}")
    log = BackOfficeAgentRunLog(owner_user_id=uid, items_flagged=result["flagged"], actions_taken=result["actions"],
                                 summary_text=result["summary"], channel_used=channel_used, delivered=delivered)
    db.session.add(log)
    settings.last_run_at = datetime.utcnow()
    db.session.commit()
    return log


@app.route("/api/back-office-agent/settings", methods=["GET"])
def back_office_agent_settings_get():
    user, err = _erp_user_or_401()
    if err: return err
    row = BackOfficeAgentSetting.query.filter_by(owner_user_id=user["id"]).first()
    if not row:
        return jsonify({"settings": {
            "enabled": False, "whatsapp_number": None, "channel": "whatsapp",
            "daily_digest_enabled": True, "auto_reorder_drafts_enabled": False,
            "low_stock_reorder_multiplier": 2.0, "last_run_at": None,
        }}), 200
    return jsonify({"settings": row.to_dict()}), 200


@app.route("/api/back-office-agent/settings", methods=["PUT"])
@csrf.exempt
def back_office_agent_settings_put():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    row = BackOfficeAgentSetting.query.filter_by(owner_user_id=user["id"]).first()
    if not row:
        row = BackOfficeAgentSetting(owner_user_id=user["id"]); db.session.add(row)
    if "enabled" in data: row.enabled = bool(data["enabled"])
    if "whatsapp_number" in data: row.whatsapp_number = sanitize_phone(data.get("whatsapp_number") or "") or None
    if "channel" in data and data["channel"] in ("whatsapp", "email", "both"): row.channel = data["channel"]
    if "daily_digest_enabled" in data: row.daily_digest_enabled = bool(data["daily_digest_enabled"])
    if "auto_reorder_drafts_enabled" in data: row.auto_reorder_drafts_enabled = bool(data["auto_reorder_drafts_enabled"])
    if "low_stock_reorder_multiplier" in data:
        try: row.low_stock_reorder_multiplier = max(1.0, float(data["low_stock_reorder_multiplier"]))
        except (TypeError, ValueError): pass
    try:
        db.session.commit()
    except Exception as e:
        db.session.rollback(); logging.error(f"[BACK-OFFICE AGENT SETTINGS] {e}")
        return jsonify({"error": "Could not save settings."}), 500
    return jsonify({"settings": row.to_dict()}), 200


@app.route("/api/back-office-agent/run-now", methods=["POST"])
@csrf.exempt
def back_office_agent_run_now():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    row = BackOfficeAgentSetting.query.filter_by(owner_user_id=user["id"]).first()
    if not row:
        row = BackOfficeAgentSetting(owner_user_id=user["id"]); db.session.add(row); db.session.commit()
    result = _run_back_office_agent_for_user(user["id"], row)
    log = _deliver_back_office_agent_result(user["id"], row, result)
    return jsonify({"ok": True, "result": result, "delivered": log.delivered, "log": log.to_dict()}), 200


@app.route("/api/back-office-agent/logs", methods=["GET"])
def back_office_agent_logs():
    user, err = _erp_user_or_401()
    if err: return err
    rows = (BackOfficeAgentRunLog.query.filter_by(owner_user_id=user["id"])
            .order_by(BackOfficeAgentRunLog.run_at.desc()).limit(30).all())
    return jsonify({"logs": [r.to_dict() for r in rows]}), 200


@app.route("/api/cron/back-office-agent-run", methods=["POST"])
@csrf.exempt
def cron_back_office_agent_run():
    """Point an external scheduler at this once a day — same
    CRON_SECRET pattern as /api/cron/invoice-chase-run etc. Throttled
    per-owner to once per calendar day via last_run_at so a scheduler
    firing more often than daily can't spam the same digest twice."""
    if not CRON_SECRET or request.headers.get("X-Cron-Secret") != CRON_SECRET:
        return jsonify({"error": "Not found."}), 404
    today = datetime.utcnow().date()
    rows = BackOfficeAgentSetting.query.filter_by(enabled=True).all()
    ran = 0
    for row in rows:
        if row.last_run_at and row.last_run_at.date() == today:
            continue
        try:
            result = _run_back_office_agent_for_user(row.owner_user_id, row)
            _deliver_back_office_agent_result(row.owner_user_id, row, result)
            ran += 1
        except Exception as e:
            db.session.rollback()
            logging.error(f"[BACK-OFFICE AGENT CRON] user {row.owner_user_id}: {e}")
    return jsonify({"ok": True, "runs": ran, "eligible": len(rows)}), 200


# ════════════════════════════════════════════════════════════
# STAGE 227: AI-RUN INVOICE CHASING & SUPPLIER NEGOTIATION (WHATSAPP)
# Upgrades the STAGE 99/166 templated invoice-chase reminders and the
# STAGE 171 practice-mode Negotiation Assistant into a real, two-way AI
# agent that actually converses over WhatsApp — with the business's
# own overdue customers (chasing payment, fielding excuses, offering
# instalments) and with its own suppliers (asking for a discount,
# extended terms, or a better price on a new order) — instead of a
# human having to type every message by hand.
#
# One thread = one live negotiation. Every inbound WhatsApp reply from
# the counterparty is checked against open threads (see the priority
# check added to whatsapp_cloud_webhook_receive above) BEFORE falling
# through to the generic chatbot reply, so a customer replying to a
# chase message gets the agent, not a stock answer.
#
# The AI is instructed to end any message where it has reached (or is
# proposing) a concrete outcome with a hidden control block:
#   <<AGENT_ACTION>>{"action": "...", ...fields}<<END_ACTION>>
# _negotiation_extract_action() strips this out before anything is
# sent over WhatsApp — the counterparty only ever sees natural
# language. Outcomes that fall within the owner's pre-set auto-approve
# thresholds (see NegotiationAgentSetting) are applied immediately;
# anything bigger is queued as "awaiting_owner_approval" and the owner
# is notified, never auto-committed — the same conservative pattern
# already used for auto_reorder_drafts_enabled in the Back-Office
# Agent above (drafts, never submits, without explicit sign-off).
# ════════════════════════════════════════════════════════════

class NegotiationAgentSetting(db.Model):
    __tablename__  = "negotiation_agent_settings"
    id             = db.Column(db.Integer, primary_key=True)
    owner_user_id  = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, unique=True, index=True)
    # Master switches — invoice-chasing and supplier-negotiation can be
    # turned on independently since not every business wants both.
    invoice_chase_ai_enabled      = db.Column(db.Boolean, nullable=False, default=False)
    supplier_negotiation_enabled  = db.Column(db.Boolean, nullable=False, default=False)
    # Where the owner gets notified about escalations / approvals needed.
    owner_whatsapp_number = db.Column(db.String(32), nullable=True)
    # Auto-approve thresholds for SUPPLIER negotiations — an agreed
    # discount/extension inside these bounds is applied automatically;
    # anything past them waits for a human tap of "Approve".
    auto_approve_max_discount_pct   = db.Column(db.Float, nullable=False, default=5.0)
    auto_approve_max_extension_days = db.Column(db.Integer, nullable=False, default=7)
    # Invoice-chase trigger — how many days overdue before the AI agent
    # opens a conversation (mirrors InvoiceChaseSetting.days_after_due
    # but is independent, since a business may run the AI agent at a
    # different cadence than the plain templated reminders).
    chase_trigger_days_overdue = db.Column(db.Integer, nullable=False, default=3)
    created_at     = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        return {
            "invoice_chase_ai_enabled": self.invoice_chase_ai_enabled,
            "supplier_negotiation_enabled": self.supplier_negotiation_enabled,
            "owner_whatsapp_number": self.owner_whatsapp_number,
            "auto_approve_max_discount_pct": self.auto_approve_max_discount_pct,
            "auto_approve_max_extension_days": self.auto_approve_max_extension_days,
            "chase_trigger_days_overdue": self.chase_trigger_days_overdue,
        }


class NegotiationAgentThread(db.Model):
    __tablename__  = "negotiation_agent_threads"
    id                 = db.Column(db.Integer, primary_key=True)
    owner_user_id      = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    kind               = db.Column(db.String(24), nullable=False, index=True)  # invoice_chase, supplier_negotiation
    counterparty_name  = db.Column(db.String(200), nullable=True)
    counterparty_phone = db.Column(db.String(32), nullable=False, index=True)
    invoice_id         = db.Column(db.Integer, db.ForeignKey("erp_invoices.id"), nullable=True, index=True)
    supplier_id        = db.Column(db.Integer, db.ForeignKey("erp_suppliers.id"), nullable=True, index=True)
    po_id              = db.Column(db.Integer, db.ForeignKey("erp_purchase_orders.id"), nullable=True, index=True)
    objective          = db.Column(db.Text, nullable=True)      # what the owner asked the agent to achieve
    constraints_json   = db.Column(db.Text, nullable=True)      # dumped dict: floor/ceiling numbers the AI must respect
    status             = db.Column(db.String(24), nullable=False, default="active", index=True)
    # active, awaiting_owner_approval, settled, declined, closed
    proposed_terms_json = db.Column(db.Text, nullable=True)     # last AGENT_ACTION payload pending approval
    outcome_json        = db.Column(db.Text, nullable=True)     # final settled terms, once applied
    created_at         = db.Column(db.DateTime, default=datetime.utcnow)
    updated_at         = db.Column(db.DateTime, default=datetime.utcnow)
    last_inbound_at    = db.Column(db.DateTime, nullable=True)

    def to_dict(self, include_messages=False):
        d = {
            "id": self.id, "kind": self.kind,
            "counterparty_name": self.counterparty_name, "counterparty_phone": self.counterparty_phone,
            "invoice_id": self.invoice_id, "supplier_id": self.supplier_id, "po_id": self.po_id,
            "objective": self.objective, "status": self.status,
            "constraints": json.loads(self.constraints_json) if self.constraints_json else {},
            "proposed_terms": json.loads(self.proposed_terms_json) if self.proposed_terms_json else None,
            "outcome": json.loads(self.outcome_json) if self.outcome_json else None,
            "created_at": self.created_at.isoformat() if self.created_at else None,
            "updated_at": self.updated_at.isoformat() if self.updated_at else None,
            "last_inbound_at": self.last_inbound_at.isoformat() if self.last_inbound_at else None,
        }
        if include_messages:
            d["messages"] = [m.to_dict() for m in
                              NegotiationAgentMessage.query.filter_by(thread_id=self.id)
                              .order_by(NegotiationAgentMessage.created_at.asc()).all()]
        return d


class NegotiationAgentMessage(db.Model):
    __tablename__  = "negotiation_agent_messages"
    id             = db.Column(db.Integer, primary_key=True)
    thread_id      = db.Column(db.Integer, db.ForeignKey("negotiation_agent_threads.id"), nullable=False, index=True)
    sender         = db.Column(db.String(16), nullable=False)  # agent, counterparty, owner, system
    body           = db.Column(db.Text, nullable=False)
    created_at     = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        return {"sender": self.sender, "body": self.body,
                "created_at": self.created_at.isoformat() if self.created_at else None}


_AGENT_ACTION_RE = re.compile(r"<<AGENT_ACTION>>\s*(\{.*?\})\s*<<END_ACTION>>", re.DOTALL)


def _negotiation_agent_row(uid, create_if_missing=True):
    row = NegotiationAgentSetting.query.filter_by(owner_user_id=uid).first()
    if not row and create_if_missing:
        row = NegotiationAgentSetting(owner_user_id=uid)
        db.session.add(row); db.session.commit()
    return row


def _negotiation_extract_action(raw_text: str):
    """Strips a hidden <<AGENT_ACTION>>{...}<<END_ACTION>> control block out
    of the AI's reply and returns (clean_text_for_whatsapp, action_dict_or_None).
    Never lets malformed JSON break the conversation — worst case the action
    is just ignored and the clean text still goes out."""
    match = _AGENT_ACTION_RE.search(raw_text or "")
    if not match:
        return (raw_text or "").strip(), None
    clean = _AGENT_ACTION_RE.sub("", raw_text).strip()
    try:
        action = json.loads(match.group(1))
    except Exception:
        action = None
    return clean, action


def _negotiation_history_for_thread(thread):
    """Rebuilds a generate_ai_reply-shaped history list from stored
    messages — agent turns are 'assistant', everything else ('counterparty'
    or 'owner') is folded in as 'user' so the model sees the full thread."""
    rows = (NegotiationAgentMessage.query.filter_by(thread_id=thread.id)
            .order_by(NegotiationAgentMessage.created_at.asc()).all())
    history = []
    for m in rows:
        role = "assistant" if m.sender == "agent" else "user"
        history.append({"role": role, "content": m.body})
    return history


def _negotiation_invoice_chase_system_prompt(thread, invoice, customer, days_overdue):
    balance = round((invoice.total or 0) - (invoice.amount_paid or 0), 2)
    return (
        f"You are a calm, professional AI collections agent for a small business, messaging a customer "
        f"named {customer.name} on WhatsApp about their overdue invoice {invoice.invoice_number} "
        f"({invoice.currency} {balance}, now {days_overdue} day(s) overdue). "
        "Be polite but firm — never rude, never threatening. Your goals, in order of preference: "
        "(1) get full payment today, (2) get a specific payment promise date within the next 14 days, "
        "(3) if they genuinely can't pay in full, offer to split the balance into 2-4 equal instalments. "
        "Never offer a discount on the amount owed — you can only discuss timing, not the amount. "
        "If the customer claims they already paid, or disputes the amount, do NOT argue — acknowledge it "
        "and flag it for the business owner to check, since you cannot verify payments yourself. "
        "Keep every message under 60 words, plain text, no markdown. "
        "Whenever you reach one of these outcomes, end your message with a hidden control block on its own "
        "line (the customer will not see it) in exactly this format:\n"
        '<<AGENT_ACTION>>{"action": "promise_to_pay", "date": "YYYY-MM-DD"}<<END_ACTION>>\n'
        "or\n"
        '<<AGENT_ACTION>>{"action": "installment_request", "num_installments": 3, "frequency_days": 14}<<END_ACTION>>\n'
        "or\n"
        '<<AGENT_ACTION>>{"action": "dispute", "reason": "short free-text summary"}<<END_ACTION>>\n'
        "or\n"
        '<<AGENT_ACTION>>{"action": "paid_claim", "reason": "short free-text summary"}<<END_ACTION>>\n'
        "Only include the control block once you have an actual outcome — most messages won't have one."
    )


def _negotiation_supplier_system_prompt(thread, supplier, constraints):
    return (
        f"You are a professional AI procurement negotiator for a small business, messaging a supplier "
        f"named {supplier.name} on WhatsApp. Objective: {thread.objective}. "
        f"You may agree to a discount of up to {constraints.get('max_discount_pct', 0)}% off the current price, "
        f"and/or extended payment terms of up to {constraints.get('max_extension_days', 0)} extra days, "
        "if the supplier pushes back on the initial ask — but always try to get the best terms you can before "
        "conceding, and never exceed those caps under any circumstances. Be courteous and businesslike, this is "
        "an ongoing supplier relationship, not a one-off haggle. Keep every message under 60 words, plain text. "
        "Whenever the supplier agrees to concrete terms (or firmly declines), end your message with a hidden "
        "control block on its own line (the supplier will not see it) in exactly this format:\n"
        '<<AGENT_ACTION>>{"action": "agreed", "discount_pct": 0, "extension_days": 0, "summary": "short free-text"}<<END_ACTION>>\n'
        "or\n"
        '<<AGENT_ACTION>>{"action": "declined", "summary": "short free-text"}<<END_ACTION>>\n'
        "Only include the control block once there is an actual outcome — most messages won't have one."
    )


def _negotiation_send_and_log(thread, text: str, sender="agent"):
    db.session.add(NegotiationAgentMessage(thread_id=thread.id, sender=sender, body=text))
    thread.updated_at = datetime.utcnow()
    db.session.commit()
    try:
        send_whatsapp_cloud_message(thread.owner_user_id, thread.counterparty_phone, text[:4000])
    except Exception as e:
        logging.error(f"[NEGOTIATION AGENT SEND ERROR] thread={thread.id}: {e}")


def _negotiation_notify_owner(setting, text: str):
    if not setting or not setting.owner_whatsapp_number:
        return
    try:
        send_whatsapp_cloud_message(setting.owner_user_id, setting.owner_whatsapp_number, text[:4000])
    except Exception as e:
        logging.error(f"[NEGOTIATION AGENT OWNER NOTIFY ERROR] {e}")


def _negotiation_apply_invoice_action(thread, invoice, customer, action: dict, setting):
    kind = action.get("action")
    if kind == "promise_to_pay":
        thread.outcome_json = json.dumps(action)
        thread.status = "active"  # stays open until actually paid or due date passes again
        db.session.commit()
        _negotiation_notify_owner(setting, f"{customer.name} promised to pay invoice {invoice.invoice_number} by {action.get('date','—')} (AI chase agent).")
    elif kind == "installment_request":
        # Reuses the STAGE 166 instalment machinery, driven by the
        # negotiated numbers instead of the static settings-based split.
        num_parts = max(2, min(12, int(action.get("num_installments") or 3)))
        freq = max(3, int(action.get("frequency_days") or 14))
        balance = round((invoice.total or 0) - (invoice.amount_paid or 0), 2)
        if balance > 0:
            per_part = round(balance / num_parts, 2)
            plan = InstallmentPlan(
                invoice_id=invoice.id, owner_user_id=invoice.owner_user_id, customer_id=invoice.customer_id,
                token=secrets.token_urlsafe(24), total_amount=balance, currency=invoice.currency,
                num_installments=num_parts, installment_amount=per_part, frequency_days=freq, status="proposed",
            )
            db.session.add(plan); db.session.flush()
            running = 0.0
            for i in range(num_parts):
                due = datetime.utcnow().date() + timedelta(days=freq * (i + 1))
                amt = balance - running if i == num_parts - 1 else per_part
                running += per_part
                db.session.add(InstallmentPayment(plan_id=plan.id, sequence_number=i + 1, due_date=due, amount=round(amt, 2)))
            link = f"{APP_BASE_URL}/?installment_plan={plan.token}"
            thread.outcome_json = json.dumps({**action, "plan_id": plan.id})
            db.session.commit()
            _negotiation_send_and_log(thread, f"Here's your payment plan: {num_parts} instalments of {invoice.currency} {per_part}, every {freq} days. Review and confirm: {link}")
            _negotiation_notify_owner(setting, f"AI chase agent agreed a {num_parts}-part instalment plan with {customer.name} for invoice {invoice.invoice_number}.")
    elif kind in ("dispute", "paid_claim"):
        thread.status = "awaiting_owner_approval"
        thread.proposed_terms_json = json.dumps(action)
        db.session.commit()
        label = "disputes the amount owed" if kind == "dispute" else "claims this invoice is already paid"
        _negotiation_notify_owner(setting, f"{customer.name} {label} on invoice {invoice.invoice_number} — check Invoice Chasing threads before the agent replies further.")


def _negotiation_apply_supplier_action(thread, supplier, action: dict, setting):
    kind = action.get("action")
    if kind == "declined":
        thread.status = "closed"
        thread.outcome_json = json.dumps(action)
        db.session.commit()
        _negotiation_notify_owner(setting, f"{supplier.name} declined the negotiation ({action.get('summary','no terms agreed')}).")
        return
    if kind != "agreed":
        return
    discount_pct = float(action.get("discount_pct") or 0)
    extension_days = int(action.get("extension_days") or 0)
    within_limits = (discount_pct <= (setting.auto_approve_max_discount_pct or 0)
                      and extension_days <= (setting.auto_approve_max_extension_days or 0))
    if within_limits:
        _negotiation_settle_supplier_thread(thread, supplier, action)
        _negotiation_notify_owner(setting, f"Auto-approved: {supplier.name} agreed {discount_pct}% off / +{extension_days}d terms. Applied automatically.")
    else:
        thread.status = "awaiting_owner_approval"
        thread.proposed_terms_json = json.dumps(action)
        db.session.commit()
        _negotiation_notify_owner(setting, f"{supplier.name} agreed {discount_pct}% off / +{extension_days}d terms — above your auto-approve limits, needs your review in Supplier Negotiations.")


def _negotiation_settle_supplier_thread(thread, supplier, action: dict):
    """Applies an agreed supplier outcome: discounts the linked draft PO
    (if any) and/or notes the extended terms against the supplier record.
    Only ever touches a PO still in 'draft' status — never a placed order."""
    discount_pct = float(action.get("discount_pct") or 0)
    extension_days = int(action.get("extension_days") or 0)
    if thread.po_id and discount_pct > 0:
        po = ErpPurchaseOrder.query.get(thread.po_id)
        if po and po.status == "draft":
            factor = 1 - (discount_pct / 100.0)
            po.subtotal = round((po.subtotal or 0) * factor, 2)
            po.total = round((po.total or 0) * factor, 2)
            po.notes = ((po.notes or "") + f"\nAI negotiation agent secured {discount_pct}% off — applied {datetime.utcnow().date().isoformat()}.").strip()
    if extension_days:
        note = f"AI negotiation agent secured +{extension_days} extra payment days as of {datetime.utcnow().date().isoformat()}."
        supplier = ErpSupplier.query.get(thread.supplier_id)
        if supplier:
            supplier.notes = ((supplier.notes or "") + "\n" + note).strip()
    thread.status = "settled"
    thread.outcome_json = json.dumps(action)
    db.session.commit()


def _negotiation_agent_handle_reply(thread, incoming_text: str):
    """Called from the WhatsApp webhook when an inbound message matches an
    open thread. Feeds the full thread history + incoming message through
    generate_ai_reply with the appropriate persona, applies any resulting
    outcome, then sends the AI's (control-block-stripped) reply back."""
    thread.last_inbound_at = datetime.utcnow()
    db.session.add(NegotiationAgentMessage(thread_id=thread.id, sender="counterparty", body=incoming_text))
    db.session.commit()

    setting = _negotiation_agent_row(thread.owner_user_id)
    history = _negotiation_history_for_thread(thread)

    # STAGE (metering gap fix): fires from the WhatsApp webhook, no
    # browser session, but the thread owner is the clear billable party.
    owner_acct = UserAccount.query.get(thread.owner_user_id)
    if owner_acct:
        gate_result = gate_ai_usage({"id": owner_acct.id, "plan": owner_acct.plan}, "negotiation_agent_reply")
        if gate_result is not None:
            return

    if thread.kind == "invoice_chase":
        invoice = ErpInvoice.query.get(thread.invoice_id)
        customer = ErpCustomer.query.get(invoice.customer_id) if invoice and invoice.customer_id else None
        if not invoice or not customer:
            return
        today = datetime.utcnow().date()
        days_overdue = max(0, (today - invoice.due_date).days) if invoice.due_date else 0
        system_prompt = _negotiation_invoice_chase_system_prompt(thread, invoice, customer, days_overdue)
    else:
        supplier = ErpSupplier.query.get(thread.supplier_id)
        if not supplier:
            return
        constraints = json.loads(thread.constraints_json) if thread.constraints_json else {}
        system_prompt = _negotiation_supplier_system_prompt(thread, supplier, constraints)

    raw_reply, _ = generate_ai_reply(incoming_text, history, user_id=thread.owner_user_id, system_prompt=system_prompt)
    clean_text, action = _negotiation_extract_action(raw_reply)
    if clean_text:
        _negotiation_send_and_log(thread, clean_text, sender="agent")

    if action:
        if thread.kind == "invoice_chase":
            _negotiation_apply_invoice_action(thread, invoice, customer, action, setting)
        else:
            _negotiation_apply_supplier_action(thread, supplier, action, setting)


def _find_active_negotiation_thread(owner_uid, sender_num: str):
    if not owner_uid:
        return None
    return (NegotiationAgentThread.query
            .filter_by(owner_user_id=owner_uid, counterparty_phone=sender_num)
            .filter(NegotiationAgentThread.status.in_(["active", "awaiting_owner_approval"]))
            .order_by(NegotiationAgentThread.updated_at.desc()).first())


