@app.route("/api/negotiation-agent/invoice-chase/start", methods=["POST"])
@csrf.exempt
def negotiation_agent_invoice_chase_start():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    invoice = ErpInvoice.query.filter_by(id=data.get("invoice_id"), owner_user_id=user["id"]).first()
    if not invoice: return jsonify({"error": "Invoice not found."}), 404
    customer = ErpCustomer.query.get(invoice.customer_id) if invoice.customer_id else None
    if not customer or not customer.phone:
        return jsonify({"error": "This customer has no phone number on file."}), 400
    existing = _find_active_negotiation_thread(user["id"], customer.phone)
    if existing and existing.invoice_id == invoice.id:
        return jsonify({"thread": existing.to_dict(include_messages=True), "already_active": True}), 200
    today = datetime.utcnow().date()
    days_overdue = max(0, (today - invoice.due_date).days) if invoice.due_date else 0
    gate_result = gate_ai_usage(user, "negotiation_agent_invoice_chase_start")
    if gate_result is not None:
        return gate_result
    thread = NegotiationAgentThread(
        owner_user_id=user["id"], kind="invoice_chase",
        counterparty_name=customer.name, counterparty_phone=customer.phone,
        invoice_id=invoice.id, objective=f"Collect payment on invoice {invoice.invoice_number}.",
        status="active",
    )
    db.session.add(thread); db.session.commit()
    system_prompt = _negotiation_invoice_chase_system_prompt(thread, invoice, customer, days_overdue)
    opener, _ = generate_ai_reply(
        "Open the conversation now with the customer about their overdue invoice.",
        [], user_id=user["id"], system_prompt=system_prompt)
    clean_text, action = _negotiation_extract_action(opener)
    _negotiation_send_and_log(thread, clean_text or f"Hi {customer.name}, following up on invoice {invoice.invoice_number} — could you let us know when we can expect payment?", sender="agent")
    if action:
        _negotiation_apply_invoice_action(thread, invoice, customer, action, _negotiation_agent_row(user["id"]))
    return jsonify({"thread": thread.to_dict(include_messages=True)}), 200


@app.route("/api/negotiation-agent/supplier/start", methods=["POST"])
@csrf.exempt
def negotiation_agent_supplier_start():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    supplier = ErpSupplier.query.filter_by(id=data.get("supplier_id"), owner_user_id=user["id"]).first()
    if not supplier: return jsonify({"error": "Supplier not found."}), 404
    if not supplier.phone:
        return jsonify({"error": "This supplier has no phone number on file."}), 400
    objective = (data.get("objective") or "").strip()[:500]
    if not objective:
        return jsonify({"error": "Describe what you'd like the agent to negotiate (e.g. '10% discount for paying this order upfront')."}), 400
    po_id = data.get("po_id")
    po = ErpPurchaseOrder.query.filter_by(id=po_id, owner_user_id=user["id"]).first() if po_id else None
    setting = _negotiation_agent_row(user["id"])
    try:
        max_discount = max(0.0, min(100.0, float(data.get("max_discount_pct", setting.auto_approve_max_discount_pct))))
    except (TypeError, ValueError):
        max_discount = setting.auto_approve_max_discount_pct
    try:
        max_extension = max(0, int(data.get("max_extension_days", setting.auto_approve_max_extension_days)))
    except (TypeError, ValueError):
        max_extension = setting.auto_approve_max_extension_days
    constraints = {"max_discount_pct": max_discount, "max_extension_days": max_extension}
    gate_result = gate_ai_usage(user, "negotiation_agent_supplier_start")
    if gate_result is not None:
        return gate_result
    thread = NegotiationAgentThread(
        owner_user_id=user["id"], kind="supplier_negotiation",
        counterparty_name=supplier.name, counterparty_phone=supplier.phone,
        supplier_id=supplier.id, po_id=po.id if po else None,
        objective=objective, constraints_json=json.dumps(constraints), status="active",
    )
    db.session.add(thread); db.session.commit()
    system_prompt = _negotiation_supplier_system_prompt(thread, supplier, constraints)
    opener, _ = generate_ai_reply(
        "Open the conversation now with the supplier about this objective.",
        [], user_id=user["id"], system_prompt=system_prompt)
    clean_text, action = _negotiation_extract_action(opener)
    _negotiation_send_and_log(thread, clean_text or f"Hi {supplier.name}, we'd like to discuss: {objective}", sender="agent")
    if action:
        _negotiation_apply_supplier_action(thread, supplier, action, setting)
    return jsonify({"thread": thread.to_dict(include_messages=True)}), 200


@app.route("/api/negotiation-agent/threads/<int:thread_id>/approve", methods=["POST"])
@csrf.exempt
def negotiation_agent_thread_approve(thread_id):
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    thread = NegotiationAgentThread.query.filter_by(id=thread_id, owner_user_id=user["id"]).first()
    if not thread: return jsonify({"error": "Not found."}), 404
    if thread.status != "awaiting_owner_approval" or not thread.proposed_terms_json:
        return jsonify({"error": "Nothing pending approval on this thread."}), 400
    action = json.loads(thread.proposed_terms_json)
