@app.route("/api/cron/negotiation-agent-invoice-chase-run", methods=["POST"])
@csrf.exempt
def cron_negotiation_agent_invoice_chase_run():
    """Daily sweep: opens an AI chase thread for newly-overdue invoices on
    accounts with invoice_chase_ai_enabled — same CRON_SECRET pattern as
    /api/cron/invoice-chase-run. Skips any invoice that already has an
    open thread so it doesn't restart a live conversation."""
    if not CRON_SECRET or request.headers.get("X-Cron-Secret") != CRON_SECRET:
        return jsonify({"error": "Not found."}), 404
    today = datetime.utcnow().date()
    settings_by_owner = {s.owner_user_id: s for s in NegotiationAgentSetting.query.filter_by(invoice_chase_ai_enabled=True).all()}
    started = 0
    rows = (ErpInvoice.query.filter(ErpInvoice.status.in_(["sent", "overdue"]))
            .filter(ErpInvoice.due_date.isnot(None), ErpInvoice.due_date < today).all())
    for inv in rows:
        setting = settings_by_owner.get(inv.owner_user_id)
        if not setting: continue
        balance = (inv.total or 0) - (inv.amount_paid or 0)
        if balance <= 0: continue
        days_overdue = (today - inv.due_date).days
        if days_overdue < setting.chase_trigger_days_overdue: continue
        already = NegotiationAgentThread.query.filter_by(invoice_id=inv.id).filter(
            NegotiationAgentThread.status.in_(["active", "awaiting_owner_approval"])).first()
        if already: continue
        customer = ErpCustomer.query.get(inv.customer_id) if inv.customer_id else None
        if not customer or not customer.phone: continue
        try:
            thread = NegotiationAgentThread(
                owner_user_id=inv.owner_user_id, kind="invoice_chase",
                counterparty_name=customer.name, counterparty_phone=customer.phone,
                invoice_id=inv.id, objective=f"Collect payment on invoice {inv.invoice_number}.", status="active",
            )
            db.session.add(thread); db.session.commit()
            system_prompt = _negotiation_invoice_chase_system_prompt(thread, inv, customer, days_overdue)
            opener, _ = generate_ai_reply(
                "Open the conversation now with the customer about their overdue invoice.",
                [], user_id=inv.owner_user_id, system_prompt=system_prompt)
            clean_text, action = _negotiation_extract_action(opener)
            _negotiation_send_and_log(thread, clean_text or f"Hi {customer.name}, following up on invoice {inv.invoice_number} — could you let us know when we can expect payment?", sender="agent")
            if action:
                _negotiation_apply_invoice_action(thread, inv, customer, action, setting)
            if inv.status == "sent":
                inv.status = "overdue"; db.session.commit()
            started += 1
        except Exception as e:
            db.session.rollback()
            logging.error(f"[NEGOTIATION AGENT CRON] invoice {inv.id}: {e}")
    return jsonify({"ok": True, "threads_started": started}), 200


# ════════════════════════════════════════════════════════════
# STAGE 345: EMBEDDED TRADE CREDIT INSURANCE
# Insures the SELLER side of a single Escrow-brokered trade against the
# BUYER defaulting on that specific deal. Sold as a one-click add-on at
# escrow checkout (quote → purchase) rather than as a separate product
# a seller has to go looking for -- the checkout step itself surfaces
# the price and lets them attach it before or right after funding.
#
# Same two-gate honesty pattern as Parametric Insurance (Stage 3):
#   • requires_feature_flag("trade_credit_insurance") -- readiness switch
#   • InsurancePartner configured -- the actual legal constraint. A
#     policy purchased before a partner is configured records the
#     premium and sits in "pending_partner" rather than pretending to
#     be bound. Reuses the SAME InsurancePartner table as parametric
#     insurance rather than inventing a parallel underwriter record.
#
# "Default" is scoped to what this platform can actually observe: the
# escrow underneath the policy ending in status="refunded" while the
# policy is active (the held funds went back to the buyer -- the
# seller's expected receivable never arrived). It is NOT a general
# business credit-insurance product covering risk outside the
# platform, and the disclaimer on every quote says so.
# ════════════════════════════════════════════════════════════

TRADE_CREDIT_INSURANCE_RATE_BY_GRADE = {
    # Rate applied to the insured coverage_amount, keyed off the
    # BUYER's own compute_credit_score() risk_grade (Stage-elsewhere) --
    # this product prices the counterparty's default risk, not the
    # policyholder's own score.
    "Low risk":             0.015,
    "Moderate risk":        0.03,
    "Elevated risk":        0.05,
    "High risk":            0.08,
    "Insufficient history": 0.045,  # neutral-but-cautious: no track record either way
}
TRADE_CREDIT_INSURANCE_MIN_COVERAGE_PCT = 0.5
TRADE_CREDIT_INSURANCE_MAX_COVERAGE_PCT = 1.0
TRADE_CREDIT_INSURANCE_DEFAULT_COVERAGE_PCT = 0.9


class TradeCreditInsurancePolicy(db.Model):
    __tablename__             = "trade_credit_insurance_policies"
    id                        = db.Column(db.Integer, primary_key=True)
    escrow_id                 = db.Column(db.Integer, db.ForeignKey("escrow_transactions.id"), nullable=False, unique=True, index=True)
    insured_user_id           = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)  # seller — payout beneficiary
    counterparty_user_id      = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)  # buyer — whose default risk is priced
    coverage_pct              = db.Column(db.Float, nullable=False, default=TRADE_CREDIT_INSURANCE_DEFAULT_COVERAGE_PCT)
    coverage_amount           = db.Column(db.Float, nullable=False)
    premium_amount            = db.Column(db.Float, nullable=False)
    currency                  = db.Column(db.String(8), nullable=False, default="NGN")
    buyer_credit_score_snapshot = db.Column(db.Integer, nullable=True)
    buyer_risk_grade_snapshot   = db.Column(db.String(32), nullable=True)
    underwriting_partner_id   = db.Column(db.Integer, db.ForeignKey("insurance_partners.id"), nullable=True)
    # pending_quote -> pending_partner (premium paid, no partner configured yet) -> active
    #   -> claim_filed -> claim_denied
    #                  -> paid_out
    #   -> expired (escrow completed/split with no default) / cancelled
    status                    = db.Column(db.String(20), nullable=False, default="pending_quote", index=True)
    premium_paid_at           = db.Column(db.DateTime, nullable=True)
    claim_filed_at            = db.Column(db.DateTime, nullable=True)
    claim_note                = db.Column(db.String(500), nullable=True)
    claim_decided_at          = db.Column(db.DateTime, nullable=True)
    claim_decided_by_admin_id = db.Column(db.Integer, nullable=True)
    payout_amount             = db.Column(db.Float, nullable=True)
    created_at                = db.Column(db.DateTime, default=datetime.utcnow, index=True)

    def to_dict(self, viewer_id=None) -> dict:
        seller = UserAccount.query.get(self.insured_user_id)
        buyer  = UserAccount.query.get(self.counterparty_user_id)
        return {
            "id": self.id, "escrow_id": self.escrow_id,
            "insured_user_id": self.insured_user_id, "insured_name": seller.name if seller else None,
            "counterparty_user_id": self.counterparty_user_id, "counterparty_name": buyer.name if buyer else None,
            "coverage_pct": self.coverage_pct, "coverage_amount": self.coverage_amount,
            "premium_amount": self.premium_amount, "currency": self.currency,
            "buyer_credit_score_snapshot": self.buyer_credit_score_snapshot,
            "buyer_risk_grade_snapshot": self.buyer_risk_grade_snapshot,
            "status": self.status,
            "role": ("insured" if viewer_id == self.insured_user_id else
                     "counterparty" if viewer_id == self.counterparty_user_id else None),
            "claim_note": self.claim_note, "payout_amount": self.payout_amount,
            "premium_paid_at": self.premium_paid_at.isoformat() if self.premium_paid_at else None,
            "claim_filed_at": self.claim_filed_at.isoformat() if self.claim_filed_at else None,
            "claim_decided_at": self.claim_decided_at.isoformat() if self.claim_decided_at else None,
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }


def _trade_credit_insurance_quote(escrow, coverage_pct) -> dict:
    """Pure pricing function -- no DB writes. Prices the BUYER's default
    risk (compute_credit_score reused as-is, same function Capital
    Marketplace and PO Financing already price off) against the
    escrow's own amount."""
    try:
        coverage_pct = float(coverage_pct)
    except (TypeError, ValueError):
        coverage_pct = TRADE_CREDIT_INSURANCE_DEFAULT_COVERAGE_PCT
    coverage_pct = max(TRADE_CREDIT_INSURANCE_MIN_COVERAGE_PCT,
                        min(TRADE_CREDIT_INSURANCE_MAX_COVERAGE_PCT, coverage_pct))
    credit = compute_credit_score(escrow.buyer_id)
    rate = TRADE_CREDIT_INSURANCE_RATE_BY_GRADE.get(credit["risk_grade"], 0.06)
    coverage_amount = round(escrow.amount * coverage_pct, 2)
    premium_amount = round(coverage_amount * rate, 2)
    return {
        "escrow_id": escrow.id, "coverage_pct": coverage_pct, "coverage_amount": coverage_amount,
        "premium_amount": premium_amount, "currency": escrow.currency,
        "buyer_credit_score": credit["score"], "buyer_risk_grade": credit["risk_grade"], "rate_applied": rate,
        "pricing_note": ("Indicative pricing computed from the buyer's own Connect It Credit Score. Not yet "
                          "binding -- final terms are set by the licensed underwriting partner."),
    }


def _trade_credit_insurance_check_claim(escrow) -> None:
    """Called from _sync_deal_confirmation_from_escrow on every escrow
    status change. Auto-files a claim the moment an insured escrow ends
    in 'refunded' (the one outcome this platform can actually observe
    that matches what the policy covers), and retires the policy
    cleanly if the trade completes instead. Idempotent: only ever acts
    on a policy that is still 'active'."""
    try:
        policy = TradeCreditInsurancePolicy.query.filter_by(escrow_id=escrow.id, status="active").first()
        if not policy:
            return
        if escrow.status == "refunded":
            policy.status = "claim_filed"
            policy.claim_filed_at = datetime.utcnow()
            policy.claim_note = "Auto-filed: insured escrow was refunded to the buyer while this policy was active."
            db.session.commit()
            logging.info(f"[TRADE CREDIT INSURANCE CLAIM FILED] policy={policy.id} escrow={escrow.id}")
        elif escrow.status in ("released", "resolved_split"):
            # Deal completed (fully or partially) — no default occurred,
            # so the policy simply retires having done its job.
            policy.status = "expired"
            db.session.commit()
    except Exception as e:
        db.session.rollback()
        logging.error(f"[TRADE CREDIT INSURANCE CLAIM CHECK ERROR] escrow #{escrow.id}: {e}")


