@app.route("/api/escrow/<int:escrow_id>/trade-credit-insurance/purchase", methods=["POST"])
@csrf.exempt
@requires_feature_flag("trade_credit_insurance")
def trade_credit_insurance_purchase(escrow_id):
    """One-click embedded purchase: creates the policy AND records the
    premium as paid in the same step (this is the 'sold at checkout',
    not a separate product someone has to seek out, requirement).
    Actually charging a card/wallet is left to whatever payment rail
    already funds the escrow itself -- same reasoning as
    insurance_policy_pay_premium above."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    escrow = EscrowTransaction.query.filter_by(id=escrow_id, seller_id=user["id"]).first()
    if not escrow:
        return jsonify({"error": "Escrow not found, or you're not the seller on this trade."}), 404
    if escrow.status not in ("pending_payment", "funded"):
        return jsonify({"error": f"This trade is already {escrow.status} — too late to insure it."}), 400
    if TradeCreditInsurancePolicy.query.filter_by(escrow_id=escrow.id).first():
        return jsonify({"error": "This trade already has a trade credit insurance policy."}), 400

    data = request.get_json(silent=True) or {}
    quote = _trade_credit_insurance_quote(escrow, data.get("coverage_pct") or TRADE_CREDIT_INSURANCE_DEFAULT_COVERAGE_PCT)

    partner = InsurancePartner.query.filter_by(active=True).first()
    policy = TradeCreditInsurancePolicy(
        escrow_id=escrow.id, insured_user_id=escrow.seller_id, counterparty_user_id=escrow.buyer_id,
        coverage_pct=quote["coverage_pct"], coverage_amount=quote["coverage_amount"],
        premium_amount=quote["premium_amount"], currency=quote["currency"],
        buyer_credit_score_snapshot=quote["buyer_credit_score"], buyer_risk_grade_snapshot=quote["buyer_risk_grade"],
        underwriting_partner_id=(partner.id if partner else None),
        premium_paid_at=datetime.utcnow(),
        status=("active" if partner else "pending_partner"),
    )
    db.session.add(policy)
    db.session.commit()
    logging.info(f"[TRADE CREDIT INSURANCE PURCHASED] policy={policy.id} escrow={escrow.id} seller={user['id']}")

    if policy.status == "pending_partner":
        return jsonify({
            "ok": True, "policy": policy.to_dict(viewer_id=user["id"]),
            "note": ("Premium recorded, but this policy cannot bind/activate until an admin configures "
                      "a licensed underwriting partner (see /admin/insurance/partner)."),
        }), 201
    return jsonify({"ok": True, "policy": policy.to_dict(viewer_id=user["id"])}), 201


