@app.route("/admin/trade-credit-insurance/claims/<int:policy_id>/decide", methods=["POST"])
@csrf.exempt
def admin_trade_credit_insurance_claim_decide(policy_id):
    user, err = _status_admin_or_401()
    if err: return err
    policy = TradeCreditInsurancePolicy.query.get(policy_id)
    if not policy or policy.status != "claim_filed":
        return jsonify({"error": "No pending claim found for that policy."}), 404
    data = request.get_json(silent=True) or {}
    decision = (data.get("decision") or "").strip().lower()
    note = (data.get("note") or "").strip()[:500]
    if decision not in ("approve", "deny"):
        return jsonify({"error": "decision must be 'approve' or 'deny'."}), 400

    if decision == "deny":
        policy.status = "claim_denied"
        policy.claim_note = note or policy.claim_note
        policy.claim_decided_at = datetime.utcnow()
        policy.claim_decided_by_admin_id = user["id"]
        db.session.commit()
        logging.info(f"[TRADE CREDIT INSURANCE CLAIM DENIED] policy={policy.id} by {user.get('email')}")
        return jsonify({"ok": True, "policy": policy.to_dict()}), 200

    partner = InsurancePartner.query.filter_by(active=True).first()
    if not partner:
        return jsonify({"error": "No active underwriting partner configured — cannot approve a payout."}), 503

    policy.status = "paid_out"
    policy.payout_amount = policy.coverage_amount
    policy.claim_note = note or policy.claim_note
    policy.claim_decided_at = datetime.utcnow()
    policy.claim_decided_by_admin_id = user["id"]
    # Records the payout on the seller's own books immediately. Actual
    # disbursement of funds is the underwriting partner's process, same
    # convention as the parametric insurance payout above.
    db.session.add(ErpLedgerEntry(
        owner_user_id=policy.insured_user_id, entry_date=datetime.utcnow().date(),
        kind="revenue", account="Trade Credit Insurance Payout",
        description=f"Trade credit insurance payout — policy #{policy.id}, escrow #{policy.escrow_id}",
        amount=policy.payout_amount,
        reference_type="trade_credit_insurance_payout", reference_id=policy.id,
    ))
    db.session.commit()
    logging.info(f"[TRADE CREDIT INSURANCE PAYOUT] policy={policy.id} escrow={policy.escrow_id} amount={policy.payout_amount} by {user.get('email')}")
    return jsonify({"ok": True, "policy": policy.to_dict()}), 200


# ════════════════════════════════════════════════════════════
# STAGE 352: DIGITIZED LETTERS OF CREDIT
# A real Letter of Credit is a bank's own conditional payment guarantee
# — this platform doesn't have a banking license or a SWIFT connection,
# and fabricating one would be dishonest. What it DOES have, already,
# is real held funds (Escrow, Stage 304) and real trade-document
# generation (commercial invoice / packing list / HS code, Stage 339).
# A "digitized LC" here is the honest version of what an LC actually
# DOES for a buyer and seller: it turns escrow's simple "buyer confirms
# receipt" release trigger into the real LC mechanic — the seller must
# PRESENT a named checklist of documents, and release only fires once
# the buyer (standing in for the issuing bank's own document
# examiners) accepts them as conforming. This layers on top of Escrow
# rather than duplicating its money-holding — an LC with no funded
# escrow underneath it isn't a payment instrument, just a checklist.
# ════════════════════════════════════════════════════════════

LC_STANDARD_DOCUMENT_TYPES = [
    "commercial_invoice", "packing_list", "bill_of_lading", "certificate_of_origin",
    "inspection_certificate", "insurance_certificate",
]


class LetterOfCredit(db.Model):
    __tablename__      = "letters_of_credit"
    id                 = db.Column(db.Integer, primary_key=True)
    escrow_id          = db.Column(db.Integer, db.ForeignKey("escrow_transactions.id"), nullable=False, unique=True, index=True)
    buyer_id           = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    seller_id          = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    required_documents = db.Column(db.Text, nullable=False)  # JSON list of document type strings from LC_STANDARD_DOCUMENT_TYPES (or a custom label)
    issuing_note       = db.Column(db.Text, nullable=True)   # buyer's own self-declared terms/conditions — NOT a bank's legal LC text
    expiry_date        = db.Column(db.Date, nullable=True)
    # draft (escrow not yet funded) -> issued (escrow funded, terms locked)
    #   -> documents_presented (every required doc uploaded)
    #   -> accepted (buyer accepted, escrow released) / discrepant (buyer flagged a problem)
    # -> expired / cancelled
    status              = db.Column(db.String(20), nullable=False, default="draft", index=True)
    discrepancy_note    = db.Column(db.String(500), nullable=True)
    created_at           = db.Column(db.DateTime, default=datetime.utcnow, index=True)
    issued_at             = db.Column(db.DateTime, nullable=True)
    presented_at           = db.Column(db.DateTime, nullable=True)
    accepted_at             = db.Column(db.DateTime, nullable=True)

    def required_documents_list(self) -> list:
        try:
            return json.loads(self.required_documents) if self.required_documents else []
        except (ValueError, TypeError):
            return []

    def to_dict(self, viewer_id=None) -> dict:
        buyer = UserAccount.query.get(self.buyer_id)
        seller = UserAccount.query.get(self.seller_id)
        docs = LetterOfCreditDocument.query.filter_by(lc_id=self.id).order_by(LetterOfCreditDocument.uploaded_at.asc()).all()
        presented_types = {d.document_type for d in docs}
        required = self.required_documents_list()
        return {
            "id": self.id, "escrow_id": self.escrow_id,
            "buyer_id": self.buyer_id, "buyer_name": buyer.name if buyer else None,
            "seller_id": self.seller_id, "seller_name": seller.name if seller else None,
            "required_documents": required,
            "outstanding_documents": [d for d in required if d not in presented_types],
            "issuing_note": self.issuing_note, "expiry_date": self.expiry_date.isoformat() if self.expiry_date else None,
            "status": self.status, "discrepancy_note": self.discrepancy_note,
            "role": ("buyer" if viewer_id == self.buyer_id else "seller" if viewer_id == self.seller_id else None),
            "documents": [d.to_dict() for d in docs],
            "created_at": self.created_at.isoformat() if self.created_at else None,
            "issued_at": self.issued_at.isoformat() if self.issued_at else None,
            "presented_at": self.presented_at.isoformat() if self.presented_at else None,
            "accepted_at": self.accepted_at.isoformat() if self.accepted_at else None,
        }


class LetterOfCreditDocument(db.Model):
    __tablename__  = "letter_of_credit_documents"
    id             = db.Column(db.Integer, primary_key=True)
    lc_id          = db.Column(db.Integer, db.ForeignKey("letters_of_credit.id"), nullable=False, index=True)
    document_type  = db.Column(db.String(50), nullable=False)
    file_url       = db.Column(db.String(500), nullable=False)
    note           = db.Column(db.String(300), nullable=True)
    uploaded_at    = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self) -> dict:
        return {
            "id": self.id, "document_type": self.document_type, "file_url": self.file_url,
            "note": self.note, "uploaded_at": self.uploaded_at.isoformat() if self.uploaded_at else None,
        }


def _lc_check_issue(escrow: "EscrowTransaction") -> None:
    """Called from _sync_deal_confirmation_from_escrow. A draft LC only
    ever becomes 'issued' once its underlying escrow is actually
    funded — an LC over unfunded escrow is just a draft term sheet, not
    a real payment commitment."""
    lc = LetterOfCredit.query.filter_by(escrow_id=escrow.id, status="draft").first()
    if lc and escrow.status == "funded":
        lc.status = "issued"
        lc.issued_at = datetime.utcnow()
        db.session.commit()
        logging.info(f"[LC ISSUED] lc={lc.id} escrow={escrow.id}")


@app.route("/api/escrow/<int:escrow_id>/letter-of-credit", methods=["POST"])
@csrf.exempt
def letter_of_credit_create(escrow_id):
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    escrow = EscrowTransaction.query.filter_by(id=escrow_id, buyer_id=user["id"]).first()
    if not escrow:
        return jsonify({"error": "Escrow not found, or you're not the buyer on this trade."}), 404
    if escrow.status not in ("pending_payment", "funded"):
        return jsonify({"error": f"This trade is already {escrow.status} — too late to attach a letter of credit."}), 400
    if LetterOfCredit.query.filter_by(escrow_id=escrow.id).first():
        return jsonify({"error": "This trade already has a letter of credit."}), 400

    data = request.get_json(silent=True) or {}
    required = [d.strip().lower().replace(" ", "_")[:50] for d in (data.get("required_documents") or []) if d.strip()]
    if not required:
        required = ["commercial_invoice", "packing_list"]
    expiry_date = None
    if data.get("expiry_date"):
        try:
            expiry_date = datetime.fromisoformat(data["expiry_date"]).date()
        except ValueError:
            expiry_date = None

    lc = LetterOfCredit(
        escrow_id=escrow.id, buyer_id=escrow.buyer_id, seller_id=escrow.seller_id,
        required_documents=json.dumps(required), issuing_note=(data.get("issuing_note") or "").strip()[:2000] or None,
        expiry_date=expiry_date, status=("issued" if escrow.status == "funded" else "draft"),
        issued_at=(datetime.utcnow() if escrow.status == "funded" else None),
    )
    db.session.add(lc)
    db.session.commit()
    seller = UserAccount.query.get(escrow.seller_id)
    if seller and seller.whatsapp_number:
        try:
            send_whatsapp_cloud_message(
                seller.id, seller.whatsapp_number,
                f"A letter of credit was set up on your trade (escrow #{escrow.id}). Required documents: "
                + ", ".join(required) + ". Present them from Marketplace -> My Escrows once ready.")
        except Exception as e:
            logging.error(f"[LC CREATE WA NOTIFY ERROR] escrow={escrow.id}: {e}")
    return jsonify({"ok": True, "lc": lc.to_dict(viewer_id=user["id"])}), 201


@app.route("/api/escrow/<int:escrow_id>/letter-of-credit", methods=["GET"])
def letter_of_credit_get(escrow_id):
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    escrow = _escrow_for_party(escrow_id, user["id"])
    if not escrow:
        return jsonify({"error": "Escrow not found."}), 404
    lc = LetterOfCredit.query.filter_by(escrow_id=escrow_id).first()
    return jsonify({"lc": lc.to_dict(viewer_id=user["id"]) if lc else None}), 200


@app.route("/api/letters-of-credit/<int:lc_id>/documents", methods=["POST"])
@csrf.exempt
def letter_of_credit_present_document(lc_id):
    """The seller PRESENTS a document against the LC's own checklist —
    the real LC mechanic this whole stage exists to digitize. Uses the
    same client-supplies-a-hosted-URL pattern already used for listing
    images and factory audit uploads elsewhere in this file, rather
    than building a second file-upload pipeline."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    lc = LetterOfCredit.query.filter_by(id=lc_id, seller_id=user["id"]).first()
    if not lc:
        return jsonify({"error": "Letter of credit not found, or you're not the seller on it."}), 404
    if lc.status not in ("issued", "documents_presented", "discrepant"):
        return jsonify({"error": f"This letter of credit isn't accepting documents right now (status: {lc.status})."}), 400
    data = request.get_json(silent=True) or {}
    document_type = (data.get("document_type") or "").strip().lower().replace(" ", "_")[:50]
    file_url = (data.get("file_url") or "").strip()[:500]
    if not document_type or not file_url:
        return jsonify({"error": "document_type and file_url are required."}), 400
    if document_type not in lc.required_documents_list():
        return jsonify({"error": f"'{document_type}' isn't one of this LC's required documents."}), 400

    # A re-presentation of the same document type replaces the earlier
    # one rather than piling up duplicates (e.g. after a discrepancy).
    existing = LetterOfCreditDocument.query.filter_by(lc_id=lc.id, document_type=document_type).first()
    if existing:
        existing.file_url = file_url
        existing.note = (data.get("note") or "").strip()[:300] or None
        existing.uploaded_at = datetime.utcnow()
    else:
        db.session.add(LetterOfCreditDocument(
            lc_id=lc.id, document_type=document_type, file_url=file_url,
            note=(data.get("note") or "").strip()[:300] or None))
    db.session.commit()

    presented_types = {d.document_type for d in LetterOfCreditDocument.query.filter_by(lc_id=lc.id).all()}
    if set(lc.required_documents_list()).issubset(presented_types):
        lc.status = "documents_presented"
        lc.presented_at = datetime.utcnow()
        db.session.commit()
        buyer = UserAccount.query.get(lc.buyer_id)
        if buyer and buyer.whatsapp_number:
            try:
                send_whatsapp_cloud_message(
                    buyer.id, buyer.whatsapp_number,
                    f"All documents presented on your letter of credit (escrow #{lc.escrow_id}). "
                    f"Review them from Marketplace -> My Escrows to accept and release funds.")
            except Exception as e:
                logging.error(f"[LC PRESENTED WA NOTIFY ERROR] lc={lc.id}: {e}")
    return jsonify({"ok": True, "lc": lc.to_dict(viewer_id=user["id"])}), 201


@app.route("/api/letters-of-credit/<int:lc_id>/accept", methods=["POST"])
@csrf.exempt
def letter_of_credit_accept(lc_id):
    """The buyer accepts the presented documents as conforming — this IS
    the LC's payment trigger, so it releases the underlying escrow the
    exact same way /api/escrow/<id>/confirm does, just gated on document
    presentation instead of a bare 'I received the goods' click."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    lc = LetterOfCredit.query.filter_by(id=lc_id, buyer_id=user["id"]).first()
    if not lc:
        return jsonify({"error": "Letter of credit not found, or you're not the buyer on it."}), 404
    if lc.status != "documents_presented":
        return jsonify({"error": f"This letter of credit isn't ready to accept (status: {lc.status})."}), 400
    escrow = EscrowTransaction.query.get(lc.escrow_id)
    if not escrow or escrow.status != "funded":
        return jsonify({"error": "The underlying escrow isn't funded — nothing to release."}), 400
    open_dispute = EscrowDispute.query.filter_by(escrow_id=escrow.id, status="open").first()
    if open_dispute:
        return jsonify({"error": "This escrow has an open dispute — resolve it before releasing."}), 400

    lc.status = "accepted"
    lc.accepted_at = datetime.utcnow()
    escrow.status = "released"
    escrow.buyer_confirmed_at = datetime.utcnow()
    escrow.released_at = datetime.utcnow()
    escrow.payout_status = "pending_manual_transfer"
    db.session.commit()
    _sync_deal_confirmation_from_escrow(escrow)
    _carbon_credit_on_escrow_settled(escrow)

    seller = UserAccount.query.get(lc.seller_id)
    if seller and seller.whatsapp_number:
        try:
            send_whatsapp_cloud_message(
                seller.id, seller.whatsapp_number,
                f"Your letter of credit was accepted — funds released on escrow #{escrow.id}.")
        except Exception as e:
            logging.error(f"[LC ACCEPT WA NOTIFY ERROR] lc={lc.id}: {e}")
    return jsonify({"ok": True, "lc": lc.to_dict(viewer_id=user["id"]), "escrow": escrow.to_dict(viewer_id=user["id"])}), 200


@app.route("/api/letters-of-credit/<int:lc_id>/flag-discrepancy", methods=["POST"])
@csrf.exempt
def letter_of_credit_flag_discrepancy(lc_id):
    """The real LC counterpart to acceptance: the buyer can refuse
    presented documents as non-conforming instead of accepting them,
    sending the seller back to re-present rather than auto-releasing
    funds on a technicality-riddled presentation."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    lc = LetterOfCredit.query.filter_by(id=lc_id, buyer_id=user["id"]).first()
    if not lc:
        return jsonify({"error": "Letter of credit not found, or you're not the buyer on it."}), 404
    if lc.status != "documents_presented":
        return jsonify({"error": f"This letter of credit isn't ready for review (status: {lc.status})."}), 400
    data = request.get_json(silent=True) or {}
    note = (data.get("note") or "").strip()[:500]
    if not note:
        return jsonify({"error": "A discrepancy note is required so the seller knows what to fix."}), 400
    lc.status = "discrepant"
    lc.discrepancy_note = note
    db.session.commit()
    seller = UserAccount.query.get(lc.seller_id)
    if seller and seller.whatsapp_number:
        try:
            send_whatsapp_cloud_message(
                seller.id, seller.whatsapp_number,
                f"Discrepancy flagged on your letter of credit (escrow #{lc.escrow_id}): {note}. Re-present corrected documents.")
        except Exception as e:
            logging.error(f"[LC DISCREPANCY WA NOTIFY ERROR] lc={lc.id}: {e}")
    return jsonify({"ok": True, "lc": lc.to_dict(viewer_id=user["id"])}), 200


# ════════════════════════════════════════════════════════════
# STAGE 228: CARBON CREDIT MARKETPLACE
# The fourth piece of the network-effect layer alongside the B2B
# Marketplace Directory (222), Smart Surplus Matching (223) and Escrow
# (224): businesses that have reduced emissions (tracked via the real
# STAGE 168 ESG/Carbon Footprint entries already on this platform) can
# list tonnes of self-attested reduction as "credits" for other
# platform members to buy — money changes hands the same safe way any
# other in-platform trade does, through the existing Escrow system
# (trade_type="carbon_credit"), and a retired order gets a downloadable
# certificate.
#
# Honesty, front and centre, same principle as the Escrow header
# comment above: this is a platform-internal, self-attested ledger —
# NOT a listing on Verra, Gold Standard, or any compliance registry.
# It's useful for a genuine internal CSR claim or an informal
# business-to-business offset arrangement between two platform
# members who trust each other's Trust Score, but it is explicitly
# NOT sold as a compliance-grade or resellable-on-a-real-registry
# credit anywhere in the UI or API responses — CARBON_CREDIT_DISCLAIMER
# below is surfaced on every listing and every certificate.
#
# Design choices, mirroring Stage 222/223/224:
#   • Gated by the SAME real Trust Score threshold as the Marketplace
#     Directory (MARKETPLACE_MIN_TRUST_SCORE) before a listing is
#     discoverable in Browse — a brand-new zero-history account can
#     create a listing but it won't surface in search until it does.
#   • tonnes_available is reserved (decremented) the moment a buyer
#     opens an order, not only once payment clears — prevents two
#     buyers racing to buy the same tonnes while the first payment is
#     still pending. If that order is ever cancelled/refunded, the
#     reserved tonnes go back on the listing.
#   • Payment flows entirely through the existing EscrowTransaction
#     machinery (platform-held Paystack funds, buyer-confirms-to-
#     release, dispute path) — no new payment code, no new BYOK
#     surface, same trust rail the rest of the platform already uses.
#   • A retirement certificate (simple PDF) is only ever issued once
#     an order's escrow has actually released — never on order
#     creation or funding alone.
# ════════════════════════════════════════════════════════════

CARBON_CREDIT_METHODOLOGIES = [
    "measured_reduction", "renewable_energy", "reforestation_agroforestry",
    "efficiency_upgrade", "waste_diversion", "other",
]

CARBON_CREDIT_DISCLAIMER = (
    "Platform-internal, self-attested carbon credits based on data the seller entered into "
    "Connect It's own ESG/Carbon Footprint tracker. These are NOT verified against Verra, Gold "
    "Standard, or any compliance carbon registry, and cannot be resold on one. Suitable for an "
    "informal business-to-business offset arrangement or an internal CSR claim between platform "
    "members — not for regulatory compliance offsetting."
)


class CarbonCreditListing(db.Model):
    __tablename__     = "carbon_credit_listings"
    id                = db.Column(db.Integer, primary_key=True)
    seller_user_id    = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    title             = db.Column(db.String(200), nullable=False)
    methodology       = db.Column(db.String(40), nullable=False, default="other", index=True)
    vintage_year      = db.Column(db.Integer, nullable=True)
    description       = db.Column(db.String(800), nullable=True)
    evidence_note     = db.Column(db.String(600), nullable=True)   # seller's own free-text explanation
    evidence_snapshot_json = db.Column(db.Text, nullable=True)     # best-effort snapshot of their ESG summary at listing time
    tonnes_total      = db.Column(db.Float, nullable=False)
    tonnes_available  = db.Column(db.Float, nullable=False)
    price_per_tonne   = db.Column(db.Float, nullable=False)
    currency          = db.Column(db.String(8), nullable=False, default="USD")
    is_active         = db.Column(db.Boolean, nullable=False, default=True, index=True)
    created_at        = db.Column(db.DateTime, default=datetime.utcnow, index=True)
    updated_at        = db.Column(db.DateTime, default=datetime.utcnow, onupdate=datetime.utcnow)

    def to_dict(self, viewer_id=None):
        seller = UserAccount.query.get(self.seller_user_id)
        trust = compute_trust_score(self.seller_user_id)
        return {
            "id": self.id, "seller_user_id": self.seller_user_id,
            "seller_name": seller.name if seller else None,
            "title": self.title, "methodology": self.methodology, "vintage_year": self.vintage_year,
            "description": self.description, "evidence_note": self.evidence_note,
            "evidence_snapshot": json.loads(self.evidence_snapshot_json) if self.evidence_snapshot_json else None,
            "tonnes_total": self.tonnes_total, "tonnes_available": round(self.tonnes_available, 3),
            "price_per_tonne": self.price_per_tonne, "currency": self.currency,
            "is_active": self.is_active,
            "trust_score": trust["score"], "trust_grade": trust["grade"],
            "meets_directory_threshold": trust["score"] >= MARKETPLACE_MIN_TRUST_SCORE,
            "is_mine": bool(viewer_id) and viewer_id == self.seller_user_id,
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }


class CarbonCreditOrder(db.Model):
    __tablename__    = "carbon_credit_orders"
    id               = db.Column(db.Integer, primary_key=True)
    listing_id       = db.Column(db.Integer, db.ForeignKey("carbon_credit_listings.id"), nullable=False, index=True)
    buyer_user_id    = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    seller_user_id   = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    tonnes           = db.Column(db.Float, nullable=False)
    price_per_tonne  = db.Column(db.Float, nullable=False)   # snapshot at order time
    total_amount     = db.Column(db.Float, nullable=False)
    currency         = db.Column(db.String(8), nullable=False, default="USD")
    status           = db.Column(db.String(20), nullable=False, default="pending_escrow", index=True)
    # pending_escrow, funded, retired, cancelled, refunded
    escrow_id        = db.Column(db.Integer, db.ForeignKey("escrow_transactions.id"), nullable=True, index=True)
    certificate_token = db.Column(db.String(48), nullable=True, unique=True)
    created_at       = db.Column(db.DateTime, default=datetime.utcnow, index=True)
    retired_at       = db.Column(db.DateTime, nullable=True)

    def to_dict(self):
        listing = CarbonCreditListing.query.get(self.listing_id)
        buyer = UserAccount.query.get(self.buyer_user_id)
        seller = UserAccount.query.get(self.seller_user_id)
        return {
            "id": self.id, "listing_id": self.listing_id,
            "listing_title": listing.title if listing else None,
            "buyer_user_id": self.buyer_user_id, "buyer_name": buyer.name if buyer else None,
            "seller_user_id": self.seller_user_id, "seller_name": seller.name if seller else None,
            "tonnes": self.tonnes, "price_per_tonne": self.price_per_tonne,
            "total_amount": self.total_amount, "currency": self.currency,
            "status": self.status, "escrow_id": self.escrow_id,
            "certificate_available": bool(self.certificate_token),
            "created_at": self.created_at.isoformat() if self.created_at else None,
            "retired_at": self.retired_at.isoformat() if self.retired_at else None,
        }


def _carbon_credit_snapshot_evidence(uid):
    """Best-effort snapshot of the seller's own STAGE 168 ESG summary at
    listing time, so a buyer can see the real numbers behind the claim
    without the seller having to type them in by hand. Returns None if
    they haven't logged anything in the ESG tracker — self-attestation
    is still allowed via evidence_note in that case, just without a
    live snapshot backing it."""
    entries = CarbonFootprintEntry.query.filter_by(owner_user_id=uid).all()
    if not entries:
        return None
    total_kg = sum(e.co2e_kg for e in entries)
    by_year = defaultdict(float)
    for e in entries:
        if e.entry_date:
            by_year[e.entry_date.year] += e.co2e_kg
    return {"total_co2e_tonnes_logged": round(total_kg / 1000, 3),
            "by_year_tonnes": {str(y): round(v / 1000, 3) for y, v in sorted(by_year.items())}}


def _carbon_credit_restore_tonnes(order):
    """Puts an order's reserved tonnes back on the listing — used on
    cancellation or refund, never on a successful retirement."""
    listing = CarbonCreditListing.query.get(order.listing_id)
    if listing:
        listing.tonnes_available = min(listing.tonnes_total, listing.tonnes_available + order.tonnes)


def _carbon_credit_on_escrow_settled(escrow):
    """Called whenever an escrow with trade_type == 'carbon_credit'
    changes status — release/split retires the order and issues a
    certificate; refund restores the reserved tonnes to the listing."""
    if escrow.trade_type != "carbon_credit" or not escrow.ref_id:
        return
    order = CarbonCreditOrder.query.get(escrow.ref_id)
    if not order:
        return
    if escrow.status in ("released", "resolved_split") and order.status != "retired":
        order.status = "retired"
        order.retired_at = datetime.utcnow()
        order.certificate_token = secrets.token_urlsafe(24)
        db.session.commit()
    elif escrow.status == "refunded" and order.status not in ("cancelled", "refunded"):
        order.status = "refunded"
        _carbon_credit_restore_tonnes(order)
        db.session.commit()


@app.route("/api/carbon-marketplace/methodologies", methods=["GET"])
@requires_feature_flag("carbon_credit_marketplace")
def carbon_marketplace_methodologies():
    return jsonify({"methodologies": CARBON_CREDIT_METHODOLOGIES, "disclaimer": CARBON_CREDIT_DISCLAIMER}), 200


@app.route("/api/carbon-marketplace/browse", methods=["GET"])
@requires_feature_flag("carbon_credit_marketplace")
def carbon_marketplace_browse():
    user, err = _erp_user_or_401()
    if err: return err
    q = CarbonCreditListing.query.filter_by(is_active=True).filter(CarbonCreditListing.tonnes_available > 0)
    methodology = request.args.get("methodology")
    if methodology in CARBON_CREDIT_METHODOLOGIES:
        q = q.filter_by(methodology=methodology)
    try:
        max_price = float(request.args.get("max_price"))
        q = q.filter(CarbonCreditListing.price_per_tonne <= max_price)
    except (TypeError, ValueError):
        pass
    try:
        min_tonnes = float(request.args.get("min_tonnes"))
        q = q.filter(CarbonCreditListing.tonnes_available >= min_tonnes)
    except (TypeError, ValueError):
        pass
    rows = q.order_by(CarbonCreditListing.created_at.desc()).limit(200).all()
    listings = [r.to_dict(viewer_id=user["id"]) for r in rows]
    visible = [l for l in listings if l["meets_directory_threshold"] or l["is_mine"]]
    return jsonify({"listings": visible, "min_trust_score": MARKETPLACE_MIN_TRUST_SCORE,
                     "disclaimer": CARBON_CREDIT_DISCLAIMER}), 200


