@app.route("/api/carbon-marketplace/listings/<int:listing_id>/buy", methods=["POST"])
@csrf.exempt
@requires_feature_flag("carbon_credit_marketplace")
def carbon_marketplace_listing_buy(listing_id):
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    listing = CarbonCreditListing.query.filter_by(id=listing_id, is_active=True).first()
    if not listing: return jsonify({"error": "Listing not found."}), 404
    if listing.seller_user_id == user["id"]:
        return jsonify({"error": "You can't buy your own listing."}), 400
    try:
        tonnes = float((request.get_json(silent=True) or {}).get("tonnes"))
        if tonnes <= 0: raise ValueError()
    except (TypeError, ValueError):
        return jsonify({"error": "tonnes must be a positive number."}), 400
    if tonnes > listing.tonnes_available:
        return jsonify({"error": f"Only {round(listing.tonnes_available,3)} tonnes available on this listing."}), 400

    total_amount = round(tonnes * listing.price_per_tonne, 2)
    if not validate_amount(total_amount):
        return jsonify({"error": "Order amount is out of the allowed range."}), 400

    try:
        listing.tonnes_available -= tonnes  # reserve immediately, restored if the order is later cancelled/refunded
        order = CarbonCreditOrder(
            listing_id=listing.id, buyer_user_id=user["id"], seller_user_id=listing.seller_user_id,
            tonnes=tonnes, price_per_tonne=listing.price_per_tonne, total_amount=total_amount,
            currency=listing.currency, status="pending_escrow",
        )
        db.session.add(order); db.session.flush()

        escrow = EscrowTransaction(
            trade_type="carbon_credit", ref_id=order.id, buyer_id=user["id"], seller_id=listing.seller_user_id,
            description=f"{tonnes} tonnes CO2e — {listing.title}"[:300],
            amount=total_amount, currency=listing.currency,
        )
        db.session.add(escrow); db.session.flush()
        order.escrow_id = escrow.id
        db.session.commit()
        _sync_deal_confirmation_from_escrow(escrow)
    except Exception as e:
        db.session.rollback(); logging.error(f"[CARBON CREDIT BUY] {e}")
        return jsonify({"error": "Could not create the order."}), 500
    return jsonify({"order": order.to_dict(), "escrow": escrow.to_dict(viewer_id=user["id"])}), 201


