@app.route("/api/carbon-marketplace/orders/<int:order_id>/cancel", methods=["POST"])
@csrf.exempt
@requires_feature_flag("carbon_credit_marketplace")
def carbon_marketplace_order_cancel(order_id):
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    order = CarbonCreditOrder.query.filter_by(id=order_id, buyer_user_id=user["id"]).first()
    if not order: return jsonify({"error": "Order not found."}), 404
    if order.status != "pending_escrow":
        return jsonify({"error": "Only an unfunded order can be cancelled — use the dispute flow in Escrow once it's funded."}), 400
    escrow = EscrowTransaction.query.get(order.escrow_id) if order.escrow_id else None
    if escrow and escrow.status == "pending_payment":
        escrow.status = "cancelled"
    order.status = "cancelled"
    _carbon_credit_restore_tonnes(order)
    db.session.commit()
    return jsonify({"order": order.to_dict()}), 200


@app.route("/api/carbon-marketplace/orders/<int:order_id>/certificate.pdf", methods=["GET"])
def carbon_marketplace_order_certificate(order_id):
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    order = CarbonCreditOrder.query.filter_by(id=order_id, buyer_user_id=user["id"]).first()
    if not order or order.status != "retired" or not order.certificate_token:
        return jsonify({"error": "Certificate not available for this order."}), 404
    if not REPORTLAB_AVAILABLE:
        return jsonify({"error": "PDF generation isn't available on this server."}), 503
    listing = CarbonCreditListing.query.get(order.listing_id)
    buyer = UserAccount.query.get(order.buyer_user_id)
    seller = UserAccount.query.get(order.seller_user_id)

    buf = io.BytesIO()
    doc = SimpleDocTemplate(buf, pagesize=A4, rightMargin=40, leftMargin=40, topMargin=50, bottomMargin=40)
    styles = getSampleStyleSheet()
    story = [
        Paragraph("Carbon Credit Retirement Certificate", styles["Title"]),
        Spacer(1, 10),
        Paragraph(f"Certificate ID: {order.certificate_token}", styles["Normal"]),
        Paragraph(f"Retired: {order.retired_at.strftime('%d %b %Y') if order.retired_at else '—'}", styles["Normal"]),
        Spacer(1, 14),
        Paragraph(f"<b>{order.tonnes} tonnes CO2e</b> retired by {buyer.name if buyer else '—'}, "
                  f"purchased from {seller.name if seller else '—'}.", styles["Normal"]),
        Spacer(1, 8),
        Paragraph(f"Listing: {listing.title if listing else '—'} — methodology: "
                  f"{(listing.methodology if listing else '—').replace('_',' ')}"
                  + (f", vintage {listing.vintage_year}" if listing and listing.vintage_year else ""), styles["Normal"]),
        Spacer(1, 8),
        Paragraph(f"Price paid: {order.currency} {order.total_amount} ({order.currency} {order.price_per_tonne}/tonne)", styles["Normal"]),
        Spacer(1, 20),
        Paragraph(CARBON_CREDIT_DISCLAIMER, styles["Normal"]),
    ]
    doc.build(story)
    buf.seek(0)
    return Response(buf, mimetype="application/pdf",
                     headers={"Content-Disposition": f'attachment; filename="carbon-credit-certificate-{order.id}.pdf"'})


@app.route("/api/carbon-marketplace/my-offset-status", methods=["GET"])
def carbon_marketplace_my_offset_status():
    user, err = _erp_user_or_401()
    if err: return err
    entries = CarbonFootprintEntry.query.filter_by(owner_user_id=user["id"]).all()
    emitted_tonnes = round(sum(e.co2e_kg for e in entries) / 1000, 3)
    retired_tonnes = round(sum(
        o.tonnes for o in CarbonCreditOrder.query.filter_by(buyer_user_id=user["id"], status="retired").all()
    ), 3)
    return jsonify({
        "emitted_tonnes": emitted_tonnes, "retired_tonnes": retired_tonnes,
        "net_tonnes": round(emitted_tonnes - retired_tonnes, 3),
        "has_footprint_data": bool(entries),
    }), 200


# ════════════════════════════════════════════════════════════
# STAGE 224: TRUST SCORE API LICENSING
# Turns the existing, already-real compute_trust_score() into a
# licensable B2B data product for banks, microfinance institutions,
# and insurers — distinct from the Stage 93/GLOBAL-05 one-off share
# links, which hand a single human reviewer a single time-limited
# view. This is a programmatic, metered API a licensed partner
# ORGANIZATION calls repeatedly across many of ITS OWN customers —
# but only for a specific business once that business has actively
# granted that specific partner consent from inside their own
# account. Nothing here is self-reported or invented: every score
# returned is the same live compute_trust_score() output already
# used by Marketplace/Surplus, and every call is logged for billing.
# ════════════════════════════════════════════════════════════

class TrustScoreLicensee(db.Model):
    """A licensed partner organization (bank, MFI, insurer) — NOT a
    single business's own developer key (see PartnerApiKey/Stage 174).
    Created by an admin after a real commercial agreement; public_code
    is what a business enters to grant consent, key_id/secret_hash is
    what the partner's own server authenticates API calls with."""
    __tablename__      = "trust_score_licensees"
    id                 = db.Column(db.Integer, primary_key=True)
    org_name           = db.Column(db.String(200), nullable=False)
    contact_email      = db.Column(db.String(200), nullable=False)
    public_code        = db.Column(db.String(40), unique=True, nullable=False, index=True)
    key_id             = db.Column(db.String(40), unique=True, nullable=False, index=True)
    secret_hash        = db.Column(db.String(128), nullable=False)
    tier               = db.Column(db.String(20), nullable=False, default="standard")  # standard, enterprise
    monthly_quota      = db.Column(db.Integer, nullable=False, default=500)
    calls_this_month   = db.Column(db.Integer, nullable=False, default=0)
    quota_reset_month  = db.Column(db.String(7), nullable=False, default=lambda: datetime.utcnow().strftime("%Y-%m"))
    active             = db.Column(db.Boolean, nullable=False, default=True)
    created_at         = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self, include_usage=True):
        d = {
            "id": self.id, "org_name": self.org_name, "contact_email": self.contact_email,
            "public_code": self.public_code, "key_id": self.key_id, "tier": self.tier,
            "monthly_quota": self.monthly_quota, "active": self.active,
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }
        if include_usage:
            d["calls_this_month"] = self.calls_this_month
            d["quota_reset_month"] = self.quota_reset_month
        return d


class TrustScoreConsent(db.Model):
    """A specific business's opt-in for a specific licensee to pull its
    Trust Score. Business-initiated and business-revocable at any time —
    a licensee can never query a business that hasn't granted it."""
    __tablename__  = "trust_score_consents"
    id             = db.Column(db.Integer, primary_key=True)
    user_id        = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    licensee_id    = db.Column(db.Integer, db.ForeignKey("trust_score_licensees.id"), nullable=False, index=True)
    granted_at     = db.Column(db.DateTime, default=datetime.utcnow)
    expires_at     = db.Column(db.DateTime, nullable=True)
    revoked        = db.Column(db.Boolean, nullable=False, default=False)

    __table_args__ = (db.UniqueConstraint("user_id", "licensee_id", name="uq_trust_consent_user_licensee"),)

    def to_dict(self):
        licensee = TrustScoreLicensee.query.get(self.licensee_id)
        return {
            "id": self.id, "licensee_id": self.licensee_id,
            "licensee_name": licensee.org_name if licensee else "Unknown",
            "granted_at": self.granted_at.isoformat() if self.granted_at else None,
            "expires_at": self.expires_at.isoformat() if self.expires_at else None,
            "revoked": self.revoked,
            "active": (not self.revoked) and (not self.expires_at or self.expires_at > datetime.utcnow()),
        }


class TrustScoreApiCall(db.Model):
    """Audit/billing log — one row per successful partner API pull, so
    usage is provable and disputable on both sides, not just a counter."""
    __tablename__  = "trust_score_api_calls"
    id             = db.Column(db.Integer, primary_key=True)
    licensee_id    = db.Column(db.Integer, db.ForeignKey("trust_score_licensees.id"), nullable=False, index=True)
    user_id        = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    score_returned = db.Column(db.Float, nullable=True)
    called_at      = db.Column(db.DateTime, default=datetime.utcnow, index=True)


def _trust_licensee_auth():
    """Returns (licensee_row, None) on success or (None, error_response).
    Same Bearer key_id.secret shape as Stage 174's PartnerApiKey, kept
    consistent on purpose — different table because a licensee is an
    organization spanning many businesses, not one business's own key."""
    auth = request.headers.get("Authorization", "")
    if not auth.startswith("Bearer "):
        return None, (jsonify({"error": "Missing Authorization: Bearer <key_id>.<secret> header."}), 401)
    token = auth[len("Bearer "):].strip()
    if "." not in token:
        return None, (jsonify({"error": "Malformed API key."}), 401)
    key_id, secret = token.split(".", 1)
    row = TrustScoreLicensee.query.filter_by(key_id=key_id, active=True).first()
    if not row or hashlib.sha256(secret.encode()).hexdigest() != row.secret_hash:
        return None, (jsonify({"error": "Invalid or revoked API key."}), 401)
    this_month = datetime.utcnow().strftime("%Y-%m")
    if row.quota_reset_month != this_month:
        row.quota_reset_month = this_month
        row.calls_this_month = 0
        db.session.commit()
    if row.calls_this_month >= row.monthly_quota:
        return None, (jsonify({"error": f"Monthly quota of {row.monthly_quota} calls reached."}), 429)
    return row, None


# ---- ADMIN: create / list / revoke licensees ----

@app.route("/admin/trust-api/licensees", methods=["POST"])
@_require_master_key
def admin_trust_licensee_create():
    data = request.get_json(silent=True) or {}
    org_name = (data.get("org_name") or "").strip()
    contact_email = (data.get("contact_email") or "").strip()
    tier = (data.get("tier") or "standard").strip()
    try:
        monthly_quota = int(data.get("monthly_quota", 500))
    except (TypeError, ValueError):
        monthly_quota = 500
    if not org_name or not contact_email:
        return jsonify({"error": "org_name and contact_email are required."}), 400

    public_code = re.sub(r"[^A-Z0-9]", "", org_name.upper())[:12] + "-" + secrets.token_hex(2).upper()
    key_id, secret, secret_hash = _generate_api_key_pair()
    try:
        row = TrustScoreLicensee(org_name=org_name, contact_email=contact_email, public_code=public_code,
                                  key_id=key_id, secret_hash=secret_hash, tier=tier, monthly_quota=monthly_quota)
        db.session.add(row)
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        return jsonify({"error": str(e)}), 500
    return jsonify({
        "licensee": row.to_dict(),
        "api_key": key_id + "." + secret,
        "warning": "Store this API key now — the secret is never shown again.",
    }), 201


@app.route("/admin/trust-api/licensees", methods=["GET"])
@_require_master_key
def admin_trust_licensee_list():
    rows = TrustScoreLicensee.query.order_by(TrustScoreLicensee.created_at.desc()).all()
    return jsonify({"licensees": [r.to_dict() for r in rows]}), 200


@app.route("/admin/trust-api/licensees/<int:licensee_id>/revoke", methods=["POST"])
@_require_master_key
def admin_trust_licensee_revoke(licensee_id):
    row = TrustScoreLicensee.query.get(licensee_id)
    if not row:
        return jsonify({"error": "Licensee not found."}), 404
    row.active = False
    db.session.commit()
    return jsonify({"ok": True}), 200


# ---- BUSINESS: grant / list / revoke consent ----

@app.route("/api/trust-score/api-consent/grant", methods=["POST"])
@csrf.exempt
def trust_consent_grant():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    public_code = (data.get("public_code") or "").strip().upper()
    if not public_code:
        return jsonify({"error": "public_code is required."}), 400
    licensee = TrustScoreLicensee.query.filter_by(public_code=public_code, active=True).first()
    if not licensee:
        return jsonify({"error": "No active partner found with that code."}), 404

    consent = TrustScoreConsent.query.filter_by(user_id=user["id"], licensee_id=licensee.id).first()
    if consent:
        consent.revoked = False
        consent.granted_at = datetime.utcnow()
        consent.expires_at = datetime.utcnow() + timedelta(days=180)
    else:
        consent = TrustScoreConsent(user_id=user["id"], licensee_id=licensee.id,
                                     expires_at=datetime.utcnow() + timedelta(days=180))
        db.session.add(consent)
    db.session.commit()
    return jsonify({"ok": True, "consent": consent.to_dict()}), 200


@app.route("/api/trust-score/api-consent/list", methods=["GET"])
def trust_consent_list():
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    rows = TrustScoreConsent.query.filter_by(user_id=user["id"]).order_by(TrustScoreConsent.granted_at.desc()).all()
    return jsonify({"consents": [c.to_dict() for c in rows]}), 200


@app.route("/api/trust-score/api-consent/<int:consent_id>/revoke", methods=["POST"])
@csrf.exempt
def trust_consent_revoke(consent_id):
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    consent = TrustScoreConsent.query.filter_by(id=consent_id, user_id=user["id"]).first()
    if not consent:
        return jsonify({"error": "Consent not found."}), 404
    consent.revoked = True
    db.session.commit()
    return jsonify({"ok": True}), 200


# ---- PARTNER: the licensed, metered external API itself ----

@app.route("/api/partner/v1/trust-score", methods=["GET"])
def partner_trust_score_lookup():
    licensee, err = _trust_licensee_auth()
    if err:
        return err
    business_email = (request.args.get("business_email") or "").strip().lower()
    if not business_email:
        return jsonify({"error": "business_email query parameter is required."}), 400

    target = UserAccount.query.filter(db.func.lower(UserAccount.email) == business_email).first()
    if not target:
        return jsonify({"error": "No business found with that email."}), 404

    consent = TrustScoreConsent.query.filter_by(user_id=target.id, licensee_id=licensee.id, revoked=False).first()
    if not consent or (consent.expires_at and consent.expires_at < datetime.utcnow()):
        return jsonify({"error": "This business has not granted your organization consent to view its Trust Score."}), 403

    try:
        result = compute_trust_score(target.id)
        licensee.calls_this_month += 1
        db.session.add(TrustScoreApiCall(licensee_id=licensee.id, user_id=target.id, score_returned=result["score"]))
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        logging.error(f"[TRUST API LOOKUP] {e}")
        return jsonify({"error": "Could not compute trust score."}), 500

    return jsonify({
        "business_name": target.name,
        "score": result["score"], "grade": result["grade"], "breakdown": result["breakdown"],
        "computed_at": result["computed_at"],
        "calls_remaining_this_month": max(0, licensee.monthly_quota - licensee.calls_this_month),
    }), 200


@app.route("/api/partner/v1/trust-score/ping", methods=["GET"])
def partner_trust_score_ping():
    licensee, err = _trust_licensee_auth()
    if err:
        return err
    return jsonify({"ok": True, "org_name": licensee.org_name, "tier": licensee.tier,
                     "calls_remaining_this_month": max(0, licensee.monthly_quota - licensee.calls_this_month)}), 200


# ════════════════════════════════════════════════════════════
# STAGE 225: AGGREGATED ECONOMIC DATA LICENSING
# A second, separate B2B data product from Stage 224's Trust Score API:
# that one sells a bank a live look at ONE consenting business; this
# one sells a DFI/government/research body anonymized, cohort-level
# SME activity trends — no single business is ever identifiable.
# Two real privacy guards, not cosmetic ones: (1) only businesses that
# have actively opted in via the platform's existing PrivacyConsent.
# third_party_sharing flag (Stage GLOBAL-07 — created there but never
# actually enforced anywhere until now) are ever included; (2) a
# segment (country + Marketplace category) only returns data once it
# has ECON_DATA_MIN_COHORT or more consenting businesses in it, so no
# aggregate can be reverse-engineered back to an individual. Every
# metric returned is computed live from real ErpInvoice/DealReview/
# DealConfirmation/Trust Score data already on the platform.
# ════════════════════════════════════════════════════════════

ECON_DATA_MIN_COHORT = 5      # minimum consenting businesses before a segment is queryable
ECON_DATA_SCORE_SAMPLE_CAP = 200  # bound compute_trust_score() calls on very large segments


class EconomicDataLicensee(db.Model):
    """A licensed DFI/government/research/analytics partner. Separate
    from TrustScoreLicensee (Stage 224) on purpose — same shape as the
    BusinessPassportShare/CreditScoreShare precedent elsewhere in this
    file: parallel single-purpose licensee records rather than one
    entity overloaded with unrelated products."""
    __tablename__      = "economic_data_licensees"
    id                 = db.Column(db.Integer, primary_key=True)
    org_name           = db.Column(db.String(200), nullable=False)
    contact_email      = db.Column(db.String(200), nullable=False)
    key_id             = db.Column(db.String(40), unique=True, nullable=False, index=True)
    secret_hash        = db.Column(db.String(128), nullable=False)
    tier               = db.Column(db.String(20), nullable=False, default="standard")
    monthly_quota      = db.Column(db.Integer, nullable=False, default=200)
    calls_this_month   = db.Column(db.Integer, nullable=False, default=0)
    quota_reset_month  = db.Column(db.String(7), nullable=False, default=lambda: datetime.utcnow().strftime("%Y-%m"))
    active             = db.Column(db.Boolean, nullable=False, default=True)
    created_at         = db.Column(db.DateTime, default=datetime.utcnow)
    # STAGE 514a: real commercial per-call price this licensee is billed,
    # set by an admin after a real agreement. 0 means no revenue-share
    # payout is generated (e.g. a free research/nonprofit tier).
    price_per_call_cents = db.Column(db.Integer, nullable=False, default=0)

    def to_dict(self):
        return {
            "id": self.id, "org_name": self.org_name, "contact_email": self.contact_email,
            "key_id": self.key_id, "tier": self.tier, "monthly_quota": self.monthly_quota,
            "calls_this_month": self.calls_this_month, "quota_reset_month": self.quota_reset_month,
            "active": self.active, "created_at": self.created_at.isoformat() if self.created_at else None,
            "price_per_call_cents": self.price_per_call_cents,
        }


class EconomicDataApiCall(db.Model):
    """Usage/billing log. No user_id column at all — a call only ever
    resolves to an aggregate segment, never to an individual business,
    so there is nothing identifying to log even by mistake."""
    __tablename__   = "economic_data_api_calls"
    id              = db.Column(db.Integer, primary_key=True)
    licensee_id     = db.Column(db.Integer, db.ForeignKey("economic_data_licensees.id"), nullable=False, index=True)
    country_code    = db.Column(db.String(4), nullable=False)
    category        = db.Column(db.String(60), nullable=False)
    business_count  = db.Column(db.Integer, nullable=False)
    called_at       = db.Column(db.DateTime, default=datetime.utcnow, index=True)


def _econ_licensee_auth():
    auth = request.headers.get("Authorization", "")
    if not auth.startswith("Bearer "):
        return None, (jsonify({"error": "Missing Authorization: Bearer <key_id>.<secret> header."}), 401)
    token = auth[len("Bearer "):].strip()
    if "." not in token:
        return None, (jsonify({"error": "Malformed API key."}), 401)
    key_id, secret = token.split(".", 1)
    row = EconomicDataLicensee.query.filter_by(key_id=key_id, active=True).first()
    if not row or hashlib.sha256(secret.encode()).hexdigest() != row.secret_hash:
        return None, (jsonify({"error": "Invalid or revoked API key."}), 401)
    this_month = datetime.utcnow().strftime("%Y-%m")
    if row.quota_reset_month != this_month:
        row.quota_reset_month = this_month
        row.calls_this_month = 0
        db.session.commit()
    if row.calls_this_month >= row.monthly_quota:
        return None, (jsonify({"error": f"Monthly quota of {row.monthly_quota} calls reached."}), 429)
    return row, None


def _econ_consenting_cohort(country_code: str, category: str):
    """Business user_ids in this country+category Marketplace segment
    who have actively opted in to third-party data sharing. Absence of
    a PrivacyConsent row (never touched their privacy settings) is NOT
    treated as consent — the column defaults to False for a reason."""
    rows = (db.session.query(MarketplaceListing.user_id)
            .join(PrivacyConsent, PrivacyConsent.owner_user_id == MarketplaceListing.user_id)
            .filter(MarketplaceListing.category == category,
                    MarketplaceListing.country_code == country_code,
                    MarketplaceListing.is_active == True,
                    PrivacyConsent.third_party_sharing == True)
            .all())
    return [r[0] for r in rows]


def _econ_sector_summary(country_code: str, category: str, days: int):
    cohort = _econ_consenting_cohort(country_code, category)
    if len(cohort) < ECON_DATA_MIN_COHORT:
        return None

    since = datetime.utcnow() - timedelta(days=days)
    invoices = ErpInvoice.query.filter(ErpInvoice.owner_user_id.in_(cohort),
                                        ErpInvoice.created_at >= since).all()
    paid = [i for i in invoices if i.status == "paid"]
    on_time = [i for i in paid if i.due_date and i.paid_at and i.paid_at.date() <= i.due_date]

    sample = cohort[:ECON_DATA_SCORE_SAMPLE_CAP]
    scores = [compute_trust_score(uid)["score"] for uid in sample]
    grade_counts = {"A": 0, "B": 0, "C": 0, "D": 0, "Building": 0}
    for uid in sample:
        g = compute_trust_score(uid)["grade"]
        grade_counts[g] = grade_counts.get(g, 0) + 1

    reviews_count = DealReview.query.filter(DealReview.reviewee_id.in_(cohort)).count()
    completed_deals = (DealConfirmation.query
                        .filter(db.or_(DealConfirmation.party_a_id.in_(cohort),
                                       DealConfirmation.party_b_id.in_(cohort)),
                                DealConfirmation.status == "confirmed")
                        .distinct().count())

    return {
        "country_code": country_code, "category": category,
        "business_count": len(cohort),
        "sampled_for_trust_score": len(sample),
        "window_days": days,
        "invoices_issued": len(invoices),
        "pct_invoices_paid": round(len(paid) / len(invoices) * 100, 1) if invoices else None,
        "pct_paid_on_time": round(len(on_time) / len(paid) * 100, 1) if paid else None,
        "avg_trust_score": round(sum(scores) / len(scores), 1) if scores else None,
        "trust_grade_distribution": grade_counts,
        "deal_reviews_total": reviews_count,
        "completed_deals_total": completed_deals,
        "computed_at": datetime.utcnow().isoformat(),
    }


