# ---- PARTNER: the licensed, metered aggregate-data API itself ----

@app.route("/api/partner/v1/economic-data/segments", methods=["GET"])
def partner_econ_segments():
    licensee, err = _econ_licensee_auth()
    if err:
        return err
    rows = (db.session.query(MarketplaceListing.country_code, MarketplaceListing.category,
                              db.func.count(db.func.distinct(MarketplaceListing.user_id)))
            .join(PrivacyConsent, PrivacyConsent.owner_user_id == MarketplaceListing.user_id)
            .filter(MarketplaceListing.is_active == True, PrivacyConsent.third_party_sharing == True)
            .group_by(MarketplaceListing.country_code, MarketplaceListing.category)
            .having(db.func.count(db.func.distinct(MarketplaceListing.user_id)) >= ECON_DATA_MIN_COHORT)
            .all())
    return jsonify({
        "segments": [{"country_code": c, "category": cat, "business_count": n} for c, cat, n in rows],
        "min_cohort_size": ECON_DATA_MIN_COHORT,
    }), 200


@app.route("/api/partner/v1/economic-data/sector-summary", methods=["GET"])
def partner_econ_sector_summary():
    licensee, err = _econ_licensee_auth()
    if err:
        return err
    country_code = (request.args.get("country") or "").strip().upper()
    category = (request.args.get("category") or "").strip()
    try:
        days = max(7, min(int(request.args.get("days", 90)), 365))
    except (TypeError, ValueError):
        days = 90
    if not country_code or not category:
        return jsonify({"error": "country and category query parameters are required."}), 400

    try:
        summary = _econ_sector_summary(country_code, category, days)
    except Exception as e:
        logging.error(f"[ECON DATA SUMMARY] {e}")
        return jsonify({"error": "Could not compute sector summary."}), 500

    if summary is None:
        return jsonify({
            "error": f"Fewer than {ECON_DATA_MIN_COHORT} consenting businesses in this segment — no aggregate can be returned.",
            "country_code": country_code, "category": category,
        }), 404

    licensee.calls_this_month += 1
    call_row = EconomicDataApiCall(licensee_id=licensee.id, country_code=country_code,
                                    category=category, business_count=summary["business_count"])
    db.session.add(call_row)
    db.session.commit()

    # STAGE 514a: real revenue share — split this call's billed price
    # evenly across every consenting seller actually in the queried
    # cohort. No price set on this licensee (price_per_call_cents=0)
    # means no earnings are generated, same as a free research tier.
    if licensee.price_per_call_cents > 0:
        try:
            cohort = _econ_consenting_cohort(country_code, category)
            if cohort:
                share_cents = licensee.price_per_call_cents // len(cohort)
                if share_cents > 0:
                    for seller_id in cohort:
                        db.session.add(DataMarketplaceEarning(
                            user_id=seller_id, licensee_id=licensee.id, econ_api_call_id=call_row.id,
                            amount_cents=share_cents, segment_label=f"{country_code} / {category}"))
                    db.session.commit()
        except Exception as e:
            db.session.rollback()
            logging.error(f"[DATA MARKETPLACE REVENUE SHARE] {e}")

    summary["calls_remaining_this_month"] = max(0, licensee.monthly_quota - licensee.calls_this_month)
    return jsonify(summary), 200


