# ════════════════════════════════════════════════════════════
# STAGE 229: CONVERSATION ANALYTICS & INSIGHTS ENGINE
# Turns the real widget-chat transcripts already logged in
# WidgetMessage into business intelligence for the owner: volume
# per day, peak hours, AI-clustered topics, sentiment trend (local
# model, no external calls), and drop-off sessions (a customer's
# last message went unanswered). No new tracking is added — this
# only reads what the chat widget already stores.
# ════════════════════════════════════════════════════════════

ANALYTICS_MAX_TOPIC_SAMPLE = 150   # cap on messages sent to the AI for topic clustering
ANALYTICS_MAX_SENTIMENT_SAMPLE = 400  # cap on messages run through the local sentiment model


def _analytics_topics(sample_texts):
    """AI-clusters a sample of real customer messages into named topics.
    Best-effort: returns [] if the AI isn't configured or the call fails,
    the rest of the dashboard still works without it."""
    if not anthropic_client or not sample_texts:
        return []
    try:
        joined = "\n".join(f"- {t[:200]}" for t in sample_texts[:ANALYTICS_MAX_TOPIC_SAMPLE])
        response = anthropic_client.messages.create(
            model="claude-sonnet-4-5", max_tokens=700,
            messages=[{
                "role": "user",
                "content": (
                    "These are real messages customers sent to a small business's AI chat widget. "
                    "Group them into at most 8 short topic labels (2-4 words each, e.g. 'Pricing questions', "
                    "'Delivery times', 'Product availability') and count how many messages fall under each. "
                    "Reply with ONLY raw JSON, no markdown fences: "
                    '{"topics": [{"label": "...", "count": 0}]}\n\n' + joined
                ),
            }],
        )
        raw = response.content[0].text.strip()
        raw = re.sub(r"^```(?:json)?|```$", "", raw.strip(), flags=re.MULTILINE).strip()
        parsed = json.loads(raw)
        topics = parsed.get("topics", [])
        topics.sort(key=lambda t: t.get("count", 0), reverse=True)
        return topics[:8]
    except Exception as e:
        logging.error(f"[ANALYTICS TOPICS] {e}")
        return []


def _analytics_sentiment_trend(user_messages):
    """Daily average sentiment across real customer messages, using the
    local distilbert model (already loaded at startup — no external API
    cost). Returns {} if the model isn't installed."""
    if not SENTIMENT_AVAILABLE or not _sentiment_pipe:
        return {}
    by_day = {}
    # Evenly sample if there are more messages than the cap, so the trend
    # still spans the whole window instead of only covering the tail end.
    msgs = user_messages
    if len(msgs) > ANALYTICS_MAX_SENTIMENT_SAMPLE:
        step = len(msgs) / ANALYTICS_MAX_SENTIMENT_SAMPLE
        msgs = [msgs[int(i * step)] for i in range(ANALYTICS_MAX_SENTIMENT_SAMPLE)]
    for m in msgs:
        text = (m.content or "").strip()[:512]
        if not text:
            continue
        try:
            result = _sentiment_pipe(text)[0]
            signed = result["score"] if result["label"] == "POSITIVE" else -result["score"]
        except Exception:
            continue
        day = m.created_at.date().isoformat()
        by_day.setdefault(day, []).append(signed)
    return {day: round(sum(vals) / len(vals), 3) for day, vals in sorted(by_day.items())}


@app.route("/api/analytics/insights", methods=["GET"])
def analytics_insights():
    user, err = _erp_user_or_401()
    if err: return err
    org = _org_for_user(user["id"])
    if not org:
        return jsonify({"error": "No workspace found. Set up your chat widget first."}), 404
    _, err = _org_member_or_403(user, org.id, roles=("owner", "admin"))
    if err: return err

    days = request.args.get("days", 30, type=int)
    days = max(1, min(days, 90))
    since = datetime.utcnow() - timedelta(days=days)

    rows = (WidgetMessage.query.filter_by(org_id=org.id)
            .filter(WidgetMessage.created_at >= since)
            .order_by(WidgetMessage.created_at.asc()).all())

    if not rows:
        return jsonify({
            "has_data": False, "days": days,
            "note": "No widget conversations recorded in this window yet.",
        }), 200

    conversations_per_day = {}
    peak_hours = {h: 0 for h in range(24)}
    sessions = {}  # session_id -> list of rows, in order
    for r in rows:
        peak_hours[r.created_at.hour] += 1
        sessions.setdefault(r.session_id, []).append(r)

    for sid, msgs in sessions.items():
        day = msgs[0].created_at.date().isoformat()
        conversations_per_day[day] = conversations_per_day.get(day, 0) + 1

    user_messages = [r for r in rows if r.role == "user"]

    drop_offs = []
    for sid, msgs in sessions.items():
        if msgs[-1].role == "user":
            drop_offs.append({
                "session_id": sid,
                "last_message": msgs[-1].content[:200],
                "last_message_at": msgs[-1].created_at.isoformat(),
                "message_count": len(msgs),
            })
    drop_offs.sort(key=lambda d: d["last_message_at"], reverse=True)

    topic_sample = [m.content for m in user_messages if m.content and m.content.strip()]
    # newest-first so topic clustering reflects recent conversations, not
    # whichever happened to be oldest within the window.
    topic_sample = list(reversed(topic_sample))

    top_topics = []
    topics_blocked_reason = None
    if topic_sample and anthropic_client:
        gate_result = gate_ai_usage(user, "analytics_ai_topics")
        if gate_result is None:
            top_topics = _analytics_topics(topic_sample)
        else:
            resp, _status = gate_result
            try:
                topics_blocked_reason = (resp.get_json() or {}).get("error")
            except Exception:
                topics_blocked_reason = "Topic clustering limit reached."

    return jsonify({
        "has_data": True, "days": days,
        "total_conversations": len(sessions),
        "total_messages": len(rows),
        "conversations_per_day": conversations_per_day,
        "peak_hours": peak_hours,
        "sentiment_trend": _analytics_sentiment_trend(user_messages),
        "sentiment_available": SENTIMENT_AVAILABLE,
        "top_topics": top_topics,
        "topics_available": anthropic_client is not None,
        "topics_blocked_reason": topics_blocked_reason,
        "drop_off_sessions": drop_offs[:10],
        "drop_off_count": len(drop_offs),
    }), 200


# ════════════════════════════════════════════════════════════
# STAGE 235: AI TRIBUTE / PROMO VIDEO GENERATOR
# Turns a business's own photos into a short, gentle animated video with
# text overlay — built on OpenAI Sora (+ a bonus DALL·E poster) and/or
# Google Vertex Veo (+ a bonus Imagen poster), both BYOK like every other
# paid-provider integration in this app. Generation genuinely takes
# minutes, so each request just creates a job row and hands the actual
# work to a background thread; the owner polls for status. Output goes
# to the owner's own GCS bucket when they've connected one (STAGE ~,
# reusing get_gcs_bucket) so it has a stable, shareable link; otherwise
# it's kept in local ephemeral storage as a best-effort fallback and
# served back through an authenticated download route.
# ════════════════════════════════════════════════════════════

def _safe_local_dir(env_var: str, subdir_name: str) -> str:
    """Resolve a writable local directory for this feature without ever
    crashing the whole app at import time. Preference order:
    1) explicit env override, 2) a folder next to this file (stable,
    doesn't depend on the OS temp dir being usable), 3) tempfile.gettempdir()
    as a last resort. If every candidate fails (e.g. disk quota exceeded),
    log and fall back to a relative path without creating it yet — first
    real use will retry and surface a normal 500 for that one request
    instead of taking down the whole WSGI app.
    """
    candidates = []
    env_val = os.environ.get(env_var)
    if env_val:
        candidates.append(env_val)
    candidates.append(os.path.join(os.path.dirname(os.path.abspath(__file__)), "var", subdir_name))
    try:
        candidates.append(os.path.join(tempfile.gettempdir(), subdir_name))
    except Exception:
        pass
    for path in candidates:
        try:
            os.makedirs(path, exist_ok=True)
            return path
        except OSError as e:
            logging.warning(f"[TRIBUTE] directory '{path}' unavailable ({e}); trying next fallback")
    fallback = os.path.join("var", subdir_name)
    logging.error(f"[TRIBUTE] no writable directory found for {subdir_name}; deferring to first use of '{fallback}'")
    return fallback

TRIBUTE_UPLOAD_DIR = _safe_local_dir("TRIBUTE_UPLOAD_DIR", "tribute_uploads")
TRIBUTE_MEDIA_DIR = _safe_local_dir("TRIBUTE_MEDIA_DIR", "tribute_media")
TRIBUTE_DEFAULT_PROMPT = (
    "Gentle animated tribute with soft zoom and light transitions between the photos. "
    "Soft lighting, warm, hopeful, respectful mood."
)
TRIBUTE_MAX_IMAGES = 4
TRIBUTE_MAX_SECONDS = 12


class TributeVideoJob(db.Model):
    __tablename__ = "tribute_video_jobs"
    id             = db.Column(db.Integer,  primary_key=True)
    owner_user_id  = db.Column(db.Integer,  db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    provider       = db.Column(db.String(20), nullable=False)  # "openai_sora" | "google_veo"
    prompt         = db.Column(db.Text,     nullable=False)
    seconds        = db.Column(db.Integer,  nullable=False, default=8)
    status         = db.Column(db.String(20), nullable=False, default="pending")  # pending|running|complete|failed
    video_url      = db.Column(db.String(500), nullable=True)   # external hosted URL or our own download route
    video_expires_note = db.Column(db.String(200), nullable=True)
    poster_url     = db.Column(db.String(500), nullable=True)
    error_message  = db.Column(db.Text,     nullable=True)
    created_at     = db.Column(db.DateTime, default=datetime.utcnow, index=True)
    completed_at   = db.Column(db.DateTime, nullable=True)

    def to_dict(self):
        return {
            "id": self.id, "provider": self.provider, "prompt": self.prompt,
            "seconds": self.seconds, "status": self.status,
            "video_url": self.video_url, "video_expires_note": self.video_expires_note,
            "poster_url": self.poster_url, "error_message": self.error_message,
            "created_at": self.created_at.isoformat(),
            "completed_at": self.completed_at.isoformat() if self.completed_at else None,
        }


def _tribute_store_output(owner_user_id, job_id, local_path, content_type, filename):
    """Prefer the owner's own GCS bucket (stable link); fall back to our
    own ephemeral local folder + an authenticated download route."""
    bucket = get_gcs_bucket(owner_user_id)
    if bucket:
        try:
            blob_path = f"users/{owner_user_id}/tribute_videos/{job_id}/{filename}"
            blob = bucket.blob(blob_path)
            blob.upload_from_filename(local_path, content_type=content_type)
            url = blob.generate_signed_url(version="v4", expiration=timedelta(days=7), method="GET")
            return url, "Link expires in 7 days — reconnect to re-share, or download and keep your own copy."
        except Exception as e:
            logging.error(f"[TRIBUTE GCS STORE] job={job_id}: {e}")
    # Fallback: keep it in local ephemeral storage.
    job_dir = os.path.join(TRIBUTE_MEDIA_DIR, str(job_id))
    os.makedirs(job_dir, exist_ok=True)
    dest = os.path.join(job_dir, filename)
    try:
        shutil.copyfile(local_path, dest)
    except Exception as e:
        logging.error(f"[TRIBUTE LOCAL STORE] job={job_id}: {e}")
        return None, None
    return f"/api/tribute-video/media/{job_id}/{filename}", \
           "Stored on this server only — not backed by cloud storage. Connect Google Cloud Storage in Workspace settings for a durable link."


def _tribute_run_openai_sora(app_ref, job_id, owner_user_id, image_paths, prompt, seconds):
    app_ref = app_ref or app  # STAGE 239: RQ can't pickle a live Flask app across processes
    with app_ref.app_context():
        job = TributeVideoJob.query.get(job_id)
        if not job:
            return
        try:
            byok_key = get_effective_credential(owner_user_id, "openai", "api_key", None)
            client = OpenAI(api_key=byok_key) if byok_key else openai_client
            if not client:
                raise RuntimeError("No OpenAI API key configured. Add one in Workspace → Integrations.")

            uploaded_ids = []
            for path in image_paths:
                with open(path, "rb") as f:
                    up = client.files.create(file=f, purpose="vision")
                uploaded_ids.append(up.id)

            video = client.videos.create(
                model="sora-1", prompt=prompt, size="1080x1920",
                seconds=seconds, reference_image_ids=uploaded_ids,
            )
            hosted_url = video.data[0].url

            # Bonus poster image — best-effort, doesn't fail the whole job.
            poster_url = None
            try:
                img = client.images.generate(model="gpt-image-1", prompt=f"Watercolor tribute poster. {prompt}", size="1024x1024")
                poster_url = img.data[0].url
            except Exception as e:
                logging.error(f"[TRIBUTE SORA POSTER] job={job_id}: {e}")

            # Download Sora's hosted copy and re-host it ourselves so the
            # link doesn't silently expire on the provider's side later.
            local_video = os.path.join(TRIBUTE_UPLOAD_DIR, f"{job_id}_sora.mp4")
            resp = requests.get(hosted_url, timeout=120)
            with open(local_video, "wb") as f:
                f.write(resp.content)
            stored_url, note = _tribute_store_output(owner_user_id, job_id, local_video, "video/mp4", "sora_tribute.mp4")

            job.video_url = stored_url or hosted_url
            job.video_expires_note = note or "This is OpenAI's own hosted link and may expire — download it soon."
            job.poster_url = poster_url
            job.status = "complete"
            job.completed_at = datetime.utcnow()
            db.session.commit()
        except Exception as e:
            logging.error(f"[TRIBUTE SORA] job={job_id}: {e}")
            job.status = "failed"
            job.error_message = str(e)[:500]
            job.completed_at = datetime.utcnow()
            db.session.commit()
        finally:
            for path in image_paths:
                try: os.remove(path)
                except Exception: pass


def _tribute_run_google_veo(app_ref, job_id, owner_user_id, image_paths, prompt, seconds):
    app_ref = app_ref or app  # STAGE 239: RQ can't pickle a live Flask app across processes
    with app_ref.app_context():
        job = TributeVideoJob.query.get(job_id)
        if not job:
            return
        try:
            if not VERTEX_AVAILABLE:
                raise RuntimeError("Video generation library not installed on the server (google-cloud-aiplatform).")
            if not PIL_AVAILABLE:
                raise RuntimeError("Image library not installed on the server (Pillow).")
            # Same BYOK-aware service-account auth as Vertex AI Lyria.
            vertex_creds = _get_google_credentials(owner_user_id, "vertex_ai_veo", "", _VERTEX_AI_SCOPES)
            project_id = get_effective_credential(owner_user_id, "vertex_ai_veo", "project_id", "")
            location = get_effective_credential(owner_user_id, "vertex_ai_veo", "location", "") or "us-central1"
            if not vertex_creds or not project_id:
                raise RuntimeError("Connect Google Vertex AI (service account + project ID) in Workspace → Integrations first.")

            _vertexai_sdk.init(project=project_id, location=location, credentials=vertex_creds)

            ref_image = PILImage.open(image_paths[0])
            video_model = VideoGenerationModel.from_pretrained("veo-3.0-generate-001")
            videos = video_model.generate_videos(
                prompt=prompt, image=ref_image, duration_seconds=seconds,
                aspect_ratio="9:16", number_of_videos=1,
            )
            local_video = os.path.join(TRIBUTE_UPLOAD_DIR, f"{job_id}_veo.mp4")
            videos[0].save(local_video)

            poster_url = None
            try:
                image_model = VertexImageModel.from_pretrained("imagen-3.0-generate-001")
                imgs = image_model.generate_images(prompt=f"Watercolor tribute poster. {prompt}", number_of_images=1)
                local_poster = os.path.join(TRIBUTE_UPLOAD_DIR, f"{job_id}_imagen.png")
                imgs[0].save(local_poster)
                poster_url, _ = _tribute_store_output(owner_user_id, job_id, local_poster, "image/png", "imagen_poster.png")
                try: os.remove(local_poster)
                except Exception: pass
            except Exception as e:
                logging.error(f"[TRIBUTE VEO POSTER] job={job_id}: {e}")

            stored_url, note = _tribute_store_output(owner_user_id, job_id, local_video, "video/mp4", "veo_tribute.mp4")
            job.video_url = stored_url
            job.video_expires_note = note
            job.poster_url = poster_url
            job.status = "complete"
            job.completed_at = datetime.utcnow()
            db.session.commit()
        except Exception as e:
            logging.error(f"[TRIBUTE VEO] job={job_id}: {e}")
            job.status = "failed"
            job.error_message = str(e)[:500]
            job.completed_at = datetime.utcnow()
            db.session.commit()
        finally:
            for path in image_paths:
                try: os.remove(path)
                except Exception: pass


@app.route("/api/tribute-video/generate", methods=["POST"])
@csrf.exempt
def tribute_video_generate():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401

    provider = (request.form.get("provider") or "openai_sora").strip()
    if provider not in ("openai_sora", "google_veo"):
        return jsonify({"error": "provider must be 'openai_sora' or 'google_veo'."}), 400
    prompt = (request.form.get("prompt") or TRIBUTE_DEFAULT_PROMPT).strip()[:1000]
    seconds = min(request.form.get("seconds", 8, type=int) or 8, TRIBUTE_MAX_SECONDS)

    files = request.files.getlist("images")
    if not files:
        return jsonify({"error": "Attach at least one photo."}), 400
    if len(files) > TRIBUTE_MAX_IMAGES:
        return jsonify({"error": f"Attach at most {TRIBUTE_MAX_IMAGES} photos."}), 400

    if provider == "openai_sora" and not (get_effective_credential(user["id"], "openai", "api_key", None) or openai_client):
        return jsonify({"error": "Connect your OpenAI API key in Workspace → Integrations first."}), 400
    if provider == "google_veo" and not get_user_credentials(user["id"], "vertex_ai_veo"):
        return jsonify({"error": "Connect Google Vertex AI in Workspace → Integrations first."}), 400

    job = TributeVideoJob(owner_user_id=user["id"], provider=provider, prompt=prompt, seconds=seconds, status="running")
    db.session.add(job)
    db.session.commit()

    saved_paths = []
    for f in files:
        ext = os.path.splitext(f.filename or "")[1][:6] or ".jpg"
        dest = os.path.join(TRIBUTE_UPLOAD_DIR, f"{job.id}_{secrets.token_hex(4)}{ext}")
        f.save(dest)
        saved_paths.append(dest)

    worker = _tribute_run_openai_sora if provider == "openai_sora" else _tribute_run_google_veo
    enqueue_job(worker, app, job.id, user["id"], saved_paths, prompt, seconds, job_timeout=1800)

    org = _org_for_user(user["id"])
    if org:
        _audit(org.id, user["id"], user["email"], "tribute_video.requested", "tribute_video_job", job.id, {"provider": provider})
    return jsonify({"ok": True, "job": job.to_dict()}), 202


