@app.route("/api/tribute-video/media/<int:job_id>/<path:filename>", methods=["GET"])
def tribute_video_media(job_id, filename):
    """Authenticated fallback download for output stored on our own
    ephemeral disk (i.e. the owner hasn't connected a GCS bucket)."""
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    job = TributeVideoJob.query.filter_by(id=job_id, owner_user_id=user["id"]).first()
    if not job:
        return jsonify({"error": "Job not found."}), 404
    job_dir = os.path.join(TRIBUTE_MEDIA_DIR, str(job_id))
    return send_from_directory(job_dir, filename, as_attachment=True)


# ════════════════════════════════════════════════════════════
# STAGE 236: TRAINING PIPELINE — FINE-TUNE ON YOUR OWN CONVERSATIONS
# The last item from the original wishlist. Honestly scoped: Anthropic
# doesn't offer public fine-tuning the way OpenAI does, so this calls
# OpenAI's real Fine-tuning API (BYOK — billed to and owned by the org,
# same as every other paid provider here), training on the business's
# own real widget-chat transcripts (including any human "[Team]"
# corrections, which are often the highest-quality examples). Once a
# job succeeds, the owner can "activate" the resulting model for their
# widget, which then bypasses the shared multi-provider default.
# ════════════════════════════════════════════════════════════

FINE_TUNE_MIN_EXAMPLES = 10
FINE_TUNE_MAX_EXAMPLES = 2000
FINE_TUNE_DEFAULT_BASE_MODEL = "gpt-4o-mini-2024-07-18"


class FineTuneJob(db.Model):
    __tablename__     = "fine_tune_jobs"
    id                = db.Column(db.Integer,  primary_key=True)
    owner_user_id     = db.Column(db.Integer,  db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    org_id            = db.Column(db.Integer,  db.ForeignKey("organizations.id"), nullable=False, index=True)
    base_model        = db.Column(db.String(80), nullable=False)
    openai_file_id    = db.Column(db.String(80), nullable=True)
    openai_job_id     = db.Column(db.String(80), nullable=True)
    example_count     = db.Column(db.Integer,  nullable=False, default=0)
    status            = db.Column(db.String(20), nullable=False, default="running")  # running|succeeded|failed
    result_model_id   = db.Column(db.String(120), nullable=True)
    error_message     = db.Column(db.Text,     nullable=True)
    created_at        = db.Column(db.DateTime, default=datetime.utcnow, index=True)
    completed_at      = db.Column(db.DateTime, nullable=True)

    def to_dict(self):
        return {
            "id": self.id, "base_model": self.base_model, "example_count": self.example_count,
            "status": self.status, "result_model_id": self.result_model_id,
            "error_message": self.error_message, "created_at": self.created_at.isoformat(),
            "completed_at": self.completed_at.isoformat() if self.completed_at else None,
        }


def _training_build_dataset(org_id, system_prompt):
    """Pairs up real user->assistant turns from this org's widget chat
    history into OpenAI chat fine-tuning format. Human "[Team]" replies
    are included and un-prefixed — a human correcting the AI is exactly
    the kind of example fine-tuning should learn from."""
    rows = (WidgetMessage.query.filter_by(org_id=org_id)
            .order_by(WidgetMessage.session_id.asc(), WidgetMessage.created_at.asc()).all())
    examples = []
    pending_user = None
    for r in rows:
        if r.role == "user":
            pending_user = r.content
        elif r.role == "assistant" and pending_user:
            assistant_text = r.content[4:].strip() if r.content.startswith("[Team]") else r.content
            if pending_user.strip() and assistant_text.strip():
                examples.append({
                    "messages": [
                        {"role": "system", "content": system_prompt},
                        {"role": "user", "content": pending_user[:4000]},
                        {"role": "assistant", "content": assistant_text[:4000]},
                    ]
                })
            pending_user = None
    return examples[:FINE_TUNE_MAX_EXAMPLES]


@app.route("/api/training/dataset-preview", methods=["GET"])
def training_dataset_preview():
    user, err = _erp_user_or_401()
    if err: return err
    org = _org_for_user(user["id"])
    if not org:
        return jsonify({"error": "No workspace found."}), 404
    _, err = _org_member_or_403(user, org.id, roles=("owner", "admin"))
    if err: return err

    cfg = WidgetConfig.query.filter_by(org_id=org.id).first()
    system_prompt = (cfg.system_prompt if cfg else None) or "You are a helpful support assistant for this business."
    examples = _training_build_dataset(org.id, system_prompt)
    return jsonify({
        "example_count": len(examples),
        "minimum_required": FINE_TUNE_MIN_EXAMPLES,
        "ready": len(examples) >= FINE_TUNE_MIN_EXAMPLES,
        "sample": [e["messages"][1:] for e in examples[:3]],  # user+assistant only, no system prompt noise
    }), 200


@app.route("/api/training/start", methods=["POST"])
@csrf.exempt
def training_start():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    org = _org_for_user(user["id"])
    if not org:
        return jsonify({"error": "No workspace found."}), 404
    _, err = _org_member_or_403(user, org.id, roles=("owner", "admin"))
    if err: return err

    byok_key = get_effective_credential(user["id"], "openai", "api_key", None)
    if not byok_key:
        return jsonify({"error": "Connect your own OpenAI API key in Workspace → Integrations first — "
                                  "fine-tuning jobs are billed to and owned by your own OpenAI account."}), 400

    data = request.get_json(silent=True) or {}
    base_model = (data.get("base_model") or FINE_TUNE_DEFAULT_BASE_MODEL).strip()

    cfg = WidgetConfig.query.filter_by(org_id=org.id).first()
    system_prompt = (cfg.system_prompt if cfg else None) or "You are a helpful support assistant for this business."
    examples = _training_build_dataset(org.id, system_prompt)
    if len(examples) < FINE_TUNE_MIN_EXAMPLES:
        return jsonify({"error": f"Need at least {FINE_TUNE_MIN_EXAMPLES} real conversation exchanges before "
                                  f"training — you currently have {len(examples)}. Keep using your chat widget "
                                  f"and check back."}), 400

    dataset_path = os.path.join(tempfile.gettempdir(), f"training_{org.id}_{secrets.token_hex(6)}.jsonl")
    try:
        with open(dataset_path, "w") as f:
            for ex in examples:
                f.write(json.dumps(ex) + "\n")

        client = OpenAI(api_key=byok_key)
        with open(dataset_path, "rb") as f:
            uploaded = client.files.create(file=f, purpose="fine-tune")
        ft_job = client.fine_tuning.jobs.create(training_file=uploaded.id, model=base_model)

        job = FineTuneJob(owner_user_id=user["id"], org_id=org.id, base_model=base_model,
                           openai_file_id=uploaded.id, openai_job_id=ft_job.id,
                           example_count=len(examples), status="running")
        db.session.add(job)
        db.session.commit()
        _audit(org.id, user["id"], user["email"], "training.job_started", "fine_tune_job", job.id,
               {"base_model": base_model, "example_count": len(examples)})
        return jsonify({"ok": True, "job": job.to_dict()}), 202
    except Exception as e:
        logging.error(f"[TRAINING START] org={org.id}: {e}")
        return jsonify({"error": str(e)}), 500
    finally:
        try: os.remove(dataset_path)
        except Exception: pass


def _training_refresh_job(job, byok_key):
    """Best-effort live status pull from OpenAI — never raises, so a
    provider hiccup just means the owner sees last-known status."""
    if job.status not in ("running",) or not job.openai_job_id:
        return job
    try:
        client = OpenAI(api_key=byok_key)
        remote = client.fine_tuning.jobs.retrieve(job.openai_job_id)
        if remote.status == "succeeded":
            job.status = "succeeded"
            job.result_model_id = remote.fine_tuned_model
            job.completed_at = datetime.utcnow()
            db.session.commit()
        elif remote.status in ("failed", "cancelled"):
            job.status = "failed"
            job.error_message = (getattr(remote, "error", None) and str(remote.error)) or f"Job {remote.status}."
            job.completed_at = datetime.utcnow()
            db.session.commit()
    except Exception as e:
        logging.error(f"[TRAINING REFRESH] job={job.id}: {e}")
    return job


