# ════════════════════════════════════════════════════════════
# STAGE 240: FraudFlag — persisted output of the platform-wide fraud/
# anomaly scan (see the rule functions and /api/fraud/* routes further
# up, grouped with the Stage 132 supplier fraud scan). source_type +
# source_id point back at whatever row triggered the flag
# (supplier_expense/invoice/ledger_entry/savings_transaction — never a
# separate copy of the money-moving data itself), so this table is
# purely an alerting/review layer, not a second source of truth.
# ════════════════════════════════════════════════════════════
class FraudFlag(db.Model):
    __tablename__    = "fraud_flags"
    id               = db.Column(db.Integer,  primary_key=True)
    owner_user_id    = db.Column(db.Integer,  db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    source_type      = db.Column(db.String(30), nullable=False, index=True)  # supplier_expense, invoice, ledger_entry, savings_transaction
    source_id        = db.Column(db.String(40), nullable=False)
    rule_code        = db.Column(db.String(50), nullable=False, index=True)
    severity         = db.Column(db.String(10), nullable=False, default="medium")  # low, medium, high
    title            = db.Column(db.String(200), nullable=False)
    detail           = db.Column(db.Text,      nullable=False)
    amount           = db.Column(db.Float,     nullable=True)
    currency         = db.Column(db.String(8), nullable=True)
    occurred_at      = db.Column(db.DateTime,  nullable=True)  # when the underlying event happened
    status           = db.Column(db.String(20), nullable=False, default="open", index=True)  # open, reviewing, confirmed_fraud, dismissed
    resolution_note  = db.Column(db.String(500), nullable=True)
    resolved_by      = db.Column(db.Integer,  db.ForeignKey("user_accounts.id"), nullable=True)
    resolved_at      = db.Column(db.DateTime, nullable=True)
    created_at       = db.Column(db.DateTime, default=datetime.utcnow, index=True)

    def to_dict(self):
        return {
            "id": self.id, "source_type": self.source_type, "source_id": self.source_id,
            "rule_code": self.rule_code, "severity": self.severity, "title": self.title,
            "detail": self.detail, "amount": self.amount, "currency": self.currency,
            "occurred_at": self.occurred_at.isoformat() if self.occurred_at else None,
            "status": self.status, "resolution_note": self.resolution_note,
            "resolved_at": self.resolved_at.isoformat() if self.resolved_at else None,
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }


# ════════════════════════════════════════════════════════════
# STAGE 241: PER-BUSINESS FRAUD/ANOMALY THRESHOLDS
# The Stage 240 rules above used platform-wide hardcoded constants
# (FRAUD_OFFHOURS_* and a fixed 2.5-stdev / 3x-mean multiplier) since
# there was no per-business config yet. A business with naturally
# lumpy spending (e.g. one big monthly stock order) would get noisy
# outlier flags at 2.5 stdev; a business that legitimately operates
# through the night would get noisy off-hours flags at the 22:00-05:00
# default window. This table lets each business override its own
# thresholds; a business with no row here still gets the same platform
# defaults as before, so nothing changes for anyone who never opens
# the settings panel.
# ════════════════════════════════════════════════════════════
class FraudSettings(db.Model):
    __tablename__            = "fraud_settings"
    id                       = db.Column(db.Integer,  primary_key=True)
    owner_user_id            = db.Column(db.Integer,  db.ForeignKey("user_accounts.id"), nullable=False, unique=True, index=True)
    offhours_start_hour      = db.Column(db.Integer,  nullable=False, default=FRAUD_OFFHOURS_START_HOUR)   # UTC hour, 0-23
    offhours_end_hour        = db.Column(db.Integer,  nullable=False, default=FRAUD_OFFHOURS_END_HOUR)     # UTC hour, 0-23
    offhours_abs_floor       = db.Column(db.Float,    nullable=False, default=FRAUD_OFFHOURS_ABS_FLOOR)    # fallback "large" amount pre-history
    offhours_mean_multiplier = db.Column(db.Float,    nullable=False, default=3.0)   # off-hours txn flagged once it's this many x normal-hours average
    outlier_stdev_multiplier = db.Column(db.Float,    nullable=False, default=2.5)   # supplier/savings amount flagged once it's this many stdevs from history
    # STAGE 522: Enterprise Roadmap Part 2.6b — ML Spending Rhythm.
    use_ml_rhythm             = db.Column(db.Boolean, nullable=False, default=True)  # learn day-of-week/month rhythm instead of a flat stdev, once there's enough history
    rhythm_zscore_multiplier  = db.Column(db.Float,    nullable=False, default=3.0)  # amount flagged once it's this many residual-stdevs from the LEARNED rhythm
    # STAGE 522b: Enterprise Roadmap Part 2.6c — ML anomaly engine choice.
    # "rhythm_zscore": the seasonal-decomposition + residual z-score above (default, always available).
    # "isolation_forest": scikit-learn IsolationForest over amount + cyclical day-of-week/day-of-month +
    #   rhythm residual — a real multivariate ML model, not a single-number threshold. Falls back to
    #   rhythm_zscore automatically (per business, per scan) if scikit-learn isn't installed or there
    #   isn't yet enough history to fit a forest, so switching this on is never a silent no-op.
    anomaly_method             = db.Column(db.String(20), nullable=False, default="rhythm_zscore")
    updated_at               = db.Column(db.DateTime, default=datetime.utcnow, onupdate=datetime.utcnow)

    def to_dict(self):
        return {
            "offhours_start_hour": self.offhours_start_hour, "offhours_end_hour": self.offhours_end_hour,
            "offhours_abs_floor": self.offhours_abs_floor, "offhours_mean_multiplier": self.offhours_mean_multiplier,
            "outlier_stdev_multiplier": self.outlier_stdev_multiplier,
            "use_ml_rhythm": self.use_ml_rhythm, "rhythm_zscore_multiplier": self.rhythm_zscore_multiplier,
            "anomaly_method": self.anomaly_method, "isolation_forest_available": SKLEARN_AVAILABLE,
            "is_custom": True,
            "updated_at": self.updated_at.isoformat() if self.updated_at else None,
        }


FRAUD_SETTINGS_DEFAULTS = {
    "offhours_start_hour": FRAUD_OFFHOURS_START_HOUR, "offhours_end_hour": FRAUD_OFFHOURS_END_HOUR,
    "offhours_abs_floor": FRAUD_OFFHOURS_ABS_FLOOR, "offhours_mean_multiplier": 3.0,
    "outlier_stdev_multiplier": 2.5, "use_ml_rhythm": True, "rhythm_zscore_multiplier": 3.0,
    "anomaly_method": "rhythm_zscore", "isolation_forest_available": SKLEARN_AVAILABLE,
    "is_custom": False, "updated_at": None,
}


def _fraud_settings_for(owner_user_id):
    """Returns this business's own saved thresholds if it has ever saved
    any, otherwise the platform defaults — as a plain dict so the scan
    functions below don't need to care which case they're in."""
    row = FraudSettings.query.filter_by(owner_user_id=owner_user_id).first()
    return row.to_dict() if row else dict(FRAUD_SETTINGS_DEFAULTS)


def _fraud_settings_validate(data):
    """Returns (cleaned_dict, error_message). error_message is None on
    success. Bounds are loose but real: they exist to stop a fat-fingered
    value (e.g. a 0-stdev multiplier) from turning the scan into either
    a no-op or a flag-everything firehose, not to second-guess a
    business's judgment about its own patterns."""
    try:
        start_hour = int(data.get("offhours_start_hour", FRAUD_OFFHOURS_START_HOUR))
        end_hour = int(data.get("offhours_end_hour", FRAUD_OFFHOURS_END_HOUR))
        abs_floor = float(data.get("offhours_abs_floor", FRAUD_OFFHOURS_ABS_FLOOR))
        mean_mult = float(data.get("offhours_mean_multiplier", 3.0))
        stdev_mult = float(data.get("outlier_stdev_multiplier", 2.5))
        use_ml_rhythm = bool(data.get("use_ml_rhythm", True))
        rhythm_zscore_mult = float(data.get("rhythm_zscore_multiplier", 3.0))
        anomaly_method = (data.get("anomaly_method") or "rhythm_zscore").strip().lower()
    except (TypeError, ValueError):
        return None, "All threshold fields must be numbers."
    if not (0 <= start_hour <= 23) or not (0 <= end_hour <= 23):
        return None, "Off-hours start/end must be an hour between 0 and 23 (UTC)."
    if abs_floor < 0:
        return None, "The off-hours amount floor can't be negative."
    if not (0.5 <= mean_mult <= 20):
        return None, "The off-hours multiplier must be between 0.5 and 20."
    if not (0.5 <= stdev_mult <= 10):
        return None, "The outlier sensitivity must be between 0.5 and 10 standard deviations."
    if not (0.5 <= rhythm_zscore_mult <= 10):
        return None, "The spending-rhythm sensitivity must be between 0.5 and 10 standard deviations."
    if anomaly_method not in ("rhythm_zscore", "isolation_forest"):
        return None, "anomaly_method must be 'rhythm_zscore' or 'isolation_forest'."
    if anomaly_method == "isolation_forest" and not SKLEARN_AVAILABLE:
        return None, ("Isolation Forest anomaly detection requires scikit-learn on the server "
                       "(pip install scikit-learn). Ask your administrator to install it, or "
                       "keep using the seasonal-rhythm method for now.")
    return {
        "offhours_start_hour": start_hour, "offhours_end_hour": end_hour,
        "offhours_abs_floor": abs_floor, "offhours_mean_multiplier": mean_mult,
        "outlier_stdev_multiplier": stdev_mult,
        "use_ml_rhythm": use_ml_rhythm, "rhythm_zscore_multiplier": rhythm_zscore_mult,
        "anomaly_method": anomaly_method,
    }, None


@app.route("/api/fraud/settings", methods=["GET"])
def fraud_settings_get():
    user, err = _erp_user_or_401()
    if err: return err
    return jsonify({"settings": _fraud_settings_for(user["id"]), "defaults": FRAUD_SETTINGS_DEFAULTS}), 200


@app.route("/api/fraud/settings", methods=["PUT"])
@csrf.exempt
def fraud_settings_update():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    cleaned, error = _fraud_settings_validate(data)
    if error: return jsonify({"error": error}), 400
    try:
        row = FraudSettings.query.filter_by(owner_user_id=user["id"]).first()
        if not row:
            row = FraudSettings(owner_user_id=user["id"])
            db.session.add(row)
        for k, v in cleaned.items():
            setattr(row, k, v)
        db.session.commit()
        org = _org_for_user(user["id"])
        if org:
            _audit(org.id, user["id"], user.get("email"), "fraud.settings_updated", "fraud_settings", row.id, cleaned)
        return jsonify({"settings": row.to_dict()}), 200
    except Exception as e:
        db.session.rollback(); logging.error(f"[FRAUD SETTINGS UPDATE] {e}")
        return jsonify({"error": "Could not save settings."}), 500


@app.route("/api/fraud/settings", methods=["DELETE"])
@csrf.exempt
def fraud_settings_reset():
    """Deletes this business's custom thresholds, reverting it to
    platform defaults — kept separate from PUT so 'reset' can never be
    mistaken for 'save these particular numbers'."""
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    try:
        row = FraudSettings.query.filter_by(owner_user_id=user["id"]).first()
        if row:
            db.session.delete(row)
            db.session.commit()
        return jsonify({"settings": dict(FRAUD_SETTINGS_DEFAULTS)}), 200
    except Exception as e:
        db.session.rollback(); logging.error(f"[FRAUD SETTINGS RESET] {e}")
        return jsonify({"error": "Could not reset settings."}), 500


# ════════════════════════════════════════════════════════════
# STAGE 522: ML-BASED SPENDING RHYTHM (Enterprise Roadmap Part 2.6b)
# Doc: "The Fraud & Anomaly Monitor currently relies on manual
# sensitivity settings (Standard Deviations). Improving this with
# Machine Learning that automatically learns a business's unique
# 'spending rhythm' would reduce false positives for 'lumpy'
# businesses."
#
# The Stage 132/240 checks above compare every amount against one flat
# mean/stdev across ALL of a supplier's or group's history. That's
# fine for steady, evenly-spaced spending — but a business that places
# one big stock order on the last Friday of every month looks, to a
# flat stdev, exactly like a business being defrauded once a month:
# both are "large outlier amounts on scattered dates." Only ever
# widening the stdev multiplier to silence the false positives also
# blinds the check to real anomalies.
#
# This fits a lightweight seasonal model per business (pure Python —
# no numpy/sklearn dependency, so it never degrades even on a minimal
# deployment) that learns from a business's own transaction history:
#   1. A day-of-week seasonal factor (Monday spending vs Friday
#      spending, etc.)
#   2. A day-of-month rhythm factor (early/mid/late month — this is
#      what actually recognizes "big order at month-end restock" or
#      "big payout on payday" as NORMAL rather than anomalous)
#   3. A linear trend, so a gradually growing or shrinking business
#      doesn't get flagged just because its baseline amounts drift
#      over time.
# Every historical amount is "deseasonalized" by dividing out its
# weekday/month-position factor and detrended; what's left is the
# residual — the part of the amount NOT explained by the business's
# normal rhythm. A new amount is scored the same way and compared to
# the residual's own mean/stdev. Only amounts whose residual is a
# genuine outlier get flagged — not every amount that merely looks
# large in isolation.
#
# Falls back cleanly to the flat Stage 240 stdev check whenever there
# isn't enough history to fit a seasonal pattern yet (cold start, new
# business/supplier/group) or when a business has switched "ML
# Spending Rhythm" off in Fraud & Anomaly Monitor > Settings.
# ════════════════════════════════════════════════════════════
FRAUD_RHYTHM_MIN_SAMPLES = 8          # below this, seasonality is noise — fall back to flat stdev
FRAUD_RHYTHM_MONTH_BUCKETS = {"early": (1, 10), "mid": (11, 20), "late": (21, 31)}
FRAUD_RHYTHM_SHRINKAGE_K = 3.0        # Bayesian shrinkage strength toward "no seasonality yet"


class FraudRhythmProfile(db.Model):
    """One row per (owner_user_id, source_type[, entity_id]) — the
    business's own learned spending-rhythm model. entity_id is null
    for a business-wide profile (supplier_expense: trained across ALL
    of that business's supplier spend, since that's the largest and
    most reliable sample of its rhythm) or a specific record id when
    the rhythm genuinely differs by entity (savings_payout: trained
    per savings group, since two groups on the same account can have
    completely different cycles/currencies).

    Retrained on every fraud scan from that business's CURRENT
    history, so it's always current without a background job. Stored
    (not just computed in-memory) so the Fraud & Anomaly Monitor
    settings panel can show the business why something wasn't
    flagged."""
    __tablename__      = "fraud_rhythm_profiles"
    id                 = db.Column(db.Integer, primary_key=True)
    owner_user_id      = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    source_type        = db.Column(db.String(30), nullable=False)   # supplier_expense, savings_payout
    entity_id          = db.Column(db.String(40), nullable=True)    # e.g. savings group id; null = business-wide
    entity_label       = db.Column(db.String(200), nullable=True)   # human-readable, e.g. the group's name
    weekday_factors_json = db.Column(db.Text, nullable=False, default="[]")       # 7 floats, Mon..Sun
    month_bucket_factors_json = db.Column(db.Text, nullable=False, default="{}")  # {early, mid, late}
    trend_intercept    = db.Column(db.Float, nullable=False, default=0.0)
    trend_slope        = db.Column(db.Float, nullable=False, default=0.0)
    residual_mean      = db.Column(db.Float, nullable=False, default=0.0)
    residual_stdev     = db.Column(db.Float, nullable=False, default=0.0)
    epoch_date         = db.Column(db.Date, nullable=True)   # day-index zero point for the trend line
    sample_count       = db.Column(db.Integer, nullable=False, default=0)
    trained_at         = db.Column(db.DateTime, default=datetime.utcnow, onupdate=datetime.utcnow)
    __table_args__ = (db.UniqueConstraint("owner_user_id", "source_type", "entity_id", name="uq_fraud_rhythm_profile"),)

    def to_dict(self):
        return {
            "id": self.id, "source_type": self.source_type,
            "entity_id": self.entity_id, "entity_label": self.entity_label,
            "weekday_factors": json.loads(self.weekday_factors_json or "[]"),
            "month_bucket_factors": json.loads(self.month_bucket_factors_json or "{}"),
            "trend_slope": self.trend_slope,
            "residual_stdev": self.residual_stdev,
            "sample_count": self.sample_count,
            "trained_at": self.trained_at.isoformat() if self.trained_at else None,
            "is_active": self.sample_count >= FRAUD_RHYTHM_MIN_SAMPLES,
        }


def _fraud_rhythm_month_bucket(day_of_month):
    for name, (lo, hi) in FRAUD_RHYTHM_MONTH_BUCKETS.items():
        if lo <= day_of_month <= hi:
            return name
    return "late"


def _fraud_rhythm_fit(dated_amounts):
    """dated_amounts: iterable of (date, amount) with amount > 0, any
    order. Returns a plain dict profile, or None if there isn't enough
    history yet to fit seasonality (caller falls back to flat stdev)."""
    rows = sorted([(d, float(a)) for d, a in dated_amounts if d is not None and a], key=lambda r: r[0])
    if len(rows) < FRAUD_RHYTHM_MIN_SAMPLES:
        return None

    global_mean = sum(a for _, a in rows) / len(rows)
    if global_mean <= 0:
        return None

    # 1) Day-of-week seasonal factors, shrunk toward 1.0 when a weekday
    #    has few samples so 1-2 lucky/unlucky data points can't swing it.
    weekday_amounts = defaultdict(list)
    for d, a in rows:
        weekday_amounts[d.weekday()].append(a)
    weekday_factors = []
    for wd in range(7):
        vals = weekday_amounts.get(wd, [])
        n = len(vals)
        raw_factor = (sum(vals) / n / global_mean) if n else 1.0
        shrink = n / (n + FRAUD_RHYTHM_SHRINKAGE_K)
        weekday_factors.append(shrink * raw_factor + (1 - shrink) * 1.0)

    # 2) Day-of-month "rhythm" bucket factors (early/mid/late) — this is
    #    the piece that actually recognizes "big order at month-end".
    bucket_amounts = defaultdict(list)
    for d, a in rows:
        bucket_amounts[_fraud_rhythm_month_bucket(d.day)].append(a)
    bucket_factors = {}
    for name in FRAUD_RHYTHM_MONTH_BUCKETS:
        vals = bucket_amounts.get(name, [])
        n = len(vals)
        raw_factor = (sum(vals) / n / global_mean) if n else 1.0
        shrink = n / (n + FRAUD_RHYTHM_SHRINKAGE_K)
        bucket_factors[name] = shrink * raw_factor + (1 - shrink) * 1.0

    # 3) Deseasonalize every point, then fit a simple linear trend over
    #    time (day index) on the deseasonalized series, so a steadily
    #    growing/shrinking business doesn't get flagged as its normal
    #    order sizes drift.
    epoch = rows[0][0]
    xs, ys = [], []
    for d, a in rows:
        seasonal = weekday_factors[d.weekday()] * bucket_factors[_fraud_rhythm_month_bucket(d.day)]
        seasonal = seasonal if seasonal > 0.05 else 0.05  # guard against near-zero division
        xs.append((d - epoch).days)
        ys.append(a / seasonal)

    n = len(xs)
    mean_x = sum(xs) / n
    mean_y = sum(ys) / n
    denom = sum((x - mean_x) ** 2 for x in xs)
    slope = (sum((xs[i] - mean_x) * (ys[i] - mean_y) for i in range(n)) / denom) if denom > 0 else 0.0
    intercept = mean_y - slope * mean_x

    residuals = [ys[i] - (intercept + slope * xs[i]) for i in range(n)]
    resid_mean = sum(residuals) / n
    resid_var = sum((r - resid_mean) ** 2 for r in residuals) / n
    resid_stdev = resid_var ** 0.5

    return {
        "weekday_factors": weekday_factors,
        "month_bucket_factors": bucket_factors,
        "trend_intercept": intercept,
        "trend_slope": slope,
        "residual_mean": resid_mean,
        "residual_stdev": resid_stdev,
        "epoch_date": epoch,
        "sample_count": n,
    }


def _fraud_rhythm_train_and_save(owner_user_id, source_type, dated_amounts, entity_id=None, entity_label=None):
    """Fits a fresh profile from current history and upserts it.
    Returns the saved FraudRhythmProfile, or None if there wasn't
    enough history yet — an existing stale profile, if any, is left in
    place rather than deleted, so a brief data gap doesn't wipe out a
    perfectly good model."""
    fit = _fraud_rhythm_fit(dated_amounts)
    if not fit:
        return None
    row = FraudRhythmProfile.query.filter_by(
        owner_user_id=owner_user_id, source_type=source_type, entity_id=entity_id,
    ).first()
    if not row:
        row = FraudRhythmProfile(owner_user_id=owner_user_id, source_type=source_type, entity_id=entity_id)
        db.session.add(row)
    row.entity_label = entity_label
    row.weekday_factors_json = json.dumps(fit["weekday_factors"])
    row.month_bucket_factors_json = json.dumps(fit["month_bucket_factors"])
    row.trend_intercept = fit["trend_intercept"]
    row.trend_slope = fit["trend_slope"]
    row.residual_mean = fit["residual_mean"]
    row.residual_stdev = fit["residual_stdev"]
    row.epoch_date = fit["epoch_date"]
    row.sample_count = fit["sample_count"]
    row.trained_at = datetime.utcnow()
    return row


def _fraud_rhythm_score(profile, d, amount):
    """Scores one (date, amount) against an already-trained profile.
    Returns (z_score, expected_amount); (None, None) if the profile
    has no usable spread yet (e.g. every historical amount was
    identical, or the date/factors don't line up)."""
    if not profile or not d or profile.residual_stdev <= 0:
        return None, None
    weekday_factors = json.loads(profile.weekday_factors_json or "[]")
    bucket_factors = json.loads(profile.month_bucket_factors_json or "{}")
    if len(weekday_factors) != 7 or not bucket_factors:
        return None, None
    seasonal = weekday_factors[d.weekday()] * bucket_factors.get(_fraud_rhythm_month_bucket(d.day), 1.0)
    seasonal = seasonal if seasonal > 0.05 else 0.05
    t = (d - profile.epoch_date).days if profile.epoch_date else 0
    expected_deseasonalized = profile.trend_intercept + profile.trend_slope * t
    expected_amount = expected_deseasonalized * seasonal
    resid = (amount / seasonal) - expected_deseasonalized
    z = (resid - profile.residual_mean) / profile.residual_stdev
    return z, expected_amount


# ════════════════════════════════════════════════════════════
# STAGE 522b: ISOLATION FOREST ANOMALY DETECTION
# Second scoring engine alongside the seasonal-rhythm one above. The
# rhythm model is a (deliberately readable) hand-built Holt-Winters
# style decomposition — weekday factor x month-bucket factor x linear
# trend, scored with a residual z-score. IsolationForest is a genuinely
# different algorithm family: it isolates each point in a MULTI-feature
# space by repeated random splits, and points that isolate in fewer
# splits (shorter average path length across the forest) are the
# outliers. That means it can catch a payment that's individually a
# normal AMOUNT but arrives on an unusual day-of-month/day-of-week
# combination, which a single-number z-score on amount alone cannot.
#
# It is retrained fresh on every scan from that business's own current
# history (same "no background job, always current" approach as the
# rhythm profile) rather than persisted, since scikit-learn's
# IsolationForest trains in milliseconds even on a few thousand rows —
# there is no accuracy or latency reason to cache it, and skipping
# persistence avoids having to pickle/version a model blob in the DB.
# ════════════════════════════════════════════════════════════

FRAUD_ISO_FOREST_MIN_SAMPLES = 12   # below this, there isn't enough data to fit a meaningful forest


def _fraud_iso_features(d, amount, rhythm_profile=None):
    """Builds one feature row for a (date, amount) pair:
      - amount itself
      - day-of-week, encoded cyclically (sin/cos) so Sunday and Monday
        are numerically adjacent instead of 7 units apart
      - day-of-month, encoded cyclically the same way
      - the rhythm model's residual for this point, if a seasonal
        profile is already trained — folding in "how far this breaks
        from the business's own learned rhythm" as a feature gives the
        forest a much stronger signal than raw amount alone, without
        forcing it to rediscover seasonality from scratch on top of
        genuinely lumpy per-supplier history.
    """
    dow = d.weekday()
    dom = d.day
    dow_sin, dow_cos = math.sin(2 * math.pi * dow / 7), math.cos(2 * math.pi * dow / 7)
    dom_sin, dom_cos = math.sin(2 * math.pi * dom / 31), math.cos(2 * math.pi * dom / 31)
    rhythm_resid = 0.0
    if rhythm_profile is not None:
        z, _ = _fraud_rhythm_score(rhythm_profile, d, amount)
        rhythm_resid = z if z is not None else 0.0
    return [float(amount), dow_sin, dow_cos, dom_sin, dom_cos, float(rhythm_resid)]


def _fraud_iso_forest_flags(dated_amounts, rhythm_profile=None, sensitivity=3.0):
    """dated_amounts: iterable of (date, amount). Fits an IsolationForest
    on the whole history and returns {index_in_input_order: (is_outlier,
    anomaly_score)} for every point whose date/amount were usable.
    anomaly_score is scikit-learn's decision_function output: negative
    means "more anomalous", positive means "more normal". `sensitivity`
    reuses the same 0.5-10 "how many stdevs" scale the rest of the fraud
    settings use, translated into IsolationForest's `contamination`
    parameter (the expected fraction of outliers) so a business doesn't
    need to learn a second, unrelated vocabulary just because the engine
    underneath changed — higher sensitivity = higher contamination =
    more points flagged.
    Returns {} if scikit-learn/numpy aren't installed, or there isn't
    enough history yet (caller falls back to the rhythm/flat-stdev
    checks in that case, same as the rhythm model already does)."""
    if not SKLEARN_AVAILABLE:
        return {}
    rows = [(i, d, float(a)) for i, (d, a) in enumerate(dated_amounts) if d is not None and a]
    if len(rows) < FRAUD_ISO_FOREST_MIN_SAMPLES:
        return {}

    X = np.array([_fraud_iso_features(d, a, rhythm_profile) for _, d, a in rows])

    # Map the 0.5-10 "how many stdevs" sensitivity scale used by the
    # flat/rhythm checks onto IsolationForest's contamination parameter
    # (expected fraction of outliers). Inverse relationship, same as
    # those checks: a higher multiplier means "it should take a bigger
    # deviation to flag something", i.e. a lower contamination. At the
    # default 3.0 this lands around 5% — a sensible starting point that
    # won't flood a business's first scan with flags — tightening toward
    # ~1.5% at the strictest setting (10) and loosening toward the 25%
    # cap at the loosest (0.5).
    sensitivity = max(0.5, min(10.0, float(sensitivity)))
    contamination = max(0.01, min(0.25, 0.15 / sensitivity))

    model = IsolationForest(
        n_estimators=200,
        contamination=contamination,
        random_state=42,
    )
    model.fit(X)
    predictions = model.predict(X)          # -1 = outlier, 1 = inlier
    scores = model.decision_function(X)     # lower = more anomalous

    out = {}
    for (orig_idx, _, _), pred, score in zip(rows, predictions, scores):
        out[orig_idx] = (pred == -1, float(score))
    return out


@app.route("/api/fraud/rhythm/<string:source_type>", methods=["GET"])
def fraud_rhythm_get(source_type):
    """Read-only view of the learned spending-rhythm model(s) for this
    business, so the Fraud & Anomaly Monitor settings panel can show
    WHY a lumpy-but-regular amount wasn't flagged, instead of the
    model being an invisible black box."""
    user, err = _erp_user_or_401()
    if err: return err
    if source_type not in ("supplier_expense", "savings_payout"):
        return jsonify({"error": "Unknown source_type."}), 400
    rows = FraudRhythmProfile.query.filter_by(owner_user_id=user["id"], source_type=source_type).all()
    return jsonify({
        "profiles": [r.to_dict() for r in rows],
        "min_samples_to_activate": FRAUD_RHYTHM_MIN_SAMPLES,
    }), 200


@app.route("/api/fraud/offline-training-cache", methods=["GET"])
def fraud_offline_training_cache():
    """Feeds the browser's local, dependency-free Isolation Forest (see
    ConnectItOfflineIsolationForest in the frontend) so a business gets an
    instant, fully on-device anomaly pre-check on a new expense even
    with zero internet connectivity — the exact "unstable connectivity"
    case Deep Offline-First Dominance targets. Always an ADVISORY
    pre-check: the authoritative scan stays the server-side scikit-learn
    IsolationForest in _fraud_iso_forest_flags, which also folds in the
    learned spending-rhythm residual this lightweight client model
    deliberately leaves out to stay small and fast on-device."""
    user, err = _erp_user_or_401()
    if err: return err
    try:
        limit = min(int(request.args.get("limit", 300) or 300), 500)
    except Exception:
        limit = 300
    rows = (ErpExpense.query
            .filter(ErpExpense.owner_user_id == user["id"], ErpExpense.expense_date.isnot(None))
            .order_by(ErpExpense.expense_date.desc())
            .limit(limit).all())
    points = [{"date": e.expense_date.isoformat(), "amount": e.amount}
              for e in rows if e.expense_date and e.amount]
    return jsonify({
        "points": points,
        "min_samples_to_activate": FRAUD_ISO_FOREST_MIN_SAMPLES,
        "generated_at": datetime.utcnow().isoformat(),
    }), 200


# ════════════════════════════════════════════════════════════
# AUCTIONS / BIDDING
# A seller lists an item with a starting price and an end time; buyers
# place bids and the highest bid standing when the timer runs out wins
# (subject to an optional reserve price). Bids happen over plain REST
# (so the outcome is always exactly what's in the database — no risk
# of two competing bids racing each other over a socket), and every
# accepted bid is broadcast over Socket.IO to everyone watching that
# auction so the price/leader update live without polling. Settlement
# after a win is contact-based, same as the Marketplace/Surplus
# listings elsewhere in this file — no Stripe/escrow wiring here.
# ════════════════════════════════════════════════════════════

AUCTION_ANTI_SNIPE_WINDOW_SECONDS = 120   # a bid this close to the end pushes the clock out
AUCTION_ANTI_SNIPE_EXTENSION_SECONDS = 120


class AuctionListing(db.Model):
    __tablename__      = "auction_listings"
    id                 = db.Column(db.Integer, primary_key=True)
    seller_id          = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    product_id         = db.Column(db.Integer, db.ForeignKey("products.id"), nullable=True, index=True)  # optional link to a catalog listing for shared photos/description
    title              = db.Column(db.String(150), nullable=False)
    description        = db.Column(db.Text, nullable=True)
    image_urls         = db.Column(db.Text, nullable=True)   # JSON-encoded list
    category           = db.Column(db.String(60), nullable=True, index=True)
    currency           = db.Column(db.String(8), nullable=False, default="USD")
    starting_price     = db.Column(db.Float, nullable=False)
    reserve_price      = db.Column(db.Float, nullable=True)
    bid_increment      = db.Column(db.Float, nullable=False, default=1.0)
    current_price      = db.Column(db.Float, nullable=False)
    bid_count          = db.Column(db.Integer, nullable=False, default=0)
    high_bidder_id     = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=True, index=True)
    starts_at          = db.Column(db.DateTime, nullable=True)
    ends_at            = db.Column(db.DateTime, nullable=False, index=True)
    status             = db.Column(db.String(16), nullable=False, default="scheduled", index=True)  # scheduled, live, ended, cancelled
    winner_id          = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=True, index=True)
    reserve_met        = db.Column(db.Boolean, nullable=False, default=True)
    created_at         = db.Column(db.DateTime, default=datetime.utcnow, index=True)
    updated_at         = db.Column(db.DateTime, default=datetime.utcnow, onupdate=datetime.utcnow)

    def refresh_status(self):
        """Lazily transitions scheduled->live->ended based on the clock,
        called at the top of every read/write path that touches an
        auction so status is always correct without a background job."""
        now = datetime.utcnow()
        changed = False
        if self.status == "scheduled" and (not self.starts_at or self.starts_at <= now):
            self.status = "live"
            changed = True
        if self.status in ("scheduled", "live") and self.ends_at <= now:
            self.status = "ended"
            if self.reserve_price is not None and self.current_price < self.reserve_price:
                self.reserve_met = False
                self.winner_id = None
            elif self.high_bidder_id:
                self.reserve_met = True
                self.winner_id = self.high_bidder_id
            changed = True
        return changed

    def min_next_bid(self):
        return round(self.current_price + self.bid_increment, 2) if self.bid_count > 0 else round(self.current_price, 2)

    def to_dict(self, viewer_id=None):
        seller = UserAccount.query.get(self.seller_id)
        high_bidder = UserAccount.query.get(self.high_bidder_id) if self.high_bidder_id else None
        images = []
        if self.image_urls:
            try:
                images = json.loads(self.image_urls)
            except Exception:
                images = []
        return {
            "id": self.id, "seller_id": self.seller_id,
            "seller_name": seller.name if seller else None,
            "product_id": self.product_id, "title": self.title, "description": self.description,
            "images": images, "category": self.category, "currency": self.currency,
            "starting_price": self.starting_price, "reserve_price": self.reserve_price,
            "has_reserve": self.reserve_price is not None,
            "bid_increment": self.bid_increment, "current_price": self.current_price,
            "min_next_bid": self.min_next_bid(), "bid_count": self.bid_count,
            "high_bidder_id": self.high_bidder_id,
            "high_bidder_name": (high_bidder.name if high_bidder else None) if viewer_id else None,
            "is_high_bidder": bool(viewer_id) and viewer_id == self.high_bidder_id,
            "starts_at": self.starts_at.isoformat() if self.starts_at else None,
            "ends_at": self.ends_at.isoformat() if self.ends_at else None,
            "status": self.status, "winner_id": self.winner_id,
            "is_winner": bool(viewer_id) and viewer_id == self.winner_id,
            "reserve_met": self.reserve_met,
            "is_mine": bool(viewer_id) and viewer_id == self.seller_id,
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }


class AuctionBid(db.Model):
    __tablename__  = "auction_bids"
    id             = db.Column(db.Integer, primary_key=True)
    auction_id     = db.Column(db.Integer, db.ForeignKey("auction_listings.id"), nullable=False, index=True)
    bidder_id      = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    amount         = db.Column(db.Float, nullable=False)
    created_at     = db.Column(db.DateTime, default=datetime.utcnow, index=True)

    def to_dict(self):
        bidder = UserAccount.query.get(self.bidder_id)
        return {
            "id": self.id, "auction_id": self.auction_id,
            "bidder_name": bidder.name if bidder else "A bidder",
            "amount": self.amount,
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }


def _auction_emit(auction, event):
    """Broadcasts a live update to everyone watching this auction. A
    no-op if flask-socketio isn't installed — REST responses already
    carry the same data, so nothing is lost, it just won't be
    real-time for anyone still on the page."""
    if not FLASK_SOCKETIO_AVAILABLE or not socketio_app:
        return
    try:
        socketio_app.emit(event, auction.to_dict(), room=f"auction_{auction.id}", namespace="/auctions")
    except Exception as e:
        logging.error(f"[AUCTION WS EMIT] {e}")


@app.route("/api/auctions", methods=["GET"])
def auctions_list():
    status_filter = (request.args.get("status") or "").strip().lower()
    category = (request.args.get("category") or "").strip()
    q = AuctionListing.query
    if category:
        q = q.filter(AuctionListing.category == category)
    rows = q.order_by(AuctionListing.ends_at.asc()).limit(200).all()
    changed_any = False
    for a in rows:
        if a.refresh_status():
            changed_any = True
    if changed_any:
        db.session.commit()
    if status_filter in ("scheduled", "live", "ended", "cancelled"):
        rows = [a for a in rows if a.status == status_filter]
    viewer = _get_current_user()
    viewer_id = viewer["id"] if viewer else None
    return jsonify({"auctions": [a.to_dict(viewer_id=viewer_id) for a in rows]}), 200


@app.route("/api/auctions/mine", methods=["GET"])
def auctions_mine():
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    selling = AuctionListing.query.filter_by(seller_id=user["id"]).order_by(AuctionListing.created_at.desc()).all()
    bid_auction_ids = [r[0] for r in db.session.query(AuctionBid.auction_id).filter_by(bidder_id=user["id"]).distinct().all()]
    bidding = AuctionListing.query.filter(AuctionListing.id.in_(bid_auction_ids)).order_by(AuctionListing.ends_at.asc()).all() if bid_auction_ids else []
    changed = False
    for a in list(selling) + list(bidding):
        if a.refresh_status():
            changed = True
    if changed:
        db.session.commit()
    return jsonify({
        "selling": [a.to_dict(viewer_id=user["id"]) for a in selling],
        "bidding": [a.to_dict(viewer_id=user["id"]) for a in bidding],
    }), 200


@app.route("/api/auctions/<int:auction_id>", methods=["GET"])
def auction_detail(auction_id):
    auction = AuctionListing.query.get(auction_id)
    if not auction:
        return jsonify({"error": "Auction not found."}), 404
    if auction.refresh_status():
        db.session.commit()
    viewer = _get_current_user()
    viewer_id = viewer["id"] if viewer else None
    bids = (AuctionBid.query.filter_by(auction_id=auction.id)
            .order_by(AuctionBid.created_at.desc()).limit(25).all())
    return jsonify({"auction": auction.to_dict(viewer_id=viewer_id), "bids": [b.to_dict() for b in bids]}), 200


@app.route("/api/auctions", methods=["POST"])
@csrf.exempt
def auction_create():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}

    title = (data.get("title") or "").strip()[:150]
    if not title:
        return jsonify({"error": "'title' is required."}), 400
    try:
        starting_price = float(data.get("starting_price"))
        if starting_price < 0:
            raise ValueError()
    except (TypeError, ValueError):
        return jsonify({"error": "A valid, non-negative 'starting_price' is required."}), 400
    try:
        bid_increment = float(data.get("bid_increment", 1.0))
        if bid_increment <= 0:
            raise ValueError()
    except (TypeError, ValueError):
        return jsonify({"error": "'bid_increment' must be a positive number."}), 400
    reserve_price = data.get("reserve_price")
    try:
        reserve_price = float(reserve_price) if reserve_price not in (None, "") else None
    except (TypeError, ValueError):
        return jsonify({"error": "'reserve_price' must be a number if provided."}), 400

    duration_hours = data.get("duration_hours")
    ends_at = None
    if data.get("ends_at"):
        try:
            ends_at = datetime.fromisoformat(str(data["ends_at"]).replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            return jsonify({"error": "'ends_at' must be a valid ISO 8601 datetime."}), 400
    elif duration_hours:
        try:
            ends_at = datetime.utcnow() + timedelta(hours=float(duration_hours))
        except (TypeError, ValueError):
            return jsonify({"error": "'duration_hours' must be a number."}), 400
    if not ends_at:
        return jsonify({"error": "Provide either 'ends_at' or 'duration_hours'."}), 400
    if ends_at <= datetime.utcnow():
        return jsonify({"error": "The auction end time must be in the future."}), 400

    starts_at = None
    if data.get("starts_at"):
        try:
            starts_at = datetime.fromisoformat(str(data["starts_at"]).replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            return jsonify({"error": "'starts_at' must be a valid ISO 8601 datetime."}), 400

    product_id = data.get("product_id")
    image_urls = []
    if product_id:
        product = Product.query.get(int(product_id))
        if product and product.seller_id == user["id"]:
            try:
                image_urls = json.loads(product.image_urls) if product.image_urls else []
            except Exception:
                image_urls = []
        else:
            product_id = None
    if not image_urls:
        image_urls = [u for u in (data.get("image_urls") or []) if isinstance(u, str)][:6]

    auction = AuctionListing(
        seller_id=user["id"], product_id=product_id, title=title,
        description=(data.get("description") or "").strip()[:2000] or None,
        image_urls=json.dumps(image_urls) if image_urls else None,
        category=(data.get("category") or "").strip()[:60] or None,
        currency=(data.get("currency") or "USD").strip()[:8].upper(),
        starting_price=starting_price, reserve_price=reserve_price, bid_increment=bid_increment,
        current_price=starting_price, starts_at=starts_at, ends_at=ends_at,
        status="scheduled" if (starts_at and starts_at > datetime.utcnow()) else "live",
    )
    db.session.add(auction)
    db.session.commit()
    return jsonify({"ok": True, "auction": auction.to_dict(viewer_id=user["id"])}), 201


@app.route("/api/auctions/<int:auction_id>/bid", methods=["POST"])
@csrf.exempt
def auction_place_bid(auction_id):
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    auction = AuctionListing.query.get(auction_id)
    if not auction:
        return jsonify({"error": "Auction not found."}), 404
    if auction.refresh_status():
        db.session.commit()
    if auction.status != "live":
        return jsonify({"error": "This auction isn't accepting bids right now (" + auction.status + ")."}), 409
    if auction.seller_id == user["id"]:
        return jsonify({"error": "You can't bid on your own auction."}), 403

    data = request.get_json(silent=True) or {}
    try:
        amount = float(data.get("amount"))
    except (TypeError, ValueError):
        return jsonify({"error": "A valid bid 'amount' is required."}), 400
    min_bid = auction.min_next_bid()
    if amount < min_bid:
        return jsonify({"error": f"Your bid must be at least {auction.currency} {min_bid}."}), 400
    if auction.high_bidder_id == user["id"]:
        return jsonify({"error": "You're already the highest bidder."}), 409

    bid = AuctionBid(auction_id=auction.id, bidder_id=user["id"], amount=amount)
    db.session.add(bid)
    auction.current_price = amount
    auction.high_bidder_id = user["id"]
    auction.bid_count += 1
    # Anti-sniping: a bid landing in the final couple of minutes pushes
    # the close out instead of letting a last-second bid steal the win
    # with no chance to respond.
    remaining = (auction.ends_at - datetime.utcnow()).total_seconds()
    if 0 < remaining < AUCTION_ANTI_SNIPE_WINDOW_SECONDS:
        auction.ends_at = datetime.utcnow() + timedelta(seconds=AUCTION_ANTI_SNIPE_EXTENSION_SECONDS)
    db.session.commit()
    _auction_emit(auction, "bid_placed")
    return jsonify({"ok": True, "auction": auction.to_dict(viewer_id=user["id"])}), 200


@app.route("/api/auctions/<int:auction_id>/cancel", methods=["POST"])
@csrf.exempt
def auction_cancel(auction_id):
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    auction = AuctionListing.query.get(auction_id)
    if not auction:
        return jsonify({"error": "Auction not found."}), 404
    if auction.seller_id != user["id"]:
        return jsonify({"error": "You can only cancel your own auctions."}), 403
    if auction.bid_count > 0:
        return jsonify({"error": "This auction already has bids and can't be cancelled — let it run its course."}), 409
    auction.status = "cancelled"
    db.session.commit()
    _auction_emit(auction, "auction_cancelled")
    return jsonify({"ok": True, "auction": auction.to_dict(viewer_id=user["id"])}), 200


if FLASK_SOCKETIO_AVAILABLE:

    @socketio_app.on("connect", namespace="/auctions")
    def auctions_ws_connect(auth=None):
        # Watching an auction's live price feed doesn't require being
        # signed in — only placing a bid (over REST, above) does.
        pass

