@app.route("/api/sourcing-agent/requests/<int:request_id>/create-rfq", methods=["POST"])
@csrf.exempt
def sourcing_agent_create_rfq(request_id):
    """Turns the agent's parsed requirements into a real RFQ on the open
    board, reusing the exact Stage 305/348 creation path (including the
    AI-assisted seller-matching notification) instead of a separate,
    parallel posting mechanism."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    row = SourcingAgentRequest.query.filter_by(id=request_id, buyer_id=user["id"]).first()
    if not row:
        return jsonify({"error": "Sourcing search not found."}), 404
    if row.created_rfq_id:
        return jsonify({"error": "An RFQ was already created from this search.",
                         "rfq_id": row.created_rfq_id}), 400
    requirements = json.loads(row.parsed_requirements_json) if row.parsed_requirements_json else {}
    title = (requirements.get("product_type") or row.raw_query)[:150]
    description_parts = [row.raw_query]
    if requirements.get("key_specs"):
        description_parts.append("Specs: " + ", ".join(requirements["key_specs"]))
    if requirements.get("quality_requirements"):
        description_parts.append("Quality/certs: " + ", ".join(requirements["quality_requirements"]))
    rfq = MarketplaceRfq(
        buyer_id=user["id"], title=title, description="\n".join(description_parts)[:2000],
        category=requirements.get("category"),
        quantity=int(requirements.get("quantity") or row.quantity_hint or 1),
        unit=requirements.get("unit"),
        target_price=requirements.get("budget_max_per_unit") or row.budget_max,
        currency="USD", needed_by_date=row.deadline_date,
    )
    db.session.add(rfq)
    db.session.commit()
    try:
        _rfq_notify_matching_sellers(rfq)
    except Exception as e:
        logging.error(f"[SOURCING AGENT RFQ MATCH NOTIFY ERROR] rfq={rfq.id}: {e}")
    row.created_rfq_id = rfq.id
    db.session.commit()
    return jsonify({"ok": True, "rfq": rfq.to_dict(viewer_id=user["id"]), "request": row.to_dict()}), 201


# ════════════════════════════════════════════════════════════
# STAGE 357: IP / BRAND-PROTECTION TAKEDOWN PORTAL
# Stage 331's ProductFlag already lets ANY user report a single listing
# as counterfeit/prohibited/misleading for admin review. That's the
# wrong shape for a brand owner: they need to (1) establish who they
# are once, against a real brand name and, optionally, a trademark
# registration, (2) proactively search the WHOLE marketplace for
# listings that might infringe it instead of reporting one link at a
# time, and (3) file a formal claim that a seller can respond to with
# a counter-notice before an admin makes the final call — closer to a
# real DMCA/brand-registry workflow than a generic report button.
# Only a VERIFIED brand registration (reviewed by an admin, same
# reviewer role as the compliance/flag queues above) can file a
# takedown; upholding one deactivates the listing the same way an
# upheld ProductFlag already does, and a seller can file exactly one
# counter-notice per claim before the admin's final resolution.
# ════════════════════════════════════════════════════════════

IP_TAKEDOWN_CLAIM_TYPES = ("counterfeit", "trademark_infringement", "unauthorized_reseller", "copyright", "other")


class BrandRegistryEntry(db.Model):
    __tablename__            = "brand_registry_entries"
    id                       = db.Column(db.Integer, primary_key=True)
    owner_user_id            = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    brand_name               = db.Column(db.String(150), nullable=False, index=True)
    trademark_number         = db.Column(db.String(80), nullable=True)
    trademark_jurisdiction   = db.Column(db.String(80), nullable=True)   # e.g. 'US', 'EU', 'WIPO'
    proof_url                = db.Column(db.String(500), nullable=True)  # link to registration certificate / proof of ownership
    status                   = db.Column(db.String(12), nullable=False, default="pending", index=True)
    # pending, verified, rejected
    reviewed_by_admin_id     = db.Column(db.Integer, nullable=True)
    reviewed_at               = db.Column(db.DateTime, nullable=True)
    rejection_reason          = db.Column(db.String(500), nullable=True)
    created_at                = db.Column(db.DateTime, default=datetime.utcnow, index=True)

    def to_dict(self):
        return {
            "id": self.id, "owner_user_id": self.owner_user_id, "brand_name": self.brand_name,
            "trademark_number": self.trademark_number, "trademark_jurisdiction": self.trademark_jurisdiction,
            "proof_url": self.proof_url, "status": self.status,
            "rejection_reason": self.rejection_reason,
            "created_at": self.created_at.isoformat() if self.created_at else None,
            "reviewed_at": self.reviewed_at.isoformat() if self.reviewed_at else None,
        }


class IpTakedownRequest(db.Model):
    __tablename__          = "ip_takedown_requests"
    id                     = db.Column(db.Integer, primary_key=True)
    brand_registry_id      = db.Column(db.Integer, db.ForeignKey("brand_registry_entries.id"), nullable=False, index=True)
    product_id             = db.Column(db.Integer, db.ForeignKey("products.id"), nullable=False, index=True)
    submitted_by_user_id   = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    claim_type             = db.Column(db.String(24), nullable=False, default="other")
    description            = db.Column(db.Text, nullable=False)
    evidence_url           = db.Column(db.String(500), nullable=True)
    status                 = db.Column(db.String(16), nullable=False, default="submitted", index=True)
    # submitted, upheld, rejected, counter_noticed
    counter_notice         = db.Column(db.Text, nullable=True)
    counter_noticed_at     = db.Column(db.DateTime, nullable=True)
    reviewed_by_admin_id   = db.Column(db.Integer, nullable=True)
    reviewed_at             = db.Column(db.DateTime, nullable=True)
    resolution_note         = db.Column(db.String(500), nullable=True)
    created_at              = db.Column(db.DateTime, default=datetime.utcnow, index=True)

    def to_dict(self):
        brand = BrandRegistryEntry.query.get(self.brand_registry_id)
        product = Product.query.get(self.product_id)
        return {
            "id": self.id, "brand_registry_id": self.brand_registry_id,
            "brand_name": brand.brand_name if brand else None,
            "product_id": self.product_id,
            "product_name": product.name if product else None,
            "seller_id": product.seller_id if product else None,
            "submitted_by_user_id": self.submitted_by_user_id,
            "claim_type": self.claim_type, "description": self.description, "evidence_url": self.evidence_url,
            "status": self.status,
            "counter_notice": self.counter_notice,
            "counter_noticed_at": self.counter_noticed_at.isoformat() if self.counter_noticed_at else None,
            "resolution_note": self.resolution_note,
            "created_at": self.created_at.isoformat() if self.created_at else None,
            "reviewed_at": self.reviewed_at.isoformat() if self.reviewed_at else None,
        }


