@app.route("/api/brand-registry/<int:entry_id>/potential-matches", methods=["GET"])
def brand_registry_potential_matches(entry_id):
    """Proactive discovery: a verified brand owner can scan every active
    marketplace listing for a real keyword match against their brand
    name, instead of only being able to act on infringement they
    happen to stumble across. Pure search — filing a claim is a
    separate, deliberate step."""
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    entry = BrandRegistryEntry.query.filter_by(id=entry_id, owner_user_id=user["id"]).first()
    if not entry:
        return jsonify({"error": "Brand registration not found."}), 404
    if entry.status != "verified":
        return jsonify({"error": "This brand registration must be verified before searching listings."}), 403
    brand_tokens = _rfq_tokenize(entry.brand_name)
    if not brand_tokens:
        return jsonify({"matches": []}), 200
    candidates = Product.query.filter(Product.is_active.is_(True)).limit(1000).all()
    matches = []
    for p in candidates:
        product_tokens = _rfq_tokenize(p.name) | _rfq_tokenize(p.description)
        overlap = brand_tokens & product_tokens
        if overlap:
            matches.append({
                "product_id": p.id, "product_name": p.name, "seller_id": p.seller_id,
                "matched_terms": sorted(overlap),
            })
    matches.sort(key=lambda m: -len(m["matched_terms"]))
    return jsonify({"matches": matches[:100]}), 200


