@app.route("/api/ip-takedown/<int:request_id>/counter-notice", methods=["POST"])
@csrf.exempt
def ip_takedown_counter_notice(request_id):
    """The seller's one chance to respond before an admin makes the
    final call — mirrors a real DMCA counter-notice, not a second
    silent report. Only the listing's own seller can file it, and only
    once, on a claim that hasn't already been finally resolved."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    row = IpTakedownRequest.query.get(request_id)
    if not row:
        return jsonify({"error": "Takedown request not found."}), 404
    product = Product.query.get(row.product_id)
    if not product or product.seller_id != user["id"]:
        return jsonify({"error": "You can only respond to claims against your own listings."}), 403
    if row.status not in ("submitted", "upheld"):
        return jsonify({"error": "This claim can no longer be responded to."}), 400
    if row.counter_notice:
        return jsonify({"error": "A counter-notice was already filed on this claim."}), 400
    text = (request.get_json(silent=True) or {}).get("counter_notice", "").strip()
    if not text:
        return jsonify({"error": "Explain why this listing does not infringe."}), 400
    row.counter_notice = text[:4000]
    row.counter_noticed_at = datetime.utcnow()
    row.status = "counter_noticed"
    db.session.commit()
    return jsonify({"ok": True, "request": row.to_dict()}), 200


