    entries = TariffScheduleEntry.query.filter_by(user_id=user["id"]).order_by(TariffScheduleEntry.created_at.desc()).all()
    for entry in entries:
        _refresh_tariff_schedule_entry(entry)
    return jsonify({"entries": [e.to_dict() for e in entries]}), 200


