@app.route("/api/procurement-agents/<int:agent_id>/run", methods=["POST"])
@csrf.exempt
def procurement_agent_run(agent_id):
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Please log in."}), 401
    agent = ProcurementAgent.query.filter_by(id=agent_id, buyer_id=user["id"]).first()
    if not agent:
        return jsonify({"error": "Agent not found."}), 404

    query = Product.query.filter_by(is_active=True)
    if agent.category:
        query = query.filter(db.func.lower(Product.category) == agent.category.strip().lower())
    candidates = query.limit(500).all()  # bounded scan, real listings only

    scored = []
    for product in candidates:
        score, reasons = _procurement_agent_score_product(agent, product)
        if score > 0:
            scored.append((score, reasons, product))
    scored.sort(key=lambda t: t[0], reverse=True)
    shortlist = scored[:15]

    agent.last_run_at = datetime.utcnow()
    db.session.commit()

    return jsonify({
        "agent": agent.to_dict(),
        "shortlist": [{
            "score": round(s, 1), "reasons": r,
            "product": {
                "id": p.id, "name": p.name, "category": p.category,
                "price": p.price, "currency": p.currency, "unit": p.unit,
                "min_order_quantity": p.min_order_quantity,
                "country_of_origin": p.country_of_origin, "seller_id": p.seller_id,
            },
        } for s, r, p in shortlist],
    }), 200


PROCUREMENT_RFQ_AI_SYSTEM_PROMPT = (
    "You write a short, professional RFQ (request for quote) description for a B2B trade platform, "
    "for a buyer sourcing a product. You are given ONLY the buyer's own saved sourcing criteria — "
    "never invent quantities, prices, specs, or requirements that are not already present in what "
    "you're given. Respond with ONLY a JSON object, no other text, no markdown fences, matching "
    'exactly this shape: {"description": "<2-3 short plain-text paragraphs restating and framing the '
    'given criteria professionally for sellers to read>"}. Always return your best-effort result, '
    "never refuse or add commentary outside the JSON."
)


def _procurement_agent_template_rfq_description(agent: "ProcurementAgent") -> str:
    """Non-AI fallback: a plain restatement of the agent's own saved
    fields, used when no AI provider replies. Same facts either way."""
    parts = [f"Sourcing request from a standing procurement agent (\"{agent.name}\")."]
    if agent.category:
        parts.append(f"Category: {agent.category}.")
    if agent.keywords:
        parts.append(f"Looking for: {agent.keywords}.")
    if agent.target_quantity:
        parts.append(f"Target quantity: {agent.target_quantity}" + (f" {agent.unit}" if agent.unit else "") + ".")
    if agent.max_price_per_unit:
        parts.append(f"Budget: up to {agent.currency} {agent.max_price_per_unit} per unit.")
    if agent.preferred_country_code:
        parts.append(f"Preferred origin: {agent.preferred_country_code}.")
    return " ".join(parts)


@app.route("/api/procurement-agents/<int:agent_id>/file-rfq", methods=["POST"])
@csrf.exempt
def procurement_agent_file_rfq(agent_id):
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Please log in."}), 401
    agent = ProcurementAgent.query.filter_by(id=agent_id, buyer_id=user["id"]).first()
    if not agent:
        return jsonify({"error": "Agent not found."}), 404

    description = None
    used_ai = False
    if not gate_ai_usage(user, "procurement_agent_rfq_draft"):
        criteria_text = (
            f"Category: {agent.category or 'unspecified'}\n"
            f"Keywords: {agent.keywords or 'unspecified'}\n"
            f"Target quantity: {agent.target_quantity or 'unspecified'} {agent.unit or ''}\n"
            f"Budget: {(str(agent.max_price_per_unit) + ' ' + agent.currency) if agent.max_price_per_unit else 'unspecified'} per unit\n"
            f"Preferred origin: {agent.preferred_country_code or 'unspecified'}"
        )
        ai_reply = _one_round(
            [{"role": "user", "content": criteria_text}],
            user_id=user["id"], system_prompt=PROCUREMENT_RFQ_AI_SYSTEM_PROMPT,
        )
        if ai_reply:
            try:
                cleaned = re.sub(r"^```(?:json)?|```$", "", ai_reply.strip(), flags=re.MULTILINE).strip()
                parsed = json.loads(cleaned)
                description = (parsed.get("description") or "").strip()[:2000] or None
                used_ai = bool(description)
            except Exception:
                description = None
    if not description:
        description = _procurement_agent_template_rfq_description(agent)

    rfq = MarketplaceRfq(
        buyer_id=user["id"],
        title=(f"{agent.name} — sourcing request")[:150],
        description=description,
        category=agent.category,
        quantity=agent.target_quantity or 1,
        unit=agent.unit,
        target_price=agent.max_price_per_unit,
        currency=agent.currency,
    )
    db.session.add(rfq)
    db.session.commit()
    return jsonify({"ok": True, "rfq": rfq.to_dict(viewer_id=user["id"]), "ai_drafted": used_ai}), 201


def _parse_iso_datetime(value):
    """Shared best-effort ISO-8601 parser for the stage-365..368 routes
    below — returns None instead of raising on missing/malformed input,
    since every field that uses it is optional."""
    if not value or not isinstance(value, str):
        return None
    try:
        return datetime.fromisoformat(value.replace("Z", "+00:00")).replace(tzinfo=None)
    except (ValueError, TypeError):
        return None


# ════════════════════════════════════════════════════════════
# STAGE 365: PREDICTIVE DEMAND-MATCHING
# No forecasting model runs anywhere in this app, so this is scoped
# honestly as statistics over the platform's OWN real ProductOrder
# history — not a machine-learning prediction. For a buyer/product
# pair with two or more past paid orders, the average gap between
# order dates gives a "predicted next reorder window"; sellers get
# the same math aggregated across all their buyers, so they can see
# which of their own listings have buyers due to reorder soon. On-
# demand only (this app runs no background worker/cron anywhere),
# same lazy-recompute pattern as Stage 362/363/364.
# ════════════════════════════════════════════════════════════

def _demand_forecast_for_buyer(buyer_id: int):
    orders = (ProductOrder.query
              .filter(ProductOrder.buyer_id == buyer_id, ProductOrder.status.in_(["paid", "contacted"]))
              .order_by(ProductOrder.product_id, ProductOrder.created_at.asc()).all())
    by_product = {}
    for o in orders:
        by_product.setdefault(o.product_id, []).append(o)

    forecasts = []
    for product_id, rows in by_product.items():
        if len(rows) < 2:
            continue
        gaps_days = []
        for i in range(1, len(rows)):
            delta = (rows[i].created_at - rows[i - 1].created_at).total_seconds() / 86400.0
            if delta > 0:
                gaps_days.append(delta)
        if not gaps_days:
            continue
        avg_gap = sum(gaps_days) / len(gaps_days)
        last_order = rows[-1]
        predicted_next = last_order.created_at + timedelta(days=avg_gap)
        product = Product.query.get(product_id)
        if not product or not product.is_active:
            continue
        confidence = "high" if len(rows) >= 4 else ("medium" if len(rows) == 3 else "low")
        forecasts.append({
            "product_id": product_id, "product_name": product.name,
            "order_count": len(rows), "avg_reorder_days": round(avg_gap, 1),
            "last_ordered_at": last_order.created_at.isoformat(),
            "predicted_next_order_at": predicted_next.isoformat(),
            "due_soon": predicted_next <= datetime.utcnow() + timedelta(days=7),
            "confidence": confidence,
            "seller_id": product.seller_id, "price": product.price, "currency": product.currency,
        })
    forecasts.sort(key=lambda f: f["predicted_next_order_at"])
    return forecasts


def _demand_forecast_for_seller(seller_id: int):
    products = Product.query.filter_by(seller_id=seller_id, is_active=True).all()
    product_ids = [p.id for p in products]
    if not product_ids:
        return []
    orders = (ProductOrder.query
              .filter(ProductOrder.seller_id == seller_id, ProductOrder.product_id.in_(product_ids),
                      ProductOrder.status.in_(["paid", "contacted"]))
              .order_by(ProductOrder.product_id, ProductOrder.buyer_id, ProductOrder.created_at.asc()).all())
    by_product_buyer = {}
    for o in orders:
        by_product_buyer.setdefault((o.product_id, o.buyer_id), []).append(o)

    product_names = {p.id: p.name for p in products}
    per_product = {}
    for (product_id, buyer_id), rows in by_product_buyer.items():
        if len(rows) < 2:
            continue
        gaps_days = []
        for i in range(1, len(rows)):
            delta = (rows[i].created_at - rows[i - 1].created_at).total_seconds() / 86400.0
            if delta > 0:
                gaps_days.append(delta)
        if not gaps_days:
            continue
        avg_gap = sum(gaps_days) / len(gaps_days)
        predicted_next = rows[-1].created_at + timedelta(days=avg_gap)
        bucket = per_product.setdefault(product_id, {"repeat_buyers": 0, "due_within_30d": 0, "predicted_qty_30d": 0})
        bucket["repeat_buyers"] += 1
        if predicted_next <= datetime.utcnow() + timedelta(days=30):
            bucket["due_within_30d"] += 1
            avg_qty = sum(r.quantity for r in rows) / len(rows)
            bucket["predicted_qty_30d"] += round(avg_qty)

    results = [{
        "product_id": pid, "product_name": product_names.get(pid, "Listing"),
        "repeat_buyers": v["repeat_buyers"], "due_within_30d": v["due_within_30d"],
        "predicted_qty_30d": v["predicted_qty_30d"],
    } for pid, v in per_product.items()]
    results.sort(key=lambda r: r["due_within_30d"], reverse=True)
    return results


@app.route("/api/demand-forecast/mine", methods=["GET"])
def demand_forecast_mine():
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Please log in."}), 401
    return jsonify({"forecasts": _demand_forecast_for_buyer(user["id"])}), 200


@app.route("/api/demand-forecast/seller", methods=["GET"])
def demand_forecast_seller():
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Please log in."}), 401
    return jsonify({"forecasts": _demand_forecast_for_seller(user["id"])}), 200


# ════════════════════════════════════════════════════════════
# STAGE 366: FACTORY-CAPACITY MARKETPLACE
# A seller lists idle real production capacity (a line, a shift block,
# machine-hours) as its own listing type, separate from a physical
# product listing since it is booked by amount-of-capacity and a date
# window rather than bought in a Stripe checkout. A buyer sends a
# booking request against a listing; the seller accepts or declines
# it directly (no payment is collected here — capacity bookings are
# a negotiated commercial arrangement, not a fixed-price purchase, so
# this app records the agreement rather than fabricating a checkout
# for a price that hasn't actually been agreed yet).
# ════════════════════════════════════════════════════════════

class FactoryCapacityListing(db.Model):
    __tablename__ = "factory_capacity_listings"
    id                  = db.Column(db.Integer, primary_key=True)
    seller_id           = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    title                = db.Column(db.String(150), nullable=False)
    description          = db.Column(db.Text, nullable=True)
    capacity_type        = db.Column(db.String(60), nullable=False)   # e.g. production line, machine-hours, full factory, shift block
    capacity_amount       = db.Column(db.Float, nullable=False)
    capacity_unit        = db.Column(db.String(32), nullable=False)   # e.g. hours, units/day, shifts
    price_per_unit        = db.Column(db.Float, nullable=True)
    currency             = db.Column(db.String(8), nullable=False, default="USD")
    available_from        = db.Column(db.DateTime, nullable=True)
    available_to          = db.Column(db.DateTime, nullable=True)
    city                 = db.Column(db.String(120), nullable=True)
    country_code          = db.Column(db.String(4), nullable=True)
    is_active            = db.Column(db.Boolean, nullable=False, default=True, index=True)
    created_at           = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        return {
            "id": self.id, "seller_id": self.seller_id, "title": self.title,
            "description": self.description, "capacity_type": self.capacity_type,
            "capacity_amount": self.capacity_amount, "capacity_unit": self.capacity_unit,
            "price_per_unit": self.price_per_unit, "currency": self.currency,
            "available_from": self.available_from.isoformat() if self.available_from else None,
            "available_to": self.available_to.isoformat() if self.available_to else None,
            "city": self.city, "country_code": self.country_code, "is_active": self.is_active,
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }


class FactoryCapacityBooking(db.Model):
    __tablename__ = "factory_capacity_bookings"
    id                = db.Column(db.Integer, primary_key=True)
    listing_id         = db.Column(db.Integer, db.ForeignKey("factory_capacity_listings.id"), nullable=False, index=True)
    buyer_id          = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
