@app.route("/api/reverse-auctions/<int:auction_id>/bid", methods=["POST"])
@csrf.exempt
def reverse_auction_bid(auction_id):
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Please log in."}), 401
    auction = ReverseAuctionListing.query.filter_by(id=auction_id, status="open").first()
    if not auction:
        return jsonify({"error": "Auction not found or already closed."}), 404
    if auction.closes_at and datetime.utcnow() > auction.closes_at:
        return jsonify({"error": "This auction has closed."}), 400
    data = request.get_json(silent=True) or {}
    product = Product.query.filter_by(id=data.get("product_id"), seller_id=user["id"], is_active=True).first()
    if not product:
        return jsonify({"error": "Pick one of your own active listings to back this bid."}), 400
    try:
        price_per_unit = float(data.get("price_per_unit"))
    except (TypeError, ValueError):
        price_per_unit = None
    if price_per_unit is None or price_per_unit <= 0:
        return jsonify({"error": "A positive price per unit is required."}), 400

    lowest = (ReverseAuctionBid.query.filter_by(auction_id=auction.id)
              .order_by(ReverseAuctionBid.price_per_unit.asc()).first())
    if lowest and price_per_unit >= lowest.price_per_unit:
        return jsonify({"error": f"Your bid must beat the current lowest bid of {auction.currency} {lowest.price_per_unit}."}), 400
    if auction.starting_max_price and price_per_unit > auction.starting_max_price:
        return jsonify({"error": f"Bid must be at or below the buyer's stated maximum of {auction.currency} {auction.starting_max_price}."}), 400

    bid = ReverseAuctionBid(
        auction_id=auction.id, seller_id=user["id"], product_id=product.id,
        price_per_unit=price_per_unit, message=(data.get("message") or "").strip()[:500] or None,
    )
    db.session.add(bid)
    db.session.commit()
    return jsonify({"ok": True, "bid": bid.to_dict()}), 201


@app.route("/api/reverse-auctions/<int:auction_id>/award/<int:bid_id>", methods=["POST"])
@csrf.exempt
def reverse_auction_award(auction_id, bid_id):
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Please log in."}), 401
    auction = ReverseAuctionListing.query.filter_by(id=auction_id, buyer_id=user["id"], status="open").first()
    if not auction:
        return jsonify({"error": "Auction not found or already decided."}), 404
    bid = ReverseAuctionBid.query.filter_by(id=bid_id, auction_id=auction.id).first()
    if not bid:
        return jsonify({"error": "Bid not found on this auction."}), 404
    product = Product.query.get(bid.product_id)
    if not product or not product.is_active:
        return jsonify({"error": "That seller's listing is no longer available — ask them to re-bid."}), 400
    if product.quantity_available and auction.quantity > product.quantity_available:
        return jsonify({"error": f"Seller only has {product.quantity_available} available, auction asked for {auction.quantity}."}), 400

    order, checkout_url = _create_product_order_checkout(
        product, auction.buyer_id, auction.quantity, unit_price=bid.price_per_unit, currency=auction.currency,
        note=f"Awarded from reverse auction #{auction.id}: {auction.title}")
    auction.status = "awarded"
    auction.winning_bid_id = bid.id
    auction.winning_order_id = order.id
    db.session.commit()
    return jsonify({"ok": True, "order_id": order.id, "checkout_url": checkout_url}), 200


