@app.route("/api/developer-apps", methods=["POST"])
@csrf.exempt
def developer_app_create():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    name = (data.get("name") or "").strip()[:120]
    if not name:
        return jsonify({"error": "'name' is required."}), 400
    category = (data.get("category") or "other").strip().lower()
    if category not in DEVELOPER_APP_CATEGORIES:
        category = "other"
    app_row = DeveloperApp(
        developer_id=user["id"], name=name,
        tagline=(data.get("tagline") or "").strip()[:200] or None,
        description=(data.get("description") or "").strip()[:3000] or None,
        category=category,
        icon_url=(data.get("icon_url") or "").strip()[:500] or None,
        website_url=(data.get("website_url") or "").strip()[:500] or None,
        pricing_note=(data.get("pricing_note") or "").strip()[:200] or None,
    )
    db.session.add(app_row)
    db.session.commit()
    return jsonify({"ok": True, "app": app_row.to_dict(viewer_id=user["id"])}), 201


