@app.route("/api/influencers/profile", methods=["POST"])
@csrf.exempt
def influencer_profile_upsert():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    display_name = (data.get("display_name") or "").strip()
    if not display_name:
        return jsonify({"error": "Display name is required."}), 400
    try:
        follower_count = max(0, int(data.get("follower_count") or 0))
    except (TypeError, ValueError):
        follower_count = 0
    rate_per_post = data.get("rate_per_post")
    try:
        rate_per_post = float(rate_per_post) if rate_per_post not in (None, "") else None
    except (TypeError, ValueError):
        rate_per_post = None
    profile = InfluencerProfile.query.filter_by(user_id=user["id"]).first()
    if not profile:
        profile = InfluencerProfile(user_id=user["id"])
        db.session.add(profile)
    profile.display_name = display_name[:120]
    profile.niche = (data.get("niche") or "").strip()[:80] or None
    profile.bio = data.get("bio") or None
    profile.platform = (data.get("platform") or "other").strip()[:20]
    profile.profile_url = (data.get("profile_url") or "").strip()[:300] or None
    profile.follower_count = follower_count
    profile.rate_per_post = rate_per_post
    profile.currency = (data.get("currency") or "USD").strip()[:8]
    profile.is_active = bool(data.get("is_active", True))
    profile.updated_at = datetime.utcnow()
    db.session.commit()
    return jsonify({"profile": profile.to_dict()}), 200


