@app.route("/api/influencer-campaigns", methods=["POST"])
@csrf.exempt
def influencer_campaign_create():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    title = (data.get("title") or "").strip()
    brief = (data.get("brief") or "").strip()
    if not title or not brief:
        return jsonify({"error": "Title and brief are required."}), 400
    product_id = data.get("product_id")
    try:
        product_id = int(product_id) if product_id else None
    except (TypeError, ValueError):
        product_id = None
    if product_id:
        product = Product.query.get(product_id)
        if not product or product.seller_id != user["id"]:
            return jsonify({"error": "You can only attach a campaign to your own listing."}), 403
    budget_total = data.get("budget_total")
    try:
        budget_total = float(budget_total) if budget_total not in (None, "") else None
    except (TypeError, ValueError):
        budget_total = None
    campaign = InfluencerCampaign(
        seller_id=user["id"], product_id=product_id, title=title[:160], brief=brief,
        budget_total=budget_total, currency=(data.get("currency") or "USD").strip()[:8],
    )
    db.session.add(campaign)
    db.session.commit()
    return jsonify({"campaign": campaign.to_dict()}), 201


@app.route("/api/influencer-campaigns/<int:campaign_id>/apply", methods=["POST"])
@csrf.exempt
def influencer_campaign_apply(campaign_id):
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    campaign = InfluencerCampaign.query.get(campaign_id)
    if not campaign:
        return jsonify({"error": "Campaign not found."}), 404
    if campaign.status != "open":
        return jsonify({"error": "This campaign is no longer open."}), 400
    if campaign.seller_id == user["id"]:
        return jsonify({"error": "You cannot apply to your own campaign."}), 400
    if InfluencerCampaignApplication.query.filter_by(campaign_id=campaign.id, influencer_id=user["id"]).first():
        return jsonify({"error": "You already applied to this campaign."}), 400
    data = request.get_json(silent=True) or {}
    proposed_rate = data.get("proposed_rate")
    try:
        proposed_rate = float(proposed_rate) if proposed_rate not in (None, "") else None
    except (TypeError, ValueError):
        proposed_rate = None
    application = InfluencerCampaignApplication(
        campaign_id=campaign.id, influencer_id=user["id"],
        pitch=(data.get("pitch") or "").strip() or None, proposed_rate=proposed_rate,
    )
    db.session.add(application)
    db.session.commit()
    return jsonify({"application": application.to_dict()}), 201


