@app.route("/api/influencer-campaign-applications/<int:application_id>/respond", methods=["POST"])
@csrf.exempt
def influencer_campaign_application_respond(application_id):
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    application = InfluencerCampaignApplication.query.get(application_id)
    if not application:
        return jsonify({"error": "Application not found."}), 404
    campaign = InfluencerCampaign.query.get(application.campaign_id)
    if not campaign or campaign.seller_id != user["id"]:
        return jsonify({"error": "Only the campaign owner can respond to applications."}), 403
    data = request.get_json(silent=True) or {}
    decision = (data.get("status") or "").strip().lower()
    if decision not in ("accepted", "rejected"):
        return jsonify({"error": "status must be 'accepted' or 'rejected'."}), 400
    application.status = decision
    db.session.commit()
    return jsonify({"application": application.to_dict()}), 200


# ════════════════════════════════════════════════════════════
# STAGE 363: CROSS-ROLE LOYALTY
# One points balance per user that accrues from BOTH sides of the
# marketplace — a buyer earns points on purchases, the same account
# earns points again on any sale it makes as a seller. Distinct from
# the existing per-business punchcard LoyaltyProgram (Stage-tagged
# "loyalty_programs"/"loyalty_customers" above), which is a phone-
# number-keyed tool a business runs for ITS OWN walk-in customers —
# this one is platform-wide and keyed to the logged-in account.
# Redemption converts points into real StoreCreditAccount balance
# using the existing _grant_store_credit() ledger, so redeemed points
# spend exactly like any other store credit at checkout.
# ════════════════════════════════════════════════════════════

LOYALTY_POINTS_PER_DOLLAR_BUYER  = 1     # 1 point per $1 spent, on marketplace purchases
LOYALTY_POINTS_PER_DOLLAR_SELLER = 0.5   # 1 point per $2 sold, on marketplace sales
LOYALTY_POINTS_PER_DOLLAR_REDEEM = 100   # 100 points redeem for $1 of store credit
LOYALTY_MIN_REDEEM_POINTS        = 500   # $5 minimum redemption


class LoyaltyPointsAccount(db.Model):
    __tablename__  = "loyalty_points_accounts"
    id             = db.Column(db.Integer, primary_key=True)
    user_id        = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, unique=True, index=True)
    points_balance = db.Column(db.Integer, nullable=False, default=0)
    lifetime_points = db.Column(db.Integer, nullable=False, default=0)
    updated_at     = db.Column(db.DateTime, default=datetime.utcnow, onupdate=datetime.utcnow)

    def to_dict(self):
        return {
            "points_balance": self.points_balance, "lifetime_points": self.lifetime_points,
            "redeemable_usd": round(self.points_balance / LOYALTY_POINTS_PER_DOLLAR_REDEEM, 2),
            "min_redeem_points": LOYALTY_MIN_REDEEM_POINTS,
        }


class LoyaltyPointsLedgerEntry(db.Model):
    __tablename__  = "loyalty_points_ledger"
    id             = db.Column(db.Integer, primary_key=True)
    user_id        = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    points         = db.Column(db.Integer, nullable=False)  # positive = earned, negative = redeemed
    reason         = db.Column(db.String(30), nullable=False)  # buyer_purchase, seller_sale, redeem
    reference      = db.Column(db.String(120), nullable=True)
    created_at     = db.Column(db.DateTime, default=datetime.utcnow, index=True)

    def to_dict(self):
        return {
            "id": self.id, "points": self.points, "reason": self.reason,
            "reference": self.reference,
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }


def _get_or_create_loyalty_account(user_id):
    account = LoyaltyPointsAccount.query.filter_by(user_id=user_id).first()
    if not account:
        account = LoyaltyPointsAccount(user_id=user_id, points_balance=0, lifetime_points=0)
        db.session.add(account)
        db.session.commit()
    return account


def _grant_loyalty_points(user_id, points, reason, reference=None):
    """Adds to a user's points balance and logs it. Caller commits."""
    points = int(round(points))
    if points <= 0:
        return None
    account = _get_or_create_loyalty_account(user_id)
    account.points_balance += points
    account.lifetime_points += points
    account.updated_at = datetime.utcnow()
    db.session.add(LoyaltyPointsLedgerEntry(
        user_id=user_id, points=points, reason=reason, reference=reference,
    ))
    return account


@app.route("/api/loyalty-points/mine", methods=["GET"])
def loyalty_points_mine():
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    account = _get_or_create_loyalty_account(user["id"])
    ledger = (LoyaltyPointsLedgerEntry.query.filter_by(user_id=user["id"])
              .order_by(LoyaltyPointsLedgerEntry.created_at.desc()).limit(50).all())
    return jsonify({"account": account.to_dict(), "ledger": [e.to_dict() for e in ledger]}), 200


@app.route("/api/loyalty-points/redeem", methods=["POST"])
@csrf.exempt
def loyalty_points_redeem():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    try:
        points = int(data.get("points") or 0)
    except (TypeError, ValueError):
        return jsonify({"error": "Invalid points amount."}), 400
    if points < LOYALTY_MIN_REDEEM_POINTS:
        return jsonify({"error": f"Minimum redemption is {LOYALTY_MIN_REDEEM_POINTS} points."}), 400
    account = _get_or_create_loyalty_account(user["id"])
    if points > account.points_balance:
        return jsonify({"error": "You don't have that many points."}), 400
    usd_value = round(points / LOYALTY_POINTS_PER_DOLLAR_REDEEM, 2)
    account.points_balance -= points
    account.updated_at = datetime.utcnow()
    db.session.add(LoyaltyPointsLedgerEntry(
        user_id=user["id"], points=-points, reason="redeem", reference=f"store_credit_{usd_value}",
    ))
    _grant_store_credit(user["id"], usd_value, reason="loyalty_redeem", reference=f"{points} points")
    db.session.commit()
    return jsonify({"account": account.to_dict(), "store_credit_granted": usd_value}), 200


# ════════════════════════════════════════════════════════════
# STAGE 364: SELLER LEADERBOARDS
# Purely computed from real data already in the database — total paid
# order revenue and order count from ProductOrder, average rating from
# the existing DealReview table. No score is invented; a seller with
# zero orders or zero reviews in the window simply doesn't rank on
# that measure. Tier badges are just labels over real revenue bands.
# ════════════════════════════════════════════════════════════

def _seller_leaderboard_tier(revenue):
    if revenue >= 10000:
        return "Platinum"
    if revenue >= 2500:
        return "Gold"
    if revenue >= 500:
        return "Silver"
    return "Bronze"


@app.route("/api/marketplace/leaderboard", methods=["GET"])
def marketplace_leaderboard():
    try:
        period_days = int(request.args.get("period_days") or 30)
    except (TypeError, ValueError):
        period_days = 30
    period_days = max(1, min(period_days, 365))
    since = datetime.utcnow() - timedelta(days=period_days)
    rows = (
        db.session.query(
            ProductOrder.seller_id,
            db.func.sum(ProductOrder.total_price).label("revenue"),
            db.func.count(ProductOrder.id).label("order_count"),
        )
        .filter(ProductOrder.status == "paid", ProductOrder.created_at >= since)
        .group_by(ProductOrder.seller_id)
        .order_by(db.func.sum(ProductOrder.total_price).desc())
        .limit(50)
        .all()
    )
    leaderboard = []
    for rank, row in enumerate(rows, start=1):
        seller = UserAccount.query.get(row.seller_id)
        if not seller:
            continue
        rating_rows = DealReview.query.filter_by(reviewee_id=row.seller_id).all()
        avg_rating = round(sum(r.rating for r in rating_rows) / len(rating_rows), 2) if rating_rows else None
        leaderboard.append({
            "rank": rank, "seller_id": row.seller_id, "seller_name": seller.name,
            "revenue": round(row.revenue or 0, 2), "order_count": row.order_count,
            "avg_rating": avg_rating, "rating_count": len(rating_rows),
            "tier": _seller_leaderboard_tier(row.revenue or 0),
        })
    return jsonify({"period_days": period_days, "leaderboard": leaderboard}), 200


# ════════════════════════════════════════════════════════════
# STAGE 365: SUBSCRIPTION COMMERCE
# "Subscribe & save" for real, recurring, physical/consumable listings.
# Honest limitation, documented rather than hidden: this platform has
# no saved-card-on-file infrastructure for marketplace purchases (only
# the SaaS billing side, Organization.stripe_customer_id, has that) —
# so a renewal does NOT silently auto-charge a card. Instead the cron
# sweep below generates the next order + a real Stripe Checkout link
# at each interval and reminds the buyer to complete it (WhatsApp/
# push, reusing existing notification channels), exactly like the tax
# deadline and low-stock reminders elsewhere in this file. Nothing
# about "auto-billing" is claimed anywhere in the UI copy.
# ════════════════════════════════════════════════════════════

class ProductSubscriptionPlan(db.Model):
    __tablename__  = "product_subscription_plans"
    id             = db.Column(db.Integer, primary_key=True)
    product_id     = db.Column(db.Integer, db.ForeignKey("products.id"), nullable=False, index=True)
    seller_id      = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    interval_days  = db.Column(db.Integer, nullable=False, default=30)
    discount_pct   = db.Column(db.Float, nullable=False, default=0.0)  # 0-50
    is_active      = db.Column(db.Boolean, nullable=False, default=True)
    created_at     = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        product = Product.query.get(self.product_id)
        return {
            "id": self.id, "product_id": self.product_id,
            "product_name": product.name if product else None,
            "seller_id": self.seller_id, "interval_days": self.interval_days,
            "discount_pct": self.discount_pct, "is_active": self.is_active,
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }


class BuyerSubscription(db.Model):
    __tablename__  = "buyer_subscriptions"
    id             = db.Column(db.Integer, primary_key=True)
    plan_id        = db.Column(db.Integer, db.ForeignKey("product_subscription_plans.id"), nullable=False, index=True)
    buyer_id       = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    quantity       = db.Column(db.Integer, nullable=False, default=1)
    status         = db.Column(db.String(16), nullable=False, default="active", index=True)  # active, paused, cancelled
    next_charge_date = db.Column(db.DateTime, nullable=False, default=datetime.utcnow, index=True)
    last_order_id  = db.Column(db.Integer, db.ForeignKey("product_orders.id"), nullable=True)
    created_at     = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        plan = ProductSubscriptionPlan.query.get(self.plan_id)
        return {
            "id": self.id, "plan": plan.to_dict() if plan else None,
            "buyer_id": self.buyer_id, "quantity": self.quantity, "status": self.status,
            "next_charge_date": self.next_charge_date.isoformat() if self.next_charge_date else None,
            "last_order_id": self.last_order_id,
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }


@app.route("/api/subscription-plans", methods=["POST"])
@csrf.exempt
def subscription_plan_create():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    product_id = data.get("product_id")
    try:
        product_id = int(product_id)
    except (TypeError, ValueError):
        return jsonify({"error": "product_id is required."}), 400
    product = Product.query.get(product_id)
    if not product or product.seller_id != user["id"]:
        return jsonify({"error": "You can only create a plan for your own listing."}), 403
    try:
        interval_days = max(7, int(data.get("interval_days") or 30))
    except (TypeError, ValueError):
        interval_days = 30
    try:
        discount_pct = max(0.0, min(50.0, float(data.get("discount_pct") or 0)))
    except (TypeError, ValueError):
        discount_pct = 0.0
    plan = ProductSubscriptionPlan(
        product_id=product.id, seller_id=user["id"],
        interval_days=interval_days, discount_pct=discount_pct,
    )
    db.session.add(plan)
    db.session.commit()
    return jsonify({"plan": plan.to_dict()}), 201


