# ════════════════════════════════════════════════════════════
# STAGE 377: RISK INDEX
# A composite 0-100 per-country trade-risk score built ONLY from
# signals this platform already computes for real elsewhere —
# nothing here is a black-box AI score. Components: how often this
# platform's own sanctions screening (Stage 123) has flagged a
# counterparty in that country, how often that country's watched
# tariff lines (Stage 362) have changed recently, and how many active
# restricted-goods rules name that country. Any component with no
# underlying data yet contributes 0, and is called out in
# missing_data rather than silently averaged away.
# ════════════════════════════════════════════════════════════

class CountryRiskIndexScore(db.Model):
    __tablename__       = "country_risk_index_scores"
    id                  = db.Column(db.Integer, primary_key=True)
    country_code         = db.Column(db.String(4), nullable=False, unique=True, index=True)
    sanctions_component   = db.Column(db.Float, nullable=False, default=0.0)
    tariff_component       = db.Column(db.Float, nullable=False, default=0.0)
    restricted_goods_component = db.Column(db.Float, nullable=False, default=0.0)
    overall_score           = db.Column(db.Float, nullable=False, default=0.0)
    missing_data_json        = db.Column(db.Text, nullable=True)
    computed_at               = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        try:
            missing = json.loads(self.missing_data_json) if self.missing_data_json else []
        except Exception:
            missing = []
        return {
            "country_code": self.country_code, "sanctions_component": self.sanctions_component,
            "tariff_component": self.tariff_component,
            "restricted_goods_component": self.restricted_goods_component,
            "overall_score": self.overall_score, "missing_data": missing,
            "computed_at": self.computed_at.isoformat() if self.computed_at else None,
        }


_RISK_INDEX_WEIGHTS = {"sanctions": 0.4, "tariff": 0.3, "restricted_goods": 0.3}


def _compute_country_risk_index(country_code):
    country_code = (country_code or "").strip().upper()[:4]
    missing = []

    screenings = (TradeComplianceScreening.query
                  .filter(db.or_(TradeComplianceScreening.buyer_country == country_code,
                                  TradeComplianceScreening.seller_country == country_code))
                  .all())
    if screenings:
        matched = sum(1 for s in screenings if s.buyer_matched or s.seller_matched)
        sanctions_component = min(100.0, round(matched / len(screenings) * 100.0, 1))
    else:
        missing.append("no Stage 340 sanctions screenings recorded for this country yet")
        sanctions_component = 0.0

    tariff_entries = TariffScheduleEntry.query.filter_by(destination_country_code=country_code).all()
    if tariff_entries:
        recent_changes = sum(1 for e in tariff_entries
                              if e.rate_changed_at and e.rate_changed_at > datetime.utcnow() - timedelta(days=90))
        tariff_component = min(100.0, recent_changes * 20.0)
    else:
        missing.append("no watched tariff lines for this destination yet")
        tariff_component = 0.0

    restricted_rules = RestrictedGoodsRule.query.filter_by(active=True).all()
    matching_rules = [r for r in restricted_rules if (r.destination_country_code or "").upper() == country_code]
    if restricted_rules:
        restricted_goods_component = min(100.0, len(matching_rules) * 15.0)
    else:
        missing.append("no restricted-goods rules configured on the platform yet")
        restricted_goods_component = 0.0

    overall = round(
        sanctions_component * _RISK_INDEX_WEIGHTS["sanctions"] +
        tariff_component * _RISK_INDEX_WEIGHTS["tariff"] +
        restricted_goods_component * _RISK_INDEX_WEIGHTS["restricted_goods"], 1
    )

    score = CountryRiskIndexScore.query.filter_by(country_code=country_code).first()
    if not score:
        score = CountryRiskIndexScore(country_code=country_code)
        db.session.add(score)
    score.sanctions_component = sanctions_component
    score.tariff_component = tariff_component
    score.restricted_goods_component = restricted_goods_component
    score.overall_score = overall
    score.missing_data_json = json.dumps(missing)
    score.computed_at = datetime.utcnow()
    db.session.commit()
    return score


@app.route("/api/risk-index/<country_code>", methods=["GET"])
def risk_index_get(country_code):
    score = _compute_country_risk_index(country_code)
    return jsonify({"ok": True, "risk_index": score.to_dict()}), 200


# ════════════════════════════════════════════════════════════
# STAGE 378: POST-QUANTUM ENCRYPTION (SENSITIVE-NOTE VAULT)
# This environment does not have a real post-quantum KEM library
# (liboqs / pqcrypto) installed, so — same graceful-degradation
# pattern used for flask-socketio and cryptography elsewhere in this
# file — PQ_KEM_AVAILABLE is checked at import time and the vault
# is honest about which scheme actually protected each stored secret:
#   - if a PQ KEM library is present: hybrid PQ-KEM + AES-256-GCM
#   - if not: classical AES-256-GCM only (via the existing Fernet
#     helper), clearly labeled as NOT post-quantum-safe, never
#     mislabeled as PQ protection it doesn't actually have.
# ════════════════════════════════════════════════════════════

try:
    import oqs  # liboqs-python — not expected to be present in this environment
    PQ_KEM_AVAILABLE = True
    _PQ_KEM_ALGORITHM = "Kyber768"
except ImportError:
    PQ_KEM_AVAILABLE = False
    _PQ_KEM_ALGORITHM = None
    logging.warning("[SKIP] liboqs/oqs not installed — post-quantum vault will store secrets with "
                     "classical AES-256-GCM (via Fernet) only, honestly labeled 'classical_fallback', "
                     "until a PQ KEM library is installed on this deployment.")


class PqVaultSecret(db.Model):
    __tablename__       = "pq_vault_secrets"
    id                  = db.Column(db.Integer, primary_key=True)
    owner_user_id        = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    label                  = db.Column(db.String(120), nullable=False)
    ciphertext_b64          = db.Column(db.Text, nullable=False)
    scheme                   = db.Column(db.String(30), nullable=False)  # 'pq_kyber768_hybrid' or 'classical_fallback'
    created_at                = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self, reveal_plaintext=None):
        d = {"id": self.id, "label": self.label, "scheme": self.scheme,
             "created_at": self.created_at.isoformat() if self.created_at else None}
        if reveal_plaintext is not None:
            d["secret"] = reveal_plaintext
        return d


def _pq_vault_encrypt(plaintext):
    """Returns (ciphertext_b64, scheme). PQ_KEM_AVAILABLE branch is
    left as an explicit integration point for when liboqs is actually
    installed — it is not simulated here."""
    if PQ_KEM_AVAILABLE:
        raise RuntimeError("liboqs present but hybrid KEM wiring not yet implemented on this deployment.")
    fernet = _get_fernet()
    if not fernet:
        raise RuntimeError("Neither a PQ KEM library nor the cryptography package is available — "
                            "cannot store this secret safely.")
    token = fernet.encrypt(plaintext.encode("utf-8"))
    return base64.urlsafe_b64encode(token).decode("ascii"), "classical_fallback"


def _pq_vault_decrypt(ciphertext_b64, scheme):
    if scheme == "pq_kyber768_hybrid":
        raise RuntimeError("This secret was stored with a PQ scheme no longer available on this deployment.")
    fernet = _get_fernet()
    if not fernet:
        raise RuntimeError("The cryptography package is not available to decrypt this secret.")
    token = base64.urlsafe_b64decode(ciphertext_b64.encode("ascii"))
    return fernet.decrypt(token).decode("utf-8")


@app.route("/api/pq-vault/store", methods=["POST"])
@csrf.exempt
def pq_vault_store():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Please log in."}), 401
    data = request.get_json(silent=True) or {}
    label = (data.get("label") or "").strip()[:120]
    secret = data.get("secret") or ""
    if not label or not secret:
        return jsonify({"error": "Both a label and a secret value are required."}), 400
    try:
        ciphertext_b64, scheme = _pq_vault_encrypt(secret)
    except RuntimeError as e:
        return jsonify({"error": str(e)}), 503
    row = PqVaultSecret(owner_user_id=user["id"], label=label, ciphertext_b64=ciphertext_b64, scheme=scheme)
    db.session.add(row)
    db.session.commit()
    return jsonify({"ok": True, "secret": row.to_dict(),
                     "pq_kem_available": PQ_KEM_AVAILABLE}), 201


