# ════════════════════════════════════════════════════════════
# STAGE 380: DID VERIFICATION (DECENTRALIZED IDENTIFIER)
# Issues each account a real did:key identifier (W3C did:key method,
# Ed25519, ed25519-pub multicodec 0xed01) using the cryptography
# library already vendored in this file — not a simulated ID string.
# The private key is generated server-side, shown to the user exactly
# once, and stored at rest only in its Fernet-encrypted form (same
# helper as the API-key vault) so it can be used for
# platform-initiated signing later without ever being displayed again.
# Anyone can verify a signature against a public did:key with no
# login required, which is the point of a DID.
# ════════════════════════════════════════════════════════════

_B58_ALPHABET = "123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz"


def _b58encode(data: bytes) -> str:
    num = int.from_bytes(data, "big")
    encoded = ""
    while num > 0:
        num, rem = divmod(num, 58)
        encoded = _B58_ALPHABET[rem] + encoded
    n_pad = len(data) - len(data.lstrip(b"\x00"))
    return "1" * n_pad + encoded


class UserDidIdentity(db.Model):
    __tablename__       = "user_did_identities"
    id                  = db.Column(db.Integer, primary_key=True)
    user_id              = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, unique=True, index=True)
    did                    = db.Column(db.String(120), nullable=False, unique=True, index=True)
    public_key_b64          = db.Column(db.String(120), nullable=False)
    private_key_encrypted     = db.Column(db.Text, nullable=True)
    created_at                 = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        return {"user_id": self.user_id, "did": self.did, "public_key_b64": self.public_key_b64,
                 "created_at": self.created_at.isoformat() if self.created_at else None}


@app.route("/api/did/generate", methods=["POST"])
@csrf.exempt
def did_generate():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Please log in."}), 401
    if UserDidIdentity.query.filter_by(user_id=user["id"]).first():
        return jsonify({"error": "A DID already exists for this account."}), 400
    try:
        from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PrivateKey
        from cryptography.hazmat.primitives import serialization
    except ImportError:
        return jsonify({"error": "The cryptography package is not available on this deployment."}), 503

    private_key = Ed25519PrivateKey.generate()
    public_key = private_key.public_key()
    pub_bytes = public_key.public_bytes(encoding=serialization.Encoding.Raw,
                                          format=serialization.PublicFormat.Raw)
    priv_bytes = private_key.private_bytes(encoding=serialization.Encoding.Raw,
                                             format=serialization.PrivateFormat.Raw,
                                             encryption_algorithm=serialization.NoEncryption())
    did = "did:key:z" + _b58encode(b"\xed\x01" + pub_bytes)

    fernet = _get_fernet()
    encrypted_priv = fernet.encrypt(priv_bytes).decode("ascii") if fernet else None

    identity = UserDidIdentity(user_id=user["id"], did=did,
                                 public_key_b64=base64.urlsafe_b64encode(pub_bytes).decode("ascii"),
                                 private_key_encrypted=encrypted_priv)
    db.session.add(identity)
    db.session.commit()
    return jsonify({"ok": True, "did": identity.to_dict(),
                     "private_key_hex_shown_once": priv_bytes.hex(),
                     "warning": "Store this private key yourself now — it will never be shown again."}), 201


