@app.route("/api/did/verify", methods=["POST"])
@csrf.exempt
def did_verify_signature():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    data = request.get_json(silent=True) or {}
    did = (data.get("did") or "").strip()
    message = data.get("message") or ""
    signature_hex = (data.get("signature_hex") or "").strip()
    identity = UserDidIdentity.query.filter_by(did=did).first()
    if not identity:
        return jsonify({"error": "Unknown DID."}), 404
    try:
        from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PublicKey
        from cryptography.exceptions import InvalidSignature
    except ImportError:
        return jsonify({"error": "The cryptography package is not available on this deployment."}), 503
    try:
        pub_bytes = base64.urlsafe_b64decode(identity.public_key_b64.encode("ascii"))
        public_key = Ed25519PublicKey.from_public_bytes(pub_bytes)
        public_key.verify(bytes.fromhex(signature_hex), message.encode("utf-8"))
        return jsonify({"ok": True, "valid": True}), 200
    except InvalidSignature:
        return jsonify({"ok": True, "valid": False}), 200
    except Exception as e:
        return jsonify({"error": f"Could not verify signature: {e}"}), 400


