# ════════════════════════════════════════════════════════════
# STAGE 382: PRE-PUBLISH COMPLIANCE CO-PILOT
# One aggregate check the seller can run before publishing a listing.
# It composes checks this codebase already performs for real elsewhere
# (HS code presence, Stage 335 restricted-goods rules, Stage 123
# sanctions screening of the seller) instead of inventing new
# analysis. Advisory only, same "floor not ceiling" posture as the
# Stage 372 ESG self-attestation — it never blocks publishing itself,
# it surfaces what a customs officer or payment processor might flag.
# ════════════════════════════════════════════════════════════

@app.route("/api/products/<int:product_id>/compliance-check", methods=["GET"])
def product_compliance_check(product_id):
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Please log in."}), 401
    product = Product.query.get(product_id)
    if not product:
        return jsonify({"error": "Listing not found."}), 404
    if product.seller_id != user["id"]:
        return jsonify({"error": "You can only run the compliance check on your own listing."}), 403

    checks = []

    if product.hs_code:
        checks.append({"check": "hs_code_present", "status": "pass",
                        "detail": f"HS code {product.hs_code} is set."})
    else:
        checks.append({"check": "hs_code_present", "status": "warning",
                        "detail": "No HS code set — customs paperwork and tariff lookups will be incomplete."})

    if product.country_of_origin:
        checks.append({"check": "country_of_origin_present", "status": "pass",
                        "detail": f"Country of origin set to {product.country_of_origin}."})
    else:
        checks.append({"check": "country_of_origin_present", "status": "warning",
                        "detail": "No country of origin set — required on most commercial invoices."})

    active_rules = RestrictedGoodsRule.query.filter_by(active=True).all()
    name_lower = (product.name or "").lower()
    category_lower = (product.category or "").lower()
    keyword_hits = [r for r in active_rules if r.keyword and r.keyword.lower() in (name_lower + " " + category_lower)]
    if keyword_hits:
        checks.append({"check": "restricted_goods_keyword_match", "status": "fail",
                        "detail": f"{len(keyword_hits)} restricted-goods rule(s) match this listing's name/category — "
                                  "review before publishing."})
    else:
        checks.append({"check": "restricted_goods_keyword_match", "status": "pass",
                        "detail": "No restricted-goods rule matched this listing's name or category."})

    seller = UserAccount.query.get(product.seller_id)
    if seller:
        sanctions_results, sanctions_error = _run_sanctions_list_check(seller.name)
        if sanctions_error:
            checks.append({"check": "seller_sanctions_screen", "status": "unknown", "detail": sanctions_error})
        elif sanctions_results:
            checks.append({"check": "seller_sanctions_screen", "status": "fail",
                            "detail": f"Seller name matched {len(sanctions_results)} entr(y/ies) on the "
                                      "Consolidated Screening List — verify this is not a true match."})
        else:
            checks.append({"check": "seller_sanctions_screen", "status": "pass",
                            "detail": "Seller name did not match the Consolidated Screening List."})

    overall = "pass"
    if any(c["status"] == "fail" for c in checks):
        overall = "fail"
    elif any(c["status"] in ("warning", "unknown") for c in checks):
        overall = "warning"

