# STAGE 383: SANDBOX MODE
# A fully isolated test environment: sandbox API keys and a
# sandbox order/payment simulator that never touch real Product,
# Order, or payment rows. Lets a developer or new seller exercise
# the integration flow (checkout, webhook shape, fee math) without
# any real money or inventory movement.
# ════════════════════════════════════════════════════════════

class SandboxApiKey(db.Model):
    __tablename__  = "sandbox_api_keys"
    id             = db.Column(db.Integer, primary_key=True)
    user_id        = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    key            = db.Column(db.String(64), unique=True, nullable=False, index=True)
    label          = db.Column(db.String(120), nullable=True)
    active         = db.Column(db.Boolean, default=True, nullable=False)
    created_at     = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        return {"id": self.id, "key": self.key, "label": self.label,
                "active": self.active,
                "created_at": self.created_at.isoformat() if self.created_at else None}


class SandboxEvent(db.Model):
    __tablename__  = "sandbox_events"
    id             = db.Column(db.Integer, primary_key=True)
    user_id        = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
