@app.route("/api/sandbox/simulate-order", methods=["POST"])
@csrf.exempt
def sandbox_simulate_order():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    data = request.get_json(silent=True) or {}
    sandbox_key = (data.get("sandbox_key") or "").strip()
    key_row = SandboxApiKey.query.filter_by(key=sandbox_key, active=True).first()
    if not key_row:
        return jsonify({"error": "Unknown or revoked sandbox key."}), 401
    product_name = (data.get("product_name") or "Sandbox test product").strip()[:200]
    quantity = max(1, int(data.get("quantity") or 1))
    unit_price = float(data.get("unit_price") or 10.0)
    total = round(unit_price * quantity, 2)
    fee = round(total * (MARKETPLACE_PLATFORM_FEE_BPS / 10000.0), 2)
    fake_order_id = "sbx_order_" + secrets.token_hex(8)
    result = {
        "sandbox": True,
        "order_id": fake_order_id,
        "status": "confirmed",
        "product_name": product_name,
        "quantity": quantity,
        "unit_price": unit_price,
        "total_amount": total,
        "platform_fee": fee,
        "webhook_shape_example": {
            "type": "sandbox.order.confirmed",
            "data": {"order_id": fake_order_id, "total_amount": total},
        },
    }
    db.session.add(SandboxEvent(user_id=key_row.user_id, event_type="simulate_order",
                                 payload_json=json.dumps(result)))
    db.session.commit()
    return jsonify(result), 200


