    eligible_categories_csv  = db.Column(db.String(400), nullable=False, default="")
    benefits_summary         = db.Column(db.String(400), nullable=False, default="")
    official_url             = db.Column(db.String(300), nullable=True)
    active                  = db.Column(db.Boolean, default=True, nullable=False)

    def to_dict(self):
        return {"id": self.id, "name": self.name, "country_code": self.country_code,
                "eligible_categories": [c.strip() for c in self.eligible_categories_csv.split(",") if c.strip()],
                "benefits_summary": self.benefits_summary, "official_url": self.official_url}


