@app.route("/api/sez/match", methods=["GET"])
def sez_match():
    category = (request.args.get("category") or "").strip().lower()
    country = (request.args.get("country_code") or "").strip().upper()
    q = SpecialEconomicZone.query.filter_by(active=True)
    if country:
        q = q.filter_by(country_code=country)
    zones = q.all()
    if category:
        zones = [z for z in zones
                 if any(category in c.strip().lower() for c in z.eligible_categories_csv.split(","))]
    return jsonify({"ok": True, "zones": [z.to_dict() for z in zones]}), 200


