# ════════════════════════════════════════════════════════════
# STAGE 386: OFFLINE SMS ACCESS
# USSD access already exists (see /api/ussd/callback and UssdMenu
# above) — this stage adds the other half of feature-phone/offline
# access: a keyword-command SMS inbound handler, so a user with no
# data connection and no USSD session open can still text a short
# command and get listings or order status back over plain SMS.
# ════════════════════════════════════════════════════════════

@app.route("/api/sms/inbound", methods=["POST"])
@csrf.exempt
def sms_inbound():
    # Keyword-command SMS handler: "SEARCH <term>" / "ORDER <id>".
    data = request.form if request.form else (request.get_json(silent=True) or {})
    message = (data.get("text") or data.get("message") or "").strip()
    upper = message.upper()
    if upper.startswith("SEARCH "):
        keyword = message[7:].strip()
        matches = Product.query.filter(Product.name.ilike(f"%{keyword}%")).limit(3).all()
        reply = "; ".join(f"{p.name[:30]} {p.currency or 'usd'}{p.price}" for p in matches) or "No matches found."
    elif upper.startswith("ORDER "):
        order_id_raw = message[6:].strip()
        order = ProductOrder.query.get(int(order_id_raw)) if order_id_raw.isdigit() else None
        reply = f"Order #{order.id}: {order.status}" if order else "Order not found."
    else:
        reply = "Commands: SEARCH <term>, ORDER <id>."
    return jsonify({"ok": True, "reply": reply}), 200


# ════════════════════════════════════════════════════════════
# STAGE 387: VOICE COMMERCE
# Accepts a speech-to-text transcript (recording/transcribing
# audio itself is a client-side concern this backend can't verify
# without a real device microphone) and resolves it to one of a
# small set of real actions against the existing catalog and order
# data — search, order status, or add-to-cart — the same way the
# USSD/SMS gateway resolves short commands.
# ════════════════════════════════════════════════════════════

class VoiceCommerceLog(db.Model):
    __tablename__  = "voice_commerce_log"
    id             = db.Column(db.Integer, primary_key=True)
    user_id        = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=True, index=True)
    transcript     = db.Column(db.String(400), nullable=False)
    resolved_intent = db.Column(db.String(40), nullable=False)
    created_at     = db.Column(db.DateTime, default=datetime.utcnow)


@app.route("/api/voice-commerce", methods=["POST"])
@csrf.exempt
def voice_commerce_command():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    data = request.get_json(silent=True) or {}
    transcript = (data.get("transcript") or "").strip()[:400]
    if not transcript:
        return jsonify({"error": "A transcript is required."}), 400
    user = _get_current_user()
    lower = transcript.lower()

    if "order status" in lower or "my order" in lower or lower.startswith("track"):
        intent = "order_status"
        if not user:
            result = {"message": "Log in to check order status by voice."}
        else:
            order = ProductOrder.query.filter_by(buyer_id=user["id"]).order_by(ProductOrder.id.desc()).first()
            result = ({"message": f"Your most recent order is number {order.id}, status {order.status}."}
                       if order else {"message": "You have no orders yet."})
    elif "find" in lower or "search" in lower or "show me" in lower:
        intent = "search"
        keyword = lower
        for phrase in ("find", "search for", "search", "show me"):
            keyword = keyword.replace(phrase, "")
        keyword = keyword.strip()[:80]
        matches = Product.query.filter(Product.name.ilike(f"%{keyword}%")).limit(5).all() if keyword else []
        result = {"message": f"Found {len(matches)} matching product(s).",
                   "products": [{"id": p.id, "name": p.name, "price": p.price} for p in matches]}
    elif "add" in lower and "cart" in lower:
        intent = "add_to_cart"
        result = {"message": "Say the exact product name after 'add' and open its listing page to confirm the "
                              "quantity — voice add-to-cart only stages the search, it does not check out."}
    else:
        intent = "unrecognized"
        result = {"message": "I did not recognize that command. Try 'search for <product>' or 'order status'."}

    db.session.add(VoiceCommerceLog(user_id=user["id"] if user else None,
                                     transcript=transcript, resolved_intent=intent))
    db.session.commit()
    result["intent"] = intent
    return jsonify({"ok": True, **result}), 200


# ════════════════════════════════════════════════════════════
# STAGE 388: SUBSIDIZED MICRO-SELLER ONBOARDING
# A discounted platform-fee track for sellers below a revenue
# threshold. Application goes to an admin queue; on approval, the
# seller's stored subsidy percent reduces the real
# MARKETPLACE_PLATFORM_FEE_BPS at checkout time via
# _effective_platform_fee_bps, the same fee math every other order
# already uses.
# ════════════════════════════════════════════════════════════

class MicroSellerApplication(db.Model):
    __tablename__            = "micro_seller_applications"
    id                       = db.Column(db.Integer, primary_key=True)
    user_id                   = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    monthly_revenue_estimate   = db.Column(db.Float, nullable=False)
    status                   = db.Column(db.String(20), nullable=False, default="pending")
    subsidy_percent            = db.Column(db.Float, nullable=False, default=0.0)
    reviewed_by_admin_id        = db.Column(db.Integer, nullable=True)
    reviewed_at               = db.Column(db.DateTime, nullable=True)
    created_at               = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        return {"id": self.id, "monthly_revenue_estimate": self.monthly_revenue_estimate,
                "status": self.status, "subsidy_percent": self.subsidy_percent,
                "created_at": self.created_at.isoformat() if self.created_at else None}


_MICRO_SELLER_REVENUE_THRESHOLD = float(os.environ.get("MICRO_SELLER_REVENUE_THRESHOLD", "500"))


def _effective_platform_fee_bps(seller_id):
    if not seller_id:
        return MARKETPLACE_PLATFORM_FEE_BPS
    micro_pct = 0.0
    approved = (MicroSellerApplication.query
                .filter_by(user_id=seller_id, status="approved")
                .order_by(MicroSellerApplication.reviewed_at.desc()).first())
    if approved:
        micro_pct = approved.subsidy_percent
    # STAGE 514c: a university/incubator fast-track discount uses the
    # same fee math; a seller takes whichever program discounts more
    # rather than stacking both.
    try:
        univ_pct = _university_partner_discount_pct(seller_id)
    except NameError:
        univ_pct = 0.0
    best_pct = max(micro_pct, univ_pct)
    if best_pct <= 0:
        return MARKETPLACE_PLATFORM_FEE_BPS
    reduced = MARKETPLACE_PLATFORM_FEE_BPS * (1 - best_pct / 100.0)
    return max(0, int(round(reduced)))


@app.route("/api/micro-seller/apply", methods=["POST"])
@csrf.exempt
def micro_seller_apply():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Please log in."}), 401
    data = request.get_json(silent=True) or {}
    try:
        revenue = float(data.get("monthly_revenue_estimate"))
    except (TypeError, ValueError):
        return jsonify({"error": "monthly_revenue_estimate must be a number."}), 400
    if revenue < 0:
        return jsonify({"error": "monthly_revenue_estimate cannot be negative."}), 400
    existing = MicroSellerApplication.query.filter_by(user_id=user["id"], status="pending").first()
    if existing:
        return jsonify({"error": "You already have a pending application."}), 400
    row = MicroSellerApplication(user_id=user["id"], monthly_revenue_estimate=revenue)
    db.session.add(row)
    db.session.commit()
    return jsonify({"ok": True, "application": row.to_dict()}), 201


