@app.route("/api/admin/micro-seller/applications/<int:app_id>/decide", methods=["POST"])
@csrf.exempt
def admin_micro_seller_decide(app_id):
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    admin_user, err = _require_admin()
    if err:
        return err
    row = MicroSellerApplication.query.get(app_id)
    if not row:
        return jsonify({"error": "Application not found."}), 404
    data = request.get_json(silent=True) or {}
    decision = data.get("decision")
    if decision not in ("approved", "rejected"):
        return jsonify({"error": "decision must be 'approved' or 'rejected'."}), 400
    row.status = decision
    if decision == "approved":
        if row.monthly_revenue_estimate <= _MICRO_SELLER_REVENUE_THRESHOLD:
            row.subsidy_percent = 100.0
        else:
            row.subsidy_percent = 50.0
    row.reviewed_by_admin_id = admin_user.id
    row.reviewed_at = datetime.utcnow()
    db.session.commit()
    return jsonify({"ok": True, "application": row.to_dict()}), 200


