@app.route("/api/checkout-sdk/start", methods=["GET"])
def checkout_sdk_start():
    publishable_key = (request.args.get("pk") or "").strip()
    product_id = request.args.get("product_id")
    quantity = max(1, int(request.args.get("quantity") or 1))
    key_row = CheckoutSdkKey.query.filter_by(publishable_key=publishable_key, active=True).first()
    if not key_row:
        return jsonify({"error": "Invalid or revoked checkout SDK key."}), 401
    product = Product.query.get(product_id) if product_id and str(product_id).isdigit() else None
    if not product:
        return jsonify({"error": "Product not found."}), 404
    if product.seller_id != key_row.user_id:
        return jsonify({"error": "This key is not authorized to sell that listing."}), 403
    user = _get_current_user()
    if not user:
        # The visitor arrived from an external site and isn't logged
        # into this platform yet — send them to log in, then straight
        # back to this same checkout-start URL to resume.
        return redirect("/?login_redirect=" + quote(request.url, safe=""))
    # Reuses the platform's real product-checkout creation path — the
    # same function every other Buy Now flow on this platform calls.
    order, checkout_url = _create_product_order_checkout(product, user["id"], quantity)
    if not checkout_url:
        return jsonify({"error": "Could not start checkout for this listing."}), 500
    return redirect(checkout_url)


# ════════════════════════════════════════════════════════════
# STAGE 390: AI DISPUTE MEDIATOR
# Drafts a neutral recommendation from the real evidence already on
# an open EscrowDispute (the dispute reason plus every message both
# sides have actually posted to it) — never invents evidence, and
# never auto-resolves anything. It runs through the same real
# provider chain (_one_round: Claude, then Gemini, then OpenAI) every
# other AI feature on this platform uses, and reports plainly if no
# provider is configured rather than fabricating a recommendation.
# ════════════════════════════════════════════════════════════

class DisputeMediationRecommendation(db.Model):
    __tablename__     = "dispute_mediation_recommendations"
    id                = db.Column(db.Integer, primary_key=True)
    dispute_id        = db.Column(db.Integer, db.ForeignKey("escrow_disputes.id"), nullable=False, index=True)
    requested_by_id   = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False)
    recommendation    = db.Column(db.Text, nullable=False)
    evidence_message_count = db.Column(db.Integer, nullable=False, default=0)
    created_at        = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        return {"id": self.id, "dispute_id": self.dispute_id, "recommendation": self.recommendation,
                "evidence_message_count": self.evidence_message_count,
                "created_at": self.created_at.isoformat() if self.created_at else None}


_DISPUTE_MEDIATOR_SYSTEM_PROMPT = (
    "You are a neutral trade-dispute mediator. You will be given a dispute reason and a "
    "chronological transcript of messages both parties actually posted. Base your recommendation "
    "ONLY on what is in that transcript — never invent facts neither party has stated. Write a short, "
    "neutral, non-binding recommendation: (1) a one-line summary of the disagreement, (2) what evidence "
    "supports each side, (3) a suggested resolution (release to seller, refund to buyer, or a specific "
    "split), (4) if the evidence is too thin to recommend one side, say so plainly instead of guessing. "
    "State clearly that this is advisory only and does not bind either party or the platform."
)


@app.route("/api/disputes/<int:dispute_id>/mediate", methods=["POST"])
@csrf.exempt
def dispute_ai_mediate(dispute_id):
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    dispute = EscrowDispute.query.get(dispute_id)
    if not dispute:
        return jsonify({"error": "Dispute not found."}), 404
    escrow = EscrowTransaction.query.get(dispute.escrow_id)
    is_party = (dispute.opened_by_id == user["id"] or
                (escrow and user["id"] in (escrow.buyer_id, escrow.seller_id)))
    if not is_party:
        return jsonify({"error": "Only the parties to this dispute can request mediation."}), 403

    messages = (EscrowDisputeMessage.query.filter_by(dispute_id=dispute_id)
                .order_by(EscrowDisputeMessage.created_at.asc()).all())
    transcript_lines = [f"Dispute reason: {dispute.reason}"]
    for m in messages:
        sender = UserAccount.query.get(m.sender_id)
        transcript_lines.append(f"{sender.name if sender else 'Unknown'}: {m.message}")
    transcript = "\n".join(transcript_lines)

    result = _one_round(
        [{"role": "user", "content": f"Dispute transcript:\n\n{transcript}\n\nProvide your mediation recommendation."}],
        user_id=user["id"], system_prompt=_DISPUTE_MEDIATOR_SYSTEM_PROMPT,
    )
    if not result:
        return jsonify({"error": "No AI provider is currently configured to run mediation."}), 503

    row = DisputeMediationRecommendation(
        dispute_id=dispute_id, requested_by_id=user["id"],
        recommendation=result, evidence_message_count=len(messages),
    )
    db.session.add(row)
    db.session.commit()
    return jsonify({"ok": True, "recommendation": row.to_dict()}), 201


