    rows = (DisputeMediationRecommendation.query.filter_by(dispute_id=dispute_id)
            .order_by(DisputeMediationRecommendation.created_at.desc()).all())
    return jsonify({"ok": True, "recommendations": [r.to_dict() for r in rows]}), 200


