# STAGE 391: THIRD-PARTY ARBITRATION MARKETPLACE
# A directory of real accredited international trade arbitration
# institutions, plus a way to escalate an open, unresolved
# EscrowDispute to one of them. The platform never claims to run
# the arbitration itself — a request just records that a party
# wants to escalate and hands them the real institution's own
# public case-filing contact.
# ════════════════════════════════════════════════════════════

class ArbitrationProvider(db.Model):
    __tablename__   = "arbitration_providers"
    id              = db.Column(db.Integer, primary_key=True)
    name            = db.Column(db.String(160), nullable=False)
    accreditation   = db.Column(db.String(200), nullable=True)
    regions_csv     = db.Column(db.String(300), nullable=False, default="")
    official_url    = db.Column(db.String(300), nullable=False)
    active          = db.Column(db.Boolean, default=True, nullable=False)

    def to_dict(self):
        return {"id": self.id, "name": self.name, "accreditation": self.accreditation,
                "regions": [r.strip() for r in self.regions_csv.split(",") if r.strip()],
                "official_url": self.official_url}


class ArbitrationRequest(db.Model):
    __tablename__     = "arbitration_requests"
    id                = db.Column(db.Integer, primary_key=True)
    dispute_id        = db.Column(db.Integer, db.ForeignKey("escrow_disputes.id"), nullable=False, index=True)
    provider_id       = db.Column(db.Integer, db.ForeignKey("arbitration_providers.id"), nullable=False)
    requested_by_id   = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False)
    status            = db.Column(db.String(20), nullable=False, default="requested")  # requested, acknowledged, closed
    created_at        = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        provider = ArbitrationProvider.query.get(self.provider_id)
        return {"id": self.id, "dispute_id": self.dispute_id, "status": self.status,
                "provider": provider.to_dict() if provider else None,
                "created_at": self.created_at.isoformat() if self.created_at else None}


