@csrf.exempt
def dispute_escalate_to_arbitration(dispute_id):
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    dispute = EscrowDispute.query.get(dispute_id)
    if not dispute:
        return jsonify({"error": "Dispute not found."}), 404
    if dispute.status != "open":
        return jsonify({"error": "Only an open dispute can be escalated."}), 400
    data = request.get_json(silent=True) or {}
    provider = ArbitrationProvider.query.get(data.get("provider_id"))
    if not provider or not provider.active:
        return jsonify({"error": "Unknown arbitration provider."}), 400
    row = ArbitrationRequest(dispute_id=dispute_id, provider_id=provider.id, requested_by_id=user["id"])
    db.session.add(row)
