# ════════════════════════════════════════════════════════════
# STAGE 392: AUTOMATED DENIED-PARTY BATCH SCREENING
# Screens an entire list of names in one request instead of one at a
# time — loops over the SAME real trade.gov Consolidated Screening
# List check (_run_sanctions_list_check) every existing on-demand
# and automatic screening already uses. Never a second, different,
# or fabricated data source for the same claim.
# ════════════════════════════════════════════════════════════

class BatchScreeningRun(db.Model):
    __tablename__  = "batch_screening_runs"
    id             = db.Column(db.Integer, primary_key=True)
    owner_id       = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    label          = db.Column(db.String(160), nullable=True)
    total_names    = db.Column(db.Integer, nullable=False, default=0)
    matched_count  = db.Column(db.Integer, nullable=False, default=0)
    created_at     = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        return {"id": self.id, "label": self.label, "total_names": self.total_names,
                "matched_count": self.matched_count,
                "created_at": self.created_at.isoformat() if self.created_at else None}


class BatchScreeningItem(db.Model):
    __tablename__  = "batch_screening_items"
    id             = db.Column(db.Integer, primary_key=True)
    batch_id       = db.Column(db.Integer, db.ForeignKey("batch_screening_runs.id"), nullable=False, index=True)
    query_name     = db.Column(db.String(200), nullable=False)
    matched        = db.Column(db.Boolean, nullable=False, default=False)
    match_count    = db.Column(db.Integer, nullable=False, default=0)
    error          = db.Column(db.String(300), nullable=True)

    def to_dict(self):
        return {"id": self.id, "query_name": self.query_name, "matched": self.matched,
                "match_count": self.match_count, "error": self.error}


_BATCH_SCREENING_MAX_NAMES = 100


@app.route("/api/compliance/batch-screen", methods=["POST"])
@csrf.exempt
def compliance_batch_screen():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    names_raw = data.get("names")
    if isinstance(names_raw, str):
        names = [n.strip() for n in names_raw.splitlines() if n.strip()]
    elif isinstance(names_raw, list):
        names = [str(n).strip() for n in names_raw if str(n).strip()]
    else:
        names = []
    if not names:
        return jsonify({"error": "Provide at least one name, one per line."}), 400
    names = names[:_BATCH_SCREENING_MAX_NAMES]

    if not TRADE_GOV_API_KEY:
        return jsonify({"error": "Sanctions screening isn't configured — needs a free API key from developer.trade.gov."}), 503

    batch = BatchScreeningRun(owner_id=user["id"], label=(data.get("label") or "").strip()[:160] or None,
                               total_names=len(names))
    db.session.add(batch)
    db.session.flush()

    matched_count = 0
    for name in names:
        results, error = _run_sanctions_list_check(name)
        item = BatchScreeningItem(
            batch_id=batch.id, query_name=name[:200],
            matched=bool(results), match_count=len(results) if results else 0,
            error=error[:300] if error else None,
        )
        if item.matched:
            matched_count += 1
        db.session.add(item)
    batch.matched_count = matched_count
    db.session.commit()
    return jsonify({"ok": True, "batch": batch.to_dict()}), 201


