# ════════════════════════════════════════════════════════════
# STAGE 393: BLOCKCHAIN-VERIFIED CERTIFICATION REGISTRY
# Same honestly-scoped mechanism as the raw-material traceability
# ledger above: no private blockchain is invented here. A
# certificate's data is hashed with SHA-256, and that hash is
# submitted to the same real, public OpenTimestamps calendar
# servers (OTS_CALENDAR_SERVERS, defined above) already used to
# anchor the transaction ledger to the actual Bitcoin blockchain —
# anyone, on any platform, can independently re-verify the result
# with the free `ots` tool, without ever trusting this server again.
# ════════════════════════════════════════════════════════════

class CertificationRecord(db.Model):
    __tablename__     = "certification_records"
    id                = db.Column(db.Integer, primary_key=True)
    seller_id         = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    cert_type         = db.Column(db.String(40), nullable=False)  # halal, kosher, organic, fair_trade, other
    issuing_body      = db.Column(db.String(160), nullable=False)
    certificate_number = db.Column(db.String(120), nullable=True)
    document_url      = db.Column(db.String(500), nullable=True)
    document_hash     = db.Column(db.String(64), nullable=False)
    ots_calendar_server = db.Column(db.String(200), nullable=True)
    ots_proof_b64     = db.Column(db.Text, nullable=True)
    anchor_status     = db.Column(db.String(16), nullable=False, default="pending")  # pending, submitted, failed
    created_at        = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        return {"id": self.id, "seller_id": self.seller_id, "cert_type": self.cert_type,
                "issuing_body": self.issuing_body, "certificate_number": self.certificate_number,
                "document_url": self.document_url, "document_hash": self.document_hash,
                "anchor_status": self.anchor_status, "has_proof": bool(self.ots_proof_b64),
                "created_at": self.created_at.isoformat() if self.created_at else None}


def _anchor_certification_hash(cert):
    digest_bytes = bytes.fromhex(cert.document_hash)
    last_error = None
    for server in OTS_CALENDAR_SERVERS:
        try:
            resp = requests.post(
                f"{server}/digest", data=digest_bytes,
                headers={"Accept": "application/vnd.opentimestamps.v1",
                         "Content-Type": "application/x-www-form-urlencoded"},
                timeout=10,
            )
            if resp.status_code == 200 and resp.content:
                cert.ots_calendar_server = server
                cert.ots_proof_b64 = base64.b64encode(resp.content).decode("ascii")
                cert.anchor_status = "submitted"
                return
            last_error = f"{server} returned HTTP {resp.status_code}"
        except Exception as e:
            last_error = f"{server}: {e}"
    cert.anchor_status = "failed"
    logging.error(f"[CERTIFICATION ANCHOR] {last_error}")


@app.route("/api/certifications", methods=["POST"])
@csrf.exempt
def certification_create():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    cert_type = (data.get("cert_type") or "").strip().lower()
    issuing_body = (data.get("issuing_body") or "").strip()[:160]
    if cert_type not in ("halal", "kosher", "organic", "fair_trade", "other") or not issuing_body:
        return jsonify({"error": "cert_type and issuing_body are required."}), 400
    canonical = json.dumps({
        "seller_id": user["id"], "cert_type": cert_type, "issuing_body": issuing_body,
        "certificate_number": (data.get("certificate_number") or "").strip()[:120],
        "document_url": (data.get("document_url") or "").strip()[:500],
    }, sort_keys=True)
    document_hash = hashlib.sha256(canonical.encode()).hexdigest()
    cert = CertificationRecord(
        seller_id=user["id"], cert_type=cert_type, issuing_body=issuing_body,
        certificate_number=(data.get("certificate_number") or "").strip()[:120] or None,
        document_url=(data.get("document_url") or "").strip()[:500] or None,
        document_hash=document_hash,
    )
    _anchor_certification_hash(cert)
    db.session.add(cert)
    db.session.commit()
    return jsonify({"ok": True, "certification": cert.to_dict()}), 201


