@app.route("/api/products/<int:product_id>/counterfeit-scan", methods=["POST"])
@csrf.exempt
def product_counterfeit_scan(product_id):
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    product = Product.query.get(product_id)
    if not product:
        return jsonify({"error": "Product not found."}), 404
    try:
        image_urls = json.loads(product.image_urls) if product.image_urls else []
    except Exception:
        image_urls = []
    if not image_urls:
        return jsonify({"error": "This product has no listing images to scan."}), 400
    assets = BrandImageAsset.query.all()
    if not assets:
        return jsonify({"error": "No registered brand images to compare against yet."}), 400

    best_asset_id, best_distance = None, None
    for url in image_urls[:5]:
        try:
            resp = requests.get(url, timeout=10)
            resp.raise_for_status()
            listing_hash = _average_hash_from_bytes(resp.content)
        except Exception:
            continue
        for asset in assets:
            distance = _hamming_distance_hex(listing_hash, asset.phash)
            if best_distance is None or distance < best_distance:
                best_distance, best_asset_id = distance, asset.id

    flagged = best_distance is not None and best_distance <= _COUNTERFEIT_FLAG_HAMMING_THRESHOLD
    result = CounterfeitScanResult(
        product_id=product_id, scanned_by_id=user["id"],
        best_match_asset_id=best_asset_id, best_hamming_distance=best_distance, flagged=flagged,
    )
    db.session.add(result)
    db.session.commit()
    return jsonify({"ok": True, "result": result.to_dict()}), 201


