    if data.get("requested_date"):
        try:
            requested_date = datetime.fromisoformat(data["requested_date"])
        except (ValueError, TypeError):
            return jsonify({"error": "requested_date must be a valid ISO 8601 datetime."}), 400
    booking = InspectionBooking(
        requested_by_id=user["id"], provider_id=provider.id,
        product_id=data.get("product_id") if str(data.get("product_id") or "").isdigit() else None,
        requested_date=requested_date, notes=(data.get("notes") or "").strip()[:500] or None,
    )
    db.session.add(booking)
    db.session.commit()
    return jsonify({"ok": True, "booking": booking.to_dict()}), 201


