# ════════════════════════════════════════════════════════════
# STAGE 398: DIGITAL TRADE PASSPORT
# Aggregates real, already-verified signals already stored elsewhere
# in this platform into one portable profile — it computes nothing
# new about a seller's trustworthiness beyond what those underlying
# records already established; it just presents them together.
# ════════════════════════════════════════════════════════════

@app.route("/api/trade-passport/<int:seller_id>", methods=["GET"])
def trade_passport(seller_id):
    seller = UserAccount.query.get(seller_id)
    if not seller:
        return jsonify({"error": "Seller not found."}), 404

    kyc = (KYCVerification.query
           .filter_by(owner_id=seller_id, context="marketplace_buyer", status="approved")
           .order_by(KYCVerification.reviewed_at.desc()).first())
    biometric = (KYCVerification.query
                 .filter_by(owner_id=seller_id, context="seller_biometric_tier")
                 .order_by(KYCVerification.created_at.desc()).first())
    biometric_verified = bool(biometric and biometric.verifier == "smile_identity"
                               and biometric.verifier_result == "verified")
    certifications = CertificationRecord.query.filter_by(seller_id=seller_id).all()
    livestream_verified_count = FactoryLivestreamSlot.query.filter_by(
        seller_id=seller_id, status="completed").count()
    ledger_entries = TransactionLedgerEntry.query.filter_by(seller_id=seller_id).count()
    anchors = ChainAnchor.query.filter_by(seller_id=seller_id, status="submitted").count()
    micro_seller_approved = MicroSellerApplication.query.filter_by(
        user_id=seller_id, status="approved").first() is not None

    signals = {
        "id_verified": bool(kyc),
        "biometric_verified": biometric_verified,
        "certifications_count": len(certifications),
        "certification_types": sorted(set(c.cert_type for c in certifications)),
        "factory_livestream_sessions_verified": livestream_verified_count,
        "fulfilled_orders_on_notarized_ledger": ledger_entries,
        "ledger_blockchain_anchors": anchors,
        "micro_seller_subsidy_approved": micro_seller_approved,
    }
    passport_score = sum([
        20 if signals["id_verified"] else 0,
        25 if signals["biometric_verified"] else 0,
        10 * min(signals["certifications_count"], 3),
        10 if signals["factory_livestream_sessions_verified"] > 0 else 0,
        15 if signals["ledger_blockchain_anchors"] > 0 else 0,
    ])
    return jsonify({"ok": True, "seller_id": seller_id, "seller_name": seller.name,
                     "signals": signals, "passport_score": min(passport_score, 100)}), 200


# ════════════════════════════════════════════════════════════
# STAGE 399: REGULATORY CHANGE ALERT FEED
# Honestly scoped: this is an admin-curated feed a compliance team
# publishes to, not an automatic law-scraper — nothing here claims to
# monitor legislation in real time on its own. A seller subscribes by
# category/corridor and sees only alerts admins have actually posted,
# the same "never fabricate a result" rule as the sanctions checks.
# ════════════════════════════════════════════════════════════

class RegulatoryAlert(db.Model):
    __tablename__  = "regulatory_alerts"
    id             = db.Column(db.Integer, primary_key=True)
    title          = db.Column(db.String(200), nullable=False)
    category       = db.Column(db.String(60), nullable=False)  # e.g. tariffs, sanctions, product_safety, labeling
    country_code   = db.Column(db.String(4), nullable=True)
    body           = db.Column(db.Text, nullable=False)
    source_url     = db.Column(db.String(500), nullable=True)
    published_by_admin_id = db.Column(db.Integer, nullable=False)
    published_at   = db.Column(db.DateTime, default=datetime.utcnow, index=True)

    def to_dict(self):
        return {"id": self.id, "title": self.title, "category": self.category,
                "country_code": self.country_code, "body": self.body, "source_url": self.source_url,
                "published_at": self.published_at.isoformat() if self.published_at else None}


class RegulatoryAlertSubscription(db.Model):
    __tablename__  = "regulatory_alert_subscriptions"
    id             = db.Column(db.Integer, primary_key=True)
    user_id        = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    category       = db.Column(db.String(60), nullable=True)   # null = all categories
    country_code   = db.Column(db.String(4), nullable=True)    # null = all countries
    created_at     = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        return {"id": self.id, "category": self.category, "country_code": self.country_code}


@app.route("/api/admin/regulatory-alerts", methods=["POST"])
@csrf.exempt
def admin_regulatory_alert_publish():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    admin_user, err = _require_admin()
    if err:
        return err
    data = request.get_json(silent=True) or {}
    title = (data.get("title") or "").strip()[:200]
    category = (data.get("category") or "").strip().lower()[:60]
    body = (data.get("body") or "").strip()
    if not (title and category and body):
        return jsonify({"error": "title, category and body are required."}), 400
    alert = RegulatoryAlert(
        title=title, category=category,
        country_code=(data.get("country_code") or "").strip().upper()[:4] or None,
        body=body, source_url=(data.get("source_url") or "").strip()[:500] or None,
        published_by_admin_id=admin_user.id,
    )
    db.session.add(alert)
    db.session.commit()
    return jsonify({"ok": True, "alert": alert.to_dict()}), 201


@app.route("/api/regulatory-alerts", methods=["GET"])
def regulatory_alerts_list():
    category = (request.args.get("category") or "").strip().lower()
    country = (request.args.get("country_code") or "").strip().upper()
    q = RegulatoryAlert.query
    if category:
        q = q.filter_by(category=category)
    if country:
        q = q.filter_by(country_code=country)
    rows = q.order_by(RegulatoryAlert.published_at.desc()).limit(100).all()
    return jsonify({"ok": True, "alerts": [r.to_dict() for r in rows]}), 200


