@app.route("/api/regulatory-alerts/my-feed", methods=["GET"])
def regulatory_alert_my_feed():
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    subs = RegulatoryAlertSubscription.query.filter_by(user_id=user["id"]).all()
    if not subs:
        return jsonify({"ok": True, "alerts": []}), 200
    all_alerts = RegulatoryAlert.query.order_by(RegulatoryAlert.published_at.desc()).limit(300).all()
    matched = []
    for alert in all_alerts:
        for sub in subs:
            cat_ok = sub.category is None or sub.category == alert.category
            country_ok = sub.country_code is None or sub.country_code == alert.country_code
            if cat_ok and country_ok:
                matched.append(alert)
                break
    return jsonify({"ok": True, "alerts": [a.to_dict() for a in matched[:100]]}), 200


