# STAGE 400: REAL-TIME FREIGHT SPOT-RATE MARKETPLACE
# Carriers or platform admins post real lane rates; sellers query by
# lane. No rate is ever generated or estimated by this platform —
# every row here is a real quote someone entered, the same
# admin-curated model already used for regulatory alerts.
# ════════════════════════════════════════════════════════════

class FreightCarrier(db.Model):
    __tablename__  = "freight_carriers"
    id             = db.Column(db.Integer, primary_key=True)
    name           = db.Column(db.String(160), nullable=False)
    modes_csv      = db.Column(db.String(120), nullable=False, default="")  # sea,air,rail,road
    official_url   = db.Column(db.String(300), nullable=True)
    active         = db.Column(db.Boolean, default=True, nullable=False)

    def to_dict(self):
        return {"id": self.id, "name": self.name,
                "modes": [m.strip() for m in self.modes_csv.split(",") if m.strip()],
                "official_url": self.official_url}


class FreightSpotRate(db.Model):
    __tablename__     = "freight_spot_rates"
    id                = db.Column(db.Integer, primary_key=True)
    carrier_id        = db.Column(db.Integer, db.ForeignKey("freight_carriers.id"), nullable=False, index=True)
    origin_port       = db.Column(db.String(120), nullable=False, index=True)
    destination_port  = db.Column(db.String(120), nullable=False, index=True)
    mode              = db.Column(db.String(16), nullable=False)  # sea, air, rail, road
    container_type    = db.Column(db.String(40), nullable=True)   # e.g. 20ft, 40ft, LCL, N/A
    rate_usd          = db.Column(db.Float, nullable=False)
    transit_days      = db.Column(db.Integer, nullable=True)
    valid_until       = db.Column(db.DateTime, nullable=True)
    posted_by_admin_id = db.Column(db.Integer, nullable=False)
    posted_at         = db.Column(db.DateTime, default=datetime.utcnow, index=True)

    def to_dict(self):
        carrier = FreightCarrier.query.get(self.carrier_id)
        return {"id": self.id, "carrier": carrier.to_dict() if carrier else None,
                "origin_port": self.origin_port, "destination_port": self.destination_port,
                "mode": self.mode, "container_type": self.container_type,
                "rate_usd": self.rate_usd, "transit_days": self.transit_days,
                "valid_until": self.valid_until.isoformat() if self.valid_until else None,
                "posted_at": self.posted_at.isoformat() if self.posted_at else None}


_FREIGHT_CARRIER_SEED = [
    {"name": "Maersk", "modes_csv": "sea", "official_url": "https://www.maersk.com"},
    {"name": "MSC", "modes_csv": "sea", "official_url": "https://www.msc.com"},
    {"name": "CMA CGM", "modes_csv": "sea", "official_url": "https://www.cma-cgm.com"},
    {"name": "DHL Global Forwarding", "modes_csv": "air,sea,road", "official_url": "https://www.dhl.com/global-en/home/our-divisions/global-forwarding.html"},
    {"name": "Kuehne+Nagel", "modes_csv": "air,sea,road,rail", "official_url": "https://www.kuehne-nagel.com"},
]


def _seed_freight_carriers_if_empty():
    if FreightCarrier.query.first() is None:
        for row in _FREIGHT_CARRIER_SEED:
            db.session.add(FreightCarrier(**row))
        db.session.commit()


@app.route("/api/freight/carriers", methods=["GET"])
def freight_carriers_list():
    rows = FreightCarrier.query.filter_by(active=True).all()
    return jsonify({"ok": True, "carriers": [r.to_dict() for r in rows]}), 200


@app.route("/api/freight/spot-rates", methods=["GET"])
def freight_spot_rates_list():
    origin = (request.args.get("origin") or "").strip()
    destination = (request.args.get("destination") or "").strip()
    mode = (request.args.get("mode") or "").strip().lower()
    q = FreightSpotRate.query
    if origin:
        q = q.filter(FreightSpotRate.origin_port.ilike(f"%{origin}%"))
    if destination:
        q = q.filter(FreightSpotRate.destination_port.ilike(f"%{destination}%"))
    if mode:
        q = q.filter_by(mode=mode)
    rows = q.order_by(FreightSpotRate.rate_usd.asc()).limit(100).all()
    return jsonify({"ok": True, "rates": [r.to_dict() for r in rows]}), 200


@app.route("/api/freight/spot-rates", methods=["POST"])
@csrf.exempt
def freight_spot_rate_publish():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    admin_user, err = _require_admin()
    if err:
        return err
    data = request.get_json(silent=True) or {}
    carrier = FreightCarrier.query.get(data.get("carrier_id"))
    if not carrier:
        return jsonify({"error": "Unknown carrier."}), 400
    origin = (data.get("origin_port") or "").strip()[:120]
    destination = (data.get("destination_port") or "").strip()[:120]
    mode = (data.get("mode") or "").strip().lower()[:16]
    if not (origin and destination and mode) or not data.get("rate_usd"):
        return jsonify({"error": "origin_port, destination_port, mode and rate_usd are required."}), 400
    valid_until = None
    if data.get("valid_until"):
        try:
            valid_until = datetime.fromisoformat(data["valid_until"])
        except (ValueError, TypeError):
            return jsonify({"error": "valid_until must be a valid ISO 8601 datetime."}), 400
    rate = FreightSpotRate(
        carrier_id=carrier.id, origin_port=origin, destination_port=destination, mode=mode,
        container_type=(data.get("container_type") or "").strip()[:40] or None,
        rate_usd=float(data["rate_usd"]), transit_days=data.get("transit_days"),
        valid_until=valid_until, posted_by_admin_id=admin_user.id,
    )
    db.session.add(rate)
    db.session.commit()
    return jsonify({"ok": True, "rate": rate.to_dict()}), 201


# ════════════════════════════════════════════════════════════
# STAGE 401: LCL (LESS-THAN-CONTAINER-LOAD) POOLING MARKETPLACE
# A real pool is a container an admin/forwarder has actually organized
# for a lane; sellers reserve cubic-meter space in it. Capacity is
# tracked server-side so a pool can never be oversold.
# ════════════════════════════════════════════════════════════

class LclPool(db.Model):
    __tablename__     = "lcl_pools"
    id                = db.Column(db.Integer, primary_key=True)
    origin_port       = db.Column(db.String(120), nullable=False, index=True)
    destination_port  = db.Column(db.String(120), nullable=False, index=True)
    container_size    = db.Column(db.String(20), nullable=False, default="40ft")
    total_cbm         = db.Column(db.Float, nullable=False)
    used_cbm          = db.Column(db.Float, nullable=False, default=0.0)
    forwarder_name    = db.Column(db.String(160), nullable=True)
    etd                = db.Column(db.DateTime, nullable=True)
    status            = db.Column(db.String(16), nullable=False, default="open")  # open, closed, departed
    created_by_admin_id = db.Column(db.Integer, nullable=False)
    created_at        = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        return {"id": self.id, "origin_port": self.origin_port, "destination_port": self.destination_port,
                "container_size": self.container_size, "total_cbm": self.total_cbm, "used_cbm": self.used_cbm,
                "available_cbm": round(self.total_cbm - self.used_cbm, 2), "forwarder_name": self.forwarder_name,
                "etd": self.etd.isoformat() if self.etd else None, "status": self.status}


class LclPoolBooking(db.Model):
    __tablename__ = "lcl_pool_bookings"
    id            = db.Column(db.Integer, primary_key=True)
    pool_id       = db.Column(db.Integer, db.ForeignKey("lcl_pools.id"), nullable=False, index=True)
    seller_id     = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    cbm_booked    = db.Column(db.Float, nullable=False)
    status        = db.Column(db.String(16), nullable=False, default="booked")
    created_at    = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        pool = LclPool.query.get(self.pool_id)
        return {"id": self.id, "pool": pool.to_dict() if pool else None, "cbm_booked": self.cbm_booked,
                "status": self.status, "created_at": self.created_at.isoformat() if self.created_at else None}


@app.route("/api/lcl-pools", methods=["GET"])
def lcl_pools_list():
    rows = LclPool.query.filter_by(status="open").order_by(LclPool.etd.asc()).all()
    return jsonify({"ok": True, "pools": [r.to_dict() for r in rows]}), 200


@app.route("/api/lcl-pools", methods=["POST"])
@csrf.exempt
def lcl_pool_create():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    admin_user, err = _require_admin()
    if err:
        return err
    data = request.get_json(silent=True) or {}
    origin = (data.get("origin_port") or "").strip()[:120]
    destination = (data.get("destination_port") or "").strip()[:120]
    if not (origin and destination) or not data.get("total_cbm"):
        return jsonify({"error": "origin_port, destination_port and total_cbm are required."}), 400
    etd = None
    if data.get("etd"):
        try:
            etd = datetime.fromisoformat(data["etd"])
        except (ValueError, TypeError):
            return jsonify({"error": "etd must be a valid ISO 8601 datetime."}), 400
    pool = LclPool(
        origin_port=origin, destination_port=destination,
        container_size=(data.get("container_size") or "40ft").strip()[:20],
        total_cbm=float(data["total_cbm"]), forwarder_name=(data.get("forwarder_name") or "").strip()[:160] or None,
        etd=etd, created_by_admin_id=admin_user.id,
    )
    db.session.add(pool)
    db.session.commit()
    return jsonify({"ok": True, "pool": pool.to_dict()}), 201


@app.route("/api/lcl-pools/<int:pool_id>/book", methods=["POST"])
@csrf.exempt
def lcl_pool_book(pool_id):
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    pool = LclPool.query.get(pool_id)
    if not pool or pool.status != "open":
        return jsonify({"error": "Pool not found or no longer open."}), 404
    data = request.get_json(silent=True) or {}
    cbm = data.get("cbm_booked")
    if not cbm or float(cbm) <= 0:
        return jsonify({"error": "cbm_booked must be a positive number."}), 400
    cbm = float(cbm)
    if pool.used_cbm + cbm > pool.total_cbm:
        return jsonify({"error": f"Only {round(pool.total_cbm - pool.used_cbm, 2)} cbm left in this pool."}), 400
    pool.used_cbm += cbm
    booking = LclPoolBooking(pool_id=pool.id, seller_id=user["id"], cbm_booked=cbm)
    db.session.add(booking)
    db.session.commit()
    return jsonify({"ok": True, "booking": booking.to_dict()}), 201


@app.route("/api/lcl-pools/bookings/mine", methods=["GET"])
def lcl_pool_bookings_mine():
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    rows = (LclPoolBooking.query.filter_by(seller_id=user["id"])
            .order_by(LclPoolBooking.created_at.desc()).all())
    return jsonify({"ok": True, "bookings": [r.to_dict() for r in rows]}), 200


