# ════════════════════════════════════════════════════════════
# STAGE 407: WEATHER DISRUPTION ALERTS
# Uses Open-Meteo's real, free, key-less forecast API — genuine
# forecast data, not simulated. A user watches a route waypoint
# (lat/lon); checking the watch pulls that point's real current
# forecast and flags conditions that could disrupt shipping (high
# wind, heavy precipitation, storms).
# ════════════════════════════════════════════════════════════

class WeatherRouteWatch(db.Model):
    __tablename__  = "weather_route_watches"
    id             = db.Column(db.Integer, primary_key=True)
    user_id        = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    route_label    = db.Column(db.String(160), nullable=False)
    lat            = db.Column(db.Float, nullable=False)
    lon            = db.Column(db.Float, nullable=False)
    created_at     = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        return {"id": self.id, "route_label": self.route_label, "lat": self.lat, "lon": self.lon}


@app.route("/api/logistics/weather-watches", methods=["POST"])
@csrf.exempt
def weather_route_watch_create():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    label = (data.get("route_label") or "").strip()[:160]
    lat, lon = data.get("lat"), data.get("lon")
    if not (label and lat is not None and lon is not None):
        return jsonify({"error": "route_label, lat and lon are required."}), 400
    watch = WeatherRouteWatch(user_id=user["id"], route_label=label, lat=float(lat), lon=float(lon))
    db.session.add(watch)
    db.session.commit()
    return jsonify({"ok": True, "watch": watch.to_dict()}), 201


@app.route("/api/logistics/weather-watches/mine", methods=["GET"])
def weather_route_watches_mine():
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    rows = WeatherRouteWatch.query.filter_by(user_id=user["id"]).all()
    return jsonify({"ok": True, "watches": [r.to_dict() for r in rows]}), 200


@app.route("/api/logistics/weather-alerts/check", methods=["GET"])
def weather_alerts_check():
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    watches = WeatherRouteWatch.query.filter_by(user_id=user["id"]).all()
    alerts = []
    for w in watches:
        try:
            resp = requests.get("https://api.open-meteo.com/v1/forecast",
                                 params={"latitude": w.lat, "longitude": w.lon,
                                         "current": "wind_speed_10m,precipitation,weather_code"},
                                 timeout=10)
            if not resp.ok:
                continue
            current = (resp.json() or {}).get("current") or {}
            wind = current.get("wind_speed_10m")
            precip = current.get("precipitation")
            disrupted = (wind is not None and wind >= 50) or (precip is not None and precip >= 10)
            if disrupted:
                alerts.append({"route_label": w.route_label, "lat": w.lat, "lon": w.lon,
                                "wind_speed_10m": wind, "precipitation": precip,
                                "message": "Elevated wind or precipitation reported at this waypoint."})
        except Exception as e:
            logging.error(f"[WEATHER DISRUPTION CHECK] {e}")
    return jsonify({"ok": True, "alerts": alerts, "watches_checked": len(watches)}), 200


