# STAGE 409: SPARE-PARTS MARKETPLACE
# Reuses the existing Product model rather than a parallel catalog —
# a spare part is a real Product row flagged is_spare_part and linked
# to the equipment it belongs to via parent_product_id, so it shows
# up in normal search/checkout as well as a dedicated parts channel.
# New columns, auto-migrated on startup (or run once on production
# MySQL):
#   ALTER TABLE products ADD COLUMN is_spare_part BOOLEAN DEFAULT FALSE;
#   ALTER TABLE products ADD COLUMN parent_product_id INTEGER NULL;
# ════════════════════════════════════════════════════════════

@app.route("/api/spare-parts", methods=["POST"])
@csrf.exempt
def spare_part_create():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    parent = Product.query.get(data.get("parent_product_id"))
    if not parent:
        return jsonify({"error": "parent_product_id must reference an existing product."}), 400
    name = (data.get("name") or "").strip()[:200]
    if not name or not data.get("price"):
        return jsonify({"error": "name and price are required."}), 400
    part = Product(
        seller_id=user["id"], name=name, description=(data.get("description") or "").strip()[:2000],
        price=float(data["price"]), quantity_available=data.get("quantity_available", 1),
        image_url=(data.get("image_url") or "").strip() or None, is_active=True,
        is_spare_part=True, parent_product_id=parent.id,
    )
    db.session.add(part)
    db.session.commit()
    return jsonify({"ok": True, "spare_part": part.to_dict()}), 201


