# ════════════════════════════════════════════════════════════
# STAGE 415: CIRCULAR ECONOMY RESALE/RETURNS MARKETPLACE
# Reuses the existing Product model rather than a parallel catalog —
# same pattern as the Spare-Parts channel right above (Stage 409). A
# refurbished/returned/open-box item is a real Product row with
# condition set to one of CIRCULAR_CONDITIONS and a mandatory
# condition_notes disclosure (enforced in product_create/
# product_update above), so it shows up in ordinary search as well as
# this dedicated channel — never a second, hidden catalog. Optionally
# links back to the real ProductOrder it was returned from via
# returned_from_order_id (validated to belong to this seller).
# ════════════════════════════════════════════════════════════

@app.route("/api/circular-marketplace/products", methods=["GET"])
def circular_marketplace_products():
    """Public browse for the dedicated refurbished/returned/open-box
    channel. Same filter shape as /api/products (category, q, price
    range, country) narrowed to CIRCULAR_CONDITIONS, plus an optional
    condition= filter to pick one of the three specifically."""
    user = _get_current_user()
    q = Product.query.filter(Product.is_active.is_(True), Product.condition.in_(CIRCULAR_CONDITIONS))

    condition = (request.args.get("condition") or "").strip().lower()
    if condition in CIRCULAR_CONDITIONS:
        q = q.filter(Product.condition == condition)
    category = (request.args.get("category") or "").strip()
    if category:
        q = q.filter(Product.category == category)
    keyword = (request.args.get("q") or "").strip()
    if keyword:
        like = f"%{keyword}%"
        q = q.filter(db.or_(Product.name.ilike(like), Product.description.ilike(like)))
    try:
        max_price = request.args.get("max_price")
        if max_price is not None and max_price != "":
            q = q.filter(Product.price <= float(max_price))
    except (TypeError, ValueError):
        pass
    country_code = (request.args.get("country_code") or "").strip().upper()
    if country_code:
        q = q.filter(Product.country_code == country_code)

    rows = q.order_by(Product.created_at.desc()).limit(200).all()
    viewer_id = user["id"] if user else None
    counts_by_condition = {
        c: Product.query.filter(Product.is_active.is_(True), Product.condition == c).count()
        for c in CIRCULAR_CONDITIONS
    }
    return jsonify({
        "products": [r.to_dict(viewer_id=viewer_id) for r in rows],
        "categories": PRODUCT_CATEGORIES,
        "conditions": [{"key": c, "label": PRODUCT_CONDITION_LABELS[c], "count": counts_by_condition[c]} for c in CIRCULAR_CONDITIONS],
    }), 200


@app.route("/api/products/<int:product_id>/relist-as-return", methods=["POST"])
@csrf.exempt
def product_relist_as_return(product_id):
    """Convenience action for a seller who already has an original
    listing and just wants a fresh condition-tagged copy for an item
    that came back to them on a real order. Doesn't touch the
    original listing at all — creates a new Product row so the
    original 'new' listing keeps selling at its own price/quantity."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    original = Product.query.get(product_id)
    if not original or original.seller_id != user["id"]:
        return jsonify({"error": "Product not found or not yours."}), 404
    data = request.get_json(silent=True) or {}
    condition = (data.get("condition") or "").strip().lower()
    if condition not in CIRCULAR_CONDITIONS:
        return jsonify({"error": f"condition must be one of {', '.join(CIRCULAR_CONDITIONS)}."}), 400
    condition_notes = (data.get("condition_notes") or "").strip()[:1000]
    if not condition_notes:
        return jsonify({"error": "condition_notes is required — describe what's refurbished, worn, or damaged."}), 400
    returned_from_order_id = None
    if data.get("returned_from_order_id") not in (None, ""):
        return_order = ProductOrder.query.get(data.get("returned_from_order_id"))
        if not return_order or return_order.seller_id != user["id"]:
            return jsonify({"error": "returned_from_order_id must reference a real order you sold."}), 400
        returned_from_order_id = return_order.id
    try:
        price = float(data.get("price", original.price))
    except (TypeError, ValueError):
        price = original.price
    relisted = Product(
        seller_id=user["id"], name=original.name, description=original.description,
        category=original.category, price=max(0.0, price), currency=original.currency,
        quantity_available=max(0, int(data.get("quantity_available", 1))),
        unit=original.unit, city=original.city, country_code=original.country_code,
        hs_code=original.hs_code, country_of_origin=original.country_of_origin,
        weight_kg_per_unit=original.weight_kg_per_unit,
        image_urls=original.image_urls, is_active=True,
        condition=condition, condition_notes=condition_notes,
        returned_from_order_id=returned_from_order_id,
    )
    db.session.add(relisted)
    db.session.commit()
    meilisearch_index_product(relisted)
    return jsonify({"ok": True, "product": relisted.to_dict(viewer_id=user["id"])}), 201


