    if keyword:
        like = f"%{keyword}%"
        q = q.filter(db.or_(Product.name.ilike(like), Product.description.ilike(like)))
    try:
        max_price = request.args.get("max_price")
        if max_price is not None and max_price != "":
            q = q.filter(Product.price <= float(max_price))
    except (TypeError, ValueError):
        pass
    country_code = (request.args.get("country_code") or "").strip().upper()
    if country_code:
        q = q.filter(Product.country_code == country_code)

    rows = q.order_by(Product.created_at.desc()).limit(200).all()
