    data = request.get_json(silent=True) or {}
    order = ProductOrder.query.filter_by(id=data.get("order_id"), seller_id=user["id"]).first()
    if not order:
        return jsonify({"error": "Order not found."}), 404
    carrier_name = (data.get("carrier_name") or "").strip()[:160]
    if not carrier_name:
        return jsonify({"error": "carrier_name is required."}), 400
    link = LastMileDeliveryLink(
        order_id=order.id, carrier_name=carrier_name,
        tracking_reference=(data.get("tracking_reference") or "").strip()[:120] or None,
        tracking_url=(data.get("tracking_url") or "").strip()[:500] or None,
        status=(data.get("status") or "").strip()[:60] or None,
    )
    db.session.add(link)
    db.session.commit()
    return jsonify({"ok": True, "link": link.to_dict()}), 201


