# ════════════════════════════════════════════════════════════
# STAGE 413: DYNAMIC TARIFF-ROUTING ADVISOR
# Builds on the existing Stage 135 USITC HTS integration
# (hs_code_lookup) rather than a second tariff data source. Given a
# product description, it pulls every real classifiable tariff line
# USITC returns and ranks them by lowest real duty rate, so a seller
# can see which legally-applicable classification carries the least
# duty. Advisory only — the response tells the seller to confirm the
# final classification with a licensed customs broker.
# ════════════════════════════════════════════════════════════

@app.route("/api/logistics/tariff-routing-advisor", methods=["POST"])
@csrf.exempt
def tariff_routing_advisor():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    query = (data.get("product_query") or "").strip()
    if not query:
        return jsonify({"error": "product_query is required."}), 400

    candidates = []
    error = None
    try:
        resp = requests.get(USITC_HTS_SEARCH, params={"keyword": query}, timeout=12)
        if resp.ok:
            raw = resp.json() if resp.text.strip() else []
            for r in raw:
                general = r.get("general")
                if general in (None, ""):
                    continue
                match = re.search(r"[\d.]+", str(general))
                duty_pct = float(match.group()) if match else None
                candidates.append({
                    "hts_number": r.get("htsno"), "description": r.get("description"),
                    "general_duty": general, "duty_pct_parsed": duty_pct,
                })
        else:
            error = f"USITC HTS API returned status {resp.status_code}"
    except Exception as e:
        logging.error(f"[TARIFF ROUTING ADVISOR] {e}")
        error = "Could not reach the USITC tariff database right now."

    ranked = sorted([c for c in candidates if c["duty_pct_parsed"] is not None], key=lambda c: c["duty_pct_parsed"])
    unranked = [c for c in candidates if c["duty_pct_parsed"] is None]

    return jsonify({
        "ok": True, "product_query": query, "ranked_by_lowest_duty": ranked[:10], "other_matches": unranked[:5],
        "error": error,
        "note": "Advisory only, based on real USITC tariff-line data. Confirm the final HS classification with "
                "a licensed customs broker before filing — misclassification carries legal risk.",
    }), 200


# ════════════════════════════════════════════════════════════
# STAGE 414: AUTOMATIC INCOTERMS SUGGESTION ENGINE
# Deterministic rule-based recommendation following Incoterms 2020,
# based on who actually arranges freight/insurance, the shipping
# mode, and the buyer's experience level. No external call — this is
# a real, documented rules engine, not a model guess.
# ════════════════════════════════════════════════════════════

def _incoterms_suggest(freight_by, insurance_by, mode, buyer_experience):
    mode = (mode or "").strip().lower()
    freight_by = (freight_by or "").strip().lower()
    insurance_by = (insurance_by or "").strip().lower()
    buyer_experience = (buyer_experience or "").strip().lower()
    sea_or_inland_waterway_only = mode in ("sea", "inland_waterway")

    if freight_by == "buyer" and insurance_by == "buyer":
        term = "FCA" if not sea_or_inland_waterway_only else "FOB"
        reason = ("The buyer arranges freight and insurance. FOB (sea/inland waterway only) or FCA (any mode) "
                   "hands over risk once goods are delivered to the carrier, matching that split of responsibility.")
    elif freight_by == "seller" and insurance_by == "seller":
        if buyer_experience == "new":
            term = "DDP"
            reason = ("The seller arranges freight and insurance, and the buyer is new to import processes. DDP "
                       "puts the full delivery and import-clearance burden on the seller, which is the least "
                       "risky option for a first-time buyer.")
        else:
            term = "CIF" if sea_or_inland_waterway_only else "CIP"
            reason = ("The seller arranges freight and insurance for an experienced buyer. CIF (sea/inland "
                       "waterway) or CIP (any mode) covers freight and minimum insurance to the destination port "
                       "or place, while risk still transfers at origin.")
    elif freight_by == "seller" and insurance_by == "buyer":
        term = "CFR" if sea_or_inland_waterway_only else "CPT"
        reason = ("The seller arranges freight but the buyer handles their own insurance. CFR (sea/inland "
                   "waterway) or CPT (any mode) covers freight to destination without bundling insurance.")
    else:
        term = "EXW"
        reason = ("Neither freight nor insurance responsibility was clearly assigned to either party. EXW is the "
                   "default fallback where the seller's only obligation is making goods available at their own "
                   "premises — everything else should be negotiated explicitly from there.")

    return term, reason


@app.route("/api/logistics/incoterms-suggestion", methods=["POST"])
@csrf.exempt
def incoterms_suggestion():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    mode = (data.get("mode") or "").strip().lower()
    if mode not in ("sea", "air", "road", "rail", "multimodal", "inland_waterway"):
        return jsonify({"error": "mode must be one of: sea, air, road, rail, multimodal, inland_waterway."}), 400
    freight_by = (data.get("freight_arranged_by") or "").strip().lower()
    insurance_by = (data.get("insurance_arranged_by") or "").strip().lower()
    if freight_by not in ("buyer", "seller") or insurance_by not in ("buyer", "seller"):
        return jsonify({"error": "freight_arranged_by and insurance_arranged_by must each be 'buyer' or 'seller'."}), 400
    term, reason = _incoterms_suggest(freight_by, insurance_by, mode, data.get("buyer_experience"))
    return jsonify({"ok": True, "suggested_incoterm": term, "reasoning": reason,
                     "note": "Based on Incoterms 2020 rules. This is a starting recommendation, not legal advice — "
                             "confirm the final term in the sales contract."}), 200



# ════════════════════════════════════════════════════════════
# STAGE 417: VERIFIED CARBON REGISTRY CREDITS
# Distinct from Stage 228's platform-internal, self-attested carbon
# credit marketplace: every batch here is admin-onboarded from a real
# credit registry (Verra, Gold Standard, Puro.earth) with the
# registry's own serial number range and public verification link, so
# a buyer can check authenticity on the registry's own site rather
# than trusting a self-attested figure. Offered as a checkout add-on:
# a buyer retires real, registry-tracked tonnes alongside a product
# order.
# ════════════════════════════════════════════════════════════

REGISTRY_CREDIT_REGISTRIES = ("verra", "gold_standard", "puro_earth", "american_carbon_registry", "acr_plastic", "verra_plastic", "plastic_bank", "reclaim_registry")

VERIFIED_REGISTRY_CREDIT_DISCLAIMER = (
    "These offset/credit batches are admin-onboarded from a named external registry using that "
    "registry's own serial numbers. Verify authenticity directly on the registry's own public "
    "lookup page before relying on a retirement for compliance purposes -- this platform resells "
    "access to a real registry entry, it does not operate the registry."
)


class VerifiedRegistryCreditBatch(db.Model):
    __tablename__       = "verified_registry_credit_batches"
    id                  = db.Column(db.Integer, primary_key=True)
    credit_type         = db.Column(db.String(16), nullable=False, index=True)  # carbon, plastic
    registry_name       = db.Column(db.String(80), nullable=False)  # one of REGISTRY_CREDIT_REGISTRIES
    project_name        = db.Column(db.String(200), nullable=False)
    project_country     = db.Column(db.String(80), nullable=True)
    serial_number_range = db.Column(db.String(200), nullable=False)
    registry_url        = db.Column(db.String(400), nullable=False)  # real public lookup page
    unit_label          = db.Column(db.String(40), nullable=False, default="tonne_co2e")  # tonne_co2e, kg_plastic
    price_per_unit      = db.Column(db.Float, nullable=False)
    currency            = db.Column(db.String(6), nullable=False, default="USD")
    units_available     = db.Column(db.Float, nullable=False, default=0.0)
    active              = db.Column(db.Boolean, default=True, nullable=False)
    created_at          = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        return {"id": self.id, "credit_type": self.credit_type, "registry_name": self.registry_name,
                "project_name": self.project_name, "project_country": self.project_country,
                "serial_number_range": self.serial_number_range, "registry_url": self.registry_url,
                "unit_label": self.unit_label, "price_per_unit": self.price_per_unit,
                "currency": self.currency, "units_available": self.units_available,
                "disclaimer": VERIFIED_REGISTRY_CREDIT_DISCLAIMER}


class VerifiedRegistryCreditOrder(db.Model):
    __tablename__     = "verified_registry_credit_orders"
    id                = db.Column(db.Integer, primary_key=True)
    batch_id          = db.Column(db.Integer, db.ForeignKey("verified_registry_credit_batches.id"), nullable=False, index=True)
    buyer_id          = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    product_order_id  = db.Column(db.Integer, db.ForeignKey("product_orders.id"), nullable=True)
    units             = db.Column(db.Float, nullable=False)
    total_price       = db.Column(db.Float, nullable=False)
    currency          = db.Column(db.String(6), nullable=False, default="USD")
    retired_serials   = db.Column(db.String(300), nullable=True)
    status            = db.Column(db.String(20), nullable=False, default="retired")  # retired, refunded
    created_at        = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        batch = VerifiedRegistryCreditBatch.query.get(self.batch_id)
        return {"id": self.id, "batch": batch.to_dict() if batch else None,
                "product_order_id": self.product_order_id, "units": self.units,
                "total_price": self.total_price, "currency": self.currency,
                "retired_serials": self.retired_serials, "status": self.status,
                "created_at": self.created_at.isoformat() if self.created_at else None}


