# ════════════════════════════════════════════════════════════
# STAGE 425: DIGITAL TWIN OF A SELLER'S SUPPLY CHAIN
# Computed live from this seller's own real data already on the
# platform — their ERP suppliers and open purchase orders, bonded
# warehouse bookings, and freight shipments — rather than a modeled
# fiction. No new data source is invented; this endpoint is a graph
# view over rows that already exist elsewhere in this file.
# ════════════════════════════════════════════════════════════

@app.route("/api/supply-chain-twin/<int:seller_id>", methods=["GET"])
def supply_chain_twin(seller_id):
    user = _get_current_user()
    if not user or user["id"] != seller_id:
        return jsonify({"error": "You can only view your own supply chain twin."}), 403

    nodes = [{"id": f"seller-{seller_id}", "type": "seller", "label": "You"}]
    edges = []

    suppliers = ErpSupplier.query.filter_by(owner_user_id=seller_id, active=True).all()
    for s in suppliers:
        node_id = f"supplier-{s.id}"
        open_pos = ErpPurchaseOrder.query.filter(
            ErpPurchaseOrder.owner_user_id == seller_id, ErpPurchaseOrder.supplier_id == s.id,
            ErpPurchaseOrder.status.in_(["draft", "ordered"])).count()
        nodes.append({"id": node_id, "type": "supplier", "label": s.name, "open_purchase_orders": open_pos})
        edges.append({"from": f"seller-{seller_id}", "to": node_id, "relationship": "sources_from"})

    warehouses = BondedWarehouseBooking.query.filter_by(seller_id=seller_id).all()
    for wbk in warehouses:
        node_id = f"warehouse-{wbk.id}"
        nodes.append({"id": node_id, "type": "warehouse", "label": f"Bonded warehouse booking #{wbk.id}",
                       "status": getattr(wbk, "status", None)})
        edges.append({"from": f"seller-{seller_id}", "to": node_id, "relationship": "stores_via"})

    shipments = FreightShipment.query.filter_by(seller_id=seller_id).order_by(FreightShipment.created_at.desc()).limit(20).all()
    for sh in shipments:
        node_id = f"shipment-{sh.id}"
        nodes.append({"id": node_id, "type": "shipment", "label": f"{sh.mode.upper()} {sh.origin} → {sh.destination}",
                       "status": sh.status, "carrier": sh.carrier_name})
        edges.append({"from": f"seller-{seller_id}", "to": node_id, "relationship": "ships_via"})

    return jsonify({"ok": True, "generated_at": datetime.utcnow().isoformat(),
                     "nodes": nodes, "edges": edges,
                     "summary": {"suppliers": len(suppliers), "active_shipments": len(shipments)}}), 200


# ════════════════════════════════════════════════════════════
# STAGE 426: PREDICTIVE MAINTENANCE ALERTS
# For buyers who purchased industrial equipment through a real
# ProductOrder on this platform. The buyer (or the seller, on the
# buyer's behalf) registers the equipment with an install date and a
# maintenance interval; this computes due dates from that real data —
# no invented sensor telemetry.
# ════════════════════════════════════════════════════════════

class EquipmentMaintenanceRecord(db.Model):
    __tablename__       = "equipment_maintenance_records"
    id                  = db.Column(db.Integer, primary_key=True)
    order_id            = db.Column(db.Integer, db.ForeignKey("product_orders.id"), nullable=False, index=True)
    owner_user_id       = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    equipment_name       = db.Column(db.String(160), nullable=False)
    install_date         = db.Column(db.Date, nullable=False)
    maintenance_interval_days = db.Column(db.Integer, nullable=False, default=180)
    last_serviced_date   = db.Column(db.Date, nullable=True)
    created_at            = db.Column(db.DateTime, default=datetime.utcnow)

    def next_due(self):
        base = self.last_serviced_date or self.install_date
        return base + timedelta(days=self.maintenance_interval_days)

    def to_dict(self):
        due = self.next_due()
        days_until = (due - date.today()).days
        return {"id": self.id, "order_id": self.order_id, "equipment_name": self.equipment_name,
                "install_date": self.install_date.isoformat(), "maintenance_interval_days": self.maintenance_interval_days,
                "last_serviced_date": self.last_serviced_date.isoformat() if self.last_serviced_date else None,
                "next_due": due.isoformat(), "days_until_due": days_until,
                "status": "overdue" if days_until < 0 else ("due_soon" if days_until <= 14 else "ok")}


@app.route("/api/predictive-maintenance/equipment", methods=["POST"])
@csrf.exempt
def predictive_maintenance_register():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    order = ProductOrder.query.get(data.get("order_id"))
    if not order or order.buyer_id != user["id"]:
        return jsonify({"error": "You can only register equipment against your own order."}), 400
    try:
        install_date = datetime.fromisoformat(data.get("install_date")).date()
    except (ValueError, TypeError):
        return jsonify({"error": "install_date must be a valid ISO date (YYYY-MM-DD)."}), 400
    interval = int(data.get("maintenance_interval_days") or 180)
    record = EquipmentMaintenanceRecord(
        order_id=order.id, owner_user_id=user["id"],
        equipment_name=(data.get("equipment_name") or "").strip()[:160] or "Unnamed equipment",
        install_date=install_date, maintenance_interval_days=max(1, interval),
    )
    db.session.add(record)
    db.session.commit()
    return jsonify({"ok": True, "equipment": record.to_dict()}), 201


