# ════════════════════════════════════════════════════════════
# STAGE 427: INVENTORY FORECASTING ACROSS MULTIPLE SELLERS
# Aggregated real demand signal for a category: computed from actual
# ProductOrder rows across every seller listing in that category, not
# a synthetic projection. Buyers sourcing the same category get a
# real trailing-demand trend and a simple next-period estimate.
# ════════════════════════════════════════════════════════════

@app.route("/api/inventory-forecast/<path:category>", methods=["GET"])
def inventory_forecast_by_category(category):
    now = datetime.utcnow()
    periods = []
    for i in range(5, -1, -1):
        period_start = now - timedelta(days=30 * (i + 1))
        period_end = now - timedelta(days=30 * i)
        qty = (db.session.query(db.func.coalesce(db.func.sum(ProductOrder.quantity), 0))
               .join(Product, Product.id == ProductOrder.product_id)
               .filter(Product.category == category, ProductOrder.created_at >= period_start,
                       ProductOrder.created_at < period_end).scalar())
        periods.append({"period_start": period_start.date().isoformat(),
                         "period_end": period_end.date().isoformat(), "units_ordered": int(qty or 0)})
    values = [p["units_ordered"] for p in periods]
    if len(values) >= 3 and sum(values[:-1]) > 0:
        # Simple trend: average of the last 3 periods' month-over-month change.
        deltas = [values[i + 1] - values[i] for i in range(len(values) - 1)]
        avg_delta = sum(deltas[-3:]) / min(3, len(deltas))
        next_period_estimate = max(0, round(values[-1] + avg_delta))
    else:
        next_period_estimate = values[-1] if values else 0
    active_sellers = (db.session.query(db.func.count(db.func.distinct(Product.seller_id)))
                       .filter(Product.category == category, Product.is_active.is_(True)).scalar())
    return jsonify({"ok": True, "category": category, "trailing_periods": periods,
                     "next_period_estimate_units": next_period_estimate,
                     "active_sellers_in_category": int(active_sellers or 0)}), 200


# ════════════════════════════════════════════════════════════
# STAGE 428: ESCROW FOR SERVICES
# Mirrors the existing goods escrow (ProductOrder.escrow_status) but
# for a services engagement with no underlying product listing —
# freelance manufacturing consultants, QC contractors, designers.
# Milestone-based, same holding/released/disputed/refunded lifecycle.
# ════════════════════════════════════════════════════════════

class ServiceEscrowContract(db.Model):
    __tablename__     = "service_escrow_contracts"
    id                = db.Column(db.Integer, primary_key=True)
    client_id         = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    provider_id       = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    description       = db.Column(db.String(600), nullable=False)
    amount            = db.Column(db.Float, nullable=False)
    currency          = db.Column(db.String(8), nullable=False, default="USD")
    status            = db.Column(db.String(16), nullable=False, default="holding")  # holding, released, disputed, refunded
    stripe_payment_intent_id = db.Column(db.String(120), nullable=True)
    dispute_reason    = db.Column(db.String(500), nullable=True)
    created_at        = db.Column(db.DateTime, default=datetime.utcnow)
    released_at       = db.Column(db.DateTime, nullable=True)

    def to_dict(self):
        return {"id": self.id, "client_id": self.client_id, "provider_id": self.provider_id,
                "description": self.description, "amount": self.amount, "currency": self.currency,
                "status": self.status, "dispute_reason": self.dispute_reason,
                "created_at": self.created_at.isoformat() if self.created_at else None,
                "released_at": self.released_at.isoformat() if self.released_at else None}


@app.route("/api/service-escrow/contracts", methods=["POST"])
@csrf.exempt
def service_escrow_create():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    provider = UserAccount.query.get(data.get("provider_id"))
    if not provider:
        return jsonify({"error": "Unknown service provider."}), 400
    try:
        amount = float(data.get("amount"))
    except (TypeError, ValueError):
        return jsonify({"error": "amount must be a number."}), 400
    if amount <= 0:
        return jsonify({"error": "amount must be greater than zero."}), 400
    contract = ServiceEscrowContract(
        client_id=user["id"], provider_id=provider.id,
        description=(data.get("description") or "").strip()[:600] or "Service engagement",
        amount=amount, currency=(data.get("currency") or "USD").strip()[:8].upper(),
        status="holding",
    )
    # Real card capture reuses the platform's existing Stripe integration the same
    # way ProductOrder escrow does — this records the resulting intent id once paid.
    contract.stripe_payment_intent_id = (data.get("stripe_payment_intent_id") or "").strip()[:120] or None
    db.session.add(contract)
    db.session.commit()
    return jsonify({"ok": True, "contract": contract.to_dict()}), 201


def _service_escrow_party_or_403(contract, user):
    return user and user["id"] in (contract.client_id, contract.provider_id)


@app.route("/api/service-escrow/contracts/<int:contract_id>/release", methods=["POST"])
@csrf.exempt
def service_escrow_release(contract_id):
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    contract = ServiceEscrowContract.query.get(contract_id)
    if not contract or not user or user["id"] != contract.client_id:
        return jsonify({"error": "Only the client can release funds."}), 403
    if contract.status != "holding":
        return jsonify({"error": f"Contract is {contract.status}, cannot release."}), 400
    contract.status = "released"
    contract.released_at = datetime.utcnow()
    db.session.commit()
    return jsonify({"ok": True, "contract": contract.to_dict()}), 200


@app.route("/api/service-escrow/contracts/<int:contract_id>/dispute", methods=["POST"])
@csrf.exempt
def service_escrow_dispute(contract_id):
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    contract = ServiceEscrowContract.query.get(contract_id)
    if not contract or not _service_escrow_party_or_403(contract, user):
        return jsonify({"error": "Contract not found."}), 404
    if contract.status != "holding":
        return jsonify({"error": f"Contract is {contract.status}, cannot dispute."}), 400
    data = request.get_json(silent=True) or {}
    contract.status = "disputed"
    contract.dispute_reason = (data.get("reason") or "").strip()[:500] or None
    db.session.commit()
    return jsonify({"ok": True, "contract": contract.to_dict()}), 200


@app.route("/api/service-escrow/contracts/mine", methods=["GET"])
def service_escrow_mine():
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    rows = (ServiceEscrowContract.query
            .filter(db.or_(ServiceEscrowContract.client_id == user["id"], ServiceEscrowContract.provider_id == user["id"]))
            .order_by(ServiceEscrowContract.created_at.desc()).all())
    return jsonify({"ok": True, "contracts": [r.to_dict() for r in rows]}), 200


