    booking = InterpreterBooking(
        requested_by_id=user["id"], provider_id=provider.id,
        language_pair=(data.get("language_pair") or "").strip()[:80] or None,
        scheduled_for=scheduled_for, notes=(data.get("notes") or "").strip()[:500] or None,
    )
    db.session.add(booking)
    db.session.commit()
    return jsonify({"ok": True, "booking": booking.to_dict()}), 201


