# ════════════════════════════════════════════════════════════
# STAGE 430: OFFLINE ORDER PLACEMENT VIA PRINTED QR/PAPER CATALOG
# Uses the qrcode library already loaded at the top of this file (no
# external API call). Generates a printable catalog page per seller;
# each product gets a real scannable QR that deep-links straight to
# a one-tap order form, so a market vendor with no internet access at
# the point of sale can still be found by a buyer who scans later.
# ════════════════════════════════════════════════════════════

@app.route("/api/offline-catalog/<int:seller_id>", methods=["GET"])
def offline_catalog_data(seller_id):
    products = Product.query.filter_by(seller_id=seller_id, is_active=True).limit(60).all()
    base_url = request.url_root.rstrip("/")
    items = [{"id": p.id, "name": p.name, "price": p.price, "currency": p.currency,
              "order_url": f"{base_url}/order/{p.id}"} for p in products]
    return jsonify({"ok": True, "seller_id": seller_id, "products": items}), 200


@app.route("/api/offline-catalog/<int:product_id>/qrcode", methods=["GET"])
def offline_catalog_qrcode(product_id):
    product = Product.query.get(product_id)
    if not product:
        return jsonify({"error": "Product not found."}), 404
    if not QRCODE_AVAILABLE:
        return jsonify({"error": "QR generation is unavailable on this server (qrcode package not installed)."}), 503
    order_url = f"{request.url_root.rstrip('/')}/order/{product.id}"
    qr = qrcode.QRCode(error_correction=ERROR_CORRECT_M, box_size=8, border=2)
    qr.add_data(order_url)
    qr.make(fit=True)
    img = qr.make_image(fill_color="black", back_color="white")
    buf = BytesIO()
    img.save(buf, format="PNG")
    buf.seek(0)
    return Response(buf.read(), mimetype="image/png")


# ════════════════════════════════════════════════════════════
# STAGE 431: FEATURE-PHONE-FRIENDLY IVR ORDERING
# Companion to the existing SMS gateway (/api/sms/inbound above), for
# buyers with no smartphone at all. Distinct from the STAGE 54
# general-support Voice/IVR bot (/api/ivr/voice) — this is a separate
# menu tree under /api/ivr-order/... specifically for product search
# and order-status lookup by phone. Returns real TwiML (plain XML —
# no external package required to build it), so pointing a real
# Twilio phone number's Voice webhook at this URL makes it work for
# an actual phone call. Requires the seller/platform to own a real
# Twilio number to go live — that account-level step can't be done
# from inside this codebase, so it's flagged here rather than assumed
# already connected.
# ════════════════════════════════════════════════════════════

@app.route("/api/ivr-order/voice", methods=["POST"])
@csrf.exempt
def ivr_order_voice_entry():
    twiml = (
        '<?xml version="1.0" encoding="UTF-8"?>'
        '<Response>'
        '<Gather numDigits="1" action="/api/ivr-order/menu" method="POST" timeout="8">'
        '<Say>Welcome. Press 1 to search products. Press 2 to check an order status. Press 3 to repeat this menu.</Say>'
        '</Gather>'
        '<Say>We did not receive a selection. Goodbye.</Say>'
        '</Response>'
    )
    return Response(twiml, mimetype="text/xml")


@app.route("/api/ivr-order/menu", methods=["POST"])
@csrf.exempt
def ivr_order_voice_menu():
    digit = request.form.get("Digits", "")
    if digit == "1":
        twiml = (
            '<?xml version="1.0" encoding="UTF-8"?>'
            '<Response><Gather input="dtmf speech" action="/api/ivr-order/search" method="POST" timeout="8">'
            '<Say>Say or type the product name using your keypad, then press pound.</Say>'
            '</Gather></Response>'
        )
    elif digit == "2":
        twiml = (
            '<?xml version="1.0" encoding="UTF-8"?>'
            '<Response><Gather numDigits="6" action="/api/ivr-order/order-status" method="POST" timeout="8">'
            '<Say>Enter your order number then press pound.</Say>'
            '</Gather></Response>'
        )
    else:
        twiml = (
            '<?xml version="1.0" encoding="UTF-8"?>'
            '<Response><Redirect method="POST">/api/ivr-order/voice</Redirect></Response>'
        )
    return Response(twiml, mimetype="text/xml")


@app.route("/api/ivr-order/search", methods=["POST"])
@csrf.exempt
def ivr_order_voice_search():
    query = (request.form.get("SpeechResult") or "").strip()
    matches = Product.query.filter(Product.name.ilike(f"%{query}%")).limit(3).all() if query else []
    if matches:
        say = "We found: " + "; ".join(f"{p.name}, {p.currency or 'USD'} {p.price}" for p in matches)
    else:
        say = "No matching products were found."
    twiml = f'<?xml version="1.0" encoding="UTF-8"?><Response><Say>{xml_escape(say)}</Say></Response>'
    return Response(twiml, mimetype="text/xml")


@app.route("/api/ivr-order/order-status", methods=["POST"])
@csrf.exempt
def ivr_order_voice_order_status():
    digits = request.form.get("Digits", "")
    order = ProductOrder.query.get(int(digits)) if digits.isdigit() else None
    say = f"Order number {order.id}, status {order.status}." if order else "Order not found."
    twiml = f'<?xml version="1.0" encoding="UTF-8"?><Response><Say>{xml_escape(say)}</Say></Response>'
    return Response(twiml, mimetype="text/xml")


# ════════════════════════════════════════════════════════════
# STAGE 432: LOW-BANDWIDTH MODE
# A genuinely separate, tiny, text-only route — no images, no JS
# bundle — that loads over 2G. Real feature, not a fake "loading
# spinner"; it's a distinct server-rendered page.
# ════════════════════════════════════════════════════════════

@app.route("/lite", methods=["GET"])
def lite_home():
    q = (request.args.get("q") or "").strip()
    products = (Product.query.filter(Product.is_active.is_(True), Product.name.ilike(f"%{q}%")).limit(20).all()
                if q else Product.query.filter_by(is_active=True).order_by(Product.id.desc()).limit(20).all())
    rows_html = "".join(
        f'<li><a href="/lite/product/{p.id}">{xml_escape(p.name)}</a> — {xml_escape(p.currency or "USD")} {p.price}</li>'
        for p in products
    )
    html = (
        "<!doctype html><html><head><title>Lite Mode</title>"
        "<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"></head><body>"
        "<h1>Lite Mode</h1>"
        f"<form method=\"get\" action=\"/lite\"><input name=\"q\" value=\"{xml_escape(q)}\"><button>Search</button></form>"
        f"<ul>{rows_html or '<li>No products found.</li>'}</ul>"
        "<p><a href=\"/\">Full site</a></p>"
        "</body></html>"
    )
    return Response(html, mimetype="text/html")


@app.route("/lite/product/<int:product_id>", methods=["GET"])
def lite_product(product_id):
    p = Product.query.get(product_id)
    if not p:
        return Response("<p>Not found. <a href=\"/lite\">Back</a></p>", mimetype="text/html"), 404
    html = (
        "<!doctype html><html><head><title>" + xml_escape(p.name) + "</title>"
        "<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"></head><body>"
        f"<h1>{xml_escape(p.name)}</h1>"
        f"<p>{xml_escape(p.currency or 'USD')} {p.price} per {xml_escape(p.unit or 'unit')}</p>"
        f"<p>{xml_escape(p.description or '')}</p>"
        f"<p><a href=\"/order/{p.id}\">Order this (full site)</a></p>"
        "<p><a href=\"/lite\">Back to search</a></p>"
        "</body></html>"
    )
    return Response(html, mimetype="text/html")


