    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    provider = CreditLineProvider.query.get(data.get("provider_id"))
    if not provider or not provider.active:
        return jsonify({"error": "Unknown credit line provider."}), 400
    try:
        amount = float(data.get("requested_amount"))
    except (TypeError, ValueError):
        return jsonify({"error": "requested_amount must be a number."}), 400
    if amount <= 0:
        return jsonify({"error": "requested_amount must be greater than zero."}), 400
    application = CreditLineApplication(
        buyer_id=user["id"], provider_id=provider.id, requested_amount=amount,
        currency=(data.get("currency") or "USD").strip()[:8].upper(),
        purpose=(data.get("purpose") or "").strip()[:500] or None,
    )
    db.session.add(application)
    db.session.commit()
    return jsonify({"ok": True, "application": application.to_dict()}), 201


