# ════════════════════════════════════════════════════════════
# STAGE 435: PUBLIC API RATE-LIMITED FREE TIER
# Distinct from the Sandbox API keys above (which only simulate
# orders) and from the AI chat Public API further up (/api/v1/chat)
# — this issues a real API key against real, live platform data
# (products and categories) so an outside developer can prototype an
# integration before any commercial conversation. Free tier is capped
# low and resets daily; a paid tier exists as a column for the future
# but there is no billing wired to it yet, matching the same
# "no billing wired here" scope already noted on DeveloperApp above —
# upgrading today is a manual admin action, not a self-serve checkout.
# ════════════════════════════════════════════════════════════

class PlatformApiKey(db.Model):
    __tablename__     = "platform_api_keys"
    id                = db.Column(db.Integer, primary_key=True)
    user_id           = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    key               = db.Column(db.String(64), unique=True, nullable=False, index=True)
    label             = db.Column(db.String(120), nullable=True)
    tier              = db.Column(db.String(10), nullable=False, default="free")   # free, paid
    requests_per_day  = db.Column(db.Integer, nullable=False, default=200)
    usage_today       = db.Column(db.Integer, nullable=False, default=0)
    usage_date        = db.Column(db.Date, nullable=True)
    active            = db.Column(db.Boolean, nullable=False, default=True)
    created_at        = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        return {"id": self.id, "key": self.key, "label": self.label, "tier": self.tier,
                "requests_per_day": self.requests_per_day, "usage_today": self.usage_today,
                "active": self.active,
                "created_at": self.created_at.isoformat() if self.created_at else None}


def _require_platform_api_key(f):
    @wraps(f)
    def wrapper(*args, **kwargs):
        raw_key = (request.headers.get("X-API-Key") or "").strip()
        if not raw_key:
            return jsonify({"error": "Missing X-API-Key header."}), 401
        record = PlatformApiKey.query.filter_by(key=raw_key, active=True).first()
        if not record:
            return jsonify({"error": "Invalid or revoked API key."}), 401
        today = date.today()
        if record.usage_date != today:
            record.usage_date = today
            record.usage_today = 0
        if record.usage_today >= record.requests_per_day:
            return jsonify({"error": f"Daily limit of {record.requests_per_day} requests reached for "
                                      f"this key's {record.tier} tier."}), 429
        record.usage_today += 1
        try:
            db.session.commit()
        except Exception:
            db.session.rollback()
        request.platform_api_record = record
        return f(*args, **kwargs)
    return wrapper


@app.route("/api/platform-api/keys", methods=["POST"])
@csrf.exempt
def platform_api_key_create():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    existing = PlatformApiKey.query.filter_by(user_id=user["id"], active=True).count()
    if existing >= 5:
        return jsonify({"error": "Limit of 5 active keys per account. Revoke an old one first."}), 400
    data = request.get_json(silent=True) or {}
    row = PlatformApiKey(
        user_id=user["id"], key="pk_" + secrets.token_hex(20),
        label=(data.get("label") or "").strip()[:120] or None,
        tier="free", requests_per_day=200, usage_today=0, usage_date=date.today(),
    )
    db.session.add(row)
    db.session.commit()
    return jsonify({"ok": True, "api_key": row.to_dict()}), 201


