# STAGE 436: MARKETPLACE-AS-A-SERVICE WHITE-LABEL LICENSING
# Distinct from STAGE 154's per-seller storefront branding (one
# business's own look on top of this one marketplace) — this is a
# structured intake for another company that wants to run its own,
# separate marketplace instance on this stack. Actually provisioning a
# new tenant means a real infrastructure step (separate database,
# domain, deploy) outside this codebase, so this stage builds the real
# qualification/intake queue an admin works from, not a self-service
# instance spin-up, exactly as the roadmap notes require for anything
# depending on systems this app cannot fully control.
# ════════════════════════════════════════════════════════════

class WhiteLabelLicenseInquiry(db.Model):
    __tablename__          = "white_label_license_inquiries"
    id                     = db.Column(db.Integer, primary_key=True)
    user_id                = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=True, index=True)
    company_name           = db.Column(db.String(160), nullable=False)
    contact_name           = db.Column(db.String(120), nullable=True)
    contact_email          = db.Column(db.String(200), nullable=False)
    target_region          = db.Column(db.String(120), nullable=True)
    expected_seller_count  = db.Column(db.Integer, nullable=True)
    message                = db.Column(db.Text, nullable=True)
    status                 = db.Column(db.String(20), nullable=False, default="new")  # new, in_review, approved, declined
    created_at             = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        return {"id": self.id, "company_name": self.company_name, "contact_name": self.contact_name,
                "contact_email": self.contact_email, "target_region": self.target_region,
                "expected_seller_count": self.expected_seller_count, "message": self.message,
                "status": self.status,
                "created_at": self.created_at.isoformat() if self.created_at else None}


@app.route("/api/white-label-license/inquiries", methods=["POST"])
@csrf.exempt
def white_label_inquiry_create():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    data = request.get_json(silent=True) or {}
    company_name = (data.get("company_name") or "").strip()[:160]
    contact_email = (data.get("contact_email") or "").strip()[:200]
    if not company_name or not contact_email:
        return jsonify({"error": "company_name and contact_email are required."}), 400
    user = _get_current_user()
    try:
        seller_count = (int(data.get("expected_seller_count"))
                         if data.get("expected_seller_count") not in (None, "") else None)
    except (TypeError, ValueError):
        seller_count = None
    row = WhiteLabelLicenseInquiry(
        user_id=user["id"] if user else None, company_name=company_name,
        contact_name=(data.get("contact_name") or "").strip()[:120] or None,
        contact_email=contact_email, target_region=(data.get("target_region") or "").strip()[:120] or None,
        expected_seller_count=seller_count, message=(data.get("message") or "").strip()[:2000] or None,
    )
    db.session.add(row)
    db.session.commit()
    return jsonify({"ok": True, "inquiry": row.to_dict()}), 201


