@app.route("/api/admin/white-label-license/inquiries/<int:inquiry_id>/status", methods=["POST"])
@csrf.exempt
def white_label_inquiry_status_update(inquiry_id):
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user or not _is_platform_admin(user["id"]):
        return jsonify({"error": "Admin access required."}), 403
    row = WhiteLabelLicenseInquiry.query.get(inquiry_id)
    if not row:
        return jsonify({"error": "Inquiry not found."}), 404
    data = request.get_json(silent=True) or {}
    new_status = (data.get("status") or "").strip()
    if new_status not in ("new", "in_review", "approved", "declined"):
        return jsonify({"error": "Invalid status."}), 400
    row.status = new_status
    db.session.commit()
    return jsonify({"ok": True, "inquiry": row.to_dict()}), 200


# ════════════════════════════════════════════════════════════
# STAGE 437: SELLER DATA PORTABILITY / EXPORT TOOL
# Distinct from /api/privacy/export above, which is an account-level
# GDPR export of profile data plus row *counts* only, by design. This
# is the seller-facing tool: the real, full catalog and order history,
# downloadable in open, non-proprietary formats (CSV and JSON) so a
# seller can move their data to another system at any time.
# ════════════════════════════════════════════════════════════

@app.route("/api/seller-data-export/catalog.csv", methods=["GET"])
def seller_data_export_catalog_csv():
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    rows = Product.query.filter_by(seller_id=user["id"]).order_by(Product.id).all()
    buf = io.StringIO()
    writer = csv.writer(buf)
    writer.writerow(["id", "name", "category", "price", "currency", "quantity_available",
                      "unit", "min_order_quantity", "city", "country_code", "is_active"])
    for p in rows:
        writer.writerow([p.id, p.name, p.category, p.price, p.currency, p.quantity_available,
                          p.unit or "", p.min_order_quantity, p.city or "", p.country_code or "",
                          p.is_active])
    resp = Response(buf.getvalue(), mimetype="text/csv")
    resp.headers["Content-Disposition"] = f"attachment; filename=catalog-export-{user['id']}.csv"
    return resp


@app.route("/api/seller-data-export/orders.csv", methods=["GET"])
def seller_data_export_orders_csv():
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    rows = ProductOrder.query.filter_by(seller_id=user["id"]).order_by(ProductOrder.id).all()
    buf = io.StringIO()
    writer = csv.writer(buf)
    writer.writerow(["id", "product_id", "buyer_id", "quantity", "total_price", "currency",
                      "status", "created_at"])
    for o in rows:
        writer.writerow([o.id, o.product_id, o.buyer_id, o.quantity, o.total_price, o.currency,
                          o.status, o.created_at.isoformat() if o.created_at else ""])
    resp = Response(buf.getvalue(), mimetype="text/csv")
    resp.headers["Content-Disposition"] = f"attachment; filename=orders-export-{user['id']}.csv"
    return resp


@app.route("/api/seller-data-export/full.json", methods=["GET"])
def seller_data_export_full_json():
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    products = Product.query.filter_by(seller_id=user["id"]).order_by(Product.id).all()
    orders = ProductOrder.query.filter_by(seller_id=user["id"]).order_by(ProductOrder.id).all()
    export = {
        "exported_at": datetime.utcnow().isoformat(),
        "seller_id": user["id"],
        "catalog": [{"id": p.id, "name": p.name, "category": p.category, "price": p.price,
                      "currency": p.currency, "quantity_available": p.quantity_available,
                      "unit": p.unit, "min_order_quantity": p.min_order_quantity,
                      "city": p.city, "country_code": p.country_code,
                      "is_active": p.is_active} for p in products],
        "orders": [{"id": o.id, "product_id": o.product_id, "buyer_id": o.buyer_id,
                     "quantity": o.quantity, "total_price": o.total_price, "currency": o.currency,
                     "status": o.status,
                     "created_at": o.created_at.isoformat() if o.created_at else None} for o in orders],
    }
    resp = Response(json.dumps(export, indent=2), mimetype="application/json")
    resp.headers["Content-Disposition"] = f"attachment; filename=full-data-export-{user['id']}.json"
    return resp


# ════════════════════════════════════════════════════════════
# STAGE 438: PLUGIN REVENUE-SHARING PROGRAM
# Builds a real usage ledger and computed revenue share on top of the
# existing DeveloperApp / DeveloperAppInstallation models above (whose
# pricing_note field was explicitly "no billing wired here"). Each
# active install can be logged as a billable usage period at a usage
# fee the developer sets; the developer's share (70%, platform keeps
# the rest) is computed and shown as a running ledger. This stage
# stops at the ledger — actually moving money to a developer's bank
# account still requires wiring a real payout rail (e.g. this
# platform's existing Stripe Connect integration used elsewhere for
# seller payouts), a separate settlement step, not simulated here.
# ════════════════════════════════════════════════════════════

DEVELOPER_REVENUE_SHARE_PCT = 0.70


class DeveloperAppRevenueEvent(db.Model):
    __tablename__   = "developer_app_revenue_events"
    id              = db.Column(db.Integer, primary_key=True)
    app_id          = db.Column(db.Integer, db.ForeignKey("developer_apps.id"), nullable=False, index=True)
    seller_id       = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False)
    usage_fee       = db.Column(db.Float, nullable=False)
    developer_share = db.Column(db.Float, nullable=False)
    period_label    = db.Column(db.String(20), nullable=False)   # e.g. "2026-08"
    created_at      = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        return {"id": self.id, "app_id": self.app_id, "seller_id": self.seller_id,
                "usage_fee": self.usage_fee, "developer_share": self.developer_share,
                "period_label": self.period_label,
                "created_at": self.created_at.isoformat() if self.created_at else None}


@app.route("/api/developer-apps/<int:app_id>/log-usage", methods=["POST"])
@csrf.exempt
def developer_app_log_usage(app_id):
    """Logs one billable usage period for one active install of this app.
    Callable by the app's own developer (self-reported, the same trust
    level pricing_note already carried) or a platform admin."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    app_row = DeveloperApp.query.get(app_id)
    if not app_row:
        return jsonify({"error": "App not found."}), 404
    if user["id"] != app_row.developer_id and not _is_platform_admin(user["id"]):
        return jsonify({"error": "Only the app's developer or an admin can log usage."}), 403
    data = request.get_json(silent=True) or {}
    seller_id = data.get("seller_id")
    installation = DeveloperAppInstallation.query.filter_by(
        app_id=app_id, seller_id=seller_id, status="installed").first()
    if not installation:
        return jsonify({"error": "That seller does not have this app installed."}), 400
    try:
        usage_fee = float(data.get("usage_fee"))
    except (TypeError, ValueError):
        return jsonify({"error": "usage_fee must be a number."}), 400
    if usage_fee <= 0:
        return jsonify({"error": "usage_fee must be greater than zero."}), 400
    period_label = (data.get("period_label") or datetime.utcnow().strftime("%Y-%m")).strip()[:20]
    event = DeveloperAppRevenueEvent(
        app_id=app_id, seller_id=seller_id, usage_fee=usage_fee,
        developer_share=round(usage_fee * DEVELOPER_REVENUE_SHARE_PCT, 2), period_label=period_label,
    )
    db.session.add(event)
    db.session.commit()
    return jsonify({"ok": True, "event": event.to_dict()}), 201


@app.route("/api/developer-apps/<int:app_id>/revenue", methods=["GET"])
def developer_app_revenue_summary(app_id):
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    app_row = DeveloperApp.query.get(app_id)
    if not app_row:
        return jsonify({"error": "App not found."}), 404
    if user["id"] != app_row.developer_id and not _is_platform_admin(user["id"]):
        return jsonify({"error": "Only the app's developer or an admin can view this."}), 403
    events = (DeveloperAppRevenueEvent.query.filter_by(app_id=app_id)
              .order_by(DeveloperAppRevenueEvent.created_at.desc()).limit(500).all())
    total_share = sum(e.developer_share for e in events)
    return jsonify({"ok": True, "share_pct": DEVELOPER_REVENUE_SHARE_PCT,
                     "total_developer_share": round(total_share, 2),
                     "events": [e.to_dict() for e in events]}), 200


