@app.route("/components", methods=["GET"])
def component_library_page():
    color_rows = "".join(
        f"<li><span class=\"swatch\" style=\"background:{v}\"></span>"
        f"{xml_escape(k)} &mdash; <code>{xml_escape(v)}</code></li>"
        for k, v in PLATFORM_DESIGN_TOKENS["colors"].items()
    )
    component_rows = "".join(
        f"<li>{xml_escape(k)} &mdash; <code>{xml_escape(v)}</code></li>"
        for k, v in PLATFORM_DESIGN_TOKENS["components"].items()
    )
    spacing_rows = "".join(
        f"<li>{xml_escape(k)} &mdash; <code>{xml_escape(v)}</code></li>"
        for k, v in {**PLATFORM_DESIGN_TOKENS["radii"], **PLATFORM_DESIGN_TOKENS["spacing"]}.items()
    )
    html = (
        "<!doctype html><html><head><title>Connect It Component Library</title>"
        "<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">"
        "<style>body{font-family:-apple-system,'Segoe UI',Arial,sans-serif;max-width:640px;"
        "margin:0 auto;padding:16px;color:#1e293b;}"
        "h1{font-size:1.05rem;}h2{font-size:0.92rem;margin-top:24px;}"
        ".swatch{display:inline-block;width:44px;height:24px;border-radius:6px;"
        "border:1px solid #e5e7eb;vertical-align:middle;margin-right:8px;}"
        "code{background:#f1f5f9;padding:2px 6px;border-radius:4px;font-size:0.78rem;}"
        "ul{padding-left:18px;}li{margin-bottom:8px;font-size:0.84rem;word-break:break-word;}"
        "</style></head><body>"
        "<h1>Connect It &mdash; Open Component Library</h1>"
        "<p style=\"font-size:0.84rem;color:#64748b;\">The design tokens this app uses "
        "internally, published so a partner integration can stay visually consistent. "
        "Also available as JSON at <code>/api/design-system/tokens</code>.</p>"
        f"<h2>Colors</h2><ul>{color_rows}</ul>"
        f"<h2>Buttons and cards</h2><ul>{component_rows}</ul>"
        f"<h2>Spacing and radii</h2><ul>{spacing_rows}</ul>"
        "</body></html>"
    )
    return Response(html, mimetype="text/html")


# ════════════════════════════════════════════════════════════
# STAGE 440: STRUCTURED FEEDBACK / ROADMAP VOTING BOARD
# Real users submit and upvote feature suggestions; an admin moves
# each one through a visible status. One vote per user per suggestion
# is enforced by a database unique constraint, not just a client-side
# check, so it holds even against a scripted client.
# ════════════════════════════════════════════════════════════

class RoadmapSuggestion(db.Model):
    __tablename__    = "roadmap_suggestions"
    id               = db.Column(db.Integer, primary_key=True)
    submitted_by_id  = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    title            = db.Column(db.String(160), nullable=False)
    description      = db.Column(db.Text, nullable=True)
    status           = db.Column(db.String(20), nullable=False, default="submitted")
    # submitted, planned, in_progress, shipped, declined
    vote_count       = db.Column(db.Integer, nullable=False, default=0)
    created_at       = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self, viewer_id=None):
        voted = False
        if viewer_id:
            voted = RoadmapVote.query.filter_by(suggestion_id=self.id, user_id=viewer_id).first() is not None
        return {"id": self.id, "title": self.title, "description": self.description,
                "status": self.status, "vote_count": self.vote_count, "my_vote": voted,
                "created_at": self.created_at.isoformat() if self.created_at else None}


class RoadmapVote(db.Model):
    __tablename__  = "roadmap_votes"
    id             = db.Column(db.Integer, primary_key=True)
    suggestion_id  = db.Column(db.Integer, db.ForeignKey("roadmap_suggestions.id"), nullable=False, index=True)
    user_id        = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    created_at     = db.Column(db.DateTime, default=datetime.utcnow)
    __table_args__ = (db.UniqueConstraint("suggestion_id", "user_id", name="uq_roadmap_vote_once"),)


@app.route("/api/roadmap/suggestions", methods=["GET"])
def roadmap_suggestions_list():
    status_filter = (request.args.get("status") or "").strip()
    q = RoadmapSuggestion.query
    if status_filter:
        q = q.filter_by(status=status_filter)
    rows = q.order_by(RoadmapSuggestion.vote_count.desc(), RoadmapSuggestion.created_at.desc()).limit(200).all()
    user = _get_current_user()
    viewer_id = user["id"] if user else None
    return jsonify({"ok": True, "suggestions": [r.to_dict(viewer_id=viewer_id) for r in rows]}), 200


@app.route("/api/roadmap/suggestions", methods=["POST"])
@csrf.exempt
def roadmap_suggestion_create():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    title = (data.get("title") or "").strip()[:160]
    if not title:
        return jsonify({"error": "title is required."}), 400
    row = RoadmapSuggestion(submitted_by_id=user["id"], title=title,
                             description=(data.get("description") or "").strip()[:2000] or None)
    db.session.add(row)
    db.session.commit()
    return jsonify({"ok": True, "suggestion": row.to_dict(viewer_id=user["id"])}), 201


@app.route("/api/roadmap/suggestions/<int:suggestion_id>/vote", methods=["POST"])
@csrf.exempt
def roadmap_suggestion_vote(suggestion_id):
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    row = RoadmapSuggestion.query.get(suggestion_id)
    if not row:
        return jsonify({"error": "Suggestion not found."}), 404
    if RoadmapVote.query.filter_by(suggestion_id=suggestion_id, user_id=user["id"]).first():
        return jsonify({"error": "You already voted for this suggestion."}), 400
    db.session.add(RoadmapVote(suggestion_id=suggestion_id, user_id=user["id"]))
    row.vote_count += 1
    db.session.commit()
    return jsonify({"ok": True, "suggestion": row.to_dict(viewer_id=user["id"])}), 200


@app.route("/api/roadmap/suggestions/<int:suggestion_id>/unvote", methods=["POST"])
@csrf.exempt
def roadmap_suggestion_unvote(suggestion_id):
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    vote = RoadmapVote.query.filter_by(suggestion_id=suggestion_id, user_id=user["id"]).first()
    if not vote:
        return jsonify({"error": "You have not voted for this suggestion."}), 400
    row = RoadmapSuggestion.query.get(suggestion_id)
    db.session.delete(vote)
    if row and row.vote_count > 0:
        row.vote_count -= 1
    db.session.commit()
    return jsonify({"ok": True}), 200


