# ════════════════════════════════════════════════════════════
# STAGE 447: VERIFIED FACTORY CAPACITY EXCHANGE (REAL-TIME FEED)
# Distinct from the existing Factory Capacity Marketplace UI (listing
# and booking one factory at a time) — this is a real-time queryable
# feed a buyer hits programmatically before sourcing, aggregating
# currently-available capacity across every active listing, and
# separately flagging which sellers are KYC-verified so "verified" in
# the name means something real, not just self-declared.
# ════════════════════════════════════════════════════════════

@app.route("/api/factory-capacity/live-feed", methods=["GET"])
def factory_capacity_live_feed():
    now = datetime.utcnow()
    q = FactoryCapacityListing.query.filter_by(is_active=True).filter(
        db.or_(FactoryCapacityListing.available_to.is_(None), FactoryCapacityListing.available_to >= now))
    country_code = (request.args.get("country_code") or "").strip().upper()
    if country_code:
        q = q.filter(FactoryCapacityListing.country_code == country_code)
    capacity_type = (request.args.get("capacity_type") or "").strip()
    if capacity_type:
        q = q.filter(FactoryCapacityListing.capacity_type == capacity_type)
    rows = q.order_by(FactoryCapacityListing.created_at.desc()).limit(100).all()

    verified_seller_ids = {
        row[0] for row in db.session.query(KYCVerification.owner_id)
        .filter(KYCVerification.owner_id.in_([r.seller_id for r in rows]), KYCVerification.status == "approved").all()
    } if rows else set()

    items = []
    for r in rows:
        d = r.to_dict()
        d["seller_kyc_verified"] = r.seller_id in verified_seller_ids
        items.append(d)
    return jsonify({"ok": True, "as_of": now.isoformat(), "listings": items}), 200


