# ════════════════════════════════════════════════════════════
# STAGE 449: TRADE-SECRET-SAFE COLLABORATIVE SPEC EDITOR
# A real two-party document with per-section visibility enforced
# server-side (not just hidden in the UI) — either party can write a
# section marked shared, buyer_only, or seller_only, and a viewer only
# ever receives sections they're actually allowed to see.
# ════════════════════════════════════════════════════════════

class SpecDocument(db.Model):
    __tablename__ = "spec_documents"
    id            = db.Column(db.Integer, primary_key=True)
    created_by_id = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    buyer_id      = db.Column(db.Integer, nullable=False)
    seller_id     = db.Column(db.Integer, nullable=False)
    title         = db.Column(db.String(160), nullable=False)
    order_id      = db.Column(db.Integer, db.ForeignKey("product_orders.id"), nullable=True)
    created_at    = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        return {"id": self.id, "title": self.title, "buyer_id": self.buyer_id, "seller_id": self.seller_id,
                "order_id": self.order_id, "created_at": self.created_at.isoformat() if self.created_at else None}


class SpecSection(db.Model):
    __tablename__ = "spec_sections"
    id            = db.Column(db.Integer, primary_key=True)
    document_id   = db.Column(db.Integer, db.ForeignKey("spec_documents.id"), nullable=False, index=True)
    author_id     = db.Column(db.Integer, nullable=False)
    heading       = db.Column(db.String(160), nullable=False)
    content       = db.Column(db.Text, nullable=True)
    visibility    = db.Column(db.String(16), nullable=False, default="shared")  # shared, buyer_only, seller_only
    updated_at    = db.Column(db.DateTime, default=datetime.utcnow, onupdate=datetime.utcnow)

    def to_dict(self):
        return {"id": self.id, "heading": self.heading, "content": self.content,
                "visibility": self.visibility, "author_id": self.author_id,
                "updated_at": self.updated_at.isoformat() if self.updated_at else None}


def _spec_doc_party_or_403(doc, user):
    return user and user["id"] in (doc.buyer_id, doc.seller_id)


@app.route("/api/spec-documents", methods=["POST"])
@csrf.exempt
def spec_document_create():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    other_party_id = data.get("counterparty_id")
    if not other_party_id:
        return jsonify({"error": "counterparty_id is required."}), 400
    role = (data.get("your_role") or "buyer").strip()
    buyer_id, seller_id = (user["id"], other_party_id) if role == "buyer" else (other_party_id, user["id"])
    doc = SpecDocument(
        created_by_id=user["id"], buyer_id=buyer_id, seller_id=seller_id,
        title=(data.get("title") or "Untitled spec").strip()[:160],
        order_id=data.get("order_id") if str(data.get("order_id") or "").isdigit() else None,
    )
    db.session.add(doc)
    db.session.commit()
    return jsonify({"ok": True, "document": doc.to_dict()}), 201


@app.route("/api/spec-documents/<int:document_id>/sections", methods=["POST"])
@csrf.exempt
def spec_section_upsert(document_id):
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    doc = SpecDocument.query.get(document_id)
    if not doc or not _spec_doc_party_or_403(doc, user):
        return jsonify({"error": "Spec document not found."}), 404
    data = request.get_json(silent=True) or {}
    visibility = (data.get("visibility") or "shared").strip()
    if visibility not in ("shared", "buyer_only", "seller_only"):
        return jsonify({"error": "Invalid visibility."}), 400
    section_id = data.get("section_id")
    if section_id:
        section = SpecSection.query.get(section_id)
        if not section or section.document_id != document_id or section.author_id != user["id"]:
            return jsonify({"error": "You can only edit your own sections."}), 403
        section.content = data.get("content", section.content)
        section.visibility = visibility
    else:
        section = SpecSection(
            document_id=document_id, author_id=user["id"],
            heading=(data.get("heading") or "Untitled section").strip()[:160],
            content=data.get("content"), visibility=visibility,
        )
        db.session.add(section)
    db.session.commit()
    return jsonify({"ok": True, "section": section.to_dict()}), 200


@app.route("/api/spec-documents/<int:document_id>", methods=["GET"])
def spec_document_view(document_id):
    user = _get_current_user()
    doc = SpecDocument.query.get(document_id)
    if not doc or not _spec_doc_party_or_403(doc, user):
        return jsonify({"error": "Spec document not found."}), 404
    my_role = "buyer" if user["id"] == doc.buyer_id else "seller"
    visible_tags = {"shared", "buyer_only" if my_role == "buyer" else "seller_only"}
    sections = (SpecSection.query.filter_by(document_id=document_id)
                .filter(SpecSection.visibility.in_(visible_tags))
                .order_by(SpecSection.id).all())
    return jsonify({"ok": True, "document": doc.to_dict(), "your_role": my_role,
                     "sections": [s.to_dict() for s in sections]}), 200


# ════════════════════════════════════════════════════════════
# STAGE 450: AUTOMATED TARIFF-ENGINEERING SIMULATION
# Reuses the exact CIF + duty formula the existing Landed-Cost
# Calculator (Stage 350-era) already uses, run once per candidate
# sourcing country so the comparison is apples-to-apples — models the
# real landed-cost impact of switching origin before committing to it.
# ════════════════════════════════════════════════════════════

@app.route("/api/tariff-engineering/simulate", methods=["POST"])
@csrf.exempt
def tariff_engineering_simulate():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    data = request.get_json(silent=True) or {}
    candidates = data.get("candidate_countries") or []
    if not isinstance(candidates, list) or not candidates:
        return jsonify({"error": "candidate_countries must be a non-empty list of "
                                  "{country_code, goods_value, freight, insurance, duty_rate_pct, other_fees}."}), 400
    results = []
    for c in candidates:
        try:
            goods_value = float(c.get("goods_value", 0))
            freight = float(c.get("freight", 0))
            insurance = float(c.get("insurance", 0))
            duty_rate_pct = float(c.get("duty_rate_pct", 0))
            other_fees = float(c.get("other_fees", 0))
        except (TypeError, ValueError):
            return jsonify({"error": f"Invalid numeric field for candidate {c.get('country_code')!r}."}), 400
        cif_value = goods_value + freight + insurance
        duty_amount = round(cif_value * (duty_rate_pct / 100.0), 2)
        total = round(cif_value + duty_amount + other_fees, 2)
        results.append({"country_code": (c.get("country_code") or "").strip().upper()[:4],
                         "cif_value": round(cif_value, 2), "duty_amount": duty_amount,
                         "total_landed_cost": total})
    results.sort(key=lambda r: r["total_landed_cost"])
    cheapest = results[0] if results else None
    return jsonify({"ok": True, "results": results, "recommended": cheapest}), 200


