# ════════════════════════════════════════════════════════════
# STAGE 453: SUPPLY CHAIN RESILIENCE SCORE (PER SUPPLIER)
# Distinct from the Stage 172 Resilience Score (a location's weather
# risk, used to underwrite parametric insurance) — this combines three
# real, already-computed signals into one per-supplier number:
# geopolitical/compliance risk (Stage 377's Country Risk Index),
# climate risk (the existing Climate Lane Risk zones), and this
# specific seller's own real payment/fulfillment history.
# ════════════════════════════════════════════════════════════

@app.route("/api/supplier-resilience-score/<int:seller_id>", methods=["GET"])
def supplier_resilience_score(seller_id):
    seller = UserAccount.query.get(seller_id)
    if not seller:
        return jsonify({"error": "Seller not found."}), 404

    geopolitical = None
    if seller.country_code:
        try:
            geo_score = _compute_country_risk_index(seller.country_code)
            geopolitical = geo_score.overall_score if geo_score else None
        except Exception:
            geopolitical = None

    climate_band = "unknown"
    if seller.country_code:
        zone = ClimateLaneRiskZone.query.filter(
            ClimateLaneRiskZone.match_keywords_csv.ilike(f"%{seller.country_code.lower()}%")).first()
        if zone:
            climate_band = zone.risk_band
    climate_component = {"low": 10.0, "moderate": 40.0, "medium": 40.0, "high": 75.0}.get(
        (climate_band or "").lower(), 30.0)

    fulfillment_rate, order_n = _dispute_rate(ProductOrder.query.filter_by(seller_id=seller_id))
    financial_component = fulfillment_rate if fulfillment_rate is not None else 20.0

    components = [c for c in (geopolitical, climate_component, financial_component) if c is not None]
    overall = round(sum(components) / len(components), 1) if components else None
    band = None
    if overall is not None:
        band = "low" if overall < 25 else ("medium" if overall < 55 else "high")

    return jsonify({
        "ok": True, "seller_id": seller_id, "overall_risk_score": overall, "risk_band": band,
        "geopolitical_component": geopolitical, "climate_component": climate_component,
        "climate_band": climate_band, "financial_component": financial_component,
        "orders_considered": order_n,
    }), 200


# ════════════════════════════════════════════════════════════
# NEW STAGE: SUPPLIER RISK SCORING VIA ML
# Genuinely different from the Supplier Resilience Score above (which
# averages three static external signals for marketplace sellers): this
# trains a real logistic-regression model — plain Python gradient
# descent, no fabricated weights — on THIS business's own procurement
# history (ErpPurchaseOrder/ErpSupplier) to predict the probability
# that a future order from a given supplier arrives late or gets
# cancelled. If a business doesn't have enough closed purchase orders
# yet, it honestly says so instead of inventing a score.
# ════════════════════════════════════════════════════════════
SUPPLIER_RISK_MIN_TRAINING_ROWS = 6

class SupplierRiskModelRun(db.Model):
    __tablename__ = "supplier_risk_model_runs"
    id                = db.Column(db.Integer,  primary_key=True)
    owner_user_id     = db.Column(db.Integer,  db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    n_training_rows   = db.Column(db.Integer,  nullable=False)
    weights_json      = db.Column(db.Text,     nullable=False)  # [bias, w_order_count, w_late_rate, w_value, w_lead_time]
    feature_means_json = db.Column(db.Text,    nullable=False)  # z-score normalization params used at train time
    feature_stds_json  = db.Column(db.Text,    nullable=False)
    trained_at        = db.Column(db.DateTime, default=datetime.utcnow, index=True)

    def to_dict(self):
        return {
            "id": self.id, "n_training_rows": self.n_training_rows,
            "weights": json.loads(self.weights_json),
            "trained_at": self.trained_at.isoformat() if self.trained_at else None,
        }


class SupplierRiskScore(db.Model):
    __tablename__ = "supplier_risk_scores"
    id                     = db.Column(db.Integer,  primary_key=True)
    owner_user_id          = db.Column(db.Integer,  db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    supplier_id            = db.Column(db.Integer,  db.ForeignKey("erp_suppliers.id"), nullable=False, index=True)
    model_run_id           = db.Column(db.Integer,  db.ForeignKey("supplier_risk_model_runs.id"), nullable=False)
    predicted_late_prob    = db.Column(db.Float,    nullable=False)
    risk_band              = db.Column(db.String(10), nullable=False)  # low, medium, high
    orders_used            = db.Column(db.Integer,  nullable=False)
    computed_at            = db.Column(db.DateTime, default=datetime.utcnow, index=True)

    def to_dict(self):
        return {
            "id": self.id, "supplier_id": self.supplier_id, "model_run_id": self.model_run_id,
            "predicted_late_probability": round(self.predicted_late_prob, 3),
            "risk_band": self.risk_band, "orders_used": self.orders_used,
            "computed_at": self.computed_at.isoformat() if self.computed_at else None,
        }


def _supplier_risk_build_training_rows(owner_user_id):
    """Walks this business's own closed POs chronologically per supplier,
    building one labeled example per PO from what was actually knowable
    about that supplier BEFORE that PO closed (no lookahead leakage)."""
    pos = (ErpPurchaseOrder.query.filter_by(owner_user_id=owner_user_id)
           .filter(ErpPurchaseOrder.status.in_(["received", "cancelled"]))
           .filter(ErpPurchaseOrder.supplier_id.isnot(None))
           .order_by(ErpPurchaseOrder.order_date.asc().nullsfirst(), ErpPurchaseOrder.id.asc()).all())
    running = {}  # supplier_id -> [count, late_count]
    rows = []
    for po in pos:
        sid = po.supplier_id
        prior_count, prior_late = running.get(sid, (0, 0))
        lead_time = None
        if po.order_date and po.expected_date:
            lead_time = (po.expected_date - po.order_date).days
        is_late = po.status == "cancelled" or (
            po.status == "received" and po.expected_date and po.received_at and po.received_at.date() > po.expected_date)
        rows.append({
            "features": [
                float(prior_count),
                (prior_late / prior_count) if prior_count else 0.0,
                float(po.total or 0.0),
                float(lead_time if lead_time is not None else 14.0),
            ],
            "label": 1.0 if is_late else 0.0,
        })
        running[sid] = (prior_count + 1, prior_late + (1 if is_late else 0))
    return rows, running


def _supplier_risk_train(owner_user_id):
    rows, running = _supplier_risk_build_training_rows(owner_user_id)
    if len(rows) < SUPPLIER_RISK_MIN_TRAINING_ROWS:
        return None, len(rows), running

    n_feat = len(rows[0]["features"])
    means = [sum(r["features"][j] for r in rows) / len(rows) for j in range(n_feat)]
    stds = []
    for j in range(n_feat):
        var = sum((r["features"][j] - means[j]) ** 2 for r in rows) / len(rows)
        stds.append(math.sqrt(var) or 1.0)

    def z(feats):
        return [(feats[j] - means[j]) / stds[j] for j in range(n_feat)]

    X = [z(r["features"]) for r in rows]
    y = [r["label"] for r in rows]
    w = [0.0] * n_feat
    b = 0.0
    lr = 0.2
    for _epoch in range(400):
        grad_w = [0.0] * n_feat
        grad_b = 0.0
        for xi, yi in zip(X, y):
            z_val = b + sum(w[j] * xi[j] for j in range(n_feat))
            pred = 1.0 / (1.0 + math.exp(-max(-30, min(30, z_val))))
            err = pred - yi
            for j in range(n_feat):
                grad_w[j] += err * xi[j]
            grad_b += err
        n = len(X)
        for j in range(n_feat):
            w[j] -= lr * grad_w[j] / n
        b -= lr * grad_b / n

    run = SupplierRiskModelRun(
        owner_user_id=owner_user_id, n_training_rows=len(rows),
        weights_json=json.dumps([b] + w),
        feature_means_json=json.dumps(means), feature_stds_json=json.dumps(stds),
    )
    db.session.add(run)
    db.session.commit()
    return run, len(rows), running


def _supplier_risk_predict(run, features):
    means = json.loads(run.feature_means_json)
    stds = json.loads(run.feature_stds_json)
    weights = json.loads(run.weights_json)
    b, w = weights[0], weights[1:]
    z = [(features[j] - means[j]) / stds[j] for j in range(len(features))]
    val = b + sum(w[j] * z[j] for j in range(len(features)))
    return 1.0 / (1.0 + math.exp(-max(-30, min(30, val))))


@app.route("/api/supplier-risk-ml/train", methods=["POST"])
def supplier_risk_ml_train():
    user, err = _erp_user_or_401()
    if err: return err
    if not _csrf_ok():
        return jsonify({"error": "Invalid request origin."}), 403
    run, n_rows, running = _supplier_risk_train(user["id"])
    if run is None:
        return jsonify({
            "ok": False, "trained": False, "n_training_rows": n_rows,
            "min_required": SUPPLIER_RISK_MIN_TRAINING_ROWS,
            "error": f"Need at least {SUPPLIER_RISK_MIN_TRAINING_ROWS} received/cancelled purchase orders with a supplier assigned to train a model — you have {n_rows}.",
        }), 200

    suppliers = ErpSupplier.query.filter_by(owner_user_id=user["id"], active=True).all()
    scored = []
    for s in suppliers:
        prior_count, prior_late = running.get(s.id, (0, 0))
        recent_pos = (ErpPurchaseOrder.query.filter_by(owner_user_id=user["id"], supplier_id=s.id)
                      .order_by(ErpPurchaseOrder.id.desc()).limit(10).all())
        avg_value = (sum(p.total or 0 for p in recent_pos) / len(recent_pos)) if recent_pos else 0.0
        avg_lead = 14.0
        leads = [(p.expected_date - p.order_date).days for p in recent_pos if p.order_date and p.expected_date]
        if leads:
            avg_lead = sum(leads) / len(leads)
        features = [float(prior_count), (prior_late / prior_count) if prior_count else 0.0, avg_value, avg_lead]
        prob = _supplier_risk_predict(run, features)
        band = "low" if prob < 0.3 else ("medium" if prob < 0.6 else "high")
        score = SupplierRiskScore(owner_user_id=user["id"], supplier_id=s.id, model_run_id=run.id,
                                   predicted_late_prob=prob, risk_band=band, orders_used=prior_count)
        db.session.add(score)
        scored.append(score)
    db.session.commit()
    return jsonify({
        "ok": True, "trained": True, "model": run.to_dict(),
        "scores": [s.to_dict() for s in scored],
    }), 200


@app.route("/api/supplier-risk-ml/scores", methods=["GET"])
def supplier_risk_ml_scores():
    user, err = _erp_user_or_401()
    if err: return err
    latest_run = (SupplierRiskModelRun.query.filter_by(owner_user_id=user["id"])
                  .order_by(SupplierRiskModelRun.trained_at.desc()).first())
    if not latest_run:
        _, n_rows, _ = _supplier_risk_build_training_rows(user["id"])
        return jsonify({
            "ok": False, "trained": False, "n_training_rows": n_rows,
            "min_required": SUPPLIER_RISK_MIN_TRAINING_ROWS,
        }), 200
    rows = (SupplierRiskScore.query.filter_by(owner_user_id=user["id"], model_run_id=latest_run.id)
            .order_by(SupplierRiskScore.predicted_late_prob.desc()).all())
    supplier_names = {s.id: s.name for s in ErpSupplier.query.filter_by(owner_user_id=user["id"]).all()}
    out = []
    for r in rows:
        d = r.to_dict()
        d["supplier_name"] = supplier_names.get(r.supplier_id, "Unknown supplier")
        out.append(d)
    return jsonify({"ok": True, "trained": True, "model": latest_run.to_dict(), "scores": out}), 200


# ════════════════════════════════════════════════════════════
# STAGE 454: UNIFIED GLOBAL TRADE IDENTITY
# Builds on the existing Digital Trade Passport (BusinessPassportShare
# above) so a partner marketplace can verify a seller's real, current
# platform standing through one public token check, without that
# seller re-doing onboarding from scratch elsewhere.
# ════════════════════════════════════════════════════════════

@app.route("/api/trade-identity/verify/<token>", methods=["GET"])
def trade_identity_verify(token):
    share = BusinessPassportShare.query.filter_by(token=token, revoked=False).first()
    if not share:
        return jsonify({"ok": False, "error": "Unknown or revoked trade identity token."}), 404
    if share.expires_at and share.expires_at < datetime.utcnow():
        return jsonify({"ok": False, "error": "This trade identity token has expired."}), 410
    seller = UserAccount.query.get(share.user_id)
    if not seller:
        return jsonify({"ok": False, "error": "Account not found."}), 404
    kyc = KYCVerification.query.filter_by(owner_id=seller.id, status="approved").first()
    active_listings = Product.query.filter_by(seller_id=seller.id, is_active=True).count()
    fulfillment_rate, order_n = _dispute_rate(ProductOrder.query.filter_by(seller_id=seller.id))
    return jsonify({
        "ok": True, "verified_identity": True,
        "seller_name": seller.name, "country_code": seller.country_code,
        "kyc_verified": bool(kyc), "active_listings": active_listings,
        "orders_fulfilled": order_n,
        "dispute_rate_pct": fulfillment_rate,
        "checked_at": datetime.utcnow().isoformat(),
    }), 200


# ════════════════════════════════════════════════════════════
# STAGE 457: OFFICE HARDWARE & PERIPHERALS BRIDGE
# Covers items 1-10 of the "Office Hardware & Peripherals" backlog
# category. Real browsers can talk directly to local USB/serial/
# Bluetooth hardware via WebUSB, WebSerial and Web Bluetooth — but
# ONLY the browser can do that; this server can never reach a
# seller's local receipt printer, scanner, or cash drawer over HTTP.
# So the split here is real and deliberate: the BACKEND's job is (a)
# turning real order/product data into the exact bytes a device
# protocol expects (ESC/POS commands, ZPL label code, receipt/label
# line items), and (b) keeping an audit trail of what was printed/
# triggered/captured and by whom. The FRONTEND's job (index.html,
# same stage number) is holding the actual WebUSB/WebSerial/
# Bluetooth device connection and sending those bytes to it — that
# part cannot live server-side at all, by browser design.
#
# Card readers (item 9, Stripe Terminal / Square Reader) are the one
# item in this batch NOT built as a working flow: those need a real
# Stripe Terminal location + reader registered on a live Stripe
# account (or a Square Reader SDK credential), which is account-
# specific and can't be simulated as "already connected." The status
# endpoint below reports honestly on whether real Terminal config is
# present rather than faking a paired reader.
# ════════════════════════════════════════════════════════════

class HardwarePeripheral(db.Model):
    __tablename__ = "hardware_peripherals"
    id            = db.Column(db.Integer, primary_key=True)
    owner_id      = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    # 'receipt_printer', 'label_printer', 'kitchen_printer', 'cash_drawer'
    # (drawers are wired through a printer's pulse line, so a drawer
    # peripheral references the printer that triggers it),
    # 'barcode_scanner', 'signature_pad', 'document_scanner'
    kind          = db.Column(db.String(24), nullable=False, index=True)
    label         = db.Column(db.String(100), nullable=False)          # seller-chosen name, e.g. "Front counter printer"
    # how the browser reached it: 'webusb', 'webserial', 'bluetooth',
    # 'network' (IPP/system print dialog), or 'camera'/'canvas' for
    # scanner/signature modes that need no paired device at all
    connection_method = db.Column(db.String(16), nullable=False)
    device_name   = db.Column(db.String(160), nullable=True)           # navigator.usb/serial/bluetooth's reported device name
    vendor_id     = db.Column(db.Integer, nullable=True)               # WebUSB/Bluetooth vendorId, when the browser exposes one
    product_id_hw = db.Column(db.Integer, nullable=True)               # WebUSB productId
    role          = db.Column(db.String(16), nullable=True)            # for printers: 'front' or 'kitchen'
    active        = db.Column(db.Boolean, default=True, nullable=False)
    created_at    = db.Column(db.DateTime, default=datetime.utcnow)
    last_used_at  = db.Column(db.DateTime, nullable=True)

    def to_dict(self):
        return {
            "id": self.id, "kind": self.kind, "label": self.label,
            "connection_method": self.connection_method, "device_name": self.device_name,
            "role": self.role, "active": self.active,
            "created_at": self.created_at.isoformat() if self.created_at else None,
            "last_used_at": self.last_used_at.isoformat() if self.last_used_at else None,
        }


class PrintJob(db.Model):
    __tablename__ = "hardware_print_jobs"
    id            = db.Column(db.Integer, primary_key=True)
    owner_id      = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    peripheral_id = db.Column(db.Integer, db.ForeignKey("hardware_peripherals.id"), nullable=True, index=True)
    # 'receipt', 'label', 'kitchen_ticket', 'document'
    job_type      = db.Column(db.String(16), nullable=False)
    reference     = db.Column(db.String(80), nullable=True)   # e.g. "order:1042" or "product:88"
    status        = db.Column(db.String(16), nullable=False, default="sent")  # 'sent', 'failed' — reported back by the browser
    error_message = db.Column(db.String(300), nullable=True)
    created_at    = db.Column(db.DateTime, default=datetime.utcnow, index=True)

    def to_dict(self):
        return {"id": self.id, "peripheral_id": self.peripheral_id, "job_type": self.job_type,
                "reference": self.reference, "status": self.status, "error_message": self.error_message,
                "created_at": self.created_at.isoformat() if self.created_at else None}


class SignatureCapture(db.Model):
    __tablename__ = "hardware_signature_captures"
    id            = db.Column(db.Integer, primary_key=True)
    owner_id      = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    order_id      = db.Column(db.Integer, db.ForeignKey("product_orders.id"), nullable=True, index=True)
    # 'delivery' (proof of delivery) or 'contract' (in-person contract sign-off)
    purpose       = db.Column(db.String(16), nullable=False, default="delivery")
    signer_name   = db.Column(db.String(120), nullable=True)
    image_data_url = db.Column(db.Text().with_variant(mysql.LONGTEXT, "mysql"), nullable=False)   # PNG data URL from the canvas pad — no external storage needed
    captured_at   = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self, include_image=True):
        d = {"id": self.id, "order_id": self.order_id, "purpose": self.purpose,
             "signer_name": self.signer_name,
             "captured_at": self.captured_at.isoformat() if self.captured_at else None}
        if include_image:
            d["image_data_url"] = self.image_data_url
        return d


class CashDrawerEvent(db.Model):
    __tablename__ = "hardware_cash_drawer_events"
    id            = db.Column(db.Integer, primary_key=True)
    owner_id      = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    peripheral_id = db.Column(db.Integer, db.ForeignKey("hardware_peripherals.id"), nullable=False, index=True)
    order_id      = db.Column(db.Integer, db.ForeignKey("product_orders.id"), nullable=True, index=True)
    triggered_at  = db.Column(db.DateTime, default=datetime.utcnow, index=True)

    def to_dict(self):
        return {"id": self.id, "peripheral_id": self.peripheral_id, "order_id": self.order_id,
                "triggered_at": self.triggered_at.isoformat() if self.triggered_at else None}


def _hw_owned_peripheral(peripheral_id, user_id):
    p = HardwarePeripheral.query.get(peripheral_id)
    if not p or p.owner_id != user_id or not p.active:
        return None
    return p


@app.route("/api/hardware/peripherals", methods=["POST"])
@csrf.exempt
def hardware_peripheral_register():
    """Called AFTER a real navigator.usb.requestDevice() / .serial.requestPort()
    / .bluetooth.requestDevice() (or a no-pairing mode like camera/canvas)
    succeeds in the browser — this just files what the browser reported."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    kind = (data.get("kind") or "").strip()
    valid_kinds = {"receipt_printer", "label_printer", "kitchen_printer", "cash_drawer",
                   "barcode_scanner", "signature_pad", "document_scanner"}
    if kind not in valid_kinds:
        return jsonify({"error": "Unknown peripheral kind."}), 400
    method = (data.get("connection_method") or "").strip()
    if method not in {"webusb", "webserial", "bluetooth", "network", "camera", "canvas"}:
        return jsonify({"error": "Unknown connection method."}), 400
    row = HardwarePeripheral(
        owner_id=user["id"], kind=kind,
        label=(data.get("label") or kind.replace("_", " ").title())[:100],
        connection_method=method,
        device_name=(data.get("device_name") or "")[:160] or None,
        vendor_id=data.get("vendor_id") if isinstance(data.get("vendor_id"), int) else None,
        product_id_hw=data.get("product_id_hw") if isinstance(data.get("product_id_hw"), int) else None,
        role=(data.get("role") or "").strip()[:16] or None,
    )
    db.session.add(row)
    db.session.commit()
    return jsonify({"ok": True, "peripheral": row.to_dict()}), 201


@app.route("/api/hardware/peripherals/mine", methods=["GET"])
def hardware_peripherals_mine():
    user = _get_current_user()
