    ticket_id  = db.Column(db.Integer, db.ForeignKey("support_tickets.id"), nullable=False, index=True)
    sender_type = db.Column(db.String(12), nullable=False)   # 'customer' or 'agent'
    sender_name = db.Column(db.String(120), nullable=True)
