# ─────────────────────────────────────────────────────────────
# ITEM 94: LIVE CHAT WIDGET for a seller's own storefront (not just
# platform-side chat). Ships as a real embeddable <script> snippet
# (served below at /widget/chat.js) any seller can drop onto their OWN
# external website — not only the platform's /store/<slug> page —
# using their storefront_slug as the account key. Visitor messages are
# polled by the seller's dashboard; no login needed on the visitor side.
#
# LIVE CHAT TRANSLATION (added later): both sides of this chat can now
# request messages pre-translated into their own language. Reuses the
# same cached google_translate_text() pipeline as the existing full-UI
# translator (see TranslationCache / FEATURE 4 below) rather than
# adding a second translation mechanism — a real cache hit/miss, never
# a fabricated translation. When Google Translate isn't configured for
# this deployment, translated_body comes back null and the caller is
# told via translation_available:false, instead of silently pretending
# to translate.
# ─────────────────────────────────────────────────────────────

def _translate_chat_text(text, target_lang):
    """Cached real-time-chat translation helper. Shares the TranslationCache
    table with the full-UI translator (FEATURE 4) so identical text already
    translated elsewhere on the platform is a free cache hit here too.
    Returns None (never a fabricated string) if translation isn't available
    or if the source text already IS the target language."""
    text = (text or "").strip()[:2000]
    target_lang = (target_lang or "").strip()[:8]
    if not text or not target_lang or target_lang.lower() in ("en", "en-us", "en-gb"):
        return None
    h = hashlib.sha256(text.encode("utf-8")).hexdigest()
    cached = TranslationCache.query.filter_by(source_hash=h, locale=target_lang).first()
    if cached:
        return cached.translated_text
    if not GTRANSLATE_AVAILABLE:
        return None
    try:
        result = google_translate_text(text, target_lang)
    except Exception:
        return None
    if not isinstance(result, dict) or not result.get("ok"):
        return None
    translated = (result.get("translated_text") or "").strip()
    if not translated or translated == text:
        return None
    try:
        db.session.add(TranslationCache(source_hash=h, locale=target_lang, translated_text=translated))
        db.session.commit()
    except Exception:
        db.session.rollback()
    return translated

class ChatWidgetSession(db.Model):
    __tablename__ = "chat_widget_sessions"
    id            = db.Column(db.Integer, primary_key=True)
    owner_id      = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    visitor_token = db.Column(db.String(48), unique=True, nullable=False, index=True)
    visitor_name  = db.Column(db.String(120), nullable=True)
    status        = db.Column(db.String(12), nullable=False, default="open")  # open, closed
    unread_for_owner = db.Column(db.Integer, nullable=False, default=0)
    created_at    = db.Column(db.DateTime, default=datetime.utcnow)
    last_message_at = db.Column(db.DateTime, default=datetime.utcnow, index=True)

    def to_dict(self):
        return {"id": self.id, "visitor_token": self.visitor_token, "visitor_name": self.visitor_name,
                "status": self.status, "unread_for_owner": self.unread_for_owner,
                "last_message_at": self.last_message_at.isoformat() if self.last_message_at else None}


class ChatWidgetMessage(db.Model):
    __tablename__ = "chat_widget_messages"
    id         = db.Column(db.Integer, primary_key=True)
    session_id = db.Column(db.Integer, db.ForeignKey("chat_widget_sessions.id"), nullable=False, index=True)
    sender     = db.Column(db.String(10), nullable=False)   # 'visitor' or 'seller'
    body       = db.Column(db.Text, nullable=False)
    created_at = db.Column(db.DateTime, default=datetime.utcnow, index=True)

    def to_dict(self):
        return {"id": self.id, "sender": self.sender, "body": self.body,
                "created_at": self.created_at.isoformat() if self.created_at else None}


@app.route("/widget/chat.js", methods=["GET"])
def chat_widget_script():
    """Real embeddable snippet: <script src=".../widget/chat.js" data-seller="SLUG" defer></script>
    Renders a floating chat bubble on ANY page it's dropped into."""
    js = """
(function(){
  var cur = document.currentScript;
  var slug = cur ? cur.getAttribute('data-seller') : null;
  if (!slug) { console.warn('Connect It chat widget: missing data-seller attribute.'); return; }
  var base = (cur && cur.src) ? cur.src.replace(/\\/widget\\/chat\\.js.*/, '') : '';
  var token = null, poll = null;
  var css = '.raiw-bubble{position:fixed;bottom:20px;right:20px;width:56px;height:56px;border-radius:50%;background:#1e3a8a;color:#fff;border:none;cursor:pointer;font-size:1.4rem;box-shadow:0 4px 16px rgba(0,0,0,.2);z-index:99999;}' +
    '.raiw-panel{position:fixed;bottom:86px;right:20px;width:320px;max-width:90vw;height:420px;background:#fff;border-radius:14px;box-shadow:0 8px 32px rgba(0,0,0,.25);display:none;flex-direction:column;overflow:hidden;z-index:99999;font-family:Arial,sans-serif;}' +
    '.raiw-head{background:#1e3a8a;color:#fff;padding:12px 14px;font-size:0.9rem;font-weight:700;}' +
    '.raiw-body{flex:1;overflow-y:auto;padding:10px;font-size:0.82rem;}' +
    '.raiw-msg{margin-bottom:8px;max-width:85%;padding:8px 10px;border-radius:10px;line-height:1.4;}' +
    '.raiw-msg.visitor{background:#1e3a8a;color:#fff;margin-left:auto;}' +
    '.raiw-msg.seller{background:#f1f5f9;color:#1e293b;}' +
    '.raiw-input{display:flex;border-top:1px solid #e2e8f0;}' +
    '.raiw-input input{flex:1;border:none;padding:10px;font-size:0.82rem;outline:none;}' +
    '.raiw-input button{border:none;background:#1e3a8a;color:#fff;padding:0 14px;cursor:pointer;}';
  var style = document.createElement('style'); style.textContent = css; document.head.appendChild(style);
  var bubble = document.createElement('button'); bubble.className='raiw-bubble'; bubble.textContent='Chat';
  var panel = document.createElement('div'); panel.className='raiw-panel';
  panel.innerHTML = '<div class="raiw-head">Chat with us</div><div class="raiw-body" id="raiw-body"></div>' +
    '<div class="raiw-input"><input id="raiw-input" placeholder="Type a message…"/><button id="raiw-send">Send</button></div>';
  document.body.appendChild(bubble); document.body.appendChild(panel);
  var visitorLang = (navigator.language || 'en').split('-')[0];
  function esc(s){ return (s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;'); }
  function render(msgs){
    var body = document.getElementById('raiw-body');
    body.innerHTML = msgs.map(function(m){
      var extra = (m.translated_body && m.translated_body !== m.body)
        ? '<div style="font-size:0.72rem;opacity:.75;margin-top:3px;font-style:italic;">'+esc(m.translated_body)+'</div>' : '';
      return '<div class="raiw-msg '+m.sender+'">'+esc(m.body)+extra+'</div>';
    }).join('');
    body.scrollTop = body.scrollHeight;
  }
  function startSession(){
    fetch(base + '/api/storefront-chat/sessions/start', { method:'POST', headers:{'Content-Type':'application/json'},
      body: JSON.stringify({ slug: slug }) })
      .then(function(r){ return r.json(); })
      .then(function(d){ if (d.ok) { token = d.visitor_token; poll = setInterval(fetchMsgs, 3000); fetchMsgs(); } });
  }
  function fetchMsgs(){
    if (!token) return;
    fetch(base + '/api/storefront-chat/sessions/' + token + '/messages?translate_to=' + encodeURIComponent(visitorLang))
      .then(function(r){ return r.json(); }).then(function(d){ if (d.ok) render(d.messages); });
  }
  function send(){
    var input = document.getElementById('raiw-input'); var val = input.value.trim();
    if (!val || !token) return;
    input.value = '';
    fetch(base + '/api/storefront-chat/sessions/' + token + '/messages', {
      method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify({ body: val, sender:'visitor' })
    }).then(fetchMsgs);
  }
  bubble.addEventListener('click', function(){
    var open = panel.style.display === 'flex';
    panel.style.display = open ? 'none' : 'flex';
    if (!open && !token) startSession();
  });
  document.getElementById && panel.querySelector('#raiw-send').addEventListener('click', send);
  panel.querySelector('#raiw-input').addEventListener('keydown', function(e){ if (e.key==='Enter') send(); });
})();
"""
    return (js, 200, {"Content-Type": "application/javascript"})


@app.route("/api/storefront-chat/sessions/start", methods=["POST"])
@csrf.exempt
def storefront_chat_start():
    data = request.get_json(silent=True) or {}
    slug = (data.get("slug") or "").strip()
    branding = BusinessBranding.query.filter_by(storefront_slug=slug).first()
    if not branding:
        return jsonify({"error": "Unknown storefront."}), 404
    token = secrets.token_urlsafe(24)
    row = ChatWidgetSession(owner_id=branding.owner_user_id, visitor_token=token,
                             visitor_name=(data.get("visitor_name") or "")[:120] or None)
    db.session.add(row)
    db.session.commit()
    return jsonify({"ok": True, "visitor_token": token}), 201


@app.route("/api/storefront-chat/sessions/<token>/messages", methods=["GET"])
def storefront_chat_get_messages(token):
    session_row = ChatWidgetSession.query.filter_by(visitor_token=token).first()
    if not session_row:
        return jsonify({"error": "Unknown session."}), 404
    rows = (ChatWidgetMessage.query.filter_by(session_id=session_row.id)
            .order_by(ChatWidgetMessage.created_at.asc()).all())
    translate_to = (request.args.get("translate_to") or "").strip()
    out = []
    for r in rows:
        d = r.to_dict()
        if translate_to:
            d["translated_body"] = _translate_chat_text(r.body, translate_to)
        out.append(d)
    return jsonify({"ok": True, "messages": out, "translation_available": GTRANSLATE_AVAILABLE}), 200


@app.route("/api/storefront-chat/sessions/<token>/messages", methods=["POST"])
@csrf.exempt
def storefront_chat_post_message(token):
    session_row = ChatWidgetSession.query.filter_by(visitor_token=token).first()
    if not session_row:
        return jsonify({"error": "Unknown session."}), 404
    data = request.get_json(silent=True) or {}
    body = (data.get("body") or "").strip()
    if not body:
        return jsonify({"error": "Message body is required."}), 400
    sender = "visitor"
    user = _get_current_user()
    if user and user["id"] == session_row.owner_id:
        sender = "seller"
    else:
        session_row.unread_for_owner = (session_row.unread_for_owner or 0) + 1
    db.session.add(ChatWidgetMessage(session_id=session_row.id, sender=sender, body=body[:2000]))
    session_row.last_message_at = datetime.utcnow()
    db.session.commit()
    return jsonify({"ok": True}), 201


