@app.route("/api/storefront-chat/sessions/<int:session_id>/thread", methods=["GET"])
def storefront_chat_seller_thread(session_id):
    """Real fix: the seller dashboard previously had NO way to read a
    visitor's messages at all — the widget only exposes the thread via
    the visitor's own token, and the seller obviously doesn't have that.
    This is the seller's own owner-checked view of the full thread.
    Also clears the unread badge on open, and optionally translates
    every message via ?translate_to=<lang> (cached, see _translate_chat_text)."""
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    session_row = ChatWidgetSession.query.get(session_id)
    if not session_row or session_row.owner_id != user["id"]:
        return jsonify({"error": "Session not found."}), 404
    rows = (ChatWidgetMessage.query.filter_by(session_id=session_row.id)
            .order_by(ChatWidgetMessage.created_at.asc()).all())
    translate_to = (request.args.get("translate_to") or "").strip()
    out = []
    for r in rows:
        d = r.to_dict()
        if translate_to:
            d["translated_body"] = _translate_chat_text(r.body, translate_to)
        out.append(d)
    if session_row.unread_for_owner:
        session_row.unread_for_owner = 0
        db.session.commit()
    return jsonify({
        "ok": True, "messages": out, "visitor_name": session_row.visitor_name,
        "translation_available": GTRANSLATE_AVAILABLE,
    }), 200


