# ITEM 95: APPOINTMENT/BOOKING SCHEDULER
# Already live on this platform — PublicBookingPage / PublicBookingService
# / PublicBookingAppointment (see /api/erp/booking-page*, ERP → Booking
# tab). Not duplicated here; the dashboard button added alongside these
# new tools links straight to that existing panel.
# ─────────────────────────────────────────────────────────────


# ─────────────────────────────────────────────────────────────
# ITEM 96: DIGITAL BUSINESS CARD / CONTACT EXCHANGE (NFC or QR)
# A real, standards-compliant vCard (.vcf) any phone can save straight
# to Contacts, plus a scannable QR code encoding the public card URL —
# tap-to-share (NFC) just means writing that same URL to an NFC tag with
# any phone's built-in NFC-write feature, which is a browser/OS action,
# not something a server can do — the URL itself is what's real here.
# ─────────────────────────────────────────────────────────────

class BusinessCard(db.Model):
    __tablename__ = "business_cards"
    id           = db.Column(db.Integer, primary_key=True)
    owner_id     = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, unique=True, index=True)
    slug         = db.Column(db.String(80), unique=True, nullable=False, index=True)
    full_name    = db.Column(db.String(120), nullable=False)
    job_title    = db.Column(db.String(120), nullable=True)
    company_name = db.Column(db.String(120), nullable=True)
    phone        = db.Column(db.String(32), nullable=True)
    email        = db.Column(db.String(200), nullable=True)
    website      = db.Column(db.String(200), nullable=True)
    updated_at   = db.Column(db.DateTime, default=datetime.utcnow, onupdate=datetime.utcnow)

    def to_dict(self):
        return {"slug": self.slug, "full_name": self.full_name, "job_title": self.job_title,
                "company_name": self.company_name, "phone": self.phone, "email": self.email,
                "website": self.website,
                "card_url": f"{APP_BASE_URL}/card/{self.slug}",
                "vcard_url": f"{APP_BASE_URL}/card/{self.slug}/vcard.vcf",
                "qr_url": f"{APP_BASE_URL}/card/{self.slug}/qr.png"}


def _card_slugify(name, owner_id):
    base = re.sub(r"[^a-z0-9]+", "-", (name or "user").lower()).strip("-") or "user"
    slug = base
    n = 1
    while BusinessCard.query.filter(BusinessCard.slug == slug, BusinessCard.owner_id != owner_id).first():
        n += 1
        slug = f"{base}-{n}"
    return slug


