def business_card_public_page(slug):
    card = BusinessCard.query.filter_by(slug=slug).first()
    if not card:
        return ("Card not found.", 404)
    branding = BusinessBranding.query.filter_by(owner_user_id=card.owner_id).first()
    primary = (branding.primary_color if branding and branding.primary_color else "#1e3a8a")
    accent = (branding.accent_color if branding and branding.accent_color else primary)
    logo_html = (f'<img src="{escape(branding.logo_url)}" alt="Logo" style="max-width:120px;max-height:60px;margin-bottom:12px;"/>'
                 if branding and branding.logo_url else "")
    # Real click-to-WhatsApp, only shown when the card owner has actually
    # set whatsapp_number on their account — never guessed from card.phone,
    # which was never confirmed to be a WhatsApp number.
    owner = UserAccount.query.get(card.owner_id)
    whatsapp_btn_html = ""
    if owner and owner.whatsapp_number:
        wa_digits = owner.whatsapp_number.lstrip("+")
        wa_text = quote(f"Hi {card.full_name}, I got your business card and would like to connect.")
        whatsapp_btn_html = (
            f'<a class="btn" style="background:#25d366;margin-top:8px;" '
            f'href="https://wa.me/{escape(wa_digits)}?text={wa_text}" target="_blank"> Message on WhatsApp</a>'
        )
    html = f"""<!DOCTYPE html><html><head><meta charset="utf-8"/>
<meta name="viewport" content="width=device-width, initial-scale=1"/>
<title>{escape(card.full_name)}</title>
<style>body{{font-family:Arial,sans-serif;background:#f1f5f9;display:flex;align-items:center;justify-content:center;
min-height:100vh;margin:0;}}
.card{{background:#fff;border-radius:16px;box-shadow:0 8px 32px rgba(0,0,0,.12);padding:32px;max-width:360px;text-align:center;
border-top:5px solid {escape(primary)};}}
.card h1{{font-size:1.3rem;margin:0 0 4px;color:#1e293b;}}
.card p{{margin:2px 0;color:#64748b;font-size:0.9rem;}}
.card img.qr{{margin:16px 0;}}
.card a.btn{{display:block;margin-top:14px;background:{escape(accent)};color:#fff;padding:12px;border-radius:10px;
text-decoration:none;font-weight:700;}}</style></head><body>
<div class="card">
{logo_html}
<h1>{escape(card.full_name)}</h1>
<p>{escape(card.job_title or "")}</p>
<p>{escape((branding.display_name if branding and branding.display_name else card.company_name) or "")}</p>
<img class="qr"src="/card/{escape(slug)}/qr.png" width="160" height="160" alt="QR code"/>
<p>{escape(card.phone or "")}</p>
<p>{escape(card.email or "")}</p>
<p>{escape(card.website or "")}</p>
<a class="btn" href="/card/{escape(slug)}/vcard.vcf">Save to Contacts</a>
{whatsapp_btn_html}
</div></body></html>"""
    return (html, 200, {"Content-Type": "text/html"})


@app.route("/card/<slug>/vcard.vcf", methods=["GET"])
def business_card_vcf(slug):
    card = BusinessCard.query.filter_by(slug=slug).first()
    if not card:
        return ("Card not found.", 404)
    branding = BusinessBranding.query.filter_by(owner_user_id=card.owner_id).first()
    org_name = card.company_name or (branding.display_name if branding else None)
    lines = ["BEGIN:VCARD", "VERSION:3.0", f"FN:{card.full_name}", f"N:{card.full_name};;;;"]
    if org_name:
        lines.append(f"ORG:{org_name}")
    if card.job_title:
        lines.append(f"TITLE:{card.job_title}")
    if card.phone:
        lines.append(f"TEL;TYPE=WORK,VOICE:{card.phone}")
    if card.email:
        lines.append(f"EMAIL:{card.email}")
    if card.website:
        lines.append(f"URL:{card.website}")
    lines.append("END:VCARD")
    vcf = "\r\n".join(lines)
    return (vcf, 200, {"Content-Type": "text/vcard", "Content-Disposition": f'attachment; filename="{slug}.vcf"'})


@app.route("/card/<slug>/qr.png", methods=["GET"])
def business_card_qr(slug):
    card = BusinessCard.query.filter_by(slug=slug).first()
    if not card:
        return ("Card not found.", 404)
    qr = qrcode.QRCode(error_correction=ERROR_CORRECT_M, box_size=8, border=2)
    qr.add_data(f"{APP_BASE_URL}/card/{slug}")
    qr.make(fit=True)
    img = qr.make_image(fill_color="black", back_color="white")
    buf = io.BytesIO()
    img.save(buf, format="PNG")
    buf.seek(0)
    return (buf.read(), 200, {"Content-Type": "image/png"})


# ─────────────────────────────────────────────────────────────
# ITEM 97: EMPLOYEE EXPENSE CARD ISSUANCE & SPEND CONTROLS
# Real card issuance (physical or virtual Visa/Mastercard numbers with
# live spend controls) needs a licensed card-issuing partner in the
# loop — Stripe Issuing, Marqeta, Highnote, etc. — with this account's
# own compliance/KYB approval on that partner's side. No such credential
# is configured here, so this is built the same honest way as the
# card-reader and payroll items: a real request queue that goes live
# the moment ISSUING credentials are added, not a fake "card issued"
# response.
# ─────────────────────────────────────────────────────────────

class ExpenseCardRequest(db.Model):
    __tablename__ = "expense_card_requests"
