    employee_name  = db.Column(db.String(120), nullable=False)
    employee_email = db.Column(db.String(200), nullable=True)
    card_type      = db.Column(db.String(10), nullable=False, default="virtual")  # virtual, physical
    monthly_limit  = db.Column(db.Float, nullable=True)
    status         = db.Column(db.String(20), nullable=False, default="queued")   # queued (no partner yet), issued
    created_at     = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        return {"id": self.id, "employee_name": self.employee_name, "employee_email": self.employee_email,
                "card_type": self.card_type, "monthly_limit": self.monthly_limit, "status": self.status,
                "created_at": self.created_at.isoformat() if self.created_at else None}


