@app.route("/api/internal-announcements/feed", methods=["GET"])
def internal_announcements_feed():
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    owner_ids = {user["id"]}
    for tm in TeamMember.query.filter_by(member_user_id=user["id"], status="active").all():
        owner_ids.add(tm.owner_user_id)
    rows = (Announcement.query.filter(Announcement.owner_id.in_(owner_ids))
            .order_by(Announcement.created_at.desc()).limit(50).all())
    read_ids = {r.announcement_id for r in
                AnnouncementReadReceipt.query.filter_by(reader_user_id=user["id"]).all()}
    out = []
    for r in rows:
        d = r.to_dict()
        d["read"] = r.id in read_ids
        out.append(d)
    return jsonify({"ok": True, "announcements": out}), 200


