@app.route("/api/vendor-contracts/<int:contract_id>", methods=["PATCH"])
@csrf.exempt
def vendor_contract_update(contract_id):
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    row = VendorContract.query.get(contract_id)
    if not row or row.owner_id != user["id"]:
        return jsonify({"error": "Not found."}), 404
    data = request.get_json(silent=True) or {}
    for field in ("vendor_name", "contract_title", "notes"):
        if field in data:
            setattr(row, field, (data[field] or "")[:2000] or None)
    if "start_date" in data:
        row.start_date = _parse_date(data["start_date"])
    if "end_date" in data:
        row.end_date = _parse_date(data["end_date"])
    if "renewal_reminder_days" in data:
        row.renewal_reminder_days = int(data["renewal_reminder_days"] or 30)
    if "status" in data and data["status"] in ("active", "expired", "cancelled"):
        row.status = data["status"]
    db.session.commit()
    return jsonify({"ok": True, "contract": row.to_dict()}), 200


