# ─────────────────────────────────────────────────────────────
# ITEM 100: CUSTOM DOMAIN & WHITE-LABEL EMAIL for a seller's storefront
# Domain OWNERSHIP verification is real: the seller uploads a small
# token file to their own domain root and this server fetches it over
# real HTTP to confirm they control it — the same technique Google
# Search Console / Let's Encrypt HTTP-01 challenges use. Actually
# ROUTING that domain (DNS A/CNAME to this app) and hosting real
# mailboxes at it needs the seller's own DNS provider and a real email
# host (Google Workspace, Zoho Mail, ImprovMX, etc.) — this app cannot
# register DNS records or provision mailboxes on someone else's domain,
# so those steps are given as real, correct instructions rather than
# simulated as already done.
# ─────────────────────────────────────────────────────────────

class CustomDomain(db.Model):
    __tablename__ = "custom_domains"
    id             = db.Column(db.Integer, primary_key=True)
    owner_id       = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, unique=True, index=True)
    domain         = db.Column(db.String(200), nullable=False, unique=True, index=True)
    verification_token = db.Column(db.String(48), nullable=False)
    verified       = db.Column(db.Boolean, default=False, nullable=False)
    verified_at    = db.Column(db.DateTime, nullable=True)
    white_label_email = db.Column(db.String(200), nullable=True)   # e.g. hello@theirdomain.com, once they host it
    created_at     = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        return {"id": self.id, "domain": self.domain, "verified": self.verified,
                "verified_at": self.verified_at.isoformat() if self.verified_at else None,
                "white_label_email": self.white_label_email,
                "verification_file_path": f"/.well-known/connectit-verify-{self.verification_token[:8]}.txt",
                "verification_token": self.verification_token,
                "cname_target": APP_BASE_URL.replace("https://", "").replace("http://", "")}


@app.route("/api/custom-domain/mine", methods=["GET"])
def custom_domain_mine():
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    row = CustomDomain.query.filter_by(owner_id=user["id"]).first()
    return jsonify({"ok": True, "domain": row.to_dict() if row else None}), 200


@app.route("/api/custom-domain", methods=["POST"])
@csrf.exempt
def custom_domain_register():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    domain = (data.get("domain") or "").strip().lower()
    domain = re.sub(r"^https?://", "", domain).strip("/")
    if not re.match(r"^[a-z0-9]([a-z0-9\-]{0,61}[a-z0-9])?(\.[a-z0-9]([a-z0-9\-]{0,61}[a-z0-9])?)+$", domain):
        return jsonify({"error": "Enter a valid domain, e.g. shop.example.com."}), 400
    row = CustomDomain.query.filter_by(owner_id=user["id"]).first()
    if not row:
        row = CustomDomain(owner_id=user["id"], domain=domain, verification_token=secrets.token_hex(16))
        db.session.add(row)
    else:
        if row.domain != domain:
            row.domain = domain
            row.verified = False
            row.verification_token = secrets.token_hex(16)
    db.session.commit()
    return jsonify({"ok": True, "domain": row.to_dict()}), 201


@app.route("/api/custom-domain/verify", methods=["POST"])
@csrf.exempt
def custom_domain_verify():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    row = CustomDomain.query.filter_by(owner_id=user["id"]).first()
    if not row:
        return jsonify({"error": "Register a domain first."}), 404
    check_url = f"http://{row.domain}/.well-known/connectit-verify-{row.verification_token[:8]}.txt"
    try:
        resp = requests.get(check_url, timeout=8)
        if resp.status_code == 200 and row.verification_token in resp.text:
            row.verified = True
            row.verified_at = datetime.utcnow()
            db.session.commit()
            return jsonify({"ok": True, "verified": True, "domain": row.to_dict()}), 200
        return jsonify({"ok": True, "verified": False,
                         "error": f"Fetched {check_url} but didn't find the token. Make sure the file "
                                  f"contains exactly: {row.verification_token}"}), 200
    except Exception as e:
        return jsonify({"ok": True, "verified": False,
                         "error": f"Could not reach {check_url}: {e}"}), 200


@app.route("/api/custom-domain/white-label-email", methods=["POST"])
@csrf.exempt
def custom_domain_white_label_email():
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    row = CustomDomain.query.filter_by(owner_id=user["id"]).first()
    if not row or not row.verified:
        return jsonify({"error": "Verify domain ownership before setting a white-label sender address."}), 400
    data = request.get_json(silent=True) or {}
    email = (data.get("email") or "").strip().lower()
    if not email.endswith("@" + row.domain):
        return jsonify({"error": f"Address must end in @{row.domain}."}), 400
    row.white_label_email = email
    db.session.commit()
    return jsonify({
        "ok": True, "domain": row.to_dict(),
        "note": ("Address saved and will be used as the Reply-To on your automated customer emails. "
                 "To actually SEND from it, point that domain's MX records at a real mailbox host "
                 "(Google Workspace, Zoho Mail, ImprovMX, etc.) — this app can't create mailboxes on "
                 "your domain, only your DNS provider and a mail host can."),
    }), 200


# ════════════════════════════════════════════════════════════════════
# MANUFACTURING & PHYSICAL OPERATIONS MODULE
# Ten features for shop-floor / warehouse users, all scoped to
# owner_user_id (same one-business-per-account pattern as the rest of
# the ERP). Reuses InventoryItem as the product/part catalog (it
# already carries sku/barcode/quantity), ErpSupplier + ErpPurchaseOrder
# for the supplier scorecard, and TraceabilityLedgerEntry.batch_lot_number
# (added above) for batch/lot traceability, rather than duplicating any
# of those tables.
#
# New tables here need one `db.create_all()` pass — handled by the
# app_context block at the bottom of this section, same pattern used
# earlier in this file for tables added after the first create_all().
# ════════════════════════════════════════════════════════════════════

# ---- 4. Equipment / asset tagging + maintenance history (machinery, tools) ----
class ManufacturingEquipment(db.Model):
    __tablename__ = "mfg_equipment"
    id              = db.Column(db.Integer, primary_key=True)
    owner_user_id   = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    name            = db.Column(db.String(160), nullable=False)
    asset_tag       = db.Column(db.String(80),  nullable=True, index=True)  # printed/scanned tag or QR code
    category        = db.Column(db.String(60),  nullable=False, default="machine")  # machine, tool, fixture, other
    location        = db.Column(db.String(160), nullable=True)
    line_name       = db.Column(db.String(120), nullable=True)  # production line it's assigned to, if any
    status          = db.Column(db.String(20),  nullable=False, default="operational")  # operational, down, maintenance, retired
    purchase_date   = db.Column(db.Date, nullable=True)
    last_service_at = db.Column(db.Date, nullable=True)
    service_interval_days = db.Column(db.Integer, nullable=True)  # e.g. 90 -> flagged due every 90 days
    notes           = db.Column(db.Text, nullable=True)
    created_at      = db.Column(db.DateTime, default=datetime.utcnow)

    def service_due(self):
        if not self.service_interval_days or not self.last_service_at:
            return False
        return (datetime.utcnow().date() - self.last_service_at).days >= self.service_interval_days

    def to_dict(self):
        return {
            "id": self.id, "name": self.name, "asset_tag": self.asset_tag, "category": self.category,
            "location": self.location, "line_name": self.line_name, "status": self.status,
            "purchase_date": self.purchase_date.isoformat() if self.purchase_date else None,
            "last_service_at": self.last_service_at.isoformat() if self.last_service_at else None,
            "service_interval_days": self.service_interval_days, "service_due": self.service_due(),
            "notes": self.notes,
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }


class EquipmentMaintenanceLog(db.Model):
    __tablename__ = "mfg_equipment_maintenance_logs"
    id             = db.Column(db.Integer, primary_key=True)
    equipment_id   = db.Column(db.Integer, db.ForeignKey("mfg_equipment.id"), nullable=False, index=True)
    owner_user_id  = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    performed_on   = db.Column(db.Date, nullable=False)
    performed_by   = db.Column(db.String(120), nullable=True)
    work_type      = db.Column(db.String(20), nullable=False, default="preventive")  # preventive, repair, inspection
    description    = db.Column(db.Text, nullable=True)
    cost           = db.Column(db.Float, nullable=True)
    created_at     = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        return {
            "id": self.id, "equipment_id": self.equipment_id,
            "performed_on": self.performed_on.isoformat() if self.performed_on else None,
            "performed_by": self.performed_by, "work_type": self.work_type,
            "description": self.description, "cost": self.cost,
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }


