@app.route("/api/mfg/dashboard", methods=["GET"])
def mfg_dashboard():
    """Real-time factory floor view: today's output vs target per line,
    plus open downtime events and equipment currently marked down —
    everything a floor supervisor needs on one screen."""
    user, err = _erp_user_or_401()
    if err: return err
    today = datetime.utcnow().date()
    runs = ProductionRun.query.filter_by(owner_user_id=user["id"], run_date=today).all()
    open_downtime = (ProductionDowntimeEvent.query
                      .filter_by(owner_user_id=user["id"])
                      .filter(ProductionDowntimeEvent.ended_at.is_(None)).all())
    down_equipment = ManufacturingEquipment.query.filter_by(owner_user_id=user["id"], status="down").all()
    total_target = sum(r.target_qty for r in runs)
    total_actual = sum(r.actual_qty for r in runs)
    return jsonify({
        "date": today.isoformat(),
        "lines": [r.to_dict() for r in runs],
        "total_target": total_target, "total_actual": total_actual,
        "total_pct_of_target": round((total_actual / total_target) * 100, 1) if total_target else None,
        "open_downtime_events": [d.to_dict() for d in open_downtime],
        "equipment_down": [e.to_dict() for e in down_equipment],
    }), 200


