class CycleCountSession(db.Model):
    __tablename__ = "mfg_cycle_count_sessions"
    id             = db.Column(db.Integer, primary_key=True)
    owner_user_id  = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    location       = db.Column(db.String(160), nullable=True)
    started_by     = db.Column(db.String(120), nullable=True)
    status         = db.Column(db.String(20), nullable=False, default="open")  # open, completed
    started_at     = db.Column(db.DateTime, default=datetime.utcnow)
    completed_at   = db.Column(db.DateTime, nullable=True)

    def to_dict(self, include_entries=False):
        d = {
            "id": self.id, "location": self.location, "started_by": self.started_by, "status": self.status,
            "started_at": self.started_at.isoformat() if self.started_at else None,
            "completed_at": self.completed_at.isoformat() if self.completed_at else None,
        }
        if include_entries:
            entries = CycleCountEntry.query.filter_by(session_id=self.id).all()
            d["entries"] = [e.to_dict() for e in entries]
            d["total_variance"] = round(sum(e.variance() for e in entries), 2)
        return d


class CycleCountEntry(db.Model):
    __tablename__ = "mfg_cycle_count_entries"
    id             = db.Column(db.Integer, primary_key=True)
    session_id     = db.Column(db.Integer, db.ForeignKey("mfg_cycle_count_sessions.id"), nullable=False, index=True)
    item_id        = db.Column(db.Integer, db.ForeignKey("inventory_items.id"), nullable=False, index=True)
    scanned_barcode = db.Column(db.String(64), nullable=True)
    system_qty     = db.Column(db.Float, nullable=False, default=0)
    counted_qty    = db.Column(db.Float, nullable=False, default=0)
    counted_at     = db.Column(db.DateTime, default=datetime.utcnow)

    def variance(self):
        return (self.counted_qty or 0) - (self.system_qty or 0)

    def to_dict(self):
        item = InventoryItem.query.get(self.item_id)
        return {
            "id": self.id, "session_id": self.session_id, "item_id": self.item_id,
            "item_name": item.name if item else None,
            "scanned_barcode": self.scanned_barcode,
            "system_qty": self.system_qty, "counted_qty": self.counted_qty, "variance": self.variance(),
            "counted_at": self.counted_at.isoformat() if self.counted_at else None,
        }


