@app.route("/api/mfg/cycle-counts/sessions/<int:session_id>/scan", methods=["POST"])
@csrf.exempt
def mfg_cycle_sessions_scan(session_id):
    """Called once per scanned barcode (or manually typed code). Looks the
    item up by InventoryItem.barcode or .sku, records the counted qty
    against the current system qty, and — when requested — reconciles
    the live stock level so the count actually corrects inventory."""
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    session_row = CycleCountSession.query.filter_by(id=session_id, owner_user_id=user["id"]).first()
    if not session_row: return jsonify({"error": "Session not found."}), 404
    data = request.get_json(silent=True) or {}
    code = (data.get("barcode") or "").strip()
    item = None
    if code:
        item = InventoryItem.query.filter_by(user_id=user["id"], barcode=code).first() \
            or InventoryItem.query.filter_by(user_id=user["id"], sku=code).first()
    if not item and data.get("item_id"):
        item = InventoryItem.query.filter_by(id=data.get("item_id"), user_id=user["id"]).first()
    if not item:
        return jsonify({"error": "No product on file with that barcode/SKU."}), 404
    counted_qty = float(data.get("counted_qty") or 0)
    entry = CycleCountEntry(
        session_id=session_id, item_id=item.id, scanned_barcode=code or None,
        system_qty=item.quantity or 0, counted_qty=counted_qty,
    )
    db.session.add(entry)
    if data.get("reconcile"):
        item.quantity = counted_qty
    db.session.commit()
    return jsonify({"ok": True, "entry": entry.to_dict(), "reconciled": bool(data.get("reconcile"))}), 201


@app.route("/api/mfg/cycle-counts/sessions/<int:session_id>/complete", methods=["POST"])
@csrf.exempt
def mfg_cycle_sessions_complete(session_id):
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    row = CycleCountSession.query.filter_by(id=session_id, owner_user_id=user["id"]).first()
    if not row: return jsonify({"error": "Session not found."}), 404
    row.status = "completed"
    row.completed_at = datetime.utcnow()
    db.session.commit()
    return jsonify({"ok": True, "session": row.to_dict(include_entries=True)}), 200


# ---- 7. Supplier scorecard automation from real delivery/quality data ----
@app.route("/api/mfg/supplier-scorecard", methods=["GET"])
def mfg_supplier_scorecard_all():
    user, err = _erp_user_or_401()
    if err: return err
    suppliers = ErpSupplier.query.filter_by(owner_user_id=user["id"]).order_by(ErpSupplier.name).all()
    return jsonify({"suppliers": [_mfg_compute_supplier_scorecard(user["id"], s) for s in suppliers]}), 200


@app.route("/api/mfg/supplier-scorecard/<int:supplier_id>", methods=["GET"])
def mfg_supplier_scorecard_one(supplier_id):
    user, err = _erp_user_or_401()
    if err: return err
    supplier = ErpSupplier.query.filter_by(id=supplier_id, owner_user_id=user["id"]).first()
    if not supplier: return jsonify({"error": "Supplier not found."}), 404
    return jsonify({"scorecard": _mfg_compute_supplier_scorecard(user["id"], supplier)}), 200


def _mfg_compute_supplier_scorecard(owner_user_id, supplier):
    """Computed live from real records every time it's requested — never
    a stored number that can drift: on-time delivery % from actual PO
    expected-vs-received dates, and quality pass-rate from real QC
    inspections tagged to this supplier's incoming goods."""
    pos = (ErpPurchaseOrder.query
           .filter_by(owner_user_id=owner_user_id, supplier_id=supplier.id)
           .filter(ErpPurchaseOrder.status == "received").all())
    on_time = 0
    dated = [p for p in pos if p.expected_date and p.received_at]
    for p in dated:
        if p.received_at.date() <= p.expected_date:
            on_time += 1
    on_time_pct = round((on_time / len(dated)) * 100, 1) if dated else None

    inspections = QcInspection.query.filter_by(owner_user_id=owner_user_id, supplier_id=supplier.id).all()
    passed = sum(1 for i in inspections if i.overall_result == "pass")
    quality_pct = round((passed / len(inspections)) * 100, 1) if inspections else None

    score = None
    parts = [v for v in (on_time_pct, quality_pct) if v is not None]
    if parts:
        score = round(sum(parts) / len(parts), 1)

    return {
        "supplier_id": supplier.id, "supplier_name": supplier.name,
        "purchase_orders_received": len(pos),
        "on_time_delivery_pct": on_time_pct,
        "quality_inspections": len(inspections),
        "quality_pass_pct": quality_pct,
        "overall_score": score,
    }


# ---- 8. Automated reorder point calculation from real consumption data ----
class InventoryConsumptionLog(db.Model):
    __tablename__ = "mfg_inventory_consumption_logs"
    id             = db.Column(db.Integer, primary_key=True)
    owner_user_id  = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    item_id        = db.Column(db.Integer, db.ForeignKey("inventory_items.id"), nullable=False, index=True)
    quantity       = db.Column(db.Float, nullable=False, default=0)
    consumed_on    = db.Column(db.Date, nullable=False, default=lambda: datetime.utcnow().date())
    line_name      = db.Column(db.String(120), nullable=True)
    created_at     = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        return {
            "id": self.id, "item_id": self.item_id, "quantity": self.quantity,
            "consumed_on": self.consumed_on.isoformat() if self.consumed_on else None,
            "line_name": self.line_name,
        }


