@csrf.exempt
def mfg_consumption_add():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    item = InventoryItem.query.filter_by(id=data.get("item_id"), user_id=user["id"]).first()
    if not item:
        return jsonify({"error": "Inventory item not found."}), 404
    qty = float(data.get("quantity") or 0)
    row = InventoryConsumptionLog(
        owner_user_id=user["id"], item_id=item.id, quantity=qty,
        consumed_on=_erp_parse_date(data.get("consumed_on"), default=datetime.utcnow().date()),
        line_name=(data.get("line_name") or "").strip() or None,
    )
    item.quantity = max(0, (item.quantity or 0) - qty)
    db.session.add(row)
    db.session.commit()
    return jsonify({"ok": True, "log": row.to_dict(), "item": item.to_dict()}), 201


@app.route("/api/mfg/reorder-suggestions", methods=["GET"])
def mfg_reorder_suggestions():
    """Reorder point = average daily consumption over the lookback window
    * lead-time days, plus a safety-stock buffer — computed from this
    account's own logged consumption, not a guess. Items below their
    computed reorder point (or the manual threshold, if no consumption
    history yet) are flagged."""
    user, err = _erp_user_or_401()
    if err: return err
    lead_time_days = int(request.args.get("lead_time_days", 7))
    lookback_days = int(request.args.get("lookback_days", 30))
    safety_stock_days = int(request.args.get("safety_stock_days", 3))
    since = datetime.utcnow().date() - timedelta(days=lookback_days)

    items = InventoryItem.query.filter_by(user_id=user["id"], active=True).all()
    suggestions = []
    for item in items:
        logs = (InventoryConsumptionLog.query
                .filter(InventoryConsumptionLog.owner_user_id == user["id"],
                        InventoryConsumptionLog.item_id == item.id,
                        InventoryConsumptionLog.consumed_on >= since).all())
        total_consumed = sum(l.quantity for l in logs)
        avg_daily = round(total_consumed / lookback_days, 3) if logs else None
        if avg_daily:
            reorder_point = round(avg_daily * (lead_time_days + safety_stock_days), 1)
        else:
            reorder_point = item.threshold or 0
        if (item.quantity or 0) <= reorder_point:
            suggestions.append({
                "item_id": item.id, "item_name": item.name, "current_qty": item.quantity,
                "avg_daily_consumption": avg_daily, "computed_reorder_point": reorder_point,
                "based_on_consumption_history": bool(logs),
                "suggested_order_qty": max(0, round(reorder_point * 2 - (item.quantity or 0), 1)),
            })
    return jsonify({"lead_time_days": lead_time_days, "lookback_days": lookback_days,
                     "safety_stock_days": safety_stock_days, "suggestions": suggestions}), 200


