@app.route("/api/mfg/transfers", methods=["POST"])
@csrf.exempt
def mfg_transfers_create():
    """Moves stock between locations. A transfer with no from_location_id
    is treated as coming from the main (unallocated) pool tracked on
    InventoryItem.quantity itself; a transfer between two named locations
    moves quantity out of one InventoryLocationStock row and into another."""
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    item = InventoryItem.query.filter_by(id=data.get("item_id"), user_id=user["id"]).first()
    if not item:
        return jsonify({"error": "Inventory item not found."}), 404
    to_location = InventoryLocation.query.filter_by(id=data.get("to_location_id"), owner_user_id=user["id"]).first()
    if not to_location:
        return jsonify({"error": "Destination location not found."}), 404
    qty = float(data.get("quantity") or 0)
    if qty <= 0:
        return jsonify({"error": "Transfer quantity must be greater than zero."}), 400

    from_location_id = data.get("from_location_id") or None
    if from_location_id:
        from_location = InventoryLocation.query.filter_by(id=from_location_id, owner_user_id=user["id"]).first()
        if not from_location:
            return jsonify({"error": "Source location not found."}), 404
        from_row = _mfg_location_stock_row(user["id"], from_location.id, item.id)
        if (from_row.quantity or 0) < qty:
            return jsonify({"error": "Not enough stock at the source location for this transfer."}), 400
        from_row.quantity -= qty
    else:
        if (item.quantity or 0) < qty:
            return jsonify({"error": "Not enough unallocated stock for this transfer."}), 400
        item.quantity -= qty

    to_row = _mfg_location_stock_row(user["id"], to_location.id, item.id)
    to_row.quantity += qty

    transfer = StockTransfer(
        owner_user_id=user["id"], item_id=item.id, from_location_id=from_location_id,
        to_location_id=to_location.id, quantity=qty,
        requested_by=(data.get("requested_by") or "").strip() or None,
    )
    db.session.add(transfer)
    db.session.commit()
    return jsonify({"ok": True, "transfer": transfer.to_dict()}), 201


