# ===========================================================
# SECURITY, IT & ACCESS MANAGEMENT MODULE
# Round 3, category 8 (features 71-80): SSO/SAML, RBAC, IP
# allow-listing & device management, security event log,
# DLP export rules, automated backup/restore, vendor app
# access review, session management, compliance evidence
# vault, self-service API keys. Same pattern as every other
# post-launch module in this file: owner_user_id-scoped
# tables, _erp_user_or_401() auth, _csrf_ok() on writes,
# db.create_all() picks these up with the rest below.
# ===========================================================

# pip install python3-saml — real SAML 2.0 assertion validator.
# Deliberately not hand-rolled: a slightly-wrong XML signature
# check would silently accept forged assertions. Degrades
# gracefully — without it, SSO config can still be stored and
# the SP metadata can still be handed to an IdP, but the actual
# ACS callback returns a clear 503 instead of doing unsafe
# unverified XML parsing.
try:
    from onelogin.saml2.auth import OneLogin_Saml2_Auth
    from onelogin.saml2.settings import OneLogin_Saml2_Settings
    SAML_AVAILABLE = True
    logging.info("[OK] python3-saml loaded — SSO/SAML ACS validation ready.")
except ImportError:
    SAML_AVAILABLE = False
    logging.warning("[SKIP] python3-saml not installed. Run: pip install python3-saml — "
                     "SSO config/metadata still work, ACS callback returns 503 until then.")


def _sec_owner_scope_or_404(model, row_id, owner_user_id):
    row = model.query.filter_by(id=row_id, owner_user_id=owner_user_id).first()
    return row


def _sec_log_event(owner_user_id, event_type, description=None, severity="info"):
    """Fire-and-forget security event write. Never raises."""
    try:
        row = SecurityEvent(
            owner_user_id=owner_user_id, event_type=event_type, severity=severity,
            description=description,
            ip_address=(request.headers.get("X-Forwarded-For", request.remote_addr) if request else None),
            user_agent=(request.headers.get("User-Agent", "")[:255] if request else None),
        )
        db.session.add(row)
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        logging.error(f"[SECURITY EVENT LOG ERROR] {event_type}: {e}")


# ---- 1. SSO / SAML config for enterprise seller accounts ----
class SsoConfig(db.Model):
    __tablename__ = "security_sso_configs"
    id              = db.Column(db.Integer, primary_key=True)
    owner_user_id   = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, unique=True, index=True)
    enabled         = db.Column(db.Boolean, default=False)
    enforce_sso     = db.Column(db.Boolean, default=False)  # require SSO, block password login
    idp_entity_id   = db.Column(db.String(500), nullable=True)
    idp_sso_url     = db.Column(db.String(500), nullable=True)
    idp_x509_cert   = db.Column(db.Text, nullable=True)
    sp_entity_id    = db.Column(db.String(255), nullable=True)
    created_at      = db.Column(db.DateTime, default=datetime.utcnow)
    updated_at      = db.Column(db.DateTime, default=datetime.utcnow, onupdate=datetime.utcnow)

    def to_dict(self):
        return {
            "id": self.id, "enabled": self.enabled, "enforce_sso": self.enforce_sso,
            "idp_entity_id": self.idp_entity_id, "idp_sso_url": self.idp_sso_url,
            "idp_x509_cert_set": bool(self.idp_x509_cert),
            "sp_entity_id": self.sp_entity_id or f"connectit-ai-seller-{self.owner_user_id}",
            "acs_url": (request.host_url.rstrip("/") + "/api/security/sso/acs") if request else None,
            "saml_library_available": SAML_AVAILABLE,
            "updated_at": self.updated_at.isoformat() if self.updated_at else None,
        }


