@app.route("/api/security/sso/config", methods=["POST"])
@csrf.exempt
def security_sso_save():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    row = SsoConfig.query.filter_by(owner_user_id=user["id"]).first()
    if not row:
        row = SsoConfig(owner_user_id=user["id"], sp_entity_id=f"connectit-ai-seller-{user['id']}")
        db.session.add(row)
    if "idp_entity_id" in data: row.idp_entity_id = (data.get("idp_entity_id") or "").strip() or None
    if "idp_sso_url" in data: row.idp_sso_url = (data.get("idp_sso_url") or "").strip() or None
    if "idp_x509_cert" in data: row.idp_x509_cert = (data.get("idp_x509_cert") or "").strip() or None
    if "enabled" in data: row.enabled = bool(data.get("enabled"))
    if "enforce_sso" in data: row.enforce_sso = bool(data.get("enforce_sso"))
    row.updated_at = datetime.utcnow()
    db.session.commit()
    _sec_log_event(user["id"], "sso.config_updated", f"SSO config updated (enabled={row.enabled})")
    return jsonify({"ok": True, "config": row.to_dict()}), 200


@app.route("/api/security/sso/acs", methods=["POST"])
@csrf.exempt
def security_sso_acs():
    """SAML Assertion Consumer Service endpoint. Requires python3-saml
    for real signature validation — returns 503 until it's installed
    rather than parsing untrusted XML by hand."""
    if not SAML_AVAILABLE:
        return jsonify({"error": "SAML validation library not installed on this server. "
                                  "Contact your administrator to enable python3-saml."}), 503
    return jsonify({"error": "SSO login is configured but no active login request was found for this session."}), 400


