    data = request.get_json(silent=True) or {}
    name = (data.get("name") or "").strip()
    if not name:
        return jsonify({"error": "Role name is required."}), 400
    perms = [p for p in (data.get("permissions") or []) if p in SECURITY_PERMISSION_CATALOG]
    row = SecurityRole(owner_user_id=user["id"], name=name, permissions_json=json.dumps(perms))
    db.session.add(row)
