    user, err = _erp_user_or_401()
    if err: return err
    row = _sec_owner_scope_or_404(SecurityRole, role_id, user["id"])
    if not row:
        return jsonify({"error": "Role not found."}), 404
    data = request.get_json(silent=True) or {}
    if "name" in data and (data.get("name") or "").strip():
        row.name = data["name"].strip()
    if "permissions" in data:
        perms = [p for p in (data.get("permissions") or []) if p in SECURITY_PERMISSION_CATALOG]
        row.permissions_json = json.dumps(perms)
    db.session.commit()
    _sec_log_event(user["id"], "rbac.role_updated", f"Role '{row.name}' updated")
    return jsonify({"ok": True, "role": row.to_dict()}), 200


