@app.route("/api/security/allowed-ips", methods=["POST"])
@csrf.exempt
def security_allowed_ips_add():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    cidr = (data.get("cidr") or "").strip()
    if not cidr:
        return jsonify({"error": "An IP address or CIDR range is required."}), 400
    import ipaddress
    try:
        ipaddress.ip_network(cidr, strict=False)
    except Exception:
        return jsonify({"error": "That doesn't look like a valid IP address or CIDR range."}), 400
    row = SecurityAllowedIp(owner_user_id=user["id"], cidr=cidr, label=(data.get("label") or "").strip() or None)
    db.session.add(row)
    db.session.commit()
    _sec_log_event(user["id"], "security.ip_allowed_added", f"Allow-listed {cidr}")
    return jsonify({"ok": True, "entry": row.to_dict()}), 201


