@csrf.exempt
def security_devices_register():
    """Called client-side with a browser fingerprint so this device shows
    up in the list; a first-seen device is unrecognized until the user
    marks it trusted."""
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    fingerprint = (data.get("fingerprint") or "").strip()
    if not fingerprint:
        return jsonify({"error": "fingerprint is required."}), 400
    ip = request.headers.get("X-Forwarded-For", request.remote_addr)
    row = SecurityTrustedDevice.query.filter_by(owner_user_id=user["id"], fingerprint=fingerprint).first()
    is_new = row is None
    if not row:
        row = SecurityTrustedDevice(owner_user_id=user["id"], fingerprint=fingerprint,
                                     device_label=(data.get("device_label") or "").strip() or None)
        db.session.add(row)
    row.last_seen_at = datetime.utcnow()
    row.last_ip = ip
    db.session.commit()
    if is_new:
        _sec_log_event(user["id"], "security.new_device_seen", f"New device seen from {ip}", severity="warning")
    return jsonify({"ok": True, "device": row.to_dict(), "is_new": is_new}), 200


