@app.route("/api/security/dlp-rules/scan", methods=["POST"])
@csrf.exempt
def security_dlp_rules_scan():
    """Runs a piece of text (e.g. a document about to be exported)
    against the seller's active DLP rules."""
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    text = (data.get("text") or "")
    rules = SecurityDlpRule.query.filter_by(owner_user_id=user["id"], enabled=True).all()
    hits = []
    for r in rules:
        try:
            if re.search(r.keyword_pattern, text, re.IGNORECASE):
                hits.append({"rule_id": r.id, "rule_name": r.name, "action": r.action})
        except re.error:
            if r.keyword_pattern.lower() in text.lower():
                hits.append({"rule_id": r.id, "rule_name": r.name, "action": r.action})
    blocked = any(h["action"] == "block" for h in hits)
    if hits:
        _sec_log_event(user["id"], "dlp.export_flagged", f"{len(hits)} DLP rule(s) matched on export", severity="warning")
    return jsonify({"ok": True, "blocked": blocked, "matches": hits}), 200


# ---- 6. Automated backup and point-in-time account restore ----
class SecurityBackupSnapshot(db.Model):
    __tablename__ = "security_backups"
    id            = db.Column(db.Integer, primary_key=True)
    owner_user_id = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    label         = db.Column(db.String(120), nullable=True)
    snapshot_json = db.Column(db.Text, nullable=True)
    size_bytes    = db.Column(db.Integer, default=0)
    status        = db.Column(db.String(20), default="completed")  # completed, restored
    created_at    = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        return {
            "id": self.id, "label": self.label or self.created_at.strftime("Snapshot %Y-%m-%d %H:%M"),
            "size_bytes": self.size_bytes, "status": self.status,
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }


def _sec_build_account_snapshot(user_id):
    """Best-effort snapshot of the seller's own account settings —
    profile fields plus counts of key business records, so a restore
    can compare state without pulling every row of every table into one
    blob."""
    u = UserAccount.query.get(user_id)
    snapshot = {
        "profile": {"name": u.name, "email": u.email, "plan": u.plan} if u else None,
        "roles": [r.to_dict() for r in SecurityRole.query.filter_by(owner_user_id=user_id).all()],
        "allowed_ips": [r.to_dict() for r in SecurityAllowedIp.query.filter_by(owner_user_id=user_id).all()],
        "dlp_rules": [r.to_dict() for r in SecurityDlpRule.query.filter_by(owner_user_id=user_id).all()],
        "captured_at": datetime.utcnow().isoformat(),
    }
    return snapshot


@app.route("/api/security/backups", methods=["GET"])
def security_backups_list():
    user, err = _erp_user_or_401()
    if err: return err
    rows = SecurityBackupSnapshot.query.filter_by(owner_user_id=user["id"]).order_by(SecurityBackupSnapshot.created_at.desc()).limit(50).all()
    return jsonify({"backups": [r.to_dict() for r in rows]}), 200


@app.route("/api/security/backups", methods=["POST"])
@csrf.exempt
def security_backups_create():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    snapshot = _sec_build_account_snapshot(user["id"])
    blob = json.dumps(snapshot)
    row = SecurityBackupSnapshot(
        owner_user_id=user["id"], label=(data.get("label") or "").strip() or None,
        snapshot_json=blob, size_bytes=len(blob.encode("utf-8")),
    )
    db.session.add(row)
    db.session.commit()
    _sec_log_event(user["id"], "backup.created", f"Backup snapshot #{row.id} created")
    return jsonify({"ok": True, "backup": row.to_dict()}), 201


@app.route("/api/security/backups/<int:backup_id>/restore", methods=["POST"])
@csrf.exempt
def security_backups_restore(backup_id):
    """Point-in-time restore: re-applies the roles, allow-listed IPs, and
    DLP rules that were captured in this snapshot. Order records
    (orders, invoices, etc.) are never rolled back this way — this
    covers account/security configuration only."""
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    row = _sec_owner_scope_or_404(SecurityBackupSnapshot, backup_id, user["id"])
    if not row:
        return jsonify({"error": "Backup not found."}), 404
    try:
        snapshot = json.loads(row.snapshot_json or "{}")
    except Exception:
        return jsonify({"error": "Snapshot data is corrupted and cannot be restored."}), 400

    SecurityRole.query.filter_by(owner_user_id=user["id"]).delete()
    for r in (snapshot.get("roles") or []):
        db.session.add(SecurityRole(owner_user_id=user["id"], name=r.get("name", "Role"),
                                     permissions_json=json.dumps(r.get("permissions") or [])))
    SecurityAllowedIp.query.filter_by(owner_user_id=user["id"]).delete()
    for ip in (snapshot.get("allowed_ips") or []):
        db.session.add(SecurityAllowedIp(owner_user_id=user["id"], cidr=ip.get("cidr"), label=ip.get("label")))
    SecurityDlpRule.query.filter_by(owner_user_id=user["id"]).delete()
    for d in (snapshot.get("dlp_rules") or []):
        db.session.add(SecurityDlpRule(owner_user_id=user["id"], name=d.get("name", "Rule"),
                                        keyword_pattern=d.get("keyword_pattern", ""), action=d.get("action", "flag"),
                                        enabled=d.get("enabled", True)))
    row.status = "restored"
    db.session.commit()
    _sec_log_event(user["id"], "backup.restored", f"Restored from backup #{row.id}", severity="warning")
    return jsonify({"ok": True, "message": "Account security configuration restored from this snapshot."}), 200


