# ---- 8. Session management — view and revoke active logins ----
@app.route("/api/security/sessions", methods=["GET"])
def security_sessions_list():
    user, err = _erp_user_or_401()
    if err: return err
    current_token = ""
    auth_header = request.headers.get("Authorization", "")
    if auth_header.startswith("Bearer "):
        current_token = auth_header[7:].strip()
    rows = AuthSessionToken.query.filter_by(user_id=user["id"]).order_by(AuthSessionToken.last_used_at.desc()).all()
    out = []
    for r in rows:
        out.append({
            "token_id": r.token[:8] + "…",
            "is_current": (r.token == current_token),
            "created_at": r.created_at.isoformat() if r.created_at else None,
            "last_used_at": r.last_used_at.isoformat() if r.last_used_at else None,
            "_full_token": r.token,  # used client-side only to target revoke; stripped below
        })
    # Never send full tokens back over the wire.
    for o in out:
        o.pop("_full_token", None)
    return jsonify({"sessions": out, "count": len(out)}), 200


@app.route("/api/security/sessions/revoke-others", methods=["POST"])
@csrf.exempt
def security_sessions_revoke_others():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    current_token = ""
    auth_header = request.headers.get("Authorization", "")
    if auth_header.startswith("Bearer "):
        current_token = auth_header[7:].strip()
    rows = AuthSessionToken.query.filter_by(user_id=user["id"]).all()
    revoked = 0
    for r in rows:
        if r.token != current_token:
            user_store.pop(r.token, None)
            db.session.delete(r)
            revoked += 1
    db.session.commit()
    _sec_log_event(user["id"], "session.revoked_others", f"{revoked} other session(s) revoked", severity="warning")
    return jsonify({"ok": True, "revoked": revoked}), 200


