@app.route("/api/security/compliance/collect", methods=["POST"])
@csrf.exempt
def security_compliance_collect():
    """Auto-collects a point-in-time compliance snapshot from the
    seller's own real security config — role/permission counts, backup
    recency, open security events, IP allow-list state. Not a
    third-party SOC2/ISO certification; it's the evidence a real
    auditor would ask to see."""
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    uid = user["id"]
    role_count = SecurityRole.query.filter_by(owner_user_id=uid).count()
    ip_count = SecurityAllowedIp.query.filter_by(owner_user_id=uid).count()
    last_backup = SecurityBackupSnapshot.query.filter_by(owner_user_id=uid).order_by(SecurityBackupSnapshot.created_at.desc()).first()
    open_critical_events = SecurityEvent.query.filter_by(owner_user_id=uid, severity="critical").count()
    sso_row = SsoConfig.query.filter_by(owner_user_id=uid).first()
    active_sessions = AuthSessionToken.query.filter_by(user_id=uid).count()

    evidence = {
        "access_control": {"roles_defined": role_count, "sso_enabled": bool(sso_row and sso_row.enabled)},
        "network_security": {"ip_allow_list_entries": ip_count},
        "backup_recovery": {
            "last_backup_at": last_backup.created_at.isoformat() if last_backup else None,
            "has_recent_backup": bool(last_backup and (datetime.utcnow() - last_backup.created_at) < timedelta(days=30)),
        },
        "monitoring": {"open_critical_events": open_critical_events, "active_sessions": active_sessions},
    }
    row = SecurityComplianceArtifact(
        owner_user_id=uid, category="periodic_review",
        title=f"Compliance snapshot — {datetime.utcnow().strftime('%Y-%m-%d')}",
        evidence_json=json.dumps(evidence),
    )
    db.session.add(row)
    db.session.commit()
    return jsonify({"ok": True, "artifact": row.to_dict()}), 201


# ---- 10. Rate-limited self-service API key management ----
class SecurityApiKey(db.Model):
    __tablename__ = "security_api_keys"
    id                  = db.Column(db.Integer, primary_key=True)
    owner_user_id       = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    label               = db.Column(db.String(120), nullable=True)
    key_prefix          = db.Column(db.String(16), nullable=False)
    key_hash            = db.Column(db.String(128), nullable=False)
    scopes              = db.Column(db.String(255), default="read")
    rate_limit_per_min  = db.Column(db.Integer, default=60)
    created_at          = db.Column(db.DateTime, default=datetime.utcnow)
    last_used_at        = db.Column(db.DateTime, nullable=True)
    revoked_at          = db.Column(db.DateTime, nullable=True)

    def to_dict(self):
        return {
            "id": self.id, "label": self.label or "Untitled key",
            "key_prefix": self.key_prefix, "masked_key": self.key_prefix + "…" + "•" * 24,
            "scopes": (self.scopes or "").split(",") if self.scopes else [],
            "rate_limit_per_min": self.rate_limit_per_min,
            "created_at": self.created_at.isoformat() if self.created_at else None,
            "last_used_at": self.last_used_at.isoformat() if self.last_used_at else None,
            "revoked": bool(self.revoked_at),
        }


# In-process sliding-window throttle keyed by key id. Best-effort, like
# the other in-memory caches in this file (e.g. user_store) — resets per
# worker, which is an acceptable tradeoff for a self-service dev-key
# limit rather than a hard billing boundary.
_sec_api_key_hits = defaultdict(list)
_sec_api_key_lock = threading.Lock()


def security_api_key_rate_limited(key_row):
    now = time.time()
    window_start = now - 60
    with _sec_api_key_lock:
        hits = [t for t in _sec_api_key_hits[key_row.id] if t > window_start]
        hits.append(now)
        _sec_api_key_hits[key_row.id] = hits
        return len(hits) > (key_row.rate_limit_per_min or 60)


@app.route("/api/security/api-keys", methods=["GET"])
def security_api_keys_list():
    user, err = _erp_user_or_401()
    if err: return err
    rows = SecurityApiKey.query.filter_by(owner_user_id=user["id"]).order_by(SecurityApiKey.created_at.desc()).all()
    return jsonify({"keys": [r.to_dict() for r in rows]}), 200


@app.route("/api/security/api-keys", methods=["POST"])
@csrf.exempt
def security_api_keys_create():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    active_count = SecurityApiKey.query.filter_by(owner_user_id=user["id"], revoked_at=None).count()
    if active_count >= 20:
        return jsonify({"error": "Limit of 20 active API keys reached. Revoke an existing key first."}), 400
    raw_key = "rj_" + secrets.token_urlsafe(32)
    key_hash = hashlib.sha256(raw_key.encode("utf-8")).hexdigest()
    scopes = data.get("scopes") or ["read"]
    if isinstance(scopes, str):
        scopes = [scopes]
    rate_limit = int(data.get("rate_limit_per_min") or 60)
    rate_limit = max(1, min(rate_limit, 600))
    row = SecurityApiKey(
        owner_user_id=user["id"], label=(data.get("label") or "").strip() or None,
        key_prefix=raw_key[:10], key_hash=key_hash,
        scopes=",".join(scopes), rate_limit_per_min=rate_limit,
    )
    db.session.add(row)
    db.session.commit()
    _sec_log_event(user["id"], "api_key.created", f"API key created ({row.key_prefix}…)")
    resp = row.to_dict()
    resp["raw_key"] = raw_key  # shown once only — never stored, never returned again
    return jsonify({"ok": True, "key": resp}), 201


@app.route("/api/security/api-keys/<int:key_id>/revoke", methods=["POST"])
@csrf.exempt
def security_api_keys_revoke(key_id):
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    row = _sec_owner_scope_or_404(SecurityApiKey, key_id, user["id"])
    if not row:
        return jsonify({"error": "Key not found."}), 404
    row.revoked_at = datetime.utcnow()
    db.session.commit()
    _sec_log_event(user["id"], "api_key.revoked", f"API key revoked ({row.key_prefix}…)", severity="warning")
    return jsonify({"ok": True, "key": row.to_dict()}), 200

# Register all the tables defined above. db.create_all() only creates
# tables that don't exist yet, matching the pattern used for every
# earlier post-launch module in this file.
with app.app_context():
    try:
        db.create_all()
    except Exception as _mfg_create_all_err:
        app.logger.warning("mfg module db.create_all() failed: %s", _mfg_create_all_err)


# ════════════════════════════════════════════════════════════════════
# MANUFACTURING & PHYSICAL OPERATIONS MODULE — PART 2
# Twelve of the fifteen "Industrial & Manufacturing" roadmap items
# (16-30 in next_100_features). Three were skipped as already built
# above: batch/lot traceability (#20 -> ManufacturingBatch), supplier
# quality scorecards (#28 -> the scorecard feature), and shift
# handover log (#30 -> ShiftHandoverLog) — building them again would
# duplicate existing functionality rather than add to it.
#
# Sensor-fed features (line dashboard, energy monitoring) cannot
# literally speak OPC-UA/Modbus from inside this web app — those are
# factory-floor network protocols, not HTTP. What's built instead is
# the honest version of that: a real ingestion endpoint, authenticated
# with the existing SecurityApiKey mechanism, that any real OPC-UA/
# Modbus gateway or smart-meter bridge (Node-RED, a small Python
# script using the `opcua` or `pymodbus` libraries, a meter's own
# webhook) can push real readings into. Nothing here fabricates
# sensor data — the dashboard just renders whatever real readings
# have actually been posted, and is empty until a gateway is wired up
# or a reading is entered manually.
#
# All tables owner_user_id-scoped. Auth via _erp_user_or_401() +
# _csrf_ok(), same as the rest of the ERP. New tables get picked up
# by the db.create_all() at the end of this section.
# ════════════════════════════════════════════════════════════════════

def _mfg2_api_key_or_401():
    """Auth for machine-to-machine ingestion endpoints (sensor/energy
    readings posted by a gateway agent, not a logged-in browser
    session). Accepts an existing, non-revoked SecurityApiKey via the
    X-Api-Key header. Returns (owner_user_id, None) or (None, resp)."""
    raw_key = request.headers.get("X-Api-Key") or (request.get_json(silent=True) or {}).get("api_key")
    if not raw_key:
        return None, (jsonify({"error": "X-Api-Key header (or api_key field) is required."}), 401)
    key_hash = hashlib.sha256(raw_key.encode("utf-8")).hexdigest()
    row = SecurityApiKey.query.filter_by(key_hash=key_hash, revoked_at=None).first()
    if not row:
        return None, (jsonify({"error": "Invalid or revoked API key."}), 401)
    if security_api_key_rate_limited(row):
        return None, (jsonify({"error": "Rate limit exceeded for this API key."}), 429)
    row.last_used_at = datetime.utcnow()
    db.session.commit()
    return row.owner_user_id, None


def _mfg2_owner_id():
    """Either a logged-in browser session or a valid X-Api-Key —
    whichever is present. Used by ingestion endpoints so a gateway can
    push readings without a browser session, while the same route
    still works from the app itself if ever called that way."""
    user = _get_current_user()
    if user:
        return user["id"], None
    return _mfg2_api_key_or_401()


