@app.route("/api/mfg/sensor-readings/ingest", methods=["POST"])
@csrf.exempt
def mfg_sensor_ingest():
    """Real ingestion endpoint for an OPC-UA/Modbus gateway agent or
    any script polling factory-floor hardware. Auth via X-Api-Key
    (see /api/security/api-keys to create one) — no browser session
    needed, so a headless gateway process can call this directly."""
    owner_id, err = _mfg2_api_key_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    line_name = (data.get("line_name") or "").strip()
    metric_name = (data.get("metric_name") or "").strip()
    if not line_name or not metric_name or data.get("value") is None:
        return jsonify({"error": "line_name, metric_name and value are required."}), 400
    try:
        value = float(data.get("value"))
    except (TypeError, ValueError):
        return jsonify({"error": "value must be numeric."}), 400
    row = MfgSensorReading(
        owner_user_id=owner_id, line_name=line_name,
        equipment_id=data.get("equipment_id") or None,
        metric_name=metric_name, value=value,
        unit=(data.get("unit") or "").strip() or None,
        source=(data.get("source") or "opcua").strip(),
    )
    db.session.add(row)
    db.session.commit()
    return jsonify({"ok": True, "reading": row.to_dict()}), 201


