@app.route("/api/mfg/work-orders/<int:wo_id>/transition", methods=["POST"])
@csrf.exempt
def mfg_work_orders_transition(wo_id):
    """Advance a work order's status: start, pause, complete, or cancel.
    Stamps actual_start/actual_end and (on complete) quantity_completed."""
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    row = MfgWorkOrder.query.filter_by(id=wo_id, owner_user_id=user["id"]).first()
    if not row: return jsonify({"error": "Work order not found."}), 404
    data = request.get_json(silent=True) or {}
    action = (data.get("action") or "").strip()
    if action == "start":
        row.status = "in_progress"
        row.actual_start = row.actual_start or datetime.utcnow()
    elif action == "pause":
        row.status = "paused"
    elif action == "complete":
        row.status = "completed"
        row.actual_end = datetime.utcnow()
        if data.get("quantity_completed") is not None:
            row.quantity_completed = float(data.get("quantity_completed") or 0)
    elif action == "cancel":
        row.status = "cancelled"
    else:
        return jsonify({"error": "action must be one of: start, pause, complete, cancel."}), 400
    db.session.commit()
    return jsonify({"ok": True, "work_order": row.to_dict()}), 200


