@app.route("/api/mfg/schedule", methods=["GET"])
def mfg_schedule_list():
    user, err = _erp_user_or_401()
    if err: return err
    start = _erp_parse_date(request.args.get("from"), default=datetime.utcnow().date() - timedelta(days=1))
    end = _erp_parse_date(request.args.get("to"), default=datetime.utcnow().date() + timedelta(days=13))
    rows = (MfgScheduleItem.query
            .filter(MfgScheduleItem.owner_user_id == user["id"],
                    MfgScheduleItem.scheduled_start < datetime.combine(end, datetime.min.time()),
                    MfgScheduleItem.scheduled_end >= datetime.combine(start, datetime.min.time()))
            .order_by(MfgScheduleItem.scheduled_start).all())
    return jsonify({"items": [r.to_dict() for r in rows], "from": start.isoformat(), "to": end.isoformat()}), 200


@app.route("/api/mfg/schedule", methods=["POST"])
@csrf.exempt
def mfg_schedule_add():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    line_name = (data.get("line_name") or "").strip()
    title = (data.get("title") or "").strip()
    start = _erp_parse_datetime(data.get("scheduled_start"))
    end = _erp_parse_datetime(data.get("scheduled_end"))
    if not line_name or not title or not start or not end:
        return jsonify({"error": "line_name, title, scheduled_start and scheduled_end are required."}), 400
    if end <= start:
        return jsonify({"error": "scheduled_end must be after scheduled_start."}), 400
    row = MfgScheduleItem(
        owner_user_id=user["id"], line_name=line_name, title=title,
        work_order_id=data.get("work_order_id") or None,
        scheduled_start=start, scheduled_end=end,
        notes=(data.get("notes") or "").strip() or None,
    )
    db.session.add(row)
    db.session.commit()
    return jsonify({"ok": True, "item": row.to_dict()}), 201


