def mfg_scrap_add():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    material_name = (data.get("material_name") or "").strip()
    if not material_name or data.get("quantity") is None:
        return jsonify({"error": "material_name and quantity are required."}), 400
    row = MfgScrapLog(
        owner_user_id=user["id"], line_name=(data.get("line_name") or "").strip() or None,
        material_name=material_name, quantity=float(data.get("quantity") or 0),
        unit=(data.get("unit") or "").strip() or None, unit_cost=data.get("unit_cost"),
        reason=(data.get("reason") or "process_defect").strip(),
        logged_by=(data.get("logged_by") or "").strip() or None,
    )
    db.session.add(row)
    db.session.commit()
    return jsonify({"ok": True, "scrap_log": row.to_dict()}), 201


@app.route("/api/mfg/scrap/summary", methods=["GET"])
def mfg_scrap_summary():
    user, err = _erp_user_or_401()
    if err: return err
    since = datetime.utcnow() - timedelta(days=int(request.args.get("days", 30)))
    rows = (MfgScrapLog.query
            .filter(MfgScrapLog.owner_user_id == user["id"], MfgScrapLog.logged_at >= since).all())
    by_reason = {}
    total_cost = 0.0
    for r in rows:
        cost = (r.quantity * r.unit_cost) if r.unit_cost else 0
        total_cost += cost
        by_reason[r.reason] = by_reason.get(r.reason, 0) + cost
    return jsonify({
        "days": int(request.args.get("days", 30)), "total_scrap_cost": round(total_cost, 2),
        "by_reason_cost": {k: round(v, 2) for k, v in sorted(by_reason.items(), key=lambda x: -x[1])},
    }), 200


# ---- 26. Worker certification/training expiry tracker ----
class MfgWorkerCertification(db.Model):
    __tablename__ = "mfg_worker_certifications"
    id                 = db.Column(db.Integer, primary_key=True)
    owner_user_id      = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    worker_name        = db.Column(db.String(120), nullable=False)
    certification_name = db.Column(db.String(160), nullable=False)
    issuing_body       = db.Column(db.String(160), nullable=True)
    issued_date        = db.Column(db.Date, nullable=True)
    expiry_date        = db.Column(db.Date, nullable=True)
    notes              = db.Column(db.Text, nullable=True)
    created_at         = db.Column(db.DateTime, default=datetime.utcnow)

    def status(self):
        if not self.expiry_date: return "no_expiry"
        days = (self.expiry_date - datetime.utcnow().date()).days
        if days < 0: return "expired"
        if days <= 30: return "expiring_soon"
        return "valid"

    def to_dict(self):
        return {
            "id": self.id, "worker_name": self.worker_name, "certification_name": self.certification_name,
            "issuing_body": self.issuing_body,
            "issued_date": self.issued_date.isoformat() if self.issued_date else None,
            "expiry_date": self.expiry_date.isoformat() if self.expiry_date else None,
            "status": self.status(), "notes": self.notes,
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }


