    last_calibrated    = db.Column(db.Date, nullable=False)
    interval_days      = db.Column(db.Integer, nullable=False, default=180)
    performed_by       = db.Column(db.String(120), nullable=True)
    certificate_reference = db.Column(db.String(160), nullable=True)
    notes              = db.Column(db.Text, nullable=True)
    created_at         = db.Column(db.DateTime, default=datetime.utcnow)

    def next_due(self):
        return self.last_calibrated + timedelta(days=self.interval_days)

    def status(self):
        days = (self.next_due() - datetime.utcnow().date()).days
        if days < 0: return "overdue"
        if days <= 14: return "due_soon"
        return "current"

    def to_dict(self):
        equip = ManufacturingEquipment.query.get(self.equipment_id)
        return {
            "id": self.id, "equipment_id": self.equipment_id,
            "equipment_name": equip.name if equip else None,
            "calibration_type": self.calibration_type,
            "last_calibrated": self.last_calibrated.isoformat() if self.last_calibrated else None,
            "interval_days": self.interval_days, "next_due": self.next_due().isoformat(),
            "status": self.status(), "performed_by": self.performed_by,
            "certificate_reference": self.certificate_reference, "notes": self.notes,
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }


