@app.route("/api/mfg/calibrations", methods=["POST"])
@csrf.exempt
def mfg_calibrations_add():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    equipment = ManufacturingEquipment.query.filter_by(id=data.get("equipment_id"), owner_user_id=user["id"]).first()
    if not equipment: return jsonify({"error": "Equipment not found."}), 404
    calibration_type = (data.get("calibration_type") or "").strip()
    last_calibrated = _erp_parse_date(data.get("last_calibrated"))
    if not calibration_type or not last_calibrated:
        return jsonify({"error": "calibration_type and last_calibrated are required."}), 400
    row = MfgCalibrationRecord(
        owner_user_id=user["id"], equipment_id=equipment.id, calibration_type=calibration_type,
        last_calibrated=last_calibrated, interval_days=int(data.get("interval_days") or 180),
        performed_by=(data.get("performed_by") or "").strip() or None,
        certificate_reference=(data.get("certificate_reference") or "").strip() or None,
        notes=(data.get("notes") or "").strip() or None,
    )
    db.session.add(row)
    db.session.commit()
    return jsonify({"ok": True, "calibration": row.to_dict()}), 201


