class DataWarehouseConnection(db.Model):
    """Credentials/config for exporting this seller's own order data to
    their own BigQuery/Snowflake/Redshift. Never used to reach any
    account but the one whose config is stored here."""
    __tablename__   = "bi_warehouse_connections"
    id              = db.Column(db.Integer, primary_key=True)
    owner_user_id   = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    provider        = db.Column(db.String(12), nullable=False)  # bigquery, snowflake, redshift
    config_json     = db.Column(db.Text, nullable=False, default="{}")
    status          = db.Column(db.String(16), nullable=False, default="not_synced")  # not_synced, synced, error
    last_sync_at    = db.Column(db.DateTime, nullable=True)
    last_sync_rows  = db.Column(db.Integer, nullable=True)
    last_error      = db.Column(db.Text, nullable=True)
