@app.route("/api/cron/scheduled-reports", methods=["POST"])
def cron_scheduled_reports():
    """External-scheduler endpoint (PythonAnywhere Scheduled Task / any
    cron), protected by CRON_SECRET — same pattern as
    /api/cron/tax-deadlines. Suggested schedule: hourly; a report only
    actually sends once its frequency window has elapsed."""
    if not CRON_SECRET or request.headers.get("X-Cron-Secret") != CRON_SECRET:
        return jsonify({"error": "Forbidden."}), 403
    now = datetime.utcnow()
    due = ScheduledReport.query.filter_by(active=True).all()
    sent = 0
    for sr in due:
        window = timedelta(days=1) if sr.frequency == "daily" else timedelta(days=7)
        if sr.last_sent_at and (now - sr.last_sent_at) < window:
            continue
        report = CustomReport.query.get(sr.report_id)
        if not report:
            continue
        result = _bi_run_report(report, sr.owner_user_id)
        html = _bi_report_to_html(report, result)
        if _send_platform_email(sr.recipient_email, f"Connect It — {report.name}", html):
            sr.last_sent_at = now
            sent += 1
    db.session.commit()
    logging.info(f"[CRON SCHEDULED REPORTS] checked {len(due)}, sent {sent}")
    return jsonify({"ok": True, "checked": len(due), "sent": sent}), 200


# ─────────────────────────────────────────────────────────────
# STAGE 461e: COHORT & RETENTION ANALYSIS (feature 3)
# ─────────────────────────────────────────────────────────────

@app.route("/api/reports/cohort-retention", methods=["GET"])
def bi_cohort_retention():
    user, err = _erp_user_or_401()
    if err: return err
    months_back = max(1, min(request.args.get("months", default=6, type=int) or 6, 12))
    start = datetime.utcnow() - timedelta(days=months_back * 31)
    orders = _bi_orders_q(user["id"], start=start).order_by(ProductOrder.created_at.asc()).all()

    first_order_month = {}
    buyer_months = {}
    for o in orders:
        if not _bi_is_realized(o):
            continue
        m = (o.created_at or datetime.utcnow()).strftime("%Y-%m")
        first_order_month.setdefault(o.buyer_id, m)
        buyer_months.setdefault(o.buyer_id, set()).add(m)

    cohorts = {}
    for buyer_id, cohort_month in first_order_month.items():
        cohorts.setdefault(cohort_month, {"buyers": set(), "months": buyer_months[buyer_id]})
        cohorts[cohort_month]["buyers"].add(buyer_id)

    def month_offset(m1, m2):
        y1, mo1 = map(int, m1.split("-")); y2, mo2 = map(int, m2.split("-"))
        return (y2 - y1) * 12 + (mo2 - mo1)

    result = []
    for cohort_month in sorted(cohorts.keys()):
        buyers = cohorts[cohort_month]["buyers"]
        size = len(buyers)
        retention = {}
        for offset in range(0, months_back):
            active = 0
            for b in buyers:
                for m in buyer_months[b]:
                    if month_offset(cohort_month, m) == offset:
                        active += 1
                        break
            retention[f"month_{offset}"] = round((active / size) * 100.0, 1) if size else 0.0
        result.append({"cohort": cohort_month, "size": size, "retention_pct": retention})

    return jsonify({"ok": True, "cohorts": result}), 200


# ─────────────────────────────────────────────────────────────
# EMOTIONAL RESILIENCE ANALYTICS
# Turns the previously one-off, unstored Stress Score reader into a
# persisted signal that feeds the Executive Dashboard — "a
# high-performing business is impossible without a healthy, inspired
# team." The AI now returns structured JSON instead of free text so a
# score can actually be stored and trended, not just displayed once
# and thrown away.
# ─────────────────────────────────────────────────────────────

class WellbeingCheckIn(db.Model):
    __tablename__ = "wellbeing_checkins"
    id             = db.Column(db.Integer, primary_key=True)
    owner_user_id  = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    score          = db.Column(db.Integer, nullable=False)          # 0-100, higher = more stressed
    level          = db.Column(db.String(20), nullable=False)       # Low / Medium / High / Critical
    signals        = db.Column(db.Text, nullable=True)
    likely_cause   = db.Column(db.Text, nullable=True)
    immediate_plan = db.Column(db.Text, nullable=True)
    weekly_plan    = db.Column(db.Text, nullable=True)
    message        = db.Column(db.Text, nullable=True)
    created_at     = db.Column(db.DateTime, default=datetime.utcnow, index=True)

    def to_dict(self, include_review=True):
        d = {
            "id": self.id, "score": self.score, "level": self.level,
            "signals": self.signals, "likely_cause": self.likely_cause,
            "immediate_plan": self.immediate_plan, "weekly_plan": self.weekly_plan,
            "message": self.message,
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }
        if include_review:
            latest_review = _wellbeing_latest_review(self.id)
            d["review"] = latest_review.to_dict() if latest_review else None
        return d


def _wellbeing_team_summary(owner_user_id):
    """Powers the "Team Wellbeing" card on the Executive Dashboard.
    Deliberately returns None fields rather than zeros when there's no
    data yet, so the dashboard can say "no check-ins yet" instead of
    implying a false all-clear score of 0."""
    now = datetime.utcnow()
    recent_30 = (WellbeingCheckIn.query
                 .filter(WellbeingCheckIn.owner_user_id == owner_user_id,
                         WellbeingCheckIn.created_at >= now - timedelta(days=30))
                 .order_by(WellbeingCheckIn.created_at.desc()).all())
    if not recent_30:
        return {
            "has_data": False, "latest_score": None, "latest_level": None,
            "avg_score_7d": None, "avg_score_30d": None,
            "checkins_7d": 0, "checkins_30d": 0, "trend": None,
        }
    recent_7 = [c for c in recent_30 if c.created_at >= now - timedelta(days=7)]
    avg_30 = round(sum(c.score for c in recent_30) / len(recent_30), 1)
    avg_7 = round(sum(c.score for c in recent_7) / len(recent_7), 1) if recent_7 else None
    trend = None
    if avg_7 is not None and len(recent_30) > len(recent_7):
        older = [c for c in recent_30 if c not in recent_7]
        avg_older = sum(c.score for c in older) / len(older)
        if avg_7 - avg_older >= 5: trend = "worsening"
        elif avg_older - avg_7 >= 5: trend = "improving"
        else: trend = "stable"
    latest = recent_30[0]
    return {
        "has_data": True, "latest_score": latest.score, "latest_level": latest.level,
        "latest_at": latest.created_at.isoformat() if latest.created_at else None,
        "avg_score_7d": avg_7, "avg_score_30d": avg_30,
        "checkins_7d": len(recent_7), "checkins_30d": len(recent_30), "trend": trend,
    }


@app.route("/api/wellbeing/checkin", methods=["POST"])
@csrf.exempt
def wellbeing_checkin():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    text = (data.get("text") or "").strip()
    if len(text.split()) < 20:
        return jsonify({"error": "Paste a bit more text for an accurate reading."}), 400

    gate_result = gate_ai_usage(user, "wellbeing_checkin")
    if gate_result is not None:
        return gate_result

    prompt = (
        "You are an expert emotional-intelligence analyst and stress researcher. "
        "Read the text below and return a JSON object with these exact keys "
        "(return ONLY valid JSON, no markdown, no backticks):\n\n"
        "{\n"
        "  \"score\": integer 0-100 (0=totally calm, 100=crisis level),\n"
        "  \"level\": one of \"Low\", \"Medium\", \"High\", \"Critical\",\n"
        "  \"signals\": \"the specific words, patterns, and emotional markers you found in the language\",\n"
        "  \"likely_cause\": \"your best analysis of what's driving it\",\n"
        "  \"immediate_plan\": \"a 3-step relief plan for right now\",\n"
        "  \"weekly_plan\": \"a 7-day recovery plan with specific daily actions\",\n"
        "  \"message\": \"a short, compassionate personal message to this person\"\n"
        "}\n\n"
        "Be honest, specific, and deeply compassionate. This person trusted you with something real.\n\n"
        "TEXT TO ANALYSE:\n\n" + text[:6000]
    )
    try:
        raw, _ = generate_ai_reply(prompt, [], user_id=user["id"])
        clean = re.sub(r'^```json\s*|^```\s*|\s*```$', '', raw.strip())
        try:
            result = json.loads(clean)
        except Exception:
            result = {"score": 50, "level": "Medium", "signals": raw, "likely_cause": "",
                       "immediate_plan": "", "weekly_plan": "", "message": ""}
        score = max(0, min(100, int(result.get("score", 50) or 50)))
        level = result.get("level") if result.get("level") in ("Low", "Medium", "High", "Critical") else \
                ("Low" if score < 30 else "Medium" if score < 55 else "High" if score < 80 else "Critical")

        row = WellbeingCheckIn(
            owner_user_id=user["id"], score=score, level=level,
            signals=(result.get("signals") or "")[:3000], likely_cause=(result.get("likely_cause") or "")[:2000],
            immediate_plan=(result.get("immediate_plan") or "")[:2000], weekly_plan=(result.get("weekly_plan") or "")[:3000],
            message=(result.get("message") or "")[:1000],
        )
        db.session.add(row)
        db.session.commit()
        return jsonify({"ok": True, "checkin": row.to_dict()}), 200
    except Exception as e:
        logging.error(f"Wellbeing check-in failed: {e}")
        return jsonify({"error": str(e)}), 500


