# ─────────────────────────────────────────────────────────────

@app.route("/api/reports/executive-dashboard", methods=["GET"])
def bi_executive_dashboard():
    user, err = _erp_user_or_401()
    if err: return err
    now = datetime.utcnow()
    today_start = now.replace(hour=0, minute=0, second=0, microsecond=0)

    orders_today = _bi_orders_q(user["id"], start=today_start).all()
    orders_7d = _bi_orders_q(user["id"], start=now - timedelta(days=7)).all()
    orders_30d = _bi_orders_q(user["id"], start=now - timedelta(days=30)).all()

    holding = [o for o in orders_30d if o.escrow_status == "holding"]
    holding_total = round(sum(o.total_price or 0 for o in holding), 2)

    top_products = {}
    for o in orders_30d:
        if not _bi_is_realized(o):
            continue
        top_products[o.product_id] = top_products.get(o.product_id, 0) + (o.total_price or 0)
    top_ids = sorted(top_products, key=top_products.get, reverse=True)[:5]
    top_rows = []
    for pid in top_ids:
        p = Product.query.get(pid)
        top_rows.append({"product_id": pid, "name": p.name if p else "Deleted product", "revenue": round(top_products[pid], 2)})

    recent = sorted(orders_30d, key=lambda o: o.created_at or now, reverse=True)[:5]
    recent_rows = [{
        "id": o.id, "total_price": o.total_price, "currency": o.currency,
        "status": o.status, "escrow_status": o.escrow_status,
        "created_at": o.created_at.isoformat() if o.created_at else None,
    } for o in recent]

    return jsonify({
        "ok": True,
        "today": _bi_metrics_for(orders_today),
        "last_7_days": _bi_metrics_for(orders_7d),
        "last_30_days": _bi_metrics_for(orders_30d),
        "escrow_holding_total": holding_total,
        "top_products_30d": top_rows,
        "recent_orders": recent_rows,
        "team_wellbeing": _wellbeing_team_summary(user["id"]),
        "generated_at": now.isoformat(),
    }), 200


