@app.route("/api/reports/warehouse-connections/<int:conn_id>/sync", methods=["POST"])
def bi_warehouse_sync(conn_id):
    """Exports this seller's own order data as rows into their own
    warehouse table. Real client libraries only — if the library isn't
    installed on the server, or the credentials are missing/invalid,
    this returns a clear error instead of pretending to sync."""
    user, err = _erp_user_or_401()
    if err: return err
    if not _csrf_ok():
        return jsonify({"error": "Invalid request origin."}), 403
    conn = DataWarehouseConnection.query.filter_by(id=conn_id, owner_user_id=user["id"]).first()
    if not conn:
        return jsonify({"error": "Not found."}), 404

    cfg = json.loads(conn.config_json or "{}")
    orders = _bi_orders_q(user["id"], start=datetime.utcnow() - timedelta(days=365)).all()
    export_rows = [{
        "order_id": o.id, "created_at": (o.created_at or datetime.utcnow()).isoformat(),
        "total_price": o.total_price, "currency": o.currency, "status": o.status,
        "escrow_status": o.escrow_status, "carrier": o.carrier, "refunded": o.refunded_at is not None,
    } for o in orders]

    try:
        if conn.provider == "bigquery":
            if not BIGQUERY_AVAILABLE:
                raise RuntimeError("google-cloud-bigquery isn't installed on the server. Run: "
                                    "pip install google-cloud-bigquery --break-system-packages")
            if not cfg.get("project_id") or not cfg.get("dataset") or not cfg.get("service_account_json"):
                raise RuntimeError("Missing project_id, dataset, or service_account_json in the connection config.")
            creds_info = json.loads(cfg["service_account_json"])
            from google.oauth2 import service_account
            credentials = service_account.Credentials.from_service_account_info(creds_info)
            client = _bq_client.Client(project=cfg["project_id"], credentials=credentials)
            table_id = f"{cfg['project_id']}.{cfg['dataset']}.connectit_orders"
            job = client.load_table_from_json(export_rows, table_id,
                                               job_config=_bq_client.LoadJobConfig(write_disposition="WRITE_TRUNCATE"))
            job.result()

        elif conn.provider == "snowflake":
            if not SNOWFLAKE_AVAILABLE:
                raise RuntimeError("snowflake-connector-python isn't installed on the server. Run: "
                                    "pip install snowflake-connector-python --break-system-packages")
            for k in ("account", "user", "password", "warehouse", "database", "schema"):
                if not cfg.get(k):
                    raise RuntimeError(f"Missing '{k}' in the connection config.")
            sf = _snowflake_client.connect(account=cfg["account"], user=cfg["user"], password=cfg["password"],
                                            warehouse=cfg["warehouse"], database=cfg["database"], schema=cfg["schema"])
            cur = sf.cursor()
            cur.execute("CREATE TABLE IF NOT EXISTS connectit_orders (order_id INT, created_at STRING, "
                        "total_price FLOAT, currency STRING, status STRING, escrow_status STRING, "
                        "carrier STRING, refunded BOOLEAN)")
            cur.execute("TRUNCATE TABLE connectit_orders")
            for r in export_rows:
                cur.execute("INSERT INTO connectit_orders VALUES (%s,%s,%s,%s,%s,%s,%s,%s)",
                            (r["order_id"], r["created_at"], r["total_price"], r["currency"],
                             r["status"], r["escrow_status"], r["carrier"], r["refunded"]))
            sf.close()

        elif conn.provider == "redshift":
            if not REDSHIFT_AVAILABLE:
                raise RuntimeError("psycopg2 isn't installed on the server. Run: "
                                    "pip install psycopg2-binary --break-system-packages")
            for k in ("host", "port", "dbname", "user", "password"):
                if not cfg.get(k):
                    raise RuntimeError(f"Missing '{k}' in the connection config.")
            rs = _redshift_client.connect(host=cfg["host"], port=cfg["port"], dbname=cfg["dbname"],
                                           user=cfg["user"], password=cfg["password"])
            cur = rs.cursor()
            cur.execute("CREATE TABLE IF NOT EXISTS connectit_orders (order_id INT, created_at VARCHAR(40), "
                        "total_price FLOAT, currency VARCHAR(8), status VARCHAR(20), escrow_status VARCHAR(16), "
                        "carrier VARCHAR(16), refunded BOOLEAN)")
            cur.execute("TRUNCATE TABLE connectit_orders")
            for r in export_rows:
                cur.execute("INSERT INTO connectit_orders VALUES (%s,%s,%s,%s,%s,%s,%s,%s)",
                            (r["order_id"], r["created_at"], r["total_price"], r["currency"],
                             r["status"], r["escrow_status"], r["carrier"], r["refunded"]))
            rs.commit()
            rs.close()

        conn.status = "synced"
        conn.last_sync_at = datetime.utcnow()
        conn.last_sync_rows = len(export_rows)
        conn.last_error = None
        db.session.commit()
        return jsonify({"ok": True, "connection": conn.to_dict()}), 200

    except Exception as e:
        conn.status = "error"
        conn.last_error = str(e)
        db.session.commit()
        return jsonify({"ok": False, "error": str(e), "connection": conn.to_dict()}), 400


# ─────────────────────────────────────────────────────────────
# STAGE 461h: ANOMALY DETECTION (feature 6)
# ─────────────────────────────────────────────────────────────

@app.route("/api/reports/anomalies", methods=["GET"])
def bi_anomalies():
    """Flags days whose revenue/order-count is more than 2.5 standard
    deviations from the trailing-7-day mean — a plain rolling z-score,
    computed on this seller's real daily order data, no ML model or
    external service involved."""
    user, err = _erp_user_or_401()
    if err: return err
    days_back = max(14, min(request.args.get("days", default=90, type=int) or 90, 365))
    start = datetime.utcnow() - timedelta(days=days_back)
    orders = _bi_orders_q(user["id"], start=start).all()

    daily = {}
    for o in orders:
        key = (o.created_at or datetime.utcnow()).strftime("%Y-%m-%d")
        daily.setdefault(key, []).append(o)
    days_sorted = sorted(daily.keys())
    series = [{"date": d, "revenue": _bi_metrics_for(daily[d])["revenue"], "orders": len(daily[d])} for d in days_sorted]

    anomalies = []
    for metric in ("revenue", "orders"):
        values = [pt[metric] for pt in series]
        for i in range(7, len(values)):
            window = values[i - 7:i]
            if len(set(window)) < 2:
                continue
            mean = _bi_stats.mean(window)
            stdev = _bi_stats.stdev(window)
            if stdev == 0:
                continue
            z = (values[i] - mean) / stdev
            if abs(z) > 2.5:
                anomalies.append({
                    "date": series[i]["date"], "metric": metric, "value": values[i],
                    "trailing_7d_mean": round(mean, 2), "z_score": round(z, 2),
                    "direction": "spike" if z > 0 else "drop",
                })

    return jsonify({"ok": True, "series": series, "anomalies": anomalies}), 200


# ─────────────────────────────────────────────────────────────
# STAGE 461i: A/B TESTING FRAMEWORK (feature 7)
# ─────────────────────────────────────────────────────────────

@app.route("/api/reports/ab-tests", methods=["GET", "POST"])
def bi_ab_tests():
    user, err = _erp_user_or_401()
    if err: return err
    if request.method == "GET":
        tests = AbTest.query.filter_by(owner_user_id=user["id"]).order_by(AbTest.created_at.desc()).all()
        out = []
        for t in tests:
            variants = [v.to_dict() for v in AbTestVariant.query.filter_by(test_id=t.id).all()]
            out.append(t.to_dict(variants=variants))
        return jsonify({"tests": out}), 200

    if not _csrf_ok():
        return jsonify({"error": "Invalid request origin."}), 403
    data = request.get_json(silent=True) or {}
    name = (data.get("name") or "").strip()
    test_type = data.get("test_type") if data.get("test_type") in ("listing_price", "listing_copy", "checkout") else "listing_price"
    variants_in = data.get("variants") or []
    if not name or len(variants_in) < 2:
        return jsonify({"error": "A test name and at least two variants are required."}), 400
    product_id = data.get("product_id")
    if test_type in ("listing_price", "listing_copy"):
        product = Product.query.filter_by(id=product_id, seller_id=user["id"]).first()
        if not product:
            return jsonify({"error": "Pick one of your own listings to test."}), 400

    test = AbTest(owner_user_id=user["id"], name=name, test_type=test_type, product_id=product_id, status="draft")
    db.session.add(test)
    db.session.flush()
    for v in variants_in:
        db.session.add(AbTestVariant(test_id=test.id, name=(v.get("name") or "Variant"),
                                      config_json=json.dumps(v.get("config") or {}),
                                      traffic_pct=int(v.get("traffic_pct") or (100 // len(variants_in)))))
    db.session.commit()
    return jsonify({"ok": True, "test": test.to_dict()}), 201


@app.route("/api/reports/ab-tests/<int:test_id>/start", methods=["POST"])
def bi_ab_test_start(test_id):
    user, err = _erp_user_or_401()
