@app.route("/api/reports/ab-tests/<int:test_id>/assign", methods=["POST"])
def bi_ab_test_assign(test_id):
    """No login required — a buyer browsing a listing gets bucketed by
    their own client-generated visitor_key. Deterministic within a
    test: same visitor_key always lands on the same variant."""
    test = AbTest.query.filter_by(id=test_id, status="running").first()
    if not test:
        return jsonify({"error": "Test not running."}), 404
    data = request.get_json(silent=True) or {}
    visitor_key = (data.get("visitor_key") or "").strip()
    if not visitor_key:
        return jsonify({"error": "visitor_key is required."}), 400

    existing = AbTestAssignment.query.filter_by(test_id=test.id, visitor_key=visitor_key).first()
    if existing:
        variant = AbTestVariant.query.get(existing.variant_id)
        return jsonify({"ok": True, "variant": variant.to_dict()}), 200

    variants = AbTestVariant.query.filter_by(test_id=test.id).order_by(AbTestVariant.id.asc()).all()
    if not variants:
        return jsonify({"error": "No variants configured."}), 400
    bucket = int(hashlib.sha256(f"{test.id}:{visitor_key}".encode()).hexdigest(), 16) % 100
    cumulative = 0
    chosen = variants[-1]
    for v in variants:
        cumulative += v.traffic_pct
        if bucket < cumulative:
            chosen = v
            break

    db.session.add(AbTestAssignment(test_id=test.id, variant_id=chosen.id, visitor_key=visitor_key))
    db.session.commit()
    return jsonify({"ok": True, "variant": chosen.to_dict()}), 200


@app.route("/api/reports/ab-tests/<int:test_id>/convert", methods=["POST"])
def bi_ab_test_convert(test_id):
    data = request.get_json(silent=True) or {}
    visitor_key = (data.get("visitor_key") or "").strip()
    row = AbTestAssignment.query.filter_by(test_id=test_id, visitor_key=visitor_key).first()
    if not row:
        return jsonify({"error": "No assignment found for this visitor on this test."}), 404
    row.converted = True
    row.conversion_value = data.get("conversion_value")
    db.session.commit()
    return jsonify({"ok": True}), 200


@app.route("/api/reports/ab-tests/<int:test_id>/results", methods=["GET"])
def bi_ab_test_results(test_id):
    user, err = _erp_user_or_401()
    if err: return err
    test = AbTest.query.filter_by(id=test_id, owner_user_id=user["id"]).first()
    if not test:
        return jsonify({"error": "Not found."}), 404
    variants = AbTestVariant.query.filter_by(test_id=test.id).all()
    results = []
    for v in variants:
        assignments = AbTestAssignment.query.filter_by(test_id=test.id, variant_id=v.id).all()
        n = len(assignments)
        conversions = sum(1 for a in assignments if a.converted)
        revenue = sum(a.conversion_value or 0 for a in assignments if a.converted)
        rate = (conversions / n * 100.0) if n else 0.0
        results.append({
            "variant": v.to_dict(), "visitors": n, "conversions": conversions,
            "conversion_rate": round(rate, 2), "revenue": round(revenue, 2),
        })
    return jsonify({"ok": True, "test": test.to_dict(), "results": results}), 200


@app.route("/api/reports/ab-tests/<int:test_id>", methods=["DELETE"])
def bi_ab_test_delete(test_id):
    user, err = _erp_user_or_401()
    if err: return err
    if not _csrf_ok():
        return jsonify({"error": "Invalid request origin."}), 403
    test = AbTest.query.filter_by(id=test_id, owner_user_id=user["id"]).first()
    if not test:
        return jsonify({"error": "Not found."}), 404
    variant_ids = [v.id for v in AbTestVariant.query.filter_by(test_id=test.id).all()]
    AbTestAssignment.query.filter(AbTestAssignment.variant_id.in_(variant_ids)).delete(synchronize_session=False)
    AbTestVariant.query.filter_by(test_id=test.id).delete()
    db.session.delete(test)
    db.session.commit()
    return jsonify({"ok": True}), 200


# ─────────────────────────────────────────────────────────────
# STAGE 461j: BENCHMARKING AGAINST PLATFORM-WIDE AVERAGES (feature 8)
# ─────────────────────────────────────────────────────────────

@app.route("/api/reports/benchmark", methods=["GET"])
def bi_benchmark():
    """Compares this seller's own numbers against the platform-wide
    average across all sellers — real aggregate numbers from this
    database, anonymized (only the averages are returned, never any
    other seller's individual figures or identity)."""
    user, err = _erp_user_or_401()
    if err: return err
    start = datetime.utcnow() - timedelta(days=30)
    my_orders = _bi_orders_q(user["id"], start=start).all()
    my_metrics = _bi_metrics_for(my_orders)

    all_orders = ProductOrder.query.filter(ProductOrder.created_at >= start).all()
    by_seller = {}
    for o in all_orders:
        by_seller.setdefault(o.seller_id, []).append(o)

    aovs, refund_rates, revenues, order_counts = [], [], [], []
    for seller_id, orders in by_seller.items():
        m = _bi_metrics_for(orders)
        if m["orders"] > 0:
            aovs.append(m["aov"])
            order_counts.append(m["orders"])
            revenues.append(m["revenue"])
        refund_rates.append(m["refund_rate"])

    platform_avg = {
        "aov": round(_bi_stats.mean(aovs), 2) if aovs else 0.0,
        "revenue": round(_bi_stats.mean(revenues), 2) if revenues else 0.0,
        "orders": round(_bi_stats.mean(order_counts), 1) if order_counts else 0.0,
        "refund_rate": round(_bi_stats.mean(refund_rates), 2) if refund_rates else 0.0,
        "sellers_in_sample": len(by_seller),
    }

    return jsonify({"ok": True, "you_last_30_days": my_metrics, "platform_average_last_30_days": platform_avg}), 200


