# ---------- 462b: SHARED HELPERS ----------

def _crm_route_territory(owner_user_id, text_blob):
    """Feature 57/58 shared: matches text against the owner's
    SalesTerritory rules (highest priority first) and returns the
    matching rule, or None."""
    text_blob = (text_blob or "").lower()
    if not text_blob:
        return None
    rules = (SalesTerritory.query.filter_by(owner_user_id=owner_user_id)
             .order_by(SalesTerritory.priority.desc()).all())
    for rule in rules:
        if rule.match_keyword and rule.match_keyword.lower() in text_blob:
            return rule
    return None


def _crm_compute_health(owner_user_id, customer_id):
    """Feature 54: derives a 0-100 score from real, already-stored
    signals — active/past-due subscriptions, unresolved payment
    failures, and recency of orders/invoices for this customer."""
    score = 70
    factors = []

    subs = CustomerSubscription.query.filter_by(owner_user_id=owner_user_id, customer_id=customer_id).all()
    if subs:
        past_due = [s for s in subs if s.status == "past_due"]
        cancelled = [s for s in subs if s.status == "cancelled"]
        if past_due:
            score -= 25
            factors.append(f"{len(past_due)} subscription(s) past due")
        if cancelled and not any(s.status == "active" for s in subs):
            score -= 20
            factors.append("no active subscription remaining")
        if any(s.status == "active" for s in subs):
            score += 10
            factors.append("has an active subscription")

    sub_ids = [s.id for s in subs]
    if sub_ids:
        open_failures = PaymentFailure.query.filter(
            PaymentFailure.subscription_id.in_(sub_ids), PaymentFailure.resolved == False  # noqa: E712
        ).count()
        if open_failures:
            score -= min(30, open_failures * 10)
            factors.append(f"{open_failures} unresolved failed payment(s)")

    try:
        recent_orders = ProductOrder.query.filter_by(customer_id=customer_id).count() if hasattr(ProductOrder, "customer_id") else 0
    except Exception:
        recent_orders = 0
    if recent_orders:
        score += min(10, recent_orders)
        factors.append(f"{recent_orders} order(s) on file")

    open_invoices = ErpInvoice.query.filter_by(owner_user_id=owner_user_id, customer_id=customer_id).all() if hasattr(ErpInvoice, "customer_id") else []
    overdue = [i for i in open_invoices if getattr(i, "status", "") == "overdue"]
    if overdue:
        score -= min(20, len(overdue) * 8)
        factors.append(f"{len(overdue)} overdue invoice(s)")

    score = max(0, min(100, score))
    status = "healthy" if score >= 70 else ("at_risk" if score >= 40 else "critical")
    return score, status, factors


# ---------- 462c: CRM PIPELINE BOARD (feature 51) ----------

@app.route("/api/crm/deals", methods=["GET", "POST"])
def crm_deals():
    user, err = _erp_user_or_401()
    if err: return err
    if request.method == "GET":
        stage = request.args.get("stage")
        q = CrmDeal.query.filter_by(owner_user_id=user["id"])
        if stage:
            q = q.filter_by(stage=stage)
        rows = q.order_by(CrmDeal.updated_at.desc()).all()
        return jsonify({"deals": [d.to_dict() for d in rows]}), 200

    if not _csrf_ok():
        return jsonify({"error": "Invalid request origin."}), 403
    data = request.get_json(silent=True) or {}
    title = (data.get("title") or "").strip()[:200]
    if not title:
        return jsonify({"error": "title is required."}), 400
    stage = data.get("stage") or "prospecting"
    if stage not in CrmDeal.STAGE_DEFAULT_PROB:
        stage = "prospecting"
    deal = CrmDeal(
        owner_user_id=user["id"], title=title,
        contact_id=data.get("contact_id") or None, customer_id=data.get("customer_id") or None,
        value=float(data.get("value") or 0), currency=(data.get("currency") or "USD")[:8],
        stage=stage,
        probability_pct=int(data.get("probability_pct") or CrmDeal.STAGE_DEFAULT_PROB[stage]),
        expected_close_date=_parse_date(data.get("expected_close_date")),
    )
    # Feature 57 hook: auto-assign a rep via territory rules using the
    # linked contact/customer's own text (company/address/notes).
    blob = ""
    if deal.contact_id:
        c = CrmContact.query.get(deal.contact_id)
        if c: blob = " ".join(filter(None, [c.company, c.notes]))
    elif deal.customer_id:
        c = ErpCustomer.query.get(deal.customer_id)
        if c: blob = " ".join(filter(None, [c.address, c.notes]))
    rule = _crm_route_territory(user["id"], blob)
    if rule:
        deal.assigned_rep = rule.assigned_rep
        deal.territory_id = rule.id

    db.session.add(deal)
    db.session.commit()
    return jsonify({"ok": True, "deal": deal.to_dict()}), 201


@app.route("/api/crm/deals/<int:deal_id>", methods=["PUT", "DELETE"])
def crm_deal_update(deal_id):
    user, err = _erp_user_or_401()
    if err: return err
    deal = CrmDeal.query.filter_by(id=deal_id, owner_user_id=user["id"]).first()
    if not deal:
        return jsonify({"error": "Not found."}), 404
    if not _csrf_ok():
        return jsonify({"error": "Invalid request origin."}), 403

    if request.method == "DELETE":
        db.session.delete(deal)
        db.session.commit()
        return jsonify({"ok": True}), 200

    data = request.get_json(silent=True) or {}
    was_won = deal.stage == "won"
    for field in ("title", "assigned_rep", "lost_reason"):
        if field in data and data[field] is not None:
            setattr(deal, field, str(data[field])[:200])
    if "value" in data:
        deal.value = float(data.get("value") or 0)
    if "probability_pct" in data:
        deal.probability_pct = max(0, min(100, int(data.get("probability_pct") or 0)))
    if "expected_close_date" in data:
        deal.expected_close_date = _parse_date(data.get("expected_close_date"))
    if "stage" in data and data["stage"] in CrmDeal.STAGE_DEFAULT_PROB:
        deal.stage = data["stage"]
        if "probability_pct" not in data:
            deal.probability_pct = CrmDeal.STAGE_DEFAULT_PROB[deal.stage]
        if deal.stage in ("won", "lost"):
            deal.closed_at = datetime.utcnow()

    db.session.commit()

    # Feature 56 hook: crossing into "won" for the first time generates
    # a commission record from the owner's matching rate rule.
    if deal.stage == "won" and not was_won:
        rule = (CommissionRule.query.filter_by(owner_user_id=user["id"], rep_name=deal.assigned_rep).first()
                or CommissionRule.query.filter_by(owner_user_id=user["id"], rep_name=None).first())
        rate = rule.rate_pct if rule else 5.0
        rec = CommissionRecord(
            owner_user_id=user["id"], deal_id=deal.id, rep_name=deal.assigned_rep,
            sale_amount=deal.value, commission_rate=rate,
            commission_amount=round(deal.value * (rate / 100.0), 2),
        )
        db.session.add(rec)
        db.session.commit()

    return jsonify({"ok": True, "deal": deal.to_dict()}), 200


@app.route("/api/crm/deals/forecast", methods=["GET"])
def crm_deals_forecast():
    """Feature 51: pipeline forecasting — weighted (value x probability)
    total per expected-close month, for open deals only."""
    user, err = _erp_user_or_401()
    if err: return err
    rows = (CrmDeal.query.filter(CrmDeal.owner_user_id == user["id"],
                                  CrmDeal.stage.notin_(["won", "lost"])).all())
    by_month = {}
    for d in rows:
        key = d.expected_close_date.strftime("%Y-%m") if d.expected_close_date else "unscheduled"
        bucket = by_month.setdefault(key, {"month": key, "weighted_total": 0.0, "deal_count": 0, "open_value": 0.0})
        bucket["weighted_total"] += d.value * (d.probability_pct / 100.0)
        bucket["open_value"] += d.value
        bucket["deal_count"] += 1
    by_stage = {}
    for d in rows:
        by_stage.setdefault(d.stage, {"stage": d.stage, "count": 0, "value": 0.0})
        by_stage[d.stage]["count"] += 1
        by_stage[d.stage]["value"] += d.value
    return jsonify({
        "by_month": sorted([{**v, "weighted_total": round(v["weighted_total"], 2), "open_value": round(v["open_value"], 2)}
                             for v in by_month.values()], key=lambda x: x["month"]),
        "by_stage": list(by_stage.values()),
    }), 200


