@app.route("/api/erp/quotes/<int:qid>/convert-to-order", methods=["POST"])
def erp_quote_convert_to_order(qid):
    user, err = _erp_user_or_401()
    if err: return err
    if not _csrf_ok():
        return jsonify({"error": "Invalid request origin."}), 403
    q = ErpQuote.query.filter_by(id=qid, owner_user_id=user["id"]).first()
    if not q:
        return jsonify({"error": "Quote not found."}), 404
    if q.status not in ("accepted", "sent"):
        return jsonify({"error": "Only an accepted (or sent) quote can be converted to an order."}), 400
    order = SalesOrder(
        owner_user_id=user["id"], quote_id=q.id, customer_id=q.customer_id,
        order_number=f"SO-{q.quote_number}", currency=q.currency, total=q.total,
        notes=f"Auto-created from quote #{q.id}.",
    )
    q.status = "converted"
    db.session.add(order)
    db.session.commit()
    return jsonify({"ok": True, "order": order.to_dict()}), 201


