# ---------- 462e: SUBSCRIPTION / RECURRING BILLING DASHBOARD (feature 53) ----------

@app.route("/api/subscriptions/customers", methods=["GET", "POST"])
def customer_subscriptions():
    user, err = _erp_user_or_401()
    if err: return err
    if request.method == "GET":
        status = request.args.get("status")
        q = CustomerSubscription.query.filter_by(owner_user_id=user["id"])
        if status:
            q = q.filter_by(status=status)
        rows = q.order_by(CustomerSubscription.next_billing_date.asc().nulls_last()).all()
        return jsonify({"subscriptions": [s.to_dict() for s in rows]}), 200

    if not _csrf_ok():
        return jsonify({"error": "Invalid request origin."}), 403
    data = request.get_json(silent=True) or {}
    plan_name = (data.get("plan_name") or "").strip()[:160]
    if not plan_name:
        return jsonify({"error": "plan_name is required."}), 400
    interval = data.get("billing_interval") if data.get("billing_interval") in ("monthly", "yearly") else "monthly"
    next_date = _parse_date(data.get("next_billing_date")) or (date.today() + timedelta(days=30 if interval == "monthly" else 365))
    sub = CustomerSubscription(
        owner_user_id=user["id"], customer_id=data.get("customer_id") or None, plan_name=plan_name,
        amount=float(data.get("amount") or 0), currency=(data.get("currency") or "USD")[:8],
        billing_interval=interval, next_billing_date=next_date,
        contract_end_date=_parse_date(data.get("contract_end_date")),
    )
    db.session.add(sub)
    db.session.commit()
    return jsonify({"ok": True, "subscription": sub.to_dict()}), 201


@app.route("/api/subscriptions/customers/<int:sub_id>", methods=["PUT", "DELETE"])
def customer_subscription_update(sub_id):
    user, err = _erp_user_or_401()
    if err: return err
    sub = CustomerSubscription.query.filter_by(id=sub_id, owner_user_id=user["id"]).first()
    if not sub:
        return jsonify({"error": "Not found."}), 404
    if not _csrf_ok():
        return jsonify({"error": "Invalid request origin."}), 403

    if request.method == "DELETE":
        db.session.delete(sub)
        db.session.commit()
        return jsonify({"ok": True}), 200

    data = request.get_json(silent=True) or {}
    if data.get("status") in ("active", "paused", "cancelled", "past_due"):
        sub.status = data["status"]
        if sub.status == "cancelled":
            sub.cancelled_at = datetime.utcnow()
    if "next_billing_date" in data:
        sub.next_billing_date = _parse_date(data.get("next_billing_date"))
    if "amount" in data:
        sub.amount = float(data.get("amount") or 0)
    db.session.commit()
    return jsonify({"ok": True, "subscription": sub.to_dict()}), 200


@app.route("/api/subscriptions/dashboard", methods=["GET"])
def subscriptions_dashboard():
    """Feature 53: MRR/ARR/active-count/churn summary from real rows,
    not simulated numbers."""
    user, err = _erp_user_or_401()
    if err: return err
    rows = CustomerSubscription.query.filter_by(owner_user_id=user["id"]).all()
    active = [s for s in rows if s.status == "active"]
    past_due = [s for s in rows if s.status == "past_due"]
    cancelled_30d = [s for s in rows if s.status == "cancelled" and s.cancelled_at
                      and s.cancelled_at >= datetime.utcnow() - timedelta(days=30)]
    mrr = sum(s.amount if s.billing_interval == "monthly" else s.amount / 12.0 for s in active)
    base_count = len([s for s in rows if s.started_at and s.started_at < datetime.utcnow() - timedelta(days=30)])
    churn_rate = round((len(cancelled_30d) / base_count) * 100, 2) if base_count else 0.0
    return jsonify({
        "active_count": len(active), "past_due_count": len(past_due),
        "mrr": round(mrr, 2), "arr": round(mrr * 12, 2),
        "churned_last_30_days": len(cancelled_30d), "churn_rate_pct": churn_rate,
    }), 200


@app.route("/api/subscriptions/renewals-due", methods=["GET"])
def subscriptions_renewals_due():
    """Feature 60 — renewal/contract expiration alerting, scoped to
    customer subscriptions (VendorContract already covers the vendor
    side under Vendor Contracts). Returns anything renewing or
    contractually ending within `days` (default 30)."""
    user, err = _erp_user_or_401()
    if err: return err
    days = min(max(request.args.get("days", default=30, type=int) or 30, 1), 365)
    horizon = date.today() + timedelta(days=days)
    rows = (CustomerSubscription.query
            .filter(CustomerSubscription.owner_user_id == user["id"],
                    CustomerSubscription.status.in_(["active", "past_due"]))
            .all())
    due = []
    for s in rows:
        next_due = s.contract_end_date or s.next_billing_date
        if next_due and next_due <= horizon:
            d = s.to_dict()
            d["renewal_type"] = "contract_end" if s.contract_end_date else "billing_cycle"
            d["due_date"] = next_due.isoformat()
            due.append(d)
    due.sort(key=lambda x: x["due_date"])
    return jsonify({"renewals_due": due, "horizon_days": days}), 200


# ---------- 462f: CUSTOMER HEALTH SCORING (feature 54) ----------

@app.route("/api/customer-health/<int:customer_id>", methods=["GET"])
def customer_health_get(customer_id):
    user, err = _erp_user_or_401()
    if err: return err
    score, status, factors = _crm_compute_health(user["id"], customer_id)
    snapshot = CustomerHealthScore(owner_user_id=user["id"], customer_id=customer_id, score=score,
                                    status=status, factors_json=json.dumps(factors))
    db.session.add(snapshot)
    db.session.commit()
    return jsonify({"health": snapshot.to_dict()}), 200


@app.route("/api/customer-health", methods=["GET"])
def customer_health_list():
    """Latest snapshot per customer this owner has ever scored."""
    user, err = _erp_user_or_401()
    if err: return err
    rows = (CustomerHealthScore.query.filter_by(owner_user_id=user["id"])
            .order_by(CustomerHealthScore.computed_at.desc()).all())
    latest = {}
    for r in rows:
        if r.customer_id not in latest:
            latest[r.customer_id] = r
    ordered = sorted(latest.values(), key=lambda r: r.score)
    return jsonify({"scores": [r.to_dict() for r in ordered]}), 200


# ---------- 462g: DUNNING FOR FAILED PAYMENTS (feature 55) ----------

@app.route("/api/dunning/failures", methods=["GET", "POST"])
def dunning_failures():
    user, err = _erp_user_or_401()
    if err: return err
    if request.method == "GET":
        resolved = request.args.get("resolved")
        q = PaymentFailure.query.filter_by(owner_user_id=user["id"])
        if resolved is not None:
            q = q.filter_by(resolved=(resolved == "true"))
        rows = q.order_by(PaymentFailure.created_at.desc()).all()
        return jsonify({"failures": [f.to_dict() for f in rows]}), 200

    if not _csrf_ok():
        return jsonify({"error": "Invalid request origin."}), 403
    data = request.get_json(silent=True) or {}
    sub = CustomerSubscription.query.filter_by(id=data.get("subscription_id"), owner_user_id=user["id"]).first()
    if not sub:
        return jsonify({"error": "subscription_id must reference one of your subscriptions."}), 400
    failure = PaymentFailure(
        owner_user_id=user["id"], subscription_id=sub.id, amount=float(data.get("amount") or sub.amount),
        currency=sub.currency, failure_reason=(data.get("failure_reason") or "Card declined")[:200],
        next_retry_at=datetime.utcnow() + timedelta(days=PaymentFailure.RETRY_SCHEDULE_DAYS[0]),
    )
    sub.status = "past_due"
    db.session.add(failure)
    db.session.commit()
    return jsonify({"ok": True, "failure": failure.to_dict()}), 201


@app.route("/api/dunning/failures/<int:failure_id>/retry", methods=["POST"])
def dunning_failure_retry(failure_id):
    """Records another retry attempt and schedules the next one per
    RETRY_SCHEDULE_DAYS; the owner triggers the actual charge through
    their existing payment integration and reports the outcome here."""
    user, err = _erp_user_or_401()
    if err: return err
    if not _csrf_ok():
        return jsonify({"error": "Invalid request origin."}), 403
    failure = PaymentFailure.query.filter_by(id=failure_id, owner_user_id=user["id"]).first()
    if not failure:
        return jsonify({"error": "Not found."}), 404
    failure.attempt_number += 1
    schedule = PaymentFailure.RETRY_SCHEDULE_DAYS
    idx = min(failure.attempt_number - 1, len(schedule) - 1)
    failure.next_retry_at = datetime.utcnow() + timedelta(days=schedule[idx])
    db.session.commit()
    return jsonify({"ok": True, "failure": failure.to_dict()}), 200


@app.route("/api/dunning/failures/<int:failure_id>/resolve", methods=["POST"])
def dunning_failure_resolve(failure_id):
    user, err = _erp_user_or_401()
    if err: return err
    if not _csrf_ok():
        return jsonify({"error": "Invalid request origin."}), 403
    failure = PaymentFailure.query.filter_by(id=failure_id, owner_user_id=user["id"]).first()
    if not failure:
        return jsonify({"error": "Not found."}), 404
    failure.resolved = True
    db.session.commit()
    sub = CustomerSubscription.query.get(failure.subscription_id)
    if sub and not PaymentFailure.query.filter_by(subscription_id=sub.id, resolved=False).count():
        sub.status = "active"
        db.session.commit()
    return jsonify({"ok": True, "failure": failure.to_dict()}), 200


