# ---------- 463b: SHARED HELPERS ----------

def _collab_emit(event, payload, doc_id):
    """Broadcasts a document update to every other browser tab open on
    the same CollabDocument, mirrors the _pos_emit pattern used by the
    Till/POS real-time layer (STAGE 500)."""
    if not FLASK_SOCKETIO_AVAILABLE or not socketio_app:
        return
    try:
        socketio_app.emit(event, payload, room=f"collabdoc_{doc_id}", namespace="/collab")
    except Exception as e:
        logging.error(f"[COLLAB EMIT ERROR] {e}")


if FLASK_SOCKETIO_AVAILABLE and socketio_app:
    @socketio_app.on("join_doc", namespace="/collab")
    def _collab_join(data):
        from flask_socketio import join_room
        doc_id = (data or {}).get("doc_id")
        if doc_id:
            join_room(f"collabdoc_{doc_id}")

    @socketio_app.on("leave_doc", namespace="/collab")
    def _collab_leave(data):
        from flask_socketio import leave_room
        doc_id = (data or {}).get("doc_id")
        if doc_id:
            leave_room(f"collabdoc_{doc_id}")

    @socketio_app.on("doc_edit", namespace="/collab")
    def _collab_edit(data):
        # Whole-document broadcast, last-write-wins — see CollabDocument
        # docstring. The HTTP PUT below is what actually persists it;
        # this socket event is the live "other tabs update instantly" path.
        doc_id = (data or {}).get("doc_id")
        if not doc_id:
            return
        socketio_app.emit("doc_updated", {
            "doc_id": doc_id,
            "content": (data or {}).get("content", ""),
            "editor": (data or {}).get("editor", "Someone"),
        }, room=f"collabdoc_{doc_id}", namespace="/collab", include_self=False)


