    col = KanbanColumn.query.get(card.column_id)
    board = KanbanBoard.query.filter_by(id=col.board_id, owner_user_id=user["id"]).first() if col else None
    if not board: return jsonify({"error": "Card not found."}), 404
    data = request.get_json(silent=True) or {}
    if "title" in data: card.title = (data["title"] or card.title).strip()
    if "description" in data: card.description = data["description"]
    if "assignee" in data: card.assignee = data["assignee"]
    if "column_id" in data:
        new_col = KanbanColumn.query.filter_by(id=data["column_id"], board_id=board.id).first()
        if new_col: card.column_id = new_col.id
    if "position" in data:
        try: card.position = int(data["position"])
        except Exception: pass
    if "due_date" in data:
        try: card.due_date = datetime.strptime(data["due_date"], "%Y-%m-%d").date() if data["due_date"] else None
        except Exception: pass
    db.session.commit()
    return jsonify({"ok": True, "card": card.to_dict()}), 200


