@app.route("/api/calendar-sync/pull", methods=["POST"])
@csrf.exempt
def calendar_sync_pull():
    """Pulls upcoming events from whichever provider(s) are connected
    and mirrors them locally in CalendarSyncLink (direction=inbound),
    upserting by external_event_id so repeated pulls don't duplicate."""
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    pulled = []

    g_token = get_valid_calendar_token(user["id"])
    if g_token:
        try:
            resp = requests.get(
                "https://www.googleapis.com/calendar/v3/calendars/primary/events",
                headers={"Authorization": f"Bearer {g_token}"},
                params={"timeMin": datetime.utcnow().isoformat() + "Z", "maxResults": 25,
                        "singleEvents": "true", "orderBy": "startTime"}, timeout=12)
            items = resp.json().get("items", []) if resp.status_code == 200 else []
            for e in items:
                ext_id = e.get("id")
                start = (e.get("start", {}) or {}).get("dateTime") or (e.get("start", {}) or {}).get("date")
                end = (e.get("end", {}) or {}).get("dateTime") or (e.get("end", {}) or {}).get("date")
                link = CalendarSyncLink.query.filter_by(owner_user_id=user["id"], provider="google", external_event_id=ext_id).first()
                if not link:
                    link = CalendarSyncLink(owner_user_id=user["id"], provider="google", external_event_id=ext_id, direction="inbound")
                    db.session.add(link)
                link.title = e.get("summary", "(No title)")
                try: link.start_time = datetime.fromisoformat(start.replace("Z", "+00:00")) if start else None
                except Exception: link.start_time = None
                try: link.end_time = datetime.fromisoformat(end.replace("Z", "+00:00")) if end else None
                except Exception: link.end_time = None
                link.synced_at = datetime.utcnow()
                pulled.append(link)
        except Exception as e:
            logging.error(f"[CAL SYNC PULL GOOGLE ERROR] {e}")

    ms_token = get_valid_microsoft_token(user["id"])
    if ms_token:
        try:
            resp = requests.get(
                "https://graph.microsoft.com/v1.0/me/events",
                headers={"Authorization": f"Bearer {ms_token}"},
                params={"$top": 25, "$orderby": "start/dateTime"}, timeout=12)
            items = resp.json().get("value", []) if resp.status_code == 200 else []
            for e in items:
                ext_id = e.get("id")
                start = (e.get("start", {}) or {}).get("dateTime")
                end = (e.get("end", {}) or {}).get("dateTime")
                link = CalendarSyncLink.query.filter_by(owner_user_id=user["id"], provider="outlook", external_event_id=ext_id).first()
                if not link:
                    link = CalendarSyncLink(owner_user_id=user["id"], provider="outlook", external_event_id=ext_id, direction="inbound")
                    db.session.add(link)
                link.title = e.get("subject", "(No title)")
                try: link.start_time = datetime.fromisoformat(start) if start else None
                except Exception: link.start_time = None
                try: link.end_time = datetime.fromisoformat(end) if end else None
                except Exception: link.end_time = None
                link.synced_at = datetime.utcnow()
                pulled.append(link)
        except Exception as e:
            logging.error(f"[CAL SYNC PULL OUTLOOK ERROR] {e}")

    db.session.commit()
    return jsonify({"ok": True, "pulled": len(pulled)}), 200


@app.route("/api/calendar-sync/push", methods=["POST"])
@csrf.exempt
def calendar_sync_push():
    """Pushes a local item (e.g. a Kanban card due date, or any ad-hoc
    title/time) out to Google or Outlook as a real event."""
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    provider = (data.get("provider") or "google").strip()
    title = (data.get("title") or "").strip()
    start_time = data.get("start_time")
    end_time = data.get("end_time")
    if not title or not start_time or not end_time:
        return jsonify({"error": "title, start_time and end_time are required."}), 400

    if provider == "outlook":
        token = get_valid_microsoft_token(user["id"])
        if not token:
            return jsonify({"error": "Not connected to Outlook Calendar."}), 400
        try:
            resp = requests.post(
                "https://graph.microsoft.com/v1.0/me/events",
                headers={"Authorization": f"Bearer {token}", "Content-Type": "application/json"},
                json={"subject": title,
                      "start": {"dateTime": start_time, "timeZone": "UTC"},
                      "end": {"dateTime": end_time, "timeZone": "UTC"}}, timeout=12)
            if resp.status_code not in (200, 201):
                return jsonify({"error": "Outlook Calendar rejected the event."}), 502
            ev = resp.json()
            ext_id = ev.get("id")
        except Exception as e:
            return jsonify({"error": str(e)}), 500
    else:
        token = get_valid_calendar_token(user["id"])
        if not token:
            return jsonify({"error": "Not connected to Google Calendar."}), 400
        try:
            resp = requests.post(
                "https://www.googleapis.com/calendar/v3/calendars/primary/events",
                headers={"Authorization": f"Bearer {token}", "Content-Type": "application/json"},
                json={"summary": title, "start": {"dateTime": start_time}, "end": {"dateTime": end_time}}, timeout=12)
            if resp.status_code not in (200, 201):
                return jsonify({"error": "Google Calendar rejected the event."}), 502
            ev = resp.json()
            ext_id = ev.get("id")
        except Exception as e:
            return jsonify({"error": str(e)}), 500
        provider = "google"

    link = CalendarSyncLink(owner_user_id=user["id"], provider=provider, external_event_id=ext_id,
                             direction="outbound", title=title, source=data.get("source"),
                             source_id=data.get("source_id"))
    try:
        link.start_time = datetime.fromisoformat(start_time.replace("Z", "+00:00"))
        link.end_time = datetime.fromisoformat(end_time.replace("Z", "+00:00"))
    except Exception:
        pass
    db.session.add(link)
    db.session.commit()
    return jsonify({"ok": True, "link": link.to_dict()}), 201


