    req = ApprovalRequest.query.filter_by(id=req_id, owner_user_id=user["id"]).first()
    if not req: return jsonify({"error": "Request not found."}), 404
    data = request.get_json(silent=True) or {}
    signer = ApprovalSigner.query.filter_by(id=data.get("signer_id"), request_id=req.id).first()
    if signer:
        signer.status = "rejected"
        signer.signed_at = datetime.utcnow()
    req.status = "rejected"
    req.decided_at = datetime.utcnow()
    db.session.commit()
    return jsonify({"ok": True, "request": req.to_dict()}), 200


