@app.route("/api/meetings/transcripts/<int:t_id>/summarize", methods=["POST"])
@csrf.exempt
def meeting_transcripts_summarize(t_id):
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    row = MeetingTranscript.query.filter_by(id=t_id, owner_user_id=user["id"]).first()
    if not row: return jsonify({"error": "Transcript not found."}), 404
    if not row.transcript_text:
        return jsonify({"error": "No transcript text to summarize."}), 400
    gate_result = gate_ai_usage(user, "meeting_transcripts_summarize")
    if gate_result is not None:
        return gate_result
    prompt = (
        "You are a professional meeting analyst. Read the transcript below and write:\n"
        "1. A 2-sentence executive summary.\n"
        "2. Action items, one per line, each with an owner if mentioned.\n\n"
        f"TRANSCRIPT:\n{row.transcript_text[:20000]}"
    )
    try:
        result_raw, _ = generate_ai_reply(prompt, [])
    except Exception as e:
        return jsonify({"error": f"Summarisation failed: {e}"}), 502
    parts = result_raw.split("Action items", 1) if "Action items" in result_raw else [result_raw, ""]
    row.summary_text = parts[0].strip()
    row.action_items_text = ("Action items" + parts[1]).strip() if len(parts) > 1 and parts[1] else None
    db.session.commit()
    return jsonify({"ok": True, "transcript": row.to_dict()}), 200


