@app.route("/api/time-tracking/timesheets/submit", methods=["POST"])
@csrf.exempt
def time_tracking_timesheet_submit():
    """Aggregates a week's TimeEntry rows for one staff member into a
    TimesheetPeriod and submits it for manager approval."""
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    try:
        week_start = datetime.strptime(data.get("week_start", ""), "%Y-%m-%d").date()
    except Exception:
        return jsonify({"error": "week_start (YYYY-MM-DD) is required."}), 400
    week_end = week_start + timedelta(days=6)
    employee_id = data.get("employee_id")
    staff_name = data.get("staff_name")
    q = TimeEntry.query.filter(TimeEntry.owner_user_id == user["id"],
                                TimeEntry.work_date >= week_start, TimeEntry.work_date <= week_end)
    if employee_id: q = q.filter(TimeEntry.employee_id == employee_id)
    elif staff_name: q = q.filter(TimeEntry.staff_name == staff_name)
    entries = q.all()
    total_minutes = sum((e.clock_out - e.clock_in).total_seconds() / 60.0 for e in entries if e.clock_in and e.clock_out)

    sheet = TimesheetPeriod.query.filter_by(owner_user_id=user["id"], employee_id=employee_id,
                                              staff_name=staff_name, week_start=week_start).first()
    if not sheet:
        sheet = TimesheetPeriod(owner_user_id=user["id"], employee_id=employee_id, staff_name=staff_name, week_start=week_start)
        db.session.add(sheet)
    sheet.total_minutes = round(total_minutes, 1)
    sheet.status = "submitted"
    sheet.submitted_at = datetime.utcnow()
    db.session.commit()
    return jsonify({"ok": True, "timesheet": sheet.to_dict()}), 200


