# ---------- STAGE 512: IN-APP PLATFORM SUPPORT CHAT (roadmap gap) ----------
# Real chat + ticket history between the signed-in business owner and the
# Connect It platform's own support team — distinct from SupportTicket
# (the owner's OWN customers writing in via their storefront) and from
# InternalTicket (an internal IT/HR helpdesk for the owner's staff).
# Admin replies reuse the existing five-admin _require_admin() gate —
# no separate agent-role system invented.

class PlatformSupportTicket(db.Model):
    __tablename__ = "platform_support_tickets"
    id            = db.Column(db.Integer, primary_key=True)
    owner_user_id = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    subject       = db.Column(db.String(200), nullable=False)
    category      = db.Column(db.String(20), nullable=False, default="general")  # general, billing, bug, feature_request, account
    status        = db.Column(db.String(16), nullable=False, default="open", index=True)  # open, in_progress, resolved, closed
    created_at    = db.Column(db.DateTime, default=datetime.utcnow, index=True)
    updated_at    = db.Column(db.DateTime, default=datetime.utcnow, onupdate=datetime.utcnow)

    def to_dict(self, include_messages=False):
        d = {"id": self.id, "subject": self.subject, "category": self.category, "status": self.status,
             "created_at": self.created_at.isoformat() if self.created_at else None,
             "updated_at": self.updated_at.isoformat() if self.updated_at else None}
        if include_messages:
            msgs = (PlatformSupportMessage.query.filter_by(ticket_id=self.id)
                    .order_by(PlatformSupportMessage.created_at.asc()).all())
            d["messages"] = [m.to_dict() for m in msgs]
        else:
            last = (PlatformSupportMessage.query.filter_by(ticket_id=self.id)
                    .order_by(PlatformSupportMessage.created_at.desc()).first())
            d["last_message"] = last.to_dict() if last else None
        return d


class PlatformSupportMessage(db.Model):
    __tablename__ = "platform_support_messages"
    id          = db.Column(db.Integer, primary_key=True)
    ticket_id   = db.Column(db.Integer, db.ForeignKey("platform_support_tickets.id"), nullable=False, index=True)
    sender_type = db.Column(db.String(12), nullable=False)  # 'user' or 'support'
    body        = db.Column(db.Text, nullable=False)
    created_at  = db.Column(db.DateTime, default=datetime.utcnow, index=True)

    def to_dict(self):
        return {"id": self.id, "sender_type": self.sender_type, "body": self.body,
                "created_at": self.created_at.isoformat() if self.created_at else None}


