    reason            = db.Column(db.String(24), nullable=False, default="surplus_to_deficit")  # surplus_to_deficit, customer_return, carrier_recall
    status            = db.Column(db.String(16), nullable=False, default="requested", index=True)  # requested, in_transit, delivered, cancelled
    requested_date    = db.Column(db.Date, nullable=True)
    completed_date    = db.Column(db.Date, nullable=True)
    notes             = db.Column(db.String(300), nullable=True)
    created_at        = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        return {"id": self.id, "container_number": self.container_number, "container_size": self.container_size,
                "from_depot": self.from_depot, "to_depot": self.to_depot, "reason": self.reason,
                "status": self.status,
                "requested_date": self.requested_date.isoformat() if self.requested_date else None,
                "completed_date": self.completed_date.isoformat() if self.completed_date else None,
                "notes": self.notes, "created_at": self.created_at.isoformat() if self.created_at else None}


