# ---- 3. FREIGHT-RATE BENCHMARKING INDEX ----
# Real peer-submitted rates only — never a fabricated external market
# feed. The index only returns an aggregate once at least 3 different
# businesses have submitted a rate for that lane/size (k-anonymity
# floor), same principle as the existing Aggregated Economic Data
# Licensing product.
FREIGHT_RATE_MIN_SUBMISSIONS = 3

class FreightRateSubmission(db.Model):
    __tablename__ = "freight_rate_submissions"
    id                = db.Column(db.Integer, primary_key=True)
    owner_user_id     = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    origin_port       = db.Column(db.String(120), nullable=False, index=True)
    destination_port  = db.Column(db.String(120), nullable=False, index=True)
    container_size    = db.Column(db.String(10), nullable=False, default="40ft", index=True)
    carrier_name      = db.Column(db.String(120), nullable=True)
    rate_amount       = db.Column(db.Float, nullable=False)
    currency          = db.Column(db.String(8), nullable=False, default="USD")
    quoted_date       = db.Column(db.Date, nullable=True)
    created_at        = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        return {"id": self.id, "origin_port": self.origin_port, "destination_port": self.destination_port,
                "container_size": self.container_size, "carrier_name": self.carrier_name,
                "rate_amount": self.rate_amount, "currency": self.currency,
                "quoted_date": self.quoted_date.isoformat() if self.quoted_date else None,
                "created_at": self.created_at.isoformat() if self.created_at else None}


@app.route("/api/logistics/freight-rates", methods=["POST"])
@csrf.exempt
def freight_rate_submit():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    origin = (data.get("origin_port") or "").strip()
    dest = (data.get("destination_port") or "").strip()
    try:
        rate = float(data.get("rate_amount"))
    except (TypeError, ValueError):
        rate = None
    if not origin or not dest or not rate:
        return jsonify({"error": "origin_port, destination_port, and rate_amount are required."}), 400
    row = FreightRateSubmission(owner_user_id=user["id"], origin_port=origin[:120], destination_port=dest[:120],
                                 container_size=data.get("container_size", "40ft"),
                                 carrier_name=(data.get("carrier_name") or "").strip()[:120] or None,
                                 rate_amount=rate, currency=data.get("currency", "USD"),
                                 quoted_date=_erp_parse_date(data.get("quoted_date"), date.today()))
    db.session.add(row); db.session.commit()
    return jsonify({"ok": True, "submission": row.to_dict()}), 201


