@app.route("/api/logistics/freight-rates/index", methods=["GET"])
def freight_rate_index():
    user, err = _erp_user_or_401()
    if err: return err
    origin = (request.args.get("origin") or "").strip()
    dest = (request.args.get("destination") or "").strip()
    size = (request.args.get("container_size") or "40ft").strip()
    if not origin or not dest:
        return jsonify({"error": "origin and destination query params are required."}), 400
    cutoff = datetime.utcnow() - timedelta(days=365)
    rows = (FreightRateSubmission.query
            .filter(FreightRateSubmission.origin_port.ilike(origin),
                    FreightRateSubmission.destination_port.ilike(dest),
                    FreightRateSubmission.container_size == size,
                    FreightRateSubmission.created_at >= cutoff).all())
    distinct_submitters = len(set(r.owner_user_id for r in rows))
    if distinct_submitters < FREIGHT_RATE_MIN_SUBMISSIONS:
        return jsonify({"available": False,
                         "reason": f"Fewer than {FREIGHT_RATE_MIN_SUBMISSIONS} businesses have submitted a rate for "
                                   f"this lane in the last 12 months — not enough data to publish a fair benchmark yet.",
                         "submissions_so_far": distinct_submitters}), 200
    amounts = sorted(r.rate_amount for r in rows)
    n = len(amounts)
    median = amounts[n // 2] if n % 2 else (amounts[n // 2 - 1] + amounts[n // 2]) / 2
    return jsonify({"available": True, "origin_port": origin, "destination_port": dest, "container_size": size,
                     "median_rate": round(median, 2), "min_rate": round(min(amounts), 2),
                     "max_rate": round(max(amounts), 2), "sample_size": n,
                     "distinct_businesses": distinct_submitters,
                     "window": "trailing 12 months"}), 200


