@app.route("/api/board/resolutions", methods=["POST"])
@csrf.exempt
def board_resolutions_add():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    title = (data.get("title") or "").strip()[:200]
    if not title:
        return jsonify({"error": "title is required."}), 400
    if data.get("meeting_id"):
        if not BoardMeeting.query.filter_by(id=data.get("meeting_id"), owner_id=user["id"]).first():
            return jsonify({"error": "Meeting not found."}), 404
    try:
        votes_for = int(data.get("votes_for", 0) or 0)
        votes_against = int(data.get("votes_against", 0) or 0)
        votes_abstain = int(data.get("votes_abstain", 0) or 0)
    except (TypeError, ValueError):
        return jsonify({"error": "vote counts must be numbers."}), 400
    outcome = "pending"
    if votes_for or votes_against:
        outcome = "passed" if votes_for > votes_against else "failed"
    r = BoardResolution(
        owner_id=user["id"], meeting_id=data.get("meeting_id"),
        resolution_number=(data.get("resolution_number") or _erp_gen_number("RES")).strip()[:40],
        title=title, description=(data.get("description") or "").strip() or None,
        proposed_by=(data.get("proposed_by") or "").strip()[:120] or None,
        votes_for=votes_for, votes_against=votes_against, votes_abstain=votes_abstain,
        outcome=data.get("outcome") if data.get("outcome") in ("pending", "passed", "failed") else outcome,
        resolution_date=_erp_parse_date(data.get("resolution_date")),
    )
    db.session.add(r); db.session.commit()
    return jsonify({"resolution": r.to_dict()}), 201


@app.route("/api/board/resolutions/<int:res_id>", methods=["PUT"])
@csrf.exempt
def board_resolutions_update(res_id):
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    r = BoardResolution.query.filter_by(id=res_id, owner_id=user["id"]).first()
    if not r: return jsonify({"error": "Resolution not found."}), 404
    data = request.get_json(silent=True) or {}
    for field in ("votes_for", "votes_against", "votes_abstain"):
        if field in data:
            try:
                setattr(r, field, int(data.get(field) or 0))
            except (TypeError, ValueError):
                return jsonify({"error": f"{field} must be a number."}), 400
    if "outcome" in data and data.get("outcome") in ("pending", "passed", "failed"):
        r.outcome = data.get("outcome")
    elif any(f in data for f in ("votes_for", "votes_against")):
        r.outcome = "passed" if r.votes_for > r.votes_against else ("failed" if r.votes_against > r.votes_for else "pending")
    if "resolution_date" in data:
        r.resolution_date = _erp_parse_date(data.get("resolution_date"))
    db.session.commit()
    return jsonify({"resolution": r.to_dict()}), 200


