class CapTableShareholder(db.Model):
    __tablename__     = "captable_shareholders"
    id                = db.Column(db.Integer, primary_key=True)
    owner_id          = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    name              = db.Column(db.String(160), nullable=False)
    email             = db.Column(db.String(160), nullable=True)
    shareholder_type  = db.Column(db.String(20), nullable=False, default="founder")  # founder, investor, employee, other
    created_at        = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        return {"id": self.id, "name": self.name, "email": self.email,
                "shareholder_type": self.shareholder_type,
                "created_at": self.created_at.isoformat() if self.created_at else None}


class CapTableShareClass(db.Model):
    __tablename__       = "captable_share_classes"
    id                  = db.Column(db.Integer, primary_key=True)
    owner_id            = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    name                = db.Column(db.String(80), nullable=False)   # e.g. "Common", "Series A Preferred"
    authorized_shares   = db.Column(db.Integer, nullable=False, default=0)
    created_at          = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        return {"id": self.id, "name": self.name, "authorized_shares": self.authorized_shares,
                "created_at": self.created_at.isoformat() if self.created_at else None}


class CapTableIssuance(db.Model):
    __tablename__     = "captable_issuances"
    id                = db.Column(db.Integer, primary_key=True)
    owner_id          = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    shareholder_id    = db.Column(db.Integer, db.ForeignKey("captable_shareholders.id"), nullable=False, index=True)
    share_class_id    = db.Column(db.Integer, db.ForeignKey("captable_share_classes.id"), nullable=False, index=True)
    shares            = db.Column(db.Integer, nullable=False, default=0)
    price_per_share   = db.Column(db.Float, nullable=True)
    transaction_type  = db.Column(db.String(20), nullable=False, default="issuance")  # issuance, transfer, buyback
    issue_date        = db.Column(db.Date, nullable=True)
    notes             = db.Column(db.String(300), nullable=True)
    created_at        = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        return {
            "id": self.id, "shareholder_id": self.shareholder_id, "share_class_id": self.share_class_id,
            "shares": self.shares, "price_per_share": self.price_per_share,
            "transaction_type": self.transaction_type,
            "issue_date": self.issue_date.isoformat() if self.issue_date else None,
            "notes": self.notes, "created_at": self.created_at.isoformat() if self.created_at else None,
        }


