@app.route("/api/captable/issuances", methods=["POST"])
@csrf.exempt
def captable_issuances_add():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    shareholder = CapTableShareholder.query.filter_by(id=data.get("shareholder_id"), owner_id=user["id"]).first()
    share_class = CapTableShareClass.query.filter_by(id=data.get("share_class_id"), owner_id=user["id"]).first()
    if not shareholder or not share_class:
        return jsonify({"error": "shareholder_id and share_class_id must reference existing records."}), 400
    try:
        shares = int(data.get("shares", 0) or 0)
    except (TypeError, ValueError):
        return jsonify({"error": "shares must be a number."}), 400
    if shares == 0:
        return jsonify({"error": "shares cannot be zero."}), 400
    txn_type = data.get("transaction_type") if data.get("transaction_type") in ("issuance", "transfer", "buyback") else "issuance"
    issued_so_far = db.session.query(db.func.coalesce(db.func.sum(CapTableIssuance.shares), 0)).filter_by(
        owner_id=user["id"], share_class_id=share_class.id).scalar() or 0
    if txn_type != "buyback" and shares > 0 and (issued_so_far + shares) > share_class.authorized_shares > 0:
        return jsonify({"error": f"This would issue {issued_so_far + shares} shares against only "
                                  f"{share_class.authorized_shares} authorized in this class."}), 400
    price = None
    if data.get("price_per_share") not in (None, ""):
        try:
            price = float(data.get("price_per_share"))
        except (TypeError, ValueError):
            return jsonify({"error": "price_per_share must be a number."}), 400
    i = CapTableIssuance(
        owner_id=user["id"], shareholder_id=shareholder.id, share_class_id=share_class.id,
        shares=shares, price_per_share=price, transaction_type=txn_type,
        issue_date=_erp_parse_date(data.get("issue_date")) or datetime.utcnow().date(),
        notes=(data.get("notes") or "").strip()[:300] or None,
    )
    db.session.add(i); db.session.commit()
    return jsonify({"issuance": i.to_dict()}), 201


