@app.route("/api/captable/summary", methods=["GET"])
def captable_summary():
    user, err = _erp_user_or_401()
    if err: return err
    shareholders = {s.id: s for s in CapTableShareholder.query.filter_by(owner_id=user["id"]).all()}
    classes = {c.id: c for c in CapTableShareClass.query.filter_by(owner_id=user["id"]).all()}
    issuances = CapTableIssuance.query.filter_by(owner_id=user["id"]).all()

    net_by_shareholder = {}
    total_outstanding = 0
    for i in issuances:
        delta = i.shares if i.transaction_type != "buyback" else -abs(i.shares)
        net_by_shareholder[i.shareholder_id] = net_by_shareholder.get(i.shareholder_id, 0) + delta
        total_outstanding += delta

    rows = []
    for sh_id, net in net_by_shareholder.items():
        sh = shareholders.get(sh_id)
        if not sh or net <= 0:
            continue
        rows.append({
            "shareholder_id": sh_id, "name": sh.name, "shareholder_type": sh.shareholder_type,
            "shares_held": net,
            "ownership_pct": round((net / total_outstanding) * 100, 2) if total_outstanding > 0 else 0,
        })
    rows.sort(key=lambda r: r["shares_held"], reverse=True)

    class_totals = []
    for c in classes.values():
        issued = sum(i.shares for i in issuances if i.share_class_id == c.id and i.transaction_type != "buyback")
        bought_back = sum(abs(i.shares) for i in issuances if i.share_class_id == c.id and i.transaction_type == "buyback")
        class_totals.append({
            "share_class_id": c.id, "name": c.name, "authorized_shares": c.authorized_shares,
            "issued_shares": issued - bought_back,
        })

    return jsonify({
        "total_outstanding_shares": total_outstanding,
        "ownership": rows, "share_classes": class_totals,
    }), 200


# ─────────────────────────────────────────────────────────────
# 73. CONTRACT LIFECYCLE MANAGEMENT WITH RENEWAL ALERTS
# General-purpose register covering any counterparty/contract type —
# complements the existing vendor-specific VendorContract repository
# (ITEM 99) rather than duplicating it.
# ─────────────────────────────────────────────────────────────

class ContractRecord(db.Model):
    __tablename__       = "contract_records"
    id                  = db.Column(db.Integer, primary_key=True)
    owner_id            = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    contract_title       = db.Column(db.String(200), nullable=False)
    counterparty         = db.Column(db.String(160), nullable=False)
    contract_type         = db.Column(db.String(20), nullable=False, default="other")  # customer, vendor, lease, employment, nda, partnership, other
    contract_value        = db.Column(db.Float, nullable=True)
    currency              = db.Column(db.String(8), nullable=True)
    start_date            = db.Column(db.Date, nullable=True)
    end_date               = db.Column(db.Date, nullable=True, index=True)
    auto_renew             = db.Column(db.Boolean, nullable=False, default=False)
    renewal_notice_days    = db.Column(db.Integer, nullable=False, default=30)
    status                  = db.Column(db.String(20), nullable=False, default="active")  # draft, active, expired, terminated, renewed
    owner_contact           = db.Column(db.String(160), nullable=True)
    notes                   = db.Column(db.Text, nullable=True)
    created_at               = db.Column(db.DateTime, default=datetime.utcnow)

    def days_to_expiry(self):
        if not self.end_date:
            return None
        return (self.end_date - datetime.utcnow().date()).days

    def to_dict(self):
        return {
            "id": self.id, "contract_title": self.contract_title, "counterparty": self.counterparty,
            "contract_type": self.contract_type, "contract_value": self.contract_value, "currency": self.currency,
            "start_date": self.start_date.isoformat() if self.start_date else None,
            "end_date": self.end_date.isoformat() if self.end_date else None,
            "auto_renew": self.auto_renew, "renewal_notice_days": self.renewal_notice_days,
            "status": self.status, "owner_contact": self.owner_contact, "notes": self.notes,
            "days_to_expiry": self.days_to_expiry(),
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }


