@app.route("/api/contracts", methods=["POST"])
@csrf.exempt
def contracts_add():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    title = (data.get("contract_title") or "").strip()[:200]
    counterparty = (data.get("counterparty") or "").strip()[:160]
    if not title or not counterparty:
        return jsonify({"error": "contract_title and counterparty are required."}), 400
    try:
        value = float(data.get("contract_value")) if data.get("contract_value") not in (None, "") else None
        notice_days = int(data.get("renewal_notice_days", 30) or 30)
    except (TypeError, ValueError):
        return jsonify({"error": "contract_value/renewal_notice_days must be numbers."}), 400
    c = ContractRecord(
        owner_id=user["id"], contract_title=title, counterparty=counterparty,
        contract_type=data.get("contract_type") if data.get("contract_type") in
            ("customer", "vendor", "lease", "employment", "nda", "partnership", "other") else "other",
        contract_value=value, currency=(data.get("currency") or "").strip()[:8] or None,
        start_date=_erp_parse_date(data.get("start_date")), end_date=_erp_parse_date(data.get("end_date")),
        auto_renew=bool(data.get("auto_renew")), renewal_notice_days=notice_days,
        status=data.get("status") if data.get("status") in ("draft", "active", "expired", "terminated", "renewed") else "active",
        owner_contact=(data.get("owner_contact") or "").strip()[:160] or None,
        notes=(data.get("notes") or "").strip() or None,
    )
    db.session.add(c); db.session.commit()
    return jsonify({"contract": c.to_dict()}), 201


@app.route("/api/contracts/<int:contract_id>", methods=["PUT"])
@csrf.exempt
def contracts_update(contract_id):
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    c = ContractRecord.query.filter_by(id=contract_id, owner_id=user["id"]).first()
    if not c: return jsonify({"error": "Contract not found."}), 404
    data = request.get_json(silent=True) or {}
    if "contract_title" in data: c.contract_title = (data.get("contract_title") or "").strip()[:200] or c.contract_title
    if "counterparty" in data: c.counterparty = (data.get("counterparty") or "").strip()[:160] or c.counterparty
    if "contract_type" in data and data.get("contract_type") in ("customer", "vendor", "lease", "employment", "nda", "partnership", "other"):
        c.contract_type = data.get("contract_type")
    if "contract_value" in data:
        try:
            c.contract_value = float(data.get("contract_value")) if data.get("contract_value") not in (None, "") else None
        except (TypeError, ValueError):
            return jsonify({"error": "contract_value must be a number."}), 400
    if "currency" in data: c.currency = (data.get("currency") or "").strip()[:8] or None
    if "start_date" in data: c.start_date = _erp_parse_date(data.get("start_date"))
    if "end_date" in data: c.end_date = _erp_parse_date(data.get("end_date"))
    if "auto_renew" in data: c.auto_renew = bool(data.get("auto_renew"))
    if "renewal_notice_days" in data:
        try:
            c.renewal_notice_days = int(data.get("renewal_notice_days") or 30)
        except (TypeError, ValueError):
            return jsonify({"error": "renewal_notice_days must be a number."}), 400
    if "status" in data and data.get("status") in ("draft", "active", "expired", "terminated", "renewed"):
        c.status = data.get("status")
    if "owner_contact" in data: c.owner_contact = (data.get("owner_contact") or "").strip()[:160] or None
    if "notes" in data: c.notes = (data.get("notes") or "").strip() or None
    db.session.commit()
    return jsonify({"contract": c.to_dict()}), 200


