    user, err = _erp_user_or_401()
    if err: return err
    v = VendorOnboarding.query.filter_by(id=ob_id, owner_id=user["id"]).first()
    if not v: return jsonify({"error": "Onboarding record not found."}), 404
    tasks = VendorOnboardingTask.query.filter_by(onboarding_id=v.id).all()
    return jsonify({"onboarding": v.to_dict(tasks=tasks)}), 200


