@app.route("/api/entities/<int:entity_id>/entries", methods=["POST"])
@csrf.exempt
def entity_entries_add(entity_id):
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    e = BusinessEntity.query.filter_by(id=entity_id, owner_id=user["id"]).first()
    if not e: return jsonify({"error": "Entity not found."}), 404
    data = request.get_json(silent=True) or {}
    kind = data.get("kind")
    if kind not in ("income", "expense"):
        return jsonify({"error": "kind must be 'income' or 'expense'."}), 400
    try:
        amount = abs(float(data.get("amount", 0) or 0))
    except (TypeError, ValueError):
        return jsonify({"error": "amount must be a number."}), 400
    entry_date = _erp_parse_date(data.get("entry_date")) or datetime.utcnow().date()
    entry = EntityFinancialEntry(
        owner_id=user["id"], entity_id=e.id, entry_date=entry_date, kind=kind,
        account=(data.get("account") or "").strip()[:100] or None,
        description=(data.get("description") or "").strip()[:300] or None, amount=amount,
    )
    db.session.add(entry); db.session.commit()
    return jsonify({"entry": entry.to_dict()}), 201


