# ─────────────────────────────────────────────────────────────
# 79. BUSINESS CONTINUITY / DISASTER-RECOVERY PLAN TRACKER
# Distinct from the existing succession-planning module (STAGE 94,
# which covers founder death/incapacity): this tracks operational
# resilience of individual critical processes/systems — recovery
# objectives, backups, and drills.
# ─────────────────────────────────────────────────────────────

class BcdrCriticalProcess(db.Model):
    __tablename__       = "bcdr_critical_processes"
    id                  = db.Column(db.Integer, primary_key=True)
    owner_id            = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    process_name        = db.Column(db.String(160), nullable=False)
    department           = db.Column(db.String(100), nullable=True)
    rto_hours             = db.Column(db.Float, nullable=True)   # Recovery Time Objective
    rpo_hours             = db.Column(db.Float, nullable=True)   # Recovery Point Objective
    backup_method          = db.Column(db.String(160), nullable=True)
    backup_verified_at      = db.Column(db.DateTime, nullable=True)
    recovery_procedure       = db.Column(db.Text, nullable=True)
    primary_contact          = db.Column(db.String(160), nullable=True)
    backup_contact            = db.Column(db.String(160), nullable=True)
    created_at                 = db.Column(db.DateTime, default=datetime.utcnow)

    def coverage_status(self):
        if not self.backup_method or not self.recovery_procedure:
            return "gap"
        if not self.backup_verified_at or (datetime.utcnow() - self.backup_verified_at).days > 90:
            return "stale_verification"
        return "covered"

    def to_dict(self):
        return {
            "id": self.id, "process_name": self.process_name, "department": self.department,
            "rto_hours": self.rto_hours, "rpo_hours": self.rpo_hours, "backup_method": self.backup_method,
            "backup_verified_at": self.backup_verified_at.isoformat() if self.backup_verified_at else None,
            "recovery_procedure": self.recovery_procedure, "primary_contact": self.primary_contact,
            "backup_contact": self.backup_contact, "coverage_status": self.coverage_status(),
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }


class BcdrDrillLog(db.Model):
    __tablename__ = "bcdr_drill_logs"
    id            = db.Column(db.Integer, primary_key=True)
    owner_id      = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    process_id    = db.Column(db.Integer, db.ForeignKey("bcdr_critical_processes.id"), nullable=True, index=True)
    drill_date    = db.Column(db.Date, nullable=False)
    drill_type    = db.Column(db.String(80), nullable=True)
    outcome       = db.Column(db.String(20), nullable=False, default="passed")  # passed, partial, failed
    notes         = db.Column(db.Text, nullable=True)
    created_at    = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        return {"id": self.id, "process_id": self.process_id,
                "drill_date": self.drill_date.isoformat() if self.drill_date else None,
                "drill_type": self.drill_type, "outcome": self.outcome, "notes": self.notes,
                "created_at": self.created_at.isoformat() if self.created_at else None}


