@app.route("/api/bcdr/processes", methods=["POST"])
@csrf.exempt
def bcdr_processes_add():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    process_name = (data.get("process_name") or "").strip()[:160]
    if not process_name:
        return jsonify({"error": "process_name is required."}), 400
