@app.route("/api/fixed-assets/<int:asset_id>/post-depreciation", methods=["POST"])
@csrf.exempt
def fixed_assets_post_depreciation(asset_id):
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    a = FixedAsset.query.filter_by(id=asset_id, owner_id=user["id"]).first()
    if not a: return jsonify({"error": "Asset not found."}), 404
    this_month = datetime.utcnow().strftime("%Y-%m")
    if a.last_depreciation_month == this_month:
        return jsonify({"error": f"Depreciation for {this_month} was already posted for this asset."}), 400
    monthly_dep = a.monthly_depreciation()
    if monthly_dep <= 0:
        return jsonify({"error": "Nothing to depreciate (cost already at or below salvage value)."}), 400
    _erp_post_ledger(
        user["id"], datetime.utcnow().date(), "expense", "Depreciation",
        f"Monthly depreciation — {a.name} ({a.category})", -monthly_dep, ref_type="fixed_asset", ref_id=a.id,
    )
    a.last_depreciation_month = this_month
    db.session.commit()
    return jsonify({"ok": True, "amount_posted": monthly_dep, "book_value": a.book_value()}), 200


@app.route("/api/fixed-assets/depreciation-summary", methods=["GET"])
def fixed_assets_depreciation_summary():
    """Unified view across FixedAsset (general register) and the
    existing ITAsset register, so one screen shows every depreciable
    asset regardless of which register it was added through."""
    user, err = _erp_user_or_401()
    if err: return err
    fixed = FixedAsset.query.filter_by(owner_id=user["id"]).all()
    it = ITAsset.query.filter_by(user_id=user["id"]).all()
    rows = [dict(r.to_dict(), source="fixed_assets") for r in fixed]
    rows += [{
        "id": r.id, "name": r.name, "category": "it_" + r.category, "source": "it_assets",
        "purchase_cost": r.purchase_cost, "salvage_value": r.salvage_value,
        "useful_life_years": r.useful_life_years, "book_value": r.book_value(),
        "last_depreciation_month": r.last_depreciation_month,
    } for r in it]
    total_cost = sum(r.get("purchase_cost") or 0 for r in rows)
    total_book_value = sum(r.get("book_value") or 0 for r in rows)
    return jsonify({
        "assets": rows, "total_assets": len(rows),
        "total_purchase_cost": round(total_cost, 2), "total_book_value": round(total_book_value, 2),
        "total_accumulated_depreciation": round(total_cost - total_book_value, 2),
    }), 200


# ════════════════════════════════════════════════════════════
# PRODUCER & AGRICULTURE MODULE
# 10 features for smallholder/commercial producers, following the
# same owner-scoped db.Model + /api/... + _erp_user_or_401() pattern
# used by every other module in this file. No simulated data — the
# irrigation reminder calls the real OpenWeatherMap forecast already
# wired up for the Farming Advisory / Weather Insurance features above.
# ════════════════════════════════════════════════════════════

# ---- 1. Crop yield logging with season-over-season comparison ----
class CropYieldLog(db.Model):
    __tablename__ = "agri_yield_logs"
    id             = db.Column(db.Integer, primary_key=True)
    owner_user_id  = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    crop           = db.Column(db.String(120), nullable=False, index=True)
    field_name     = db.Column(db.String(120), nullable=True)
    season         = db.Column(db.String(40),  nullable=False)  # e.g. "2025/26", "Summer 2026"
    harvest_date   = db.Column(db.Date, nullable=True)
    area_value     = db.Column(db.Float, nullable=True)
    area_unit      = db.Column(db.String(20),  nullable=False, default="ha")  # ha, acre
    yield_amount   = db.Column(db.Float, nullable=False, default=0.0)
    yield_unit     = db.Column(db.String(20),  nullable=False, default="kg")  # kg, tonnes, bags
    notes          = db.Column(db.Text, nullable=True)
    created_at     = db.Column(db.DateTime, default=datetime.utcnow)

    def yield_per_area(self):
        if not self.area_value:
            return None
        return round(self.yield_amount / self.area_value, 2)

    def to_dict(self):
        return {
            "id": self.id, "crop": self.crop, "field_name": self.field_name, "season": self.season,
            "harvest_date": self.harvest_date.isoformat() if self.harvest_date else None,
            "area_value": self.area_value, "area_unit": self.area_unit,
            "yield_amount": self.yield_amount, "yield_unit": self.yield_unit,
            "yield_per_area": self.yield_per_area(), "notes": self.notes,
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }


