@app.route("/api/agri/yield-logs/comparison", methods=["GET"])
def agri_yield_logs_comparison():
    """Season-over-season comparison for one crop: total yield and
    yield-per-area per season, plus the % change vs the prior season."""
    user, err = _erp_user_or_401()
    if err: return err
    crop = (request.args.get("crop") or "").strip()
    if not crop:
        return jsonify({"error": "crop query parameter is required."}), 400
    rows = (CropYieldLog.query.filter_by(owner_user_id=user["id"], crop=crop)
            .order_by(CropYieldLog.season).all())
    by_season = {}
    for r in rows:
        s = by_season.setdefault(r.season, {"season": r.season, "total_yield": 0.0, "total_area": 0.0, "unit": r.yield_unit})
        s["total_yield"] += r.yield_amount
        if r.area_value:
            s["total_area"] += r.area_value
    seasons = list(by_season.values())
    for s in seasons:
        s["total_yield"] = round(s["total_yield"], 2)
        s["yield_per_area"] = round(s["total_yield"] / s["total_area"], 2) if s["total_area"] else None
    prev_yield = None
    for s in seasons:
        if prev_yield:
            s["pct_change_vs_prior_season"] = round((s["total_yield"] - prev_yield) / prev_yield * 100, 1) if prev_yield else None
        else:
            s["pct_change_vs_prior_season"] = None
        prev_yield = s["total_yield"]
    return jsonify({"crop": crop, "seasons": seasons}), 200


