@app.route("/api/agri/livestock/due-soon", methods=["GET"])
def agri_livestock_due_soon():
    """Vaccinations/treatments due in the next 14 days (or overdue)."""
    user, err = _erp_user_or_401()
    if err: return err
    cutoff = datetime.utcnow().date() + timedelta(days=14)
    rows = (LivestockHealthRecord.query.filter_by(owner_user_id=user["id"])
            .filter(LivestockHealthRecord.next_due_date.isnot(None))
            .filter(LivestockHealthRecord.next_due_date <= cutoff)
            .order_by(LivestockHealthRecord.next_due_date).all())
    out = []
    for r in rows:
        animal = LivestockAnimal.query.get(r.animal_id)
        d = r.to_dict()
        d["animal_tag_id"] = animal.tag_id if animal else None
        d["animal_species"] = animal.species if animal else None
        d["overdue"] = r.next_due_date < datetime.utcnow().date()
        out.append(d)
    return jsonify({"due": out}), 200


