@app.route("/api/agri/irrigation-fields/<int:field_id>/check", methods=["POST"])
@csrf.exempt
def agri_irrigation_fields_check(field_id):
    """Pulls the real 5-day rainfall forecast for the field's location
    and flags whether irrigation is needed against the saved threshold."""
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    row = IrrigationField.query.filter_by(id=field_id, owner_user_id=user["id"]).first()
    if not row: return jsonify({"error": "Field not found."}), 404
    forecast = _fetch_rain_forecast_mm(user["id"], row.location)
    if not forecast.get("ok"):
        return jsonify({"error": forecast.get("error", "Could not fetch rainfall forecast.")}), 502
    row.last_forecast_mm = forecast["total_mm_next_5_days"]
    row.needs_irrigation = row.last_forecast_mm < row.rain_threshold_mm
    row.last_checked_at = datetime.utcnow()
    db.session.commit()
    return jsonify({"ok": True, "field": row.to_dict(), "daily_mm": forecast.get("daily_mm")}), 200


# ---- 5. Grain/produce storage inventory with spoilage-risk alerts ----
class StorageInventoryItem(db.Model):
    __tablename__ = "agri_storage_inventory"
    id                     = db.Column(db.Integer, primary_key=True)
    owner_user_id          = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    commodity              = db.Column(db.String(120), nullable=False)
    storage_location       = db.Column(db.String(160), nullable=True)
    quantity               = db.Column(db.Float, nullable=False, default=0.0)
    unit                   = db.Column(db.String(20),  nullable=False, default="kg")
    stored_date            = db.Column(db.Date, nullable=False)
    expected_shelf_life_days = db.Column(db.Integer, nullable=True)
    notes                  = db.Column(db.Text, nullable=True)
    created_at             = db.Column(db.DateTime, default=datetime.utcnow)

    def spoilage_risk(self):
        if not self.expected_shelf_life_days:
            return "unknown"
        days_stored = (datetime.utcnow().date() - self.stored_date).days
        remaining = self.expected_shelf_life_days - days_stored
        if remaining <= 0:
            return "expired"
        if remaining <= self.expected_shelf_life_days * 0.15:
            return "high"
        if remaining <= self.expected_shelf_life_days * 0.35:
            return "medium"
        return "low"

    def to_dict(self):
        days_stored = (datetime.utcnow().date() - self.stored_date).days if self.stored_date else None
        return {
            "id": self.id, "commodity": self.commodity, "storage_location": self.storage_location,
            "quantity": self.quantity, "unit": self.unit,
            "stored_date": self.stored_date.isoformat() if self.stored_date else None,
            "expected_shelf_life_days": self.expected_shelf_life_days,
            "days_stored": days_stored, "spoilage_risk": self.spoilage_risk(),
            "notes": self.notes, "created_at": self.created_at.isoformat() if self.created_at else None,
        }


@app.route("/api/agri/storage-inventory", methods=["GET"])
def agri_storage_inventory_list():
    user, err = _erp_user_or_401()
    if err: return err
    rows = (StorageInventoryItem.query.filter_by(owner_user_id=user["id"])
            .order_by(StorageInventoryItem.stored_date).all())
    items = [r.to_dict() for r in rows]
    at_risk = [i for i in items if i["spoilage_risk"] in ("high", "expired")]
    return jsonify({"items": items, "at_risk_count": len(at_risk)}), 200


@app.route("/api/agri/storage-inventory", methods=["POST"])
@csrf.exempt
def agri_storage_inventory_add():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    commodity = (data.get("commodity") or "").strip()
    if not commodity:
        return jsonify({"error": "Commodity is required."}), 400
    try:
        quantity = float(data.get("quantity", 0) or 0)
    except (TypeError, ValueError):
        quantity = 0.0
    row = StorageInventoryItem(
        owner_user_id=user["id"], commodity=commodity,
        storage_location=(data.get("storage_location") or "").strip() or None,
        quantity=quantity, unit=(data.get("unit") or "kg").strip(),
        stored_date=_erp_parse_date(data.get("stored_date"), default=datetime.utcnow().date()),
        expected_shelf_life_days=data.get("expected_shelf_life_days") or None,
        notes=(data.get("notes") or "").strip() or None,
    )
    db.session.add(row)
    db.session.commit()
    return jsonify({"ok": True, "item": row.to_dict()}), 201


