# ---- 6. Cooperative harvest pooling and shared transport coordination ----
class HarvestPool(db.Model):
    __tablename__ = "agri_harvest_pools"
    id                  = db.Column(db.Integer, primary_key=True)
    owner_user_id       = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    crop                = db.Column(db.String(120), nullable=False)
    pooling_date        = db.Column(db.Date, nullable=False)
    location             = db.Column(db.String(160), nullable=True)
    transport_capacity   = db.Column(db.Float, nullable=True)  # e.g. truck capacity in the chosen unit
    capacity_unit         = db.Column(db.String(20), nullable=False, default="kg")
    status               = db.Column(db.String(20), nullable=False, default="open")  # open, full, closed
    notes                = db.Column(db.Text, nullable=True)
    created_at           = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self, contributions=None):
        contributions = contributions if contributions is not None else []
        total_pooled = round(sum(c.quantity for c in contributions), 2)
        return {
            "id": self.id, "crop": self.crop,
            "pooling_date": self.pooling_date.isoformat() if self.pooling_date else None,
            "location": self.location, "transport_capacity": self.transport_capacity,
            "capacity_unit": self.capacity_unit, "status": self.status, "notes": self.notes,
            "total_pooled": total_pooled, "contributor_count": len(contributions),
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }


class HarvestPoolContribution(db.Model):
    __tablename__ = "agri_harvest_pool_contributions"
    id             = db.Column(db.Integer, primary_key=True)
    pool_id        = db.Column(db.Integer, db.ForeignKey("agri_harvest_pools.id"), nullable=False, index=True)
    owner_user_id  = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    contributor_name = db.Column(db.String(120), nullable=False)
    quantity       = db.Column(db.Float, nullable=False, default=0.0)
    unit           = db.Column(db.String(20),  nullable=False, default="kg")
    created_at     = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        return {
            "id": self.id, "pool_id": self.pool_id, "contributor_name": self.contributor_name,
            "quantity": self.quantity, "unit": self.unit,
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }


@app.route("/api/agri/harvest-pools", methods=["GET"])
def agri_harvest_pools_list():
    user, err = _erp_user_or_401()
    if err: return err
    rows = HarvestPool.query.filter_by(owner_user_id=user["id"]).order_by(HarvestPool.pooling_date.desc()).all()
    out = []
    for p in rows:
        contribs = HarvestPoolContribution.query.filter_by(pool_id=p.id).all()
        out.append(p.to_dict(contribs))
    return jsonify({"pools": out}), 200


@app.route("/api/agri/harvest-pools", methods=["POST"])
@csrf.exempt
def agri_harvest_pools_add():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    crop = (data.get("crop") or "").strip()
    if not crop:
        return jsonify({"error": "Crop is required."}), 400
    try:
        capacity = float(data.get("transport_capacity")) if data.get("transport_capacity") not in (None, "") else None
    except (TypeError, ValueError):
        capacity = None
    row = HarvestPool(
        owner_user_id=user["id"], crop=crop,
        pooling_date=_erp_parse_date(data.get("pooling_date"), default=datetime.utcnow().date()),
        location=(data.get("location") or "").strip() or None,
        transport_capacity=capacity, capacity_unit=(data.get("capacity_unit") or "kg").strip(),
        notes=(data.get("notes") or "").strip() or None,
    )
    db.session.add(row)
    db.session.commit()
    return jsonify({"ok": True, "pool": row.to_dict()}), 201


@app.route("/api/agri/harvest-pools/<int:pool_id>/contribute", methods=["POST"])
@csrf.exempt
def agri_harvest_pools_contribute(pool_id):
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    pool = HarvestPool.query.filter_by(id=pool_id, owner_user_id=user["id"]).first()
    if not pool: return jsonify({"error": "Pool not found."}), 404
    data = request.get_json(silent=True) or {}
    contributor_name = (data.get("contributor_name") or "").strip()
    if not contributor_name:
        return jsonify({"error": "Contributor name is required."}), 400
    try:
        quantity = float(data.get("quantity", 0) or 0)
    except (TypeError, ValueError):
        quantity = 0.0
    contrib = HarvestPoolContribution(
        pool_id=pool_id, owner_user_id=user["id"], contributor_name=contributor_name,
        quantity=quantity, unit=(data.get("unit") or pool.capacity_unit).strip(),
    )
    db.session.add(contrib)
    db.session.commit()
    contribs = HarvestPoolContribution.query.filter_by(pool_id=pool_id).all()
    if pool.transport_capacity and sum(c.quantity for c in contribs) >= pool.transport_capacity:
        pool.status = "full"
        db.session.commit()
    return jsonify({"ok": True, "contribution": contrib.to_dict(), "pool": pool.to_dict(contribs)}), 201


@app.route("/api/agri/harvest-pools/<int:pool_id>", methods=["DELETE"])
@csrf.exempt
def agri_harvest_pools_delete(pool_id):
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    pool = HarvestPool.query.filter_by(id=pool_id, owner_user_id=user["id"]).first()
    if not pool: return jsonify({"error": "Pool not found."}), 404
    HarvestPoolContribution.query.filter_by(pool_id=pool.id).delete()
    db.session.delete(pool)
    db.session.commit()
    return jsonify({"ok": True}), 200


