# ---- 8. Farm equipment maintenance log (mirrors ManufacturingEquipment / EquipmentMaintenanceLog) ----
class FarmEquipment(db.Model):
    __tablename__ = "agri_equipment"
    id              = db.Column(db.Integer, primary_key=True)
    owner_user_id   = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    name            = db.Column(db.String(160), nullable=False)
    asset_tag       = db.Column(db.String(80),  nullable=True, index=True)
    category        = db.Column(db.String(60),  nullable=False, default="tractor")  # tractor, harvester, irrigation, tool, other
    location        = db.Column(db.String(160), nullable=True)
    status          = db.Column(db.String(20),  nullable=False, default="operational")  # operational, down, maintenance, retired
    purchase_date   = db.Column(db.Date, nullable=True)
    last_service_at = db.Column(db.Date, nullable=True)
    service_interval_days = db.Column(db.Integer, nullable=True)
    notes           = db.Column(db.Text, nullable=True)
    created_at      = db.Column(db.DateTime, default=datetime.utcnow)

    def service_due(self):
        if not self.service_interval_days or not self.last_service_at:
            return False
        return (datetime.utcnow().date() - self.last_service_at).days >= self.service_interval_days

    def to_dict(self):
        return {
            "id": self.id, "name": self.name, "asset_tag": self.asset_tag, "category": self.category,
            "location": self.location, "status": self.status,
            "purchase_date": self.purchase_date.isoformat() if self.purchase_date else None,
            "last_service_at": self.last_service_at.isoformat() if self.last_service_at else None,
            "service_interval_days": self.service_interval_days, "service_due": self.service_due(),
            "notes": self.notes, "created_at": self.created_at.isoformat() if self.created_at else None,
        }


class FarmEquipmentMaintenanceLog(db.Model):
    __tablename__ = "agri_equipment_maintenance_logs"
    id             = db.Column(db.Integer, primary_key=True)
    equipment_id   = db.Column(db.Integer, db.ForeignKey("agri_equipment.id"), nullable=False, index=True)
    owner_user_id  = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    performed_on   = db.Column(db.Date, nullable=False)
    performed_by   = db.Column(db.String(120), nullable=True)
    work_type      = db.Column(db.String(20), nullable=False, default="preventive")  # preventive, repair, inspection
    description    = db.Column(db.Text, nullable=True)
    cost           = db.Column(db.Float, nullable=True)
    created_at     = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        return {
            "id": self.id, "equipment_id": self.equipment_id,
            "performed_on": self.performed_on.isoformat() if self.performed_on else None,
            "performed_by": self.performed_by, "work_type": self.work_type,
            "description": self.description, "cost": self.cost,
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }


