# ---- 10. Certification expiry tracker (organic, fair-trade, etc.) ----
class FarmCertification(db.Model):
    __tablename__ = "agri_certifications"
    id                 = db.Column(db.Integer, primary_key=True)
    owner_user_id      = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    certification_name = db.Column(db.String(160), nullable=False)  # e.g. Organic, Fair-Trade, GlobalG.A.P.
    certifying_body     = db.Column(db.String(160), nullable=True)
    certificate_number  = db.Column(db.String(120), nullable=True)
    issued_date         = db.Column(db.Date, nullable=True)
    expiry_date          = db.Column(db.Date, nullable=False)
    notes                = db.Column(db.Text, nullable=True)
    created_at           = db.Column(db.DateTime, default=datetime.utcnow)

    def status(self):
        days_left = (self.expiry_date - datetime.utcnow().date()).days
        if days_left < 0:
            return "expired"
        if days_left <= 30:
            return "expiring_soon"
        return "valid"

    def to_dict(self):
        days_left = (self.expiry_date - datetime.utcnow().date()).days if self.expiry_date else None
        return {
            "id": self.id, "certification_name": self.certification_name,
            "certifying_body": self.certifying_body, "certificate_number": self.certificate_number,
            "issued_date": self.issued_date.isoformat() if self.issued_date else None,
            "expiry_date": self.expiry_date.isoformat() if self.expiry_date else None,
            "days_left": days_left, "status": self.status(), "notes": self.notes,
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }


@app.route("/api/agri/certifications", methods=["GET"])
def agri_certifications_list():
    user, err = _erp_user_or_401()
