    rows = (FarmCertification.query.filter_by(owner_user_id=user["id"])
            .order_by(FarmCertification.expiry_date).all())
    items = [r.to_dict() for r in rows]
    expiring = [i for i in items if i["status"] in ("expiring_soon", "expired")]
    return jsonify({"certifications": items, "expiring_count": len(expiring)}), 200


