# =====================================================================
# STAGE: Enterprise Roadmap Part 2.2 — Data Architecture & Resilience
# (BYOS: Bring Your Own Storage + encrypted-at-rest server sync).
#
# Problem this closes: To-Dos, Notes, Habits and Budget entries lived
# ONLY in browser localStorage (see TODO_KEY/NOTES_KEY/HABIT_KEY/
# BUDGET_KEY in index.html) — cleared cache or a new device meant that
# data was just gone. This adds a real server-side copy (encrypted at
# rest via the DB layer's existing disk encryption) for those four data
# types, plus an on-demand snapshot export pushed into the user's own
# Google Drive, OneDrive, or AWS S3 bucket — reusing the Drive/OneDrive
# upload helpers and the BYOK credential store that already power the
# rest of the Integrations tab, rather than building a new auth flow.
# =====================================================================

class LocalDataSync(db.Model):
    """One row per (user, data_key) — a JSON blob mirroring what used to
    live only in localStorage. Whitelisted keys only (see
    _LOCAL_SYNC_ALLOWED_KEYS) so this can't become a generic file store.
    This DB row is now the fallback copy only: when a user has connected
    their own cloud storage (Drive/OneDrive/S3/Azure — see
    cloud_sync_push/pull above), that connected storage is the primary
    copy and this row is kept as a fast local cache + safety net for
    the (common) case where no provider is connected yet."""
    __tablename__ = "local_data_sync"
    id            = db.Column(db.Integer, primary_key=True)
    owner_user_id = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    data_key      = db.Column(db.String(40), nullable=False)
    # NOTE: this column was originally db.Text, which on this app's
    # MySQL backend maps to a 64KB-capped TEXT column. Widened to
    # LONGTEXT (4GB) below to actually remove the size ceiling, per
    # AM's request — plain db.Text stayed silently capped at 64KB even
    # while the old app-level check allowed up to 300KB/2MB, so this
    # also fixes a latent bug, not just a preference. Existing MySQL
    # deployments no longer need a hand-run ALTER for this: startup's
    # _auto_migrate_widen_columns() detects the model/DB type mismatch
    # and runs "ALTER TABLE local_data_sync MODIFY COLUMN data_json
    # LONGTEXT NOT NULL" automatically, the same way _auto_migrate_columns()
    # already auto-adds missing columns.
    data_json     = db.Column(db.Text().with_variant(mysql.LONGTEXT, "mysql"), nullable=False, default="[]")
    updated_at    = db.Column(db.DateTime, default=datetime.utcnow, onupdate=datetime.utcnow)
    __table_args__ = (db.UniqueConstraint("owner_user_id", "data_key", name="uq_local_data_sync"),)


# Keep this list tight — it's the difference between "syncs a handful
# of known data types" and "arbitrary user-controlled storage".
# mega_hidden_programs added after the Hide/Unhide Programs feature
# (index.html) hit QuotaExceededError writing to localStorage on a
# real device — it's moved OFF localStorage entirely (not just mirrored
# like todos/notes/habits/budget below) since a per-browser list was
# never meant to grow large or need an offline-first fast path; the
# server copy is now the only copy, same as any other account setting.
_LOCAL_SYNC_ALLOWED_KEYS = {
    "todos", "notes", "habits", "budget", "mega_hidden_programs",
    # Added in the "shift away from localStorage forever" pass: chat
    # history, journal sparks, marketplace cart, and the hope counter
    # were still browser-only and vanished on cache clear / new device.
    # Profile photo and gallery images are deliberately NOT here — those
    # are binary and belong in the BYOS Drive/OneDrive/S3/Azure uploader
    # (cloud_sync_push/pull above), not this JSON-blob table.
    "chat_history", "journal_sparks", "cart", "hope_count",
    # Added when the nine fake "/api/<feature>/sync" endpoints (see the
    # removed-code note near their old location, above the ERP section)
    # were replaced with real persistence: WhatsApp Order Management,
    # Recurring Invoice System, Study Group Coordinator, Accountability
    # Partner goals, AI Memory Journal, Water & Sleep Tracker, Mental
    # Health Check-In, Expense Analytics/Receipt Scanner, Ghostwriter/
    # Brand Builder content, and the AI Daily Planner schedule.
    "waorders", "rinvoices", "studygroups", "goals", "memories",
    "health_log", "health_quality", "mh_checkins", "expenses_log",
    "content", "planner_schedule", "focus_minutes",
    "pw_vault_blob", "pw_vault_salt",
    "availability", "competitors", "feedbacks", "future_letters",
    "proposals", "sheets_crm_id", "diaspora_profile",
    "loadshedding_schedule", "splitter_people", "vwa_contacts",
    "paynow_wallet",
    # File-order sweep, batch 2: gallery/code/CRM/catalog/WhatsApp/
    # payments/jobs/e-signatures/scheduling/SMS/marketing/medications/
    # polls/skill-swap/integration-config/Kanban/time-tracker — every
    # remaining feature that held real data only in the browser.
    "gallery", "code_projects", "gallery_reactions", "profile_photo",
    "pomo_sessions", "crm", "birthdays", "challenges", "badges",
    "catalog", "wa_config", "wa_contacts", "wa_messages", "pay_history",
    "pay_gateway", "jobs", "esignatures", "schedule", "sms_contacts",
    "news_alerts", "biz_briefing", "emkt_subscribers", "emkt_campaigns",
    "medications", "polls", "skillswap", "sms_log",
    "kanban", "timetracker", "sheets_log",
    "sms_campaigns", "gcal_events",
    "at_status", "sg_status", "sheets_status",
}
# No application-level size cap on these anymore, per AM's request —
# each key is either mirrored into the user's own connected cloud
# storage (no cap there either) or, for users with nothing connected
# yet, into the LONGTEXT column above (4GB ceiling, not a realistic
# constraint for personal/business-scale JSON lists).


# Per-day keys (the Daily Planner schedule and the Water Tracker total create
# a new key each day). Only these two exact shapes are accepted, so this is
# not an open-ended key store and the value is safe inside a cloud filename.
_LOCAL_SYNC_DAILY_RE = re.compile(r"^(planner|water)_\d{4}-\d{2}-\d{2}$")

def _local_sync_key_ok(data_key):
    return data_key in _LOCAL_SYNC_ALLOWED_KEYS or bool(_LOCAL_SYNC_DAILY_RE.match(data_key or ""))


@app.route("/api/local-sync/<string:data_key>", methods=["GET"])
def local_sync_get(data_key):
    user, err = _erp_user_or_401()
    if err: return err
    if not _local_sync_key_ok(data_key):
        return jsonify({"error": "Unknown sync key."}), 400
    # Prefer the user's own connected cloud storage when they have one —
    # that's the actual source of truth once connected, not just a
    # backup destination. Falls back to the DB row (covers everyone who
    # hasn't connected a provider, and doubles as a fast cache so every
    # read doesn't have to round-trip to Drive/S3/etc).
    found_cloud, cloud_bytes = cloud_sync_pull(user["id"], f"connectit_sync_{data_key}.json")
    if found_cloud:
        try:
            value = cloud_bytes.decode("utf-8")
            return jsonify({"key": data_key, "value": value, "source": "cloud"}), 200
        except Exception:
            pass  # fall through to the DB copy if the cloud blob was unreadable
    row = LocalDataSync.query.filter_by(owner_user_id=user["id"], data_key=data_key).first()
    return jsonify({
        "key": data_key,
        "value": row.data_json if row else None,
        "updated_at": row.updated_at.isoformat() if row else None,
        "source": "database",
    }), 200


@app.route("/api/local-sync/<string:data_key>", methods=["POST"])
@csrf.exempt
def local_sync_set(data_key):
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    if not _local_sync_key_ok(data_key):
        return jsonify({"error": "Unknown sync key."}), 400
    data = request.get_json(silent=True) or {}
    value = data.get("value", "[]")
    if not isinstance(value, str):
        value = json.dumps(value)
    # Always write the DB copy first — cheap, and guarantees nothing is
    # lost even if the user has no cloud provider connected or a cloud
    # write happens to fail.
    row = LocalDataSync.query.filter_by(owner_user_id=user["id"], data_key=data_key).first()
    if row:
        row.data_json = value
    else:
        row = LocalDataSync(owner_user_id=user["id"], data_key=data_key, data_json=value)
        db.session.add(row)
    db.session.commit()
    # Then mirror to the user's own connected cloud storage, if any.
    # Best-effort: a cloud hiccup shouldn't turn into a lost save when
    # the DB write above already succeeded.
    cloud_provider, cloud_err = cloud_sync_push(user["id"], f"connectit_sync_{data_key}.json", value.encode("utf-8"))
    return jsonify({
        "ok": True, "key": data_key, "updated_at": row.updated_at.isoformat(),
        "cloud_synced_to": cloud_provider, "cloud_error": cloud_err,
    }), 200


def _byos_upload_s3(user_id, filename: str, file_bytes: bytes, mime_type: str) -> dict:
    """AWS S3 upload using the user's own BYOK credentials (access_key_id,
    secret_access_key, bucket_name, region — pasted once under
    Integrations, same pattern as every other provider in this file)."""
    try:
        import boto3
    except ImportError:
        return {"ok": False, "error": "boto3 is not installed. Run: pip install boto3"}

    creds = get_user_credentials(user_id, "aws_s3") or {}
    access_key = creds.get("access_key_id")
    secret_key = creds.get("secret_access_key")
    bucket     = creds.get("bucket_name")
    region     = creds.get("region") or "us-east-1"
    if not (access_key and secret_key and bucket):
        return {"ok": False, "error": "AWS S3 is not configured. Add access_key_id, secret_access_key and bucket_name under Integrations."}

    try:
        s3 = boto3.client("s3", aws_access_key_id=access_key, aws_secret_access_key=secret_key, region_name=region)
        key = f"connectit-ai-backups/{user_id}/{filename}"
        s3.put_object(Bucket=bucket, Key=key, Body=file_bytes, ContentType=mime_type)
        url = f"https://{bucket}.s3.{region}.amazonaws.com/{key}"
        return {"ok": True, "provider": "aws_s3", "location": url}
    except Exception as e:
        logging.error(f"[S3 UPLOAD ERROR] user={user_id}: {e}")
        return {"ok": False, "error": str(e)}


def _byos_download_s3(user_id, filename: str):
    """Counterpart to _byos_upload_s3 — reads the same fixed key back.
    Returns (True, bytes) or (False, error_string)."""
    try:
        import boto3
        from botocore.exceptions import ClientError
    except ImportError:
        return False, "boto3 is not installed. Run: pip install boto3"

    creds = get_user_credentials(user_id, "aws_s3") or {}
    access_key = creds.get("access_key_id")
    secret_key = creds.get("secret_access_key")
    bucket     = creds.get("bucket_name")
    region     = creds.get("region") or "us-east-1"
    if not (access_key and secret_key and bucket):
        return False, "AWS S3 is not configured. Add access_key_id, secret_access_key and bucket_name under Integrations."

    try:
        s3 = boto3.client("s3", aws_access_key_id=access_key, aws_secret_access_key=secret_key, region_name=region)
        key = f"connectit-ai-backups/{user_id}/{filename}"
        obj = s3.get_object(Bucket=bucket, Key=key)
        return True, obj["Body"].read()
    except ClientError as e:
        if e.response.get("Error", {}).get("Code") in ("NoSuchKey", "404"):
            return False, "No data found yet."
        logging.error(f"[S3 DOWNLOAD ERROR] user={user_id}: {e}")
        return False, str(e)
    except Exception as e:
        logging.error(f"[S3 DOWNLOAD ERROR] user={user_id}: {e}")
        return False, str(e)


def _byos_upload_azure(user_id, filename: str, file_bytes: bytes, mime_type: str) -> dict:
    """Azure Blob Storage upload using the user's own BYOK credentials —
    account_name + account_key (or a sas_token in place of account_key)
    + container_name, pasted once under Integrations. Fourth BYOS option
    alongside Drive/OneDrive/S3, since not every business already has
    one of those three — several run on Azure instead."""
    try:
        from azure.storage.blob import BlobServiceClient
    except ImportError:
        return {"ok": False, "error": "azure-storage-blob is not installed. Run: pip install azure-storage-blob"}

    creds = get_user_credentials(user_id, "azure_blob") or {}
    account_name = creds.get("account_name")
    account_key  = creds.get("account_key")
    sas_token    = creds.get("sas_token")
    container    = creds.get("container_name")
    if not (account_name and container and (account_key or sas_token)):
        return {"ok": False, "error": "Azure Blob Storage is not configured. Add account_name, container_name, and either account_key or sas_token under Integrations."}

    try:
        if account_key:
            client = BlobServiceClient(
                account_url=f"https://{account_name}.blob.core.windows.net",
                credential=account_key,
            )
        else:
            client = BlobServiceClient(
                account_url=f"https://{account_name}.blob.core.windows.net?{sas_token.lstrip('?')}",
            )
        blob_path = f"connectit-ai-backups/{user_id}/{filename}"
        blob_client = client.get_blob_client(container=container, blob=blob_path)
        from azure.storage.blob import ContentSettings
        blob_client.upload_blob(file_bytes, overwrite=True, content_settings=ContentSettings(content_type=mime_type))
        url = f"https://{account_name}.blob.core.windows.net/{container}/{blob_path}"
        return {"ok": True, "provider": "azure_blob", "location": url}
    except Exception as e:
        logging.error(f"[AZURE UPLOAD ERROR] user={user_id}: {e}")
        return {"ok": False, "error": str(e)}


def _byos_download_azure(user_id, filename: str):
    """Counterpart to _byos_upload_azure. Returns (True, bytes) or
    (False, error_string)."""
    try:
        from azure.storage.blob import BlobServiceClient
        from azure.core.exceptions import ResourceNotFoundError
    except ImportError:
        return False, "azure-storage-blob is not installed. Run: pip install azure-storage-blob"

    creds = get_user_credentials(user_id, "azure_blob") or {}
    account_name = creds.get("account_name")
    account_key  = creds.get("account_key")
    sas_token    = creds.get("sas_token")
    container    = creds.get("container_name")
    if not (account_name and container and (account_key or sas_token)):
        return False, "Azure Blob Storage is not configured. Add account_name, container_name, and either account_key or sas_token under Integrations."

    try:
        if account_key:
            client = BlobServiceClient(
                account_url=f"https://{account_name}.blob.core.windows.net",
                credential=account_key,
            )
        else:
            client = BlobServiceClient(
                account_url=f"https://{account_name}.blob.core.windows.net?{sas_token.lstrip('?')}",
            )
        blob_path = f"connectit-ai-backups/{user_id}/{filename}"
        blob_client = client.get_blob_client(container=container, blob=blob_path)
        return True, blob_client.download_blob().readall()
    except ResourceNotFoundError:
        return False, "No data found yet."
    except Exception as e:
        logging.error(f"[AZURE DOWNLOAD ERROR] user={user_id}: {e}")
        return False, str(e)


def _byos_upload_ipfs(user_id, filename: str, file_bytes: bytes, mime_type: str) -> dict:
    """Decentralised Storage (IPFS) upload via the user's own Pinata
    pinning-service account (BYOK: pinata_jwt, pasted once under
    Integrations). Real Pinata REST API call — no local IPFS node is
    required, since running one isn't something a hosted web app can
    do on the user's behalf, but pinning is the honest, standard way
    real applications put data on IPFS. The resulting CID is content-
    addressed: it is not tied to Connect It or to Pinata specifically
    and can be fetched from any public IPFS gateway, which is the
    actual "outside Big Tech's reach" property this feature exists for.
    We record filename -> CID in this user's own UserPreference row
    (key f"ipfs_cid::{filename}") purely so _byos_download_ipfs can
    find the right object again later; the object itself lives on IPFS,
    not in our database."""
    creds = get_user_credentials(user_id, "ipfs") or {}
    jwt_token = creds.get("pinata_jwt")
    if not jwt_token:
        return {"ok": False, "error": "IPFS (Pinata) is not configured. Add your pinata_jwt under Integrations."}
    gateway = (creds.get("gateway_url") or "https://gateway.pinata.cloud/ipfs").rstrip("/")

    try:
        resp = requests.post(
            "https://api.pinata.cloud/pinning/pinFileToIPFS",
            headers={"Authorization": f"Bearer {jwt_token}"},
            files={"file": (filename, file_bytes, mime_type)},
            data={"pinataMetadata": json.dumps({"name": f"connectit-ai/{user_id}/{filename}"})},
            timeout=60,
        )
    except requests.RequestException as e:
        logging.error(f"[IPFS UPLOAD ERROR] user={user_id}: {e}")
        return {"ok": False, "error": f"Could not reach Pinata: {e}"}

    if resp.status_code != 200:
        return {"ok": False, "error": f"Pinata returned {resp.status_code}: {resp.text[:300]}"}

    cid = (resp.json() or {}).get("IpfsHash")
    if not cid:
        return {"ok": False, "error": "Pinata response did not include an IPFS hash."}

    pref_key = f"ipfs_cid::{filename}"
    pref_row = UserPreference.query.filter_by(owner_user_id=user_id, pref_key=pref_key).first()
    if pref_row:
        pref_row.pref_value = cid
    else:
        db.session.add(UserPreference(owner_user_id=user_id, pref_key=pref_key, pref_value=cid))
    db.session.commit()

    return {"ok": True, "provider": "ipfs", "location": f"{gateway}/{cid}", "cid": cid}


def _byos_download_ipfs(user_id, filename: str):
    """Counterpart to _byos_upload_ipfs. Looks up the CID this user last
    pinned for `filename`, then fetches the bytes back from a public
    IPFS gateway (the user's configured gateway if set, else Pinata's,
    with ipfs.io as a last-resort fallback so a pin still works even if
    the user's own gateway is temporarily unreachable). Returns
    (True, bytes) or (False, error_string)."""
    pref_key = f"ipfs_cid::{filename}"
    pref_row = UserPreference.query.filter_by(owner_user_id=user_id, pref_key=pref_key).first()
    if not pref_row or not pref_row.pref_value:
        return False, "No data found yet."
    cid = pref_row.pref_value

    creds = get_user_credentials(user_id, "ipfs") or {}
    gateway = (creds.get("gateway_url") or "https://gateway.pinata.cloud/ipfs").rstrip("/")
    gateways_to_try = [gateway]
    if gateway != "https://ipfs.io/ipfs":
        gateways_to_try.append("https://ipfs.io/ipfs")

    last_error = "No data found yet."
    for gw in gateways_to_try:
        try:
            resp = requests.get(f"{gw}/{cid}", timeout=30)
        except requests.RequestException as e:
            last_error = str(e)
            continue
        if resp.status_code == 200:
            return True, resp.content
        last_error = f"{gw} returned {resp.status_code}"
    logging.error(f"[IPFS DOWNLOAD ERROR] user={user_id}: {last_error}")
    return False, last_error


def _cloud_sync_providers(user_id):
    """Returns an ordered {name: (put_fn, get_fn, configured_bool)} map
    for every BYOS provider this user could plausibly have connected —
    preferred provider (per the 'byos_provider' UserPreference) first,
    otherwise Drive, OneDrive, S3, Azure in that order. Reused by both
    the per-key local-sync routes and the full-snapshot backup export
    so there's exactly one place that knows the provider order."""
    pref_row = UserPreference.query.filter_by(owner_user_id=user_id, pref_key="byos_provider").first()
    preferred = pref_row.pref_value if pref_row else None

    def drive_put(filename, raw): return _drive_appdata_upsert(user_id, filename, raw)
    def drive_get(filename): return _drive_appdata_download(user_id, filename)
    def drive_configured(): return GCALENDAR_AVAILABLE and bool(get_valid_google_token(user_id, required_scope="drive.appdata"))

    def onedrive_put(filename, raw): return _onedrive_approot_put_bytes(user_id, filename, raw)
    def onedrive_get(filename): return _onedrive_approot_get_bytes(user_id, filename)
    def onedrive_configured(): return bool(get_valid_microsoft_token(user_id))

    def s3_put(filename, raw):
        res = _byos_upload_s3(user_id, filename, raw, "application/json")
        return (True, res) if res.get("ok") else (False, res.get("error"))
    def s3_get(filename): return _byos_download_s3(user_id, filename)
    def s3_configured(): return bool(get_user_credentials(user_id, "aws_s3"))

    def azure_put(filename, raw):
        res = _byos_upload_azure(user_id, filename, raw, "application/json")
        return (True, res) if res.get("ok") else (False, res.get("error"))
    def azure_get(filename): return _byos_download_azure(user_id, filename)
    def azure_configured(): return bool(get_user_credentials(user_id, "azure_blob"))

    def ipfs_put(filename, raw):
        res = _byos_upload_ipfs(user_id, filename, raw, "application/json")
        return (True, res) if res.get("ok") else (False, res.get("error"))
    def ipfs_get(filename): return _byos_download_ipfs(user_id, filename)
    def ipfs_configured(): return bool(get_user_credentials(user_id, "ipfs"))

    providers = {
        "google_drive": (drive_put, drive_get, drive_configured),
        "onedrive":     (onedrive_put, onedrive_get, onedrive_configured),
        "aws_s3":       (s3_put, s3_get, s3_configured),
        "azure_blob":   (azure_put, azure_get, azure_configured),
        "ipfs":         (ipfs_put, ipfs_get, ipfs_configured),
    }
    order = ([preferred] if preferred in providers else []) + [p for p in providers if p != preferred]
    return [(name,) + providers[name] for name in order]


def cloud_sync_push(user_id, filename, raw_bytes):
    """Pushes to whichever cloud storage the user has connected (first
    configured provider in preference order). Returns (provider_name,
    None) on success, (None, None) if nothing is connected (not an
    error — the DB copy is still the safety net for that case), or
    (None, error_string) if a connected provider was tried and failed."""
    for name, put_fn, _get_fn, configured in _cloud_sync_providers(user_id):
        if not configured():
            continue
        ok, err = put_fn(filename, raw_bytes)
        if ok:
            return name, None
        return None, f"{name}: {err}"
    return None, None


def cloud_sync_pull(user_id, filename):
    """Pulls from whichever cloud storage the user has connected, trying
    providers in preference order until one has the file. Returns
    (True, bytes) or (False, None) if nothing connected/nothing found."""
    for _name, _put_fn, get_fn, configured in _cloud_sync_providers(user_id):
        if not configured():
            continue
        ok, result = get_fn(filename)
        if ok:
            return True, result
    return False, None


def backup_snapshot_to_user_storage(user_id, filename: str, file_bytes: bytes, mime_type: str = "application/json") -> dict:
    """BYOS dispatcher: pushes a file to whichever cloud storage the user
    has connected, preferring an explicit choice saved under the
    'byos_provider' preference, otherwise trying Drive, then OneDrive,
    then S3 — whichever is actually configured. Returns {"ok": False,
    "error": "..."} with a clear reason if none are connected, rather
    than silently doing nothing."""
    pref_row = UserPreference.query.filter_by(owner_user_id=user_id, pref_key="byos_provider").first()
    preferred = pref_row.pref_value if pref_row else None

    def try_drive():
        if not (GCALENDAR_AVAILABLE and get_user_credentials(user_id, "google_drive")):
            return None
        user_row = UserAccount.query.get(user_id)
        res = upload_file_to_drive(user_id, filename, file_bytes, mime_type,
                                    share_with_email=user_row.email if user_row else None)
        return {"ok": res.get("ok", False), "provider": "google_drive",
                "location": res.get("web_view_link"), "error": res.get("error")}

    def try_onedrive():
        headers = _microsoft_headers(user_id, json_body=False)
        if not headers:
            return None
        ok, result = _onedrive_put_bytes(user_id, filename, file_bytes)
        if ok:
            return {"ok": True, "provider": "onedrive", "location": result.get("web_url")}
        return {"ok": False, "provider": "onedrive", "error": result}

    def try_s3():
        if not get_user_credentials(user_id, "aws_s3"):
            return None
        return _byos_upload_s3(user_id, filename, file_bytes, mime_type)

    def try_azure():
        if not get_user_credentials(user_id, "azure_blob"):
            return None
        return _byos_upload_azure(user_id, filename, file_bytes, mime_type)

    def try_ipfs():
        if not get_user_credentials(user_id, "ipfs"):
            return None
        return _byos_upload_ipfs(user_id, filename, file_bytes, mime_type)

    providers = {"google_drive": try_drive, "onedrive": try_onedrive, "aws_s3": try_s3, "azure_blob": try_azure, "ipfs": try_ipfs}
    order = ([preferred] if preferred in providers else []) + [p for p in providers if p != preferred]

    attempted = []
    for name in order:
        result = providers[name]()
        if result is None:
            continue  # not configured — skip silently, try the next one
        attempted.append(name)
        if result.get("ok"):
            return result
    if not attempted:
        return {"ok": False, "error": "No storage provider connected. Add Google Drive, Microsoft 365 (OneDrive), AWS S3, Azure Blob Storage, or IPFS (Pinata) under Integrations."}
    return {"ok": False, "error": f"Tried {', '.join(attempted)} but none succeeded. Check Integrations."}


@app.route("/api/backup/export", methods=["POST"])
@csrf.exempt
def backup_export():
    """On-demand BYOS snapshot: bundles the user's synced local data
    (todos/notes/habits/budget) into one JSON file and pushes it to
    whichever cloud storage they've connected."""
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err

    rows = LocalDataSync.query.filter_by(owner_user_id=user["id"]).all()
    snapshot = {
        "exported_at": datetime.utcnow().isoformat(),
        "user_id": user["id"],
        "data": {r.data_key: json.loads(r.data_json) if r.data_json else [] for r in rows},
    }
    file_bytes = json.dumps(snapshot, indent=2).encode("utf-8")
    filename = f"connectit-ai-backup-{user['id']}-{datetime.utcnow().strftime('%Y%m%d-%H%M%S')}.json"

    result = backup_snapshot_to_user_storage(user["id"], filename, file_bytes, "application/json")
    if result.get("ok"):
        pref = UserPreference.query.filter_by(owner_user_id=user["id"], pref_key="byos_last_backup").first()
        now_iso = datetime.utcnow().isoformat()
        if pref:
            pref.pref_value = now_iso
        else:
            db.session.add(UserPreference(owner_user_id=user["id"], pref_key="byos_last_backup", pref_value=now_iso))
        db.session.commit()
        notify_user(user["id"], "backup", "Backup complete",
                    f"Your data was backed up to {result.get('provider')}.", result.get("location"))
    return jsonify(result), (200 if result.get("ok") else 400)


@app.route("/api/backup/run-all", methods=["POST"])
@csrf.exempt
def backup_run_all():
    """Batch endpoint for a scheduled task (e.g. PythonAnywhere's daily
    Scheduled Tasks) to hit once a day, backing up every user who has a
    storage provider connected. Auth is a shared secret header, not a
    user session — set EXTERNAL_BACKUP_KEY and point the scheduled task
    at this URL with header X-Backup-Key: <that value>."""
    if not EXTERNAL_BACKUP_KEY or request.headers.get("X-Backup-Key") != EXTERNAL_BACKUP_KEY:
        return jsonify({"error": "Unauthorized."}), 401

    results = {"backed_up": 0, "skipped": 0, "failed": 0}
    user_ids = [r.owner_user_id for r in db.session.query(LocalDataSync.owner_user_id).distinct().all()]
    for uid in user_ids:
        rows = LocalDataSync.query.filter_by(owner_user_id=uid).all()
        snapshot = {
            "exported_at": datetime.utcnow().isoformat(), "user_id": uid,
            "data": {r.data_key: json.loads(r.data_json) if r.data_json else [] for r in rows},
        }
        file_bytes = json.dumps(snapshot, indent=2).encode("utf-8")
        filename = f"connectit-ai-backup-{uid}-{datetime.utcnow().strftime('%Y%m%d-%H%M%S')}.json"
        res = backup_snapshot_to_user_storage(uid, filename, file_bytes, "application/json")
        if res.get("ok"):
            results["backed_up"] += 1
            pref = UserPreference.query.filter_by(owner_user_id=uid, pref_key="byos_last_backup").first()
            now_iso = datetime.utcnow().isoformat()
            if pref: pref.pref_value = now_iso
            else: db.session.add(UserPreference(owner_user_id=uid, pref_key="byos_last_backup", pref_value=now_iso))
            db.session.commit()
        elif "No storage provider connected" in res.get("error", ""):
            results["skipped"] += 1
        else:
            results["failed"] += 1
            logging.warning(f"[BYOS BATCH] backup failed for user={uid}: {res.get('error')}")
    return jsonify(results), 200


# =====================================================================
# STAGE: Enterprise Roadmap Part 2.5 — Verification & Human-in-the-Loop
# Network. Lets a user route an AI-generated contract, financial model,
# or compliance filing to a certified human professional (lawyer, CPA,
# engineer) for review and a formal digital sign-off — closing the
# "nothing generated constitutes professional advice" gap the doc
# flagged as a blocker for high-stakes enterprise use.
# =====================================================================

class ProfessionalReviewer(db.Model):
    """A platform user who has applied to review documents. `verified`
    is admin-set only (is_admin gate below) — nothing here claims a
    credential is real until a human at Connect It has checked it."""
    __tablename__ = "professional_reviewers"
    id              = db.Column(db.Integer, primary_key=True)
    owner_user_id   = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, unique=True, index=True)
    credential_type = db.Column(db.String(30), nullable=False)   # 'lawyer' | 'cpa' | 'engineer' | 'other'
    license_info    = db.Column(db.String(300), nullable=True)   # bar number, jurisdiction, etc. — self-reported
    bio             = db.Column(db.Text, nullable=True)
    verified        = db.Column(db.Boolean, nullable=False, default=False)
    active          = db.Column(db.Boolean, nullable=False, default=True)
    created_at      = db.Column(db.DateTime, default=datetime.utcnow)


class ReviewRequest(db.Model):
    """One document submitted for human review. Status flow:
    pending -> claimed -> completed (or rejected by the reviewer)."""
    __tablename__ = "review_requests"
    id                 = db.Column(db.Integer, primary_key=True)
    requester_user_id  = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    reviewer_user_id   = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=True, index=True)
    credential_type    = db.Column(db.String(30), nullable=False)  # which kind of professional this needs
    document_title     = db.Column(db.String(200), nullable=False)
    document_type      = db.Column(db.String(40), nullable=True)   # 'contract' | 'financial' | 'compliance' | 'other'
    content_text        = db.Column(db.Text().with_variant(mysql.LONGTEXT, "mysql"), nullable=False)
    status              = db.Column(db.String(20), nullable=False, default="pending")  # pending/claimed/completed/rejected
    review_notes        = db.Column(db.Text, nullable=True)
    signed_off           = db.Column(db.Boolean, nullable=False, default=False)
    submitted_at         = db.Column(db.DateTime, default=datetime.utcnow)
    claimed_at            = db.Column(db.DateTime, nullable=True)
    completed_at           = db.Column(db.DateTime, nullable=True)


@app.route("/api/hitl/reviewers/apply", methods=["POST"])
@csrf.exempt
def hitl_reviewer_apply():
    user, err = _erp_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    credential_type = (data.get("credential_type") or "").strip().lower()
    if credential_type not in ("lawyer", "cpa", "engineer", "other"):
        return jsonify({"error": "credential_type must be lawyer, cpa, engineer, or other."}), 400
    existing = ProfessionalReviewer.query.filter_by(owner_user_id=user["id"]).first()
    if existing:
        existing.credential_type = credential_type
        existing.license_info = (data.get("license_info") or "")[:300]
        existing.bio = data.get("bio") or ""
        existing.verified = False  # re-verify on any change to claimed credentials
        existing.active = True
    else:
        db.session.add(ProfessionalReviewer(
            owner_user_id=user["id"], credential_type=credential_type,
            license_info=(data.get("license_info") or "")[:300], bio=data.get("bio") or "",
        ))
    db.session.commit()
    return jsonify({"ok": True, "status": "pending_verification"}), 200


@app.route("/api/hitl/reviewers", methods=["GET"])
def hitl_reviewers_list():
    """Public-ish list of verified, active reviewers (name withheld — an
    enterprise admin verifying credentials is a manual, out-of-band step;
    this just shows what's available so a requester can pick a credential type)."""
    q = ProfessionalReviewer.query.filter_by(verified=True, active=True)
    ct = (request.args.get("credential_type") or "").strip().lower()
    if ct:
        q = q.filter_by(credential_type=ct)
    reviewers = q.all()
    return jsonify({"reviewers": [
        {"credential_type": r.credential_type, "bio": r.bio} for r in reviewers
    ]}), 200


@app.route("/api/admin/hitl/reviewers/pending", methods=["GET"])
def hitl_admin_pending_reviewers():
    user, err = _erp_user_or_401()
    if err: return err
    if not user.get("is_admin"):
        return jsonify({"error": "Admin only."}), 403
    pending = ProfessionalReviewer.query.filter_by(verified=False, active=True).all()
    out = []
    for r in pending:
        u = UserAccount.query.get(r.owner_user_id)
        out.append({"id": r.id, "name": u.name if u else None, "email": u.email if u else None,
                    "credential_type": r.credential_type, "license_info": r.license_info, "bio": r.bio})
    return jsonify({"pending": out}), 200


@app.route("/api/admin/hitl/reviewers/<int:reviewer_id>/verify", methods=["POST"])
@csrf.exempt
def hitl_admin_verify_reviewer(reviewer_id):
    user, err = _erp_user_or_401()
    if err: return err
    if not user.get("is_admin"):
        return jsonify({"error": "Admin only."}), 403
    r = ProfessionalReviewer.query.get(reviewer_id)
    if not r:
        return jsonify({"error": "Not found."}), 404
    r.verified = True
    db.session.commit()
    notify_user(r.owner_user_id, "hitl", "You're a verified reviewer",
                f"Your {r.credential_type} credential was verified. You can now claim review requests.")
    return jsonify({"ok": True}), 200


@app.route("/api/hitl/requests", methods=["POST"])
@csrf.exempt
def hitl_request_create():
    user, err = _erp_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    title = (data.get("document_title") or "").strip()
    content = (data.get("content_text") or "").strip()
    credential_type = (data.get("credential_type") or "").strip().lower()
    if not title or not content:
        return jsonify({"error": "'document_title' and 'content_text' are required."}), 400
    if credential_type not in ("lawyer", "cpa", "engineer", "other"):
        return jsonify({"error": "credential_type must be lawyer, cpa, engineer, or other."}), 400
    req_row = ReviewRequest(
        requester_user_id=user["id"], credential_type=credential_type,
        document_title=title[:200], document_type=(data.get("document_type") or "other")[:40],
        content_text=content,
    )
    db.session.add(req_row)
    db.session.commit()
    return jsonify({"ok": True, "id": req_row.id, "status": req_row.status}), 200


@app.route("/api/hitl/requests/mine", methods=["GET"])
def hitl_requests_mine():
    user, err = _erp_user_or_401()
    if err: return err
    rows = ReviewRequest.query.filter_by(requester_user_id=user["id"]).order_by(ReviewRequest.submitted_at.desc()).all()
    return jsonify({"requests": [{
        "id": r.id, "document_title": r.document_title, "document_type": r.document_type,
        "credential_type": r.credential_type, "status": r.status, "signed_off": r.signed_off,
        "review_notes": r.review_notes, "submitted_at": r.submitted_at.isoformat() if r.submitted_at else None,
        "completed_at": r.completed_at.isoformat() if r.completed_at else None,
    } for r in rows]}), 200


@app.route("/api/hitl/requests/available", methods=["GET"])
def hitl_requests_available():
    """Open requests a verified reviewer can claim, filtered to their
    own credential type."""
    user, err = _erp_user_or_401()
    if err: return err
    reviewer = ProfessionalReviewer.query.filter_by(owner_user_id=user["id"], verified=True, active=True).first()
    if not reviewer:
        return jsonify({"error": "You are not a verified reviewer."}), 403
    rows = ReviewRequest.query.filter_by(status="pending", credential_type=reviewer.credential_type) \
        .order_by(ReviewRequest.submitted_at.asc()).all()
    return jsonify({"requests": [{
        "id": r.id, "document_title": r.document_title, "document_type": r.document_type,
        "submitted_at": r.submitted_at.isoformat() if r.submitted_at else None,
    } for r in rows]}), 200


@app.route("/api/hitl/requests/<int:request_id>/claim", methods=["POST"])
@csrf.exempt
def hitl_request_claim(request_id):
    user, err = _erp_user_or_401()
    if err: return err
    reviewer = ProfessionalReviewer.query.filter_by(owner_user_id=user["id"], verified=True, active=True).first()
    if not reviewer:
        return jsonify({"error": "You are not a verified reviewer."}), 403
    r = ReviewRequest.query.get(request_id)
    if not r or r.status != "pending":
        return jsonify({"error": "Request is not available to claim."}), 400
    if r.credential_type != reviewer.credential_type:
        return jsonify({"error": f"This request needs a {r.credential_type}, not a {reviewer.credential_type}."}), 400
    r.status = "claimed"
    r.reviewer_user_id = user["id"]
    r.claimed_at = datetime.utcnow()
    db.session.commit()
    notify_user(r.requester_user_id, "hitl", "Your document was claimed for review",
                f"A verified {r.credential_type} is now reviewing \"{r.document_title}\".")
    return jsonify({"ok": True, "id": r.id, "content_text": r.content_text}), 200


@app.route("/api/hitl/requests/<int:request_id>/complete", methods=["POST"])
@csrf.exempt
def hitl_request_complete(request_id):
    user, err = _erp_user_or_401()
    if err: return err
    r = ReviewRequest.query.get(request_id)
    if not r or r.status != "claimed" or r.reviewer_user_id != user["id"]:
        return jsonify({"error": "You don't have this request claimed."}), 400
    data = request.get_json(silent=True) or {}
    notes = (data.get("review_notes") or "").strip()
    if not notes:
        return jsonify({"error": "'review_notes' is required to complete a review."}), 400
    r.status = "rejected" if data.get("reject") else "completed"
    r.review_notes = notes[:8000]
    r.signed_off = bool(data.get("signed_off")) and r.status == "completed"
    r.completed_at = datetime.utcnow()
    db.session.commit()
    notify_user(r.requester_user_id, "hitl",
                "Review complete" if r.status == "completed" else "Review declined",
                f"\"{r.document_title}\" — {notes[:150]}")
    return jsonify({"ok": True, "id": r.id, "status": r.status}), 200


# =====================================================================
# STAGE: Enterprise Roadmap Part 2.7 — Offline Resilience (CRDT queue).
# Remote operators (factory floor, farm field) often have no signal.
# The client queues entries locally with a generated client_sync_id and
# a local timestamp, then flushes the whole queue here on reconnect.
# Because every entry carries its own unique ID, this endpoint is a
# grow-only, conflict-free merge: replaying the same entry twice (a
# flaky reconnect retry) is a no-op, not a duplicate row, and entries
# from different offline sessions never overwrite each other — there's
# nothing to "merge" because each entry is independent.
# =====================================================================
_OFFLINE_SYNC_HANDLERS = {}  # entity_type -> function(user_id, client_sync_id, recorded_at, payload) -> dict

def _offline_sync_mfg_downtime(user_id, client_sync_id, recorded_at, payload):
    existing = ProductionDowntimeEvent.query.filter_by(owner_user_id=user_id, client_sync_id=client_sync_id).first()
    if existing:
        return {"ok": True, "id": existing.id, "already_synced": True}
    row = ProductionDowntimeEvent(
        owner_user_id=user_id, client_sync_id=client_sync_id,
        line_name=(payload.get("line_name") or "Unnamed line")[:120],
        reason_code=(payload.get("reason_code") or "unplanned")[:40],
        root_cause=payload.get("root_cause"), logged_by=(payload.get("logged_by") or "")[:120],
        started_at=recorded_at or datetime.utcnow(),
    )
    db.session.add(row)
    db.session.commit()
    return {"ok": True, "id": row.id}

def _offline_sync_soil_test(user_id, client_sync_id, recorded_at, payload):
    existing = SoilTestLog.query.filter_by(owner_user_id=user_id, client_sync_id=client_sync_id).first()
    if existing:
        return {"ok": True, "id": existing.id, "already_synced": True}
    row = SoilTestLog(
        owner_user_id=user_id, client_sync_id=client_sync_id,
        field_name=(payload.get("field_name") or "Unnamed field")[:120],
        test_date=(recorded_at.date() if recorded_at else datetime.utcnow().date()),
        ph_level=payload.get("ph_level"), nitrogen_ppm=payload.get("nitrogen_ppm"),
        phosphorus_ppm=payload.get("phosphorus_ppm"), potassium_ppm=payload.get("potassium_ppm"),
        organic_matter_pct=payload.get("organic_matter_pct"), lab_name=payload.get("lab_name"),
        recommendation_notes=payload.get("recommendation_notes"),
    )
    db.session.add(row)
    db.session.commit()
    return {"ok": True, "id": row.id}

def _offline_sync_erp_expense(user_id, client_sync_id, recorded_at, payload):
    """Lets a business log an expense with zero connectivity (see the
    on-device Isolation Forest pre-check in the frontend) and have it
    land exactly the way a live POST to /api/erp/expenses would —
    including the matching ledger entry — the moment the device is
    back online. Idempotent on (owner_user_id, client_sync_id)."""
    existing = ErpExpense.query.filter_by(owner_user_id=user_id, client_sync_id=client_sync_id).first()
    if existing:
        return {"ok": True, "id": existing.id, "already_synced": True}
    try:
        amount = float(payload.get("amount", 0) or 0)
    except Exception:
        amount = 0
    if amount <= 0:
        return {"ok": False, "error": "amount must be greater than zero."}
    expense_date = recorded_at.date() if recorded_at else datetime.utcnow().date()
    row = ErpExpense(
        owner_user_id=user_id, client_sync_id=client_sync_id, expense_date=expense_date,
        category=(payload.get("category") or "general")[:80], vendor=payload.get("vendor"),
        amount=amount, currency=payload.get("currency", "USD"), payment_method=payload.get("payment_method"),
        notes=payload.get("notes"),
    )
    db.session.add(row)
    db.session.flush()
    _erp_post_ledger(user_id, row.expense_date, "expense", row.category,
                      row.vendor or row.notes, -abs(amount), "expense", row.id)
    db.session.commit()
    return {"ok": True, "id": row.id}

_OFFLINE_SYNC_HANDLERS["mfg_downtime"] = _offline_sync_mfg_downtime
_OFFLINE_SYNC_HANDLERS["soil_test"] = _offline_sync_soil_test
_OFFLINE_SYNC_HANDLERS["erp_expense"] = _offline_sync_erp_expense


@app.route("/api/offline-sync/batch", methods=["POST"])
@csrf.exempt
def offline_sync_batch():
    user, err = _erp_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    entries = data.get("entries") or []
    if not isinstance(entries, list) or not entries:
        return jsonify({"error": "'entries' must be a non-empty array."}), 400
    if len(entries) > 200:
        return jsonify({"error": "Max 200 entries per batch."}), 400

    results = []
    for entry in entries:
        client_sync_id = (entry.get("client_id") or "").strip()
        entity_type = (entry.get("entity_type") or "").strip()
        payload = entry.get("payload") or {}
        recorded_at = _erp_parse_datetime(entry.get("recorded_at"), default=None)
        if not client_sync_id or entity_type not in _OFFLINE_SYNC_HANDLERS:
            results.append({"client_id": client_sync_id, "ok": False, "error": f"Unknown or missing entity_type '{entity_type}'."})
            continue
        try:
            res = _OFFLINE_SYNC_HANDLERS[entity_type](user["id"], client_sync_id, recorded_at, payload)
            res["client_id"] = client_sync_id
            results.append(res)
        except Exception as e:
            db.session.rollback()
            logging.error(f"[OFFLINE SYNC ERROR] user={user['id']} type={entity_type} client_id={client_sync_id}: {e}")
            results.append({"client_id": client_sync_id, "ok": False, "error": str(e)})

    synced = sum(1 for r in results if r.get("ok"))
    return jsonify({"ok": synced > 0, "synced": synced, "total": len(entries), "results": results}), 200


