# FEATURE 1 — Unified notification inbox across every module.
# Any module in the app can call notify_user(...) to drop a bell-icon
# notification for a user; the frontend polls the two GET endpoints.
# ---------------------------------------------------------------------
class Notification(db.Model):
    __tablename__ = "notifications"
    id            = db.Column(db.Integer, primary_key=True)
    owner_user_id = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    module        = db.Column(db.String(40),  nullable=False, default="general", index=True)
    title         = db.Column(db.String(200), nullable=False)
    body          = db.Column(db.Text,        nullable=True)
    link          = db.Column(db.String(500), nullable=True)
    is_read       = db.Column(db.Boolean,     nullable=False, default=False, index=True)
    created_at    = db.Column(db.DateTime,    default=datetime.utcnow, index=True)

    def to_dict(self):
        return {
            "id": self.id, "module": self.module, "title": self.title, "body": self.body,
            "link": self.link, "is_read": self.is_read,
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }


def notify_user(owner_user_id, module, title, body=None, link=None):
    """Call this from anywhere in the app to raise a notification —
    e.g. notify_user(sale.owner_user_id, 'pos', 'Low stock', 'SKU 1042 is below reorder point.')"""
    try:
        db.session.add(Notification(owner_user_id=owner_user_id, module=module[:40],
                                     title=title[:200], body=body, link=link))
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        logging.warning(f"[NOTIFY] failed to write notification: {e}")


@app.route("/api/notifications", methods=["GET"])
def notifications_list():
    user, err = _erp_user_or_401()
    if err: return err
    q = Notification.query.filter_by(owner_user_id=user["id"])
    module = request.args.get("module")
    if module: q = q.filter_by(module=module)
    if request.args.get("unread_only") == "1": q = q.filter_by(is_read=False)
    limit = min(int(request.args.get("limit", 50) or 50), 200)
    rows = q.order_by(Notification.created_at.desc()).limit(limit).all()
    return jsonify({"notifications": [r.to_dict() for r in rows]}), 200


