@app.route("/api/dashboard/departments", methods=["GET"])
def dashboard_departments_list():
    user, err = _erp_user_or_401()
    if err: return err
    rows = DepartmentDashboard.query.filter_by(owner_user_id=user["id"]).all()
    configured = {r.department: r.to_dict() for r in rows}
    depts = sorted(set(list(DASHBOARD_DEFAULT_WIDGETS.keys()) + list(configured.keys())) - {"default"})
    out = []
    for d in depts:
        out.append(configured.get(d) or {"department": d, "widgets": DASHBOARD_DEFAULT_WIDGETS.get(d, DASHBOARD_DEFAULT_WIDGETS["default"])})
    return jsonify({"departments": out, "widget_catalog": DASHBOARD_WIDGET_CATALOG}), 200


