    data = request.get_json(silent=True) or {}
    department = (data.get("department") or "").strip().lower()[:40]
    if not department:
        return jsonify({"error": "Department is required."}), 400
    widgets = [w for w in (data.get("widgets") or []) if w in DASHBOARD_WIDGET_CATALOG]
    row = DepartmentDashboard.query.filter_by(owner_user_id=user["id"], department=department).first()
