@app.route("/api/reports/builder/modules", methods=["GET"])
def report_builder_modules():
    user, err = _erp_user_or_401()
    if err: return err
    out = {k: v["fields"] for k, v in REPORT_MODULE_REGISTRY.items()}
    return jsonify({"modules": out}), 200


def _report_builder_query(user_id, module, fields, filters, group_by, limit):
    cfg = REPORT_MODULE_REGISTRY.get(module)
    if not cfg:
        return None, f"Unknown report module '{module}'."
    model, owner_field = cfg["model"], cfg["owner_field"]
    safe_fields = [f for f in (fields or cfg["fields"]) if f in cfg["fields"]] or cfg["fields"]
    q = model.query.filter(getattr(model, owner_field) == user_id)
    for f in (filters or [])[:10]:
        col = f.get("field")
        if col not in cfg["fields"]: continue
        val = f.get("value")
        op = f.get("op", "eq")
        column = getattr(model, col)
        if op == "eq":   q = q.filter(column == val)
        elif op == "contains" and hasattr(column.type, "python_type"):
            try: q = q.filter(column.ilike(f"%{val}%"))
            except Exception: pass
        elif op == "gte": q = q.filter(column >= val)
        elif op == "lte": q = q.filter(column <= val)
    rows = q.limit(min(int(limit or 500), 5000)).all()
    out_rows = []
    for r in rows:
        row = {}
        for f in safe_fields:
            v = getattr(r, f, None)
            row[f] = v.isoformat() if hasattr(v, "isoformat") else v
        out_rows.append(row)
    if group_by and group_by in safe_fields:
        grouped = defaultdict(list)
        for r in out_rows: grouped[r.get(group_by)].append(r)
        return {"grouped": True, "groups": [{"key": k, "rows": v, "count": len(v)} for k, v in grouped.items()], "fields": safe_fields}, None
    return {"grouped": False, "rows": out_rows, "fields": safe_fields}, None


