@app.route("/api/export/<string:module>", methods=["GET"])
def universal_export(module):
    """Universal CSV / Excel export — add ?format=xlsx for Excel,
    defaults to CSV. Works against any module in REPORT_MODULE_REGISTRY,
    which is the same whitelist the report builder uses, so a list view
    just needs one 'Export' button pointed at this endpoint."""
    user, err = _erp_user_or_401()
    if err: return err
    fmt = (request.args.get("format") or "csv").lower()
    fields_param = request.args.get("fields")
    fields = fields_param.split(",") if fields_param else None
    result, error = _report_builder_query(user["id"], module, fields, None, None, request.args.get("limit", 5000))
    if error: return jsonify({"error": error}), 400
    rows, out_fields = result["rows"], result["fields"]

    if fmt == "xlsx":
        wb = _MegaWorkbook()
        ws = wb.active
        ws.title = module[:31]
        ws.append(out_fields)
        for r in rows:
            ws.append([r.get(f, "") for f in out_fields])
        buf = BytesIO()
        wb.save(buf)
        buf.seek(0)
        resp = app.response_class(buf.read(), mimetype="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")
        resp.headers["Content-Disposition"] = f"attachment; filename={module}-export.xlsx"
        return resp

    buf = io.StringIO()
    writer = csv.writer(buf)
    writer.writerow(out_fields)
    for r in rows:
        writer.writerow([r.get(f, "") for f in out_fields])
    resp = app.response_class(buf.getvalue(), mimetype="text/csv")
    resp.headers["Content-Disposition"] = f"attachment; filename={module}-export.csv"
    return resp


# ---------------------------------------------------------------------
# FEATURE 9 — White-label branding applied to invoices/receipts.
# BusinessBranding already exists (chat widget + storefront). This adds
# a shared helper any invoice/receipt endpoint can call to fetch the
# same logo/colors, so a business's branding is consistent everywhere.
# ---------------------------------------------------------------------
def get_document_branding(owner_user_id):
    b = BusinessBranding.query.filter_by(owner_user_id=owner_user_id).first()
    if not b:
        return {"display_name": None, "logo_url": None, "primary_color": "#ea580c",
                "accent_color": "#7c3aed", "footer_text": None}
    return {"display_name": b.display_name, "logo_url": b.logo_url,
            "primary_color": b.primary_color or "#ea580c", "accent_color": b.accent_color or "#7c3aed",
            "footer_text": b.footer_text}


@app.route("/api/pos/sales/<int:sale_id>/receipt-branding", methods=["GET"])
def pos_receipt_branding(sale_id):
    """Companion to the existing /api/pos/sales/<id>/receipt (plain text)
    endpoint above — returns just the branding block so the receipt
    renderer on the frontend can show the business's own logo/colors
    instead of the default Connect It look."""
    user, err = _erp_user_or_401()
    if err: return err
    sale = PosSale.query.get(sale_id)
    if not sale or sale.owner_user_id != user["id"]:
        return jsonify({"error": "Sale not found."}), 404
    return jsonify({"branding": get_document_branding(user["id"])}), 200




