# ---------------------------------------------------------------
# 1. LOYALTY CARD AS APPLE WALLET / GOOGLE WALLET PASS
#    BYOK: a business pastes their own Apple Pass Type ID cert (+ WWDR
#    cert + private key, all PEM, base64-pasted) and/or a Google Wallet
#    service-account JSON under provider "apple_wallet" / "google_wallet"
#    via the existing /api/integrations/keys endpoint. Without those on
#    file the endpoints below return a clear 400 telling the business
#    what to configure, rather than silently faking a pass.
# ---------------------------------------------------------------

def _wallet_apple_configured(user_id):
    c = get_user_credentials(user_id, "apple_wallet")
    return bool(c.get("pass_type_identifier") and c.get("team_identifier")
                and c.get("signer_cert_pem") and c.get("signer_key_pem") and c.get("wwdr_cert_pem"))


def _wallet_google_configured(user_id):
    c = get_user_credentials(user_id, "google_wallet")
    return bool(c.get("service_account_json") and c.get("issuer_id"))


@app.route("/api/wallet/status", methods=["GET"])
def wallet_pass_status():
    user, err = _erp_user_or_401()
    if err: return err
    return jsonify({
        "apple_configured": _wallet_apple_configured(user["id"]),
        "google_configured": _wallet_google_configured(user["id"]),
    }), 200


def _build_apple_pkpass_bytes(user_id, program, customer):
    """Builds a real, signed .pkpass file using openssl (present on every
    PythonAnywhere/Linux box) via the smime CLI for the PKCS#7 detached
    signature Apple requires — no extra pip package needed beyond the
    stdlib zipfile/json already imported at the top of this file."""
    import subprocess
    creds = get_user_credentials(user_id, "apple_wallet")
    branding = get_document_branding(user_id)
    serial = f"loy-{customer.id}-{secrets.token_hex(4)}"
    pass_json = {
        "formatVersion": 1,
        "passTypeIdentifier": creds["pass_type_identifier"],
        "teamIdentifier": creds["team_identifier"],
        "organizationName": branding.get("display_name") or "Connect It",
        "serialNumber": serial,
        "description": f"{program.name} loyalty card",
        "backgroundColor": "rgb(30,58,138)",
        "foregroundColor": "rgb(255,255,255)",
        "storeCard": {
            "primaryFields": [{"key": "balance", "label": "POINTS", "value": customer.balance}],
            "secondaryFields": [{"key": "name", "label": "MEMBER", "value": customer.name or customer.phone}],
            "auxiliaryFields": [{"key": "reward", "label": "REWARD AT", "value": program.threshold}],
        },
        "barcodes": [{"message": customer.phone, "format": "PKBarcodeFormatQR",
                       "messageEncoding": "iso-8859-1", "altText": customer.phone}],
    }
    pass_bytes = json.dumps(pass_json).encode("utf-8")
    # A 1x1 transparent PNG placeholder — businesses can override icon.png
    # /logo.png later by re-uploading through this same endpoint once we
    # add image fields; the pass is fully valid without a custom icon.
    tiny_png = base64.b64decode(
        "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNk+A8AAQUBAScY42YAAAAASUVORK5CYII=")
    files = {"pass.json": pass_bytes, "icon.png": tiny_png, "icon@2x.png": tiny_png}
    manifest = {name: hashlib.sha1(content).hexdigest() for name, content in files.items()}
    manifest_bytes = json.dumps(manifest).encode("utf-8")

    with tempfile.TemporaryDirectory() as td:
        cert_path = os.path.join(td, "signer.pem")
        key_path = os.path.join(td, "signer.key")
        wwdr_path = os.path.join(td, "wwdr.pem")
        manifest_path = os.path.join(td, "manifest.json")
        sig_path = os.path.join(td, "signature")
        with open(cert_path, "w") as f: f.write(creds["signer_cert_pem"])
        with open(key_path, "w") as f: f.write(creds["signer_key_pem"])
        with open(wwdr_path, "w") as f: f.write(creds["wwdr_cert_pem"])
        with open(manifest_path, "wb") as f: f.write(manifest_bytes)
        key_pass = creds.get("signer_key_password", "")
        cmd = ["openssl", "smime", "-binary", "-sign", "-certfile", wwdr_path,
               "-signer", cert_path, "-inkey", key_path,
               "-in", manifest_path, "-out", sig_path,
               "-outform", "DER"]
        if key_pass:
            cmd += ["-passin", f"pass:{key_pass}"]
        result = subprocess.run(cmd, capture_output=True, timeout=15)
        if result.returncode != 0:
            raise RuntimeError(f"openssl signing failed: {result.stderr.decode(errors='replace')[:300]}")
        with open(sig_path, "rb") as f: signature_bytes = f.read()

    buf = BytesIO()
    with zipfile.ZipFile(buf, "w", zipfile.ZIP_DEFLATED) as zf:
        for name, content in files.items():
            zf.writestr(name, content)
        zf.writestr("manifest.json", manifest_bytes)
        zf.writestr("signature", signature_bytes)
    buf.seek(0)
    return buf.read(), serial


@app.route("/api/wallet/loyalty/<int:customer_id>/apple", methods=["GET"])
def wallet_loyalty_apple_pkpass(customer_id):
    user, err = _erp_user_or_401()
    if err: return err
    customer = LoyaltyCustomer.query.get(customer_id)
    if not customer:
        return jsonify({"error": "Loyalty member not found."}), 404
    program = LoyaltyProgram.query.get(customer.program_id)
    if not program or program.owner_id != user["id"]:
        return jsonify({"error": "Not your loyalty program."}), 403
    if not _wallet_apple_configured(user["id"]):
        return jsonify({"error": "Add your Apple Pass Type ID, Team ID, signer cert/key and WWDR cert "
                                  "under Integrations \u2192 Apple Wallet before issuing passes."}), 400
    try:
        pkpass_bytes, serial = _build_apple_pkpass_bytes(user["id"], program, customer)
    except Exception as e:
        logging.error(f"[APPLE WALLET] {e}")
        return jsonify({"error": f"Could not build pass: {e}"}), 500
    resp = app.response_class(pkpass_bytes, mimetype="application/vnd.apple.pkpass")
    resp.headers["Content-Disposition"] = f"attachment; filename=loyalty-{serial}.pkpass"
    return resp


@app.route("/api/wallet/loyalty/<int:customer_id>/google", methods=["GET"])
def wallet_loyalty_google_link(customer_id):
    user, err = _erp_user_or_401()
    if err: return err
    customer = LoyaltyCustomer.query.get(customer_id)
    if not customer:
        return jsonify({"error": "Loyalty member not found."}), 404
    program = LoyaltyProgram.query.get(customer.program_id)
    if not program or program.owner_id != user["id"]:
        return jsonify({"error": "Not your loyalty program."}), 403
    if not _wallet_google_configured(user["id"]):
        return jsonify({"error": "Add your Google Wallet service-account JSON and Issuer ID "
                                  "under Integrations \u2192 Google Wallet before issuing passes."}), 400
    creds = get_user_credentials(user["id"], "google_wallet")
    branding = get_document_branding(user["id"])
    try:
        sa = json.loads(creds["service_account_json"])
        issuer_id = creds["issuer_id"]
        class_id = f"{issuer_id}.loyalty_{program.id}"
        object_id = f"{issuer_id}.loyalty_{program.id}_{customer.id}"
        loyalty_object = {
            "id": object_id,
            "classId": class_id,
            "state": "ACTIVE",
            "accountId": customer.phone,
            "accountName": customer.name or customer.phone,
            "loyaltyPoints": {"balance": {"int": customer.balance}},
            "barcode": {"type": "QR_CODE", "value": customer.phone},
        }
        payload = {
            "iss": sa["client_email"],
            "aud": "google",
            "typ": "savetowallet",
            "iat": int(time.time()),
            "origins": [],
            "payload": {
                "loyaltyClasses": [{
                    "id": class_id, "issuerName": branding.get("display_name") or "Connect It",
                    "programName": program.name, "reviewStatus": "UNDER_REVIEW",
                }],
                "loyaltyObjects": [loyalty_object],
            },
        }
        signed = jwt.encode(payload, sa["private_key"], algorithm="RS256")
        save_url = f"https://pay.google.com/gp/v/save/{signed}"
    except Exception as e:
        logging.error(f"[GOOGLE WALLET] {e}")
        return jsonify({"error": f"Could not build Google Wallet link: {e}"}), 500
    return jsonify({"ok": True, "save_url": save_url}), 200


# ---------------------------------------------------------------
# 2. OPT-IN BLUETOOTH-BEACON FOOTFALL COUNTER
#    A store places one or more cheap BLE beacons; a customer opts in
#    once (via the storefront/PWA, which then silently reports beacon
#    RSSI pings while in range). No location tracking of any customer
#    who hasn't explicitly opted in, and opt-out removes future pings.
# ---------------------------------------------------------------

class StoreBeacon(db.Model):
    __tablename__ = "retail_store_beacons"
    id             = db.Column(db.Integer, primary_key=True)
    owner_user_id  = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    location_id    = db.Column(db.Integer, db.ForeignKey("mfg_inventory_locations.id"), nullable=True)
    label          = db.Column(db.String(120), nullable=False)          # e.g. "Front door", "Aisle 3"
    beacon_uuid    = db.Column(db.String(64),  nullable=False, index=True)
    major          = db.Column(db.Integer, nullable=True)
    minor          = db.Column(db.Integer, nullable=True)
    active         = db.Column(db.Boolean, nullable=False, default=True)
    created_at     = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        return {"id": self.id, "location_id": self.location_id, "label": self.label,
                "beacon_uuid": self.beacon_uuid, "major": self.major, "minor": self.minor,
                "active": self.active}


class BeaconOptIn(db.Model):
    __tablename__ = "retail_beacon_optins"
    id             = db.Column(db.Integer, primary_key=True)
    owner_user_id  = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    device_token   = db.Column(db.String(120), nullable=False, index=True)   # random id generated client-side, not a real device id
    customer_phone = db.Column(db.String(32), nullable=True)
    opted_in       = db.Column(db.Boolean, nullable=False, default=True)
    updated_at     = db.Column(db.DateTime, default=datetime.utcnow, onupdate=datetime.utcnow)
    __table_args__ = (db.UniqueConstraint("owner_user_id", "device_token", name="uq_beacon_optin_device"),)


class BeaconFootfallEvent(db.Model):
    __tablename__ = "retail_beacon_footfall"
    id             = db.Column(db.Integer, primary_key=True)
    owner_user_id  = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    beacon_id      = db.Column(db.Integer, db.ForeignKey("retail_store_beacons.id"), nullable=False, index=True)
    device_token   = db.Column(db.String(120), nullable=False, index=True)
    rssi           = db.Column(db.Integer, nullable=True)
    created_at     = db.Column(db.DateTime, default=datetime.utcnow, index=True)


