# ---------------------------------------------------------------
# 6. CURBSIDE PICKUP SCHEDULING
#    A business defines pickup slots per location; a buyer with an
#    existing ProductOrder books a slot. Capacity-limited per slot.
# ---------------------------------------------------------------

class CurbsidePickupSlot(db.Model):
    __tablename__ = "retail_curbside_slots"
    id             = db.Column(db.Integer, primary_key=True)
    owner_user_id  = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    location_id    = db.Column(db.Integer, db.ForeignKey("mfg_inventory_locations.id"), nullable=True)
    start_time     = db.Column(db.DateTime, nullable=False, index=True)
    end_time       = db.Column(db.DateTime, nullable=False)
    capacity       = db.Column(db.Integer, nullable=False, default=4)
    created_at     = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self, booked_count=0):
        return {"id": self.id, "location_id": self.location_id,
                "start_time": self.start_time.isoformat() if self.start_time else None,
                "end_time": self.end_time.isoformat() if self.end_time else None,
                "capacity": self.capacity, "booked_count": booked_count,
                "spots_left": max(0, self.capacity - booked_count)}


class CurbsidePickupBooking(db.Model):
    __tablename__ = "retail_curbside_bookings"
    id             = db.Column(db.Integer, primary_key=True)
    slot_id        = db.Column(db.Integer, db.ForeignKey("retail_curbside_slots.id"), nullable=False, index=True)
    order_id       = db.Column(db.Integer, db.ForeignKey("product_orders.id"), nullable=False, index=True)
    buyer_id       = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    vehicle_desc   = db.Column(db.String(160), nullable=True)   # "Blue Toyota Vitz, ABC 1234" \u2014 for staff to spot
    status         = db.Column(db.String(20), nullable=False, default="scheduled")  # scheduled, arrived, completed, cancelled
    created_at     = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        return {"id": self.id, "slot_id": self.slot_id, "order_id": self.order_id,
                "vehicle_desc": self.vehicle_desc, "status": self.status,
                "created_at": self.created_at.isoformat() if self.created_at else None}


@app.route("/api/retail/curbside/slots", methods=["GET"])
def retail_curbside_slots_list():
    """Public-ish read (any logged-in user, since a buyer needs to see a
    seller's open slots) \u2014 pass owner_user_id as a query param."""
    owner_user_id = request.args.get("owner_user_id", type=int)
    if not owner_user_id:
        user, err = _erp_user_or_401()
        if err: return err
        owner_user_id = user["id"]
    from_time = datetime.utcnow()
    rows = (CurbsidePickupSlot.query.filter(CurbsidePickupSlot.owner_user_id == owner_user_id,
                                             CurbsidePickupSlot.start_time >= from_time)
            .order_by(CurbsidePickupSlot.start_time).limit(100).all())
    out = []
    for r in rows:
        booked = CurbsidePickupBooking.query.filter(CurbsidePickupBooking.slot_id == r.id,
                                                      CurbsidePickupBooking.status != "cancelled").count()
        out.append(r.to_dict(booked))
    return jsonify({"slots": out}), 200


@app.route("/api/retail/curbside/slots", methods=["POST"])
@csrf.exempt
def retail_curbside_slots_create():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
