# ---------------------------------------------------------------
# 7. STORE-TO-STORE INVENTORY TRANSFER REQUESTS
#    Extends the existing StockTransfer/InventoryLocation tables (mfg
#    module) with a request \u2192 approve/reject \u2192 fulfil workflow instead
#    of the "always already completed" transfer it supported before.
#    Reuses that table rather than a parallel one.
# ---------------------------------------------------------------

@app.route("/api/retail/transfer-requests", methods=["POST"])
@csrf.exempt
def retail_transfer_request_create():
    """Same owner (one business, many store locations) requests stock be
    moved from one of their locations to another \u2014 status starts at
    'requested' instead of the old default 'completed', and stock does
    NOT move until it's approved and fulfilled below."""
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    item = InventoryItem.query.filter_by(id=data.get("item_id"), user_id=user["id"]).first()
    to_loc = InventoryLocation.query.filter_by(id=data.get("to_location_id"), owner_user_id=user["id"]).first()
    if not item: return jsonify({"error": "Item not found."}), 404
    if not to_loc: return jsonify({"error": "Destination location not found."}), 404
    try:
        qty = float(data.get("quantity"))
        if qty <= 0: raise ValueError
    except (TypeError, ValueError):
        return jsonify({"error": "quantity must be a positive number."}), 400
    row = StockTransfer(owner_user_id=user["id"], item_id=item.id,
                         from_location_id=data.get("from_location_id"), to_location_id=to_loc.id,
                         quantity=qty, status="requested",
                         requested_by=(data.get("requested_by") or "").strip() or None)
    db.session.add(row); db.session.commit()
    return jsonify({"ok": True, "transfer": row.to_dict()}), 201


@app.route("/api/retail/transfer-requests/<int:transfer_id>/approve", methods=["POST"])
@csrf.exempt
def retail_transfer_request_approve(transfer_id):
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    row = StockTransfer.query.filter_by(id=transfer_id, owner_user_id=user["id"]).first()
    if not row: return jsonify({"error": "Transfer request not found."}), 404
    if row.status != "requested":
        return jsonify({"error": f"Cannot approve a transfer in '{row.status}' status."}), 400
    row.status = "in_transit"
    db.session.commit()
    return jsonify({"ok": True, "transfer": row.to_dict()}), 200


@app.route("/api/retail/transfer-requests/<int:transfer_id>/reject", methods=["POST"])
@csrf.exempt
def retail_transfer_request_reject(transfer_id):
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    row = StockTransfer.query.filter_by(id=transfer_id, owner_user_id=user["id"]).first()
    if not row: return jsonify({"error": "Transfer request not found."}), 404
    if row.status != "requested":
        return jsonify({"error": f"Cannot reject a transfer in '{row.status}' status."}), 400
    row.status = "rejected"
    db.session.commit()
    return jsonify({"ok": True, "transfer": row.to_dict()}), 200


@app.route("/api/retail/transfer-requests/<int:transfer_id>/fulfil", methods=["POST"])
@csrf.exempt
def retail_transfer_request_fulfil(transfer_id):
    """Actually moves the stock, once approved (in_transit)."""
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    row = StockTransfer.query.filter_by(id=transfer_id, owner_user_id=user["id"]).first()
    if not row: return jsonify({"error": "Transfer request not found."}), 404
    if row.status != "in_transit":
        return jsonify({"error": "Only an approved (in-transit) transfer can be fulfilled."}), 400
    if row.from_location_id:
        from_stock = _mfg_location_stock_row(user["id"], row.from_location_id, row.item_id)
        if from_stock.quantity < row.quantity:
            return jsonify({"error": "Not enough stock at the source location."}), 400
        from_stock.quantity -= row.quantity
    to_stock = _mfg_location_stock_row(user["id"], row.to_location_id, row.item_id)
    to_stock.quantity += row.quantity
    row.status = "completed"
    db.session.commit()
    return jsonify({"ok": True, "transfer": row.to_dict()}), 200


@app.route("/api/retail/transfer-requests", methods=["GET"])
def retail_transfer_requests_list():
    user, err = _erp_user_or_401()
    if err: return err
    status = request.args.get("status")
    q = StockTransfer.query.filter_by(owner_user_id=user["id"])
    if status: q = q.filter_by(status=status)
    rows = q.order_by(StockTransfer.created_at.desc()).limit(200).all()
    return jsonify({"transfers": [r.to_dict() for r in rows]}), 200


