# ---------------------------------------------------------------
# 8. DIGITAL RECEIPT LOOKUP BY PHONE NUMBER
#    A walk-in customer without their paper receipt can be looked up by
#    the phone number captured at sale time (new PosSale.customer_phone
#    snapshot) or via their saved ErpCustomer record.
# ---------------------------------------------------------------

@app.route("/api/retail/receipts/lookup", methods=["GET"])
def retail_receipt_lookup():
    user, err = _erp_user_or_401()
    if err: return err
    phone = (request.args.get("phone") or "").strip()
    if not phone:
        return jsonify({"error": "phone is required."}), 400
    digits = "".join(ch for ch in phone if ch.isdigit())
    customer_ids = [c.id for c in ErpCustomer.query.filter_by(owner_user_id=user["id"]).all()
                    if c.phone and "".join(ch for ch in c.phone if ch.isdigit()).endswith(digits[-7:] if len(digits) >= 7 else digits)]
    q = PosSale.query.filter_by(owner_user_id=user["id"], voided=False)
    matches = [s for s in q.order_by(PosSale.created_at.desc()).limit(500).all()
               if (s.customer_phone and "".join(ch for ch in s.customer_phone if ch.isdigit()).endswith(digits[-7:] if len(digits) >= 7 else digits))
               or (s.customer_id in customer_ids)]
    return jsonify({"receipts": [s.to_dict() for s in matches[:50]]}), 200


