@app.route("/api/retail/bundles/<int:bundle_id>/sell", methods=["POST"])
@csrf.exempt
def retail_bundle_sell(bundle_id):
    """Deducts each component's stock by (component quantity x kits sold).
    Does not create a PosSale itself — pairs with the till's own checkout
    for recording the money side; this just moves the stock."""
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    bundle = ProductBundle.query.filter_by(id=bundle_id, owner_user_id=user["id"]).first()
    if not bundle: return jsonify({"error": "Bundle not found."}), 404
    data = request.get_json(silent=True) or {}
    try:
        kits = float(data.get("quantity", 1))
        if kits <= 0: raise ValueError
    except (TypeError, ValueError):
        return jsonify({"error": "quantity must be a positive number."}), 400
    items = ProductBundleItem.query.filter_by(bundle_id=bundle.id).all()
    for it in items:
        comp = InventoryItem.query.filter_by(id=it.item_id, user_id=user["id"]).first()
        if comp is None: continue
        need = it.quantity * kits
        if (comp.quantity or 0) < need:
            return jsonify({"error": f"Not enough stock of '{comp.name}' for {kits} kit(s)."}), 400
    for it in items:
        comp = InventoryItem.query.filter_by(id=it.item_id, user_id=user["id"]).first()
        if comp is None: continue
        comp.quantity = (comp.quantity or 0) - (it.quantity * kits)
    db.session.commit()
    return jsonify({"ok": True, "bundle": bundle.to_dict()}), 200


# ---------------------------------------------------------------
# 10. RETURN-REASON ANALYTICS DASHBOARD
#     Aggregates the free-text `reason` fields already captured on
#     PosReturn (till returns) and ReturnClaim (warranty claims) into a
#     small set of buckets by keyword match — no new data entry required
#     from staff, since both tables already collect a reason today.
# ---------------------------------------------------------------

_RETURN_REASON_BUCKETS = [
    ("Defective / damaged", ["defect", "broken", "damage", "faulty", "doesn't work", "not working", "malfunction"]),
    ("Wrong item", ["wrong item", "wrong size", "wrong color", "wrong colour", "incorrect item", "not what i ordered"]),
    ("Changed mind", ["changed my mind", "changed mind", "no longer need", "don't want", "dont want", "found cheaper"]),
    ("Size / fit", ["too small", "too big", "doesn't fit", "does not fit", "fit issue", "size issue"]),
    ("Late / never arrived", ["late", "never arrived", "took too long", "delayed"]),
]


def _bucket_return_reason(text):
    t = (text or "").lower()
    for label, keywords in _RETURN_REASON_BUCKETS:
        if any(k in t for k in keywords):
            return label
    return "Other / unspecified"


@app.route("/api/retail/returns/analytics", methods=["GET"])
def retail_returns_analytics():
    user, err = _erp_user_or_401()
    if err: return err
    try:
        days = int(request.args.get("days", 90))
    except (TypeError, ValueError):
        days = 90
    since = datetime.utcnow() - timedelta(days=max(days, 1))
    pos_returns = PosReturn.query.filter(PosReturn.owner_user_id == user["id"],
                                          PosReturn.created_at >= since).all()
    claims = ReturnClaim.query.filter(ReturnClaim.owner_id == user["id"],
                                       ReturnClaim.created_at >= since).all()
    buckets = {}
    monthly = {}
    total_refund = 0.0
    for r in pos_returns:
        label = _bucket_return_reason(r.reason)
        buckets.setdefault(label, {"count": 0, "amount": 0.0})
        buckets[label]["count"] += 1
        buckets[label]["amount"] += (r.refund_amount or 0.0)
        total_refund += (r.refund_amount or 0.0)
        key = r.created_at.strftime("%Y-%m") if r.created_at else "unknown"
        monthly[key] = monthly.get(key, 0) + 1
    for c in claims:
        label = _bucket_return_reason(c.reason)
        buckets.setdefault(label, {"count": 0, "amount": 0.0})
        buckets[label]["count"] += 1
        key = c.created_at.strftime("%Y-%m") if c.created_at else "unknown"
        monthly[key] = monthly.get(key, 0) + 1
    breakdown = [{"reason": label, "count": v["count"], "amount": round(v["amount"], 2)}
                 for label, v in sorted(buckets.items(), key=lambda kv: -kv[1]["count"])]
    trend = [{"month": k, "count": v} for k, v in sorted(monthly.items())]
    return jsonify({
        "period_days": days, "total_returns": len(pos_returns) + len(claims),
        "total_refund_amount": round(total_refund, 2),
        "breakdown": breakdown, "monthly_trend": trend,
    }), 200


# ---------------------------------------------------------------
# 11. CONSIGNMENT INVENTORY TRACKING
#     Stock a business sells on behalf of a third-party vendor, paying
#     the vendor their cut only once each unit actually sells.
# ---------------------------------------------------------------

class ConsignmentVendor(db.Model):
    __tablename__  = "consignment_vendors"
    id             = db.Column(db.Integer, primary_key=True)
    owner_user_id  = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    name           = db.Column(db.String(160), nullable=False)
    contact_phone  = db.Column(db.String(64), nullable=True)
    contact_email  = db.Column(db.String(160), nullable=True)
    commission_pct = db.Column(db.Float, nullable=False, default=30.0)  # the business's cut, %
    created_at     = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        return {"id": self.id, "name": self.name, "contact_phone": self.contact_phone,
                "contact_email": self.contact_email, "commission_pct": self.commission_pct}


class ConsignmentItem(db.Model):
    __tablename__     = "consignment_items"
    id                = db.Column(db.Integer, primary_key=True)
    owner_user_id     = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    vendor_id         = db.Column(db.Integer, db.ForeignKey("consignment_vendors.id"), nullable=False, index=True)
    item_id           = db.Column(db.Integer, db.ForeignKey("inventory_items.id"), nullable=True)
    description       = db.Column(db.String(200), nullable=False)
    unit_price        = db.Column(db.Float, nullable=False, default=0)
    quantity_received = db.Column(db.Float, nullable=False, default=0)
    quantity_sold      = db.Column(db.Float, nullable=False, default=0)
    paid_out_amount    = db.Column(db.Float, nullable=False, default=0)
    created_at         = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        vendor = ConsignmentVendor.query.get(self.vendor_id)
        commission_pct = vendor.commission_pct if vendor else 30.0
        gross = self.quantity_sold * self.unit_price
        vendor_owed = round(gross * (1 - commission_pct / 100.0) - self.paid_out_amount, 2)
        return {"id": self.id, "vendor_id": self.vendor_id, "vendor_name": vendor.name if vendor else None,
                "item_id": self.item_id, "description": self.description, "unit_price": self.unit_price,
                "quantity_received": self.quantity_received, "quantity_sold": self.quantity_sold,
                "quantity_on_hand": round(self.quantity_received - self.quantity_sold, 2),
                "paid_out_amount": self.paid_out_amount, "vendor_owed": max(vendor_owed, 0)}


