@app.route("/api/retail/consignment/items", methods=["POST"])
@csrf.exempt
def retail_consignment_item_create():
    """Receiving stock from a vendor. If item_id points at a real
    InventoryItem, that item's quantity is bumped too so the regular
    Inventory panel reflects it; otherwise it's tracked here only."""
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    vendor = ConsignmentVendor.query.filter_by(id=data.get("vendor_id"), owner_user_id=user["id"]).first()
    if not vendor: return jsonify({"error": "Vendor not found."}), 404
    desc = (data.get("description") or "").strip()
    if not desc: return jsonify({"error": "Description is required."}), 400
    try:
        qty = float(data.get("quantity_received", 0))
        price = float(data.get("unit_price", 0))
        if qty <= 0: raise ValueError
    except (TypeError, ValueError):
        return jsonify({"error": "quantity_received must be positive and unit_price must be a number."}), 400
    item_id = data.get("item_id")
    linked = InventoryItem.query.filter_by(id=item_id, user_id=user["id"]).first() if item_id else None
    row = ConsignmentItem(owner_user_id=user["id"], vendor_id=vendor.id, item_id=(linked.id if linked else None),
                           description=desc, unit_price=price, quantity_received=qty)
    db.session.add(row)
    if linked:
        linked.quantity = (linked.quantity or 0) + qty
    db.session.commit()
    return jsonify({"ok": True, "item": row.to_dict()}), 201


