@app.route("/api/retail/consignment/items/<int:item_id>/record-sale", methods=["POST"])
@csrf.exempt
def retail_consignment_record_sale(item_id):
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    row = ConsignmentItem.query.filter_by(id=item_id, owner_user_id=user["id"]).first()
    if not row: return jsonify({"error": "Consignment item not found."}), 404
    data = request.get_json(silent=True) or {}
    try:
        qty = float(data.get("quantity", 0))
        if qty <= 0: raise ValueError
    except (TypeError, ValueError):
        return jsonify({"error": "quantity must be a positive number."}), 400
    on_hand = row.quantity_received - row.quantity_sold
    if qty > on_hand:
        return jsonify({"error": f"Only {on_hand} on hand."}), 400
    row.quantity_sold += qty
    if row.item_id:
        linked = InventoryItem.query.get(row.item_id)
        if linked: linked.quantity = max((linked.quantity or 0) - qty, 0)
    db.session.commit()
    return jsonify({"ok": True, "item": row.to_dict()}), 200


@app.route("/api/retail/consignment/vendors/<int:vendor_id>/settle", methods=["POST"])
@csrf.exempt
def retail_consignment_settle(vendor_id):
    """Marks everything currently owed to this vendor as paid out."""
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    vendor = ConsignmentVendor.query.filter_by(id=vendor_id, owner_user_id=user["id"]).first()
    if not vendor: return jsonify({"error": "Vendor not found."}), 404
    rows = ConsignmentItem.query.filter_by(owner_user_id=user["id"], vendor_id=vendor.id).all()
    total_paid = 0.0
    for r in rows:
        d = r.to_dict()
        if d["vendor_owed"] > 0:
            r.paid_out_amount += d["vendor_owed"]
            total_paid += d["vendor_owed"]
    db.session.commit()
    return jsonify({"ok": True, "paid_out": round(total_paid, 2)}), 200


# ---------------------------------------------------------------
# 12. EXTEND STORE-CREDIT WALLET WITH GIFTING BETWEEN CUSTOMERS
#     Reuses StoreCreditAccount/StoreCreditTransaction (Stage 328) rather
#     than a parallel ledger — a gift is just a spend on one account and
#     a grant on another, both logged with new reason codes.
# ---------------------------------------------------------------

@app.route("/api/retail/store-credit/wallet", methods=["GET"])
def retail_store_credit_wallet():
    user, err = _erp_user_or_401()
    if err: return err
    account = _get_or_create_store_credit_account(user["id"])
    tx = StoreCreditTransaction.query.filter_by(user_id=user["id"]).order_by(StoreCreditTransaction.created_at.desc()).limit(50).all()
    return jsonify({"balance": account.balance, "currency": account.currency,
                     "transactions": [t.to_dict() for t in tx]}), 200


@app.route("/api/retail/store-credit/gift", methods=["POST"])
@csrf.exempt
def retail_store_credit_gift():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    recipient_email = (data.get("recipient_email") or "").strip().lower()
    if not recipient_email:
        return jsonify({"error": "recipient_email is required."}), 400
    recipient = UserAccount.query.filter(db.func.lower(UserAccount.email) == recipient_email).first()
    if not recipient:
        return jsonify({"error": "No account found with that email."}), 404
    if recipient.id == user["id"]:
        return jsonify({"error": "You can't gift store credit to yourself."}), 400
    try:
        amount = round(float(data.get("amount")), 2)
        if amount <= 0: raise ValueError
    except (TypeError, ValueError):
        return jsonify({"error": "amount must be a positive number."}), 400
    account = _get_or_create_store_credit_account(user["id"])
    if account.balance < amount:
        return jsonify({"error": f"Insufficient balance. You have {account.balance}."}), 400
    note = (data.get("note") or "").strip()[:100]
    spent = _spend_store_credit(user["id"], amount, "gift_sent", reference=f"to:{recipient.email}" + (f" ({note})" if note else ""))
    if spent < amount:
        db.session.rollback()
        return jsonify({"error": "Insufficient balance."}), 400
    _grant_store_credit(recipient.id, amount, "gift_received", reference=f"from:{user['email']}" + (f" ({note})" if note else ""))
    db.session.commit()
    try:
        notify_user(recipient.id, "store_credit", "You received a store-credit gift",
                     body=f"{user.get('name') or user['email']} sent you {amount} in store credit.")
    except Exception:
        pass
    return jsonify({"ok": True, "new_balance": _get_or_create_store_credit_account(user["id"]).balance}), 200


# ---------------------------------------------------------------
# 13. DELIVERY-ZONE / FEE CALCULATOR BY POSTCODE
#     Zones are matched by postcode PREFIX (longest match wins) so one
#     zone can cover "1000*" while a narrower one overrides "10001" with
#     its own fee — same idea as shipping-carrier zone tables.
# ---------------------------------------------------------------

class DeliveryZone(db.Model):
    __tablename__       = "delivery_zones"
    id                  = db.Column(db.Integer, primary_key=True)
    owner_user_id       = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    name                = db.Column(db.String(160), nullable=False)
    postcode_prefixes   = db.Column(db.Text, nullable=False)  # JSON list of strings
    fee                 = db.Column(db.Float, nullable=False, default=0)
    currency            = db.Column(db.String(8), nullable=False, default="USD")
    free_over_amount    = db.Column(db.Float, nullable=True)
    eta_days            = db.Column(db.Integer, nullable=True)
    created_at          = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        return {"id": self.id, "name": self.name, "postcode_prefixes": json.loads(self.postcode_prefixes or "[]"),
                "fee": self.fee, "currency": self.currency, "free_over_amount": self.free_over_amount,
                "eta_days": self.eta_days}


@app.route("/api/retail/delivery-zones", methods=["POST"])
@csrf.exempt
def retail_delivery_zone_create():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    name = (data.get("name") or "").strip()
    prefixes = data.get("postcode_prefixes") or []
    if isinstance(prefixes, str):
        prefixes = [p.strip() for p in prefixes.split(",") if p.strip()]
    if not name or not prefixes:
        return jsonify({"error": "name and at least one postcode prefix are required."}), 400
    try:
        fee = float(data.get("fee", 0))
    except (TypeError, ValueError):
        return jsonify({"error": "fee must be a number."}), 400
    row = DeliveryZone(owner_user_id=user["id"], name=name, postcode_prefixes=json.dumps(prefixes),
                        fee=fee, currency=data.get("currency") or "USD",
                        free_over_amount=(float(data["free_over_amount"]) if data.get("free_over_amount") not in (None, "") else None),
                        eta_days=(int(data["eta_days"]) if data.get("eta_days") not in (None, "") else None))
    db.session.add(row); db.session.commit()
    return jsonify({"ok": True, "zone": row.to_dict()}), 201


