@app.route("/api/retail/delivery-fee", methods=["GET"])
def retail_delivery_fee_lookup():
    user, err = _erp_user_or_401()
    if err: return err
    postcode = (request.args.get("postcode") or "").strip()
    if not postcode:
        return jsonify({"error": "postcode is required."}), 400
    try:
        order_total = float(request.args.get("order_total", 0))
    except (TypeError, ValueError):
        order_total = 0.0
    zones = DeliveryZone.query.filter_by(owner_user_id=user["id"]).all()
    best, best_len = None, -1
    for z in zones:
        for prefix in json.loads(z.postcode_prefixes or "[]"):
            if postcode.startswith(prefix) and len(prefix) > best_len:
                best, best_len = z, len(prefix)
    if not best:
        return jsonify({"matched": False, "message": "No delivery zone configured for this postcode yet."}), 200
    fee = best.fee
    free = best.free_over_amount is not None and order_total >= best.free_over_amount
    return jsonify({"matched": True, "zone": best.to_dict(), "fee": (0 if free else fee),
                     "free_delivery_applied": free, "eta_days": best.eta_days}), 200


# ---------------------------------------------------------------
# 14. SHELF / PLANOGRAM PHOTO COMPLIANCE CHECKER
#     A manager uploads a reference planogram photo once; each shelf-walk
#     photo is compared against it. If the business has a Claude key on
#     file (BYOK or platform), that comparison is a real vision call;
#     otherwise the check is honestly queued for manual review instead of
#     faking a score.
# ---------------------------------------------------------------

class PlanogramTemplate(db.Model):
    __tablename__       = "planogram_templates"
    id                  = db.Column(db.Integer, primary_key=True)
    owner_user_id       = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    name                = db.Column(db.String(160), nullable=False)
    reference_image_url = db.Column(db.String(500), nullable=False)
    notes               = db.Column(db.String(500), nullable=True)
    created_at          = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        return {"id": self.id, "name": self.name, "reference_image_url": self.reference_image_url,
                "notes": self.notes}


class PlanogramCheck(db.Model):
    __tablename__  = "planogram_checks"
    id             = db.Column(db.Integer, primary_key=True)
    owner_user_id  = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    template_id    = db.Column(db.Integer, db.ForeignKey("planogram_templates.id"), nullable=False, index=True)
    photo_url      = db.Column(db.String(500), nullable=False)
    status         = db.Column(db.String(20), nullable=False, default="pending_manual")  # ai_reviewed, pending_manual
    ai_score       = db.Column(db.Integer, nullable=True)
    ai_notes       = db.Column(db.Text, nullable=True)
    created_at     = db.Column(db.DateTime, default=datetime.utcnow, index=True)

    def to_dict(self):
        return {"id": self.id, "template_id": self.template_id, "photo_url": self.photo_url,
                "status": self.status, "ai_score": self.ai_score, "ai_notes": self.ai_notes,
                "created_at": self.created_at.isoformat() if self.created_at else None}


def _planogram_ai_compare(user_id, reference_url, photo_url, notes):
    """Returns (score 0-100 or None, notes text or None). None, None means
    no AI provider was available — caller leaves the check as
    pending_manual rather than inventing a score."""
    api_key = get_effective_credential(user_id, "claude", "api_key")
    client = None
    try:
        client = anthropic.Anthropic(api_key=api_key) if api_key else anthropic_client
    except Exception:
        client = anthropic_client
    if not client:
        return None, None
    try:
        ref_bytes = requests.get(reference_url, timeout=15).content
        photo_bytes = requests.get(photo_url, timeout=15).content
        response = client.messages.create(
            model=CLAUDE_MODELS[0], max_tokens=500,
            messages=[{"role": "user", "content": [
                {"type": "text", "text": "This first image is the reference planogram — how this shelf should be stocked and arranged:"},
                {"type": "image", "source": {"type": "base64", "media_type": "image/jpeg", "data": base64.b64encode(ref_bytes).decode()}},
                {"type": "text", "text": "This second image is an actual photo of the shelf taken just now:"},
                {"type": "image", "source": {"type": "base64", "media_type": "image/jpeg", "data": base64.b64encode(photo_bytes).decode()}},
                {"type": "text", "text": ("Extra context from the store: " + notes if notes else "") +
                 "\n\nCompare the actual shelf photo to the reference planogram. Reply with just a number "
                 "0-100 on the first line (compliance score, 100 = perfect match), then on the following "
                 "lines a short bullet list of specific discrepancies (missing products, wrong facing, "
                 "out of stock, wrong shelf position). If it matches well, say so briefly."}
            ]}],
        )
        text = response.content[0].text.strip()
        first_line = text.splitlines()[0].strip()
        digits = "".join(ch for ch in first_line if ch.isdigit())
        score = max(0, min(100, int(digits))) if digits else None
        return score, text
    except Exception as e:
        logging.error(f"Planogram AI compare failed: {e}")
        return None, None


@app.route("/api/retail/planogram/templates", methods=["POST"])
@csrf.exempt
def retail_planogram_template_create():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    name = (request.form.get("name") or "").strip()
