    image_url = None
    if "reference_image" in request.files and request.files["reference_image"].filename:
        image_url = _upload_to_cloudinary(file_bytes=request.files["reference_image"].read(),
                                           resource_type="image", folder="connect it/planogram")
    elif (request.form.get("reference_image_url") or "").strip():
        image_url = _upload_to_cloudinary(file_url=request.form.get("reference_image_url").strip(),
                                           resource_type="image", folder="connect it/planogram")
    if not image_url:
        return jsonify({"error": "A reference photo (file or URL) is required."}), 400
    row = PlanogramTemplate(owner_user_id=user["id"], name=name, reference_image_url=image_url,
                             notes=(request.form.get("notes") or "").strip() or None)
    db.session.add(row); db.session.commit()
