@app.route("/api/retail/planogram/checks", methods=["POST"])
@csrf.exempt
def retail_planogram_check_create():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    template = PlanogramTemplate.query.filter_by(id=request.form.get("template_id"), owner_user_id=user["id"]).first()
    if not template: return jsonify({"error": "Template not found."}), 404
    photo_url = None
    if "photo" in request.files and request.files["photo"].filename:
        photo_url = _upload_to_cloudinary(file_bytes=request.files["photo"].read(),
                                           resource_type="image", folder="connect it/planogram")
    elif (request.form.get("photo_url") or "").strip():
        photo_url = _upload_to_cloudinary(file_url=request.form.get("photo_url").strip(),
                                           resource_type="image", folder="connect it/planogram")
    if not photo_url:
        return jsonify({"error": "A shelf photo (file or URL) is required."}), 400
    score, notes = _planogram_ai_compare(user["id"], template.reference_image_url, photo_url, template.notes)
    row = PlanogramCheck(owner_user_id=user["id"], template_id=template.id, photo_url=photo_url,
                          status=("ai_reviewed" if score is not None else "pending_manual"),
                          ai_score=score, ai_notes=notes)
    db.session.add(row); db.session.commit()
    return jsonify({"ok": True, "check": row.to_dict()}), 201


