# ---------------------------------------------------------------
# 15. AGE-VERIFICATION WORKFLOW FOR RESTRICTED PRODUCTS
#     A seller flags a listing as age-restricted with a minimum age.
#     A buyer self-attests their date of birth (and can optionally attach
#     an ID photo); anyone under the stated minimum is rejected
#     immediately, everyone else is either auto-approved (self-attestation
#     only) or queued for the seller's manual review (if an ID photo was
#     required/attached) — same manual-review honesty as KYCVerification
#     above, never an automated identity check.
# ---------------------------------------------------------------

class AgeVerificationRecord(db.Model):
    __tablename__      = "age_verification_records"
    id                 = db.Column(db.Integer, primary_key=True)
    owner_user_id      = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)  # seller
    buyer_id           = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    order_id           = db.Column(db.Integer, db.ForeignKey("product_orders.id"), nullable=True, index=True)
    declared_birthdate = db.Column(db.Date, nullable=False)
    id_document_url    = db.Column(db.String(500), nullable=True)
    required_min_age   = db.Column(db.Integer, nullable=False, default=18)
    status             = db.Column(db.String(20), nullable=False, default="pending")  # approved, pending, rejected
    reviewer_notes     = db.Column(db.String(300), nullable=True)
    created_at         = db.Column(db.DateTime, default=datetime.utcnow, index=True)
    reviewed_at        = db.Column(db.DateTime, nullable=True)

    def to_dict(self):
        return {"id": self.id, "buyer_id": self.buyer_id, "order_id": self.order_id,
                "required_min_age": self.required_min_age, "status": self.status,
                "id_document_url": self.id_document_url, "reviewer_notes": self.reviewer_notes,
                "created_at": self.created_at.isoformat() if self.created_at else None}


def _age_from_birthdate(bdate):
    today = date.today()
    return today.year - bdate.year - ((today.month, today.day) < (bdate.month, bdate.day))


@app.route("/api/retail/products/<int:product_id>/age-restriction", methods=["POST"])
@csrf.exempt
def retail_product_age_restriction_set(product_id):
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    product = Product.query.filter_by(id=product_id, seller_id=user["id"]).first()
    if not product: return jsonify({"error": "Product not found."}), 404
    data = request.get_json(silent=True) or {}
    product.age_restricted = bool(data.get("age_restricted", True))
    if product.age_restricted:
        try:
            product.min_age = int(data.get("min_age", 18) or 18)
        except (TypeError, ValueError):
            product.min_age = 18
    db.session.commit()
    return jsonify({"ok": True, "age_restricted": product.age_restricted, "min_age": product.min_age}), 200


@app.route("/api/retail/age-verification", methods=["POST"])
@csrf.exempt
def retail_age_verification_submit():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    order = ProductOrder.query.filter_by(id=request.form.get("order_id"), buyer_id=user["id"]).first() \
        if request.form.get("order_id") else None
    seller_id = order.seller_id if order else request.form.get("seller_id")
    if not seller_id:
        return jsonify({"error": "order_id or seller_id is required."}), 400
    dob_str = (request.form.get("declared_birthdate") or "").strip()
    try:
        bdate = datetime.strptime(dob_str, "%Y-%m-%d").date()
    except ValueError:
        return jsonify({"error": "declared_birthdate must be YYYY-MM-DD."}), 400
    min_age = 18
    if order and order.product_id:
        p = Product.query.get(order.product_id)
        if p and getattr(p, "age_restricted", False):
            min_age = p.min_age or 18
    age = _age_from_birthdate(bdate)
    if age < min_age:
        row = AgeVerificationRecord(owner_user_id=seller_id, buyer_id=user["id"], order_id=(order.id if order else None),
                                     declared_birthdate=bdate, required_min_age=min_age, status="rejected",
                                     reviewer_notes="Declared date of birth is under the required minimum age.")
        db.session.add(row); db.session.commit()
        return jsonify({"ok": True, "verification": row.to_dict()}), 200
    id_url = None
    if "id_document" in request.files and request.files["id_document"].filename:
        id_url = _upload_to_cloudinary(file_bytes=request.files["id_document"].read(),
                                        resource_type="image", folder="connect it/age_verification")
    status = "pending" if id_url else "approved"
    row = AgeVerificationRecord(owner_user_id=seller_id, buyer_id=user["id"], order_id=(order.id if order else None),
                                 declared_birthdate=bdate, id_document_url=id_url,
                                 required_min_age=min_age, status=status)
    db.session.add(row); db.session.commit()
    return jsonify({"ok": True, "verification": row.to_dict()}), 200 if status == "approved" else 201


@app.route("/api/retail/age-verification", methods=["GET"])
def retail_age_verification_list():
    user, err = _erp_user_or_401()
    if err: return err
    mine_as_seller = AgeVerificationRecord.query.filter_by(owner_user_id=user["id"])
    order_id = request.args.get("order_id")
    if order_id: mine_as_seller = mine_as_seller.filter_by(order_id=order_id)
    rows = mine_as_seller.order_by(AgeVerificationRecord.created_at.desc()).limit(100).all()
    return jsonify({"verifications": [r.to_dict() for r in rows]}), 200


@app.route("/api/retail/age-verification/<int:record_id>/review", methods=["POST"])
@csrf.exempt
def retail_age_verification_review(record_id):
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    row = AgeVerificationRecord.query.filter_by(id=record_id, owner_user_id=user["id"]).first()
    if not row: return jsonify({"error": "Verification record not found."}), 404
    data = request.get_json(silent=True) or {}
    status = data.get("status")
    if status not in ("approved", "rejected"):
        return jsonify({"error": "status must be 'approved' or 'rejected'."}), 400
    row.status = status
    row.reviewer_notes = (data.get("notes") or "").strip()[:300] or row.reviewer_notes
    row.reviewed_at = datetime.utcnow()
    db.session.commit()
    return jsonify({"ok": True, "verification": row.to_dict()}), 200


