# ---------- 501a: MODELS ----------

class MeetingRoom(db.Model):
    """Feature 1 — physical/virtual rooms a business can book against."""
    __tablename__ = "office_meeting_rooms"
    id            = db.Column(db.Integer, primary_key=True)
    owner_user_id = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    name          = db.Column(db.String(120), nullable=False)
    location      = db.Column(db.String(200), nullable=True)
    capacity      = db.Column(db.Integer, nullable=True)
    created_at    = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        return {"id": self.id, "name": self.name, "location": self.location,
                "capacity": self.capacity,
                "created_at": self.created_at.isoformat() if self.created_at else None}


class RoomBooking(db.Model):
    """Feature 1 — a single reservation against a MeetingRoom. Conflict
    resolution happens in the /api/office/rooms/<id>/bookings POST route
    below: any overlapping start/end on the same room is rejected with
    a 409 and the next free slot that day, instead of silently
    double-booking the room."""
    __tablename__ = "office_room_bookings"
    id           = db.Column(db.Integer, primary_key=True)
    room_id      = db.Column(db.Integer, db.ForeignKey("office_meeting_rooms.id"), nullable=False, index=True)
    owner_user_id = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    title        = db.Column(db.String(200), nullable=False)
    organizer    = db.Column(db.String(120), nullable=True)
    attendees    = db.Column(db.String(400), nullable=True)
    start_time   = db.Column(db.DateTime, nullable=False, index=True)
    end_time     = db.Column(db.DateTime, nullable=False)
    created_at   = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        return {"id": self.id, "room_id": self.room_id, "title": self.title,
                "organizer": self.organizer, "attendees": self.attendees,
                "start_time": self.start_time.isoformat() if self.start_time else None,
                "end_time": self.end_time.isoformat() if self.end_time else None,
                "created_at": self.created_at.isoformat() if self.created_at else None}


class DocumentVersion(db.Model):
    """Feature 2 — version history for the existing CollabDocument
    (STAGE 463e). A snapshot is taken every time a document is saved
    (see collab_docs_update, which now writes one of these rows after
    each PUT) so the viewer below can show who changed what and when,
    and restore an earlier version on demand."""
    __tablename__ = "office_document_versions"
    id            = db.Column(db.Integer, primary_key=True)
    document_id   = db.Column(db.Integer, db.ForeignKey("collab_documents.id"), nullable=False, index=True)
    version_number = db.Column(db.Integer, nullable=False, default=1)
    content       = db.Column(db.Text, nullable=True, default="")
    editor        = db.Column(db.String(120), nullable=True)
    created_at    = db.Column(db.DateTime, default=datetime.utcnow, index=True)

    def to_dict(self, with_content=True):
        out = {"id": self.id, "document_id": self.document_id,
               "version_number": self.version_number, "editor": self.editor,
               "created_at": self.created_at.isoformat() if self.created_at else None}
        if with_content:
            out["content"] = self.content or ""
        return out


