class OnboardingChecklist(db.Model):
    """Feature 6 — employee onboarding automation. Ties to the existing
    ErpEmployee roster rather than a new employee table; creating a
    checklist auto-generates a standard set of OnboardingTask rows
    (see _office_default_onboarding_tasks below) instead of the admin
    having to type them out every time."""
    __tablename__ = "office_onboarding_checklists"
    id             = db.Column(db.Integer, primary_key=True)
    owner_user_id  = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    employee_id    = db.Column(db.Integer, db.ForeignKey("erp_employees.id"), nullable=True)
    employee_name  = db.Column(db.String(160), nullable=False)
    start_date     = db.Column(db.Date, nullable=True)
    created_at     = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self, with_tasks=False):
        out = {"id": self.id, "employee_id": self.employee_id, "employee_name": self.employee_name,
               "start_date": self.start_date.isoformat() if self.start_date else None,
               "created_at": self.created_at.isoformat() if self.created_at else None}
        if with_tasks:
            tasks = OnboardingTask.query.filter_by(checklist_id=self.id).order_by(OnboardingTask.due_offset_days).all()
            task_list = [t.to_dict() for t in tasks]
            out["tasks"] = task_list
            out["progress_pct"] = round(100 * sum(1 for t in task_list if t["completed"]) / len(task_list), 1) if task_list else 0
        return out


class OnboardingTask(db.Model):
    __tablename__ = "office_onboarding_tasks"
    id              = db.Column(db.Integer, primary_key=True)
    checklist_id    = db.Column(db.Integer, db.ForeignKey("office_onboarding_checklists.id"), nullable=False, index=True)
