    completed       = db.Column(db.Boolean, nullable=False, default=False)
    completed_at    = db.Column(db.DateTime, nullable=True)

    def to_dict(self):
        return {"id": self.id, "checklist_id": self.checklist_id, "title": self.title,
                "category": self.category, "assignee": self.assignee,
                "due_offset_days": self.due_offset_days, "completed": self.completed,
                "completed_at": self.completed_at.isoformat() if self.completed_at else None}


