# ---------- 501b: SHARED HELPERS ----------

def _office_default_onboarding_tasks():
    """Standard new-hire checklist. Category groups them in the UI;
    due_offset_days is relative to the employee's start_date."""
    return [
        ("Send offer letter & contract for signature", "paperwork", -7),
        ("Collect tax / statutory forms", "paperwork", -3),
        ("Create company email & accounts", "it", -2),
        ("Provision laptop & equipment", "it", -1),
        ("Add to payroll", "hr", 0),
        ("Office tour / desk setup", "logistics", 0),
        ("Team introduction meeting", "logistics", 0),
        ("Assign onboarding buddy", "hr", 0),
        ("Company policies & handbook walkthrough", "hr", 1),
        ("30-day check-in", "hr", 30),
    ]


def _office_send_email(to_email, subject, html_body):
    """Best-effort send over the existing SMTP config. Returns True/False
    and never raises — a single bad address should not abort a broadcast
    to the rest of the company."""
    if not (SMTP_USER and SMTP_PASS and to_email):
        return False
    try:
        msg = MIMEMultipart("alternative")
        msg["Subject"] = subject
        msg["From"] = SMTP_FROM
        msg["To"] = to_email
        msg.attach(MIMEText(html_body, "html"))
        with smtplib.SMTP(SMTP_HOST, SMTP_PORT, timeout=15) as server:
            server.ehlo()
            server.starttls()
            server.login(SMTP_USER, SMTP_PASS)
            server.sendmail(SMTP_USER, to_email, msg.as_string())
        return True
    except Exception as e:
        logging.error(f"[ANNOUNCEMENT EMAIL ERROR] {to_email}: {e}")
        return False


