@app.route("/api/office/bookings", methods=["POST"])
@csrf.exempt
def office_bookings_create():
    """Conflict resolution: rejects any booking that overlaps an
    existing one on the same room with a 409 and a suggested next
    free slot of the same duration later that day, instead of
    silently double-booking the room."""
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    room_id = data.get("room_id")
    title = (data.get("title") or "").strip()
    room = MeetingRoom.query.filter_by(id=room_id, owner_user_id=user["id"]).first() if room_id else None
    if not room:
        return jsonify({"error": "A valid room_id is required."}), 400
    if not title:
        return jsonify({"error": "Booking title is required."}), 400
    start_time = _erp_parse_datetime(data.get("start_time"))
    end_time = _erp_parse_datetime(data.get("end_time"))
    if not start_time or not end_time or end_time <= start_time:
        return jsonify({"error": "start_time and end_time are required and end_time must be after start_time."}), 400

    existing = RoomBooking.query.filter_by(room_id=room.id).order_by(RoomBooking.start_time.asc()).all()
    conflicts = [b for b in existing if b.start_time < end_time and b.end_time > start_time]
    if conflicts:
        duration = end_time - start_time
        day_end = start_time.replace(hour=18, minute=0, second=0, microsecond=0)
        candidate = start_time
        suggested = None
        for b in sorted(existing, key=lambda x: x.start_time):
            if b.end_time > candidate and b.start_time < candidate + duration:
                candidate = b.end_time
        if candidate + duration <= day_end:
            suggested = candidate
        return jsonify({
            "error": "This room is already booked for part of that time.",
            "conflicts": [c.to_dict() for c in conflicts],
            "suggested_start_time": suggested.isoformat() if suggested else None,
            "suggested_end_time": (suggested + duration).isoformat() if suggested else None,
        }), 409

    booking = RoomBooking(room_id=room.id, owner_user_id=user["id"], title=title,
                           organizer=(data.get("organizer") or "").strip() or None,
                           attendees=(data.get("attendees") or "").strip() or None,
                           start_time=start_time, end_time=end_time)
    db.session.add(booking)
    db.session.commit()
    return jsonify({"ok": True, "booking": booking.to_dict()}), 201


