@app.route("/api/collab-docs/<int:doc_id>/versions/<int:version_id>/restore", methods=["POST"])
@csrf.exempt
def office_doc_version_restore(doc_id, version_id):
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    doc = CollabDocument.query.filter_by(id=doc_id, owner_user_id=user["id"]).first()
    if not doc: return jsonify({"error": "Document not found."}), 404
    version = DocumentVersion.query.filter_by(id=version_id, document_id=doc.id).first()
    if not version: return jsonify({"error": "Version not found."}), 404
    doc.content = version.content
    doc.last_editor = f"Restored from v{version.version_number}"
    db.session.commit()
    latest = DocumentVersion.query.filter_by(document_id=doc.id).order_by(DocumentVersion.version_number.desc()).first()
    next_num = (latest.version_number + 1) if latest else 1
    db.session.add(DocumentVersion(document_id=doc.id, version_number=next_num, content=doc.content,
                                    editor=doc.last_editor))
    db.session.commit()
    _collab_emit("doc_updated", {"doc_id": doc.id, "content": doc.content, "editor": doc.last_editor}, doc.id)
    return jsonify({"ok": True, "document": doc.to_dict()}), 200


