@app.route("/api/office/onboarding", methods=["POST"])
@csrf.exempt
def office_onboarding_create():
    """Auto-generates the standard new-hire checklist (see
    _office_default_onboarding_tasks) so nobody has to type out the
    same ten tasks for every new employee."""
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    employee_name = (data.get("employee_name") or "").strip()
    if not employee_name:
        return jsonify({"error": "employee_name is required."}), 400
    employee_id = data.get("employee_id")
    if employee_id:
        emp = ErpEmployee.query.filter_by(id=employee_id, owner_user_id=user["id"]).first()
        if not emp:
            employee_id = None
    checklist = OnboardingChecklist(owner_user_id=user["id"], employee_id=employee_id,
                                     employee_name=employee_name,
                                     start_date=_erp_parse_date(data.get("start_date")))
    db.session.add(checklist)
    db.session.flush()
    for title, category, offset in _office_default_onboarding_tasks():
        db.session.add(OnboardingTask(checklist_id=checklist.id, title=title, category=category,
                                       due_offset_days=offset))
    db.session.commit()
    return jsonify({"ok": True, "checklist": checklist.to_dict(with_tasks=True)}), 201


