@app.route("/api/office/announcements", methods=["POST"])
@csrf.exempt
def office_announcements_create():
    """Broadcasts to every ErpEmployee on file with an email address.
    Saved even if sending fails so the announcement isn't lost."""
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    title = (data.get("title") or "").strip()
    body = (data.get("body") or "").strip()
    if not title or not body:
        return jsonify({"error": "title and body are required."}), 400
    announcement = AnnouncementBroadcast(owner_user_id=user["id"], title=title, body=body,
                                 created_by=(data.get("created_by") or "").strip() or None)
    db.session.add(announcement)
    db.session.flush()

    recipients = [e.email for e in ErpEmployee.query.filter_by(owner_user_id=user["id"], status="active").all()
                  if e.email]
    sent_count = 0
    if data.get("send_now", True) and recipients:
        html_body = (
            f"<div style='font-family:sans-serif;max-width:600px;margin:0 auto;'>"
            f"<h2 style='margin-bottom:4px;'>{xml_escape(title)}</h2>"
            f"<div style='white-space:pre-wrap;color:#334155;'>{xml_escape(body)}</div>"
            f"</div>"
        )
        for addr in recipients:
            if _office_send_email(addr, title, html_body):
                sent_count += 1
        announcement.sent_at = datetime.utcnow()

    announcement.recipient_count = sent_count
    db.session.commit()
    return jsonify({"ok": True, "announcement": announcement.to_dict(),
                     "recipients_attempted": len(recipients)}), 201


