# STAGE 502: CONTAINER TRACKING (MILESTONE EVENTS)
# No single free/universal carrier tracking API exists across Maersk,
# MSC, CMA CGM etc. — most require paid, carrier-specific credentials.
# Rather than fake a live feed, this logs the real milestone events a
# freight forwarder or ops team already receives (by email/portal/
# phone) against a container number, optionally tied to an existing
# FreightShipment (Stage from the freight module above) so the two
# don't duplicate each other. A BYOK carrier API key can be layered on
# top of this later without changing the shape of the data.
# ════════════════════════════════════════════════════════════

CONTAINER_MILESTONES = [
    "booked", "gate_in_origin", "loaded_on_vessel", "vessel_departed",
    "vessel_arrived", "discharged", "gate_out_destination", "empty_returned",
]


class ContainerTrackingEvent(db.Model):
    __tablename__  = "container_tracking_events"
    id             = db.Column(db.Integer,  primary_key=True)
    owner_user_id  = db.Column(db.Integer,  db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    shipment_id    = db.Column(db.Integer,  db.ForeignKey("freight_shipments.id"), nullable=True, index=True)
    container_number = db.Column(db.String(24), nullable=False, index=True)
    milestone      = db.Column(db.String(30), nullable=False)
    location       = db.Column(db.String(160), nullable=True)
    event_time     = db.Column(db.DateTime, nullable=False, default=datetime.utcnow)
    notes          = db.Column(db.String(300), nullable=True)
    created_at     = db.Column(db.DateTime, default=datetime.utcnow, index=True)

    def to_dict(self):
        return {"id": self.id, "shipment_id": self.shipment_id, "container_number": self.container_number,
                "milestone": self.milestone, "location": self.location,
                "event_time": self.event_time.isoformat() if self.event_time else None,
                "notes": self.notes, "created_at": self.created_at.isoformat() if self.created_at else None}


@app.route("/api/logistics/container-events", methods=["POST"])
@csrf.exempt
def container_event_create():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user: return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    container_number = (data.get("container_number") or "").strip().upper()
    milestone = (data.get("milestone") or "").strip().lower()
    if not container_number:
        return jsonify({"error": "container_number is required."}), 400
    if milestone not in CONTAINER_MILESTONES:
        return jsonify({"error": f"milestone must be one of: {', '.join(CONTAINER_MILESTONES)}"}), 400
    shipment_id = data.get("shipment_id")
    if shipment_id:
        ship = FreightShipment.query.filter_by(id=shipment_id, seller_id=user["id"]).first()
        if not ship:
            shipment_id = None
    event_time = datetime.utcnow()
    if data.get("event_time"):
        try:
            event_time = datetime.fromisoformat(data["event_time"])
        except (TypeError, ValueError):
            pass
    try:
        row = ContainerTrackingEvent(owner_user_id=user["id"], shipment_id=shipment_id or None,
                                      container_number=container_number[:24], milestone=milestone,
                                      location=(data.get("location") or "").strip()[:160] or None,
                                      event_time=event_time, notes=(data.get("notes") or "").strip()[:300] or None)
        db.session.add(row); db.session.commit()
    except Exception as e:
        db.session.rollback(); logging.error(f"[CONTAINER EVENT CREATE] {e}")
        return jsonify({"error": "Could not save the event."}), 500
    return jsonify({"event": row.to_dict()}), 201


@app.route("/api/logistics/container-events/<container_number>", methods=["GET"])
def container_event_timeline(container_number):
    user = _get_current_user()
    if not user: return jsonify({"error": "Login required."}), 401
    rows = (ContainerTrackingEvent.query
            .filter_by(owner_user_id=user["id"], container_number=container_number.strip().upper())
            .order_by(ContainerTrackingEvent.event_time.asc()).all())
    latest_milestone = rows[-1].milestone if rows else None
    return jsonify({"container_number": container_number.upper(), "timeline": [r.to_dict() for r in rows],
                     "current_status": latest_milestone}), 200


# ════════════════════════════════════════════════════════════
# STAGE 503: BERTH / DOCK SCHEDULING
# Real conflict-checked booking of a limited physical resource (a
# named berth/dock/bay) against a time window — same double-booking
# guard shape as the existing curbside-pickup-slot feature.
# ════════════════════════════════════════════════════════════

class BerthBooking(db.Model):
    __tablename__  = "berth_bookings"
    id             = db.Column(db.Integer,  primary_key=True)
    owner_user_id  = db.Column(db.Integer,  db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    berth_label    = db.Column(db.String(80), nullable=False)
    vessel_or_truck_name = db.Column(db.String(160), nullable=False)
    cargo_type     = db.Column(db.String(120), nullable=True)
    scheduled_start = db.Column(db.DateTime, nullable=False, index=True)
    scheduled_end  = db.Column(db.DateTime, nullable=False)
    status         = db.Column(db.String(20), nullable=False, default="scheduled")  # scheduled, arrived, departed, cancelled
    created_at     = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        return {"id": self.id, "berth_label": self.berth_label, "vessel_or_truck_name": self.vessel_or_truck_name,
                "cargo_type": self.cargo_type,
                "scheduled_start": self.scheduled_start.isoformat() if self.scheduled_start else None,
                "scheduled_end": self.scheduled_end.isoformat() if self.scheduled_end else None,
                "status": self.status}


@app.route("/api/logistics/berth-bookings", methods=["POST"])
@csrf.exempt
def berth_booking_create():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user: return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    berth_label = (data.get("berth_label") or "").strip()
    vessel = (data.get("vessel_or_truck_name") or "").strip()
    if not berth_label or not vessel:
        return jsonify({"error": "berth_label and vessel_or_truck_name are required."}), 400
    try:
        start = datetime.fromisoformat(data.get("scheduled_start"))
        end = datetime.fromisoformat(data.get("scheduled_end"))
    except (TypeError, ValueError):
        return jsonify({"error": "scheduled_start and scheduled_end must be ISO 8601 datetimes."}), 400
    if end <= start:
        return jsonify({"error": "scheduled_end must be after scheduled_start."}), 400
    overlap = (BerthBooking.query.filter(
        BerthBooking.owner_user_id == user["id"], BerthBooking.berth_label == berth_label[:80],
        BerthBooking.status != "cancelled",
        BerthBooking.scheduled_start < end, BerthBooking.scheduled_end > start).first())
    if overlap:
        return jsonify({"error": f"Berth '{berth_label}' is already booked for part of that window "
                                  f"({overlap.vessel_or_truck_name}, {overlap.scheduled_start.isoformat()}–{overlap.scheduled_end.isoformat()})."}), 409
    try:
        row = BerthBooking(owner_user_id=user["id"], berth_label=berth_label[:80],
                            vessel_or_truck_name=vessel[:160], cargo_type=(data.get("cargo_type") or "").strip()[:120] or None,
                            scheduled_start=start, scheduled_end=end)
        db.session.add(row); db.session.commit()
    except Exception as e:
        db.session.rollback(); logging.error(f"[BERTH BOOKING CREATE] {e}")
        return jsonify({"error": "Could not save the booking."}), 500
    return jsonify({"booking": row.to_dict()}), 201


@app.route("/api/logistics/berth-bookings", methods=["GET"])
def berth_booking_list():
    user = _get_current_user()
    if not user: return jsonify({"error": "Login required."}), 401
    q = BerthBooking.query.filter_by(owner_user_id=user["id"])
    if request.args.get("from"):
        try: q = q.filter(BerthBooking.scheduled_end >= datetime.fromisoformat(request.args["from"]))
        except (TypeError, ValueError): pass
    if request.args.get("to"):
        try: q = q.filter(BerthBooking.scheduled_start <= datetime.fromisoformat(request.args["to"]))
        except (TypeError, ValueError): pass
    rows = q.order_by(BerthBooking.scheduled_start.asc()).limit(300).all()
    return jsonify({"bookings": [r.to_dict() for r in rows]}), 200


@app.route("/api/logistics/berth-bookings/<int:booking_id>/status", methods=["POST"])
@csrf.exempt
def berth_booking_update_status(booking_id):
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user: return jsonify({"error": "Login required."}), 401
    row = BerthBooking.query.filter_by(id=booking_id, owner_user_id=user["id"]).first()
    if not row: return jsonify({"error": "Booking not found."}), 404
    status = (request.get_json(silent=True) or {}).get("status")
    if status not in ("scheduled", "arrived", "departed", "cancelled"):
        return jsonify({"error": "Invalid status."}), 400
    row.status = status
    db.session.commit()
    return jsonify({"booking": row.to_dict()}), 200


# ════════════════════════════════════════════════════════════
# STAGE 504: CUSTOMS DOCUMENT CHECKLIST
# Distinct from Stage 352's Letter-of-Credit document checklist (which
# gates a payment release) — this one gates a shipment clearing customs
# at the border and isn't tied to escrow/payment at all. Standard
# document set below is generic/illustrative; a business can add
# custom document types a specific destination country requires.
# ════════════════════════════════════════════════════════════

CUSTOMS_STANDARD_DOCUMENTS = [
    "commercial_invoice", "packing_list", "certificate_of_origin",
    "bill_of_lading", "import_permit", "customs_declaration", "insurance_certificate",
]


class CustomsChecklist(db.Model):
    __tablename__  = "customs_checklists"
    id             = db.Column(db.Integer,  primary_key=True)
    owner_user_id  = db.Column(db.Integer,  db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    shipment_id    = db.Column(db.Integer,  db.ForeignKey("freight_shipments.id"), nullable=True)
    destination_country = db.Column(db.String(100), nullable=False)
    required_documents  = db.Column(db.Text, nullable=False)  # JSON list
    created_at     = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        required = json.loads(self.required_documents or "[]")
        items = CustomsChecklistDocument.query.filter_by(checklist_id=self.id).all()
        done_types = {i.document_type for i in items if i.status == "complete"}
        outstanding = [d for d in required if d not in done_types]
        return {"id": self.id, "shipment_id": self.shipment_id, "destination_country": self.destination_country,
                "required_documents": required, "items": [i.to_dict() for i in items],
                "outstanding_documents": outstanding, "complete": len(outstanding) == 0,
                "created_at": self.created_at.isoformat() if self.created_at else None}


class CustomsChecklistDocument(db.Model):
    __tablename__  = "customs_checklist_documents"
    id             = db.Column(db.Integer,  primary_key=True)
    checklist_id   = db.Column(db.Integer,  db.ForeignKey("customs_checklists.id"), nullable=False, index=True)
    document_type  = db.Column(db.String(60), nullable=False)
    document_url   = db.Column(db.String(500), nullable=True)
    status         = db.Column(db.String(20), nullable=False, default="pending")  # pending, complete
    updated_at     = db.Column(db.DateTime, default=datetime.utcnow, onupdate=datetime.utcnow)

    def to_dict(self):
        return {"id": self.id, "document_type": self.document_type, "document_url": self.document_url,
                "status": self.status, "updated_at": self.updated_at.isoformat() if self.updated_at else None}


@app.route("/api/logistics/customs-checklists", methods=["POST"])
@csrf.exempt
def customs_checklist_create():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user: return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    dest = (data.get("destination_country") or "").strip()
    if not dest:
        return jsonify({"error": "destination_country is required."}), 400
    custom_docs = data.get("extra_documents") or []
    if isinstance(custom_docs, str):
        custom_docs = [d.strip() for d in custom_docs.split(",") if d.strip()]
    required = CUSTOMS_STANDARD_DOCUMENTS + [d for d in custom_docs if d not in CUSTOMS_STANDARD_DOCUMENTS]
    shipment_id = data.get("shipment_id")
    if shipment_id and not FreightShipment.query.filter_by(id=shipment_id, seller_id=user["id"]).first():
        shipment_id = None
    try:
        checklist = CustomsChecklist(owner_user_id=user["id"], shipment_id=shipment_id or None,
                                      destination_country=dest[:100], required_documents=json.dumps(required))
        db.session.add(checklist); db.session.flush()
        for doc_type in required:
            db.session.add(CustomsChecklistDocument(checklist_id=checklist.id, document_type=doc_type))
        db.session.commit()
    except Exception as e:
        db.session.rollback(); logging.error(f"[CUSTOMS CHECKLIST CREATE] {e}")
        return jsonify({"error": "Could not create the checklist."}), 500
    return jsonify({"checklist": checklist.to_dict()}), 201


@app.route("/api/logistics/customs-checklists", methods=["GET"])
def customs_checklist_list():
    user = _get_current_user()
    if not user: return jsonify({"error": "Login required."}), 401
    rows = (CustomsChecklist.query.filter_by(owner_user_id=user["id"])
            .order_by(CustomsChecklist.created_at.desc()).limit(100).all())
    return jsonify({"checklists": [r.to_dict() for r in rows]}), 200


@app.route("/api/logistics/customs-checklists/<int:checklist_id>/documents/<int:doc_id>", methods=["POST"])
@csrf.exempt
def customs_checklist_document_update(checklist_id, doc_id):
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user: return jsonify({"error": "Login required."}), 401
    checklist = CustomsChecklist.query.filter_by(id=checklist_id, owner_user_id=user["id"]).first()
    if not checklist: return jsonify({"error": "Checklist not found."}), 404
    doc = CustomsChecklistDocument.query.filter_by(id=doc_id, checklist_id=checklist_id).first()
    if not doc: return jsonify({"error": "Document not found."}), 404
    data = request.get_json(silent=True) or {}
    doc.document_url = (data.get("document_url") or doc.document_url or "").strip()[:500] or None
    doc.status = "complete" if (data.get("status") == "complete" or doc.document_url) else "pending"
    db.session.commit()
    return jsonify({"checklist": checklist.to_dict()}), 200


# ════════════════════════════════════════════════════════════
# STAGE 505: DEMURRAGE / DETENTION CALCULATOR
# Standard industry formula: billable_days = max(0, days_since_discharge
# - free_days), charge = billable_days × daily_rate. Live-recomputes
# against today's date until a return_date is logged, then locks to
# the final figure — same "real math on real dates, nothing invented"
# approach as the existing fuel-efficiency and repair-cost calculators.
# ════════════════════════════════════════════════════════════

class DemurrageCalculation(db.Model):
    __tablename__  = "demurrage_calculations"
    id             = db.Column(db.Integer,  primary_key=True)
    owner_user_id  = db.Column(db.Integer,  db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    container_number = db.Column(db.String(24), nullable=False)
    discharge_date = db.Column(db.Date, nullable=False)
    free_days      = db.Column(db.Integer, nullable=False, default=5)
    daily_rate     = db.Column(db.Float,   nullable=False)
    currency       = db.Column(db.String(8), nullable=False, default="USD")
    return_date    = db.Column(db.Date, nullable=True)
    charge_type    = db.Column(db.String(12), nullable=False, default="demurrage")  # demurrage (port) or detention (empty return)
    created_at     = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        end_date = self.return_date or date.today()
        days_used = (end_date - self.discharge_date).days
        billable_days = max(0, days_used - self.free_days)
        charge = round(billable_days * self.daily_rate, 2)
        return {"id": self.id, "container_number": self.container_number, "charge_type": self.charge_type,
                "discharge_date": self.discharge_date.isoformat(), "free_days": self.free_days,
                "daily_rate": self.daily_rate, "currency": self.currency,
                "return_date": self.return_date.isoformat() if self.return_date else None,
                "days_used": days_used, "billable_days": billable_days, "estimated_charge": charge,
                "is_final": self.return_date is not None}


@app.route("/api/logistics/demurrage", methods=["POST"])
@csrf.exempt
def demurrage_create():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user: return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    container_number = (data.get("container_number") or "").strip().upper()
    if not container_number:
        return jsonify({"error": "container_number is required."}), 400
    try:
        discharge_date = datetime.strptime(data.get("discharge_date"), "%Y-%m-%d").date()
        daily_rate = float(data.get("daily_rate"))
    except (TypeError, ValueError):
        return jsonify({"error": "discharge_date (YYYY-MM-DD) and daily_rate (number) are required."}), 400
    charge_type = data.get("charge_type") if data.get("charge_type") in ("demurrage", "detention") else "demurrage"
    return_date = None
    if data.get("return_date"):
        try:
            return_date = datetime.strptime(data["return_date"], "%Y-%m-%d").date()
        except (TypeError, ValueError):
            return jsonify({"error": "return_date must be YYYY-MM-DD."}), 400
    try:
        row = DemurrageCalculation(owner_user_id=user["id"], container_number=container_number[:24],
                                    discharge_date=discharge_date, free_days=int(data.get("free_days", 5) or 5),
                                    daily_rate=daily_rate, currency=(data.get("currency") or "USD"),
                                    return_date=return_date, charge_type=charge_type)
        db.session.add(row); db.session.commit()
    except Exception as e:
        db.session.rollback(); logging.error(f"[DEMURRAGE CREATE] {e}")
        return jsonify({"error": "Could not save the calculation."}), 500
    return jsonify({"calculation": row.to_dict()}), 201


@app.route("/api/logistics/demurrage", methods=["GET"])
def demurrage_list():
    user = _get_current_user()
    if not user: return jsonify({"error": "Login required."}), 401
    rows = (DemurrageCalculation.query.filter_by(owner_user_id=user["id"])
            .order_by(DemurrageCalculation.created_at.desc()).limit(200).all())
    items = [r.to_dict() for r in rows]
    return jsonify({"calculations": items,
                     "total_outstanding": round(sum(i["estimated_charge"] for i in items if not i["is_final"]), 2)}), 200


