@csrf.exempt
def demurrage_mark_returned(calc_id):
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user: return jsonify({"error": "Login required."}), 401
    row = DemurrageCalculation.query.filter_by(id=calc_id, owner_user_id=user["id"]).first()
    if not row: return jsonify({"error": "Calculation not found."}), 404
    data = request.get_json(silent=True) or {}
    try:
        row.return_date = datetime.strptime(data.get("return_date"), "%Y-%m-%d").date() if data.get("return_date") else date.today()
    except (TypeError, ValueError):
        return jsonify({"error": "return_date must be YYYY-MM-DD."}), 400
    db.session.commit()
    return jsonify({"calculation": row.to_dict()}), 200


# ════════════════════════════════════════════════════════════
# STAGE 506: CARGO MANIFEST RECONCILIATION
# A manifest is entered once (expected line items), then reconciled
# against what actually arrived — flags short/over/matched per line so
# discrepancies with a supplier or carrier are backed by a real record
# instead of a memory of what was supposed to show up.
# ════════════════════════════════════════════════════════════

class CargoManifest(db.Model):
    __tablename__  = "cargo_manifests"
    id             = db.Column(db.Integer,  primary_key=True)
    owner_user_id  = db.Column(db.Integer,  db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    shipment_id    = db.Column(db.Integer,  db.ForeignKey("freight_shipments.id"), nullable=True)
    reference      = db.Column(db.String(120), nullable=True)
    created_at     = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        lines = CargoManifestLine.query.filter_by(manifest_id=self.id).all()
        line_dicts = [l.to_dict() for l in lines]
        discrepancies = [l for l in line_dicts if l["discrepancy"] != 0]
        return {"id": self.id, "shipment_id": self.shipment_id, "reference": self.reference,
                "lines": line_dicts, "discrepancy_count": len(discrepancies),
                "fully_reconciled": all(l["received_qty"] is not None for l in line_dicts) and len(discrepancies) == 0,
                "created_at": self.created_at.isoformat() if self.created_at else None}


class CargoManifestLine(db.Model):
    __tablename__  = "cargo_manifest_lines"
    id             = db.Column(db.Integer,  primary_key=True)
    manifest_id    = db.Column(db.Integer,  db.ForeignKey("cargo_manifests.id"), nullable=False, index=True)
    description    = db.Column(db.String(200), nullable=False)
    expected_qty   = db.Column(db.Float, nullable=False)
    received_qty   = db.Column(db.Float, nullable=True)
    note           = db.Column(db.String(300), nullable=True)

    def to_dict(self):
        discrepancy = (self.received_qty - self.expected_qty) if self.received_qty is not None else 0
        return {"id": self.id, "description": self.description, "expected_qty": self.expected_qty,
                "received_qty": self.received_qty, "discrepancy": discrepancy, "note": self.note}


@app.route("/api/logistics/manifests", methods=["POST"])
@csrf.exempt
def cargo_manifest_create():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user: return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    lines = data.get("lines") or []
    if not lines:
        return jsonify({"error": "At least one manifest line is required."}), 400
    shipment_id = data.get("shipment_id")
    if shipment_id and not FreightShipment.query.filter_by(id=shipment_id, seller_id=user["id"]).first():
        shipment_id = None
    try:
        manifest = CargoManifest(owner_user_id=user["id"], shipment_id=shipment_id or None,
                                  reference=(data.get("reference") or "").strip()[:120] or None)
        db.session.add(manifest); db.session.flush()
        for line in lines:
            desc = (line.get("description") or "").strip()
            if not desc:
                continue
            try:
                qty = float(line.get("expected_qty"))
            except (TypeError, ValueError):
                continue
            db.session.add(CargoManifestLine(manifest_id=manifest.id, description=desc[:200], expected_qty=qty))
        db.session.commit()
    except Exception as e:
        db.session.rollback(); logging.error(f"[CARGO MANIFEST CREATE] {e}")
        return jsonify({"error": "Could not create the manifest."}), 500
    return jsonify({"manifest": manifest.to_dict()}), 201


@app.route("/api/logistics/manifests", methods=["GET"])
def cargo_manifest_list():
    user = _get_current_user()
    if not user: return jsonify({"error": "Login required."}), 401
    rows = (CargoManifest.query.filter_by(owner_user_id=user["id"])
            .order_by(CargoManifest.created_at.desc()).limit(100).all())
    return jsonify({"manifests": [r.to_dict() for r in rows]}), 200


@app.route("/api/logistics/manifests/lines/<int:line_id>/receive", methods=["POST"])
@csrf.exempt
def cargo_manifest_line_receive(line_id):
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user: return jsonify({"error": "Login required."}), 401
    line = CargoManifestLine.query.get(line_id)
    if not line: return jsonify({"error": "Line not found."}), 404
    manifest = CargoManifest.query.filter_by(id=line.manifest_id, owner_user_id=user["id"]).first()
    if not manifest: return jsonify({"error": "Not your manifest."}), 403
    data = request.get_json(silent=True) or {}
    try:
        line.received_qty = float(data.get("received_qty"))
    except (TypeError, ValueError):
        return jsonify({"error": "received_qty must be a number."}), 400
    line.note = (data.get("note") or "").strip()[:300] or line.note
    db.session.commit()
    return jsonify({"manifest": manifest.to_dict()}), 200


