# ════════════════════════════════════════════════════════════
# PLUGIN ENGINE — added once, never touched again for new features.
#
# The problem this solves: every feature added to this codebase so
# far meant hand-editing this multi-megabyte file directly, which is
# exactly how naming collisions happen (this file has had several —
# fleet_dispatch_create, retailSwitchTab, an entire duplicate
# "Vehicle & Fleet Diagnostics" build attempt that was caught only by
# manually grepping for the function name before shipping). A plugin
# only has to avoid colliding with itself; the loader catches
# collisions against everything else automatically at startup.
#
# CONTRACT for a backend plugin — a single file dropped in
# plugins/backend/<slug>.py. db, app, jsonify, request, csrf, logging,
# datetime, _get_current_user, and _csrf_ok are already available as
# top-level names inside your plugin file — same as every other stage
# in this file, no imports needed for them:
#
#   bp = Blueprint("myfeature", __name__)
#   MANIFEST = {
#       "slug": "myfeature",              # unique, used for URLs/ids
#       "label": "My Feature",            # shown in the dropdown menu
#       "category": "Business",           # existing or new menu section
#       "description": "One line.",       # shown in the registry
#       "frontend_js": "myfeature.js",    # optional — file in plugins/frontend/
#   }
#
#   class MyThing(db.Model):
#       __tablename__ = "myfeature_things"
#       id = db.Column(db.Integer, primary_key=True)
#       owner_user_id = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False)
#       ...
#
#   @bp.route("/api/plugins/myfeature/things", methods=["GET"])
#   def list_things():
#       user = _get_current_user()
#       if not user: return jsonify({"error": "Login required."}), 401
#       ...
#
# The plugin can define its own db.Model classes at module level same
# as anywhere else in this file — db.create_all() below picks them up.
# A plugin is skipped (not the whole app) if it's missing MANIFEST/bp,
# has a slug that collides with an already-loaded plugin, or throws on
# import — the reason is logged, nothing else breaks.
#
# CONTRACT for the optional frontend file — plugins/frontend/<slug>.js
# — is documented in index.html next to registerPlugin().
# ════════════════════════════════════════════════════════════

import importlib.util
import pathlib
from flask import Blueprint

PLUGIN_REGISTRY = []
_PLUGIN_LOAD_ERRORS = []
_PLUGINS_BACKEND_DIR = pathlib.Path(__file__).parent / "plugins" / "backend"
_PLUGINS_FRONTEND_DIR = pathlib.Path(__file__).parent / "plugins" / "frontend"


def _load_plugins():
    _PLUGINS_BACKEND_DIR.mkdir(parents=True, exist_ok=True)
    _PLUGINS_FRONTEND_DIR.mkdir(parents=True, exist_ok=True)
    known_slugs = set()

    # Every stage in this file already uses app/db/jsonify/request/
    # _get_current_user/_csrf_ok/csrf/datetime as ambient names without
    # re-importing them — plugins get the same thing by having these
    # injected into their module namespace before their code runs, so
    # a plugin file reads exactly like any other stage in this file,
    # not like a package importing across a circular boundary.
    shared_globals = {
        "app": app, "db": db, "jsonify": jsonify, "request": request,
        "csrf": csrf, "logging": logging, "datetime": datetime,
        "_get_current_user": _get_current_user, "_csrf_ok": _csrf_ok,
        "Blueprint": Blueprint,
        # Existing model classes a plugin may need to interoperate with
        # rather than duplicate (e.g. a till-scan plugin earning points
        # against the real LoyaltyProgram tables instead of inventing its
        # own copy). Extend this list as new plugins need to reference
        # more of the existing schema — do not duplicate a table a
        # plugin could instead read/write via the real one here.
        "LoyaltyProgram": LoyaltyProgram, "LoyaltyCustomer": LoyaltyCustomer,
        "LoyaltyTransaction": LoyaltyTransaction,
        "ErpInvoice": ErpInvoice, "ErpInvoiceItem": ErpInvoiceItem,
        "ErpEmployee": ErpEmployee, "ErpCustomer": ErpCustomer,
        "PosSale": PosSale, "PosSaleItem": PosSaleItem, "PosSaleTender": PosSaleTender,
    }

    for f in sorted(_PLUGINS_BACKEND_DIR.glob("*.py")):
        if f.stem.startswith("_"):
            continue
        try:
            spec = importlib.util.spec_from_file_location(f"connectit_plugin_{f.stem}", f)
            mod = importlib.util.module_from_spec(spec)
            mod.__dict__.update(shared_globals)
            spec.loader.exec_module(mod)
        except Exception as e:
            msg = f"Plugin '{f.stem}' failed to import: {e}"
            logging.error(f"[PLUGIN ENGINE] {msg}")
            _PLUGIN_LOAD_ERRORS.append(msg)
            continue
        manifest = getattr(mod, "MANIFEST", None)
        blueprint = getattr(mod, "bp", None)
        if not manifest or not blueprint:
            msg = f"Plugin '{f.stem}' is missing MANIFEST or bp — skipped."
            logging.warning(f"[PLUGIN ENGINE] {msg}")
            _PLUGIN_LOAD_ERRORS.append(msg)
            continue
        slug = manifest.get("slug")
        if not slug or slug in known_slugs:
            msg = f"Plugin '{f.stem}' has a missing or duplicate slug ('{slug}') — skipped."
            logging.warning(f"[PLUGIN ENGINE] {msg}")
            _PLUGIN_LOAD_ERRORS.append(msg)
            continue
        try:
            app.register_blueprint(blueprint)
        except Exception as e:
            msg = f"Plugin '{slug}' blueprint failed to register (likely a route collision): {e}"
            logging.error(f"[PLUGIN ENGINE] {msg}")
            _PLUGIN_LOAD_ERRORS.append(msg)
            continue
        known_slugs.add(slug)
        PLUGIN_REGISTRY.append(manifest)
        logging.info(f"[PLUGIN ENGINE] Loaded plugin '{slug}'.")


_load_plugins()

# One shared table-creation pass covers every plugin's models, same
# db.create_all()-only-creates-missing-tables pattern used everywhere
# else in this file.
with app.app_context():
    try:
        db.create_all()
    except Exception as _plugin_create_all_err:
        app.logger.warning(f"plugin db.create_all() failed: {_plugin_create_all_err}")


@app.route("/api/platform/feature-registry", methods=["GET"])
def platform_feature_registry():
    """Every plugin currently loaded — the frontend fetches this on
    boot to build the extra menu entries and pull in each plugin's
    frontend_js. load_errors is included so a broken plugin shows up
    somewhere visible instead of failing invisibly."""
    return jsonify({"plugins": PLUGIN_REGISTRY, "load_errors": _PLUGIN_LOAD_ERRORS}), 200


@app.route("/plugins/frontend/<path:filename>", methods=["GET"])
def serve_plugin_frontend(filename):
    safe_name = pathlib.Path(filename).name  # strips any path traversal
    if not safe_name.endswith(".js"):
        return jsonify({"error": "Not found"}), 404
    full_path = _PLUGINS_FRONTEND_DIR / safe_name
    if not full_path.exists():
        return jsonify({"error": "Not found"}), 404
    return send_from_directory(str(_PLUGINS_FRONTEND_DIR), safe_name, mimetype="application/javascript")




# ════════════════════════════════════════════════════════════
# STAGE 464: PAYROLL/HR SELF-SERVICE BACKEND
# The index.html "Payroll, HR & Bank/Tax Rails" panel (hrFetch calls
# against /api/hr/*) was built with no matching backend — every button
# in it 404'd. This stage builds the eight missing endpoints for real,
# scoped to ErpEmployee/owner_user_id like the rest of the ERP suite.
# Real payroll runs, bank verification and benefits enrollment still
# need a licensed partner (HrPartner below lists real named ones and
# logs a request — it doesn't fake the integration); the classification
# checker and tax-table estimator are explicitly labeled as estimates/
# awareness tools, not legal or tax advice.
# ════════════════════════════════════════════════════════════

# ---------- 464a: MODELS ----------

class TimeClockEntry(db.Model):
    """Feature 22 — time clock / attendance, tied to payroll hours."""
    __tablename__ = "hr_time_clock_entries"
    id            = db.Column(db.Integer, primary_key=True)
    owner_user_id = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    employee_id   = db.Column(db.Integer, db.ForeignKey("erp_employees.id"), nullable=False, index=True)
    clock_in_at   = db.Column(db.DateTime, nullable=False, default=datetime.utcnow)
    clock_out_at  = db.Column(db.DateTime, nullable=True)

    def to_dict(self):
        hours = None
        if self.clock_out_at:
            hours = round((self.clock_out_at - self.clock_in_at).total_seconds() / 3600.0, 2)
        return {"id": self.id, "employee_id": self.employee_id,
                "clock_in_at": self.clock_in_at.isoformat() if self.clock_in_at else None,
                "clock_out_at": self.clock_out_at.isoformat() if self.clock_out_at else None,
                "hours": hours}


HR_CLASSIFICATION_QUESTION_KEYS = ["sets_hours", "provides_tools", "exclusive", "ongoing",
                                    "direction", "integral", "own_business", "own_profit_loss"]
# own_business / own_profit_loss are contractor-like signals — answering
# "yes" there LOWERS risk; the other six are employee-like signals where
# "yes" RAISES risk. Mirrors the common-law control test factors.
_HR_CLASSIFICATION_INVERTED = {"own_business", "own_profit_loss"}

HR_CLASSIFICATION_DISCLAIMER = (
    "General awareness check based on common factors tax authorities use (similar to the "
    "IRS twenty-factor / common-law control test) — not legal or tax advice. Consult an "
    "employment attorney or your local labor authority before making a classification decision.")


class WorkerClassificationCheck(db.Model):
    """Feature 25 — contractor vs employee classification risk checker."""
    __tablename__ = "hr_classification_checks"
    id            = db.Column(db.Integer, primary_key=True)
    owner_user_id = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    worker_name   = db.Column(db.String(160), nullable=False)
    answers_json  = db.Column(db.Text, nullable=False)
    risk_score    = db.Column(db.Integer, nullable=False)
    risk_level    = db.Column(db.String(10), nullable=False)  # low, medium, high
    created_at    = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        return {"id": self.id, "worker_name": self.worker_name,
                "answers": json.loads(self.answers_json) if self.answers_json else {},
                "risk_score": self.risk_score, "risk_level": self.risk_level,
                "created_at": self.created_at.isoformat() if self.created_at else None}


