class HrReimbursement(db.Model):
    """Feature 30 — expense reimbursement with a real bank payout, via
    stripe.Transfer.create() to the recipient's own connected Stripe
    account (same real-transfer pattern as the milestone-escrow payout
    above) — never marked 'paid' unless the transfer actually succeeds."""
    __tablename__ = "hr_reimbursements"
    id                  = db.Column(db.Integer, primary_key=True)
    owner_user_id       = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    employee_id         = db.Column(db.Integer, db.ForeignKey("erp_employees.id"), nullable=True, index=True)
    description         = db.Column(db.String(300), nullable=False)
    amount              = db.Column(db.Float, nullable=False)
    currency            = db.Column(db.String(8), nullable=False, default="USD")
    status              = db.Column(db.String(16), nullable=False, default="pending")  # pending, approved, paid, rejected
    payout_error        = db.Column(db.String(300), nullable=True)
    stripe_transfer_id  = db.Column(db.String(120), nullable=True)
    created_at          = db.Column(db.DateTime, default=datetime.utcnow)
    approved_at         = db.Column(db.DateTime, nullable=True)
    paid_at             = db.Column(db.DateTime, nullable=True)

    def to_dict(self):
        return {"id": self.id, "employee_id": self.employee_id, "description": self.description,
                "amount": self.amount, "currency": self.currency, "status": self.status,
                "payout_error": self.payout_error,
                "created_at": self.created_at.isoformat() if self.created_at else None}


