@app.route("/api/hr/time-clock/<int:employee_id>", methods=["GET"])
def hr_time_clock_list(employee_id):
    user, err = _erp_user_or_401()
    if err: return err
    employee = ErpEmployee.query.filter_by(id=employee_id, owner_user_id=user["id"]).first()
    if not employee:
        return jsonify({"error": "Employee not found."}), 404
    rows = (TimeClockEntry.query.filter_by(employee_id=employee_id, owner_user_id=user["id"])
            .order_by(TimeClockEntry.clock_in_at.desc()).limit(60).all())
    total_hours = round(sum((r.to_dict()["hours"] or 0) for r in rows), 2)
    return jsonify({"ok": True, "entries": [r.to_dict() for r in rows],
                     "total_hours_last_60_entries": total_hours}), 200


@app.route("/api/hr/time-clock/in", methods=["POST"])
@csrf.exempt
def hr_time_clock_in():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    employee = ErpEmployee.query.filter_by(id=data.get("employee_id"), owner_user_id=user["id"]).first()
    if not employee:
        return jsonify({"error": "Employee not found."}), 404
    open_entry = TimeClockEntry.query.filter_by(employee_id=employee.id, owner_user_id=user["id"],
                                                 clock_out_at=None).first()
    if open_entry:
        return jsonify({"error": "This employee is already clocked in."}), 400
    row = TimeClockEntry(owner_user_id=user["id"], employee_id=employee.id, clock_in_at=datetime.utcnow())
    db.session.add(row)
    db.session.commit()
    return jsonify({"ok": True, "entry": row.to_dict()}), 201


