# ---------- 464d: CLASSIFICATION CHECKER (feature 25) ----------

@app.route("/api/hr/classification-check", methods=["POST"])
@csrf.exempt
def hr_classification_check_create():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    worker_name = (data.get("worker_name") or "").strip()[:160]
    if not worker_name:
        return jsonify({"error": "worker_name is required."}), 400
    answers = data.get("answers") or {}
    score = 0
    for key in HR_CLASSIFICATION_QUESTION_KEYS:
        checked = bool(answers.get(key))
        if key in _HR_CLASSIFICATION_INVERTED:
            if not checked:
                score += 1
        elif checked:
            score += 1
    max_score = len(HR_CLASSIFICATION_QUESTION_KEYS)
    if score <= 2:
        level = "low"
    elif score <= 5:
        level = "medium"
    else:
        level = "high"
    row = WorkerClassificationCheck(owner_user_id=user["id"], worker_name=worker_name,
                                     answers_json=json.dumps(answers), risk_score=score, risk_level=level)
    db.session.add(row)
    db.session.commit()
    return jsonify({"ok": True, "check": row.to_dict(), "max_score": max_score,
                     "disclaimer": HR_CLASSIFICATION_DISCLAIMER}), 201


