@app.route("/api/hr/tax-tables", methods=["POST"])
@csrf.exempt
def hr_tax_tables_create():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    data = request.get_json(silent=True) or {}
    country_code = (data.get("country_code") or "").strip().upper()[:8]
    label = (data.get("label") or "").strip()[:160]
    if not country_code or not label:
        return jsonify({"error": "country_code and label are required."}), 400

    def _pct(v):
        try:
            return float(v) if v not in (None, "") else None
        except (TypeError, ValueError):
            return None

    row = HrTaxTable(owner_user_id=user["id"], country_code=country_code, label=label,
                      flat_pct=_pct(data.get("flat_pct")),
                      employee_pct_extra=_pct(data.get("employee_pct_extra")),
                      employer_pct_extra=_pct(data.get("employer_pct_extra")),
                      source_note=(data.get("source_note") or "").strip()[:300] or None)
    db.session.add(row)
    db.session.commit()
    return jsonify({"ok": True, "tax_table": row.to_dict()}), 201


@app.route("/api/hr/tax-tables/<int:table_id>/estimate", methods=["POST"])
@csrf.exempt
def hr_tax_tables_estimate(table_id):
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    table = HrTaxTable.query.filter_by(id=table_id, owner_user_id=user["id"]).first()
    if not table:
        return jsonify({"error": "Tax table not found."}), 404
    data = request.get_json(silent=True) or {}
    try:
        gross = float(data.get("gross"))
    except (TypeError, ValueError):
        return jsonify({"error": "A valid gross amount is required."}), 400
    total_pct = (table.flat_pct or 0) + (table.employee_pct_extra or 0)
    estimated_income_tax = round(gross * (total_pct / 100.0), 2)
    estimated_net = round(gross - estimated_income_tax, 2)
    return jsonify({"ok": True, "estimate": {
        "gross": gross, "estimated_income_tax": estimated_income_tax, "estimated_net": estimated_net,
        "note": ("Estimate only, based on the flat/extra percentages entered for this table — "
                 "verify against your local tax authority before running real payroll."),
    }}), 200


# ---------- 464f: COMPLIANCE DASHBOARD (feature 28) ----------

@app.route("/api/hr/compliance-dashboard", methods=["GET"])
def hr_compliance_dashboard():
    user, err = _erp_user_or_401()
    if err: return err
    total_employees = ErpEmployee.query.filter_by(owner_user_id=user["id"]).count()
    tables = (HrTaxTable.query.filter_by(owner_user_id=user["id"])
              .order_by(HrTaxTable.created_at.desc()).all())
    jurisdictions = {}
    for t in tables:
        if t.country_code in jurisdictions:
            continue  # most recent table per country wins
        partner_reqs = HrPartnerRequest.query.filter_by(
            owner_user_id=user["id"], country_code=t.country_code, category="payroll_run").all()
        jurisdictions[t.country_code] = {
            "tax_table_label": t.label,
            "payroll_partner_requests": [r.to_dict() for r in partner_reqs],
        }
    return jsonify({"ok": True, "total_employees": total_employees, "jurisdictions": jurisdictions}), 200


