# ---------- 464h: YEAR-END SUMMARY (feature 29) ----------

@app.route("/api/hr/year-end-summary/<int:employee_id>/<int:year>", methods=["GET"])
def hr_year_end_summary(employee_id, year):
    user, err = _erp_user_or_401()
    if err: return err
    employee = ErpEmployee.query.filter_by(id=employee_id, owner_user_id=user["id"]).first()
    if not employee:
        return jsonify({"error": "Employee not found."}), 404
    runs = (ErpPayrollRun.query.filter_by(owner_user_id=user["id"])
            .filter(ErpPayrollRun.period_end >= date(year, 1, 1),
                    ErpPayrollRun.period_end <= date(year, 12, 31)).all())
    run_ids = [r.id for r in runs]
    payslips = (ErpPayslip.query.filter(ErpPayslip.employee_id == employee_id,
                                         ErpPayslip.payroll_run_id.in_(run_ids)).all()
                if run_ids else [])
    gross_total = round(sum(p.gross for p in payslips), 2)
    net_total = round(sum(p.net for p in payslips), 2)
    distinct_runs = len({p.payroll_run_id for p in payslips})
    return jsonify({
        "ok": True, "year": year, "employee_id": employee_id,
        "gross_total_recorded": gross_total, "net_total_recorded": net_total,
        "payslips_found": len(payslips), "payroll_runs_found": distinct_runs,
        "note": ("This totals payslips this platform actually processed and posted for this employee "
                 "in this year — it is not an official W-2/1099/P60 filing. If this employee's real "
                 "payroll runs through an external provider (Gusto/ADP/Deel), get their official "
                 "year-end document from that provider directly."),
    }), 200


