    employee_id = data.get("employee_id")
    if employee_id:
        employee = ErpEmployee.query.filter_by(id=employee_id, owner_user_id=user["id"]).first()
        employee_id = employee.id if employee else None
    row = HrReimbursement(owner_user_id=user["id"], employee_id=employee_id, description=description,
                           amount=round(amount, 2), currency=(data.get("currency") or "USD").strip()[:8].upper())
    db.session.add(row)
    db.session.commit()
    return jsonify({"ok": True, "reimbursement": row.to_dict()}), 201


