# ---------- 465a: EXPENSE REPORT OCR INTAKE ----------
# Reuses the existing ocr_image_bytes() / parse_receipt_text_with_ai()
# Google Vision chain (already wired for /api/vision/scan-receipt)
# and _upload_to_cloudinary() for the receipt image itself — this
# endpoint is the missing piece that turns a scanned receipt directly
# into a posted ErpExpense row instead of just returning parsed JSON
# for the frontend to re-key by hand.

@app.route("/api/erp/expenses/ocr-intake", methods=["POST"])
@csrf.exempt
def erp_expense_ocr_intake():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err

    image_bytes = None
    if "file" in request.files:
        image_bytes = request.files["file"].read()
    else:
        data = request.get_json(silent=True) or {}
        b64 = data.get("image_base64")
        if b64:
            try:
                image_bytes = base64.b64decode(b64.split(",")[-1])
            except Exception:
                return jsonify({"error": "image_base64 could not be decoded."}), 400
    if not image_bytes:
        return jsonify({"error": "Send a receipt image under form field 'file' or as 'image_base64' in JSON."}), 400

    gate_result = gate_ai_usage(user, "erp_expense_ocr_intake")
    if gate_result is not None:
        return gate_result

    ocr = ocr_image_bytes(image_bytes, user_id=user["id"])
    if not ocr.get("ok"):
        return jsonify({"ok": False, "error": ocr.get("error")}), 502
    structured = parse_receipt_text_with_ai(ocr["text"])

    receipt_url = _upload_to_cloudinary(file_bytes=image_bytes, resource_type="image", folder="connect it/receipts")

    expense_date = date.today()
    raw_date = structured.get("date")
    if raw_date:
        try:
            expense_date = datetime.fromisoformat(str(raw_date)[:10]).date()
        except (TypeError, ValueError):
            pass

    try:
        amount = float(structured.get("total") or 0)
    except (TypeError, ValueError):
        amount = 0.0

    expense = ErpExpense(
        owner_user_id=user["id"], expense_date=expense_date, category="general",
        vendor=(structured.get("vendor") or None), amount=round(amount, 2),
        currency=(structured.get("currency") or "USD").strip()[:8].upper(),
        payment_method=None, receipt_url=receipt_url,
        notes="Created from OCR receipt intake — review vendor/amount/category before reconciling.",
    )
    db.session.add(expense)
    db.session.commit()
    return jsonify({
        "ok": True, "expense": expense.to_dict(), "raw_text": ocr["text"], "structured": structured,
        "note": "Amount, vendor, and date were read from the receipt automatically — double-check them before this expense is reconciled.",
    }), 201


# ---------- 465b: CONFERENCE ROOM AV/EQUIPMENT FAULT REPORTING ----------
# Attaches to the existing MeetingRoom (STAGE 501/463) rather than a
# separate room table.

class RoomEquipmentFault(db.Model):
    __tablename__  = "office_room_equipment_faults"
    id             = db.Column(db.Integer, primary_key=True)
    owner_user_id  = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    room_id        = db.Column(db.Integer, db.ForeignKey("office_meeting_rooms.id"), nullable=False, index=True)
    equipment      = db.Column(db.String(80), nullable=False)   # e.g. projector, AV system, HVAC, wifi, phone
    description    = db.Column(db.Text, nullable=False)
    severity       = db.Column(db.String(10), nullable=False, default="medium")  # low, medium, high
    reported_by    = db.Column(db.String(160), nullable=True)
    status         = db.Column(db.String(15), nullable=False, default="open")    # open, in_progress, resolved
    created_at     = db.Column(db.DateTime, default=datetime.utcnow, index=True)
    resolved_at    = db.Column(db.DateTime, nullable=True)
    resolved_note  = db.Column(db.Text, nullable=True)

    def to_dict(self):
        return {"id": self.id, "room_id": self.room_id, "equipment": self.equipment,
                "description": self.description, "severity": self.severity,
                "reported_by": self.reported_by, "status": self.status,
                "created_at": self.created_at.isoformat() if self.created_at else None,
                "resolved_at": self.resolved_at.isoformat() if self.resolved_at else None,
                "resolved_note": self.resolved_note}


ROOM_FAULT_SEVERITIES = ("low", "medium", "high")


@app.route("/api/office/rooms/<int:room_id>/faults", methods=["POST"])
@csrf.exempt
def office_room_fault_report(room_id):
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    room = MeetingRoom.query.filter_by(id=room_id, owner_user_id=user["id"]).first()
    if not room:
        return jsonify({"error": "Room not found."}), 404
    data = request.get_json(silent=True) or {}
    equipment = (data.get("equipment") or "").strip()[:80]
    description = (data.get("description") or "").strip()
    if not equipment or not description:
        return jsonify({"error": "equipment and description are required."}), 400
    severity = (data.get("severity") or "medium").strip().lower()
    if severity not in ROOM_FAULT_SEVERITIES:
        severity = "medium"
    fault = RoomEquipmentFault(
        owner_user_id=user["id"], room_id=room.id, equipment=equipment, description=description,
        severity=severity, reported_by=(data.get("reported_by") or "").strip()[:160] or None,
    )
    db.session.add(fault)
    db.session.commit()
    return jsonify({"ok": True, "fault": fault.to_dict()}), 201


@app.route("/api/office/rooms/<int:room_id>/faults", methods=["GET"])
def office_room_fault_list(room_id):
    user, err = _erp_user_or_401()
    if err: return err
    room = MeetingRoom.query.filter_by(id=room_id, owner_user_id=user["id"]).first()
    if not room:
        return jsonify({"error": "Room not found."}), 404
    rows = (RoomEquipmentFault.query.filter_by(owner_user_id=user["id"], room_id=room.id)
            .order_by(RoomEquipmentFault.created_at.desc()).all())
    return jsonify({"ok": True, "faults": [r.to_dict() for r in rows]}), 200


@app.route("/api/office/faults", methods=["GET"])
def office_fault_list_all():
    """Cross-room dashboard — every open/in-progress fault for this
    business, newest first, with the room name attached."""
    user, err = _erp_user_or_401()
    if err: return err
    status_filter = (request.args.get("status") or "").strip().lower()
    q = RoomEquipmentFault.query.filter_by(owner_user_id=user["id"])
    if status_filter in ("open", "in_progress", "resolved"):
        q = q.filter_by(status=status_filter)
    rows = q.order_by(RoomEquipmentFault.created_at.desc()).limit(300).all()
    rooms_by_id = {r.id: r.name for r in MeetingRoom.query.filter_by(owner_user_id=user["id"]).all()}
    out = []
    for r in rows:
        d = r.to_dict()
        d["room_name"] = rooms_by_id.get(r.room_id)
        out.append(d)
    return jsonify({"ok": True, "faults": out}), 200


@app.route("/api/office/faults/<int:fault_id>/resolve", methods=["POST"])
@csrf.exempt
def office_fault_resolve(fault_id):
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    fault = RoomEquipmentFault.query.filter_by(id=fault_id, owner_user_id=user["id"]).first()
    if not fault:
        return jsonify({"error": "Fault not found."}), 404
    data = request.get_json(silent=True) or {}
    new_status = (data.get("status") or "resolved").strip().lower()
    if new_status not in ("in_progress", "resolved"):
        new_status = "resolved"
    fault.status = new_status
    fault.resolved_note = (data.get("note") or "").strip()[:500] or None
    if new_status == "resolved":
        fault.resolved_at = datetime.utcnow()
    db.session.commit()
    return jsonify({"ok": True, "fault": fault.to_dict()}), 200


# ---------- 465c: REEFER CONTAINER TEMPERATURE LOG INGESTION ----------
# Sits alongside ContainerTrackingEvent (STAGE 43-ish, milestone
# tracking) rather than replacing it — that table tracks *where* a
# container is, this one tracks *how cold* a reefer container is
# staying along the way, with breach detection against a set point.

class ContainerTempReading(db.Model):
    __tablename__   = "container_temp_readings"
    id              = db.Column(db.Integer, primary_key=True)
    owner_user_id   = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    shipment_id     = db.Column(db.Integer, db.ForeignKey("freight_shipments.id"), nullable=True, index=True)
    container_number = db.Column(db.String(24), nullable=False, index=True)
    recorded_at     = db.Column(db.DateTime, nullable=False, default=datetime.utcnow, index=True)
    temperature_c   = db.Column(db.Float, nullable=False)
    humidity_pct    = db.Column(db.Float, nullable=True)
    set_point_c     = db.Column(db.Float, nullable=True)
    source          = db.Column(db.String(20), nullable=False, default="manual")  # manual, sensor
    breach          = db.Column(db.Boolean, nullable=False, default=False)
    created_at      = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        return {"id": self.id, "shipment_id": self.shipment_id, "container_number": self.container_number,
                "recorded_at": self.recorded_at.isoformat() if self.recorded_at else None,
                "temperature_c": self.temperature_c, "humidity_pct": self.humidity_pct,
                "set_point_c": self.set_point_c, "source": self.source, "breach": self.breach,
                "created_at": self.created_at.isoformat() if self.created_at else None}


REEFER_BREACH_TOLERANCE_C = 2.0  # default allowed drift either side of set_point_c


def _reefer_reading_from_dict(owner_user_id, data):
    container_number = (data.get("container_number") or "").strip().upper()
    if not container_number:
        return None, "container_number is required."
    try:
        temperature_c = float(data.get("temperature_c"))
    except (TypeError, ValueError):
        return None, "temperature_c is required and must be a number."
    set_point_c = data.get("set_point_c")
    try:
        set_point_c = float(set_point_c) if set_point_c is not None else None
    except (TypeError, ValueError):
        set_point_c = None
    humidity_pct = data.get("humidity_pct")
    try:
        humidity_pct = float(humidity_pct) if humidity_pct is not None else None
    except (TypeError, ValueError):
        humidity_pct = None
    recorded_at = datetime.utcnow()
    if data.get("recorded_at"):
        try:
            recorded_at = datetime.fromisoformat(data["recorded_at"])
        except (TypeError, ValueError):
            pass
    shipment_id = data.get("shipment_id")
    if shipment_id:
        ship = FreightShipment.query.filter_by(id=shipment_id, seller_id=owner_user_id).first()
        shipment_id = ship.id if ship else None
    tolerance = REEFER_BREACH_TOLERANCE_C
    try:
        if data.get("tolerance_c") is not None:
            tolerance = float(data["tolerance_c"])
    except (TypeError, ValueError):
        pass
    breach = bool(set_point_c is not None and abs(temperature_c - set_point_c) > tolerance)
    reading = ContainerTempReading(
        owner_user_id=owner_user_id, shipment_id=shipment_id, container_number=container_number[:24],
        recorded_at=recorded_at, temperature_c=temperature_c, humidity_pct=humidity_pct,
        set_point_c=set_point_c, source=(data.get("source") or "manual").strip().lower()[:20] or "manual",
        breach=breach,
    )
    return reading, None


@app.route("/api/logistics/container-temp-log", methods=["POST"])
@csrf.exempt
def container_temp_log_ingest():
    """Accepts either a single reading object or {"readings": [...]}
    for bulk sensor ingestion (a reefer datalogger typically uploads a
    batch of timestamped points at once, not one per request)."""
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user: return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    batch = data.get("readings") if isinstance(data.get("readings"), list) else [data]

    created, skipped, breaches = [], [], 0
    for i, item in enumerate(batch[:500]):
        reading, error = _reefer_reading_from_dict(user["id"], item or {})
        if error:
            skipped.append({"index": i, "reason": error})
            continue
        db.session.add(reading)
        created.append(reading)
        if reading.breach:
            breaches += 1
    if created:
        try:
            db.session.commit()
        except Exception as e:
            db.session.rollback()
            logging.error(f"[CONTAINER TEMP LOG] {e}")
            return jsonify({"error": "Could not save the readings."}), 500
    return jsonify({
        "ok": True, "created": [r.to_dict() for r in created], "skipped": skipped,
        "breach_count": breaches,
    }), 201


@app.route("/api/logistics/container-temp-log/<container_number>", methods=["GET"])
def container_temp_log_timeline(container_number):
    user = _get_current_user()
    if not user: return jsonify({"error": "Login required."}), 401
    rows = (ContainerTempReading.query
            .filter_by(owner_user_id=user["id"], container_number=container_number.strip().upper())
            .order_by(ContainerTempReading.recorded_at.asc()).all())
    temps = [r.temperature_c for r in rows]
    summary = {
        "readings_count": len(rows),
        "min_c": round(min(temps), 2) if temps else None,
        "max_c": round(max(temps), 2) if temps else None,
        "avg_c": round(sum(temps) / len(temps), 2) if temps else None,
        "breach_count": sum(1 for r in rows if r.breach),
    }
    return jsonify({"ok": True, "container_number": container_number.upper(),
                     "timeline": [r.to_dict() for r in rows], "summary": summary}), 200


# ---------- 465d: BULK CSV IMPORT WIZARD WITH FIELD MAPPING ----------
# Generic across record types (STAGE 311's product bulk import already
# covers marketplace listings and is left untouched — this handles the
# ERP record types it doesn't: customers, expenses, and inventory).
# Two-step wizard, both stateless: preview reads the CSV's own headers
# and suggests a mapping; commit re-sends the file plus the (possibly
# hand-edited) mapping and actually creates the rows. No server-side
# session/cache needed, matching the "tolerant single-request" pattern
# already used for the product CSV importer.

IMPORT_TARGETS = {
    "customers": {
        "model": ErpCustomer, "owner_field": "owner_user_id",
        "fields": {
            "name": {"required": True, "type": "str", "max": 200},
            "email": {"type": "str", "max": 200}, "phone": {"type": "str", "max": 64},
            "address": {"type": "str", "max": 400}, "notes": {"type": "str", "max": 2000},
            "tax_id": {"type": "str", "max": 64},
        },
    },
    "expenses": {
        "model": ErpExpense, "owner_field": "owner_user_id",
        "fields": {
            "expense_date": {"required": True, "type": "date"},
            "amount": {"required": True, "type": "float"},
            "category": {"type": "str", "max": 80}, "vendor": {"type": "str", "max": 200},
            "currency": {"type": "str", "max": 8}, "payment_method": {"type": "str", "max": 40},
            "notes": {"type": "str", "max": 2000},
        },
    },
    "inventory": {
        "model": InventoryItem, "owner_field": "user_id",
        "fields": {
            "name": {"required": True, "type": "str", "max": 200},
            "sku": {"type": "str", "max": 64}, "category": {"type": "str", "max": 100},
            "unit": {"type": "str", "max": 32}, "quantity": {"type": "float"},
            "threshold": {"type": "float"}, "cost_price": {"type": "float"},
            "unit_price": {"type": "float"}, "barcode": {"type": "str", "max": 64},
        },
    },
}


def _import_suggest_mapping(headers, target_fields):
    suggestions = {}
    normalized_targets = {k.replace("_", "").lower(): k for k in target_fields}
    for h in headers:
        norm = (h or "").strip().replace(" ", "_").replace("-", "_").replace("_", "").lower()
        suggestions[h] = normalized_targets.get(norm)
    return suggestions


def _import_coerce(value, spec):
    value = (value or "").strip()
    if not value:
        return None, None
    field_type = spec.get("type", "str")
    if field_type == "float":
        try:
            return float(value.replace(",", "")), None
        except ValueError:
            return None, "not a number"
    if field_type == "date":
        try:
            return datetime.fromisoformat(value[:10]).date(), None
        except ValueError:
            return None, "not a valid date (expected YYYY-MM-DD)"
    max_len = spec.get("max")
    return (value[:max_len] if max_len else value), None


@app.route("/api/import/targets", methods=["GET"])
def import_targets_list():
    """What record types this wizard can import into, and their fields
    — drives the mapping UI without hardcoding field lists client-side."""
    return jsonify({"ok": True, "targets": {
        key: {"fields": [{"key": fk, "required": bool(fs.get("required")), "type": fs.get("type", "str")}
                          for fk, fs in cfg["fields"].items()]}
        for key, cfg in IMPORT_TARGETS.items()
    }}), 200


@app.route("/api/import/preview", methods=["POST"])
@csrf.exempt
def import_preview():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user: return jsonify({"error": "Login required."}), 401
    target = (request.form.get("target") or "").strip().lower()
    if target not in IMPORT_TARGETS:
        return jsonify({"error": f"target must be one of: {', '.join(IMPORT_TARGETS)}"}), 400
    if "file" not in request.files:
        return jsonify({"error": "Send the CSV under form field 'file'."}), 400
    raw = request.files["file"].read().decode("utf-8-sig", errors="replace")
    reader = csv.DictReader(io.StringIO(raw))
    if not reader.fieldnames:
        return jsonify({"error": "CSV file is empty or has no header row."}), 400
    sample_rows = []
    for i, row in enumerate(reader):
        if i >= 5:
            break
        sample_rows.append(row)
    target_fields = IMPORT_TARGETS[target]["fields"]
    return jsonify({
        "ok": True, "target": target, "headers": reader.fieldnames, "sample_rows": sample_rows,
        "target_fields": [{"key": fk, "required": bool(fs.get("required")), "type": fs.get("type", "str")}
                           for fk, fs in target_fields.items()],
        "suggested_mapping": _import_suggest_mapping(reader.fieldnames, target_fields),
    }), 200


@app.route("/api/import/commit", methods=["POST"])
@csrf.exempt
def import_commit():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user: return jsonify({"error": "Login required."}), 401
    target = (request.form.get("target") or "").strip().lower()
    if target not in IMPORT_TARGETS:
        return jsonify({"error": f"target must be one of: {', '.join(IMPORT_TARGETS)}"}), 400
    if "file" not in request.files:
        return jsonify({"error": "Send the CSV under form field 'file'."}), 400
    try:
        mapping = json.loads(request.form.get("mapping") or "{}")
    except (TypeError, ValueError):
        return jsonify({"error": "mapping must be a JSON object of {csv_column: target_field}."}), 400
    if not isinstance(mapping, dict):
        return jsonify({"error": "mapping must be a JSON object of {csv_column: target_field}."}), 400

    cfg = IMPORT_TARGETS[target]
    model, owner_field, target_fields = cfg["model"], cfg["owner_field"], cfg["fields"]
    required_keys = [k for k, spec in target_fields.items() if spec.get("required")]

    raw = request.files["file"].read().decode("utf-8-sig", errors="replace")
    reader = csv.DictReader(io.StringIO(raw))
    if not reader.fieldnames:
        return jsonify({"error": "CSV file is empty or has no header row."}), 400

    created, skipped = [], []
    row_num = 1
    for raw_row in reader:
        row_num += 1
        if row_num > 502:
            skipped.append({"row": row_num, "reason": "Stopped at 500 rows — split larger files into multiple uploads."})
            break
        if not raw_row or all(not (v or "").strip() for v in raw_row.values()):
            continue
        field_values, row_error = {}, None
        for csv_col, target_field in mapping.items():
            if not target_field or target_field not in target_fields:
                continue
            coerced, err = _import_coerce(raw_row.get(csv_col), target_fields[target_field])
            if err:
                row_error = f"{target_field}: {err}"
                break
            if coerced is not None:
                field_values[target_field] = coerced
        if row_error:
            skipped.append({"row": row_num, "reason": row_error})
            continue
        missing = [k for k in required_keys if field_values.get(k) is None]
        if missing:
            skipped.append({"row": row_num, "reason": f"missing required field(s): {', '.join(missing)}"})
            continue
        field_values[owner_field] = user["id"]
        try:
            obj = model(**field_values)
            db.session.add(obj)
            created.append(obj)
        except Exception as e:
            skipped.append({"row": row_num, "reason": str(e)[:200]})

    if created:
        try:
            db.session.commit()
        except Exception as e:
            db.session.rollback()
            logging.error(f"[IMPORT COMMIT] {e}")
            return jsonify({"error": "Could not save the imported rows."}), 500
    return jsonify({
        "ok": True, "target": target, "created_count": len(created), "skipped": skipped,
        "created": [c.to_dict() for c in created[:50]],  # first 50 only, to keep the response small
    }), 201


# ---------- 465e: CUSTOM FIELDS & TAGS ACROSS RECORDS ----------
# Generic — entity_type is a free string ("customers", "inventory",
# "expenses", "employees", etc.) matched against entity_id from that
# record's own table. Kept intentionally decoupled from any one
# model (no foreign key into a specific table) so it works uniformly
# across every record type in the ERP without a schema change per type.

class CustomFieldDefinition(db.Model):
    __tablename__  = "custom_field_definitions"
    id             = db.Column(db.Integer, primary_key=True)
    owner_user_id  = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    entity_type    = db.Column(db.String(40), nullable=False, index=True)
    field_key      = db.Column(db.String(60), nullable=False)
    label          = db.Column(db.String(120), nullable=False)
    field_type     = db.Column(db.String(20), nullable=False, default="text")  # text, number, date, boolean, select
    options_csv    = db.Column(db.String(500), nullable=True)  # for field_type == 'select'
    created_at     = db.Column(db.DateTime, default=datetime.utcnow)
    __table_args__ = (db.UniqueConstraint("owner_user_id", "entity_type", "field_key", name="uq_custom_field_per_entity"),)

    def to_dict(self):
        return {"id": self.id, "entity_type": self.entity_type, "field_key": self.field_key,
                "label": self.label, "field_type": self.field_type,
                "options": [o.strip() for o in (self.options_csv or "").split(",") if o.strip()],
                "created_at": self.created_at.isoformat() if self.created_at else None}


class CustomFieldValue(db.Model):
    __tablename__  = "custom_field_values"
    id             = db.Column(db.Integer, primary_key=True)
