@app.route("/api/custom-fields/definitions", methods=["POST"])
@csrf.exempt
def custom_field_definition_create():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user: return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    entity_type = (data.get("entity_type") or "").strip().lower()[:40]
    field_key = (data.get("field_key") or "").strip().lower().replace(" ", "_")[:60]
    label = (data.get("label") or "").strip()[:120]
    field_type = (data.get("field_type") or "text").strip().lower()
    if field_type not in ("text", "number", "date", "boolean", "select"):
        field_type = "text"
    if not entity_type or not field_key or not label:
        return jsonify({"error": "entity_type, field_key, and label are required."}), 400
    existing = CustomFieldDefinition.query.filter_by(
        owner_user_id=user["id"], entity_type=entity_type, field_key=field_key).first()
    if existing:
        return jsonify({"error": "A custom field with this key already exists for this record type."}), 409
    options_csv = ",".join(o.strip() for o in (data.get("options") or []) if o.strip())[:500] or None
    row = CustomFieldDefinition(owner_user_id=user["id"], entity_type=entity_type, field_key=field_key,
                                 label=label, field_type=field_type, options_csv=options_csv)
    db.session.add(row)
    db.session.commit()
    return jsonify({"ok": True, "definition": row.to_dict()}), 201


