    user = _get_current_user()
    if not user: return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    row = UserAccessibilityPref.query.filter_by(owner_user_id=user["id"]).first()
    if not row:
        row = UserAccessibilityPref(owner_user_id=user["id"])
