# STAGE 466: FIVE REMAINING ROADMAP GAPS (audit items 1-5)
# Closes the next batch of items flagged as missing from both the
# backend and the frontend in the full roadmap audit:
#   1. AI video product demos               (roadmap_100 #39)
#   2. Automated compliance document translation (roadmap_100 #44)
#   3. AI-negotiated freight consolidation   (roadmap_100 #46)
#   4. National pavilion program             (roadmap_100 #49)
#   5. Virtual trade mission events          (roadmap_100 #50)
# Each reuses existing, already-configured infrastructure (Claude
# for scripting, gTTS for narration, MoviePy for assembly, Google
# Translate, Cloudinary, the freight/livestream models) rather than
# faking a new integration. Where a real external dependency is
# unavoidable (actual video-conferencing infra for trade missions),
# the seller/host supplies their own real meeting link, the same
# pattern already used by FactoryLivestreamSlot, instead of the
# platform pretending to generate one itself.
# ════════════════════════════════════════════════════════════

# ---------- 466a: AI VIDEO PRODUCT DEMOS ----------
# Turns a listing's existing spec text + photos into a real narrated
# slideshow-style demo video: Claude writes a short script from the
# product's name/description/spec fields, gTTS narrates it, MoviePy
# assembles the seller's own product photos with the narration and
# text captions into an MP4, which is then hosted on Cloudinary like
# every other media asset on the platform. Degrades with a clear
# error (never a fake/placeholder video) if MoviePy or gTTS aren't
# configured.

class ProductVideoDemo(db.Model):
    __tablename__     = "product_video_demos"
    id                = db.Column(db.Integer, primary_key=True)
    product_id        = db.Column(db.Integer, db.ForeignKey("products.id"), nullable=False, index=True)
    seller_id         = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    script_text       = db.Column(db.Text, nullable=True)
    video_url         = db.Column(db.String(500), nullable=True)
    status            = db.Column(db.String(16), nullable=False, default="processing")  # processing, ready, failed
    error_message     = db.Column(db.String(500), nullable=True)
    created_at        = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        return {"id": self.id, "product_id": self.product_id, "script_text": self.script_text,
                "video_url": self.video_url, "status": self.status, "error_message": self.error_message,
                "created_at": self.created_at.isoformat() if self.created_at else None}


def _generate_product_demo_script(product) -> str | None:
    prompt = (
        f"Write a tight 5-sentence voiceover script for a product demo video. "
        f"Product: {product.name}. Category: {product.category}. "
        f"Description: {(product.description or '')[:500]}. "
        f"Plain spoken language, no stage directions, no markdown, just the words to narrate."
    )
    return _one_round([{"role": "user", "content": prompt}])


@app.route("/api/products/<int:product_id>/video-demo", methods=["POST"])
@csrf.exempt
def product_video_demo_create(product_id):
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user: return jsonify({"error": "Login required."}), 401
    product = Product.query.get(product_id)
    if not product or product.seller_id != user["id"]:
        return jsonify({"error": "Product not found or not owned by you."}), 404
    if not MOVIEPY_AVAILABLE:
        return jsonify({"error": "MoviePy is not installed. Run: pip install moviepy"}), 503
    if not GTTS_AVAILABLE:
        return jsonify({"error": "Google Text-to-Speech is not configured. Set GOOGLE_SPEECH_CREDENTIALS_JSON."}), 503

    gate_result = gate_ai_usage(user, "product_video_demo_create")
    if gate_result is not None:
        return gate_result

    demo = ProductVideoDemo(product_id=product.id, seller_id=user["id"], status="processing")
    db.session.add(demo)
    db.session.commit()

    try:
        script = _generate_product_demo_script(product)
        if not script:
            raise RuntimeError("Script generation failed — no AI provider is currently configured.")
        demo.script_text = script

        tts = text_to_speech(script, user_id=user["id"])
        if not tts.get("ok"):
            raise RuntimeError(f"Narration failed: {tts.get('error')}")
        audio_bytes = base64.b64decode(tts["audio_base64"])
        tmp_dir = tempfile.mkdtemp(prefix="video_demo_")
        audio_path = os.path.join(tmp_dir, "narration.mp3")
        with open(audio_path, "wb") as f:
            f.write(audio_bytes)

        from moviepy.editor import ImageClip, AudioFileClip, concatenate_videoclips
        image_urls = json.loads(product.image_urls) if product.image_urls else []
        clips = []
        audio_clip = AudioFileClip(audio_path)
        per_image_dur = max(2.5, audio_clip.duration / max(1, len(image_urls) or 1))
        if image_urls:
            for i, url in enumerate(image_urls[:8]):
                try:
                    resp = requests.get(url, timeout=15)
                    img_path = os.path.join(tmp_dir, f"img_{i}.jpg")
                    with open(img_path, "wb") as f:
                        f.write(resp.content)
                    clips.append(ImageClip(img_path).set_duration(per_image_dur))
                except Exception as img_err:
                    logging.warning(f"[VIDEO DEMO] image {url} skipped: {img_err}")
        if not clips:
            clips = [ColorClip(size=(1280, 720), color=(20, 20, 30)).set_duration(audio_clip.duration)]

        video = concatenate_videoclips(clips, method="compose").resize(width=1280)
        title_card = TextClip(product.name[:60], fontsize=48, color="white", size=(1280, 100), bg_color="black") \
            .set_duration(min(3, video.duration)).set_position(("center", "bottom"))
        final = CompositeVideoClip([video, title_card]).set_audio(audio_clip.set_duration(video.duration))

        out_path = os.path.join(tmp_dir, "demo.mp4")
        final.write_videofile(out_path, fps=24, codec="libx264", audio_codec="aac", verbose=False, logger=None)

        with open(out_path, "rb") as f:
            video_url = _upload_to_cloudinary(file_bytes=f.read(), resource_type="video", folder="connect it/product_demos")

        shutil.rmtree(tmp_dir, ignore_errors=True)
        demo.video_url = video_url
        demo.status = "ready"
        db.session.commit()
        return jsonify({"ok": True, "demo": demo.to_dict()}), 201
    except Exception as e:
        logging.error(f"[VIDEO DEMO ERROR] product={product_id}: {e}")
        demo.status = "failed"
        demo.error_message = str(e)[:500]
        db.session.commit()
        return jsonify({"ok": False, "error": demo.error_message, "demo": demo.to_dict()}), 502


