@app.route("/api/compliance/translate-document", methods=["POST"])
@csrf.exempt
def compliance_translate_document():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user: return jsonify({"error": "Login required."}), 401

    text = None
    label = None
    if "file" in request.files:
        upload = request.files["file"]
        label = upload.filename
        raw = upload.read()
        try:
            if upload.filename.lower().endswith(".pdf"):
                reader = PdfReader(io.BytesIO(raw))
                text = "\n".join((p.extract_text() or "") for p in reader.pages)
            elif upload.filename.lower().endswith(".docx"):
                doc = Document(io.BytesIO(raw))
                text = "\n".join(p.text for p in doc.paragraphs)
            else:
                text = raw.decode("utf-8", errors="ignore")
        except Exception as e:
            return jsonify({"error": f"Could not read uploaded document: {e}"}), 400
    else:
        data = request.get_json(silent=True) or {}
        text = data.get("text")
        label = data.get("document_label")

    if not text or not text.strip():
        return jsonify({"error": "Send a document file under 'file', or JSON with a 'text' field."}), 400

    data = request.get_json(silent=True) or {}
    target_lang = (request.form.get("target_lang") or data.get("target_lang") or "").strip()
    source_lang = (request.form.get("source_lang") or data.get("source_lang") or "").strip() or None
    if not target_lang:
        return jsonify({"error": "target_lang is required (e.g. 'es', 'fr', 'zh')."}), 400

    result = google_translate_text(text[:20000], target_lang=target_lang, source_lang=source_lang, user_id=user["id"])
    job = ComplianceTranslationJob(
        owner_user_id=user["id"], document_label=(label or "")[:160] or None,
        source_lang=(result.get("detected_source_language") or source_lang),
        target_lang=target_lang[:8],
    )
    if not result.get("ok"):
        job.status = "failed"
        job.error_message = result.get("error", "")[:500]
        db.session.add(job)
        db.session.commit()
        return jsonify({"ok": False, "error": job.error_message, "job": job.to_dict()}), 502

    job.translated_text = result["translated_text"]

    try:
        out_doc = Document()
        out_doc.add_heading((label or "Translated Compliance Document"), level=1)
        for line in result["translated_text"].split("\n"):
            if line.strip():
                out_doc.add_paragraph(line)
        buf = BytesIO()
        out_doc.save(buf)
        buf.seek(0)
        job.file_url = _upload_to_cloudinary(file_bytes=buf.read(), resource_type="raw", folder="connect it/compliance_translations")
    except Exception as e:
        logging.warning(f"[COMPLIANCE TRANSLATE] docx build failed, text still returned: {e}")

    db.session.add(job)
    db.session.commit()
    return jsonify({"ok": True, "job": job.to_dict()}), 201


