    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user: return jsonify({"error": "Login required."}), 401
    group = FreightConsolidationGroup.query.get(group_id)
    if not group or group.seller_id != user["id"]:
        return jsonify({"error": "Consolidation group not found."}), 404
    group.status = "dismissed"
    for s in FreightShipment.query.filter_by(consolidation_group_id=group.id).all():
        s.consolidation_group_id = None
    db.session.commit()
    return jsonify({"ok": True, "group": group.to_dict()}), 200


