# ---------- 467b: WOMEN-IN-TRADE ACCELERATOR PROGRAM ----------
# Cohort-based program: an admin (or a partnering trade body acting
# through an admin account) opens a cohort with a focus area and
# mentor; women-owned sellers apply; the admin accepts, waitlists, or
# declines. Mirrors the National Pavilion apply/review flow above.

class AcceleratorCohort(db.Model):
    __tablename__ = "accelerator_cohorts"
    id            = db.Column(db.Integer, primary_key=True)
    admin_id      = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False)
    name          = db.Column(db.String(200), nullable=False)
    focus_area    = db.Column(db.String(200), nullable=True)  # e.g. "Export readiness", "Access to finance"
    mentor_name   = db.Column(db.String(120), nullable=True)
    start_date    = db.Column(db.Date, nullable=True)
    end_date      = db.Column(db.Date, nullable=True)
    description   = db.Column(db.Text, nullable=True)
    is_active     = db.Column(db.Boolean, nullable=False, default=True, index=True)
    created_at    = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        accepted = AcceleratorApplication.query.filter_by(cohort_id=self.id, status="accepted").count()
        return {"id": self.id, "name": self.name, "focus_area": self.focus_area, "mentor_name": self.mentor_name,
                "start_date": self.start_date.isoformat() if self.start_date else None,
                "end_date": self.end_date.isoformat() if self.end_date else None,
                "description": self.description, "is_active": self.is_active, "accepted_count": accepted,
                "created_at": self.created_at.isoformat() if self.created_at else None}


class AcceleratorApplication(db.Model):
    __tablename__ = "accelerator_applications"
    id            = db.Column(db.Integer, primary_key=True)
    cohort_id     = db.Column(db.Integer, db.ForeignKey("accelerator_cohorts.id"), nullable=False, index=True)
    applicant_id  = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    business_description = db.Column(db.Text, nullable=True)
    status        = db.Column(db.String(16), nullable=False, default="pending")  # pending, accepted, waitlisted, rejected
    applied_at    = db.Column(db.DateTime, default=datetime.utcnow)
    reviewed_at   = db.Column(db.DateTime, nullable=True)

    def to_dict(self):
        return {"id": self.id, "cohort_id": self.cohort_id, "applicant_id": self.applicant_id,
                "business_description": self.business_description, "status": self.status,
                "applied_at": self.applied_at.isoformat() if self.applied_at else None,
                "reviewed_at": self.reviewed_at.isoformat() if self.reviewed_at else None}


@app.route("/api/accelerator/cohorts", methods=["POST"])
@csrf.exempt
def accelerator_cohort_create():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user or not user.get("is_admin"):
        return jsonify({"error": "Admin login required."}), 403
    data = request.get_json(silent=True) or {}
    name = (data.get("name") or "").strip()[:200]
    if not name:
        return jsonify({"error": "name is required."}), 400
    def _parse_date(v):
        try: return datetime.fromisoformat(v).date() if v else None
        except (ValueError, TypeError): return None
    cohort = AcceleratorCohort(
        admin_id=user["id"], name=name,
        focus_area=(data.get("focus_area") or "").strip()[:200] or None,
        mentor_name=(data.get("mentor_name") or "").strip()[:120] or None,
        start_date=_parse_date(data.get("start_date")), end_date=_parse_date(data.get("end_date")),
        description=data.get("description"),
    )
    db.session.add(cohort)
    db.session.commit()
    return jsonify({"ok": True, "cohort": cohort.to_dict()}), 201


@app.route("/api/accelerator/cohorts", methods=["GET"])
def accelerator_cohort_list():
    rows = AcceleratorCohort.query.filter_by(is_active=True).order_by(AcceleratorCohort.created_at.desc()).all()
    return jsonify({"ok": True, "cohorts": [r.to_dict() for r in rows]}), 200


@app.route("/api/accelerator/cohorts/<int:cohort_id>/apply", methods=["POST"])
@csrf.exempt
def accelerator_apply(cohort_id):
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user: return jsonify({"error": "Login required."}), 401
    cohort = AcceleratorCohort.query.get(cohort_id)
    if not cohort or not cohort.is_active:
        return jsonify({"error": "Cohort not found."}), 404
    existing = AcceleratorApplication.query.filter_by(cohort_id=cohort_id, applicant_id=user["id"]).first()
    if existing:
        return jsonify({"ok": True, "application": existing.to_dict(), "note": "Application already on file."}), 200
    data = request.get_json(silent=True) or {}
    app_row = AcceleratorApplication(cohort_id=cohort_id, applicant_id=user["id"],
                                      business_description=(data.get("business_description") or "").strip()[:2000] or None)
    db.session.add(app_row)
    db.session.commit()
    return jsonify({"ok": True, "application": app_row.to_dict()}), 201


@app.route("/api/accelerator/applications/mine", methods=["GET"])
def accelerator_applications_mine():
    user = _get_current_user()
    if not user: return jsonify({"error": "Login required."}), 401
    rows = AcceleratorApplication.query.filter_by(applicant_id=user["id"]).order_by(AcceleratorApplication.applied_at.desc()).all()
    return jsonify({"ok": True, "applications": [r.to_dict() for r in rows]}), 200


@app.route("/api/accelerator/applications/<int:application_id>/review", methods=["POST"])
@csrf.exempt
def accelerator_review(application_id):
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user or not user.get("is_admin"):
        return jsonify({"error": "Admin login required."}), 403
    row = AcceleratorApplication.query.get(application_id)
    if not row:
        return jsonify({"error": "Application not found."}), 404
    decision = (request.get_json(silent=True) or {}).get("decision")
    if decision not in ("accepted", "waitlisted", "rejected"):
        return jsonify({"error": "decision must be 'accepted', 'waitlisted', or 'rejected'."}), 400
    row.status = decision
    row.reviewed_at = datetime.utcnow()
    db.session.commit()
    return jsonify({"ok": True, "application": row.to_dict()}), 200


# ---------- 467c: SUPPLIER DIVERSITY CERTIFICATION HUB ----------
# Sellers self-identify a diversity category and submit a supporting
# document link (e.g. a scan of a third-party certifying body's
# letter); an admin reviews and, on approval, issues a certificate
# number with an expiry date. Approved certifications are browsable
# in a public directory so buyers can filter for verified categories.

DIVERSITY_CATEGORIES = ("women-owned", "minority-owned", "veteran-owned", "lgbtq-owned",
                         "disability-owned", "small-business")


class DiversityCertification(db.Model):
    __tablename__      = "diversity_certifications"
    id                 = db.Column(db.Integer, primary_key=True)
    seller_id          = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    category           = db.Column(db.String(40), nullable=False, index=True)
    supporting_doc_url = db.Column(db.String(500), nullable=True)
    status             = db.Column(db.String(16), nullable=False, default="pending")  # pending, approved, denied
    certificate_number = db.Column(db.String(40), nullable=True, unique=True)
    reviewed_by_admin_id = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=True)
    notes              = db.Column(db.Text, nullable=True)
    issued_at          = db.Column(db.DateTime, nullable=True)
    expires_at         = db.Column(db.DateTime, nullable=True)
    created_at         = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        return {"id": self.id, "seller_id": self.seller_id, "category": self.category,
                "supporting_doc_url": self.supporting_doc_url, "status": self.status,
                "certificate_number": self.certificate_number, "notes": self.notes,
                "issued_at": self.issued_at.isoformat() if self.issued_at else None,
                "expires_at": self.expires_at.isoformat() if self.expires_at else None,
                "created_at": self.created_at.isoformat() if self.created_at else None}


@app.route("/api/diversity-certifications", methods=["POST"])
@csrf.exempt
def diversity_certification_apply():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user: return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    category = (data.get("category") or "").strip().lower()
    if category not in DIVERSITY_CATEGORIES:
        return jsonify({"error": f"category must be one of: {', '.join(DIVERSITY_CATEGORIES)}"}), 400
    row = DiversityCertification(
        seller_id=user["id"], category=category,
        supporting_doc_url=(data.get("supporting_doc_url") or "").strip()[:500] or None,
    )
    db.session.add(row)
    db.session.commit()
    return jsonify({"ok": True, "certification": row.to_dict()}), 201


@app.route("/api/diversity-certifications/mine", methods=["GET"])
def diversity_certification_mine():
    user = _get_current_user()
    if not user: return jsonify({"error": "Login required."}), 401
    rows = DiversityCertification.query.filter_by(seller_id=user["id"]).order_by(DiversityCertification.created_at.desc()).all()
    return jsonify({"ok": True, "certifications": [r.to_dict() for r in rows]}), 200


@app.route("/api/diversity-certifications/directory", methods=["GET"])
def diversity_certification_directory():
    category = request.args.get("category")
    q = DiversityCertification.query.filter_by(status="approved")
    if category:
        q = q.filter_by(category=category.strip().lower())
    rows = q.order_by(DiversityCertification.issued_at.desc()).limit(200).all()
    out = []
    for r in rows:
        seller = UserAccount.query.get(r.seller_id)
        out.append({**r.to_dict(), "seller_name": seller.name if seller else None})
    return jsonify({"ok": True, "certifications": out}), 200


@app.route("/api/diversity-certifications/<int:cert_id>/review", methods=["POST"])
@csrf.exempt
def diversity_certification_review(cert_id):
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user or not user.get("is_admin"):
        return jsonify({"error": "Admin login required."}), 403
    row = DiversityCertification.query.get(cert_id)
    if not row:
        return jsonify({"error": "Certification request not found."}), 404
    data = request.get_json(silent=True) or {}
    decision = data.get("decision")
    if decision not in ("approved", "denied"):
        return jsonify({"error": "decision must be 'approved' or 'denied'."}), 400
    row.status = decision
    row.reviewed_by_admin_id = user["id"]
    row.notes = (data.get("notes") or "").strip()[:1000] or None
    if decision == "approved":
        row.certificate_number = "DIV-" + secrets.token_hex(4).upper()
        row.issued_at = datetime.utcnow()
        row.expires_at = datetime.utcnow() + timedelta(days=365)
    db.session.commit()
    return jsonify({"ok": True, "certification": row.to_dict()}), 200


# ---------- 467d: COMMUNITY-FUNDED MICRO-MANUFACTURING ----------
# A producer who needs equipment (a CNC unit, a loom, a bottling line)
# lists it with a funding goal; the community backs it with real
# pledges tracked here. raised_amount is always recomputed from the
# sum of backings, never trusted as a stored counter, so it can't
# drift out of sync.

class MicroManufacturingCampaign(db.Model):
    __tablename__         = "micro_manufacturing_campaigns"
    id                    = db.Column(db.Integer, primary_key=True)
    producer_id           = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    title                 = db.Column(db.String(200), nullable=False)
    equipment_description = db.Column(db.Text, nullable=True)
    goal_amount           = db.Column(db.Float, nullable=False)
    currency              = db.Column(db.String(8), nullable=False, default="USD")
    deadline              = db.Column(db.DateTime, nullable=True)
    status                = db.Column(db.String(16), nullable=False, default="active")  # active, funded, closed
    created_at            = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        raised = db.session.query(db.func.coalesce(db.func.sum(MicroManufacturingBacking.amount), 0.0)) \
            .filter(MicroManufacturingBacking.campaign_id == self.id).scalar() or 0.0
        return {"id": self.id, "producer_id": self.producer_id, "title": self.title,
                "equipment_description": self.equipment_description, "goal_amount": self.goal_amount,
                "raised_amount": round(float(raised), 2), "currency": self.currency,
                "deadline": self.deadline.isoformat() if self.deadline else None, "status": self.status,
                "created_at": self.created_at.isoformat() if self.created_at else None}


class MicroManufacturingBacking(db.Model):
    __tablename__ = "micro_manufacturing_backings"
    id           = db.Column(db.Integer, primary_key=True)
    campaign_id  = db.Column(db.Integer, db.ForeignKey("micro_manufacturing_campaigns.id"), nullable=False, index=True)
    backer_id    = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    amount       = db.Column(db.Float, nullable=False)
    created_at   = db.Column(db.DateTime, default=datetime.utcnow)


@app.route("/api/micro-mfg/campaigns", methods=["POST"])
@csrf.exempt
def micro_mfg_campaign_create():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user: return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    title = (data.get("title") or "").strip()[:200]
    try:
        goal_amount = float(data.get("goal_amount"))
    except (TypeError, ValueError):
        return jsonify({"error": "title and a numeric goal_amount are required."}), 400
    if not title or goal_amount <= 0:
        return jsonify({"error": "title and a numeric goal_amount are required."}), 400
    deadline = None
    try:
        if data.get("deadline"): deadline = datetime.fromisoformat(data["deadline"])
    except (ValueError, TypeError):
        deadline = None
    campaign = MicroManufacturingCampaign(
        producer_id=user["id"], title=title, equipment_description=data.get("equipment_description"),
        goal_amount=goal_amount, currency=(data.get("currency") or "USD").strip()[:8].upper(), deadline=deadline,
    )
    db.session.add(campaign)
    db.session.commit()
    return jsonify({"ok": True, "campaign": campaign.to_dict()}), 201


@app.route("/api/micro-mfg/campaigns", methods=["GET"])
def micro_mfg_campaign_list():
    rows = (MicroManufacturingCampaign.query.filter(MicroManufacturingCampaign.status == "active")
            .order_by(MicroManufacturingCampaign.created_at.desc()).limit(200).all())
    return jsonify({"ok": True, "campaigns": [r.to_dict() for r in rows]}), 200


@app.route("/api/micro-mfg/campaigns/mine", methods=["GET"])
def micro_mfg_campaign_mine():
    user = _get_current_user()
    if not user: return jsonify({"error": "Login required."}), 401
    rows = MicroManufacturingCampaign.query.filter_by(producer_id=user["id"]).order_by(MicroManufacturingCampaign.created_at.desc()).all()
    return jsonify({"ok": True, "campaigns": [r.to_dict() for r in rows]}), 200


@app.route("/api/micro-mfg/campaigns/<int:campaign_id>/back", methods=["POST"])
@csrf.exempt
def micro_mfg_campaign_back(campaign_id):
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user: return jsonify({"error": "Login required."}), 401
    campaign = MicroManufacturingCampaign.query.get(campaign_id)
    if not campaign or campaign.status != "active":
        return jsonify({"error": "Campaign not found or no longer accepting backers."}), 404
    data = request.get_json(silent=True) or {}
    try:
        amount = float(data.get("amount"))
    except (TypeError, ValueError):
        return jsonify({"error": "amount must be a number."}), 400
    if amount <= 0:
        return jsonify({"error": "amount must be greater than zero."}), 400
    db.session.add(MicroManufacturingBacking(campaign_id=campaign_id, backer_id=user["id"], amount=amount))
    db.session.commit()
    refreshed = campaign.to_dict()
    if refreshed["raised_amount"] >= campaign.goal_amount and campaign.status == "active":
        campaign.status = "funded"
        db.session.commit()
        refreshed = campaign.to_dict()
    return jsonify({"ok": True, "campaign": refreshed}), 201


# ---------- 467e: SUPPLIER APPRENTICESHIP / TRAINING EXCHANGE ----------
# Suppliers post open apprenticeship or skills-training slots; workers
