# ---------- 467f: BUYER GROUP CO-OP PURCHASING ----------
# Buyers pool orders on one product to collectively reach a
# volume-discount minimum order quantity. Any buyer can start a group
# against a real Product; other buyers commit a quantity; once
# committed quantities reach the target, the group flips to
# "target_met" so the initiator can proceed to place the bulk order.

class CoopPurchaseGroup(db.Model):
    __tablename__    = "coop_purchase_groups"
    id               = db.Column(db.Integer, primary_key=True)
    initiator_id     = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    product_id       = db.Column(db.Integer, db.ForeignKey("products.id"), nullable=False, index=True)
    target_quantity  = db.Column(db.Integer, nullable=False)
    discount_note    = db.Column(db.String(300), nullable=True)
    deadline         = db.Column(db.DateTime, nullable=True)
    status           = db.Column(db.String(16), nullable=False, default="open")  # open, target_met, closed
    created_at       = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        committed = db.session.query(db.func.coalesce(db.func.sum(CoopPurchaseCommitment.quantity), 0)) \
            .filter(CoopPurchaseCommitment.group_id == self.id).scalar() or 0
        return {"id": self.id, "initiator_id": self.initiator_id, "product_id": self.product_id,
                "target_quantity": self.target_quantity, "committed_quantity": int(committed),
                "discount_note": self.discount_note,
                "deadline": self.deadline.isoformat() if self.deadline else None, "status": self.status,
                "created_at": self.created_at.isoformat() if self.created_at else None}


class CoopPurchaseCommitment(db.Model):
    __tablename__ = "coop_purchase_commitments"
    id           = db.Column(db.Integer, primary_key=True)
    group_id     = db.Column(db.Integer, db.ForeignKey("coop_purchase_groups.id"), nullable=False, index=True)
    buyer_id     = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    quantity     = db.Column(db.Integer, nullable=False)
    committed_at = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        return {"id": self.id, "group_id": self.group_id, "buyer_id": self.buyer_id, "quantity": self.quantity,
                "committed_at": self.committed_at.isoformat() if self.committed_at else None}


@app.route("/api/coop-purchasing/groups", methods=["POST"])
@csrf.exempt
def coop_group_create():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user: return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    product = Product.query.get(data.get("product_id"))
    try:
        target_quantity = int(data.get("target_quantity"))
    except (TypeError, ValueError):
        return jsonify({"error": "product_id and a numeric target_quantity are required."}), 400
    if not product or target_quantity <= 0:
        return jsonify({"error": "product_id and a numeric target_quantity are required."}), 400
    deadline = None
    try:
        if data.get("deadline"): deadline = datetime.fromisoformat(data["deadline"])
    except (ValueError, TypeError):
        deadline = None
    group = CoopPurchaseGroup(
        initiator_id=user["id"], product_id=product.id, target_quantity=target_quantity,
        discount_note=(data.get("discount_note") or "").strip()[:300] or None, deadline=deadline,
    )
    db.session.add(group)
    db.session.commit()
    return jsonify({"ok": True, "group": group.to_dict()}), 201


