@app.route("/api/coop-purchasing/groups/<int:group_id>/commit", methods=["POST"])
@csrf.exempt
def coop_group_commit(group_id):
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user: return jsonify({"error": "Login required."}), 401
    group = CoopPurchaseGroup.query.get(group_id)
    if not group or group.status == "closed":
        return jsonify({"error": "Co-op purchase group not found or closed."}), 404
    data = request.get_json(silent=True) or {}
    try:
        quantity = int(data.get("quantity"))
    except (TypeError, ValueError):
        return jsonify({"error": "quantity must be a whole number."}), 400
    if quantity <= 0:
        return jsonify({"error": "quantity must be greater than zero."}), 400
    db.session.add(CoopPurchaseCommitment(group_id=group_id, buyer_id=user["id"], quantity=quantity))
    db.session.commit()
    refreshed = group.to_dict()
    if refreshed["committed_quantity"] >= group.target_quantity and group.status == "open":
        group.status = "target_met"
        db.session.commit()
        refreshed = group.to_dict()
    return jsonify({"ok": True, "group": refreshed}), 201


