# ============================================================
# STAGE 468: LOCAL NETWORK PRINTER DISCOVERY, BARCODE LABEL
# GENERATOR + PRINTER PAIRING, ALL-IN-ONE POS REGISTER MODE, and
# LOYALTY CARD SCAN AT TILL.
# (White-label storefront builder was already fully built end to
# end -- Stage 309's BusinessBranding + public /store/<slug> page
# with the real product catalog, plus the existing "Business
# Branding" panel as the builder UI -- so nothing new was added
# for that item; a colliding duplicate /store/<slug> route that
# had briefly been added here has been removed. Offline POS with
# sync-on-reconnect also already existed end-to-end via the
# Stage 118 queuedFetch()/offline-queue system, which
# posCheckout() already calls -- see the frontend's POS panel for
# the new visible pending-sync indicator added in this stage.)
# ============================================================

# ---------- 468b: LOCAL NETWORK PRINTER DISCOVERY ----------
# Scans an IP range on the caller's own local subnet for SNMP-
# speaking printers, reusing the same SNMP GET the Stage 324 printer
# monitor already uses. A cloud-hosted server has no visibility into
# a browser's LAN, so the subnet has to be supplied by someone
# actually on that network (typically 192.168.x / 10.x); capped to
# 64 hosts per scan with a short per-host timeout so one scan can't
# hang the request.

def _printer_discover_scan(base_ip, start, end, community="public"):
    if not PYSNMP_AVAILABLE:
        return [], "SNMP support is not installed on the server (pip install pysnmp)."
    import concurrent.futures
    def probe(host):
        val = _snmp_get(host, community, SNMP_OID_DEVICE_STATUS, 161, "2c", timeout=1)
        if val is None:
            val = _snmp_get(host, community, SNMP_OID_PRINTER_STATUS, 161, "2c", timeout=1)
        return host if val is not None else None
    hosts = [base_ip + "." + str(i) for i in range(start, end + 1)]
    found = []
    with concurrent.futures.ThreadPoolExecutor(max_workers=32) as ex:
        for host, result in zip(hosts, ex.map(probe, hosts)):
            if result:
                found.append(result)
    return found, None


@app.route("/api/devices/printers/discover", methods=["POST"])
@csrf.exempt
def printer_discover():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user: return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    base_ip = (data.get("base_ip") or "").strip()
    parts = base_ip.split(".")
    if len(parts) != 3 or not all(p.isdigit() and 0 <= int(p) <= 255 for p in parts):
        return jsonify({"error": "base_ip must be the first three octets of your local subnet, e.g. 192.168.1"}), 400
    try:
        start = max(1, int(data.get("start", 1)))
        end = min(254, int(data.get("end", 254)))
    except (TypeError, ValueError):
        start, end = 1, 254
    if end < start: start, end = end, start
    if end - start > 63: end = start + 63
    community = (data.get("community") or "public").strip()[:120]
    found, err = _printer_discover_scan(base_ip, start, end, community)
    if err:
        return jsonify({"error": err}), 400
    existing_hosts = {p.host for p in PrinterDevice.query.filter_by(user_id=user["id"]).all()}
    return jsonify({"ok": True, "found": [{"host": h, "already_added": h in existing_hosts} for h in found],
                     "scanned": end - start + 1}), 200


# ---------- 468c: BARCODE LABEL GENERATOR + PRINTER PAIRING ----------
# Renders a scannable label (QR-encoded, reusing the same `qrcode`
# library the platform's other QR routes already depend on, rather
# than a hand-built Code128 bar-width table that would risk producing
# an unscannable barcode) for any InventoryItem, printable straight
# from the browser or pushed as raw ZPL to a paired network label
# printer (Zebra-compatible printers accept raw ZPL on TCP port 9100).
# The existing camera-based "Scan Barcode" feature (html5-qrcode)
# already reads QR codes as well as linear barcodes, so labels from
# this generator scan the same way products' printed UPC/EAN codes do.

@app.route("/api/erp/inventory/<int:item_id>/label", methods=["GET"])
def erp_inventory_label(item_id):
    user = _get_current_user()
    if not user: return jsonify({"error": "Login required."}), 401
    item = InventoryItem.query.filter_by(id=item_id, user_id=user["id"]).first()
    if not item: return jsonify({"error": "Item not found."}), 404
    if not QRCODE_AVAILABLE:
        return jsonify({"error": "Label rendering is not installed on the server (pip install qrcode[pil])."}), 503
    code_value = item.barcode or item.sku or ("ITEM-" + str(item.id))
    qr = qrcode.QRCode(box_size=6, border=2, error_correction=ERROR_CORRECT_M)
    qr.add_data(code_value)
    qr.make(fit=True)
    qr_img = qr.make_image(fill_color="black", back_color="white").convert("RGB")
    try:
        from PIL import Image, ImageDraw
        label = Image.new("RGB", (max(qr_img.width, 220), qr_img.height + 50), "white")
        label.paste(qr_img, (0, 0))
        draw = ImageDraw.Draw(label)
        draw.text((4, qr_img.height + 4), (item.name or "")[:34], fill="black")
        draw.text((4, qr_img.height + 24), code_value[:34], fill="black")
        buf = io.BytesIO()
        label.save(buf, format="PNG")
    except Exception:
        buf = io.BytesIO()
        qr_img.save(buf, format="PNG")
    buf.seek(0)
    resp = Response(buf.getvalue(), mimetype="image/png")
    resp.headers["Content-Disposition"] = "inline; filename=label-" + str(item.id) + ".png"
    return resp


@app.route("/api/devices/printers/<int:printer_id>/print-label", methods=["POST"])
@csrf.exempt
def printer_print_label(printer_id):
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user: return jsonify({"error": "Login required."}), 401
    printer = PrinterDevice.query.filter_by(id=printer_id, user_id=user["id"]).first()
    if not printer: return jsonify({"error": "Printer not found."}), 404
    data = request.get_json(silent=True) or {}
    item = InventoryItem.query.filter_by(id=data.get("item_id"), user_id=user["id"]).first()
    if not item: return jsonify({"error": "item_id must reference one of your inventory items."}), 400
    code_value = item.barcode or item.sku or ("ITEM-" + str(item.id))
    name = (item.name or "")[:32].replace("^", "").replace("~", "")
    zpl = ("^XA\n^FO20,20^BQN,2,5\n^FDQA," + code_value + "^FS\n"
           "^FO160,30^A0N,28,28^FD" + name + "^FS\n"
           "^FO160,65^A0N,22,22^FD" + code_value + "^FS\n^XZ\n")
    import socket as _socket
    try:
        with _socket.create_connection((printer.host, 9100), timeout=4) as s:
            s.sendall(zpl.encode("utf-8"))
    except Exception as e:
        return jsonify({"ok": False, "error": "Could not reach " + printer.name + " for direct printing (" +
                         str(e) + "). Use the browser Print button instead for non-ZPL printers."}), 502
    return jsonify({"ok": True, "message": "Label sent to " + printer.name}), 200


# ---------- 468d: LOYALTY CARD SCAN/SWIPE AT TILL ----------
# A cashier scans a printed/QR loyalty card's code (via the same
# "pos-barcode" scan field the register already uses for products,
# see the frontend change) and it resolves straight to the
# customer's phone number, which the existing checkout loyalty
# lookup (by phone) already uses -- no changes needed on the
# checkout side itself.

@app.route("/api/loyalty/customers/<int:customer_id>/card", methods=["POST"])
@csrf.exempt
def loyalty_customer_set_card(customer_id):
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user: return jsonify({"error": "Login required."}), 401
    customer = LoyaltyCustomer.query.get(customer_id)
    program = LoyaltyProgram.query.get(customer.program_id) if customer else None
    if not customer or not program or program.owner_id != user["id"]:
        return jsonify({"error": "Loyalty customer not found."}), 404
    code = (request.get_json(silent=True) or {}).get("card_code", "").strip()[:64]
    if not code: return jsonify({"error": "card_code is required."}), 400
    clash = LoyaltyCustomer.query.filter(LoyaltyCustomer.card_code == code, LoyaltyCustomer.id != customer.id).first()
    if clash: return jsonify({"error": "That card code is already assigned to another customer."}), 409
    customer.card_code = code
    db.session.commit()
    return jsonify({"ok": True, "customer": customer.to_dict()}), 200


