    code = (request.args.get("code") or "").strip()[:64]
    if not code: return jsonify({"error": "code is required."}), 400
    customer = (LoyaltyCustomer.query.join(LoyaltyProgram, LoyaltyCustomer.program_id == LoyaltyProgram.id)
                .filter(LoyaltyCustomer.card_code == code, LoyaltyProgram.owner_id == user["id"]).first())
    if not customer:
        return jsonify({"ok": False, "error": "No loyalty customer found for that card."}), 404
    return jsonify({"ok": True, "customer": customer.to_dict()}), 200


