# ════════════════════════════════════════════════════════════
# STAGE 469: MULTI-LEG SHIPMENT MILESTONE TRACKER
# A single shipment often moves through several physical legs before
# it reaches the buyer (factory -> origin port by road, origin port ->
# destination port by sea, destination port -> warehouse by road, for
# example). The existing FreightShipment/ContainerTrackingEvent models
# (Stage 502) track one mode/one leg at a time; this stage adds a
# parent "MultiLegShipment" that groups an ordered sequence of legs,
# each with its own mode, carrier, planned/actual times and a
# milestone status, plus an aggregate progress view so a seller can
# see the whole journey — and which leg it's currently stuck on — at
# a glance instead of piecing it together from separate shipments.
# ════════════════════════════════════════════════════════════

SHIPMENT_LEG_MILESTONES = [
    "booked", "in_transit", "arrived", "delayed", "completed",
]
SHIPMENT_LEG_MODES = ["air", "sea", "rail", "road"]


class MultiLegShipment(db.Model):
    __tablename__  = "multi_leg_shipments"
    id             = db.Column(db.Integer, primary_key=True)
    owner_user_id  = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    title          = db.Column(db.String(200), nullable=False)
    order_id       = db.Column(db.Integer, db.ForeignKey("product_orders.id"), nullable=True)
    origin         = db.Column(db.String(160), nullable=True)
    final_destination = db.Column(db.String(160), nullable=True)
    notes          = db.Column(db.Text, nullable=True)
    created_at     = db.Column(db.DateTime, default=datetime.utcnow, index=True)

    def to_dict(self, include_legs=False):
        legs = (ShipmentLeg.query.filter_by(multi_leg_shipment_id=self.id)
                .order_by(ShipmentLeg.sequence.asc()).all())
        total = len(legs)
        completed = sum(1 for l in legs if l.milestone == "completed")
        current_leg = next((l for l in legs if l.milestone != "completed"), None)
        delayed = any(l.milestone == "delayed" for l in legs)
        d = {
            "id": self.id, "title": self.title, "order_id": self.order_id,
            "origin": self.origin, "final_destination": self.final_destination,
            "notes": self.notes, "created_at": self.created_at.isoformat() if self.created_at else None,
            "leg_count": total, "legs_completed": completed,
            "progress_pct": round((completed / total) * 100, 1) if total else 0.0,
            "current_leg_id": current_leg.id if current_leg else None,
            "current_leg_label": (current_leg.origin + " -> " + current_leg.destination) if current_leg else None,
            "overall_status": "completed" if total and completed == total
                               else ("delayed" if delayed else ("in_progress" if total else "no_legs_yet")),
        }
        if include_legs:
            d["legs"] = [l.to_dict() for l in legs]
        return d


class ShipmentLeg(db.Model):
    __tablename__          = "shipment_legs"
    id                     = db.Column(db.Integer, primary_key=True)
    multi_leg_shipment_id  = db.Column(db.Integer, db.ForeignKey("multi_leg_shipments.id"), nullable=False, index=True)
    sequence               = db.Column(db.Integer, nullable=False, default=1)
    mode                   = db.Column(db.String(16), nullable=False)  # air, sea, rail, road
    carrier_name           = db.Column(db.String(160), nullable=True)
    reference_number       = db.Column(db.String(120), nullable=True)
    origin                 = db.Column(db.String(160), nullable=False)
    destination            = db.Column(db.String(160), nullable=False)
    planned_depart         = db.Column(db.DateTime, nullable=True)
    planned_arrive         = db.Column(db.DateTime, nullable=True)
    actual_depart          = db.Column(db.DateTime, nullable=True)
    actual_arrive          = db.Column(db.DateTime, nullable=True)
    milestone              = db.Column(db.String(16), nullable=False, default="booked")
    notes                  = db.Column(db.String(300), nullable=True)
    updated_at             = db.Column(db.DateTime, default=datetime.utcnow, onupdate=datetime.utcnow)

    def to_dict(self):
        return {
            "id": self.id, "multi_leg_shipment_id": self.multi_leg_shipment_id, "sequence": self.sequence,
            "mode": self.mode, "carrier_name": self.carrier_name, "reference_number": self.reference_number,
            "origin": self.origin, "destination": self.destination,
            "planned_depart": self.planned_depart.isoformat() if self.planned_depart else None,
            "planned_arrive": self.planned_arrive.isoformat() if self.planned_arrive else None,
            "actual_depart": self.actual_depart.isoformat() if self.actual_depart else None,
            "actual_arrive": self.actual_arrive.isoformat() if self.actual_arrive else None,
            "milestone": self.milestone, "notes": self.notes,
            "updated_at": self.updated_at.isoformat() if self.updated_at else None,
        }


def _parse_iso_dt_or_none(value):
    if not value:
        return None
    try:
        return datetime.fromisoformat(value)
    except (TypeError, ValueError):
        return None


