@app.route("/api/logistics/multi-leg-shipments/<int:shipment_id>/legs", methods=["POST"])
@csrf.exempt
def shipment_leg_create(shipment_id):
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user: return jsonify({"error": "Login required."}), 401
    parent = MultiLegShipment.query.filter_by(id=shipment_id, owner_user_id=user["id"]).first()
    if not parent: return jsonify({"error": "Shipment not found."}), 404
    data = request.get_json(silent=True) or {}
    mode = (data.get("mode") or "").strip().lower()[:16]
    origin = (data.get("origin") or "").strip()[:160]
    destination = (data.get("destination") or "").strip()[:160]
    if mode not in SHIPMENT_LEG_MODES or not (origin and destination):
        return jsonify({"error": "mode (air/sea/rail/road), origin and destination are required."}), 400
    existing_count = ShipmentLeg.query.filter_by(multi_leg_shipment_id=shipment_id).count()
    leg = ShipmentLeg(
        multi_leg_shipment_id=shipment_id,
        sequence=int(data["sequence"]) if str(data.get("sequence", "")).isdigit() else existing_count + 1,
        mode=mode, carrier_name=(data.get("carrier_name") or "").strip()[:160] or None,
        reference_number=(data.get("reference_number") or "").strip()[:120] or None,
        origin=origin, destination=destination,
        planned_depart=_parse_iso_dt_or_none(data.get("planned_depart")),
        planned_arrive=_parse_iso_dt_or_none(data.get("planned_arrive")),
        notes=(data.get("notes") or "").strip()[:300] or None,
    )
    db.session.add(leg)
    db.session.commit()
    return jsonify({"ok": True, "leg": leg.to_dict(), "shipment": parent.to_dict()}), 201


@app.route("/api/logistics/shipment-legs/<int:leg_id>/milestone", methods=["POST"])
@csrf.exempt
def shipment_leg_update_milestone(leg_id):
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user: return jsonify({"error": "Login required."}), 401
    leg = ShipmentLeg.query.get(leg_id)
    parent = MultiLegShipment.query.get(leg.multi_leg_shipment_id) if leg else None
    if not leg or not parent or parent.owner_user_id != user["id"]:
        return jsonify({"error": "Leg not found."}), 404
    data = request.get_json(silent=True) or {}
    milestone = (data.get("milestone") or "").strip().lower()
    if milestone not in SHIPMENT_LEG_MILESTONES:
        return jsonify({"error": "milestone must be one of: " + ", ".join(SHIPMENT_LEG_MILESTONES)}), 400
    leg.milestone = milestone
    if data.get("actual_depart"):
        leg.actual_depart = _parse_iso_dt_or_none(data.get("actual_depart"))
    if data.get("actual_arrive"):
        leg.actual_arrive = _parse_iso_dt_or_none(data.get("actual_arrive"))
    if milestone == "in_transit" and not leg.actual_depart:
        leg.actual_depart = datetime.utcnow()
    if milestone in ("arrived", "completed") and not leg.actual_arrive:
        leg.actual_arrive = datetime.utcnow()
    if data.get("notes") is not None:
        leg.notes = (data.get("notes") or "").strip()[:300] or None
    db.session.commit()
    return jsonify({"ok": True, "leg": leg.to_dict(), "shipment": parent.to_dict()}), 200


