# ════════════════════════════════════════════════════════════
# STAGE 470: SCHEDULED EMAIL / PDF REPORT DIGESTS
# Lets a business subscribe to a recurring summary (sales, inventory,
# or payroll) delivered by email and/or as a downloadable PDF, on a
# daily/weekly/monthly cadence, instead of having to open the
# relevant dashboard and check manually. There is no long-running
# process on this deployment target to fire timers on its own, so
# — same honest, degrade-gracefully pattern used elsewhere in this
# file (see the printer-discovery note above) — /run-due is the
# endpoint an external scheduler (a real OS cron job, PythonAnywhere's
# scheduled tasks, or a Cloud Run/Cloud Scheduler job) should call
# periodically (e.g. once an hour); it sends every digest that's
# actually due and reschedules it. A manual "Send now" endpoint is
# also provided for on-demand use and testing.
# ════════════════════════════════════════════════════════════

REPORT_DIGEST_TYPES = ["sales_summary", "inventory_summary", "payroll_summary", "shipment_summary"]
REPORT_DIGEST_FREQUENCIES = ["daily", "weekly", "monthly"]
REPORT_DIGEST_FORMATS = ["email", "pdf", "both"]


class ReportDigestSubscription(db.Model):
    __tablename__   = "report_digest_subscriptions"
    id              = db.Column(db.Integer, primary_key=True)
    owner_user_id   = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    report_type     = db.Column(db.String(30), nullable=False)
    frequency       = db.Column(db.String(10), nullable=False, default="weekly")
    delivery_format = db.Column(db.String(10), nullable=False, default="email")
    recipient_email = db.Column(db.String(200), nullable=False)
    active          = db.Column(db.Boolean, nullable=False, default=True, index=True)
    last_sent_at    = db.Column(db.DateTime, nullable=True)
    next_run_at     = db.Column(db.DateTime, nullable=False, default=datetime.utcnow, index=True)
    created_at      = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        return {
            "id": self.id, "report_type": self.report_type, "frequency": self.frequency,
            "delivery_format": self.delivery_format, "recipient_email": self.recipient_email,
            "active": self.active,
            "last_sent_at": self.last_sent_at.isoformat() if self.last_sent_at else None,
            "next_run_at": self.next_run_at.isoformat() if self.next_run_at else None,
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }


class ReportDigestRun(db.Model):
    __tablename__   = "report_digest_runs"
    id              = db.Column(db.Integer, primary_key=True)
    subscription_id = db.Column(db.Integer, db.ForeignKey("report_digest_subscriptions.id"), nullable=False, index=True)
    sent_at         = db.Column(db.DateTime, default=datetime.utcnow)
    email_sent      = db.Column(db.Boolean, nullable=False, default=False)
    pdf_generated   = db.Column(db.Boolean, nullable=False, default=False)
    summary_text    = db.Column(db.Text, nullable=True)

    def to_dict(self):
        return {"id": self.id, "subscription_id": self.subscription_id,
                "sent_at": self.sent_at.isoformat() if self.sent_at else None,
                "email_sent": self.email_sent, "pdf_generated": self.pdf_generated,
                "summary_text": self.summary_text}


def _report_digest_next_run(frequency, from_dt=None):
    base = from_dt or datetime.utcnow()
    if frequency == "daily":
        return base + timedelta(days=1)
    if frequency == "monthly":
        return base + timedelta(days=30)
    return base + timedelta(days=7)  # weekly default


def _report_digest_build_content(owner_user_id, report_type):
    """Builds real report title/lines from this business's own data —
    no synthetic numbers. Returns (title, [line strings])."""
    if report_type == "sales_summary":
        since = datetime.utcnow() - timedelta(days=30)
        sales = (PosSale.query.filter_by(owner_user_id=owner_user_id, voided=False)
                 .filter(PosSale.created_at >= since).all())
        total = round(sum(s.total for s in sales), 2)
        count = len(sales)
        avg = round(total / count, 2) if count else 0.0
        title = "Sales Summary — Last 30 Days"
        lines = [
            "Sales recorded: " + str(count),
            "Total revenue: " + str(total),
            "Average sale: " + str(avg),
        ]
        return title, lines
    if report_type == "inventory_summary":
        items = InventoryItem.query.filter_by(user_id=owner_user_id).all()
        low_stock = [i for i in items if (i.threshold or 0) and i.quantity <= i.threshold]
        title = "Inventory Summary"
        lines = [
            "Items tracked: " + str(len(items)),
            "Items at or below reorder threshold: " + str(len(low_stock)),
        ] + ["  - " + (i.name or "Unnamed item") + ": " + str(i.quantity) + " on hand" for i in low_stock[:20]]
        return title, lines
    if report_type == "payroll_summary":
        employees = ErpEmployee.query.filter_by(owner_user_id=owner_user_id, status="active").all()
        total_gross = round(sum((e.salary or 0) for e in employees), 2)
        title = "Payroll Summary"
        lines = [
            "Active employees: " + str(len(employees)),
            "Combined gross per pay period (mixed frequencies, unadjusted): " + str(total_gross),
        ]
        return title, lines
    if report_type == "shipment_summary":
        shipments = MultiLegShipment.query.filter_by(owner_user_id=owner_user_id).all()
        in_progress = [s for s in shipments if s.to_dict()["overall_status"] == "in_progress"]
        delayed = [s for s in shipments if s.to_dict()["overall_status"] == "delayed"]
        title = "Shipment Summary"
        lines = [
            "Multi-leg shipments tracked: " + str(len(shipments)),
            "In progress: " + str(len(in_progress)),
            "Delayed: " + str(len(delayed)),
        ]
        return title, lines
    return "Report", ["Unknown report type."]


def _report_digest_render_pdf(title, lines):
    if not REPORTLAB_AVAILABLE:
        return None
    buf = io.BytesIO()
    doc = SimpleDocTemplate(buf, pagesize=A4, rightMargin=40, leftMargin=40, topMargin=50, bottomMargin=40)
    styles = getSampleStyleSheet()
    story = [Paragraph(title, styles["Title"]), Spacer(1, 12)]
    for line in lines:
        safe = escape(line)
        story.append(Paragraph(safe, styles["Normal"]))
        story.append(Spacer(1, 6))
    doc.build(story)
    buf.seek(0)
    return buf


def _report_digest_send(sub):
    """Generates the report and sends/records it per delivery_format.
    Returns a ReportDigestRun row."""
    title, lines = _report_digest_build_content(sub.owner_user_id, sub.report_type)
    summary_text = "\n".join(lines)
    email_sent = False
    pdf_generated = False
    if sub.delivery_format in ("email", "both"):
        html_body = "<h2>" + escape(title) + "</h2><ul>" + "".join(
            "<li>" + escape(l) + "</li>" for l in lines) + "</ul>"
        email_sent = _office_send_email(sub.recipient_email, title, html_body)
    if sub.delivery_format in ("pdf", "both"):
        pdf_generated = REPORTLAB_AVAILABLE
    run = ReportDigestRun(subscription_id=sub.id, email_sent=email_sent,
                           pdf_generated=pdf_generated, summary_text=summary_text)
    db.session.add(run)
    sub.last_sent_at = datetime.utcnow()
    sub.next_run_at = _report_digest_next_run(sub.frequency, sub.last_sent_at)
    db.session.commit()
    return run


@app.route("/api/reports/digests", methods=["POST"])
@csrf.exempt
def report_digest_create():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user: return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    report_type = (data.get("report_type") or "").strip()
    frequency = (data.get("frequency") or "weekly").strip()
    delivery_format = (data.get("delivery_format") or "email").strip()
    recipient_email = (data.get("recipient_email") or user.get("email") or "").strip()[:200]
    if report_type not in REPORT_DIGEST_TYPES:
        return jsonify({"error": "report_type must be one of: " + ", ".join(REPORT_DIGEST_TYPES)}), 400
    if frequency not in REPORT_DIGEST_FREQUENCIES:
        return jsonify({"error": "frequency must be one of: " + ", ".join(REPORT_DIGEST_FREQUENCIES)}), 400
    if delivery_format not in REPORT_DIGEST_FORMATS:
        return jsonify({"error": "delivery_format must be one of: " + ", ".join(REPORT_DIGEST_FORMATS)}), 400
    if not recipient_email:
        return jsonify({"error": "recipient_email is required."}), 400
    row = ReportDigestSubscription(
        owner_user_id=user["id"], report_type=report_type, frequency=frequency,
        delivery_format=delivery_format, recipient_email=recipient_email,
        next_run_at=_report_digest_next_run(frequency),
    )
    db.session.add(row)
    db.session.commit()
    return jsonify({"ok": True, "subscription": row.to_dict()}), 201


