@csrf.exempt
def report_digest_send_now(sub_id):
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user: return jsonify({"error": "Login required."}), 401
    row = ReportDigestSubscription.query.filter_by(id=sub_id, owner_user_id=user["id"]).first()
    if not row: return jsonify({"error": "Subscription not found."}), 404
