@app.route("/api/data-marketplace/earnings/request-payout", methods=["POST"])
@csrf.exempt
def data_marketplace_request_payout():
    if not _csrf_ok():
        return jsonify({"error": "Invalid request origin."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    account = UserAccount.query.get(user["id"])
    if not account.stripe_connect_account_id or not account.stripe_connect_payouts_enabled:
        return jsonify({"error": "Connect a Stripe account under Integrations before requesting a payout."}), 400
    if not STRIPE_SECRET_KEY:
        return jsonify({"error": "Stripe isn't configured on this platform yet, so payouts can't be sent."}), 400
    pending = DataMarketplaceEarning.query.filter_by(user_id=user["id"], status="pending").all()
    total_cents = sum(r.amount_cents for r in pending)
    if total_cents <= 0:
        return jsonify({"error": "No pending balance to pay out."}), 400
    try:
        import stripe
        stripe.api_key = STRIPE_SECRET_KEY
        transfer = stripe.Transfer.create(
            amount=total_cents, currency="usd", destination=account.stripe_connect_account_id,
            metadata={"purpose": "data_marketplace_revenue_share", "user_id": str(user["id"])},
        )
    except Exception as e:
        for r in pending:
            r.payout_error = str(e)[:300]
        db.session.commit()
        return jsonify({"error": f"Payout failed: {e}"}), 400
    for r in pending:
        r.status = "paid"
        r.stripe_transfer_id = transfer.id
        r.paid_at = datetime.utcnow()
        r.payout_error = None
    db.session.commit()
    return jsonify({"ok": True, "paid_cents": total_cents, "stripe_transfer_id": transfer.id}), 200


