# ---------------------------------------------------------------
# 514b (roadmap item 2): MULTILINGUAL VOICE-TO-TEXT SUPPORT BOT
# A visitor or user records a support question in any language.
# Real Whisper transcription (auto-detects the spoken language, same
# call shape as the existing meeting-transcribe endpoint) -> if not
# English, real AI translation to English via generate_ai_reply ->
# an AI support answer scoped to explaining how Connect It works ->
# translated back to the caller's own language -> optionally
# synthesised to speech with the existing real Google TTS integration.
# Every step is a real call to a real provider; nothing here is a
# canned script.
# ---------------------------------------------------------------

class VoiceSupportQuery(db.Model):
    __tablename__   = "voice_support_queries"
    id              = db.Column(db.Integer, primary_key=True)
    user_id         = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=True, index=True)
    detected_language = db.Column(db.String(20), nullable=True)
    question_text_en  = db.Column(db.Text, nullable=True)
    answer_text_en    = db.Column(db.Text, nullable=True)
    answer_text_local = db.Column(db.Text, nullable=True)
    created_at      = db.Column(db.DateTime, default=datetime.utcnow, index=True)

    def to_dict(self):
        return {"id": self.id, "detected_language": self.detected_language,
                "question_text_en": self.question_text_en, "answer_text_local": self.answer_text_local,
                "created_at": self.created_at.isoformat() if self.created_at else None}


_VOICE_SUPPORT_SYSTEM_PROMPT = (
    "You are the Connect It platform support assistant. Answer the user's "
    "question about how to use Connect It's features (chat tools, "
    "marketplace, ERP/CRM, payments, invoicing, escrow, logistics, and the "
    "other business tools on the platform) clearly and concisely, in "
    "English, in 3-6 sentences. If the question isn't about using the "
    "platform, answer it helpfully anyway but note you're primarily a "
    "platform support assistant."
)


@app.route("/api/support/voice-query", methods=["POST"])
@csrf.exempt
def voice_support_query():
    """No login required — this is meant to also serve prospective
    visitors evaluating the platform, not only signed-in users."""
    if 'audio' not in request.files:
        return jsonify({"error": "No audio file provided."}), 400
    audio_file = request.files['audio']
    if not audio_file.filename:
        return jsonify({"error": "Empty audio file."}), 400

    current_user = _get_current_user()
    current_uid = current_user.get('id') if current_user else None
    byok_key = get_effective_credential(current_uid, 'openai', 'api_key', None)
    client = OpenAI(api_key=byok_key) if byok_key else openai_client
    if not client:
        return jsonify({"error": "Voice transcription isn't configured on this platform yet."}), 503

    # STAGE (metering gap fix): anonymous access here is intentional (see
    # docstring above) — meter signed-in callers, rate-limit anonymous
    # ones by IP instead, before the paid Whisper STT call fires either way.
    if current_user:
        gate_result = gate_ai_usage(current_user, "voice_support_query")
        if gate_result is not None:
            return gate_result
    elif _rate_limited(f"voice_support:ip:{_client_ip()}", max_attempts=10, window_seconds=3600):
        return jsonify({"error": "Too many requests. Please try again later."}), 429

    with tempfile.NamedTemporaryFile(delete=False, suffix='.webm') as tmp:
        audio_file.save(tmp.name)
        tmp_path = tmp.name
    try:
        with open(tmp_path, 'rb') as f:
            stt_result = client.audio.transcriptions.create(
                model='whisper-1', file=f, response_format='verbose_json')
        question_raw = stt_result.text
        detected_language = getattr(stt_result, 'language', None) or 'english'
    except Exception as e:
        logging.error(f"[VOICE SUPPORT STT] {e}")
        return jsonify({"error": str(e)}), 500
    finally:
        try: os.unlink(tmp_path)
        except Exception: pass

    if not question_raw.strip():
        return jsonify({"error": "Could not make out any speech in that recording."}), 400

    is_english = detected_language.strip().lower() in ("english", "en")
    if is_english:
        question_en = question_raw
    else:
        translate_prompt = (f"Translate the following text into English. "
                             f"Return ONLY the translated text, nothing else.\n\nTEXT:\n{question_raw}")
        question_en, _ = generate_ai_reply(translate_prompt, [])

    answer_en, _ = generate_ai_reply(question_en, [], system_prompt=_VOICE_SUPPORT_SYSTEM_PROMPT)

    if is_english:
        answer_local = answer_en
    else:
        back_prompt = (f"Translate the following text into {detected_language}. "
                        f"Return ONLY the translated text, nothing else.\n\nTEXT:\n{answer_en}")
        answer_local, _ = generate_ai_reply(back_prompt, [])

    row = VoiceSupportQuery(user_id=current_uid, detected_language=detected_language,
                             question_text_en=question_en[:4000], answer_text_en=answer_en[:4000],
                             answer_text_local=answer_local[:4000])
    db.session.add(row)
    db.session.commit()

    return jsonify({
        "ok": True, "detected_language": detected_language,
        "question_transcript": question_raw, "question_text_en": question_en,
        "answer_text": answer_local, "answer_text_en": answer_en,
        "tts_available": GTTS_AVAILABLE,
    }), 200


@app.route("/api/support/voice-query/<int:query_id>/speak", methods=["POST"])
@csrf.exempt
def voice_support_query_speak(query_id):
    """Synthesises the stored answer back to audio in the caller's own
    language via the existing real Google TTS integration. Separate
    endpoint so text-only clients aren't forced to pay the TTS cost."""
    if not _csrf_ok():
        return jsonify({"error": "Invalid request origin."}), 403
    row = VoiceSupportQuery.query.get(query_id)
    if not row:
        return jsonify({"error": "Query not found."}), 404

    # STAGE (metering gap fix): same anonymous-by-design flow as its
    # parent /api/support/voice-query — meter if signed in, IP-rate-limit
    # if not, since this had zero protection of any kind before.
    current_user = _get_current_user()
    if current_user:
        gate_result = gate_ai_usage(current_user, "voice_support_query_speak")
        if gate_result is not None:
            return gate_result
    elif _rate_limited(f"voice_support_speak:ip:{_client_ip()}", max_attempts=20, window_seconds=3600):
        return jsonify({"error": "Too many requests. Please try again later."}), 429

    lang_map = {"english": "en-US", "french": "fr-FR", "spanish": "es-ES", "portuguese": "pt-PT",
                "swahili": "sw-KE", "shona": "en-US", "arabic": "ar-XA", "chinese": "cmn-CN",
                "hindi": "hi-IN", "zulu": "en-US"}
    lang_code = lang_map.get((row.detected_language or "").strip().lower(), "en-US")
    result = text_to_speech(row.answer_text_local or row.answer_text_en or "", user_id=None, language_code=lang_code)
    if not result.get("ok"):
        return jsonify({"error": result.get("error", "Text-to-speech failed.")}), 503
    return jsonify({"ok": True, "audio_base64": result["audio_base64"], "mime_type": result["mime_type"]}), 200


@app.route("/api/admin/support/voice-queries", methods=["GET"])
def admin_voice_support_queries():
    """Lets platform admins see what people are actually asking, and in
    which languages — useful for spotting a missing feature or a
    confusing flow before it becomes a support-ticket flood."""
    admin_user, err = _require_admin()
    if err: return err
    rows = VoiceSupportQuery.query.order_by(VoiceSupportQuery.created_at.desc()).limit(200).all()
    return jsonify({"queries": [r.to_dict() for r in rows]}), 200


# ---------------------------------------------------------------
# 514c (roadmap item 3): UNIVERSITY / INCUBATOR PARTNERSHIP PROGRAM
# A fast-tracked onboarding lane for students and early-stage
# founders, reusing the same real fee-discount mechanism Stage 388
# built for micro-sellers (_effective_platform_fee_bps) rather than
# inventing a second, disconnected discount system.
# ---------------------------------------------------------------

class UniversityPartnerApplication(db.Model):
    __tablename__       = "university_partner_applications"
    id                  = db.Column(db.Integer, primary_key=True)
    user_id             = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    institution_name    = db.Column(db.String(200), nullable=False)
    institution_email   = db.Column(db.String(200), nullable=True)
    program_type        = db.Column(db.String(20), nullable=False, default="university")  # university, incubator, accelerator
    stage_description   = db.Column(db.String(300), nullable=True)  # e.g. "final-year project", "pre-revenue"
    status               = db.Column(db.String(20), nullable=False, default="pending")  # pending, approved, rejected
    subsidy_percent      = db.Column(db.Float, nullable=False, default=0.0)
    fast_track_months    = db.Column(db.Integer, nullable=False, default=6)
    reviewed_at          = db.Column(db.DateTime, nullable=True)
    created_at           = db.Column(db.DateTime, default=datetime.utcnow, index=True)

    def to_dict(self):
        expired = False
        if self.status == "approved" and self.reviewed_at:
            expired = datetime.utcnow() > self.reviewed_at + timedelta(days=30 * self.fast_track_months)
        return {"id": self.id, "institution_name": self.institution_name,
                "institution_email": self.institution_email, "program_type": self.program_type,
                "stage_description": self.stage_description, "status": self.status,
                "subsidy_percent": self.subsidy_percent, "fast_track_months": self.fast_track_months,
                "active": self.status == "approved" and not expired,
                "created_at": self.created_at.isoformat() if self.created_at else None}


@app.route("/api/university-partner/apply", methods=["POST"])
@csrf.exempt
def university_partner_apply():
    if not _csrf_ok():
        return jsonify({"error": "Invalid request origin."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Please log in."}), 401
    data = request.get_json(silent=True) or {}
    institution_name = (data.get("institution_name") or "").strip()
    program_type = (data.get("program_type") or "university").strip().lower()
    if not institution_name:
        return jsonify({"error": "institution_name is required."}), 400
    if program_type not in ("university", "incubator", "accelerator"):
        return jsonify({"error": "program_type must be university, incubator, or accelerator."}), 400
    existing = UniversityPartnerApplication.query.filter_by(user_id=user["id"], status="pending").first()
    if existing:
        return jsonify({"error": "You already have a pending application."}), 400
    row = UniversityPartnerApplication(
        user_id=user["id"], institution_name=institution_name[:200],
        institution_email=(data.get("institution_email") or "").strip()[:200] or None,
        program_type=program_type, stage_description=(data.get("stage_description") or "").strip()[:300] or None,
    )
    db.session.add(row)
    db.session.commit()
    return jsonify({"ok": True, "application": row.to_dict()}), 201


@app.route("/api/university-partner/my-application", methods=["GET"])
def university_partner_my_application():
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Please log in."}), 401
    row = (UniversityPartnerApplication.query.filter_by(user_id=user["id"])
           .order_by(UniversityPartnerApplication.created_at.desc()).first())
    return jsonify({"application": row.to_dict() if row else None}), 200


@app.route("/api/university-partner/onboarding-checklist", methods=["GET"])
def university_partner_onboarding_checklist():
    """The actual fast-tracked flow: a shorter, prioritized checklist
    shown once an application is approved, pointing straight at the
    real setup endpoints rather than the normal-pace full onboarding."""
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Please log in."}), 401
    row = (UniversityPartnerApplication.query
           .filter_by(user_id=user["id"], status="approved")
           .order_by(UniversityPartnerApplication.created_at.desc()).first())
    if not row or not row.to_dict()["active"]:
        return jsonify({"error": "No active university/incubator fast-track for this account."}), 403
    checklist = [
        {"step": "Complete your business profile", "endpoint": "/api/business/profile"},
        {"step": "List your first product or service", "endpoint": "/api/marketplace/listings"},
        {"step": "Connect a payment method", "endpoint": "/api/payments/integrations"},
        {"step": "Set up your storefront branding", "endpoint": "/api/branding"},
        {"step": "Review your reduced platform fee", "endpoint": "/api/marketplace/fee-info"},
    ]
    return jsonify({"ok": True, "checklist": checklist, "subsidy_percent": row.subsidy_percent,
                     "fast_track_months": row.fast_track_months}), 200


