def admin_university_partner_list():
    admin_user, err = _require_admin()
    if err: return err
    status = request.args.get("status")
    q = UniversityPartnerApplication.query
    if status:
        q = q.filter_by(status=status)
    rows = q.order_by(UniversityPartnerApplication.created_at.desc()).all()
    return jsonify({"applications": [r.to_dict() for r in rows]}), 200


@app.route("/api/admin/university-partner/applications/<int:app_id>/review", methods=["POST"])
@csrf.exempt
def admin_university_partner_review(app_id):
    if not _csrf_ok(): return jsonify({"error": "Invalid request origin."}), 403
    admin_user, err = _require_admin()
    if err: return err
    row = UniversityPartnerApplication.query.get(app_id)
    if not row:
        return jsonify({"error": "Application not found."}), 404
    data = request.get_json(silent=True) or {}
    decision = (data.get("decision") or "").strip().lower()
    if decision not in ("approved", "rejected"):
        return jsonify({"error": "decision must be approved or rejected."}), 400
    row.status = decision
    row.reviewed_at = datetime.utcnow()
    if decision == "approved":
        try:
            row.subsidy_percent = max(0.0, min(100.0, float(data.get("subsidy_percent", 50.0))))
        except (TypeError, ValueError):
            row.subsidy_percent = 50.0
        try:
            row.fast_track_months = max(1, int(data.get("fast_track_months", 6)))
        except (TypeError, ValueError):
            row.fast_track_months = 6
        notify_user(row.user_id, "university_partner",
                     "Your university/incubator application was approved",
                     f"Your platform fee is reduced by {row.subsidy_percent:.0f}% for {row.fast_track_months} months. "
                     f"Check your fast-track onboarding checklist to get started.")
    db.session.commit()
    return jsonify({"ok": True, "application": row.to_dict()}), 200


# Wires the approved discount into the same real fee-charging path
# every marketplace order already uses (Stage 388's function), taking
# whichever program gives the seller the bigger discount rather than
# stacking them.
def _university_partner_discount_pct(seller_id):
    row = (UniversityPartnerApplication.query
           .filter_by(user_id=seller_id, status="approved")
           .order_by(UniversityPartnerApplication.reviewed_at.desc()).first())
    if not row or not row.to_dict()["active"]:
        return 0.0
    return row.subsidy_percent


# ---------------------------------------------------------------
# 514d (roadmap item 4): AGENCY / MULTI-TENANT SUB-MARKETPLACE MODE
# Distinct from Branch (Stage 77 — one seller's own multiple physical
# locations) and from the white-label license inquiry (Stage 436 —
# licensing the whole platform). This is an agency account that
# curates a roster of SEPARATE, independently-owned client seller
# accounts under its own branded public page. Each client keeps full
# ownership and control of their own account and storefront and must
# explicitly accept the agency's invitation; the agency never gains
# login access to a client's account or data — only a public listing
# link to whatever the client has already made public (their real
# storefront, if they have one).
# ---------------------------------------------------------------

class AgencyProfile(db.Model):
    __tablename__  = "agency_profiles"
    id             = db.Column(db.Integer, primary_key=True)
    owner_user_id  = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, unique=True, index=True)
    agency_name    = db.Column(db.String(160), nullable=False)
    slug           = db.Column(db.String(80), nullable=False, unique=True, index=True)
    logo_url       = db.Column(db.String(500), nullable=True)
    primary_color  = db.Column(db.String(7), nullable=True)
    description    = db.Column(db.String(500), nullable=True)
    created_at     = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        return {"id": self.id, "agency_name": self.agency_name, "slug": self.slug,
                "logo_url": self.logo_url, "primary_color": self.primary_color,
                "description": self.description, "public_url": f"/agency/{self.slug}"}


class AgencyClientLink(db.Model):
    __tablename__   = "agency_client_links"
    id              = db.Column(db.Integer, primary_key=True)
    agency_user_id  = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    client_user_id  = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
