@app.route("/agency/<slug>", methods=["GET"])
def agency_public_page(slug):
    """Public, no-login HTML page listing every active client's real
    storefront under the agency's own branding — same rendering
    pattern as /store/<slug>. A client without a published storefront
    yet is shown honestly as not-yet-public rather than a dead or
    fabricated link."""
    profile = AgencyProfile.query.filter_by(slug=slug).first()
    if not profile:
        return render_template_string(
            "<!DOCTYPE html><html><head><meta charset=\"UTF-8\"/>"
            "<title>Agency not found</title></head><body style=\"font-family:sans-serif;"
            "text-align:center;padding:60px;\"><h1>Agency page not found</h1></body></html>"), 404
    links = AgencyClientLink.query.filter_by(agency_user_id=profile.owner_user_id, status="active").all()
    primary = profile.primary_color or "#ea580c"
    card_parts = []
    for link in links:
        branding = BusinessBranding.query.filter_by(owner_user_id=link.client_user_id).first()
        client_account = UserAccount.query.get(link.client_user_id)
        name = escape(branding.display_name if branding and branding.display_name
                       else (client_account.name if client_account else "Client"))
        logo = branding.logo_url if branding else None
        store_url = ("/store/" + branding.storefront_slug) if branding and branding.storefront_slug else None
        if logo:
            logo_tag = '<img src="' + escape(logo) + '" style="width:56px;height:56px;border-radius:10px;object-fit:cover;">'
        else:
            logo_tag = '<div style="width:56px;height:56px;border-radius:10px;background:#f1f5f9;"></div>'
        if store_url:
            card_parts.append(
                '<a href="' + escape(store_url) + '" style="text-decoration:none;color:inherit;">'
                '<div style="display:flex;gap:12px;align-items:center;background:#fff;border-radius:10px;'
                'padding:12px;box-shadow:0 1px 4px rgba(0,0,0,0.08);margin-bottom:10px;">'
                + logo_tag + '<div style="font-weight:700;color:#1e293b;">' + name + '</div></div></a>')
        else:
            card_parts.append(
                '<div style="display:flex;gap:12px;align-items:center;background:#f8fafc;'
                'border-radius:10px;padding:12px;margin-bottom:10px;opacity:0.7;">'
                + logo_tag + '<div><div style="font-weight:700;color:#1e293b;">' + name + '</div>'
                '<div style="font-size:0.78rem;color:#94a3b8;">Storefront not yet public</div></div></div>')
    cards_html = "".join(card_parts) if card_parts else '<p style="color:#94a3b8;">No client storefronts to show yet.</p>'
    desc_html = ('<p style="color:#475569;">' + escape(profile.description) + '</p>') if profile.description else ''
    html = ("<!DOCTYPE html><html><head><meta charset=\"UTF-8\"/>"
            "<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"/>"
            "<title>" + escape(profile.agency_name) + "</title>"
            "<style>body{font-family:'Segoe UI',sans-serif;background:#f1f5f9;margin:0;padding:24px;"
            "max-width:640px;margin:0 auto;}</style></head><body>"
            "<h1 style=\"color:" + escape(primary) + ";\">" + escape(profile.agency_name) + "</h1>"
            + desc_html +
            "<div style=\"margin-top:20px;\">" + cards_html + "</div>"
            "</body></html>")
    return render_template_string(html), 200


# ---------------------------------------------------------------
# 514e (roadmap item 5): CROSS-DEPARTMENT BUDGET TRACKER
# Separate from the existing UserBudgetEntry (a personal, single-
# owner income/expense log) — this is department-level allocation
# against real logged spend, with a cross-department comparison view,
# for a business with more than one cost center.
# ---------------------------------------------------------------

class Department(db.Model):
    __tablename__  = "departments"
    id             = db.Column(db.Integer, primary_key=True)
    owner_user_id  = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    name           = db.Column(db.String(120), nullable=False)
    created_at     = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        return {"id": self.id, "name": self.name,
                "created_at": self.created_at.isoformat() if self.created_at else None}


class DepartmentBudget(db.Model):
    __tablename__  = "department_budgets"
    id             = db.Column(db.Integer, primary_key=True)
    department_id  = db.Column(db.Integer, db.ForeignKey("departments.id"), nullable=False, index=True)
    period_label   = db.Column(db.String(20), nullable=False, index=True)  # e.g. "2026-08" or "2026-Q3"
    allocated_amount = db.Column(db.Float, nullable=False, default=0)
    currency       = db.Column(db.String(8), nullable=False, default="USD")
    created_at     = db.Column(db.DateTime, default=datetime.utcnow)
    __table_args__ = (db.UniqueConstraint("department_id", "period_label", name="uq_dept_budget_period"),)

    def to_dict(self):
        return {"id": self.id, "department_id": self.department_id, "period_label": self.period_label,
                "allocated_amount": self.allocated_amount, "currency": self.currency}


class DepartmentExpense(db.Model):
    __tablename__  = "department_expenses"
    id             = db.Column(db.Integer, primary_key=True)
    department_id  = db.Column(db.Integer, db.ForeignKey("departments.id"), nullable=False, index=True)
    description    = db.Column(db.String(200), nullable=False)
    amount         = db.Column(db.Float, nullable=False)
    expense_date   = db.Column(db.Date, nullable=False, default=lambda: datetime.utcnow().date())
    created_at     = db.Column(db.DateTime, default=datetime.utcnow, index=True)

    def to_dict(self):
        return {"id": self.id, "department_id": self.department_id, "description": self.description,
                "amount": self.amount, "expense_date": self.expense_date.isoformat() if self.expense_date else None}


def _dept_period_of(d: date) -> str:
    return d.strftime("%Y-%m")


