@app.route("/api/departments/<int:dept_id>/budget", methods=["POST"])
@csrf.exempt
def department_budget_set(dept_id):
    if not _csrf_ok(): return jsonify({"error": "Invalid request origin."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    dept = Department.query.filter_by(id=dept_id, owner_user_id=user["id"]).first()
    if not dept: return jsonify({"error": "Department not found."}), 404
    data = request.get_json(silent=True) or {}
    period_label = (data.get("period_label") or "").strip()
    if not period_label:
        return jsonify({"error": "period_label is required (e.g. 2026-08)."}), 400
    try:
        allocated = float(data.get("allocated_amount"))
    except (TypeError, ValueError):
        return jsonify({"error": "allocated_amount must be a number."}), 400
    row = DepartmentBudget.query.filter_by(department_id=dept.id, period_label=period_label).first()
    if not row:
        row = DepartmentBudget(department_id=dept.id, period_label=period_label)
        db.session.add(row)
    row.allocated_amount = max(0.0, allocated)
    row.currency = (data.get("currency") or row.currency or "USD")[:8]
    db.session.commit()
    return jsonify({"ok": True, "budget": row.to_dict()}), 201


@app.route("/api/departments/<int:dept_id>/expenses", methods=["GET", "POST"])
@csrf.exempt
def department_expenses(dept_id):
    user, err = _erp_user_or_401()
    if err: return err
    dept = Department.query.filter_by(id=dept_id, owner_user_id=user["id"]).first()
    if not dept: return jsonify({"error": "Department not found."}), 404
    if request.method == "GET":
        rows = DepartmentExpense.query.filter_by(department_id=dept.id).order_by(DepartmentExpense.expense_date.desc()).all()
        return jsonify({"expenses": [r.to_dict() for r in rows]}), 200
    if not _csrf_ok(): return jsonify({"error": "Invalid request origin."}), 403
    data = request.get_json(silent=True) or {}
    description = (data.get("description") or "").strip()
    try:
        amount = float(data.get("amount"))
    except (TypeError, ValueError):
        return jsonify({"error": "amount must be a number."}), 400
    if not description or amount <= 0:
        return jsonify({"error": "description is required and amount must be positive."}), 400
    expense_date = datetime.utcnow().date()
    if data.get("expense_date"):
        try: expense_date = datetime.fromisoformat(data["expense_date"]).date()
        except (TypeError, ValueError): pass
    row = DepartmentExpense(department_id=dept.id, description=description[:200],
                             amount=amount, expense_date=expense_date)
    db.session.add(row)
    db.session.commit()
    return jsonify({"ok": True, "expense": row.to_dict()}), 201


@app.route("/api/departments/budget-overview", methods=["GET"])
def departments_budget_overview():
    """The cross-department comparison view: every department's
    allocated vs. actual spend for one period, side by side."""
    user, err = _erp_user_or_401()
    if err: return err
    period_label = (request.args.get("period") or datetime.utcnow().strftime("%Y-%m")).strip()
    depts = Department.query.filter_by(owner_user_id=user["id"]).order_by(Department.name.asc()).all()
    rows = []
    total_allocated = 0.0
    total_actual = 0.0
    for d in depts:
        budget = DepartmentBudget.query.filter_by(department_id=d.id, period_label=period_label).first()
        allocated = budget.allocated_amount if budget else 0.0
        if period_label and len(period_label) == 7:  # "YYYY-MM"
            try:
                year, month = int(period_label[:4]), int(period_label[5:7])
                expenses = DepartmentExpense.query.filter(
                    DepartmentExpense.department_id == d.id,
                    db.extract("year", DepartmentExpense.expense_date) == year,
                    db.extract("month", DepartmentExpense.expense_date) == month).all()
            except (TypeError, ValueError):
                expenses = []
        else:
            expenses = []
        actual = sum(e.amount for e in expenses)
        total_allocated += allocated
        total_actual += actual
        rows.append({
            "department_id": d.id, "department_name": d.name,
            "allocated_amount": allocated, "actual_spend": actual,
            "variance": round(allocated - actual, 2),
            "pct_used": round((actual / allocated * 100), 1) if allocated else None,
        })
    return jsonify({"period": period_label, "departments": rows,
                     "total_allocated": round(total_allocated, 2), "total_actual": round(total_actual, 2),
                     "total_variance": round(total_allocated - total_actual, 2)}), 200


# ---------------------------------------------------------------
# 514f (roadmap item 6): POLICY ACKNOWLEDGMENT / COMPLIANCE SIGN-OFF LOG
# Same owner-manages-employee-records shape as the existing HR
# self-service tools (TimeClockEntry etc.) — this app has no separate
# employee login, so acknowledgment is recorded by the owning account
# against a named ErpEmployee row, with a full audit trail of who
# has and hasn't signed off on which policy version.
# ---------------------------------------------------------------

class PolicyDocument(db.Model):
    __tablename__  = "policy_documents"
    id             = db.Column(db.Integer, primary_key=True)
    owner_user_id  = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    title          = db.Column(db.String(200), nullable=False)
    content        = db.Column(db.Text, nullable=False)
    version        = db.Column(db.Integer, nullable=False, default=1)
    active         = db.Column(db.Boolean, nullable=False, default=True)
    created_at     = db.Column(db.DateTime, default=datetime.utcnow, index=True)

    def to_dict(self):
        total_employees = ErpEmployee.query.filter_by(owner_user_id=self.owner_user_id, status="active").count()
        signed = PolicyAcknowledgment.query.filter_by(policy_id=self.id).count()
        return {"id": self.id, "title": self.title, "content": self.content, "version": self.version,
                "active": self.active, "created_at": self.created_at.isoformat() if self.created_at else None,
                "total_employees": total_employees, "signed_count": signed,
                "pending_count": max(0, total_employees - signed)}


class PolicyAcknowledgment(db.Model):
    __tablename__  = "policy_acknowledgments"
    id             = db.Column(db.Integer, primary_key=True)
    policy_id      = db.Column(db.Integer, db.ForeignKey("policy_documents.id"), nullable=False, index=True)
    employee_id    = db.Column(db.Integer, db.ForeignKey("erp_employees.id"), nullable=False, index=True)
    acknowledged_at = db.Column(db.DateTime, default=datetime.utcnow)
    ip_address     = db.Column(db.String(64), nullable=True)
    __table_args__ = (db.UniqueConstraint("policy_id", "employee_id", name="uq_policy_employee_ack"),)

    def to_dict(self):
        emp = ErpEmployee.query.get(self.employee_id)
        return {"id": self.id, "employee_id": self.employee_id,
                "employee_name": emp.full_name if emp else None,
                "acknowledged_at": self.acknowledged_at.isoformat() if self.acknowledged_at else None}


@app.route("/api/compliance/policies", methods=["GET", "POST"])
@csrf.exempt
def compliance_policies():
    user, err = _erp_user_or_401()
    if err: return err
    if request.method == "GET":
        rows = PolicyDocument.query.filter_by(owner_user_id=user["id"]).order_by(PolicyDocument.created_at.desc()).all()
        return jsonify({"policies": [r.to_dict() for r in rows]}), 200
    if not _csrf_ok(): return jsonify({"error": "Invalid request origin."}), 403
    data = request.get_json(silent=True) or {}
    title = (data.get("title") or "").strip()
    content = (data.get("content") or "").strip()
    if not title or not content:
        return jsonify({"error": "title and content are required."}), 400
    row = PolicyDocument(owner_user_id=user["id"], title=title[:200], content=content[:20000])
    db.session.add(row)
    db.session.commit()
    return jsonify({"ok": True, "policy": row.to_dict()}), 201


@app.route("/api/compliance/policies/<int:policy_id>/new-version", methods=["POST"])
@csrf.exempt
def compliance_policy_new_version(policy_id):
    """A material policy change resets sign-off — a new version row is
    created and acknowledgments only ever apply to the exact version
    they were given for, so 'signed' never silently covers a change
    an employee never actually saw."""
    if not _csrf_ok(): return jsonify({"error": "Invalid request origin."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    old = PolicyDocument.query.filter_by(id=policy_id, owner_user_id=user["id"]).first()
    if not old: return jsonify({"error": "Policy not found."}), 404
    data = request.get_json(silent=True) or {}
    old.active = False
    new_row = PolicyDocument(owner_user_id=user["id"], title=old.title,
                              content=(data.get("content") or old.content)[:20000], version=old.version + 1)
    db.session.add(new_row)
    db.session.commit()
    return jsonify({"ok": True, "policy": new_row.to_dict()}), 201


@app.route("/api/compliance/policies/<int:policy_id>/acknowledge", methods=["POST"])
@csrf.exempt
def compliance_policy_acknowledge(policy_id):
    if not _csrf_ok(): return jsonify({"error": "Invalid request origin."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    policy = PolicyDocument.query.filter_by(id=policy_id, owner_user_id=user["id"]).first()
    if not policy: return jsonify({"error": "Policy not found."}), 404
    data = request.get_json(silent=True) or {}
    employee = ErpEmployee.query.filter_by(id=data.get("employee_id"), owner_user_id=user["id"]).first()
    if not employee:
        return jsonify({"error": "Employee not found."}), 404
    existing = PolicyAcknowledgment.query.filter_by(policy_id=policy.id, employee_id=employee.id).first()
    if existing:
        return jsonify({"error": "This employee already signed off on this policy version."}), 400
    row = PolicyAcknowledgment(policy_id=policy.id, employee_id=employee.id, ip_address=request.remote_addr)
    db.session.add(row)
    db.session.commit()
    return jsonify({"ok": True, "acknowledgment": row.to_dict()}), 201


@app.route("/api/compliance/policies/<int:policy_id>/sign-off-log", methods=["GET"])
def compliance_policy_sign_off_log(policy_id):
    user, err = _erp_user_or_401()
    if err: return err
    policy = PolicyDocument.query.filter_by(id=policy_id, owner_user_id=user["id"]).first()
    if not policy: return jsonify({"error": "Policy not found."}), 404
    signed = PolicyAcknowledgment.query.filter_by(policy_id=policy.id).order_by(PolicyAcknowledgment.acknowledged_at.desc()).all()
    signed_ids = {a.employee_id for a in signed}
    all_employees = ErpEmployee.query.filter_by(owner_user_id=user["id"], status="active").all()
    pending = [{"employee_id": e.id, "employee_name": e.full_name} for e in all_employees if e.id not in signed_ids]
    return jsonify({"policy": policy.to_dict(), "signed": [a.to_dict() for a in signed], "pending": pending}), 200


# ---------------------------------------------------------------
# 514g (roadmap item 7): CONTAINER TRACKING VIA A REAL CARRIER API
# Extends Stage 502's manual milestone log with a real pull from the
# Maersk Track & Trace API (public developer API, BYOK per business —
# same credential pattern as the DHL/FedEx/UPS shipping integration).
# No universal free carrier API exists across Maersk/MSC/CMA CGM, so
# rather than fake coverage this is honest per-carrier: Maersk pulls
# real live data when connected; other carriers fall back to the
# existing manual log with a clear message instead of a fabricated
# pull.
# ---------------------------------------------------------------

MAERSK_TRACK_TRACE_BASE = "https://api.maersk.com/track-and-trace-private"


@app.route("/api/logistics/container-events/pull/<container_number>", methods=["POST"])
@csrf.exempt
def container_event_pull_live(container_number):
    if not _csrf_ok(): return jsonify({"error": "Invalid request origin."}), 403
    user = _get_current_user()
    if not user: return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    carrier = (data.get("carrier") or "").strip().lower()
    if carrier != "maersk":
        return jsonify({
            "error": ("A live pull is only available for Maersk right now (BYOK). "
                      "Other carriers (MSC, CMA CGM, etc.) don't expose a usable public "
                      "tracking API, so log milestones manually below for those shipments."),
        }), 400
    creds = get_user_credentials(user["id"], "maersk_tracking")
    if not creds or not creds.get("api_key"):
        return jsonify({"error": "Connect your Maersk Developer Portal API key under Integrations first."}), 400
    try:
        resp = requests.get(
            f"{MAERSK_TRACK_TRACE_BASE}/events",
            headers={"Consumer-Key": creds["api_key"]},
            params={"equipmentReference": container_number.strip().upper()},
            timeout=15,
        )
    except Exception as e:
        logging.error(f"[MAERSK TRACK PULL] {e}")
        return jsonify({"error": f"Could not reach Maersk's API: {e}"}), 502
    if resp.status_code == 401:
        return jsonify({"error": "Maersk rejected the connected API key. Reconnect it under Integrations."}), 401
    if resp.status_code != 200:
        return jsonify({"error": f"Maersk API returned {resp.status_code}."}), 502

    try:
        events = resp.json().get("events", [])
    except Exception:
        events = []
    milestone_map = {
        "EQUIPMENT_RECEIPT": "gate_in_origin", "GATE_IN": "gate_in_origin",
        "LOAD": "loaded_on_vessel", "VESSEL_DEPARTURE": "vessel_departed",
        "VESSEL_ARRIVAL": "vessel_arrived", "DISCHARGE": "discharged",
        "GATE_OUT": "gate_out_destination", "EQUIPMENT_RETURN": "empty_returned",
    }
    created = 0
    for e in events:
        raw_type = (e.get("eventType") or e.get("transportEventTypeCode") or "").upper()
        milestone = milestone_map.get(raw_type)
        if not milestone:
            continue
        event_time_raw = e.get("eventDateTime") or e.get("eventCreatedDateTime")
        try:
            event_time = datetime.fromisoformat(event_time_raw.replace("Z", "+00:00")) if event_time_raw else datetime.utcnow()
        except Exception:
            event_time = datetime.utcnow()
        already = ContainerTrackingEvent.query.filter_by(
            owner_user_id=user["id"], container_number=container_number.strip().upper(),
            milestone=milestone, event_time=event_time).first()
        if already:
            continue
        location = None
        loc = e.get("location") or {}
        if isinstance(loc, dict):
            location = loc.get("locationName") or loc.get("UNLocationCode")
        db.session.add(ContainerTrackingEvent(
            owner_user_id=user["id"], container_number=container_number.strip().upper()[:24],
            milestone=milestone, location=(location or "")[:160] or None,
            event_time=event_time, notes="Pulled live from Maersk API"))
        created += 1
    db.session.commit()
    return jsonify({"ok": True, "events_added": created}), 200


# ---------------------------------------------------------------
# 514h (roadmap item 8): PROOF OF DELIVERY (SIGNATURE / PHOTO TIED
# TO SHIPMENT RECORDS)
# Attaches to the real ProductOrder record (and, if present, the
# container/shipment tracking tied to it) rather than a free-floating
# upload — a proof-of-delivery is only meaningful linked to a real
# order both parties can already see.
# ---------------------------------------------------------------

class ProofOfDelivery(db.Model):
    __tablename__     = "proof_of_deliveries"
    id                = db.Column(db.Integer, primary_key=True)
    order_id          = db.Column(db.Integer, db.ForeignKey("product_orders.id"), nullable=False, unique=True, index=True)
    recorded_by_user_id = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    signature_data    = db.Column(db.Text, nullable=True)    # base64 PNG from a signature pad, same as e-sign
    photo_url         = db.Column(db.String(500), nullable=True)
    recipient_name    = db.Column(db.String(160), nullable=True)
    notes             = db.Column(db.String(500), nullable=True)
    delivered_at      = db.Column(db.DateTime, default=datetime.utcnow)
    created_at        = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        return {"id": self.id, "order_id": self.order_id, "has_signature": bool(self.signature_data),
                "photo_url": self.photo_url, "recipient_name": self.recipient_name, "notes": self.notes,
                "delivered_at": self.delivered_at.isoformat() if self.delivered_at else None,
                "created_at": self.created_at.isoformat() if self.created_at else None}


@app.route("/api/orders/<int:order_id>/proof-of-delivery", methods=["GET", "POST"])
@csrf.exempt
def order_proof_of_delivery(order_id):
    user = _get_current_user()
    if not user: return jsonify({"error": "Login required."}), 401
    order = ProductOrder.query.get(order_id)
    if not order or user["id"] not in (order.seller_id, order.buyer_id):
        return jsonify({"error": "Order not found."}), 404
    if request.method == "GET":
        row = ProofOfDelivery.query.filter_by(order_id=order_id).first()
        return jsonify({"proof_of_delivery": row.to_dict() if row else None}), 200
    if not _csrf_ok(): return jsonify({"error": "Invalid request origin."}), 403
    if user["id"] != order.seller_id:
        return jsonify({"error": "Only the seller can record proof of delivery."}), 403
    if ProofOfDelivery.query.filter_by(order_id=order_id).first():
        return jsonify({"error": "Proof of delivery already recorded for this order."}), 400
    data = request.get_json(silent=True) or {}
    signature_data = data.get("signature_data")
    photo_url = (data.get("photo_url") or "").strip()[:500] or None
    if not signature_data and not photo_url:
        return jsonify({"error": "A signature or a delivery photo is required."}), 400
    row = ProofOfDelivery(
        order_id=order_id, recorded_by_user_id=user["id"],
        signature_data=signature_data, photo_url=photo_url,
        recipient_name=(data.get("recipient_name") or "").strip()[:160] or None,
        notes=(data.get("notes") or "").strip()[:500] or None,
    )
    db.session.add(row)
    order.status = "delivered" if order.status not in ("cancelled",) else order.status
    db.session.commit()
    notify_user(order.buyer_id, "orders", f"Order #{order.id} delivered",
                 "The seller has recorded proof of delivery for your order.", link=f"/orders/{order.id}")
    return jsonify({"ok": True, "proof_of_delivery": row.to_dict()}), 201


@app.route("/api/orders/<int:order_id>/proof-of-delivery/signature-image", methods=["GET"])
def order_proof_of_delivery_signature_image(order_id):
    """Serves the raw signature as a viewable PNG rather than a JSON
    blob, mirroring how the existing e-sign contract signatures are
    served."""
    user = _get_current_user()
    if not user: return jsonify({"error": "Login required."}), 401
    order = ProductOrder.query.get(order_id)
    if not order or user["id"] not in (order.seller_id, order.buyer_id):
        return jsonify({"error": "Order not found."}), 404
    row = ProofOfDelivery.query.filter_by(order_id=order_id).first()
    if not row or not row.signature_data:
        return jsonify({"error": "No signature recorded for this order."}), 404
    try:
        raw = row.signature_data.split(",", 1)[-1]
        img_bytes = base64.b64decode(raw)
    except Exception:
        return jsonify({"error": "Stored signature data is invalid."}), 500
    return Response(img_bytes, mimetype="image/png")


