# 514k (roadmap item 10): SANDBOX / DEMO MODE FOR PROSPECTIVE
# CUSTOMERS
# Distinct from the existing authenticated developer API sandbox
# (Stage 383) — this is a real, fully-functional account a visitor
# can drop straight into with zero signup, seeded with realistic
# sample data. Never a fake screenshot tour: every feature the demo
# account touches runs against real rows in the real database, just
# in an isolated, clearly-labeled, auto-expiring account. Demo
# accounts never see real other users' data (same row-level scoping
# as every other account) and can never send real money (Stripe
# calls made from a demo session are blocked below).
# ---------------------------------------------------------------

DEMO_ACCOUNT_LIFETIME_HOURS = int(os.environ.get("DEMO_ACCOUNT_LIFETIME_HOURS", "2"))


def _seed_demo_account_data(demo_user_id):
    db.session.add(Product(
        seller_id=demo_user_id, name="Sample Roasted Coffee Beans (Demo)",
        description="A sample listing to show how the marketplace catalog works.",
        category="Food & Beverage", price=24.99, currency="USD",
        quantity_available=50, unit="kg", country_code="ZW", is_active=True))
    db.session.add(CrmContact(
        user_id=demo_user_id, name="Jane Demo Buyer", email="jane@example.com",
        company="Example Imports Ltd", stage="negotiating"))
    db.session.add(ErpInvoice(
        owner_user_id=demo_user_id, invoice_number="DEMO-0001", status="paid",
        currency="USD", issue_date=datetime.utcnow().date(), total=249.99, amount_paid=249.99))
    db.session.commit()


@app.route("/api/demo/start", methods=["POST"])
@csrf.exempt
def demo_start():
    if not _csrf_ok(): return jsonify({"error": "Invalid request origin."}), 403
    token = secrets.token_hex(6)
    email = f"demo-{token}@demo.connectit.internal"
    user = UserAccount(name="Demo Account", email=email, plan="free",
                        is_active=True, email_verified=True)
    user.set_password(secrets.token_urlsafe(24))
    user.is_demo_account = True
    user.demo_expires_at = datetime.utcnow() + timedelta(hours=DEMO_ACCOUNT_LIFETIME_HOURS)
    db.session.add(user)
    db.session.commit()
    try:
        _seed_demo_account_data(user.id)
    except Exception as e:
        db.session.rollback()
        logging.error(f"[DEMO SEED] {e}")

    session["user_id"] = user.id
    session["user_name"] = user.name
    session["user_email"] = user.email
    session["user_plan"] = user.plan
    session["is_demo_account"] = True

    return jsonify({"ok": True, "demo": True,
                     "expires_at": user.demo_expires_at.isoformat(),
                     "message": f"Demo mode — this account and its data auto-expire in {DEMO_ACCOUNT_LIFETIME_HOURS} hours."}), 201


@app.route("/api/demo/status", methods=["GET"])
def demo_status():
    user = _get_current_user()
    if not user:
        return jsonify({"is_demo": False}), 200
    account = UserAccount.query.get(user["id"])
    if not account or not account.is_demo_account:
        return jsonify({"is_demo": False}), 200
    return jsonify({"is_demo": True,
                     "expires_at": account.demo_expires_at.isoformat() if account.demo_expires_at else None}), 200


def _block_if_demo_account():
    """Called from any route that would move real money. Demo
    accounts never get a real Stripe key path, so this is a defensive
    second guard, not the only one."""
    user = _get_current_user()
    if not user:
        return None
    account = UserAccount.query.get(user["id"])
    if account and account.is_demo_account:
        return jsonify({"error": "This is a demo account — real payments are disabled. Sign up for a full account to continue."}), 403
    return None


@app.route("/api/demo/cleanup-expired", methods=["POST"])
@csrf.exempt
def demo_cleanup_expired():
    """Meant to be hit by an external scheduler on a timer, same
    pattern as the report-digest sweep. Deletes expired demo accounts
    and their seeded rows so demo data never accumulates indefinitely."""
    if not _csrf_ok(): return jsonify({"error": "Invalid request origin."}), 403
    admin_user, err = _require_admin()
    if err: return err
    expired = UserAccount.query.filter(
        UserAccount.is_demo_account == True,  # noqa: E712
        UserAccount.demo_expires_at != None,  # noqa: E711
        UserAccount.demo_expires_at < datetime.utcnow()).all()
    deleted = 0
    for acct in expired:
        try:
            Product.query.filter_by(seller_id=acct.id).delete()
            CrmContact.query.filter_by(user_id=acct.id).delete()
            ErpInvoice.query.filter_by(owner_user_id=acct.id).delete()
            db.session.delete(acct)
            db.session.commit()
            deleted += 1
        except Exception as e:
            db.session.rollback()
            logging.error(f"[DEMO CLEANUP] account {acct.id}: {e}")
    return jsonify({"ok": True, "deleted": deleted}), 200


# ---------------------------------------------------------------
# 514l (roadmap item 12): MEETING TRANSCRIPTION TIED TO REAL
# CALENDAR EVENTS
# Stage 463h's /api/meetings/transcripts already accepts a
# calendar_event_id and MeetingTranscript already stores it, but there
# was no endpoint feeding the frontend a real, pickable list of the
# user's actual synced calendar events to attach a recording to —
# meaning it stayed a free-standing paste/record tool in practice.
# This closes that gap by surfacing CalendarSyncLink rows (Stage
# 463d's real Google/Outlook two-way sync) as a picker list, and by
# chaining the real Whisper transcription directly into a
# MeetingTranscript row tied to the chosen event, in one call.
# ---------------------------------------------------------------

@app.route("/api/meetings/upcoming-calendar-events", methods=["GET"])
def meetings_upcoming_calendar_events():
    """Real events already synced from the user's connected Google/
    Outlook calendar (Stage 463d) — not a fabricated list. Returns an
    empty list with a clear reason if nothing is connected yet."""
    user, err = _erp_user_or_401()
    if err: return err
    google_connected = bool(get_valid_calendar_token(user["id"]))
    outlook_connected = bool(get_valid_microsoft_token(user["id"]))
    if not google_connected and not outlook_connected:
        return jsonify({"events": [], "calendar_connected": False,
                         "message": "Connect Google or Outlook calendar under Integrations, then pull your events."}), 200
    since = datetime.utcnow() - timedelta(hours=6)
    rows = (CalendarSyncLink.query
            .filter(CalendarSyncLink.owner_user_id == user["id"],
                    CalendarSyncLink.direction == "inbound",
                    CalendarSyncLink.start_time >= since)
            .order_by(CalendarSyncLink.start_time.asc()).limit(30).all())
    already_transcribed = {t.calendar_event_id for t in
                            MeetingTranscript.query.filter_by(owner_user_id=user["id"]).all()
                            if t.calendar_event_id}
    events = [{"external_event_id": r.external_event_id, "title": r.title,
               "start_time": r.start_time.isoformat() if r.start_time else None,
               "provider": r.provider, "already_transcribed": r.external_event_id in already_transcribed}
              for r in rows]
    return jsonify({"events": events, "calendar_connected": True}), 200


@app.route("/api/meetings/transcribe-for-event", methods=["POST"])
@csrf.exempt
def meetings_transcribe_for_event():
    """One-call version of record -> transcribe -> save, tied straight
    to a real synced calendar event, so a meeting recording never
    exists disconnected from the actual event it belongs to."""
    if 'audio' not in request.files:
        return jsonify({'error': 'No audio file provided'}), 400
    user, err = _erp_user_or_401()
    if err: return err
    calendar_event_id = (request.form.get("calendar_event_id") or "").strip()
    if not calendar_event_id:
        return jsonify({"error": "calendar_event_id is required — pick a real synced calendar event first."}), 400
    link = CalendarSyncLink.query.filter_by(owner_user_id=user["id"], external_event_id=calendar_event_id).first()
    if not link:
        return jsonify({"error": "That calendar event wasn't found in your synced events. Pull your calendar again."}), 404

    audio_file = request.files['audio']
    if not audio_file.filename:
        return jsonify({'error': 'Empty audio file'}), 400
    byok_key = get_effective_credential(user["id"], 'openai', 'api_key', None)
    client = OpenAI(api_key=byok_key) if byok_key else openai_client
    if not client:
        return jsonify({'error': 'OpenAI client not initialised. Add your own OpenAI key under Settings > Integrations.'}), 503

    with tempfile.NamedTemporaryFile(delete=False, suffix='.webm') as tmp:
        audio_file.save(tmp.name)
        tmp_path = tmp.name
    try:
        with open(tmp_path, 'rb') as f:
            result = client.audio.transcriptions.create(
                model='whisper-1', file=f, response_format='verbose_json')
        transcript_text = result.text
    except Exception as e:
        logging.error(f"[MEETING TRANSCRIBE FOR EVENT] {e}")
        return jsonify({'error': str(e)}), 500
    finally:
        try: os.unlink(tmp_path)
        except Exception: pass

    row = MeetingTranscript(owner_user_id=user["id"], calendar_event_id=calendar_event_id,
                             event_title=link.title, event_start=link.start_time,
                             transcript_text=transcript_text)
    db.session.add(row)
    db.session.commit()
    return jsonify({"ok": True, "transcript": row.to_dict()}), 201


