# ════════════════════════════════════════════════════════════
# STAGE 515: RESEARCH NOTEBOOK (NotebookLM-style source-grounded
# research tool). A user creates a notebook, feeds it real sources
# (pasted text, uploaded files via the existing FILE INTELLIGENCE
# extractors, or a fetched webpage), then asks questions that are
# answered ONLY from those sources (keyword-overlap retrieval, same
# proven approach as STAGE 230's Knowledge Base — no vector-DB
# dependency) with the source(s) used named alongside every answer,
# plus an on-demand AI-generated summary/key-topics/FAQ overview.
# Reuses _kb_chunk_text/_kb_tokenize (STAGE 230), fi_extract (FILE
# INTELLIGENCE), _strip_html_tags (STAGE 92), and the existing
# Claude→Gemini→OpenAI→Ollama provider chain via _one_round — no new
# infra, no fabricated citations, no answer without real source text
# backing it.
# ════════════════════════════════════════════════════════════

NB_MAX_NOTEBOOKS_PER_USER = 30
NB_MAX_SOURCES_PER_NOTEBOOK = 40
NB_TOP_K = 6
NB_MAX_CONTEXT_CHARS = 4000
NB_OVERVIEW_MAX_CHARS = 30000
NB_MINDMAP_MAX_CHARS = 20000
NB_FLASHCARD_MAX_CHARS = 24000
NB_AUDIO_MAX_CHARS = 16000
NB_AUDIO_MAX_TURNS = 16
NB_AUDIO_HOST_A_VOICE = "en-US-Neural2-D"   # Google Cloud TTS, male
NB_AUDIO_HOST_B_VOICE = "en-US-Neural2-F"   # Google Cloud TTS, female


class ResearchNotebook(db.Model):
    __tablename__ = "research_notebooks"
    id            = db.Column(db.Integer, primary_key=True)
    owner_user_id = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    title         = db.Column(db.String(200), nullable=False)
    created_at    = db.Column(db.DateTime, default=datetime.utcnow)
    updated_at    = db.Column(db.DateTime, default=datetime.utcnow, onupdate=datetime.utcnow)

    def to_dict(self):
        return {"id": self.id, "title": self.title,
                "created_at": self.created_at.isoformat() if self.created_at else None,
                "updated_at": self.updated_at.isoformat() if self.updated_at else None}


class NotebookSource(db.Model):
    """One ingested source (pasted text / uploaded file / fetched
    webpage) belonging to a single notebook."""
    __tablename__ = "notebook_sources"
    id            = db.Column(db.Integer, primary_key=True)
    notebook_id   = db.Column(db.Integer, db.ForeignKey("research_notebooks.id"), nullable=False, index=True)
    owner_user_id = db.Column(db.Integer, nullable=False, index=True)
    title         = db.Column(db.String(200), nullable=False)
    source_type   = db.Column(db.String(20), nullable=False, default="pasted")  # pasted | upload | url
    origin        = db.Column(db.String(500), nullable=True)  # filename or url, if any
    char_count    = db.Column(db.Integer, nullable=False, default=0)
    created_at    = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        return {"id": self.id, "title": self.title, "source_type": self.source_type,
                "origin": self.origin, "char_count": self.char_count,
                "created_at": self.created_at.isoformat() if self.created_at else None}


class NotebookChunk(db.Model):
    """Precomputed retrievable slice of a NotebookSource's text —
    same chunking strategy as STAGE 230's KnowledgeChunk. `embedding`
    is a JSON-encoded vector from the shared _get_embedding() helper
    (STAGE 153), computed once at ingestion time in
    _notebook_ingest_source — null when embeddings aren't configured
    (no OpenAI key), in which case retrieval transparently falls back
    to keyword-overlap only. See _notebook_semantic_retrieve /
    _notebook_retrieve below."""
    __tablename__ = "notebook_chunks"
    id          = db.Column(db.Integer, primary_key=True)
    source_id   = db.Column(db.Integer, db.ForeignKey("notebook_sources.id"), nullable=False, index=True)
    notebook_id = db.Column(db.Integer, db.ForeignKey("research_notebooks.id"), nullable=False, index=True)
    chunk_index = db.Column(db.Integer, nullable=False, default=0)
    text        = db.Column(db.Text, nullable=False)
    embedding   = db.Column(db.Text, nullable=True)   # JSON-encoded list[float], or null


class NotebookOverview(db.Model):
    """Cached AI-generated summary/key-topics/FAQ for a notebook.
    Regenerated on demand, not automatically, so it never silently
    goes stale without the user knowing — the frontend shows how many
    sources it was generated from vs. the current count."""
    __tablename__ = "notebook_overviews"
    id                          = db.Column(db.Integer, primary_key=True)
    notebook_id                 = db.Column(db.Integer, db.ForeignKey("research_notebooks.id"), nullable=False, unique=True, index=True)
    summary                     = db.Column(db.Text, nullable=True)
    key_topics                  = db.Column(db.Text, nullable=True)  # JSON list[str]
    faq                         = db.Column(db.Text, nullable=True)  # JSON list[{q,a}]
    source_count_at_generation  = db.Column(db.Integer, nullable=False, default=0)
    generated_at                = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        try: topics = json.loads(self.key_topics) if self.key_topics else []
        except Exception: topics = []
        try: faq = json.loads(self.faq) if self.faq else []
        except Exception: faq = []
        return {"summary": self.summary or "", "key_topics": topics, "faq": faq,
                "source_count_at_generation": self.source_count_at_generation,
                "generated_at": self.generated_at.isoformat() if self.generated_at else None}


class NotebookMessage(db.Model):
    """Persisted Q&A turn so a notebook's research chat survives a
    page reload, same pattern as WidgetMessage."""
    __tablename__ = "notebook_messages"
    id            = db.Column(db.Integer, primary_key=True)
    notebook_id   = db.Column(db.Integer, db.ForeignKey("research_notebooks.id"), nullable=False, index=True)
    role          = db.Column(db.String(10), nullable=False)  # user | assistant
    content       = db.Column(db.Text, nullable=False)
    cited_sources = db.Column(db.Text, nullable=True)  # JSON list[str] of source titles
    created_at    = db.Column(db.DateTime, default=datetime.utcnow, index=True)

    def to_dict(self):
        try: cites = json.loads(self.cited_sources) if self.cited_sources else []
        except Exception: cites = []
        return {"id": self.id, "role": self.role, "content": self.content,
                "cited_sources": cites,
                "created_at": self.created_at.isoformat() if self.created_at else None}


class NotebookAudioOverview(db.Model):
    """Cached podcast-style Audio Overview for a notebook — a
    two-host script grounded in the real source text, synthesized to
    MP3 with the existing text_to_speech() pipeline (STAGE 49177) and
    concatenated into one clip. `audio_base64` is null when TTS isn't
    configured on this deployment, in which case the (still real,
    still grounded) script is saved on its own so there's a transcript
    to read even without audio, rather than failing the whole
    feature."""
    __tablename__ = "notebook_audio_overviews"
