NB_GREETING_WORDS = {
    "hi", "hii", "hiya", "hello", "hey", "heya", "yo", "sup", "howdy",
    "greetings", "morning", "afternoon", "evening", "there", "again",
    "thanks", "thank", "ok", "okay", "cool", "nice",
}


def _nb_is_pure_greeting(question):
    """True only for messages that are ENTIRELY small talk (hi, hello
    there, thanks!) with no actual question content — so a bare 'hi'
    gets a friendly nudge instead of being run through retrieval (which
    would correctly, but unhelpfully, find nothing and sound broken)."""
    words = re.findall(r"[a-zA-Z']+", question.lower())
    return bool(words) and all(w in NB_GREETING_WORDS for w in words)


@app.route("/api/notebooks/<int:notebook_id>/ask", methods=["POST"])
@csrf.exempt
def notebook_ask(notebook_id):
    """Source-grounded Q&A — retrieval is scoped to THIS notebook only
    (never the user's other notebooks or general chat history), the
    system prompt forbids outside knowledge, and every answer is
    persisted with exactly which source titles backed it.

    Two things this used to get wrong, both fixed here:
    1. A bare "hi"/"thanks" ran through keyword retrieval, correctly
       found nothing, and returned a blunt "nothing related" refusal —
       reads as broken for what's just small talk. Pure greetings now
       get a friendly nudge instead, with no retrieval/AI round-trip.
    2. A real, on-topic question that doesn't share exact keywords with
       the source text (or whose only real source got its actual
       content drowned out by unrelated URL fetch noise, since fixed
       — see _strip_html_tags) used to also hit that same blunt
       refusal with NO attempt to actually answer. Real NotebookLM
       always tries against the source content and lets the model
       itself say when it doesn't know; a keyword-overlap miss now
       falls back to a broad sample of every source (budget-shared
       across them) instead of refusing outright, so the AI only ever
       says "not covered" when it's actually looked and means it."""
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    nb = _notebook_owned_or_404(notebook_id, user["id"])
    if not nb:
        return jsonify({"error": "Notebook not found."}), 404
    data = request.get_json(silent=True) or {}
    question = (data.get("question") or "").strip()
    if not question:
        return jsonify({"error": "question is required."}), 400
    sources = NotebookSource.query.filter_by(notebook_id=nb.id).order_by(NotebookSource.created_at.asc()).all()
    if not sources:
        return jsonify({"error": "Add at least one source before asking questions."}), 400

    if _nb_is_pure_greeting(question):
        titles = ", ".join(s.title for s in sources[:4]) + ("…" if len(sources) > 4 else "")
        answer = f"Hi! Ask me anything about this notebook's sources ({titles}) and I'll answer from those only."
        cited = []
    else:
        retrieved = _notebook_retrieve(nb.id, question)
        fell_back = False
        if not retrieved:
            # Keyword overlap found nothing — fall back to a broad sample
            # across every source instead of refusing outright, same
            # budget as normal retrieval so the prompt can't blow out.
            fell_back = True
            per_source_budget = max(400, NB_MAX_CONTEXT_CHARS // max(1, len(sources)))
            retrieved = []
            for s in sources:
                chunks = (NotebookChunk.query.filter_by(source_id=s.id)
                          .order_by(NotebookChunk.chunk_index.asc()).all())
                text = "\n".join(c.text for c in chunks)[:per_source_budget]
                if text.strip():
                    retrieved.append({"source_title": s.title, "text": text})
        context_block = "\n\n".join(f"[Source: {r['source_title']}]\n{r['text']}" for r in retrieved)
        system_prompt = (
            "You are a research assistant. Answer ONLY using the excerpts below, which come from "
            "the user's own uploaded sources for this notebook. Do not use outside knowledge and "
            "do not fill gaps with general facts. If the excerpts don't contain the answer, say so "
            "plainly and briefly instead of guessing — you can mention what these sources DO cover "
            "if that's more helpful than a flat no. Keep the answer itself free of citation markup "
            "— the source titles are shown separately by the app.\n\n"
            f"SOURCE EXCERPTS:\n{context_block}"
        )
        result = _one_round([{"role": "user", "content": question}], user_id=user["id"], system_prompt=system_prompt)
        answer = result or "The AI providers are unavailable right now — please try again shortly."
        # Only cite sources the model actually had in front of it; on the
        # fallback path that's still real source text, just not
        # keyword-matched, so citing it is accurate either way.
        cited = sorted({r["source_title"] for r in retrieved}) if not fell_back else []

    db.session.add(NotebookMessage(notebook_id=nb.id, role="user", content=question))
    db.session.add(NotebookMessage(notebook_id=nb.id, role="assistant", content=answer, cited_sources=json.dumps(cited)))
    nb.updated_at = datetime.utcnow()
    db.session.commit()
    return jsonify({"ok": True, "answer": answer, "cited_sources": cited}), 200


@app.route("/api/notebooks/<int:notebook_id>/overview", methods=["POST"])
@csrf.exempt
def notebook_generate_overview(notebook_id):
    """Generates (or regenerates, on explicit request) a summary + key
    topics + FAQ from the notebook's real source text. If the AI
    doesn't return clean JSON, the raw text is kept as the summary
    rather than inventing structured fields that weren't actually
    produced."""
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    nb = _notebook_owned_or_404(notebook_id, user["id"])
    if not nb:
        return jsonify({"error": "Notebook not found."}), 404
    sources = NotebookSource.query.filter_by(notebook_id=nb.id).order_by(NotebookSource.created_at.asc()).all()
    if not sources:
        return jsonify({"error": "Add at least one source first."}), 400

    per_source_budget = max(1000, NB_OVERVIEW_MAX_CHARS // len(sources))
    parts = []
    for s in sources:
        chunks = NotebookChunk.query.filter_by(source_id=s.id).order_by(NotebookChunk.chunk_index.asc()).all()
        text = "\n".join(c.text for c in chunks)[:per_source_budget]
        parts.append(f"[Source: {s.title}]\n{text}")
    combined = "\n\n".join(parts)

    system_prompt = (
        "You are a research assistant producing a study guide from the user's own uploaded "
        "sources. Base everything strictly on the text given — never invent facts not present in "
        "it. Respond with ONLY a JSON object, no markdown fences, no commentary, shaped exactly "
        "like this: "
        '{"summary": "2-4 paragraph plain-language summary", '
        '"key_topics": ["short topic", "..."], '
        '"faq": [{"q": "question a reader would ask", "a": "answer grounded in the sources"}]}'
    )
    result = _one_round([{"role": "user", "content": f"Sources:\n\n{combined}"}],
                         user_id=user["id"], system_prompt=system_prompt)
    if not result:
        return jsonify({"error": "AI providers are unavailable right now — try again shortly."}), 503

    cleaned = result.strip()
    if cleaned.startswith("```"):
        cleaned = re.sub(r"^```(json)?", "", cleaned).rstrip("`").strip()
    try:
        parsed = json.loads(cleaned)
        summary = str(parsed.get("summary") or "").strip()
        key_topics = [str(t).strip() for t in (parsed.get("key_topics") or []) if str(t).strip()][:12]
        faq = [{"q": str(x.get("q", "")).strip(), "a": str(x.get("a", "")).strip()}
               for x in (parsed.get("faq") or []) if isinstance(x, dict) and x.get("q") and x.get("a")][:10]
    except Exception:
        summary, key_topics, faq = cleaned, [], []

    overview = NotebookOverview.query.filter_by(notebook_id=nb.id).first()
    if not overview:
        overview = NotebookOverview(notebook_id=nb.id)
        db.session.add(overview)
    overview.summary = summary
    overview.key_topics = json.dumps(key_topics)
    overview.faq = json.dumps(faq)
    overview.source_count_at_generation = len(sources)
    overview.generated_at = datetime.utcnow()
    nb.updated_at = datetime.utcnow()
    db.session.commit()
    return jsonify({"ok": True, "overview": overview.to_dict()}), 200


