@app.route("/api/notebooks/<int:notebook_id>/mind-map", methods=["POST"])
@csrf.exempt
def notebook_generate_mind_map(notebook_id):
    """Generates (or regenerates) a visual topic graph — one central
    node for the notebook's overall subject, a handful of branch
    topics, each with a few sub-points — grounded strictly in the
    notebook's real source text. Rendered client-side as a radial SVG,
    no graphing library needed."""
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    blocked = gate_ai_usage(user, "notebook_mind_map")
    if blocked: return blocked
    nb = _notebook_owned_or_404(notebook_id, user["id"])
    if not nb:
        return jsonify({"error": "Notebook not found."}), 404
    sources = NotebookSource.query.filter_by(notebook_id=nb.id).order_by(NotebookSource.created_at.asc()).all()
    if not sources:
        return jsonify({"error": "Add at least one source first."}), 400

    combined = _notebook_combined_source_text(sources, NB_MINDMAP_MAX_CHARS)
    system_prompt = (
        "You are building a mind map from the user's own uploaded sources. Base every node "
        "strictly on the text given — never invent a topic not present in it. Respond with ONLY "
        "a JSON object, no markdown fences, no commentary, shaped exactly like this: "
        '{"central": "short label for the notebook\'s overall subject", '
        '"branches": [{"label": "short branch topic", "children": ["short sub-point", "..."]}]}. '
        "Use at most 7 branches, and at most 6 children per branch. Keep every label under 6 words."
    )
    result = _one_round([{"role": "user", "content": f"Sources:\n\n{combined}"}],
                         user_id=user["id"], system_prompt=system_prompt)
    if not result:
        return jsonify({"error": "AI providers are unavailable right now — try again shortly."}), 503

    cleaned = result.strip()
    if cleaned.startswith("```"):
        cleaned = re.sub(r"^```(json)?", "", cleaned).rstrip("`").strip()
    try:
        parsed = json.loads(cleaned)
        central = str(parsed.get("central") or nb.title).strip()[:80]
        branches = []
        for b in (parsed.get("branches") or [])[:7]:
            if not isinstance(b, dict):
                continue
            label = str(b.get("label", "")).strip()[:80]
            if not label:
                continue
            children = [str(c).strip()[:80] for c in (b.get("children") or []) if str(c).strip()][:6]
            branches.append({"label": label, "children": children})
        if not branches:
            raise ValueError("no branches")
        graph = {"central": central, "branches": branches}
    except Exception:
        return jsonify({"error": "Could not parse a mind map from the AI's response — try again."}), 502

    mm = NotebookMindMap.query.filter_by(notebook_id=nb.id).first()
    if not mm:
        mm = NotebookMindMap(notebook_id=nb.id)
        db.session.add(mm)
    mm.graph_json = json.dumps(graph)
    mm.source_count_at_generation = len(sources)
    mm.generated_at = datetime.utcnow()
    nb.updated_at = datetime.utcnow()
    db.session.commit()
    return jsonify({"ok": True, "mind_map": mm.to_dict()}), 200


