@csrf.exempt
def notebook_generate_flashcards(notebook_id):
    """Generates (or regenerates) a study guide outline plus a deck of
    Q/A flashcards, grounded strictly in the notebook's real source
    text — same no-fabrication contract as the overview/mind map."""
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
