@app.route("/api/notebooks/<int:notebook_id>/audio-overview", methods=["POST"])
@csrf.exempt
def notebook_generate_audio_overview(notebook_id):
    """Generates (or regenerates) a two-host podcast-style Audio
    Overview: an LLM writes a grounded back-and-forth script from the
    notebook's real source text, then each line is synthesized with
    the existing text_to_speech() Google Cloud TTS pipeline (STAGE
    49177), alternating voices per host, and the resulting clips are
    concatenated into one MP3. If TTS isn't configured on this
    deployment, the real script is still generated and saved — so
    there's a transcript to read even without audio — rather than
    failing the whole feature."""
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    blocked = gate_ai_usage(user, "notebook_audio_overview")
    if blocked: return blocked
    nb = _notebook_owned_or_404(notebook_id, user["id"])
    if not nb:
        return jsonify({"error": "Notebook not found."}), 404
    sources = NotebookSource.query.filter_by(notebook_id=nb.id).order_by(NotebookSource.created_at.asc()).all()
    if not sources:
        return jsonify({"error": "Add at least one source first."}), 400

    combined = _notebook_combined_source_text(sources, NB_AUDIO_MAX_CHARS)
    system_prompt = (
        "You are writing a short two-host podcast script that explains the user's own uploaded "
        "sources to a listener who hasn't read them. Base everything strictly on the text given — "
        "never invent a fact not present in it. Natural, conversational tone; hosts build on each "
        f"other, ask each other questions, react — not a dry summary read aloud. Use at most "
        f"{NB_AUDIO_MAX_TURNS} turns total, alternating between the two hosts, each turn under 60 "
        "words. Respond with ONLY a JSON object, no markdown fences, no commentary, shaped exactly "
        'like this: {"turns": [{"speaker": "A", "text": "..."}, {"speaker": "B", "text": "..."}]}.'
    )
    result = _one_round([{"role": "user", "content": f"Sources:\n\n{combined}"}],
                         user_id=user["id"], system_prompt=system_prompt)
    if not result:
        return jsonify({"error": "AI providers are unavailable right now — try again shortly."}), 503

    cleaned = result.strip()
    if cleaned.startswith("```"):
        cleaned = re.sub(r"^```(json)?", "", cleaned).rstrip("`").strip()
    turns = []
    try:
        parsed = json.loads(cleaned)
        for t in (parsed.get("turns") or [])[:NB_AUDIO_MAX_TURNS]:
            if not isinstance(t, dict):
                continue
            speaker = "B" if str(t.get("speaker", "A")).strip().upper().startswith("B") else "A"
            text = str(t.get("text", "")).strip()
            if text:
                turns.append({"speaker": speaker, "text": text[:600]})
    except Exception:
        turns = []
    if not turns:
        return jsonify({"error": "Could not parse a podcast script from the AI's response — try again."}), 502

    # Best-effort synthesis — a script with no audio is still a real,
    # useful result, so a TTS hiccup never throws away the script.
    audio_b64, mime_type = None, None
    if GTTS_AVAILABLE:
        clips = []
        for turn in turns:
            voice = NB_AUDIO_HOST_A_VOICE if turn["speaker"] == "A" else NB_AUDIO_HOST_B_VOICE
            try:
                tts_result = text_to_speech(turn["text"], user_id=user["id"], voice_name=voice)
                if tts_result.get("ok"):
                    clips.append(base64.b64decode(tts_result["audio_base64"]))
            except Exception as e:
                logging.error(f"[NOTEBOOK AUDIO OVERVIEW TTS] {e}")
        if clips:
            audio_b64 = base64.b64encode(b"".join(clips)).decode("utf-8")
            mime_type = "audio/mpeg"

    ao = NotebookAudioOverview.query.filter_by(notebook_id=nb.id).first()
    if not ao:
        ao = NotebookAudioOverview(notebook_id=nb.id)
        db.session.add(ao)
    ao.script_json = json.dumps(turns)
    ao.audio_base64 = audio_b64
    ao.mime_type = mime_type
    ao.source_count_at_generation = len(sources)
    ao.generated_at = datetime.utcnow()
    nb.updated_at = datetime.utcnow()
    db.session.commit()
    return jsonify({"ok": True, "audio_overview": ao.to_dict(), "tts_available": GTTS_AVAILABLE}), 200


# ────────────────────────────────────────────────────────────
# NOTEBOOK EXPORT — one endpoint, many destinations. Reuses every
# existing export/push helper on the platform rather than building a
# parallel export system just for notebooks: python-docx/python-pptx/
# openpyxl/reportlab for local downloads (STAGE 34's _build_docx_bytes
# / _build_pptx_bytes, the report-builder's xlsx pattern, and
# reportlab the same way the audit-trail PDF export uses it);
# create_google_doc / create_google_sheet for Google; and STAGE 34's
# _onedrive_put_bytes for Word Online / PowerPoint Online / an Excel
# workbook landing straight in OneDrive.
# ────────────────────────────────────────────────────────────

def _notebook_export_materialize(nb, sources, content_type):
    """Turns one piece of a notebook's real, already-generated output
    into a generic {title, sections, table_headers, table_rows} shape
    every destination below builds from — one materializer, many
    export formats, instead of duplicating notebook-content logic per
    format. Raises ValueError (never fabricates content to export) if
    the requested piece hasn't been generated yet."""
    content_type = (content_type or "overview").strip().lower()

    if content_type == "sources":
        if not sources:
            raise ValueError("This notebook has no sources yet.")
        table_headers = ["Title", "Type", "Origin", "Length (chars)"]
        table_rows = [[s.title, s.source_type, s.origin or "", s.char_count] for s in sources]
        sections = [{"heading": s.title,
                     "body": f"Type: {s.source_type}\nOrigin: {s.origin or '(n/a)'}\nLength: {s.char_count} characters"}
                    for s in sources]
        return {"title": f"{nb.title} — Sources", "sections": sections,
                "table_headers": table_headers, "table_rows": table_rows}

    if content_type == "mindmap":
        mm = NotebookMindMap.query.filter_by(notebook_id=nb.id).first()
        if not mm:
            raise ValueError("No mind map has been generated yet — generate one first.")
        graph = json.loads(mm.graph_json) if mm.graph_json else {}
        sections = [{"heading": graph.get("central", nb.title), "body": ""}]
        table_rows = []
        for b in (graph.get("branches") or []):
            label = b.get("label", "")
            children = b.get("children") or []
            sections.append({"heading": label, "body": "\n".join("- " + c for c in children)})
            if children:
                table_rows.extend([[label, c] for c in children])
            else:
                table_rows.append([label, ""])
        return {"title": f"{nb.title} — Mind Map", "sections": sections,
                "table_headers": ["Branch", "Sub-topic"], "table_rows": table_rows}

    if content_type == "flashcards":
        fc = NotebookFlashcardSet.query.filter_by(notebook_id=nb.id).first()
        if not fc:
            raise ValueError("No study guide has been generated yet — generate one first.")
        cards = json.loads(fc.cards_json) if fc.cards_json else []
        sections = [{"heading": "Study Guide", "body": fc.study_guide or ""},
                    {"heading": "Flashcards",
                     "body": "\n\n".join(f"Q: {c.get('q','')}\nA: {c.get('a','')}" for c in cards)}]
        table_rows = [[c.get("q", ""), c.get("a", "")] for c in cards]
        return {"title": f"{nb.title} — Study Guide", "sections": sections,
                "table_headers": ["Question", "Answer"], "table_rows": table_rows}

    if content_type == "audio":
        ao = NotebookAudioOverview.query.filter_by(notebook_id=nb.id).first()
        if not ao:
            raise ValueError("No audio overview has been generated yet — generate one first.")
        turns = json.loads(ao.script_json) if ao.script_json else []
        sections = [{"heading": f"Host {t.get('speaker', '')}", "body": t.get("text", "")} for t in turns]
        table_rows = [[t.get("speaker", ""), t.get("text", "")] for t in turns]
        return {"title": f"{nb.title} — Audio Overview Transcript", "sections": sections,
                "table_headers": ["Host", "Line"], "table_rows": table_rows}

    # default: overview
    ov = NotebookOverview.query.filter_by(notebook_id=nb.id).first()
    if not ov:
        raise ValueError("No overview has been generated yet — generate one first.")
    try: topics = json.loads(ov.key_topics) if ov.key_topics else []
    except Exception: topics = []
    try: faq = json.loads(ov.faq) if ov.faq else []
    except Exception: faq = []
    sections = [{"heading": "Summary", "body": ov.summary or ""}]
    if topics:
        sections.append({"heading": "Key Topics", "body": "\n".join("- " + t for t in topics)})
    if faq:
        sections.append({"heading": "Frequently Asked",
                          "body": "\n\n".join(f"Q: {f.get('q','')}\nA: {f.get('a','')}" for f in faq)})
    table_rows = [[f.get("q", ""), f.get("a", "")] for f in faq]
    return {"title": f"{nb.title} — Overview", "sections": sections,
            "table_headers": ["Question", "Answer"], "table_rows": table_rows}


@app.route("/api/notebooks/<int:notebook_id>/export", methods=["POST"])
@csrf.exempt
def notebook_export(notebook_id):
    """Body: {"content": "overview"|"mindmap"|"flashcards"|"sources",
    "destination": "docx"|"pptx"|"xlsx"|"csv"|"pdf"|"google_doc"|
    "google_sheet"|"word_online"|"powerpoint_online"|"onedrive_excel"}.
    The first five stream a real file back for direct download; the
    rest push to the user's own Google/Microsoft account (which must
    already be connected under Integrations) and return a link."""
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    nb = _notebook_owned_or_404(notebook_id, user["id"])
    if not nb:
        return jsonify({"error": "Notebook not found."}), 404
    sources = NotebookSource.query.filter_by(notebook_id=nb.id).order_by(NotebookSource.created_at.asc()).all()
    data = request.get_json(silent=True) or {}
    content_type = (data.get("content") or "overview").strip().lower()
    destination = (data.get("destination") or "docx").strip().lower()

    try:
        mat = _notebook_export_materialize(nb, sources, content_type)
    except ValueError as ve:
        return jsonify({"error": str(ve)}), 400

    safe_stub = re.sub(r"[^A-Za-z0-9 _-]", "", mat["title"])[:60].strip() or "notebook-export"

    if destination == "docx":
        if not DOCX_AVAILABLE:
            return jsonify({"error": "python-docx not installed on the server."}), 500
        file_bytes = _build_docx_bytes(mat["title"], mat["sections"])
        return Response(
            file_bytes,
            mimetype="application/vnd.openxmlformats-officedocument.wordprocessingml.document",
            headers={"Content-Disposition": f'attachment; filename="{safe_stub}.docx"'},
        )

    if destination == "pptx":
        if not PPTX_AVAILABLE:
            return jsonify({"error": "python-pptx not installed on the server."}), 500
        slides = [{"title": s["heading"] or mat["title"],
                   "bullets": [b for b in (s["body"] or "").split("\n") if b.strip()]}
                  for s in mat["sections"]]
        file_bytes = _build_pptx_bytes(mat["title"], slides)
        return Response(
            file_bytes,
            mimetype="application/vnd.openxmlformats-officedocument.presentationml.presentation",
            headers={"Content-Disposition": f'attachment; filename="{safe_stub}.pptx"'},
        )

    if destination in ("xlsx", "onedrive_excel"):
        if not OPENPYXL_AVAILABLE:
            return jsonify({"error": "openpyxl not installed on the server."}), 500
        wb = _MegaWorkbook()
        ws = wb.active
        ws.title = "Data"
        if mat["table_headers"]:
            ws.append(mat["table_headers"])
        for row in mat["table_rows"]:
            ws.append(row)
        buf = io.BytesIO()
        wb.save(buf)
        file_bytes = buf.getvalue()
        if destination == "xlsx":
            return Response(
                file_bytes,
                mimetype="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
                headers={"Content-Disposition": f'attachment; filename="{safe_stub}.xlsx"'},
            )
        ok, result = _onedrive_put_bytes(user["id"], f"{safe_stub}.xlsx", file_bytes)
        if not ok:
            return jsonify({"error": result}), 400
        return jsonify({"ok": True, "excel_online_url": result["web_url"]}), 200

    if destination == "csv":
        buf = io.StringIO()
        writer = csv.writer(buf)
        if mat["table_headers"]:
            writer.writerow(mat["table_headers"])
        for row in mat["table_rows"]:
            writer.writerow(row)
        return Response(
            buf.getvalue(), mimetype="text/csv",
            headers={"Content-Disposition": f'attachment; filename="{safe_stub}.csv"'},
        )

    if destination == "pdf":
        if not REPORTLAB_AVAILABLE:
            return jsonify({"error": "reportlab not installed on the server."}), 500
        buf = io.BytesIO()
        doc = SimpleDocTemplate(buf, pagesize=A4)
        styles = getSampleStyleSheet()
        story = [Paragraph(mat["title"], styles["Title"]), Spacer(1, 12)]
        for sec in mat["sections"]:
            if sec.get("heading"):
                story.append(Paragraph(sec["heading"], styles["Heading2"]))
            if sec.get("body"):
                story.append(Paragraph(sec["body"].replace("\n", "<br/>"), styles["Normal"]))
            story.append(Spacer(1, 10))
        doc.build(story)
        return Response(
            buf.getvalue(), mimetype="application/pdf",
            headers={"Content-Disposition": f'attachment; filename="{safe_stub}.pdf"'},
        )

    if destination == "google_doc":
        body_text = "\n\n".join(
            (f"{s['heading']}\n" if s.get("heading") else "") + (s.get("body") or "")
            for s in mat["sections"]
        )
        result = create_google_doc(user["id"], mat["title"], body_text, share_with_email=user.get("email"))
        return jsonify(result), (200 if result.get("ok") else 502)

    if destination == "google_sheet":
        result = create_google_sheet(user["id"], mat["title"], mat["table_headers"], mat["table_rows"],
                                      share_with_email=user.get("email"))
        return jsonify(result), (200 if result.get("ok") else 502)

    if destination == "word_online":
        if not DOCX_AVAILABLE:
            return jsonify({"error": "python-docx not installed on the server."}), 500
        file_bytes = _build_docx_bytes(mat["title"], mat["sections"])
        ok, result = _onedrive_put_bytes(user["id"], f"{safe_stub}.docx", file_bytes)
        if not ok:
            return jsonify({"error": result}), 400
        return jsonify({"ok": True, "word_online_url": result["web_url"]}), 200

    if destination == "powerpoint_online":
        if not PPTX_AVAILABLE:
            return jsonify({"error": "python-pptx not installed on the server."}), 500
        slides = [{"title": s["heading"] or mat["title"],
                   "bullets": [b for b in (s["body"] or "").split("\n") if b.strip()]}
                  for s in mat["sections"]]
        file_bytes = _build_pptx_bytes(mat["title"], slides)
        ok, result = _onedrive_put_bytes(user["id"], f"{safe_stub}.pptx", file_bytes)
        if not ok:
            return jsonify({"error": result}), 400
        return jsonify({"ok": True, "powerpoint_online_url": result["web_url"]}), 200

    return jsonify({"error": f"Unknown destination '{destination}'."}), 400


# ════════════════════════════════════════════════════════════
# SELLING TOOLS PACK — Dynamic Repricing, Vendor-Managed
# Inventory (VMI), and Dropshipping Supplier Integration.
# All three are new, admin-lockable programs (see
# PlatformFeatureFlag / requires_feature_flag near the top of this
# file) — every route below is gated behind its own flag and
# defaults LOCKED until a platform admin turns it on from the
# "Feature Flags — Lock / Unlock" panel, same as every other
# opt-in program on this platform.
# ════════════════════════════════════════════════════════════

# (Product.is_dropship / Product.dropship_supplier_product_id are
# declared directly in the Product class above, not monkey-patched
# here — SQLAlchemy's declarative mapper must see every column at
# class-definition time.)


# ────────────────────────────────────────────────────────────
# 1) DYNAMIC REPRICING ENGINE
# ────────────────────────────────────────────────────────────
# A seller attaches a repricing rule to one of their own listings.
# On each run (manual "Run now", or the scheduled cron sweep) the
# engine finds the cheapest *other* active listing on this platform
# in the same category with a similar name (the closest thing to a
# real "competitor price" this marketplace can see — there is no
# external price-scraping here, deliberately: repricing off other
# sellers' real, live listings on this platform is honest and
# auditable, unlike guessing at an outside site's price), applies
# the seller's chosen strategy, and clamps the result to the
# seller's own floor/ceiling so an engine never prices a listing
# below cost or above what the seller considers reasonable.
class RepricingRule(db.Model):
    __tablename__      = "repricing_rules"
    id                 = db.Column(db.Integer, primary_key=True)
    product_id         = db.Column(db.Integer, db.ForeignKey("products.id"), nullable=False, unique=True, index=True)
    seller_id          = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    strategy           = db.Column(db.String(20), nullable=False, default="match_lowest")  # match_lowest, beat_lowest
    beat_type          = db.Column(db.String(10), nullable=True)   # 'percent' or 'amount' (only used by beat_lowest)
    beat_value         = db.Column(db.Float, nullable=True)
    min_price          = db.Column(db.Float, nullable=False)
    max_price          = db.Column(db.Float, nullable=False)
    is_active          = db.Column(db.Boolean, nullable=False, default=True)
    last_run_at        = db.Column(db.DateTime, nullable=True)
    last_competitor_price = db.Column(db.Float, nullable=True)
    last_applied_price = db.Column(db.Float, nullable=True)
    created_at         = db.Column(db.DateTime, default=datetime.utcnow)
    updated_at         = db.Column(db.DateTime, default=datetime.utcnow, onupdate=datetime.utcnow)

    def to_dict(self) -> dict:
        product = Product.query.get(self.product_id)
        return {
            "id": self.id, "product_id": self.product_id,
            "product_name": product.name if product else None,
            "current_price": product.price if product else None,
            "currency": product.currency if product else None,
            "strategy": self.strategy, "beat_type": self.beat_type, "beat_value": self.beat_value,
            "min_price": self.min_price, "max_price": self.max_price, "is_active": self.is_active,
            "last_run_at": self.last_run_at.isoformat() if self.last_run_at else None,
            "last_competitor_price": self.last_competitor_price,
            "last_applied_price": self.last_applied_price,
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }


class RepricingLog(db.Model):
    __tablename__ = "repricing_logs"
    id            = db.Column(db.Integer, primary_key=True)
    rule_id       = db.Column(db.Integer, db.ForeignKey("repricing_rules.id"), nullable=False, index=True)
    product_id    = db.Column(db.Integer, db.ForeignKey("products.id"), nullable=False, index=True)
    old_price     = db.Column(db.Float, nullable=True)
    new_price     = db.Column(db.Float, nullable=True)
    competitor_price = db.Column(db.Float, nullable=True)
    note          = db.Column(db.String(300), nullable=True)
    created_at    = db.Column(db.DateTime, default=datetime.utcnow, index=True)

    def to_dict(self) -> dict:
        return {
            "id": self.id, "old_price": self.old_price, "new_price": self.new_price,
            "competitor_price": self.competitor_price, "note": self.note,
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }


_STOPWORDS_REPRICING = {"the", "a", "an", "and", "or", "of", "for", "with", "new", "pcs", "pack", "set"}

def _repricing_tokenize(name: str) -> set:
    return {w for w in re.findall(r"[a-z0-9]+", (name or "").lower()) if w not in _STOPWORDS_REPRICING and len(w) > 1}


def _repricing_find_competitor_price(product: "Product"):
    """Cheapest OTHER active listing, different seller, same category,
    with at least one significant name-token in common. Returns
    (price, matched_count) or (None, 0) if nothing comparable exists."""
    my_tokens = _repricing_tokenize(product.name)
    candidates = (Product.query
                  .filter(Product.category == product.category, Product.is_active.is_(True),
                          Product.seller_id != product.seller_id, Product.id != product.id)
                  .limit(500).all())
    best = None
    matched = 0
    for c in candidates:
        if my_tokens and not (my_tokens & _repricing_tokenize(c.name)):
            continue
        matched += 1
        if best is None or (c.price or 0) < best:
            best = c.price
    return best, matched


def _repricing_apply_rule(rule: "RepricingRule") -> "RepricingLog":
    product = Product.query.get(rule.product_id)
    if not product:
        return None
    competitor_price, matched = _repricing_find_competitor_price(product)
    old_price = product.price
    rule.last_run_at = datetime.utcnow()
    if competitor_price is None:
        rule.last_competitor_price = None
        log = RepricingLog(rule_id=rule.id, product_id=product.id, old_price=old_price, new_price=old_price,
                            competitor_price=None, note="No comparable listing from another seller found — price unchanged.")
        db.session.add(log)
        db.session.commit()
        return log
    if rule.strategy == "beat_lowest" and rule.beat_value is not None:
        if rule.beat_type == "amount":
            target = competitor_price - rule.beat_value
        else:
            target = competitor_price * (1 - (rule.beat_value / 100.0))
    else:
        target = competitor_price  # match_lowest
    target = max(rule.min_price, min(rule.max_price, target))
    target = round(max(0.01, target), 2)
    rule.last_competitor_price = competitor_price
    rule.last_applied_price = target
    changed = abs((old_price or 0) - target) >= 0.01
    if changed:
        product.price = target
        product.updated_at = datetime.utcnow()
    note = (f"Matched against {matched} listing(s); lowest competitor price {competitor_price}. "
            + ("Price updated." if changed else "Already at target price — no change."))
    log = RepricingLog(rule_id=rule.id, product_id=product.id, old_price=old_price, new_price=target,
                        competitor_price=competitor_price, note=note)
    db.session.add(log)
    db.session.commit()
    return log


def _repricing_owned_rule_or_404(rule_id, user_id):
    return RepricingRule.query.filter_by(id=rule_id, seller_id=user_id).first()


@app.route("/api/repricing/rules", methods=["POST"])
@csrf.exempt
@requires_feature_flag("dynamic_repricing_engine")
def repricing_upsert_rule():
    """Creates or updates the (single) repricing rule attached to one
    of the caller's own listings. One rule per product."""
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user: return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    try:
        product_id = int(data.get("product_id"))
    except (TypeError, ValueError):
        return jsonify({"error": "product_id is required."}), 400
    product = Product.query.filter_by(id=product_id, seller_id=user["id"]).first()
    if not product:
        return jsonify({"error": "Listing not found on your account."}), 404
    strategy = (data.get("strategy") or "match_lowest").strip()
    if strategy not in ("match_lowest", "beat_lowest"):
        return jsonify({"error": "strategy must be match_lowest or beat_lowest."}), 400
    beat_type = (data.get("beat_type") or "percent").strip()
    if beat_type not in ("percent", "amount"):
        return jsonify({"error": "beat_type must be percent or amount."}), 400
    try:
        beat_value = float(data.get("beat_value")) if strategy == "beat_lowest" else None
        min_price = float(data.get("min_price"))
        max_price = float(data.get("max_price"))
    except (TypeError, ValueError):
        return jsonify({"error": "min_price and max_price must be numbers."}), 400
    if min_price <= 0 or max_price <= 0 or min_price > max_price:
        return jsonify({"error": "min_price must be positive and no greater than max_price."}), 400
    if strategy == "beat_lowest" and (beat_value is None or beat_value < 0):
        return jsonify({"error": "beat_value must be a non-negative number for the beat-lowest strategy."}), 400
    rule = RepricingRule.query.filter_by(product_id=product_id).first()
    if not rule:
        rule = RepricingRule(product_id=product_id, seller_id=user["id"])
        db.session.add(rule)
    rule.strategy = strategy
    rule.beat_type = beat_type if strategy == "beat_lowest" else None
    rule.beat_value = beat_value
    rule.min_price = min_price
    rule.max_price = max_price
    rule.is_active = bool(data.get("is_active", True))
    db.session.commit()
    return jsonify({"ok": True, "rule": rule.to_dict()}), 200


