@app.route("/api/repricing/rules/<int:rule_id>", methods=["DELETE"])
@csrf.exempt
@requires_feature_flag("dynamic_repricing_engine")
def repricing_delete_rule(rule_id):
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user: return jsonify({"error": "Login required."}), 401
    rule = _repricing_owned_rule_or_404(rule_id, user["id"])
    if not rule: return jsonify({"error": "Rule not found."}), 404
    RepricingLog.query.filter_by(rule_id=rule.id).delete()
    db.session.delete(rule)
    db.session.commit()
    return jsonify({"ok": True}), 200


@app.route("/api/repricing/rules/<int:rule_id>/run-now", methods=["POST"])
@csrf.exempt
@requires_feature_flag("dynamic_repricing_engine")
def repricing_run_now(rule_id):
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user: return jsonify({"error": "Login required."}), 401
    rule = _repricing_owned_rule_or_404(rule_id, user["id"])
    if not rule: return jsonify({"error": "Rule not found."}), 404
    log = _repricing_apply_rule(rule)
    return jsonify({"ok": True, "rule": rule.to_dict(), "log": log.to_dict() if log else None}), 200


