def _vmi_replenishment_owned_by_vendor(ro_id, vendor_user_id):
    ro = VmiReplenishmentOrder.query.get(ro_id)
    if not ro: return None
    agreement = VmiAgreement.query.get(ro.agreement_id)
    if not agreement or agreement.vendor_id != vendor_user_id: return None
    return ro


@app.route("/api/vmi/replenishments/<int:ro_id>/confirm", methods=["POST"])
@csrf.exempt
@requires_feature_flag("vendor_managed_inventory")
def vmi_replenishment_confirm(ro_id):
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user: return jsonify({"error": "Login required."}), 401
    ro = _vmi_replenishment_owned_by_vendor(ro_id, user["id"])
    if not ro or ro.status != "pending":
        return jsonify({"error": "Replenishment order not found or already actioned."}), 404
    ro.status = "confirmed"
    ro.confirmed_at = datetime.utcnow()
    db.session.commit()
    return jsonify({"ok": True, "replenishment": ro.to_dict()}), 200


