    user = _get_current_user()
    if not user: return jsonify({"error": "Login required."}), 401
    ro = _vmi_replenishment_owned_by_vendor(ro_id, user["id"])
    if not ro or ro.status != "confirmed":
        return jsonify({"error": "Replenishment order not found or not yet confirmed."}), 404
    data = request.get_json(silent=True) or {}
    ro.status = "shipped"
    ro.shipped_at = datetime.utcnow()
