@app.route("/api/vmi/replenishments/<int:ro_id>/receive", methods=["POST"])
@csrf.exempt
@requires_feature_flag("vendor_managed_inventory")
def vmi_replenishment_receive(ro_id):
    """Seller confirms the stock physically arrived — this is the ONLY
    step that actually increments the listing's quantity_available."""
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user: return jsonify({"error": "Login required."}), 401
    ro = VmiReplenishmentOrder.query.get(ro_id)
    agreement = VmiAgreement.query.get(ro.agreement_id) if ro else None
    if not ro or not agreement or agreement.seller_id != user["id"]:
        return jsonify({"error": "Replenishment order not found."}), 404
    if ro.status != "shipped":
        return jsonify({"error": "Replenishment order has not been marked shipped yet."}), 400
    product = Product.query.get(ro.product_id)
    if product:
        product.quantity_available = (product.quantity_available or 0) + ro.quantity
    ro.status = "received"
    ro.received_at = datetime.utcnow()
    agreement.last_replenished_at = datetime.utcnow()
    db.session.commit()
    return jsonify({"ok": True, "replenishment": ro.to_dict(),
                     "quantity_available": product.quantity_available if product else None}), 200


# ────────────────────────────────────────────────────────────
# 3) DROPSHIPPING SUPPLIER INTEGRATION
# ────────────────────────────────────────────────────────────
# A supplier lists catalog items with no seller inventory required.
# A seller imports one into their own storefront at a retail price
# of their choosing (a real Product row, flagged is_dropship). When
# a buyer pays for it, the order routes straight to the supplier as
# a fulfillment task (mirroring how Stage 351's Platform Fulfillment
# Centers already route warehouse orders) instead of the seller
# having to pack/ship anything themselves.
class DropshipSupplierProduct(db.Model):
    __tablename__      = "dropship_supplier_products"
    id                 = db.Column(db.Integer, primary_key=True)
    supplier_id        = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    name               = db.Column(db.String(150), nullable=False)
    description        = db.Column(db.Text, nullable=True)
    category           = db.Column(db.String(60), nullable=False, index=True)
    cost_price         = db.Column(db.Float, nullable=False)
    currency           = db.Column(db.String(8), nullable=False, default="USD")
    stock_quantity     = db.Column(db.Integer, nullable=False, default=0)
    unit               = db.Column(db.String(32), nullable=True)
    min_order_quantity = db.Column(db.Integer, nullable=False, default=1)
    image_urls         = db.Column(db.Text, nullable=True)  # JSON-encoded list
    is_active          = db.Column(db.Boolean, nullable=False, default=True, index=True)
    created_at         = db.Column(db.DateTime, default=datetime.utcnow)
    updated_at         = db.Column(db.DateTime, default=datetime.utcnow, onupdate=datetime.utcnow)

    def to_dict(self) -> dict:
        try:
            images = json.loads(self.image_urls) if self.image_urls else []
        except Exception:
            images = []
        supplier = UserAccount.query.get(self.supplier_id)
        return {
            "id": self.id, "supplier_id": self.supplier_id,
            "supplier_name": supplier.name if supplier else None,
            "name": self.name, "description": self.description, "category": self.category,
            "cost_price": self.cost_price, "currency": self.currency,
            "stock_quantity": self.stock_quantity, "unit": self.unit,
            "min_order_quantity": self.min_order_quantity, "images": images, "is_active": self.is_active,
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }


class DropshipFulfillmentTask(db.Model):
    __tablename__       = "dropship_fulfillment_tasks"
    id                  = db.Column(db.Integer, primary_key=True)
    order_id            = db.Column(db.Integer, db.ForeignKey("product_orders.id"), nullable=False, unique=True, index=True)
    supplier_id         = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    supplier_product_id = db.Column(db.Integer, db.ForeignKey("dropship_supplier_products.id"), nullable=False, index=True)
    quantity            = db.Column(db.Integer, nullable=False, default=1)
    status               = db.Column(db.String(12), nullable=False, default="pending", index=True)  # pending, shipped, cancelled
    tracking_number       = db.Column(db.String(100), nullable=True)
    carrier                = db.Column(db.String(50), nullable=True)
    created_at             = db.Column(db.DateTime, default=datetime.utcnow)
    shipped_at              = db.Column(db.DateTime, nullable=True)

    def to_dict(self) -> dict:
        order = ProductOrder.query.get(self.order_id)
        sp = DropshipSupplierProduct.query.get(self.supplier_product_id)
        return {
            "id": self.id, "order_id": self.order_id, "product_name": sp.name if sp else None,
            "quantity": self.quantity, "status": self.status,
            "tracking_number": self.tracking_number, "carrier": self.carrier,
            "shipping_address": order.shipping_address if order else None,
            "created_at": self.created_at.isoformat() if self.created_at else None,
            "shipped_at": self.shipped_at.isoformat() if self.shipped_at else None,
        }


def _dropship_route_order_paid(order: "ProductOrder", product: "Product") -> None:
    """Called right after a paid order's stock decrement. If this order
    was against an imported dropship listing, decrements the
    supplier's own stock and opens a fulfillment task assigned to the
    supplier, exactly mirroring _fulfillment_sync_order_paid's
    pattern for platform-warehouse orders."""
    if not _feature_enabled("dropshipping_supplier_integration") or not product or not product.is_dropship:
        return
    if not product.dropship_supplier_product_id:
        return
    sp = DropshipSupplierProduct.query.get(product.dropship_supplier_product_id)
    if not sp:
        return
    sp.stock_quantity = max(0, sp.stock_quantity - order.quantity)
    if not DropshipFulfillmentTask.query.filter_by(order_id=order.id).first():
        db.session.add(DropshipFulfillmentTask(order_id=order.id, supplier_id=sp.supplier_id,
                                                 supplier_product_id=sp.id, quantity=order.quantity))
    db.session.commit()
    try:
        send_user_push(sp.supplier_id, "New dropship order",
                        f"{order.quantity} x {sp.name} needs fulfillment — ships directly to the buyer.")
    except Exception as e:
        logging.error(f"[DROPSHIP PUSH ERROR] order={order.id}: {e}")


@app.route("/api/dropship/supplier-products", methods=["POST"])
@csrf.exempt
@requires_feature_flag("dropshipping_supplier_integration")
def dropship_create_supplier_product():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user: return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    name = (data.get("name") or "").strip()
    category = (data.get("category") or "").strip()
    if not name or not category:
        return jsonify({"error": "name and category are required."}), 400
    try:
        cost_price = float(data.get("cost_price"))
        stock_quantity = int(data.get("stock_quantity", 0))
    except (TypeError, ValueError):
        return jsonify({"error": "cost_price must be a number and stock_quantity a whole number."}), 400
    if cost_price <= 0 or stock_quantity < 0:
        return jsonify({"error": "cost_price must be positive and stock_quantity cannot be negative."}), 400
    sp = DropshipSupplierProduct(
        supplier_id=user["id"], name=name[:150], description=(data.get("description") or "").strip() or None,
        category=category[:60], cost_price=cost_price, currency=(data.get("currency") or "USD").strip()[:8],
        stock_quantity=stock_quantity, unit=(data.get("unit") or "").strip()[:32] or None,
        min_order_quantity=max(1, int(data.get("min_order_quantity", 1) or 1)),
        image_urls=json.dumps(data.get("images")) if isinstance(data.get("images"), list) else None,
    )
    db.session.add(sp)
    db.session.commit()
    return jsonify({"ok": True, "supplier_product": sp.to_dict()}), 201


