@requires_feature_flag("dropshipping_supplier_integration")
def dropship_browse_catalog():
    user = _get_current_user()
    if not user: return jsonify({"error": "Login required."}), 401
    q = DropshipSupplierProduct.query.filter_by(is_active=True).filter(DropshipSupplierProduct.stock_quantity > 0)
    category = (request.args.get("category") or "").strip()
    search = (request.args.get("search") or "").strip()
    if category:
        q = q.filter(DropshipSupplierProduct.category == category)
    if search:
        q = q.filter(DropshipSupplierProduct.name.ilike(f"%{search}%"))
    rows = q.order_by(DropshipSupplierProduct.created_at.desc()).limit(100).all()
    return jsonify([p.to_dict() for p in rows]), 200


@app.route("/api/dropship/import/<int:sp_id>", methods=["POST"])
@csrf.exempt
@requires_feature_flag("dropshipping_supplier_integration")
def dropship_import_product(sp_id):
    """Seller imports a supplier's catalog item into their own
    storefront as a real Product, at a retail price of their choosing
    (must at least cover the supplier's cost price)."""
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user: return jsonify({"error": "Login required."}), 401
    sp = DropshipSupplierProduct.query.filter_by(id=sp_id, is_active=True).first()
    if not sp: return jsonify({"error": "Supplier catalog item not found."}), 404
    data = request.get_json(silent=True) or {}
    try:
        retail_price = float(data.get("retail_price"))
    except (TypeError, ValueError):
        return jsonify({"error": "retail_price is required."}), 400
    if retail_price < sp.cost_price:
        return jsonify({"error": f"retail_price must be at least the supplier's cost price ({sp.cost_price} {sp.currency})."}), 400
    product = Product(
        seller_id=user["id"], name=sp.name, description=sp.description, category=sp.category,
        price=round(retail_price, 2), currency=sp.currency, quantity_available=sp.stock_quantity,
        unit=sp.unit, min_order_quantity=sp.min_order_quantity, image_urls=sp.image_urls,
        is_active=True, is_dropship=True, dropship_supplier_product_id=sp.id,
    )
    db.session.add(product)
    db.session.commit()
    return jsonify({"ok": True, "product": product.to_dict()}), 201


