@csrf.exempt
@requires_feature_flag("dropshipping_supplier_integration")
def dropship_fulfillment_task_ship(task_id):
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user: return jsonify({"error": "Login required."}), 401
    task = DropshipFulfillmentTask.query.filter_by(id=task_id, supplier_id=user["id"]).first()
    if not task or task.status != "pending":
        return jsonify({"error": "Fulfillment task not found or already actioned."}), 404
    data = request.get_json(silent=True) or {}
    tracking_number = (data.get("tracking_number") or "").strip()[:100] or None
    carrier = (data.get("carrier") or "").strip()[:50] or None
    task.status = "shipped"
    task.tracking_number = tracking_number
    task.carrier = carrier
    task.shipped_at = datetime.utcnow()
    # Mirror the tracking info onto the underlying order so the buyer
    # sees it in the same "Track my order" UI as every other order —
    # reuses ProductOrder's existing Stage 310 shipping columns rather
    # than inventing a second tracking surface for dropship orders.
    order = ProductOrder.query.get(task.order_id)
    if order:
        order.tracking_number = tracking_number
        order.carrier = carrier
        order.shipped_at = task.shipped_at
    db.session.commit()
    return jsonify({"ok": True, "task": task.to_dict()}), 200



# ════════════════════════════════════════════════════════════
# ENTERPRISE PROCUREMENT PACK — Purchase-Order Approval
# Workflows and Punchout/EDI Catalog Integration (cXML).
# Both new, admin-lockable programs (see PlatformFeatureFlag /
# requires_feature_flag near the top of this file) — every route
# below is gated behind its own flag and defaults LOCKED until a
# platform admin turns it on from the "Feature Flags — Lock /
# Unlock" panel, same as every other opt-in program on this
# platform. Both are built on top of the existing Organization /
# OrgMember workspace model (see _org_for_user / _org_member_or_403
# near the top of this file) rather than inventing a second team
# system.
# ════════════════════════════════════════════════════════════

import secrets as _secrets


# ────────────────────────────────────────────────────────────
# 1) PURCHASE-ORDER APPROVAL WORKFLOWS
# ────────────────────────────────────────────────────────────
# An org owner/admin defines a tiered approval policy by dollar
# amount ("orders over $X need an admin's sign-off; over $Y also
# need the owner's"). A 'member'-role buyer whose org has any policy
# configured can no longer check out directly — they submit a
# Purchase Requisition instead, which walks the applicable levels in
# order. Only once every applicable level has signed off does the
# requisition unlock an approval_token that the existing cart
# checkout (see cart_checkout) will accept. Owners/admins are never
# gated by their own org's policy — the same real-world distinction
# between "needs a sign-off" and "is a sign-off".
class ApprovalPolicy(db.Model):
    __tablename__     = "approval_policies"
    id                = db.Column(db.Integer, primary_key=True)
    org_id            = db.Column(db.Integer, db.ForeignKey("organizations.id"), nullable=False, index=True)
    level             = db.Column(db.Integer, nullable=False)
    threshold_amount  = db.Column(db.Float, nullable=False, default=0.0)
    approver_role     = db.Column(db.String(16), nullable=False, default="admin")  # admin or owner
    created_at        = db.Column(db.DateTime, default=datetime.utcnow)

    __table_args__ = (db.UniqueConstraint("org_id", "level", name="uq_approval_policy_org_level"),)

    def to_dict(self) -> dict:
        return {"id": self.id, "level": self.level, "threshold_amount": self.threshold_amount,
                "approver_role": self.approver_role}


class PurchaseRequisition(db.Model):
    __tablename__          = "purchase_requisitions"
    id                     = db.Column(db.Integer, primary_key=True)
    org_id                 = db.Column(db.Integer, db.ForeignKey("organizations.id"), nullable=False, index=True)
    requester_id           = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    title                  = db.Column(db.String(150), nullable=True)
    currency               = db.Column(db.String(8), nullable=False, default="USD")
    total_estimated_amount = db.Column(db.Float, nullable=False, default=0.0)
    status                 = db.Column(db.String(20), nullable=False, default="pending_approval", index=True)
    # pending_approval, approved, rejected, cancelled, converted
    current_level          = db.Column(db.Integer, nullable=True)
    approval_token         = db.Column(db.String(64), nullable=True, unique=True, index=True)
    created_at             = db.Column(db.DateTime, default=datetime.utcnow, index=True)
    decided_at             = db.Column(db.DateTime, nullable=True)

    def to_dict(self) -> dict:
        items = PurchaseRequisitionItem.query.filter_by(requisition_id=self.id).all()
        approvals = (PurchaseRequisitionApproval.query.filter_by(requisition_id=self.id)
                     .order_by(PurchaseRequisitionApproval.level.asc()).all())
        requester = UserAccount.query.get(self.requester_id)
        return {
            "id": self.id, "title": self.title, "requester_id": self.requester_id,
            "requester_name": requester.name if requester else None,
            "currency": self.currency, "total_estimated_amount": self.total_estimated_amount,
            "status": self.status, "current_level": self.current_level,
            "items": [i.to_dict() for i in items],
            "approvals": [a.to_dict() for a in approvals],
            "created_at": self.created_at.isoformat() if self.created_at else None,
            "decided_at": self.decided_at.isoformat() if self.decided_at else None,
        }


class PurchaseRequisitionItem(db.Model):
    __tablename__ = "purchase_requisition_items"
    id            = db.Column(db.Integer, primary_key=True)
    requisition_id = db.Column(db.Integer, db.ForeignKey("purchase_requisitions.id"), nullable=False, index=True)
    product_id    = db.Column(db.Integer, db.ForeignKey("products.id"), nullable=False)
    product_name_snapshot = db.Column(db.String(150), nullable=True)
    quantity      = db.Column(db.Integer, nullable=False, default=1)
    unit_price_snapshot = db.Column(db.Float, nullable=False, default=0.0)

    def to_dict(self) -> dict:
        return {"id": self.id, "product_id": self.product_id, "product_name": self.product_name_snapshot,
                "quantity": self.quantity, "unit_price": self.unit_price_snapshot,
                "line_total": round(self.quantity * self.unit_price_snapshot, 2)}


class PurchaseRequisitionApproval(db.Model):
    __tablename__ = "purchase_requisition_approvals"
    id            = db.Column(db.Integer, primary_key=True)
    requisition_id = db.Column(db.Integer, db.ForeignKey("purchase_requisitions.id"), nullable=False, index=True)
    level         = db.Column(db.Integer, nullable=False)
    approver_role_required = db.Column(db.String(16), nullable=False)
    decision      = db.Column(db.String(10), nullable=False, default="pending")  # pending, approved, rejected
    approver_user_id = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=True)
    note          = db.Column(db.String(300), nullable=True)
    decided_at    = db.Column(db.DateTime, nullable=True)

    def to_dict(self) -> dict:
        approver = UserAccount.query.get(self.approver_user_id) if self.approver_user_id else None
        return {"id": self.id, "level": self.level, "approver_role_required": self.approver_role_required,
                "decision": self.decision, "approver_name": approver.name if approver else None,
                "note": self.note, "decided_at": self.decided_at.isoformat() if self.decided_at else None}


def _procurement_role_outranks(role: str, required: str) -> bool:
    """Owner can sign off on anything an admin can; admin can only sign
    off on admin-level steps. Mirrors real org hierarchy."""
    if required == "admin":
        return role in ("owner", "admin")
    if required == "owner":
        return role == "owner"
    return False


def _procurement_create_requisition(org_id, requester_id, title, currency, item_lines):
    """item_lines: list of (product, quantity). Computes the total,
    determines which policy levels apply, and either auto-approves
    (no policy configured for this org) or opens the first pending
    approval level."""
    total = sum((p.price or 0) * q for p, q in item_lines)
    req = PurchaseRequisition(org_id=org_id, requester_id=requester_id, title=(title or "")[:150] or None,
                               currency=currency, total_estimated_amount=round(total, 2))
    db.session.add(req)
    db.session.flush()
    for product, qty in item_lines:
        db.session.add(PurchaseRequisitionItem(requisition_id=req.id, product_id=product.id,
                                                 product_name_snapshot=product.name, quantity=qty,
                                                 unit_price_snapshot=product.price or 0))
    policy_levels = (ApprovalPolicy.query.filter(ApprovalPolicy.org_id == org_id,
                                                  ApprovalPolicy.threshold_amount <= total)
                     .order_by(ApprovalPolicy.level.asc()).all())
    if not policy_levels:
        req.status = "approved"
        req.approval_token = _secrets.token_urlsafe(24)
        req.decided_at = datetime.utcnow()
    else:
        for lvl in policy_levels:
            db.session.add(PurchaseRequisitionApproval(requisition_id=req.id, level=lvl.level,
                                                         approver_role_required=lvl.approver_role))
        req.current_level = policy_levels[0].level
    db.session.commit()
    return req


