@app.route("/api/procurement/approval-policy", methods=["POST"])
@csrf.exempt
@requires_feature_flag("po_approval_workflows")
def procurement_set_policy():
    """Owner/admin replaces the whole tiered policy in one call — a
    list of {level, threshold_amount, approver_role}. Passing an empty
    list turns approval requirements off entirely for this org."""
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    org = _org_for_user(user["id"])
    if not org: return jsonify({"error": "You don't belong to a workspace yet."}), 404
    _, err = _org_member_or_403(user, org.id, roles=("owner", "admin"))
    if err: return err
    data = request.get_json(silent=True) or {}
    levels = data.get("levels")
    if not isinstance(levels, list):
        return jsonify({"error": "levels must be a list."}), 400
    parsed = []
    seen_levels = set()
    for lvl in levels:
        try:
            level_num = int(lvl.get("level"))
            threshold = float(lvl.get("threshold_amount"))
        except (TypeError, ValueError, AttributeError):
            return jsonify({"error": "Each level needs a whole-number level and a numeric threshold_amount."}), 400
        role = (lvl.get("approver_role") or "admin").strip()
        if role not in ("admin", "owner"):
            return jsonify({"error": "approver_role must be admin or owner."}), 400
        if level_num in seen_levels:
            return jsonify({"error": f"Level {level_num} is duplicated."}), 400
        seen_levels.add(level_num)
        parsed.append((level_num, threshold, role))
    ApprovalPolicy.query.filter_by(org_id=org.id).delete()
    for level_num, threshold, role in parsed:
        db.session.add(ApprovalPolicy(org_id=org.id, level=level_num, threshold_amount=threshold, approver_role=role))
    db.session.commit()
    _audit(org.id, user["id"], user["email"], "procurement.policy_updated", "organization", org.id,
           {"levels": len(parsed)})
    rows = ApprovalPolicy.query.filter_by(org_id=org.id).order_by(ApprovalPolicy.level.asc()).all()
    return jsonify({"ok": True, "levels": [r.to_dict() for r in rows]}), 200


@app.route("/api/procurement/requisitions", methods=["POST"])
@csrf.exempt
@requires_feature_flag("po_approval_workflows")
def procurement_create_requisition():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    org = _org_for_user(user["id"])
    if not org: return jsonify({"error": "You don't belong to a workspace yet."}), 404
    _, err = _org_member_or_403(user, org.id)
    if err: return err
    data = request.get_json(silent=True) or {}
    raw_items = data.get("items") or []
    if not raw_items or not isinstance(raw_items, list):
        return jsonify({"error": "At least one item is required."}), 400
    if len(raw_items) > 50:
        return jsonify({"error": "A requisition can hold up to 50 line items."}), 400
    lines = []
    currency = None
    for item in raw_items:
        try:
            product_id = int(item.get("product_id"))
            quantity = max(1, int(item.get("quantity", 1)))
        except (TypeError, ValueError):
            return jsonify({"error": "Invalid line item."}), 400
        product = Product.query.get(product_id)
        if not product or not product.is_active:
            return jsonify({"error": f"Product #{product_id} is not available."}), 400
        if currency is None:
            currency = product.currency or "USD"
        lines.append((product, quantity))
    req = _procurement_create_requisition(org.id, user["id"], data.get("title"), currency or "USD", lines)
    _audit(org.id, user["id"], user["email"], "procurement.requisition_created", "purchase_requisition", req.id,
           {"total": req.total_estimated_amount, "status": req.status})
    return jsonify({"ok": True, "requisition": req.to_dict()}), 201


