@app.route("/api/procurement/punchout-connections", methods=["POST"])
@csrf.exempt
@requires_feature_flag("punchout_edi_catalog")
def punchout_connection_upsert():
    """Owner/admin registers or rotates the shared secret their
    procurement system will authenticate with. from_identity must be
    globally unique across the platform (cXML has no separate
    per-supplier namespace for it)."""
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    org = _org_for_user(user["id"])
    if not org: return jsonify({"error": "You don't belong to a workspace yet."}), 404
    _, err = _org_member_or_403(user, org.id, roles=("owner", "admin"))
    if err: return err
    data = request.get_json(silent=True) or {}
    from_identity = (data.get("from_identity") or "").strip()
    shared_secret = data.get("shared_secret") or ""
    procurement_system = (data.get("procurement_system") or "other").strip()
    if procurement_system not in ("ariba", "coupa", "sap_srm", "other"):
        procurement_system = "other"
    if not from_identity or len(shared_secret) < 12:
        return jsonify({"error": "from_identity is required and shared_secret must be at least 12 characters."}), 400
    existing_other = PunchoutCatalogConnection.query.filter(
        PunchoutCatalogConnection.from_identity == from_identity, PunchoutCatalogConnection.org_id != org.id).first()
    if existing_other:
        return jsonify({"error": "That From Identity is already registered by another workspace — choose a unique one."}), 409
    conn = PunchoutCatalogConnection.query.filter_by(org_id=org.id).first()
    if not conn:
        conn = PunchoutCatalogConnection(org_id=org.id, to_identity=f"connectit-marketplace-{org.id}")
        db.session.add(conn)
    conn.from_identity = from_identity
    conn.procurement_system = procurement_system
    conn.set_shared_secret(shared_secret)
    conn.is_active = True
    db.session.commit()
    _audit(org.id, user["id"], user["email"], "procurement.punchout_connection_saved", "organization", org.id, {})
    return jsonify({"ok": True, "connection": conn.to_dict()}), 200


