@app.route("/api/procurement/punchout/session/<token>/login", methods=["POST"])
@csrf.exempt
def punchout_session_login(token):
    if not _feature_enabled("punchout_edi_catalog"):
        return jsonify({"error": "Not found."}), 404
    session_row = _punchout_session_or_none(token)
    if not session_row:
        return jsonify({"error": "Session expired."}), 410
    data = request.get_json(silent=True) or {}
    email = (data.get("email") or "").strip().lower()
    password = data.get("password") or ""
    account = UserAccount.query.filter(db.func.lower(UserAccount.email) == email).first()
    if not account or not account.check_password(password):
        return jsonify({"error": "Invalid email or password."}), 401
    member, err = _org_member_or_403({"id": account.id}, session_row.org_id)
    if err:
        return jsonify({"error": "This account does not belong to the workspace that owns this punch-out connection."}), 403
    session_row.requester_user_id = account.id
    session_row.status = "active"
    db.session.commit()
    return jsonify({"ok": True}), 200


@app.route("/api/procurement/punchout/session/<token>/catalog", methods=["GET"])
def punchout_session_catalog(token):
    if not _feature_enabled("punchout_edi_catalog"):
        return jsonify({"error": "Not found."}), 404
    session_row = _punchout_session_or_none(token)
    if not session_row or not session_row.requester_user_id:
        return jsonify({"error": "Session not ready."}), 401
    search = (request.args.get("search") or "").strip()
    q = Product.query.filter_by(is_active=True)
    if search:
        q = q.filter(Product.name.ilike(f"%{search}%"))
    rows = q.order_by(Product.created_at.desc()).limit(50).all()
    return jsonify({"products": [{"id": p.id, "name": p.name, "price": p.price, "currency": p.currency} for p in rows]}), 200


@app.route("/api/procurement/punchout/session/<token>/items", methods=["GET", "POST"])
@csrf.exempt
def punchout_session_items(token):
    if not _feature_enabled("punchout_edi_catalog"):
        return jsonify({"error": "Not found."}), 404
    session_row = _punchout_session_or_none(token)
    if not session_row or not session_row.requester_user_id:
        return jsonify({"error": "Session not ready."}), 401
    if request.method == "GET":
        rows = PunchoutSessionItem.query.filter_by(session_id=session_row.id).all()
        return jsonify({"items": [r.to_dict() for r in rows]}), 200
    data = request.get_json(silent=True) or {}
    try:
        product_id = int(data.get("product_id"))
        quantity = int(data.get("quantity", 1))
    except (TypeError, ValueError):
        return jsonify({"error": "Invalid item."}), 400
    existing = PunchoutSessionItem.query.filter_by(session_id=session_row.id, product_id=product_id).first()
    if quantity <= 0:
        if existing:
            db.session.delete(existing)
            db.session.commit()
        return jsonify({"ok": True}), 200
    product = Product.query.filter_by(id=product_id, is_active=True).first()
    if not product:
        return jsonify({"error": "Product not available."}), 404
    if not existing:
        existing = PunchoutSessionItem(session_id=session_row.id, product_id=product_id)
        db.session.add(existing)
    existing.quantity = quantity
    existing.product_name_snapshot = product.name
    existing.unit_price_snapshot = product.price or 0
    existing.currency_snapshot = product.currency or "USD"
    db.session.commit()
    return jsonify({"ok": True}), 200


@app.route("/api/procurement/punchout/session/<token>/return", methods=["POST"])
@csrf.exempt
def punchout_session_return(token):
    """Builds the cXML PunchOutOrderMessage and hands the frontend a
    URL-encoded payload to submit via a hidden browser form POST to
    the buyer's own BrowserFormPost URL — this is a browser-mediated
    handoff per the cXML spec, not a server-to-server call, so the
    buyer's procurement system receives it in the same request/session
    context the employee's browser is already in."""
    if not _feature_enabled("punchout_edi_catalog"):
        return jsonify({"error": "Not found."}), 404
    session_row = _punchout_session_or_none(token)
    if not session_row or not session_row.requester_user_id:
        return jsonify({"error": "Session not ready."}), 401
    items = PunchoutSessionItem.query.filter_by(session_id=session_row.id).all()
    if not items:
        return jsonify({"error": "Cart is empty."}), 400
    conn = PunchoutCatalogConnection.query.get(session_row.connection_id)
    item_xml = "".join(
        f'<ItemIn quantity="{i.quantity}"><ItemID><SupplierPartID>{xml_escape(str(i.product_id))}</SupplierPartID></ItemID>'
        f'<ItemDetail><UnitPrice><Money currency="{xml_escape(i.currency_snapshot)}">{i.unit_price_snapshot}</Money></UnitPrice>'
        f'<Description xml:lang="en">{xml_escape(i.product_name_snapshot or "")}</Description>'
        f'<UnitOfMeasure>EA</UnitOfMeasure></ItemDetail></ItemIn>'
        for i in items
    )
    total = round(sum(i.unit_price_snapshot * i.quantity for i in items), 2)
    currency = items[0].currency_snapshot if items else "USD"
    payload_id = f"{_secrets.token_hex(16)}@connectit-marketplace"
    cxml = (
        '<?xml version="1.0" encoding="UTF-8"?>'
        f'<cXML payloadID="{payload_id}" timestamp="{datetime.utcnow().isoformat()}Z">'
        '<Header><From><Credential domain="Connect It"><Identity>' + xml_escape(conn.to_identity if conn else "connectit-marketplace") + '</Identity></Credential></From>'
        '<To><Credential domain="Connect It"><Identity>' + xml_escape(conn.from_identity if conn else "") + '</Identity></Credential></To>'
        '<Sender><Credential domain="Connect It"><Identity>connectit-marketplace</Identity></Credential>'
        '<UserAgent>Connect It Marketplace Punchout</UserAgent></Sender></Header>'
        '<Message><PunchOutOrderMessage><BuyerCookie>' + xml_escape(session_row.buyer_cookie) + '</BuyerCookie>'
        '<PunchOutOrderMessageHeader operationAllowed="create">'
        f'<Total><Money currency="{xml_escape(currency)}">{total}</Money></Total>'
        '</PunchOutOrderMessageHeader>' + item_xml + '</PunchOutOrderMessage></Message></cXML>'
    )
    session_row.status = "returned"
    session_row.returned_at = datetime.utcnow()
    db.session.commit()
    _audit(session_row.org_id, session_row.requester_user_id, None, "procurement.punchout_cart_returned",
           "punchout_session", session_row.id, {"total": total, "item_count": len(items)})
    return jsonify({"ok": True, "cxml_urlencoded": urllib.parse.quote(cxml)}), 200


