# ════════════════════════════════════════════════════════════
# STAGE 516: PREDICTIVE SUPPLY CHAIN INTELLIGENCE
# (PORT DELAY & SHIPPING STRIKE RISK FORECASTING)
#
# Expands the Maersk Track & Trace integration (Stage 514g, above)
# from "what already happened to my container" into "what might
# happen next on this lane." Same honesty rule as the rest of the
# app: there is no invented ML model pretending to predict the
# future. Instead this combines three real, independently-checkable
# signals at request time:
#
#   1. Live news headlines (NewsAPI if a key is configured, else the
#      same keyless Google News RSS fallback the Discover feed uses)
#      mentioning strikes, congestion, backlogs or closures at the
#      named ports, filtered to the last 14 days.
#   2. Current weather at each port city, via the existing BYOK
#      OpenWeatherMap connection (Stage 23) — severe conditions slow
#      port operations regardless of any labor situation.
#   3. The business's own shipment history on this exact
#      origin -> destination lane (FreightShipment + Container
#      Tracking Events, Stage 502/514g already in this database) —
#      if transit times on this lane have been trending longer
#      recently, that's a real early-warning signal specific to this
#      business, not a generic industry average.
#
# Every factor is tagged with its real source so a user can verify
# it themselves. An empty section just means that signal genuinely
# found nothing right now — it is never padded with fabricated risk
# to look more "predictive" than the underlying data supports.
# ════════════════════════════════════════════════════════════

_RISK_NEWS_TIMEOUT = 6
_RISK_NEWS_LOOKBACK_DAYS = 14
_RISK_HIGH_KEYWORDS = ("strike", "shutdown", "shut down", "closure", "closed", "walkout", "blockade", "lockout", "picket")
_RISK_MEDIUM_KEYWORDS = ("congestion", "backlog", "delay", "delayed", "disruption", "bottleneck",
                          "understaffed", "labor dispute", "labour dispute", "gridlock", "port jam")
_RISK_SEVERE_WEATHER = ("storm", "hurricane", "typhoon", "cyclone", "tornado", "thunderstorm",
                         "blizzard", "heavy snow", "gale")


def _risk_classify_headline(title: str) -> str:
    t = (title or "").lower()
    if any(k in t for k in _RISK_HIGH_KEYWORDS):
        return "high"
    if any(k in t for k in _RISK_MEDIUM_KEYWORDS):
        return "medium"
    return "low"


def _risk_parse_pubdate(raw):
    if not raw:
        return None
    try:
        return parsedate_to_datetime(raw).replace(tzinfo=None)
    except Exception:
        pass
    try:
        return datetime.fromisoformat(raw.replace("Z", "+00:00")).replace(tzinfo=None)
    except Exception:
        return None


def _risk_port_news(port_name: str, role: str, limit: int = 5) -> list:
    """Real headlines about this port. Uses NewsAPI if configured,
    otherwise falls back to keyless Google News RSS — same source
    priority as the Discover feed's _discover_fetch_news."""
    if not port_name:
        return []
    factors = []
    query = f'"{port_name}" port (strike OR congestion OR delay OR backlog OR closure OR disruption OR shutdown)'
    articles = []
    try:
        if NEWS_API_KEY:
            r = requests.get(
                "https://newsapi.org/v2/everything",
                params={"q": query, "apiKey": NEWS_API_KEY, "language": "en",
                        "sortBy": "publishedAt", "pageSize": limit},
                timeout=_RISK_NEWS_TIMEOUT,
            )
            if r.ok:
                for a in (r.json().get("articles") or [])[:limit]:
                    articles.append({"title": a.get("title", ""), "url": a.get("url", ""),
                                      "source": (a.get("source", {}) or {}).get("name", "News"),
                                      "published": a.get("publishedAt", "")})
            else:
                logging.warning(f"NewsAPI returned {r.status_code} for port risk query")
        if not articles:
            r = requests.get(
                "https://news.google.com/rss/search",
                params={"q": query, "hl": "en-US", "gl": "US", "ceid": "US:en"},
                timeout=_RISK_NEWS_TIMEOUT,
            )
            if r.ok:
                root = ET.fromstring(r.content)
                for entry in root.findall(".//item")[:limit]:
                    title = (entry.findtext("title") or "").strip()
                    link = (entry.findtext("link") or "").strip()
                    pub = (entry.findtext("pubDate") or "").strip()
                    source_el = entry.find("source")
                    source_name = source_el.text if source_el is not None else "Google News"
                    articles.append({"title": title, "url": link, "source": source_name, "published": pub})
    except Exception as e:
        logging.error(f"[PORT RISK NEWS] {port_name}: {e}")
        return []

    cutoff = datetime.utcnow() - timedelta(days=_RISK_NEWS_LOOKBACK_DAYS)
    for a in articles:
        published_dt = _risk_parse_pubdate(a.get("published"))
        if published_dt and published_dt < cutoff:
            continue
        severity = _risk_classify_headline(a["title"])
        if severity == "low":
            continue
        factors.append({
            "type": "news", "role": role, "severity": severity,
            "message": f"{role.capitalize()} port ({port_name}): {a['title']}",
            "source": a.get("source"), "source_url": a.get("url") or None,
            "published": a.get("published") or None,
        })
    return factors


def _risk_port_weather(user_id, port_name: str, role: str) -> list:
    """Severe current weather at the port city, via the same BYOK
    OpenWeatherMap connection as Stage 23. Silently skipped (never
    faked) if no key is configured or the city can't be resolved."""
    if not port_name:
        return []
    result = get_current_weather(user_id, port_name)
    if not result.get("ok"):
        return []
    w = result.get("weather") or {}
    desc = (w.get("description") or "").lower()
    if not any(k in desc for k in _RISK_SEVERE_WEATHER):
        return []
    temp = w.get("temp")
    return [{
        "type": "weather", "role": role, "severity": "medium",
        "message": (f"{role.capitalize()} port ({port_name}): current conditions are "
                    f"\"{w.get('description')}\"" + (f" at {round(temp)}°" if temp is not None else "") +
                    " — severe weather can slow gate, crane and vessel operations."),
        "source": "OpenWeatherMap", "source_url": None, "published": None,
    }]


def _risk_lane_history(user_id, origin: str, destination: str) -> list:
    """Compares recent vs. older transit times on this exact
    origin -> destination lane, using this business's own
    FreightShipment + ContainerTrackingEvent records (Stage 502 /
    514g). Same recent-vs-older trend technique as the Fleet
    predictive alerts (_fleet_predictive_alerts) — a signal from the
    business's own real history, not an industry benchmark."""
    if not origin or not destination:
        return []
    shipments = FreightShipment.query.filter(
        FreightShipment.seller_id == user_id,
        db.func.lower(FreightShipment.origin) == origin.lower(),
        db.func.lower(FreightShipment.destination) == destination.lower(),
    ).all()
    if not shipments:
        return []
    shipment_ids = [s.id for s in shipments]
    events = (ContainerTrackingEvent.query
              .filter(ContainerTrackingEvent.owner_user_id == user_id,
                      ContainerTrackingEvent.shipment_id.in_(shipment_ids))
              .order_by(ContainerTrackingEvent.event_time.asc()).all())
    by_container = defaultdict(dict)
    for e in events:
        by_container[e.container_number].setdefault(e.milestone, e.event_time)

    durations = []
    for cn, milestones in by_container.items():
        dep = milestones.get("vessel_departed") or milestones.get("gate_in_origin")
        arr = milestones.get("vessel_arrived") or milestones.get("gate_out_destination")
        if dep and arr and arr > dep:
            durations.append((dep, (arr - dep).total_seconds() / 86400.0))
    if len(durations) < 4:
        return []

    durations.sort(key=lambda d: d[0])
    half = len(durations) // 2
    older_avg = sum(d[1] for d in durations[:half]) / half
    recent_avg = sum(d[1] for d in durations[half:]) / (len(durations) - half)
    if recent_avg - older_avg < 1.0:
        return []
    pct = ((recent_avg - older_avg) / older_avg * 100) if older_avg else 0
    return [{
        "type": "historical", "role": "lane", "severity": "high" if pct > 30 else "medium",
        "message": (f"Your own shipments on {origin} \u2192 {destination} have been taking longer recently: "
                    f"{round(recent_avg, 1)} days on average now vs {round(older_avg, 1)} days earlier "
                    f"({round(pct)}% slower) \u2014 worth building in extra buffer on this lane."),
        "source": "Your container tracking history", "source_url": None, "published": None,
    }]


@app.route("/api/logistics/port-risk-forecast", methods=["GET"])
def logistics_port_risk_forecast():
    user = _get_current_user()
    if not user: return jsonify({"error": "Login required."}), 401
    origin = (request.args.get("origin") or "").strip()[:120]
    destination = (request.args.get("destination") or "").strip()[:120]
    if not origin or not destination:
        return jsonify({"error": "origin and destination are required."}), 400

    factors = []
    factors += _risk_port_news(origin, "origin")
    factors += _risk_port_news(destination, "destination")
    factors += _risk_port_weather(user["id"], origin, "origin")
    factors += _risk_port_weather(user["id"], destination, "destination")
    factors += _risk_lane_history(user["id"], origin, destination)

    severity_order = {"high": 0, "medium": 1, "low": 2}
    factors.sort(key=lambda f: severity_order.get(f["severity"], 2))

    if any(f["severity"] == "high" for f in factors):
        risk_level = "high"
    elif any(f["severity"] == "medium" for f in factors):
        risk_level = "elevated"
    else:
        risk_level = "low"

    return jsonify({
        "ok": True, "origin": origin, "destination": destination,
        "risk_level": risk_level, "factors": factors,
        "news_source": "NewsAPI" if NEWS_API_KEY else "Google News (keyless, no API key needed)",
        "weather_configured": bool(get_effective_credential(user["id"], "openweathermap", "api_key", OPENWEATHERMAP_API_KEY)),
        "generated_at": datetime.utcnow().isoformat(),
    }), 200


@app.route("/api/freight/shipments/<int:shipment_id>/risk-forecast", methods=["GET"])
def freight_shipment_risk_forecast(shipment_id):
    """Same forecast as /api/logistics/port-risk-forecast, pre-filled
    from an existing FreightShipment's own origin/destination so the
    Container Tracking screen can offer a one-click forecast next to
    a shipment a user already has open."""
    user = _get_current_user()
    if not user: return jsonify({"error": "Login required."}), 401
    shipment = FreightShipment.query.filter_by(id=shipment_id, seller_id=user["id"]).first()
    if not shipment:
        return jsonify({"error": "Shipment not found."}), 404

    factors = []
    factors += _risk_port_news(shipment.origin, "origin")
    factors += _risk_port_news(shipment.destination, "destination")
    factors += _risk_port_weather(user["id"], shipment.origin, "origin")
    factors += _risk_port_weather(user["id"], shipment.destination, "destination")
    factors += _risk_lane_history(user["id"], shipment.origin, shipment.destination)

    severity_order = {"high": 0, "medium": 1, "low": 2}
    factors.sort(key=lambda f: severity_order.get(f["severity"], 2))
    if any(f["severity"] == "high" for f in factors):
        risk_level = "high"
    elif any(f["severity"] == "medium" for f in factors):
        risk_level = "elevated"
    else:
        risk_level = "low"

    return jsonify({
        "ok": True, "shipment_id": shipment.id,
        "origin": shipment.origin, "destination": shipment.destination,
        "risk_level": risk_level, "factors": factors,
        "news_source": "NewsAPI" if NEWS_API_KEY else "Google News (keyless, no API key needed)",
        "generated_at": datetime.utcnow().isoformat(),
    }), 200


# ════════════════════════════════════════════════════════════
# STAGE 517: COMMUNITY-LED (PEER JURY) DISPUTE RESOLUTION
#
# The existing Escrow & Disputes flow (Stage above) already supports
# two resolution paths: mutual agreement between buyer and seller, or
# an admin stepping in. This adds a real third path in between those
# two — a small panel of trusted platform members (not staff) votes
# on the same release/refund/split resolution an admin would choose,
# using the platform's own Connect It Trust Score as the eligibility bar
# rather than a title or a paid role. Either party on an open,
# unresolved dispute can request this instead of waiting on an admin.
#
# Design choices, and why:
#   - Eligibility is the same real Trust Score (compute_trust_score,
#     defined above) every other trust-gated feature on this platform
#     already uses — no separate "reputation" system invented just for
#     this. Re-checked at selection time (not just at opt-in) the same
#     way the Marketplace Directory's trust gate is re-checked per
#     query rather than cached, so a juror's standing has to still be
#     current, not just historical.
#   - Jurors never see each other's votes before casting their own
#     (avoids anchoring/groupthink), and the disputing parties never
#     see which named juror cast which vote — only the aggregate
#     tally once a decision is reached — the same protection a real
#     jury gets from deliberating in private.
#   - The panel is a plain majority of a small, fixed panel size. No
#     weighting, no invented "confidence score" — a majority vote is
#     the one mechanism that's fully explainable to both sides.
#   - A juror is excluded from ever sitting on a dispute involving
#     their own trade, and jurors already sitting on several undecided
#     panels are skipped so jury duty doesn't concentrate on a small
#     handful of very active users.
# ════════════════════════════════════════════════════════════

JURY_MIN_TRUST_SCORE   = 60.0   # same 0-100 scale as compute_trust_score()
JURY_PANEL_SIZE        = 3
JURY_MAX_OPEN_DUTY     = 5      # a juror already sitting on this many undecided panels is skipped for new ones


class PeerJuryPool(db.Model):
    __tablename__ = "peer_jury_pool"
    id             = db.Column(db.Integer, primary_key=True)
    user_id        = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, unique=True, index=True)
    active         = db.Column(db.Boolean, nullable=False, default=True)
    joined_at      = db.Column(db.DateTime, default=datetime.utcnow)
    disputes_judged = db.Column(db.Integer, nullable=False, default=0)
    # How many of this juror's cast votes matched the eventual panel
    # majority — a self-reported quality signal shown back to the
    # juror themselves, not used to include/exclude them from future
    # panels (that would just reward voting with the crowd).
    majority_agreement_count = db.Column(db.Integer, nullable=False, default=0)

    def to_dict(self):
        return {
            "active": self.active, "joined_at": self.joined_at.isoformat() if self.joined_at else None,
            "disputes_judged": self.disputes_judged,
            "majority_agreement_rate": (round(self.majority_agreement_count / self.disputes_judged * 100, 1)
                                         if self.disputes_judged else None),
        }


class PeerJuryAssignment(db.Model):
    __tablename__  = "peer_jury_assignments"
    id             = db.Column(db.Integer, primary_key=True)
    dispute_id     = db.Column(db.Integer, db.ForeignKey("escrow_disputes.id"), nullable=False, index=True)
    juror_user_id  = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    assigned_at    = db.Column(db.DateTime, default=datetime.utcnow)
    vote_resolution = db.Column(db.String(10), nullable=True)  # release, refund, split
    vote_comment   = db.Column(db.String(500), nullable=True)
    voted_at       = db.Column(db.DateTime, nullable=True)

    def to_dict(self):
        return {
            "id": self.id, "dispute_id": self.dispute_id,
            "assigned_at": self.assigned_at.isoformat() if self.assigned_at else None,
            "has_voted": bool(self.voted_at),
            "voted_at": self.voted_at.isoformat() if self.voted_at else None,
        }


def _jury_eligible_candidates(exclude_user_ids):
    """Active pool members, re-checked against the live Trust Score
    right now (not a cached value from whenever they opted in), minus
    anyone tied to this trade and anyone already overloaded with open
    jury duty. Mirrors the dynamic-gate pattern MARKETPLACE_MIN_TRUST_SCORE
    already uses elsewhere in this file (gate applied in Python at
    query time, not stored)."""
    pool = PeerJuryPool.query.filter_by(active=True).all()
    candidates = []
    for p in pool:
        if p.user_id in exclude_user_ids:
            continue
        open_duty = PeerJuryAssignment.query.filter_by(juror_user_id=p.user_id, voted_at=None).count()
        if open_duty >= JURY_MAX_OPEN_DUTY:
            continue
        trust = compute_trust_score(p.user_id)
        if trust["score"] < JURY_MIN_TRUST_SCORE:
            continue
        candidates.append(p.user_id)
    return candidates


@app.route("/api/escrow/jury/status", methods=["GET"])
def escrow_jury_status():
    user = _get_current_user()
    if not user: return jsonify({"error": "Login required."}), 401
    trust = compute_trust_score(user["id"])
    membership = PeerJuryPool.query.filter_by(user_id=user["id"]).first()
    return jsonify({
        "eligible": trust["score"] >= JURY_MIN_TRUST_SCORE,
        "trust_score": trust["score"], "trust_grade": trust["grade"],
        "min_trust_score": JURY_MIN_TRUST_SCORE,
        "membership": membership.to_dict() if membership else None,
    }), 200


@app.route("/api/escrow/jury/opt-in", methods=["POST"])
@csrf.exempt
def escrow_jury_opt_in():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user: return jsonify({"error": "Login required."}), 401
    trust = compute_trust_score(user["id"])
    if trust["score"] < JURY_MIN_TRUST_SCORE:
        return jsonify({"error": f"A Trust Score of at least {JURY_MIN_TRUST_SCORE} is required to join the "
                                  f"jury pool (yours is currently {trust['score']})."}), 400
    membership = PeerJuryPool.query.filter_by(user_id=user["id"]).first()
    if membership:
        membership.active = True
    else:
        membership = PeerJuryPool(user_id=user["id"], active=True)
        db.session.add(membership)
    db.session.commit()
    return jsonify({"ok": True, "membership": membership.to_dict()}), 200


@app.route("/api/escrow/jury/opt-out", methods=["POST"])
@csrf.exempt
def escrow_jury_opt_out():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user: return jsonify({"error": "Login required."}), 401
    membership = PeerJuryPool.query.filter_by(user_id=user["id"]).first()
    if not membership:
        return jsonify({"error": "You're not in the jury pool."}), 400
    membership.active = False
    db.session.commit()
    return jsonify({"ok": True}), 200


@app.route("/api/escrow/dispute/<int:dispute_id>/escalate-to-jury", methods=["POST"])
@csrf.exempt
def escrow_dispute_escalate_to_jury(dispute_id):
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user: return jsonify({"error": "Login required."}), 401
    dispute, escrow = _dispute_for_party(dispute_id, user["id"])
    if not dispute:
        return jsonify({"error": "Dispute not found."}), 404
    if dispute.status != "open":
        return jsonify({"error": "This dispute is already resolved."}), 400
    if dispute.jury_status != "none":
        return jsonify({"error": "This dispute is already with a peer jury."}), 400

    candidates = _jury_eligible_candidates({escrow.buyer_id, escrow.seller_id})
    if len(candidates) < JURY_PANEL_SIZE:
        return jsonify({"error": f"Not enough eligible jurors in the pool right now "
                                  f"({len(candidates)} available, {JURY_PANEL_SIZE} needed). "
                                  f"Try mutual proposal/accept, or ask an admin to step in."}), 400

    panel = random.sample(candidates, JURY_PANEL_SIZE)
    for juror_id in panel:
        db.session.add(PeerJuryAssignment(dispute_id=dispute.id, juror_user_id=juror_id))
    dispute.jury_status = "pending_votes"
    db.session.commit()
    return jsonify({"ok": True, "dispute": dispute.to_dict()}), 200


@app.route("/api/escrow/jury/my-duty", methods=["GET"])
def escrow_jury_my_duty():
    user = _get_current_user()
    if not user: return jsonify({"error": "Login required."}), 401
    assignments = (PeerJuryAssignment.query.filter_by(juror_user_id=user["id"], voted_at=None)
                   .order_by(PeerJuryAssignment.assigned_at.asc()).all())
    duty = []
    for a in assignments:
        dispute = EscrowDispute.query.get(a.dispute_id)
        if not dispute:
            continue
        escrow = EscrowTransaction.query.get(dispute.escrow_id)
        msgs = (EscrowDisputeMessage.query.filter_by(dispute_id=dispute.id)
                .order_by(EscrowDisputeMessage.created_at.asc()).all())
        duty.append({
            "assignment_id": a.id, "dispute_id": dispute.id,
            "reason": dispute.reason,
            "escrow_description": escrow.description if escrow else None,
            "escrow_amount": escrow.amount if escrow else None,
            "escrow_currency": escrow.currency if escrow else None,
            "messages": [m.to_dict() for m in msgs],
            "assigned_at": a.assigned_at.isoformat() if a.assigned_at else None,
        })
    return jsonify({"duty": duty}), 200


@app.route("/api/escrow/jury/assignment/<int:assignment_id>/vote", methods=["POST"])
@csrf.exempt
def escrow_jury_vote(assignment_id):
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user: return jsonify({"error": "Login required."}), 401
    assignment = PeerJuryAssignment.query.filter_by(id=assignment_id, juror_user_id=user["id"]).first()
    if not assignment:
        return jsonify({"error": "Jury assignment not found."}), 404
    if assignment.voted_at:
        return jsonify({"error": "You've already voted on this dispute."}), 400
    dispute = EscrowDispute.query.get(assignment.dispute_id)
    if not dispute or dispute.status != "open" or dispute.jury_status != "pending_votes":
        return jsonify({"error": "This dispute is no longer awaiting jury votes."}), 400

    data = request.get_json(silent=True) or {}
    resolution = (data.get("resolution") or "").strip().lower()
    if resolution not in ESCROW_RESOLUTIONS:
        return jsonify({"error": "resolution must be release, refund, or split."}), 400
    comment = (data.get("comment") or "").strip()[:500] or None

    assignment.vote_resolution = resolution
    assignment.vote_comment = comment
    assignment.voted_at = datetime.utcnow()
    db.session.commit()

    panel = PeerJuryAssignment.query.filter_by(dispute_id=dispute.id).all()
    if all(a.voted_at for a in panel):
        tally = {}
        for a in panel:
            tally[a.vote_resolution] = tally.get(a.vote_resolution, 0) + 1
        winning_resolution, winning_votes = max(tally.items(), key=lambda kv: kv[1])
        # A genuine tie across a 3-seat panel isn't possible (3 votes,
        # 3 options can't split evenly with a plain majority), but for
        # any future larger panel size this leaves it with an admin
        # rather than silently picking one at random.
        is_majority = winning_votes > len(panel) / 2
        if is_majority:
            escrow = EscrowTransaction.query.get(dispute.escrow_id)
            _apply_escrow_resolution(escrow, winning_resolution, resolved_by="peer_jury")
            dispute.status = "resolved"
            dispute.resolution = winning_resolution
            dispute.resolved_by = "peer_jury"
            dispute.resolution_note = "Decided by peer jury vote: " + ", ".join(
                f"{count} for {res}" for res, count in sorted(tally.items(), key=lambda kv: -kv[1]))
            dispute.resolved_at = datetime.utcnow()
            dispute.jury_status = "decided"
            for a in panel:
                pool_row = PeerJuryPool.query.filter_by(user_id=a.juror_user_id).first()
                if pool_row:
                    pool_row.disputes_judged += 1
                    if a.vote_resolution == winning_resolution:
                        pool_row.majority_agreement_count += 1
            db.session.commit()
        else:
            dispute.jury_status = "needs_admin"
            dispute.resolution_note = "Peer jury vote had no clear majority — routed to admin for final resolution."
            db.session.commit()

    return jsonify({"ok": True, "assignment": assignment.to_dict(), "dispute": dispute.to_dict()}), 200


# ════════════════════════════════════════════════════════════
# STAGE 518: PUBLIC PRODUCT Q&A (roadmap feature #62)
# Closes a real gap: every buyer question about a listing has, until
# now, only ever gone through the private MarketplaceInquiry/DirectMessage
# channels — answered once, for one buyer, then invisible to every future
# visitor who has the exact same question. This adds a lightweight,
# per-product Q&A thread that's public once answered (like the "Q: … A:
# …" sections on Alibaba/Amazon product pages), while an unanswered
# question stays visible only to the asker and the seller until the
# seller replies — so a listing's public Q&A is never a queue of
# unanswered noise, only real answered questions building trust for the
# next visitor.
#
# Design choices, all deliberate:
#   • New table, not bolted onto MarketplaceInquiry — that table's FK is
#     a MarketplaceListing (the barter/matching directory), not a
#     Product (Stage 302's actual product catalog), and its shape
#     (one message + one reply, buyer-specific) doesn't fit "public
#     once answered."
#   • seller_id is denormalized onto the row at creation time (copied
#     from Product.seller_id) so an answer-permission check and a
#     seller's cross-product "questions to answer" queue never require
#     a join back through Product for every row.
#   • is_hidden lets a seller moderate an inappropriate/spam question
#     off their public page without deleting the row outright (keeps an
#     audit trail); hidden questions never show to anyone but the
#     seller and the original asker.
#   • Answering and asking both raise a real Notification via the
#     existing notify_user() helper (Stage-level Notifications system)
#     rather than a silent write — a seller actually finds out a buyer
#     is waiting, and a buyer actually finds out their question got a
#     reply, without needing to keep the product page open.
# ════════════════════════════════════════════════════════════

class ProductQuestion(db.Model):
    __tablename__ = "product_questions"
    id           = db.Column(db.Integer, primary_key=True)
    product_id   = db.Column(db.Integer, db.ForeignKey("products.id"), nullable=False, index=True)
    seller_id    = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    asker_id     = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    question     = db.Column(db.String(500), nullable=False)
    answer       = db.Column(db.String(1500), nullable=True)
    is_hidden    = db.Column(db.Boolean, nullable=False, default=False, index=True)
    created_at   = db.Column(db.DateTime, default=datetime.utcnow, index=True)
    answered_at  = db.Column(db.DateTime, nullable=True)

    def to_dict(self, viewer_id=None):
        asker = UserAccount.query.get(self.asker_id)
        asker_name = (asker.name if asker else None) or "A buyer"
        return {
            "id": self.id,
            "product_id": self.product_id,
            "question": self.question,
            "answer": self.answer,
            "is_answered": bool(self.answer),
            "is_hidden": self.is_hidden,
            "asker_name": asker_name,
            "is_mine": bool(viewer_id) and viewer_id == self.asker_id,
            "created_at": self.created_at.isoformat() if self.created_at else None,
            "answered_at": self.answered_at.isoformat() if self.answered_at else None,
        }


@app.route("/api/products/<int:product_id>/questions", methods=["GET"])
def product_questions_list(product_id):
    """Public — no login required, same spirit as the storefront's
    written-reviews section. Anonymous and unrelated visitors only ever
    see answered, non-hidden questions. The seller additionally sees
    their own unanswered queue (so this same endpoint powers both the
    public product page and the seller's own 'questions to answer'
    view); an asker also always sees their own question even before
    it's answered, so they know it went through."""
    product = Product.query.get(product_id)
    if not product:
        return jsonify({"error": "Product not found."}), 404
    user = _get_current_user()
    viewer_id = user["id"] if user else None
    is_seller = bool(viewer_id) and viewer_id == product.seller_id

    rows = (ProductQuestion.query.filter_by(product_id=product_id, is_hidden=False)
            .order_by(ProductQuestion.created_at.desc()).all())
    visible = [q for q in rows if q.answer or is_seller or (viewer_id and viewer_id == q.asker_id)]
    unanswered_count = sum(1 for q in rows if not q.answer)
    return jsonify({
        "questions": [q.to_dict(viewer_id=viewer_id) for q in visible],
        "unanswered_count": unanswered_count if is_seller else None,
    }), 200


@app.route("/api/products/<int:product_id>/questions", methods=["POST"])
@csrf.exempt
def product_questions_ask(product_id):
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    product = Product.query.get(product_id)
    if not product or not product.is_active:
        return jsonify({"error": "Product not found."}), 404
    if product.seller_id == user["id"]:
        return jsonify({"error": "You can't ask a question on your own listing."}), 400
    data = request.get_json(silent=True) or {}
    question = (data.get("question") or "").strip()[:500]
    if not question:
        return jsonify({"error": "question is required."}), 400

    row = ProductQuestion(product_id=product_id, seller_id=product.seller_id,
                           asker_id=user["id"], question=question)
    db.session.add(row)
    db.session.commit()

    notify_user(product.seller_id, "product_qa", f"New question on {product.name}",
                body=question, link=f"{APP_BASE_URL}/?product={product.id}")
    return jsonify({"ok": True, "question": row.to_dict(viewer_id=user["id"])}), 201


@app.route("/api/products/questions/pending", methods=["GET"])
def product_questions_pending():
    """A seller's own cross-product queue of unanswered questions —
    surfaced in the Sell tab so a listing's Q&A doesn't quietly go
    stale just because the seller never happened to reopen that one
    product page."""
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    rows = (ProductQuestion.query.filter_by(seller_id=user["id"], is_hidden=False)
            .filter(ProductQuestion.answer.is_(None))
            .order_by(ProductQuestion.created_at.asc()).all())
    out = []
    for q in rows:
        d = q.to_dict(viewer_id=user["id"])
        product = Product.query.get(q.product_id)
        d["product_name"] = product.name if product else None
        out.append(d)
    return jsonify({"questions": out}), 200


@app.route("/api/products/questions/<int:question_id>/answer", methods=["POST"])
@csrf.exempt
def product_questions_answer(question_id):
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    row = ProductQuestion.query.filter_by(id=question_id, seller_id=user["id"]).first()
    if not row:
        return jsonify({"error": "Question not found."}), 404
    data = request.get_json(silent=True) or {}
    answer = (data.get("answer") or "").strip()[:1500]
    if not answer:
        return jsonify({"error": "answer is required."}), 400
    row.answer = answer
    row.answered_at = datetime.utcnow()
    db.session.commit()

    product = Product.query.get(row.product_id)
    notify_user(row.asker_id, "product_qa",
                f"Your question was answered — {product.name if product else 'listing'}",
                body=answer, link=f"{APP_BASE_URL}/?product={row.product_id}")
    return jsonify({"ok": True, "question": row.to_dict(viewer_id=user["id"])}), 200


@app.route("/api/products/questions/<int:question_id>/hide", methods=["POST"])
@csrf.exempt
def product_questions_hide(question_id):
    """Seller-only moderation: pull an inappropriate/spam question off
    the public page without erasing the row. Hidden questions stop
    appearing to everyone, including the original asker's own view."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user:
        return jsonify({"error": "Login required."}), 401
    row = ProductQuestion.query.filter_by(id=question_id, seller_id=user["id"]).first()
    if not row:
        return jsonify({"error": "Question not found."}), 404
    row.is_hidden = True
    db.session.commit()
    return jsonify({"ok": True}), 200


# ════════════════════════════════════════════════════════════════════
# ENTERPRISE PROCUREMENT PACK (cont'd) — FRANCHISE / MULTI-LOCATION
# LICENSING MANAGEMENT. A seller ("franchisor") registers a brand;
# other users apply to run a location under it ("franchisee"); once
# approved, a franchisee tags their own real listings with that
# license, and every paid order against a tagged listing automatically
# logs a royalty charge to the franchisor — computed from the order's
# real total_price, at a rate the franchisor set. Nothing here
# collects money automatically: royalty charges are a real, computed
# ledger the franchisor can mark "collected" once paid outside the
# platform (or, for a franchisor already on Stripe Connect, a manual
# transfer button reusing the exact same stripe.Transfer.create()
# pattern used elsewhere in this file), same honesty pattern as
# consignment vendor settlement — never a fabricated "paid" status.
# ════════════════════════════════════════════════════════════════════
class FranchiseBrand(db.Model):
    __tablename__ = "franchise_brands"
    id                  = db.Column(db.Integer, primary_key=True)
    franchisor_user_id  = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    brand_name          = db.Column(db.String(150), nullable=False)
    brand_code          = db.Column(db.String(16), nullable=False, unique=True, index=True)
    description         = db.Column(db.Text, nullable=True)
    default_royalty_pct = db.Column(db.Float, nullable=False, default=5.0)  # % of each order's total_price
    is_active            = db.Column(db.Boolean, nullable=False, default=True)
    created_at            = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self):
        return {
            "id": self.id, "brand_name": self.brand_name, "brand_code": self.brand_code,
            "description": self.description, "default_royalty_pct": self.default_royalty_pct,
            "is_active": self.is_active, "created_at": self.created_at.isoformat() if self.created_at else None,
        }


class FranchiseLicense(db.Model):
    __tablename__ = "franchise_licenses"
    id                 = db.Column(db.Integer, primary_key=True)
    brand_id           = db.Column(db.Integer, db.ForeignKey("franchise_brands.id"), nullable=False, index=True)
    licensee_user_id   = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    location_name      = db.Column(db.String(150), nullable=False)
    city               = db.Column(db.String(120), nullable=True)
    country_code       = db.Column(db.String(4), nullable=True)
    royalty_pct        = db.Column(db.Float, nullable=True)  # None = inherit brand.default_royalty_pct
    status             = db.Column(db.String(20), nullable=False, default="pending")  # pending/active/rejected/revoked
    applied_at         = db.Column(db.DateTime, default=datetime.utcnow)
    decided_at          = db.Column(db.DateTime, nullable=True)

    def effective_royalty_pct(self):
        if self.royalty_pct is not None:
            return self.royalty_pct
        brand = FranchiseBrand.query.get(self.brand_id)
        return brand.default_royalty_pct if brand else 5.0

    def to_dict(self):
        brand = FranchiseBrand.query.get(self.brand_id)
        licensee = UserAccount.query.get(self.licensee_user_id)
        return {
            "id": self.id, "brand_id": self.brand_id, "brand_name": brand.brand_name if brand else None,
            "licensee_user_id": self.licensee_user_id, "licensee_name": licensee.name if licensee else None,
            "location_name": self.location_name, "city": self.city, "country_code": self.country_code,
            "royalty_pct": self.effective_royalty_pct(), "status": self.status,
            "applied_at": self.applied_at.isoformat() if self.applied_at else None,
            "decided_at": self.decided_at.isoformat() if self.decided_at else None,
        }


class FranchiseRoyaltyCharge(db.Model):
    __tablename__ = "franchise_royalty_charges"
    id           = db.Column(db.Integer, primary_key=True)
    license_id   = db.Column(db.Integer, db.ForeignKey("franchise_licenses.id"), nullable=False, index=True)
    order_id     = db.Column(db.Integer, db.ForeignKey("product_orders.id"), nullable=False, index=True)
    amount       = db.Column(db.Float, nullable=False)
    currency     = db.Column(db.String(8), nullable=False, default="USD")
    status       = db.Column(db.String(20), nullable=False, default="owed")  # owed/collected
    created_at    = db.Column(db.DateTime, default=datetime.utcnow)
    collected_at  = db.Column(db.DateTime, nullable=True)

    def to_dict(self):
        license_ = FranchiseLicense.query.get(self.license_id)
        return {
            "id": self.id, "license_id": self.license_id,
            "location_name": license_.location_name if license_ else None,
            "order_id": self.order_id, "amount": self.amount, "currency": self.currency,
            "status": self.status, "created_at": self.created_at.isoformat() if self.created_at else None,
            "collected_at": self.collected_at.isoformat() if self.collected_at else None,
        }


def _franchise_charge_royalty_if_licensed(order, product):
    """No-op unless the sold listing is tagged with an active franchise
    license and the feature flag is unlocked — mirrors the VMI/dropship
    guard pattern right above this call site."""
    if not _feature_enabled("franchise_licensing") or not product or not product.franchise_license_id:
        return
    license_ = FranchiseLicense.query.get(product.franchise_license_id)
    if not license_ or license_.status != "active":
        return
    amount = round(order.total_price * (license_.effective_royalty_pct() / 100.0), 2)
    if amount <= 0:
        return
    charge = FranchiseRoyaltyCharge(
        license_id=license_.id, order_id=order.id, amount=amount,
        currency=(order.currency or "USD"),
    )
    db.session.add(charge)
    db.session.commit()
    brand = FranchiseBrand.query.get(license_.brand_id)
    if brand:
        try:
            send_user_push(brand.franchisor_user_id, "New franchise royalty charge",
                            f"{license_.location_name}: {order.currency} {amount} owed from a new sale.")
        except Exception as e:
            logging.error(f"[FRANCHISE ROYALTY PUSH ERROR] license={license_.id}: {e}")


def _franchise_brand_code():
    code = ("FR" + secrets.token_hex(4)).upper()
    while FranchiseBrand.query.filter_by(brand_code=code).first():
        code = ("FR" + secrets.token_hex(4)).upper()
    return code


@app.route("/api/franchise/brands", methods=["POST"])
@csrf.exempt
@requires_feature_flag("franchise_licensing")
def franchise_create_brand():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user: return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    brand_name = (data.get("brand_name") or "").strip()
    if not brand_name:
        return jsonify({"error": "brand_name is required."}), 400
    try:
        royalty_pct = float(data.get("default_royalty_pct", 5.0))
    except (TypeError, ValueError):
        return jsonify({"error": "default_royalty_pct must be a number."}), 400
    if royalty_pct < 0 or royalty_pct > 50:
        return jsonify({"error": "default_royalty_pct must be between 0 and 50."}), 400
    brand = FranchiseBrand(
        franchisor_user_id=user["id"], brand_name=brand_name[:150], brand_code=_franchise_brand_code(),
        description=(data.get("description") or "").strip()[:2000] or None,
        default_royalty_pct=royalty_pct,
    )
    db.session.add(brand)
    db.session.commit()
    return jsonify({"ok": True, "brand": brand.to_dict()}), 201


