@app.route("/api/franchise/licenses/apply", methods=["POST"])
@csrf.exempt
@requires_feature_flag("franchise_licensing")
def franchise_license_apply():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user: return jsonify({"error": "Login required."}), 401
    data = request.get_json(silent=True) or {}
    code = (data.get("brand_code") or "").strip().upper()
    location_name = (data.get("location_name") or "").strip()
    brand = FranchiseBrand.query.filter_by(brand_code=code, is_active=True).first()
    if not brand:
        return jsonify({"error": "No active franchise brand matches that code."}), 404
    if not location_name:
        return jsonify({"error": "location_name is required."}), 400
    if brand.franchisor_user_id == user["id"]:
        return jsonify({"error": "You can't apply to license your own brand."}), 400
    existing = FranchiseLicense.query.filter_by(
        brand_id=brand.id, licensee_user_id=user["id"], location_name=location_name[:150]).first()
    if existing and existing.status in ("pending", "active"):
        return jsonify({"error": "You already have an application/license for this location under this brand."}), 400
    lic = FranchiseLicense(
        brand_id=brand.id, licensee_user_id=user["id"], location_name=location_name[:150],
        city=(data.get("city") or "").strip()[:120] or None,
        country_code=(data.get("country_code") or "").strip()[:4] or None,
    )
    db.session.add(lic)
    db.session.commit()
    try:
        send_user_push(brand.franchisor_user_id, "New franchise application",
                        f'A new applicant wants to license "{brand.brand_name}" for {location_name}.')
    except Exception as e:
        logging.error(f"[FRANCHISE APPLY PUSH ERROR] brand={brand.id}: {e}")
    return jsonify({"ok": True, "license": lic.to_dict()}), 201


