@app.route("/api/franchise/licenses/<int:license_id>/decision", methods=["POST"])
@csrf.exempt
@requires_feature_flag("franchise_licensing")
def franchise_license_decision(license_id):
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user: return jsonify({"error": "Login required."}), 401
    lic = FranchiseLicense.query.get(license_id)
    if not lic: return jsonify({"error": "License not found."}), 404
    brand = FranchiseBrand.query.get(lic.brand_id)
    if not brand or brand.franchisor_user_id != user["id"]:
        return jsonify({"error": "License not found."}), 404
    if lic.status != "pending":
        return jsonify({"error": "This application has already been decided."}), 400
    data = request.get_json(silent=True) or {}
    decision = (data.get("decision") or "").strip().lower()
    if decision not in ("approve", "reject"):
        return jsonify({"error": "decision must be 'approve' or 'reject'."}), 400
    lic.status = "active" if decision == "approve" else "rejected"
    if decision == "approve" and data.get("royalty_pct") not in (None, ""):
        try:
            rp = float(data.get("royalty_pct"))
            if 0 <= rp <= 50:
                lic.royalty_pct = rp
        except (TypeError, ValueError):
            pass
    lic.decided_at = datetime.utcnow()
    db.session.commit()
    try:
        send_user_push(lic.licensee_user_id, f"Franchise application {lic.status}",
                        f'Your application for "{brand.brand_name}" — {lic.location_name} was {lic.status}.')
    except Exception as e:
        logging.error(f"[FRANCHISE DECISION PUSH ERROR] license={lic.id}: {e}")
    return jsonify({"ok": True, "license": lic.to_dict()}), 200


@app.route("/api/franchise/licenses/<int:license_id>/revoke", methods=["POST"])
@csrf.exempt
@requires_feature_flag("franchise_licensing")
def franchise_license_revoke(license_id):
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user: return jsonify({"error": "Login required."}), 401
    lic = FranchiseLicense.query.get(license_id)
    if not lic: return jsonify({"error": "License not found."}), 404
    brand = FranchiseBrand.query.get(lic.brand_id)
    if not brand or brand.franchisor_user_id != user["id"]:
        return jsonify({"error": "License not found."}), 404
    if lic.status != "active":
        return jsonify({"error": "Only an active license can be revoked."}), 400
    lic.status = "revoked"
    lic.decided_at = datetime.utcnow()
    # Untag every listing that was under this license — a revoked
    # license can't keep quietly earning royalties for a listing that's
    # still selling.
    Product.query.filter_by(franchise_license_id=lic.id).update({Product.franchise_license_id: None})
    db.session.commit()
    return jsonify({"ok": True, "license": lic.to_dict()}), 200


@app.route("/api/franchise/products/<int:product_id>/tag", methods=["POST"])
@csrf.exempt
@requires_feature_flag("franchise_licensing")
def franchise_tag_product(product_id):
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user: return jsonify({"error": "Login required."}), 401
    product = Product.query.get(product_id)
    if not product or product.seller_id != user["id"]:
        return jsonify({"error": "Listing not found."}), 404
    data = request.get_json(silent=True) or {}
    license_id = data.get("license_id")
    if license_id is None:
        product.franchise_license_id = None
        db.session.commit()
        return jsonify({"ok": True, "product": {"id": product.id, "franchise_license_id": None}}), 200
    lic = FranchiseLicense.query.filter_by(id=license_id, licensee_user_id=user["id"], status="active").first()
    if not lic:
        return jsonify({"error": "You don't hold an active license with that ID."}), 404
    product.franchise_license_id = lic.id
    db.session.commit()
    return jsonify({"ok": True, "product": {"id": product.id, "franchise_license_id": lic.id}}), 200


