@app.route("/api/coldroom/units/<int:unit_id>/regenerate-key", methods=["POST"])
@csrf.exempt
def coldroom_unit_regenerate_key(unit_id):
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
