@app.route("/api/coldroom/units/<int:unit_id>/control", methods=["POST"])
@csrf.exempt
def coldroom_unit_control(unit_id):
    """Issues a REAL command for the physical device to pick up next
    time it polls GET /api/coldroom/device/command — does not itself
    flip is_on (that only ever changes from a real device
    acknowledgement/reading), it just queues the instruction."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    unit, err = _coldroom_unit_or_404(unit_id, user)
    if err: return err
    data = request.get_json(silent=True) or {}
    action = (data.get("action") or "").strip().lower()
    if action not in ("on", "off", "set_target"):
        return jsonify({"error": "'action' must be 'on', 'off', or 'set_target'."}), 400

    if action == "set_target":
        try:
            target = float(data.get("target_temp_c"))
        except (TypeError, ValueError):
            return jsonify({"error": "'target_temp_c' is required and must be a number for action=set_target."}), 400
        unit.target_temp_c = target
        unit.pending_command = "set_target"
        unit.pending_command_target_temp = target
    else:
        unit.pending_command = action
        unit.pending_command_target_temp = None
    unit.pending_command_issued_at = datetime.utcnow()
    db.session.commit()
    return jsonify({"ok": True, "unit": unit.to_dict()}), 200


@app.route("/api/coldroom/units/<int:unit_id>/readings", methods=["GET"])
def coldroom_unit_readings(unit_id):
    user, err = _erp_user_or_401()
    if err: return err
    unit, err = _coldroom_unit_or_404(unit_id, user)
    if err: return err
    hours = min(int(request.args.get("hours", 24) or 24), 24 * 30)
    since = datetime.utcnow() - timedelta(hours=hours)
    rows = (ColdRoomReading.query.filter(ColdRoomReading.unit_id == unit.id, ColdRoomReading.recorded_at >= since)
            .order_by(ColdRoomReading.recorded_at.asc()).limit(2000).all())
    temps = [r.temperature_c for r in rows]
    summary = {
        "readings_count": len(rows),
        "min_c": round(min(temps), 2) if temps else None,
        "max_c": round(max(temps), 2) if temps else None,
        "avg_c": round(sum(temps) / len(temps), 2) if temps else None,
    }
    return jsonify({"ok": True, "readings": [r.to_dict() for r in rows], "summary": summary}), 200


# ---------- Device-facing endpoints (X-Coldroom-Device-Key header auth, NOT user session) ----------

@app.route("/api/coldroom/device/ingest", methods=["POST"])
@csrf.exempt
def coldroom_device_ingest():
    """The physical controller calls this — real hardware, real reading.
    Accepts either a single reading or {"readings": [...]} for a device
    that batches points before it gets signal."""
    unit, err = _coldroom_unit_from_device_key()
    if err: return err
    data = request.get_json(silent=True) or {}
    batch = data.get("readings") if isinstance(data.get("readings"), list) else [data]

    created = []
    for item in batch[:500]:
        item = item or {}
        try:
            temperature_c = float(item.get("temperature_c"))
        except (TypeError, ValueError):
            continue
        humidity_pct = item.get("humidity_pct")
        try:
            humidity_pct = float(humidity_pct) if humidity_pct is not None else None
        except (TypeError, ValueError):
            humidity_pct = None
        door_open = item.get("door_open")
        door_open = bool(door_open) if door_open is not None else unit.door_open
        is_on = item.get("is_on")
        is_on = bool(is_on) if is_on is not None else unit.is_on
        recorded_at = datetime.utcnow()
        if item.get("recorded_at"):
            try:
                recorded_at = datetime.fromisoformat(item["recorded_at"])
            except (TypeError, ValueError):
                pass
        reading = ColdRoomReading(unit_id=unit.id, recorded_at=recorded_at, temperature_c=temperature_c,
                                   humidity_pct=humidity_pct, door_open=door_open, is_on=is_on, source="device")
        db.session.add(reading)
        created.append((reading, door_open))

    if not created:
        return jsonify({"error": "No valid reading found. 'temperature_c' is required."}), 400

    created.sort(key=lambda pair: pair[0].recorded_at)
    for reading, door_open in created:
        # Real door-open-duration tracking: only starts/stops the clock
        # on an actual reported transition, never assumed.
        if door_open and not unit.door_open:
            unit.door_opened_at = reading.recorded_at
        elif not door_open and unit.door_open:
            unit.door_opened_at = None
        unit.door_open = door_open
        unit.current_temp_c = reading.temperature_c
        if reading.humidity_pct is not None:
            unit.current_humidity_pct = reading.humidity_pct
        unit.is_on = reading.is_on
        unit.last_reading_at = reading.recorded_at
        db.session.flush()
        _coldroom_evaluate_alarms(unit, reading)

    db.session.commit()
    return jsonify({"ok": True, "created": len(created), "unit": unit.to_dict()}), 201


@app.route("/api/coldroom/device/command", methods=["GET"])
def coldroom_device_command_poll():
    """The physical controller polls this periodically to check for a
    real pending command issued from the dashboard."""
    unit, err = _coldroom_unit_from_device_key()
    if err: return err
    if not unit.pending_command:
        return jsonify({"ok": True, "command": None}), 200
    return jsonify({"ok": True, "command": {
        "action": unit.pending_command,
        "target_temp_c": unit.pending_command_target_temp,
        "issued_at": unit.pending_command_issued_at.isoformat() if unit.pending_command_issued_at else None,
    }}), 200


@app.route("/api/coldroom/device/command/ack", methods=["POST"])
@csrf.exempt
def coldroom_device_command_ack():
    """The physical controller calls this once it has actually applied
    the command (opened/closed the compressor relay, changed the
    setpoint) — this is what clears pending_command and, for on/off,
    updates is_on."""
    unit, err = _coldroom_unit_from_device_key()
    if err: return err
    data = request.get_json(silent=True) or {}
    applied_action = (data.get("action") or "").strip().lower()
    if applied_action and applied_action != unit.pending_command:
        return jsonify({"error": "Acknowledged action does not match the currently pending command."}), 409
    if unit.pending_command == "on":
        unit.is_on = True
    elif unit.pending_command == "off":
        unit.is_on = False
    unit.pending_command = None
    unit.pending_command_target_temp = None
    unit.pending_command_issued_at = None
    db.session.commit()
    return jsonify({"ok": True, "unit": unit.to_dict()}), 200


