    org = _org_for_user(user["id"])
    unit_q = ColdRoomUnit.query.filter_by(is_active=True)
    if org:
        unit_q = unit_q.filter(db.or_(ColdRoomUnit.owner_user_id == user["id"], ColdRoomUnit.org_id == org.id))
    else:
        unit_q = unit_q.filter_by(owner_user_id=user["id"])
    unit_ids = [u.id for u in unit_q.all()]
    q = ColdRoomAlert.query.filter(ColdRoomAlert.unit_id.in_(unit_ids)) if unit_ids else ColdRoomAlert.query.filter(False)
    if request.args.get("open_only", "true").lower() != "false":
        q = q.filter(ColdRoomAlert.resolved_at.is_(None))
    unit_filter = request.args.get("unit_id")
    if unit_filter:
        q = q.filter(ColdRoomAlert.unit_id == int(unit_filter))
    alerts = q.order_by(ColdRoomAlert.triggered_at.desc()).limit(200).all()
    return jsonify({"ok": True, "alerts": [a.to_dict() for a in alerts]}), 200


