@app.route("/api/coldroom/alerts/<int:alert_id>/resolve", methods=["POST"])
@csrf.exempt
def coldroom_alert_resolve(alert_id):
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    alert = ColdRoomAlert.query.get(alert_id)
    if not alert:
        return jsonify({"error": "Alert not found."}), 404
    unit, err = _coldroom_unit_or_404(alert.unit_id, user)
    if err: return err
    alert.resolved_at = datetime.utcnow()
    if not alert.acknowledged_at:
        alert.acknowledged_at = datetime.utcnow()
        alert.acknowledged_by = user["id"]
    db.session.commit()
    return jsonify({"ok": True, "alert": alert.to_dict()}), 200


# ════════════════════════════════════════════════════════════
# STAGE 520: TERMINAL QUICK-SETUP + PERSISTENT COMMAND AUDIT LOG
#
# Deliberately builds on the two remote-execution channels that
# already exist in this file rather than adding a third:
#   - the real SSH Terminal (Stage 150/151) — for a VM/server the
#     business actually owns (this is where Ollama/heavy installs
#     belong — it needs real disk/RAM/CPU a shared web worker doesn't
#     have, and it's a box only this business's own data touches)
#   - the PythonAnywhere Consoles API (Stage 519) — for this account
# Both are already admin-only. This stage adds (a) a curated list of
# one-click install/setup commands the UI can drop into whichever
# channel is currently open, and (b) a real, queryable audit log —
# previously commands only went to the python logger, not a table.
#
# SECURITY NOTE: the SSH channel streams raw per-keystroke PTY input
# (ssh_ws_input above) — that is deliberately NOT persisted here, since
# a keystroke-level log would capture anything typed into that
# terminal verbatim, including a sudo/database password. Only whole,
# intentional commands (a Quick-Setup preset, or a PythonAnywhere
# console "Run" submission) are ever written to this table.
# ════════════════════════════════════════════════════════════

class TerminalCommandLog(db.Model):
    __tablename__ = "terminal_command_log"
    id             = db.Column(db.Integer, primary_key=True)
    admin_user_id  = db.Column(db.Integer, db.ForeignKey("user_accounts.id"), nullable=False, index=True)
    channel        = db.Column(db.String(20), nullable=False)   # "ssh" | "pythonanywhere"
    target         = db.Column(db.String(200), nullable=True)   # host label / console id
    command        = db.Column(db.Text, nullable=False)
    run_at         = db.Column(db.DateTime, default=datetime.utcnow, index=True)

    def to_dict(self):
        return {"id": self.id, "channel": self.channel, "target": self.target,
                "command": self.command, "run_at": self.run_at.isoformat() if self.run_at else None}


def _log_terminal_command(admin_user_id, channel, target, command):
    """Best-effort — a logging failure must never block the command that
    was actually run on the real channel."""
    try:
        db.session.add(TerminalCommandLog(admin_user_id=admin_user_id, channel=channel,
                                           target=str(target)[:200], command=(command or "")[:4000]))
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        logging.warning(f"[TERMINAL AUDIT LOG ERROR] {e}")


# vm_only=True commands need a real machine (disk/RAM/GPU, apt/systemd,
# a non-root sudo user) — they will fail or get killed on a
# PythonAnywhere web worker. The UI should only offer those when an SSH
# session to an external VM is the active channel.
QUICK_SETUP_COMMANDS = [
    {"key": "ollama_install", "label": "Install Ollama", "vm_only": True,
     "command": "curl -fsSL https://ollama.com/install.sh | sh"},
    {"key": "ollama_pull_llama3", "label": "Pull Llama 3 (8B) model", "vm_only": True,
     "command": "ollama pull llama3"},
    {"key": "ollama_pull_mistral", "label": "Pull Mistral (7B) model", "vm_only": True,
     "command": "ollama pull mistral"},
    {"key": "ollama_serve_check", "label": "Check Ollama is running", "vm_only": True,
     "command": "curl -s http://127.0.0.1:11434/api/version"},
    {"key": "node_install", "label": "Install Node.js LTS (nvm)", "vm_only": True,
     "command": "curl -fsSL https://raw.githubusercontent.com/nvm-sh/nvm/v0.40.1/install.sh | bash && "
                "export NVM_DIR=\"$HOME/.nvm\" && [ -s \"$NVM_DIR/nvm.sh\" ] && \\. \"$NVM_DIR/nvm.sh\" && nvm install --lts"},
    {"key": "docker_install", "label": "Install Docker", "vm_only": True,
     "command": "curl -fsSL https://get.docker.com | sh"},
    {"key": "apt_update", "label": "apt update && upgrade", "vm_only": True,
     "command": "sudo apt-get update && sudo apt-get -y upgrade"},
    {"key": "pip_upgrade", "label": "Upgrade pip + build tools", "vm_only": False,
     "command": "python3 -m pip install --upgrade pip setuptools wheel"},
    {"key": "pip_requirements", "label": "Install from requirements.txt", "vm_only": False,
     "command": "pip install -r requirements.txt"},
    {"key": "disk_usage", "label": "Check disk usage", "vm_only": False,
     "command": "df -h"},
    {"key": "python_version", "label": "Check Python/pip versions", "vm_only": False,
     "command": "python3 --version && pip3 --version"},
]


@app.route("/api/terminal/quick-commands", methods=["GET"])
def terminal_quick_commands():
    user = _get_current_user()
    if not user or not _sdk_is_admin(user["id"]):
        return jsonify({"error": "Admin access required."}), 403
    return jsonify({"ok": True, "commands": QUICK_SETUP_COMMANDS}), 200


@app.route("/api/terminal/log-command", methods=["POST"])
@csrf.exempt
def terminal_log_command():
    """Called by the UI right before it sends a Quick-Setup preset down
    the SSH channel, so intentional setup commands land in the audit
    trail even though raw SSH keystrokes are never logged (see note
    above)."""
    if not _csrf_ok():
        return jsonify({"error": "CSRF token invalid or missing."}), 403
    user = _get_current_user()
    if not user or not _sdk_is_admin(user["id"]):
        return jsonify({"error": "Admin access required."}), 403
    data = request.get_json(force=True) or {}
    command = (data.get("command") or "").strip()
    if not command:
        return jsonify({"error": "command is required."}), 400
    _log_terminal_command(user["id"], "ssh", data.get("target"), command)
    return jsonify({"ok": True}), 200


@app.route("/api/terminal/command-log", methods=["GET"])
def terminal_command_log():
    user = _get_current_user()
    if not user or not _sdk_is_admin(user["id"]):
        return jsonify({"error": "Admin access required."}), 403
    channel = (request.args.get("channel") or "").strip()
    q = TerminalCommandLog.query
    if channel:
        q = q.filter_by(channel=channel)
    rows = q.order_by(TerminalCommandLog.run_at.desc()).limit(200).all()
    return jsonify({"ok": True, "log": [r.to_dict() for r in rows]}), 200


