@csrf.exempt
def health_who_country_snapshot(iso3):
    """One call, several key WHO GHO indicators for one country — built
    on the existing /api/who/indicator/<code> data source (Stage 46),
    pre-selected for a fast country health overview."""
    iso3 = iso3.strip().upper()
    snapshot = {}
    for key, code in WHO_SNAPSHOT_INDICATORS.items():
        try:
            resp = requests.get(f"{WHO_GHO_BASE}/{code}?$filter=SpatialDim eq '{iso3}'", timeout=12)
            if resp.status_code == 200:
                rows = sorted(resp.json().get("value", []), key=lambda r: r.get("TimeDim") or 0, reverse=True)
                snapshot[key] = {"year": rows[0].get("TimeDim"), "value": rows[0].get("NumericValue")} if rows else None
            else:
                snapshot[key] = None
        except Exception as e:
            logging.warning(f"[WHO SNAPSHOT ERROR] {key}: {e}")
            snapshot[key] = None
    return jsonify({"ok": True, "country": iso3, "indicators": snapshot}), 200


@app.route("/api/health/openfda/drug-label", methods=["GET"])
@csrf.exempt
def health_openfda_drug_label():
    """Free, no-key US FDA drug label search — dosage/warnings text for
    a named medicine."""
    query = (request.args.get("drug") or "").strip()
    if not query:
        return jsonify({"error": "?drug= is required."}), 400
    try:
        resp = requests.get(
            "https://api.fda.gov/drug/label.json",
            params={"search": f'openfda.brand_name:"{query}" OR openfda.generic_name:"{query}"', "limit": 3},
            timeout=12,
        )
        if resp.status_code != 200:
            return jsonify({"ok": False, "error": f"OpenFDA returned {resp.status_code}"}), 502
        results = resp.json().get("results", [])
        simplified = [{
            "brand_name": (r.get("openfda", {}).get("brand_name") or [None])[0],
            "generic_name": (r.get("openfda", {}).get("generic_name") or [None])[0],
            "purpose": (r.get("purpose") or [None])[0],
            "warnings": (r.get("warnings") or [None])[0],
            "dosage_and_administration": (r.get("dosage_and_administration") or [None])[0],
        } for r in results]
        return jsonify({"ok": True, "results": simplified}), 200
    except Exception as e:
        logging.error(f"[OPENFDA ERROR] {e}")
        return jsonify({"ok": False, "error": str(e)}), 500


