@app.route("/api/health/pubmed/search", methods=["GET"])
@csrf.exempt
def health_pubmed_search():
    """US NLM PubMed E-utilities — free, no key (unauthenticated, so
    result counts are kept modest to stay inside fair-use limits)."""
    query = (request.args.get("query") or "").strip()
    if not query:
        return jsonify({"error": "?query= is required."}), 400
    try:
        search_resp = requests.get(
            "https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi",
            params={"db": "pubmed", "term": query, "retmode": "json", "retmax": 8}, timeout=12,
        )
        ids = search_resp.json().get("esearchresult", {}).get("idlist", [])
        if not ids:
            return jsonify({"ok": True, "results": []}), 200
        summary_resp = requests.get(
            "https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esummary.fcgi",
            params={"db": "pubmed", "id": ",".join(ids), "retmode": "json"}, timeout=12,
        )
        summary = summary_resp.json().get("result", {})
        results = [{
            "pmid": pmid, "title": summary.get(pmid, {}).get("title"),
            "journal": summary.get(pmid, {}).get("fulljournalname"),
            "pub_date": summary.get(pmid, {}).get("pubdate"),
            "url": f"https://pubmed.ncbi.nlm.nih.gov/{pmid}/",
        } for pmid in ids]
        return jsonify({"ok": True, "results": results}), 200
    except Exception as e:
        logging.error(f"[PUBMED ERROR] {e}")
        return jsonify({"ok": False, "error": str(e)}), 500


