def _xc_creds(user_id, provider) -> dict:
    row = UserIntegration.query.filter_by(user_id=user_id, provider=provider, active=True).first()
    if not row:
        return {}
    try:
        return decrypt_secret_blob(row.credentials_encrypted) or {}
    except Exception:
        return {}


def _xc_find_owner(provider, webhook_secret):
    """Return (owner_user_id, creds) for the account whose private webhook
    path secret matches. Constant-time compare."""
    if not webhook_secret:
        return None, {}
    try:
        for row in UserIntegration.query.filter_by(provider=provider, active=True).all():
            creds = decrypt_secret_blob(row.credentials_encrypted) or {}
            if hmac.compare_digest(str(creds.get("webhook_secret", "")), str(webhook_secret)):
                return row.user_id, creds
    except Exception as e:
        logging.error(f"[XC OWNER LOOKUP {provider}] {e}")
    return None, {}


def _xc_public_base():
    return (os.environ.get("PUBLIC_BASE_URL") or request.host_url).rstrip("/")


def _xc_webhook_url(channel, secret):
    return f"{_xc_public_base()}/inbox-channel/{channel}/webhook/{secret}"


def _xc_safe_https_url(url: str) -> str:
    """The Apple Messages relay URL is user-supplied and we POST to it from
    the server, so refuse anything that isn't public https (blocks SSRF to
    localhost / cloud metadata / private networks)."""
    import ipaddress, socket
    from urllib.parse import urlparse
    u = urlparse((url or "").strip())
    if u.scheme != "https" or not u.hostname:
        raise ValueError("The send URL must be a public https:// address.")
    try:
        infos = socket.getaddrinfo(u.hostname, u.port or 443, proto=socket.IPPROTO_TCP)
    except Exception:
        raise ValueError("Could not resolve the send URL's host.")
    for info in infos:
        ip = ipaddress.ip_address(info[4][0])
        if ip.is_private or ip.is_loopback or ip.is_link_local or ip.is_reserved or ip.is_multicast or ip.is_unspecified:
            raise ValueError("The send URL must point to a public host.")
    return u.geturl()


def _xc_truthy(v) -> bool:
    return str(v or "").strip().lower() in ("1", "true", "yes", "on")


def _autoprovision_inbox_channel(user_id, provider, credentials: dict) -> dict:
    """Called from save_user_integration. Generates the private webhook
    secret and does whatever one-time setup the platform allows."""
    credentials = dict(credentials or {})
    existing = _xc_creds(user_id, provider)   # keep the same webhook URL when a user re-saves
    credentials["webhook_secret"] = credentials.get("webhook_secret") or existing.get("webhook_secret") or secrets.token_urlsafe(24)
    if existing.get("client_token") and not credentials.get("client_token"):
        credentials["client_token"] = existing["client_token"]
    channel = XC_PROVIDER_TO_CHANNEL[provider]
    if provider == "viber_bot":
        token = (credentials.get("auth_token") or "").strip()
        if not token:
            raise ValueError("Viber needs your bot's auth token.")
        try:
            r = requests.post("https://chatapi.viber.com/pa/set_webhook",
                              headers={"X-Viber-Auth-Token": token},
                              json={"url": _xc_webhook_url(channel, credentials["webhook_secret"]),
                                    "event_types": ["message", "conversation_started"]},
                              timeout=15).json()
        except Exception as e:
            raise ValueError(f"Couldn't reach Viber: {e}")
        if r.get("status") != 0:
            raise ValueError(f"Viber rejected that token/webhook: {r.get('status_message', r)}")
    elif provider == "msteams_bot":
        if not (credentials.get("app_id") and credentials.get("app_password")):
            raise ValueError("Teams needs the bot's Microsoft App ID and client secret.")
        _xc_teams_token(credentials)  # fail now, not on the first customer message
    elif provider == "rcs_business":
        if not (credentials.get("agent_id") and credentials.get("service_account_json")):
            raise ValueError("RCS needs your RBM agent ID and the agent's service-account JSON.")
        credentials["client_token"] = credentials.get("client_token") or secrets.token_urlsafe(24)
        _xc_rcs_access_token(credentials)
    elif provider == "apple_messages":
        credentials["send_url"] = _xc_safe_https_url(credentials.get("send_url"))
        if not credentials.get("api_key"):
            raise ValueError("Apple Messages needs your provider's API key.")
    return credentials


# ── Microsoft Teams ──────────────────────────────────────────
_xc_teams_token_cache = {}

def _xc_teams_token(creds) -> str:
    app_id = creds.get("app_id", "")
    hit = _xc_teams_token_cache.get(app_id)
    if hit and hit[1] > time.time() + 60:
        return hit[0]
    tenant = (creds.get("tenant_id") or "botframework.com").strip()
    r = requests.post(f"https://login.microsoftonline.com/{tenant}/oauth2/v2.0/token", data={
        "grant_type": "client_credentials", "client_id": app_id,
        "client_secret": creds.get("app_password", ""),
        "scope": "https://api.botframework.com/.default"}, timeout=15)
    j = r.json()
    if not r.ok or not j.get("access_token"):
        raise ValueError(f"Microsoft rejected the bot credentials: {j.get('error_description', r.status_code)}")
    _xc_teams_token_cache[app_id] = (j["access_token"], time.time() + int(j.get("expires_in", 3000)))
    return j["access_token"]


_xc_botfw_jwk_client = None

def _xc_teams_verify_inbound(auth_header: str, app_id: str, service_url: str) -> bool:
    """Validate the Bot Framework JWT on an inbound activity. Fails closed."""
    global _xc_botfw_jwk_client
    try:
        import jwt as _jwt
        if not auth_header.lower().startswith("bearer "):
            return False
        token = auth_header.split(" ", 1)[1].strip()
        if _xc_botfw_jwk_client is None:
            meta = requests.get("https://login.botframework.com/v1/.well-known/openidconfiguration", timeout=10).json()
            _xc_botfw_jwk_client = _jwt.PyJWKClient(meta["jwks_uri"])
        key = _xc_botfw_jwk_client.get_signing_key_from_jwt(token).key
        claims = _jwt.decode(token, key, algorithms=["RS256"], audience=app_id,
                             issuer="https://api.botframework.com",
                             options={"require": ["exp", "iss", "aud"]})
        claim_su = claims.get("serviceurl") or claims.get("serviceUrl")
        if claim_su and service_url and claim_su.rstrip("/") != service_url.rstrip("/"):
            return False
        return True
    except Exception as e:
        logging.warning(f"[TEAMS JWT] rejected: {e}")
        return False


def _xc_send_teams(user_id, contact, text, creds):
    ref_row = InboxChannelRef.query.filter_by(owner_user_id=user_id, channel="msteams", contact_identifier=contact).first()
    if not ref_row:
        raise ValueError("No Teams conversation on record for that contact yet — they must message the bot first.")
    ref = json.loads(ref_row.ref_json or "{}")
    base = (ref.get("service_url") or "").rstrip("/")
    if not base.startswith("https://"):
        raise ValueError("Missing Teams service URL for that conversation.")
    r = requests.post(f"{base}/v3/conversations/{ref['conversation_id']}/activities",
                      headers={"Authorization": f"Bearer {_xc_teams_token(creds)}"},
                      json={"type": "message", "text": text,
                            "from": {"id": ref.get("bot_id", creds.get("app_id")), "name": ref.get("bot_name", "")},
                            "conversation": {"id": ref["conversation_id"]},
                            "recipient": {"id": ref.get("user_id", "")}}, timeout=15)
    if not r.ok:
        raise ValueError(f"Teams send failed ({r.status_code}).")
    return (r.json() or {}).get("id")


# ── Viber ────────────────────────────────────────────────────
def _xc_send_viber(contact, text, creds):
    r = requests.post("https://chatapi.viber.com/pa/send_message",
                      headers={"X-Viber-Auth-Token": creds["auth_token"]},
                      json={"receiver": contact, "min_api_version": 1,
                            "sender": {"name": (creds.get("bot_name") or "Support")[:28]},
                            "type": "text", "text": text}, timeout=15).json()
    if r.get("status") != 0:
        raise ValueError(f"Viber send failed: {r.get('status_message', r)}")
    return r.get("message_token")


# ── RCS (Google RCS Business Messaging) ─────────────────────
def _xc_rcs_access_token(creds) -> str:
    from google.oauth2 import service_account
    from google.auth.transport.requests import Request as _GReq
    try:
        info = json.loads(creds["service_account_json"]) if isinstance(creds["service_account_json"], str) else creds["service_account_json"]
        gc = service_account.Credentials.from_service_account_info(
            info, scopes=["https://www.googleapis.com/auth/rcsbusinessmessaging"])
        gc.refresh(_GReq())
        return gc.token
    except Exception as e:
        raise ValueError(f"Google rejected the RCS service account: {e}")


def _xc_send_rcs(contact, text, creds):
    phone = contact.split(":", 1)[-1]
    if not re.fullmatch(r"\+\d{6,15}", phone):
        raise ValueError("RCS contacts must be E.164 phone numbers like +263771234567.")
    mid = str(uuid.uuid4())
    from urllib.parse import quote
    r = requests.post(
        f"https://rcsbusinessmessaging.googleapis.com/v1/phones/{quote(phone, safe='')}/agentMessages",
        params={"messageId": mid, "agentId": creds["agent_id"]},
        headers={"Authorization": f"Bearer {_xc_rcs_access_token(creds)}"},
        json={"contentMessage": {"text": text}}, timeout=20)
    if not r.ok:
        raise ValueError(f"RCS send failed ({r.status_code}): {r.text[:200]}")
    return mid


# ── Apple Messages for Business (through an approved MSP) ───
def _xc_send_applemsg(contact, text, creds):
    url = _xc_safe_https_url(creds.get("send_url"))
    r = requests.post(url, headers={"Authorization": f"Bearer {creds['api_key']}"},
                      json={"to": contact.split(":", 1)[-1], "text": text,
                            "channel": "apple_messages", "business_id": creds.get("business_id", "")},
                      timeout=20, allow_redirects=False)
    if not r.ok:
        raise ValueError(f"Apple Messages provider rejected the send ({r.status_code}).")
    try:
        return (r.json() or {}).get("id")
    except Exception:
        return None


def xc_send(user_id, channel, contact, text):
    """Single outbound entry point used by /api/inbox/reply. Returns the
    external message id (or None). Raises ValueError with a safe message."""
    provider = XC_CHANNELS[channel][0]
    creds = _xc_creds(user_id, provider)
    if not creds:
        raise ValueError(f"{XC_CHANNELS[channel][1]} isn't connected for this account.")
    if channel == "msteams":  return _xc_send_teams(user_id, contact, text, creds)
    if channel == "viber":    return _xc_send_viber(contact.split(":", 1)[-1], text, creds)
    if channel == "rcs":      return _xc_send_rcs(contact, text, creds)
    if channel == "applemsg": return _xc_send_applemsg(contact, text, creds)


def _xc_ingest(owner_uid, channel, contact, name, text, creds, ext_id=None):
    """Write an inbound message to the Unified Inbox and, only if the
    business switched auto-reply on, answer with the same AI pipeline the
    Telegram bot uses."""
    _inbox_log(owner_uid, channel, contact, "in", text, contact_name=name, wa_message_id=ext_id)
    if not _xc_truthy(creds.get("auto_reply")):
        return
    try:
        key = f"{channel}:{contact}"
        if key not in whatsapp_store:
            whatsapp_store[key] = _db_get_history(key, channel=channel)
        history = _get_history(whatsapp_store, key)
        reply, updated = generate_ai_reply(text, history)
        _save_history(whatsapp_store, key, updated)
        _db_save_turn(key, channel, "user", text, owner_user_id=owner_uid)
        _db_save_turn(key, channel, "assistant", reply, owner_user_id=owner_uid)
        xc_send(owner_uid, channel, contact, reply)
        _inbox_log(owner_uid, channel, contact, "out", reply, contact_name=name)
    except Exception as e:
        logging.error(f"[XC AUTO-REPLY {channel}] {e}")


def _xc_save_ref(owner_uid, channel, contact, ref: dict):
    try:
        row = InboxChannelRef.query.filter_by(owner_user_id=owner_uid, channel=channel, contact_identifier=contact).first()
        if row:
            row.ref_json = json.dumps(ref)
        else:
            db.session.add(InboxChannelRef(owner_user_id=owner_uid, channel=channel,
                                           contact_identifier=contact, ref_json=json.dumps(ref)))
        db.session.commit()
    except Exception as e:
        db.session.rollback(); logging.error(f"[XC SAVE REF] {e}")


@app.route("/inbox-channel/<channel>/webhook/<webhook_secret>", methods=["GET", "POST"])
@csrf.exempt
def xc_webhook(channel, webhook_secret):
    if channel not in XC_CHANNELS:
        return jsonify({"status": "ignored"}), 404
    provider = XC_CHANNELS[channel][0]
    owner_uid, creds = _xc_find_owner(provider, webhook_secret)
    if not owner_uid:
        return jsonify({"status": "ignored"}), 200   # don't reveal which secrets exist
    if request.method == "GET":
        return jsonify({"status": "ok"}), 200
    raw = request.get_data() or b""
    try:
        data = json.loads(raw.decode("utf-8") or "{}")
    except Exception:
        return jsonify({"status": "ignored"}), 200
    try:
        # ---- Microsoft Teams ----
        if channel == "msteams":
            if data.get("type") != "message" or not data.get("text"):
                return "", 200
            if not _xc_teams_verify_inbound(request.headers.get("Authorization", ""),
                                            creds.get("app_id", ""), data.get("serviceUrl", "")):
                return jsonify({"error": "unauthorized"}), 401
            frm = data.get("from") or {}
            contact = "msteams:" + (frm.get("aadObjectId") or frm.get("id") or "unknown")
            text = re.sub(r"<at>.*?</at>", "", data["text"]).strip()
            if text:
                _xc_save_ref(owner_uid, channel, contact, {
                    "service_url": data.get("serviceUrl"), "conversation_id": (data.get("conversation") or {}).get("id"),
                    "user_id": frm.get("id"), "bot_id": (data.get("recipient") or {}).get("id"),
                    "bot_name": (data.get("recipient") or {}).get("name", "")})
                _xc_ingest(owner_uid, channel, contact, frm.get("name"), text, creds, ext_id=data.get("id"))
            return "", 200
        # ---- Viber ----
        if channel == "viber":
            sig = request.headers.get("X-Viber-Content-Signature", "")
            want = hmac.new(creds.get("auth_token", "").encode(), raw, hashlib.sha256).hexdigest()
            if not hmac.compare_digest(sig, want):
                return jsonify({"error": "bad signature"}), 401
            if data.get("event") != "message":
                return "", 200            # webhook / delivered / seen / conversation_started: just acknowledge
            msg = data.get("message") or {}
            sender = data.get("sender") or {}
            if msg.get("type") == "text" and msg.get("text") and sender.get("id"):
                _xc_ingest(owner_uid, channel, "viber:" + sender["id"], sender.get("name"),
                           msg["text"], creds, ext_id=str(data.get("message_token") or ""))
            return "", 200
        # ---- RCS ----
        if channel == "rcs":
            # One-off endpoint verification from Google when registering the webhook.
            if data.get("clientToken") and data.get("secret") and "message" not in data:
                if hmac.compare_digest(str(data["clientToken"]), str(creds.get("client_token", ""))):
                    return jsonify({"secret": data["secret"]}), 200
                return jsonify({"error": "bad client token"}), 401
            sig = request.headers.get("X-Goog-Signature", "")
            env = data.get("message") or {}
            b64 = env.get("data", "")
            key = creds.get("client_token", "").encode()
            def _h(b): return base64.b64encode(hmac.new(key, b, hashlib.sha512).digest()).decode()
            # Google documents HMAC-SHA512 keyed by the client token; accept the
            # payload (raw / encoded data / decoded data) forms it has used.
            if not any(hmac.compare_digest(sig, _h(c)) for c in (raw, b64.encode(), base64.b64decode(b64 or "")) if c is not None):
                return jsonify({"error": "bad signature"}), 401
            ev = json.loads(base64.b64decode(b64).decode("utf-8")) if b64 else {}
            phone = ev.get("senderPhoneNumber")
            text = ev.get("text") or ((ev.get("suggestionResponse") or {}).get("text"))
            if phone and text:
                _xc_ingest(owner_uid, channel, "rcs:" + phone, None, text, creds, ext_id=ev.get("messageId"))
            return "", 200
        # ---- Apple Messages for Business (normalised relay from the MSP) ----
        if channel == "applemsg":
            sig = request.headers.get("X-Signature", "")
            want = hmac.new(creds.get("webhook_secret", "").encode(), raw, hashlib.sha256).hexdigest()
            if sig and not hmac.compare_digest(sig, want):
                return jsonify({"error": "bad signature"}), 401
            who, text = data.get("from"), (data.get("text") or "").strip()
            if who and text:
                _xc_ingest(owner_uid, channel, "applemsg:" + str(who), data.get("name"), text, creds,
                           ext_id=str(data.get("message_id") or ""))
            return "", 200
    except Exception as e:
        logging.error(f"[XC WEBHOOK {channel}] {e}")
        return "", 200   # never make the platform retry-storm us
    return "", 200


@app.route("/api/inbox/channels", methods=["GET"])
@csrf.exempt
def inbox_channels_status():
    """Which extra channels this account has connected, plus the webhook URL
    to paste into each platform's console."""
    user, err = _erp_user_or_401()
    if err: return err
    out = []
    for ch, (provider, label) in XC_CHANNELS.items():
        c = _xc_creds(user["id"], provider)
        out.append({"channel": ch, "provider": provider, "label": label, "connected": bool(c),
                    "auto_reply": _xc_truthy(c.get("auto_reply")) if c else False,
                    "webhook_url": _xc_webhook_url(ch, c["webhook_secret"]) if c.get("webhook_secret") else None,
                    "client_token": c.get("client_token") if ch == "rcs" else None})
    return jsonify({"channels": out}), 200




