def _i25_parse_iso(s):
    try:
        return datetime.fromisoformat(str(s).replace("Z", "+00:00")).astimezone(__import__("datetime").timezone.utc).replace(tzinfo=None)
    except Exception:
        return None


# ---------- Stage 2: Calendly ----------
def _cal_creds(user_id):
    return _xc_creds(user_id, "calendly")


def _cal_phone(payload, default_cc):
    raw = payload.get("text_reminder_number") or ""
    if not raw:
        for qa in payload.get("questions_and_answers") or []:
            q = (qa.get("question") or "").lower()
            if any(k in q for k in ("whatsapp", "phone", "mobile", "cell", "number")):
                raw = qa.get("answer") or ""
                break
    digits = re.sub(r"\D", "", raw or "")
    if not digits:
        return None
    if str(raw).strip().startswith("+") or str(raw).strip().startswith("00"):
        return digits.lstrip("0") if str(raw).strip().startswith("00") else digits
    cc = re.sub(r"\D", "", default_cc or "")
    if digits.startswith("0") and cc:
        return cc + digits.lstrip("0")
    return digits


def _cal_when(booking):
    try:
        from zoneinfo import ZoneInfo
        tz = ZoneInfo(booking.timezone or "UTC")
    except Exception:
        tz = __import__("datetime").timezone.utc
    local = booking.start_time.replace(tzinfo=__import__("datetime").timezone.utc).astimezone(tz)
    return local.strftime("%a %d %b, %H:%M") + f" ({booking.timezone or 'UTC'})"


def _cal_schedule_reminders(booking):
    now = datetime.utcnow()
    plan = [("confirm", now), ("24h", booking.start_time - timedelta(hours=24)),
            ("1h", booking.start_time - timedelta(hours=1))]
    for kind, send_at in plan:
        if kind != "confirm" and send_at <= now:
            continue                                  # already past — don't spam
        if not BookingReminder.query.filter_by(booking_id=booking.id, kind=kind).first():
            db.session.add(BookingReminder(booking_id=booking.id, kind=kind, send_at=send_at,
                                           status="pending" if booking.invitee_phone else "skipped",
                                           error=None if booking.invitee_phone else "No phone number on this booking."))
    db.session.commit()


def _cal_send_reminder(rem):
    b = CalendlyBooking.query.get(rem.booking_id)
    creds = _cal_creds(b.owner_user_id)
    first = (b.invitee_name or "there").split(" ")[0]
    when = _cal_when(b)
    tmpl = (creds.get("reminder_template_name") or "").strip()
    if tmpl:
        # Pre-approved template (required to message outside WhatsApp's 24h window).
        # Expected body variables: {{1}} first name, {{2}} event name, {{3}} date/time.
        comps = [{"type": "body", "parameters": [{"type": "text", "text": t} for t in (first, b.event_name or "your booking", when)]}]
        send_whatsapp_template_message(b.owner_user_id, b.invitee_phone, tmpl,
                                       (creds.get("reminder_template_language") or "en_US"), comps)
        return
    lead = {"confirm": "Your booking is confirmed", "24h": "Reminder: your booking is tomorrow",
            "1h": "Reminder: your booking starts in about an hour"}[rem.kind]
    text = f"Hi {first}, {lead.lower() if rem.kind == 'confirm' else lead}: {b.event_name or 'appointment'} on {when}."
    if b.join_url:
        text += f" Join: {b.join_url}"
    send_whatsapp_cloud_message(b.owner_user_id, b.invitee_phone, text)


def _cal_process_due(limit=50):
    now = datetime.utcnow()
    BookingReminder.query.filter(BookingReminder.status == "sending",
                                 BookingReminder.claimed_at < now - timedelta(minutes=10)
                                 ).update({"status": "pending"}); db.session.commit()
    due = BookingReminder.query.filter(BookingReminder.status == "pending",
                                       BookingReminder.send_at <= now).limit(limit).all()
    done = 0
    for rem in due:
        claimed = BookingReminder.query.filter_by(id=rem.id, status="pending").update(
            {"status": "sending", "claimed_at": now}); db.session.commit()
        if not claimed:
            continue                                  # another worker took it
        rem = BookingReminder.query.get(rem.id)
        b = CalendlyBooking.query.get(rem.booking_id)
        if not b or b.status != "active" or (rem.kind != "confirm" and b.start_time <= now):
            rem.status = "canceled" if (not b or b.status != "active") else "skipped"
            db.session.commit(); continue
        try:
            _cal_send_reminder(rem)
            rem.status, rem.sent_at, rem.error = "sent", datetime.utcnow(), None
            done += 1
        except Exception as e:
            rem.status = "failed"
            rem.error = (str(e)[:300] + " — outside WhatsApp's 24h window you must set a reminder_template_name.")[:400]
        db.session.commit()
    return done


def _cal_reminder_worker():
    time.sleep(30)
    while True:
        try:
            with app.app_context():
                _cal_process_due()
        except Exception as e:
            logging.error(f"[CALENDLY REMINDER WORKER] {e}")
        time.sleep(60)


if os.environ.get("DISABLE_BOOKING_REMINDER_WORKER") != "1":
    threading.Thread(target=_cal_reminder_worker, name="booking-reminders", daemon=True).start()


# ---------- Stage 3: bookings -> CRM ----------
def _cal_push_to_crms(owner_user_id, booking_id):
    with app.app_context():
        b = CalendlyBooking.query.get(booking_id)
        if not b or not (b.invitee_email or b.invitee_phone):
            return
        cust = ErpCustomer.query.filter_by(owner_user_id=owner_user_id, email=b.invitee_email).first() if b.invitee_email else None
        if not cust:
            cust = ErpCustomer(owner_user_id=owner_user_id, name=b.invitee_name or b.invitee_email or "Calendly guest",
                               email=b.invitee_email, phone=b.invitee_phone,
                               notes=f"Booked via Calendly: {b.event_name}")
            db.session.add(cust); db.session.commit()
        results = []
        for org in Organization.query.filter_by(owner_user_id=owner_user_id).all():
            for conn in CrmConnection.query.filter_by(org_id=org.id, enabled=True).all():
                try:
                    existing = CrmSyncedRecord.query.filter_by(org_id=org.id, provider=conn.provider,
                                                               erp_customer_id=cust.id).first()
                    ext = _crm_push_contact(conn.provider, decrypt_secret_blob(conn.credentials_blob), cust,
                                            existing.external_id if existing else None)
                    if ext and not existing:
                        db.session.add(CrmSyncedRecord(org_id=org.id, provider=conn.provider,
                                                       erp_customer_id=cust.id, external_id=str(ext)))
                    results.append(f"{conn.provider}:ok")
                except Exception as e:
                    results.append(f"{conn.provider}:failed ({str(e)[:80]})")
        b.crm_status = ", ".join(results) if results else "no CRM connected"
        db.session.commit()


# ---------- Calendly routes ----------
@app.route("/api/calendly/connect", methods=["POST"])
@csrf.exempt
def calendly_connect():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    d = request.get_json(silent=True) or {}
    pat = (d.get("personal_access_token") or "").strip()
    if not pat:
        return jsonify({"error": "personal_access_token is required."}), 400
    hdr = {"Authorization": f"Bearer {pat}", "Content-Type": "application/json"}
    try:
        me = requests.get("https://api.calendly.com/users/me", headers=hdr, timeout=15)
        if not me.ok:
            return jsonify({"error": f"Calendly rejected that token ({me.status_code})."}), 400
        res = me.json().get("resource") or {}
        secret, signing = _isec.token_urlsafe(24), _isec.token_urlsafe(32)
        url = f"{_xc_public_base()}/calendly/webhook/{secret}"
        sub = requests.post("https://api.calendly.com/webhook_subscriptions", headers=hdr, timeout=15, json={
            "url": url, "events": ["invitee.created", "invitee.canceled"],
            "organization": res.get("current_organization"), "user": res.get("uri"),
            "scope": "user", "signing_key": signing})
        if not sub.ok:
            return jsonify({"error": "Calendly would not create the webhook (it needs a paid Calendly plan): "
                                     + sub.text[:200]}), 502
        save_user_integration(user["id"], "calendly", {
            "personal_access_token": pat, "webhook_secret": secret, "signing_key": signing,
            "default_country_code": (d.get("default_country_code") or "").strip(),
            "reminder_template_name": (d.get("reminder_template_name") or "").strip(),
            "reminder_template_language": (d.get("reminder_template_language") or "en_US").strip(),
            "webhook_uri": (sub.json().get("resource") or {}).get("uri", "")})
        return jsonify({"ok": True, "webhook_url": url}), 200
    except requests.RequestException as e:
        return jsonify({"error": f"Could not reach Calendly: {e}"}), 502


@app.route("/calendly/webhook/<secret>", methods=["POST"])
@csrf.exempt
def calendly_webhook(secret):
    owner, creds = _xc_find_owner("calendly", secret)
    if not owner:
        return jsonify({"error": "unknown"}), 404
    raw = request.get_data()
    sig = request.headers.get("Calendly-Webhook-Signature", "")
    parts = dict(p.split("=", 1) for p in sig.split(",") if "=" in p)
    expected = hmac.new(creds.get("signing_key", "").encode(), f"{parts.get('t', '')}.".encode() + raw,
                        hashlib.sha256).hexdigest()
    try:
        fresh = abs(time.time() - int(parts.get("t", "0"))) < 300
    except ValueError:
        fresh = False
    if not (parts.get("v1") and fresh and hmac.compare_digest(parts["v1"], expected)):
        return jsonify({"error": "bad signature"}), 401
    body = request.get_json(silent=True) or {}
    p, ev = body.get("payload") or {}, body.get("event")
    se = p.get("scheduled_event") or {}
    start = _i25_parse_iso(se.get("start_time"))
    if not p.get("uri") or not start:
        return jsonify({"ok": True}), 200
    b = CalendlyBooking.query.filter_by(owner_user_id=owner, invitee_uri=p["uri"]).first()
    if ev == "invitee.canceled":
        if b:
            b.status = "canceled"
            BookingReminder.query.filter(BookingReminder.booking_id == b.id,
                                         BookingReminder.status.in_(("pending", "sending"))).update(
                {"status": "canceled"}, synchronize_session=False)
            db.session.commit()
        return jsonify({"ok": True}), 200
    if ev == "invitee.created":
        if not b:
            b = CalendlyBooking(owner_user_id=owner, invitee_uri=p["uri"])
            db.session.add(b)
        b.event_name, b.invitee_name, b.invitee_email = se.get("name"), p.get("name"), p.get("email")
        b.invitee_phone = _cal_phone(p, creds.get("default_country_code"))
        b.timezone, b.start_time, b.end_time = p.get("timezone"), start, _i25_parse_iso(se.get("end_time"))
        b.join_url = ((se.get("location") or {}).get("join_url") or "")[:500] or None
        b.status = "active"
        db.session.commit()
        _cal_schedule_reminders(b)
        threading.Thread(target=_cal_push_to_crms, args=(owner, b.id), daemon=True).start()
    return jsonify({"ok": True}), 200


