# ---------- Stage 4: Amazon + Shopify marketplace sync ----------
_AMZ_HOSTS = {"na": "sellingpartnerapi-na.amazon.com", "eu": "sellingpartnerapi-eu.amazon.com",
              "fe": "sellingpartnerapi-fe.amazon.com"}
_amz_tok = {}


def _amz_token(c):
    key = c.get("refresh_token", "")[-24:]
    hit = _amz_tok.get(key)
    if hit and hit[1] > time.time() + 60:
        return hit[0]
    r = requests.post("https://api.amazon.com/auth/o2/token", timeout=15, data={
        "grant_type": "refresh_token", "refresh_token": c.get("refresh_token"),
        "client_id": c.get("lwa_client_id"), "client_secret": c.get("lwa_client_secret")})
    if not r.ok:
        raise ValueError(f"Amazon login failed ({r.status_code}): {r.text[:150]}")
    j = r.json()
    _amz_tok[key] = (j["access_token"], time.time() + int(j.get("expires_in", 3600)))
    return j["access_token"]


def _amz_fetch_orders(user_id, days):
    c = _xc_creds(user_id, "amazon_sp")
    if not (c.get("refresh_token") and c.get("lwa_client_id") and c.get("lwa_client_secret") and c.get("marketplace_ids")):
        raise ValueError("Amazon is not connected. Add your SP-API credentials under Integrations (amazon_sp).")
    host = _AMZ_HOSTS.get((c.get("region") or "eu").lower(), _AMZ_HOSTS["eu"])
    hdr = {"x-amz-access-token": _amz_token(c)}
    params = {"MarketplaceIds": c["marketplace_ids"].replace(" ", ""),
              "CreatedAfter": (datetime.utcnow() - timedelta(days=days)).strftime("%Y-%m-%dT%H:%M:%SZ")}
    out = []
    for _ in range(10):                                  # max 10 pages per run
        r = requests.get(f"https://{host}/orders/v0/orders", headers=hdr, params=params, timeout=30)
        if not r.ok:
            raise ValueError(f"Amazon orders error ({r.status_code}): {r.text[:200]}")
        pl = (r.json() or {}).get("payload") or {}
        out += pl.get("Orders") or []
        if not pl.get("NextToken"):
            break
        params = {"NextToken": pl["NextToken"]}
        time.sleep(1)                                    # stay under the Orders rate limit
    return [{"external_id": o.get("AmazonOrderId"), "order_ref": o.get("AmazonOrderId"),
             "status": o.get("OrderStatus"),
             "total": float((o.get("OrderTotal") or {}).get("Amount") or 0) or None,
             "currency": (o.get("OrderTotal") or {}).get("CurrencyCode"),
             "customer_name": None, "customer_email": None,   # buyer PII needs Amazon's restricted role
             "items_count": (o.get("NumberOfItemsShipped") or 0) + (o.get("NumberOfItemsUnshipped") or 0),
             "ordered_at": _i25_parse_iso(o.get("PurchaseDate"))} for o in out if o.get("AmazonOrderId")]


def _shop_fetch_orders(user_id, days):
    since = (datetime.utcnow() - timedelta(days=days)).strftime("%Y-%m-%dT%H:%M:%SZ")
    r = _shopify_request(user_id, "GET", "/orders.json",
                         params={"limit": 250, "status": "any", "created_at_min": since})
    if not r.get("ok"):
        raise ValueError(r.get("error", "Shopify error"))
    out = []
    for o in (r["data"] or {}).get("orders", []):
        cu = o.get("customer") or {}
        out.append({"external_id": str(o.get("id")), "order_ref": str(o.get("name") or o.get("order_number")),
                    "status": o.get("financial_status"),
                    "total": float(o.get("total_price") or 0) or None, "currency": o.get("currency"),
                    "customer_name": f"{cu.get('first_name') or ''} {cu.get('last_name') or ''}".strip() or None,
                    "customer_email": o.get("email") or cu.get("email"),
                    "items_count": sum((li.get("quantity") or 0) for li in o.get("line_items") or []),
                    "ordered_at": _i25_parse_iso(o.get("created_at"))})
    return out


@app.route("/api/marketplace-sync/run", methods=["POST"])
@csrf.exempt
def marketplace_sync_run():
    if not _csrf_ok(): return jsonify({"error": "CSRF token invalid or missing."}), 403
    user, err = _erp_user_or_401()
    if err: return err
    d = request.get_json(silent=True) or {}
    days = max(1, min(int(d.get("days") or 14), 90))
    report = {}
    for ch, fn in (("shopify", _shop_fetch_orders), ("amazon", _amz_fetch_orders)):
        if ch not in (d.get("channels") or ["shopify", "amazon"]):
            continue
        try:
            rows, new, upd = fn(user["id"], days), 0, 0
            for r in rows:
                m = MarketplaceOrder.query.filter_by(owner_user_id=user["id"], channel=ch,
                                                     external_id=r["external_id"]).first()
                if m: upd += 1
                else: m = MarketplaceOrder(owner_user_id=user["id"], channel=ch); new += 1; db.session.add(m)
                for k, v in r.items(): setattr(m, k, v)
                m.synced_at = datetime.utcnow()
            db.session.commit()
            report[ch] = {"ok": True, "new": new, "updated": upd}
        except Exception as e:
            db.session.rollback()
            report[ch] = {"ok": False, "error": str(e)[:300]}
    return jsonify({"ok": True, "report": report}), 200


@app.route("/api/marketplace-sync/orders", methods=["GET"])
@csrf.exempt
def marketplace_sync_orders():
    user, err = _erp_user_or_401()
    if err: return err
    q = MarketplaceOrder.query.filter_by(owner_user_id=user["id"])
    if request.args.get("channel") in ("shopify", "amazon"):
        q = q.filter_by(channel=request.args["channel"])
    rows = q.order_by(MarketplaceOrder.ordered_at.desc()).limit(request.args.get("limit", 100, type=int)).all()
    summary = {}
    for r in MarketplaceOrder.query.filter_by(owner_user_id=user["id"]).all():
        s = summary.setdefault(r.channel, {"orders": 0, "revenue": {}})
        s["orders"] += 1
        if r.total and r.currency:
            s["revenue"][r.currency] = round(s["revenue"].get(r.currency, 0) + r.total, 2)
    return jsonify({"orders": [r.to_dict() for r in rows], "summary": summary}), 200


# ---------- Stage 5: ElevenLabs (TTS) + Deepgram (STT) ----------
ELEVENLABS_API_KEY = os.environ.get("ELEVENLABS_API_KEY", "")
DEEPGRAM_API_KEY   = os.environ.get("DEEPGRAM_API_KEY", "")
_EL_LANGS = {"en", "ja", "zh", "de", "hi", "fr", "ko", "pt", "it", "es", "id", "nl", "tr", "fil", "pl", "sv", "bg",
             "ro", "ar", "cs", "el", "fi", "hr", "ms", "sk", "da", "ta", "uk", "ru"}
_DG_LANGS = {"en", "es", "fr", "de", "hi", "ja", "ko", "pt", "it", "nl", "tr", "id", "ru", "uk", "sv", "da", "no",
             "pl", "zh", "ta", "bg", "ca", "cs", "el", "fi", "hu", "lv", "lt", "ms", "ro", "sk", "vi", "th"}


def _elevenlabs_tts(text, user_id, language_code, voice_name):
    key = get_effective_credential(user_id, "elevenlabs", "api_key", ELEVENLABS_API_KEY)
    if not key or (language_code or "en").split("-")[0].lower() not in _EL_LANGS:
        return None
    voice = (voice_name if voice_name and re.fullmatch(r"[A-Za-z0-9]{18,24}", voice_name) else None) \
        or get_effective_credential(user_id, "elevenlabs", "voice_id", "21m00Tcm4TlvDq8ikWAM")
    chunks, cur = [], ""
    for sent in re.split(r"(?<=[.!?])\s+", text):
        if len(cur) + len(sent) > 4500 and cur:
            chunks.append(cur); cur = ""
        cur += (" " if cur else "") + sent
    if cur: chunks.append(cur)
    audio = b""
    for ch in chunks:
        r = requests.post(f"https://api.elevenlabs.io/v1/text-to-speech/{voice}",
                          params={"output_format": "mp3_44100_128"},
                          headers={"xi-api-key": key, "Content-Type": "application/json"},
                          json={"text": ch[:5000], "model_id": "eleven_multilingual_v2"}, timeout=60)
        if not r.ok:
            raise ValueError(f"ElevenLabs error ({r.status_code}): {r.text[:150]}")
        audio += r.content
    return {"ok": True, "audio_base64": base64.b64encode(audio).decode(), "mime_type": "audio/mpeg",
            "provider": "elevenlabs"}


def _deepgram_stt(audio_bytes, user_id, language_code, sample_rate_hertz, encoding):
    key = get_effective_credential(user_id, "deepgram", "api_key", DEEPGRAM_API_KEY)
    lang = (language_code or "en-US")
    if not key or lang.split("-")[0].lower() not in _DG_LANGS:
        return None
    params = {"model": "nova-2", "smart_format": "true", "punctuate": "true", "language": lang}
    head = audio_bytes[:12]
    container = (head[:4] in (b"RIFF", b"OggS", b"fLaC", b"\x1aE\xdf\xa3") or head[:3] == b"ID3"
                 or head[4:8] == b"ftyp" or head[:2] in (b"\xff\xfb", b"\xff\xf3"))
    if not container:                                    # raw PCM needs explicit params
        params.update({"encoding": {"LINEAR16": "linear16", "MULAW": "mulaw", "FLAC": "flac"}.get(encoding, "linear16"),
                       "sample_rate": sample_rate_hertz})
    r = requests.post("https://api.deepgram.com/v1/listen", params=params, data=audio_bytes, timeout=120,
                      headers={"Authorization": f"Token {key}", "Content-Type": "application/octet-stream"})
    if not r.ok:
        raise ValueError(f"Deepgram error ({r.status_code}): {r.text[:150]}")
    alt = ((((r.json().get("results") or {}).get("channels") or [{}])[0]).get("alternatives") or [{}])[0]
    return {"ok": True, "transcript": alt.get("transcript", ""), "confidence": alt.get("confidence"),
            "provider": "deepgram"}


def text_to_speech(text: str, user_id=None, language_code: str = "en-US", voice_name: str | None = None) -> dict:
    """ElevenLabs first (if a key is set), Google Cloud TTS as the fallback."""
    try:
        out = _elevenlabs_tts(text, user_id, language_code, voice_name)
        if out: return out
    except Exception as e:
        logging.error(f"[ELEVENLABS TTS] falling back to Google: {e}")
    return _google_text_to_speech(text, user_id, language_code, voice_name)


def speech_to_text(audio_bytes: bytes, user_id=None, language_code: str = "en-US",
                   sample_rate_hertz: int = 16000, encoding: str = "LINEAR16") -> dict:
    """Deepgram first (if a key is set), Google Cloud STT as the fallback."""
    try:
        out = _deepgram_stt(audio_bytes, user_id, language_code, sample_rate_hertz, encoding)
        if out: return out
    except Exception as e:
        logging.error(f"[DEEPGRAM STT] falling back to Google: {e}")
    return _google_speech_to_text(audio_bytes, user_id, language_code, sample_rate_hertz, encoding)


